/* 정보보안기사 필기 기출풀이 데이터 — ★자동생성물(build_past.py)★ 직접 고치지 말 것.
   소스: ../기출풀이_json/*.json (원본 시험지 PDF 전사 + 해설) */
CPPG.past = [{"id":"2023-10-07","title":"2023년 제4회 (10월 7일)","src":"시험지 스캔본 · 정답 미공개(풀이 기준)","official":false,"items":[{"n":1,"s":"s1","q":"다음 중 리눅스 /etc/passwd 파일에 대한 설명으로 옳은 것은?","c":["저장되는 필드 중 첫 번째에는 사용자 계정 UID가 있다.","사용자 계정과 패스워드가 저장되어 있다.","사용자 계정 UID 값이 \"0\"이면 root이다.","총 5개의 필드로 이루어져 있다."],"a":2,"e":"UID가 0인 계정은 root 권한을 가지므로 옳은 설명입니다. 첫 번째 필드는 UID가 아니라 사용자명이고, 패스워드는 /etc/shadow에 저장되며(passwd에는 x 표시), /etc/passwd는 7개 필드로 구성됩니다.","ce":["/etc/passwd의 첫 번째 필드는 로그인 계정명(username)이며, UID는 세 번째 필드에 저장된다.","현재 리눅스는 패스워드 해시를 /etc/shadow에 분리 저장하고 passwd의 두 번째 필드에는 'x'만 표시한다.","UID 0은 커널이 슈퍼유저로 인식하는 값으로, 계정명과 무관하게 UID가 0이면 root 권한을 가진다.","/etc/passwd는 계정명:패스워드:UID:GID:설명:홈디렉터리:셸의 7개 필드로 구성되며 5개가 아니다."],"rel":["1-6"]},{"n":2,"s":"s1","q":"리눅스/유닉스 시스템 로그에서 로그인 계정 이름, 로그인한 환경, 로그인한 디바이스, 로그인한 쉘(Shell)의 프로세스 ID, 로그인한 계정의 형식, 로그오프 여부, 시간에 대한 저장 구조를 갖는 로그 파일은?","c":["wtmp","utmp","loginlog","sulog"],"a":1,"e":"utmp는 현재 로그인한 사용자 정보를 utmp 구조체(ut_user, ut_line, ut_pid, ut_type, ut_time 등)로 저장하며, 문제의 필드는 이 구조체를 설명합니다. wtmp도 같은 구조체를 쓰지만 로그인·로그아웃 이력을 누적 기록하는 파일이고, loginlog는 로그인 실패, sulog는 su 사용 기록입니다.","ce":["wtmp도 utmp 구조체와 같은 형식을 쓰지만 로그인·로그아웃 이력을 누적 기록하는 파일(last로 조회)이다. 구조체 기준으로 보면 정답 논란 여지가 있다.","utmp는 현재 로그인 사용자의 계정명·터미널·PID·로그인 형식(ut_type)·시간을 utmp 구조체로 저장하며(w, who로 조회) 발문 필드와 일치한다.","loginlog는 연속 로그인 실패(기본 5회 이상) 기록을 남기는 파일로, 로그인 구조체 전체를 저장하지 않는다.","sulog는 su 명령 사용 내역(시간, 성공/실패, 전환 계정)을 기록하는 로그로, 로그인 세션 구조와 무관하다."],"rel":["1-7"],"sure":false,"flag":"utmp/wtmp가 같은 구조체를 사용 — 출제 의도상 utmp로 판단"},{"n":3,"s":"s1","q":"개인정보처리자는 개인정보의 오·남용, 분실·도난·유출·위조·변조 또는 훼손 등에 대응하기 위해 개인정보처리시스템의 접속기록을 점검하여야 한다. 특히 그 사유를 반드시 확인해야 하는 점검 사항은?","c":["개인정보 추가가 발견된 경우","개인정보 수정이 발견된 경우","개인정보 조회가 발견된 경우","개인정보 다운로드가 발견된 경우"],"a":3,"e":"개인정보의 안전성 확보조치 기준은 접속기록 점검 시 개인정보를 다운로드한 것이 발견되면 내부관리계획에 따라 그 사유를 반드시 확인하도록 규정하고 있습니다. 추가·수정·조회는 일반 점검 대상이지만 사유 확인 의무가 명시된 항목은 다운로드입니다.","ce":["개인정보 추가는 접속기록에 남는 처리 유형이지만, 사유를 반드시 확인하도록 명시된 대상은 아니다.","개인정보 수정 역시 접속기록 점검 대상일 뿐, 고시가 사유 확인을 의무화한 항목은 다운로드이다.","조회는 가장 빈번한 처리 행위로 점검 대상이지만, 사유 확인 의무가 명시된 항목은 아니다.","안전성 확보조치 기준은 접속기록 점검 중 개인정보 다운로드가 발견되면 내부관리계획에 따라 사유를 반드시 확인하도록 규정한다(개정 여부 확인)."],"rel":["5-9"]},{"n":4,"s":"s1","q":"시스템 관리자가 다음 문장에서 설명하는 작업을 위하여 설치할 프로그램은?","c":["Nessus","John the ripper","Tripwire","PAM"],"a":2,"e":"Tripwire는 파일의 해시 스냅샷(기준선)을 저장해 두고 변경 여부를 비교·보고하는 무결성 점검 도구입니다. Nessus는 취약점 스캐너, John the ripper는 패스워드 크래킹 도구, PAM은 인증 모듈 프레임워크입니다.","ce":["Nessus는 원격 호스트의 알려진 취약점을 스캔하는 취약점 진단 도구로, 파일 무결성 기준선 비교 기능이 아니다.","John the ripper는 패스워드 해시를 사전·무차별 대입으로 크래킹하는 도구로, 취약 패스워드 점검용이다.","Tripwire는 파일 속성·해시로 기준 스냅샷(DB)을 만들고 이후 변경 내역을 관리자에게 보고하는 무결성 점검 도구이다.","PAM(Pluggable Authentication Modules)은 응용프로그램에 인증 방식을 모듈로 붙이는 인증 프레임워크이다."],"rel":["1-11"],"box":"유닉스 계열 파일시스템의 무결성을 점검하는데 높은 신뢰성을 제공하며, 파일의 스냅샷을 저장하고 이를 기준으로 변경된 파일정보를 관리자에게 보고하여 파일시스템의 변화를 모니터링한다."},{"n":5,"s":"s1","q":"다음 중 포맷 스트링의 점검 도구로 틀린 것은?","c":["gdb","objdump","iptables","ltrace"],"a":2,"e":"iptables는 리눅스 패킷 필터링 방화벽 도구로 포맷 스트링 점검과 무관합니다. gdb(디버거), objdump(바이너리 역어셈블), ltrace(라이브러리 호출 추적)는 printf 계열 함수 호출과 메모리를 분석하는 데 사용됩니다.","ce":["gdb는 실행 중인 프로세스의 스택·메모리를 추적하는 디버거로 %x, %n 입력 시 메모리 변화를 확인하는 데 쓰인다.","objdump는 바이너리를 역어셈블해 printf 계열 호출부와 GOT/.dtors 주소 등 포맷 스트링 공격 대상 주소를 찾는 데 쓰인다.","iptables는 리눅스 넷필터 기반 패킷 필터링 방화벽 설정 도구로, 프로그램 내부의 포맷 스트링 취약점 점검과 무관하다.","ltrace는 라이브러리 함수 호출을 추적해 printf에 사용자 입력이 포맷 인자로 직접 전달되는지 확인할 수 있다."],"rel":["1-10"]},{"n":6,"s":"s1","q":"다음 중 무차별 대입 공격에 대한 설명으로 옳은 것은?","c":["SQL(Structured Query Language) 인젝션을 통해 단순히 참 거짓을 판단할 수 있는 상황에서 실제 값을 파악하기 위한 공격이다.","별도의 인증없이 접근이 가능한 취약점을 이용한 악의적인 행위이다.","특정한 암호를 풀기 위해 가능한 모든 값을 대입하는 것을 의미한다.","웹 페이지에 입력값을 통해서 SQL 명령어를 주입하여 오동작을 일으키는 해킹 방법이다."],"a":2,"e":"무차별 대입(Brute Force) 공격은 가능한 모든 값을 차례로 대입해 암호를 알아내는 공격입니다. ①은 Blind SQL 인젝션, ④는 일반 SQL 인젝션에 대한 설명입니다.","ce":["참·거짓 응답 차이만으로 실제 값을 한 글자씩 추론하는 것은 Blind SQL 인젝션에 대한 설명이다.","인증 없이 접근 가능한 취약점을 악용하는 것은 인증 우회(부적절한 인증/접근통제) 취약점에 해당한다.","무차별 대입(Brute Force)은 가능한 모든 키·패스워드 조합을 차례로 대입해 암호를 알아내는 공격이다.","입력값에 SQL 구문을 주입해 쿼리 동작을 바꾸는 것은 일반 SQL 인젝션에 대한 설명이다."],"rel":["4-1"]},{"n":7,"s":"s1","q":"다음 문장에서 설명하는 공격은?","c":["워너크라이","익스플로잇","미라이 봇넷","제로데이 공격"],"a":2,"e":"미라이(Mirai)는 기본 계정이 설정된 취약한 IoT 기기를 감염시켜 좀비 봇넷을 만들고 C&C 명령으로 대규모 DDoS를 수행한 악성코드입니다. 워너크라이는 SMB 취약점을 이용한 랜섬웨어입니다.","ce":["워너크라이(WannaCry)는 SMBv1 취약점(EternalBlue)으로 전파된 랜섬웨어로, 파일을 암호화하고 금전을 요구했다.","익스플로잇은 취약점을 악용하는 코드·기법의 일반 명칭으로, IoT 봇넷 DDoS라는 특정 사건을 가리키지 않는다.","미라이(Mirai)는 기본 계정의 IoT 기기를 텔넷 대입으로 감염시켜 봇넷을 만들고 C&C 명령으로 대규모 DDoS를 수행했다.","제로데이 공격은 패치가 나오기 전 미공개 취약점을 노리는 공격 시점 개념으로, 미라이는 기본 계정 악용이 핵심이었다."],"rel":["1-19"],"box":"보안이 취약한 IoT 기기들을 해킹하여 악성코드에 감염시켜 좀비 네트워크를 만들고 해커의 명령을 받아 DDoS 공격을 발생시켰다."},{"n":8,"s":"s1","q":"다음 중 보안운영체제(Secure OS)의 특징으로 틀린 것은?","c":["운영체제에 내재된 결함으로 인해 발생할 수 있는 각종 해킹으로부터 보호하기 위해 보안 기능이 통합된 보안 커널을 추가로 이식한 운영체제이다.","기본으로 열려있는 취약한 서비스를 모두 차단한다.","계정 관리 및 서비스 관리에 있어 좀 더 나은 보안 체계를 가지고 운영될 수 있도록 한다.","보안 운영체제는 시스템에서 일어나는 프로세스의 활동이 보안 정책에 위반되지 않는지를 검사하지만 시스템 성능에는 아무런 영향이 없다."],"a":3,"e":"보안 운영체제는 모든 접근 요청을 참조 모니터로 검사하므로 일정 수준의 성능 저하(오버헤드)가 발생합니다. 따라서 성능에 아무런 영향이 없다는 설명은 틀립니다.","ce":["보안 OS는 기존 OS 커널에 참조 모니터 등 보안 커널을 추가 이식해 커널 수준에서 접근통제를 강제하므로 옳다.","보안 OS는 최소 서비스 원칙에 따라 기본으로 열린 취약 서비스를 차단해 공격 표면을 줄이므로 옳다.","강제적 접근통제(MAC)·역할 기반 통제 등으로 계정·서비스 관리를 강화하므로 옳은 설명이다.","모든 접근 요청을 보안 정책으로 검사하므로 커널 오버헤드가 생겨 성능에 영향이 있다. '아무 영향 없다'가 틀렸다."],"rel":["1-1"]},{"n":9,"s":"s1","q":"다음 중 Nmap 명령의 기본적인 사용법과 그에 대한 설명으로 틀린 것은?","c":["nmap -sS [target] : 대상에서 열려있는 포트를 확인하기 위해 TCP SYN 스캔을 사용한다.","nmap -sU [target] : 대상에서 열려있는 포트를 확인하기 위해 UDP 스캔을 사용한다.","nmap -O [target] : 대상의 운영체제를 확인하려고 시도한다.","nmap -v [target] : 대상에 대한 운영체제, 소프트웨어 버전 및 기타 정보를 확인하려고 시도한다."],"a":3,"e":"-v는 출력을 자세히 보여주는 verbose 옵션일 뿐입니다. 운영체제·서비스 버전 등을 종합적으로 확인하는 옵션은 -A(또는 -O, -sV)입니다.","ce":["-sS는 SYN만 보내고 SYN/ACK 수신 시 RST로 끊는 Half-open(스텔스) 스캔으로 옳은 설명이다.","-sU는 UDP 포트에 패킷을 보내 ICMP Port Unreachable 응답 여부로 개방 여부를 판단하는 UDP 스캔이다.","-O는 TCP/IP 스택 응답 특성(핑거프린팅)으로 대상 운영체제를 추정하는 옵션이다.","-v는 출력 상세도를 높이는 verbose 옵션일 뿐이다. OS·버전 등 종합 정보 탐지는 -A(-O, -sV, 스크립트 포함)이다."],"rel":["2-4","1-11"]},{"n":10,"s":"s1","q":"경량화된 IoT(Internet of Things) 장치들은 도난 후 기계 분석을 통해 정보 유출과 같은 물리적 공격이 가능하다. 다음 중 공격자가 IoT 장치에 물리적으로 접근하여 수행할 수 있는 공격으로 틀린 것은?","c":["입출력 포트를 이용한 공격","역공학을 통한 버스 프루빙 공격","펌웨어 다운그레이드 공격","부채널 공격"],"a":2,"e":"입출력(JTAG·UART) 포트 접근, 버스 프루빙, 전력·전자파 부채널 공격은 장치를 손에 쥐어야 가능한 물리적 공격입니다. 펌웨어 다운그레이드는 업데이트 절차의 검증 미흡을 노려 네트워크(OTA)로도 수행하는 소프트웨어 공격으로 분류됩니다.","ce":["JTAG·UART 등 디버그·입출력 포트에 직접 연결해 펌웨어 추출·셸 획득을 하는 것은 대표적 물리 공격이다.","기판을 역공학해 버스 라인에 프로브를 대고 흐르는 데이터·키를 엿보는 버스 프루빙은 물리 접근이 필요하다.","펌웨어 다운그레이드는 구버전 펌웨어를 설치해 패치된 취약점을 되살리는 공격으로 OTA 등 원격으로도 가능해 정답으로 본다. 다만 물리 포트로도 수행 가능해 논란 여지가 있다.","부채널 공격은 전력 소비·전자파·처리 시간을 측정해 키를 추출하므로 장치에 대한 물리적 근접·계측이 필요하다."],"rel":["1-15"],"sure":false},{"n":11,"s":"s1","q":"다음 중 TCP SYN Ping을 이용하여 Ping Sweep Filter를 우회하는 방법으로 옳은 것은?","c":["nmap -sP [target] --disable-arp-ping","nmap -sn [target] --disable-arp-ping","nmap -sP -PB [target] --disable-arp-ping","nmap -sP -PS [target] --disable-arp-ping"],"a":3,"e":"-PS 옵션은 ICMP Echo 대신 TCP SYN 패킷으로 호스트 생존 여부를 확인하므로 ICMP 기반 Ping 필터를 우회할 수 있습니다. -sP/-sn 단독은 기본 핑 스윕이며 -PB는 기본 ICMP+ACK 조합 옵션입니다.","ce":["-sP는 기본 핑 스윕(ICMP Echo 등)으로 호스트를 확인하므로 ICMP 필터가 있으면 차단되어 우회 효과가 없다.","-sn은 -sP의 신버전 명칭(포트 스캔 없는 호스트 탐색)으로, 역시 기본 ICMP 기반이라 TCP SYN Ping이 아니다.","-PB는 구버전의 기본 핑 방식(ICMP Echo+TCP ACK 병행) 옵션으로, TCP SYN 핑을 지정하는 옵션이 아니다.","-PS는 대상 포트로 TCP SYN을 보내 SYN/ACK·RST 응답으로 생존을 확인하므로 ICMP 차단 필터를 우회할 수 있다."],"rel":["2-4"]},{"n":12,"s":"s1","q":"다음 중 모의해킹 등 침투 테스트를 위한 리눅스 운영체제로 틀린 것은?","c":["백 트랙(Back track)","칼리 리눅스(Kali linux)","미고(MeeGo)","패롯 리눅스(Parrot linux)"],"a":2,"e":"MeeGo는 노키아·인텔이 개발한 모바일·임베디드용 리눅스 운영체제로 침투 테스트 용도가 아닙니다. BackTrack, Kali, Parrot은 모의해킹 도구를 탑재한 보안 배포판입니다.","ce":["BackTrack은 Kali의 전신으로, 모의해킹 도구를 대거 탑재한 우분투 기반 보안 배포판이다.","Kali Linux는 Offensive Security가 BackTrack을 계승해 만든 데비안 기반 침투 테스트 표준 배포판이다.","MeeGo는 노키아·인텔이 모바일·넷북·임베디드 기기용으로 만든 리눅스 OS로 침투 테스트 배포판이 아니다.","Parrot OS는 모의해킹·포렌식·익명화 도구를 갖춘 데비안 기반 보안 배포판이다."],"rel":["1-11"]},{"n":13,"s":"s1","q":"다음 중 리눅스 Passwd에 저장되어 있지 않는 필드는?","c":["최근 로그인 정보","사용자 계정","사용자명","사용자 계정 홈 디렉터리"],"a":0,"e":"/etc/passwd에는 계정명, 패스워드(x), UID, GID, 설명(사용자명), 홈 디렉터리, 로그인 셸이 저장됩니다. 최근 로그인 정보는 lastlog 등 별도 로그에 기록됩니다.","ce":["최근 로그인 정보는 /var/log/lastlog(lastlog 명령) 등에 기록되며 /etc/passwd 필드에는 없다.","사용자 계정(로그인명)은 /etc/passwd의 첫 번째 필드에 저장된다.","사용자명(실명·설명)은 다섯 번째 GECOS(comment) 필드에 저장된다.","사용자 홈 디렉터리 경로는 여섯 번째 필드에 저장된다."],"rel":["1-6"]},{"n":14,"s":"s1","q":"다음은 SSI 인젝션 취약점에 대한 설명이다. 괄호 안에 들어갈 내용으로 옳은 것은?","c":["홈 디렉터리","유저 디렉터리","기본 웹 사이트","어드민 디렉터리"],"a":0,"e":"DOCUMENT_ROOT 환경변수는 웹 서버의 문서 루트(홈 디렉터리) 경로를 의미하므로, echo 지시자가 실행되면 응답 페이지에 홈 디렉터리 경로가 표시되어 SSI 인젝션 취약점을 확인할 수 있습니다.","ce":["DOCUMENT_ROOT는 웹 서버 문서 루트(홈 디렉터리) 경로이므로, SSI가 실행되면 응답에 이 경로가 출력되어 취약점이 확인된다.","유저 디렉터리(~user 형태의 개인 웹 디렉터리)는 DOCUMENT_ROOT 변수가 가리키는 값이 아니다.","기본 웹 사이트는 서버 설정상 사이트 명칭이며, DOCUMENT_ROOT는 사이트의 루트 디렉터리 경로를 반환한다.","어드민 디렉터리는 관리자 페이지 경로로, DOCUMENT_ROOT 환경변수가 출력하는 값이 아니다."],"rel":["3-6"],"box":"SSI 인젝션 취약점 점검을 위하여 사용자가 입력 가능한 파라미터 값에 <!--#echo var=\"DOCUMENT_ROOT\" -->를 삽입하여 전송 후 반환되는 페이지에 사이트의 (    )가 표시되는지 확인한다."},{"n":15,"s":"s1","q":"다음 중 Linux 시스템의 로그인 시 로그인 메시지와 관련된 설정 파일로 옳은 것은?","c":["㉠ : issue.net, ㉡ : issue, ㉢ : motd","㉠ : motd, ㉡ : issue.net, ㉢ : issue","㉠ : issue, ㉡ : issue.net, ㉢ : motd","㉠ : issue, ㉡ : motd, ㉢ : issue.net"],"a":1,"e":"/etc/motd는 로그인 성공 후 출력되는 메시지, /etc/issue.net은 telnet 등 원격 접속 시 로그인 전에 출력되는 메시지, /etc/issue는 로컬 콘솔(KVM) 로그인 전에 출력되는 메시지입니다. 따라서 ㉠ motd, ㉡ issue.net, ㉢ issue입니다.","ce":["issue.net은 원격(telnet) 로그인 전 메시지라 ㉡에, motd는 로그인 성공 후 메시지라 ㉠에 해당하므로 ㉠과 ㉢의 짝이 어긋났다.","㉠ 로그인 후 메시지=motd, ㉡ telnet 로그인 전=issue.net, ㉢ 로컬 콘솔 로그인 전=issue로 모두 맞는다.","issue는 로컬 콘솔 로그인 전 메시지이므로 ㉠이 아니라 ㉢이고, ㉢의 motd는 로그인 후 메시지라 ㉠에 가야 한다.","㉠ issue는 ㉢에, ㉡ motd는 ㉠에, ㉢ issue.net은 ㉡에 들어가야 하므로 세 짝이 모두 어긋났다."],"rel":["1-16"],"box":"o /etc/( ㉠ ) : telnet 또는 ssh로 shell 접속 시 로그인이 성공되었을 때 보이는 메시지\no /etc/( ㉡ ) : telnet으로 shell 접속 시 사용자가 로그인할 때 로그인하기 전에 출력되는 메시지\no /etc/( ㉢ ) : IDC센터에 있는 Real 서버에 로컬로 KVM을 붙여서 확인했을 때 출력되는 메시지, 로컬 로그인 시 로그인 전 출력되는 메시지 설정"},{"n":16,"s":"s1","q":"유닉스 환경에서 다음 문장과 같은 기능을 수행하는 로깅 도구는?","c":["tripwire","sysloged","ghost","glog"],"a":1,"e":"syslog.conf 설정에 따라 커널·messages·secure·cron·boot·mail 로그 등을 관리하는 데몬은 syslogd이며, 보기 ②(sysloged)가 이를 가리킵니다. tripwire는 무결성 점검 도구입니다.","ce":["tripwire는 파일 해시 기준선을 비교하는 무결성 점검 도구로, syslog.conf에 따라 로그를 수집하지 않는다.","syslogd(원문 표기 sysloged)는 /etc/syslog.conf의 facility.priority 규칙에 따라 커널·messages·secure·cron·mail 등 로그를 분류 저장하는 데몬이다.","ghost는 디스크 이미지 백업·복구 도구(또는 glibc 취약점명)로 로깅 데몬이 아니다.","glog는 구글의 C++ 애플리케이션 로깅 라이브러리로, syslog.conf 기반 시스템 로그 데몬이 아니다."],"rel":["1-7"],"box":"syslog.conf 파일 설정에 따라 동작하는 로그 데몬으로 커널 로그, 메시지(messages) 로그, secure 로그, 크론 로그, 부팅 로그 및 메일 로그, 네임서버 로그, ftp 로그 등의 로그를 관리할 수 있다.","flag":"보기 ② 원문 표기 'sysloged'(syslogd 오기로 보임) 그대로 전사"},{"n":17,"s":"s1","q":"다음 중 칼리 리눅스(Kali Linux)에서 기본으로 제공하는 도구인 버프 스위트(Burp Suite)에서 무차별 대입 공격(Brute Force Attack) 및 퍼징(Fuzzing) 공격과 같은 자동화된 사용자 지정 공격을 수행할 수 있는 기능으로 옳은 것은?","c":["Scope","Intruder","Intercept","History"],"a":1,"e":"Burp Suite의 Intruder는 요청의 특정 위치에 페이로드를 자동 대입해 무차별 대입·퍼징을 수행하는 기능입니다. Intercept는 요청을 가로채 수정하는 Proxy 기능, Scope는 대상 범위 지정 기능입니다.","ce":["Scope는 테스트 대상 호스트·URL 범위를 지정해 다른 기능의 적용 범위를 제한하는 설정이다.","Intruder는 요청의 지정 위치(§)에 페이로드 목록을 자동 대입해 무차별 대입·퍼징을 수행하는 기능이다.","Intercept는 Proxy 탭에서 브라우저 요청·응답을 중간에 가로채 수동으로 수정하는 기능으로 자동화 공격이 아니다.","History(HTTP history)는 Proxy를 거친 요청·응답 이력을 보여주는 기록 기능이다."],"rel":["1-11"]},{"n":18,"s":"s1","q":"다음 문장에서 괄호 안에 들어갈 용어로 옳은 것은?","c":["듀얼-홈드 게이트웨이(Dual-homed gateway)","스크린드 서브넷 게이트웨이(Screened subnet gateway)","스크린드 호스트 게이트웨이(Screened host gateway)","배스천 호스트(Bastion host)"],"a":1,"e":"스크린드 서브넷은 외부·내부 쪽에 각각 패킷 필터링 라우터를 두고 그 사이(DMZ)에 배스천 호스트를 배치하는 구조입니다. 스크린드 호스트는 필터링 라우터 1개와 배스천 호스트로 구성됩니다.","ce":["듀얼 홈드 게이트웨이는 NIC 2개를 가진 단일 배스천 호스트가 내·외부망을 분리하는 구성으로, 라우터 2개 구조가 아니다.","스크린드 서브넷은 외부·내부 필터링 라우터 2개 사이에 배스천 호스트를 둔 DMZ(서브넷)를 만드는 구성이다.","스크린드 호스트는 패킷 필터링 라우터 1개와 내부 배스천 호스트 1개로 구성되어 라우터가 둘이 아니다.","배스천 호스트는 외부 공격에 노출되는 강화된 단일 호스트 자체를 뜻하며, 라우터 조합 구성명이 아니다."],"rel":["2-9"],"box":"방화벽(Firewall)은 외부로부터의 불법적인 접근이나 해커의 공격으로부터 내부 네트워크를 방어하기 위해 내부 네트워크와 외부 네트워크 사이의 통로에 설치된다. (    )은/는 인터넷 쪽과 내부 네트워크 쪽에 패킷 필터링 라우터를 설치하고 그 라우터들 사이에 배스천 호스트를 설치하는 구성을 가진다."},{"n":19,"s":"s1","q":"윈도우에서 관리 목적상 기본적으로 공유되는 폴더 중 Null Session 공유 취약점을 가지고 있는 것은?","c":["C$","Print$","IPC$","ADMIN$"],"a":2,"e":"IPC$는 프로세스 간 통신용 기본 공유로, 계정·패스워드 없이 연결하는 Null Session을 허용해 사용자 목록·공유 정보가 노출될 수 있습니다. C$·ADMIN$은 관리자 권한이 필요한 관리 공유입니다.","ce":["C$는 C 드라이브 루트의 관리 목적 숨은 공유로, 관리자 인증이 있어야 접근 가능하다.","Print$는 프린터 드라이버 배포용 공유로, 널 세션 취약점의 대표 대상이 아니다.","IPC$는 명명된 파이프 기반 프로세스 간 통신 공유로, 빈 계정·패스워드 연결(Null Session)을 허용해 계정·공유 목록이 노출된다.","ADMIN$는 %SystemRoot%(Windows 폴더) 관리 공유로 원격 관리용이며 관리자 권한이 필요하다."],"rel":["1-17"]},{"n":20,"s":"s1","q":"힙 오버플로우 공격에 대한 설명으로 틀린 것은?","c":["프로그래머가 malloc()과 같은 함수를 이용한다.","힙 영역을 오버플로우시켜 특정 코드를 실행하여 공격한다.","버스를 통해 전달되는 중요 정보를 엿보고 가로채는 공격이다.","프로그램이 실행되면서 메모리를 동적으로 할당하는 영역을 이용한다."],"a":2,"e":"버스를 통해 전달되는 정보를 엿보는 것은 스니핑(버스 프루빙)에 해당하며 힙 오버플로우와 무관합니다. 힙 오버플로우는 malloc() 등으로 동적 할당된 힙 영역을 넘치게 해 포인터 등을 조작하는 공격입니다.","ce":["힙은 malloc()·calloc() 등으로 할당되는 영역이므로, 해당 함수 사용이 힙 오버플로우의 전제가 된다는 설명은 옳다.","할당된 힙 버퍼를 넘치게 써 인접 청크의 메타데이터·함수 포인터를 덮어 원하는 코드를 실행하므로 옳다.","버스를 흐르는 정보를 엿보는 것은 버스 프루빙·스니핑이며, 힙 오버플로우는 메모리 경계 초과 쓰기 공격이다.","힙은 실행 중 동적으로 메모리를 할당하는 영역이므로 옳은 설명이다."],"rel":["1-10"]},{"n":21,"s":"s2","q":"정해진 시간 내 메시지의 모든 단편이 수신되지 않았을 때 해당하는 ICMP(Internet Control Message Protocol) 오류 메시지는?","c":["목적지 도달 불가능(destination-unreachable)","시간 경과(time-exceeded)","매개변수 문제(parameter-problem)","발신지 억제(source-quench)"],"a":1,"e":"ICMP Time Exceeded(Type 11)는 TTL 만료(Code 0)와 단편 재조립 시간 초과(Code 1) 두 경우에 전송됩니다. 정해진 시간 내 모든 단편이 도착하지 않은 경우는 Code 1에 해당합니다.","ce":["Destination Unreachable(Type 3)은 네트워크·호스트·포트 도달 불가, DF 설정 시 단편화 필요 등에 쓰인다.","Time Exceeded(Type 11)의 Code 1은 재조립 타이머 안에 모든 단편이 도착하지 않았을 때 발생한다(Code 0은 TTL 만료).","Parameter Problem(Type 12)은 IP 헤더 필드 값이 잘못되어 처리할 수 없을 때 보내는 메시지이다.","Source Quench(Type 4)는 수신 측 버퍼 혼잡 시 송신 속도를 낮추라는 흐름 제어 메시지(현재 폐기)이다."],"rel":["2-12"]},{"n":22,"s":"s2","q":"다음 중 라우팅 프로토콜에 대한 설명으로 틀린 것은?","c":["RIP(Routing Information Protocol)은 소규모 네트워크에 적합하다.","RIP은 전통적인 Distance Vector Algorithm을 사용한다.","OSPF(Open Shortest Path First) 프로토콜은 수평적 구조로 네트워크 구성이 가능하여 대규모 네트워크에 적합하다.","IGRP(Interior Gateway Routing Protocol)은 자율 시스템 내의 라우팅 데이터를 교환할 목적으로 사용하기 위해 개발되어 네트워크의 규모가 크고 복잡하더라도 안정적으로 움직일 수 있게 되어있다."],"a":2,"e":"OSPF는 Area 0(백본)과 하위 Area로 나누는 계층적 구조를 지원해 대규모 네트워크에 적합합니다. 수평적 구조라는 설명이 틀립니다.","ce":["RIP은 최대 홉 수가 15로 제한되어 소규모 네트워크에 적합하므로 옳다.","RIP은 벨만-포드 기반 거리 벡터 알고리즘으로 홉 수를 메트릭으로 사용하므로 옳다.","OSPF는 백본 Area 0과 하위 Area로 나누는 계층적 구조를 지원해 대규모에 적합하다. '수평적 구조'가 틀렸다.","IGRP는 시스코가 RIP의 홉 제한을 보완해 대역폭·지연 등 복합 메트릭으로 AS 내부의 큰 망에서도 안정 동작하도록 만든 프로토콜이다."],"rel":["2-12"]},{"n":23,"s":"s2","q":"다음 중 Windows 운영체제의 'net share' 명령어의 설명으로 틀린 것은?","c":["'net share' 명령어는 공유 자원의 목록을 보여주거나 공유를 생성하고 삭제할 수 있다.","'net share' 명령어를 사용하여 공유의 권한을 변경할 수 있다.","'net share' 명령어는 공유에 연결된 클라이언트의 수를 확인할 수 있다.","'net share' 명령어를 사용하여 공유된 폴더의 암호화 설정을 변경할 수 있다."],"a":3,"e":"net share는 공유 생성·삭제·목록 조회, /GRANT 권한 지정, /USERS 사용자 수 제한 및 공유별 사용자 확인 등을 지원하지만 폴더 암호화 설정 기능은 없습니다. 암호화는 EFS(cipher 명령) 등 별도 기능으로 설정합니다.","ce":["net share는 인수 없이 실행하면 공유 목록을, 공유명=경로로 생성, /DELETE로 삭제할 수 있으므로 옳다.","공유 생성 시 /GRANT:사용자,READ|CHANGE|FULL 옵션으로 공유 권한을 지정할 수 있어 옳은 설명으로 본다.","net share 공유명을 실행하면 해당 공유에 연결된 사용자 정보를 보여주고, /USERS로 동시 연결 수를 제한할 수 있다.","net share에는 암호화 설정 옵션이 없고 폴더 암호화는 EFS(cipher 명령)로 설정한다. 다만 ②의 '변경'도 생성 시 지정만 가능해 논란 여지가 있다."],"rel":["2-13","1-17"],"sure":false},{"n":24,"s":"s2","q":"다음 문장에서 설명하는 것은?","c":["Samba","DNS(Domain Name System)","RPC(Remote Procedure Call)","NIS(Network Information Service)"],"a":0,"e":"Samba는 SMB/CIFS 프로토콜을 구현해 리눅스·유닉스와 윈도우처럼 서로 다른 운영체제 간 파일·프린터를 공유하게 하는 서버입니다. NIS는 계정 등 관리 정보의 중앙 공유, RPC는 원격 함수 호출 방식입니다.","ce":["Samba는 SMB/CIFS를 구현해 리눅스·유닉스와 윈도우 등 이기종 OS 간 파일·프린터 공유를 제공하는 서버이다.","DNS는 도메인 이름과 IP 주소를 상호 변환하는 이름 해석 서비스로 자원 공유 기능이 없다.","RPC는 원격 시스템의 프로시저를 로컬처럼 호출하는 통신 방식으로, NFS 등 서비스의 기반 기술이다.","NIS는 유닉스 계열 호스트 간 계정·호스트 정보 등 관리 DB를 중앙 공유하는 서비스로, 이기종 파일 공유 서버가 아니다."],"rel":["2-13"],"box":"서로 다른 운영체제(OS) 간의 자원 공유를 위해 이용하는 서버로 같은 네트워크 내 연결된 PC는 서로 운영체제가 달라도 네트워크로 파일을 주고받고 자원을 공유할 수 있도록 하는 기법"},{"n":25,"s":"s2","q":"다음 문장에서 설명하는 공격으로 옳은 것은?","c":["Tiny fragment 공격","Fragment Overlap 공격","IP Fragmentation을 이용한 서비스거부 공격 - Jolt","IP Fragmentation을 이용한 서비스거부 공격 - Teardrop"],"a":1,"e":"두 번째 단편의 offset을 조작해 첫 번째 단편의 포트번호 영역을 덮어써서 필터를 우회하는 기법은 Fragment Overlap 공격입니다. Tiny fragment는 TCP 헤더를 두 단편으로 쪼개 필터를 우회하고, Teardrop은 offset 중첩으로 재조합 오류를 일으켜 서비스를 거부시키는 공격입니다.","ce":["Tiny fragment는 첫 단편을 아주 작게 만들어 TCP 헤더(포트)를 두 번째 단편으로 밀어내 필터 검사를 피하는 기법이다.","두 번째 단편의 offset을 조작해 재조립 시 첫 단편의 포트 필드를 덮어써 필터를 우회하는 것이 Fragment Overlap 공격이다.","Jolt는 재조립 불가능한 대형 ICMP 단편을 대량 전송해 시스템 자원을 고갈시키는 서비스 거부 공격이다.","Teardrop은 단편 offset을 겹치거나 어긋나게 보내 재조립 오류로 시스템을 다운시키는 DoS 공격으로, 필터 우회 목적이 아니다."],"rel":["2-12"],"box":"공격자는 공격용 IP 패킷을 위해 두 개의 fragment를 생성한다. 첫 번째 fragment에서는 패킷 필터링 장비에서 허용하는 http(TCP 80) 포트와 같은 포트번호를 가진다. 그리고 두 번째 fragment에서는 offset을 아주 작게 조작해서 fragment들이 재조합될 때 두 번째 fragment가 첫 번째 fragment의 일부분을 덮어쓰도록 한다. 일반적으로 공격자들은 첫 번째 fragment의 포트번호가 있는 부분까지 덮어씌운다. IDS에서는 첫 번째 fragment는 허용된 포트번호이므로 통과시키고 두 번째 fragment는 이전에 이미 허용된 fragment의 ID를 가진 fragment이므로 역시 통과시킨다. 이 두 개의 fragment가 목적지 서버에 도달하여 재조합되면 첫 번째 fragment의 포트 번호는 두 번째 fragment의 포트 번호로 overwrite되고 TCP/IP 스택은 이 패킷이 필터링되어야 할 포트의 응용프로그램에 전달한다."},{"n":26,"s":"s2","q":"다음 중 DDoS(Distributed Denial of Service) 공격의 대응 방안으로 틀린 것은?","c":["방화벽을 설치하여 내부 네트워크로 패킷이 진입하는 것을 차단한다.","IDS를 통해 공격을 탐지하고 대응한다.","Zombie 툴을 사용하여 내부 DDoS 툴을 탐색하여 제거한다.","호스트의 서비스별 대역폭을 증가시킨다."],"a":3,"e":"DDoS 대응에서는 서비스별 대역폭을 제한(QoS·Rate Limit)해 특정 서비스로의 트래픽 폭주가 전체에 영향을 주지 않게 해야 합니다. 서비스별 대역폭을 증가시키는 것은 올바른 대응이 아닙니다. Zombie Zapper 같은 도구로 내부 좀비 에이전트를 찾아 제거하는 것은 대응 방안에 포함됩니다.","ce":["방화벽에서 공격 출발지·비정상 패킷을 차단해 내부망 유입을 줄이는 것은 DDoS 대응 방안으로 옳다.","IDS로 트래픽 이상을 탐지해 차단·경보 등 대응하는 것은 옳은 대응 방안이다.","Zombie Zapper 등 도구로 내부에 설치된 DDoS 에이전트(좀비)를 찾아 제거하는 것은 옳은 대응이다.","서비스별 대역폭은 제한(QoS·Rate Limit)해 폭주가 전체로 번지지 않게 해야 한다. 회선 대역폭 증설도 완화책으로 거론되기에 표현상 논란 여지가 있다."],"rel":["2-3"],"sure":false},{"n":27,"s":"s2","q":"다음 중 NMAP 포트 스캔에 대한 설명으로 틀린 것은?","c":["TCP Connect Scan : 대상 포트에 대해 3-Way Handshaking을 정상적으로 통신하는 방식으로 정상적이면 포트가 열려있다고 판단할 수 있다.","TCP FIN Scan : 대상 포트로 FIN 패킷을 전송하는 방식으로 응답받으면 포트가 열려있다고 판단할 수 있다.","TCP X-MAS Scan : 대상 포트로 FIN, URG, PSH 플래그가 모두 설정된 패킷을 전송하는 방식으로 응답받으면 포트가 닫혀있다고 판단할 수 있다.","TCP Null Scan : 대상 포트로 NULL 패킷을 전송하는 방식으로 응답받으면 포트가 닫혀있다고 판단할 수 있다."],"a":1,"e":"FIN 스캔에서 RST 응답이 오면 포트가 닫힌 것이고, 응답이 없으면 열린 것으로 판단합니다. X-MAS·Null 스캔도 같은 원리로 응답(RST)이 오면 닫힌 포트입니다.","ce":["TCP Connect Scan은 3-way handshake를 완전히 맺어 연결 성립 시 열린 포트로 판단하므로 옳다.","FIN 스캔은 닫힌 포트가 RST로 응답하고 열린 포트는 무응답이므로, '응답받으면 열림'은 반대로 틀렸다.","X-MAS 스캔은 FIN·URG·PSH 플래그 패킷을 보내 RST 응답이 오면 닫힌 포트로 판단하므로 옳다.","Null 스캔은 플래그가 없는 패킷을 보내 RST 응답이 오면 닫힌 포트, 무응답이면 열린 포트로 판단하므로 옳다."],"rel":["2-4"]},{"n":28,"s":"s2","q":"hosts 파일을 통해 도메인 이름에 대한 IP 주소 작성 시 대응할 수 있는 스푸핑 공격은?","c":["DNS 스푸핑","ARP 스푸핑","IP 스푸핑","이메일 스푸핑"],"a":0,"e":"hosts 파일은 DNS 질의보다 먼저 참조되므로 중요 도메인의 IP를 직접 기록해 두면 위조된 DNS 응답에 속지 않아 DNS 스푸핑에 대응할 수 있습니다. ARP 스푸핑은 정적 ARP 테이블로 대응합니다.","ce":["hosts 파일은 DNS 질의보다 먼저 참조되므로 중요 도메인 IP를 고정해 두면 위조 DNS 응답에 속지 않는다.","ARP 스푸핑은 IP-MAC 매핑을 위조하는 공격으로, 정적 ARP 테이블(arp -s)로 대응한다.","IP 스푸핑은 출발지 IP를 위조하는 공격으로, 트러스트 관계 제거·ingress/egress 필터링으로 대응한다.","이메일 스푸핑은 발신자 주소를 위조하는 공격으로 SPF·DKIM·DMARC로 대응한다."],"rel":["2-5"]},{"n":29,"s":"s2","q":"다음 문장은 IP 스푸핑 보안 대책에 대한 설명이다. 괄호 안에 들어갈 내용으로 옳은 것은?","c":["㉠ : NAT, ㉡ : dynamic","㉠ : NAT, ㉡ : static","㉠ : 트러스트, ㉡ : dynamic","㉠ : 트러스트, ㉡ : static"],"a":3,"e":"IP 스푸핑은 rlogin 등의 트러스트 관계를 악용하므로 트러스트를 사용하지 않는 것이 최선이며, 불가피하면 MAC 주소를 static으로 고정해 ARP 변조를 막습니다.","ce":["NAT는 사설 IP 변환 기술로 IP 스푸핑의 악용 대상 관계가 아니며, MAC을 dynamic으로 두면 ARP 변조에 취약하다.","㉡ static은 맞지만 ㉠ NAT가 틀렸다. IP 스푸핑이 악용하는 것은 rlogin 등 트러스트 관계이다.","㉠ 트러스트는 맞지만 ㉡ dynamic은 틀렸다. MAC을 동적으로 두면 ARP 스푸핑으로 쉽게 변조된다.","트러스트(.rhosts 등 IP 기반 인증)를 쓰지 않는 것이 최선이며, 불가피하면 MAC을 static으로 고정해 위조를 막는다."],"rel":["2-5"],"box":"( ㉠ ) 관계를 이용한 IP 스푸핑 방지 대책으로 가장 좋은 보안 대책은 ( ㉠ )을(를) 사용하지 않는 것이다. 불가피하게 사용할 경우 MAC 주소를 ( ㉡ )으로 지정한다."},{"n":30,"s":"s2","q":"다음은 리눅스 시스템의 '/var/log/messages' 파일 내 로그 내용이다. 다음 중 해당 로그를 통해 추정할 수 있는 공격으로 옳은 것은?","c":["Sniffing","Spoofing","DoS Attack","Noise Jamming"],"a":0,"e":"NIC가 promiscuous 모드로 진입하면 자신에게 오지 않은 패킷까지 모두 수신하므로 스니핑 도구 실행을 의심할 수 있습니다.","ce":["promiscuous 모드는 NIC가 자신에게 오지 않은 패킷까지 수신하는 모드로, 스니핑 도구 실행 시 설정되므로 스니핑을 추정할 수 있다.","스푸핑은 IP·MAC·DNS 정보를 위조하는 공격으로, NIC의 무차별 모드 진입 로그만으로는 추정할 수 없다.","DoS는 자원 고갈로 서비스를 마비시키는 공격으로, 대량 트래픽·연결 로그가 나타나야 추정할 수 있다.","Noise Jamming은 무선 주파수 대역에 잡음을 쏴 통신을 방해하는 전자전 기법으로 NIC 모드 변경과 무관하다."],"rel":["2-5"],"box":"Sep 21 16:55:08 Security kernel: device eth0 entered promiscuous mode\nSep 21 16:55:34 Security kernel: device eth0 left promiscuous mode"},{"n":31,"s":"s2","q":"다음 중 스니핑에 사용되는 툴로 틀린 것은?","c":["DSniff","PGP","TCP Dump","fragroute"],"a":1,"e":"PGP는 이메일 암호화·전자서명 도구로 스니핑 도구가 아닙니다. dsniff, tcpdump는 패킷 수집 도구이며 fragroute는 dsniff 제작자가 만든 패킷 조작·중간자 공격 보조 도구입니다.","ce":["dsniff는 네트워크 트래픽에서 패스워드 등을 수집하는 스니핑 도구 모음이다.","PGP는 이메일·파일 암호화와 전자서명을 제공하는 보안 도구로, 오히려 스니핑에 대한 대응책이다.","tcpdump는 libpcap 기반으로 네트워크 패킷을 캡처·출력하는 대표적 스니핑 도구이다.","fragroute는 dsniff 제작자가 만든 패킷 단편화·조작 도구로, 트래픽 가로채기·IDS 우회용 스니핑 보조 도구로 분류된다."],"rel":["2-5"]},{"n":32,"s":"s2","q":"다음 중 NFS(Network File System) 서비스 취약점 발견에 따른 조치사항이 아닌 것은?","c":["NFS 서비스 중지","인가되지 않은 시스템을 umount함","네트워크상의 파일시스템을 mount함","nfsd, statd, lockd 중지"],"a":2,"e":"취약점 조치는 불필요한 NFS 서비스·데몬 중지와 비인가 공유 해제(umount)입니다. 네트워크상의 파일시스템을 mount하는 것은 노출을 늘리는 행위로 조치사항이 아닙니다.","ce":["불필요한 NFS 서비스를 중지하는 것은 취약점 제거의 기본 조치이다.","인가되지 않은 시스템의 공유를 umount해 접근을 끊는 것은 올바른 조치이다.","네트워크 파일시스템을 추가로 mount하면 공유·노출 범위가 넓어지므로 취약점 조치가 아니다.","NFS 관련 데몬(nfsd, statd, lockd)을 중지하는 것은 서비스 중지 조치에 해당한다."],"rel":["2-13"]},{"n":33,"s":"s2","q":"다음 중 HTTPS(HyperText Transfer Protocol Secure)의 특징으로 틀린 것은?","c":["데이터를 주고받는 과정에 SSL/TLS 암호화를 사용하여 데이터를 암호화한다.","HTTPS는 공격자가 중간에 스니핑을 하기 어렵다.","HTTPS는 HTTP의 처리속도를 빠르게 향상시켰다.","무결성을 사용하여 데이터가 전송 중에 변경되지 않았는지 확인할 수 있다."],"a":2,"e":"HTTPS는 핸드셰이크와 암호화·복호화 과정이 추가되어 HTTP보다 처리 부담이 늘어나며, 속도 향상이 목적이 아닙니다. 기밀성(스니핑 방지)과 무결성 보장이 주된 특징입니다.","ce":["HTTPS는 HTTP를 SSL/TLS 위에서 동작시켜 전송 데이터를 암호화하므로 옳다.","전송 구간이 암호화되어 스니핑으로 평문을 얻기 어려우므로 옳다.","HTTPS는 TLS 핸드셰이크·암복호화 과정이 추가되어 HTTP보다 처리 부담이 늘며, 속도 향상은 목적이 아니다.","TLS는 MAC(또는 AEAD)으로 전송 중 변조 여부를 검증해 무결성을 제공하므로 옳다."],"rel":["2-7","3-4"]},{"n":34,"s":"s2","q":"다음 문장에서 설명하는 것은?","c":["Anomaly-based IDS","Snort","Signature-based IDS","IPS"],"a":1,"e":"libpcap 기반으로 동작하고 커뮤니티가 룰(시그니처)을 배포하며 관리자가 룰을 수정·작성할 수 있는 공개 소스 네트워크 IDS는 Snort입니다.","ce":["Anomaly-based IDS는 정상 행위 프로파일과의 편차로 탐지하는 방식을 가리키는 탐지 유형 명칭이지 특정 제품이 아니다.","Snort는 libpcap 기반 오픈소스 네트워크 IDS로, 커뮤니티가 룰을 빠르게 배포하고 관리자가 룰을 수정·작성할 수 있다.","Signature-based IDS는 알려진 공격 패턴 매칭 방식의 일반 명칭으로, 발문의 특정 공개 소스 제품을 가리키지 않는다.","IPS는 탐지 후 인라인으로 차단까지 수행하는 시스템 유형의 명칭으로, 발문 제품명에 해당하지 않는다."],"rel":["2-11"],"box":"수십만 시스템에 설치된 공공 도메인의 공개 소스 IDS이다. 일반적인 탐지 인터페이스인 libpcap을 사용한다. 일반적으로 새로운 공격이 나타난 후 수 시간 내에 공격 시그니처를 작성·배포하고 세계 곳곳의 수십만 시스템에 다운로드 된다. 네트워크 관리자는 이 공개 소스 IDS에 있는 기존 시그니처를 수정하거나 새로 만들어 자기 조직에 맞는 시그니처를 생성할 수 있다."},{"n":35,"s":"s2","q":"다음은 네트워크 트래픽을 분석하던 중 발견된 로그의 일부이다. 해당 로그의 공격 방식과 목표에 대한 설명으로 옳지 않은 것은?","c":["해당 로그는 공격자가 포트 스캐닝을 시도했음을 나타낸다. 공격자는 서버의 개방된 포트를 찾아 추가적인 공격의 기반이 될 정보를 수집하려고 했나.","공격자는 TCP/IP 네트워크에서 가장 일반적으로 사용되는 포트를 스캔했다. 이 포트들은 각각 SSH, Telnet, HTTP, HTTPS, MySQL을 위한 것이다.","\"Source:192.168.0.1 Dest:192.168.0.2 Port:3306\" 로그는 공격자가 MySQL 데이터베이스 서버에 접근 가능한지 확인하려는 시도를 보여준다.","이 로그는 공격자가 DoS 공격을 시도하였음을 나타낸다."],"a":3,"e":"동일 출발지가 같은 시각에 22·23·80·443·3306 포트를 차례로 두드린 것은 포트 스캐닝(정보 수집) 흔적입니다. 포트당 1건씩이므로 대량 트래픽으로 서비스를 마비시키는 DoS 공격으로 볼 수 없습니다.","ce":["같은 출발지가 한 대상의 여러 포트에 순차 접근한 것은 포트 스캐닝으로, 열린 포트 정보 수집 목적이라는 해석은 옳다.","22 SSH, 23 Telnet, 80 HTTP, 443 HTTPS, 3306 MySQL로 포트-서비스 매핑이 정확하다.","3306은 MySQL 기본 포트이므로 해당 로그를 DB 서버 접근 가능성 확인 시도로 보는 것은 옳다.","각 포트에 1건씩 접속한 정찰 로그로 트래픽 폭주가 없으므로 DoS 공격으로 볼 수 없다."],"rel":["2-4"],"box":"[06/Jul/2023:00:00:01 +0900] \"Source:192.168.0.1 Dest:192.168.0.2 Port:22\"\n[06/Jul/2023:00:00:01 +0900] \"Source:192.168.0.1 Dest:192.168.0.2 Port:23\"\n[06/Jul/2023:00:00:01 +0900] \"Source:192.168.0.1 Dest:192.168.0.2 Port:80\"\n[06/Jul/2023:00:00:01 +0900] \"Source:192.168.0.1 Dest:192.168.0.2 Port:443\"\n[06/Jul/2023:00:00:01 +0900] \"Source:192.168.0.1 Dest:192.168.0.2 Port:3306\"","flag":"보기① 끝 '했나.'는 원문 오기('했다.')로 보이나 그대로 전사"},{"n":36,"s":"s2","q":"다음 중 사용자 인증과 무결성 검사가 핵심이 적용된 기술로 단말(End Point)에 대한 통합위협관리 시스템을 지칭하는 것은?","c":["Firewall","UTM(Unified Threat Management)","DRM(Device Relationship Management)","NAC(Network Access Control)"],"a":3,"e":"NAC는 단말이 네트워크에 접속할 때 사용자 인증과 백신·패치 등 무결성(보안 정책 준수) 검사를 수행해 접근을 통제하는 엔드포인트 중심 보안 솔루션입니다. UTM은 네트워크 경계에서 여러 보안 기능을 통합한 장비입니다.","ce":["Firewall은 네트워크 경계에서 IP·포트 규칙으로 트래픽을 허용·차단하는 장비로, 단말 무결성 검사 기능이 핵심이 아니다.","UTM은 방화벽·IPS·안티바이러스 등을 한 장비에 통합한 네트워크 경계 보안 장비로, 단말 중심이 아니다.","DRM은 일반적으로 Digital Rights Management(디지털 저작권·문서 보호)를 뜻하며 단말 접속 통제 솔루션이 아니다.","NAC는 단말 접속 시 사용자 인증과 백신·패치 등 보안 정책 준수(무결성)를 검사해 네트워크 접근을 통제한다."],"rel":["2-10"]},{"n":37,"s":"s2","q":"UTM(Unified Threat Management)에 대한 설명으로 틀린 것은?","c":["UTM은 다양한 보안 솔루션을 하나의 장비에 탑재하여 운영하는 All-in-One 통합보안 솔루션이다.","보안 정책 적용이 개별적으로 이루어지므로 전문가의 운영이 필요하다.","다양한 보안 기능을 하나의 솔루션에 통합하여 복합 해킹 위협에 효과적으로 대응하는 것에 목적을 두고 있다.","보안 정책, 필터링 시그니처를 통합 관리하여 일관성과 운영 효율성을 제공한다."],"a":1,"e":"UTM은 방화벽·IPS·안티바이러스 등의 정책을 하나의 콘솔에서 통합 적용·관리하는 것이 특징입니다. 정책이 개별적으로 이루어진다는 설명은 UTM의 특징과 반대입니다.","ce":["방화벽·IPS·VPN·안티바이러스 등을 하나의 장비에 탑재한 All-in-One 통합보안 솔루션이므로 옳다.","UTM은 여러 보안 기능의 정책을 단일 콘솔에서 통합 적용·관리해 운영 부담을 줄인다. '개별 적용·전문가 필요'는 반대 설명이다.","여러 보안 기능을 통합해 복합 위협에 대응하는 것이 UTM의 도입 목적이므로 옳다.","정책·시그니처를 중앙에서 통합 관리해 일관성과 운영 효율을 높이는 것이 UTM의 장점이므로 옳다."],"rel":["2-10"]},{"n":38,"s":"s2","q":"다음 문장의 스노트(snort) 룰 예시에 대한 설정으로 옳은 것은?","c":["alert tcp any any -> any 23 (msg:\"Dangerous\"; content:\"anonymous\"; depth:14; sid:1;)","alert tcp any any -> any 80 (msg:\"Dangerous\"; content:\"anonymous\"; depth:14; sid:1;)","alert tcp any any -> any 23 (msg:\"Dangerous\"; content:\"anonymous\"; distnace:14; sid:1;)","alert tcp any any -> any 80 (msg:\"Dangerous\"; content:\"anonymous\"; distnace:14; sid:1;)"],"a":0,"e":"텔넷은 TCP 23번 포트이고, 페이로드 처음부터 14바이트 범위 안에서 검색하는 옵션은 depth입니다. distance는 이전 content 매칭 이후부터의 상대 위치를 지정하는 옵션입니다.","ce":["텔넷은 TCP 23번이고, depth:14는 페이로드 처음부터 14바이트 범위 내에서 content를 검색하므로 요구사항과 일치한다.","80번은 HTTP 포트이므로 텔넷 트래픽을 대상으로 하라는 조건과 목적지 포트가 어긋난다.","포트 23은 맞지만 distance는 이전 content 매칭 지점 이후의 상대 거리를 지정하는 옵션이라 '처음부터 14바이트' 조건과 다르다.","포트(80)와 옵션(distance) 모두 틀렸다. 텔넷은 23번, 시작부터 범위 지정은 depth를 써야 한다."],"rel":["2-11"],"box":"모든 네트워크 대역에서 텔넷(Telnet)으로 접속하는 패킷 중 첫 바이트부터 14번째 바이트까지 'anonymous'가 포함된 트래픽에 대해서 'Dangerous' 메시지로 경고한다.","flag":"보기③④ 'distnace' 원문 오기 그대로 전사"},{"n":39,"s":"s2","q":"IPsec을 이용하여 VPN 구축 시 IKE(Internet Key Exchange)에서 작성하는 정책을 IPSec SA라 한다. 다음 중 SA 내용에 포함되지 않는 것은?","c":["인캡슐레이션(Encapsulation) 방식","데이터 암호화 방식","무결성 확인 알고리즘","보호 대상 네트워크"],"a":3,"e":"IKE로 협상되는 IPsec SA(Transform Set)에는 캡슐화 모드(터널/전송)·보안 프로토콜(AH/ESP), 암호화 알고리즘, 무결성(인증) 알고리즘, 키와 수명 등이 포함됩니다. 보호 대상 네트워크(트래픽)는 SA가 아니라 SPD의 셀렉터(crypto ACL)로 지정합니다.","ce":["캡슐화 모드(터널/전송)와 보안 프로토콜(AH/ESP)은 IPsec SA(Transform Set)에 포함되는 속성이다.","데이터 암호화 알고리즘(AES, 3DES 등)과 키는 SA가 정의하는 핵심 속성이다.","무결성·인증 알고리즘(HMAC-SHA 등)은 SA에 포함되는 속성이다.","보호 대상 네트워크(트래픽 셀렉터)는 SPD·crypto ACL로 지정한다고 보아 정답으로 본다. 다만 IKEv2에선 SA 협상 시 트래픽 셀렉터(TS)를 교환하므로 논란 여지가 있다."],"rel":["2-6"],"sure":false},{"n":40,"s":"s2","q":"다음 중 Sendmail의 로그 형식에서 관련 지시자에 대한 정의로 틀린 것은?","c":["Stat : 메시지 전달 상태","Proto : 수신 시 사용된 프로토콜","Class : 메시지 식별자","Delay : 메시지 발신에서 수신까지 걸린 시간"],"a":2,"e":"Sendmail 로그의 class는 메시지의 클래스(우선순위)를 나타내며, 메시지 식별자는 msgid입니다. stat은 전달 상태, proto는 수신 프로토콜, delay는 수신부터 전달까지 걸린 시간입니다.","ce":["stat은 메시지 전달 상태(Sent, Deferred 등)를 나타내므로 옳다.","proto는 메시지를 수신할 때 사용된 프로토콜(SMTP, ESMTP 등)을 나타내므로 옳다.","class는 메시지의 클래스(우선순위 값)이며, 메시지 식별자는 msgid 필드이다.","delay는 메시지 수신부터 전달 시도까지 걸린 총 시간을 나타내므로 옳은 정의로 본다."],"rel":["2-13"]},{"n":41,"s":"s3","q":"다음 중 FTP(File Transfer Protocol)에서 데이터 전송 모드에 관한 설명으로 옳은 것은?","c":["default는 active 모드이며, passive 모드로의 변경은 FTP 서버가 결정한다.","default는 active 모드이며, passive 모드로의 변경은 FTP 클라이언트가 결정한다.","default는 passive 모드이며, active 모드로의 변경은 FTP 서버가 결정한다.","default는 passive 모드이며, active 모드로의 변경은 FTP 클라이언트가 결정한다."],"a":1,"e":"FTP 프로토콜의 기본 데이터 전송 방식은 active 모드이며, 클라이언트가 PASV 명령을 보내야 passive 모드로 전환됩니다. 즉 모드 선택은 클라이언트가 결정합니다.","ce":["기본은 active 모드가 맞지만, passive 전환은 서버가 아니라 클라이언트가 PASV 명령으로 요청한다.","FTP 기본 전송 모드는 active이며, 클라이언트가 PASV 명령을 보내야 passive 모드로 전환되므로 클라이언트가 결정한다.","FTP 프로토콜의 기본은 passive가 아니라 active 모드이며, 모드 선택 주체도 서버가 아니다.","모드 선택 주체가 클라이언트인 점은 맞지만 기본 모드는 passive가 아니라 active이다."],"rel":["3-1"]},{"n":42,"s":"s3","q":"다음은 FTP(File Transfer Protocol) 서비스의 패시브모드(Passive Mode)로 설정하여 서버에 명령을 전송한 응답이다. 데이터 전송을 위한 서버의 포트 번호는?","c":["20","21","25616","10016"],"a":2,"e":"227 응답의 마지막 두 숫자가 포트를 의미하며 포트 = 100 × 256 + 16 = 25616입니다. 앞의 네 숫자(1.222.15.150)는 서버 IP 주소입니다.","ce":["20번은 active 모드에서 서버가 데이터 연결을 여는 포트로, passive 모드 응답 포트와 다르다.","21번은 FTP 제어(명령) 연결 포트로, 데이터 전송 포트가 아니다.","227 응답의 (h1,h2,h3,h4,p1,p2)에서 포트 = p1×256+p2 = 100×256+16 = 25616이다.","10016은 100과 16을 단순히 이어 붙인 값으로, p1×256+p2 계산 규칙을 따르지 않았다."],"rel":["3-1"],"box":"227 Entering Passive Mode (1,222,15,150,100,16)"},{"n":43,"s":"s3","q":"다음 중 메일 서비스 운영 시 메일 수신이 거부되거나 스팸메일로 분류되는 경우 확인 또는 조치할 수 있는 사항으로 틀린 것은?","c":["White Domain을 등록한다.","ISP의 클린존 서비스를 이용한다.","SPF(Sender Policy Framework) Record에 등록된 발신자인지 확인한다.","RBL(Real-Time Blocking List)을 확인하고 차단되어 있으면 차단해제를 신청한다."],"a":1,"e":"화이트도메인 등록, SPF 레코드 확인, RBL 등재 여부 확인 및 해제 신청은 발신 메일이 스팸으로 분류될 때의 조치입니다. ISP의 클린존 서비스는 이용자 측 유해사이트·피싱 차단 서비스로 메일 수신 거부 해결과 무관합니다.","ce":["KISA 화이트도메인에 발송 도메인을 등록하면 국내 주요 포털의 스팸 필터에서 신뢰 발신자로 처리되어 수신 거부를 줄일 수 있다.","ISP 클린존은 이용자 단말의 유해·피싱 사이트 접속을 차단하는 부가 서비스로, 발송 메일의 스팸 분류 해제 조치와 무관하다고 보아 정답으로 본다.","수신 측은 SPF 레코드로 발신 서버 IP가 도메인의 허가된 발신자인지 검증하므로, 등록 여부 확인은 적절한 조치이다.","발신 IP가 RBL(실시간 차단 목록)에 등재되면 수신이 거부되므로, 확인 후 해제 신청하는 것은 올바른 조치이다."],"rel":["3-2"],"sure":false},{"n":44,"s":"s3","q":"다음 문장에서 설명하는 메일 클라이언트 보안은 무엇인가?","c":["필터링","첨부 파일","PGP","악성 스크립트"],"a":2,"e":"PGP는 메일·첨부파일 암호화로 기밀성을, 전자서명으로 송신자 인증을 제공하며 최대 4,096비트 공개키를 생성할 수 있는 메일 보안 도구입니다.","ce":["필터링은 스팸·유해 메일을 규칙으로 걸러내는 기능으로, 암호화·전자서명 기능을 제공하지 않는다.","첨부 파일은 메일 보안의 위협 대상(악성 첨부)일 뿐 기밀성·전자서명을 제공하는 보안 수단이 아니다.","PGP는 메일·첨부파일 암호화(기밀성)와 전자서명(송신자 인증)을 제공하며 최대 4,096비트 공개키를 생성할 수 있다.","악성 스크립트는 메일 본문 HTML 등에 삽입된 위협 요소로, 보안 기능이 아니다."],"rel":["3-2"],"box":"o 사용자가 작성한 이메일의 내용과 첨부되는 파일을 암호화하여 이메일 수신자만이 그 내용을 볼 수 있도록 하는 기밀성을 제공한다.\no 전자서명 기능을 제공하여 송신자라고 주장하는 사용자와 이메일의 실제 송신자가 동일한가를 확인한다.\no 공개키를 4,096비트까지 생성할 수 있다."},{"n":45,"s":"s3","q":"다음 중 애플 iOS 운영체제 기반의 앱을 개발하고 분석할 수 있는 개발도구로 옳은 것은?","c":["Xcode","adb","apktool","dex2jar"],"a":0,"e":"Xcode는 애플이 제공하는 iOS·macOS 앱 통합 개발 환경입니다. adb, apktool, dex2jar는 안드로이드 앱 디버깅·디컴파일 도구입니다.","ce":["Xcode는 애플이 제공하는 iOS·macOS 앱 통합 개발 환경(IDE)으로 빌드·디버깅·분석(Instruments)이 가능하다.","adb(Android Debug Bridge)는 안드로이드 기기와 PC를 연결해 셸 실행·앱 설치·로그 확인을 하는 도구이다.","apktool은 안드로이드 APK를 디코딩(smali·리소스 추출)하고 재빌드하는 리버싱 도구이다.","dex2jar는 안드로이드 DEX 바이트코드를 JAR로 변환해 자바 디컴파일러로 분석하게 하는 도구이다."],"rel":["1-15"]},{"n":46,"s":"s3","q":"다음 문장에서 설명하는 웹 서비스 공격 유형은?","c":["XSS(Cross Site Scripting)","쿠키/세션 위조","SQL Injection","CSRF(Cross Site Request Forgery)"],"a":0,"e":"게시글에 스크립트를 삽입해 글을 읽는 사용자의 브라우저에서 실행되게 하고 쿠키 등 클라이언트 정보를 탈취하는 것은 (저장형) XSS입니다. CSRF는 사용자 권한으로 원치 않는 요청을 서버에 보내게 하는 공격입니다.","ce":["게시글에 스크립트를 저장해 열람자 브라우저에서 실행시키고 쿠키 등 클라이언트 정보를 탈취하는 것은 저장형 XSS이다.","쿠키/세션 위조는 세션 값을 추측·변조해 다른 사용자로 가장하는 공격으로, 게시글 스크립트 삽입과 다르다.","SQL Injection은 입력값으로 DB 쿼리를 조작해 서버 측 데이터를 탈취하는 공격으로, 클라이언트 대상이 아니다.","CSRF는 피해자 권한으로 서버에 원치 않는 요청(글쓰기·송금 등)을 보내게 하는 공격으로, 클라이언트 정보 유출이 목적이 아니다."],"rel":["3-6"],"box":"게시판의 글에 원본과 함께 악성코드를 삽입하여 글을 읽을 경우 악성코드가 실행되도록 하여 클라이언트의 정보를 유출하는 클라이언트에 대한 공격"},{"n":47,"s":"s3","q":"다음과 같은 소스 코드를 작성하는 기법은?","c":["암호화","난독화","캡슐화","모듈화"],"a":1,"e":"변수·함수명을 의미 없는 기호(_ 등)로 바꿔 사람이 읽기 어렵게 만든 코드로, 역공학을 어렵게 하는 난독화 기법입니다. 동작은 유지되므로 암호화와는 다릅니다.","ce":["암호화는 키로 데이터를 복호화 전까지 읽을 수 없게 변환하는 것이며, 지문 코드는 키 없이 그대로 실행된다.","식별자를 의미 없는 밑줄 기호로 바꿔 기능은 유지한 채 가독성을 떨어뜨려 역공학을 어렵게 하는 난독화 기법이다.","캡슐화는 데이터와 메서드를 묶고 내부를 은닉하는 객체지향 설계 원칙으로, 코드 가독성 저하 기법이 아니다.","모듈화는 프로그램을 기능 단위로 분리해 재사용·유지보수성을 높이는 설계 기법이다."],"rel":["3-9"],"box":"function____(_:int,__:int=0,___:int=6):Boolean{return(__+___/___)*(_ ... )}  (밑줄 기호로만 식별자를 구성한 코드)","flag":"지문 코드는 밑줄 기호 나열로 전사 생략·요약"},{"n":48,"s":"s3","q":"다음 중 DNSSEC(DNS Security Extensions)으로 대응이 가능한 공격유형은?","c":["파밍(캐시 포이즈닝)","피싱","DDoS 공격","웜바이러스에 의한 호스트 정보 변조"],"a":0,"e":"DNSSEC은 DNS 응답에 전자서명을 붙여 위·변조를 검증하므로 캐시 포이즈닝을 이용한 파밍에 대응할 수 있습니다. 피싱·DDoS·호스트 파일 변조는 DNSSEC의 보호 범위 밖입니다.","ce":["DNSSEC은 DNS 응답에 전자서명(RRSIG)을 붙여 위조 여부를 검증하므로, 캐시 포이즈닝을 이용한 파밍에 대응한다.","피싱은 가짜 메일·링크로 사용자를 속이는 사회공학 공격으로, 정상 DNS 응답만으로는 막을 수 없다.","DDoS는 트래픽 폭주로 서비스를 마비시키는 공격으로, DNSSEC은 오히려 응답 크기 증가로 증폭 공격에 악용될 수 있다.","웜이 로컬 hosts 파일 등을 변조하면 DNS 질의 자체를 거치지 않으므로 DNSSEC으로 대응할 수 없다."],"rel":["3-7"]},{"n":49,"s":"s3","q":"다음 문장에서 설명하는 DNS(Domain Name System) 레코드는?","c":["A","MX","NS","CNAME"],"a":2,"e":"NS 레코드는 해당 도메인을 관리하는 권한 있는 네임서버를 가리키며 도메인마다 최소 1개 이상 있어야 합니다. A는 IPv4 주소, MX는 메일 서버, CNAME은 별칭입니다.","ce":["A 레코드는 도메인 이름을 IPv4 주소에 매핑하는 레코드이다.","MX 레코드는 도메인의 메일을 받을 메일 서버와 우선순위를 지정하는 레코드이다.","NS 레코드는 해당 도메인(존)을 관리하는 권한 있는 네임서버를 가리키며 도메인마다 최소 1개 이상 필요하다.","CNAME 레코드는 도메인에 별칭(정식 이름)을 지정하는 레코드이다."],"rel":["3-7"],"box":"DNS 서버를 가리키며, 각 도메인에 적어도 한 개 이상 있어야 한다."},{"n":50,"s":"s3","q":"다음과 같은 내용이 규정되어 있는 표준은?","c":["PCI-DSS(Payment Card Industry - Data Security Standard)","SET(Secure Electronic Transaction)","PKI(Public Key Infrastructure)","ISMS(Interactive Short Message Service)"],"a":0,"e":"PCI-DSS는 VISA·MasterCard 등 국제 카드사가 만든 카드 데이터 보안 표준으로, 카드 소유자 데이터 보호·암호화·보안 정책 등을 규정합니다. SET은 카드 결제 프로토콜입니다.","ce":["PCI-DSS는 VISA·MasterCard 등 국제 카드사(PCI SSC)가 만든 카드 데이터 보안 표준으로 암호화·보안정책 요구사항을 규정한다.","SET는 VISA·MasterCard가 만든 전자상거래 카드 결제 보안 프로토콜로, 데이터 보안 규정 표준이 아니다.","PKI는 공개키 인증서 발급·관리를 위한 기반 구조로, 카드 데이터 보호 표준이 아니다.","ISMS는 정보보호 관리체계(Information Security Management System)로, 보기의 풀이도 잘못됐고 카드사 표준이 아니다."],"rel":["3-10"],"box":"카드 정보 해킹 및 도난, 분실 사고로부터 고객의 신용카드 정보 유출을 막기 위해 여러 글로벌 신용카드사에서 만든 신용카드 데이터 보안 표준으로 보안 시스템에 대한 기술 요구 사항, 개발 과정 및 운영 시 보안 요구 사항, 카드 소유자의 데이터 암호화, 정보보호 정책 등이 규정"},{"n":51,"s":"s3","q":"다음 문장에서 설명하는 기술은?","c":["CDR(Content Disarm & Reconstruction)","EDR(Endpoint Detection & Response)","NFV(Network Function Virtualization)","SDN(Software Defined Network)"],"a":0,"e":"CDR은 문서 파일에서 매크로·스크립트 등 잠재적 위협 요소를 제거한 뒤 파일을 재구성해 안전한 파일로 제공하는 기술입니다. EDR은 단말 행위를 탐지·대응하는 솔루션입니다.","ce":["CDR은 파일을 분해해 매크로·스크립트·OLE 객체 등 위협 요소만 제거한 뒤 원래 형식으로 재조합해 무해한 파일을 제공한다.","EDR은 단말의 프로세스·파일·네트워크 행위를 수집·분석해 위협을 탐지하고 격리 등으로 대응하는 솔루션으로, 파일 재조합 기능이 아니다.","NFV는 방화벽·라우터 등 네트워크 기능을 전용 장비 대신 범용 서버의 가상머신 소프트웨어로 구현하는 기술이다.","SDN은 제어 평면과 데이터 평면을 분리해 중앙 컨트롤러가 소프트웨어로 네트워크를 제어하는 구조이다."],"rel":["1-11"],"box":"파일을 분석하여 악성코드 등 문제 있는 해당 영역만을 제거하고 파일을 재조합하여 무해한 파일로 제공하는 보안기술이다."},{"n":52,"s":"s3","q":"다음 중 안드로이드 기기에서 데이터를 안전하게 처리하는 방법으로 틀린 것은?","c":["전송중인 데이터의 경우 민감도와 관계없이 모든 데이터 전송에 TLS(Transport Layer Security)를 사용한다.","민감한 정보를 다른 앱으로 전달해야 한다면 명시적인 인텐트를 사용한다. 일회성 데이터 액세스 권한을 부여하여 다른 앱의 액세스를 더 엄격하게 제한한다.","Logcat 메시지 또는 앱의 로그 파일에 민감한 정보를 포함하지 않는다.","민감한 정보가 포함된 파일은 SDcard와 같은 외부 저장소에 배치한다."],"a":3,"e":"SD카드 등 외부 저장소는 다른 앱이 접근할 수 있으므로 민감한 파일은 앱 전용 내부 저장소에 저장해야 합니다. 나머지는 안드로이드 보안 가이드의 권장 사항입니다.","ce":["안드로이드 보안 가이드는 전송 데이터 민감도와 무관하게 모든 네트워크 통신에 TLS 사용을 권장하므로 옳다.","명시적 인텐트는 수신 컴포넌트를 지정해 가로채기를 막고, URI 권한 등 일회성 액세스 부여로 다른 앱 접근을 제한하므로 옳다.","Logcat은 다른 앱·디버깅 도구로 읽힐 수 있으므로 민감 정보를 로그에 남기지 않는 것은 옳은 권장 사항이다.","SD카드 등 외부 저장소는 다른 앱·PC 연결로 접근 가능하므로, 민감 파일은 앱 전용 내부 저장소에 두어야 한다."],"rel":["1-15"]},{"n":53,"s":"s3","q":"다음 포맷 스트링 주요 함수 중 인자값을 포맷 스트링으로 지정한 버퍼(Buffer)에 출력하는 함수로 옳은 것은?","c":["sprintf","vprintf","fprintf","printf"],"a":0,"e":"sprintf는 포맷 문자열에 따라 결과를 문자열 버퍼에 저장합니다. printf·vprintf는 표준 출력, fprintf는 파일 스트림으로 출력합니다.","ce":["sprintf는 포맷 스트링에 따라 변환한 결과를 첫 번째 인자로 지정한 문자열 버퍼에 저장한다.","vprintf는 가변 인자를 va_list로 받아 표준 출력(stdout)에 출력하는 함수로, 버퍼에 쓰지 않는다.","fprintf는 포맷 결과를 FILE 스트림(파일·stderr 등)에 출력하는 함수이다.","printf는 포맷 결과를 표준 출력(stdout)으로 출력하는 함수이다."],"rel":["1-10","3-9"]},{"n":54,"s":"s3","q":"다음 공개소프트웨어 점검 도구 중 지원언어가 다른 것은?","c":["WAP","Pixy","PHP-Sat","UNO"],"a":3,"e":"WAP(Web Application Protection), Pixy, PHP-Sat은 PHP 소스코드 정적 분석 도구이고, UNO는 C 언어 소스코드 분석 도구입니다.","ce":["WAP(Web Application Protection)는 PHP 웹 애플리케이션 소스코드의 입력 검증 취약점을 찾는 정적 분석 도구이다.","Pixy는 PHP 스크립트의 XSS·SQL 인젝션 취약점을 데이터 흐름 분석으로 찾는 정적 분석 도구이다.","PHP-Sat는 PHP 소스코드의 보안 결함을 탐지하는 정적 분석 도구이다.","UNO는 C 언어 소스코드의 미초기화 변수·널 포인터 역참조·배열 범위 초과를 찾는 분석 도구로, 대상 언어가 다르다."],"rel":["3-9"],"sure":false},{"n":55,"s":"s3","q":"DBMS(Database Management System) 기본 계정 디폴트 패스워드 및 권한 정책을 변경하지 않을 경우 비인가자가 인터넷을 통해 DBMS 기본 계정의 디폴트 패스워드를 획득하여 디폴트 패스워드를 그대로 사용하고 있는 DB에 접근하여 DB 정보를 유출할 수 있는 위험이 존재한다. 다음 중 oracle 설치 시 생성되는 디폴트 계정과 디폴트 패스워드의 연결이 틀린 것은?","c":["sys - changeon_install","scott - tiger","system - manage","dbsnmp - dbsnmp"],"a":2,"e":"Oracle의 기본 계정 system의 디폴트 패스워드는 manager입니다. sys는 change_on_install, scott은 tiger, dbsnmp는 dbsnmp입니다.","ce":["sys 계정의 기본 패스워드는 change_on_install이므로(원문 표기 changeon_install) 옳은 연결이다.","scott은 예제 스키마 계정으로 기본 패스워드가 tiger이므로 옳은 연결이다.","system 계정의 기본 패스워드는 manager이며 'manage'는 틀린 연결이다.","dbsnmp는 Enterprise Manager 에이전트용 계정으로 기본 패스워드가 dbsnmp이므로 옳은 연결이다."],"rel":["3-8"],"flag":"보기① 'changeon_install' 원문 표기(change_on_install)"},{"n":56,"s":"s3","q":"다음 중 데이터베이스 보안을 위한 설정 및 명령어의 의미로 틀린 것은?","c":["alter login sa with password='test_password';\n=> sa 계정 암호 변경","EXEC sp_dropsrvrolemember 'user01', 'sysadmin';\n=> user01 및 sysadmin 계정을 삭제","CREATE PROFILE grace_5 LIMIT;\nFAILED_LOGIN_ATTEMPTS 3\n=> lock걸리기 전까지 패스워드 실패 3번까지만 가능","CREATE PROFILE grace_5 LIMIT;\nPASSWORD_LOCK_TIME 1\n=> 암호 입력 실패하였을 경우 1일동안 해당 계정에 대해 lock 유지"],"a":1,"e":"sp_dropsrvrolemember는 로그인(user01)을 고정 서버 역할(sysadmin)에서 제외하는 프로시저로, 계정을 삭제하지 않습니다. sysadmin은 계정이 아니라 서버 역할입니다.","ce":["MSSQL에서 ALTER LOGIN sa WITH PASSWORD=...는 sa 로그인의 암호를 변경하는 명령이므로 옳다.","sp_dropsrvrolemember는 로그인 user01을 고정 서버 역할 sysadmin에서 제외할 뿐, 계정을 삭제하지 않는다. sysadmin은 계정이 아니라 역할이다.","Oracle 프로파일의 FAILED_LOGIN_ATTEMPTS 3은 로그인 3회 연속 실패 시 계정을 잠그는 설정이므로 옳다.","PASSWORD_LOCK_TIME 1은 로그인 실패로 잠긴 계정의 잠금 유지 기간을 1일로 지정하는 설정이므로 옳다."],"rel":["3-8"]},{"n":57,"s":"s3","q":"다음 전자상거래 보안 중 SSL record 프로토콜의 동기 암호화 알고리즘을 이용하여 압축하는 알고리즘으로 틀린 것은?","c":["IDEA","RCs-40","DES-40","WPKI"],"a":3,"e":"SSL Record 프로토콜은 IDEA, RC2-40, RC4-40, DES-40, DES, 3DES 등 대칭(동기) 암호 알고리즘을 사용합니다. WPKI는 무선 공개키 기반구조로 암호 알고리즘이 아닙니다.","ce":["IDEA는 128비트 키의 블록 암호로, SSL Record 프로토콜의 대칭 암호 스위트로 사용된다.","RC2-40·RC4-40(원문 RCs-40)은 수출용 40비트 키 대칭 암호로 SSL Record 프로토콜에서 사용되었다.","DES-40은 수출 제한용 40비트 키 DES로 SSL Record 프로토콜의 대칭 암호 스위트에 포함되었다.","WPKI는 무선 환경용 공개키 기반구조(인증서 관리 체계)로, 레코드 암호화에 쓰는 대칭 암호 알고리즘이 아니다."],"rel":["2-7","3-14"],"flag":"보기② 'RCs-40' 원문 표기(RC2-40/RC4-40 의미로 보임)"},{"n":58,"s":"s3","q":"다음 문장에서 설명하는 핀테크(FinTech) 기술과 관련된 것은?","c":["CNP(Credit-Not_Present)","PCI-DSS(Payment Card Industry-Data Security Standard)","FDS(Fraud Detection System)","EMV(Europay, Mastercard, Visa)"],"a":2,"e":"FDS(이상금융거래탐지시스템)는 결제·접속 정보와 소비 패턴을 분석해 평소와 다른 의심 거래를 탐지하고 차단·확인하는 시스템입니다. EMV는 IC 카드 결제 표준입니다.","ce":["CNP(Card Not Present)는 온라인·전화 결제처럼 카드 실물 없이 이루어지는 거래 유형을 뜻하며 탐지 시스템이 아니다.","PCI-DSS는 카드 데이터 보호를 위한 보안 표준으로, 거래 패턴 분석 시스템이 아니다.","FDS는 결제·접속 정보와 소비 패턴을 분석해 해외 사용 등 평소와 다른 이상 거래를 탐지·확인·차단하는 시스템이다.","EMV는 Europay·Mastercard·Visa가 만든 IC칩 카드 결제 표준으로, 카드 복제를 막는 기술이다."],"rel":["3-13"],"box":"고객 신용카드 거래를 분석해 평소와 다른 의심 거래 이상 징후가 있을 때 회원과 통화하거나 확인 과정을 통해 사고를 예방하는 시스템을 말한다. 예를 들어 출국 기록이 없는데 갑자기 해외에서 카드를 사용할 경우 이를 발견하는 등 금융거래정보를 중심으로 카드사 고객의 소비 스타일 및 각종 패턴까지 분석하는 기능을 제공한다."},{"n":59,"s":"s3","q":"다음 문장에서 설명하는 내용에 대한 조치 방법으로 틀린 것은?","c":["사용자가 주민등록번호 뒷자리, 비밀번호 입력 시 별표 표시하는 등 마스킹 처리를 하여 주변 사람들에게 노출되지 않도록 한다.","웹페이지를 운영 서버에 이관 시 주석은 모두 제거하여 이관한다.","중요정보(개인정보, 계정정보, 금융정보 등)를 HTML 소스에 포함하지 않도록 한다.","로그인 실패 시 반환되는 에러 메시지는 회원을 위해 특정 ID의 가입 여부를 식별할 수 있게 구현한다."],"a":3,"e":"로그인 실패 메시지가 ID 존재 여부를 구분해 주면 공격자가 유효 계정을 수집할 수 있으므로, 'ID 또는 비밀번호가 올바르지 않습니다'처럼 동일한 메시지를 반환해야 합니다.","ce":["주민번호 뒷자리·비밀번호를 별표 등으로 마스킹해 화면 노출을 막는 것은 중요정보 노출 대응으로 옳다.","개발 주석에는 경로·계정·로직 정보가 담길 수 있어 운영 이관 시 제거하는 것은 옳은 조치이다.","HTML 소스는 사용자가 누구나 볼 수 있으므로 중요정보를 포함하지 않는 것은 옳은 조치이다.","ID 존재 여부를 구분하는 에러 메시지는 계정 수집(열거)에 악용되므로, ID·비밀번호 구분 없는 동일 메시지를 반환해야 한다."],"rel":["3-4"],"box":"웹 사이트에 중요정보(개인정보, 계정정보, 금융정보 등)가 노출되거나 에러 발생 시 과도한 정보(어플리케이션 정보, DB 정보, 웹 서버 구성 정보, 개발 과정의 코멘트 등)가 노출될 경우 공격자들의 2차 공격을 위한 정보로 활용될 수 있다."},{"n":60,"s":"s3","q":"다음은 HTTP Request 메시지의 일부이다. 이를 통해 알 수 없는 것은?","c":["클라이언트가 요청한 파일 이름","클라이언트가 요청한 방식","서버의 운영체제 종류","서버의 DNS 이름"],"a":2,"e":"요청 라인에서 요청 방식(GET)과 파일(/index.html)을, Host 헤더에서 서버 DNS 이름을 알 수 있습니다. User-Agent의 Windows NT는 클라이언트의 운영체제이며 서버 운영체제는 알 수 없습니다.","ce":["요청 라인 'GET /index.html'에서 요청 파일 이름(/index.html)을 알 수 있다.","요청 라인의 메서드 GET으로 클라이언트의 요청 방식을 알 수 있다.","User-Agent의 Windows NT는 클라이언트(브라우저) 운영체제이며, 요청 메시지에는 서버 OS 정보가 없다(서버 OS는 응답 Server 헤더 등으로 추정).","Host 헤더의 www.test.com으로 요청 대상 서버의 DNS 이름을 알 수 있다."],"rel":["3-3"],"box":"GET /index.html HTTP/1.1\nUser-Agent: Mozilla/4.0 (compatible; MSIE5.01; Windows NT)\nHost: www.test.com\nAccept-Language: en-us\nAccept-Encoding: gzip, deflate\nConnection: Keep-Alive"},{"n":61,"s":"s4","q":"다음 중 RADIUS(Remote Authentication Dial In User Services) 서버가 사용자 인증을 하는 프로토콜이 아닌 것은?","c":["PAP","CHAP","EAP","NTP"],"a":3,"e":"RADIUS는 PAP, CHAP, EAP 등을 이용해 사용자를 인증합니다. NTP는 시간 동기화 프로토콜로 인증과 무관합니다.","ce":["PAP는 ID·패스워드를 평문으로 전송하는 인증 프로토콜로, RADIUS가 지원하는 인증 방식이다.","CHAP는 챌린지-응답과 해시로 패스워드를 직접 전송하지 않는 인증 방식으로, RADIUS가 지원한다.","EAP는 인증서·토큰 등 다양한 인증 방법을 담는 확장 프레임워크로, RADIUS가 802.1X 등에서 중계한다.","NTP는 네트워크 시각 동기화 프로토콜(UDP 123)로 사용자 인증 기능이 없다."],"rel":["2-8"]},{"n":62,"s":"s4","q":"다음 중 정보보호 통제 분야 중 '정보보호 정책'에 대한 통제 목표가 아닌 것은?","c":["정책의 승인 및 공표","정책의 체계","정책의 작성방법","정책의 유지 관리"],"a":2,"e":"ISMS 정보보호 정책 분야의 통제 항목은 정책의 승인 및 공표, 정책의 체계, 정책의 유지관리입니다. 정책의 작성방법은 통제 목표에 포함되지 않습니다.","ce":["정보보호 정책을 경영진이 승인하고 임직원에게 공표하는 것은 정책 분야 통제 목표에 포함된다.","정책·지침·절차 등 문서 체계를 수립하는 '정책의 체계'는 정책 분야 통제 목표에 포함된다.","구 ISMS 정책 분야 통제 목표는 승인·공표, 체계, 유지관리이며 '작성방법'은 통제 목표로 규정되지 않았다. 기준 버전에 따라 표현이 달라 논란 여지는 있다.","정책을 정기 검토해 변경 사항을 반영하는 '정책의 유지관리'는 정책 분야 통제 목표에 포함된다."],"rel":["5-5","5-1"],"sure":false},{"n":63,"s":"s4","q":"다음 중 주체와 객체의 수가 많거나 이들이 빈번하게 변경될 경우 접근통제 구현이 어려운 방법은?","c":["접근통제 매트릭스(Access Control Matrix)","접근통제 목록(Access Control List)","접근통제 자격(Access Control Capability)","임의적 접근통제(Discretionary Access Control)"],"a":0,"e":"접근통제 매트릭스는 모든 주체×객체 조합을 행렬로 관리하므로 수가 많으면 희소 행렬이 커지고 변경 관리가 어렵습니다. 이를 보완한 것이 객체 중심 ACL, 주체 중심 Capability List입니다.","ce":["접근통제 매트릭스는 모든 주체×객체 조합을 행렬로 관리해 규모가 크면 희소 행렬이 비대해지고 변경 반영이 어렵다.","ACL은 매트릭스의 열(객체 기준)만 저장해 객체별 접근 가능한 주체를 관리하는 보완 방식이다.","Capability(자격 목록)는 매트릭스의 행(주체 기준)만 저장해 주체가 접근 가능한 객체를 관리하는 보완 방식이다.","DAC는 객체 소유자가 재량으로 권한을 부여하는 정책 유형으로, 구현 구조의 확장성 문제를 가리키는 용어가 아니다."],"rel":["4-10"]},{"n":64,"s":"s4","q":"다음 중 공개키 교환방식에 대한 설명으로 틀린 것은?","c":["서로 다른 암호화 키와 복호화 키를 사용한다.","대칭키 알고리즘에 비해 속도가 느리다.","대표적인 알고리즘으로는 RSA가 있다.","공개키 방식의 암호화 키와 복호화 키는 비공개되어 있다."],"a":3,"e":"공개키 방식에서 한 키(공개키)는 공개되고 다른 키(개인키)만 비밀로 유지합니다. 두 키가 모두 비공개라는 설명은 틀립니다.","ce":["공개키 방식은 공개키로 암호화하고 짝이 되는 개인키로 복호화하는 등 서로 다른 두 키를 사용하므로 옳다.","공개키 암호는 큰 수의 모듈러 거듭제곱 등 연산량이 많아 대칭키 암호보다 느리므로 옳다.","RSA는 소인수분해 난제에 기반한 대표적 공개키 알고리즘이므로 옳다.","공개키 방식에서 한 키(공개키)는 누구에게나 공개되고 개인키만 비밀로 유지한다. 둘 다 비공개라는 것이 틀렸다."],"rel":["4-4"]},{"n":65,"s":"s4","q":"SET(Secure Electronic Transaction)에서 도입된 기술로 고객의 구매 정보는 은행이 모르게 하고, 지불 정보는 상점이 모르게 하도록 사용하는 서명 방식은?","c":["은닉 서명(Blind Signature)","그룹 서명(Group Signature)","수신자 지정 서명(Nominative Signature)","이중 서명(Dual Signature)"],"a":3,"e":"SET의 이중 서명은 주문 정보(OI)와 지불 정보(PI)의 해시를 결합해 서명함으로써 상점은 지불 정보를, 은행은 주문 정보를 보지 않고도 둘의 연결을 검증하게 합니다.","ce":["은닉 서명은 서명자가 메시지 내용을 모른 채 서명하게 하는 방식으로, 전자화폐 익명성 보장에 쓰인다.","그룹 서명은 그룹 구성원 누구나 그룹 명의로 서명하되 서명자 신원은 관리자만 확인할 수 있는 방식이다.","수신자 지정 서명은 지정된 수신자만 서명을 검증하거나 제3자에게 증명할 수 있게 하는 방식이다.","이중 서명은 주문정보(OI)·지불정보(PI) 해시를 결합해 서명하여, 상점은 지불정보를·은행은 주문정보를 모른 채 연결을 검증하게 한다."],"rel":["4-6","3-10"]},{"n":66,"s":"s4","q":"다음 중 블라인드 디지털 서명에 대한 설명으로 틀린 것은?","c":["문서의 내용을 보여주지 않고 서명을 받아 검증하는 방식이다.","특허에 대한 공증을 받는 분야에서 활용될 수 있다.","서명자에게 불리한 내용에 대한 서명을 하도록 악용될 수 있다.","블라인드 디지털 서명은 실제로 구현될 수 없다."],"a":3,"e":"블라인드 서명은 Chaum이 RSA 기반으로 구현했으며 전자화폐·전자투표 등에 실제로 쓰입니다. 실제 구현이 불가능하다는 설명은 틀립니다.","ce":["블라인드 서명은 메시지를 블라인드 인수로 가려 서명자가 내용을 보지 못한 채 서명하게 하므로 옳다.","내용을 공개하지 않고 존재·시점을 공증받아야 하는 특허 공증 등에 활용될 수 있으므로 옳다.","서명자는 내용을 볼 수 없으므로 불리한 문서에 서명하도록 악용될 위험이 있어 옳은 설명이다.","블라인드 서명은 Chaum이 RSA 기반으로 구현했고 전자화폐·전자투표에 실제 적용되므로 '구현 불가'가 틀렸다."],"rel":["4-6"]},{"n":67,"s":"s4","q":"다음 문장에서 설명하는 암호 알고리즘은?","c":["HIGHT","ARIA","LEA","SEED"],"a":3,"e":"SEED는 1999년 한국정보보호센터(현 KISA)와 국내 암호 전문가들이 개발한 128비트 블록암호로 Feistel 구조를 사용합니다. ARIA는 SPN 구조이며, HIGHT·LEA는 경량 암호입니다.","ce":["HIGHT는 2005년 KISA 등이 개발한 64비트 블록의 경량 암호로, RFID·USN 등 저전력 환경용이다.","ARIA는 2004년 국가보안기술연구소 주도로 개발된 SPN 구조의 128비트 블록 암호로 Feistel 구조가 아니다.","LEA는 2013년 개발된 ARX 연산 기반의 경량 128비트 블록 암호이다.","SEED는 1999년 한국정보보호센터(현 KISA)와 국내 전문가가 개발한 128비트 블록, 16라운드 Feistel 구조 암호이다."],"rel":["4-2"],"box":"o 암호화는 DES와 유사한 변형된 Feistel 구조이다.\no 1999년 한국인터넷진흥원과 국내 암호전문가들이 함께 개발한 알고리즘으로 인터넷, 전자상거래 등에서 공개될 경우 민감한 영향을 끼칠 수 있는 중요정보 및 개인정보를 보호하기 위한 대칭키 암호 알고리즘이다."},{"n":68,"s":"s4","q":"다음 중 RSA(Rivest-Shamir-Adleman) 암호화 알고리즘에 발생할 수 있는 공격에 대한 설명으로 틀린 것은?","c":["수학적 공격(Mathematical Attack)은 두 개의 소수 곱을 인수분해하고자 하는 공격으로 개인키 d의 비트 수가 클수록 안전하다.","시간 공격(Timing Attack)은 복호화 알고리즘의 실행 시간에 의존하는 공격으로 Random Delay라는 방법을 이용하여 방어한다.","선택 암호문 공격(Chosen Ciphertext Attack)은 RSA 알고리즘이 지닌 임의의 데이터 송신 시 암호문으로 간주하여 회신하는 기능을 이용하는 공격으로 OAEP(Optimal Asymmetric Encryption Padding)라는 알고리즘을 이용하여 방어할 수 있다.","재생 공격(Replaying Attack)은 암호화하여 송신한 데이터를 보관하고 있다가 일정 시간 경과 후 재전송하여 비인가 접근을 시도하는 공격으로 방어할 수 없다."],"a":3,"e":"재생 공격은 타임스탬프, 논스(nonce), 순서번호 등을 사용해 방어할 수 있으므로 방어할 수 없다는 설명이 틀립니다. 나머지는 RSA에 대한 대표 공격과 대응(키 길이, 랜덤 지연, OAEP)을 옳게 설명합니다.","ce":["RSA의 안전성은 n=p×q 소인수분해 난도에 달려 있어 키(모듈러스) 비트 수가 클수록 안전하므로 옳은 취지이다.","시간 공격은 복호화 연산 시간 차이로 개인키를 추정하며, 랜덤 지연·블라인딩으로 방어하므로 옳다.","RSA의 곱셈 준동형성을 이용한 선택 암호문 공격은 OAEP 패딩으로 암호문 구조를 무작위화해 방어하므로 옳다.","재생 공격은 타임스탬프·논스·순서번호로 메시지의 신선도를 검증해 방어할 수 있다. '방어할 수 없다'가 틀렸다."],"rel":["4-4"]},{"n":69,"s":"s4","q":"CTR 모드에서 암호문 블록의 한 비트가 전송 도중에 다른 비트로 변경되었지만 암호문 블록의 길이 자체는 변동이 없다고 한다면 복호화 과정에서 몇 개의 평문 블록에 영향을 미치는가?","c":["1","2","3","4"],"a":0,"e":"CTR 모드는 카운터를 암호화한 키스트림과 암호문을 XOR해 복호화하므로 오류가 전파되지 않고, 해당 평문 블록의 같은 위치 1비트만 영향을 받습니다. 따라서 영향을 받는 평문 블록은 1개입니다.","ce":["CTR 모드는 카운터 암호화 키스트림과 암호문을 XOR하므로 비트 오류가 해당 평문 블록의 같은 비트 1개에만 영향을 준다.","2개 블록에 영향이 가는 것은 이전 암호문이 다음 블록 복호에 쓰이는 CBC·CFB 모드의 오류 전파 특성이다.","CTR은 블록 간 연쇄가 없어 오류가 다른 블록으로 번지지 않으므로 3개 블록에 영향을 주지 않는다.","CTR은 각 블록이 독립적으로 복호되므로 4개 블록에 영향이 갈 수 없다."],"rel":["4-3"]},{"n":70,"s":"s4","q":"다음 중 타원곡선암호(ECC)에 대한 설명으로 틀린 것은?","c":["대표적인 비대칭키 암호시스템이다.","동일한 수준의 보안성을 제공하면서 키의 길이는 짧다.","타원곡선에서 소인수분해의 문제를 기초로 한다.","다양한 암호방식 설계와 H/W 및 S/W의 구현이 용이하다."],"a":2,"e":"ECC는 타원곡선 위의 이산대수 문제(ECDLP)의 어려움에 기반합니다. 소인수분해 문제에 기반한 것은 RSA입니다.","ce":["ECC는 공개키·개인키 쌍을 쓰는 대표적 비대칭(공개키) 암호 체계이므로 옳다.","ECC-256은 RSA-3072 수준의 보안을 제공하는 등 같은 보안 강도에서 키 길이가 짧아 옳다.","ECC는 타원곡선 이산대수 문제(ECDLP)에 기반한다. 소인수분해 문제에 기반한 것은 RSA이다.","짧은 키로 연산·저장 부담이 적어 스마트카드·IoT 등 H/W·S/W 구현이 용이하므로 옳다."],"rel":["4-4"]},{"n":71,"s":"s4","q":"다음 SHA 해시함수 중 블록길이가 1,024인 함수는?","c":["SHA-224, SHA-256","SHA-1, SHA-224","SHA-256, SHA-384","SHA-384, SHA-512"],"a":3,"e":"SHA-384와 SHA-512는 64비트 워드 기반으로 1,024비트 블록을 처리합니다. SHA-1, SHA-224, SHA-256은 512비트 블록을 사용합니다.","ce":["SHA-224와 SHA-256은 32비트 워드 기반으로 512비트 블록을 처리한다.","SHA-1과 SHA-224는 모두 512비트 블록을 사용한다.","SHA-384는 1,024비트 블록이지만 SHA-256은 512비트 블록이라 짝이 맞지 않는다.","SHA-384와 SHA-512는 64비트 워드 기반으로 1,024비트 블록을 처리한다."],"rel":["4-5"]},{"n":72,"s":"s4","q":"다음 중 GMAC(Galois Message Authentication Code)와 GCM(Galois/Counter Mode)에 대한 설명으로 틀린 것은?","c":["GCM은 인증 암호의 일종이다.","AES와 같은 128비트 블록암호를 CTR 모드로 이용하여 MAC값을 얻는다.","CTR 모드는 1씩 늘어가는 숫자를 암호화하기 때문에 각 블록을 직렬 처리하여 실행 속도를 높일 수 있다.","CTR 모드와 MAC값 생성에 공통 키를 사용하기 때문에 키 관리가 편리하다."],"a":2,"e":"CTR 모드는 카운터 값만 알면 각 블록을 독립적으로 암호화할 수 있어 병렬 처리로 속도를 높입니다. 직렬 처리로 속도를 높인다는 설명이 틀립니다. GCM은 CTR 암호화와 GHASH 인증을 결합한 인증 암호(AEAD)입니다.","ce":["GCM은 CTR 암호화와 GHASH 인증을 결합해 기밀성과 무결성을 함께 제공하는 인증 암호(AEAD)이다.","GCM/GMAC은 AES 등 128비트 블록 암호를 CTR 모드로 사용하고 GHASH 결과를 카운터 블록 암호값으로 마스킹해 MAC(태그)을 얻는다.","CTR 모드는 카운터 값만 알면 각 블록을 독립적으로 암호화할 수 있어 병렬 처리로 속도를 높인다. '직렬 처리'가 틀렸다.","GCM은 하나의 키로 CTR 암호화와 GHASH 키(H=E_K(0))를 모두 도출하므로 키 관리가 편리하다는 설명은 옳다."],"rel":["4-3"],"sure":false},{"n":73,"s":"s4","q":"암호 프로토콜을 이용한 디바이스 인증 중 RC4 기반의 WEP(Wired Equivalent Privacy) 기술에 대한 취약점을 해결하기 위한 인증 기술은?","c":["인증서 인증","IEEE 802.11i 인증","Challenge-Response 인증","Kerberos 인증"],"a":1,"e":"IEEE 802.11i는 WEP의 취약점을 보완하기 위해 802.1X/EAP 인증과 TKIP·CCMP(AES) 암호화를 정의한 무선랜 보안 표준(WPA2)입니다.","ce":["인증서 인증은 PKI 인증서로 신원을 확인하는 일반 방식으로, WEP 취약점 보완을 위해 정의된 무선 보안 표준명이 아니다.","IEEE 802.11i는 WEP의 RC4·정적 키 취약점을 보완하려고 802.1X/EAP 인증과 TKIP·CCMP(AES) 암호화를 정의한 표준(WPA2)이다.","Challenge-Response는 WEP의 공유키 인증 자체가 쓰던 방식이며, 키스트림 노출 취약점이 있어 해결책이 아니다.","Kerberos는 티켓 기반의 유선 네트워크 SSO 인증 프로토콜로, 무선 WEP 대체 표준이 아니다."],"rel":["2-10"]},{"n":74,"s":"s4","q":"리눅스 커널 내부의 네트워크 관련 프레임워크인 리눅스 방화벽은?","c":["iptables","ufw","nftables","netfilter"],"a":3,"e":"netfilter는 리눅스 커널 내부의 패킷 처리 프레임워크(훅)이며, iptables·nftables·ufw는 netfilter 규칙을 설정하는 사용자 영역 도구입니다.","ce":["iptables는 netfilter 훅에 규칙을 등록하는 사용자 영역 명령 도구로, 커널 내부 프레임워크 자체가 아니다.","ufw(Uncomplicated Firewall)는 우분투의 iptables/nftables 규칙을 쉽게 설정하는 프런트엔드 도구이다.","nftables는 iptables를 대체하는 신규 규칙 설정 도구·문법으로, 역시 netfilter 위에서 동작한다.","netfilter는 리눅스 커널 내부의 패킷 필터링·NAT 처리 훅 프레임워크로, 리눅스 방화벽의 실체이다."],"rel":["2-9"]},{"n":75,"s":"s4","q":"인증기관(CA : Certification Authority)을 이용하여 철수의 공개키를 얻어야 할 때, 얻은 철수의 공개키가 가짜가 아니라는 것을 확신할 수 있는 이유는 무엇인가?","c":["철수의 인증서는 위조할 수 없는 CA의 개인키로 서명되어 있기 때문이다.","철수의 인증서는 인증기관이 신분 확인을 통해 검증했기 때문이다.","철수의 인증서는 세션키를 통해 안전하게 암호화되었기 때문이다.","철수의 인증서는 통제된 신뢰받는 센터를 통해 전달되었기 때문이다."],"a":0,"e":"인증서는 CA의 개인키로 전자서명되어 있어 CA의 공개키로 검증하면 위·변조 여부를 확인할 수 있습니다. 인증서는 암호화되어 전달되는 것이 아니며, 전달 경로가 신뢰의 근거도 아닙니다.","ce":["인증서는 CA의 개인키로 전자서명되어 있어 CA 공개키로 검증하면 위·변조 여부를 확인할 수 있다.","CA의 신원 확인은 발급 전 절차일 뿐, 받은 인증서가 가짜가 아님을 수신자가 확인하는 근거는 CA 서명 검증이다.","인증서는 공개 문서로 세션키로 암호화해 전달하지 않으며, 암호화는 위조 방지 근거가 아니다.","전달 경로의 신뢰성과 무관하게, 서명 검증만으로 인증서 진위를 판단할 수 있는 것이 PKI의 핵심이다."],"rel":["4-7"]},{"n":76,"s":"s4","q":"다음 중 전통적 서명과 디지털 서명의 차이점에 대한 내용으로 틀린 것은?","c":["전통적 서명은 문서에 포함되지만 디지털 서명은 분리되어 있다.","전통적 서명은 한 사람이 많은 문서에 동일한 서명이 가능하지만 디지털 서명은 불가능하다.","전통적 서명은 복사본이 원래 문서와 구별되지만 디지털 서명은 복제 시 구별할 수 없다.","전통적 서명은 서명과 문서 사이에 1:n 관계가 성립하지만 디지털 서명은 1:1 관계이다."],"a":1,"e":"교재(Forouzan) 기준으로 포함 여부·관계(1:n vs 1:1)·복제 구별 여부는 모두 옳은 비교입니다. 다만 디지털 서명도 같은 개인키로 여러 문서에 서명할 수 있으며 서명값만 문서마다 달라지므로, '많은 문서에 서명하는 것이 불가능하다'는 ②의 표현이 틀린 것으로 판단됩니다.","ce":["전통적 서명은 문서에 포함되지만 디지털 서명은 문서와 별도로 전송되므로 교재 기준 옳은 비교이다.","디지털 서명도 같은 개인키로 여러 문서에 서명할 수 있고 서명값만 문서마다 달라지므로 '불가능'이 틀렸다고 판단한다. 다만 '동일한 서명값'으로 해석하면 참이 되어 공식 정답 확인이 필요하다.","전통적 서명의 복사본은 원본과 구별되지만 디지털 서명은 비트 복제 시 원본과 구별할 수 없어 옳다. 복제 구별이 핵심이라 이 보기가 답일 가능성도 배제할 수 없다.","전통적 서명은 하나의 서명이 여러 문서에 쓰이는 1:n이고 디지털 서명은 문서마다 다른 1:1 관계이므로 교재 기준 옳다."],"rel":["4-6"],"sure":false,"flag":"보기 모두 교재상 참에 가까움 — 풀이 기준 ② 선택, 공식 정답 확인 필요"},{"n":77,"s":"s4","q":"RSA(Rivest-Shamir-Adleman) 알고리즘에서 안전성을 높이기 위한 조건으로 틀린 것은?","c":["p와 q는 거의 같은 크기의 소수이어야 한다.","p-1과 q-1은 큰 소수를 인수로 가져야 한다.","p와 q를 곱한 N은 200자리 이상의 소수이어야 한다.","p-1과 q-1의 최대공약수는 작아야 한다."],"a":2,"e":"N은 두 소수 p·q의 곱이므로 합성수이며 소수가 될 수 없습니다. 충분히 큰 N을 쓰는 것은 맞지만 'N이 소수'라는 조건은 틀립니다.","ce":["p와 q는 비슷한 크기여야 한쪽이 작아 쉽게 인수분해되는 위험을 피하므로 옳은 조건이다.","p-1, q-1이 큰 소인수를 가져야 Pollard p-1 인수분해 공격을 막을 수 있으므로 옳다.","N=p×q는 두 소수의 곱이므로 합성수이며 소수일 수 없다. N의 크기를 충분히 크게 하는 것은 맞지만 '소수'가 틀렸다.","gcd(p-1, q-1)가 작아야 개인키 추정 공격을 피할 수 있으므로 옳은 조건이다."],"rel":["4-4"]},{"n":78,"s":"s4","q":"192비트 키를 사용하는 AES 알고리즘의 복호화 과정에서 12라운드에 포함되지 않는 함수는?","c":["AddRoundKey","InvSubBytes","InvShiftRows","InvMixColumns"],"a":3,"e":"AES-192는 12라운드이며, 마지막 라운드(12라운드)에서는 MixColumns(복호화 시 InvMixColumns)를 수행하지 않습니다. 따라서 InvShiftRows, InvSubBytes, AddRoundKey만 수행됩니다.","ce":["AddRoundKey는 모든 라운드(마지막 라운드 포함)에서 라운드 키를 XOR하므로 12라운드에 포함된다.","InvSubBytes는 역 S-box 치환으로 마지막 라운드에도 수행된다.","InvShiftRows는 행 역이동 연산으로 마지막 라운드에도 수행된다.","AES-192는 12라운드이며, 마지막 라운드는 (Inv)MixColumns를 생략하므로 12라운드에 포함되지 않는다."],"rel":["4-2"]},{"n":79,"s":"s4","q":"다음 중 HMAC(Hash-based Message Authentication Code)에 대한 설계 목적의 설명으로 틀린 것은?","c":["내장된 해시함수를 손쉽게 교체할 수 있어야 한다.","사용되는 해시함수를 손쉽게 구할 수 있어야 한다.","제공되는 해시함수를 목적에 맞게 변경해서 사용할 수 있어야 한다.","해시함수의 원래의 성능을 거의 유지할 수 있어야 한다."],"a":2,"e":"HMAC(RFC 2104)의 설계 목표는 기존 해시함수를 수정하지 않고 그대로 사용하는 것입니다. 해시함수를 목적에 맞게 변경해 사용한다는 설명은 설계 목표와 반대입니다.","ce":["HMAC은 내장 해시함수를 SHA-256 등 더 안전한 것으로 쉽게 교체할 수 있도록 설계되었으므로 옳다.","널리 쓰이고 구현이 공개된 해시함수를 그대로 가져다 쓸 수 있도록 설계되었으므로 옳다.","HMAC(RFC 2104)은 기존 해시함수를 수정 없이 그대로 사용하는 것이 설계 목표로, '목적에 맞게 변경'은 반대다.","HMAC은 해시를 두 번 호출하는 수준의 오버헤드로 원래 해시 성능을 거의 유지하도록 설계되었으므로 옳다."],"rel":["4-5"]},{"n":80,"s":"s4","q":"다음 문장에서 설명하는 것은?","c":["Schnorr 디지털 서명 구조","RSA 디지털 서명 구조","ECDSA","DSS"],"a":0,"e":"Schnorr 서명은 ElGamal 서명을 기반으로 하되 서명 길이를 줄인 구조로, 서명 크기를 줄이는 것이 핵심입니다. DSS(DSA)도 ElGamal 계열이지만 문제의 제안 배경 설명은 Schnorr 서명에 해당합니다.","ce":["Schnorr 서명은 ElGamal 서명을 기반으로 하되 부분군 연산을 써서 서명 길이를 줄인 구조이다.","RSA 서명은 소인수분해 난제 기반으로 ElGamal(이산대수) 계열이 아니며, 서명 길이도 모듈러스 길이와 같아 짧지 않다.","ECDSA는 DSA를 타원곡선 위에서 구현한 서명으로, 발문의 'ElGamal 서명 길이 문제를 해결하려 제안된 구조' 설명과 다르다.","DSS(DSA)도 ElGamal·Schnorr 계열로 서명이 짧지만, 발문의 제안 배경(ElGamal 서명 길이 단축)은 Schnorr 서명을 가리킨다."],"rel":["4-6"],"box":"ElGamal 디지털 서명 구조의 문제점은 생성되는 서명의 길이가 2048비트를 넘어간다는 것이다. 이를 해결하기 위해 제안된 방식으로 Elgamal을 기반하고 있지만 서명의 길이가 짧은 디지털 서명구조이다."},{"n":81,"s":"s5","q":"다음 문장에서 괄호 안에 들어갈 용어로 옳은 것은?","c":["경영진의 참여","현업 및 관련부서의 참여","정보보호 담당자의 참여","정보보호 관리자의 참여"],"a":0,"e":"ISMS-P 1.1.1 '경영진의 참여' 항목은 최고경영자가 관리체계 수립·운영 전반에 참여할 수 있도록 보고 및 의사결정 책임과 역할을 문서화하도록 요구합니다.","ce":["ISMS-P 1.1.1 '경영진의 참여'는 최고경영자가 관리체계 전반에 참여하도록 보고·의사결정 책임과 역할을 문서화할 것을 요구한다.","현업·관련 부서의 참여는 1.1.3 조직 구성의 실무 협의체 등에서 다루며, '의사 결정권이 있는' 주체가 아니다.","정보보호 담당자는 실무 수행자로, 관리체계 전반의 의사 결정권을 가진 주체가 아니다.","정보보호 관리자는 실무 관리 책임자로, 발문의 의사 결정권자(경영진) 참여 요건과 다르다."],"rel":["5-11"],"box":"정보보호 및 개인정보보호 관리체계의 수립 및 운영 활동 전반에 의사 결정권이 있는 (    )가 이루어질 수 있도록 보고 및 의사 결정 등의 책임과 역할을 문서화하여야 한다."},{"n":82,"s":"s5","q":"정보보호 조직구성 시 고려해야 할 사항으로 옳지 않은 것은?","c":["정보보호 최고책임자 및 개인정보 보호책임자의 업무를 지원하고 조직의 정보보호 및 개인정보보호 활동을 체계적으로 이행하기 위해 전문성을 갖춘 실무조직을 구성하여 운영하여야 한다.","정보보호 및 개인정보보호 위원회를 구성할 경우 반드시 임원 등 경영진을 포함하지 않고 실무부서의 장으로만 구성하여 실질적이고 효율적인 협의체를 운영하여야 한다.","조직 전반에 걸친 중요한 정보보호 및 개인정보보호 관련 사항에 대하여 검토, 승인 및 의사 결정을 할 수 있는 위원회를 구성하여 운영하여야 한다.","전사적 정보보호 및 개인정보보호 활동을 위하여 정보보호 및 개인정보보호 관련 담당자 및 부서별 담당자로 구성된 실무 협의체를 구성하여 운영하여야 한다."],"a":1,"e":"ISMS-P 1.1.3 조직 구성에서 정보보호위원회는 임원 등 경영진이 참여해 중요 사항을 검토·승인·의사결정하도록 구성해야 합니다. 경영진을 배제하고 실무부서장으로만 구성하는 것은 옳지 않습니다.","ce":["CISO·CPO 업무를 지원할 전문성을 갖춘 실무조직을 구성·운영하는 것은 1.1.3 조직 구성 요건으로 옳다.","정보보호위원회는 임원 등 경영진을 포함해 중요 사항을 검토·승인·결정하도록 구성해야 하므로, 경영진 배제는 틀렸다.","조직 전반의 중요 정보보호 사항을 검토·승인·의사결정하는 위원회 구성은 1.1.3 요건으로 옳다.","정보보호 담당자와 부서별 담당자로 구성된 실무 협의체 운영은 1.1.3 요건으로 옳다."],"rel":["5-11","5-12"]},{"n":83,"s":"s5","q":"다음 중 정보통신기반 보호법에 따른 정보통신기반보호위원회의 심의 사항으로 틀린 것은?","c":["주요정보통신기반시설 보호계획의 조정에 관한 사항","주요정보통신기반시설 보호와 관련된 법 제정에 관한 사항","주요정보통신기반시설 지정 및 지정 취소에 관한 사항","주요정보통신기반시설 보호와 관련된 주요 정책 사항으로서 위원장이 회의에 부치는 사항"],"a":1,"e":"위원회는 보호정책 조정, 보호계획의 종합·조정, 보호계획 추진 실적, 보호 관련 '제도개선' 등을 심의하며, 법 제정은 심의 사항이 아닙니다. 주요정보통신기반시설의 지정·지정취소는 중앙행정기관의 장이 위원회 심의를 거쳐 결정합니다(개정 여부 확인).","ce":["주요정보통신기반시설 보호계획의 종합·조정은 정보통신기반보호위원회의 심의 사항이다.","위원회는 보호 관련 '제도개선'을 심의할 뿐, 법 제정은 입법 절차(국회)의 영역으로 심의 사항이 아니다.","기반시설 지정·지정취소는 중앙행정기관의 장이 위원회 심의를 거쳐 결정하도록 되어 있어 심의 사항으로 본다. 다만 제3조 심의 사항 목록에 직접 열거되지 않아 논란 여지가 있다(개정 여부 확인).","보호 관련 주요 정책 사항으로 위원장이 회의에 부치는 사항은 심의 사항으로 규정되어 있다."],"rel":["5-13"],"sure":false},{"n":84,"s":"s5","q":"다음 중 위험식별 및 평가를 위한 위험평가 방법으로 틀린 것은?","c":["베이스라인 접근법","자산 분석법","상세 위험 분석법","복합 접근법"],"a":1,"e":"위험평가 접근법은 베이스라인 접근법, 비정형(전문가 판단) 접근법, 상세 위험 분석법, 복합 접근법으로 구분됩니다. 자산 분석은 위험평가의 한 단계일 뿐 별도의 접근법이 아닙니다.","ce":["베이스라인 접근법은 표준화된 기본 보호대책 목록을 기준으로 현 수준을 점검하는 위험평가 접근법이다.","자산 분석(식별·가치평가)은 위험평가 과정의 한 단계일 뿐, 베이스라인·상세·복합 같은 독립된 위험평가 접근법이 아니다.","상세 위험 분석법은 자산·위협·취약성을 세부적으로 분석해 위험을 산정하는 접근법이다.","복합 접근법은 중요 시스템은 상세 분석, 나머지는 베이스라인을 적용하는 혼합 접근법이다."],"rel":["5-12"]},{"n":85,"s":"s5","q":"다음 중 조직의 위험분석 및 평가와 관련한 설명으로 틀린 것은?","c":["위험평가 방법론은 조직의 특성에 맞게 자체적으로 정하여 적용할 수 있으나 위험평가의 과정은 합리적이어야 하고 위험평가 결과는 실질적인 위험의 심각성을 대변하여야 한다.","조직의 위험평가 수행 시 외부의 보안 컨설턴트 등 전문가를 필수적으로 참여시켜야 한다.","위험식별 및 평가 시행을 위한 예산 계획을 매년 수립하고 정보보호 최고책임자 등 경영진의 승인을 받아야 한다.","위험평가는 연 1회 이상 정기적으로 수행하되 조직의 변화, 신규시스템 도입 등 중요한 사유가 발생한 경우 해당 부분에 대하여 정기적인 위험평가 이외에 별도로 위험평가를 수행하여야 한다."],"a":1,"e":"위험평가는 정보보호팀·현업 담당자 등 내부 인력이 수행할 수 있으며, 외부 전문가 참여는 필요 시 선택 사항입니다. 필수로 참여시켜야 한다는 설명이 틀립니다.","ce":["위험평가 방법론은 조직 특성에 맞게 자체 선정할 수 있으나 과정의 합리성과 결과의 실질성이 요구되므로 옳다.","위험평가는 정보보호팀·현업 등 내부 인력으로 수행할 수 있고 외부 전문가 참여는 필요 시 선택 사항이다. '필수'가 틀렸다.","위험관리 계획(예산 포함)을 매년 수립하고 CISO 등 경영진 승인을 받도록 하는 것은 ISMS-P 요건으로 옳다.","위험평가는 연 1회 이상 정기 수행하고 조직 변화·신규 시스템 도입 시 별도 수행해야 하므로 옳다."],"rel":["5-11","5-12"]},{"n":86,"s":"s5","q":"디지털포렌식 과정 중 수집된 디지털 증거를 이송, 분석, 보관, 법정 제출 등 각 단계에서 담당자 및 책임자를 명확히 함으로써 증거물의 진정성을 판단하는 중요한 기준을 지칭하는 원칙은?","c":["관리 연속성","전문 배제성","독수 독과성","증거 무결성"],"a":0,"e":"관리 연속성(Chain of Custody)은 증거의 획득부터 법정 제출까지 각 단계의 담당자·책임자와 이력을 명확히 기록해 증거의 진정성을 보장하는 원칙입니다. 증거 무결성은 증거가 변경되지 않았음을 해시 등으로 입증하는 원칙입니다.","ce":["관리 연속성(Chain of Custody)은 증거의 획득·이송·분석·보관·제출 각 단계의 담당자와 이력을 명확히 해 진정성을 보장하는 원칙이다.","전문 배제성(전문증거 배제 법칙)은 원진술자의 직접 진술이 아닌 전문증거의 증거능력을 원칙적으로 부정하는 법리이다.","독수독과는 위법하게 수집된 증거(독수)에서 파생된 2차 증거(과실)도 증거능력을 배제한다는 원칙이다.","증거 무결성은 해시값 비교 등으로 증거가 수집 이후 변경되지 않았음을 입증하는 원칙으로, 담당자 이력 관리와 다르다."],"rel":["3-11"]},{"n":87,"s":"s5","q":"다음 물리적 보호대책 구현 중 출입통제에 대한 설명으로 틀린 것은?","c":["보호구역별로 허가된 자만이 출입할 수 있도록 내·외부자 출입통제 절차를 마련하고 출입 가능한 인원현황을 관리하여야 한다.","보호구역별로 출입 가능한 부서·직무·업무를 정의하며, 출입 권한이 부여된 임직원을 식별하고 그 현황을 관리하여야 한다.","각 보호구역에 대한 내·외부자 출입 기록을 일정기간 보존하고 출입 기록 및 출입 권한을 주기적으로 검토하여야 한다.","시스템적으로 출입 로그를 남길 수 없는 경우 출입 통제 장치만 설치하여도 된다."],"a":3,"e":"출입 통제 장치가 로그를 남기지 못하면 출입 대장 등 수기 기록을 병행해 출입 이력을 관리해야 합니다. 통제 장치만 설치하면 된다는 설명은 틀립니다.","ce":["보호구역별 허가자만 출입하도록 내·외부자 출입통제 절차를 마련하고 인원 현황을 관리하는 것은 ISMS-P 2.4.2 요건이다.","보호구역별 출입 가능한 부서·직무를 정의하고 권한자 현황을 관리하는 것은 옳은 출입통제 요건이다.","출입 기록을 일정 기간 보존하고 기록·권한을 주기적으로 검토하는 것은 옳은 요건이다.","시스템 로그가 남지 않으면 출입대장 등 수기 기록을 병행해 이력을 관리해야 한다. 장치만 설치해선 안 된다."],"rel":["5-11"]},{"n":88,"s":"s5","q":"다음 중 외부자 보안에 대한 설명으로 틀린 것은?","c":["업무의 일부를 외부에 위탁하거나 외부의 시설 또는 서비스를 이용하는 경우, 그 현황을 식별하고 법적 요구 사항 및 외부 조직과 서비스로부터 발생하는 위험을 파악하여 적절한 보호 대책을 마련하여야 한다.","외부 서비스를 이용하거나 외부자에게 업무를 위탁하는 경우 이에 따른 정보보호 및 개인정보보호 요구 사항을 식별하고 관련 내용을 계약서 또는 협정서 등에 명시하여야 한다.","계약서, 협정서, 내부정책에 명시된 정보보호 및 개인정보보호 요구 사항에 따라 외부자의 보호 대책 이행 여부는 주기적인 점검 또는 감사 등 관리·감독하지 않아도 된다.","외부자 계약만료, 업무종료, 담당자 변경 시에는 제공한 정보자산 반납, 정보시스템 접근 계정 삭제, 중요정보 파기, 업무 수행 중 취득정보의 비밀 유지 확약서 징구 등의 보호 대책을 이행하여야 한다."],"a":2,"e":"ISMS-P 2.3.3 '외부자 보안 이행 관리'는 외부자의 보호대책 이행 여부를 주기적인 점검 또는 감사 등으로 관리·감독하도록 요구합니다. 관리·감독하지 않아도 된다는 설명은 틀립니다.","ce":["외부 위탁·시설·서비스 현황을 식별하고 법적 요구사항과 위험을 파악해 보호대책을 마련하는 것은 ISMS-P 2.3.1 요건이다.","위탁 시 보호 요구사항을 식별해 계약서·협정서에 명시하는 것은 2.3.2 요건으로 옳다.","ISMS-P 2.3.3은 외부자의 보호대책 이행 여부를 주기적 점검·감사로 관리·감독하도록 요구하므로 '하지 않아도 된다'가 틀렸다.","계약 만료·담당자 변경 시 자산 반납·계정 삭제·정보 파기·비밀유지 확약서 징구는 2.3.4 요건으로 옳다."],"rel":["5-11"]},{"n":89,"s":"s5","q":"다음 중 정보보안제품의 보안기능 요구사항 계층 구조에 대한 설명으로 틀린 것은?","c":["클래스 - 동일 보안목적을 가지는 패밀리들의 집합","패밀리 - 동일 보안목적이나 보안 강도 또는 제약사항이 다른 컴포넌트들의 집합","컴포넌트 - 보호프로파일 또는 보안목표명세서에서 선택 가능한 최대 단위","엘리먼트 - 보안기능을 세부적으로 표현할 수 있는 단위"],"a":2,"e":"CC(공통평가기준)에서 컴포넌트는 보호프로파일(PP)·보안목표명세서(ST)에서 선택할 수 있는 '최소' 단위입니다. 최대 단위라는 설명이 틀리며, 엘리먼트는 더 이상 나눌 수 없는 가장 하위 요구사항입니다.","ce":["클래스는 동일한 보안 목적(예: 식별 및 인증)을 가진 패밀리들의 집합이므로 옳다.","패밀리는 보안 목적은 같지만 강도·제약사항이 다른 컴포넌트들의 집합이므로 옳다.","CC에서 컴포넌트는 PP·ST에서 선택할 수 있는 '최소' 단위이다. '최대 단위'가 틀렸다.","엘리먼트는 보안기능 요구사항을 세부 표현하는, 더 이상 나눌 수 없는 최하위 단위이므로 옳다."],"rel":["5-6"]},{"n":90,"s":"s5","q":"다음 중 정보보호 및 개인정보보호 관리체계(ISMS-P) 인증 심사원에 대한 설명으로 틀린 것은?","c":["인증심사원의 자격 유효기간은 자격을 부여받은 날로부터 3년이다.","심사원보 자격 취득 후 인증심사에 4회 이상 참여하고 심사 일수의 합이 20일 이상이 되면 심사원 자격을 획득할 수 있다.","인증심사원의 자격발급 및 관리는 금융분야는 금융보안원, 그 외의 분야는 한국인터넷진흥원에서 수행한다.","인증심사원으로서 객관적이고 공정한 인증심사를 수행하지 않는 경우 심사원 자격을 취소할 수 있다."],"a":2,"e":"ISMS-P 인증심사원의 자격 발급·관리는 분야와 관계없이 한국인터넷진흥원(KISA)이 수행합니다. 금융보안원은 금융분야 인증기관으로 심사를 수행할 뿐 심사원 자격을 발급하지 않습니다(개정 여부 확인).","ce":["ISMS-P 인증심사원 자격 유효기간은 부여일로부터 3년이므로 옳은 설명으로 본다(개정 여부 확인).","심사원보가 인증심사 4회 이상, 심사일수 합 20일 이상 참여하면 심사원 자격을 신청할 수 있는 것으로 규정되어 있다(개정 여부 확인).","인증심사원 자격 발급·관리는 분야와 무관하게 한국인터넷진흥원이 수행한다. 금융보안원은 금융분야 인증기관일 뿐이다.","객관적·공정한 심사를 하지 않는 등 자격 취소 사유에 해당하면 심사원 자격을 취소할 수 있으므로 옳다."],"rel":["5-11"]},{"n":91,"s":"s5","q":"정보통신서비스제공자의 지휘·감독을 받아 이용자의 개인정보를 처리하는 역할을 수행하는 개인정보취급자의 역할 및 책임 사항으로 틀린 것은?","c":["내부관리계획 등 각종 규정, 지침 등 준수","개인정보처리시스템의 안전한 운영 및 관리","개인정보보호 교육 세부 수립 및 시행","개인정보 침해사고 발생 시 대응 및 보고"],"a":2,"e":"개인정보보호 교육 계획의 수립·시행은 개인정보 보호책임자의 업무입니다. 개인정보취급자는 규정 준수, 시스템의 안전한 운영, 침해사고 발생 시 대응·보고 등의 책임을 집니다.","ce":["개인정보취급자는 내부관리계획 등 규정·지침을 준수할 책임이 있으므로 옳은 역할이다.","개인정보취급자는 담당 개인정보처리시스템을 안전하게 운영·관리할 책임이 있으므로 옳다.","개인정보보호 교육 계획의 수립·시행은 개인정보 보호책임자(CPO)의 업무로, 취급자는 교육을 받는 대상이다. 가이드 버전에 따라 표현 차이가 있을 수 있다.","침해사고를 인지하면 즉시 대응하고 보호책임자에게 보고하는 것은 취급자의 책임이므로 옳다."],"rel":["5-9"],"sure":false},{"n":92,"s":"s5","q":"정보통신기반 보호법에서 주요정보통신기반시설의 보호에 관한 사항을 심의하기 위하여 정보통신기반보호위원회를 구성하도록 규정하고 있다. 다음 중 정보통신기반보호위원회에 대한 설명으로 옳은 것은?","c":["주요정보통신기반시설의 보호에 관한 사항을 심의하기 위하여 대통령산하에 정보통신기반보호위원회를 둔다.","정보통신기반보호위원회의 위원은 위원장 1인을 포함한 20인 이내의 위원으로 구성한다.","위원회의 위원장은 국무총리가 되고 위원회의 위원은 대통령령이 정하는 중앙행정기관의 차관급 공무원과 위원장이 위촉하는 자로 한다.","정보통신기반보호위원회의 효율적인 운영을 위하여 위원회에 공공분야와 민간분야를 각각 담당하는 실무위원회를 둔다."],"a":3,"e":"정보통신기반 보호법 제3조는 위원회에 공공분야와 민간분야를 각각 담당하는 실무위원회를 두도록 규정합니다. 위원회는 국무총리 소속이고, 위원장 포함 25명 이내로 구성하며, 위원장은 국무조정실장입니다(개정 여부 확인).","ce":["위원회는 대통령 소속이 아니라 국무총리 소속으로 둔다(개정 여부 확인).","위원 수는 위원장을 포함해 20인이 아니라 25인 이내로 규정되어 있다(개정 여부 확인).","현행법상 위원장은 국무총리가 아니라 국무조정실장이며, 위원은 중앙행정기관 차관급 공무원과 위촉 위원으로 구성한다(개정 여부 확인).","정보통신기반 보호법 제3조는 위원회의 효율적 운영을 위해 공공분야·민간분야 실무위원회를 각각 두도록 규정한다."],"rel":["5-13"]},{"n":93,"s":"s5","q":"다음 문장에서 설명하는 용어로 적합한 것은?","c":["개인정보처리시스템","정보보안 관리시스템","정보통신기반시설","출입통제시스템"],"a":2,"e":"정보통신기반 보호법 제2조는 국가안전보장·행정·국방·치안·금융·통신·운송·에너지 등의 업무와 관련된 전자적 제어·관리시스템 및 정보통신망을 정보통신기반시설로 정의합니다.","ce":["개인정보처리시스템은 개인정보를 처리할 수 있도록 체계적으로 구성한 데이터베이스 시스템을 말한다.","정보보안 관리시스템은 법률상 국가 기반 업무 관련 전자적 제어·관리시스템을 지칭하는 정의 용어가 아니다.","정보통신기반 보호법 제2조는 국가안전보장·행정·국방·금융·통신·에너지 등 업무 관련 전자적 제어·관리시스템과 정보통신망을 정보통신기반시설로 정의한다.","출입통제시스템은 물리적 보호구역 출입을 통제하는 보안 설비로, 발문의 법적 정의와 다르다."],"rel":["5-13"],"box":"국가안전보장, 행정, 국방, 치안, 금융, 통신, 운송, 에너지 등의 업무와 관련된 전자적 제어·관리시스템"},{"n":94,"s":"s5","q":"개인정보보호법 안전성확보조치기준에 따라 개인정보처리자는 개인정보취급자가 개인정보처리시스템에 접속한 기록을 1년 이상 보관·관리하여야 한다. 이때 기록해야 하는 항목으로 틀린 것은?","c":["개인정보를 처리한 계정","마지막 로그아웃 시간","수행한 업무의 내용","처리한 정보주체의 정보"],"a":1,"e":"접속기록에는 계정(식별자), 접속일시, 접속지 정보, 처리한 정보주체 정보, 수행업무가 포함되어야 합니다. 마지막 로그아웃 시간은 필수 기록 항목이 아닙니다(개정 여부 확인).","ce":["개인정보를 처리한 계정(식별자)은 접속기록 필수 항목이다.","필수 항목은 계정, 접속일시, 접속지 정보, 처리한 정보주체 정보, 수행업무이며 로그아웃 시간은 포함되지 않는다(개정 여부 확인).","수행한 업무 내용(조회·수정·다운로드 등)은 접속기록 필수 항목이다.","처리한 정보주체를 식별할 수 있는 정보는 접속기록 필수 항목이다."],"rel":["5-9"]},{"n":95,"s":"s5","q":"다음 중 개인정보와 프라이버시에 대한 설명으로 옳은 것은?","c":["개인정보는 자기 자신에 전속한 권리로서 누구의 간섭도 받지 않고 독립적으로 그 권리를 행사할 수 있으나 프라이버시는 실질적으로 수집, 관리하고 있는 기관의 권리도 인정된다.","프라이버시는 정보, 신체, 지역, 금융, 사회적 프라이버시 다섯 가지로 분류된다.","프라이버시는 인격권 그 자체이지만 개인정보는 인격권의 침해가 없더라도 보호해야 할 경우가 있다.","개인정보와 프라이버시에 대한 보호제도는 혼재된 것이 아닌 완전히 다른 개념이다."],"a":2,"e":"프라이버시는 인격권 그 자체인 반면, 개인정보는 인격권 침해가 없더라도 오·남용 방지를 위해 보호해야 하는 경우가 있어 보호 범위가 다릅니다. ①은 프라이버시와 개인정보의 설명이 뒤바뀌었고, ④ 두 보호제도는 서로 겹쳐(혼재되어) 있습니다.","ce":["자기에게 전속되어 독립적으로 행사하는 권리는 프라이버시 쪽이고, 수집·관리 기관의 권리도 인정되는 것은 개인정보 쪽이라 설명이 뒤바뀌었다.","프라이버시는 통상 정보·신체·영역(공간)·통신 프라이버시 4가지로 분류하며, 금융·사회적 프라이버시를 포함한 5분류는 일반적이지 않다.","프라이버시는 인격권 자체이지만, 개인정보는 인격권 침해가 없어도 오·남용 방지를 위해 보호해야 하는 경우가 있어 옳다고 본다. 분류 기준 출처에 따라 ②와 논란 여지가 있다.","개인정보보호와 프라이버시 보호는 보호 대상이 상당 부분 겹쳐 제도가 혼재되어 있으므로 '완전히 다른 개념'은 틀렸다."],"rel":["5-7"],"sure":false},{"n":96,"s":"s5","q":"정보통신망 이용촉진 및 정보보호에 관한 법률 시행령 제36조의 7(정보보호 최고책임자의 지정 및 겸직금지 등)에 규정되어 있는 정보보호 최고책임자의 자격 요건으로 올바르게 정의한 것은?","c":["정보보호 또는 정보기술 분야의 국내 또는 외국의 학사학위이상 학위를 취득한 자","정보보호 또는 정보기술 분야의 국내 또는 외국의 석사학위이상 학위를 취득한 자","정보보호 또는 정보기술 분야의 국내 또는 외국의 학사학위이상 학위를 취득 및 정보보호 또는 정보기술 분야의 5년 이상 경력자","정보보호 또는 정보기술 분야의 국내 또는 외국의 전문학사학위이상 학위를 취득 및 정보보호 또는 정보기술 분야의 10년 이상 경력자"],"a":1,"e":"시행령은 석사학위 이상 취득자, 학사학위 취득 후 3년 이상 경력자, 전문학사 취득 후 5년 이상 경력자, 10년 이상 경력자 등을 자격으로 규정합니다. 따라서 석사학위 이상 취득자(②)가 올바르며, ③은 3년, ④는 5년이 맞습니다(개정 여부 확인).","ce":["학사학위만으로는 부족하며, 시행령은 학사학위 취득 후 일정 기간(3년) 이상 경력을 요구한다(개정 여부 확인).","시행령 제36조의7은 정보보호·정보기술 분야 국내외 석사학위 이상 취득자를 CISO 자격 요건 중 하나로 규정한다(개정 여부 확인).","학사학위 취득자의 요구 경력은 5년이 아니라 3년 이상으로 규정되어 수치가 틀렸다(개정 여부 확인).","전문학사 취득자의 요구 경력은 10년이 아니라 5년 이상이며, 10년은 학위 무관 경력자 요건이다(개정 여부 확인)."],"rel":["5-12"]},{"n":97,"s":"s5","q":"다음 중 위험관리 절차의 순서를 올바르게 나열한 것은?","c":["㉠ - ㉡ - ㉢ - ㉣ - ㉤","㉠ - ㉣ - ㉢ - ㉡ - ㉤","㉠ - ㉡ - ㉣ - ㉢ - ㉤","㉠ - ㉣ - ㉡ - ㉢ - ㉤"],"a":1,"e":"위험관리는 자산 식별 → 위험분석 → 위험평가 → 정보보호대책 선정 → 위험 감시 및 재검토 순으로 진행됩니다.","ce":["자산 식별 다음에 바로 대책 선정(㉡)이 오면 위험분석·평가 없이 대책을 고르는 것이 되어 순서가 틀렸다.","자산 식별(㉠) → 위험분석(㉣) → 위험평가(㉢) → 대책 선정(㉡) → 감시·재검토(㉤)가 올바른 순서이다.","대책 선정(㉡)이 위험분석·평가보다 앞에 와서 순서가 틀렸다.","위험분석(㉣) 뒤에 위험평가(㉢) 없이 대책 선정(㉡)이 먼저 와서 평가·선정 순서가 뒤바뀌었다."],"rel":["5-12","5-2"],"box":"㉠ 자산 식별\n㉡ 식별된 위험에 대한 정보보호대책 선정\n㉢ 위험평가\n㉣ 위험분석\n㉤ 위험 감시 및 재검토"},{"n":98,"s":"s5","q":"시스템 침해사고 발생에 따라 디지털 포렌식을 진행할 때 다음 명령어로 확인할 수 있는 것은?","c":["동작 프로세스 행위 분석","시스템 주요 경로 무결성 점검","서비스 시작과 서비스 확인","시스템 정보 확인"],"a":2,"e":"net start는 실행 중인 서비스 목록을, sc query는 서비스의 상태를 조회하는 윈도우 명령으로, 악성 서비스 등록 여부 등 서비스 시작·상태를 확인할 때 사용합니다.","ce":["프로세스 행위 분석은 tasklist, Process Explorer, Process Monitor 등으로 수행하며 서비스 조회 명령과 다르다.","시스템 주요 경로 무결성 점검은 해시 비교·Tripwire·sigcheck 등으로 수행한다.","net start는 실행 중인 서비스 목록을, sc query는 서비스 상태를 보여줘 악성 서비스 등록·실행 여부를 확인하는 데 쓰인다.","시스템 정보 확인은 systeminfo, hostname, ver 등의 명령으로 수행한다."],"rel":["3-11"],"box":"- net start\n- sc query"},{"n":99,"s":"s5","q":"다음 중 업무용 단말기기 보안에 대한 설명으로 틀린 것은?","c":["업무용 단말기기에 대하여 기기 인증, 승인, 접근범위 설정, 기기 보안 설정 등의 보안 통제 정책을 수립·이행해야 한다.","자료공유프로그램 사용 금지, 공유설정 제한, 무선망 이용 통제 등 개인정보 및 중요정보가 유출되는 것을 방지하기 위한 정책을 수립·이행해야 한다.","업무용 단말기기에 대한 접근통제 대책의 적절성에 대하여 점검하지 않아도 된다.","업무용 단말기기의 분실, 도난 등으로 인한 개인정보 및 중요정보의 유·노출을 방지하기 위하여 비밀번호 설정 등의 보안 정책을 적용하여야 한다."],"a":2,"e":"ISMS-P 2.10.6 업무용 단말기기 보안은 단말기기 접근통제 대책의 적절성을 주기적으로 점검하도록 요구합니다. 점검하지 않아도 된다는 설명은 틀립니다.","ce":["업무용 단말기기에 기기 인증·승인·접근범위·보안 설정 등 통제 정책을 수립·이행하는 것은 ISMS-P 2.10.6 요건이다.","자료공유 프로그램 금지·공유설정 제한·무선망 통제로 정보 유출을 막는 정책은 옳은 요건이다.","ISMS-P 2.10.6은 업무용 단말기기 접근통제 대책의 적절성을 주기적으로 점검하도록 요구하므로 '점검하지 않아도 된다'가 틀렸다.","분실·도난 대비 비밀번호 설정 등 보안 정책을 적용하는 것은 옳은 요건이다."],"rel":["5-11"]},{"n":100,"s":"s5","q":"개인정보처리시스템에 대한 불법적인 접근 및 침해사고 방지를 위한 설명으로 틀린 것은?","c":["개인정보처리시스템의 Session Timeout을 설정해야 한다.","Session Timeout 설정값은 업무상 필요한 최소한의 시간으로 적용해야 한다.","개인정보 취급자의 업무용 컴퓨터 화면보호기 설정을 통해서도 가능하다.","일정시간 이상 업무처리를 하지 않아 개인정보처리시스템에 접속이 차단된 이후 다시 접속하고자 할 때도 최초의 로그인과 동일한 방법으로 접속하여야 한다."],"a":2,"e":"안전성 확보조치 기준의 '일정시간 이상 업무처리를 하지 않는 경우 자동 접속 차단'은 개인정보처리시스템 자체의 세션 차단을 의미하며, 업무용 컴퓨터의 화면보호기 설정으로 대체할 수 없습니다. 재접속 시에는 최초 로그인과 동일한 인증 절차를 거쳐야 합니다.","ce":["안전성 확보조치 기준은 일정 시간 업무처리가 없으면 개인정보처리시스템 접속을 자동 차단하도록 요구하므로 옳다.","차단 시간은 업무 특성을 고려해 필요한 최소한으로 정하도록 권고하므로 옳다.","접속 차단은 개인정보처리시스템 자체의 세션 차단을 의미해 PC 화면보호기로 대체할 수 없다고 보아 정답으로 본다. 다만 일부 해설서가 화면보호기를 보완책으로 언급해 논란 여지가 있다.","세션이 차단된 후 재접속 시에는 최초 로그인과 동일한 인증 절차를 거쳐야 하므로 옳다."],"rel":["5-9"],"sure":false}]},{"id":"2023-03-11","title":"2023년 3월 11일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"윈도우 시스템의 사용자 계정 및 패스워드를 암호화하여 보관하고 있는 SAM(Security Account Manager)에 대한 설명으로 틀린 것은?","c":["HKEY_LOCAL_MACHINE\\SAM에 저장된 키는 일반계정도 확인할 수 있다.","크래킹을 통해 패스워드를 얻을 수 있다.","운영체제가 작동하는 한 접근할 수 없도록 잠겨져 있다.","레지스트리 HKEY_LOCAL_MACHINE\\SAM에 구체화된 자료들을 실제로 저장한다."],"a":0,"e":"HKLM\\SAM 키는 SYSTEM 계정만 접근 가능하며 관리자조차 기본 권한으로는 내용을 볼 수 없으므로 일반계정이 확인할 수 있다는 설명은 틀리다. SAM 파일은 OS 동작 중 잠겨 있지만 오프라인 추출 후 LM/NTLM 해시를 크래킹하여 패스워드를 얻을 수 있다.","ce":["HKLM\\SAM 키는 SYSTEM 계정만 읽을 수 있고 관리자도 기본 권한으로는 하위 내용이 보이지 않으므로, 일반계정이 확인할 수 있다는 진술이 틀렸다.","SAM에 저장된 LM/NTLM 해시를 오프라인으로 추출해 사전·무차별 대입이나 레인보우 테이블로 크래킹하면 패스워드를 얻을 수 있어 옳은 설명이다.","SAM 파일(%SystemRoot%\\system32\\config\\SAM)은 OS 동작 중 커널이 독점적으로 잠가 복사·열람이 불가하므로 옳은 설명이다.","레지스트리 HKLM\\SAM 하이브는 실제로 config\\SAM 파일에 저장된 계정 데이터를 구체화해 보여주는 것이므로 옳은 설명이다."],"rel":["1-2"]},{"n":2,"s":"s1","q":"디스크 스케줄링 알고리즘 중 엘리베이터 알고리즘이라고 불리는 기법은?","c":["SCAN","SSTF","C-SCAN","FCFS"],"a":0,"e":"SCAN은 헤드가 한쪽 끝까지 이동하며 요청을 처리한 뒤 방향을 바꾸는 방식으로, 엘리베이터 동작과 같아 엘리베이터 알고리즘이라 한다. C-SCAN은 한 방향으로만 서비스하고 반대편 끝으로 복귀하며, SSTF는 탐색거리가 가장 짧은 요청을 먼저 처리한다.","ce":["SCAN은 헤드가 한쪽 끝까지 가며 요청을 처리한 뒤 방향을 바꿔 되돌아오는 방식으로, 엘리베이터 동작과 같아 엘리베이터 알고리즘이라 부른다.","SSTF(Shortest Seek Time First)는 현재 헤드 위치에서 탐색거리가 가장 짧은 요청부터 처리하는 방식으로, 기아 현상이 생길 수 있으며 엘리베이터 방식이 아니다.","C-SCAN은 한 방향으로만 요청을 처리하고 끝에 도달하면 반대편 시작점으로 즉시 복귀하는 순환 방식으로, 양방향 왕복하는 엘리베이터(SCAN)의 변형이다.","FCFS(First Come First Served)는 요청이 도착한 순서대로 처리하는 가장 단순한 방식으로, 헤드 이동 방향을 고려하지 않는다."],"rel":["1-1"]},{"n":3,"s":"s1","q":"윈도우에서 제공하는 BitLocker에 대한 설명으로 틀린 것은?","c":["윈도우 7에서도 가능하다.","exFAT 파일 시스템은 지원하지 않는다.","USB 저장매체도 지원 가능하다.","텍스트 파일 형태의 복구키를 제공한다."],"a":1,"e":"BitLocker(BitLocker To Go 포함)는 NTFS뿐 아니라 FAT16/FAT32/exFAT 볼륨도 암호화할 수 있으므로 exFAT 미지원은 틀린 설명이다. Windows 7(Ultimate/Enterprise)부터 지원되며 USB 이동식 저장매체 암호화와 텍스트 파일 형태의 복구키 저장도 제공한다.","ce":["BitLocker는 Windows Vista에서 도입되어 Windows 7 Ultimate/Enterprise에서도 사용 가능하므로 옳은 설명이다.","BitLocker(To Go 포함)는 NTFS뿐 아니라 FAT16·FAT32·exFAT 볼륨도 암호화할 수 있으므로 exFAT 미지원이라는 진술이 틀렸다.","BitLocker To Go 기능으로 USB 메모리 등 이동식 저장매체도 암호화할 수 있으므로 옳은 설명이다.","BitLocker는 48자리 복구키를 텍스트 파일로 저장·인쇄하거나 Microsoft 계정에 백업하는 기능을 제공하므로 옳은 설명이다."],"rel":["1-18"]},{"n":4,"s":"s1","q":"EDR(Endpoint Detection Response) 솔루션의 주요 기능으로 옳지 않은 것은?","c":["보안사고 탐지 영역","보안사고 통제 영역","보안사고 확산 영역","보안사고 치료 영역"],"a":2,"e":"EDR은 엔드포인트에서 보안사고를 탐지·통제(격리·차단)·조사·치료(복구)하는 솔루션으로, 사고 확산을 막는 것이 목적이지 '확산 영역'이라는 기능은 없다.","ce":["EDR은 엔드포인트의 프로세스·파일·네트워크 행위를 수집·분석해 이상 징후를 탐지하는 기능을 핵심으로 하므로 주요 기능에 해당한다.","EDR은 탐지된 위협 단말을 네트워크에서 격리하거나 프로세스를 차단하는 통제(대응) 기능을 제공하므로 주요 기능에 해당한다.","EDR은 사고 확산을 '막는' 솔루션이며 '확산 영역'이라는 기능은 존재하지 않는다. 주요 영역은 탐지·통제·조사(분석)·치료(복구)이다.","EDR은 악성 파일 삭제, 변경된 레지스트리·설정 원복 등 감염 단말을 치료·복구하는 기능을 제공하므로 주요 기능에 해당한다."],"rel":["1-11"]},{"n":5,"s":"s1","q":"Window 서버의 보안 옵션 설정 중 보안 강화를 위한 설정으로 옳지 않은 것은?","c":["\"로그온 하지 않고 시스템 종료 허용\"을 \"사용 안함\"으로 설정하였다.","원격 관리를 위해 \"원격 시스템에서 강제로 종료\" 정책의 \"Administrators\" 외 서버에 등록된 계정을 모두 등록하였다.","\"이동식 미디어 포맷 및 꺼내기 허용\" 정책이 \"Administrators\"로 되어 있다.","\"SAM 계정과 공유의 익명 열거 허용 안함\" 정책을 설정하였다."],"a":1,"e":"\"원격 시스템에서 강제로 종료\" 권한은 Administrators 그룹만 갖도록 제한해야 하며, 다른 계정을 모두 등록하면 원격 서비스 거부 위험이 커진다. 나머지는 주요정보통신기반시설 취약점 점검 기준의 권고 설정이다.","ce":["'로그온하지 않고 시스템 종료 허용'을 사용 안 함으로 두면 로그인하지 않은 사람이 서버를 끌 수 없으므로 권고되는 보안 강화 설정이다.","'원격 시스템에서 강제로 종료' 권한은 Administrators만 가져야 한다. 다른 계정을 모두 등록하면 원격 강제 종료에 의한 서비스 거부 위험이 커져 틀린 설정이다.","'이동식 미디어 포맷 및 꺼내기 허용'을 Administrators로 제한하면 일반 사용자의 이동식 미디어 조작·반출을 막을 수 있어 권고 설정이다.","'SAM 계정과 공유의 익명 열거 허용 안 함'을 설정하면 널 세션으로 계정·공유 목록을 수집하는 정보 노출을 막을 수 있어 권고 설정이다."],"rel":["1-17"]},{"n":6,"s":"s1","q":"웹사이트의 쿠키(cookie)에 대한 설명으로 틀린 것은?","c":["Set-Cookie 헤더를 통해 쿠키를 설정","여러개의 값을 추가시 \"/\" 특수문자를 사용","쿠키의 구조는 이름=값 형태로 구성","사용자 PC에 저장"],"a":1,"e":"쿠키 여러 개의 이름=값 쌍이나 속성은 세미콜론(;)으로 구분하므로 '/' 사용은 틀리다. 쿠키는 서버가 Set-Cookie 응답 헤더로 설정하고 클라이언트(사용자 PC)에 저장된다.","ce":["서버는 HTTP 응답의 Set-Cookie 헤더로 쿠키를 설정하고 브라우저는 이후 요청의 Cookie 헤더로 되돌려 보내므로 옳은 설명이다.","쿠키의 여러 이름=값 쌍이나 속성(Path, Expires 등)은 세미콜론(;)으로 구분하므로 '/' 특수문자를 사용한다는 진술이 틀렸다. '/'는 Path 값에 쓰이는 경로 문자이다.","쿠키는 기본적으로 'name=value' 형태의 이름·값 쌍에 Domain·Path·Expires 등 속성이 붙는 구조이므로 옳은 설명이다.","쿠키는 서버가 아닌 클라이언트(사용자 PC의 브라우저 저장소)에 저장되는 정보이므로 옳은 설명이다. 서버에 저장되는 것은 세션이다."],"rel":["3-3"]},{"n":7,"s":"s1","q":"다음 문장에서 설명하는 공격으로 올바르게 짝지어진 것은?","c":["㉠ : Warwalking, ㉡ : Evil Twin","㉠ : 사전 공격, ㉡ : 무차별 공격","㉠ : 무차별 공격, ㉡ : 사전 공격","㉠ : Evil Twin, ㉡ : Wardriving"],"a":2,"e":"가능한 모든 조합을 자동 대입하는 것은 무차별(Brute Force) 공격, 가능성 높은 단어 목록(사전파일)을 대입하는 것은 사전(Dictionary) 공격이다. Evil Twin·Wardriving은 무선랜 관련 공격이다.","ce":["Warwalking·Wardriving은 걸어서/차로 이동하며 무선 AP를 탐색하는 행위, Evil Twin은 정상 AP를 흉내 낸 가짜 AP 공격으로, 패스워드 크랙 공격이 아니다.","㉠·㉡이 뒤바뀌었다. 자동 조합으로 모든 경우를 대입하는 ㉠이 무차별 공격, 사전파일의 단어를 대입하는 ㉡이 사전 공격이다.","㉠ 모든 조합을 자동 대입하는 것은 무차별(Brute Force) 공격, ㉡ 가능성 높은 단어의 사전파일을 대입하는 것은 사전(Dictionary) 공격으로 올바른 짝이다.","Evil Twin(가짜 AP)과 Wardriving(차량 이동 AP 탐색)은 무선랜 관련 공격·정찰 기법으로, ID·패스워드 대입 크랙 공격이 아니다."],"rel":["4-1"],"box":"- ( ㉠ ) : 시스템 또는 서비스의 ID, 패스워드에 대해서 도구를 이용하여 ID, 패스워드를 자동 조합하여 크랙하는 공격\n- ( ㉡ ) : 시스템 또는 서비스의 ID, 패스워드를 크랙하기 위해서 ID와 패스워드가 될 가능성이 있는 단어를 사전파일로 만들어놓고 사전파일의 단어를 대입하여 크랙하는 공격"},{"n":8,"s":"s1","q":"내부 정보 유출 차단용 보안솔루션에 대한 설명으로 틀린 것은?","c":["문서암호화 솔루션 : PC에 저장되는 파일을 암호화하고 외부로 유출시 복호화 기능","내부정보 유출 방지 솔루션 : 메일, 메신저, 웹 등을 통해 발생할 수 있는 중요정보 유출을 탐지, 차단","문서중앙화 시스템 : 문서 작업의 결과가 원천적으로 PC에 남지 않으므로 파일 유출을 차단","네트워크 방화벽 : PC 메신저나 웹 메일 등 내부정보유출 수단으로 쓰이는 프로그램을 네트워크 방화벽에서 도메인 기준으로 차단"],"a":0,"e":"문서암호화(DRM) 솔루션은 파일을 암호화해 두어 외부로 유출되더라도 권한 없는 사용자가 열람하지 못하게 하는 것이므로, 유출 시 복호화된다는 설명은 틀리다. DLP는 메일·메신저·웹 등 채널의 유출을 탐지·차단한다.","ce":["문서암호화(DRM)는 파일을 암호화한 상태로 유지해 외부로 유출되더라도 권한 없는 사용자가 열람하지 못하게 하는 것이므로, 유출 시 복호화된다는 진술이 틀렸다.","DLP(내부정보 유출 방지)는 메일·메신저·웹 업로드 등 채널의 콘텐츠를 검사해 중요정보 유출을 탐지·차단하므로 옳은 설명이다.","문서중앙화는 작업 문서를 중앙 서버에만 저장하고 PC에는 남기지 않아 로컬 파일 유출을 원천 차단하므로 옳은 설명이다.","네트워크 방화벽에서 웹메일·메신저 서비스의 도메인(또는 IP)을 차단하면 해당 유출 수단 사용을 막을 수 있으므로 옳은 설명이다."],"rel":["1-11"]},{"n":9,"s":"s1","q":"리눅스 환경에서 로그에 대한 설명으로 틀린 것은?","c":["secure 로그 : 사용자의 원격 로그인 정보를 저장","dmesg 로그 : 시스템 부팅 관련 시스템 메시지 저장","lastlog 로그 : 사용자가 로그인한 마지막 로그를 저장","wtmp 로그 : 사용자의 루트 접속 기록 저장"],"a":3,"e":"wtmp는 전체 사용자의 로그인·로그아웃 이력과 시스템 재부팅·종료 기록을 저장하며 last 명령으로 확인한다. 루트 접속만 저장하는 로그가 아니며, su 기록은 sulog, 인증 관련은 secure에 남는다.","ce":["/var/log/secure는 SSH·telnet 등 원격 로그인과 인증(su, sudo 포함) 관련 정보를 기록하므로 옳은 설명이다.","dmesg는 커널 링 버퍼에 저장된 부팅 시 하드웨어 인식·드라이버 메시지를 보여주므로 옳은 설명이다.","lastlog는 각 사용자의 마지막 로그인 시간·접속지를 기록하며 lastlog 명령으로 확인하므로 옳은 설명이다.","wtmp는 루트만이 아닌 전체 사용자의 로그인·로그아웃 이력과 재부팅·종료 기록을 저장하며 last 명령으로 본다. 루트 접속 기록만 저장한다는 진술이 틀렸다."],"rel":["1-7"]},{"n":10,"s":"s1","q":"윈도우 시스템 암호화에 대한 설명으로 틀린 것은?","c":["BitLocker는 윈도우 운영체제에서 제공하는 볼륨 단위와 암호화 기능이다.","BitLocker는 컴퓨터를 시작하는데 필요한 시스템 파티션 부분도 암호화한다.","EFS(Encrypted File Service)는 사용자 단위 데이터 암호화 기능을 제공한다.","EFS(Encrypted File Service)는 컴퓨터 단일 또는 복수 사용자에게 대한 파일 및 폴더 단위 암호화를 지원한다."],"a":1,"e":"BitLocker는 운영체제 볼륨을 암호화하지만 부팅에 필요한 시스템 파티션(부트 파티션)은 암호화하지 않은 상태로 남겨 두어야 부팅이 가능하다. EFS는 NTFS에서 사용자 단위로 파일·폴더를 암호화한다.","ce":["BitLocker는 Windows가 제공하는 전체 볼륨(드라이브) 단위 암호화 기능이므로 옳은 설명이다.","BitLocker는 OS 볼륨을 암호화하되 부팅에 필요한 시스템 파티션은 암호화하지 않고 남겨 두어야 부팅이 가능하므로, 시스템 파티션도 암호화한다는 진술이 틀렸다.","EFS는 NTFS에서 사용자 인증서(키)에 묶어 해당 사용자만 열 수 있게 암호화하는 사용자 단위 암호화 기능이므로 옳은 설명이다.","EFS는 파일·폴더 단위로 암호화하며 다른 사용자의 인증서를 추가해 복수 사용자에게 접근을 허용할 수도 있으므로 옳은 설명이다."],"rel":["1-18","1-3"]},{"n":11,"s":"s1","q":"AI나 머신러닝의 이미지 인식에 있어서 이미지 속에 인간이 감지할 수 없는 노이즈나 작은 변화를 주어 AI 알고리즘의 특성을 악용하여 잘못된 판단을 유도하는 공격은?","c":["Membership inversion 공격","Adversarial 공격","Poisoning 공격","Model inversion 공격"],"a":1,"e":"입력에 사람이 인지하기 어려운 미세한 섭동(perturbation)을 추가해 모델의 오분류를 유도하는 것은 적대적(Adversarial) 공격이다. Poisoning은 학습 데이터 오염, Model inversion은 모델 출력으로 학습 데이터를 역추론하는 공격이다.","ce":["멤버십 추론(Membership inference) 공격은 특정 데이터가 학습 데이터에 포함됐는지를 모델 출력으로 알아내는 프라이버시 공격으로, 입력 변조로 오분류를 유도하는 것이 아니다.","적대적(Adversarial) 공격은 입력 이미지에 사람이 인지 못하는 미세한 섭동을 더해 모델이 잘못 분류하도록 만드는 공격으로 설명과 일치한다.","Poisoning(중독) 공격은 학습 단계에서 오염된 데이터를 주입해 모델 자체를 왜곡하는 공격으로, 추론 단계 입력 노이즈 공격과 다르다.","Model inversion 공격은 모델의 출력·신뢰도를 이용해 학습에 쓰인 원본 데이터(얼굴 등)를 역으로 복원하는 공격이다."],"rel":["1-19"]},{"n":12,"s":"s1","q":"다음은 포맷스트링의 종류를 설명하고 있다. 형식에 대한 매개변수는?","c":["㉠ : %s, ㉡ : %o, ㉢ : %lf","㉠ : %s, ㉡ : %x, ㉢ : %hn","㉠ : %c, ㉡ : %o, ㉢ : %lf","㉠ : %c, ㉡ : %x, ㉢ : %hn"],"a":1,"e":"%s는 문자열, %x는 16진수, %hn은 %n(4바이트 쓰기)의 절반인 2바이트 단위로 출력 문자 수를 기록한다. %o는 8진수, %c는 단일 문자, %lf는 double 실수이다.","ce":["㉠ %s는 맞지만 ㉡ %o는 8진수, ㉢ %lf는 double형 실수 서식이므로 16진수·2바이트 쓰기와 어긋난다.","㉠ %s 문자열, ㉡ %x 16진수 양의 정수, ㉢ %hn은 %n(4바이트 쓰기)의 절반인 2바이트 단위로 출력 문자 수를 기록하므로 모두 올바르다.","㉠ %c는 단일 문자, ㉡ %o는 8진수, ㉢ %lf는 double 실수로 세 항목 모두 설명과 맞지 않는다.","㉡ %x, ㉢ %hn은 맞지만 ㉠ %c는 단일 문자(char) 서식이며 문자스트링은 %s이다."],"rel":["1-10"],"box":"매개변수 | 형식\n%d | 정수형 10진수 상수(integer)\n( ㉠ ) | 문자스트링\n( ㉡ ) | 16진수 양의 정수\n( ㉢ ) | %n의 반인 2바이트 단위"},{"n":13,"s":"s1","q":"netstat 명령어를 통해 확인할 수 없는 정보는?","c":["소켓을 열고 있는 프로세스 ID, 프로세스 이름","라우팅 테이블 정보","열린 포트 정보","데이터 패킷"],"a":3,"e":"netstat은 연결·리스닝 포트, 소켓을 연 프로세스(-p), 라우팅 테이블(-r), 인터페이스 통계 등을 보여주지만 실제 데이터 패킷 내용은 볼 수 없다. 패킷 내용은 tcpdump·Wireshark 같은 스니퍼로 확인한다.","ce":["netstat -p(리눅스) 또는 -o/-b(윈도우) 옵션으로 소켓을 연 프로세스의 PID와 이름을 확인할 수 있다.","netstat -r 옵션으로 커널 라우팅 테이블을 출력할 수 있다.","netstat -an, -l 옵션으로 LISTEN 상태의 열린 포트와 연결 상태를 확인할 수 있다.","netstat은 연결·포트·라우팅·인터페이스 통계만 보여줄 뿐 실제 패킷 내용은 볼 수 없다. 데이터 패킷은 tcpdump·Wireshark 같은 스니퍼로 확인한다."],"rel":["2-2"]},{"n":14,"s":"s1","q":"리눅스에서 제공하는 Cron 기능에 대한 설명으로 틀린 것은?","c":["crontab -r 명령어로 등록된 데이터를 삭제할 수 있다.","루트 권한으로 실행은 불가능하다.","특정 시간에 작업해야 하는 명령어 실행이 가능하다.","파이썬, 펄 등의 스크립트 언어도 실행이 가능하다."],"a":1,"e":"cron은 root 계정의 crontab이나 /etc/crontab에 등록해 루트 권한으로도 작업을 실행할 수 있다. crontab -r은 등록 내용을 삭제하고, 셸·파이썬·펄 등 실행 가능한 모든 명령을 예약 실행할 수 있다.","ce":["crontab -r은 현재 사용자의 crontab 등록 내용을 모두 삭제하는 옵션이므로 옳은 설명이다(-l 조회, -e 편집).","root의 crontab이나 /etc/crontab·/etc/cron.d에 등록하면 루트 권한으로 작업이 실행되므로 불가능하다는 진술이 틀렸다.","cron은 '분 시 일 월 요일' 형식으로 지정한 시각에 명령을 주기적으로 실행하는 스케줄러이므로 옳은 설명이다.","cron은 실행 가능한 명령이면 무엇이든 실행하므로 셸·파이썬·펄 스크립트도 예약 실행할 수 있어 옳은 설명이다."],"rel":["1-16"]},{"n":15,"s":"s1","q":"Visual Basic 스크립트를 이용한 악성코드에 대한 설명으로 옳은 것은?","c":["웹브라우저에서 실행될 경우 스크립트가 브라우저에 내장되므로 파일의 내용을 확인하기 어렵다.","독립형으로 개발할 경우 파일 생성에 제한을 받아 웜형 악성코드를 만들지 못한다.","확장자는 VBA 이다.","러브버그라고 불리는 이메일에 첨부되어 전파된 바이러스가 Visual Basic 스크립트로 개발되었다."],"a":3,"e":"2000년 러브버그(ILOVEYOU) 웜은 LOVE-LETTER-FOR-YOU.TXT.vbs 형태의 VBScript 첨부파일로 전파되었다. VBScript 파일 확장자는 .vbs이며, 독립형(WSH)으로 실행 시 파일 생성·메일 발송이 가능해 웜 제작이 가능하다.","ce":["웹브라우저에서 실행되는 VBScript는 HTML 소스에 평문으로 포함되므로 소스 보기로 내용을 쉽게 확인할 수 있어, 확인하기 어렵다는 설명은 틀리다.","독립형(WSH, .vbs)으로 실행하면 FileSystemObject로 파일 생성·복사, Outlook 개체로 메일 발송이 가능해 웜 제작이 가능하므로 틀린 설명이다.","VBScript 파일의 확장자는 .vbs이며, VBA는 오피스 매크로 언어(Visual Basic for Applications)를 가리키므로 틀린 설명이다.","2000년 러브버그(ILOVEYOU) 웜은 LOVE-LETTER-FOR-YOU.TXT.vbs라는 VBScript 첨부파일로 전파되었으므로 옳은 설명이다."],"rel":["1-19"]},{"n":16,"s":"s1","q":"다음은 sudo 설정파일(/etc/sudoers)의 내용이다. sudo를 통한 명령 사용이 불가능한 사용자는?","c":["uid=(10)guest1, gid(10)guest1, groups=(10)guest1,3(admin)","uid=(11)guest2, gid(11)guest2, groups=(11)guest2,4(sudo)","uid=(12)guest3, gid(12)guest3, groups=(12)guest3,5(adm)","uid=(13)guest4, gid(13)guest4, groups=(13)guest4,5(adm)"],"a":3,"e":"sudoers에서 %admin·%sudo 그룹과 guest3 사용자에게 권한이 있다. guest1은 admin 그룹, guest2는 sudo 그룹, guest3은 사용자 항목으로 허용되지만 guest4는 adm 그룹(로그 열람용)만 속해 sudo 권한이 없다.","ce":["guest1은 admin 그룹(gid 3)에 속하며 sudoers의 '%admin ALL=(ALL) ALL'에 의해 sudo 사용이 가능하다.","guest2는 sudo 그룹(gid 4)에 속하며 '%sudo ALL=(ALL:ALL) ALL'에 의해 sudo 사용이 가능하다.","guest3은 adm 그룹이지만 sudoers에 'guest3 ALL=(ALL:ALL) ALL' 사용자 항목이 있어 sudo 사용이 가능하다.","guest4는 adm 그룹(로그 열람용)에만 속하고 sudoers에 사용자 항목도 없어 sudo 명령을 사용할 수 없다."],"rel":["1-6"],"box":"%admin ALL=(ALL) ALL\n%sudo ALL=(ALL:ALL) ALL\nroot ALL=(ALL:ALL) ALL\nguest3 ALL=(ALL:ALL) ALL"},{"n":17,"s":"s1","q":"랜섬웨어에 대한 설명으로 틀린 것은?","c":["단방향 암호화 방식을 주로 사용한다.","파일 확장자를 임의 변경한다.","안티바이러스 프로그램을 강제 종료한다.","윈도우 복원 시점을 제거한다."],"a":0,"e":"랜섬웨어는 금전을 받고 복호화 키를 제공해야 하므로 복호화가 가능한 대칭키·공개키(하이브리드) 암호를 사용하며, 복호화 불가능한 단방향(해시) 암호화를 쓰지 않는다. 복구를 막기 위해 볼륨 섀도 복사본(복원 시점)을 삭제하고 백신을 종료하기도 한다.","ce":["랜섬웨어는 몸값을 받고 복호화 키를 줘야 하므로 복호화 가능한 대칭키+공개키(하이브리드) 암호를 쓴다. 되돌릴 수 없는 단방향(해시) 암호화를 쓴다는 진술이 틀렸다.","랜섬웨어는 암호화한 파일에 .locky, .WNCRY 등 임의 확장자를 붙여 감염 파일을 표시하므로 옳은 설명이다.","랜섬웨어는 암호화 방해를 막기 위해 백신·보안 프로세스를 강제 종료하기도 하므로 옳은 설명이다.","랜섬웨어는 vssadmin 등으로 볼륨 섀도 복사본(복원 시점)을 삭제해 자체 복구를 막으므로 옳은 설명이다."],"rel":["1-19","1-9"]},{"n":18,"s":"s1","q":"리버스엔지니어링 분석 방법 중 소스코드를 이해하고 분석하는 방법으로 소프트웨어의 프로그래밍 오류와 구현 오류를 찾을 때 유용한 분석 방법은?","c":["블랙박스 분석","화이트박스 분석","그레이박스 분석","그린박스 분석"],"a":1,"e":"화이트박스 분석은 소스코드(내부 구조)를 직접 보고 분석하므로 프로그래밍·구현 오류를 찾는 데 유용하다. 블랙박스 분석은 내부 구조 없이 입력과 출력만으로 동작을 분석한다.","ce":["블랙박스 분석은 소스코드 없이 입력과 출력(외부 동작)만 관찰해 분석하는 방식으로, 소스코드를 이해하는 방법이 아니다.","화이트박스 분석은 소스코드·내부 구조를 직접 보고 분석하므로 프로그래밍 오류와 구현 오류를 찾는 데 유용하다.","그레이박스 분석은 내부 구조 일부 정보만 알고 블랙박스·화이트박스를 혼합해 분석하는 방식으로, 소스코드 전체 이해가 전제가 아니다.","그린박스 분석은 리버스엔지니어링 분석 방법 분류(블랙·화이트·그레이박스)에 없는 용어이다."],"rel":["1-9"]},{"n":19,"s":"s1","q":"침해 당한 리눅스 서버의 하드 디스크를 umount 명령을 통해 분리하는 과정에서 \"Device is busy\"라는 문구 때문에 분리하지 못하고 있는 상황이다. 디바이스를 사용 중인 프로세스를 찾기 위해 사용할 수 있는 명령어로 옳은 것은?","c":["mount","lsof","ps","netstat"],"a":1,"e":"lsof(list open files)는 특정 파일·디바이스·마운트 지점을 열고 있는 프로세스를 보여주므로 umount를 방해하는 프로세스를 찾을 수 있다(fuser -m도 가능). ps는 프로세스 목록만, netstat은 네트워크 연결을 보여준다.","ce":["mount는 파일시스템을 연결하거나 마운트 목록을 보여주는 명령으로, 디바이스를 점유한 프로세스는 알려주지 않는다.","lsof(list open files)는 특정 파일·디바이스·마운트 지점을 열고 있는 프로세스를 보여주므로 umount를 방해하는 프로세스를 찾을 수 있다(fuser -m도 가능).","ps는 실행 중인 프로세스 목록만 보여줄 뿐 어떤 프로세스가 해당 디바이스를 열고 있는지는 알려주지 않는다.","netstat은 네트워크 연결·포트 상태를 보여주는 명령으로, 디스크 디바이스 점유 프로세스 확인과 무관하다."],"rel":["1-16"]},{"n":20,"s":"s1","q":"다음 중 파일 시스템의 무결성 보장을 위해 점검해야 할 사항으로 옳지 않은 것은?","c":["파일의 소유자, 소유그룹 등의 변경 여부 점검","파일의 크기 변경 점검","최근에 파일에 접근한 시간 점검","파일의 symbolic link의 수 점검"],"a":3,"e":"Tripwire 등 무결성 점검은 파일의 소유자·그룹·권한·크기·해시·수정/접근 시간 등 inode 속성 변경을 확인한다. 심볼릭 링크 개수는 inode 속성이 아니어서 점검 대상이 아니며, inode에 기록되는 것은 하드 링크 수이다.","ce":["파일 소유자·소유그룹이 바뀌면 권한 탈취나 백도어 설치 흔적일 수 있어 무결성 점검 대상(inode 속성)이다.","파일 크기 변경은 내용 변조의 직접적 징후이므로 Tripwire 등 무결성 점검 도구가 확인하는 항목이다.","접근·수정 시간(atime/mtime/ctime)은 inode에 기록되며 변조 시점 추적에 쓰이므로 점검 대상이다.","심볼릭 링크 개수는 inode 속성이 아니어서 무결성 점검 항목이 아니다. inode에 기록되어 점검하는 것은 하드 링크 수이다."],"rel":["1-11"]},{"n":21,"s":"s2","q":"다음 문장에서 설명하는 보안시스템은?","c":["NAC","DRM","SSO","IDS"],"a":0,"e":"NAC(Network Access Control)는 IP 관리 시스템에서 발전하여 단말의 MAC 주소 기반 인증·무결성 점검 후 네트워크 접속을 통제한다. DRM은 콘텐츠 저작권 보호, SSO는 통합 인증, IDS는 침입 탐지 시스템이다.","ce":["NAC는 IP 관리 시스템에서 발전해 MAC 주소 기반으로 단말을 인증하고 보안 상태(백신·패치)를 점검한 뒤 네트워크 접속을 통제하는 솔루션으로 설명과 일치한다.","DRM(Digital Rights Management)은 문서·콘텐츠를 암호화해 사용 권한을 통제하는 저작권·정보 보호 솔루션으로, 네트워크 접근 통제가 아니다.","SSO(Single Sign-On)는 한 번 인증으로 여러 시스템에 접속하게 하는 통합 인증 솔루션으로, IP 관리 시스템에서 발전한 것이 아니다.","IDS는 네트워크·호스트의 침입 행위를 탐지하는 시스템으로, MAC 기반 단말 접속 통제 기능이 없다."],"rel":["2-10"],"box":"- 과거 IP 관리 시스템에서 발전한 솔루션으로 기본적인 개념은 IP 관리 시스템과 거의 같고, IP 관리 시스템에 네트워크에 대한 통제를 강화한 보안시스템이다.\n- 접근 제어 및 인증 기능은 일반적으로 MAC 주소를 기반으로 수행된다."},{"n":22,"s":"s2","q":"봇넷(Botnet) 또는 C&C(Command &Control)에 많이 사용되는 프로토콜로 IRC(Internet Relay Chat) 프로토콜이 있다. 다음 중 IRC의 기능이 아닌 것은?","c":["다수의 사용자들과 텍스트 메시지를 공유","사용자들 간의 파일 전송","한 클라이언트의 사용자가 다른 클라이언트 상에서 실행 가능한 메시지 전송","바이러스 프로그램의 제작"],"a":3,"e":"IRC는 채널 기반 다자간 텍스트 채팅, DCC를 이용한 파일 전송, 명령 메시지 전달 기능을 제공하며 봇넷은 이를 C&C 명령 전달에 악용한다. 바이러스 제작은 IRC 프로토콜의 기능이 아니다.","ce":["IRC는 채널에 접속한 다수 사용자가 텍스트 메시지를 실시간으로 공유하는 채팅 프로토콜이므로 기능에 해당한다.","IRC는 DCC(Direct Client-to-Client) SEND로 사용자 간 파일 전송을 지원하므로 기능에 해당한다.","IRC는 CTCP 등으로 다른 클라이언트에서 처리되는 명령 메시지를 보낼 수 있어 봇넷이 C&C 명령 전달에 악용하는 기능이다.","바이러스 제작은 프로그래밍 행위이지 통신 프로토콜인 IRC가 제공하는 기능이 아니다."],"rel":["2-3"]},{"n":23,"s":"s2","q":"어느 회사의 메일 서버가 스팸 메일 발송 경유지로 악용하는 사례가 발생하였다. 이 때 보안관리자는 pcap 파일을 통해 패킷 분석을 진행하고자 보기와 같은 필터링을 실행하였다. 다음 필터링 결과에 대한 설명으로 옳은 것은?","c":["이메일 서비스 확장 지원 세션을 시작한 것을 필터링","SMTP 세션을 시작한 것을 필터링","서버에 인증을 시작한 것을 필터링","메일 데이터 전송을 한 것을 필터링"],"a":0,"e":"EHLO는 ESMTP(확장 SMTP) 세션을 시작하며 서버가 지원하는 확장 기능 목록을 요청하는 명령이다. 기본 SMTP 세션 시작은 HELO, 인증 시작은 AUTH, 메일 본문 전송은 DATA 명령이다.","ce":["EHLO는 ESMTP(확장 SMTP) 세션을 시작하며 서버가 지원하는 확장 기능(AUTH, STARTTLS, SIZE 등) 목록을 요청하는 명령이므로 옳은 설명이다.","기본 SMTP 세션 시작 명령은 HELO이며, EHLO는 확장 기능 지원을 요청하는 ESMTP 세션 시작이므로 단순 SMTP 세션 시작으로 보기 어렵다.","서버 인증 시작은 AUTH 명령(예 AUTH LOGIN)으로 필터링해야 하며, EHLO는 인증 명령이 아니다.","메일 본문 전송 시작은 DATA 명령이며, 수신자·발신자 지정은 RCPT TO·MAIL FROM이다."],"rel":["2-13"],"box":"SMTP.req.command==\"EHLO\""},{"n":24,"s":"s2","q":"리버싱을 하기 위해서는 여러 가지 도구가 필요하다. 제시된 도구들과 그 역할이 올바르게 짝지어진 것은?","c":["㉠-ⓐ, ㉡-ⓑ, ㉢-ⓒ","㉠-ⓐ, ㉡-ⓒ, ㉢-ⓑ","㉠-ⓒ, ㉡-ⓑ, ㉢-ⓐ","㉠-ⓒ, ㉡-ⓐ, ㉢-ⓑ"],"a":1,"e":"OllyDbg는 실행파일(PE)을 디버깅하며 구조와 동작을 확인하는 디버거, Process Explorer(Procexp)는 프로세스 동작 정보 확인, FileMon은 파일 접근 이벤트를 모니터링하는 도구이다.","ce":["㉠-ⓐ는 맞지만 Procexp는 프로세스 동작 정보(ⓒ), Filemonitor는 파일 이벤트(ⓑ)를 확인하는 도구라 ㉡·㉢이 뒤바뀌었다.","OllyDbg는 PE 실행파일을 디버깅해 구조·동작을 확인(ⓐ), Process Explorer는 프로세스 동작 정보(ⓒ), FileMon은 파일 이벤트(ⓑ)를 확인하므로 올바른 짝이다.","OllyDbg는 프로세스 모니터가 아닌 디버거(ⓐ)이고, Filemonitor는 PE 구조가 아닌 파일 이벤트(ⓑ) 도구이므로 ㉠·㉢이 어긋난다.","㉢-ⓑ만 맞고, OllyDbg는 PE 파일 분석(ⓐ), Procexp는 프로세스 정보(ⓒ)이므로 ㉠·㉡이 뒤바뀌었다."],"rel":["1-9"],"box":"㉠ OllyDbg  ⓐ PE 파일의 구조와 동작 확인\n㉡ Procexp  ⓑ 파일 이벤트 정보 확인\n㉢ Filemonitor  ⓒ 프로세스 동작 정보 확인"},{"n":25,"s":"s2","q":"스니핑(sniffing) 기법으로 틀린 것은?","c":["Switch Jamming","SYN Flooding","ARP Redirect","ICMP Redirect"],"a":1,"e":"SYN Flooding은 TCP 3-way handshake의 반개방 연결을 대량으로 만들어 백로그 큐를 고갈시키는 서비스 거부(DoS) 공격이다. Switch Jamming(MAC 테이블 오버플로), ARP Redirect, ICMP Redirect는 스위치 환경에서 트래픽을 공격자에게 우회시키는 스니핑 기법이다.","ce":["Switch Jamming은 위조 MAC으로 스위치 MAC 테이블을 가득 채워 허브처럼 모든 포트로 브로드캐스트하게 만드는 스니핑 기법이다.","SYN Flooding은 SYN만 대량 전송해 반개방 연결로 백로그 큐를 고갈시키는 서비스 거부(DoS) 공격이므로 스니핑 기법이 아니다.","ARP Redirect는 공격자가 자신을 게이트웨이로 속이는 위조 ARP 응답을 보내 트래픽을 자신에게 우회시키는 스니핑 기법이다.","ICMP Redirect는 위조된 ICMP 리다이렉트(Type 5) 메시지로 대상의 라우팅을 공격자 경유로 바꿔 트래픽을 엿보는 스니핑 기법이다."],"rel":["2-5"]},{"n":26,"s":"s2","q":"2016년에 처음 발견되었으며, IP 카메라나 가정용 라우터와 같은 IoT 장치를 주요 공격 대상으로 삼는 DDoS 공격용 봇넷은?","c":["님다(Nimda)","미라이(Mirai)","스턱스넷(Stuxnet)","SQL슬래머(Slammer)"],"a":1,"e":"미라이(Mirai)는 2016년 기본 계정·패스워드를 쓰는 IP 카메라·라우터 등 IoT 기기를 감염시켜 대규모 DDoS(Dyn DNS 공격 등)를 일으킨 봇넷이다. 스턱스넷은 산업제어시스템 공격 웜, 님다·SQL 슬래머는 2001·2003년 웜이다.","ce":["님다(Nimda)는 2001년 이메일·웹·공유폴더 등 다중 경로로 전파된 윈도우 웜으로 IoT 봇넷이 아니다.","미라이(Mirai)는 2016년 기본 계정·패스워드를 쓰는 IP 카메라·라우터 등 IoT 기기를 감염시켜 Dyn DNS 공격 등 대규모 DDoS를 일으킨 봇넷이다.","스턱스넷(Stuxnet)은 2010년 발견된, 이란 원심분리기 등 지멘스 PLC 산업제어시스템을 노린 웜이다.","SQL 슬래머(Slammer)는 2003년 MS SQL Server 취약점(UDP 1434)을 이용해 인터넷 대란을 일으킨 웜이다."],"rel":["2-3","1-19"]},{"n":27,"s":"s2","q":"ARP 스푸핑(Spoofing)은 LAN(Local Area Network) 상에서 MAC 주소를 조작하는 공격기법이다. 이에 대한 설명으로 옳은 것은?","c":["시스템의 ARP 테이블을 동적(Dynamic)으로 관리한다.","ping [ip주소] 명령을 사용하여 시스템을 모니터링한다.","arp -s [ip주소] [mac 주소] 명령을 통해 ARP 테이블을 관리한다.","nslookup [mac 주소] 명령을 사용해 통신경로를 절대경로로 설정한다."],"a":2,"e":"ARP 스푸핑 대응책은 arp -s 명령으로 게이트웨이 등 주요 IP-MAC 쌍을 정적(static)으로 등록하는 것이다. 동적 ARP 테이블은 위조된 ARP 응답으로 덮어써질 수 있어 공격에 취약하다.","ce":["ARP 테이블을 동적으로 관리하면 위조된 ARP 응답으로 캐시가 덮어써지므로 이는 ARP 스푸핑이 가능한 원인이지 대응책이 아니다.","ping은 대상 호스트의 도달 가능 여부만 확인하며 IP-MAC 매핑 변조를 탐지·방지하지 못한다(탐지는 arp -a 확인, arpwatch 등).","arp -s 명령으로 게이트웨이 등 주요 IP-MAC 쌍을 정적(static)으로 등록하면 위조 ARP 응답에 덮어써지지 않아 ARP 스푸핑 대응책으로 옳다.","nslookup은 도메인과 IP를 조회하는 DNS 질의 도구로, MAC 주소를 인자로 받지 않고 통신 경로 설정 기능도 없다."],"rel":["2-5"]},{"n":28,"s":"s2","q":"Tcpdump 를 사용한 패킷 스니핑에 관한 설명이다. 괄호 안에 들어갈 적당한 말은?","c":["㉠ : 포트 스캐닝, ㉡ : 단일 모드","㉠ : 포트 미러링, ㉡ : 무차별 모드","㉠ : 포트 미러링, ㉡ : 단일 모드","㉠ : 포트 스캐닝, ㉡ : 무차별 모드"],"a":1,"e":"포트 미러링(SPAN)은 스위치에서 특정 포트의 트래픽을 복제해 모니터링 포트로 보내는 기능이다. 무차별(Promiscuous) 모드는 NIC가 목적지 MAC이 자신이 아닌 프레임도 폐기하지 않고 수신하는 모드이다.","ce":["포트 스캐닝은 대상의 열린 포트를 찾는 정찰 기법이고, '단일 모드'는 NIC의 수신 모드 용어가 아니므로 ㉠·㉡ 모두 틀렸다.","㉠ 포트 미러링(SPAN)은 스위치 포트 트래픽을 복제해 모니터링 포트로 보내고, ㉡ 무차별(Promiscuous) 모드는 목적지 MAC이 달라도 프레임을 수신하므로 올바르다.","㉠ 포트 미러링은 맞지만 ㉡ 목적지 MAC과 무관하게 수신하는 것은 무차별(Promiscuous) 모드이며 '단일 모드'가 아니다.","㉡ 무차별 모드는 맞지만 ㉠ 패킷 복제는 포트 미러링이며, 포트 스캐닝은 열린 포트 탐색 기법이다."],"rel":["2-5"],"box":"- ( ㉠ ) : 동일 Segment 내 패킷을 복제하여 정보를 수집한다.\n- ( ㉡ ) : 목적지의 MAC 주소가 같지 않아도 패킷을 폐기하지 않고 수신한다."},{"n":29,"s":"s2","q":"네트워크 침입탐지와 방지를 위해 ModSecurity를 설치 운용하고자 한다. ModSecurity 정책 설정을 위해 SecAuditEngine에서 설정할 수 없는 것은?","c":["DetectionOnly","On","Off","RelevantOnly"],"a":0,"e":"SecAuditEngine(감사 로그 설정)의 값은 On, Off, RelevantOnly(관련 트랜잭션만 기록) 세 가지이다. DetectionOnly는 규칙 엔진 설정인 SecRuleEngine의 값(탐지만 하고 차단하지 않음)이다.","ce":["DetectionOnly는 규칙 엔진 설정인 SecRuleEngine의 값(탐지만 하고 차단 안 함)으로, 감사 로그 설정인 SecAuditEngine에는 쓸 수 없다.","SecAuditEngine On은 모든 트랜잭션을 감사 로그에 기록하는 설정값이다.","SecAuditEngine Off는 감사 로그 기록을 끄는 설정값이다.","SecAuditEngine RelevantOnly는 경고·오류 등 관련(SecAuditLogRelevantStatus에 해당) 트랜잭션만 기록하는 설정값이다."],"rel":["2-13"]},{"n":30,"s":"s2","q":"정찰공격(reconnaissance attack)을 위해 사용되는 도구가 아닌 것은?","c":["핑 스윕(Ping sweep)","포트 스캔(Port scan)","패킷 스니퍼(Packet sniffer)","포트 리다이렉션(Port redirection)"],"a":3,"e":"정찰공격은 핑 스윕으로 살아있는 호스트를, 포트 스캔으로 열린 서비스를, 패킷 스니퍼로 네트워크 정보를 수집한다. 포트 리다이렉션은 침투 후 신뢰 관계를 악용해 트래픽을 우회시키는 접근(Access) 공격 기법이다.","ce":["핑 스윕은 ICMP Echo를 대역 전체에 보내 살아 있는 호스트를 파악하는 정찰 도구이다.","포트 스캔은 대상 호스트의 열린 포트와 동작 중인 서비스를 파악하는 대표적인 정찰 도구이다.","패킷 스니퍼는 네트워크 트래픽을 수집해 주소·프로토콜·계정 정보 등을 파악하므로 정찰 단계에서 사용된다.","포트 리다이렉션은 이미 침투한 호스트의 신뢰 관계를 이용해 트래픽을 다른 포트·호스트로 우회시키는 접근(Access) 공격 기법으로, 정찰 도구가 아니다."],"rel":["2-4"]},{"n":31,"s":"s2","q":"다음 IPv4(IP version 4) 데이터그램에 대한 설명으로 옳은 것은?","c":["IPsec(IP Security) 터널모드(Tunnel)의 데이터그램이다.","IPsec(IP Security)의 AH(Authentication Header)가 적용되어 TCP헤더와 TCP데이터는 암호화되어 있다.","IPsec(IP Security)의 AH(Authentication Header)가 적용되어 SA(Security association)를 식별할 수 있다.","IPsec(IP Security)의 AH(Authentication Header)가 적용되어 IPv4 헤더에 무결성, 인증을 위한 데이터가 추가된 데이터그램이다."],"a":2,"e":"AH 헤더에는 SPI(Security Parameters Index)가 있어 목적지 주소·프로토콜과 함께 SA를 식별할 수 있다. 원래 IP 헤더 뒤에 AH가 삽입된 전송모드 구조이며(터널모드는 새 IP 헤더 추가), AH는 암호화 기능이 없고 인증 데이터는 IPv4 헤더가 아닌 별도 AH 헤더에 들어간다.","ce":["원래 IPv4 헤더 바로 뒤에 AH가 삽입된 전송모드 구조이다. 터널모드라면 새 IP 헤더|AH|원래 IP 헤더|TCP 순서가 된다.","AH는 무결성·인증만 제공하고 암호화 기능이 없으므로 TCP 헤더와 데이터가 암호화된다는 설명은 틀리다. 암호화는 ESP가 담당한다.","AH 헤더에는 SPI(Security Parameters Index)가 있어 목적지 IP·보안 프로토콜과 함께 SA를 식별할 수 있으므로 옳은 설명이다.","인증 데이터(ICV)는 IPv4 헤더에 추가되는 것이 아니라 별도의 AH 헤더 안에 들어간다. AH는 IP 헤더의 불변 필드를 인증 범위에 포함할 뿐이다."],"rel":["2-6"],"box":"IPv4 헤더(IPv4 Header) | AH 헤더(Authentication Header) | TCP 헤더(TCP Header) | TCP 데이터(TCP DATA)"},{"n":32,"s":"s2","q":"네트워크 처리 능력을 개선하고자 VLAN을 구성할 때 VLAN 오/남용을 경감시키기 위한 방법으로 옳지 않은 것은? (단, 스위치에 연결된 호스트들을 그룹으로 나누어서 VLAN-1(native)과 VLAN-2로 그룹을 설정하였다고 가정한다.)","c":["관리상 VLAN 관리 정책 서버(VMPS)를 사용한다.","native VLAN 포트 (VLAN ID 1)에 대한 접근을 제한한다.","트렁크 포트들의 native VLAN에 신뢰할 수 없는 네트워크를 붙이지 않는다.","모든 포트에 동적 트렁킹 프로토콜(DTP)을 꺼 놓는다."],"a":0,"e":"VMPS는 MAC 주소 기반으로 VLAN을 동적 할당하는 관리 편의 기능으로, MAC 위조 시 오히려 다른 VLAN 접근이 가능해 VLAN 호핑 경감책이 아니다. native VLAN 접근 제한, 트렁크 native VLAN 분리, DTP 비활성화는 VLAN 호핑(더블 태깅·스위치 스푸핑) 대응책이다.","ce":["VMPS는 MAC 주소에 따라 VLAN을 동적 할당하는 관리 편의 기능으로, MAC 위조 시 다른 VLAN 접근을 허용할 수 있어 오/남용 경감책이 아니다.","native VLAN(VLAN 1)은 태그 없이 전달되어 더블 태깅 VLAN 호핑에 악용되므로 해당 포트 접근 제한은 올바른 경감책이다.","트렁크의 native VLAN에 신뢰할 수 없는 네트워크를 붙이지 않으면 더블 태깅 공격 경로가 차단되므로 올바른 경감책이다.","DTP를 끄면 공격자가 스위치처럼 트렁크 협상을 해 모든 VLAN 트래픽을 받는 스위치 스푸핑을 막으므로 올바른 경감책이다."],"rel":["2-12"]},{"n":33,"s":"s2","q":"다음 문장은 어떤 스푸핑(spoofing) 공격인가?","c":["e-mail 스푸핑","IP 스푸핑","DNS 스푸핑","ARP 스푸핑"],"a":3,"e":"IP 주소를 MAC 주소로 변환하는 프로토콜은 ARP이며, 위조된 ARP 응답으로 대상의 ARP 캐시 테이블을 조작해 트래픽을 가로채는 것이 ARP 스푸핑이다. DNS 스푸핑은 도메인-IP 응답을 위조한다.","ce":["e-mail 스푸핑은 SMTP 발신자 주소(From)를 위조해 다른 사람이 보낸 것처럼 속이는 공격으로, MAC 캐시 조작과 무관하다.","IP 스푸핑은 패킷의 출발지 IP 주소를 위조해 신뢰 호스트로 가장하는 공격으로, IP-MAC 대응 테이블을 조작하지 않는다.","DNS 스푸핑은 DNS 응답을 위조해 도메인을 공격자 IP로 연결시키는 공격으로, 도메인-IP 매핑을 조작한다.","IP를 MAC으로 대응시키는 프로토콜은 ARP이며, 대상의 ARP cache 테이블에 위조 IP-MAC 쌍을 넣어 패킷 흐름을 가로채는 것이 ARP 스푸핑이다."],"rel":["2-5"],"box":"32bit IP 주소를 48bit의 네트워크 카드 주소[MAC Address]로 대응시켜 주는 프로토콜로 실제 IP 주소를 통해 네트워크 연결을 시도하면 TCP/IP 에서는 해당 IP에 해당하는 네트워크 카드 주소를 찾아 연결하게 된다. 이더넷 환경에서 공격대상자의 cache 테이블에 공격자가 원하는 IP에 대한 네트워크 카드 주소[MAC Address] 쌍을 업데이트하며 공격대상자의 패킷 흐름을 공격자가 원하는 방향으로 조절하여 공격하는 기술이다."},{"n":34,"s":"s2","q":"네트워크 공격 유형이 아닌 것은?","c":["패킷 스니핑 공격","포맷스트링 공격","서비스거부 공격","스푸핑 공격"],"a":1,"e":"포맷스트링 공격은 printf 계열 함수의 서식 문자열을 사용자 입력으로 조작해 메모리를 읽거나 쓰는 애플리케이션(시스템) 취약점 공격이다. 스니핑·서비스거부·스푸핑은 네트워크 공격 유형이다.","ce":["패킷 스니핑은 네트워크를 흐르는 패킷을 도청하는 대표적인 네트워크 공격이다.","포맷스트링 공격은 printf 계열 함수에 사용자 입력을 서식 문자열로 넘길 때 %n 등으로 메모리를 읽고 쓰는 애플리케이션(시스템) 취약점 공격이다.","서비스 거부(DoS/DDoS)는 네트워크 트래픽·연결 자원을 고갈시켜 서비스를 방해하는 네트워크 공격이다.","스푸핑(IP·ARP·DNS)은 네트워크 주소·응답을 위조해 트래픽을 속이는 네트워크 공격이다."],"rel":["1-10"]},{"n":35,"s":"s2","q":"IDS(Intrusion Detection System)에 대한 설명으로 틀린 것은?","c":["감사와 로깅할 때 네트워크 자원이 손실되거나 데이터가 변조되지 않는다.","네트워크에서 백신과 유사한 역할을 하는 것으로 네트워크를 통한 공격을 탐지하기 위한 장비이다.","네트워크를 통한 공격을 탐지할뿐 아니라 차단을 수행한다.","설치 위치와 목적에 따라 HIDS와 NIDS로 나뉠 수 있다."],"a":2,"e":"IDS는 공격을 탐지하고 경고하는 수동적 장비이며, 탐지와 함께 실시간 차단까지 수행하는 것은 IPS(Intrusion Prevention System)이다. IDS는 설치 위치에 따라 호스트 기반(HIDS)과 네트워크 기반(NIDS)으로 나뉜다.","ce":["IDS는 트래픽을 복사·관찰해 감사·로깅하므로 원본 네트워크 자원 손실이나 데이터 변조를 일으키지 않는다는 설명은 옳다.","IDS는 알려진 공격 패턴(시그니처)과 이상 행위를 탐지해 알리는, 네트워크의 백신과 유사한 탐지 장비라는 설명은 옳다.","IDS는 탐지·경보 위주의 수동적 장비이며 실시간 차단까지 수행하는 것은 IPS이므로 차단을 수행한다는 진술이 틀렸다.","IDS는 설치 위치에 따라 호스트 기반(HIDS)과 네트워크 기반(NIDS)으로 나뉘므로 옳은 설명이다."],"rel":["2-9"]},{"n":36,"s":"s2","q":"윈도우즈 시스템에서 포트번호와 서비스명 및 전송 프로토콜이 올바르게 연결된 것은?","c":["138-NetBIOS 데이터그램 서비스-UDP","139-NetBIOS 세션 서비스-UDP","110-POP3-UDP","143-IMAP-UDP"],"a":0,"e":"NetBIOS 데이터그램 서비스는 UDP 138을 사용한다. NetBIOS 세션 서비스(139), POP3(110), IMAP(143)은 연결 지향 서비스로 TCP를 사용한다.","ce":["NetBIOS 데이터그램 서비스는 UDP 138번을 사용하므로 올바른 연결이다(이름 서비스 UDP 137).","NetBIOS 세션 서비스는 139번이지만 연결 지향이므로 UDP가 아닌 TCP를 사용한다.","POP3는 110번이지만 메일 수신 세션을 유지하는 TCP를 사용한다.","IMAP은 143번이지만 TCP를 사용한다(IMAPS는 TCP 993)."],"rel":["2-1"]},{"n":37,"s":"s2","q":"다음 문장의 (가), (나)에 들어갈 말로 올바르게 연결된 것은?","c":["가 : Exploit, 나 : Trojan","가 : Imapd, 나 : Trojan","가 : Trojan, 나 : Exploit","가 : Exploit, 나 : Imapd"],"a":2,"e":"정상 프로그램으로 위장해 실행을 유도하고 백도어 포트를 여는 것은 트로이목마(Trojan)이다. 소프트웨어 버그를 이용해 루트 권한 획득 등을 수행하는 공격 코드는 익스플로잇(Exploit)이며, imapd는 IMAP 서버 데몬이다.","ce":["순서가 뒤바뀌었다. 정상 프로그램으로 위장해 포트를 여는 (가)는 트로이목마, 버그를 이용하는 공격 코드 (나)가 익스플로잇이다.","imapd는 IMAP 메일 서버 데몬 이름으로, 위장 악성 프로그램 (가)에 해당하지 않는다. (나)도 Exploit이어야 한다.","(가) 정상 프로그램으로 위장해 실행을 유도하고 백도어 포트를 여는 것은 트로이목마, (나) 버그를 이용해 루트 권한을 얻는 공격 코드는 익스플로잇이므로 올바르다.","(가)는 Trojan이어야 하며, (나)의 imapd는 IMAP 서버 데몬으로 공격 코드가 아니다."],"rel":["1-9"],"box":"- ( 가 )은/는 악의적인 프로그램을 건전한 프로그램처럼 포장하여 일반 사용자들이 의심없이 자신의 컴퓨터 안에서 이를 실행시키고 실행된 ( 가 )은/는 특정 포트를 열어 공격자의 침입을 돕고 추가적으로 정보를 자동 유출하며 자신의 존재를 숨긴다.\n- ( 나 )은/는 OS에서 버그를 이용하여 루트권한 획득 또는 특정 기능을 수행하기 위한 공격 코드 및 프로그램을 의미한다."},{"n":38,"s":"s2","q":"다음 문장에서 설명하는 VPN(Virtual Private Network)으로 옳은 것은?","c":["PPTP","L2TP","SSTP","SSH"],"a":1,"e":"L2TP는 2계층 터널링 프로토콜로 자체 암호화가 없어 IPsec(IKE 키교환, ESP 암호화)과 결합한 L2TP/IPsec으로 사용되며 대부분의 OS·장비가 지원한다. PPTP는 2계층이지만 MPPE/GRE를 쓰고, SSTP는 SSL/TLS 기반이다.","ce":["PPTP는 2계층 터널링이지만 IKE/ESP가 아닌 GRE 캡슐화와 MPPE 암호화를 사용한다.","L2TP는 2계층 터널링 프로토콜로 자체 암호화가 없어 IPsec(IKE 키교환, ESP 암호화)과 결합한 L2TP/IPsec으로 쓰이며 대부분의 OS·장비가 지원한다.","SSTP는 MS가 만든 SSL/TLS(TCP 443) 기반 터널링 프로토콜로 IKE·ESP를 쓰지 않는다.","SSH는 응용계층의 원격 접속 보안 프로토콜로, 2계층 VPN이 아니며 IKE·ESP와 무관하다."],"rel":["2-7"],"box":"- OSI 7 Layer 중 2 Layer에서 동작\n- IKE(Internet Key Exchange)와 ESP(Encapsulation Security Payload)를 사용\n- 대부분의 운영체제 및 네트워크 장비에서 지원"},{"n":39,"s":"s2","q":"다음은 스노트(snort)룰 예시이다. 룰의 구성에 대한 설명으로 틀린 것은?","c":["alert를 발생하고 로그를 남긴다.","패턴 매칭시 대소문자를 구분한다.","content를 첫 번째 바이트로부터 13번째 바이트 범위안에서 검사한다.","출발지를 기준으로 매 1초동안 10번째 이벤트마다 action을 수행한다."],"a":1,"e":"nocase 옵션은 content 패턴 매칭 시 대소문자를 구분하지 않게 한다. depth 13은 페이로드 처음부터 13바이트 범위를 검사하고, threshold type threshold, track by_src, count 10, seconds 1은 출발지별 1초 동안 10번째 이벤트마다 동작한다.","ce":["action이 alert이므로 규칙에 맞는 패킷에 대해 경고를 발생시키고 로그를 남긴다는 설명은 옳다.","nocase 옵션은 content 패턴 매칭 시 대소문자를 구분하지 않게 하므로, 대소문자를 구분한다는 진술이 틀렸다.","depth 13은 페이로드 첫 바이트부터 13바이트 범위 안에서 content를 검사하라는 옵션이므로 옳은 설명이다.","threshold type threshold, track by_src, count 10, seconds 1은 출발지별로 1초 동안 10번째 이벤트마다 action을 수행하므로 옳은 설명이다."],"rel":["2-11"],"box":"alert tcp any any -> any 80 (msg:\"HTTP Get Flooding Detect\"; content:\"GET/HTTP1\"; depth 13; nocase; threshold; type threshold, track by src, count 10, seconds 1; sid:1000001)"},{"n":40,"s":"s2","q":"무선LAN 통신에서 패스프레이즈와 같은 인증없이 단말과 액세스 포인트간의 무선 통신을 암호화하는 것은?","c":["Enhanced Open","FIDO2","WebAuthn","WPA3"],"a":0,"e":"Wi-Fi Enhanced Open은 OWE(Opportunistic Wireless Encryption) 기반으로 패스워드 인증 없는 개방형 무선망에서도 단말과 AP 간 통신을 개별 암호화한다. WPA3-Personal은 SAE 기반 패스프레이즈 인증을 사용하며, FIDO2·WebAuthn은 무패스워드 사용자 인증 표준이다.","ce":["Enhanced Open은 OWE(Opportunistic Wireless Encryption) 기반으로 패스워드 인증 없는 개방형 무선망에서도 단말-AP 간 통신을 개별 암호화한다.","FIDO2는 WebAuthn과 CTAP으로 구성된 무패스워드 사용자 인증 표준으로, 무선 구간 암호화 기술이 아니다.","WebAuthn은 웹 브라우저에서 공개키 기반으로 사용자를 인증하는 W3C 표준 API로, 무선랜 암호화와 무관하다.","WPA3-Personal은 SAE 기반 패스프레이즈 인증을 거쳐 암호화하므로 '인증 없이' 암호화하는 방식이 아니다."],"rel":["2-10"]},{"n":41,"s":"s3","q":"다음 문장에서 설명하는 공격 위협은?","c":["정보 누출","악성 콘텐츠","크로스사이트 스크립팅","디렉터리 인덱싱"],"a":3,"e":"웹 서버의 디렉터리 리스팅 설정으로 인덱스 파일이 없는 디렉터리의 파일 목록이 브라우저에 노출되는 취약점은 디렉터리 인덱싱이다. 정보 누출은 에러 메시지·주석 등을 통한 민감정보 노출을 가리키는 별도 항목이다.","ce":["정보 누출은 에러 메시지·주석·백업파일 등으로 민감정보가 노출되는 넓은 범주로, 디렉터리 파일 목록 노출을 특정한 항목은 디렉터리 인덱싱이다.","악성 콘텐츠는 웹페이지에 악성코드 유포 스크립트 등을 삽입하는 위협으로, 디렉터리 목록 노출과 다르다.","크로스사이트 스크립팅은 입력값에 스크립트를 삽입해 다른 사용자 브라우저에서 실행시키는 공격이다.","인덱스 파일이 없는 디렉터리 요청 시 웹 서버가 파일 목록을 그대로 보여주는 취약점이 디렉터리 인덱싱으로 설명과 일치한다."],"rel":["3-4"],"box":"해당 취약점이 존재할 경우 브라우저를 통해 특정 디렉터리 내 파일 리스트를 노출하며 응용시스템의 구조를 외부에 허용할 수 있고, 민감한 정보가 포함된 설정 파일 등이 노출될 경우 보안상 심각한 위험을 초래할 수 있다."},{"n":42,"s":"s3","q":"다음 중 무선 인터넷 보안 기술에 대한 설명이 맞게 짝지어진 것은?","c":["WAP(Wireless Application Protocol) - 무선 전송계층 보안을 위해 적용한다.","WTLS(Wireless Transport Layer Security) - 이동형 단말기에서 인터넷에 접속하기 위해 고안된 통신 규약이다.","WSP(Wireless Session Protocol) - 장시간 활용하는 세션을 정의하고 세션 관리를 위해 Suspend/Resume 기능과 프로토콜 기능에 대한 협상이 가능하다.","WTP(Wireless Transaction Protocol) - IEEE 802.11i 표준에 정의된 보안규격으로 RC4 알고리즘을 기반으로 한다."],"a":2,"e":"WSP는 WAP 세션 계층으로 장시간 세션 정의와 Suspend/Resume, 기능 협상을 제공한다. 무선 전송계층 보안은 WTLS, 이동 단말 인터넷 접속 규약은 WAP이며, RC4 기반은 WEP/TKIP으로 WTP(트랜잭션 계층)와 무관하다.","ce":["WAP는 이동 단말이 인터넷에 접속하기 위한 무선 응용 통신 규약 전체이며, 무선 전송계층 보안은 WTLS가 담당한다.","WTLS는 WAP의 무선 전송계층 보안 프로토콜(TLS 기반)이며, 이동 단말 인터넷 접속 규약은 WAP이다. 설명이 WAP과 뒤바뀌었다.","WSP는 WAP 세션 계층으로 장시간 세션을 정의하고 Suspend/Resume, 프로토콜 기능 협상을 제공하므로 올바른 짝이다.","WTP는 WAP의 트랜잭션 계층(요청/응답 신뢰성 전송)이며, IEEE 802.11i·RC4 기반 보안규격은 TKIP/WEP 계열 설명이다."],"rel":["3-14"]},{"n":43,"s":"s3","q":"PGP(Pretty Good Privacy)에서 사용하는 암호 알고리즘이 아닌 것은?","c":["RSA","SHA","Diffie-Hellman","AES"],"a":3,"e":"전통적 PGP 교재 기준으로 공개키는 RSA·Diffie-Hellman(ElGamal), 해시는 MD5·SHA-1, 대칭키는 IDEA·3DES·CAST-128을 사용하므로 AES를 정답으로 처리한다. 다만 현행 OpenPGP(RFC 4880)는 AES도 지원하므로 엄밀히는 논란의 여지가 있다.","ce":["RSA는 PGP의 대표 공개키 알고리즘으로 세션키 암호화와 전자서명에 사용된다.","SHA(SHA-1 등)는 PGP에서 메시지 다이제스트(전자서명용 해시)에 사용된다.","Diffie-Hellman(ElGamal 변형)은 PGP에서 세션키 암호화용 공개키 알고리즘으로 사용된다.","전통적 PGP 교재 기준 대칭키는 IDEA·3DES·CAST-128이라 AES를 답으로 처리한다. 단 현행 OpenPGP(RFC 4880)는 AES를 지원하므로 논란의 여지가 있다."],"rel":["3-2"],"flag":"현행 OpenPGP는 AES 지원 — 교재 기준 정답"},{"n":44,"s":"s3","q":"익명 FTP 보안 대책 수립에서 익명 FTP에 불필요한 항목(계정 등)을 제거하기 위한 파일의 경로로 옳은 것은?","c":["/etc/pam.d/ftp","/etc/ftpusers","$root/etc/passwd","/bin/etc/pub"],"a":1,"e":"/etc/ftpusers는 FTP 접속을 거부할 계정 목록 파일로, root 등 불필요한 계정의 FTP 접근을 차단하는 데 사용된다. /etc/pam.d/ftp는 FTP의 PAM 인증 모듈 설정 파일이다.","ce":["/etc/pam.d/ftp는 FTP 데몬의 PAM 인증 모듈 설정 파일로, 계정 목록을 관리하는 파일은 아니다.","/etc/ftpusers는 FTP 접속을 거부할 계정 목록 파일로, root 등 불필요한 계정의 FTP 접근을 제거·차단하는 데 사용된다.","익명 FTP 홈의 ~ftp/etc/passwd는 ls 출력용 최소 정보만 두는 파일로, 접속 계정 제거를 위한 표준 경로로 쓰이지 않는다.","/bin/etc/pub는 존재하지 않는 경로이며, 익명 FTP 공개 디렉터리는 보통 ~ftp/pub이다."],"rel":["3-1"]},{"n":45,"s":"s3","q":"홈·가전 IOT 제품들의 주요 보안위협 원인으로 틀린 것은?","c":["인증메커니즘 부재","물리적 보안 취약점","강도가 약한 비밀번호","취약한 DBMS 버전"],"a":3,"e":"홈·가전 IoT 보안 가이드는 인증 메커니즘 부재, 약한 비밀번호, 암호화 미적용, 펌웨어 업데이트 부재, 물리적 보안 취약점(디버깅 포트 노출) 등을 주요 위협 원인으로 든다. 취약한 DBMS 버전은 IoT 제품의 주요 위협 원인으로 분류되지 않는다.","ce":["인증 메커니즘 부재로 누구나 기기에 접속·제어할 수 있는 것은 홈·가전 IoT의 주요 보안위협 원인이다.","디버깅 포트(UART·JTAG) 노출 등 물리적 보안 취약점은 펌웨어 추출·변조로 이어지는 주요 위협 원인이다.","기본 비밀번호·약한 비밀번호 사용은 Mirai 봇넷 감염의 원인이 된 대표적 IoT 위협 원인이다.","홈·가전 IoT 보안 가이드의 위협 원인(인증 부재, 약한 비밀번호, 암호화 미적용, 업데이트 부재, 물리 취약점)에 취약한 DBMS 버전은 포함되지 않는다."],"rel":["1-15"]},{"n":46,"s":"s3","q":"다음 중 SQL Injection의 공격 유형이 아닌 것은?","c":["인증 우회","데이터 노출","원격 명령 실행","서비스 거부"],"a":3,"e":"SQL Injection으로 인증 우회(항상 참 조건 삽입), 데이터 노출(UNION 기반 등), 확장 프로시저(xp_cmdshell 등)를 이용한 원격 명령 실행이 가능하다. 서비스 거부는 SQL Injection의 대표 공격 유형으로 분류되지 않는다.","ce":["' OR '1'='1 같은 항상 참 조건을 삽입해 로그인 인증을 우회하는 것은 대표적인 SQL Injection 유형이다.","UNION SELECT, 에러 기반, 블라인드 기법으로 DB 데이터를 조회·노출시키는 것은 SQL Injection 유형이다.","MS-SQL의 xp_cmdshell 같은 확장 프로시저를 호출해 OS 명령을 실행하는 것도 SQL Injection 유형이다.","서비스 거부는 SQL Injection의 대표 공격 유형(인증 우회·데이터 노출·원격 명령 실행)으로 분류되지 않는다."],"rel":["3-6"]},{"n":47,"s":"s3","q":"버퍼오버플로우 공격을 막기 위해 사용을 권장하는 프로그램 함수는?","c":["strcat( )","strncat( )","gets( )","sscanf( )"],"a":1,"e":"strncat()은 복사할 최대 길이를 인자로 지정해 버퍼 경계를 넘지 않도록 할 수 있어 권장된다. strcat(), gets(), sscanf()(%s 사용 시)는 입력 길이를 검사하지 않아 버퍼 오버플로에 취약한 함수이다.","ce":["strcat()은 목적 버퍼 크기를 검사하지 않고 문자열을 이어 붙여 버퍼 오버플로에 취약한 함수이다.","strncat()은 붙일 최대 길이를 인자로 지정해 버퍼 경계를 넘지 않게 할 수 있어 권장 함수이다(strlcat 등도 사용).","gets()는 입력 길이를 전혀 제한하지 않아 가장 위험한 함수로 폐기되었으며 fgets()로 대체해야 한다.","sscanf()는 %s 서식 사용 시 길이 제한이 없어 오버플로에 취약하므로 권장 함수가 아니다(%10s처럼 폭 지정 필요)."],"rel":["1-10","3-9"]},{"n":48,"s":"s3","q":"다음 문장에서 설명하는 것은?","c":["복합서명","복합암호화","이중서명","이중암호화"],"a":2,"e":"SET의 이중서명(Dual Signature)은 주문정보(OI)와 지불정보(PI)의 해시를 연결해 다시 해시한 값을 고객 개인키로 서명한다. 이를 통해 상점은 지불정보를, 은행은 주문정보를 보지 못하면서도 두 정보의 연관성을 검증할 수 있다.","ce":["'복합서명'은 SET 표준 용어가 아니며, 주문·지불정보 해시를 결합해 서명하는 방식은 이중서명이다.","복합암호화는 SET 용어가 아니며, 설명은 암호화가 아니라 개인키 서명 절차이다.","SET의 이중서명은 주문정보(OI)와 지불정보(PI)의 해시를 연결해 다시 해시한 값을 고객 서명용 개인키로 암호화하는 방식으로 설명과 일치한다.","이중암호화는 같은 데이터를 두 번 암호화하는 개념으로, 해시 결합 후 개인키로 서명하는 이중서명과 다르다."],"rel":["3-10"],"box":"주문정보의 메시지 다이제스트와 지불정보의 메시지 다이제스트를 합하여 다시 이것의 메시지 다이제스트를 구한 후 고객의 서명용 개인키로 암호화한다."},{"n":49,"s":"s3","q":"다음 문장에서 설명하는 공격 대응 방법은?","c":["DNS 라우팅","DNS 스푸핑","DNS 웜홀","DNS 싱크홀"],"a":3,"e":"DNS 싱크홀은 봇이 C&C 서버 도메인을 질의할 때 싱크홀 서버 IP를 응답하여 C&C 연결을 차단하고 감염 PC를 탐지하는 대응 기법이다(KISA 운영). DNS 스푸핑은 DNS 응답을 위조하는 공격 기법이다.","ce":["DNS 라우팅은 정식 보안 대응 기법 용어가 아니며, 봇의 C&C 접속을 우회시키는 기법은 DNS 싱크홀이다.","DNS 스푸핑은 DNS 응답을 위조해 사용자를 악성 사이트로 유도하는 공격 기법으로, 대응 방법이 아니다.","DNS 웜홀은 해당 대응 기법 용어가 아니다(웜홀은 무선 애드혹 네트워크 공격 용어).","DNS 싱크홀은 봇이 C&C 도메인을 질의하면 싱크홀 서버 IP를 응답해 명령 수신을 차단하고 감염 PC를 파악하는 대응 기법이다(KISA 운영)."],"rel":["3-7","2-3"],"box":"악성봇에 감염된 PC를 해커가 제어하지 못하도록 하는 방법으로 악성봇이 해커의 제어 서버에 연결 시도시 특정 서버로 우회 접속되도록 하며 해커의 악의적인 명령을 전달받지 못하도록 한다."},{"n":50,"s":"s3","q":"안드로이드 앱 구조 요소 중 앱 실행시 반드시 필요한 권한을 선언하며, 안드로이드 빌드 도구 및 안드로이드 운영체제에 관한 필수 정보를 설명하는 파일은?","c":["AndroidManifest.xml","MainActivity","activity_main.xml","build.gradle"],"a":0,"e":"AndroidManifest.xml은 패키지명, 구성요소(Activity·Service 등), 필요 권한(uses-permission)을 선언해 빌드 도구와 OS에 앱 필수 정보를 제공한다. activity_main.xml은 화면 레이아웃, build.gradle은 빌드 설정 파일이다.","ce":["AndroidManifest.xml은 패키지명, 구성요소(Activity·Service 등), 필요한 권한(uses-permission)을 선언해 빌드 도구와 OS에 필수 정보를 제공한다.","MainActivity는 앱의 시작 화면을 구현한 Java/Kotlin 클래스로, 권한 선언 파일이 아니다.","activity_main.xml은 액티비티의 화면 레이아웃(UI 배치)을 정의하는 리소스 파일이다.","build.gradle은 SDK 버전·의존성 라이브러리 등 빌드 설정 파일로, 실행 권한은 매니페스트에서 선언한다."],"rel":["1-15"]},{"n":51,"s":"s3","q":"이메일 클라이언트를 이용해 이메일을 발송하는 경우 SMTP가 사용된다. 인증절차 후 이메일을 발송하는 절차로 옳은 것은?(문제 오류로 가답안 발표시 2번으로 발표되었지만 확정답안 발표시 모두 정답처리 되었습니다. 여기서는 가답안인 2번을 누르면 정답 처리 됩니다.)","c":["EHLO > MAIL > RCPT > DATA > QUIT","EHLO > AUTH > RCPT > MAIL > DATA > QUIT","AUTH > EHLO > RCTP > DATA > QUIT","AUTH > EHLO > RCTP > MAIL > DATA > QUIT"],"a":1,"e":"SMTP 인증 발송 순서는 EHLO → AUTH → MAIL FROM → RCPT TO → DATA → QUIT이다. 가답안 ②는 MAIL과 RCPT 순서가 뒤바뀌어 있고 ①은 AUTH가 없어 보기 중 완전히 맞는 것이 없으므로 확정답안에서 전항 정답 처리되었다.","ce":["EHLO 뒤 MAIL→RCPT→DATA→QUIT 순서는 맞지만 인증 명령 AUTH가 빠져 '인증절차 후 발송' 조건을 충족하지 못한다. 확정답안에서 전항 정답 처리되었다.","가답안이다. EHLO→AUTH로 시작하는 점은 맞으나 MAIL FROM(발신자)이 RCPT TO(수신자)보다 먼저 와야 하는데 순서가 뒤바뀌어, 확정답안에서 전항 정답 처리되었다.","AUTH는 EHLO로 확장 기능(AUTH 지원)을 확인한 뒤에 보내야 하며, MAIL 명령도 빠져 있다(RCTP는 RCPT 오기). 확정답안에서 전항 정답 처리되었다.","AUTH가 EHLO보다 먼저 올 수 없다. 올바른 순서는 EHLO→AUTH→MAIL→RCPT→DATA→QUIT이며, 확정답안에서 전항 정답 처리되었다."],"rel":["3-2"],"flag":"확정답안 전항 정답 처리 문항(가답안 ②)"},{"n":52,"s":"s3","q":"다음 중 안드로이드 시스템 권한에 대한 설명으로 틀린 것은?","c":["ACCESS_CHECKIN_PROPERTIES : 체크인 데이터베이스의 속성테이블 액세스 권한","LOADER_USAGE_STATS : 액세스 로그 읽기 권한","SET_PROCESS_LIMIT : 제한처리 지정 권한","CHANGE_COMPONENT_ENABLED_STATE : 환경 설정 변경 권한"],"a":3,"e":"CHANGE_COMPONENT_ENABLED_STATE는 앱 구성요소(컴포넌트)의 활성화/비활성화 상태를 변경하는 권한이며, 환경 설정 변경 권한은 CHANGE_CONFIGURATION이다. ACCESS_CHECKIN_PROPERTIES와 SET_PROCESS_LIMIT 설명은 맞다.","ce":["ACCESS_CHECKIN_PROPERTIES는 체크인 데이터베이스의 properties 테이블에 읽기/쓰기 액세스를 허용하는 권한으로 설명이 맞다.","LOADER_USAGE_STATS는 앱 사용 통계(액세스 로그) 데이터를 읽을 수 있게 하는 시스템 권한으로 설명이 맞다.","SET_PROCESS_LIMIT는 실행 가능한 최대 애플리케이션 프로세스 수 제한을 지정하는 권한으로 설명이 맞다.","CHANGE_COMPONENT_ENABLED_STATE는 앱 구성요소(컴포넌트)의 활성화/비활성화 상태를 바꾸는 권한이다. 환경 설정 변경 권한은 CHANGE_CONFIGURATION이다."],"rel":["1-15"]},{"n":53,"s":"s3","q":"XSS(Cross-Site Scripting)에 대한 설명으로 틀린 것은?","c":["XSS 공격은 다른 사용자의 정보를 추출하기 위해 사용되는 공격 기법을 말한다.","사용자가 전달하는 입력값 부분에 스크립트 태그를 필터링 하지 못하였을 때 XSS 취약점이 발생한다.","Stored XSS는 게시판 또는 자료실과 같이 사용자가 글을 저장할 수 있는 부분에 정상적인 평문이 아닌 스크립트 코드를 입력하는 기법을 말한다.","Reflected XSS는 웹 애플리케이션상에 스크립트를 저장해 놓은 것이다."],"a":3,"e":"Reflected XSS는 스크립트가 서버에 저장되지 않고, 조작된 URL 파라미터의 스크립트가 서버 응답에 그대로 반사되어 피해자 브라우저에서 실행되는 방식이다. 웹 애플리케이션에 스크립트를 저장해 두는 것은 Stored XSS이다.","ce":["XSS는 악성 스크립트를 피해자 브라우저에서 실행시켜 쿠키·세션 등 다른 사용자의 정보를 탈취하는 공격이므로 옳은 설명이다.","입력값의 <script> 등 태그·특수문자를 필터링·인코딩하지 않고 출력할 때 XSS 취약점이 발생하므로 옳은 설명이다.","Stored XSS는 게시판·자료실 등 서버에 저장되는 입력란에 스크립트를 넣어 열람자마다 실행되게 하는 방식이므로 옳은 설명이다.","Reflected XSS는 스크립트를 저장하지 않고 조작된 URL 파라미터가 서버 응답에 그대로 반사되어 실행되는 방식이다. 스크립트를 저장해 두는 것은 Stored XSS이다."],"rel":["3-6"]},{"n":54,"s":"s3","q":"검색엔진에서 자동으로 사이트를 수집 및 등록하기 위해서는 사용하는 크롤러(Crawler)로부터 사이트를 제어하기 위해서 사용하는 파일은?","c":["crawler.txt","access.conf","httpd.conf","robots.txt"],"a":3,"e":"robots.txt는 웹 루트에 두어 검색엔진 크롤러의 수집 허용·차단 경로를 지정하는 파일(로봇 배제 표준)이다. httpd.conf·access.conf는 Apache 웹 서버 설정 파일이다.","ce":["crawler.txt는 표준에 정의된 파일이 아니며, 크롤러 제어는 로봇 배제 표준 파일인 robots.txt로 한다.","access.conf는 구버전 Apache에서 디렉터리별 접근 제어를 설정하던 서버 설정 파일로, 외부 크롤러에 수집 규칙을 알리는 용도가 아니다.","httpd.conf는 Apache 웹 서버의 주 설정 파일로, 검색엔진 크롤러가 읽는 파일이 아니다.","robots.txt는 웹 루트에 두고 User-agent·Disallow로 크롤러의 수집 허용·차단 경로를 지정하는 로봇 배제 표준 파일이다."],"rel":["3-4"]},{"n":55,"s":"s3","q":"안드로이드(Android) 플랫폼을 기반으로 개발된 모바일 앱의 경우, 디컴파일 도구 이용시 실행파일(.apk)을 소스코드로 쉽게 변환시킬 수 있어 앱 구조 및 소스코드를 쉽게 분석할 수 있다. 이를 방지하기 위한 기술은?","c":["난독화","무결성 점검","안티 디버깅","루팅"],"a":0,"e":"난독화(Obfuscation)는 클래스·메서드명 변경, 제어흐름 변형, 문자열 암호화 등으로 디컴파일된 코드의 분석을 어렵게 한다(ProGuard 등). 안티 디버깅은 동적 분석(디버거 연결)을 막는 기술이며 루팅은 관리자 권한 획득이다.","ce":["난독화는 클래스·메서드명 치환, 제어흐름 변형, 문자열 암호화 등으로 디컴파일된 코드를 이해하기 어렵게 만드는 정적 분석 방지 기술이다(ProGuard, DexGuard).","무결성 점검은 앱 서명·해시를 확인해 위변조(리패키징) 여부를 탐지하는 기술로, 디컴파일된 소스 분석 자체를 어렵게 하지는 못한다.","안티 디버깅은 디버거 연결을 탐지·차단해 동적 분석을 방해하는 기술로, 디컴파일을 통한 정적 소스 분석 방지와는 대상이 다르다.","루팅은 안드로이드 기기의 관리자(root) 권한을 획득하는 행위로, 보호 기술이 아니라 오히려 보안 위협 요인이다."],"rel":["3-9"]},{"n":56,"s":"s3","q":"다음 중 DNS 증폭 공격(DNS Amplification DDoS Attack)에 대한 설명으로 틀린 것은?","c":["DNS 질의는 DNS 질의량에 비하여 DNS 서버의 응답량이 훨씬 크다는 점을 이용한다.","DNS 프로토콜에는 인증 절차가 없다는 점을 이용한다.","Open DNS Resolver 서버에 DNS Query의 Type을 \"Any\"로 요청한다.","대응 방안으로 DNS 서버 설정을 통해 내부 사용자의 주소만 반복쿼리(Interactive Query)를 허용한다."],"a":3,"e":"대응 방안은 내부 사용자에게만 재귀 질의(Recursive Query)를 허용하여 Open Resolver가 되지 않게 하는 것이므로, 반복쿼리(Iterative Query) 허용이라는 설명은 틀리다. 공격자는 출발지 IP를 피해자로 위조해 ANY 타입 질의를 보내 작은 요청으로 큰 응답을 유발한다.","ce":["DNS 증폭 공격은 수십 바이트 질의로 수천 바이트 응답을 유발하는 응답 크기 차이(증폭률)를 이용하므로 옳은 설명이다.","DNS는 UDP 기반이고 질의자 인증이 없어 출발지 IP를 피해자 주소로 위조한 질의가 가능하므로 옳은 설명이다.","Open Resolver에 모든 레코드를 요청하는 ANY 타입 질의를 보내 응답 크기를 키우므로 옳은 설명이다.","대응 방안은 내부 사용자에게만 재귀 질의(Recursive Query)를 허용해 Open Resolver가 되지 않게 하는 것이다. '반복쿼리(Iterative) 허용'이라는 진술이 틀렸다."],"rel":["3-7","2-3"]},{"n":57,"s":"s3","q":"다음 문장에서 설명하는 데이터베이스의 보안 사항은?","c":["DDL(Data Definition Language)","뷰(View)","SQL(Structed Query Language)","DCL(Data Control Language)"],"a":1,"e":"뷰(View)는 기본 테이블에서 필요한 행·열만 선택해 만든 가상 테이블로, 사용자에게 뷰에만 권한을 주어 열 단위 접근통제를 간편하게 구현한다. DCL은 GRANT·REVOKE 같은 권한 제어 언어이다.","ce":["DDL은 CREATE·ALTER·DROP 등 데이터 구조를 정의하는 언어로, 열 단위 권한 설정을 대신하는 가상 테이블이 아니다.","뷰(View)는 기본 테이블에서 필요한 행·열만 골라 만든 가상 테이블로, 사용자에게 뷰에만 권한을 주어 열 단위 접근통제를 간편하게 구현한다.","SQL은 관계형 DB를 다루는 질의 언어 전체를 가리키며, 특정 보안 수단인 가상 테이블이 아니다.","DCL은 GRANT·REVOKE 등 권한을 부여·회수하는 언어로, 권한 설정의 불편을 줄이기 위해 만든 가상 테이블 자체는 아니다."],"rel":["3-8"],"box":"각 사용자에 대해 참조 테이블의 각 열에 대한 권한을 설정하는 것이 불편해서 만든 가상 테이블이다."},{"n":58,"s":"s3","q":"어플리케이션의 공유 라이브러리에 대한 호출을 확인하기 위해 사용되는 리눅스의 디버깅 유틸리티는?","c":["windbg","jdbc","ltrace","tcpdump"],"a":2,"e":"ltrace는 프로세스가 호출하는 공유 라이브러리 함수를 추적하는 리눅스 유틸리티이다(시스템 콜 추적은 strace). windbg는 윈도우 디버거, jdbc는 자바 DB 연결 API, tcpdump는 패킷 캡처 도구이다.","ce":["windbg는 마이크로소프트의 윈도우용 디버거로, 리눅스 공유 라이브러리 호출 추적 유틸리티가 아니다.","JDBC는 자바 프로그램이 DB에 접속하기 위한 API로 디버깅 유틸리티가 아니다.","ltrace는 프로세스가 호출하는 공유 라이브러리 함수와 인자·반환값을 추적하는 리눅스 유틸리티이다(시스템 콜 추적은 strace).","tcpdump는 네트워크 패킷을 캡처·분석하는 도구로 라이브러리 호출 추적과 무관하다."],"rel":["3-9"]},{"n":59,"s":"s3","q":"다음 문장에서 설명하는 것은?","c":["EDI(Electronic Data Interchange)","XML/EDI","XML(Extensible Markup Language)","ebXML(Electronic Business Extensible Markup Language)"],"a":3,"e":"ebXML은 UN/CEFACT와 OASIS가 공동 개발한 XML 기반 전자상거래 개방형 표준 프레임워크이다. EDI는 표준 전자문서 교환 방식, XML은 W3C의 범용 마크업 언어이다.","ce":["EDI는 기업 간 표준화된 전자문서를 전용망(VAN)으로 교환하는 방식으로, UN/CEFACT·OASIS가 개발한 XML 기반 개방형 표준이 아니다.","XML/EDI는 기존 EDI 문서를 XML로 표현하려는 접근 방식을 가리키며, UN/CEFACT와 OASIS가 공동 제정한 표준 명칭은 ebXML이다.","XML은 W3C가 제정한 범용 마크업 언어로, 전자상거래 전용 프레임워크 표준이 아니다.","ebXML은 UN/CEFACT와 OASIS가 공동 개발한 XML 기반 전자상거래 개방형 표준 프레임워크로 설명과 일치한다."],"rel":["3-14"],"box":"모든 거래 당사자가 상호 운영성과 일관성이 확보된 환경에서 안전하게 전자상거래 정보를 사용할 수 있도록 개방형 기반 구조를 제공하는 것을 목표로 하며 전자상거래를 위해 UN/CEFACT와 민간 비영리 IT 표준화 컨소시엄인 OASIS가 개발한 전자상거래 분야 개방형 표준이다."},{"n":60,"s":"s3","q":"다음 설명과 같이 서버에서 활성화 여부를 점검해야하는 프로토콜은?","c":["tftp","vsftp","ftp","proftp"],"a":0,"e":"TFTP(Trivial FTP)는 UDP 69번을 사용하는 단순 파일 전송 프로토콜로 인증 절차가 없어 불필요 시 비활성화해야 하며, 네트워크 부팅(PXE) 등에 쓰인다. vsftpd·proftpd는 인증을 지원하는 FTP 서버 프로그램이다.","ce":["TFTP는 UDP 69번을 쓰는 단순 파일 전송 프로토콜로 인증 절차가 없고 네트워크 부팅(PXE)·장비 설정 파일 전송에 쓰이므로 불필요 시 비활성화해야 한다.","vsftpd는 ID/PW 인증과 chroot 등 보안 기능을 지원하는 FTP 서버 프로그램으로, 인증 절차가 없다는 설명과 맞지 않는다.","FTP는 TCP 20/21을 쓰며 사용자 인증 절차가 있고 구조가 TFTP보다 복잡하다.","ProFTPD는 인증을 지원하는 FTP 서버 프로그램으로, 설명의 단순·무인증 프로토콜이 아니다."],"rel":["3-1"],"box":"- 파일 전송을 위한 프로토콜로서 FTP 서비스보다 구조가 단순하며, 적은 양의 데이터를 보낼 때 사용한다.\n- 주로 원격의 부팅파일을 불러오거나 설치 프로세스를 시작하기 위한 초기 데이터 호출 용도로 사용한다.\n- 사용시 인증절차가 없어 보안에 취약하다."},{"n":61,"s":"s4","q":"CRL(Cetificate Revocation List)에 포함되는 정보는?","c":["만료된 디지털 인증서의 공개키","만료된 디지털 인증서 일련번호","만료일 내에 만료된 디지털 인증서의 공개키","만료일 내에 만료된 디지털 인증서 일련 번호"],"a":1,"e":"CRL에는 폐기된 인증서의 일련번호와 폐기 일자·사유가 수록되며 공개키는 포함되지 않는다. 이 문항은 확정답안이 ②로, 유효기간 내 폐기된 인증서 일련번호를 뜻하는 ④와의 구분이 모호한 표현이다.","ce":["CRL에는 폐기된 인증서의 일련번호·폐기 일자·사유가 수록될 뿐 공개키는 포함되지 않는다.","확정답안이다. CRL은 인증서를 일련번호로 식별해 목록화하며 공개키는 넣지 않는다. 다만 엄밀히는 '만료'가 아닌 '폐기(유효기간 내)' 인증서이므로 ④와 표현상 모호하다.","유효기간 내 폐기된 인증서라도 CRL에는 공개키가 아닌 일련번호가 수록되므로 틀린 설명이다.","유효기간 내 폐기된 인증서의 일련번호라는 의미로 내용상 CRL과 맞아 보이지만, 공식 확정답안은 ②이다. 표현이 모호해 논란이 있는 보기이다."],"rel":["4-7"],"flag":"④와 표현상 모호 — 확정답안 ② 기준"},{"n":62,"s":"s4","q":"다음 문장은 어떤 인증방식을 설명한 것인가?","c":["OTP","UTP","SEP","전자화폐"],"a":0,"e":"OTP(One Time Password)는 인증할 때마다 새로 생성되는 일회용 비밀번호로, 노출된 비밀번호를 재사용하는 공격을 막는다. UTP는 비차폐 꼬임쌍선 케이블로 인증과 무관하다.","ce":["OTP(One Time Password)는 인증 시마다 새로 생성되는 일회용 비밀번호로, 노출된 비밀번호의 재사용 공격을 방지하므로 설명과 일치한다.","UTP(Unshielded Twisted Pair)는 비차폐 꼬임쌍선 네트워크 케이블로 인증 방식과 무관하다.","SEP는 일회성 인증암호 체계를 가리키는 표준 인증 용어가 아니다.","전자화폐는 화폐 가치를 전자적으로 저장·지급하는 결제 수단으로 사용자 인증 방식이 아니다."],"rel":["4-8"],"box":"원격 사용자 인증시 유발되는 패스워드 재사용 공격을 방지하기 위한 기술이며, 사용시마다 매번 바뀌는 일회성 사용자 인증암호 및 체계로 사용자의 관리 소홀이나 패스워드가 노출되는 것을 방지하기 위한 인증방식이다."},{"n":63,"s":"s4","q":"SSL/TLS에 대한 설명으로 옳은 것은?","c":["SSL/TLS를 사용하고 있는 기업은 신뢰할 수 있기 때문에 신용카드 번호를 보내도 된다.","SSL/TLS에서는 공개키가 서버로부터 오기 때문에 클라이언트는 공개키를 가지고 있지 않아도 서버를 인증할 수 있다.","SSL/TLS 1.3을 사용하면 통신의 기밀성을 확보할 수 있다.","SSL/TLS에서는 통신 전의 데이터, 통신 중의 데이터, 통신 후의 데이터를 보호해준다."],"a":2,"e":"TLS 1.3은 AEAD 암호와 (EC)DHE 키교환만 허용해 전송 구간의 기밀성을 보장한다. SSL/TLS는 통신 중인 데이터만 보호하며 통신 전·후 저장 데이터는 보호하지 않고, 서버 인증에는 클라이언트가 신뢰하는 CA의 공개키(루트 인증서)가 필요하다.","ce":["SSL/TLS는 전송 구간만 암호화할 뿐 상대 기업의 신뢰성·데이터 처리의 안전성을 보장하지 않는다(피싱 사이트도 TLS 인증서를 가질 수 있음).","서버가 보낸 인증서를 검증하려면 클라이언트가 신뢰하는 CA의 공개키(루트 인증서)를 미리 가지고 있어야 하므로 틀린 설명이다.","TLS 1.3은 AEAD 암호와 (EC)DHE 키교환만 허용해 전송 데이터의 기밀성을 확보하므로 옳은 설명이다.","SSL/TLS는 통신 중인 데이터만 보호하며 통신 전·후 단말·서버에 저장된 데이터는 보호하지 않는다."],"rel":["2-7"]},{"n":64,"s":"s4","q":"해시값과 메시지 인증 코드(Message Authentication Code, MAC)에 대한 설명으로 틀린 것은?","c":["해시값만을 통해 두사람이 문서를 주고 받았을 때 MITM(Man-In-The-Middle, 중간자 공격)공격을 받을 수 있다. 즉, 해시값을 보고 수신된 문서 위변조에 대한 상호신뢰를 확신할 수 없다.","해시값에 암호개념을 도입한 것이 HMAC(Hash Message Authentication Code)이며, 이때 메시지 송수신자는 비밀키(Encryption Key) 또는 세션키(session Code)를 사전에 안전한 채널을 통해 공유해야 한다.","메시지 인증을 위해서는 사용되는 Message Digest(해시값)는 메시지 저장소에 파일이 위변조되지 않았다는 것을 보장하기 위해서 사용하기도 한다.","메시지 크기와 상관없이 MAC 생성과정, 즉 해시값 생성, 암호화 등이 속도는 균일하여 다른 암호화 알고리즘에 비해 속도가 빠르다."],"a":3,"e":"MAC 생성 시간은 입력 메시지 길이에 비례하므로 메시지 크기와 상관없이 균일하다는 설명은 틀리다. 키 없는 해시값만으로는 중간자가 메시지와 해시를 함께 바꿀 수 있어 HMAC처럼 사전 공유한 비밀키가 필요하다.","ce":["키 없는 해시값만 보내면 중간자가 문서를 바꾸고 해시도 다시 계산해 바꿀 수 있어 위변조 여부를 상호 신뢰할 수 없으므로 옳은 설명이다.","HMAC은 해시에 비밀키를 결합한 MAC으로, 송수신자가 비밀키를 사전에 안전한 채널로 공유해야 하므로 옳은 설명이다.","메시지 다이제스트는 저장된 파일의 해시를 보관·비교해 저장소 파일 위변조 여부를 확인하는 데도 쓰이므로 옳은 설명이다.","MAC 생성은 입력 메시지를 블록 단위로 처리하므로 소요 시간이 메시지 길이에 비례한다. 크기와 상관없이 균일하다는 진술이 틀렸다."],"rel":["4-5"]},{"n":65,"s":"s4","q":"OTP(One Time Password)와 HSM(Hardware Security Module)에 대한 설명으로 틀린 것은?","c":["OTP는 공개키를 사용한다.","OTP는 PKI를 개별 연동한다.","HSM의 안정성 인증 적용 표준은 FIPS 140-2 이다.","HSM은 공개키를 사용한다."],"a":0,"e":"OTP는 공유 비밀키(시드)와 시간·이벤트 값을 해시(HMAC)하여 일회용 비밀번호를 생성하며 공개키 암호를 사용하지 않는다. HSM은 공개키 인증서의 개인키를 안전하게 보관·연산하는 장치로, FIPS 140-2 암호모듈 인증을 받는다.","ce":["OTP는 공유 비밀키(시드)와 시간·이벤트 값을 해시(HMAC)해 생성하는 대칭키 기반 방식으로, 공개키를 사용하지 않는다.","OTP 통합인증센터 등과 연계해 PKI 기반 인증서와 개별 연동하여 사용하므로 옳은 설명으로 처리된다.","HSM은 미국 NIST의 암호모듈 검증 표준 FIPS 140-2(현 140-3)로 안전성을 인증받으므로 옳은 설명이다.","HSM은 공개키 인증서의 개인키를 안전하게 생성·보관하고 서명 연산을 수행하므로 공개키 암호를 사용한다는 설명은 옳다."],"rel":["4-8","4-4"]},{"n":66,"s":"s4","q":"다음 문장에서 설명하는 원칙은?","c":["최소 권한","필요 권한","불필요 권한","등급 권한"],"a":0,"e":"업무 수행에 필요한 최소한의 권한만 부여하는 것은 최소 권한(Least Privilege) 원칙이다. 이는 알 필요(Need-to-know), 직무 분리와 함께 접근통제의 기본 원칙이다.","ce":["업무 수행에 필요한 최소한의 권한만 부여하고 그 이상은 주지 않는 것은 최소 권한(Least Privilege) 원칙이다.","'필요 권한'은 표준 원칙 명칭이 아니며, 비슷한 개념인 알 필요(Need-to-know)는 필요한 정보만 접근하게 하는 원칙이다.","'불필요 권한'은 제거 대상이지 원칙 명칭이 아니다.","'등급 권한'은 표준 원칙이 아니며, 보안등급에 따른 통제는 MAC(강제적 접근통제) 개념이다."],"rel":["4-10"],"box":"모든 사용자는 현재 작업을 완료하는데 필요한 최소한의 권한만 가진 사용자 계정으로 로그온해야 하며, 그 이상의 권한을 부여하지 않는다."},{"n":67,"s":"s4","q":"다음 중 빅데이터 비식별화 처리기법 중 가명처리 방법에 해당하는 것은?(문제 오류로 가답안 발표시 3번으로 발표되었지만 확정답안 발표시 모두 정답처리 되었습니다. 여기서는 가답안인 3번을 누르면 정답 처리 됩니다.)","c":["총계처리","랜덤 라운딩","암호화","재배열"],"a":2,"e":"개인정보 비식별 조치 가이드라인(2016)에서 가명처리 기법은 휴리스틱 가명화, 암호화, 교환 방법이다. 총계처리·랜덤 라운딩·재배열은 총계처리 기법에 속하지만, 재배열을 가명처리의 교환(swapping) 방식으로 볼 여지 등이 있어 확정답안에서 전항 정답 처리되었다.","ce":["총계처리는 데이터의 합계·평균 등 통계값만 보여주는 기법으로, 가이드라인상 '총계처리' 범주에 속하며 가명처리가 아니다. 확정답안에서 전항 정답 처리되었다.","랜덤 라운딩은 수치를 임의 기준으로 올림·내림하는 총계처리 범주 기법으로 가명처리가 아니다. 확정답안에서 전항 정답 처리되었다.","비식별 조치 가이드라인(2016)의 가명처리 기법은 휴리스틱 가명화, 암호화, 교환 방법이므로 암호화가 가명처리에 해당한다(가답안). 확정답안은 전항 정답.","재배열은 가이드라인상 총계처리 범주 기법이나, 값을 교환(swapping)하는 가명처리 '교환 방법'과 유사해 논란이 되어 확정답안에서 전항 정답 처리되었다."],"rel":["5-7"],"flag":"확정답안 전항 정답 처리 문항(가답안 ③)"},{"n":68,"s":"s4","q":"다음 그림의 Needham-Schroeder 프로토콜에 대한 설명으로 틀린 것은?","c":["사용자 Alice는 사용자 Bob과 공유할 대칭키를 KDC에게 생성해주도록 요청한 후 사용자 Bob과 안전하게 공유하게 된다.","사용자 Alice와 KDC, 사용자 Bob과 KDC 간에 전달되는 메시지는 사전에 공유된 대칭키인 마스터키를 이용하여 암호화되어 전달되므로 안전하게 보호된다.","사용자 Alice와 Bob이 난수 N2와 N3를 암호화해서 교환하고 암호화된 N2-1과 N3-1을 받는 이유는 상호인증 기능을 수행하는데 목적이 있다.","이 방식은 공격자가 Ticketb와 Kab{N2}를 스니핑하여 복제한 후 복제된 메시지와 Alice로 위장한 자신의 신분 정보를 보내는 재전송공격에 취약한 단점이 있다."],"a":3,"e":"Needham-Schroeder의 알려진 약점은 과거 세션키 Kab가 노출된 경우 공격자가 이전 Ticketb를 재전송해 Alice로 위장하는 재전송 공격(Denning-Sacco)이다. 단순히 Ticketb와 Kab{N2}를 복제하는 것만으로는 Kab를 모르는 공격자가 N3-1 응답을 만들 수 없으므로 ④가 틀린 설명이다.","ce":["Alice가 KDC에 Bob과의 통신을 요청하면 KDC가 대칭 세션키 Kab를 생성해 전달하고, Alice는 Ticketb로 Bob과 이를 공유하므로 옳은 설명이다.","Ka{...}, Kb{...}처럼 KDC와 각 사용자 간 메시지는 사전 공유한 마스터키로 암호화되어 보호되므로 옳은 설명이다.","N2-1, N3-1 응답은 상대가 Kab를 실제로 알고 있음을 증명하는 챌린지-응답으로, 상호인증이 목적이므로 옳은 설명이다.","Kab를 모르는 공격자는 Ticketb와 Kab{N2}를 복제해도 N3-1 응답을 만들 수 없다. 실제 약점은 과거 Kab가 노출됐을 때 옛 티켓을 재전송하는 공격(Denning-Sacco)이다."],"rel":["4-12"],"box":"Alice → KDC : N1, I want to speak to Bob\nKDC(generates key Kab) → Alice : Ka{N1, Kab, Bob, Ticketb}, Ticketb = Kb{Kab, Alice}\nAlice → Bob : I'm Alice, Ticketb, Kab{N2}\nBob → Alice : Kab{N2-1, N3}\nAlice → Bob : Kab{N3-1}"},{"n":69,"s":"s4","q":"보안 인증기법에 대한 설명으로 틀린 것은?","c":["OTP 인증기법은 지식기반 인증방식으로 고정된 시간 간격 주기로 난수값을 생성하고, 생성된 난수값과 개인 PIN 번호 입력을 통해 인증시스템의 정보와 비교하여 사용자 인증을 수행한다.","ID/PW 인증기법은 지식기반 인증방식으로 타 인증방식에 비해 구축비용이 적고 사용하기 편리하다는 장점이 있다.","공인인증서 인증기법은 소유기반 인증방식으로 별도 매체의 고유정보를 제시하도록 함으로써 사용자 인증을 수행한다.","I-PIN(Internet Personal Identification Number)는 지식기반 인증방식으로 'ID/PW'와 주민번호를 대체하기 위하여 만들어졌다."],"a":0,"e":"OTP는 OTP 생성기(토큰·휴대폰)를 가지고 있어야 하는 소유기반 인증방식이므로 지식기반이라는 설명은 틀리다. ID/PW는 지식기반, 공인인증서는 저장매체에 보관하는 소유기반으로 분류된다.","ce":["OTP는 OTP 생성기(토큰·스마트폰)를 가지고 있어야 하는 소유기반 인증방식이므로 지식기반이라는 진술이 틀렸다.","ID/PW는 사용자가 아는 것(지식)에 기반하며 별도 장비가 필요 없어 구축비용이 적고 사용이 편리하므로 옳은 설명이다.","공인인증서는 USB·보안토큰 등 저장매체에 보관된 인증서와 개인키를 제시하는 소유기반 인증으로 분류되므로 옳은 설명이다.","I-PIN은 인터넷상에서 주민등록번호 대신 본인확인에 쓰는 수단으로 ID/PW(지식기반)를 이용하므로 옳은 설명으로 처리된다."],"rel":["4-8"]},{"n":70,"s":"s4","q":"다음 중 OCSP(Online Certificate Status Protocol : 온라인 인증서 상태 프로토콜) 서버의 응답값 중 인증서 상태표시 메시지가 아닌 것은?","c":["good","revoked","unknown","bad"],"a":3,"e":"OCSP 응답의 인증서 상태(certStatus)는 good(유효), revoked(폐지), unknown(알 수 없음) 세 가지이다(RFC 6960). bad라는 상태값은 없다.","ce":["good은 인증서가 폐지되지 않은 유효 상태임을 나타내는 OCSP 상태값이다.","revoked는 인증서가 폐지(또는 효력정지)된 상태를 나타내는 OCSP 상태값이다.","unknown은 응답자가 해당 인증서의 발급자를 알지 못해 상태를 판단할 수 없음을 나타내는 OCSP 상태값이다.","OCSP 인증서 상태(certStatus)는 good·revoked·unknown 세 가지뿐이며(RFC 6960) bad라는 값은 없다."],"rel":["4-7"]},{"n":71,"s":"s4","q":"다음 문장에서 설명하는 사전 키 분배 방식은?","c":["Blom 방식","커버로스 방식","공개키분배 방식","키 로밍 방식"],"a":0,"e":"Blom 방식은 KDC가 대칭 행렬 기반의 비밀 정보(함수값)를 각 노드에 사전 분배하고, 두 노드가 이를 이용해 서로 같은 세션키를 계산하는 사전 키 분배 방식이다. 커버로스는 통신 시마다 KDC가 세션키와 티켓을 발급하는 방식이다.","ce":["Blom 방식은 KDC가 대칭 행렬 기반 비밀 정보(함수값)를 각 노드에 사전 분배하고, 두 노드가 이를 이용해 같은 세션키를 계산하는 사전 키 분배 방식이다.","커버로스는 통신이 필요할 때마다 KDC(AS·TGS)가 세션키와 티켓을 발급하는 온라인 키 분배 방식으로, 함수값 사전 분배 방식이 아니다.","공개키 분배 방식은 공개 디렉터리·인증서로 공개키를 배포하는 방식으로 KDC의 함수값 전송과 다르다.","키 로밍은 사용자의 키·인증서를 서버에 두고 여러 단말에서 내려받아 쓰는 방식으로, 세션키 사전 분배 방식이 아니다."],"rel":["4-12"],"box":"키 분배센터(KDC : Key Distributin Center)에서 두 노드에게 임의의 함수값을 전송하면 두 노드는 전송받은 정보로부터 두 노드 사이의 통신에 필요한 세션키를 생성한다."},{"n":72,"s":"s4","q":"다음은 Diffie-Hellman 알고리즘에 대한 내용을 설명한 것이다. 괄호 안에 들어가야 할 내용은?","c":["㉠ : 공개키, ㉡ : 개인키","㉠ : 마스터키, ㉡ : 공개키","㉠ : 임시키, ㉡ : 고정키","㉠ : 개인키, ㉡ : 공개키"],"a":3,"e":"각 가입자는 임의의 개인키 x를 선정하고 공개키 y = g^x mod p를 계산해 공개한다. 상대 공개키에 자신의 개인키를 거듭제곱해 같은 공유 비밀키를 얻으며, 공개키에서 개인키를 구하는 것은 이산로그 문제로 어렵다.","ce":["순서가 뒤바뀌었다. 가입자는 비밀인 개인키를 먼저 선정하고 그로부터 계산한 공개키를 공개한다.","DH에서 가입자가 선정하는 것은 마스터키가 아니라 임의의 개인키 x이다.","DH 설명에 쓰는 용어는 임시키/고정키가 아니라 개인키/공개키이다(일회성 사용 여부는 DHE 등 별도 개념).","가입자는 개인키 x를 선정하고 공개키 y = g^x mod p를 계산해 공개하므로 올바르다. 공개키에서 x를 구하는 것은 이산로그 문제로 어렵다."],"rel":["4-12","4-4"],"box":"Diffie-Hellman 알고리즘은 이산로그 문제에 기반을 두고 있다. 키 분배 센터는 큰 소수 p를 선정하고, 원시근 g를 찾아 공개한다. 가입자는 ( ㉠ )를 선정하고 ( ㉡ )를 계산하여 공개한다."},{"n":73,"s":"s4","q":"다음 문장에서 설명하는 접근통제 구성요소는?","c":["정책","매커니즘","보안모델","OSI 보안구조"],"a":0,"e":"접근통제 정책은 누가 어떤 자원에 어떤 모드로 접근할 수 있는지 규칙과 조건을 정의한다. 메커니즘은 정책을 구현하는 수단(ACL, 능력 리스트 등), 보안모델은 정책을 수학적으로 표현한 것(BLP, Biba 등)이다.","ce":["접근통제 정책은 누가 어떤 자원에 어떤 모드로 접근할 수 있는지 규칙과 조건을 정의하는 것으로 설명과 일치한다.","메커니즘은 정책을 실제로 구현하는 수단(ACL, 능력 리스트, 보안 레이블 등)으로, 조건을 정의하는 것이 아니라 집행한다.","보안모델은 정책을 수학적·형식적으로 표현한 것(BLP, Biba 등)이다.","OSI 보안구조(X.800)는 보안 서비스·메커니즘·공격을 분류한 참조 구조로, 접근통제 구성요소가 아니다."],"rel":["4-10"],"box":"시스템 자원에 접근하는 사용자 접근모드 및 모든 접근통제 조건 등을 정의"},{"n":74,"s":"s4","q":"온라인 인증서 상태 프로토콜(OCSP : Online Certificate Status Protocol)에 대한 설명으로 틀린 것은?","c":["OCSP는 X.509를 이용한 전자 서명 인증서의 폐지 상태를 파악하는데 사용되는 인터넷 프로토콜이다.","RFC 6960로 묘사되며, 인터넷 표준의 경로가 된다.","온라인 인증서 상태 프로토콜을 통해 전달받는 메시지들을 AES로 암호화되며, 보통 HTTP로 전달받는다.","이 프로토콜의 도입 이유 중 하나는 고가의 증권 정보나 고액의 현금 거래 등 데이터 트랜잭션의 중요성이 매우 높은 경우 실시간으로 인증서 유효성 검증이 필요하기 때문이다."],"a":2,"e":"OCSP 메시지는 ASN.1로 인코딩되어 주로 HTTP로 전달되며, 응답은 OCSP 응답자가 전자서명해 무결성과 출처를 보장할 뿐 AES로 암호화되지 않는다. OCSP는 RFC 6960에 정의된 실시간 인증서 상태 확인 프로토콜이다.","ce":["OCSP는 X.509 인증서의 폐지 상태를 실시간으로 조회하는 인터넷 프로토콜이므로 옳은 설명이다.","OCSP는 RFC 6960에 정의되어 인터넷 표준 경로(Standards Track)에 있으므로 옳은 설명이다.","OCSP 메시지는 ASN.1로 인코딩되어 주로 HTTP로 전달되며, 응답은 응답자가 전자서명할 뿐 AES로 암호화되지 않으므로 틀린 진술이다.","고액 거래처럼 중요도가 높은 트랜잭션은 주기적으로 갱신되는 CRL이 아닌 실시간 유효성 검증이 필요해 OCSP를 도입하므로 옳은 설명이다."],"rel":["4-7"]},{"n":75,"s":"s4","q":"다음 중 신규 OTP 기술에 대한 설명으로 틀린 것은?","c":["거래연동 OTP란 수신자계좌번호, 송금액 등의 전자금융거래 정보와 연동되어 OTP를 발생시키는 OTP로 정의된다.","USIM OTP는 사용자의 휴대폰의 USIM내에 OTP모듈 및 주요정보를 저장하여 OTP를 안전하게 생성하고 인증을 수행하는 OTP이다.","스마트 OTP란 IC칩 기반의 스마트카드와 NFC 기능을 지원하는 스마트폰에 OTP를 발생시키는 것이다.","MicroSD OTP란 사용자 휴대폰의 MicroSD내에 OTP모듈 및 주요정보를 저장하여 복제가 되지 않는 안전한 IC 칩 기반의 OTP이다."],"a":3,"e":"금융권 신규 OTP 분류에서 거래연동·USIM·스마트 OTP에 대한 ①~③의 설명은 표준 정의와 일치하며, 출제기관은 MicroSD OTP에 대한 ④의 서술을 틀린 것으로 처리하였다. MicroSD OTP는 휴대폰에 장착하는 MicroSD 카드 형태의 보안 매체에 OTP 모듈을 탑재하는 방식이다.","ce":["거래연동 OTP는 수신계좌번호·송금액 등 거래정보를 입력값으로 OTP를 생성해 거래 변조를 막는 방식으로 정의와 일치한다.","USIM OTP는 휴대폰 USIM 칩 안에 OTP 모듈·시드를 저장해 생성·인증하는 방식으로 정의와 일치한다.","스마트 OTP는 IC칩 스마트카드를 NFC 스마트폰에 접촉해 OTP를 생성하는 방식으로 정의와 일치한다.","출제기관이 틀린 설명으로 처리한 보기이다. MicroSD OTP는 휴대폰에 끼우는 MicroSD 카드 형태의 보안매체에 OTP를 탑재하는 방식으로, 오답 근거는 교재 서술에 의존한다(확인 권장)."],"rel":["4-8"],"flag":"④ 오답 근거 교재 의존 — 확인 권장"},{"n":76,"s":"s4","q":"메시지 인증 코드(MAC)의 재전송 공격을 예방하기 위한 방법으로 옳지 않은 것은?","c":["순서 번호","타임스탬프","비표","부인방지"],"a":3,"e":"MAC 재전송 공격은 메시지에 순서 번호, 타임스탬프, 비표(nonce, 일회용 난수)를 포함해 이전 메시지 재사용을 탐지하여 막는다. 부인방지는 MAC이 제공하지 못하는 보안 서비스(전자서명이 제공)로 재전송 방지책이 아니다.","ce":["메시지에 순서 번호를 붙이면 이미 받은 번호의 메시지를 재수신했을 때 재전송으로 판단해 폐기할 수 있다.","타임스탬프를 넣으면 허용 시간 범위를 벗어난 오래된 메시지를 재전송으로 판단해 거부할 수 있다.","비표(nonce)는 한 번만 쓰는 난수로, 수신자가 매번 새 값을 요구해 이전 메시지 재사용을 막는다.","부인방지는 송신 사실을 부인하지 못하게 하는 보안 서비스로 MAC이 아닌 전자서명이 제공하며, 재전송 공격 예방 수단이 아니다."],"rel":["4-5"]},{"n":77,"s":"s4","q":"암호화 장치에서 암호화 처리시에 소비 전력을 측정하는 등 해당 장치 내부의 비밀 정보를 추정하는 공격은?","c":["키로거","사이드채널 공격","스미싱","중간자 공격"],"a":1,"e":"사이드채널 공격은 암호 장치의 전력 소비, 전자기파, 처리 시간 등 부수 정보를 분석해 내부 비밀키를 추정한다(전력분석 SPA/DPA 등). 중간자 공격은 통신 경로에 끼어들어 메시지를 가로채는 공격이다.","ce":["키로거는 키보드 입력을 가로채 기록하는 악성코드로, 암호 장치의 물리적 부수 정보를 분석하지 않는다.","사이드채널 공격은 전력 소비(SPA/DPA)·전자기파·처리 시간 등 부수 정보를 측정해 장치 내부의 비밀키를 추정하는 공격이다.","스미싱은 문자메시지(SMS)에 악성 링크를 넣어 악성앱 설치·정보 탈취를 유도하는 사회공학 공격이다.","중간자 공격은 통신 경로에 끼어들어 메시지를 가로채거나 변조하는 공격으로, 장치 전력 측정과 무관하다."],"rel":["4-1"]},{"n":78,"s":"s4","q":"RSA 암호시스템에서 다음의 값을 이용한 암호문 C값은?","c":["1","3","5","7"],"a":0,"e":"C = P^e mod n = 5^2 mod 4 = 25 mod 4 = 1이다. 암호화에는 공개값 e를 사용하며, 비밀값 d는 복호화에 사용된다.","ce":["C = P^e mod n = 5^2 mod 4 = 25 mod 4 = 1이므로 정답이다. 암호화에는 공개값 e를 쓴다.","25를 4로 나누면 몫 6, 나머지 1이므로 3은 나올 수 없다. 5 mod 4=1이라 5를 몇 제곱해도 결과는 1이다.","5는 평문 P 그대로이며, 모듈러 n=4 연산 결과는 항상 0~3 범위이므로 나올 수 없다.","7은 n=4보다 크므로 mod 4 연산 결과(0~3)가 될 수 없다."],"rel":["4-4"],"box":"- 조건 : 공개값 e=2, 비밀값 d=3, 평문 P=5, 모듈러 n=4\n- 암호문 C = 평문 Pe mod n"},{"n":79,"s":"s4","q":"다음 중 스마트카드에 대한 설명으로 틀린 것은?","c":["접촉식 스마트카드는 리더기와 스마트카드의 접촉부(CHIP) 사이의 물리적 접촉에 의해 작동하는 스마트카드이다.","SIM카드는 가입자 식별 모듈(Subscriber Identification Module)을 구현한 IC 카드이다.","인증 데이터 저장을 위해 서명된 정적 응용 프로그램 데이터와 인증기관(CA)의 개인키로 발행자의 공개키를 암호화된 데이터를 스마트카드에 저장한다.","인증기관(CA)의 개인키를 스마트카드 단말에 배포한다."],"a":3,"e":"CA의 개인키는 CA만 비밀로 보관해야 하며, 단말에는 서명 검증용 CA 공개키가 배포된다. EMV 정적 데이터 인증(SDA)에서는 CA 개인키로 서명된 발행자 공개키 인증서와 서명된 정적 데이터를 카드에 저장한다.","ce":["접촉식 스마트카드는 카드의 금속 접촉부(칩)와 리더기가 물리적으로 닿아 전원·데이터를 주고받으므로 옳은 설명이다.","SIM 카드는 이동통신 가입자 식별 모듈(Subscriber Identification Module)을 구현한 IC 카드이므로 옳은 설명이다.","EMV 정적 데이터 인증(SDA)에서는 CA 개인키로 서명된 발행자 공개키 인증서와 서명된 정적 응용 데이터를 카드에 저장하므로 옳은 설명이다.","CA의 개인키는 CA만 비밀로 보관해야 하며 단말에는 서명 검증용 CA 공개키가 배포된다. CA 개인키를 단말에 배포한다는 진술이 틀렸다."],"rel":["4-7"]},{"n":80,"s":"s4","q":"다음 중 접근통제 정책이 아닌 것은?","c":["MAC","DAC","RBAC","ACL"],"a":3,"e":"접근통제 정책에는 강제적(MAC), 임의적(DAC), 역할기반(RBAC) 접근통제가 있다. ACL(Access Control List)은 객체별 접근 권한 목록으로, 정책을 구현하는 접근통제 메커니즘이다.","ce":["MAC(강제적 접근통제)은 주체·객체의 보안등급에 따라 시스템이 접근을 강제하는 접근통제 정책이다.","DAC(임의적 접근통제)은 객체 소유자가 재량으로 접근 권한을 부여하는 접근통제 정책이다.","RBAC(역할기반 접근통제)은 사용자에게 부여된 역할에 따라 권한을 주는 접근통제 정책이다.","ACL(Access Control List)은 객체별로 주체와 권한을 나열한 목록으로, 정책을 구현하는 접근통제 메커니즘이지 정책이 아니다."],"rel":["4-10"]},{"n":81,"s":"s5","q":"보통의 일반적인 데이터로부터 비밀정보를 획득할 수 있는 가능성을 의미하며, 사용자가 통계적인 데이터 값으로부터 개별적인 데이터 항목에 대한 정보를 추적하지 못하도록 하는 것은?(문제 오류로 가답안 발표시 2번으로 발표되었지만 확정답안 발표시 2, 4번이 정답처리 되었습니다. 여기서는 가답안인 2번을 누르면 정답 처리 됩니다.)","c":["집합(aggregation)","추론(inference)","분할(partition)","셀 은폐(cell suppression)"],"a":1,"e":"일반 데이터나 통계값으로부터 비밀정보를 유추할 수 있는 가능성은 추론(inference)이며, 이를 막기 위한 대책이 셀 은폐(cell suppression)·분할·잡음 추가 등이다. 발문이 개념과 대책을 모두 묻는 형태여서 확정답안에서 ②와 ④가 모두 정답 처리되었다.","ce":["집합(aggregation)은 낮은 등급 정보를 모았을 때 높은 등급 정보가 되는 문제로, 통계값에서 개별 항목을 유추하는 추론과 구분된다.","가답안이다. 일반 데이터·통계값으로부터 비밀정보를 유추할 수 있는 가능성은 추론(inference)이다. 다만 확정답안에서 ④도 정답으로 인정되었다.","분할(partition)은 데이터베이스를 나눠 추론을 어렵게 하는 대책 중 하나이지만, 문제의 '가능성' 개념을 가리키는 용어는 아니다.","셀 은폐(cell suppression)는 통계표의 민감 셀 값을 숨겨 개별 항목 추적을 막는 추론 방지 대책이다. 발문 후반부 해석에 따라 확정답안에서 복수정답으로 인정되었다."],"rel":["3-8"],"flag":"확정답안 ②④ 복수정답(가답안 ②)"},{"n":82,"s":"s5","q":"이 표준은 조직이나 기업이 정보보안 경영시스템을 수립하여 이행하고 감시 및 검토, 유지, 개선하기 위해 필요한 요구사항을 명시하며, 국제표준화기구 및 국제전기기술위원회에서 제정한 정보보호 관리체계에 대한 국제표준이다. Plan-Do-Check-Action(PDCA, 구축-실행-유지-개선) 모델을 채택하여 정보자산의 기밀성, 무결성, 가용성을 실현하기 위하여 관련 프로세스를 체계적으로 수립, 문서화하고 이를 지속적으로 운영, 관리하는 표준은?","c":["ISMS-P","ISO27001","ISMS","ISO27701"],"a":1,"e":"ISO/IEC 27001은 ISO와 IEC가 제정한 정보보호 관리체계(ISMS) 요구사항 국제표준이다. ISMS·ISMS-P는 국내 인증제도이며, ISO/IEC 27701은 27001을 확장한 개인정보 관리체계(PIMS) 표준이다.","ce":["ISMS-P는 국내 정보보호 및 개인정보보호 관리체계 인증제도로, ISO·IEC가 제정한 국제표준이 아니다.","ISO/IEC 27001은 ISO와 IEC가 제정한 정보보호 관리체계(ISMS) 요구사항 국제표준으로, PDCA 모델 기반 설명과 일치한다.","ISMS는 국내 정보통신망법에 근거한 정보보호 관리체계 인증제도로 국제표준이 아니다.","ISO/IEC 27701은 27001을 확장해 개인정보 관리체계(PIMS) 요구사항을 정한 표준으로, 정보보안 경영시스템 자체의 요구사항 표준이 아니다."],"rel":["5-12"]},{"n":83,"s":"s5","q":"A 쇼핑몰에서 물품 배송을 위해 B 배송업체와 개인정보처리 업무 위탁 계약을 맺었고 이름, 주소, 핸드폰번호를 전달하였다. A 쇼핑몰이 B 배송업체를 대상으로 관리 감독할 수 없는 것은?","c":["B 배송업체의 직원을 대상으로 개인정보보호 교육을 한다.","B 배송업체에서 개인정보취급자를 채용할 것을 요청해야 한다.","B 배송업체가 개인정보를 안전하게 처리하고 있는지 점검해야 한다.","B 배송업체가 재위탁을 하지 못하도록 제재한다."],"a":1,"e":"개인정보 보호법상 위탁자는 수탁자를 교육하고 처리 현황을 점검하는 등 감독해야 하며, 위탁 문서에 재위탁 제한을 포함한다. 수탁자의 인력 채용은 수탁자의 인사 사항으로 위탁자의 관리·감독 범위에 해당하지 않는다.","ce":["개인정보 보호법상 위탁자는 수탁자가 개인정보를 안전하게 처리하도록 교육해야 하므로 관리·감독 범위에 포함된다.","수탁자의 인력 채용은 수탁자 자체의 인사 사항이며, 위탁자가 법적으로 요구할 수 있는 관리·감독 사항에 해당하지 않는다.","위탁자는 수탁자의 처리 현황을 점검하는 등 안전하게 처리하는지 감독해야 하므로 관리·감독 범위이다.","위탁 문서에 재위탁 제한에 관한 사항을 포함하도록 하므로, 재위탁 제한은 위탁자의 관리·감독 범위이다."],"rel":["5-8"]},{"n":84,"s":"s5","q":"영상정보처리기기를 설치·운영할 수 있는 경우가 아닌 것은?","c":["범죄의 예방 및 수사를 위하여 필요한 경우","시설안전 및 화재 예방을 위하여 필요한 경우","쇼핑몰 고객의 이동경로 수집·분석 및 제공을 위하여 필요한 경우","교통단속을 위하여 필요한 경우"],"a":2,"e":"개인정보 보호법 제25조는 공개된 장소에 고정형 영상정보처리기기를 설치할 수 있는 경우로 법령 허용, 범죄 예방·수사, 시설안전·화재 예방, 교통단속, 교통정보 수집·분석·제공 등을 한정한다. 쇼핑몰 고객 이동경로 수집·분석은 이에 해당하지 않는다(개정 여부 확인).","ce":["범죄의 예방 및 수사를 위해 필요한 경우는 개인정보 보호법 제25조가 허용하는 설치·운영 사유이다.","시설안전 및 화재 예방을 위해 필요한 경우는 법이 허용하는 설치·운영 사유이다(정보주체 열람·확인 가능 조건 등 조문 확인).","쇼핑몰 고객의 이동경로 수집·분석·제공은 제25조의 허용 사유에 없으므로 공개된 장소 설치·운영 근거가 될 수 없다(개정 여부 확인).","교통단속을 위해 필요한 경우는 법이 허용하는 설치·운영 사유이다."],"rel":["5-14"]},{"n":85,"s":"s5","q":"다음 문장에서 설명하는 위험분석을 방법론은?","c":["과거자료 분석법","확률 분포법","델파이법","시나리오법"],"a":3,"e":"시나리오법은 어떤 사건도 기대대로 발생하지 않는다는 가정 아래 일정 조건에서 위협의 발생 가능한 결과를 추정하는 정성적 위험분석 기법이다. 델파이법은 전문가 집단의 의견을 반복 수렴하는 방법이다.","ce":["과거자료 분석법은 과거 사고 데이터를 기반으로 위험 발생 확률을 산출하는 정량적 분석 방법이다.","확률 분포법은 미지의 사건을 확률분포로 추정해 위험을 계산하는 정량적 분석 방법이다.","델파이법은 전문가 집단의 의견을 설문으로 반복 수렴해 위험을 평가하는 정성적 방법으로, 사건 결과 추정 시나리오와는 다르다.","시나리오법은 사건이 기대대로 발생하지 않는다는 가정 아래 특정 조건에서 위협의 발생 가능한 결과를 추정하는 정성적 방법으로 설명과 일치한다."],"rel":["5-2"],"box":"- 어떤 사건도 기대대로 발생하지 않았다는 사실에 근거하여 일정 조건하에서 위협에 대한 발생 가능한 결과들을 추정하는 방법\n- 적은 정보를 가지고 전반적인 가능성을 추론할 수 있고, 위험분석팀과 관리층 간의 원활한 의사소통을 가능케 한다. 그러나 발생 가능한 사건의 이론적인 추측에 불과하고 정확도, 완성도, 이용기술의 수준 등이 낮을 수 있음"},{"n":86,"s":"s5","q":"다음 문장에서 설명하는 포렌식 수행 절차 단계는?","c":["수사 준비","증거물 획득","분석 및 조사","보고서 작성"],"a":1,"e":"시스템 정보 기록, 원본 매체 복제와 사진 촬영, 증거 라벨 부착은 증거물 획득(수집) 단계의 활동이다. 분석 및 조사 단계는 복제본을 대상으로 데이터를 복구·검색·분석하는 단계이다.","ce":["수사 준비는 장비·도구·인력·법적 절차를 사전에 갖추는 단계로, 현장에서 시스템 정보 기록·라벨 부착을 하는 단계가 아니다.","시스템 정보 기록, 원본 매체 복제 및 사진 촬영, 증거 라벨 부착은 증거물 획득(수집) 단계의 활동이다.","분석 및 조사는 획득한 복제본을 대상으로 삭제 파일 복구·키워드 검색·타임라인 분석을 하는 단계이다.","보고서 작성은 분석 결과와 절차를 문서화해 제출하는 마지막 단계이다."],"rel":["3-11"],"box":"- 컴퓨터의 일반적인 하드디스크를 검사할 때는 컴퓨터 시스템 정보를 기록한다.\n- 복제 작업을 한 원본 매체나 시스템의 디지털 사진을 찍는다.\n- 모든 매체에 적절한 증거 라벨을 붙인다."},{"n":87,"s":"s5","q":"재택·원격근무시 지켜야 할 정보보호 실천 수칙 중 보안관리자가 해야할 일이 아닌 것은?","c":["원격 접속 모니터링 강화","일정시간 부재시 네트워크 차단","재택근무자 대상 보안지침 마련 및 보안인식 제고","원격에서 사내 시스템 접근시 VPN을 사용하지 않고 VNC 등 원격 연결 프로그램 사용"],"a":3,"e":"재택·원격근무 보안수칙은 사내 시스템 원격 접속 시 VPN 등 암호화된 안전한 접속 수단을 사용하고, 보안 취약한 원격 연결 프로그램 사용을 자제하도록 한다. 원격 접속 모니터링, 부재 시 네트워크 차단, 보안지침 마련은 관리자 수칙이다.","ce":["원격 접속 로그와 이상 접속을 모니터링하는 것은 재택근무 환경에서 보안관리자가 해야 할 일이다.","일정 시간 부재 시 세션·네트워크를 차단해 방치된 원격 세션의 악용을 막는 것은 관리자 수칙이다.","재택근무자용 보안지침을 마련하고 보안인식 교육을 하는 것은 관리자 수칙이다.","원격 접속 시에는 VPN 등 암호화된 안전한 수단을 사용해야 하며, VPN 없이 VNC 등 원격 연결 프로그램을 쓰는 것은 권고와 반대되는 행위이다."],"rel":["2-7"]},{"n":88,"s":"s5","q":"다음 문장에서 설명하고 있는 포렌식으로 획득한 증거의 법적인 효력 보장을 위한 5대 원칙은?","c":["정당성의 원칙","재현의 원칙","신속성의 원칙","연계 보관성의 원칙"],"a":1,"e":"재현의 원칙은 같은 조건과 절차로 수행하면 언제나 같은 결과가 나와야 한다는 원칙이다. 정당성은 적법 절차에 따른 수집, 연계 보관성(CoC)은 증거 이동·보관 이력의 관리를 뜻한다.","ce":["정당성의 원칙은 증거가 적법한 절차에 따라 수집되어야 한다는 원칙으로, 동일 결과 재생성과는 다르다.","재현의 원칙은 같은 환경·절차로 수행하면 언제나 같은 결과가 나와야 법적 유효성을 인정받는다는 원칙으로 설명과 일치한다.","신속성의 원칙은 휘발성 증거 등이 사라지기 전에 신속하게 수집해야 한다는 원칙이다.","연계 보관성(Chain of Custody)의 원칙은 증거의 획득·이송·보관·분석 각 단계의 담당자와 이력을 기록해 관리해야 한다는 원칙이다."],"rel":["3-11"],"box":"증거는 절차를 통해 정제되는 과정을 거칠 수 있다. 예를 들면 시스템에서 삭제된 파일이나 손상된 파일을 복구하는 과정 등을 말한다. 이 증거를 법정에 제출하기 위해서는 동일한 환경에서 반드시 동일한 결과가 생성되어야 하며, 만약 동일한 환경에서 서로 다른 결과가 나온다면 그 증거는 법적으로 유효성을 인정받을 수 없으며, 동일한 결과와 생성에 따른 법적 유효성 보장과 관련된 원칙이다."},{"n":89,"s":"s5","q":"다음 중 클라우드컴퓨팅 발전 및 이용자 보호에 관한 법률(클라우드컴퓨팅법)에 따른 클라우드컴퓨팅 기술연구, 도입 및 이용 활성화, 전문인력 양성 등을 전담하는 전담기관에 해당하지 않는 것은?","c":["한국지능정보사회진흥원","한국지역정보개발원","한국인터넷진흥원","한국전자통신연구원"],"a":3,"e":"클라우드컴퓨팅법 시행령상 전담기관은 정보통신산업진흥원, 한국지능정보사회진흥원, 한국인터넷진흥원, 한국지역정보개발원 등으로 지정되어 있다. 한국전자통신연구원(ETRI)은 전담기관으로 지정되어 있지 않다(개정 여부 확인).","ce":["한국지능정보사회진흥원(NIA)은 클라우드컴퓨팅법 시행령상 전담기관으로 지정되어 있다(개정 여부 확인).","한국지역정보개발원은 지자체 클라우드 도입 지원 등을 위해 전담기관으로 지정되어 있다(개정 여부 확인).","한국인터넷진흥원(KISA)은 클라우드 보안 인증 등 업무를 수행하는 전담기관으로 지정되어 있다(개정 여부 확인).","한국전자통신연구원(ETRI)은 정부출연 연구기관으로, 클라우드컴퓨팅법상 전담기관으로 지정되어 있지 않다(개정 여부 확인)."],"rel":["5-10"]},{"n":90,"s":"s5","q":"과학기술정보통신부장관이 정보통신망의 안정성·신뢰성 확보를 위하여 관리적·기술적·물리적 보호조치를 포함한 종합적 관리체계를 수립·운영하고 있는 자에 대하여 법에 정한 기준에 적합한지에 관하여 인증을 할 수 있도록 하는 정보보호 관리체계 인증(ISMS)을 명시한 법률은?","c":["정보통신망 이용촉진 및 정보보호 등에 관한 법률","전자서명법","개인정보보호법","정보통신기반 보호법"],"a":0,"e":"정보보호 관리체계(ISMS) 인증은 정보통신망법 제47조에 근거한다. 개인정보보호법은 개인정보 보호 인증(ISMS-P의 개인정보 영역, 제32조의2)의 근거이다.","ce":["정보보호 관리체계(ISMS) 인증은 정보통신망법 제47조에 근거하므로 정답이다.","전자서명법은 전자서명의 효력과 인증서비스(인정 제도 등)를 규정하는 법으로, ISMS 인증 근거가 아니다.","개인정보보호법은 개인정보 보호 인증(제32조의2)의 근거로, 정보통신망 안정성 관리체계(ISMS) 인증 근거는 아니다.","정보통신기반 보호법은 주요정보통신기반시설의 지정·취약점 분석·보호대책을 규정하는 법이다."],"rel":["5-11"]},{"n":91,"s":"s5","q":"다음 중 정보자산 중요도 평가에 관한 설명으로 틀린 것은?","c":["기밀성, 무결성, 가용성에 기반하여 자산 중요도를 평가","인터넷을 통해 서비스를 제공하는 웹서버는 가용성을 가장 높게 평가","백업데이터는 내화금고에 보관하고 있으므로 무결성을 가장 낮게 평가","고객 개인정보, 임직원 개인정보를 기밀성을 가장 높게 평가"],"a":2,"e":"자산 중요도는 자산 자체의 가치(기밀성·무결성·가용성 영향)로 평가해야 하며, 내화금고 보관 같은 보호대책 적용 여부를 이유로 낮게 평가하면 안 된다. 백업데이터는 복구에 쓰이므로 무결성이 중요하다.","ce":["자산 중요도는 자산이 훼손될 때 기밀성·무결성·가용성에 미치는 영향으로 평가하므로 옳은 설명이다.","인터넷 서비스용 웹서버는 서비스 중단 시 영향이 커 가용성을 가장 높게 평가하는 것이 적절하다.","중요도는 보호대책 적용 여부가 아니라 자산 자체의 가치로 평가해야 한다. 내화금고 보관을 이유로 무결성을 낮게 평가한 것이 틀렸으며, 백업데이터는 복구용이라 무결성이 중요하다.","고객·임직원 개인정보는 유출 시 피해가 크므로 기밀성을 가장 높게 평가하는 것이 적절하다."],"rel":["5-12"]},{"n":92,"s":"s5","q":"다음은 CERT가 정의하는 보안사고를 서술한 것이다. 일반 보안사고가 아닌 중대 보안사고에 해당하는 것을 모두 고른 것은?","c":["㉠, ㉢","㉠, ㉣","㉡, ㉢","㉢, ㉣"],"a":3,"e":"보안 장치의 변경·파괴와 대외 이미지에 중대한 손상을 끼친 정보자산 오용은 중대 보안사고로 분류된다. 악성코드 침해와 비인가 침해 시도는 일반 보안사고에 해당한다.","ce":["㉠ 악성코드 침해는 일반 보안사고로 분류되므로 ㉠이 포함된 조합은 틀리다.","㉣은 중대 보안사고이지만 ㉠ 악성코드 침해는 일반 보안사고이다.","㉢은 중대 보안사고이지만 ㉡ 비인가 침해 시도는 일반 보안사고이다.","㉢ 보안 장치의 변경·파괴와 ㉣ 대외 이미지에 중대한 손상을 끼친 정보자산 오용이 중대 보안사고에 해당한다."],"rel":["5-3"],"box":"㉠ 악성 소프트웨어(웜, 바이러스, 백도어, 트로이목마 등)에 의한 침해\n㉡ 네트워크 및 시스템에 대한 비인가된 침해 시도\n㉢ 보안 장치의 변경이나 파괴(출입보안, 침입탐지시스템, 잠금장치, 보안 카메라 등)\n㉣ 정보자산의 오용으로 대외 이미지에 중대한 손상을 끼친 경우"},{"n":93,"s":"s5","q":"다음 중 금융회사 또는 전자금융업자가 설치·운영하는 정보보호위원회의 심의·의결 사항으로 틀린 것은?","c":["정보기술부문 계획서에 관한 사항","취약점 분석·평가 결과 및 보완조치의 이행계획에 관한 사항","전산보안사고 및 전산보안관련 규정 위반자의 처리에 관한 사항","기타 정보보호관리자가 정보보안업무 수행에필요하다고 정한 사항"],"a":3,"e":"전자금융감독규정상 정보보호위원회는 정보기술부문 계획, 취약점 분석·평가 결과 및 보완 이행계획, 보안사고·규정 위반자 처리 등을 심의·의결하며, 기타 사항은 정보보호최고책임자(CISO)가 필요하다고 정한 사항이다. 정보보호관리자가 정한다는 표현이 틀리다(개정 여부 확인).","ce":["정보기술부문 계획서에 관한 사항은 전자금융감독규정상 정보보호위원회 심의·의결 사항이다.","취약점 분석·평가 결과 및 보완조치 이행계획은 정보보호위원회 심의·의결 사항이다.","전산보안사고 및 보안 규정 위반자 처리에 관한 사항은 정보보호위원회 심의·의결 사항이다.","기타 사항은 '정보보호최고책임자(CISO)'가 필요하다고 정한 사항이다. '정보보호관리자'라는 주체가 틀렸다(개정 여부 확인)."],"rel":["5-10"]},{"n":94,"s":"s5","q":"다음 중 정보보호관리체계 인증 범위 내 필수적으로 포함해야 할 자산이 아닌 것은?","c":["DMZ 구간 내 정보시스템","개발서버, 테스트서버","ERP, DW, GroupWare","관리자 PC, 개발자 PC"],"a":2,"e":"ISMS 인증 범위에는 서비스와 관련된 DMZ 구간 정보시스템, 개발·테스트 서버, 관리자·개발자 PC 등 서비스 운영에 관여하는 자산이 필수로 포함된다. ERP·DW·그룹웨어 같은 내부 업무 시스템은 인증 대상 서비스와 직접 관련이 없으면 필수 포함 대상이 아니다.","ce":["서비스 제공과 연결된 DMZ 구간 웹·메일 서버 등은 ISMS 인증 범위에 필수 포함되는 자산이다.","서비스 개발·테스트에 쓰이는 개발서버·테스트서버는 운영 환경에 영향을 주므로 필수 포함 대상이다.","ERP·DW·그룹웨어 같은 내부 업무 시스템은 인증 대상 서비스와 직접 관련이 없으면 필수 포함 대상이 아니다.","서비스 시스템에 접속하는 관리자 PC·개발자 PC는 침해 경로가 되므로 필수 포함 대상이다."],"rel":["5-11"]},{"n":95,"s":"s5","q":"정보주체의 동의없이 가명정보를 처리할 수 없는 경우는?","c":["상업적 1:1 마케팅","통계작성","과학적 연구","공익적 기록보존"],"a":0,"e":"개인정보 보호법 제28조의2에 따라 가명정보는 통계작성, 과학적 연구, 공익적 기록보존 목적에 한해 정보주체 동의 없이 처리할 수 있다. 특정 개인을 대상으로 하는 1:1 마케팅은 이 목적에 해당하지 않아 동의가 필요하다.","ce":["특정 개인을 대상으로 하는 상업적 1:1 마케팅은 개인정보 보호법 제28조의2의 가명정보 처리 목적(통계·연구·공익 기록보존)에 해당하지 않아 동의가 필요하다.","통계작성(상업적 목적 포함)은 동의 없이 가명정보를 처리할 수 있는 목적이다.","과학적 연구(산업적 연구 포함)는 동의 없이 가명정보를 처리할 수 있는 목적이다.","공익적 기록보존은 동의 없이 가명정보를 처리할 수 있는 목적이다."],"rel":["5-7"]},{"n":96,"s":"s5","q":"다음 중 사이버 윤리의 개념과 내용으로 옳지 않은 것은?","c":["사이버 공간에서 인간의 도덕적 관계에 관심을 갖는다.","사이버 세계 속에 거주하는 모든 인간의 책임과 의무를 규정해 주는 것을 의미한다.","사이버윤리는 기존의 컴퓨터 윤리의 개념을 포함하지는 않는다.","사이버 상의 일탈상황에 따른 구체적인 행동 요령을 알아보는 실증적인 내용으로 연구되고 있다."],"a":2,"e":"사이버 윤리는 컴퓨터 윤리·정보 윤리를 포괄·확장한 개념으로, 기존 컴퓨터 윤리를 포함한다. 사이버 공간의 도덕적 관계와 구성원의 책임·의무를 다룬다.","ce":["사이버 윤리는 사이버 공간에서 인간 사이의 도덕적 관계와 행위 규범을 다루므로 옳은 설명이다.","사이버 윤리는 사이버 공간 구성원의 책임과 의무를 규정하는 규범이므로 옳은 설명이다.","사이버 윤리는 기존 컴퓨터 윤리·정보 윤리를 포괄·확장한 개념이므로 컴퓨터 윤리를 포함하지 않는다는 진술이 틀렸다.","사이버 윤리는 사이버 일탈 상황의 구체적 행동 요령 등 실증적 내용으로도 연구되므로 옳은 설명이다."]},{"n":97,"s":"s5","q":"다음 중 「클라우드컴퓨팅 발전 및 이용자 보호에 관한 법률」 제 25조(침해사고 등의 통지 등)에 따라 지체없이 이용자에게 알려야 할 상황이 아닌 것은?","c":["해킹, 컴퓨터바이러스 논리폭탄, 메일폭탄, 서비스 거부 또는 고출력 전자기파 등의 방법으로 정보통신망 또는 이와 관련된 정보시스템을 공격하는 행위를 하며 발생한 사태가 발생한 때","이용자 정보가 유출된 때","사전예고 없이 서비스의 중단 기간이 연속해서 10분 이상인 경우이거나 중단 사고가 발생한 때부터 24기간 이내에 서비스가 2회 이상 중단된 경우로서 그 중단된 기간을 합하여 15분 이상 서비스 중단이 발생한 때","민·관 합동조사단이 발생한 침해사고의 원인 분석이 끝났을 때"],"a":3,"e":"클라우드컴퓨팅법 제25조는 침해사고 발생, 이용자 정보 유출, 대통령령으로 정하는 서비스 중단(연속 10분 이상 또는 24시간 내 2회 이상 합계 15분 이상) 시 지체 없이 이용자에게 알리도록 한다. 민·관 합동조사단의 원인 분석 종료는 통지 사유가 아니다(개정 여부 확인).","ce":["해킹·바이러스·서비스 거부 등으로 정보통신망을 공격해 발생한 침해사고는 제25조의 통지 사유이다(개정 여부 확인).","이용자 정보 유출은 제25조에 따라 지체 없이 이용자에게 알려야 하는 사유이다.","예고 없이 연속 10분 이상, 또는 24시간 내 2회 이상 합계 15분 이상의 서비스 중단은 시행령이 정한 통지 사유이다(개정 여부 확인).","민·관 합동조사단의 원인 분석 종료는 제25조의 이용자 통지 사유에 없다."],"rel":["5-10"]},{"n":98,"s":"s5","q":"로그관리와 관련되는 정보보안 속성은?","c":["기밀성","무결성","가용성","책임추적성"],"a":3,"e":"로그는 누가 언제 무엇을 했는지 기록하여 행위자를 추적·식별할 수 있게 하므로 책임추적성(Accountability)과 직결된다. 기밀성·무결성·가용성은 정보 자체의 보호 속성이다.","ce":["기밀성은 인가된 자만 정보에 접근하게 하는 속성으로, 행위 기록·추적을 목적으로 하는 로그관리와 직접 대응되지 않는다.","무결성은 정보가 인가 없이 변경되지 않도록 하는 속성으로, 로그 자체의 무결성 보호는 필요하지만 로그관리가 실현하는 속성은 책임추적성이다.","가용성은 필요할 때 정보·서비스를 사용할 수 있게 하는 속성으로 로그관리의 목적과 다르다.","로그는 누가 언제 무엇을 했는지 기록해 행위자를 식별·추적하게 하므로 책임추적성(Accountability)과 직결된다."],"rel":["5-1"]},{"n":99,"s":"s5","q":"다음 중 정량적 위험분석 방법은?","c":["델파이법","과거 자료 분석법","순위 결정법","시나리오법"],"a":1,"e":"정량적 위험분석에는 과거자료 분석법, 수학공식 접근법, 확률 분포법 등이 있다. 델파이법, 순위 결정법, 시나리오법은 정성적 위험분석 방법이다.","ce":["델파이법은 전문가 의견을 반복 수렴하는 정성적 위험분석 방법이다.","과거 자료 분석법은 과거 사고 통계로 발생 빈도·손실액을 수치화하는 정량적 위험분석 방법이다.","순위 결정법은 위험 요소를 비교해 상대적 순위를 매기는 정성적 방법이다.","시나리오법은 가정된 조건에서 발생 가능한 결과를 추정하는 정성적 방법이다."],"rel":["5-2"]},{"n":100,"s":"s5","q":"다음 중 공공기관이 개인정보 파일을 운용하거나 변경하는 경우 개인정보보호위원회에 등록하여 관리가 필요한 사항이 아닌 것은?","c":["개인정보파일의 명칭","개인정보파일의 운영 근거 및 목적","개인정보파일의 작성 일시","개인정보파일에 기록되는 개인정보의 항목"],"a":2,"e":"개인정보 보호법 제32조에 따른 등록 사항은 개인정보파일의 명칭, 운영 근거 및 목적, 기록되는 개인정보 항목, 처리방법, 보유기간, 제공받는 자 등이다. 개인정보파일의 작성 일시는 등록 사항이 아니다(개정 여부 확인).","ce":["개인정보파일의 명칭은 개인정보 보호법 제32조의 등록 사항이다.","개인정보파일의 운영 근거 및 목적은 등록 사항이다.","개인정보파일의 작성 일시는 제32조의 등록 사항(명칭·근거·목적·항목·처리방법·보유기간·제공받는 자 등)에 없다(개정 여부 확인).","개인정보파일에 기록되는 개인정보의 항목은 등록 사항이다."],"rel":["5-14"]}]},{"id":"2022-06-25","title":"2022년 6월 25일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"서버 시스템의 접근통제 관리에 대한 설명으로 틀린 것은?","c":["윈도우 시스템 이벤트에는 시스템, 어플리케이션, 보안 이벤트가 있으며 감사로그는 제어판-관리도구-로컬보안설정-감사정책에서 각각 설정할 수 있다.","윈도우 시스템은 도메인 환경에서 사용자 인증을 위하여 레지스트리가 익명의 사용자에 의해 접근될 수 있도록 설정하여야 한다.","iptables, tcp wrapper 도구를 사용하면 서버 시스템의 네트워크 접근통제 기능을 설정할 수 있다.","Unix 서버 시스템에서 불필요한 파일에 설정된 SUID와 SGID 비트를 제거하여 실행 권한이 없는 프로그램의 비인가된 실행을 차단하여야 한다."],"a":1,"e":"레지스트리는 시스템 구성과 계정 정보를 담고 있어 익명 사용자의 원격 접근을 차단해야 하며, 도메인 인증을 위해 익명 접근을 허용할 필요는 없다. 감사정책 설정, iptables·TCP Wrapper를 통한 접근통제, 불필요한 SUID/SGID 제거는 올바른 설명이다.","ce":["윈도우 이벤트 로그는 시스템·응용 프로그램·보안으로 나뉘고, 로컬 보안 정책의 감사 정책에서 로그온·개체 액세스 등 감사를 설정하므로 옳은 설명이다.","레지스트리는 시스템 구성과 계정 정보를 담고 있어 익명 사용자의 원격 접근을 차단해야 하며, 도메인 인증을 위해 익명 접근을 허용할 필요는 없다.","iptables(커널 패킷 필터)와 TCP Wrapper(hosts.allow/deny)로 IP·포트 기반 네트워크 접근통제를 설정할 수 있으므로 옳은 설명이다.","불필요한 파일의 SUID/SGID 비트를 제거하면 소유자 권한으로 실행되는 권한 상승 경로를 줄여 비인가 실행을 막으므로 옳은 설명이다."],"rel":["1-17","1-16"]},{"n":2,"s":"s1","q":"다음은 passwd 파일 구조를 나타내는 그림이다. \"G\"가 의미하는 것은?","c":["홈디렉터리 위치","지정된 셸(Shell)","패스워드","설명"],"a":1,"e":"/etc/passwd는 '계정명:패스워드(x):UID:GID:설명:홈디렉터리:로그인 셸' 7개 필드로 구성되며, 마지막 필드 G(/usr/bin/bash)는 로그인 셸이다. F(/home/test)는 홈 디렉터리, E(Gen-User)는 설명 필드이다.","ce":["홈 디렉터리 위치는 여섯 번째 필드 F(/home/test)이다.","/etc/passwd의 마지막(일곱 번째) 필드 G(/usr/bin/bash)는 로그인 시 실행되는 지정된 셸이다.","패스워드는 두 번째 필드 B(x)이며, x는 실제 해시가 /etc/shadow에 있음을 뜻한다.","설명(GECOS, 사용자 정보)은 다섯 번째 필드 E(Gen-User)이다."],"rel":["1-6"],"box":"Test : x : 500 : 500 : Gen-User : /home/test : /usr/bin/bash\n(A=Test, B=x, C=500, D=500, E=Gen-User, F=/home/test, G=/usr/bin/bash)"},{"n":3,"s":"s1","q":"안드로이드 adb를 통해 접속 후 쓰기 가능한 디렉터리는?","c":["/system/","/data/app","/data/local/tmp/","/bin/"],"a":2,"e":"adb shell 사용자(shell 계정)는 /data/local/tmp/에 쓰기 권한이 있어 분석 도구나 바이너리를 업로드해 실행하는 데 흔히 쓰인다. /system은 읽기 전용으로 마운트되고 /data/app은 system 권한이 필요하다.","ce":["/system은 OS 핵심 파일이 있는 파티션으로 읽기 전용으로 마운트되어 adb shell 권한으로는 쓸 수 없다.","/data/app은 설치된 앱 APK가 저장되는 곳으로 system 권한이 필요해 adb shell 사용자는 쓸 수 없다.","/data/local/tmp/는 adb shell 사용자(shell 계정)에게 쓰기 권한이 있어 분석 도구·바이너리를 올려 실행하는 데 흔히 쓰인다.","/bin/은 안드로이드 기본 구조에 없거나(실행파일은 /system/bin) 시스템 영역이라 adb shell 권한으로 쓸 수 없다."],"rel":["1-15"]},{"n":4,"s":"s1","q":"다음 문장에서 설명하는 공격 위협은?","c":["XPath 인젝션","디렉터리 인덱싱","운영체제 명령 실행","정보 누출"],"a":3,"e":"중요정보나 에러 메시지·주석을 통해 시스템 정보가 노출되는 취약점은 정보 누출이다. 디렉터리 인덱싱은 디렉터리 파일 목록 노출, XPath 인젝션은 XML 질의 조작 공격이다.","ce":["XPath 인젝션은 입력값으로 XPath 질의를 조작해 XML 문서의 데이터를 조회하는 공격으로, 에러·중요정보 노출 자체를 가리키지 않는다.","디렉터리 인덱싱은 디렉터리의 파일 목록이 브라우저에 노출되는 취약점으로, 에러 메시지·코멘트를 통한 정보 노출과 구분된다.","운영체제 명령 실행은 입력값이 system() 등으로 전달되어 OS 명령이 실행되는 취약점이다.","중요정보나 에러 메시지·개발 주석 등을 통해 시스템 정보가 노출되어 2차 공격에 활용되는 취약점은 정보 누출이다."],"rel":["3-5"],"box":"웹 사이트에 개인정보, 계정정보, 금융정보 등의 중요정보가 노출되거나 에러 발생시 과도한 정보(애플리케이션 정보, DB정보, 웹 서버 구성 정보, 개발과정의 코멘트 등)가 노출될 경우, 공격자들의 2차 공격을 위한 정보로 활용될 수 있다."},{"n":5,"s":"s1","q":"인증 장치에 대한 설명으로 옳은 것은?","c":["USB 메모리에 디지털 증명서를 넣어 인증 디바이스로 하는 경우 그 USB 메모리를 접속하는 PC의 MAC 어드레스가 필요하다.","성인의 홍채는 변화가 없고 홍채 인증에서는 인증 장치에서의 패턴 갱신이 불필요하다.","정전용량 방식의 지문인증 디바이스 LED 조명을 설치한 실내에서는 정상적으로 인증할 수 없게 될 가능성이 높다.","인증에 이용되는 접촉형 IC 카드는 카드 내의 코일의 유도 기전력을 이용하고 있다."],"a":1,"e":"홍채 패턴은 생후 약 18개월 이후 평생 거의 변하지 않아 등록 패턴을 갱신할 필요가 없다. 정전용량 방식은 조명과 무관하며, 코일의 유도 기전력을 이용하는 것은 비접촉형 IC 카드이다.","ce":["USB에 저장된 인증서는 PC의 MAC 주소와 무관하게 인증서와 개인키(비밀번호)로 인증하므로 MAC 주소가 필요하다는 설명은 틀리다.","홍채 패턴은 생후 약 18개월 이후 평생 거의 변하지 않아 등록 패턴을 갱신할 필요가 없으므로 옳은 설명이다.","정전용량 방식은 지문 융선과 골의 전기 용량 차이를 측정하므로 LED 조명의 영향을 받지 않는다. 조명 영향은 광학식에서 문제된다.","코일의 유도 기전력으로 전원을 얻는 것은 비접촉형(RF) IC 카드이며, 접촉형은 금속 접점으로 전원·데이터를 받는다."],"rel":["4-8"]},{"n":6,"s":"s1","q":"컴퓨터 시스템에 대한 하드닝(Hardening) 활동으로 틀린 것은?","c":["사용하지 않는 PDF 소프트웨어를 제거하였다.","시스템 침해에 대비하여 전체 시스템에 대한 백업을 받아 두었다.","운영체제의 감사 기능과 로깅 기능을 활성화하였다.","운영체제 보안 업데이트를 수행하였다."],"a":1,"e":"하드닝은 불필요한 소프트웨어·서비스 제거, 보안 패치, 감사·로깅 활성화 등으로 공격 표면을 줄이는 예방 활동이다. 백업은 침해 후 복구를 위한 대비책으로 시스템 자체의 보안 강화 활동에 해당하지 않는다.","ce":["사용하지 않는 소프트웨어를 제거하면 취약점이 생길 수 있는 공격 표면이 줄어들므로 하드닝 활동이다.","백업은 침해 후 복구를 위한 대비책으로, 시스템 자체의 공격 표면을 줄이는 하드닝(보안 강화) 활동에 해당하지 않는다.","감사·로깅 기능 활성화는 보안 설정 강화 항목으로 하드닝 가이드(CIS 벤치마크 등)에 포함된다.","운영체제 보안 업데이트(패치)는 알려진 취약점을 제거하는 대표적인 하드닝 활동이다."],"rel":["1-1"]},{"n":7,"s":"s1","q":"다음 문장에서 설명하는 기억 장치의 메모리 반입 정책은?","c":["최초 적합(First fit)","최상 적합(Best fit)","최악 적합(Worst fit)","다음 적합(Next fit)"],"a":2,"e":"최악 적합은 수용 가능한 공간 중 가장 큰 공간에 할당하는 배치 전략이다. 최초 적합은 처음 발견한 공간, 최상 적합은 단편화가 가장 작게 남는 공간에 할당한다(엄밀히는 반입이 아닌 배치 정책).","ce":["최초 적합은 가용 공간을 처음부터 탐색해 처음 발견한 수용 가능 공간에 할당하는 방식이다.","최상 적합은 수용 가능한 공간 중 할당 후 남는 공간이 가장 작은(가장 딱 맞는) 공간에 할당하는 방식이다.","최악 적합은 수용 가능한 공간 중 가장 큰 공간에 할당해 남는 공간을 크게 만드는 방식으로 설명과 일치한다.","다음 적합은 이전 탐색이 끝난 위치부터 이어서 탐색해 처음 맞는 공간에 할당하는 방식이다."],"rel":["1-1"],"box":"입력된 프로그램을 수용할 수 있는 공간 중 가장 큰 공간을 할당한다."},{"n":8,"s":"s1","q":"악성프로그램에 대한 설명으로 틀린 것은?","c":["바이러스 : 한 시스템에서 다른 시스템으로 전파하기 위해서 사람이나 도구의 도움이 필요한 악성프로그램이다.","웜 : 한 시스템에서 다른 시스템으로 전파하는데 있어서 외부의 도움이 필요하지 않은 악성프로그램이다.","백도어 : 사용자의 동의없이 설치되어 컴퓨터 정보 및 사용자 개인정보를 수집하고 전송하는 악성프로그램이다.","논리 폭탄 : 합법적 프로그램 안에 내장된 코드로서 특정한 조건이 만족되었을 때 작동하는 악성 코드이다."],"a":2,"e":"사용자 동의 없이 설치되어 정보를 수집·전송하는 것은 스파이웨어이다. 백도어는 정상 인증 절차를 우회하여 시스템에 접근할 수 있도록 만든 비밀 통로이다.","ce":["바이러스는 다른 파일에 기생하며 사용자의 실행이나 매체 이동 등 외부 도움이 있어야 전파되므로 옳은 설명이다.","웜은 네트워크 취약점 등을 이용해 스스로 복제·전파하므로 외부 도움이 필요 없다는 설명은 옳다.","동의 없이 설치되어 정보를 수집·전송하는 것은 스파이웨어이다. 백도어는 정상 인증 절차를 우회해 시스템에 접근하도록 만든 비밀 통로이다.","논리 폭탄은 정상 프로그램에 숨겨져 특정 날짜·조건이 충족되면 악성 동작을 하는 코드이므로 옳은 설명이다."],"rel":["1-9"]},{"n":9,"s":"s1","q":"다음은 SUID 프로그램이 일반 권한에서 관리자 권한으로 상승하여 처리하는 정상적인 과정을 나타내고 있다. 심볼릭 링크를 이용한 레이스 컨디션 공격이 실행되는 단계는?","c":["1단계","2단계","3단계","4단계"],"a":2,"e":"레이스 컨디션 공격은 SUID 프로그램이 임시 파일을 생성한 뒤 그 파일을 처리(쓰기)하기 직전의 틈에 임시 파일을 삭제하고 같은 이름의 심볼릭 링크(/etc/passwd 등 대상 파일)로 바꿔치기하는 방식으로, 임시 파일 처리 단계(3단계)에서 실행된다.","ce":["1단계는 일반 사용자가 SUID 프로그램을 실행하는 단계로, 아직 임시 파일이 없어 심볼릭 링크 바꿔치기 대상이 없다.","2단계는 SetUID로 권한이 상승하는 단계로, 공격자가 끼어들 임시 파일 처리 틈이 아직 생기지 않았다.","임시 파일을 생성한 뒤 처리하기 직전의 틈에 공격자가 파일을 지우고 같은 이름의 심볼릭 링크(/etc/passwd 등)로 바꿔치기하므로 3단계에서 공격이 실행된다.","4단계는 프로그램 종료 단계로 이미 처리가 끝나 관리자 권한으로 대상 파일을 조작할 기회가 없다."],"rel":["1-10"],"box":"(그림) 일반 권한: 프로그램 실행 →(①단계) SetUID로 인한 프로세스 권한 상승 →(②단계) 관리자 권한: 임시 파일 생성 →(③단계) 프로그램 동작 및 임시 파일 처리 →(④단계) 프로그램 종료","fig":"past/2022-06-25-q9.png"},{"n":10,"s":"s1","q":"다음은 IDS Snort Rule이다. Rule이 10~11번째 2바이트의 값이 0xFFFF인지를 검사하는 Rule이라 할 때 ㉠~㉢의 올바른 키워드는 무엇인가?","c":["㉠ : value, ㉡ : offset, ㉢ : content","㉠ : value, ㉡ : content, ㉢ : offset","㉠ : content, ㉡ : depth, ㉢ : offset","㉠ : content, ㉡ : offset, ㉢ : depth"],"a":3,"e":"검사할 패턴은 content로 지정하고, offset 9는 페이로드 처음부터 9바이트를 건너뛰어 10번째 바이트부터 검사, depth 2는 그 위치부터 2바이트 범위만 검사하도록 한다. 따라서 10~11번째 바이트가 0xFFFF인지 검사하게 된다.","ce":["value는 Snort 패턴 매칭 키워드가 아니며, offset 뒤에 범위를 지정하는 ㉢도 content가 아니라 depth여야 한다.","㉠ 패턴 지정 키워드는 content이고, ㉡·㉢은 시작 위치(offset)와 범위(depth)여야 하므로 모두 어긋난다.","㉠ content는 맞지만 ㉡·㉢이 뒤바뀌었다. 9바이트를 건너뛰는 것은 offset, 2바이트 범위는 depth이다(depth:9면 처음 9바이트 범위).","㉠ content로 |FF FF|를 지정하고, ㉡ offset 9로 9바이트를 건너뛰어 10번째부터, ㉢ depth 2로 2바이트 범위만 검사해 10~11번째 바이트를 확인하므로 올바르다."],"rel":["2-11","2-9"],"box":"alert tcp any any → any any ( flow: to_server; ㉠:\"|FF FF|\"; ㉡:9; ㉢:2; msg:\"Error\";, sid: 1000002; )"},{"n":11,"s":"s1","q":"매크로 바이러스에 대한 설명으로 틀린 것은?","c":["플랫폼과 무관하게 실행된다.","주로 이메일을 통해 감염된다.","문서 파일의 기능을 악용한다.","EXE 형태의 자동화된 기능을 포함한다."],"a":3,"e":"매크로 바이러스는 MS Office 문서 등의 매크로(VBA) 기능을 악용하며 실행파일(EXE)이 아닌 문서 파일에 포함된다. 문서를 여는 응용프로그램만 있으면 운영체제와 무관하게 동작하고 주로 이메일 첨부 문서로 전파된다.","ce":["매크로 바이러스는 문서를 여는 응용프로그램(MS Office 등)에서 실행되므로 운영체제 플랫폼과 무관하게 동작한다는 설명은 옳다.","매크로 바이러스는 주로 이메일에 첨부된 워드·엑셀 문서를 통해 감염되므로 옳은 설명이다.","문서 파일의 매크로(VBA) 자동 실행 기능을 악용하므로 옳은 설명이다.","매크로 바이러스는 실행파일(EXE)이 아닌 문서 파일 내 매크로 코드로 존재하므로 EXE 형태 기능을 포함한다는 진술이 틀렸다."],"rel":["1-19"]},{"n":12,"s":"s1","q":"Window에서 파일이 삭제된 직후 일정 시간(기본 15초)안에 동일한 이름의 파일이 생성되는 경우 방금 삭제된 파일의 테이블 레코드를 재사용하는 경우가 있다. 이러한 특징을 갖는 기능은?","c":["파일시스템 터널링(File system tunneling)","Shellbags","윈도우 파일 프로텍션","타임스톰핑"],"a":0,"e":"파일시스템 터널링은 파일 삭제·이름 변경 후 기본 15초 이내에 같은 이름의 파일이 생성되면 이전 파일의 생성시간 등 메타데이터를 재사용하는 NTFS/FAT 기능으로, 포렌식 타임라인 분석 시 주의해야 한다. 타임스톰핑은 공격자가 파일 시간 정보를 의도적으로 조작하는 안티포렌식 기법이다.","ce":["파일시스템 터널링은 파일 삭제·이름 변경 후 기본 15초 안에 같은 이름의 파일이 생성되면 이전 파일의 생성시간 등 메타데이터를 재사용하는 기능이다.","Shellbags는 사용자가 탐색기에서 연 폴더의 보기 설정·경로를 레지스트리에 기록하는 아티팩트로, 파일 레코드 재사용과 무관하다.","윈도우 파일 보호(WFP)는 중요 시스템 파일이 변경·삭제되면 원본으로 자동 복원하는 기능이다.","타임스톰핑은 공격자가 파일의 MAC 시간 정보를 의도적으로 조작하는 안티포렌식 기법으로, OS 자동 기능이 아니다."],"rel":["1-18"]},{"n":13,"s":"s1","q":"리눅스 Capabilities에서 실행 바이너리에 커널 모듈을 올리거나 내릴 수 있는 권한을 할당할 수 있는 Capability는 무엇인가?","c":["CAP_CHOWN","CAP_AUDIT_CONTROL","CAP_SYS_MODULE","CAP_MAC_ADMIN"],"a":2,"e":"CAP_SYS_MODULE은 커널 모듈 적재·제거(init_module, delete_module) 권한이다. CAP_CHOWN은 파일 소유자 변경, CAP_AUDIT_CONTROL은 커널 감사 설정, CAP_MAC_ADMIN은 MAC(SELinux·Smack 등) 설정 변경 권한이다.","ce":["CAP_CHOWN은 파일의 소유자·그룹을 임의로 변경할 수 있게 하는 권한이다.","CAP_AUDIT_CONTROL은 커널 감사(audit) 규칙과 설정을 변경할 수 있게 하는 권한이다.","CAP_SYS_MODULE은 init_module·delete_module로 커널 모듈을 적재·제거할 수 있게 하는 권한이다.","CAP_MAC_ADMIN은 SELinux·Smack 등 MAC(강제적 접근통제) 정책 설정을 변경할 수 있게 하는 권한이다."],"rel":["1-16"]},{"n":14,"s":"s1","q":"다음 중 로그의 성격이 다른 것은?","c":["데이터베이스 로그","웹서버 로그","메일서버 로그","유닉스 계열의 syslog"],"a":3,"e":"syslog는 운영체제(커널·데몬)의 시스템 로그를 수집하는 유닉스 계열 로그 체계이다. 데이터베이스·웹서버·메일서버 로그는 각 응용프로그램이 생성하는 애플리케이션 로그이다.","ce":["데이터베이스 로그는 DBMS 응용프로그램이 생성하는 애플리케이션 로그이다.","웹서버 로그(access·error log)는 웹서버 응용프로그램이 생성하는 애플리케이션 로그이다.","메일서버 로그는 메일 서버(sendmail·postfix 등) 응용프로그램이 생성하는 애플리케이션 로그이다.","syslog는 커널·시스템 데몬의 메시지를 수집하는 운영체제 수준의 시스템 로그 체계로, 나머지 응용 로그와 성격이 다르다."],"rel":["1-7"]},{"n":15,"s":"s1","q":"윈도 운영체제의 레지스트리에 대한 설명으로 틀린 것은?(문제 오류로 확정답안 발표시 3, 4번이 정답처리 되었습니다. 여기서는 3을 누르면 정답 처리 됩니다.)","c":["시스템 구성정보를 저장하는 데이터베이스로 SYSTEM.DAT, USER.DAT 파일을 말한다.","레지스트리는 regedit.exe 전용 편집기에 의해서만 편집이 가능하다.","윈도우 레지스트리 키는 HKEY_CLASS_ROOT, HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE, HKEY_USERS, HKEY_CURRENT_CONFIG 등이 있다.","레지스트리 백업 및 복구는 shell.exe를 구동하여 행한다."],"a":2,"e":"레지스트리 백업·복구는 regedit.exe(내보내기/가져오기)나 reg.exe 등으로 하며 shell.exe를 쓰지 않으므로 ④가 틀리다. ③은 루트키 HKEY_CLASSES_ROOT를 HKEY_CLASS_ROOT로 잘못 표기해 함께 정답 처리되었으며, ②도 reg.exe 등으로 편집 가능하므로 엄밀히 틀린 설명이다.","ce":["Windows 9x 계열에서 레지스트리는 SYSTEM.DAT·USER.DAT 파일로 저장된 시스템 구성 데이터베이스이므로 옳은 설명으로 처리된다.","regedit 외에 reg.exe, 그룹 정책, PowerShell, API로도 편집할 수 있어 엄밀히 틀리지만, 공식 정답에는 포함되지 않았다.","루트키 이름은 HKEY_CLASSES_ROOT인데 HKEY_CLASS_ROOT로 잘못 표기되어 틀린 진술이다. 확정답안에서 ④와 함께 정답 처리되었다.","레지스트리 백업·복구는 regedit(내보내기/가져오기)이나 reg save/restore로 하며 shell.exe를 쓰지 않는다. 확정답안에서 ③과 함께 정답 처리되었다."],"rel":["1-3"],"flag":"확정답안 ③④ 복수정답(여기선 ③)"},{"n":16,"s":"s1","q":"대부분의 응용 프로그램에서 생성된 파일은 그 응용 프로그램이 생성한 파일임을 인식할 수 있도록 항상 동일한 몇 바이트를 파일 내부의 특정 위치에 가지고 있다. 특정위치의 고정값이 의미하는 것은?","c":["시그니처(Signature)","확장자(Extensions)","메타데이터(Metadata)","레코드(Record)"],"a":0,"e":"파일 시그니처(매직 넘버)는 파일 헤더 등 특정 위치의 고정 바이트로 파일 형식을 식별한다(예: PE 파일 'MZ', PDF '%PDF'). 확장자는 파일명에 붙는 것으로 쉽게 위조할 수 있어 포렌식에서는 시그니처로 실제 형식을 확인한다.","ce":["시그니처(매직 넘버)는 파일 헤더 등 특정 위치의 고정 바이트로 파일 형식을 식별한다(예 PE 'MZ', PDF '%PDF').","확장자는 파일 내부가 아닌 파일명에 붙는 문자열로, 쉽게 바꿀 수 있어 파일 형식 판단의 신뢰 근거가 되지 못한다.","메타데이터는 작성자·생성시간 등 파일을 설명하는 부가 정보로, 형식 식별용 고정 바이트를 뜻하지 않는다.","레코드는 데이터베이스·파일시스템의 데이터 단위(예 MFT 레코드)로, 파일 형식 식별 고정값이 아니다."],"rel":["1-18"]},{"n":17,"s":"s1","q":"다음 그림은 a.a.a.a 시스템에서 UDP 패킷을 TTL=1부터 하나씩 늘려가면서 b.b.b.b로 전송하고, TTL=4일 때 b.b.b.b 시스템에 UDP 패킷이 도달하고 ICMP Port Unreachable(Type 3) 패킷이 a.a.a.a 시스템으로 돌아왔다. 무엇을 하기 위한 과정인가?","c":["ICMP scan","traceroute","ping","UDP scan"],"a":1,"e":"traceroute(유닉스)는 TTL을 1씩 늘린 UDP 패킷을 보내 각 라우터가 반환하는 ICMP Time Exceeded로 경로를 파악하고, 목적지에서 ICMP Port Unreachable을 받으면 종료한다. 윈도우 tracert는 UDP 대신 ICMP Echo를 사용한다.","ce":["ICMP scan은 ICMP Echo 등으로 살아 있는 호스트를 찾는 스캔으로, TTL을 1씩 늘리는 경로 추적과 다르다.","TTL을 1씩 늘린 UDP 패킷으로 각 라우터의 ICMP Time Exceeded를 받아 경로를 파악하고, 목적지의 Port Unreachable로 종료하는 것은 traceroute이다.","ping은 ICMP Echo Request/Reply로 대상의 응답 여부와 왕복시간만 확인하며 TTL을 늘려가며 보내지 않는다.","UDP scan은 여러 포트에 UDP를 보내 Port Unreachable 여부로 포트 개폐를 판단하며, TTL 증가로 중간 경로를 파악하지 않는다."],"rel":["2-2"]},{"n":18,"s":"s1","q":"다음 문장에서 설명하는 Window 시스템의 인증 구성 요소는?","c":["LSA(Local Security Authority)","LAM(Local Authentication Manager)","SAM(Security Account Manager)","SRM(Security Reference Monitor)"],"a":3,"e":"SRM은 인증된 사용자에게 SID를 부여하고, SID 기반으로 객체 접근 허용 여부를 결정하며 감사 메시지를 생성하는 커널 모드 구성요소이다. LSA는 로컬·원격 로그인 인증과 보안 정책을 담당하고, SAM은 계정·패스워드 해시 데이터베이스이다.","ce":["LSA는 로컬·원격 로그인 인증과 보안 정책·감사 정책을 관리하는 구성요소로, 객체 접근 허용 여부를 직접 판단하지 않는다.","LAM(Local Authentication Manager)은 윈도우 인증 구성요소에 없는 용어이다.","SAM은 사용자 계정과 패스워드 해시를 저장·관리하는 데이터베이스로, 접근 결정·감사 메시지 생성 역할이 아니다.","SRM은 인증된 사용자에게 SID를 부여하고 SID 기반으로 객체 접근 허용 여부를 결정하며 감사 메시지를 생성하는 커널 모드 구성요소이다."],"rel":["1-2"],"box":"- 사용자에게 SID(Security Identifier)를 부여한다.\n- SID에 기반하여 파일이나 디렉토리에 대한 접근 허용 여부를 결정한다.\n- 이에 대한 감사 메시지를 생성한다."},{"n":19,"s":"s1","q":"BIOS에 대한 설명으로 틀린 것은?","c":["하드디스키의 구성, 종류, 용량을 확인할 수 있다.","전원이 공급되지 않으면 정보가 유지되지 않는다.","운영체제와 하드웨어 사이의 입출력을 담당하는 펌웨어이다.","BIOS에 저장된 시스템 시간은 포렌식 관점에서 중요하다."],"a":1,"e":"BIOS 프로그램은 ROM(플래시 메모리)에 저장되어 전원이 없어도 유지되며, 설정값은 CMOS 배터리로 유지된다. BIOS는 하드웨어 초기화와 입출력을 담당하는 펌웨어로, 디스크 구성 확인이 가능하고 시스템 시간은 포렌식 타임라인 기준으로 중요하다.","ce":["BIOS 설정 화면에서 연결된 하드디스크의 구성·종류·용량을 확인할 수 있으므로 옳은 설명이다.","BIOS 프로그램은 ROM(플래시)에 저장되어 전원 없이도 유지되고, 설정값은 CMOS 배터리로 유지되므로 정보가 유지되지 않는다는 진술이 틀렸다.","BIOS는 하드웨어 초기화(POST)와 운영체제-하드웨어 간 기본 입출력을 담당하는 펌웨어이므로 옳은 설명이다.","BIOS(RTC) 시간은 OS 시간 기준이 되어 포렌식 타임라인의 오차 보정에 중요하므로 옳은 설명이다."],"rel":["1-17"]},{"n":20,"s":"s1","q":"다음 중 인증의 방법이 아닌 것은?","c":["당신이 알고 있는 것(Something You Know)","당신이 위치를 알고 있는 곳(Somewhere You Know)","당신이 가지고 있는 것(Something You Have)","당신 모습 자체(Something You Are)"],"a":1,"e":"인증 방식은 지식(Something You Know), 소유(Something You Have), 존재·생체(Something You Are), 행위(Something You Do)로 분류되며, 위치 기반은 'Somewhere You Are'(현재 있는 곳)로 표현한다. '위치를 알고 있는 곳'은 인증 요소가 아니다.","ce":["Something You Know는 비밀번호·PIN처럼 사용자가 알고 있는 것에 기반한 지식기반 인증이다.","위치 기반 인증은 'Somewhere You Are'(현재 있는 곳)로 표현하며, '위치를 알고 있는 곳'은 인증 요소 분류에 없다.","Something You Have는 OTP 토큰·스마트카드처럼 사용자가 가진 것에 기반한 소유기반 인증이다.","Something You Are는 지문·홍채 등 사용자 신체 특성에 기반한 생체(존재) 인증이다."],"rel":["4-8"]},{"n":21,"s":"s2","q":"패킷 필터링을 위한 규칙에 대한 설명으로 틀린 것은? (단, 서비스에 사용되는 포트는 기본값이며, Internal은 내부, External은 외부 네트워크를 의미한다.)","c":["내부에서 외부로 나가는 웹 서비스에 대해서 허용한다.","서버(169.168.2.25)로 FTP 서비스 연결은 어디에서나 가능하나 데이터 전송은 원활하게 이루어지지 않을 수 있다.","필터링 규칙에 명시하지 않은 모든 프로토콜에 대해서는 거부한다.","서버(169.168.10.10)로 DNS 서비스는 내부에서 이용이 가능하나 Message 정보가 512 바이트보다 클 경우에는 허용하지 않는다."],"a":3,"e":"DNS는 일반 질의에 UDP 53을, 512바이트를 초과하는 응답이나 영역 전송에 TCP 53을 사용한다. 규칙 3은 TCP 53만 허용하므로 512바이트 이하 일반 UDP 질의가 오히려 차단되고 큰 메시지는 허용되어 ④는 틀리다. FTP는 21번 제어 연결만 허용되어 20번 데이터 연결이 원활하지 않을 수 있다.","ce":["규칙 1은 내부에서 외부로 향하는 80/TCP(HTTP)를 허용하므로 옳은 설명이다.","규칙 2는 21/TCP 제어 연결만 허용하고 20번(Active)·임의 포트(Passive) 데이터 연결은 허용하지 않아 데이터 전송이 원활하지 않을 수 있으므로 옳은 설명이다.","마지막 규칙 4(Any/Any/Any/Deny)가 기본 거부 규칙이므로 명시하지 않은 모든 트래픽을 거부한다는 설명은 옳다.","DNS는 일반 질의에 UDP 53, 512바이트 초과 응답·영역 전송에 TCP 53을 쓴다. 규칙 3은 TCP 53만 허용하므로 오히려 큰 메시지는 허용되고 일반 UDP 질의가 차단되어 틀린 진술이다."],"rel":["2-9"],"box":"번호 | From | To | Service | Action\n1 | Internal | External | 80/TCP | Allow\n2 | Any | 169.168.2.25 | 21/TCP | Allow\n3 | Internal | 169.168.10.10 | 53/TCP | Allow\n4 | Any | Any | Any | Duny"},{"n":22,"s":"s2","q":"UDP Flooding의 대응 방안으로 틀린 것은?","c":["미사용 프로토콜 필터링","도착지 IP별 임계치 기반 차단","패킷 크기 기반 차단","Anycast를 이용한 대응"],"a":1,"e":"UDP Flooding은 출발지 IP별 임계치(PPS) 기반으로 차단해야 하며, 도착지 IP별 임계치로 차단하면 공격 대상 서버로 가는 정상 트래픽까지 모두 차단된다. 미사용 프로토콜 필터링, 비정상 패킷 크기 차단, Anycast 분산은 유효한 대응이다.","ce":["사용하지 않는 UDP 서비스·프로토콜을 방화벽에서 필터링하면 공격 트래픽이 서버에 도달하지 않으므로 유효한 대응이다.","도착지 IP별 임계치로 차단하면 공격 대상 서버로 향하는 정상 트래픽까지 모두 차단된다. 출발지 IP별 임계치(PPS) 기반으로 차단해야 한다.","UDP Flooding은 비정상적으로 큰(또는 고정된) 크기의 패킷을 쓰는 경우가 많아 패킷 크기 기반 차단이 유효하다.","Anycast로 동일 IP를 여러 지역 노드에 분산하면 공격 트래픽이 분산 흡수되므로 유효한 대응이다."],"rel":["2-3"]},{"n":23,"s":"s2","q":"클라우드 시스템 및 서비스와 관련한 보안 측면의 설명으로 틀린 것은?","c":["클라우드 서비스를 구동하기 위해 필수적인 가상화 시스템 내 하이퍼바이저가 취약할 경우 이를 활용하는 여러 개의 가상머신(VM)이 동시에 피해를 입을 가능성을 고려해야 한다.","기존 네트워크 보안기술(방화벽, IPS/IDS)로는 가상화 내부 영역에 대한 침입탐지가 어렵다.","사용자의 가상머신들의 상호 연결되어 내부의 가상머신에서 다른 가상 머신으로서 패킷스니핑, 해킹, DDoS 공격, 악성코드전파 등의 공격 경로가 존재한다.","가상화 기술 중 스토리지 가상화와 네트워크 가상화에 보안 위협이 존재하나 메모리 가상화에는 보안 위협이 존재하지 않는다."],"a":3,"e":"메모리 가상화에도 VM 간 메모리 공유·중복 제거를 악용한 사이드채널 공격, VM 탈출 등 보안 위협이 존재한다. 하이퍼바이저 취약 시 다수 VM 동시 피해, 기존 경계 보안장비로 VM 간 내부 트래픽 탐지가 어려운 점은 맞는 설명이다.","ce":["하이퍼바이저가 취약하면 그 위에서 동작하는 여러 VM이 동시에 영향을 받으므로(VM 탈출 등) 옳은 설명이다.","VM 간 트래픽은 물리 네트워크를 거치지 않고 가상 스위치 안에서 오가므로 기존 경계 방화벽·IPS/IDS로는 탐지가 어렵다는 설명은 옳다.","같은 호스트의 VM들이 가상 네트워크로 연결되어 VM 간 스니핑·해킹·DDoS·악성코드 전파 경로가 존재하므로 옳은 설명이다.","메모리 가상화에도 VM 간 메모리 공유·중복 제거를 악용한 사이드채널 공격, 메모리 탈취 등 위협이 존재하므로 위협이 없다는 진술이 틀렸다."],"rel":["1-12"]},{"n":24,"s":"s2","q":"다음 중 원격지 서버의 스니핑 모니터링 프로그램인 sentinal을 이용하여 스니퍼를 탐지하는 예시와 그에 대한 의미로 틀린 것은?","c":["./sentinel -a -t 211.47.65.4 : ARP 테스트","./sentinel -d -f 1.1.1.1 -t 211.47.65.4 : DNS 테스트","./sentinel -e -t 211.47.65.4 : Etherping 테스트","./sentinel -t 211.47.65.4 -f 1.1.1.1 -d -a -e : 3개의 테스트 중 하나만 테스트"],"a":3,"e":"sentinel은 -a(ARP 테스트), -d(DNS 테스트), -e(Etherping 테스트) 옵션으로 원격 호스트의 무차별 모드 여부를 검사하며, -t는 대상, -f는 DNS 테스트용 가짜 IP이다. ④처럼 -d -a -e를 함께 지정하면 세 가지 테스트를 모두 수행한다.","ce":["-a 옵션은 위조 ARP 요청에 대한 응답 여부로 무차별 모드를 판단하는 ARP 테스트이므로 옳은 설명이다.","-d 옵션은 -f로 지정한 가짜 IP로 패킷을 보낸 뒤 대상이 그 IP의 DNS 역조회를 하는지 보는 DNS 테스트이므로 옳은 설명이다.","-e 옵션은 위조 MAC 주소로 ICMP Echo를 보내 응답 여부를 보는 Etherping 테스트이므로 옳은 설명이다.","-d -a -e를 함께 지정하면 세 가지 테스트를 모두 수행하므로 '하나만 테스트'한다는 설명이 틀렸다(원문 끝부분 인쇄가 흐려 -e로 추정)."],"rel":["2-5"],"flag":"④ 옵션 끝부분 인쇄 흐림(-e 추정)"},{"n":25,"s":"s2","q":"다음 문장의 괄호 안에 들어갈 명령어를 순서대로 나열한 것은?","c":["㉠ : show process, ㉡ : show controllers, ㉢ : show flash","㉠ : show process, ㉡ : show controllers, ㉢ : show memory","㉠ : show process, ㉡ : show interface, ㉢ : show flash","㉠ : show process, ㉡ : show interface, ㉢ : show memory"],"a":1,"e":"show process(cpu)는 CPU 사용률, show controllers는 인터페이스 하드웨어(컨트롤러) 정보, show memory는 메모리 전체·사용·여유 용량을 보여준다. show interface는 인터페이스 상태·트래픽 통계, show flash는 플래시에 저장된 IOS 이미지 정보를 보여준다.","ce":["㉠ show process, ㉡ show controllers는 맞지만 ㉢ show flash는 플래시에 저장된 IOS 이미지 파일 정보를 보여주며 메모리 사용량 명령이 아니다.","㉠ show process(cpu)는 CPU 사용률, ㉡ show controllers는 인터페이스 하드웨어 정보, ㉢ show memory는 메모리 전체·사용·여유 용량을 보여주므로 올바르다.","㉡ show interface는 인터페이스 상태·트래픽 통계를 보여주고, ㉢ show flash는 플래시 파일 정보이므로 둘 다 어긋난다.","㉢ show memory는 맞지만 ㉡ show interface는 하드웨어(컨트롤러) 정보가 아닌 인터페이스 상태·통계를 보여준다."],"rel":["2-12"],"box":"시스코 라우터에서 CPU 평균 사용률을 보기 위해서는 ( ㉠ )의 명령어를 사용하고 라우터 인터페이스 하드웨어 정보를 보기 위해서는 ( ㉡ )을 사용하며, 메모리의 전체 용량, 사용량, 남은 용량 등을 확인하기 위해서는 ( ㉢ ) 명령어를 사용한다."},{"n":26,"s":"s2","q":"다음 문장에서 설명하는 해커의 분류는?","c":["Elite","Script Kiddie","Developed Kiddie","Lamer"],"a":2,"e":"Developed Kiddie는 여러 번 시도 끝에 침투에 성공하기도 하고 이를 자랑하지만, 취약점을 새로 발견하거나 상황에 맞게 변형할 능력은 없는 수준이다. Script Kiddie는 원리를 모른 채 공개 도구만 사용하고, Lamer는 해킹 능력 없이 해커를 동경하는 수준이다.","ce":["Elite는 취약점을 직접 발견하고 흔적 없이 침투하는 최상위 수준 해커로, 취약점 발견 능력이 없다는 설명과 맞지 않는다.","Script Kiddie는 원리를 모른 채 공개된 도구·스크립트만 실행하는 수준으로, 여러 번 시도해 침투하고 자랑하는 Developed Kiddie보다 한 단계 아래로 분류된다.","Developed Kiddie는 여러 번 시도 끝에 침투에 성공하기도 하고 자랑하지만, 취약점을 새로 발견하거나 변형할 능력은 없는 수준으로 설명과 일치한다.","Lamer는 해킹 능력 없이 해커를 동경하기만 하는 최하위 수준이다."],"box":"- 해킹수행코드가 적용될 수 있을 만한 취약점을 발견할 때까지 여러 번 시도해 시스템 침투해 성공하는 경우도 있으며, 성공된 해킹에 대해 자랑하고 다닌다.\n- 보안상 취약점을 새로 발견하거나 최근 취약점을 주어진 상황에 맞게 바꿀만한 능력이 없다."},{"n":27,"s":"s2","q":"SNMP 커뮤니티 스트링에 대한 설명으로 틀린 것은?","c":["기본적으로 Public, Private으로 설정된 경우가 많다.","모든 서버 및 클라이언트에서 동일한 커뮤니티 스트링을 사용해야만 한다.","MIB 정보를 주고 받기 위하여 커뮤니티 스트링을 사용한다.","유닉스 환경에서 커뮤니티 스트링 변경은 일반 권한으로 설정한다."],"a":3,"e":"SNMP 설정 파일(snmpd.conf)의 커뮤니티 스트링 변경은 root(관리자) 권한으로 수행해야 한다. 커뮤니티 스트링은 매니저와 에이전트 간 MIB 정보 교환 시 인증 암호 역할을 하며 기본값 public/private은 반드시 변경해야 한다.","ce":["SNMP 장비는 기본 커뮤니티 스트링이 읽기용 public, 쓰기용 private으로 설정된 경우가 많아 반드시 변경해야 하므로 옳은 설명이다.","매니저와 에이전트가 같은 커뮤니티 스트링을 써야 통신·인증이 되므로 옳은 설명으로 처리된다.","커뮤니티 스트링은 매니저-에이전트 간 MIB 정보 교환 시 일종의 비밀번호 역할을 하므로 옳은 설명이다.","유닉스에서 snmpd.conf의 커뮤니티 스트링 변경은 root(관리자) 권한으로 수행해야 하므로 일반 권한으로 설정한다는 진술이 틀렸다."],"rel":["2-13"]},{"n":28,"s":"s2","q":"TCP 세션 하이재킹의 공격 순서로 옳은 것은?","c":["㉠→㉡→㉢→㉣→㉤","㉠→㉣→㉢→㉡→㉤","㉠→㉡→㉣→㉢→㉤","㉠→㉢→㉣→㉡→㉤"],"a":3,"e":"공격자는 먼저 스니핑으로 시퀀스 넘버를 파악(㉠)한 뒤 RST로 서버 측 연결을 끊고(㉢), 새 시퀀스 넘버를 생성해 서버에 보내면(㉣) 서버가 이를 받아들여 세션을 다시 열고(㉡), 공격자와 서버가 established 상태가 된다(㉤).","ce":["스니핑(㉠) 직후 서버가 새 시퀀스를 받아들이는 ㉡이 올 수 없다. RST로 연결을 끊고(㉢) 새 시퀀스를 보내야(㉣) 서버가 세션을 연다.","새 시퀀스 전송(㉣)이 RST로 서버 연결을 끊는 ㉢보다 먼저 올 수 없다. 기존 세션을 끊은 뒤 새 시퀀스를 보내야 한다.","서버가 새 시퀀스를 받아들이는 ㉡이 RST(㉢)·새 시퀀스 전송(㉣)보다 앞설 수 없어 인과 순서가 어긋난다.","스니핑으로 시퀀스 획득(㉠)→RST로 서버 연결 끊기(㉢)→새 시퀀스 생성·전송(㉣)→서버가 수용하고 세션 재개(㉡)→양측 established(㉤)의 올바른 순서이다."],"rel":["2-5"],"box":"㉠ 공격자는 스니핑을 하며 세션을 확인하고 적절한 시퀀스 넘버를 획득한다.\n㉡ 서버는 새로운 시퀀스 넘버를 받아들이며, 다시 세션을 연다.\n㉢ RST 패킷을 보내 서버쪽 연결만을 끊는다. 서버는 잠시 closed 상태가 되나 클라이언트는 그대로 established 상태로 남는다.\n㉣ 공격자는 새로 시퀀스 넘버를 생성하며 서버로 보낸다.\n㉤ 공격자는 정상적인 연결처럼 서버와 시퀀스 넘버를 교환하고 공격자와 서버 모두 established 상태가 된다."},{"n":29,"s":"s2","q":"침입탐지 시스템(Intrusion Detection System)의 이상 탐지(anomaly detection) 방법 중 다음 문장에서 설명하는 방법은 무엇인가?","c":["예측 가능한 패턴 생성(Predictive Pattern Generation)","통계적 접근법(Statictical Approaches)","비정상적인 행위 측정 방법들의 결합(anomaly measures)의 결합","특징 추출(Feature Selection)"],"a":1,"e":"통계적 접근법은 과거 경험 자료로 사용자·시스템 행위 프로파일을 만들고 주기적으로 갱신·비교하여 통계적 편차가 큰 행위를 이상으로 판단한다. 예측 가능한 패턴 생성은 사건 간 순차 관계(시간 규칙)를 이용해 다음 사건을 예측하는 방법이다.","ce":["예측 가능한 패턴 생성은 사건 간 순차 관계(시간 기반 규칙)를 학습해 다음 사건을 예측하고 어긋나면 이상으로 판단하는 방법으로, 프로파일 통계와 다르다.","통계적 접근법은 과거 경험 자료로 사용자·시스템 행위 프로파일을 만들고 주기적으로 갱신·비교해 편차가 큰 행위를 이상으로 판단하므로 설명과 일치한다.","비정상 행위 측정 방법의 결합은 여러 이상 탐지 척도를 조합해 판단하는 방식으로, 과거 자료 프로파일 생성 방식 자체를 가리키지 않는다.","특징 추출은 침입 탐지에 유효한 측정 항목(특징)의 부분집합을 골라내는 방법이다."],"rel":["2-9"],"box":"- 과거의 경험적인 자료를 토대로 처리한다.\n- 행위를 관찰하고 각각의 행위에 대한 프로파일을 생성한다.\n- 프로파일들을 주기적으로 관찰하며 이상을 측정한다."},{"n":30,"s":"s2","q":"다음 중 일반적으로 사용되는 서비스와 해당 서비스의 기본 설정 포트연결이 틀린 것은?","c":["SSH(Secure Shell) - 22","SMTP(Simple Mail Transfer Protocol) - 25","FTP(File Transfer Protocol) - 28","HTTPS(Hyper-Text Transfer Protocol over Secure layer) - 443"],"a":2,"e":"FTP는 TCP 21번(제어)과 20번(데이터, Active 모드)을 사용하며 28번이 아니다. SSH 22, SMTP 25, HTTPS 443은 올바른 기본 포트이다.","ce":["SSH의 기본 포트는 TCP 22번으로 올바른 연결이다.","SMTP의 기본 포트는 TCP 25번으로 올바른 연결이다.","FTP는 TCP 21번(제어)과 20번(Active 모드 데이터)을 사용하며 28번이 아니다.","HTTPS의 기본 포트는 TCP 443번으로 올바른 연결이다."],"rel":["2-1"]},{"n":31,"s":"s2","q":"네트워크 도청을 예방하기 위한 대책으로 틀린 것은?","c":["업무용 무선 AP와 방문자용 AP를 같이 사용한다.","무선 AP의 비밀번호는 쉽게 예측하지 못하는 안전한 비밀번호로 설정한다.","업무용 단말기는 방문자용 AP에 접속하지 않도록 조치한다.","중요 정보는 암호화 통신을 이용하여 전송한다."],"a":0,"e":"업무용 AP와 방문자용 AP는 SSID·VLAN 등으로 분리해야 방문자 단말을 통한 업무망 도청·침입을 막을 수 있다. 안전한 AP 비밀번호, 업무 단말의 방문자 AP 접속 금지, 암호화 통신은 올바른 대책이다.","ce":["업무용 AP와 방문자용 AP를 함께 쓰면 방문자 단말이 업무망 트래픽을 도청하거나 침입할 수 있다. SSID·VLAN 등으로 분리해야 한다.","AP 비밀번호를 예측하기 어렵게 설정하면 비인가 접속과 사전 공격을 통한 무선망 도청을 막으므로 올바른 대책이다.","업무 단말이 보안 수준이 낮은 방문자용 AP에 접속하지 않게 하면 업무 트래픽 노출을 막으므로 올바른 대책이다.","중요 정보를 TLS·VPN 등 암호화 통신으로 전송하면 도청되더라도 내용이 보호되므로 올바른 대책이다."],"rel":["2-10"]},{"n":32,"s":"s2","q":"다익스트라(Dijkstra) 알고리즘을 사용하는 라우팅 프로토콜에 대한 설명으로 틀린 것은?","c":["대규모 망에 적합한 알고리즘이다.","커리벡터 알고리즘이다.","OSPF에서 사용된다.","링크상태 알고리즘이다."],"a":1,"e":"다익스트라 알고리즘은 전체 토폴로지로 최단 경로 트리를 계산하는 링크 상태(Link State) 알고리즘으로 OSPF·IS-IS에서 사용되며 대규모 망에 적합하다. 거리 벡터(Distance Vector) 알고리즘은 벨만-포드 기반으로 RIP에서 사용된다.","ce":["다익스트라 기반 링크 상태 라우팅은 계층(Area) 구조로 확장이 가능하고 수렴이 빨라 대규모 망에 적합하므로 옳은 설명이다.","다익스트라는 거리 벡터(Distance Vector)가 아닌 링크 상태 알고리즘이다. 거리 벡터는 벨만-포드 기반으로 RIP에서 사용된다('커리벡터'는 거리벡터 오기).","OSPF는 링크 상태 정보로 다익스트라(SPF) 알고리즘을 실행해 최단 경로 트리를 계산하므로 옳은 설명이다.","다익스트라는 전체 토폴로지(링크 상태 DB)로 최단 경로를 계산하는 링크 상태 알고리즘이므로 옳은 설명이다."],"rel":["2-12"]},{"n":33,"s":"s2","q":"IPSec을 구축하기 위해 SA를 사용한다. SA 매개변수에 포함되는 내용으로 틀린 것은?","c":["AH Information","Routing Protocol","IPSec Protocol Mode","Sequence Number Counter"],"a":1,"e":"SA(Security Association) 매개변수에는 순서번호 카운터, 순서 카운터 오버플로, 재전송 방지 윈도, AH 정보, ESP 정보, SA 수명, IPsec 프로토콜 모드(전송/터널), 경로 MTU 등이 포함된다. 라우팅 프로토콜은 SA 매개변수가 아니다.","ce":["AH Information(인증 알고리즘·키·키 수명 등)은 SA 매개변수에 포함된다.","라우팅 프로토콜은 경로 선택을 위한 별개 기능으로 SA 매개변수에 포함되지 않는다.","IPsec 프로토콜 모드(전송/터널)는 SA 매개변수에 포함된다.","Sequence Number Counter는 AH/ESP 헤더의 순서번호 생성에 쓰이는 SA 매개변수이다(재전송 방지 윈도와 함께 사용)."],"rel":["2-6"]},{"n":34,"s":"s2","q":"최근 장시간 악성코드를 잠복시킨 후 일정 시간이 되면 공격을 시도하여 정보 유출 및 내부망 마비 등 피해를 유발시키는 APT 공격이 잦아지고 있다. APT는 무엇의 약자인가?","c":["Advanced Pain Threat","Advanced Post Threat","Advanced Persistent Target","Advanced Persistent Threat"],"a":3,"e":"APT는 Advanced Persistent Threat(지능형 지속 위협)의 약자로, 특정 대상을 정해 장기간 잠복하며 지능적 기법으로 지속 공격하는 형태이다.","ce":["'Pain'은 APT의 P가 아니다. P는 Persistent(지속적)이다.","'Post'는 APT의 P가 아니며, 장기간 잠복·지속 공격을 뜻하는 Persistent가 맞다.","P는 Persistent가 맞지만 T는 Target(대상)이 아니라 Threat(위협)이다.","APT는 Advanced Persistent Threat(지능형 지속 위협)의 약자로, 특정 대상을 정해 장기간 잠복하며 지속 공격하는 형태이다."],"rel":["1-19"]},{"n":35,"s":"s2","q":"BYOD(Bring Your Own Device)의 보안 기술 중 다음 문장에서 설명하는 모바일 기기 보안 기술은?","c":["클라우드 DaaS(Desktop As A Service)","모바일 가상화(Hypervisors)","컨테이너화(Containerization)","가상데스크톱 인프라(Virtual Desktop Infrastructure)"],"a":1,"e":"확정답안은 모바일 가상화(Hypervisors)이다. 모바일 가상화는 단말에 하이퍼바이저를 두어 개인용 OS와 업무용 OS를 분리 실행하는 기술이며, 컨테이너화는 하나의 OS 안에서 업무 앱·데이터 영역을 격리한다.","ce":["DaaS는 클라우드에서 가상 데스크톱을 서비스로 제공하는 방식으로 단말에 OS를 분리 실행하지 않는다. 원문 설명 문장이 누락되어 공식 정답 기준으로 판단한다.","공식 정답이다. 모바일 가상화는 단말에 하이퍼바이저를 두어 개인용 OS와 업무용 OS를 분리 실행하는 기술이다(원문 설명 문장 누락, 공식 정답 기준).","컨테이너화는 하나의 OS 안에서 업무 앱·데이터 영역을 암호화·격리하는 기술로 하이퍼바이저를 쓰지 않는다. 원문 설명 문장 누락으로 공식 정답 기준 판단이다.","VDI는 서버의 가상 데스크톱 화면만 단말로 전송하는 방식이다. 원문 설명 문장이 누락되어 공식 정답 기준으로 판단한다."],"rel":["1-15"],"flag":"원본에 설명 문장(보기 상자) 누락"},{"n":36,"s":"s2","q":"다음 문장의 괄호 안에 들어갈 말은?","c":["Duplex Mode","MAC","Promiscuous Mode","ARP"],"a":2,"e":"스니퍼는 자신에게 오지 않은 패킷도 수신하기 위해 NIC를 무차별(Promiscuous) 모드로 설정하므로, 안티 스니퍼 도구는 NIC의 무차별 모드 여부를 검사해 스니퍼를 탐지한다.","ce":["Duplex Mode는 NIC의 반이중/전이중 통신 방식 설정으로, 스니퍼 동작 여부와 무관하다.","MAC은 NIC의 하드웨어 주소로, 안티 스니퍼 도구가 점검하는 '모드'가 아니다(MAC 위조 패킷은 탐지 수단으로 쓰일 뿐).","스니퍼는 자신에게 오지 않은 프레임도 받기 위해 NIC를 무차별(Promiscuous) 모드로 설정하므로 안티 스니퍼는 이 모드 여부를 검사한다.","ARP는 IP를 MAC으로 변환하는 프로토콜로, 탐지 기법(ARP 테스트)에 쓰일 수는 있으나 NIC의 설정 상태 자체는 아니다."],"rel":["2-5"],"box":"Anti Sniffer 도구들의 특징은 로콜 네트워크에서 네트워크 카드의 (   ) 여부를 체크하며 스니퍼가 돌고 있는지를 파악한다."},{"n":37,"s":"s2","q":"다음 공개 해킹도구 중 사용용도가 다른 도구(소프트웨어)는?","c":["넷버스(Netbus)","스쿨버스(Schoolbus)","백오리피스(Back Orifice)","키로그23(Keylog23)"],"a":3,"e":"넷버스, 스쿨버스, 백오리피스는 감염 PC를 원격 제어하는 트로이목마(백도어) 계열 도구이다. 키로그23은 키보드 입력을 가로채 기록하는 키로거이다.","ce":["넷버스(NetBus)는 감염 PC를 원격 제어하는 트로이목마(백도어) 도구이다.","스쿨버스(Schoolbus)는 넷버스와 유사한 원격 제어 트로이목마(백도어) 도구이다.","백오리피스(Back Orifice)는 윈도우 PC를 원격 제어하는 대표적인 트로이목마(백도어) 도구이다.","키로그23은 키보드 입력을 가로채 기록하는 키로거로, 원격 제어 백도어인 나머지 도구와 용도가 다르다."],"rel":["1-19"]},{"n":38,"s":"s2","q":"RFID 보안 기술에서 암호 기술을 사용하는 보호대책은?","c":["Kill 명령어 기법","블로커 태그 기법","XOR(Exclusive OR) 기반 원타임 패드 기법","Sleep 명령과 Wake 명령어 기법"],"a":2,"e":"XOR 기반 원타임 패드 기법은 태그와 리더가 공유한 비밀값을 XOR 연산해 ID를 매번 바꾸는 암호 기반 보호대책이다. Kill 명령, 블로커 태그, Sleep/Wake 명령은 암호를 사용하지 않는 물리적·논리적 차단 방식이다.","ce":["Kill 명령은 태그를 영구 비활성화해 정보 노출을 막는 방식으로 암호 기술을 쓰지 않는다.","블로커 태그는 방해 신호로 리더의 태그 인식을 교란하는 물리적 차단 방식으로 암호 기술을 쓰지 않는다.","XOR 기반 원타임 패드 기법은 태그와 리더가 공유한 비밀값을 XOR 연산해 ID를 매번 바꾸는 암호 기반 보호대책이다.","Sleep/Wake 명령은 태그를 일시 비활성화했다가 다시 켜는 제어 방식으로 암호 기술을 쓰지 않는다."],"rel":["1-15"]},{"n":39,"s":"s2","q":"포트 스캐너로 유명한 Nmap에서 대상 시스템의 운영체제를 판단할 때 이용하는 기법을 가장 잘 표현하고 있는 것은?","c":["Telnet 접속시 운영체제가 표시하는 고유한 문자열을 분석하는 배너 그래빙(banner grabbing)","운영체제별로 지원하는 서비스 및 열려 있는 포트의 차이","운영체제별로 고유한 식별자 탐지","TCP/IP 프로토콜 표준이 명시하지 않은 패킷 처리 기능의 운영체제별 구현"],"a":3,"e":"Nmap의 OS 탐지(-O)는 TCP/IP 스택 핑거프린팅으로, 표준에 명시되지 않은 부분(비정상 플래그 조합 응답, 초기 TTL, 윈도 크기, ISN 패턴 등)의 운영체제별 구현 차이를 이용한다. 배너 그래빙은 서비스 응답 문자열을 이용하는 별도 기법이다.","ce":["배너 그래빙은 서비스 응답 문자열로 OS·버전을 추정하는 별도 기법이며, Nmap의 -O OS 탐지 원리는 TCP/IP 스택 핑거프린팅이다.","열린 포트·서비스 차이는 OS 추정의 보조 단서일 뿐 운영체제가 같아도 설정에 따라 달라져 Nmap OS 탐지의 핵심 기법이 아니다.","'운영체제별 고유 식별자'가 네트워크로 전송되는 것은 아니며, Nmap은 패킷 응답의 구현 차이를 비교해 추정한다.","Nmap은 표준에 명시되지 않은 부분(비정상 플래그 응답, 초기 TTL, 윈도 크기, ISN 패턴 등)의 OS별 구현 차이를 이용하는 스택 핑거프린팅으로 OS를 판단한다."],"rel":["2-4"]},{"n":40,"s":"s2","q":"리눅스 환경에서 트래픽을 분석하기 위해 MRTG(Multi Router Traffic Grapher)를 사용한다. 다음 중 MRTG를 설치 및 수행하는데 필요없는 프로그램은?","c":["C Compiler","Perl","Gd Library","Libpcap"],"a":3,"e":"MRTG는 SNMP로 트래픽 정보를 수집해 그래프로 보여주며 설치·수행에 C 컴파일러, Perl, 그래프 생성용 gd·libpng·zlib 라이브러리가 필요하다. libpcap은 패킷 캡처 라이브러리로 MRTG에는 필요하지 않다.","ce":["MRTG 일부 모듈(rateup 등)은 C 소스로 제공되어 설치 시 C 컴파일러가 필요하다.","MRTG 본체는 Perl 스크립트로 작성되어 있어 수행에 Perl이 필요하다.","MRTG는 트래픽 그래프(PNG) 생성에 gd 라이브러리(및 libpng·zlib)를 사용한다.","libpcap은 패킷 캡처 라이브러리로, SNMP로 트래픽 카운터를 수집하는 MRTG에는 필요하지 않다."],"rel":["2-13"]},{"n":41,"s":"s3","q":"PGP 서비스와 관련하여 디지털 서명 기능을 위해 사용되는 알고리즘은?(문제 오류로 확정답안 발표시 2, 3번이 정답처리 되었습니다. 여기서는 2번을 누르시면 정답 처리 됩니다.)","c":["3DES","DSS/SHA","RSA","Radix-64"],"a":1,"e":"PGP의 전자서명은 DSS/SHA 또는 RSA/SHA 조합으로 수행되므로 ②와 ③이 모두 정답 처리되었다. 3DES는 메시지 암호화(기밀성), Radix-64는 이메일 호환성을 위한 인코딩에 사용된다.","ce":["3DES는 PGP에서 메시지 암호화(기밀성)에 쓰이는 대칭키 알고리즘으로 서명용이 아니다.","PGP 전자서명은 DSS/SHA 조합으로 수행할 수 있어 정답이다. 단 RSA/SHA도 가능해 확정답안에서 ③과 복수정답 처리되었다.","PGP는 RSA/SHA 조합으로도 전자서명을 하므로 확정답안에서 ②와 함께 정답으로 인정되었다.","Radix-64는 바이너리 데이터를 이메일 호환 ASCII로 변환하는 인코딩 방식으로 서명 알고리즘이 아니다."],"rel":["3-2"],"flag":"확정답안 ②③ 복수정답(여기선 ②)"},{"n":42,"s":"s3","q":"OTP에 대한 설명으로 틀린 것은?","c":["의미있는 숫자로 구성된다.","비밀번호 재사용이 불가능하다.","비밀번호 유추가 불가능하다.","사전 공격(Dictionary Attack)에 안전하다."],"a":0,"e":"OTP는 시드와 시간·이벤트 값으로 생성된 무작위성 숫자로 의미가 없는 값이다. 한 번만 사용되고 매번 바뀌므로 재사용·유추가 불가능하고 사전 공격에도 안전하다.","ce":["OTP는 시드와 시간·이벤트 값으로 생성된 무작위 숫자로 의미 있는 값이 아니다. 의미 있는 숫자로 구성된다는 진술이 틀렸다.","OTP는 한 번 사용하면 폐기되고 매번 새로 생성되므로 재사용이 불가능하다.","OTP는 해시·암호 연산 결과라 이전 값으로 다음 값을 유추할 수 없다.","OTP는 사전 단어가 아닌 무작위 일회성 값이라 사전 공격이 통하지 않는다."],"rel":["4-8"]},{"n":43,"s":"s3","q":"웹 어플리케이션 취약성 조치방안에 대한 설명으로 틀린 것은?","c":["server side session 방식은 침해 가능성도 있고, 구조상 다양한 취약점에 노출될 수 있으므로 가볍고 안전한 client side의 cookie를 사용한다.","모든 인자에 대해 사용 전에 입력값 검증을 수행하도록 구성한다.","파일 다운로드시 위치는 지정된 데이터 저장소를 지정하여 사용하고 데이터 저장소 상위로 이동되지 않도록 구성한다.","SSL/TLS와 같은 기술을 이용하여 로그인 트랜잭션 전체를 암호화한다."],"a":0,"e":"클라이언트 측 쿠키는 사용자가 조작할 수 있어 세션 정보 저장에 취약하므로 서버 측 세션 방식을 사용하는 것이 권장된다. 입력값 검증, 다운로드 경로 제한(경로 조작 방지), 로그인 구간 SSL/TLS 암호화는 올바른 조치이다.","ce":["클라이언트 쿠키는 사용자가 조작·탈취할 수 있어 인증·세션 정보 저장에 취약하므로 서버 측 세션을 쓰는 것이 권장된다. 권장 방향이 반대로 서술되었다.","모든 인자에 대해 사용 전에 입력값을 검증하면 인젝션·XSS 등 다수 취약점을 예방하므로 올바른 조치이다.","다운로드 경로를 지정된 저장소로 제한하고 ../ 상위 이동을 막으면 경로 조작(Path Traversal)을 방지하므로 올바른 조치이다.","로그인 트랜잭션 전체를 SSL/TLS로 암호화하면 계정 정보 스니핑을 막으므로 올바른 조치이다."],"rel":["3-3"]},{"n":44,"s":"s3","q":"다음 문장에서 설명하는 FTP 공격은?","c":["FTP Bounce Attack","Anonymous FTP Attack","TFTP Attack","FTP Anyconnect Attack"],"a":0,"e":"FTP Bounce 공격은 PORT 명령으로 데이터 연결 목적지를 제3의 호스트로 지정해 FTP 서버를 경유한 포트 스캔이나 위조 메일 전송 등을 수행한다. Anonymous FTP 공격은 익명 계정의 쓰기 권한 등 설정 취약점을 악용한다.","ce":["FTP Bounce 공격은 PORT 명령으로 데이터 연결 목적지를 제3의 호스트로 지정해 FTP 서버를 경유한 포트 스캔·위조 메일 전송 등을 하는 공격으로 설명과 일치한다.","Anonymous FTP 공격은 익명 계정의 쓰기 권한·디렉터리 설정 취약점을 악용하는 공격으로, 전송 목적지 미검사와 다르다.","TFTP 공격은 인증 없는 TFTP로 설정 파일·passwd 등을 내려받는 공격이다.","FTP Anyconnect Attack은 존재하지 않는 공격 명칭이다."],"rel":["3-1"],"box":"- FTP서버가 데이터를 전송할 때 목적지가 어디인지 검사하지 않는 설계상의 문제점을 이용한 공격이다.\n- FTP서버의 전송 목적지 주소를 임의로 지정하여 FTP 서버를 경유해 임의의 목적지로 메시지나 자료를 전송하도록 할 수 있다."},{"n":45,"s":"s3","q":"웹 어플리케이션의 취약성을 악용하는 공격 방법 중 웹 페이지에 입력한 문자열이 perl의 system 함수나 PHP의 exec 함수 등에 건네지는 것을 이용해 부정하게 쉘 스크립트를 실행시키는 것은?","c":["HTTP header injection","OS command injection","CSRF(cross-site request forgery)","Session hijacking"],"a":1,"e":"OS 명령어 삽입(OS command injection)은 입력값이 system(), exec() 등 운영체제 명령 실행 함수로 전달되는 점을 악용해 임의 명령·셸 스크립트를 실행한다. HTTP 헤더 인젝션은 응답 헤더에 개행문자를 삽입하는 공격이다.","ce":["HTTP header injection은 입력값에 CR/LF를 넣어 응답 헤더를 조작(응답 분할)하는 공격으로, 셸 명령 실행이 아니다.","OS command injection은 입력값이 system()·exec() 등 OS 명령 실행 함수로 전달되는 점을 악용해 임의 명령·셸 스크립트를 실행하는 공격이다.","CSRF는 로그인된 사용자의 브라우저가 의도치 않은 요청을 서버에 보내도록 유도하는 공격이다.","Session hijacking은 세션 ID를 탈취해 정상 사용자로 가장하는 공격이다."],"rel":["3-6"]},{"n":46,"s":"s3","q":"다크웹(Dark Web)에 대한 설명으로 틀린 것은?","c":["공공인터넷을 사용하는 오버레이 네트워크(Overlay Network)이다.","딥웹(Deep web)은 다크웹의 일부분이다.","토르(TOR)같은 특수한 웹브라우저를 사용해야만 접근할 수 있다.","다크넷에 존해하는 웹사이트를 의미한다."],"a":1,"e":"딥웹은 검색엔진에 색인되지 않는 웹 전체이며, 다크웹은 딥웹 중 TOR 등 특수 소프트웨어로만 접근 가능한 일부분이다. 즉 다크웹이 딥웹의 일부이지 그 반대가 아니다.","ce":["다크웹은 공공 인터넷 위에 TOR 등으로 구성된 오버레이 네트워크(다크넷) 상의 웹이므로 옳은 설명이다.","포함 관계가 뒤바뀌었다. 딥웹은 검색엔진에 색인되지 않는 웹 전체이고, 다크웹이 그중 특수 소프트웨어로만 접근 가능한 일부이다.","다크웹은 TOR·I2P 같은 특수 브라우저·소프트웨어를 통해서만 접근할 수 있으므로 옳은 설명이다.","다크웹은 다크넷(익명 오버레이 네트워크)에 존재하는 웹사이트를 의미하므로 옳은 설명이다."]},{"n":47,"s":"s3","q":"다음 문장에서 설명하는 것은?","c":["SSL(Secure Socket Layter)","SET(Secure Electronic Transaction)","SOC(Security Operation Center)","Lattice Security Model"],"a":1,"e":"SET은 VISA·MasterCard가 개발한 전자상거래 지불 프로토콜로, 이중서명을 통해 카드번호를 상점이 아닌 지불 게이트웨이만 알게 하고 전자서명으로 부인방지를 제공한다. SSL은 전송 구간만 암호화하며 상점이 카드번호를 알 수 있다.","ce":["SSL은 전송 구간만 암호화할 뿐 상점이 카드번호를 볼 수 있고 전자서명에 의한 부인방지를 제공하지 않는다.","SET은 이중서명으로 카드번호를 상점이 아닌 지불 게이트웨이만 알게 하고 전자서명으로 부인방지를 제공하는 전자상거래 지불 프로토콜이다.","SOC(보안관제센터)는 보안 이벤트를 모니터링·대응하는 조직·시설로 지불 프로토콜이 아니다.","Lattice(격자) 보안 모델은 보안 등급의 격자 구조로 정보 흐름을 통제하는 접근통제 모델이다."],"rel":["3-10"],"box":"- 카드사용자, 상점, 지불-게이트웨이간에 안전한 채널을 제공한다.\n- 신용카드번호가 상점에는 알려지지 않고 지불-게이트웨이에 알려진다.\n- 상점에 의한 사기 가능성이 감소한다.\n- 서명 기능이 있어 부인방지 서비스를 제공한다."},{"n":48,"s":"s3","q":"DNS 캐시 포이즌닝으로 분류되는 공격은?","c":["DNS 서버의 소프트웨어 버전 정보를 얻어 DNS 서버의 보안 취약점을 판단한다.","PC가 참조하는 DNS 서버에 잘못된 도메인 관리 정보를 주입하여 위장된 웹서버로 PC 사용자를 유도한다.","공격 대상의 서비스를 방해하기 위해 공격자가 DNS 서버를 이용하여 재귀적인 쿼리를 대량으로 발생시킨다.","내부 정보를 얻기 위해 DNS 서버에 저장된 영역 정보를 함께 전송한다."],"a":1,"e":"DNS 캐시 포이즈닝은 DNS 서버 캐시에 위조된 도메인-IP 정보를 주입하여 사용자를 위장 사이트로 유도한다. ①은 정보 수집(버전 확인), ③은 DNS 증폭 DDoS, ④는 영역 전송(Zone Transfer)을 이용한 정보 유출이다.","ce":["DNS 서버의 버전 정보를 얻어 취약점을 판단하는 것은 정보 수집(footprinting) 단계로 캐시를 오염시키지 않는다.","PC가 참조하는 DNS 서버 캐시에 위조된 도메인-IP 정보를 주입해 사용자를 위장 웹서버로 유도하는 것이 DNS 캐시 포이즈닝이다.","DNS 서버를 이용해 대량의 재귀 질의를 발생시켜 대상을 방해하는 것은 DNS 증폭(반사) DDoS 공격이다.","영역 정보를 통째로 전송받아 내부 정보를 얻는 것은 영역 전송(Zone Transfer) 악용 정보 유출이다."],"rel":["3-7"]},{"n":49,"s":"s3","q":"DDos 공격 형태 중 자원 소진 공격이 아닌 것은?","c":["ICMP Flooding","SYN Flooding","ACK Flooding","DNS Query Flooding"],"a":0,"e":"ICMP Flooding은 대량의 ICMP 패킷으로 네트워크 회선 대역폭을 고갈시키는 대역폭 소진 공격이다. SYN·ACK Flooding과 DNS Query Flooding은 서버·장비의 세션 테이블, CPU 등 시스템 자원을 소진시키는 공격으로 분류된다.","ce":["ICMP Flooding은 대량 ICMP 패킷으로 네트워크 회선 대역폭을 고갈시키는 대역폭 소진 공격이다.","SYN Flooding은 서버의 연결 대기 큐(백로그)를 고갈시키는 자원 소진 공격이다.","ACK Flooding은 대량 ACK로 서버·방화벽의 세션 테이블 조회 부하를 유발하는 자원 소진 공격이다.","DNS Query Flooding은 대량 질의로 DNS 서버의 CPU 등 처리 자원을 소진시키는 공격이다."],"rel":["2-3"]},{"n":50,"s":"s3","q":"다음 표의 소극적·적극적 암호공격 방식의 구분이 옳은 것은?","c":["①","②","③","④"],"a":0,"e":"소극적(수동적) 공격은 도청·트래픽 분석처럼 데이터를 변경하지 않는 공격이고, 적극적(능동적) 공격은 삽입·삭제·재생·메시지 변조·서비스 거부처럼 데이터를 변경하거나 흐름에 개입한다. 재생공격과 메시지 변조는 적극적 공격이므로 ②~④는 틀리다.","ce":["트래픽 분석은 데이터를 변경하지 않는 소극적 공격, 삽입공격은 메시지를 끼워 넣는 적극적 공격으로 구분이 옳다.","재생공격은 캡처한 메시지를 다시 보내 흐름에 개입하는 적극적 공격이므로 소극적 공격 칸에 올 수 없다.","메시지 변조는 데이터를 바꾸는 적극적 공격이므로 소극적 공격 칸에 올 수 없다.","메시지 변조는 적극적 공격이므로 소극적 공격 칸에 올 수 없다(삽입공격은 적극적 공격으로 맞음)."],"rel":["4-1"],"box":"구분 | 소극적 공격 | 적극적 공격\n① | 트래픽 분석 | 삽입공격\n② | 재생공격 | 삭제공격\n③ | 메시지 변조 | 재생공격\n④ | 메시지 변조 | 삽입공격"},{"n":51,"s":"s3","q":"다음 문장의 괄호 안에 알맞은 용어는?","c":["워터링 홀","스팸","스피어피싱","랜섬웨어"],"a":3,"e":"랜섬웨어는 데이터를 암호화해 접근을 제한하고 몸값을 요구하는 악성코드로, 최근에는 데이터 유출 후 공개 협박을 더하는 이중 갈취 방식으로 진화했다. 워터링 홀은 표적이 자주 방문하는 사이트를 감염시키는 공격이다.","ce":["워터링 홀은 표적 집단이 자주 방문하는 웹사이트를 감염시켜 방문자에게 악성코드를 유포하는 공격으로, 데이터 암호화 후 몸값 요구가 아니다.","스팸은 수신자가 원치 않는 광고성 대량 메일·메시지로, 시스템 접근을 제한하고 몸값을 요구하지 않는다.","스피어피싱은 특정 대상을 겨냥해 맞춤형 메일로 악성 첨부·링크를 열게 하는 표적형 피싱으로, 랜섬웨어의 유포 수단일 수는 있으나 몸값 요구 악성코드 자체가 아니다.","랜섬웨어는 데이터를 암호화해 접근을 제한하고 몸값을 요구하는 악성코드로, 최근 데이터 유출 후 공개 협박을 더하는 이중 갈취로 진화했다."],"rel":["1-9"],"box":"과거 (   )공격은 불특성 다수를 대상으로 데이터를 암호화하고 이에 대한 몸값을 요구하는 방식이 대부분이었다. 그러나 최근에는 높은 금액을 지불할 수 있는 대규모 엔터프라이즈 환경이 주로 공격 대상이 되고 있고 암호화 뿐만 아니라 데이터 유출 후 인터넷 공개를 미끼로 협박하는 형태의 공격 방식으로 진화되고 있다. 컴퓨터 시스템을 감염시켜 접근을 제한하고 일종의 몸값을 요구하는 악성 소프트웨어의 한 종류이다."},{"n":52,"s":"s3","q":"MS SQL 서버의 인증 모드에 대한 설명 중 성격이 다른 하나는?","c":["SQL Server 기본 인증 모드이다.","데이터베이스 관리자가 사용자에게 접근 권한 부여가 가능하다.","윈도우즈 인증 로그온은 추적시 SID 값을 사용한다.","트러스트되지 않은 연결(SQL 연결)을 사용한다."],"a":3,"e":"①~③은 SQL Server의 기본 인증 모드인 Windows 인증 모드에 대한 설명으로, 윈도우 계정과 SID로 로그온을 추적한다. ④의 트러스트되지 않은 연결(SQL 연결)은 SQL Server 자체 계정을 쓰는 SQL Server 인증(혼합 모드)에 해당한다.","ce":["SQL Server 설치 시 기본 인증 모드는 Windows 인증 모드이므로 Windows 인증에 대한 설명이다.","Windows 인증 모드에서 DB 관리자가 윈도우 사용자·그룹에 접근 권한을 부여하므로 Windows 인증에 대한 설명이다.","Windows 인증 로그온은 윈도우 계정의 SID로 식별·추적하므로 Windows 인증에 대한 설명이다.","트러스트되지 않은 연결(SQL 연결)은 SQL Server 자체 계정(ID/PW)을 쓰는 SQL Server 인증(혼합 모드)의 특징으로, 나머지(Windows 인증)와 성격이 다르다."],"rel":["3-8"]},{"n":53,"s":"s3","q":"다음 문장에서 설명하는 보안솔루션은?","c":["DRM","SSO","OTP","APT"],"a":1,"e":"SSO(Single Sign-On)는 한 번의 인증으로 여러 시스템에 접근할 수 있게 하는 통합 인증 솔루션이다. DRM은 디지털 콘텐츠 저작권 보호, OTP는 일회용 비밀번호, APT는 지능형 지속 위협이다.","ce":["DRM은 디지털 콘텐츠·문서를 암호화해 사용 권한을 통제하는 저작권·정보 보호 솔루션으로, 통합 로그인 기능이 아니다.","SSO(Single Sign-On)는 한 번 인증으로 여러 시스템에 접근하게 하는 통합 인증 솔루션으로, 계정 관리 위험 감소·편의 증진·관리비 절감 효과가 있다.","OTP는 매번 바뀌는 일회용 비밀번호를 생성하는 인증 수단으로, 여러 시스템의 인증을 통합하지 않는다.","APT는 지능형 지속 위협(Advanced Persistent Threat)이라는 공격 유형으로 보안솔루션이 아니다."],"rel":["4-9"],"box":"- 한번의 로그인만으로 기업의 각종 시스템이나 인터넷 서비스에 접속하게 해주는 보안 응용 솔루션이다.\n- 각각의 시스템마다 인증 절차를 밟지 않고도 1개의 계정만으로 다양한 시스템에 접근할 수 있어 ID, 비밀번호에 대한 보안 위험 예방과 사용자 편의 증진, 인증 관리비용의 절감 효과가 있다."},{"n":54,"s":"s3","q":"데이터베이스 보안 방법으로 틀린 것은?","c":["데이터베이스 서버를 백업하며 관리한다.","Guest 계정을 사용하여 관리한다.","데이터베이스 쿼리만 웹 서버와 데이터베이스 서버 사이에 통과할 수 있도록 방화벽을 설치한다.","데이터베이스 관리자만 로그인 권한을 부여한다."],"a":1,"e":"Guest 계정은 누구나 접근할 수 있는 공용 계정으로 책임추적이 불가능하고 비인가 접근 위험이 있어 비활성화해야 한다. 정기 백업, 웹-DB 간 필요한 쿼리만 허용하는 방화벽, 관리자 로그인 권한 제한은 올바른 보안 방법이다.","ce":["DB 서버를 정기 백업하면 장애·랜섬웨어 등으로부터 데이터를 복구할 수 있어 올바른 보안 방법이다.","Guest 계정은 누구나 쓰는 공용 계정이라 책임추적이 불가능하고 비인가 접근 위험이 있어 비활성화해야 한다. Guest로 관리한다는 것은 틀린 방법이다.","웹서버와 DB 서버 사이에 방화벽을 두고 필요한 DB 쿼리 포트만 통과시키면 DB 직접 공격을 막을 수 있어 올바른 방법이다.","로그인 권한을 DB 관리자로 한정하면 비인가 접근을 줄이는 최소 권한 원칙에 부합해 올바른 방법이다."],"rel":["3-8"]},{"n":55,"s":"s3","q":"다음 문장에서 설명하는 웹 공격의 명칭은?","c":["XSS(Cross Site Scripting)","SQL(Structured Query Language) Ingection","CSRF(Cross-site request forgery)","쿠키(Cookie) 획득"],"a":0,"e":"XSS는 웹 페이지에 삽입된 악성 스크립트가 사용자 브라우저에서 실행되어 쿠키 탈취·피싱 유도 등을 수행하는 공격이다. CSRF는 스크립트 실행이 아니라 로그인된 사용자의 브라우저가 의도하지 않은 요청을 서버에 보내게 해 서버에서 원치 않는 기능이 수행되게 하는 공격이다.","ce":["XSS는 웹 페이지에 삽입된 악성 스크립트가 사용자 브라우저에서 실행되어 쿠키 탈취 등을 수행하는 공격으로 설명과 일치한다.","SQL Injection은 입력값으로 SQL 쿼리를 조작해 DB 서버에서 실행시키는 공격으로, 스크립트가 사용자 브라우저에서 실행되지 않는다.","CSRF는 로그인된 사용자의 브라우저가 의도하지 않은 요청을 서버로 보내게 해 서버 측 기능을 수행시키는 공격으로, 공격 결과가 서버에서 발생한다.","쿠키 획득은 XSS 등의 결과로 얻는 공격 목표일 뿐, 스크립트가 브라우저에서 실행되는 공격 기법의 명칭이 아니다."],"rel":["3-6"],"box":"브라우저로 전달되는 데이터에 포함된 악성 스크립트가 개인의 브라우저에서 실행되어 공격이 진행되는 웹 해킹의 일종이다."},{"n":56,"s":"s3","q":"버퍼오버플로우에 대한 보안 대책이 아닌 것은?","c":["운영체제 커널 패치","경계 검사를 하는 컴파일러 및 링크 사용","스택내의 코드 실행 금지","포맷 스트링 검사"],"a":3,"e":"포맷 스트링 검사는 포맷 스트링 취약점 대책이다. 버퍼 오버플로 대책으로는 커널 패치, 경계 검사 컴파일러(Stack Guard 등), 스택 실행 금지(NX/DEP), ASLR, 안전한 함수 사용 등이 있다.","ce":["운영체제 커널 패치(스택 실행 방지, ASLR 적용 등)는 버퍼 오버플로 공격을 어렵게 하는 대책이다.","경계 검사를 수행하는 컴파일러·링커(StackGuard 카나리, -fstack-protector 등)는 버퍼 경계 초과를 탐지하는 대책이다.","스택 내 코드 실행 금지(NX/DEP)는 스택에 주입된 셸코드 실행을 막는 대표적인 대책이다.","포맷 스트링 검사는 printf 계열 서식 문자열 취약점에 대한 대책으로, 버퍼 경계 초과 자체를 막는 대책이 아니다."],"rel":["1-10"]},{"n":57,"s":"s3","q":"SSO(Single Sign On)와 관련이 없는 것은?","c":["Delegation 검사","Propagation 방식","웹 기반 쿠키 도메인 SSO","보안토큰"],"a":3,"e":"SSO 구현 방식에는 인증 대행(Delegation) 방식, 인증정보 전달(Propagation) 방식, 웹 기반 쿠키 도메인 SSO 등이 있다. 보안토큰은 인증서·키를 저장하는 하드웨어 인증 매체로 SSO 구현 방식이 아니다.","ce":["Delegation(인증 대행) 방식은 SSO 에이전트가 사용자 대신 각 시스템에 저장된 인증정보로 로그인하는 SSO 구현 방식이다.","Propagation(인증정보 전달) 방식은 통합 인증 후 발급한 토큰을 각 시스템에 전달해 인증하는 SSO 구현 방식이다.","웹 기반 쿠키 도메인 SSO는 같은 도메인의 인증 쿠키를 공유해 여러 웹 서비스에 로그인하는 SSO 방식이다.","보안토큰은 인증서·개인키를 안전하게 저장·연산하는 하드웨어 인증 매체로, SSO 구현 방식이 아니다."],"rel":["4-9"]},{"n":58,"s":"s3","q":"S/MIME의 주요 기능이 아닌 것은?","c":["봉인된 데이터(Enveloped data)","서명 데이터(Signed data)","순수한 데이터(Clear-signed data)","비순수 서명과 봉인된 데이터(Unclear Signed and Enveloped data)"],"a":3,"e":"S/MIME의 기능은 봉인된 데이터(Enveloped), 서명 데이터(Signed), 순수 서명 데이터(Clear-signed), 서명·봉인 데이터(Signed and Enveloped) 네 가지이다. '비순수 서명과 봉인된 데이터'라는 기능은 없다.","ce":["봉인된 데이터(Enveloped data)는 콘텐츠를 암호화하고 암호화 키를 수신자 공개키로 감싸는 S/MIME 기능이다.","서명 데이터(Signed data)는 콘텐츠와 서명을 함께 base64로 인코딩해 S/MIME 지원 수신자만 볼 수 있게 하는 기능이다.","순수 서명 데이터(Clear-signed data)는 본문은 평문으로 두고 서명만 base64로 붙여 비지원 수신자도 내용을 볼 수 있게 하는 기능이다.","S/MIME 기능은 Enveloped, Signed, Clear-signed, Signed and Enveloped 네 가지이며 '비순수 서명과 봉인된 데이터'는 존재하지 않는다."],"rel":["3-2"]},{"n":59,"s":"s3","q":"DNS(Domain Name System)에 대한 설명으로 틀린 것은?","c":["DNS 서비스는 클라이언트에 해당하는 리졸버(resolver)와 서버에 해당하는 네임서버(name server)로 구성되며, DNS 서비스에 해당되는 포트 번호는 53번이다.","주(primary) 네임서버와 보조(secondary) 네임서버는 DNS 서비스 제공에 필요한 정보가 포함된 존(zone) 파일을 기초로 리졸버로부터의 요청을 처리한다.","ISP 등이 운영하는 캐시 네임서버가 관리하는 DNS 캐시에 IP 주소, UDP 포트번호, DNS 메시지 ID값이 조작된 정보를 추가함으로써 DNS 캐시 포이즈닝(poisoning) 공격이 가능하다.","DNSSEC 보안 프로토콜은 초기 DNS 서비스가 보안 기능이 포함되지 않았던 문제점을 해결하기 위해 개발되었으며, DNS 데이터의 비밀성, 무결성, 출처 인증 등의 기능을 제공한다."],"a":3,"e":"DNSSEC은 전자서명으로 DNS 응답의 무결성과 출처 인증을 제공하지만 데이터를 암호화하지 않으므로 비밀성(기밀성)은 제공하지 않는다. DNS 기밀성은 DoT·DoH 같은 별도 기술이 담당한다.","ce":["DNS는 클라이언트인 리졸버와 서버인 네임서버로 구성되고 UDP/TCP 53번 포트를 사용하므로 옳은 설명이다.","주·보조 네임서버는 존 파일(영역 데이터)을 바탕으로 해당 도메인 질의에 권한 있는 응답을 하므로 옳은 설명이다.","캐시 네임서버에 조작된 응답(포트번호·트랜잭션 ID를 맞춘 위조 응답)을 먼저 넣어 캐시를 오염시키는 것이 DNS 캐시 포이즈닝이므로 옳은 설명이다.","DNSSEC은 전자서명으로 무결성과 출처 인증을 제공하지만 데이터를 암호화하지 않아 비밀성(기밀성)은 제공하지 않는다."],"rel":["3-7"]},{"n":60,"s":"s3","q":"다음 문장에서 설명하는 전자서명 기법은?","c":["다중서명","그룹서명","은닉서명","검증자 지정서명"],"a":2,"e":"은닉서명(Blind Signature)은 서명자가 메시지 내용을 모른 채 서명하게 하는 기법으로, 전자화폐의 익명성(사용자 추적 불가)을 보장한다. 그룹서명은 그룹 구성원 중 한 명이 그룹을 대표해 서명하는 기법이다.","ce":["다중서명은 여러 서명자가 하나의 문서에 함께 서명하는 기법으로, 서명자가 내용을 모르게 하는 기능이 없다.","그룹서명은 그룹 구성원 중 한 명이 그룹을 대표해 익명으로 서명하는 기법으로, 서명자는 문서 내용을 본다.","은닉서명(Blind Signature)은 서명자가 메시지 내용을 모른 채 서명하게 하는 기법으로, e-cash에서 사용자 추적 불가(익명성)를 보장한다.","검증자 지정서명은 서명자가 지정한 검증자만 서명을 검증할 수 있게 하는 기법이다."],"rel":["3-13","4-6"],"box":"전자화폐의 일종인 e-cash는 익명성을 제공하기 위해 서명자가 문서의 내용을 보지 않은 상태에서 전자서명을 생성하는 기법을 사용한다."},{"n":61,"s":"s4","q":"다음은 특정 블록 암호 운영 모드의 암호화 과정이다. 해당하는 모드는?","c":["ECB 모드(Electronic Code Book Mode)","CBC 모드(Cipher Block Chaining Mode)","CFB 모드(Cipher Feedback Mode)","OFB 모드(Output Feedback Mode)"],"a":2,"e":"CFB 모드는 IV 또는 이전 암호문 블록을 암호화한 출력과 평문을 XOR하여 암호문을 만들고, 그 암호문을 다음 블록의 암호화 입력으로 되돌린다. OFB는 암호문이 아닌 암호화 출력 자체를 다음 입력으로 쓰고, CBC는 평문과 이전 암호문을 XOR한 뒤 암호화한다.","ce":["ECB는 각 평문 블록을 독립적으로 키로 암호화하며, IV나 이전 암호문을 되먹임하지 않는다.","CBC는 평문 블록을 이전 암호문(또는 IV)과 XOR한 뒤 암호화한다. 그림은 먼저 암호화한 출력과 평문을 XOR하므로 순서가 다르다.","CFB는 IV 또는 이전 암호문 블록을 암호화한 출력과 평문을 XOR해 암호문을 만들고, 그 암호문을 다음 입력으로 되먹임하므로 그림과 일치한다.","OFB는 암호문이 아니라 암호화 출력 자체를 다음 블록의 입력으로 되먹임한다. 그림은 암호문 블록이 다음 입력이므로 OFB가 아니다."],"rel":["4-3"],"box":"(그림) 초기화 벡터(IV) → 암호화(KEY) → 출력 ⊕ 평문 블록 1 → 암호문 블록 1\n암호문 블록 1 → 암호화(KEY) → 출력 ⊕ 평문 블록 2 → 암호문 블록 2\n암호문 블록 2 → 암호화(KEY) → 출력 ⊕ 평문 블록 3 → 암호문 블록 3","fig":"past/2022-06-25-q61.png"},{"n":62,"s":"s4","q":"접근통제 모델에 대한 각각의 설명 중 옳은 것은?","c":["비바(Biba) 모델 : 임의적 접근통제(DAC: Doscretionary Access Control)를 기반으로 하는 상태 머신 모델이다.","벨-라파듈라(Bell-Lapadula) 모델 : 객체에 대한 무결성 또는 가용성을 유지하는데 중점을 두고 있으며, 기밀성의 측면에는 대처하지 않는다.","비바(Biba) 모델 : 비밀 채널을 방지하며, 내부 및 외부 객체 일관성을 보호한다.","클락-윌슨(Clark-Wilson) 모델 : 허가 받은 사용자가 허가 받지 않고 데이터를 수정하는 것을 방지한다."],"a":3,"e":"클락-윌슨 모델은 잘 형성된 트랜잭션과 직무 분리로 허가받은 사용자의 부적절한 데이터 수정까지 막는 무결성 모델이다. 비바 모델은 강제적 접근통제(MAC) 기반의 무결성 모델이고, 벨-라파듈라 모델은 기밀성에 중점을 둔다.","ce":["비바 모델은 임의적 접근통제(DAC)가 아닌 강제적 접근통제(MAC)의 무결성 등급을 기반으로 한 상태 머신 모델이다.","벨-라파듈라 모델은 기밀성 유지에 중점을 둔 모델(No Read Up, No Write Down)로, 설명이 무결성 모델과 뒤바뀌었다.","비밀 채널 방지와 내부·외부 일관성 보호는 비바가 아닌 클락-윌슨 모델의 특징으로 거론된다. 비바는 비인가자의 수정 방지에 초점을 둔다.","클락-윌슨 모델은 잘 형성된 트랜잭션과 직무 분리로 허가받은 사용자의 부적절한 데이터 수정까지 막는 무결성 모델이다."],"rel":["4-11"]},{"n":63,"s":"s4","q":"해시함수의 분류 중 MDC(Modification Detection Cryptography)에 포함되지 않는 알고리즘은?","c":["MD(Message Digest)","SHA(Secure Hash Algorithm)","LSH(Lightweight Secure Hash)","H-MAC(Hash-MAC)"],"a":3,"e":"해시함수는 키 없는 변경 탐지 코드(MDC)와 키를 사용하는 메시지 인증 코드(MAC)로 나뉜다. MD5·SHA·LSH는 MDC이고, HMAC은 비밀키를 사용하는 MAC에 해당한다.","ce":["MD 계열(MD5 등)은 키 없이 메시지 변경을 탐지하는 MDC(변경 탐지 코드) 해시함수이다.","SHA 계열은 키 없이 사용하는 MDC 해시함수이다.","LSH는 국산 경량 해시함수로 키를 사용하지 않는 MDC에 속한다.","HMAC은 해시함수에 비밀키를 결합한 메시지 인증 코드(MAC)로, 키를 쓰지 않는 MDC에 포함되지 않는다."],"rel":["4-5"]},{"n":64,"s":"s4","q":"실시간으로 인증서 유효성을 검증하는 OCSP(Online Certificate Status Protocol)의 서비스가 아닌 것은?","c":["ORS : 온라인 취소상태 확인서비스","DPD : 대리인증 경로 발전 서비스","CRL : 인증서 폐지 목록 확인서비스","DPV : 대리인증 경로 검증 서비스"],"a":2,"e":"OCSP 서비스에는 ORS(온라인 취소 상태 확인), DPD(대리 인증 경로 발견), DPV(대리 인증 경로 검증)가 있다. CRL은 주기적으로 발행되는 폐지 목록을 내려받아 확인하는 방식으로, OCSP가 보완하려는 대상이다.","ce":["ORS는 OCSP의 온라인 인증서 취소 상태 확인 서비스이다.","DPD(Delegated Path Discovery)는 클라이언트 대신 인증 경로를 찾아주는 OCSP 서비스이다(보기의 '발전'은 '발견' 오기).","CRL은 CA가 주기적으로 발행하는 폐지 목록을 내려받아 확인하는 방식으로, OCSP가 실시간 조회로 보완하려는 대상이지 OCSP 서비스가 아니다.","DPV(Delegated Path Validation)는 클라이언트 대신 인증 경로를 검증해주는 OCSP 서비스이다."],"rel":["4-7"]},{"n":65,"s":"s4","q":"접근통제정책 구성요소에 대한 설명으로 틀린 것은?","c":["사용자 : 시스템을 사용하는 주체이다.","자원 : 사용자가 사용하는 객체이다.","행위 : 객체가 행하는 논리적 접근통제이다.","관계 : 사용자에게 승인된 허가(읽기, 쓰기, 실행)이다."],"a":2,"e":"행위는 주체(사용자)가 객체(자원)에 대해 수행하는 작업(읽기·쓰기·실행 등)이다. 객체는 행위의 대상일 뿐 행위를 하는 주체가 아니므로 ③이 틀리다.","ce":["사용자는 시스템 자원을 사용하는 주체(Subject)이므로 옳은 설명이다.","자원은 사용자가 접근·사용하는 객체(Object)이므로 옳은 설명이다.","행위는 주체(사용자)가 객체(자원)에 수행하는 작업이며, 객체가 행하는 것이 아니다. 행위의 주어가 틀렸다.","관계는 사용자에게 승인된 허가(읽기·쓰기·실행 등 접근 모드)로 정의되므로 옳은 설명이다."],"rel":["4-10"]},{"n":66,"s":"s4","q":"다음 중 전자서명인증업무지침에 따라 공인인증기관이 지켜야 할 구체적인 사항이 아닌 것은?","c":["공인인증서의 관리에 관한 사항","전자서명생성정보의 관리에 관한 사항","공인인증기관 시설의 보호에 관한 사항","공인인증기관 지정 절차에 관한 사항"],"a":3,"e":"(구)전자서명인증업무지침은 공인인증기관의 인증서 관리, 전자서명생성정보(개인키) 관리, 시설 보호 등 업무 수행 시 준수 사항을 정한다. 공인인증기관 지정 절차는 전자서명법 및 시행령에서 정하는 사항이다. 2020년 전자서명법 전부개정으로 공인인증제도가 폐지되었다(개정 여부 확인).","ce":["공인인증서 발급·갱신·폐지 등 인증서 관리는 전자서명인증업무지침의 준수 사항이다.","가입자·인증기관의 전자서명생성정보(개인키) 관리는 지침의 준수 사항이다.","인증시스템이 설치된 시설의 출입통제·보호는 지침의 준수 사항이다.","공인인증기관 지정 절차는 인증기관이 지킬 업무 준수 사항이 아니라 (구)전자서명법·시행령이 정하는 지정 요건·절차이다(2020년 개정으로 공인인증제 폐지, 개정 여부 확인)."],"rel":["4-7"]},{"n":67,"s":"s4","q":"IAM(Identity Access Management)에 대한 설명으로 틀린 것은?","c":["전사적 계정관리, 권한관리의 구현에 필요한 모든 요소들을 일반적으로 IAM이라고 부른다.","IAM은 계정관리를 담당하는 IM분야와 권한통제를 담당하는 AM으로 나뉘진다.","사용자가 시스템을 사용하기 위해 로그인 ID를 발급하는 과정을 프로비저닝이라고 한다.","사용자가 시스템에 로그인할 때 본인임을 증명하는 과정을 인가(Authorization)라고 한다."],"a":3,"e":"로그인 시 본인임을 증명하는 과정은 인증(Authentication)이며, 인가(Authorization)는 인증된 사용자에게 자원 접근 권한을 부여하는 과정이다. IAM은 계정관리(IM)와 접근관리(AM)로 구성된다.","ce":["IAM은 전사적 계정관리·권한관리 구현에 필요한 정책·프로세스·솔루션 전체를 가리키므로 옳은 설명이다.","IAM은 계정(Identity) 관리를 담당하는 IM과 접근(Access) 권한 통제를 담당하는 AM으로 나뉘므로 옳은 설명이다.","사용자에게 계정과 권한을 발급·생성하는 과정을 프로비저닝이라 하므로 옳은 설명이다.","로그인 시 본인임을 증명하는 과정은 인증(Authentication)이다. 인가(Authorization)는 인증된 사용자에게 자원 접근 권한을 부여하는 과정이다."],"rel":["4-9","4-10"]},{"n":68,"s":"s4","q":"전자서명을 적용한 예에 해당되지 않는 것은?","c":["Code Signing","X.509 Certificate","SSL/TLS Protocol","Kerberos Protocol"],"a":3,"e":"Kerberos는 KDC가 발급하는 대칭키 기반 티켓으로 인증하는 프로토콜로 전자서명을 사용하지 않는다. 코드 서명, X.509 인증서(CA 서명), SSL/TLS(인증서 검증·핸드셰이크 서명)는 전자서명을 적용한 예이다.","ce":["코드 서명은 개발자 개인키로 프로그램 해시에 서명해 출처와 무결성을 보장하는 전자서명 적용 예이다.","X.509 인증서는 CA가 개인키로 서명해 공개키와 소유자 정보를 결합하는 전자서명 적용 예이다.","SSL/TLS는 서버 인증서 검증과 핸드셰이크 메시지 서명에 전자서명을 사용한다.","Kerberos는 KDC가 발급한 대칭키 기반 티켓으로 인증하는 프로토콜로 전자서명을 사용하지 않는다."],"rel":["4-6"]},{"n":69,"s":"s4","q":"다음 문장과 같이 처리되는 프로토콜은?","c":["Diffie-Hellman","Needhan-Schroeder","Otway-Rees","Kerberos"],"a":1,"e":"KDC에 비표와 두 ID를 보내 세션키와 B용 티켓을 받고, B가 세션키로 암호화한 시도(R_B)에 A가 R_B-1로 응답하는 절차는 Needham-Schroeder 프로토콜이다. Otway-Rees는 B가 KDC와 통신하는 구조이고, Kerberos는 AS·TGS와 타임스탬프를 사용한다.","ce":["Diffie-Hellman은 KDC 없이 두 당사자가 공개값을 교환해 공유 비밀키를 계산하는 키 교환 방식이다.","A가 비표와 두 ID를 KDC에 보내 세션키와 B용 티켓을 받고, B의 시도 R_B에 R_B-1로 응답하는 절차는 Needham-Schroeder 프로토콜이다.","Otway-Rees는 A가 B에게 먼저 메시지를 보내고 B가 KDC와 통신하는 구조로, A가 직접 KDC에 요청하는 순서와 다르다.","Kerberos는 AS에서 TGT, TGS에서 서비스 티켓을 받는 2단계 구조이고 비표 대신 타임스탬프를 사용한다."],"rel":["4-12"],"box":"㉠ A는 자신의 비표인 R_A, 자신의 ID, B의 ID가 포함된 메시지를 KDC에게 전송한다.\n㉡ KDC는 암호화된 메시지를 A에게 전송한다. 이 안에는 A의 비표, B의 ID, A와 B의 세션키 및 B에게 줄 암호화된 티켓이 포함되어 있다. 전체 메시지는 A의 키로 암호화되어 있다.\n㉢ A는 B의 티켓을 B에게 보낸다.\n㉣ B는 자신의 시도인 R_B를 A와 B의 세션키로 암호화 된 뒤에 A에게 보낸다.\n㉤ A는 B의 시도에 대한 응답으로 R_B-1을 A와 B의 세션키로 암호화한 뒤에 B에게 보낸다."},{"n":70,"s":"s4","q":"송신자 A와 수신자 B가 RSA를 이용하여 키를 공유하는 방법에 대한 설명으로 틀린 것은?","c":["미국 MIT의 Rivest, Shamir, Adelman이 발표한 공개키 암호화 방식으로 이해와 구현이 쉽고, 검증이 오랫동안 되어서 가장 널리 쓰이고 있다.","A가 암호화 되지 않은 평문으로 A의 공개키를 B에게 전송한다.","B는 공유 비밀키를 생성, A에게서 받은 A의 공개키로 암호화 전송한다.","A는 자신의 공개키로 공유 비밀키를 추출하고 데이터를 암호화 전송한다."],"a":3,"e":"B가 A의 공개키로 암호화해 보낸 공유 비밀키는 A가 자신의 개인키로 복호화해 추출해야 한다. 공개키로 암호화한 것은 짝이 되는 개인키로만 복호화할 수 있다.","ce":["RSA는 MIT의 Rivest·Shamir·Adleman이 1977년 발표한 공개키 방식으로, 구현이 쉽고 오래 검증되어 널리 쓰이므로 옳은 설명이다.","공개키는 공개되어도 되는 값이므로 A가 자신의 공개키를 평문으로 B에게 보내는 것은 옳은 절차이다(진위 보장에는 인증서 사용).","B가 공유 비밀키를 생성해 A의 공개키로 암호화해 보내면 A만 복호화할 수 있으므로 옳은 절차이다.","A의 공개키로 암호화된 공유 비밀키는 A의 공개키가 아닌 A의 개인키로 복호화해 추출해야 한다."],"rel":["4-4"]},{"n":71,"s":"s4","q":"암호문에 대응하는 일부 평문이 가용한 상황에서의 암호 공격 방법은?","c":["암호문 단독 공격","알려진 평문 공격","선택 평문 공격","선택 암호문 공격"],"a":1,"e":"알려진 평문 공격은 공격자가 일부 평문-암호문 쌍을 알고 있는 상황에서 키나 나머지 평문을 찾는 공격이다. 선택 평문 공격은 공격자가 원하는 평문을 골라 암호문을 얻을 수 있는 상황이다.","ce":["암호문 단독 공격은 공격자가 암호문만 가진 상태에서 평문이나 키를 알아내는 공격으로, 평문 정보가 없다.","알려진 평문 공격은 일부 평문-암호문 쌍을 알고 있는 상황에서 키나 나머지 평문을 찾는 공격으로 설명과 일치한다.","선택 평문 공격은 공격자가 원하는 평문을 골라 암호화 결과를 얻을 수 있는 상황으로, 단순히 일부 평문이 가용한 것보다 강한 조건이다.","선택 암호문 공격은 공격자가 원하는 암호문을 골라 복호화 결과를 얻을 수 있는 상황이다."],"rel":["4-1"]},{"n":72,"s":"s4","q":"합성수 n을 사용하는 RSA 전자서명 환경에서 메시지 M에 대해 난수 r에 공개 검증키 e를 가지고 reM mod n값을 서명자에게 전송하는 전자서명 기법은 무엇인가?","c":["은닉서명","위임서명","부인방지 서명","이중서명"],"a":0,"e":"RSA 은닉서명에서는 사용자가 r^e·M mod n으로 메시지를 가려(blinding) 서명자에게 보내고, 받은 서명에 r의 역원을 곱해 원래 M에 대한 서명을 얻는다. 서명자는 M의 내용을 알 수 없다.","ce":["은닉서명은 사용자가 r^e·M mod n으로 메시지를 가려 서명자에게 보내고, 받은 서명에 r^-1을 곱해 M의 서명을 얻는 기법으로 설명과 일치한다.","위임서명은 원서명자가 대리인에게 서명 권한을 위임해 대신 서명하게 하는 기법으로, 난수 r로 메시지를 가리지 않는다.","부인방지 서명은 서명자의 협조가 있어야 검증할 수 있게 한 서명 기법으로, 메시지 은닉과 다르다.","이중서명은 SET에서 주문정보와 지불정보의 해시를 결합해 서명하는 기법이다."],"rel":["4-6"]},{"n":73,"s":"s4","q":"다음 문장에서 설명하는 위험분석 방법론을 옳게 연결한 것은?","c":["㉠ : 확률 분포법, ㉡ : 순위결정법","㉠ : 시나리오법, ㉡ : 델파이법","㉠ : 델파이법, ㉡ : 확률 분포법","㉠ : 시나리오법, ㉡ : 순위결정법"],"a":3,"e":"㉠은 시나리오법, ㉡은 위협을 상호 비교해 우선순위를 도출하는 순위결정법으로 모두 정성적 분석 기법이다. 델파이법은 전문가 의견을 반복 수렴하는 방법이며, 확률 분포법은 통계적 분포로 위험을 추정하는 정량적 기법이다.","ce":["㉡ 순위결정법은 맞지만 ㉠은 확률 분포법이 아니라 시나리오법이다. 확률 분포법은 통계적 분포로 위험을 추정하는 정량적 기법이다.","㉠ 시나리오법은 맞지만 ㉡ 델파이법은 전문가 의견을 반복 수렴하는 방법으로, 위협을 상호 비교해 순위를 매기는 방법이 아니다.","㉠ 델파이법, ㉡ 확률 분포법 모두 설명과 맞지 않는다.","㉠ 기대대로 발생하지 않는다는 가정 아래 결과를 추정하는 시나리오법, ㉡ 위협을 상호 비교해 우선순위를 도출하는 순위결정법으로 올바르다."],"rel":["5-2"],"box":"㉠ 어떤 사건도 기대대로 발생하지 않는다는 사실에 근거하여 일정 조건하에서 위협에 대해 발생 가능한 결과들을 추정하는 방법\n㉡ 각각의 위협을 상호 비교하여 최종 위협요인의 우선순위를 도출하는 방법"},{"n":74,"s":"s4","q":"다음 중 공개키 암호의 필요성으로 틀린 것은?","c":["무결성","키 관리 문제","인증","부인방지"],"a":0,"e":"공개키 암호는 대칭키의 키 분배·관리 문제 해결, 전자서명을 통한 인증과 부인방지를 위해 등장했다. 무결성은 해시함수·MAC으로도 제공할 수 있어 공개키 암호 등장의 직접적 필요성으로 보지 않는다.","ce":["무결성은 해시함수·MAC 등으로도 제공할 수 있어 공개키 암호가 등장한 직접적 필요성으로 보지 않는다.","대칭키는 사용자 n명일 때 n(n-1)/2개의 키가 필요하고 안전한 분배가 어려워, 이 키 관리 문제 해결이 공개키 암호의 필요성이다.","공개키 기반 전자서명으로 상대방을 확인하는 인증 제공이 공개키 암호의 필요성이다.","개인키로 서명하면 서명자만 생성 가능해 부인방지를 제공하는데, 이는 대칭키로는 불가능해 공개키 암호의 필요성이다."],"rel":["4-4"]},{"n":75,"s":"s4","q":"다음 중 커버로스(Kerberos)의 구성요소가 아닌 것은?","c":["KDC(Key Distribution Center)","TGS(Ticket Granting Service)","AS(Authetication Service)","TS(Token Service)"],"a":3,"e":"Kerberos는 KDC와 그 안의 AS(인증 서비스), TGS(티켓 발급 서비스), 그리고 티켓(TGT·서비스 티켓)으로 구성된다. TS(Token Service)는 Kerberos 구성요소가 아니다.","ce":["KDC는 Kerberos의 핵심 구성요소로 AS와 TGS를 포함하는 신뢰된 제3자이다.","TGS(Ticket Granting Service)는 TGT를 받아 서비스 티켓을 발급하는 Kerberos 구성요소이다.","AS(Authentication Service)는 사용자를 인증하고 TGT를 발급하는 Kerberos 구성요소이다.","TS(Token Service)는 Kerberos 구성요소가 아니다. Kerberos는 토큰이 아닌 티켓(TGT·서비스 티켓)을 사용한다."],"rel":["2-8"]},{"n":76,"s":"s4","q":"공개키 암호 알고리즘이 아닌 것은?","c":["RSA(Rivest, Shamir, Adelman)","ECC(Elliptic, Curvem Cryptosystems)","ElGamal","Rijndeal"],"a":3,"e":"Rijndael은 AES로 채택된 대칭키 블록 암호 알고리즘이다. RSA(소인수분해), ElGamal(이산대수), ECC(타원곡선 이산대수)는 공개키 암호 알고리즘이다.","ce":["RSA는 큰 수의 소인수분해 난제에 기반한 공개키 암호 알고리즘이다.","ECC는 타원곡선 이산대수 난제에 기반한 공개키 암호 알고리즘이다.","ElGamal은 이산대수 난제에 기반한 공개키 암호 알고리즘이다.","Rijndael은 AES로 채택된 대칭키 블록 암호 알고리즘으로 공개키 암호가 아니다."],"rel":["4-4"]},{"n":77,"s":"s4","q":"키를 분배하는 방법이 아닌 것은?","c":["KDC(Key Distribution Center)","공개키 암호시스템","Diffie-Hellman 키 분배 알고리즘","Kerberos"],"a":3,"e":"확정답안은 Kerberos이다. 키 분배 방식은 KDC를 이용한 방식, 공개키 암호를 이용한 방식, Diffie-Hellman 키 교환으로 분류되며, Kerberos는 KDC 방식을 활용한 인증 프로토콜로 분류된다.","ce":["KDC(키 분배 센터)는 신뢰된 제3자가 세션키를 생성·분배하는 대표적인 키 분배 방식이다.","공개키 암호시스템은 세션키를 상대 공개키로 암호화해 전달하는 키 분배 방식이다.","Diffie-Hellman은 공개값 교환으로 공유 비밀키를 합의하는 키 분배(교환) 방식이다.","공식 정답이다. Kerberos는 KDC 방식을 활용한 '인증 프로토콜'로 분류해 답으로 처리했으나, 실제로 세션키를 분배하므로 논란의 여지가 있다."],"rel":["4-12"],"flag":"Kerberos도 세션키를 분배하므로 논란 여지"},{"n":78,"s":"s4","q":"해시함수 h와 주어진 입력값 x에 대해 h(x)=h(x')을 만족하는 x'(≠x)를 찾는 것이 계산적으로 불가능한 것을 의미하는 것은?","c":["압축성","일방향성","두 번째 역상저항성","충돌 저항성"],"a":2,"e":"두 번째 역상 저항성(약한 충돌 저항성)은 주어진 x에 대해 같은 해시값을 갖는 다른 x'를 찾기 어려운 성질이다. 충돌 저항성은 x를 지정하지 않고 h(x)=h(x')인 임의의 쌍을 찾기 어려운 성질이고, 일방향성은 해시값으로 입력을 찾기 어려운 성질이다.","ce":["압축성은 임의 길이 입력을 고정 길이 해시값으로 변환하는 성질로, 충돌 찾기 난이도와 무관하다.","일방향성(역상 저항성)은 해시값 y가 주어졌을 때 h(x)=y인 입력 x를 찾기 어려운 성질이다.","두 번째 역상 저항성(약한 충돌 저항성)은 주어진 x에 대해 h(x)=h(x')인 다른 x'를 찾기 어려운 성질로 설명과 일치한다.","충돌 저항성(강한 충돌 저항성)은 x를 미리 정하지 않고 h(x)=h(x')인 임의의 쌍을 찾기 어려운 성질이다."],"rel":["4-5"]},{"n":79,"s":"s4","q":"다음 문장에서 설명하는 것은?","c":["타원 곡선 암호 시스템","하이브리드 암호 시스템","세션 키(의사난수 생성기)","이중 암호 시스템"],"a":1,"e":"하이브리드 암호 시스템은 빠른 대칭키로 메시지를 암호화하고 그 대칭키(세션키)만 공개키로 암호화해 전달하여, 대칭키의 속도와 공개키의 키 분배 장점을 결합한다(PGP·TLS 등).","ce":["타원 곡선 암호는 타원곡선 이산대수 문제에 기반한 공개키 암호 방식으로, 대칭키와 공개키를 결합하는 구조를 뜻하지 않는다.","하이브리드 암호 시스템은 메시지를 빠른 대칭키로 암호화하고 그 대칭키만 공개키로 암호화해 전달하는 방식이다(PGP·TLS).","세션 키는 하이브리드 방식에서 한 번 쓰고 버리는 대칭키 자체이며, 전체 암호화 구조의 명칭이 아니다.","이중 암호 시스템은 같은 데이터를 두 번 암호화하는 개념으로, 대칭키·공개키 역할 분담 구조와 다르다."],"rel":["4-1"],"box":"- 메시지 전체를 대칭 암호로 암호화하고 대칭 암호키만을 공개키로 암호화한다.\n- 대칭 암호키를 메시지로 간주하고 이것을 공개키로 암호화한 것이다."},{"n":80,"s":"s4","q":"메시지 출처 인증(Message Origin Authentication)에 활용되는 암호 기술 중 대칭키 방식에 해당하는 것은?","c":["전자서명","해시함수","이중서명","메시지 인증 코드"],"a":3,"e":"메시지 인증 코드(MAC)는 송수신자가 공유한 대칭 비밀키로 생성·검증하여 메시지 출처와 무결성을 인증한다. 전자서명·이중서명은 공개키 방식이며, 해시함수는 키를 사용하지 않아 단독으로 출처 인증을 할 수 없다.","ce":["전자서명은 서명자의 개인키로 생성하고 공개키로 검증하는 공개키(비대칭) 방식이다.","해시함수는 키를 사용하지 않아 누구나 계산할 수 있으므로 단독으로 메시지 출처를 인증하지 못한다.","이중서명은 SET에서 쓰는 개인키 기반 서명으로 공개키 방식이다.","메시지 인증 코드(MAC)는 송수신자가 공유한 대칭 비밀키로 생성·검증해 메시지 출처와 무결성을 인증한다."],"rel":["4-5"]},{"n":81,"s":"s5","q":"주요 직무자 지정 및 관리시 고려해야 할 사항으로 틀린 것은?","c":["개인정보 및 중요정보의 취급, 주요 시스템 접근 등 주요 직무의 기준을 명확히 정의하여야 한다.","주요 직무를 수행하는 임직원 및 외부자를 주요 직무자로 지정하고 그 목록을 최신으로 관리하여야 한다.","업무 필요성에 따라 주요 직무자 및 개인정보취급자 지정을 최소화하는 등 관리방안을 수립·이행하여야 한다.","파견근로자, 시간제근로자 등을 제외한 임직원 중 업무상 개인정보를 취급하는 자를 개인정보취급자로 지정하고 목록을 관리하여야 한다."],"a":3,"e":"개인정보취급자는 정규직뿐 아니라 파견근로자, 시간제근로자 등 개인정보처리자의 지휘·감독을 받아 개인정보를 처리하는 모든 자를 포함한다(ISMS-P 2.2.1). 따라서 파견·시간제 근로자를 제외한다는 설명은 틀리다.","ce":["개인정보 취급, 주요 시스템 접근 등 주요 직무의 기준을 명확히 정의하는 것은 ISMS-P 2.2.1의 요구사항이다.","주요 직무를 수행하는 임직원과 외부자를 주요 직무자로 지정하고 목록을 최신으로 관리하는 것은 올바른 사항이다.","업무상 필요한 경우에만 주요 직무자·개인정보취급자로 지정해 인원을 최소화하는 것은 올바른 사항이다.","개인정보취급자에는 파견근로자·시간제근로자 등 개인정보처리자의 지휘·감독을 받아 개인정보를 처리하는 모든 자가 포함되므로 이들을 제외하면 틀리다."],"rel":["5-11"]},{"n":82,"s":"s5","q":"정보통신기반보호법에서 정하는 주요 정보통신기반시설 보호계획의 수립 등에 포함되지 않는 사항은?","c":["주요정보통신기반시설의 취약점 분석·평가에 관한 사항","정보보호 책임자 지정에 관한 사항","주요정보통신기반시설 및 관리 정보의 침해사고에 대한 예방, 백업, 복구대책에 관한 사항","주요정보통신기반시설의 보호에 관하여 필요한 사항"],"a":1,"e":"정보통신기반 보호법 제5조의 보호계획 포함 사항은 취약점 분석·평가, 침해사고 예방·백업·복구대책, 그 밖에 보호에 필요한 사항이다. 정보보호책임자 지정은 같은 법 제5조의2에서 별도로 규정하는 사항이다(개정 여부 확인).","ce":["주요정보통신기반시설의 취약점 분석·평가에 관한 사항은 보호계획 포함 사항이다.","정보보호책임자 지정은 보호계획의 내용이 아니라 같은 법 제5조의2에서 별도로 규정하는 사항이다(개정 여부 확인).","기반시설 및 관리 정보의 침해사고 예방·백업·복구대책은 보호계획 포함 사항이다.","그 밖에 주요정보통신기반시설의 보호에 관하여 필요한 사항은 보호계획 포함 사항이다."],"rel":["5-13"]},{"n":83,"s":"s5","q":"다음 내용에 따른 국내대리인의 필수 공개 정보로 잘못된 것은?","c":["법인명, 대표명","주소","고객센터 연락처","이메일"],"a":2,"e":"국내대리인 공개 사항은 국내대리인의 성명(법인은 명칭과 대표자 성명), 주소(법인은 영업소 소재지), 전화번호, 전자우편 주소이다. 고객센터 연락처는 법정 공개 항목이 아니다(개정 여부 확인).","ce":["국내대리인의 성명(법인은 명칭과 대표자 성명)은 공개해야 하는 사항이다.","국내대리인의 주소(법인은 영업소 소재지)는 공개해야 하는 사항이다.","공개 항목은 전화번호이며 '고객센터 연락처'는 법정 공개 항목으로 규정되어 있지 않다(개정 여부 확인).","국내대리인의 전자우편(이메일) 주소는 공개해야 하는 사항이다."],"rel":["5-10"],"box":"국내대리인을 지정해야 하는 국외사업자는 개인정보 처리방침에 국내대리인의 정보를 공개하여야 한다."},{"n":84,"s":"s5","q":"정보통신기반 보호법에 의거하여 주요정보통신기반시설을 지정할 때 주요 고려사항으로 틀린 것은?","c":["다른 정보통신기반시설과의 상호연계성","업무의 정보통신기반시설에 대한 의존도","업무의 개인정보 보유 건수","정보통신기반시설을 관리하는 기관이 수행하는 업무의 국가사회적 중요성"],"a":2,"e":"정보통신기반 보호법 제8조의 지정 기준은 업무의 국가사회적 중요성, 업무의 정보통신기반시설 의존도, 다른 기반시설과의 상호연계성, 침해사고 시 피해 규모 및 범위, 침해사고 발생 가능성·복구 용이성이다. 개인정보 보유 건수는 지정 기준이 아니다.","ce":["다른 정보통신기반시설과의 상호연계성은 정보통신기반 보호법 제8조의 지정 기준이다.","업무의 정보통신기반시설에 대한 의존도는 지정 기준이다.","개인정보 보유 건수는 지정 기준에 없다. 이는 개인정보 보호 관련 법령에서 다루는 기준이다.","기반시설을 관리하는 기관이 수행하는 업무의 국가사회적 중요성은 지정 기준이다."],"rel":["5-13"]},{"n":85,"s":"s5","q":"정보통신망 이용 촉진 및 정보 보호 등에 관한 법률에서 정의하는 용어에 대한 설명으로 틀린 것은?","c":["㉠, ㉡","㉡, ㉢","㉢, ㉣","㉡, ㉣"],"a":0,"e":"법상 전자문서는 '송수신되거나 저장된' 문서형식의 자료로 '암호화되어'라는 요건이 없고, 개인정보는 '살아 있는(생존하는)' 개인에 관한 정보로 사망자는 포함하지 않는다. 침해사고와 게시판의 정의는 법 조문과 일치한다(개인정보 정의는 2020년 개인정보 보호법으로 일원화, 개정 여부 확인).","ce":["㉠ 전자문서 정의에는 '암호화되어'라는 요건이 없고, ㉡ 개인정보는 '살아 있는' 개인에 관한 정보로 사망자를 포함하지 않아 둘 다 틀렸다.","㉡은 틀렸지만 ㉢ 침해사고 정의는 법 조문(해킹·바이러스·논리폭탄·메일폭탄·서비스 거부·고출력 전자기파)과 일치한다.","㉢ 침해사고와 ㉣ 게시판 정의는 모두 법 조문과 일치하는 옳은 설명이다.","㉡은 틀렸지만 ㉣ 게시판 정의는 법 조문과 일치하므로 틀린 것의 조합이 될 수 없다."],"rel":["5-10"],"box":"㉠ \"전자문서\"란 컴퓨터 등 정보처리능력을 가진 장치에 의하여 전자적인 형태로 작성되어 송수신되거나 암호화되어 저장된 문서형식의 자료로서 표준화된 것을 말한다.\n㉡ \"개인정보\"란 생존 및 사망한 개인에 관한 정보로서 성명·주민등록번호 등에 의하여 특정한 개인을 알아볼 수 있는 부호·문자·음성·음향 및 영상 등의 정보(해당 정보만으로는 특정 개인을 알아볼 수 없어도 다른 정보와 쉽게 결합하여 알아볼 수 있는 경우에는 그 정보를 포함한다)를 말한다.\n㉢ \"침해사고\"란 해킹, 컴퓨터바이러스, 논리폭탄, 메일폭탄, 서비스 거부 또는 고출력 전자기파 등의 방법으로 정보통신망 또는 이와 관련된 정보시스템을 공격하는 행위를 하여 발생한 사태를 말한다.\n㉣ \"게시판\"이란 그 명칭과 관계없이 정보통신망을 이용하여 일반에게 공개할 목적으로 부호·문자·음성·음향·화상·동영상 등의 정보를 이용자가 게재할 수 있는 컴퓨터 프로그램이나 기술적 장치를 말한다."},{"n":86,"s":"s5","q":"조직의 정보보호 교육 대상자에 해당되지 않는 사람은?","c":["조직의 중요한 고객","최고 경영자","조직의 신입직원","조직이 제공하는 정보를 이용하는 일부 외부 이용자 그룹"],"a":0,"e":"정보보호 교육 대상은 최고경영자를 포함한 모든 임직원(신입직원 포함)과 조직의 정보·시스템에 접근하는 외부자(수탁자, 외부 이용자 그룹 등)이다. 조직의 고객은 교육 대상이 아니라 보호 대상이다.","ce":["조직의 고객은 정보보호 교육 대상이 아니라 보호 대상(서비스 이용자)이다.","최고경영자는 정보보호 의사결정과 책임을 지므로 교육 대상에 포함된다.","신입직원은 입사 시 보안 교육을 받아야 하는 교육 대상이다.","조직의 정보·시스템에 접근하는 외부 이용자 그룹(수탁자 등)도 교육 대상에 포함된다."],"rel":["5-11"]},{"n":87,"s":"s5","q":"다음 문장은 위험분석에 관한 설명이다. 괄호 안에 들어갈 내용은?","c":["㉠ : 위협, ㉡ : 위험, ㉢ : 발생가능성, ㉣ : 취약성","㉠ : 취약성, ㉡ : 위험, ㉢ : 발생가능성, ㉣ : 위협","㉠ : 위험, ㉡ : 취약성, ㉢ : 위협, ㉣ : 발생가능성","㉠ : 발생가능성, ㉡ : 위협, ㉢ : 취약성, ㉣ : 위험"],"a":1,"e":"위험분석은 자산의 취약성을 식별하고 존재하는 위험을 분석하여 발생가능성과 위협의 영향을 파악하는 과정이다. 위험은 잠재적 위협이 현실화될 때의 손실액과 그 발생 확률의 곱(연간 예상 손실 개념)으로 표현된다.","ce":["㉠ 자산에서 식별하는 것은 위협이 아닌 취약성이며, ㉣ 현실화되어 손실을 내는 것은 취약성이 아닌 위협이다.","자산의 취약성(㉠)을 식별하고 위험(㉡)을 분석하며 발생가능성(㉢)과 위협(㉣)의 영향을 파악하고, 위험=잠재적 위협의 손실액×확률로 정의되어 올바르다.","위험이 잠재적 손실액(손실×확률)이라는 둘째 문장의 ㉡ 자리에 취약성이 올 수 없다.","㉡은 위험, ㉣은 위협이어야 하는데 위협과 위험이 뒤바뀌었다."],"rel":["5-2"],"box":"- 자산의 ( ㉠ )을 식별하고 존재하는 ( ㉡ )를 분석하며 이들이 ( ㉢ ) 및 ( ㉣ )이 미칠 수 있는 영향을 파악하며 보안위험의 내용과 정도를 결정하는 과정이다.\n- ( ㉡ )은 잠재적 ( ㉣ )이 현실화되어 나타날 손실액과 이러한 손실이 발생할 확률의 곱(잠재적 손실액)이다."},{"n":88,"s":"s5","q":"다음 문장에서 설명하는 위험평가 방법은?","c":["기준선 접근법","비정형 접근법","상세 위험분석","복합 접근방법"],"a":0,"e":"기준선(베이스라인) 접근법은 표준화된 체크리스트 등으로 모든 시스템에 기본 보호수준을 적용하는 방식으로 시간·비용이 적게 들지만 조직 특성을 반영하지 못해 과보호·과소보호가 생길 수 있다. 비정형 접근법은 전문가 경험에 의존하며, 상세 위험분석은 자산·위협·취약점을 정밀 분석한다.","ce":["기준선(베이스라인) 접근법은 표준 체크리스트로 모든 시스템에 기본 보호수준을 적용해 시간·비용이 적지만, 조직 특성 미반영으로 과보호·과소보호가 생길 수 있다.","비정형 접근법은 전문가의 지식·경험에 의존해 빠르게 분석하는 방식으로, 기본 보호수준 일괄 적용이 아니다.","상세 위험분석은 자산·위협·취약점을 정밀 분석해 적절한 대책을 도출하지만 시간과 비용이 많이 든다.","복합 접근법은 중요 시스템은 상세 분석, 나머지는 기준선 접근법을 적용하는 혼합 방식이다."],"rel":["5-12"],"box":"- 모든 시스템에 기본적인 보호수준을 정하고 이를 달성하기 위한 보호대책을 선택하여 적용할 수 있다.\n- 시간과 비용을 많이 들이지 않고 기본적인 보호대책을 선택하여 적용할 수 있다.\n- 과보호 또는 부족한 보호대책이 적용될 가능성이 존재한다."},{"n":89,"s":"s5","q":"정보보호관리체계 구축시 발생 가능한 문제점과 해결방안에 대한 설명으로 틀린 것은?","c":["관련 부서와의 조정이 곤란하다.","직원들이 일상 업무에 바빠 관리체계 구축사업에 시간을 내기 어렵다.","직원들은 자신의 책임을 피하기 위해 문제점이 발생하면 즉시 상사에게 보고하는 경향을 보인다.","관리체계 구축에는 경영자의 리더십이 필수적으로 요구된다."],"a":2,"e":"관리체계 구축 시 흔한 문제점은 직원들이 책임을 피하려고 문제를 숨기거나 보고를 미루는 경향이다. 즉시 상사에게 보고하는 것은 문제점이 아니라 바람직한 행동이므로 ③이 틀리다.","ce":["관리체계는 여러 부서가 관여해 부서 간 이해관계 조정이 어렵다는 것은 실제 문제점이다.","직원들이 일상 업무에 바빠 구축 사업에 시간을 내기 어렵다는 것은 실제 문제점이다.","실제 문제점은 직원들이 책임을 피하려 문제를 숨기거나 보고를 미루는 경향이다. 즉시 보고는 바람직한 행동이라 문제점이 아니다.","경영진의 지원과 리더십이 있어야 자원 확보·부서 조정이 가능하므로 필수 해결방안이라는 설명은 옳다."],"rel":["5-12"]},{"n":90,"s":"s5","q":"다음 문장에서 설명하는 시스템 보안평가 기준은?","c":["TCSEC","ITSEC","CTCPEC","CC"],"a":2,"e":"캐나다의 CTCPEC은 기능성(비밀성·무결성·가용성·책임성 4개 분류)과 보증성 요구사항으로 구성되며 보증 등급은 T0~T7로 구분된다. TCSEC은 D~A1 등급, ITSEC은 E0~E6 등급을 사용하고, CC는 EAL1~7을 쓰지만 기능을 4가지로 분류하지 않는다.","ce":["TCSEC(오렌지북)은 미국 기준으로 주로 기밀성 중심이며 D~A1 등급(7개)을 쓰고, 기능을 비밀성·무결성·가용성·책임성 4가지로 나누지 않는다.","ITSEC은 유럽 기준으로 기능(F)과 보증(E0~E6) 등급을 분리하지만, 기능을 설명처럼 4가지로 분류하지 않는다.","캐나다의 CTCPEC은 기능성(비밀성·무결성·가용성·책임성)과 보증성 요구사항으로 구성되며 보증 등급이 T0~T7로 나뉜다.","CC는 보증 평가등급 EAL1~7을 쓰지만 기능 요구사항을 클래스(FAU, FCS 등)로 구성하며 4가지로 분류하지 않는다."],"rel":["5-6"],"box":"- 보안제품 개발자에게 제공되어야 할 서비스에 대한 지침을 제시한다.\n- 구매자에게는 필요한 서비스 지침을 제공한다.\n- 기능성과 보증성에 대한 요구사항으로 구성된다.\n- 기능은 비밀성, 무결성, 가용성, 책임성 4가지로 분류된다.\n- 보증 평가등급은 7개 등급으로 분류된다."},{"n":91,"s":"s5","q":"100만명 미만의 정보주체에 관한 개인정보를 보유한 중소기업의 내부관리계획의 내용에 포함되지 않아도 될 사항은?","c":["개인정보 보호책임자의 지정에 관한 사항","개인정보 유출사고 대응 계획 수립·시행에 관한 사항","개인정보의 암호화 조치에 관한 사항","개인정보 처리업무를 위탁하는 경우 수탁자에게 대한 관리 및 감독에 관한 사항"],"a":3,"e":"(구)개인정보의 안전성 확보조치 기준은 개인정보처리자 유형별로 내부관리계획 포함 사항을 차등 적용하여, 100만명 미만 중소기업 등 유형2는 수탁자 관리·감독 등 일부 항목을 제외할 수 있었다. 개인정보 보호책임자 지정, 유출사고 대응, 암호화 조치는 포함해야 하는 사항이다(2023년 고시 개정으로 유형 구분 폐지, 개정 여부 확인).","ce":["개인정보 보호책임자 지정은 모든 유형의 내부관리계획에 포함해야 하는 사항이다.","개인정보 유출사고 대응 계획 수립·시행은 내부관리계획에 포함해야 하는 사항이다.","개인정보 암호화 조치는 내부관리계획에 포함해야 하는 사항이다.","(구)안전성 확보조치 기준은 100만명 미만 중소기업 등(유형2)에 수탁자 관리·감독 항목을 제외할 수 있게 했다(2023년 고시 개정으로 유형 구분 폐지, 개정 여부 확인)."],"rel":["5-9"]},{"n":92,"s":"s5","q":"비즈니스 연속성에서 고장과 관계된 수용될 수 없는 결과를 피하기 위해 재해 후에 비즈니스가 복구되어야 하는 최단 시간 및 서비스 수준을 의미하는 것은?","c":["RTO","WRT","RP","MTD"],"a":0,"e":"RTO(Recovery Time Objective, 목표 복구 시간)는 재해 후 수용 불가능한 결과를 피하기 위해 업무가 복구되어야 하는 시간과 서비스 수준이다. MTD는 업무 중단을 견딜 수 있는 최대 허용 시간, WRT는 시스템 복구 후 데이터 검증 등 작업 복구 시간이다.","ce":["RTO(목표 복구 시간)는 재해 후 수용 불가능한 결과를 피하기 위해 업무가 복구되어야 하는 시간과 서비스 수준이다.","WRT(Work Recovery Time)는 시스템 복구 후 데이터 검증·동기화 등 업무 재개 준비에 걸리는 시간이다.","RP는 BCP 표준 용어가 아니며, 데이터 손실 허용 시점은 RPO(목표 복구 시점)로 표현한다.","MTD(최대 허용 중단 시간)는 업무 중단을 견딜 수 있는 최대 시간(RTO+WRT)으로, 복구 목표 시간 자체와 구분된다."],"rel":["5-3"]},{"n":93,"s":"s5","q":"정보의 수집·가공·저장·검색·송신·수신 중에 정보의 훼손·변조·유출 등을 방지하기 위한 관리적·기술적 수단인 정보보호의 목적으로 틀린 것은?","c":["기밀성 서비스 제공","무결성 서비스 제공","가용성 서비스 제공","추적성 서비스 제공"],"a":3,"e":"정보보호의 3대 목적은 기밀성(유출 방지), 무결성(훼손·변조 방지), 가용성(필요 시 사용 보장)이다. 추적성은 3대 목적에 해당하지 않는다.","ce":["기밀성은 인가되지 않은 자에게 정보가 유출되지 않도록 하는 정보보호 3대 목적이다.","무결성은 정보가 인가 없이 훼손·변조되지 않도록 하는 정보보호 3대 목적이다.","가용성은 인가된 사용자가 필요할 때 정보를 사용할 수 있도록 보장하는 정보보호 3대 목적이다.","추적성(책임추적성)은 행위자를 추적하는 부가 속성으로, 정보보호 3대 목적(기밀성·무결성·가용성)에 해당하지 않는다."],"rel":["5-1"]},{"n":94,"s":"s5","q":"위험분석의 구성요소가 아닌 것은?","c":["비용","취약점","위협","자산"],"a":0,"e":"위험분석의 구성요소는 자산, 위협, 취약점(그리고 기존 보호대책)이며 이들의 관계로 위험을 산정한다. 비용은 대책 선정 시 비용-효과 분석의 고려 요소일 뿐 위험분석 구성요소가 아니다.","ce":["비용은 대책 선정 시 비용-효과 분석에서 고려하는 요소일 뿐 위험을 산정하는 구성요소가 아니다.","취약점은 위협이 이용할 수 있는 자산의 약점으로 위험분석 구성요소이다.","위협은 자산에 손실을 줄 수 있는 잠재적 원인으로 위험분석 구성요소이다.","자산은 보호해야 할 가치를 지닌 대상으로 위험분석 구성요소이다."],"rel":["5-2"]},{"n":95,"s":"s5","q":"정보보호의 예방대책을 관리적 예방대책과 기술적 예방대책으로 나누어 볼 때 관리적 예방대책에 속하는 것은?","c":["안전한 패스워드를 강제로 사용","침입차단 시스템을 이용하여 접속을 통제","가상 사설망을 이용하여 안전한 통신 환경 구현","문서처리 순서의 표준화"],"a":3,"e":"문서처리 순서의 표준화는 절차·규정에 관한 관리적 대책이다. 패스워드 강제 적용, 방화벽을 통한 접속 통제, VPN 구현은 시스템으로 구현하는 기술적 대책이다.","ce":["안전한 패스워드 강제 사용은 시스템 설정(복잡도·주기 정책)으로 구현하는 기술적 대책이다.","침입차단 시스템(방화벽)을 이용한 접속 통제는 장비로 구현하는 기술적 대책이다.","VPN으로 안전한 통신 환경을 구현하는 것은 암호화 기술을 이용한 기술적 대책이다.","문서처리 순서의 표준화는 절차·규정을 정하는 관리적 예방대책이다."],"rel":["5-1"]},{"n":96,"s":"s5","q":"건물 관리 및 화재 등 사고관리를 위해 건물입구를 비추도록 설치된 영상정보처리기기에서 사용할 수 있는 기능으로 옳은 것은?","c":["사고를 확인하기 위한 카메라 줌인, 줌아웃","범인을 추적하기 위한 카메라 이동","사고 내용을 확인하기 위한 음성 녹음","사고 내용을 전달하기 위한 영상 전송"],"a":3,"e":"개인정보 보호법 제25조에 따라 영상정보처리기기 운영자는 설치 목적과 다른 목적으로 기기를 임의로 조작(줌·이동)하거나 다른 곳을 비춰서는 안 되며 녹음 기능은 사용할 수 없다. 사고 영상을 관계 기관 등에 전송하는 것은 설치 목적 범위 내에서 가능하다(개정 여부 확인).","ce":["설치 목적과 다른 목적으로 카메라를 임의 조작(줌인·줌아웃)하는 것은 개인정보 보호법 제25조가 금지한다(개정 여부 확인).","범인 추적을 위해 카메라를 움직여 다른 곳을 비추는 것은 임의 조작 금지에 해당한다.","영상정보처리기기의 녹음 기능 사용은 법으로 금지되어 있다.","사고 영상을 관계 기관 등에 전달하는 것은 설치 목적(시설 안전·화재 예방) 범위 내 이용으로 가능하다(개정 여부 확인)."],"rel":["5-14"]},{"n":97,"s":"s5","q":"다음 문장의 정보보호대책 선정시 영향을 주는 제약사항으로 옳은 것은?","c":["환경적 제약","법적 제약","시간적 제약","사회적 제약"],"a":3,"e":"직원의 수용성, 조직 문화 등 사람과 관련된 요인은 사회적 제약에 해당한다. 법적 제약은 법·규제 요건, 시간적 제약은 대책 구현 기한, 환경적 제약은 공간·기후 등 물리 환경 요인이다.","ce":["환경적 제약은 공간·기후·전력 등 물리적 환경 요인에 따른 제약이다.","법적 제약은 법령·규제 요건 준수에 따른 제약이다.","시간적 제약은 대책을 구현해야 하는 기한·일정에 따른 제약이다.","직원의 이해·수용성, 조직 문화 등 사람과 관련된 요인은 사회적 제약에 해당한다."],"rel":["5-12"],"box":"많은 기술적 대책들이 직원의 능동적인 지원에 의존하기 때문에 이러한 제약사항을 고려하여야 한다. 만약 직원이 대책에 대한 필요성을 이해하지 못하고 문화적으로 수용할 만하다는 것을 알지 못한다면 대책은 시간이 지날수록 비효율적인 것이 된다."},{"n":98,"s":"s5","q":"개인정보보호 법령에 따른 영상정보처리기기의 설치·운영과 관련하여 정보주체가 쉽게 인식할 수 있도록 설치하는 안내판의 기재 항목이 아닌 것은?","c":["설치 목적","영상정보 보관기관","설치 장소","촬영 범위"],"a":1,"e":"안내판에는 설치 목적 및 장소, 촬영 범위 및 시간, 관리책임자의 성명(직책)·연락처, 위탁 시 수탁자 명칭·연락처를 기재한다. 영상정보 보관기간은 운영·관리 방침에 포함할 사항으로 안내판 기재 항목이 아니다(개정 여부 확인).","ce":["설치 목적(범죄 예방, 시설 안전 등)은 정보주체가 촬영 사실을 알 수 있도록 안내판에 기재해야 하는 항목이다(개정 여부 확인).","영상정보 보관기간은 운영·관리 방침에 포함할 사항으로 안내판 기재 항목이 아니다(보기의 '보관기관'은 '보관기간' 오기).","설치 장소는 설치 목적과 함께 안내판에 기재해야 하는 항목으로, 정보주체가 촬영 구역을 인식하게 한다.","촬영 범위 및 시간은 안내판 기재 항목이며, 관리책임자 성명·연락처도 함께 기재한다."],"rel":["5-14"]},{"n":99,"s":"s5","q":"개인정보보호법상 개인정보 유출사고의 통지, 신고 의무에 대한 설명으로 틀린 것은?","c":["정보통신서비스 제공자등은 개인정보의 유출등의 사실을 안 때에는 지체 없이 유출 등의 내역을 해당 이용자에게 알려야 한다.","정보통신서비스 제공자등은 1천명 이상의 정보주체에 관한 개인정보의 유출등의 사실을 안 때에는 지체 없이 유출 등의 내역을 방송통신위원회 또는 한국인터넷진흥원에 신고하여야 한다.","정보통신서비스 제공자등은 정당한 사유 없이 유출 등의 사실을 안 때에는 24시간을 경과하여 통지·신고해서는 아니 된다.","정보통신서비스 제공자 등은 이용자의 연락처를 알 수 없는 등 정당한 사유가 있는 경우에는 유출 등의 내역을 자신의 인터넷 홈페이지에 30일 이상 게시하여야 한다."],"a":1,"e":"출제 당시 정보통신서비스 제공자 특례(개인정보 보호법 제39조의4)는 유출 규모와 관계없이(1명이라도) 보호위원회 또는 한국인터넷진흥원에 신고하도록 했으므로 '1천명 이상'이라는 조건이 틀리다. 1천명 이상 기준은 일반 개인정보처리자(제34조)의 신고 기준이었다(2023년 개정으로 특례 통합, 개정 여부 확인).","ce":["정보통신서비스 제공자등은 유출 사실을 안 때 지체 없이 해당 이용자에게 알려야 했으므로 출제 당시 옳은 설명이다(2023년 개정으로 특례 통합, 개정 여부 확인).","출제 당시 정보통신서비스 제공자 특례는 유출 규모와 관계없이(1명이라도) 신고하도록 했으므로 '1천명 이상' 조건이 틀렸다(1천명은 일반 처리자 기준). 신고처도 2020년 이후 방통위가 아닌 보호위원회였다.","출제 당시 특례는 정당한 사유 없이 유출 사실을 안 때부터 24시간을 넘겨 통지·신고해서는 안 된다고 규정했으므로 옳은 설명이다(개정 여부 확인).","연락처를 알 수 없는 등 정당한 사유가 있으면 홈페이지에 30일 이상 게시하는 것으로 통지를 갈음할 수 있었으므로 옳은 설명이다."],"rel":["5-9"]},{"n":100,"s":"s5","q":"정보보호 거버넌스 국제 표준으로 옳은 것은?","c":["ISO27001","BS10012","ISO27014","ISO27018"],"a":2,"e":"ISO/IEC 27014는 정보보호 거버넌스 국제 표준이다. ISO/IEC 27001은 ISMS 요구사항, BS 10012는 영국 개인정보 관리체계 표준, ISO/IEC 27018은 퍼블릭 클라우드 개인정보 보호 지침이다.","ce":["ISO/IEC 27001은 정보보호 관리체계(ISMS) 요구사항 표준으로 거버넌스 표준이 아니다.","BS 10012는 영국의 개인정보 관리체계(PIMS) 표준이다.","ISO/IEC 27014는 정보보호 거버넌스의 원칙과 프로세스(평가·지시·모니터·소통)를 정한 국제 표준이다.","ISO/IEC 27018은 퍼블릭 클라우드에서 개인식별정보(PII) 보호를 위한 실무 지침이다."],"rel":["5-12"]}]},{"id":"2022-03-13","title":"2022년 3월 13일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"다음 중 취약점 점검 도구에 대한 설명으로 틀린 것은?(문제 오류로 확정답안 발표시 1, 3번이 정답처리 되었습니다. 여기서는 1번을 누르시면 정답 처리 됩니다.)","c":["COPS/COPE : 네트워크 기반의 취약점 분석도구로 컴퓨터, 서버, N/W IDS의 보안 취약점을 분석한다.","Nessus : 네트워크 취약점 점검도구로써 클라이언트-서버 구조로 클라이언트의 취약점을 점검하는 기능이 있다.","nmap : 시스템 내부에 존재하는 취약성을 점검하는 도구로써 취약한 패스워드 점검 기능 등이 있다.","SAINT : 네트워크 취약점 분석도구로써 HTML 형식의 보고서 기능이 있으며 원격으로 취약점을 점검하는 기능을 가지고 있다."],"a":0,"e":"COPS는 유닉스 호스트 내부의 설정·권한·패스워드 취약점을 점검하는 호스트 기반 도구이므로 \"네트워크 기반\"이라는 설명이 틀리다. nmap 역시 원격 포트·서비스 스캐너로 시스템 내부 취약점이나 취약 패스워드를 점검하는 도구가 아니어서 ③도 틀린 설명이며, 확정답안에서 ①·③ 복수 정답 처리되었다.","ce":["COPS/COPE는 유닉스 호스트 내부의 파일 권한·설정·패스워드를 점검하는 호스트 기반 도구로, '네트워크 기반·N/W IDS 분석'이라는 설명이 틀리다. 확정답안에서 ③과 함께 복수 정답 처리되었다.","Nessus는 서버(nessusd)와 클라이언트로 구성된 대표적 네트워크 취약점 스캐너로, 원격 대상의 취약점을 플러그인 기반으로 점검하므로 옳은 설명이다.","nmap은 원격 포트·서비스·OS를 식별하는 네트워크 스캐너로, 시스템 내부 취약성이나 취약 패스워드를 점검하는 도구가 아니다. 이 때문에 확정답안에서 ①과 함께 복수 정답 처리되었다.","SAINT는 SATAN을 계승한 네트워크 취약점 분석 도구로 원격 점검 기능과 HTML 형식 보고서를 제공하므로 옳은 설명이다."],"rel":["1-11"],"flag":"복수정답(①·③) 인정 문항"},{"n":2,"s":"s1","q":"다음은 passwd 파일 구조를 나타내는 그림이다. \"A\"는 무엇인가?","c":["패스워드","UID 값","계정명","설명"],"a":2,"e":"/etc/passwd 는 \"계정명:패스워드(x):UID:GID:설명(GECOS):홈디렉터리:로그인 셸\" 7개 필드로 구성되며 A는 첫 필드인 계정명(Test)이다. B는 패스워드 자리(x, 실제 해시는 /etc/shadow), C는 UID, E가 설명 필드이다.","ce":["패스워드 필드는 두 번째 필드(B 위치의 x)이며, 실제 해시는 /etc/shadow에 저장된다. A가 가리키는 첫 필드가 아니다.","UID는 세 번째 필드(C 위치의 첫 번째 500)이다. A는 그보다 앞선 첫 필드를 가리킨다.","/etc/passwd의 첫 번째 필드는 로그인 계정명이며, A는 그 위치의 'Test'를 가리키므로 계정명이 정답이다.","설명(GECOS) 필드는 다섯 번째 필드(E 위치의 Gen-User)로, 사용자 이름·부서 등 부가 정보를 적는 자리이다."],"rel":["1-6"],"box":"Test : x : 500 : 500 : Gen-User : /home/test : /usr/bin/bash\n(A=Test 위, B=x 아래, C=첫 번째 500 위, D=두 번째 500 위, E=Gen-User 아래, F=/home/test 위, G=/usr/bin/bash 아래를 가리킴)"},{"n":3,"s":"s1","q":"버퍼오버플로우 공격을 완화할 수 있는 방법으로 스택과 힙 영역에 쉘코드 등을 실행하지 못하도록 하는 메모리 보호기법에 해당하는 것은?","c":["ASLR","DEP/NX bit","Format String","Stack Canary"],"a":1,"e":"DEP(Data Execution Prevention)/NX bit는 스택·힙 등 데이터 영역을 실행 불가로 표시해 삽입된 쉘코드 실행을 막는다. ASLR은 메모리 주소를 무작위화하는 기법이고, Stack Canary는 리턴 주소 앞의 값 변조를 탐지하는 기법이며, Format String은 공격 유형이다.","ce":["ASLR은 스택·힙·라이브러리의 적재 주소를 실행 때마다 무작위화해 공격 주소 예측을 어렵게 하는 기법으로, 영역 자체의 실행을 금지하지는 않는다.","DEP/NX bit는 스택·힙 같은 데이터 영역 페이지에 실행 금지 속성을 부여해, 그곳에 삽입된 쉘코드가 실행되지 못하게 하는 메모리 보호기법이다.","Format String은 printf 계열 함수의 서식 문자열을 조작해 메모리를 읽고 쓰는 공격(취약점) 유형으로, 보호기법이 아니다.","Stack Canary는 리턴 주소 앞에 임의 값을 두고 함수 복귀 전 변조 여부를 검사하는 기법으로, 실행 자체를 막는 것이 아니라 오버플로우를 탐지한다."],"rel":["1-10"]},{"n":4,"s":"s1","q":"도구의 기능과 도구명이 짝지어진 것 중 틀린 것은?","c":["운영체제별 로그 변조 탐지도구 - Chklastlog","운영체제별 감사로그 관리도구 - Natas","취약점 진단도구 - SATAN","접근통제관련 로깅 도구 - Syslogd"],"a":1,"e":"Natas는 운영체제별 감사로그 관리 도구로 분류되지 않으므로 틀린 짝이다. Chklastlog는 lastlog·wtmp 변조 여부를 점검하는 도구, SATAN은 원격 네트워크 취약점 진단 도구, Syslogd는 시스템 로그를 수집하는 데몬으로 나머지 짝은 옳다.","ce":["Chklastlog는 lastlog와 wtmp 기록을 비교해 로그 삭제·변조 흔적을 찾는 도구로 '로그 변조 탐지도구' 짝이 옳다.","Natas는 운영체제별 감사로그 관리 도구로 분류되지 않으므로 이 짝이 틀렸다(공식 정답 기준). 감사로그 관리는 syslog·auditd 등 OS 로깅 체계가 담당한다.","SATAN은 원격에서 네트워크 서비스 취약점을 점검하는 초기 대표 취약점 진단도구로 짝이 옳다.","Syslogd는 커널·데몬의 메시지(접속·인증 기록 포함)를 수집·기록하는 로깅 데몬이므로 접근통제 관련 로깅 도구로 볼 수 있다."],"rel":["1-11","1-7"]},{"n":5,"s":"s1","q":"다음 윈도우(Windows)의 Administrators 그룹에 대한 설명으로 틀린 것은?","c":["대표적인 관리자 그룹으로 윈도우 시스템의 모든 권한을 가지고 있다.","사용자 계정을 만들거나 없앨 수 있다.","윈도우가 사용 가능한 모든 자원에 대한 권한을 설정할 수 있다.","해당 컴퓨터 밖의 네트워크에서도 일반 사용자보다 특별한 권한을 행사할 수 있다."],"a":3,"e":"로컬 Administrators 그룹의 권한은 해당 컴퓨터 안에서만 유효하며, 네트워크의 다른 시스템에서는 별도 권한이 부여되지 않는 한 특별한 권한이 없다. 도메인 전체 관리 권한은 Domain Admins 그룹의 역할이다.","ce":["Administrators는 로컬 시스템의 최고 권한 그룹으로 시스템 설정·파일·서비스 전반을 제어할 수 있으므로 옳은 설명이다.","Administrators 구성원은 로컬 사용자 계정을 생성·삭제·수정할 수 있으므로 옳은 설명이다.","Administrators는 파일·폴더·레지스트리 등 모든 자원의 소유권을 가져와 권한(ACL)을 설정할 수 있으므로 옳은 설명이다.","로컬 Administrators의 권한은 해당 컴퓨터 안에서만 유효하며 다른 네트워크 시스템에서는 특별 권한이 없다. 도메인 전체 권한은 Domain Admins 그룹이 가진다."],"rel":["1-17"]},{"n":6,"s":"s1","q":"사용자 PC가 언제 부팅되었는지를 확인하기 위해 입력해야 하는 명령어는?","c":["net statistics workstation","net computer boot time","net reboot time","net time boot"],"a":0,"e":"net statistics workstation(또는 net stats srv) 출력의 \"통계 시작 시간\"이 워크스테이션 서비스가 시작된 시점, 즉 마지막 부팅 시각을 나타낸다. 나머지 보기는 존재하지 않는 명령 형식이다.","ce":["net statistics workstation 출력의 '통계 시작 시간'은 워크스테이션 서비스가 시작된 시점, 즉 마지막 부팅 시각을 보여준다.","윈도우 net 명령에는 computer 하위 명령이 있으나 'boot time' 옵션은 없어 부팅 시각을 조회할 수 없다.","net 명령에는 reboot 하위 명령이 존재하지 않는다. 재부팅은 shutdown /r 명령으로 수행한다.","net time은 네트워크 시간 동기화·조회용 명령이며 boot 옵션이 없어 부팅 시각을 확인할 수 없다."],"rel":["1-17"]},{"n":7,"s":"s1","q":"리눅스 proc 파일 시스템에서 ASLR(Address Space Layout Randomization) 설정값을 확인할 수 있는 파일은 무엇인가?","c":["/proc/sys/kernel/randomize_va_space","/proc/sys/kernel/watchdog","/proc/sys/kernel/panic","/proc/sys/kernel/random"],"a":0,"e":"/proc/sys/kernel/randomize_va_space 값이 0이면 ASLR 비활성, 1이면 스택·라이브러리 등 부분 무작위화, 2이면 힙까지 포함한 전체 무작위화이다. watchdog·panic은 커널 감시·패닉 동작 설정이고 random은 난수 생성기 관련 디렉터리이다.","ce":["randomize_va_space는 ASLR 설정값 파일로 0=비활성, 1=스택·라이브러리 등 부분 무작위화, 2=힙(brk)까지 전체 무작위화를 뜻한다.","/proc/sys/kernel/watchdog은 커널 락업을 감시하는 워치독 기능의 활성 여부를 설정하는 파일이다.","/proc/sys/kernel/panic은 커널 패닉 발생 후 자동 재부팅까지 대기할 초 단위 시간을 설정하는 파일이다.","/proc/sys/kernel/random은 엔트로피 풀 크기·UUID 등 커널 난수 생성기 관련 정보를 담은 디렉터리로 ASLR과 무관하다."],"rel":["1-10"]},{"n":8,"s":"s1","q":"다음 중 무결성(Integrity) 검사를 위한 도구가 아닌 것은?","c":["tripwire","Fcheck","Samhain","prstat"],"a":3,"e":"prstat은 솔라리스에서 프로세스 상태(CPU·메모리 사용률)를 보여주는 모니터링 명령이다. Tripwire, Fcheck, Samhain은 파일 해시 기준값과 비교해 변조를 탐지하는 무결성 검사 도구이다.","ce":["Tripwire는 파일의 해시·속성을 기준 DB로 저장해 두고 주기적으로 비교해 변조를 탐지하는 대표 무결성 검사 도구이다.","Fcheck는 Perl로 작성된 파일 무결성 점검 도구로, 기준 스냅샷과 비교해 파일 변경을 탐지한다.","Samhain은 파일 무결성 검사와 호스트 기반 침입탐지 기능을 제공하는 도구로 무결성 검사 도구에 해당한다.","prstat은 솔라리스에서 프로세스별 CPU·메모리 사용 현황을 보여주는 모니터링 명령으로, 파일 무결성 검사 기능이 없다."],"rel":["1-11"]},{"n":9,"s":"s1","q":"다음 문장에서 설명하고 있는 내용의 괄호 안에 들어갈 올바른 항목은?","c":["MBR","BIOS","FAT","NTFS"],"a":3,"e":"NTFS는 MFT(Master File Table)를 두고 파일·디렉터리뿐 아니라 메타데이터까지 모두 파일 형태로 관리하므로 포렌식 분석에 유용하다. FAT는 FAT 테이블과 디렉터리 엔트리 구조이며, MBR과 BIOS는 파일 시스템이 아니다.","ce":["MBR은 디스크 첫 섹터에 있는 부트 코드와 파티션 테이블로, 파일·디렉터리·메타정보를 관리하는 파일 시스템이 아니다.","BIOS는 메인보드 펌웨어로 하드웨어 초기화와 부팅 장치 선택을 담당하며 파일 시스템과 무관하다.","FAT는 FAT 테이블과 디렉터리 엔트리로 파일 위치를 관리하는 파일 시스템으로, 메타정보까지 파일 형태로 관리하지는 않는다.","NTFS는 $MFT·$LogFile·$Bitmap 등 메타데이터까지 모두 파일 형태로 관리하므로 포렌식 분석에 유용하다는 설명에 부합한다."],"rel":["1-18"],"box":"포렌식 관점에서 파일 시스템 영역은 매우 중요하다고 볼 수 있다. 특히, (   )는(은) 파일, 디렉터리 및 메타 정보 까지 파일 형태로 관리하며 파일과 디렉터리를 분석하여 정보를 알아내는데 유용하다."},{"n":10,"s":"s1","q":"다음 중 프로세스 스케줄링과 관계가 가장 먼 것은?","c":["페이징(Paging)","스와핑(Swapping)","레이스컨디션(Race condition)","환형대기(Circular wait)"],"a":0,"e":"페이징은 가상 메모리를 고정 크기 페이지로 나누어 관리하는 메모리 관리 기법으로 프로세스 스케줄링과 거리가 멀다. 스와핑은 프로세스를 메모리와 디스크 사이에서 교체하는 중기 스케줄링이고, 레이스 컨디션·환형대기는 프로세스 실행 순서·자원 경쟁에서 발생하는 문제이다.","ce":["페이징은 가상 메모리를 고정 크기 페이지로 나눠 물리 프레임에 매핑하는 메모리 관리 기법으로, CPU를 어느 프로세스에 줄지 정하는 스케줄링과 거리가 가장 멀다.","스와핑은 메모리 부족 시 프로세스 전체를 디스크로 내보내고 다시 들이는 것으로, 중기 스케줄링의 핵심 동작이다.","레이스 컨디션은 여러 프로세스의 실행 순서(스케줄링 타이밍)에 따라 결과가 달라지는 문제로 스케줄링과 관련된다.","환형대기는 교착상태 4조건 중 하나로, 프로세스들이 자원을 순환적으로 기다리는 병행 프로세스 실행 문제이다."],"rel":["1-1"]},{"n":11,"s":"s1","q":"다음 문장이 설명한 공격 위협은 무엇인가?","c":["운영체제 명령 실행","XPath 인젝션","디렉터리 인덱싱","정보 누출"],"a":0,"e":"|, &, ;, ` 문자는 셸에서 명령을 연결·치환하는 메타문자이므로 필터링 대상이 되는 공격은 운영체제 명령 실행(OS Command Injection)이다. XPath 인젝션은 XML 질의문 조작, 디렉터리 인덱싱은 디렉터리 목록 노출 취약점이다.","ce":["|, &, ;, ` 는 셸에서 명령을 파이프·연결·치환하는 메타문자로, 이를 필터링해야 하는 위협은 운영체제 명령 실행(OS Command Injection)이다.","XPath 인젝션은 XML 문서 질의(XPath)에 ' or '1'='1 같은 조건을 삽입하는 공격으로, 필터링 대상은 따옴표·괄호·= 등이다.","디렉터리 인덱싱은 기본 문서가 없을 때 디렉터리 파일 목록이 노출되는 설정 취약점으로, 웹 서버 설정에서 인덱싱을 끄는 것이 대책이다.","정보 누출은 오류 메시지·주석 등으로 시스템 정보가 노출되는 취약점으로, 대책은 오류 처리·응답 정보 최소화이다."],"rel":["3-6"],"box":"해당 취약점이 존재하는 경우 부적절하게 권한이 변경되거나 시스템 동작 및 운영에 악영향을 줄 가능성이 있으므로 \"|\", \"&\", \";\", \"`\" 문자에 대한 필터링 구현이 필요함"},{"n":12,"s":"s1","q":"웹 쿠키(Cookies)에 대한 설명 중 올바른 것은?","c":["쿠키는 서버가 아닌 클라이언트에 저장된다.","쿠키는 웹 서버에 저장되므로 클라이언트에서 제어할 수 없다.","쿠키는 실행가능한 파일로 바이러스로 동작할 수 있다.","쿠키는 강력한 인증 기능을 제공한다."],"a":0,"e":"쿠키는 웹 서버가 전달한 이름=값 형태의 텍스트 데이터로 클라이언트(브라우저)에 저장되며 사용자가 조회·수정·삭제할 수 있다. 실행 파일이 아니므로 바이러스로 동작하지 않고, 탈취·변조가 가능해 그 자체로 강력한 인증 수단이 아니다.","ce":["쿠키는 서버가 Set-Cookie로 보낸 이름=값 텍스트를 클라이언트(브라우저)가 저장했다가 요청 시 다시 보내는 구조이다.","쿠키는 서버가 아니라 클라이언트에 저장되므로 사용자가 브라우저에서 조회·수정·삭제할 수 있다. 서버 측에 저장되는 것은 세션이다.","쿠키는 단순 텍스트 데이터로 실행 코드가 아니어서 스스로 바이러스로 동작할 수 없다. 다만 개인정보·세션 탈취에 악용될 수 있다.","쿠키는 클라이언트에서 변조·탈취(XSS·스니핑)될 수 있어 그 자체로 강력한 인증을 제공하지 못한다. Secure·HttpOnly 속성 등 보완이 필요하다."],"rel":["3-3"]},{"n":13,"s":"s1","q":"Syslog와 같은 시스템 로그를 주기적으로 스캔하여 어떠한 행위가 발생했는지를 분석하는 시스템 로깅 도구는?","c":["Nikto","X-scan","N-stealth","Swatch(Simple WATCHer)"],"a":3,"e":"Swatch는 로그 파일을 감시하다가 지정한 패턴이 나타나면 경보·명령 실행 등으로 대응하는 로그 모니터링 도구이다. Nikto와 N-stealth는 웹 서버 취약점 스캐너, X-scan은 네트워크 취약점 스캐너이다.","ce":["Nikto는 웹 서버의 위험 파일·구버전·설정 오류를 점검하는 웹 취약점 스캐너로, 로그 감시 도구가 아니다.","X-scan은 원격 호스트의 포트·서비스·취약 계정 등을 점검하는 네트워크 취약점 스캐너이다.","N-stealth는 웹 서버 취약점을 점검하는 상용 웹 스캐너로 로그 분석 기능과 무관하다.","Swatch는 syslog 등 로그를 실시간 감시하다가 정규식 패턴이 나타나면 경보·명령 실행으로 대응하는 로그 모니터링 도구이다."],"rel":["1-7"]},{"n":14,"s":"s1","q":"다음 문장에서 설명한 공격 위협은 무엇인가?","c":["SSI 인젝션","XPath 인젝션","크로스사이트 스크립팅","악성 콘텐츠"],"a":2,"e":"게시판 등에 스크립트를 삽입해 열람자의 브라우저에서 실행시키고 쿠키(세션)를 탈취하는 공격은 크로스사이트 스크립팅(XSS)이다. SSI 인젝션은 서버 측 include 지시어를 삽입해 서버에서 명령을 실행시키는 공격이다.","ce":["SSI 인젝션은 <!--#exec cmd=...--> 같은 서버 측 include 지시어를 삽입해 서버에서 명령을 실행시키는 공격으로, 열람자 쿠키 탈취와 다르다.","XPath 인젝션은 XML 데이터 질의를 조작해 인증 우회·데이터 열람을 노리는 공격으로 스크립트 삽입과 무관하다.","게시판·URL에 스크립트를 삽입해 열람자의 브라우저에서 실행시켜 쿠키(세션)를 탈취하거나 리다이렉트하는 공격은 크로스사이트 스크립팅(XSS)이다.","악성 콘텐츠는 악성 파일·링크 등을 게시해 이용자를 감염시키는 위협을 포괄하는 말로, 입력값 필터링 미흡에 따른 스크립트 실행을 특정하지 않는다."],"rel":["3-6"],"box":"웹 애플리케이션에서 사용자 입력 값에 대한 필터링이 제대로 이루어지지 않을 경우, 공격자는 사용자 입력 값을 받는 게시판, URL 등에 악의적인 스크립트(Javascript, VBScript, ActiveX, Flash 등)를 삽입하여 게시글이나 이메일을 읽는 사용자의 쿠키(세션)를 탈취하여 도용하거나 악성코드 유포 사이트로 Redirect 할 수 있음"},{"n":15,"s":"s1","q":"다음 중 트로이목마 프로그램인 루트킷에 대한 설명으로 가장 부적절한 것은?","c":["루트킷의 목적은 자신과 다른 소프트웨어를 보이지 않게 숨기고 사용자가 공격자의 소프트웨어를 인지하고 제거할 가능성을 피한다.","윈도우용 루트킷에는 FU-Rootkit, Hxdef100, NTRRootkit 등이 있다.","리눅스용 루트킷에는 Suckit, lrk4, lrk5, adore 등이 있다.","자기 복제를 하여 다른 컴퓨터에 루트킷을 설치함으로써 그 피해가 커질 수 있다."],"a":3,"e":"루트킷은 트로이목마 계열로 자기 복제·전파 기능이 없으며, 공격자의 존재와 도구를 숨기는 은닉이 핵심 목적이다. 자기 복제로 다른 컴퓨터에 퍼지는 것은 웜·바이러스의 특성이다.","ce":["루트킷의 핵심 목적은 공격자의 프로세스·파일·연결을 숨겨 탐지와 제거를 피하는 것이므로 옳은 설명이다.","FU-Rootkit, Hxdef100(Hacker Defender), NTRootkit은 윈도우용 루트킷으로 알려져 있어 옳은 설명이다.","Suckit, lrk4·lrk5(Linux Rootkit), adore는 리눅스용 루트킷으로 옳은 설명이다.","루트킷은 트로이목마 계열로 자기 복제·전파 기능이 없다. 스스로 복제해 다른 컴퓨터로 퍼지는 것은 웜·바이러스의 특성이다."],"rel":["1-9"]},{"n":16,"s":"s1","q":"관리자 A는 개별그룹으로 신규 사용자 등록(kim, jang) 작업을 어느날 수행한 후 1주일 후에 아래와 같은 시스템 내용을 보고 판단하였다. 올바른 판단은?","c":["패스워드 파일(/etc/passwd)은 누구든지 직접 수정 가능하다.","사용자 jang은 /etc/passwd 파일의 권한을 설정할 수 있다.","사용자 kim은 사용자 계정에 jang 디렉토리에 들어가서 읽을 수도 없고 실행을 못 시킬 것이다.","jang은 kim의 패스워드를 바꿀 수 있다."],"a":2,"e":"/home/jang 은 drwx------ 로 소유자 jang에게만 권한이 있어 kim(기타 사용자)은 디렉터리 진입·읽기·실행이 모두 불가하다. /etc/passwd 는 -rw-r--r-- root 소유이므로 root만 수정·권한 변경할 수 있고, 일반 사용자는 다른 사용자의 패스워드를 바꿀 수 없다.","ce":["/etc/passwd는 -rw-r--r-- root 소유로 소유자 root만 쓸 수 있고 그룹·기타 사용자는 읽기만 가능하므로 누구나 수정할 수 없다.","파일 권한(chmod) 변경은 소유자나 root만 가능하다. /etc/passwd 소유자는 root이므로 jang은 권한을 설정할 수 없다.","/home/jang은 drwx------로 소유자 jang에게만 rwx가 있고 기타 사용자 권한이 없으므로 kim은 진입·목록 읽기·실행이 모두 불가하다.","일반 사용자는 passwd 명령으로 자신의 패스워드만 바꿀 수 있고, 타인의 패스워드 변경은 root만 가능하다."],"rel":["1-4"],"box":"#ls -al /etc/passwd\n-rw-r--r-- 1 root root 54192 Jan 20 2015 passwd\n#ls -al /home/jang\ndrwx------ 2 jang jang 120 Jan 27 05:12 .\n#ls -al /home/kim\ndrwxr-xr-x 2 kim kim 120 jan 20 04:12 ."},{"n":17,"s":"s1","q":"소유권 없는 파일을 찾는 명령어 및 옵션이 아닌 것은?","c":["find / -ls 2 >/dev/null","find / \\( -nouser -o -nogroup \\) -xdev -exec ls -al {} \\; 2> /dev/null","find / -nouser -print","find / -nogroup -print"],"a":0,"e":"소유자·그룹이 없는 파일은 -nouser, -nogroup 조건으로 찾는다. ①은 조건 없이 모든 파일을 -ls 형식으로 나열할 뿐이므로 소유권 없는 파일 검색 명령이 아니다.","ce":["조건 없이 find / -ls를 실행하면 모든 파일을 ls -dils 형식으로 나열할 뿐이며, -nouser·-nogroup 조건이 없어 소유권 없는 파일을 골라내지 못한다.","-nouser -o -nogroup 조건으로 소유자나 그룹이 없는 파일을 찾고, -xdev로 다른 파일시스템을 제외하며 결과를 ls -al로 출력하는 올바른 명령이다.","-nouser는 /etc/passwd에 없는 UID를 소유자로 가진 파일을 찾는 조건으로, 소유자 없는 파일 검색에 해당한다.","-nogroup은 /etc/group에 없는 GID를 가진 파일을 찾는 조건으로, 그룹 소유권 없는 파일 검색에 해당한다(원문 'fine'은 find 오탈자)."],"rel":["1-16"],"flag":"④ 원문 \"fine\" → \"find\" 오탈자 교정"},{"n":18,"s":"s1","q":"다음 문장의 괄호 안에 해당하는 것은 무엇인가?","c":["버퍼오버플로우","루팅","인젝션","접근 제어"],"a":1,"e":"안드로이드에서 루트 권한을 획득해 제조사·판매자의 제약을 해제하는 것을 루팅(Rooting)이라 한다. iOS에서 같은 행위는 탈옥(Jailbreak)이라 부른다.","ce":["버퍼오버플로우는 경계 검사 없는 입력으로 메모리를 덮어쓰는 공격 기법으로, 권한 획득 수단이 될 수는 있지만 장치 제약 해제를 뜻하는 용어가 아니다.","안드로이드에서 루트 권한을 얻어 제조사·통신사의 제약을 풀고 장치를 완전히 제어하는 것을 루팅(Rooting)이라 한다. iOS에서는 탈옥이라 부른다.","인젝션은 입력값에 SQL·명령어 등을 삽입해 의도치 않은 실행을 유발하는 공격으로 루트 권한 획득 행위의 명칭이 아니다.","접근 제어는 주체의 객체 접근을 허용·제한하는 보안 기능으로, 제약을 풀어 권한을 얻는 행위와 반대 개념이다."],"rel":["1-15"],"box":"안드로이드는 리눅스 커널을 기반으로 개발되어, 일반 사용자 계정과 루트 계정의 두가지 유형의 사용자 계정으로 나뉜다. 운영체제 변경이나, 특정 명령 실행, 도구 설치 등을 하기 위해서는 루트 권한이 필요하다. (   )은 루트 액세스 권한을 얻어 장치를 완전히 제어하는 것을 말한다. 특히, 기기의 생산자나 판매자가 걸어놓은 제약을 풀기 위해 사용한다."},{"n":19,"s":"s1","q":"다음 중 은폐형 바이러스에 대한 설명으로 가장 적합한 것은?","c":["파일이 감염될 경우 그 파일의 내용을 확인할 수 없다.","감염된 파일의 길이가 증가하지 않은 것처럼 보이게 하고, 감염전의 내용을 보여주어 바이러스가 없는 것처럼 백신과 사용자를 속인다.","바이러스 분석가에게 분석을 어렵게 하고 백신 개발을 지연시키도록 여러 단계의 기법을 사용한다.","백신으로 진단이 어렵도록 바이러스 프로그램의 일부 또는 전체를 암호화한다."],"a":1,"e":"은폐형(Stealth) 바이러스는 시스템 호출을 가로채 감염 파일의 크기 증가를 숨기고 감염 전 내용을 보여줘 백신과 사용자를 속인다. ④는 암호형(Encrypted) 바이러스, ③은 분석 방해를 위한 갑옷형(Armored) 바이러스의 설명이다.","ce":["감염 파일의 내용을 확인할 수 없게 되는 것은 은폐형의 특징이 아니다. 은폐형은 오히려 감염 전 내용을 보여줘 정상처럼 속인다.","은폐형(Stealth) 바이러스는 시스템 호출을 가로채 감염 파일의 크기 증가를 숨기고 감염 전 내용을 보여줘 백신과 사용자를 속인다.","여러 단계의 기법으로 분석을 어렵게 하고 백신 개발을 지연시키는 것은 갑옷형(Armored) 바이러스의 특징이다.","바이러스 코드 일부·전체를 암호화해 진단을 어렵게 하는 것은 암호형(Encrypted) 바이러스의 특징이다."],"rel":["1-19"]},{"n":20,"s":"s1","q":"다음 문장에서 리눅스 시스템에 침해 흔적을 조사하기 위해 루트 권한을 가진 setuid를 찾는 명령어로 괄호안에 들어갈 적합한 것은?","c":["-perm -06000 \\","-perm -00100 \\","-perm -00400 \\","-perm -00200 \\"],"a":0,"e":"특수권한 비트는 SetUID=4000, SetGID=2000이므로 -perm -06000 으로 두 특수권한이 설정된 root 소유 파일을 찾는다. 00100·00400·00200은 각각 소유자의 실행·읽기·쓰기 일반 권한 비트로 setuid 검색과 무관하다.","ce":["특수권한은 SetUID=4000, SetGID=2000이므로 -perm -06000은 둘 다 설정된 파일을 찾는 조건으로, 선택지 중 setuid 검색에 해당하는 유일한 특수권한 값이다.","00100은 소유자 실행(x) 권한 비트로, 일반 실행 권한만 검사하므로 setuid 파일 검색이 아니다.","00400은 소유자 읽기(r) 권한 비트로 setuid와 무관하다.","00200은 소유자 쓰기(w) 권한 비트로 setuid와 무관하다."],"rel":["1-5"],"box":"find / -user root -type f \\(    ) -exec ls -al { } \\;"},{"n":21,"s":"s2","q":"다음 중 VPN에 대한 설명으로 가장 옳지 않은 것은?","c":["SSL VPN은 웹브라우저만 있으면 언제 어디서나 사용이 가능하다.","IPsec VPN은 네트워크 계층에서 안전하게 정보를 전송하는 방법이다.","IPsec VPN은 운영방식에 따라 트랜스포트 모드만 지원하고 암호화 여부에 따라 ESP, AH 프로토콜을 사용한다.","기본적으로 SSL VPN과 IPsec VPN은 데이터의 기밀성과 무결성은 동일하며, 단지 데이터의 암호화 구현 방식에 차이가 있다."],"a":2,"e":"IPsec은 운영 방식에 따라 전송(Transport) 모드와 터널(Tunnel) 모드를 모두 지원하므로 \"트랜스포트 모드만\"이 틀리다. 프로토콜은 암호화가 필요하면 ESP, 인증·무결성만 필요하면 AH를 사용한다.","ce":["SSL VPN은 웹 브라우저에 내장된 SSL/TLS를 이용하므로 별도 클라이언트 없이 어디서나 접속할 수 있어 옳은 설명이다.","IPsec은 IP 계층(3계층)에서 패킷을 암호화·인증해 안전하게 전송하는 프로토콜이므로 옳은 설명이다.","IPsec은 전송(Transport) 모드와 터널(Tunnel) 모드를 모두 지원하므로 '트랜스포트 모드만'이 틀리다. 기밀성이 필요하면 ESP, 인증·무결성만이면 AH를 쓴다.","두 방식 모두 암호화와 무결성 검증을 제공하며, 차이는 동작 계층(IPsec=3계층, SSL=전송 계층 위)과 구현 방식에 있으므로 옳은 설명이다."],"rel":["2-7","2-6"]},{"n":22,"s":"s2","q":"다음 스크린드 서브넷 구조에 대한 설명으로 가장 옳지 않은 것은?","c":["외부 인터넷 환경에서 접속이 되어야 한다.","스크리닝 라우터 사이에 듀얼 홈드 게이트웨이가 위치하는 구조이다.","다른 방화벽에 비해 설치 및 관리가 쉽다.","서비스 속다가 낮다."],"a":2,"e":"스크린드 서브넷은 두 스크리닝 라우터 사이에 듀얼 홈드 게이트웨이(DMZ)를 두는 구조로 보안성이 가장 높지만 구성 장비가 많아 설치·관리가 어렵고 비용이 크며 처리 속도가 낮다. 따라서 \"설치 및 관리가 쉽다\"는 틀린 설명이다.","ce":["스크린드 서브넷의 DMZ에는 웹·메일 등 공개 서버가 위치해 외부 인터넷에서 접속이 가능해야 하므로 옳은 설명이다.","외부·내부 스크리닝 라우터 사이에 듀얼 홈드 게이트웨이(배스천 호스트)를 두어 DMZ를 구성하는 구조이므로 옳은 설명이다.","스크린드 서브넷은 라우터 2대와 게이트웨이 등 구성 장비가 많아 설치·관리가 가장 어렵고 비용이 크다. '쉽다'는 틀린 설명이다.","다단계 필터링을 거치므로 처리 속도가 상대적으로 낮다는 단점이 있어 옳은 설명이다(원문 '속다가'는 '속도가' 오탈자)."],"rel":["2-9"]},{"n":23,"s":"s2","q":"다음 중 Window 계열의 시스템에 대한 포트 스캐닝을 할 수 없는 것은?","c":["TCP SYN Scan","TCP FIN Scan","TCP Connect Scan","UDP Scan"],"a":1,"e":"FIN·NULL·Xmas 스캔은 닫힌 포트만 RST로 응답하는 RFC 793 동작에 의존하는데, 윈도우는 포트 상태와 무관하게 RST를 보내므로 열린 포트를 구분할 수 없다. SYN·Connect·UDP 스캔은 윈도우에서도 동작한다.","ce":["SYN 스캔은 SYN에 대한 SYN/ACK(열림)·RST(닫힘) 응답으로 판별하므로 윈도우에서도 정상적으로 포트 상태를 알 수 있다.","FIN 스캔은 닫힌 포트만 RST를 보내는 RFC 793 동작에 의존하는데, 윈도우는 열린 포트에도 RST를 보내므로 포트 상태를 구분할 수 없다.","Connect 스캔은 3-way handshake를 완전히 맺어 판별하므로 운영체제와 무관하게 윈도우에서도 동작한다.","UDP 스캔은 닫힌 포트의 ICMP Port Unreachable 응답으로 판별하며 윈도우에서도 사용할 수 있다."],"rel":["2-4"]},{"n":24,"s":"s2","q":"바이러스 및 공격으로부터 IoT(Internet of Thing) 기기를 보호할 수 있는 접근제어, 기기 인증, 통신 암호화, 가용성 등과 같은 보안 요구 사항을 알기 쉽게 나타내도록 IoT용 SoA(Service oriented Architecture)는 4계층으로 구성된다. 다음 중 IoT용 SoA 4 계층에 포함되지 않는 계층은 어떤 계층인가?","c":["센싱 계층","네트워크 계층","트랜스포트 계층","서비스 계층"],"a":2,"e":"IoT용 SoA 4계층은 센싱 계층, 네트워크 계층, 서비스 계층, 인터페이스(애플리케이션) 계층으로 구성된다. 트랜스포트 계층은 OSI 참조모델의 계층으로 IoT SoA 4계층에 포함되지 않는다.","ce":["센싱 계층은 센서·RFID 등으로 데이터를 수집하는 최하위 계층으로 IoT SoA 4계층에 포함된다.","네트워크 계층은 수집 데이터를 유·무선 통신으로 전달하는 계층으로 IoT SoA 4계층에 포함된다.","IoT SoA 4계층은 센싱·네트워크·서비스·인터페이스 계층이다. 트랜스포트 계층은 OSI 참조모델의 4계층으로 여기에 포함되지 않는다.","서비스 계층은 데이터 관리·서비스 제공을 담당하는 중간 계층으로 IoT SoA 4계층에 포함된다."],"rel":["1-15"]},{"n":25,"s":"s2","q":"다음 문장의 괄호 안에 들어갈 알맞은 용어는?","c":["PLC","SCADA","Stuxnet","Modbus"],"a":1,"e":"SCADA(Supervisory Control And Data Acquisition)는 원격지의 공정·기반시설을 감시하고 제어하는 산업제어시스템으로 전력·수도 등 사회기반시설 사이버 공격의 대상이 된다. PLC는 현장 제어기, Modbus는 산업용 통신 프로토콜, Stuxnet은 SCADA를 공격한 악성코드이다.","ce":["PLC(Programmable Logic Controller)는 현장 설비를 직접 제어하는 산업용 제어기로, 공정 전체를 감시·제어하는 컴퓨터 시스템 자체를 가리키지 않는다.","SCADA는 원격지 공정·기반시설의 데이터를 수집하고 감시·제어하는 시스템으로, 전력·수도 등 사회기반시설 사이버 공격의 대상이 된다.","Stuxnet은 2010년 발견된 SCADA·PLC 공격용 악성코드(웜)로, 제어 시스템 자체가 아니라 공격 도구이다.","Modbus는 PLC·장비 간 통신에 쓰이는 산업용 통신 프로토콜로, 감시·제어 시스템을 지칭하는 용어가 아니다."],"rel":["2-13"],"box":"(   )는(은) 산업제어시스템(Industrial Control System)에 대한 공정, 기반 시설, 설비를 바탕으로 한 작업공정을 감시하고 제어하는 컴퓨터 시스템으로 최근 이를 대상으로 이루어진 사이버 공격으로 인해 전력공급체계 등 사회기반시설 운영에 피해가 발생하고 있다."},{"n":26,"s":"s2","q":"네트워크에서 큰 크기의 파일을 전송할 때, 정상적인 경우에 전송가능한 최대 사이즈로 조각화 되어 전송되며, 이때 Fragment Number를 붙여 수신측에서 재조합을 하게 된다. Fragmentation Offset을 위조하여 중복하게 하거나 공간을 두어 재조합을 방해하는 공격은 OSI 7계층 중 어느 계층에서 발생하는 것인가?","c":["OSI 2 계층","OSI 3 계층","OSI 4 계층","OSI 5 계층"],"a":1,"e":"단편화(Fragmentation)와 Fragment Offset 필드는 IP 헤더에 있으므로 이를 위조하는 Teardrop 등의 공격은 네트워크 계층(3계층)에서 발생한다. 4계층(TCP/UDP)에는 단편화 오프셋 필드가 없다.","ce":["2계층(데이터링크)은 프레임 단위로 인접 노드 간 전송을 담당하며 IP 단편화 오프셋 필드가 없다.","단편화와 Fragment Offset 필드는 IP 헤더에 있으므로, 이를 조작하는 Teardrop 류 공격은 네트워크 계층(3계층)에서 발생한다.","4계층(TCP/UDP)은 세그먼트의 순서번호·포트를 다루며, 단편화 재조합은 그 아래 IP 계층에서 이뤄진다.","5계층(세션)은 대화 설정·동기화를 담당하며 패킷 단편화와 무관하다."],"rel":["2-12"]},{"n":27,"s":"s2","q":"다음 문장은 모바일 악성코드에 관한 설명이다. 어떤 악성코드에 관한 설명인가?","c":["Card trap. A","CommWarrior","Hobbles. A","Brader"],"a":1,"e":"CommWarrior는 심비안 기반 휴대전화에서 블루투스와 MMS를 통해 확산된 웜으로, 단말에 저장된 전화번호로 MMS를 보내 스스로 퍼뜨렸다. 따라서 휴대전화 통신망을 통해 저장된 번호로 전파된다는 설명에 해당한다.","ce":["Card trap.A는 심비안 단말에서 악성 파일을 메모리 카드에 복사해 PC 감염을 시도하는 트로이목마로, 통신망 전화번호 전파와 다르다.","CommWarrior는 심비안 단말의 주소록 전화번호로 MMS를 보내고 블루투스로도 확산된 웜으로, 휴대전화 통신망을 통해 전파된 대표 사례이다.","Hobbles.A는 심비안 단말용 악성코드로, 저장된 전화번호로 통신망을 통해 퍼지는 전파 방식에 해당하지 않는다(공식 정답 기준).","Brador는 Windows Mobile(Pocket PC)용 백도어 트로이목마로, 원격 제어 포트를 여는 것이 특징이며 전화번호로 확산하지 않는다."],"rel":["1-19"],"box":"저장매체나 인터넷으로 전파되던 악성코드가 휴대전화 통신망으로 전파되기 시작하며, 휴대전화에 저장된 전화번호로 악성코드를 퍼트린다."},{"n":28,"s":"s2","q":"사용자마다 계정 및 패스워드를 설정하고 원격에서 텔넷으로 라우터에 접속할 때, 계정 및 패스워드를 이용하여 로그인 할 수 있도록 설정한 것은 무엇인가?","c":["Router(config)#username XXXX password XXXX\nRouter(config)#line vty 0 4\nRouter(config-line)#login local","Router#username XXXX password XXXX\nRouter(config)#line vty 0 4\nRouter(config-line)#login local","Router(config)#line vty 0\nRouter(config-if)#username XXXX password XXXX\nRouter(config-line)#login local","Router#username XXXX\nRouter(config)#password XXXX\nRouter(config)#line vty 0 4\nRouter(config-line)#login local"],"a":0,"e":"로컬 계정은 전역 설정 모드(config)에서 username ... password ... 로 생성하고, line vty 0 4 로 텔넷 가상 터미널에 진입해 login local 로 로컬 계정 인증을 적용한다. ②·④는 특권 모드(Router#)에서 username 을 입력해 문법상 불가하고, ③은 인터페이스 모드에서 계정을 생성해 틀리다.","ce":["전역 설정 모드에서 username/password로 로컬 계정을 만들고, line vty 0 4에서 login local을 적용하는 올바른 순서·모드이다.","username 명령은 전역 설정 모드(Router(config)#)에서만 입력할 수 있어 특권 모드(Router#)에서는 오류가 난다.","line vty 0은 가상 터미널 1개만 지정하고, username을 config-if(인터페이스) 모드에서 입력한 점과 프롬프트가 맞지 않는 점이 틀리다.","username과 password를 분리해 특권 모드·전역 모드에 따로 입력한 형식으로, username XXXX password XXXX는 한 줄로 전역 설정 모드에서 입력해야 한다."],"rel":["2-12"]},{"n":29,"s":"s2","q":"다음 화면은 DoS 공격을 실시한 TCP Dump이다. 네트워크 패킷들의 특징으로 보았을 때 무슨 공격을 한 것으로 보이는가?","c":["UDP 플러딩(flooding)","SYN 플러딩(flooding)","Bonk 공격","Land 공격"],"a":3,"e":"캡처된 모든 패킷의 출발지와 목적지 IP가 192.168.0.10으로 동일하므로 Land 공격이다. Land 공격은 출발지를 목적지와 같게 위조해 대상이 자기 자신에게 응답하도록 만들어 자원을 소모시킨다.","ce":["UDP 플러딩은 대량의 UDP 패킷을 보내는 공격인데, 덤프의 프로토콜은 ICMP(proto ICMP (1))이다.","SYN 플러딩은 TCP SYN 패킷을 대량 전송하는 공격으로, 덤프에는 TCP 패킷이 없고 ICMP echo request만 있다.","Bonk는 UDP 단편의 Fragment Offset을 조작해 재조합 오류를 일으키는 공격으로, 덤프의 offset은 0이고 단편화가 없다.","모든 패킷의 출발지와 목적지가 192.168.0.10으로 같으므로, 출발지를 목적지로 위조해 자기 자신에게 응답하게 만드는 Land 공격이다."],"rel":["2-3"],"box":"16:50:52.357500 IP (tos 0x0, ttl 64, id 15412, offset 0, flags [none], proto ICMP (1), length 28)\n    192.168.0.10 > 192.168.0.10: ICMP echo request, id 6409, seq 8527, length 8\n16:50:52.357536 IP (tos 0x0, ttl 64, id 61920, offset 0, flags [none], proto ICMP (1), length 28)\n    192.168.0.10 > 192.168.0.10: ICMP echo request, id 6409, seq 9295, length 8\n16:50:52.357561 IP (tos 0x0, ttl 64, id 28711, offset 0, flags [none], proto ICMP (1), length 28)\n    192.168.0.10 > 192.168.0.10: ICMP echo request, id 6409, seq 9807, length 8\n16:50:52.357585 IP (tos 0x0, ttl 64, id 22490, offset 0, flags [none], proto ICMP (1), length 28)\n    192.168.0.10 > 192.168.0.10: ICMP echo request, id 6409, seq 10319, length 8\n(각 패킷 아래 16진 덤프 생략)"},{"n":30,"s":"s2","q":"다음 중 OSI 7 계층의 데이터 링크 계층과 관련성이 가장 적은 것은?","c":["통신 경로상의 지점간(Link-to-Link)의 오류 없는 데이터 전송","멀티포인트 회선제어 기능","데이터 압축 및 암호화","정지-대기 흐름제어 기법"],"a":2,"e":"데이터 압축·암호화·코드 변환은 표현 계층(6계층)의 기능이다. 데이터 링크 계층은 인접 노드 간 오류 없는 전송, 회선 제어, 정지-대기·슬라이딩 윈도우 흐름 제어를 담당한다.","ce":["인접 노드(Link-to-Link) 간 오류 없는 전송은 오류 검출·재전송을 수행하는 데이터 링크 계층의 핵심 기능이다.","멀티포인트 회선에서 전송 권한을 조정하는 회선 제어(폴링·셀렉션)는 데이터 링크 계층 기능이다.","데이터 압축·암호화·코드 변환은 표현 계층(6계층)의 기능으로 데이터 링크 계층과 관련성이 가장 적다.","정지-대기(Stop-and-Wait)는 프레임 단위 흐름제어 기법으로 데이터 링크 계층에서 사용된다."],"rel":["2-1"]},{"n":31,"s":"s2","q":"Snort에서 Rule에 대한 정보제공을 위해 사용되며, 탐지에 영향이 없는 옵션의 명령어 형식은?","c":["msg","rawbytes","drop","reject"],"a":0,"e":"msg는 경보·로그에 출력할 메시지를 지정하는 일반(General) 옵션으로 탐지 여부에 영향을 주지 않는다. rawbytes는 디코딩 전 원본 페이로드를 검사하게 하는 페이로드 옵션이고, drop·reject는 탐지 시 패킷을 차단하는 룰 액션이다.","ce":["msg는 경보·로그에 표시할 메시지를 지정하는 일반(General) 옵션으로 탐지 여부에 영향을 주지 않고 정보 제공에만 쓰인다.","rawbytes는 전처리기 디코딩 전 원본 페이로드를 content 검사 대상으로 삼게 하는 페이로드 탐지 옵션으로 탐지 결과에 영향을 준다.","drop은 탐지된 패킷을 차단하고 로그를 남기는 인라인 모드 룰 액션으로 정보 제공용 옵션이 아니다.","reject는 패킷을 차단하면서 TCP RST나 ICMP Unreachable을 응답하는 룰 액션이다."],"rel":["2-11"]},{"n":32,"s":"s2","q":"다음 문장은 무선랜 환경에서 어떠한 AP(Access Point)를 설명하고 있는가?","c":["Normal AP","Rogue AP","Honeypot AP","Ad-hoc AP"],"a":1,"e":"관리자 승인 없이 비인가로 설치된 AP를 Rogue AP(불법 AP)라 하며 내부망 우회 침입 경로가 된다. Honeypot AP는 정상 AP로 위장해 사용자의 접속을 유도하는 공격용 AP이다.","ce":["Normal AP는 관리자가 승인·등록해 운영하는 정상 AP로 보안 위협의 원인으로 정의되지 않는다.","관리자 허가 없이 비인가로 설치돼 내부망 우회 침입 경로가 되는 AP를 Rogue AP(불법 AP)라 한다.","Honeypot AP는 정상 AP와 같은 SSID로 위장해 사용자의 접속을 유도하는 공격용 AP로, 내부 비인가 설치와는 개념이 다르다.","Ad-hoc은 AP 없이 단말끼리 직접 통신하는 방식으로 특정 AP 유형을 가리키지 않는다."],"rel":["2-10"],"box":"관리자의 허가없이 비인가적으로 설치되어 외부인 또는 내부인이 악의적인 목적으로 내부 네트워크에 침입 가능한 보안 위협성을 야기시킬 수 있는 AP"},{"n":33,"s":"s2","q":"자신의 컴퓨터가 인터넷을 통해 목적지를 찾아가면서 구간의 게이트웨이 정보나 걸리는 시간 등을 표시해 줌으로써 인터넷 경로상의 네트워크 경로를 파악할 수 있게 하는 명령어는?","c":["Tcpdump","Ping","Traceroute(Tracert)","Netstat"],"a":2,"e":"traceroute(윈도우 tracert)는 TTL 값을 1씩 늘리며 각 홉 라우터의 ICMP Time Exceeded 응답을 받아 경로와 구간별 지연 시간을 표시한다. ping은 도달 여부와 왕복 시간만, netstat은 로컬 연결 상태만 보여준다.","ce":["tcpdump는 인터페이스를 지나는 패킷을 캡처·출력하는 도구로, 경로상 게이트웨이를 추적하지 않는다.","ping은 ICMP Echo로 대상 도달 여부와 왕복 시간만 확인하며 중간 경로 정보는 보여주지 않는다.","traceroute(tracert)는 TTL을 1씩 늘려 각 홉의 ICMP Time Exceeded 응답을 받아 경유 게이트웨이와 구간별 지연 시간을 표시한다.","netstat은 로컬 시스템의 연결 상태·라우팅 테이블·포트 사용 현황을 보여줄 뿐 원격 경로를 추적하지 않는다."],"rel":["2-2"]},{"n":34,"s":"s2","q":"N-IDS가 수집하여 처리하는 패킷들에서 다음과 같은 형태의 패킷들의 발견되었다. 이에 대한 설명으로 가장 옳은 것은?","c":["S1 시스템이 D1 시스템에 비해 SYN flooding 공격을 시도하였다.","S1 시스템이 D1 시스템에 비해 TCP SYN 스캔을 시도하였다.","S1 시스템이 D1 시스템에 비해 TCP CONNECT 스캔을 시도하였다.","S1 시스템이 D1 시스템에 비해 Stealth 스캔을 시도하였다."],"a":1,"e":"S1이 SYN을 보내고 D1이 SYN/ACK(열린 포트)로 응답하면 S1이 ACK 대신 RST로 연결을 끊으며, 닫힌 포트(P6)는 RST/ACK로 응답하므로 half-open 방식의 TCP SYN 스캔이다. CONNECT 스캔은 3-way handshake를 완료(ACK)해야 하고, SYN flooding은 RST를 보내지 않는다.","ce":["SYN flooding은 응답을 받아도 RST·ACK를 보내지 않아 대상의 반개방 연결을 쌓는 공격인데, 로그에서 S1은 SYN/ACK에 RST로 즉시 연결을 끊고 있다.","SYN 전송 후 열린 포트의 SYN/ACK에는 RST로 끊고, 닫힌 포트는 RST/ACK로 응답받는 half-open 패턴이므로 TCP SYN 스캔이다.","CONNECT 스캔은 SYN/ACK에 ACK를 보내 3-way handshake를 완성해야 하는데, 로그에는 ACK 없이 RST만 있다.","Stealth 스캔(FIN·NULL·Xmas)은 SYN이 아닌 FIN 등 비정상 플래그를 보내는데, 로그의 탐침 패킷은 모두 SYN이다."],"rel":["2-4"],"box":"출발지IP | 목적지IP | 출발지포트 | 목적지포트 | TCP세그먼트\nS1 | D1 | P1 | P2 | SYN\nS1 | D1 | P3 | P4 | SYN\nD1 | S1 | P2 | P1 | SYN, ACK\nS1 | D1 | P1 | P2 | RST\nD1 | S1 | P4 | P3 | SYN, ACK\nS1 | D1 | P3 | P4 | RST\nS1 | D1 | P5 | P6 | SYN\nD1 | S1 | P6 | P5 | RST, ACK"},{"n":35,"s":"s2","q":"다음 중 세션 하이재킹(Session Hijacking)에 대한 설명으로 가장 옳지 않은 것은?","c":["클라이언트와 서버 간의 통신을 관찰할 수 있을 뿐만 아니라 신뢰(trust)를 이용한 세션은 물론 Telent, FTP 등 TCP를 이용한 거의 모든 세션의 탈취가 가능하다.","인증에 대한 문제점을 해결하기 위해 도입된 일회용 패스워드(OTP), Token Based authentication, Kerberos(토큰 기반 인증)을 이용한 세션의 탈취도 가능하다.","서버와 클라이언트가 TCP를 이용해서 통신을 하고 있을 때 RST 패킷을 보내 일시적으로 TCP 세션을 끊고, 시퀀스 넘버를 새로 생성하여 세션을 빼앗고 인증을 회피하는 공격이다.","실제 DNS 서버보다도 빨리 공격 대상에게 DNS 응답(response) 패킷을 보내 공격 대상이 잘못된 IP 주소로 이름 해석을 하도록 하여 잘못된 웹 접속을 유도하는 공격이다."],"a":3,"e":"④는 위조 DNS 응답으로 잘못된 IP 주소를 해석하게 하는 DNS 스푸핑의 설명이다. 세션 하이재킹은 이미 인증된 TCP 세션의 시퀀스 번호를 가로채 탈취하므로 OTP·Kerberos로 인증한 세션도 탈취될 수 있다.","ce":["세션 하이재킹은 통신을 관찰해 시퀀스 번호를 알아낸 뒤 신뢰 관계 세션뿐 아니라 Telnet·FTP 등 TCP 세션 대부분을 탈취할 수 있으므로 옳은 설명이다.","인증이 끝난 뒤의 세션을 가로채므로 OTP·토큰·Kerberos 같은 강한 인증을 쓴 세션도 탈취할 수 있어 옳은 설명이다.","RST로 세션을 일시적으로 끊고 새 시퀀스 번호로 재동기화해 세션을 빼앗는 것은 TCP 세션 하이재킹의 대표적 동작이므로 옳은 설명이다.","실제 DNS보다 먼저 위조 응답을 보내 잘못된 IP로 이름 해석을 유도하는 것은 DNS 스푸핑으로, 세션 하이재킹의 설명이 아니다."],"rel":["2-5"]},{"n":36,"s":"s2","q":"다음 문장에서 설명하고 있는 것은 무엇인가?","c":["Intrusion Prevention System","Screened Subnet","Knowledge-Base IDS","Singature-Base IDS"],"a":0,"e":"위협 트래픽을 탐지하는 데 그치지 않고 미리 정의한 정책에 따라 해당 패킷을 차단·제거하는 것은 IPS(침입방지시스템)이다. 지식·시그니처 기반 IDS는 탐지·경보까지만 수행한다.","ce":["IPS는 탐지에 그치지 않고 사전에 정의한 대응 정책에 따라 인라인에서 위협 패킷을 즉시 차단·제거하므로 지문의 설명과 일치한다.","Screened Subnet은 두 스크리닝 라우터 사이에 DMZ를 두는 방화벽 구축 구조로, 트래픽 탐지·대응 시스템의 명칭이 아니다.","지식(오용) 기반 IDS는 알려진 공격 지식과 비교해 탐지하고 경보를 발생시키는 데 그치며, 패킷을 직접 제거하지 않는다.","시그니처 기반 IDS는 공격 패턴(시그니처) 일치 여부로 탐지해 경보를 내는 시스템으로, 패킷을 스스로 차단하지 않는다(원문 'Singature'는 오탈자)."],"rel":["2-9"],"box":"의심스런 트래픽을 탐지할 뿐 아니라, 위협이 되는 트래픽을 발견하게 되는 어떻게 대응할 지를 미리 정의해 놓고 해당 패킷을 제거한다."},{"n":37,"s":"s2","q":"무선랜 보안에 대한 설명으로 가장 옳지 않은 것은?","c":["Open System 인증방식은 어떤 무선 단말이라도 AP를 경유하여 인터넷에 접속하도록 허용하는 방식을 의미하며, 실질적인 인증을 하지 않고 무선 단말과 AP간 전달되는 데이터가 평문 형태로 전달된다.","Shared Key(SK) 인증방식은 무선 단말 사용자가 AP에 설정된 키와 동일한 키를 입력하는 경우 AP를 경유하여 인터넷에 접속을 허용한다.","무선 단말과 AP간 전달되는 데이터를 암호화하는 경우 WEP 암호 방식이 이용될 수 있으며, 이 방식은 AES 대칭키 암호 알고리즘을 이용하여 매우 높은 강도의 비밀성을 제공한다.","RSN(Robust Security Network)에서는 WPA-Personal과 WPA-Enterprise 모드가 있는데, WPA-Personal 모드에서는 미리 설정된 비밀키를 이용하는 반면 WPA-Enterprise 모드에서는 RADIUS 서버를 이용한다."],"a":2,"e":"WEP는 RC4 스트림 암호와 24비트 IV를 사용하며 IV 재사용 등으로 쉽게 해독되는 취약한 방식이다. AES(CCMP)를 사용하는 것은 WPA2이다.","ce":["Open System 인증은 SSID만 맞으면 접속을 허용하는 사실상 무인증 방식이며, 별도 암호화 설정이 없으면 데이터가 평문으로 전달되므로 옳은 설명이다.","Shared Key 인증은 AP와 단말이 같은 WEP 키를 가졌는지 챌린지-응답으로 확인해 접속을 허용하므로 옳은 설명이다.","WEP는 AES가 아니라 RC4 스트림 암호와 24비트 IV를 사용하며, IV 재사용 등으로 쉽게 해독되는 취약한 방식이다. AES(CCMP)는 WPA2에서 사용한다.","RSN(802.11i)의 WPA-Personal은 사전 공유키(PSK)를, WPA-Enterprise는 802.1X/EAP와 RADIUS 인증 서버를 사용하므로 옳은 설명이다."],"rel":["2-10"]},{"n":38,"s":"s2","q":"클라우드 컴퓨팅 보안에 대한 설명으로 가장 옳지 않은 것은?","c":["가상화 시스템의 취약점을 상속한다.","정보 위탁에 따른 정보 유출의 가능성이 있다.","집중화로 보안 적용이 용이하다.","자원 공유 및 집중화에 따른 서비스 장애가 발생할 수 있다."],"a":2,"e":"클라우드는 자원과 데이터가 집중되어 한 번의 침해·장애가 다수 이용자에게 확산되는 위험이 있고, 멀티테넌트 환경으로 보안 적용이 복잡해진다. 따라서 보안 위협 관점의 설명으로 \"보안 적용이 용이하다\"는 옳지 않다.","ce":["클라우드는 하이퍼바이저·가상머신 위에서 동작하므로 VM 탈출 등 가상화 시스템의 취약점을 그대로 물려받아 옳은 설명이다.","데이터를 외부 사업자에게 위탁 저장·처리하므로 사업자 내부자나 침해로 인한 정보 유출 가능성이 있어 옳은 설명이다.","자원·데이터 집중은 한 번의 침해가 다수 이용자에게 확산되는 위험을 키우고, 멀티테넌트 환경으로 보안 적용이 오히려 복잡해진다. '용이하다'가 틀렸다.","자원 공유·집중화 구조에서는 한 지점의 장애가 다수 서비스 중단으로 이어질 수 있어 옳은 설명이다."],"rel":["1-12"]},{"n":39,"s":"s2","q":"다음 장비 중 네트워크 계층 장비를 바르게 설명한 것은?","c":["리피터 : 불분명해진 네트워크 신호세기를 다시 증가시키기 위한 장비이다.","더미 허브 : 데이터를 보낼 때 모든 곳에 데이터를 똑같이 복사해서 보낸다.","브리지 : 랜과 랜을 연결하는 네트워크 장치이다.","라우터 : 서로 다른 프로토콜을 사용하는 네트워크를 연결해주는 장비이다."],"a":3,"e":"라우터는 IP 주소 기반으로 경로를 결정해 서로 다른 네트워크를 연결하는 네트워크 계층(3계층) 장비이다. 리피터·더미 허브는 물리 계층(1계층), 브리지는 데이터 링크 계층(2계층) 장비이다.","ce":["리피터는 감쇠된 신호를 재생·증폭하는 물리 계층(1계층) 장비로 네트워크 계층 장비가 아니다.","더미 허브는 수신 신호를 모든 포트로 그대로 복사하는 물리 계층(1계층) 장비이다.","브리지는 MAC 주소 기반으로 LAN 세그먼트를 연결·필터링하는 데이터 링크 계층(2계층) 장비이다.","라우터는 IP 주소로 경로를 결정해 서로 다른 네트워크(프로토콜 환경)를 연결하는 네트워크 계층(3계층) 장비이므로 정답이다."],"rel":["2-1","2-12"]},{"n":40,"s":"s2","q":"RIP(Routing Information Protocol)는 Distance Vector 라우팅 알고리즘을 사용하고 매 30초마다 모든 전체 라우팅 테이블을 Active Interface로 전송한다. 원격 네트워크에서 RIP에 의해 사용되는 최적의 경로 결정 방법은 무엇인가?","c":["HoP count","Routed information","TTL(Time To Live)","Link length"],"a":0,"e":"RIP는 목적지까지 거치는 라우터 수인 홉 카운트(Hop count)를 메트릭으로 최단 경로를 선택하며 최대 15홉(16은 도달 불가)까지 허용한다. TTL은 IP 패킷의 수명 필드로 경로 결정 메트릭이 아니다.","ce":["RIP는 목적지까지 거치는 라우터 수(홉 카운트)를 메트릭으로 최단 경로를 선택하며, 최대 15홉까지 허용하고 16홉은 도달 불가로 본다.","Routed information은 라우팅 프로토콜의 경로 결정 메트릭이 아니며, 'routed'는 IP처럼 라우팅되는 프로토콜을 가리키는 표현이다.","TTL은 IP 패킷이 무한 순환하지 않도록 라우터를 지날 때마다 1씩 줄어드는 수명 필드로, 경로 선택 기준이 아니다.","링크 길이(물리적 거리)는 RIP의 메트릭이 아니다. 대역폭·지연 등 링크 속성을 반영하는 것은 OSPF의 cost 같은 링크 상태 방식이다."],"rel":["2-12"]},{"n":41,"s":"s3","q":"클라이언트(웹 브라우저)와 서버(웹 서버)간에 개인정보, 금융정보, 패스워드 등의 중요정보를 안전하게 전송하기 위해 사용되는 암호 채널은?","c":["S/MIME","PGP","SSH","SSL"],"a":3,"e":"SSL(현 TLS)은 웹 브라우저와 웹 서버 사이에 암호화 채널을 구성해 HTTPS로 중요정보를 보호한다. S/MIME·PGP는 전자우편 보안, SSH는 원격 접속용 보안 셸이다.","ce":["S/MIME은 인증서 기반으로 전자우편 본문·첨부를 암호화·서명하는 메일 보안 표준으로 웹 통신 채널이 아니다.","PGP는 전자우편·파일 암호화와 서명에 쓰이는 보안 프로그램으로 웹 브라우저-서버 채널에 쓰이지 않는다.","SSH는 원격 로그인·명령 실행·파일 전송을 암호화하는 보안 셸로, 브라우저-웹 서버 간 채널이 아니다.","SSL(현 TLS)은 브라우저와 웹 서버 사이에 암호화 채널을 구성해 HTTPS로 개인·금융정보, 패스워드를 보호한다."],"rel":["2-7"]},{"n":42,"s":"s3","q":"ebXML의 구성요소가 아닌 것은?","c":["비즈니스 프로세스","EDI 문서","핵심컴포넌트","전송, 교환 및 패키징"],"a":1,"e":"ebXML은 비즈니스 프로세스, 핵심 컴포넌트, 거래당사자 정보(CPP/CPA), 등록저장소(Registry/Repository), 메시지 전송·교환·패키징으로 구성된다. 기존 EDI 문서는 ebXML이 대체하려는 대상으로 구성요소가 아니다.","ce":["비즈니스 프로세스(BPSS)는 거래 절차를 모델링한 ebXML 구성요소이다.","EDI 문서는 ebXML이 XML 기반으로 대체하려는 기존 전자문서 교환 방식으로, ebXML 구성요소가 아니다.","핵심 컴포넌트(Core Component)는 문서의 재사용 가능한 데이터 요소를 정의하는 ebXML 구성요소이다.","메시지 전송·교환·패키징(ebMS)은 SOAP 기반 메시지 서비스로 ebXML 구성요소이다."],"rel":["3-14"]},{"n":43,"s":"s3","q":"다음 중 리버스도메인에 대한 설명이 잘못된 것은?","c":["도메인이름을 IP주소로 변환하기 위해 네임서버에 설정하는 특수 도메인이다.","IP주소를 도메인 이름으로 변환하기 위해 네임서버에 설정하는 특수 도메인이다.","\"역질의\"라고도 한다.","IP주소에 해당하는 숫자와 특수 문자열 in-addr.arpa로 구성되어 있다."],"a":0,"e":"리버스 도메인은 IP 주소를 도메인 이름으로 변환(역방향 조회, PTR 레코드)하기 위한 in-addr.arpa 특수 도메인이다. 도메인 이름을 IP 주소로 변환하는 것은 정방향 조회(A 레코드)이다.","ce":["도메인 이름을 IP 주소로 변환하는 것은 정방향 조회(A 레코드)이다. 리버스 도메인은 그 반대인 IP→도메인 변환에 쓰인다.","리버스 도메인은 IP 주소를 도메인 이름으로 변환(PTR 레코드)하기 위해 네임서버에 설정하는 특수 도메인이므로 옳은 설명이다.","IP로 이름을 찾는 역방향 조회이므로 '역질의(Reverse Lookup)'라고도 불러 옳은 설명이다.","IPv4 주소를 역순으로 적고 in-addr.arpa를 붙여(예: 1.0.168.192.in-addr.arpa) 구성하므로 옳은 설명이다."],"rel":["3-7"]},{"n":44,"s":"s3","q":"다음 중 SSL(Secure Socket Layter) 프로토콜에 대한 설명으로 잘못된 것은?","c":["웹 서버와 브라우저간의 안전한 통신을 위해 넷스케이프 사에 의해 개발되었다.","세션계층에 적용되며, 응용계층의 FTP, TELNET, HTTP 등의 프로토콜의 안전성 보장을 위해 사용된다.","SSL 프로토콜은 TCP/IP상의 444/tcp 포트만을 사용하여야 한다.","SSL을 사용하기 위해서는 우리가 흔히 사용하는 URL 표기 방식인 \"http://*\" 대신에 \"https://*\"를 사용해야 한다."],"a":2,"e":"HTTPS는 443/tcp를 기본으로 사용하며, SSL/TLS는 특정 포트에 고정되지 않고 SMTPS·IMAPS 등 여러 응용 프로토콜 포트에 적용된다. 따라서 \"444/tcp 포트만 사용\"은 틀린 설명이다.","ce":["SSL은 1994년경 넷스케이프사가 웹 서버-브라우저 간 보안 통신을 위해 개발했으므로 옳은 설명이다.","SSL은 전송 계층과 응용 계층 사이(세션 계층 수준)에서 동작해 HTTP·FTP·TELNET 등 응용 프로토콜을 보호할 수 있으므로 옳은 설명이다.","HTTPS의 기본 포트는 443/tcp이고, SSL/TLS는 SMTPS(465)·IMAPS(993) 등 여러 포트에 적용된다. '444/tcp 포트만'은 포트 번호와 한정 모두 틀렸다.","웹에서 SSL을 적용할 때 URL 스킴은 http:// 대신 https://를 사용하므로 옳은 설명이다."],"rel":["2-7"]},{"n":45,"s":"s3","q":"다음은 보안 기술에 대해 설명한 것이다. 괄호 안에 들어갈 가장 올바른 것은?","c":["DRM(Digital Rights Management)","스테가노그래피(Steganography)","디지털 워터마크(Digital Watermark)","보안토큰(Security Token)"],"a":0,"e":"DRM은 암호화·라이선스 관리로 디지털 콘텐츠의 불법 복제·유통을 막고 저작권자의 이익과 권리를 관리하는 기술·서비스이다. 워터마크는 저작권 정보를 삽입해 사후 추적·증명하는 기술로 이용 통제 기능이 없다.","ce":["DRM은 암호화와 라이선스(사용 권한) 관리로 디지털 콘텐츠의 불법 복제·유통을 막고 저작권자의 수익을 관리하는 기술·서비스이다.","스테가노그래피는 이미지·음성 등에 비밀 메시지를 숨겨 존재 자체를 감추는 정보 은닉 기술로, 콘텐츠 이용 통제와 무관하다.","디지털 워터마크는 콘텐츠에 저작권 정보를 삽입해 사후 소유권 증명·추적에 쓰며, 복제·유통을 사전에 통제하거나 수익을 관리하지는 않는다.","보안토큰은 인증서·개인키를 안전하게 저장하는 하드웨어 장치(HSM)로 디지털 콘텐츠 보호 기술이 아니다."],"rel":["3-12"],"box":"(   )은(는) 디지털 콘텐츠의 불법 복제와 유포를 막고 저작권 보유자의 이익과 권리를 보호해주는 기술과 서비스를 말한다. 전자책, 음악, 비디오, 게임 등등 각종 디지털 콘텐츠의 불법 유통과 복제를 방지하고, 보호된 콘텐츠로 인해 저작권 당사자에게 발생하는 이익을 관리하여 주는 기술과 서비스이다."},{"n":46,"s":"s3","q":"Spam Assassin은 들어오는 메일을 미리 설정해 둔 패턴에 따라서 스팸으로 의심되면 삭제를 하거나 분리시키는 기능을 하는 스팸필터링 도구이다. 이러한 도구에서 스팸 필터링 분류기준이 아닌 것은?","c":["헤더검사","본문내용","IP 필터링","첨부파일만 필터링 가능"],"a":2,"e":"SpamAssassin은 메일 헤더 검사, 본문 내용 검사, 첨부파일 검사 등 메시지 내용에 대한 규칙 점수로 스팸을 판별하는 콘텐츠 필터이다. 공식 정답은 IP 필터링으로, 송신 IP 차단은 MTA·방화벽 단계의 기능으로 분류된다.","ce":["SpamAssassin은 From·Received·Subject 등 메일 헤더 규칙을 검사해 스팸 점수를 매기므로 분류 기준에 해당한다.","본문 내용의 키워드·패턴과 베이지안 필터로 스팸 여부를 점수화하므로 분류 기준에 해당한다.","송신 IP 차단은 MTA·방화벽 단계의 기능으로 보아 공식 정답은 IP 필터링이다. 다만 SpamAssassin도 DNSBL(IP 블랙리스트) 규칙을 쓰므로 논란 소지가 있다.","SpamAssassin은 첨부파일 형식·내용도 검사 대상에 포함하므로 분류 기준에 해당하는 것으로 본다(보기 표현 '만'은 원문 그대로, 공식 정답 기준)."],"rel":["3-2"]},{"n":47,"s":"s3","q":"디지털 증거의 특성을 설명한 것으로 가장 적절하지 않은 것은?","c":["내용 자체가 변하지 않는 한 어느 매체에 저장되어도 동일하다.","간단한 조작만으로 정보를 변경하거나 삭제할 수 있다.","컴퓨터 디스크에 항상 안전하게 보관할 수 있다.","대량의 정보가 저장 매체에 저장되고 대량으로 유통될 수 있다."],"a":2,"e":"디지털 증거는 휘발성·취약성이 있어 쉽게 변경·삭제·훼손되므로 해시값 확보와 증거 보관 연속성(CoC) 관리가 필요하다. 따라서 \"항상 안전하게 보관할 수 있다\"는 특성에 맞지 않는다.","ce":["디지털 정보는 내용이 같으면 어느 매체에 복제해도 비트 단위로 동일하므로(매체 독립성) 옳은 설명이다.","간단한 조작으로 변경·삭제가 가능한 취약성이 있어 해시값 확보 등 무결성 입증이 필요하므로 옳은 설명이다.","디지털 증거는 휘발성·취약성 때문에 쉽게 훼손·삭제되므로 쓰기 방지·해시·증거 보관 연속성(CoC) 관리가 필요하다. '항상 안전하게 보관'은 틀렸다.","저장 매체의 대용량화로 대량의 정보가 저장·유통될 수 있다는 대량성 특성으로 옳은 설명이다."],"rel":["3-11"]},{"n":48,"s":"s3","q":"다음 암호화 구현에 대한 설명으로 잘못된 것은?","c":["대칭키 알고리즘 이용시에는 키 길이를 128비트 이상으로 사용하는 것이 안전하다.","비대칭키 알고리즘 이용시에는 키 길이를 2,048비트 이상으로 사용하는 것이 안전하다.","입력된 메시지는 취약한 AES(Advanced Encryption Standard) 대신 안전한 DES(Data Encryption Standard) 알고리즘으로 암호화한다.","해쉬함수 사용시 Salt 값을 사용한다."],"a":2,"e":"DES는 56비트 키로 전수조사에 취약해 사용이 권고되지 않으며, 안전한 대체 알고리즘이 AES이다. 설명의 안전성 관계가 뒤바뀌었다.","ce":["대칭키 알고리즘은 전수조사 공격을 고려해 128비트 이상 키 사용이 권고되므로 옳은 설명이다.","RSA 등 비대칭키 알고리즘은 2,048비트 이상 키 사용이 권고되므로 옳은 설명이다.","DES는 56비트 키로 전수조사에 취약해 사용이 권고되지 않고, AES가 안전한 표준이다. 보기는 두 알고리즘의 안전성을 뒤바꿔 틀렸다.","해시에 Salt를 더하면 같은 패스워드도 다른 해시값이 되어 레인보우 테이블·사전 공격을 어렵게 하므로 옳은 설명이다."],"rel":["4-2"]},{"n":49,"s":"s3","q":"다음 웹 서비스 공격 유형으로 적절한 것은?","c":["XSS","SSRF","HTTP Smuggling","CSRF"],"a":2,"e":"Content-Length와 Transfer-Encoding: chunked 헤더를 동시에 넣어 프런트엔드와 백엔드 서버가 요청 경계를 다르게 해석하게 만들고, 뒤에 숨긴 두 번째 요청(GET /home)을 끼워 넣는 HTTP Request Smuggling 공격이다.","ce":["XSS는 웹 페이지에 스크립트를 삽입해 열람자 브라우저에서 실행시키는 공격으로, 요청에 스크립트가 없다.","SSRF는 서버가 공격자가 지정한 내부·외부 URL로 요청을 보내게 만드는 공격으로, 헤더 충돌을 이용하지 않는다.","Content-Length와 Transfer-Encoding: chunked를 함께 넣어 프런트엔드·백엔드가 요청 경계를 다르게 해석하게 하고, 숨긴 GET 요청을 끼워 넣는 HTTP Request Smuggling이다.","CSRF는 인증된 사용자가 의도치 않은 요청을 보내도록 유도하는 공격으로, 요청 경계 해석 차이와 무관하다."],"rel":["3-6"],"box":"POST / HTTP/1.1\nHost: vulnerable-website.com\nContent-Length: 20\nTransfer-Encoding: chunked\n0\nGET /home HTTP/1.1\nHost: attacker-website.com\nFoo: X"},{"n":50,"s":"s3","q":"다음 문장에서 설명하는 데이터베이스 보안 솔루션 종류는?","c":["데이터베이스 백업 솔루션","데이터베이스 감사 솔루션","데이터베이스 암호화 솔루션","데이터베이스 접근 제어 솔루션"],"a":3,"e":"보안정책에 따라 DB 접근 허가·로깅을 결정하고, 독립 서버(게이트웨이 방식)로 구성되어 이중화가 필요하며 네트워크를 우회한 접근에 취약한 것은 DB 접근제어 솔루션의 특징이다. 암호화 솔루션은 저장 데이터 자체를 암호화하는 방식이다.","ce":["DB 백업 솔루션은 데이터 손실에 대비해 복제본을 만드는 것으로, 접근 허가·로깅 결정이나 우회 접근 취약점과 무관하다.","DB 감사 솔루션은 쿼리를 수집·기록·분석하는 데 중점을 두며, 사용허가 여부를 결정해 통제하는 기능이 핵심이 아니다.","DB 암호화 솔루션은 저장 데이터 컬럼·파일을 암호화하는 방식으로, 독립 서버 이중화·네트워크 우회 취약점과 같은 특징을 갖지 않는다.","정책에 따라 접근 허가·로깅을 결정하고, 독립 서버(게이트웨이) 방식이라 이중화가 필요하며 우회 접근에 취약한 것은 DB 접근제어 솔루션의 특징이다."],"rel":["3-8"],"box":"- 조직의 보안정책 구성에 따라 사용허가 및 로깅 여부를 결정한다.\n- 독립된 서버로 구축되기 때문에 이중화 구성을 필요로 한다.\n- 네트워크를 우회하여 접근하는 경우 보안 취약점이 발생한다.\n- 독립된 서버로 다중 인스턴스에 대한 통제가 가능하다."},{"n":51,"s":"s3","q":"다음 중 익명 FTP에 대한 보안 대책으로 틀린 것은?","c":["익명의 사용자에게 쓰기권한을 부여하여 자유롭게 파일 업로드 및 다운로드 하여 사용할 수 있게 한다.","반드시 사용하지 않을 경우 서비스를 제거한다.","핵심 디렉터리의 권한을 설정하여 접근하지 못하도록 설정한다.","익명의 사용자가 접근하여 파일을 다운로드 할 수 있으므로 개인정보나 중요정보는 보이지 않도록 마스킹 처리 한다."],"a":0,"e":"익명 FTP 사용자에게 쓰기 권한을 주면 악성파일 업로드, 불법 자료 유통, 디스크 고갈 공격에 악용될 수 있다. 익명 FTP는 불필요하면 제거하고, 사용 시 읽기 전용으로 제한해야 한다.","ce":["익명 사용자에게 쓰기 권한을 주면 악성파일 업로드, 불법 자료 유통, 디스크 고갈에 악용된다. 익명 FTP는 읽기 전용으로 제한해야 한다.","익명 FTP를 사용하지 않으면 서비스를 제거하는 것이 공격 표면을 줄이는 가장 확실한 대책으로 옳다.","핵심 디렉터리 권한을 제한해 익명 사용자가 접근하지 못하게 하는 것은 올바른 대책이다.","익명 사용자는 누구나 파일을 받을 수 있으므로 공개 영역의 개인·중요정보는 마스킹하거나 두지 않는 것이 올바른 대책이다."],"rel":["3-1"]},{"n":52,"s":"s3","q":"SQL 인젝션(injection) 공격에 대한 설명으로 가장 적절하지 않은 것은?","c":["클라이언트의 입력 값을 조작하여 사용자 인증 절차를 우회하는 등의 SQL 문을 생성하여 서버의 DB를 공격하는 기법이다.","준비된 명령문(prepared statement) 등을 이용하는 안전한 코딩 기법을 활용하여 SQL 인젝션 공격을 감소시킬 수 있다.","SQL 인젝션 공격에 대응하는 방법으로는 클라이언트부터 전달된 입력값을 점검없이 SQL문으로 변환하지 않고 DBMS에서 처리될 수 있는 특수문자가 포함되어 있는지 검사하는 방법이 있다.","SQL 인젝션 공격에 대응하는 방법으로 허용되지 않는 입력값에 대한 블랙리스트 방식으로 차단하는 방법을 사용하는 것이 화이트리스트 방식보다 높은 보안성을 제공한다."],"a":3,"e":"블랙리스트는 알려진 위험 문자만 차단하므로 변형·우회 입력에 취약하고, 허용된 값만 통과시키는 화이트리스트 방식이 더 높은 보안성을 제공한다. 설명의 우열이 반대이다.","ce":["입력값을 조작해 인증 우회용 SQL(예: ' or 1=1--)을 만들어 DB를 공격하는 것이 SQL 인젝션의 정의이므로 옳은 설명이다.","Prepared Statement는 쿼리 구조와 입력값을 분리해 입력이 SQL 문법으로 해석되지 않게 하므로 효과적인 대응이다.","입력값을 그대로 SQL에 넣지 않고 ', --, ; 등 DBMS 특수문자 포함 여부를 검사하는 것은 올바른 대응 방법이다.","블랙리스트는 알려진 위험 문자만 막아 변형·인코딩 우회에 취약하고, 허용 값만 통과시키는 화이트리스트가 더 안전하다. 우열이 뒤바뀌었다."],"rel":["3-6"]},{"n":53,"s":"s3","q":"다음 중 관리자 페이지 노출 취약점을 제거하기 위한 점검 방법으로 가장 적절하지 않은 것은?","c":["추측하기 쉬운 관리자 페이지 경로(/damin, /manager, /system 등) 접근을 시도하여 관리자 페이지가 노출되는지 확인한다.","추측하기 쉬운 포트(7001, 8080, 8443, 8888 등) 접속을 시도하여 관리자 페이지가 노출되는지 확인한다.","관리자 페이지 로그인 후 식별된 하위 페이지(/admin/main.asp, /admin/menu.html 등) URL을 새 세션에서 직접 입력하여 인증과정 없이 접근 가능한지 확인한다.","관리자 페이지 로그인 후 세션이 발행된 페이지의 리퀘스트를 취득하여 일정 시간이 지난 후에 재전송 시 정상 처리가 되는지 확인한다."],"a":3,"e":"④는 세션 만료·재전송(세션 관리 취약점) 점검 방법으로 관리자 페이지 노출 여부 점검과 거리가 멀다. ①~③은 추측 가능한 경로·포트 접근이나 인증 우회로 관리자 페이지가 노출되는지를 확인하는 방법이다.","ce":["/admin, /manager 등 추측 쉬운 경로에 접근해 관리자 페이지 노출 여부를 확인하는 것은 올바른 점검 방법이다.","7001·8080·8443 등 관리 콘솔이 자주 쓰는 포트로 접속해 관리자 페이지가 노출되는지 확인하는 것은 올바른 점검 방법이다.","로그인 후 알아낸 하위 페이지 URL을 새 세션에서 직접 입력해 인증 없이 접근되는지 보는 것은 관리자 페이지 인증 우회 점검으로 옳다.","일정 시간 후 요청을 재전송해 정상 처리되는지 보는 것은 세션 만료·재전송(세션 관리) 취약점 점검으로, 관리자 페이지 노출 점검과 거리가 멀다."],"rel":["3-4"]},{"n":54,"s":"s3","q":"전자 입찰 시 필요한 보안 요구사항과 거리가 먼 것은?","c":["비밀성","공평성","무결성","동시성"],"a":3,"e":"전자입찰 보안 요구사항은 독립성, 비밀성(입찰 내용 기밀), 무결성, 공평성, 안전성 등이다. 동시성은 전자입찰 보안 요구사항에 해당하지 않는다.","ce":["입찰 내용이 개찰 전까지 공개되지 않아야 하므로 비밀성은 전자입찰의 핵심 보안 요구사항이다.","모든 입찰자가 동등한 조건에서 참여하고 결과가 공정해야 하므로 공평성은 보안 요구사항이다.","제출된 입찰서가 위·변조되지 않아야 하므로 무결성은 보안 요구사항이다.","전자입찰 보안 요구사항은 독립성·비밀성·무결성·공평성·안전성 등이며, 동시성은 여기에 포함되지 않는다."],"rel":["3-13"]},{"n":55,"s":"s3","q":"다음 문장에서 설명하는 것은?","c":["이상행위 탐지시스템(FDS)","침입탐지시스템(IDS)","블록체인(Blockchain)","SET(Secure Electronic Transaction)"],"a":0,"e":"FDS(Fraud Detection System)는 결제자의 접속·거래 정보를 수집·분석해 이상 거래 패턴을 탐지·차단하는 시스템이다. IDS는 네트워크·호스트 침입을 탐지하며 결제 이상거래 탐지가 목적이 아니다.","ce":["FDS는 결제자의 접속 환경·거래 정보를 수집해 정상 패턴을 만들고, 벗어나는 이상 결제를 실시간 탐지·차단하는 시스템이다.","IDS는 네트워크·호스트의 침입 행위를 탐지하는 시스템으로, 결제 패턴 분석을 통한 이상 거래 차단이 목적이 아니다.","블록체인은 분산 원장에 거래 기록을 해시 체인으로 연결해 위변조를 어렵게 하는 기술로, 이상 결제 탐지 방식이 아니다.","SET은 이중서명·인증서로 카드 결제 정보를 보호하는 전자결제 프로토콜로, 빅데이터 기반 이상 거래 탐지와 무관하다."],"rel":["3-13"],"box":"결제자의 다양한 정보를 수집해 패턴을 만든 후 패턴과 다른 이상 결제를 잡아내고 결제 경로를 차단하는 보안 방식으로, 보안 솔루션에 의존하던 기존 보안과 달리 빅데이터를 바탕으로 적극적인 보안 개입을 하는 것이 특징이다."},{"n":56,"s":"s3","q":"다음 중 FTP 서버의 Bounce Attack에 대해 바르게 설명한 것은?","c":["분산 반사 서비스 거부 공격(DRDoS)으로 악용할 수 있다.","접근이 FTP의 PORT command를 악용하여 외부에서 직접 접근 불가능한 내부망 컴퓨터상의 포트에 FTP 서버를 통해 접근할 수 있다.","login id를 입력 후 다음 응답 코드를 줄 때까지의 반응 속도 차이를 이용하여 실제 계정이 존재하는지 여부를 추측할 수 있다.","active, passive 모드를 임의로 변경할 수 있다."],"a":1,"e":"FTP Bounce 공격은 PORT 명령에 제3의 IP·포트를 지정해 FTP 서버가 대신 연결하게 만들어, 외부에서 직접 접근할 수 없는 내부 호스트를 스캔하거나 접근하는 공격이다. ③은 응답 시간 차이를 이용한 계정 추측 공격으로 Bounce 공격과 무관하다.","ce":["DRDoS는 정상 서버에 출발지를 위조한 요청을 보내 응답을 피해자에게 집중시키는 공격으로, FTP Bounce의 본질(PORT 명령 악용 우회 접근)과 다르다.","PORT 명령에 제3의 IP·포트를 지정해 FTP 서버가 대신 연결하게 만들어, 외부에서 직접 접근 불가능한 내부 호스트에 접근·스캔하는 것이 Bounce 공격이다.","로그인 응답 시간 차이로 계정 존재 여부를 추측하는 것은 타이밍 기반 계정 열거 공격으로 Bounce 공격이 아니다.","Active/Passive 모드는 클라이언트 설정으로 선택하는 데이터 연결 방식이며, 이를 임의 변경하는 것이 Bounce 공격의 정의가 아니다."],"rel":["3-1"]},{"n":57,"s":"s3","q":"다음 문장이 설명하는 스팸메일 대응 방안으로 가장 옳은 것은?","c":["procmail","Sender Policy Framework","Sanitizer","Spam Assassin"],"a":1,"e":"SPF는 발송 도메인이 DNS(TXT 레코드)에 허용 발송 서버 IP를 등록하고, 수신 서버가 실제 발송 서버와 대조해 발신자 위변조를 판별하는 기술이다. procmail·Sanitizer는 메일 처리·필터링 도구, SpamAssassin은 내용 기반 스팸 필터이다.","ce":["procmail은 수신 메일을 규칙에 따라 분류·전달하는 메일 처리(MDA) 도구로, DNS 기반 발신 서버 검증 기능이 없다.","SPF는 도메인이 허용 발송 서버 IP를 DNS TXT 레코드에 등록하고, 수신 서버가 실제 발송 서버와 대조해 발신자 위변조를 판별하는 기술이다.","Sanitizer는 메일의 위험한 첨부파일·코드를 제거하는 필터로, 발송 서버의 DNS 등록 여부를 확인하지 않는다.","SpamAssassin은 헤더·본문 규칙 점수로 스팸을 판별하는 콘텐츠 필터로, 지문처럼 DNS 등록 발송 서버를 검증하는 기술 자체가 아니다."],"rel":["3-2"],"box":"메일 헤더에 표시된 발송정보가 실제 메일을 발송한 서버와 일치하는지를 비교하며 발송자 정보의 위변조 여부를 파악할 수 있는 기술이다. 발송자의 서버를 DNS에 미리 등록하고 수신자의 서버에 메일이 도착하면 등록된 서버로부터 발신되었는지 확인 후 스팸 메일을 차단하는 기술이다."},{"n":58,"s":"s3","q":"DNS 서버가 알고 있는 모든 유형의 레코드를 리턴하고 DNS 관련 DoS(서비스 거부) 공격에 많이 이용되는 질의 유형은?","c":["NS","ANY","A","TXT"],"a":1,"e":"ANY 질의는 해당 도메인의 모든 레코드를 한꺼번에 응답받아 요청 대비 응답 크기가 커서 DNS 증폭(DRDoS) 공격에 주로 악용된다. NS·A·TXT는 특정 유형의 레코드만 반환한다.","ce":["NS 질의는 해당 도메인의 권한 네임서버 레코드만 반환하므로 응답 크기가 제한적이다.","ANY 질의는 도메인의 모든 레코드를 한꺼번에 반환해 요청 대비 응답이 매우 커서 DNS 증폭(DRDoS) 공격에 주로 악용된다.","A 질의는 도메인의 IPv4 주소 레코드만 반환하는 일반 조회이다.","TXT 질의는 SPF 등 텍스트 레코드만 반환하며, 모든 유형을 리턴하는 질의가 아니다."],"rel":["3-7"]},{"n":59,"s":"s3","q":"다음 중 랜섬웨어(Rnasomware)에 대한 설명과 거리가 먼 것은?","c":["컴퓨터나 스마트폰에 저장된 파일을 암호화한 뒤 복호화 키를 주는 대가로 돈을 요구하는 악성 프로그램이다.","Browlock인 경우 수사 기관을 사칭한 뒤 허가받지 않은 사이트를 방문한 대가로 벌금을 지불하도록 유도하는 등의 피해가 발생한다.","암호 시스템인 RSA 서명을 위조해 암호화한 통신을 가로채는 악성 프로그램이다.","Cryptolocker인 경우 사용자의 파일에 강력한 암호화 알고리즘을 적용하여, 복호화 키에 대한 비용을 지불하지 않고는 파일 복구가 불가능하게 만드는 등의 피해가 발생한다."],"a":2,"e":"랜섬웨어는 파일·화면을 암호화하거나 잠근 뒤 금전을 요구하는 악성코드이다. RSA 서명을 위조해 암호 통신을 가로채는 것은 중간자 공격 유형으로 랜섬웨어의 설명이 아니다.","ce":["파일을 암호화한 뒤 복호화 키를 대가로 금전을 요구하는 것이 랜섬웨어의 정의이므로 옳은 설명이다.","Browlock은 브라우저를 잠그고 수사기관을 사칭해 벌금 명목으로 돈을 요구하는 화면 잠금형 랜섬웨어로 옳은 설명이다.","RSA 서명을 위조해 암호 통신을 가로채는 것은 중간자(MITM) 공격 유형으로 랜섬웨어와 무관하다. 랜섬웨어는 RSA 등을 파일 암호화 키 보호에 이용한다.","Cryptolocker는 RSA·AES로 파일을 암호화해 비용을 지불하지 않으면 복구할 수 없게 만든 대표 랜섬웨어로 옳은 설명이다."],"rel":["1-9"],"flag":"발문 \"Rnasomware\" 원문 오탈자(Ransomware)"},{"n":60,"s":"s3","q":"취약점 제거를 위해 보안사항을 고려하여 안전한 코드를 작성하였다. 다음 코드를 통해 차단할 수 있는 보안취약점은 무엇인가?","c":["SQL Injection 취약점","XSS(Cross Site Scripting)","부적절한 에러처리를 통해 정보 노출","경로 조작(Path Traversal) 취약점"],"a":1,"e":"시험지 이미지에 제시 코드가 수록되어 있지 않아 코드 자체의 근거는 확인할 수 없으며, 공식 정답은 XSS이다. XSS는 출력값의 <, >, \", ' 등을 HTML 엔티티로 치환(이스케이프)하는 코드로 차단한다.","ce":["SQL Injection 차단 코드는 Prepared Statement나 SQL 특수문자 검증을 사용한다. 원문 코드가 누락되어 코드 근거는 확인할 수 없으며 공식 정답 기준으로 오답이다.","원문 코드가 누락되어 코드 근거는 없으나 공식 정답은 XSS이다. XSS는 출력값의 <, >, \", ' 등을 HTML 엔티티로 치환하는 코드로 차단한다.","에러 처리 취약점은 예외 발생 시 상세 오류 대신 일반화된 메시지를 반환하는 코드로 막는다. 원문 코드 누락으로 판단 근거 없음 — 공식 정답 기준 오답.","경로 조작은 ../ 등 경로 문자를 제거·정규화하고 허용 경로만 쓰는 코드로 막는다. 원문 코드 누락으로 판단 근거 없음 — 공식 정답 기준 오답."],"rel":["3-6"],"flag":"원문에 제시 코드 누락(이미지·기존 txt 모두 없음)"},{"n":61,"s":"s4","q":"다음 중 메시지 인증방식의 해시(HASH) 함수 사용 기법이 아닌 것은?","c":["키 공유 해시함수 사용","암호화된 해시함수 사용","공개키 암호체계에서 송신자 개인키 해시함수 사용","공개키 암호화된 해시함수 사용"],"a":3,"e":"해시를 이용한 메시지 인증은 공유 비밀값을 포함한 해시(HMAC), 대칭키로 암호화한 해시, 송신자 개인키로 암호화한 해시(전자서명) 방식으로 이루어진다. 공개키로 암호화한 해시는 누구나 생성할 수 있어 송신자를 인증하지 못한다.","ce":["송·수신자가 공유한 비밀값을 메시지와 함께 해시하는 방식(HMAC 등)은 비밀값을 아는 자만 만들 수 있어 메시지 인증에 쓰인다.","해시값을 공유 대칭키로 암호화해 첨부하면 키를 가진 자만 생성·검증할 수 있어 메시지 인증 기법에 해당한다.","해시값을 송신자 개인키로 암호화하는 전자서명 방식은 송신자 인증과 무결성을 함께 제공하는 메시지 인증 기법이다.","공개키는 누구나 알 수 있으므로 공개키로 암호화한 해시는 제3자도 만들 수 있어 송신자를 인증하지 못한다. 메시지 인증 기법이 아니다."],"rel":["4-5"]},{"n":62,"s":"s4","q":"다음 문장에서 설명하고 있는 공개키 기반구조의 구성요소는?","c":["정책승인기관(Policy Approving Authority)","정책인증기관(Policy Certification Authority)","인증기관(Certification Authority)","등록기관(Registration Authority)"],"a":1,"e":"시험지 이미지에 설명 지문이 수록되어 있지 않으며 공식 정답은 PCA이다. PCA는 PAA 아래에서 자신의 도메인 정책을 수립하고 하위 CA의 공개키를 인증하는 기관이며, PAA는 최상위 정책 승인, CA는 사용자 인증서 발급, RA는 사용자 신원 확인·등록을 담당한다.","ce":["PAA는 PKI 최상위 기관으로 전체 정책을 수립·승인하고 하위 PCA를 인증한다. 원문 지문이 누락되어 공식 정답(PCA) 기준으로 오답이다.","원문 지문은 누락됐으나 공식 정답은 PCA이다. PCA는 PAA 아래에서 자신의 도메인 정책을 수립하고 하위 CA의 공개키를 인증·관리한다.","CA는 사용자 인증서를 발급·폐지하는 기관이다. 원문 지문 누락으로 판단 근거 없음 — 공식 정답 기준 오답.","RA는 사용자 신원을 확인하고 인증서 발급 요청을 CA에 중개하는 등록기관이다. 원문 지문 누락으로 판단 근거 없음 — 공식 정답 기준 오답."],"rel":["4-7"],"flag":"원문에 설명 지문 누락"},{"n":63,"s":"s4","q":"KDC를 이용한 키 분배 방식에 대한 설명 중 옳지 않은 것은?","c":["사용자들은 사전에 KDC와 마스터 키를 공유해야 한다.","사용자의 요청이 있는 경우, KDC는 일회용 세션키를 생성한다.","사용자들 간에는 사전에 공유한 비밀정보가 필요하지 않다.","KDC는 일회용 세션키를 사용자의 공개키로 암호화하여 전송한다."],"a":3,"e":"KDC 방식은 대칭키 기반으로, KDC가 생성한 세션키를 각 사용자와 사전에 공유한 마스터키(대칭키)로 암호화해 전달한다. 공개키로 세션키를 암호화하는 것은 공개키 기반 키 분배 방식이다.","ce":["KDC 방식에서 각 사용자는 사전에 KDC와 마스터키(대칭키)를 공유해 두어야 하므로 옳은 설명이다.","사용자가 통신을 요청하면 KDC가 해당 통신에만 쓸 일회용 세션키를 생성해 배포하므로 옳은 설명이다.","각 사용자는 KDC와만 키를 공유하면 되고 사용자 간에는 사전 공유 비밀이 필요 없어, n명일 때 n개 키로 관리가 가능하다. 옳은 설명이다.","KDC는 대칭키 기반으로 세션키를 각 사용자와 공유한 마스터키로 암호화해 전달한다. 사용자의 공개키로 암호화하는 것은 공개키 기반 키 분배 방식이다."],"rel":["4-12"]},{"n":64,"s":"s4","q":"다음 중 해시함수의 조건이 아닌 것은?","c":["압축","일방향","생일공격","충돌회피"],"a":2,"e":"해시함수는 임의 길이 입력을 고정 길이로 줄이는 압축성, 역산이 불가능한 일방향성, 충돌 저항성을 갖춰야 한다. 생일공격은 충돌을 찾는 공격 기법으로 조건이 아니다.","ce":["임의 길이 입력을 고정 길이 출력으로 줄이는 압축성은 해시함수의 기본 조건이다.","해시값으로부터 원래 입력을 찾을 수 없는 일방향성(역상 저항성)은 해시함수의 조건이다.","생일공격은 생일 역설을 이용해 약 2^(n/2)번 시도로 충돌을 찾는 공격 기법으로, 해시함수가 갖춰야 할 조건이 아니다.","같은 해시값을 내는 두 입력을 찾기 어려운 충돌 저항성(충돌 회피)은 해시함수의 조건이다."],"rel":["4-5"]},{"n":65,"s":"s4","q":"다음 중 전자상거래에서 이중서명에 대한 설명으로 잘못된 것은?","c":["카드결제에서 계좌정보나 구매물품 목록의 노출을 방지하는 효과가 있다.","이중서명의 검증은 위변조 여부 확인일 뿐 사용자 인증은 포함되지 않는다.","판매자가 결제정보를 위변조하는 것을 방지한다.","이중서명에 대한 검증은 판매자가 수행한다."],"a":1,"e":"SET 이중서명은 주문정보(OI)와 결제정보(PI)의 해시를 연결해 고객의 개인키로 서명하므로, 검증 시 무결성뿐 아니라 서명한 고객의 인증도 함께 이루어진다. 이를 통해 판매자는 결제정보를, 은행은 주문정보를 보지 못한다.","ce":["이중서명으로 판매자는 결제정보(PI)를, 은행은 주문정보(OI)를 보지 못하므로 계좌정보·구매목록 노출 방지 효과가 있어 옳은 설명이다.","이중서명은 고객의 개인키로 서명하므로 검증 과정에서 무결성뿐 아니라 서명한 고객(사용자) 인증도 함께 이루어진다. '인증 미포함'이 틀렸다.","결제정보 해시가 서명에 묶여 있어 판매자가 결제정보를 위변조하면 검증에 실패하므로 옳은 설명이다.","판매자는 받은 OI와 PI 해시(PIMD)로 이중서명을 검증하므로(은행도 PI 측 검증) 판매자가 검증을 수행한다는 설명은 옳다."],"rel":["4-6","3-10"]},{"n":66,"s":"s4","q":"Rabin 암호시스템에서 암호문의 제곱근을 구하여 복호화하면 평문 후보가 몇 개 나오는가?","c":["1","2","3","4"],"a":3,"e":"Rabin 암호는 n=p×q에서 C=M² mod n으로 암호화하며, 복호화 시 p와 q 각각에서 2개씩의 제곱근을 중국인의 나머지 정리로 결합해 4개의 평문 후보가 나온다. 그중 하나를 중복 비트 등 부가 정보로 선택한다.","ce":["Rabin 복호화는 제곱근을 구하는 과정이라 해가 하나로 정해지지 않으며, 평문 후보는 1개가 아니라 4개이다.","mod p와 mod q에서 각각 2개씩 제곱근이 나오며, 이를 조합하면 2개가 아닌 4개의 후보가 된다.","제곱근 조합은 2×2=4개이므로 3개가 될 수 없다.","n=p×q에서 mod p, mod q 각각 2개의 제곱근을 중국인의 나머지 정리로 결합하면 4개의 평문 후보가 나오며, 중복 비트 등으로 올바른 하나를 고른다."],"rel":["4-4"]},{"n":67,"s":"s4","q":"다음은 접근 통제 모델에 대한 설명이다. ㉠~㉢에 들어갈 말을 옳게 나열한 것은?","c":["㉠ RBAC, ㉡ MAC, ㉢ DAC","㉠ RBAC, ㉡ DAC, ㉢ MAC","㉠ DAC, ㉡ MAC, ㉢ RBAC","㉠ MAC, ㉡ DAC, ㉢ RBAC"],"a":3,"e":"주체·객체의 보안 등급을 비교하고 관리자만 분류를 변경하는 것은 MAC, 신분 기반으로 ACL을 쓰는 것은 DAC, 두 모델의 단점을 보완해 역할에 기반하는 것은 RBAC이다.","ce":["㉠은 보안 등급 비교·관리자 분류가 특징인 MAC이고 RBAC가 아니다. ㉡은 ACL 기반 DAC, ㉢이 RBAC이므로 세 자리가 모두 어긋났다.","㉠(등급 비교)은 MAC, ㉢(역할 기반)은 RBAC인데 둘을 뒤바꿨다. ㉡ DAC만 맞다.","㉠에 DAC, ㉡에 MAC을 넣어 둘을 뒤바꿨다. 등급 비교는 MAC, 신분·ACL 기반은 DAC이다.","등급 비교와 관리자 분류는 MAC(㉠), 신분 기반 ACL은 DAC(㉡), 두 모델의 단점을 보완한 역할 기반은 RBAC(㉢)이다."],"rel":["4-10"],"box":"- ( ㉠ ) 모델은 주체와 객체의 등급을 비교하여 접근 권한을 부여하는 방식으로서, 관리자만이 정보자원의 분류를 설정하고 변경하는 방법이다.\n- 일반적으로 ACL을 사용하는 ( ㉡ ) 모델은 주체의 신분에 근거하여 접근 통제를 적용한다.\n- ( ㉢ ) 모델은 ( ㉠ ) 모델과 ( ㉡ ) 모델의 단점을 보완한 접근 통제 모델로서, 역할에 기반을 두고 접근을 통제하는 모델이다."},{"n":68,"s":"s4","q":"다음 중 ACL(Acces Control List)에 대한 설명으로 옳지 않은 것은?","c":["어떤 사용자들이 ACL 타켓에서 어떤 행위를 할 수 있는지 나타낸다.","ACL은 관련된 객체에 대하여 접근 행렬에서 열의 내용을 반영한다.","접근 권한의 취소가 쉽다.","개시자 또는 개시자의 그룹이 다수일 때 편리하다."],"a":3,"e":"ACL은 객체 기준(접근 행렬의 열)으로 주체별 권한을 기록하므로 객체별 권한 취소는 쉽지만, 주체(개시자)가 많아지면 목록이 길어져 관리가 불편하다. 주체가 많을 때 편리한 것은 주체 기준의 자격 목록(Capability List)이다.","ce":["ACL은 객체(타깃)마다 어떤 주체가 어떤 행위(읽기·쓰기·실행)를 할 수 있는지 기록하므로 옳은 설명이다.","ACL은 객체 기준으로 접근 행렬의 한 열(해당 객체에 대한 모든 주체의 권한)을 저장한 것이므로 옳은 설명이다.","객체별로 목록이 모여 있어 특정 객체에 대한 권한을 찾아 취소하기 쉬우므로 옳은 설명이다.","ACL은 주체(개시자)가 많아질수록 각 객체의 목록이 길어져 관리가 불편하다. 주체가 많을 때 유리한 것은 주체 기준의 자격 목록(Capability List)이다."],"rel":["4-10"]},{"n":69,"s":"s4","q":"다음 중 전자서명의 특징으로 볼 수 없는 것은?","c":["위조불가","부인불가","데이터 불법유출 불가","변경불가"],"a":2,"e":"전자서명은 위조 불가, 서명자 인증, 부인 방지, 변경 불가, 재사용 불가를 제공한다. 전자서명 자체는 메시지를 암호화하지 않으므로 기밀성(불법 유출 방지)은 제공하지 않는다.","ce":["전자서명은 서명자의 개인키로만 생성할 수 있어 타인이 위조할 수 없는 위조불가 특성을 가진다.","서명자만 생성 가능하므로 서명자가 나중에 서명 사실을 부인할 수 없는 부인불가 특성을 가진다.","전자서명은 메시지를 암호화하지 않고 서명값만 붙이므로 기밀성(불법 유출 방지)을 제공하지 않는다. 기밀성은 별도 암호화로 확보해야 한다.","서명된 문서가 변경되면 해시가 달라져 검증에 실패하므로 변경불가 특성을 가진다."],"rel":["4-6"]},{"n":70,"s":"s4","q":"8차 기약 다항식으로 만든 LFSR(Linear Feedback Shift Register)의 출력이 가질 수 있는 주기는 어느 것인가?","c":["8","16","17","127"],"a":2,"e":"n차 LFSR의 최대 주기는 2^n−1로, 8차 원시 다항식이면 255이다. 기약(비원시) 다항식이면 주기는 255의 약수가 되며, 보기 중 255의 약수인 17이 가능한 주기이다(127은 2^7−1로 약수가 아님).","ce":["8은 255(=2^8−1)의 약수가 아니므로 8차 기약 다항식 LFSR의 주기가 될 수 없다. 주기는 255의 약수여야 한다.","16은 255의 약수가 아니므로 불가능하다. LFSR 주기는 2^n 형태가 아니라 2^n−1의 약수로 정해진다.","n차 기약 다항식 LFSR의 주기는 2^n−1의 약수이며, 8차이면 255=3×5×17의 약수이다. 보기 중 255의 약수는 17뿐이다.","127은 2^7−1로 7차 원시 다항식의 최대 주기이며, 255의 약수가 아니어서 8차 LFSR의 주기가 될 수 없다."],"rel":["4-2"]},{"n":71,"s":"s4","q":"다음 중 '커버로스(Kerberos)'의 세 가지 요소에 속하지 않는 것은?","c":["사용자","클라이언트","SSO(Single Sign On)서버","서버"],"a":0,"e":"Kerberos의 세 요소는 클라이언트, 서버, 그리고 인증을 중계하는 KDC(인증 서버)이며, 보기의 SSO 서버는 KDC 역할을 가리킨다. 사용자(사람)는 프로토콜의 구성 요소로 분류되지 않는다.","ce":["사용자(사람)는 Kerberos 프로토콜의 구성 요소로 분류되지 않는다. Kerberos 3요소는 클라이언트·서버·KDC(인증 서버)이다.","클라이언트는 티켓을 요청하고 서비스를 이용하는 주체로 Kerberos 3요소에 속한다.","보기의 SSO 서버는 인증과 티켓 발급을 중계하는 KDC(AS+TGS)를 가리키며 Kerberos 3요소에 속한다.","서버(응용 서버)는 티켓을 검증하고 서비스를 제공하는 Kerberos 3요소 중 하나이다."],"rel":["2-8"]},{"n":72,"s":"s4","q":"해시(HASH)된 패스워드를 알아내기 위한 레인보우 테이블 공격을 방어하기 위해 암호에 추가된 임의의 값은 무엇인가?","c":["Hash","Salt","Extender","Rebar"],"a":1,"e":"Salt는 패스워드마다 임의의 값을 덧붙여 해시하므로, 같은 패스워드라도 해시값이 달라져 미리 계산한 레인보우 테이블을 무력화한다.","ce":["해시는 입력을 고정 길이 값으로 바꾸는 함수 자체로, 레인보우 테이블 방어를 위해 추가하는 임의 값이 아니다.","Salt는 패스워드마다 임의 값을 덧붙여 해시하므로 같은 패스워드도 해시값이 달라져, 미리 계산한 레인보우 테이블을 무력화한다.","Extender는 패스워드 해시 보안 용어가 아니다. 반복 해시로 계산 비용을 늘리는 것은 키 스트레칭이라 한다.","Rebar(철근)는 암호 기술 용어가 아니며 레인보우 테이블 방어와 무관하다."],"rel":["4-5"]},{"n":73,"s":"s4","q":"다음 중 AES-CCM 운영모드의 특징이 아닌 것은?","c":["암호화 블록의 크기가 128bit 이다.","메시지 인증은 GHASH를 사용한다.","패딩(Padding)이 불필요하다.","인증 암호화 운영모드에 해당된다."],"a":1,"e":"CCM은 CTR 모드로 암호화하고 CBC-MAC으로 메시지 인증을 수행하는 인증 암호화 모드이다. GHASH를 사용하는 것은 GCM 모드이다.","ce":["CCM은 AES의 128비트 블록 크기를 그대로 사용하는 운영 모드이므로 옳은 특징이다.","CCM은 CBC-MAC으로 메시지 인증을 수행한다. GHASH(GF(2^128) 곱셈 기반)를 쓰는 것은 GCM 모드이다.","CCM은 CTR 모드로 암호화해 키스트림과 XOR하므로 평문 패딩이 필요 없다.","CCM은 CTR 암호화와 CBC-MAC을 결합해 기밀성과 무결성을 함께 제공하는 인증 암호화(AEAD) 모드이다."],"rel":["4-3"]},{"n":74,"s":"s4","q":"다음 중 키 분배(Key Distriution) 프로토콜과 관련 없는 것은?","c":["키 분배 센터(KDC, Key Distriution Center)는 비밀키를 만들어서 대칭키 암호화 통신을 원하는 사람들에게 키를 나누어 주는 역할을 한다.","키를 분배 받는 모든 사람은 키 분배 센터(KDC, Key Distriution Center)를 신뢰해야 한다.","같은 키를 소유하는 관련된 사용자들은 관리기관(TA, Trusted Authority)을 제외하고는 정보가 누설되지 않도록 하여 비밀정보를 보호해야 한다.","키 관리기관은 사내 사용자가 담당하는 역할에 근거하여 자원에 대한 접근을 관리한다."],"a":3,"e":"역할에 근거해 자원 접근을 관리하는 것은 역할기반 접근통제(RBAC)의 설명으로 키 분배와 무관하다. ①~③은 KDC가 비밀키를 생성·분배하고, 참여자가 KDC(TA)를 신뢰하며 키를 비밀로 유지해야 한다는 키 분배 프로토콜의 요건이다.","ce":["KDC가 비밀키(세션키)를 생성해 대칭키 통신을 원하는 사용자들에게 나눠 주는 것은 키 분배 프로토콜의 핵심 동작이다.","KDC가 모든 키를 생성·분배하므로 참여자 모두가 KDC를 신뢰해야 한다는 것은 키 분배 방식의 전제이다.","같은 키를 가진 사용자들은 TA를 제외한 누구에게도 키를 누설하지 않아야 한다는 것은 키 분배의 비밀 유지 요건이다.","역할(직무)에 근거해 자원 접근을 관리하는 것은 역할기반 접근통제(RBAC)의 설명으로, 키 분배 프로토콜과 관련이 없다."],"rel":["4-12"],"flag":"발문 \"Distriution\" 원문 오탈자(Distribution)"},{"n":75,"s":"s4","q":"다음 중 접근통제의 원칙에 대한 설명으로 올바르지 않은 것은?(문제 오류로 확정답안 발표시 모두 정답처리 되었습니다. 여기서는 1번을 누르면 정답 처리 됩니다.)","c":["시스템 주체에게 권한을 부여할 때에는 조직의 업무효율을 떨어뜨리지 않게 주체의 업무에 필요로 하는 만큼 충분한 권한이 부여되어야 한다.","경영자나 관리자 한 사람이 업무의 발생, 승인, 변경, 확인, 배포 등을 처음부터 끝까지 처리할 수 없도록 해야 한다.","보안정책에 따른 접근 허용된 주체와 주체의 접근 가능한 접근통제 규칙을 설정하고, 접근규칙에 해당하지 않는 모든 접근에 대해서는 위반으로 간주한다.","금지된 주체와 객체의 리스트들에 대해서 미리 접근통제 규칙을 설정하고, 접근 통제 규칙에 설정되지 않은 모든 접근에 대해서는 허용한다."],"a":0,"e":"최소 권한 원칙에 따라 업무 수행에 필요한 최소한의 권한만 부여해야 하므로 \"충분한 권한\"은 원칙과 거리가 있다. 다만 ②(직무분리), ③(화이트리스트), ④(블랙리스트)도 접근통제 방식의 설명이라 문항 오류로 전항 정답 처리되었다.","ce":["최소 권한 원칙상 업무에 필요한 최소한의 권한만 부여해야 하므로 '충분한 권한'은 옳지 않다. 다만 문항 오류로 전항 정답 처리되었다.","한 사람이 업무의 발생부터 배포까지 처리하지 못하게 하는 것은 직무분리 원칙으로 옳은 설명이나, 문항 오류로 이 보기도 정답 처리되었다.","허용 규칙만 정하고 나머지는 위반으로 보는 화이트리스트(기본 거부) 방식의 설명이다. 문항 오류로 이 보기도 정답 처리되었다.","금지 규칙만 정하고 나머지는 허용하는 블랙리스트(기본 허용) 방식으로, 보안상 권장되지 않지만 방식 설명 자체로 출제 논란이 있어 전항 정답 처리되었다."],"rel":["4-10"],"flag":"문제 오류 — 확정답안 전항 정답 처리"},{"n":76,"s":"s4","q":"다음 문장은 송신자 \"A\"가 수신자 \"B\"에게 메시지를 보낼 때, 발생할 수 있는 보안 위협에 대응하는 보안기술을 설명한 것이다. 각각의 보안서비스로 알맞게 나타낸 것은?","c":["ㄱ. 기밀성, ㄴ. 인증, ㄷ. 무결성","ㄱ. 가용성, ㄴ. 무결성, ㄷ. 기밀성","ㄱ. 부인봉쇄, ㄴ. 가용성, ㄷ. 무결성","ㄱ. 무결성, ㄴ. 인증, ㄷ. 기밀성"],"a":3,"e":"메시지가 변경 없이 전송되었는지 확인하는 것은 무결성, 송신자가 A임을 확인하는 것은 인증, 전송 중 노출에 대응하는 것은 기밀성이다.","ce":["ㄱ(변경 없이 전송)은 무결성, ㄷ(노출 대응)은 기밀성인데 둘을 뒤바꿨다. ㄴ 인증만 맞다.","ㄱ을 가용성, ㄴ을 무결성으로 잘못 연결했다. 가용성은 필요할 때 서비스를 쓸 수 있는 성질로 메시지 변경 확인과 무관하다.","ㄱ을 부인봉쇄, ㄴ을 가용성, ㄷ을 무결성으로 연결해 세 항목이 모두 틀렸다.","변경 여부 확인은 무결성(ㄱ), 송신자가 A임을 확인하는 것은 인증(ㄴ), 전송 중 노출 대응은 기밀성(ㄷ)이다."],"rel":["5-1"],"box":"ㄱ. \"A\"로부터 \"B\"에게 전송된 메시지가 변경 없이 전송되었는지를 확인하는 보안서비스\nㄴ. 수신자 \"B\"가 받은 메시지가 분명히 송신자 \"A\"가 보낸 것인가를 확인하는 보안서비스\nㄷ. 전송 중의 메시지가 공격자에게 노출되는 것에 대응하는 보안서비스"},{"n":77,"s":"s4","q":"다음 문장은 어떤 인증기법을 설명하고 있는가?","c":["IEEE 802.1x","IEEE 802.1i","Wi-Fi Protected Access","Extensible Authentication Protocol"],"a":0,"e":"IEEE 802.1X는 포트 기반 네트워크 접근 제어 표준으로 EAP·RADIUS를 이용해 사용자 인증과 동적 키 관리를 지원한다. EAP는 802.1X가 사용하는 인증 프레임워크 프로토콜 자체이며, WPA는 무선 보안 규격이다.","ce":["IEEE 802.1X는 포트 기반 네트워크 접근 제어 표준으로 EAP·RADIUS를 이용해 사용자 인증, 동적 키 관리, 계정 관리를 지원한다.","IEEE 802.11i는 무선랜 보안 강화 표준(RSN, WPA2)으로 802.1X를 인증에 활용하지만, 포트 기반 접근 제어 인증기법 자체는 아니다('802.1i'는 존재하지 않는 표기).","WPA는 Wi-Fi Alliance의 무선랜 보안 규격(TKIP 등)으로, 포트 기반 접근 제어 인증 표준이 아니다.","EAP는 다양한 인증 방식을 담는 인증 프레임워크 프로토콜로, 802.1X가 그 위에서 포트 기반 접근 제어를 수행한다. 지문의 IEEE 표준 인증기법은 802.1X이다."],"rel":["2-10","2-8"],"box":"무선 네트워크에서 기기를 인증하는 IEEE표준 인증기법으로서, 사용자 ID 인증과 동적 키 관리 및 계정을 지원한다. PAP, CHAP, RADIUS, PEAP, WEP 등의 프로토콜들이 사용되며, 포트를 기반으로 네트워크 접근을 제어한다.","flag":"보기 원문 \"802.lx/802.li/Wifi Protected Acces\" 오탈자 교정"},{"n":78,"s":"s4","q":"다음 중 Kerberos V4의 단점을 개선한 Kerberos V5의 장점으로 옳지 않은 것은 무엇인가?","c":["Kerberos V4는 암호화 시스템으로 DES 만을 사용하였지만, Kerberos V5는 모든 종류의 암호화 시스템을 사용할 수 있다.","Kerberos V4는 인터넷 프로토콜(IP) 주소 외에 다른 특정 네트워크 주소를 사용하지 못하였지만, Kerberos V5는 어떤 유형의 네트워크 주소로 사용될 수 있다.","Kerberos V4는 인증서버로부터 클라이언트로 가는 메시지에 패스워드에 기초한 키로 암호화된 내용을 포함하고 있어 패스워드 공격(Password attacks)에 취약하였으나, Kerberos V5는 메시지에 암호화된 내용을 포함하지 않아 패스워드 공격에 취약하지 않다.","Kerberos V4의 티켓 유효기간(Ticket lifetime)의 값은 최대 시간이 제한되어 있었으나, Kerberos V5는 유효기간이 따로 없다."],"a":2,"e":"Kerberos V5도 AS가 클라이언트에게 보내는 응답을 패스워드에서 유도한 키로 암호화하므로 오프라인 패스워드 추측 공격 위험이 여전히 남아 있다. V5는 암호 알고리즘 선택, 다양한 주소 체계, 티켓 유효기간 확장을 지원하도록 개선되었다.","ce":["V4는 DES만 사용했지만 V5는 암호 유형 식별자를 두어 여러 암호 알고리즘을 선택할 수 있게 개선되었으므로 옳은 설명이다.","V4는 IP 주소만 지원했으나 V5는 주소 유형·길이를 태그로 지정해 다양한 네트워크 주소를 쓸 수 있으므로 옳은 설명이다.","V5도 AS가 클라이언트에게 보내는 응답을 패스워드에서 유도한 키로 암호화하므로 오프라인 패스워드 추측 공격 위험이 남아 있다. '취약하지 않다'가 틀렸다.","V4의 티켓 수명은 8비트(5분 단위, 약 21시간)로 제한됐지만 V5는 시작·종료 시각을 명시해 임의로 길게 지정할 수 있어 옳은 설명으로 본다."],"rel":["4-12","2-8"]},{"n":79,"s":"s4","q":"다음은 무엇에 대한 설명인가?","c":["타원 곡선 전자 서명","DSS","RSA","KCDSA"],"a":1,"e":"DSS(Digital Signature Standard)는 1994년 NIST가 제정한 전자서명 표준으로 슈노어·엘가말 기반의 DSA와 SHA-1을 사용한다. KCDSA는 국내 표준 전자서명, RSA는 소인수분해 기반 방식이다.","ce":["타원 곡선 전자서명(ECDSA)은 타원곡선 이산대수 문제 기반 서명으로, 1994년 표준·SHA-1·엘가말 기반 DSA라는 설명과 맞지 않는다.","DSS는 1994년 NIST가 제정한 전자서명 표준으로, 슈노어·엘가말 기반 DSA와 SHA-1을 사용하며 RSA를 배제했다.","RSA는 소인수분해 문제 기반 알고리즘으로, 지문은 오히려 RSA를 배제했다고 설명한다.","KCDSA는 한국정보보호센터 주도로 개발된 국내 표준 전자서명 알고리즘으로, 미국 1994년 표준이 아니다."],"rel":["4-6"],"box":"전자서명과 관련한 대표적인 표준으로 1994년 미국에서 만들어진 표준이다. 이것은 DSA(Digital Signature Algorithm)를 사용하는데, DSA는 슈노어(Schnorr)와 엘가말(엘가마)의 알고리즘을 기반으로 하며, 서명 생성이나 암호키 생성에서는 SHA-1을 이용한다. NIST가 안전성과 특허 사용료를 이유로 기존의 기업과 정보 기관에서 널리 사용하고 있는 RSA 방식을 배제하고, ElGamal 알고리즘을 사용하여 차별화하고 있다."},{"n":80,"s":"s4","q":"다음에서 설명하는 블랙암호 알고리즘은 무엇인가?","c":["SEED","HIGHT","ARIA","TDEA"],"a":2,"e":"ARIA는 128비트 블록에 128/192/256비트 키를 사용하는 국내 표준(KS X 1213) 블록 암호이다. SEED는 KS X 1213이 아닌 별도 표준이고, HIGHT는 64비트 블록 경량 암호, TDEA는 64비트 블록의 3중 DES이다.","ce":["SEED는 128비트 블록·128비트 키(이후 256비트 추가) 국내 블록 암호로 표준 번호가 KS X 1213이 아니다.","HIGHT는 64비트 블록·128비트 키의 경량 블록 암호로, 입출력 128비트 조건과 맞지 않는다.","ARIA는 128비트 블록에 128/192/256비트 키를 쓰는 국내 표준(KS X 1213) 블록 암호로 지문과 일치한다.","TDEA(3DES)는 64비트 블록에 DES를 3번 적용하는 알고리즘으로, 블록 크기와 표준이 모두 맞지 않는다."],"rel":["4-2"],"box":"입출력 크기(bit) : 128\n비밀키 크기(bit) : 128/192/256\n참조규격 : KATS KS X 1213-1","flag":"발문 \"블랙암호\" 원문 오탈자(블록암호)"},{"n":81,"s":"s5","q":"개인정보의 가명·익명처리 시 개인정보 일부 또는 전부를 대체하는 일반화 방법으로 다음 설명에 해당되는 기술은?","c":["상하단코딩(Top and bottom coding)","제어 라운딩(Controlled rounding)","랜덤 라운딩(Random rounding)","일반 라운딩(Rounding)"],"a":3,"e":"시험지 이미지에 설명 지문이 수록되어 있지 않으며 공식 정답은 일반 라운딩이다. 일반 라운딩은 수치 데이터를 올림·내림·반올림 기준으로 일정 단위로 변환하는 일반화 기법이고, 랜덤 라운딩은 임의 기준으로, 제어 라운딩은 행·열 합계가 일치하도록 라운딩한다.","ce":["상하단코딩은 분포 양 끝의 극단값을 일정 기준값으로 묶는 기법이다. 원문 설명 지문이 누락되어 공식 정답(일반 라운딩) 기준 오답이다.","제어 라운딩은 라운딩 후에도 행·열 합계가 원래 합계와 일치하도록 조정하는 기법이다. 원문 지문 누락 — 공식 정답 기준 오답.","랜덤 라운딩은 올림·내림 기준을 임의로 정해 라운딩하는 기법이다. 원문 지문 누락 — 공식 정답 기준 오답.","원문 지문은 누락됐으나 공식 정답은 일반 라운딩이다. 수치를 올림·내림·반올림 등 정해진 기준으로 일정 단위로 변환하는 일반화 기법이다."],"rel":["5-7"],"flag":"원문에 설명 지문 누락"},{"n":82,"s":"s5","q":"다음 중 전기통신사업자와 전기통신사업자의 전기통신역무를 이용하여 정보를 제공하거나 정보의 제공을 매개하는 자로서, 정보보호 관리체계 인증을 의무적으로 받아야 할 대상이 아닌 것은?","c":["집적정보통신시설 사업자","정보통신서비스 부문 3개월간 일일평균 이용자수 100만명 이상인 사업자","정보통신서비스 부문 100억원 이상인 사업자","연간 매출액 또는 세입 등이 1,000억원 이상인 사업자"],"a":3,"e":"ISMS 의무대상은 ISP, 집적정보통신시설(IDC) 사업자, 정보통신서비스 부문 전년도 매출 100억원 이상 또는 직전 3개월 일평균 이용자 100만명 이상 사업자, 연간 매출액 또는 세입 1,500억원 이상인 상급종합병원·학교 등이다. 기준 금액은 1,000억원이 아니라 1,500억원이다(개정 여부 확인).","ce":["집적정보통신시설(IDC) 사업자는 ISMS 인증 의무대상으로 법에 명시되어 있다.","정보통신서비스 부문 직전 3개월 일평균 이용자 100만명 이상인 사업자는 ISMS 의무대상이다.","정보통신서비스 부문 전년도 매출액 100억원 이상인 사업자는 ISMS 의무대상이다.","연간 매출액·세입 기준은 1,000억원이 아니라 1,500억원 이상(상급종합병원·재학생 1만명 이상 학교 등)이므로 틀린 기준이다(개정 여부 확인)."],"rel":["5-11"]},{"n":83,"s":"s5","q":"다음 정보보호 교육과 관련한 설명으로 잘못된 것은?","c":["교육의 시기, 기간, 대상, 내용, 방법 등의 내용이 포함된 연간 정보보호 교육 계획을 술비하면서, 대상에는 정보보호 관리체계 범위 내 임직원을 포함시켜야 하고, 외부용역 인력은 제외해도 무방하다.","교육에는 정보보호 및 정보보호 관리 체계 개요, 보안사고 사례, 내부 규정 및 절차, 법적 책임 등의 내용을 포함하고 일반 임직원, 책임자, IT 및 정보보호 담당자 등 각 직무별 전문성 제고에 적합한 교육내용 및 방법을 정하여야 한다.","연 1회 이상 교육을 시행하고 정보보호 정책 및 절차의 중대한 변경, 조직 내외부 보안사고 발생, 관련 법규 변경 등의 사유가 발생할 경우 추가 교육을 수행해야 한다.","교육 내용에는 구성원들이 무엇을 해야 하며, 어떻게 할 수 있는지에 대한 것을 포함해야 하며, 가장 기본적인 보안 단계의 실행에서부터 좀 더 고급의 전문화된 기술에 이르기까지 다양한 단계로 나누어 구성할 수 있다."],"a":0,"e":"ISMS-P 인증기준(2.2.4)상 교육 대상에는 관리체계 범위 내 임직원뿐 아니라 정보자산에 접근하는 외부 용역 인력도 포함해야 한다. 따라서 외부용역 인력을 제외해도 된다는 설명이 틀리다.","ce":["ISMS-P 인증기준 2.2.4상 교육 대상에는 임직원뿐 아니라 정보자산에 접근하는 외부 용역 인력도 포함해야 하므로 '제외해도 무방'이 틀렸다.","교육 내용에 관리체계 개요·사고 사례·내부 규정·법적 책임을 포함하고 직무별로 차별화하도록 하는 것은 인증기준 요구사항에 부합한다.","연 1회 이상 정기 교육과 정책 변경·사고·법규 변경 시 추가 교육을 요구하는 것은 인증기준 내용과 일치한다.","구성원이 해야 할 일과 방법을 포함하고 기초부터 전문 기술까지 단계별로 구성하는 것은 올바른 교육 설계 원칙이다."],"rel":["5-11"],"flag":"① 원문 \"술비\" 오탈자(수립) — 원문 유지"},{"n":84,"s":"s5","q":"다음 클라우드 SaaS 서비스 중 반드시 클라우드 보안인증 표준등급으로 인증 받아야되는 서비스가 아닌 것은?","c":["전자결재 서비스","개인정보 유통 보안 서비스","소프트웨어 개발환경(개발, 배포, 운영, 관리 등)","이메일/메신저 서비스"],"a":3,"e":"공식 정답은 ④로, 당시 클라우드 보안인증 SaaS 등급 기준에서 전자결재·개인정보 처리·보안 서비스·개발환경 등 중요 데이터를 다루는 서비스는 표준등급 대상이었고 이메일/메신저 서비스는 해당되지 않았다. 등급 구분은 이후 고시 개정으로 변경될 수 있다(개정 여부 확인).","ce":["전자결재 서비스는 조직의 중요 업무 데이터를 처리하므로 당시 기준에서 표준등급 인증 대상으로 분류되었다(개정 여부 확인).","개인정보 유통·보안 관련 서비스는 개인정보 등 중요 데이터를 다뤄 표준등급 인증 대상으로 분류되었다(개정 여부 확인).","개발·배포·운영·관리 등 소프트웨어 개발환경 서비스는 당시 기준에서 표준등급 대상에 포함되었다(개정 여부 확인).","공식 정답으로, 이메일/메신저 서비스는 당시 SaaS 등급 기준상 반드시 표준등급을 받아야 하는 서비스로 분류되지 않았다. 등급 기준은 이후 개정될 수 있다."],"rel":["5-6"]},{"n":85,"s":"s5","q":"다음 정보보호 대책 구현에 관한 설명으로 올바르지 않은 것은?","c":["효율적인 대책선정을 위해서는 위험분석 결과를 고려하여야 한다.","대책 선정에 있어 고려해야 할 중요한 요소 중 하나는 비용이다.","대부분의 대책들이 복합적인 기능 즉 감지, 억제, 방어, 제한, 교정 등을 수행할 수 있기 때문에 복수의 기능을 만족시키는 대책을 선택하는 것이 비용측면에서 효율적이다.","대책이 사용될 수 있는 영역은 물리적, 기술적 환경에 한정하여야 하며, 관리적 분야 즉 인적, 행정 분야 등에는 적용하지 않는다."],"a":3,"e":"정보보호 대책은 물리적·기술적 영역뿐 아니라 인적 보안, 정책·절차 등 관리적 영역에도 적용해야 한다. 나머지는 위험분석 결과·비용·복합 기능을 고려한 대책 선정 원칙으로 옳다.","ce":["위험분석으로 파악한 위험 수준에 맞춰 대책을 고르는 것이 효율적이므로 옳은 설명이다.","대책 비용이 보호 대상 자산 가치·기대 손실을 넘지 않도록 비용을 고려해야 하므로 옳은 설명이다.","하나의 대책이 감지·억제·방어·제한·교정 등 여러 기능을 수행하면 적은 비용으로 더 많은 위험을 줄일 수 있어 옳은 설명이다.","정보보호 대책은 물리적·기술적 영역뿐 아니라 인적 보안·정책·절차 같은 관리적 영역에도 적용해야 하므로, 관리적 분야 제외는 틀렸다."],"rel":["5-12"]},{"n":86,"s":"s5","q":"정보통신 서비스 제공자가 이용자의 컴퓨터나 모바일 등에 영리목적의 광고성 프로그램 등을 설치할 경우 준수해야 하는 사항으로 옳지 않은 것은?","c":["정보통신서비스 제공자는 영리목적의 광고성 정보가 보이는 프로그램을 이용자의 컴퓨터나 모바일에 설치하려면 이용자의 동의를 받아야 한다.","정보통신서비스 제공자는 영리목적의 개인정보를 수집하는 프로그램을 이용자의 컴퓨터나 모바일에 설치하려면 이용자의 동의를 받아야 한다.","정보통신서비스 제공자는 영리목적의 광고성 정보가 보이는 프로그램의 용도와 삭제 방법을 고지하여야 한다.","정보통신서비스 제공자는 영리목적의 광고성 정보를 편리하게 차단하거나 신고할 수 있는 소프트웨어나 컴퓨터 프로그램을 개발하여 보급하여야 한다."],"a":3,"e":"정보통신망법 제50조의5는 광고성 정보가 보이거나 개인정보를 수집하는 프로그램 설치 시 이용자 동의를 받고, 시행령에 따라 용도와 삭제 방법을 고지하도록 한다. 광고성 정보 차단·신고 소프트웨어의 개발·보급은 정부(방송통신위원회)가 할 수 있는 사항으로, 사업자의 준수사항이 아니다(개정 여부 확인).","ce":["정보통신망법은 광고성 정보가 보이는 프로그램을 설치할 때 이용자 동의를 받도록 규정하므로 옳은 준수사항이다.","개인정보를 수집하는 프로그램을 설치할 때도 이용자 동의를 받아야 하므로 옳은 준수사항이다.","시행령에 따라 설치 프로그램의 용도와 삭제 방법을 고지해야 하므로 옳은 준수사항이다.","광고성 정보 차단·신고 소프트웨어의 개발·보급은 정부(방송통신위원회)가 할 수 있는 사항으로, 사업자의 준수 의무가 아니다(개정 여부 확인)."],"rel":["5-10"]},{"n":87,"s":"s5","q":"정보보호 조직 구성원의 역할과 책임에 대한 설명으로 틀린 것은?","c":["최고 경영자 : 정보보호를 위한 총괄책임이 있다.","데이터 관리자 : 정보자산에 대한 책임을 보유한 현업 관리자이다.","프로세스 관리자 : 해당 정보 시스템에 대한 조직의 정보보호 정책에 따라 적절한 보안을 보증할 책임이 있다.","사용자 : 조직의 정보보호 정책에 따라 수립된 절차를 준수할 책임이 있다."],"a":1,"e":"정보자산에 대한 책임을 보유한 현업 관리자는 데이터 소유자(Owner)이다. 데이터 관리자(Custodian)는 소유자로부터 위임받아 데이터를 관리·운영(백업, 접근권한 적용 등)하는 역할이다.","ce":["최고 경영자는 조직 정보보호의 최종·총괄 책임을 지므로 옳은 설명이다.","정보자산에 대한 책임을 보유한 현업 관리자는 데이터 소유자(Owner)이다. 데이터 관리자(Custodian)는 소유자의 위임을 받아 백업·권한 적용 등 운영을 맡는다.","프로세스 관리자는 담당 정보시스템이 조직 정책에 맞게 보안이 유지되도록 보증할 책임이 있어 옳은 설명이다.","사용자는 정책에 따라 수립된 절차를 준수할 책임이 있으므로 옳은 설명이다."],"rel":["5-12"]},{"n":88,"s":"s5","q":"다음 중 개인정보처리자가 내부관리계획을 수립·시행할 때 반드시 포함되어야 하는 사항이 아닌 것은?","c":["개인정보보호책임자 지정에 관한 사항","개인정보취급자 상/벌에 관한 사항","개인정보 암호화 조치에 관한 사항","개인정보처리시스템 접근통제에 관한 사항"],"a":1,"e":"개인정보의 안전성 확보조치 기준상 내부관리계획에는 개인정보 보호책임자 지정, 취급자 교육, 접근권한 관리, 접근통제, 암호화, 접속기록 보관·점검 등이 포함된다. 개인정보취급자 상벌에 관한 사항은 필수 포함 항목이 아니다(개정 여부 확인).","ce":["개인정보 보호책임자 지정에 관한 사항은 안전성 확보조치 기준상 내부관리계획의 필수 포함 항목이다.","개인정보취급자의 상벌에 관한 사항은 내부관리계획의 법정 필수 항목이 아니다. 필수 항목은 책임자 지정·교육·접근권한·접근통제·암호화·접속기록 등이다(개정 여부 확인).","개인정보 암호화 조치에 관한 사항은 내부관리계획의 필수 포함 항목이다.","개인정보처리시스템 접근통제에 관한 사항은 내부관리계획의 필수 포함 항목이다."],"rel":["5-9"]},{"n":89,"s":"s5","q":"다음 중 정보통신기반보호위원회에 대한 설명으로 틀린 것은?","c":["주요정보통신기반시설의 보호에 관한 사항을 심의하기 위하여 국무총리 소속하에 정보통신기반보호위원회를 구성한다.","정보통신기반보호위원회 위원장은 국무총리가 되고, 위원회의 위원은 대통령령으로 정하는 중앙행정기관의 차관급 공무원과 위원장이 위촉하는 사람으로 한다.","정보통신기반보호위원회의 효율적인 운영을 위하여 위원회에 공공분야와 민간분야를 각각 담당하는 실무위원회를 둔다.","정보통신기반보호위원회의 위원은 위원장 1인을 포함한 25인 이내의 위원으로 구성한다."],"a":1,"e":"정보통신기반 보호법 제3조에 따라 위원회는 국무총리 소속이지만 위원장은 국무조정실장이 맡는다. 위원장 포함 25명 이내로 구성하고 공공·민간 실무위원회를 둔다(개정 여부 확인).","ce":["정보통신기반 보호법 제3조에 따라 주요정보통신기반시설 보호 사항을 심의하는 위원회는 국무총리 소속으로 두므로 옳은 설명이다.","위원회는 국무총리 소속이지만 위원장은 국무총리가 아니라 국무조정실장이 맡으므로 틀렸다(개정 여부 확인).","위원회에 공공분야와 민간분야를 각각 담당하는 실무위원회를 두므로 옳은 설명이다.","위원회는 위원장 1인을 포함한 25인 이내의 위원으로 구성하므로 옳은 설명이다."],"rel":["5-13"]},{"n":90,"s":"s5","q":"다음 무장의 내용을 포함하는 지침으로 가장 적합한 것은?","c":["문서관리 지침","위험평가관리 지침","침해사고대응 지침","업무연속성관리 지침"],"a":3,"e":"업무영향분석(BIA), 복구전략 수립, 교육·훈련, 비상연락망 등은 재해·장애 시 핵심 업무를 지속하기 위한 업무연속성관리(BCM) 지침의 구성 내용이다. 침해사고대응 지침은 보안사고 탐지·대응 절차 중심이다.","ce":["문서관리 지침은 문서의 작성·승인·배포·보관·폐기 절차를 다루며, 업무영향분석·복구전략과는 관련이 없다.","위험평가관리 지침은 자산 식별·위협·취약점 분석과 위험 평가 절차를 다루며, 복구전략·비상연락망 중심이 아니다.","침해사고대응 지침은 보안사고 탐지·보고·분석·복구 절차 중심으로, 업무 중요도 등급·업무영향분석을 핵심으로 하지 않는다.","업무영향분석(BIA), 복구전략 수립, 교육·훈련, 비상연락망은 재해 시 핵심 업무를 지속하기 위한 업무연속성관리(BCM) 지침의 구성 내용이다."],"rel":["5-3"],"box":"- 책임과 역할\n- 업무의 중요도 등급 및 업무영향분석\n- 복구전략수립\n- 교육 및 훈련\n- 사후관리\n- 비상연락망","flag":"발문 \"무장\" 원문 오탈자(문장)"},{"n":91,"s":"s5","q":"다음 중 개인정보 처리자가 정보주체에게 사유를 알리고 열람을 제한하거나 거절할 수 있는 경우로 옳지 않은 것은?","c":["법률에 따라 열람이 금지되거나 제한되는 경우","다른 사람의 생명, 신체를 해할 우려가 있거나 다른 사람의 재산과 그 밖의 이익을 부당하게 침해할 우려가 있는 경우","공공기관의 개인정보를 처리하지 아니하면 다른 법률에서 정하는 소관 업무를 수행할 수 없는 경우","공공기관의 학력 및 채용에 관한 시험, 자격 심사에 관한 업무를 수행할 때 중대한 지장을 초래하는 경우"],"a":2,"e":"개인정보 보호법 제35조 제4항의 열람 제한 사유는 법률상 금지, 타인의 생명·신체·재산 등 침해 우려, 공공기관의 조세 부과·징수, 학력·기능 시험 및 채용 등 업무에 중대한 지장이 있는 경우이다. ③은 공공기관의 개인정보 수집·이용 근거(제15조)이지 열람 제한 사유가 아니다(개정 여부 확인).","ce":["법률에 따라 열람이 금지·제한되는 경우는 개인정보 보호법 제35조 제4항의 열람 제한 사유이다.","타인의 생명·신체를 해하거나 재산 등 이익을 부당하게 침해할 우려가 있는 경우는 열람 제한 사유이다.","소관 업무 수행을 위해 불가피한 경우는 공공기관의 개인정보 수집·이용 근거(제15조)이며, 열람 제한 사유가 아니다(개정 여부 확인).","공공기관의 학력·기능 시험, 채용·자격 심사 업무에 중대한 지장을 초래하는 경우는 열람 제한 사유이다."],"rel":["5-8"]},{"n":92,"s":"s5","q":"다음 중 정량적 분석의 장점이 아닌 것은?","c":["위험평가 결과가 금전적 가치, 백분율, 확률 등으로 표현되어 이해가 쉽다.","위험관리 성능평가가 용이하다.","정보자산의 가치가 논리적으로 평가되고 화폐로 표현되어 이해가 쉽다.","비용대비 이익을 평가할 필요가 없다."],"a":3,"e":"정량적 분석은 자산 가치와 손실을 금액으로 산출하므로 비용 대비 효과(이익) 분석이 가능하고 필요하다는 점이 장점이다. \"비용대비 이익을 평가할 필요가 없다\"는 장점이 아니며, 계산이 복잡하고 시간이 많이 든다는 것이 단점이다.","ce":["정량적 분석은 결과를 금액·백분율·확률로 표현해 이해하기 쉽다는 장점이 있다.","수치로 산출되므로 대책 전후를 비교해 위험관리 성능을 평가하기 쉽다는 장점이 있다.","자산 가치를 논리적으로 평가해 화폐로 표현하므로 경영진이 이해하기 쉽다는 장점이 있다.","정량적 분석은 손실 금액을 산출해 비용 대비 효과(이익) 분석을 가능하게 하는 것이 장점이므로, '평가할 필요가 없다'는 장점이 아니다."],"rel":["5-2"]},{"n":93,"s":"s5","q":"재해복구 시스템의 유형과 복구목표 시간(RTO, Recovery Time Objective)의 설명이 틀린 것은?","c":["미러 사이트 : 즉시","핫 사이트 : 수시간 이내","웜 사이트 : 수일 ~ 수주","콜드 사이트 : 수일 ~ 수주"],"a":3,"e":"콜드 사이트는 전산실 공간과 전원 등 기본 설비만 갖춘 형태로 RTO가 수주~수개월이다. 미러 사이트는 즉시, 핫 사이트는 수시간 이내, 웜 사이트는 수일~수주이다.","ce":["미러 사이트는 주센터와 동일한 시스템을 실시간 동기화(Active-Active)해 RTO가 사실상 즉시이므로 옳다.","핫 사이트는 동일 수준 설비를 대기 상태로 두어 수시간 이내 복구가 가능하므로 옳다.","웜 사이트는 중요 설비 일부만 갖춰 수일~수주의 복구 시간이 필요하므로 옳다.","콜드 사이트는 공간·전원 등 기본 설비만 갖춰 장비 반입·설치가 필요하므로 RTO가 수주~수개월이다. '수일~수주'는 웜 사이트의 RTO이다."],"rel":["5-3"]},{"n":94,"s":"s5","q":"다음 중 개인정보보호 관련 법률과 그 소관 부처가 올바르게 짝지어진 것은?","c":["개인정보 보호법 - 법무부","위치정보의 보호 및 이용 등에 관한 법률 - 국방부","지방공기업법 - 국토교통부","전자서명법 - 과학기술정보통신부"],"a":3,"e":"전자서명법의 소관 부처는 과학기술정보통신부이다. 개인정보 보호법은 개인정보보호위원회, 위치정보법은 방송통신위원회, 지방공기업법은 행정안전부 소관이다(개정 여부 확인).","ce":["개인정보 보호법의 소관은 법무부가 아니라 개인정보보호위원회이다(2020년 개정 이후).","위치정보법의 소관은 국방부가 아니라 방송통신위원회이다.","지방공기업법의 소관은 국토교통부가 아니라 행정안전부이다.","전자서명법의 소관 부처는 과학기술정보통신부로 올바른 짝이다(개정 여부 확인)."],"rel":["5-10"]},{"n":95,"s":"s5","q":"다음의 업무를 모두 수행하는 기관은?","c":["정보공유·분석센터","한국인터넷진흥원","관리기관","지식정보보안 컨설팅업체"],"a":0,"e":"정보통신기반 보호법 제16조의 정보공유·분석센터(ISAC)는 금융·통신 등 분야별로 구축·운영되며 취약점·침해요인 정보 제공과 실시간 경보·분석체계 운영을 수행한다. 관리기관은 주요정보통신기반시설을 직접 관리하는 기관이다.","ce":["정보공유·분석센터(ISAC)는 금융·통신 등 분야별로 구축·운영되며 취약점·침해요인 정보 제공과 실시간 경보·분석체계를 운영한다(정보통신기반 보호법 제16조).","한국인터넷진흥원(KISA)은 기술적 지원 기관으로 분야별로 구축·운영되는 조직이 아니며, 지문의 세 업무를 모두 수행하는 주체로 규정되지 않는다.","관리기관은 주요정보통신기반시설을 직접 관리·운영하며 취약점 분석·보호대책을 수립하는 기관으로, 분야별 정보공유·경보 조직이 아니다.","지식정보보안 컨설팅업체는 취약점 분석·평가와 보호대책 수립을 지원하는 민간 전문업체로 실시간 경보·분석체계 운영 기관이 아니다."],"rel":["5-13"],"box":"- 금융·통신 등 분야별 정보통신기반시설을 보호하기 위하여 구축·운영\n- 취약점 및 침해요인과 그 대응방안에 관한 정보 제공\n- 침해사고가 발생하는 경우 실시간 경보·분석체계 운영"},{"n":96,"s":"s5","q":"정량적 위험분석의 방법론 중 다음 문장에서 설명한 방법으로 알맞은 것은?","c":["연간예상손실법","과거자료 분석법","수학공식 접근법","확률 분포법"],"a":2,"e":"수학공식 접근법은 위협 발생 빈도를 계산하는 식을 이용해 위험을 계량화하는 방법으로, 과거 자료가 부족할 때 유용하고 간결하지만 기대 손실 추정 자료의 양이 적다는 단점이 있다. 과거자료 분석법은 충분한 과거 자료가 있어야 하고, 확률 분포법은 미지의 사건을 확률 분포로 추정한다.","ce":["연간예상손실법(ALE)은 자산 가치×노출계수×연간발생률로 연간 손실액을 계산하는 방법으로, 위협 빈도 계산식 자체가 핵심이 아니다.","과거자료 분석법은 충분한 과거 자료가 있어야 정확도가 높아지는 방법으로, 과거 자료 획득이 어려울 때 유용하다는 설명과 반대이다.","수학공식 접근법은 위협 발생 빈도를 계산하는 식으로 위험을 계량화하며, 과거 자료가 부족할 때 유용하고 간결하지만 기대 손실 추정 자료가 적다는 단점이 있다.","확률 분포법은 미지의 사건을 확률 분포로 추정하는 방법으로 정확도가 낮다는 한계가 있으며, 지문의 빈도 계산식 설명과 다르다."],"rel":["5-2"],"box":"이 방법은 위협의 발생빈도를 계산하는 식을 이용하며 위협을 계량하는 방법이다. 과거자료의 획득이 어려울 경우 위협 발생 빈도를 추정, 분석하는데 유용하며, 위험을 경량화 화여 매우 간결하게 나타낼 수 있다. 하지만 이는 기대 손실을 추정하는 자료의 양이 낮다는 단점이 있다."},{"n":97,"s":"s5","q":"정보보호 관리체계는 정보보호를 스스로, 체계적으로, 지속적으로 하기 위해 3가지 요소가 필요하다. 관련이 적은 것은?","c":["정보보호 조직과 인력","정보보호 사업의 추진과 예산 배정","정보보호 규정에 기반한 전사적인 정보보호 활동","정보보호 운영에 필요한 보안 솔루션"],"a":3,"e":"관리체계의 3요소는 정보보호 조직·인력, 사업 추진과 예산, 규정에 기반한 전사적 활동으로 관리적 체계를 의미한다. 보안 솔루션은 관리체계 운영 결과 선정되는 기술적 대책으로 3요소에 해당하지 않는다.","ce":["정보보호 조직과 인력은 관리체계를 스스로 운영하기 위한 3요소 중 하나이다.","정보보호 사업의 추진과 예산 배정은 관리체계를 지속적으로 운영하기 위한 3요소 중 하나이다.","정보보호 규정에 기반한 전사적 정보보호 활동은 관리체계를 체계적으로 운영하기 위한 3요소 중 하나이다.","보안 솔루션은 관리체계 운영 결과 선정되는 기술적 대책일 뿐, 관리체계를 구성하는 3요소(조직·예산·활동)에 해당하지 않는다."],"rel":["5-12"]},{"n":98,"s":"s5","q":"다음 중 100만명 미만의 정보주체에 관한 개인정보를 보유한 중소기업의 내부관리계획의 내용에 포함하지 않아도 될 내용은 무엇인가?","c":["개인정보 보호책임자의 지정에 관한 사항","개인정보 유출사고 대응 계획 수립·시행에 관한 사항","개인정보의 암호화 조치에 관한 사항","개인정보 처리업무를 위탁하는 경우 수탁자에 대한 관리 및 감독에 관한 사항"],"a":3,"e":"당시 개인정보의 안전성 확보조치 기준은 유형2(100만명 미만 중소기업 등)의 내부관리계획에서 위험도 분석·대응, 수탁자 관리·감독 등 일부 항목을 생략할 수 있도록 했다. 책임자 지정, 유출사고 대응, 암호화 조치는 포함해야 한다. 2023년 고시 개정으로 유형 구분이 정비되었다(개정 여부 확인).","ce":["개인정보 보호책임자 지정은 유형과 관계없이 내부관리계획에 포함해야 하는 기본 항목이다.","개인정보 유출사고 대응 계획은 당시 유형2(100만명 미만 중소기업)에서도 내부관리계획에 포함해야 하는 항목이었다(개정 여부 확인).","개인정보 암호화 조치는 유형2 내부관리계획에도 포함해야 하는 항목이었다(개정 여부 확인).","당시 안전성 확보조치 기준은 유형2의 내부관리계획에서 수탁자 관리·감독 등 일부 항목을 생략할 수 있게 했다. 2023년 고시 개정으로 유형 구분이 정비되었다(개정 여부 확인)."],"rel":["5-9"]},{"n":99,"s":"s5","q":"인터넷에 공개된 서버를 운영하는 경우 적절하지 못한 보안 방법은?","c":["공개서버를 운영하는 경우 이에 대한 보호대책을 수립·이행한다.","공개서버는 내부 네트워크의 서버팜 영역에 설치하고 침입차단 시스템 등 보안시스템을 통해 보호한다.","공개서버에 개인정보 및 중요정보를 게시하거나 저장하여야 할 경우 책임자 승인 등 허가 및 게시절차를 수립·이행한다.","조직의 중요정보가 웹사이트 및 웹서버를 통해 노출되고 있는지 여부를 주기적으로 확인하여 중요정보 노출을 인지한 경우 이를 즉시 차단하는 등의 적절한 조치를 취한다."],"a":1,"e":"ISMS-P 기준(2.10.3 공개서버 보안)상 공개서버는 내부망과 분리된 DMZ 영역에 설치하고 침입차단시스템으로 보호해야 한다. 내부 서버팜에 두면 공개서버 침해 시 내부망으로 피해가 확산된다.","ce":["공개서버를 운영할 때 별도의 보호대책을 수립·이행해야 한다는 것은 ISMS-P 2.10.3 요구사항이다.","공개서버는 내부망 서버팜이 아니라 내부망과 분리된 DMZ에 설치하고 침입차단시스템으로 보호해야 한다. 내부에 두면 침해가 내부망으로 확산된다.","공개서버에 개인·중요정보를 게시할 때 책임자 승인 등 허가·게시 절차를 두는 것은 올바른 보안 방법이다.","웹사이트·웹서버를 통한 중요정보 노출 여부를 주기적으로 확인하고 즉시 차단하는 것은 올바른 보안 방법이다."],"rel":["5-11"]},{"n":100,"s":"s5","q":"다음 문장은 위험관리를 위한 위험 처리 방안 중 어떤 방안을 설명한 것인가?","c":["위험 수용","위험 제거","위험 전이","위험 회피"],"a":3,"e":"위험을 감내할 수 없어 위험 원인이 되는 자산을 제거하거나 해당 업무 자체를 수행하지 않는 것은 위험 회피이다. 위험 전이는 보험·외주로 위험을 제3자에게 넘기는 것이고, 위험 수용은 위험을 그대로 받아들이는 것이다.","ce":["위험 수용은 위험을 인지하고 대책 없이 그대로 받아들이는 것으로, 자산 제거·업무 중단과 반대이다.","위험 제거(감소)는 통제를 적용해 위험 수준을 낮추는 방안으로, 업무 자체를 수행하지 않는 것과 다르다.","위험 전이는 보험·아웃소싱 등으로 위험을 제3자에게 넘기는 방안이다.","위험을 감내할 수 없어 위험의 근원인 자산을 없애거나 해당 업무를 수행하지 않는 것은 위험 회피이다."],"rel":["5-2"],"box":"발생할 위험을 감내할 수 없으므로 위험의 근원이 되는 자산을 제거하거나 해당 업무를 수행하지 않는 방안"}]},{"id":"2021-09-04","title":"2021년 9월 4일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"NTFS 파일 시스템의 메타 파일에 해당하지 않는 것은?","c":["$MFT","$Logfile","$Volume","$Bios"],"a":3,"e":"NTFS 메타파일에는 $MFT, $MFTMirr, $LogFile, $Volume, $AttrDef, $Bitmap, $Boot, $BadClus, $Secure, $UpCase, $Extend 등이 있으며 $Bios는 존재하지 않는다. $LogFile은 트랜잭션 저널, $Volume은 볼륨 레이블·버전 정보를 담는다.","ce":["$MFT는 볼륨의 모든 파일·디렉터리 레코드를 담은 마스터 파일 테이블로 대표적인 NTFS 메타파일이다.","$LogFile은 메타데이터 변경을 트랜잭션 단위로 기록하는 저널 파일로, 장애 시 복구에 쓰이는 NTFS 메타파일이다.","$Volume은 볼륨 레이블·NTFS 버전·더티 플래그 등 볼륨 정보를 담은 NTFS 메타파일이다.","$Bios라는 NTFS 메타파일은 없다. 부트 관련 메타파일은 $Boot이며, BIOS는 메인보드 펌웨어이다."],"rel":["1-18"],"flag":"원문에 발문과 무관한 지문 상자(DLP 설명: \"PC에 에이전트를 설치하며 메일, SNS, 웹사이트 등을 통해 발생할 수 있는 중요 정보 유출을 탐지하여 차단한다.\")가 삽입되어 있어 생략함"},{"n":2,"s":"s1","q":"다음 지문에서 설명하는 공격은 무엇인가?","c":["힙 오버플로우 공격","레이스 컨디션 공격","스택 오버플로우 공격","코드 기반 공격"],"a":1,"e":"두 프로세스가 같은 자원(임시파일 등)에 접근하는 경쟁 상태를 이용해, SetUID 프로그램이 가진 root 권한으로 공격자가 원하는 파일에 접근하게 만드는 공격은 레이스 컨디션 공격이다. 힙·스택 오버플로우는 버퍼 경계를 넘는 쓰기로 메모리를 덮어쓰는 공격이다.","ce":["힙 오버플로우는 동적 할당된 힙 버퍼의 경계를 넘어 인접 데이터·관리 구조를 덮어쓰는 공격으로, 프로세스 간 자원 경쟁을 이용하지 않는다.","두 프로세스가 같은 자원(임시파일 등)에 접근하는 경쟁 상태를 만들어, SetUID 프로그램의 root 권한으로 원하는 파일에 접근하게 하는 것이 레이스 컨디션 공격이다.","스택 오버플로우는 스택 버퍼를 넘치게 해 리턴 주소를 덮어써 실행 흐름을 바꾸는 공격으로 경쟁 상태와 무관하다.","코드 기반 공격은 특정 공격 기법의 명칭이 아니며, 지문의 경쟁 상태 이용 특징을 설명하지 않는다."],"rel":["1-10"],"box":"두 프로세스 간에 자원을 사용하기 위해서 경쟁하는 것을 이용한 공격으로 시스템 프로그램과 공격 프로그램이 경쟁 상태에 이르게 하며 시스템 프로그램이 갖는 권한으로(set user id가 붙은 경우 root 권한) 파일에 접근을 가능하게 하는 방법을 말한다."},{"n":3,"s":"s1","q":"리눅스에서 새로 생성되는 사용자 계정의 홈 디렉터리는 .bashrc 등과 같이 모든 사용자가 필요로 하는 파일들을 만들어줄 필요가 있다. 이러한 공통 파일들을 미리 만들어 특정 디렉토리에 넣어두면 사용자 계정 생성 시 자동복사 되도록 설정할 수 있는데, 이러한 용도의 디렉터리는 무엇인가?","c":["/etc/init","/etc/services","/etc/login.defs","/etc/skel"],"a":3,"e":"/etc/skel 디렉터리의 .bashrc, .profile 등은 useradd로 계정을 만들 때 새 홈 디렉터리로 자동 복사된다. /etc/login.defs는 UID 범위·패스워드 정책 등 계정 생성 기본값, /etc/services는 서비스-포트 매핑 파일이다.","ce":["/etc/init은 시스템 초기화(upstart) 작업 설정이 있는 디렉터리로, 새 계정 홈에 복사할 기본 파일을 두는 곳이 아니다.","/etc/services는 서비스 이름과 포트 번호·프로토콜 매핑을 정의한 파일이다.","/etc/login.defs는 UID·GID 범위, 패스워드 만료 정책 등 계정 생성 기본값을 정한 설정 파일로, 복사될 파일을 담는 디렉터리가 아니다.","/etc/skel의 .bashrc·.profile 등은 useradd로 계정을 만들 때 새 홈 디렉터리로 자동 복사된다."],"rel":["1-16"]},{"n":4,"s":"s1","q":"2016년에 처음 발견되었으며 IP 카메라나 가정용 라우터와 같은 IoT 장치를 주요 공격 대상으로 삼는 DDoS 공격용 봇넷 악성코드는 무엇인가?","c":["님다","미라이","스턱스넷","SQL 슬래머"],"a":1,"e":"미라이(Mirai)는 기본 계정·패스워드로 텔넷에 접속해 IP 카메라·라우터 등 IoT 기기를 감염시키고 대규모 DDoS 봇넷을 구성한 악성코드로 2016년 발견되었다. 님다(2001)와 SQL 슬래머(2003)는 웜, 스턱스넷(2010)은 산업제어시스템 공격 악성코드이다.","ce":["님다(Nimda, 2001)는 이메일·웹·공유폴더 등 다중 경로로 확산된 윈도우 웜으로, IoT 봇넷이 아니다.","미라이(Mirai)는 2016년 발견되어 기본 계정·패스워드로 텔넷에 접속해 IP 카메라·라우터 등 IoT 기기를 감염시키고 대규모 DDoS 봇넷을 만든 악성코드이다.","스턱스넷(2010)은 원심분리기 PLC를 노린 산업제어시스템 공격 악성코드로 DDoS 봇넷이 아니다.","SQL 슬래머(2003)는 MS SQL Server의 UDP 1434 취약점을 이용해 빠르게 확산된 웜으로 IoT 기기를 대상으로 하지 않는다."],"rel":["1-19"]},{"n":5,"s":"s1","q":"다음 지문에서 설명하는 내용은 스푸핑 공격 중 어떤 공격에 해당하는가?","c":["DHCP 스푸핑","IP 스푸핑","DNS 스푸핑","ARP 스푸핑"],"a":3,"e":"ARP는 IP 주소를 MAC 주소로 변환하는 프로토콜이며, 위조한 ARP 응답으로 대상의 ARP 캐시 테이블을 변조해 패킷 흐름을 가로채는 것이 ARP 스푸핑이다. DNS 스푸핑은 도메인-IP 매핑을 위조한다.","ce":["DHCP 스푸핑은 가짜 DHCP 서버가 위조한 IP·게이트웨이·DNS 정보를 할당해 트래픽을 가로채는 공격으로, ARP 캐시 조작과 다르다.","IP 스푸핑은 패킷의 출발지 IP 주소를 위조해 신뢰 관계를 악용하는 공격으로, IP-MAC 매핑 캐시를 변조하지 않는다.","DNS 스푸핑은 도메인 이름과 IP 주소 매핑을 위조해 잘못된 사이트로 유도하는 공격이다.","IP 주소를 MAC 주소로 대응시키는 ARP의 캐시 테이블에 위조 응답으로 거짓 MAC을 등록해 패킷 흐름을 가로채는 것이 ARP 스푸핑이다."],"rel":["2-5"],"box":"32bit IP 주소를 48bit의 네트워크 카드 주소(MAC Address)로 대응시켜 주는 프로토콜이고 실제로 IP 주소를 통해 네트워크 연결을 시도하면 TCP/IP에서는 해당 IP주소 해당하는 네트워크 카드 주소를 찾아 연결하게 된다. 이더넷 환경에서 공격대상자의 cache 테이블에 공격자가 원하는 IP에 대한 하드웨어 주소(MAC Address)를 거짓으로 업데이트함으로써 공격대상자의 패킷 흐름을 공격자가 원하는 방향으로 조절하며 공격하는 기술이다."},{"n":6,"s":"s1","q":"디지털저장매체 중 하드디스크 구조에서 물리적으로는 할당된 공간이지만 논리적으로는 사용할 수 없는 공간을 무엇이라고 하는가?","c":["슬랙","CHS","클러스터","확장 공간"],"a":0,"e":"슬랙(Slack) 공간은 클러스터·섹터 단위로 할당되었으나 실제 파일 데이터가 채우지 못해 논리적으로 사용되지 않는 공간으로, 이전 데이터 잔재나 은닉 데이터가 남아 포렌식 분석 대상이 된다. CHS는 실린더·헤드·섹터 주소 지정 방식, 클러스터는 할당 단위이다.","ce":["슬랙 공간은 클러스터·섹터 단위로 할당됐지만 파일 데이터가 다 채우지 못해 논리적으로 쓰이지 않는 공간으로, 이전 데이터 잔재가 남아 포렌식 대상이 된다.","CHS는 실린더·헤드·섹터로 디스크 위치를 지정하는 주소 방식으로, 사용되지 않는 공간을 뜻하지 않는다.","클러스터는 파일 시스템이 공간을 할당하는 기본 단위로, 그 안에서 남는 부분이 슬랙이다.","확장 공간은 확장 파티션 등을 뜻하는 말로, 할당됐으나 논리적으로 사용 불가한 공간을 가리키는 용어가 아니다."],"rel":["1-18"]},{"n":7,"s":"s1","q":"윈도우 레지스트리 키 중에서 파일의 각 확장자에 대한 정보와 프로그램의 맵핑 정보가 저장된 키로 옳은 것은?","c":["HKEY_CLASSES_ROOT","HKEY_CURRENT_USER","HKEY_FILE_EXT","HKEY_LOCAL_MACHINE"],"a":0,"e":"HKEY_CLASSES_ROOT(HKCR)는 파일 확장자와 연결 프로그램, COM 객체 등록 정보를 담는다. HKEY_CURRENT_USER는 로그인 사용자 설정, HKEY_LOCAL_MACHINE은 시스템 전체 설정이며, HKEY_FILE_EXT라는 루트 키는 없다.","ce":["HKEY_CLASSES_ROOT(HKCR)는 파일 확장자와 연결 프로그램, COM 객체 등록 정보를 저장하는 루트 키이다.","HKEY_CURRENT_USER는 현재 로그인한 사용자의 바탕화면·프로그램 설정 등 사용자 프로필 정보를 담는다.","HKEY_FILE_EXT라는 레지스트리 루트 키는 존재하지 않는다.","HKEY_LOCAL_MACHINE은 하드웨어·드라이버·서비스 등 시스템 전체 설정을 담으며, HKCR은 그 하위 Software\\Classes를 병합해 보여주는 키이다."],"rel":["1-3"]},{"n":8,"s":"s1","q":"다음 지문에서 설명하고 있는 시스템 보안은?","c":["TPM","SRM","SAM","SID"],"a":0,"e":"TPM(Trusted Platform Module)은 암호 연산·키 보관을 하드웨어 칩으로 수행해 보안 부팅, 인증, 암호화 등 신뢰 기반 기능을 제공한다. SRM은 윈도우 보안 참조 모니터, SAM은 계정 DB, SID는 보안 식별자이다.","ce":["TPM은 암호 연산과 키 보관을 하드웨어 칩으로 수행해 보안 부팅, 인증, 암호화 등 신뢰 기반 기능을 제공한다.","SRM(Security Reference Monitor)은 윈도우 커널에서 객체 접근 권한을 검사하는 보안 참조 모니터로, 암호 연산 하드웨어가 아니다.","SAM(Security Account Manager)은 윈도우 로컬 계정과 패스워드 해시를 저장하는 데이터베이스이다.","SID(Security Identifier)는 윈도우 사용자·그룹을 고유하게 식별하는 보안 식별자이다."],"rel":["1-18"],"box":"- 민감한 암호연산을 하드웨어로 이동함으로써 시스템 보안을 향상시키고자 나온 개념\n- 인증된 부트, 인증, 암호화와 같은 기본적인 기능을 제공\n- 안전한 입출력에 사용되는 암호 프로세서를 제공"},{"n":9,"s":"s1","q":"아래 지문의 척도들과 가장 관련성이 높은 보안 서비스는?","c":["기밀성","무결성","가용성","유지보수성"],"a":2,"e":"가동시간·정지시간·MTTF·MTTR은 시스템이 필요할 때 사용 가능한 정도를 측정하는 가용성 척도이며, 가용성은 MTTF/(MTTF+MTTR)로 산출한다. 기밀성·무결성은 정보 노출·변조 방지와 관련된다.","ce":["기밀성은 인가되지 않은 자에게 정보가 노출되지 않도록 하는 성질로, 가동·정지 시간 같은 시간 척도로 측정하지 않는다.","무결성은 정보가 인가되지 않은 방식으로 변경되지 않도록 하는 성질로, 가동시간·MTTR과 무관하다.","가동·정지시간, MTTF, MTTR은 시스템을 필요할 때 사용할 수 있는 정도를 재는 가용성 척도이며, 가용성=MTTF/(MTTF+MTTR)로 계산한다.","유지보수성은 MTTR과 관련이 있으나 보안 3요소(기밀성·무결성·가용성)에 속하는 보안 서비스가 아니며, 가동·정지시간 전체를 대표하지 않는다."],"rel":["1-14"],"box":"- 정보시스템의 가동시간(Up Time)\n- 정지시간(Down Time)\n- 평균 장애시간(MTTF, Mean Time To Failure)\n- 평균 복구시간(MTTR, Mean Time to Repair)"},{"n":10,"s":"s1","q":"IoT 위협 및 보안에 대한 설명으로 올바르지 않은 것은?","c":["홈가전 IoT 제품의 보안 요구사항에는 시큐어 코딩, 알려진 보안약점 및 취약점 제거, 최신 제3자(3rd party) 소프트웨어 사용 등이 있다.","홈캠, 네트워크 카메라 등의 네트워크 제품에 대한 주요 보안 위협에는 사진 및 동영상을 공격자의 서버 및 이메일로 전송하는 것이 있다. 이에 대한 원인으로는 접근통제 및 전송 데이터 보호의 부재가 있다.","시큐어 코딩이 적용되지 않은 스마트 홈가전 제품의 경우 입력 데이터 검증 및 표현, 보안 기능, 시간 및 상태, 에러처리 등에서 보안 취약점이 발생할 수 있다.","스마트 홈가전 제품의 데이터 기밀성 및 무결성을 위해 안전한 암호인 MD5, SHA-1 등의 사용이 권장된다."],"a":3,"e":"MD5와 SHA-1은 충돌 공격이 입증된 취약한 해시 함수이며, 해시는 기밀성을 제공하는 암호도 아니다. 기밀성에는 AES 등 검증된 암호 알고리즘을, 무결성에는 SHA-256 이상의 해시를 사용해야 한다.","ce":["시큐어 코딩, 알려진 보안약점·취약점 제거, 최신 제3자 소프트웨어 사용은 IoT 홈가전 보안 요구사항에 포함되므로 옳은 설명이다.","접근통제·전송 데이터 보호가 없으면 홈캠 영상이 공격자 서버·메일로 유출될 수 있어 옳은 설명이다.","시큐어 코딩 미적용 시 입력 검증·보안 기능·시간 및 상태·에러 처리 등 보안약점 유형에서 취약점이 생길 수 있어 옳은 설명이다.","MD5·SHA-1은 충돌 공격이 입증된 취약한 해시이며 해시는 기밀성도 제공하지 않는다. 기밀성은 AES, 무결성은 SHA-256 이상을 써야 한다."],"rel":["1-15"]},{"n":11,"s":"s1","q":"기존 파일 시스템에 새로운 파일 시스템을 하위 디렉터리로 연결하기 위해 사용되는 명령어는 무엇인가?","c":["mkfs","mount","fsck","mknod"],"a":1,"e":"mount는 장치의 파일 시스템을 기존 디렉터리 트리의 특정 디렉터리(마운트 포인트)에 연결한다. mkfs는 파일 시스템 생성, fsck는 파일 시스템 검사·복구, mknod는 장치 파일 생성 명령이다.","ce":["mkfs는 파티션에 새 파일 시스템을 생성(포맷)하는 명령으로, 디렉터리 트리에 연결하지 않는다.","mount는 장치의 파일 시스템을 기존 디렉터리 트리의 특정 디렉터리(마운트 포인트)에 연결하는 명령이다.","fsck는 파일 시스템의 일관성을 검사·복구하는 명령이다.","mknod는 블록·문자 장치 파일이나 FIFO 같은 특수 파일을 생성하는 명령이다."],"rel":["1-16"]},{"n":12,"s":"s1","q":"㉠에 들어갈 내용으로 적절한 것은?","c":["해시 암호화 패스워드 파일","섀도(Shadow) 패스워드 파일","익명(Anonymity) 패스워드 파일","PAM(Pluggable Authentication Module) 패스워드 파일"],"a":1,"e":"유닉스는 모든 사용자가 읽을 수 있는 /etc/passwd 대신 root만 읽을 수 있는 /etc/shadow에 암호화된 패스워드를 저장하는 섀도 패스워드 방식을 사용한다. PAM은 인증 모듈 프레임워크로 패스워드 파일이 아니다.","ce":["해시로 처리된 패스워드를 담는 것은 맞지만 '해시 암호화 패스워드 파일'은 유닉스의 공식 명칭이 아니며, 일반 사용자 접근 제한 방식을 가리키지 않는다.","유닉스는 누구나 읽는 /etc/passwd 대신 root만 읽을 수 있는 /etc/shadow에 암호화된 패스워드를 저장하는 섀도 패스워드 방식을 쓴다.","익명 패스워드 파일이라는 유닉스 구성 요소는 존재하지 않는다.","PAM은 응용프로그램의 인증 방식을 모듈로 교체할 수 있게 하는 프레임워크로, 패스워드를 저장하는 파일이 아니다."],"rel":["1-6"],"box":"유닉스에서는 패스워드 보호를 위해 암호 처리된 패스워드 정보를 공격자가 접근하기 어렵게 일반 사용자 권한으로 접근할 수 없는 ( ㉠ )을 사용하고 있다."},{"n":13,"s":"s1","q":"[그림1]은 어떤 리눅스 시스템에 존재하는 특정 /home 디렉터리와 그 아래에 존재하는 디렉터리 및 파일들의 속성 중 name, permission, user, group 등에 대한 정보만 요약한 것이며, [그림2]는 이 시스템에 존재하는 /etc/group 파일의 일부분이다. 이를 통하여 확인할 수 있는 파일 및 디렉터리의 permission에 관한 설명 중 올바르지 않은 것은?","c":["user1이란 사용자는 /home/user1 디렉터리로 이동할 수 있다","user2란 사용자는 exam.txt란 파일의 내용을 읽을 수 있다.","user3란 사용자는 exam.txt란 파일을 삭제할 수 있다.","시스템 내에 존재하는 user4란 사용자는 /home/user1 디렉터리로 이동할 수 없다."],"a":2,"e":"user3는 security 그룹 구성원이지만 /home/user1 디렉터리의 그룹 권한이 r-x로 쓰기(w) 권한이 없어, 디렉터리 내 파일(exam.txt)을 삭제할 수 없다. user2는 그룹 권한 rw-로 exam.txt를 읽을 수 있고, 그룹에 속하지 않은 user4는 기타 권한(---)이라 디렉터리로 이동할 수 없다.","ce":["user1은 /home/user1의 소유자이며 소유자 권한 rwx 중 x가 있어 디렉터리로 이동할 수 있으므로 옳은 설명이다.","user2는 security 그룹 구성원이고 /home/user1 그룹 권한 r-x로 진입 가능하며, exam.txt 그룹 권한 rw-로 읽을 수 있어 옳은 설명이다.","파일 삭제는 상위 디렉터리의 쓰기(w) 권한이 필요한데, /home/user1의 그룹 권한은 r-x라 security 그룹의 user3는 exam.txt를 삭제할 수 없다.","user4는 security 그룹이 아니므로 /home/user1의 기타 권한(---)이 적용되어 x 권한이 없어 이동할 수 없으므로 옳은 설명이다."],"rel":["1-4"],"box":"[그림 1]\n[name] | [permisson] | [user] | [group]\n/home | drwxr-xr-x | root | root\n/home/user1 | drwxr-x--- | user1 | security\n/home/user1/exam.txt | -rw-rw---- | user1 | security\n[그림 2]\nsecurity:x:510:user1,user2,user3:"},{"n":14,"s":"s1","q":"로그파일은?","c":["btmp","wtmp","syslog","messages"],"a":3,"e":"/var/log/messages는 서비스 동작, 커널 메시지, 버퍼 오버플로 공격 흔적 등 시스템 전반의 정보를 가장 많이 기록하는 로그이다. btmp는 로그인 실패, wtmp는 로그인·로그아웃·재부팅 기록을 담는다.","ce":["btmp는 실패한 로그인 시도를 기록하는 바이너리 로그(lastb로 조회)로, 시스템 장애 정보를 폭넓게 담지 않는다.","wtmp는 사용자 로그인·로그아웃과 재부팅 이력을 기록하는 바이너리 로그(last로 조회)이다.","syslog는 로그를 수집·기록하는 데몬·프로토콜 이름이며, 지문이 가리키는 특정 로그 파일(messages)과 구분된다.","/var/log/messages는 서비스 동작·커널 메시지·버퍼 오버플로 공격 흔적 등 시스템 전반 정보를 가장 많이 기록하는 로그이다."],"rel":["1-7"],"box":"다른 로그파일에 비해 많은 정보를 포함하고 있는 로그파일로 동작 중인 서비스에 대한 버퍼 오버플로우 공격의 경우와 같이 시스템 장애에 대한 정보를 로그파일로 저장한다."},{"n":15,"s":"s1","q":"랜섬웨어에 해당하지 않는 것은?","c":["페트야(Petya)","크립토월(CryptoWall)","워너크라이(WannaCry)","크립토재커(CryptoJacker)"],"a":3,"e":"크립토재커(Cryptojacking)는 피해자 PC의 자원을 몰래 사용해 암호화폐를 채굴하는 악성코드로, 파일을 암호화하고 금전을 요구하는 랜섬웨어가 아니다. 페트야, 크립토월, 워너크라이는 대표적인 랜섬웨어이다.","ce":["페트야(Petya)는 MBR과 MFT를 암호화해 부팅을 막고 몸값을 요구하는 랜섬웨어이다.","크립토월(CryptoWall)은 사용자 파일을 암호화하고 비트코인 결제를 요구하는 랜섬웨어이다.","워너크라이(WannaCry)는 2017년 SMB 취약점(EternalBlue)으로 확산되며 파일을 암호화한 랜섬웨어이다.","크립토재커는 피해자 PC 자원을 몰래 써서 암호화폐를 채굴하는 악성코드로, 파일을 암호화하고 금전을 요구하는 랜섬웨어가 아니다."],"rel":["1-19"]},{"n":16,"s":"s1","q":"서버의 파일 시스템에 대한 시간 속성이 잘못 기술된 것은?","c":["mtime: 파일을 생성하거나 내용을 수정한 시간","atime: 최근 파일을 읽거나 실행시킨 시간","ctime: 파일 속성이 변경된 시간","rtime: 파일을 실시간 실행시킨 시간"],"a":3,"e":"유닉스·리눅스 파일의 시간 속성은 mtime(내용 수정), atime(접근), ctime(inode 속성 변경) 세 가지이며 MAC time이라 부른다. rtime이라는 파일 시간 속성은 존재하지 않는다.","ce":["mtime은 파일 내용을 수정(생성 포함)한 시간으로 옳은 설명이다.","atime은 파일을 마지막으로 읽거나 실행한 접근 시간으로 옳은 설명이다.","ctime은 권한·소유자 등 inode 속성이 변경된 시간으로 옳은 설명이다(생성 시간이 아님).","유닉스 파일의 시간 속성은 mtime·atime·ctime(MAC time)이며 rtime이라는 속성은 존재하지 않는다."],"rel":["1-18"]},{"n":17,"s":"s1","q":"다음에서 설명하고 있는 것은 무엇인가?","c":["sudo","PAM","Batch file","Shell script"],"a":1,"e":"PAM(Pluggable Authentication Modules)은 인증 방법을 공유 라이브러리 모듈로 분리해, 관리자가 설정 파일만 바꾸면 응용프로그램을 재컴파일하지 않고 인증 방식을 변경할 수 있게 한다. sudo는 다른 사용자 권한으로 명령을 실행하는 도구이다.","ce":["sudo는 허가된 사용자가 다른 사용자(주로 root) 권한으로 명령을 실행하게 하는 도구로, 인증 방식 선택용 라이브러리가 아니다.","PAM은 인증 방법을 공유 라이브러리 모듈로 분리해, 설정 파일만 바꾸면 응용프로그램을 재컴파일하지 않고 인증 방식을 변경할 수 있게 한다.","Batch file은 윈도우에서 여러 명령을 순차 실행하는 스크립트 파일로 인증과 무관하다.","Shell script는 셸 명령을 묶어 자동화하는 스크립트로, 인증 방식을 교체하는 라이브러리가 아니다."],"rel":["1-16"],"box":"리눅스에서 시스템 관리자가 응용프로그램들이 사용자를 인증하는 방법을 선택할 수 있도록 해주는 공유라이브러리 묶음으로 이것을 사용하는 응용프로그램을 재컴파일 하지 않고, 인증방법을 변경할 수 있다는 장점이 있다."},{"n":18,"s":"s1","q":"윈도우 NTFS 파일 시스템의 특징으로 옳지 않은 것은?","c":["파일과 폴더에 개별 권한을 설정할 수 있어 강력한 보안 정책 설정이 가능하다.","이벤트 뷰어를 사용하여 MFT(Master File Table)의 내용을 확인할 수 있다.","FAT 파일 시스템에 없는 보안 속성(사용자 접근제어) 정보를 내장하고 있다.","파일 압축 및 암호화를 위한 구조를 갖는다."],"a":1,"e":"이벤트 뷰어는 시스템·보안·응용프로그램 이벤트 로그를 보는 도구이며 MFT 내용을 확인할 수 없다. MFT는 포렌식 도구나 디스크 편집기로 분석한다. NTFS는 ACL 기반 권한, 압축, EFS 암호화를 지원한다.","ce":["NTFS는 ACL로 파일·폴더마다 개별 권한을 설정할 수 있어 옳은 설명이다.","이벤트 뷰어는 시스템·보안·응용프로그램 이벤트 로그를 보는 도구로 MFT 내용을 보여주지 않는다. MFT는 포렌식 도구·디스크 편집기로 분석한다.","NTFS는 FAT에 없는 보안 설명자($Secure 등)로 사용자 접근제어 정보를 내장하므로 옳은 설명이다.","NTFS는 파일 압축과 EFS 암호화를 지원하는 구조를 가지므로 옳은 설명이다."],"rel":["1-18","1-3"]},{"n":19,"s":"s1","q":"rlogin 접속을 허용하는 설정 파일들로 올바르게 짝지어진 것은?","c":["/etc/hosts.allow, /etc/exports","/etc/hosts.allow, /.rhosts","/etc/hosts.equiv, /etc/exports","/etc/hosts.equiv, /.rhosts"],"a":3,"e":"r-계열 서비스(rlogin, rsh)의 신뢰 호스트는 시스템 전체 설정인 /etc/hosts.equiv와 사용자별 설정인 $HOME/.rhosts로 지정한다. /etc/hosts.allow는 TCP Wrapper 접근제어, /etc/exports는 NFS 공유 설정 파일이다.","ce":["/etc/hosts.allow는 TCP Wrapper 접근 허용 규칙, /etc/exports는 NFS 공유 설정 파일로 둘 다 rlogin 신뢰 설정과 무관하다.","/.rhosts는 맞지만 /etc/hosts.allow는 TCP Wrapper 설정 파일로 r-계열 신뢰 호스트 설정이 아니다.","/etc/hosts.equiv는 맞지만 /etc/exports는 NFS 공유 설정 파일로 rlogin과 무관하다.","r-계열 서비스의 신뢰 호스트는 시스템 전체 설정 /etc/hosts.equiv와 사용자별 설정 $HOME/.rhosts로 지정한다."],"rel":["1-16"]},{"n":20,"s":"s1","q":"다음 지문에서 설명하고 있는 안전한 보안 인증 방식은?","c":["SSH(Secure Shell)","SAM(Secure Access Module)","SSO(Single Sign On)","PAM(Pluggable Authentication Module)"],"a":3,"e":"PAM은 공유 라이브러리 형태의 인증 모듈로 관리자가 응용프로그램별 인증 방식을 선택하고 다양한 인증 방식을 부가적으로 조합할 수 있게 한다. SSO는 한 번의 인증으로 여러 시스템을 이용하는 통합 인증 방식이다.","ce":["SSH는 원격 접속 통신을 암호화하는 보안 셸 프로토콜로, 응용프로그램의 인증 방식을 선택하게 하는 공유 라이브러리가 아니다.","SAM(Secure Access Module)은 교통카드 단말 등에서 키를 저장·인증하는 보안 모듈로 지문의 공유 라이브러리와 다르다.","SSO는 한 번 인증으로 여러 시스템을 이용하게 하는 통합 인증 방식으로, 인증 모듈 라이브러리 구조를 뜻하지 않는다.","PAM은 공유 라이브러리 형태 인증 모듈로 관리자가 응용프로그램별 인증 방식을 선택하고 여러 인증 방식을 부가적으로 조합할 수 있게 한다."],"rel":["1-16"],"box":"- 시스템 관리자가 응용 프로그램들이 사용자를 인증하는 방법을 선택할 수 있도록 해주는 일종의 공유 라이브러리이다.\n- 다양한 형태의 인증방식을 부가적으로 사용할 수 있는 장점이 있다.\n- 시스템 환경에 맞게 설정하여 각 시스템에서 사용 가능한 인증 모듈을 통해 사용자의 인증 요구를 처리한다."},{"n":21,"s":"s2","q":"㉠에 들어갈 용어로 적절한 것은?","c":["Duplex Mode","MAC 변조","Promiscuous Mode","ARP"],"a":2,"e":"스니퍼는 자신에게 오지 않은 패킷까지 수신하도록 NIC를 무차별(Promiscuous) 모드로 설정하므로, 탐지 도구는 이 모드 설정 여부를 검사해 스니퍼 동작을 확인한다.","ce":["Duplex Mode는 반이중·전이중 등 송수신 방식 설정으로, 스니퍼 동작 여부와 관련이 없다.","MAC 변조는 NIC 주소를 위조하는 행위로, 스니퍼 탐지 도구가 검사하는 인터페이스 모드가 아니다.","스니퍼는 자신에게 오지 않은 패킷도 받도록 NIC를 무차별(Promiscuous) 모드로 설정하므로, 탐지 도구는 이 모드 여부를 검사한다.","ARP는 IP를 MAC으로 변환하는 프로토콜로 NIC의 동작 모드가 아니다. 다만 ARP 요청을 이용해 무차별 모드를 간접 탐지하는 기법은 있다."],"rel":["2-5"],"box":"스니퍼 탐지 도구는 로컬 네트워크 상의 호스트들에서 네트워크 인터페이스 카드의 ( ㉠ ) 여부를 검사함으로써 스니퍼가 수행되고 있는지를 확인할 수 있다."},{"n":22,"s":"s2","q":"다음 지문에서 설명하는 공격 대응 방법은 무엇인가?","c":["DNS 라우팅","DNS 스푸핑","DNS 웜홀","DNS 싱크홀"],"a":3,"e":"DNS 싱크홀은 악성 C&C 도메인 질의에 싱크홀 서버 IP를 응답해 좀비 PC가 해커의 명령 서버에 연결하지 못하게 하는 대응 기법이다. DNS 스푸핑은 위조 응답을 이용한 공격이다.","ce":["DNS 라우팅은 표준 보안 대응 기법 명칭이 아니며, C&C 연결 차단을 뜻하지 않는다.","DNS 스푸핑은 위조 DNS 응답으로 사용자를 잘못된 사이트로 유도하는 공격 기법으로, 대응 방법이 아니다.","DNS 웜홀은 C&C 차단 기법 명칭이 아니다. 웜홀 공격은 애드혹·센서 네트워크에서 터널로 패킷을 우회시키는 공격이다.","DNS 싱크홀은 악성 C&C 도메인 질의에 싱크홀 서버 IP를 응답해 좀비 PC가 해커 명령 서버에 연결하지 못하게 하는 대응 기법이다."],"rel":["2-3"],"box":"악성봇에 감염된 PC를 해커가 제어하지 못하도록 특정 주소로 연결을 시도할 때 실제 해당 주소로 연결되지 않게 하며 해커의 악의적인 명령을 전달 받지 못하도록 한다."},{"n":23,"s":"s2","q":"Firewall, IDS, IPS의 비교 중 올바른 것으로 짝지어진 것은?","c":["㉠, ㉢","㉡, ㉢","㉠, ㉣, ㉤","㉠, ㉢, ㉣"],"a":3,"e":"패킷 차단(㉠), 이상 탐지(㉢), 장점(㉣)은 옳다. ㉡은 IDS도 시그니처 기반 오용 탐지를 수행하므로 IDS가 ×인 것이 틀리고, ㉤은 방화벽의 단점이 외부가 아닌 내부 공격·우회 공격에 취약하다는 점이어서 틀리다.","ce":["㉠·㉢은 옳지만 역시 옳은 ㉣(장점: 방화벽 엄격한 접근통제, IDS 실시간 탐지, IPS 세션 기반 탐지)이 빠져 있다.","㉡은 IDS도 시그니처 기반 오용 탐지를 수행하므로 IDS를 ×로 표기한 것이 틀려, ㉡을 포함한 조합은 오답이다.","㉤의 방화벽 단점은 외부가 아니라 내부 공격·우회 경로에 취약하다는 점이어서 틀리므로, ㉤을 포함한 조합은 오답이다.","패킷 차단(㉠), 이상 탐지(㉢), 장점(㉣)의 비교가 옳고, ㉡(IDS 오용 탐지 ×)과 ㉤(방화벽 외부 공격 취약)은 틀리다."],"rel":["2-9"],"box":"구분 | Firewall | IDS | IPS\n㉠ 패킷 차단 | ○ | × | ○\n㉡ 오용 탐지 | × | × | ○\n㉢ 이상 탐지 | × | ○ | ○\n㉣ 장점 | 엄격한 접근통제 | 실시간 탐지 | 세션 기반 탐지 가능\n㉤ 단점 | 외부 공격에 취약 | 변형 패턴 탐지 어려움 | 오탐 현상 발생 가능"},{"n":24,"s":"s2","q":"다음 지문에서 설명하는 용어는 무엇인가?","c":["HSM","비트라커","OTP","TCB"],"a":0,"e":"HSM(Hardware Security Module)은 암·복호화, 전자서명 등 암호 연산을 고속으로 수행하고 암호키를 생성·보관하는 전용 하드웨어 장치이다. 비트라커는 윈도우 디스크 암호화 기능, TCB는 신뢰 컴퓨팅 기반 개념이다.","ce":["HSM은 암·복호화와 전자서명 연산을 고속으로 수행하고 암호키를 생성·안전 보관하는 전용 하드웨어 장치이다.","비트라커(BitLocker)는 윈도우의 디스크 볼륨 암호화 기능(소프트웨어)으로 별도의 암호 연산 하드웨어 장치가 아니다.","OTP는 매번 바뀌는 일회용 비밀번호로 인증을 강화하는 방식으로, 암호 연산 가속·키 보관 장치를 뜻하지 않는다.","TCB(Trusted Computing Base)는 보안 정책을 강제하는 하드웨어·펌웨어·소프트웨어 전체를 가리키는 개념으로 특정 장치가 아니다."],"rel":["4-4"],"box":"암호화, 복호화, 전자서명 등의 암호 관련 연산을 빠르게 수행하고, 암호키의 생성 및 안전한 보관을 할 수 있는 하드웨어 장치를 의미한다."},{"n":25,"s":"s2","q":"침입차단시스템에 대한 설명으로 옳지 않은 것은?","c":["패킷 필터링 방화벽은 패킷의 통과여부를 결정하기 위해 프로토콜 종류, 출발지 또는 목적지 IP 주소, TCP/UDP 포트 번호 등을 이용한다.","응용 게이트웨이 방식 방화벽은 내부망으로 패킷이 전송되는 것을 방지할 수 있으며 사용자 인증 기능도 제공할 수 있다.","상태 기반 패킷 검사(SPI) 방식 방화벽은 프로토콜 종류, 출발지 또는 목적지 IP 주소, TCP/UDP 포트 번호 외에 패킷의 데이터 부분에 대한 점검도 수행하지만, nmap 도구에 의해 ACK 스캔을 차단하지 못하는 단점이 있다.","심층 패킷 분석(DPI) 방식 방화벽은 패킷의 데이터 부분에 포함된 바이러스 등 악성코드를 검사할 수 있다."],"a":2,"e":"SPI 방화벽은 세션 상태 테이블로 연결 흐름을 추적하므로 연결 수립 없이 들어오는 ACK 패킷(ACK 스캔)을 비정상으로 차단할 수 있다. 패킷 데이터 부분까지 검사하는 것은 DPI 방식의 특징이다.","ce":["패킷 필터링 방화벽은 3·4계층 헤더의 프로토콜, 출발지·목적지 IP, TCP/UDP 포트로 통과 여부를 정하므로 옳은 설명이다.","응용 게이트웨이는 프록시로 연결을 대리해 외부 패킷이 내부망에 직접 전달되지 않게 하고 사용자 인증도 제공할 수 있어 옳은 설명이다.","SPI는 세션 상태 테이블로 연결을 추적하므로, 연결 수립 없이 들어온 ACK 패킷(ACK 스캔)을 차단할 수 있다. 데이터 부분 점검은 DPI의 특징이다.","DPI는 패킷의 페이로드까지 분석해 바이러스 등 악성코드와 애플리케이션을 식별할 수 있어 옳은 설명이다."],"rel":["2-9"]},{"n":26,"s":"s2","q":"서비스의 가용성과 성능뿐만 아니라 DDoS 공격 대응에도 효과적이서 최근 Anycast DNS가 많이 도입되어 있다. 다음 중 이 기술에 대해 잘못 설명한 것은?","c":["사용자가 접속에 사용하는 IP 주소의 패킷은 해당 주소를 갖는 가장 가까운 호스트로 라우팅된다.","주요 라우팅 프로토콜로 OSPF가 사용된다.","IPv4/IPv6 anycast 모두 적용 가능하다.","1.1.1.1이나 8.8.8.8 등의 Public DNS뿐만 아니라 kr root DNS 등이 대표적인 예이다."],"a":1,"e":"Anycast DNS는 여러 지역 서버가 같은 IP 주소를 BGP로 광고해, 사용자 패킷이 라우팅상 가장 가까운 서버로 전달되게 하는 방식이다. 내부망용 IGP인 OSPF가 아니라 인터넷 경로 제어용 BGP가 주로 사용된다.","ce":["Anycast는 같은 IP를 여러 지역 서버가 공유하고, 패킷은 라우팅상 가장 가까운 서버로 전달되므로 옳은 설명이다.","Anycast DNS는 인터넷 도메인 간 경로 제어 프로토콜인 BGP로 같은 주소를 광고한다. OSPF는 단일 조직 내부용 IGP로 주요 프로토콜이 아니다.","Anycast는 라우팅 방식이므로 IPv4와 IPv6 모두에 적용 가능해 옳은 설명이다.","Cloudflare 1.1.1.1, Google 8.8.8.8 같은 공용 DNS와 루트 DNS 서버들이 Anycast로 운영되는 대표 사례이므로 옳은 설명이다."],"rel":["2-12","2-3"]},{"n":27,"s":"s2","q":"다음 지문에서 설명하는 시스템으로 옳은 것은?","c":["SIEM","UTM","EMS","ESM"],"a":0,"e":"SIEM(Security Information and Event Management)은 정형·비정형 데이터와 보안 로그를 빅데이터 기반으로 통합 수집·상관분석해 침해 징후를 예측·대응하고 포렌식·컴플라이언스를 지원한다. ESM은 보안장비 이벤트를 통합 관리하는 전 세대 솔루션, UTM은 다기능 통합 보안 장비이다.","ce":["SIEM은 정형·비정형 데이터와 보안 로그를 빅데이터 기반으로 통합 수집·상관분석해 위협 징후를 예측·대응하고 포렌식·컴플라이언스를 지원한다.","UTM은 방화벽·IPS·안티바이러스·VPN 등 여러 보안 기능을 한 장비에 통합한 제품으로, 빅데이터 로그 분석 시스템이 아니다.","EMS(Enterprise Management System)는 기업 IT 인프라의 장애·성능을 관리하는 시스템으로 보안 위협 분석이 목적이 아니다.","ESM은 보안 장비의 이벤트를 통합 관리하는 전 세대 솔루션으로, 정형 이벤트 중심이라 비정형 빅데이터 분석을 강조하는 지문과 차이가 있다."],"rel":["2-10","1-11"],"box":"정형·비정형 데이터와 보안 로그 속에서 침입자 공격을 빠른 속도로 분석하고 예측해야 한다. 보안 위협 징후를 판단할 수 있는 데이터를 생성하고, 이 데이터로 보안 사고를 분석하고 예방·대응한다. 또한 로그 관리를 통합적으로 수행하며 네트워크 포렌식(Forensic)과 보안 관련 준수성(Compliance)에 중요한 역할을 담당한다."},{"n":28,"s":"s2","q":"㉠, ㉡, ㉢, ㉣에 들어갈 내용으로 적절한 것은?","c":["㉠ LAND ㉡ SYN Flooding ㉢ Smurf ㉣ DoS","㉠ SYN Flooding ㉡ Smurf ㉢ LAND ㉣ Sniffing","㉠ SYN Flooding ㉡ LAND ㉢ Smurf ㉣ DoS","㉠ LAND ㉡ Smurf ㉢ SYN Flooding ㉣ Sniffing"],"a":2,"e":"Half-Open 연결을 대량으로 만드는 것은 SYN Flooding, 출발지와 목적지 IP를 동일하게 위조하는 것은 LAND, ICMP Request로 대량 응답을 유발하는 것은 Smurf 공격이며, 모두 서비스 거부(DoS) 공격이다.","ce":["㉠(Half-Open 이용)은 SYN Flooding, ㉡(출발지=목적지 IP)은 LAND인데 둘을 뒤바꿨다. ㉢ Smurf, ㉣ DoS는 맞다.","㉡에 Smurf, ㉢에 LAND를 넣어 뒤바꿨고, 이 공격들은 서비스 거부 공격이므로 ㉣ Sniffing(도청)도 틀렸다.","Half-Open 연결 이용은 SYN Flooding(㉠), 출발지·목적지 IP 동일 위조는 LAND(㉡), ICMP Request 대량 유발은 Smurf(㉢)이며 모두 DoS(㉣)이다.","㉠ LAND, ㉡ Smurf, ㉢ SYN Flooding으로 세 공격을 모두 잘못 배치했고, ㉣ Sniffing도 틀렸다."],"rel":["2-3"],"box":"( ㉠ ) 공격은 TCP 연결 설정 과정 중 3-Way Handshaking 과정에서의 Half-Open 연결 시도가 가능하다는 취약점을 이용한 공격 방식이다.\n( ㉡ ) 공격은 패킷을 전송할 때 출발지와 목적지 IP 주소를 공격대상의 IP로 동일하게 패킷을 생성하여 전송하는 공격 방식이며, 또한 ( ㉢ ) 공격은 ICMP Request 메시지를 이용하여 공격 대상 시스템에 대량의 메시지를 전송하는 공격 방식이다. 이와 같은 방식은 ( ㉣ ) 공격에 해당한다."},{"n":29,"s":"s2","q":"애플리케이션 계층 취약점을 이용하는 공격유형과 거리가 먼 것은?","c":["Heartbleed","Memcached DDoS","Meltdown, Spectre","Shell Shock"],"a":0,"e":"comcbt 교사용 시험지와 정답표 기준 정답은 ①(Heartbleed)이다. Heartbleed는 OpenSSL의 TLS 하트비트 확장 구현 결함으로 서버 메모리를 유출하는 암호 통신 라이브러리 취약점이고, Memcached DDoS·Shell Shock는 응용 서비스(memcached, bash)의 취약점을 이용한다. 다만 Meltdown·Spectre는 CPU 투기적 실행을 악용하는 하드웨어 취약점이어서 ③도 거리가 멀다는 견해가 있다.","ce":["정답표 기준 정답이다. Heartbleed는 OpenSSL의 TLS 하트비트 확장 구현 결함으로 서버 메모리를 유출하는 암호 라이브러리 취약점으로 분류되었다. 다만 ③도 거리가 멀다는 정답 논란이 있다.","Memcached DDoS는 UDP로 노출된 memcached 서비스를 반사·증폭에 악용하는 공격으로, 응용 서비스 취약점을 이용한다.","Meltdown·Spectre는 CPU의 비순차·투기적 실행을 악용하는 하드웨어 취약점이라 내용상 이 보기도 '거리가 멀다'고 볼 여지가 있으나, 공식 정답은 ①이다.","Shell Shock는 bash 셸이 환경 변수의 함수 정의 뒤 명령을 실행하는 결함으로, CGI 등 애플리케이션을 통해 원격 명령을 실행하는 공격이다."],"rel":["2-7"],"flag":"정답 불일치: 이미지(❶)·정답표 ① vs 기존 txt ②. 내용상 ③(하드웨어 취약점)도 논란 — 이미지 기준 ① 채택"},{"n":30,"s":"s2","q":"스푸핑 공격에 따른 침해사고 발생 시 네트워크 기반 증거의 출처 장비 중 물리적인 포트와 MAC 주소 간의 매핑을 저장하는 CAM 테이블을 포함하고 있으며, 조사관이 트래픽을 캡처하거나 저장할 수 있는 플랫폼을 갖는 장비는 무엇인가?","c":["방화벽","스위치","IDS","IPS"],"a":1,"e":"스위치는 CAM(Content Addressable Memory) 테이블에 포트와 MAC 주소 매핑을 저장해 프레임을 전달하며, 포트 미러링(SPAN)으로 트래픽을 캡처할 수 있다. 따라서 ARP 스푸핑 등 조사 시 핵심 증거 출처가 된다.","ce":["방화벽은 정책에 따라 트래픽을 허용·차단하고 로그를 남기지만, 포트와 MAC 주소 매핑 CAM 테이블을 갖지 않는다.","스위치는 CAM 테이블에 포트-MAC 매핑을 저장해 프레임을 전달하고, 포트 미러링(SPAN)으로 트래픽을 캡처할 수 있어 ARP 스푸핑 조사의 증거 출처가 된다.","IDS는 트래픽을 분석해 침입을 탐지·경보하는 장비로, CAM 테이블을 갖지 않는다.","IPS는 인라인으로 공격 트래픽을 차단하는 장비로, 포트-MAC 매핑 CAM 테이블을 저장하지 않는다."],"rel":["2-12"]},{"n":31,"s":"s2","q":"다음 지문에서 설명하는 ICMP 메시지 타입은?","c":["Source Quench","Destination Unreachable","Time Exceeded","Parameter Problem"],"a":0,"e":"Source Quench(Type 4)는 라우터·목적지의 버퍼가 넘쳐 데이터그램이 폐기될 때 송신측에 전송 속도를 줄이도록 알리는 흐름·혼잡 제어 메시지이다. Time Exceeded는 TTL 만료, Destination Unreachable은 목적지 도달 불가를 알린다.","ce":["Source Quench(Type 4)는 버퍼가 넘쳐 데이터그램이 폐기될 때 송신측에 전송 속도를 줄이라고 알리는 흐름·혼잡 제어 메시지이다(현재는 폐지 권고).","Destination Unreachable(Type 3)은 목적지 네트워크·호스트·포트에 도달할 수 없음을 알리는 메시지로 혼잡 제어 목적이 아니다.","Time Exceeded(Type 11)는 TTL이 0이 되거나 단편 재조합 시간이 초과됐을 때 보내는 메시지이다.","Parameter Problem(Type 12)은 IP 헤더 필드 값이 잘못되어 처리할 수 없을 때 알리는 메시지이다."],"rel":["2-12"],"box":"네트워크 상의 통신량이 폭주하여 목적지 또는 라우터 등의 메모리나 버퍼 용량이 초과되어 IP 데이터그램이 유실되는 상태가 되면 해당 에러 메시지를 송신측에 통보함으로써 일종의 흐름제어 및 혼잡제어 등의 역할을 한다."},{"n":32,"s":"s2","q":"다음 중 파일을 안전하게 전송하기 위하여 SSH(Secure Shell)를 사용하는 프로토콜은?","c":["SFTP(Secure FTP)","TFTP(Trivial FTP)","FTPS(FTP-SSL)","HTTPS(HTTP-Secure)"],"a":0,"e":"SFTP는 SSH 채널(22/tcp) 위에서 파일 전송을 수행한다. FTPS와 HTTPS는 SSL/TLS를 사용하고, TFTP는 인증·암호화가 없는 UDP 69번 기반 단순 전송 프로토콜이다.","ce":["SFTP는 SSH 채널(22/tcp) 위에서 동작하는 파일 전송 프로토콜로, 인증과 전송 내용이 모두 암호화된다.","TFTP는 UDP 69번을 쓰는 단순 파일 전송 프로토콜로 인증·암호화 기능이 없다.","FTPS는 기존 FTP에 SSL/TLS를 적용한 방식으로, SSH를 사용하지 않는다.","HTTPS는 HTTP에 SSL/TLS를 적용한 웹 보안 프로토콜로 SSH와 무관하다."],"rel":["2-7","3-1"]},{"n":33,"s":"s2","q":"무선 네트워크 보안 프로토콜에 관한 다음 설명 중 틀린 것은?","c":["WEP, WPA, WPA2 모두 통신 기기들에 대한 인증과 메시지 암호화 기능을 제공한다.","WEP에서는 암호 강도가 높지 않은 RC4를 암호화 알고리즘으로 사용하였으며, AES 기반의 강력한 암호화 방식을 의무화한 것은 WPA에서부터이다.","WEP에서는 인증이나 암호화에 사전 공유키를 사용할 수 있지만, WPA나 WPA2에서처럼 동적으로 암호키를 변경하는 기능을 제공하지는 않는다.","WPA, WPA2 등에서는 WEP에는 없는 엔터프라이즈 모드를 제공하며, 엔터프라이즈 모드에서는 인증 및 키 관리 기능을 수행하는 중앙 서버를 이용할 수 있다."],"a":1,"e":"WPA는 WEP 하드웨어를 재사용하기 위해 RC4 기반 TKIP를 사용했고, AES 기반 CCMP를 의무화한 것은 WPA2부터이다. 따라서 \"WPA에서부터\"가 틀린 설명이다.","ce":["WEP·WPA·WPA2 모두 단말 인증 절차와 데이터 암호화 기능을 제공하므로(강도는 다름) 옳은 설명이다.","WPA는 기존 WEP 하드웨어를 쓰기 위해 RC4 기반 TKIP를 사용했고, AES 기반 CCMP를 의무화한 것은 WPA2부터이다. 'WPA에서부터'가 틀렸다.","WEP는 정적 사전 공유키를 계속 쓰며, WPA/WPA2처럼 TKIP·4-way handshake로 세션마다 키를 동적으로 바꾸지 않으므로 옳은 설명이다.","WPA/WPA2 엔터프라이즈 모드는 802.1X와 RADIUS 서버로 사용자 인증·키 관리를 중앙에서 수행하며 WEP에는 없으므로 옳은 설명이다."],"rel":["2-10"]},{"n":34,"s":"s2","q":"네트워크 방화벽(Firewall)의 주요 기능과 거리가 먼 것은?","c":["접근 제어","로깅과 감사 추적","인증","개인정보 마스킹"],"a":3,"e":"방화벽의 주요 기능은 접근 제어, 사용자·호스트 인증, 로깅·감사 추적, NAT, 무결성 점검 등이다. 개인정보 마스킹은 DB 보안·개인정보 보호 솔루션의 기능이다.","ce":["접근 제어는 정책에 따라 패킷을 허용·차단하는 방화벽의 가장 핵심 기능이다.","로깅과 감사 추적은 허용·차단 내역을 기록해 사후 분석에 쓰는 방화벽의 주요 기능이다.","방화벽은 접속 사용자·호스트에 대한 인증 기능을 제공할 수 있어 주요 기능에 포함된다.","개인정보 마스킹은 DB 보안·개인정보 보호 솔루션이 화면·출력 데이터를 가리는 기능으로 방화벽 기능이 아니다."],"rel":["2-9"]},{"n":35,"s":"s2","q":"Smurf 공격은 보통 라우터가 패킷을 받아서 다른 포트로 forwarding할 때 목적지 IP 주소의 네트워크 부분만 참조하고 라우팅 테이블을 검색하여 패킷을 전달하는 점을 이용한 공격 방법이다. Source IP 주소를 자신의 IP 주소가 아닌 공격대상 시스템의 IP 주소로 변조한 후 subnet의 broadcast 주소로 ICMP Echo Request를 보내면 이 패킷은 라우터를 거쳐서 특정 네트워크에 도착하여 모든 시스템이 받게 된다. 그러면 네트워크의 모든 시스템은 위조된 IP 주소로 ICMP Echo Reply 패킷을 전송하게 된다. 결과적으로 시스템은 Congestion 상태에 빠지게 되어 심각한 서비스 장애를 일으킨다. 이러한 공격 방법을 방지하기 위한 설명 중 내용이 적절하지 못한 것은?","c":["라우터에서 Direct Broadcast를 Disable시킨다.","IP Broadcast 주소로 도착한 ICMP 패킷에 대한 Reply를 금지시킨다.","라우터의 Ingress Filtering을 이용하여 Spoof된 패킷을 막는다.","65,535byte보다 큰 ICMP Echo 패킷을 IP Fragmentation을 이용하여 전송한다."],"a":3,"e":"65,535바이트를 초과하는 ICMP 패킷을 단편화해 보내는 것은 Ping of Death 공격 기법이며 Smurf 방지 대책이 아니다. Smurf는 Directed Broadcast 차단, 브로드캐스트 ICMP 응답 금지, Ingress Filtering으로 방지한다.","ce":["라우터에서 Directed Broadcast를 비활성화하면 외부에서 온 브로드캐스트 ICMP가 서브넷 전체로 퍼지지 않아 Smurf 증폭을 막는다.","브로드캐스트 주소로 온 ICMP Echo Request에 응답하지 않게 하면 증폭 반사 트래픽이 생기지 않아 올바른 대책이다.","Ingress Filtering으로 내부 대역을 출발지로 위조한 외부 유입 패킷을 막으면 위조 출발지 기반 Smurf를 차단할 수 있어 올바른 대책이다.","65,535바이트를 넘는 ICMP 패킷을 단편화해 보내는 것은 Ping of Death 공격 기법 자체로, Smurf 방지 대책이 아니다."],"rel":["2-3"]},{"n":36,"s":"s2","q":"VPN을 구현하는 프로토콜과 해당 프로토콜이 속하는 계층이 바르게 연결된 것은?","c":["L2TP - Data Link Layer","SSH - Session Layer","IPSec - Transport Layer","SSL - Network Layer"],"a":0,"e":"L2TP·PPTP·L2F는 데이터 링크 계층(2계층) 터널링 프로토콜이다. IPSec은 네트워크 계층(3계층), SSL/TLS는 전송 계층 상위(4~5계층), SSH는 응용 계층에서 동작한다.","ce":["L2TP는 PPP 프레임을 터널링하는 데이터 링크 계층(2계층) VPN 프로토콜로 올바른 짝이다(PPTP·L2F도 같은 계층).","SSH는 세션 계층이 아니라 응용 계층에서 동작하는 원격 접속·터널링 프로토콜이다.","IPSec은 전송 계층이 아니라 IP 패킷을 보호하는 네트워크 계층(3계층) 프로토콜이다.","SSL/TLS는 네트워크 계층이 아니라 전송 계층 위(4~5계층 사이)에서 동작한다."],"rel":["2-7"]},{"n":37,"s":"s2","q":"파일에 숨겨진 악성코드만 골라 막는 콘텐츠 보안 솔루션으로 파일을 분해해 악성파일 혹은 불필요한 파일을 제거하고 콘텐츠는 원본과 동일하게 새로운 파일을 만드는 솔루션은?","c":["CDR(Content Disarm &Reconstruction)","WAF(Web Application Firewall)","DLP(Data Loss Prevention)","스팸 필터 솔루션"],"a":0,"e":"CDR은 문서 파일을 분해해 매크로·스크립트 등 잠재적 악성 요소를 제거한 뒤 원본과 같은 형태로 재구성하는 무해화 솔루션이다. DLP는 중요정보 유출 방지, WAF는 웹 공격 차단 솔루션이다.","ce":["CDR은 문서 파일을 분해해 매크로·스크립트 등 잠재적 악성 요소를 제거하고 원본과 같은 형태로 재구성하는 콘텐츠 무해화 솔루션이다.","WAF는 HTTP 요청을 분석해 SQL 인젝션·XSS 등 웹 공격을 차단하는 솔루션으로, 파일을 분해·재구성하지 않는다.","DLP는 중요정보가 메일·USB·웹 등으로 유출되는 것을 탐지·차단하는 솔루션으로 악성 요소 제거와 무관하다.","스팸 필터는 메일의 헤더·본문 규칙으로 스팸을 분류·차단할 뿐, 첨부파일을 분해해 재구성하지 않는다."],"rel":["2-10"]},{"n":38,"s":"s2","q":"침입 탐지에 대한 설명 중 옳은 것은?","c":["침입을 하는 전문적인 집단으로 CERT가 있다.","Honey pot을 이용하면 공격자의 행동 정보를 수집할 수 있다.","침입을 탐지 못하고, 통과시키는 것을 False Positive라고 한다.","내부 공격자의 위협을 줄이기 위해서는 보안 설정을 Blacklist 방식으로 해야 한다."],"a":1,"e":"허니팟은 의도적으로 취약하게 만든 유인 시스템으로 공격자의 행동·기법 정보를 수집한다. CERT는 침해사고 대응팀이고, 침입을 탐지하지 못하는 것은 False Negative이며, 내부 위협 감소에는 허용 목록(Whitelist) 방식이 적합하다.","ce":["CERT는 침입하는 집단이 아니라 침해사고를 접수·분석·대응하는 침해사고 대응팀이다.","허니팟은 의도적으로 취약하게 만든 유인 시스템으로, 접근한 공격자의 행동·도구·기법 정보를 수집할 수 있다.","침입을 탐지하지 못하고 통과시키는 것은 False Negative(미탐)이다. False Positive는 정상을 공격으로 잘못 탐지하는 오탐이다.","내부 공격자 위협을 줄이려면 허용된 것만 통과시키는 Whitelist(기본 거부) 방식이 적합하다. Blacklist는 알려진 위협만 막는다."],"rel":["2-9","2-10"]},{"n":39,"s":"s2","q":"올바르지 않은 것은?","c":["TCP SYN 플러딩 공격은 서버의 시스템 자원에 대한 공격이며, 일반 사용자들이 서버로 접속을 못하도록 하는 공격으로 서버 측의 대기 큐의 크기를 늘리는 방법이 대응 방안이 될 수 있다.","스머프 공격은 UDP 플러딩 공격으로 IP 주소의 브로드캐스트 주소대역을 이용한다.","Teardrop 공격은 IP 단편들이 서로 중첩되도록 IP 패킷 헤더를 조작해서 수신 측의 IP 패킷의 재조합 과정에서 오류를 발생시키도록 하는 공격이나, 최신 운영체제로의 업데이트로 문제를 해결할 수 있다.","HTTP GET 플러딩 공격은 공격자가 에이전트 다수에게 원격에서 명령을 보내어 동시에 특정 웹 페이지를 요청하는 형태로 공격이 이루어질 수 있으며, DDoS 공격 대응 장비에서 임계치 기반 방어 기법을 사용하면 해결에 도움이 된다."],"a":1,"e":"스머프 공격은 브로드캐스트 주소로 ICMP Echo Request를 보내 증폭된 ICMP Echo Reply로 공격하는 ICMP 플러딩이며 UDP 플러딩이 아니다. 브로드캐스트를 이용한 UDP 증폭 공격은 Fraggle 공격이다.","ce":["SYN 플러딩은 서버의 백로그 큐를 반개방 연결로 채워 정상 접속을 막는 자원 고갈 공격이며, 대기 큐 확대·SYN 쿠키 등이 대응책이므로 옳은 설명이다.","스머프 공격은 브로드캐스트 주소로 ICMP Echo Request를 보내 증폭된 Echo Reply로 공격하는 ICMP 플러딩이다. 브로드캐스트를 쓰는 UDP 증폭은 Fraggle 공격이다.","Teardrop은 IP 단편의 Offset을 중첩되게 조작해 재조합 오류를 일으키는 공격이며, 운영체제 패치로 해결할 수 있어 옳은 설명이다.","HTTP GET 플러딩은 다수 에이전트가 동시에 특정 페이지를 요청하는 DDoS이며, 임계치 기반 방어가 대응에 도움이 되므로 옳은 설명이다."],"rel":["2-3"]},{"n":40,"s":"s2","q":"아래의 결과를 보았을 때 이 네트워크는 어떠한 공격에 취약하다고 추측할 수 있는가?","c":["Land Attack","Smurf Attack","Syn Flooding Attack","Ping of Death Attack"],"a":1,"e":"브로드캐스트 주소(202.102.233.255)로 보낸 ping 한 번에 여러 호스트가 응답(DUP!)하므로 Directed Broadcast가 허용된 상태이다. 출발지를 위조하면 증폭된 Echo Reply가 피해자에게 몰리는 Smurf 공격에 취약하다.","ce":["Land 공격은 출발지와 목적지 IP를 같게 위조한 패킷을 보내는 공격으로, 브로드캐스트 ping에 여러 호스트가 응답하는 결과와 무관하다.","브로드캐스트 주소(.255)로 보낸 ping 한 번에 여러 호스트가 응답(DUP!)해 Directed Broadcast가 허용된 상태이므로, 출발지 위조 시 Smurf 증폭에 취약하다.","SYN Flooding은 TCP SYN을 대량 전송하는 공격으로, ICMP 브로드캐스트 응답 결과로 취약성을 추측할 수 없다.","Ping of Death는 65,535바이트를 넘는 ICMP 패킷으로 재조합 오류를 일으키는 공격인데, 결과의 패킷 크기는 64바이트로 정상이다."],"rel":["2-3"],"box":"# ping 202.102.233.255\nPING 202.102.233.255 (202.102.233.255) from 211.13.2.1: 56(84) bytes of data.\n64 bytes from 202.102.233.207: icmp_seq=0 ttl=126 time=3345.4 ms\n64 bytes from 202.102.233.194: icmp_seq=0 ttl=126 time=3542.7 ms (DUP!)\n64 bytes from 202.102.233.193: icmp_seq=0 ttl=126 time=3738.8 ms (DUP!)\n64 bytes from 202.102.233.214: icmp_seq=0 ttl=126 time=4053.1 ms (DUP!)\n64 bytes from 202.102.233.207: icmp_seq=1 ttl=126 time=3316.3 ms\n64 bytes from 202.102.233.194: icmp_seq=1 ttl=126 time=3541.0 ms (DUP!)"},{"n":41,"s":"s3","q":"다음 지문에서 설명하고 있는 API는?","c":["WebCrypto API","REST API","SOAP API","Indexing API"],"a":0,"e":"W3C Web Cryptography API는 브라우저에서 실제 키를 노출하지 않은 채 서명·검증, 해싱, 암·복호화, 키 생성·유도 등 암호 연산을 수행하는 표준 자바스크립트 API이다. REST·SOAP API는 서비스 호출 방식이다.","ce":["W3C Web Cryptography API는 브라우저에서 실제 키를 노출하지 않고 서명·검증, 해싱, 암·복호화, 키 생성·유도를 수행하는 표준 자바스크립트 API이다.","REST API는 HTTP 메서드로 자원을 다루는 웹 서비스 설계 방식으로, 브라우저 내 암호 연산 기능을 제공하지 않는다.","SOAP API는 XML 메시지 기반 웹 서비스 호출 규약으로, 암호 연산용 브라우저 API가 아니다.","Indexing API는 검색 엔진에 페이지 색인을 요청하는 등의 용도로 쓰이며 암호 기능과 무관하다."],"rel":["3-14"],"box":"- 사용자 브라우저를 통해 실제 키를 노출하지 않고 암호화/복호화 등을 처리한다.\n- 실제 키에 대한 접근 요청을 제외한 전자서명 생성 및 검증, 해싱, 암호화, 복호화, 키 생성, 키 유도, 키 탐색 등을 수행한다.\n- 인증서를 사용한 방식은 물론 TLS 클라이언트 인증서와 연동 등으로 보다 나은 인증 방법을 제공한다."},{"n":42,"s":"s3","q":"다음 중 DB 암호화 유형 중 애플리케이션의 수정 없이 사용할 수 있는 유형으로 올바르게 짝지어진 것은?","c":["Plug-In 유형 - API 유형","TDE 방식 - 파일 암호화","API 유형 - TDE 방식","Plug-In 유형 - 파일 암호화"],"a":1,"e":"TDE는 DBMS 커널 수준, 파일 암호화는 OS 수준에서 암·복호화가 이루어지므로 애플리케이션 수정이 필요 없다. API 방식은 애플리케이션 코드에 암·복호화 함수를 넣어야 하고, Plug-In 방식도 쿼리 일부 수정이 필요하다.","ce":["Plug-In 방식은 DB 내부 함수 호출로 일부 쿼리 수정이 필요하고, API 방식은 애플리케이션 코드에 암·복호화 함수를 넣어야 하므로 둘 다 수정이 필요하다.","TDE는 DBMS 커널 수준, 파일 암호화는 OS·파일 시스템 수준에서 암·복호화가 투명하게 이뤄져 애플리케이션 수정이 필요 없다.","TDE는 수정이 필요 없지만 API 방식은 애플리케이션 소스에 암호화 API를 호출하도록 수정해야 하므로 짝이 틀렸다.","파일 암호화는 수정이 필요 없지만 Plug-In 방식은 암·복호화 함수를 쿼리에 넣는 수정이 필요하므로 짝이 틀렸다."],"rel":["3-8"]},{"n":43,"s":"s3","q":"CAPTCHA에 대한 설명으로 잘못된 것은?","c":["HIP(Human Interaction Proof) 기술의 일종이다.","웹사이트 회원가입 시 자동가입방지 등을 위해 사용된다.","튜링 테스트(Turing Test)라고도 부른다.","인공지능의 한계를 이용한 인증 기법이다."],"a":2,"e":"CAPTCHA는 컴퓨터가 사람을 판별하는 구조여서, 사람이 기계를 판별하는 튜링 테스트와 반대인 역 튜링 테스트(Reverse Turing Test)라고 부른다. HIP 기술의 일종으로 자동가입 방지에 쓰인다.","ce":["CAPTCHA는 사람만 풀 수 있는 문제로 사람임을 증명하는 HIP(Human Interaction Proof) 기술의 일종이므로 옳은 설명이다.","회원가입·로그인 시 봇의 자동가입·무차별 대입을 막는 데 사용되므로 옳은 설명이다.","CAPTCHA는 컴퓨터가 사람을 판별하므로, 사람이 기계를 판별하는 튜링 테스트와 반대인 역 튜링 테스트(Reverse Turing Test)라고 부른다.","왜곡 문자·이미지 인식처럼 기계가 풀기 어려운 문제를 내는, 인공지능의 한계를 이용한 기법이므로 옳은 설명이다."]},{"n":44,"s":"s3","q":"XML 기반의 보안기술에 대한 설명 중 옳지 않은 것은?","c":["XML Signature - 무결성 및 부인방지 기능","XKMS - PKI 서비스 기능","SAML - 가용성 보장 기능","XACML - 접근제어 기능"],"a":2,"e":"SAML(Security Assertion Markup Language)은 인증·권한 정보를 교환하는 XML 표준으로 SSO 구현에 사용되며 가용성 보장 기능이 아니다. XKMS는 XML 기반 키 관리(PKI) 서비스, XACML은 접근제어 정책 언어이다.","ce":["XML Signature는 XML 문서에 전자서명을 적용해 무결성·부인방지를 제공하므로 옳은 짝이다.","XKMS는 XML 기반으로 공개키 등록·조회·검증 등 PKI 서비스를 제공하므로 옳은 짝이다.","SAML은 인증·권한 정보(assertion)를 교환해 SSO를 구현하는 XML 표준으로, 가용성 보장 기능과 무관하다.","XACML은 XML로 접근제어 정책을 기술하고 판정하는 언어이므로 옳은 짝이다."],"rel":["3-14"]},{"n":45,"s":"s3","q":"WPKI에 대한 설명으로 적절하지 않은 것은?","c":["무선 인터넷 상에서의 인터넷 뱅킹, 사이버 주식 거래 시 외부 침입이나 정보 누출로부터 보호받을 수 있도록 하는 무선 인터넷 공개키 기반이다.","PKI 기술의 핵심인 비밀성, 무결성, 신원 확인과 부인방지 같은 서비스를 무선 환경에서 구현함으로써 무선 보안을 가능하게 한다.","모바일의 특성을 고려하지 않은 솔루션으로 무선 인터넷 기기와 주고받는 데이터나 애플리케이션에 보안을 지원한다.","규격 내용은 전자서명, WTLS(Wireless Transport Layer Security) 인증서 프로파일, 인증서 DN(Distinguished Name), 인증서 및 알고리즘 관련 OID(Object Identifier) 등으로 구성되어 있다."],"a":2,"e":"WPKI는 무선 단말의 낮은 연산 능력·메모리·대역폭 등 모바일 특성을 고려해 경량화한 무선 공개키 기반 구조이다. 따라서 \"모바일의 특성을 고려하지 않은 솔루션\"은 틀린 설명이다.","ce":["WPKI는 무선 인터넷 뱅킹·주식 거래 등에서 정보 누출을 막기 위한 무선 공개키 기반 구조이므로 옳은 설명이다.","PKI의 기밀성·무결성·인증·부인방지 서비스를 무선 환경에서 구현하므로 옳은 설명이다.","WPKI는 무선 단말의 낮은 연산 능력·메모리·대역폭 등 모바일 특성을 고려해 경량 인증서·WTLS 등으로 최적화한 구조이므로 '고려하지 않은'이 틀렸다.","WPKI 규격은 전자서명, WTLS 인증서 프로파일, 인증서 DN, 알고리즘 OID 등으로 구성되므로 옳은 설명이다."],"rel":["3-14"]},{"n":46,"s":"s3","q":"모바일 앱(App) 보안에 관한 내용으로 틀린 것은?","c":["서비스 지속성을 위해 루팅이나 탈옥된 단말에서도 서비스가 정상적으로 동작되어야 한다.","정상 기능 오동작이나 취약점을 통해 배터리 고갈, 과도한 트래픽 유발, 허가되지 않은 주소로 정보 전송 등이 되어서는 안 된다.","디컴파일 도구를 이용 시 실행파일을 소스코드로 쉽게 변환시킬 수 있으며, 이를 이용하여 앱 위변조 발생이 가능하다. 이를 예방하기 위하여 난독화 도구를 사용하여 패키징한 후 배포해야 한다.","앱 설치 시 비정상적인 파일/디렉터리가 생성되지 않아야 하며, 실행 시에는 불필요한 접근 권한이 존재해서는 안된다. 또한 앱 삭제 시에는 관련된 파일이 완전히 삭제되어야 한다."],"a":0,"e":"루팅·탈옥된 단말은 보안 통제가 무력화되어 앱 위변조, 메모리 해킹, 정보 탈취 위험이 크므로 이를 탐지해 실행을 차단하거나 경고해야 한다. 나머지는 앱 보안 요구사항으로 옳다.","ce":["루팅·탈옥 단말은 OS 보안 통제가 무력화돼 앱 위변조·메모리 해킹 위험이 크므로, 이를 탐지해 실행을 차단하거나 경고해야 한다. '정상 동작'이 틀렸다.","오동작·취약점으로 배터리 고갈, 과도한 트래픽, 비인가 주소로 정보 전송이 발생하지 않아야 하는 것은 옳은 앱 보안 요구사항이다.","디컴파일로 소스가 노출돼 위변조가 가능하므로 난독화 후 배포해야 한다는 것은 옳은 앱 보안 요구사항이다.","설치 시 비정상 파일 생성 금지, 불필요한 권한 제거, 삭제 시 관련 파일 완전 삭제는 옳은 앱 보안 요구사항이다."],"rel":["1-15","3-9"]},{"n":47,"s":"s3","q":"다음 중 메일 서버의 구성요소로만 이루어진 것은?","c":["MUA, MTA, SPF","MUA, URLBL, PGP","IMAP, MDA, POP3","SMTP, SPF, MTA"],"a":2,"e":"메일 서버 측 구성요소는 메일 전송(MTA·SMTP), 메일함 전달(MDA), 사용자 메일 인출(POP3·IMAP) 등이다. MUA는 사용자 측 클라이언트이고, SPF·URLBL·PGP는 스팸 대응·메일 암호화 기술이다.","ce":["MTA는 서버 구성요소이지만 MUA는 사용자 측 메일 클라이언트이고, SPF는 발신자 위조 검증 기술이라 서버 구성요소로만 이뤄지지 않았다.","MUA는 클라이언트, URLBL은 URL 기반 스팸 차단 목록, PGP는 메일 암호화 프로그램으로 모두 메일 서버 구성요소가 아니다.","IMAP·POP3는 서버가 사용자에게 메일을 내려주는 수신 프로토콜 서비스, MDA는 메일을 사용자 메일함에 전달하는 서버 구성요소이다.","SMTP·MTA는 서버 측 전송 요소이지만 SPF는 DNS에 등록하는 발신 서버 인증 기술로 메일 서버 구성요소가 아니다."],"rel":["3-2"]},{"n":48,"s":"s3","q":"다음은 HTTP 프로토콜 중 Header 옵션에 대한 설명이다. 가장 알맞은 것은?","c":["Cookie","User-Agent","Cache-Control","Content-Length"],"a":2,"e":"Cache-Control 헤더(no-cache, no-store 등)는 웹 리소스의 캐싱 여부를 제어하며, 공격자가 no-cache를 넣어 캐시 서버를 우회해 원 서버에 직접 부하를 주는 CC(Cache-Control) 공격에 악용된다. RFC 2616(HTTP/1.1)에 정의되어 있다.","ce":["Cookie 헤더는 클라이언트가 저장한 쿠키를 서버로 보내는 헤더로, 캐싱 제어와 무관하다.","User-Agent는 요청을 보낸 브라우저·OS 정보를 알리는 헤더로, 캐싱 여부를 정하지 않는다.","Cache-Control(no-cache, no-store 등)은 리소스 캐싱을 제어하며, 공격자가 no-cache로 캐시 서버를 우회해 원 서버에 부하를 주는 CC 공격에 악용된다.","Content-Length는 메시지 본문 길이를 바이트로 알리는 헤더로, 캐싱 제어 기능이 없다(조작 시 Slow 공격·스머글링에 쓰임)."],"rel":["3-3"],"box":"해당 옵션의 설정에 따라서 특정 웹 리소스의 캐싱이 되지 않게 하며, 악용되어 사용될 경우 서버에 부하가 발생하는 공격으로도 사용될 수 있다. 이는 RFC 2616(HTTP 1.1)에 규정되어 있다."},{"n":49,"s":"s3","q":"FTP Passive 모드에 대한 설명으로 옳지 않은 것은?","c":["데이터 전송을 위해 1024번 이전 포트를 사용한다.","서버에서 클라이언트를 접속해야 하는 모순을 해결하기 위해 고안된 방식이다.","보안을 위해서는 서버에서 Passive 모드로 사용할 포트를 제한한다.","제어 전송을 위해 서버에서는 21번 포트를 사용한다."],"a":0,"e":"Passive 모드에서 서버는 1024번 이후의 임의 포트를 열어 클라이언트에 알려주고, 클라이언트가 그 포트로 데이터 연결을 맺는다. 1024 미만의 20번 포트로 데이터를 보내는 것은 Active 모드이다.","ce":["Passive 모드에서 서버는 데이터 전송에 1024번 이후의 임의 포트를 연다. 1024 미만(20번) 포트로 데이터를 보내는 것은 Active 모드이다.","Active 모드는 서버가 클라이언트로 데이터 연결을 맺어 방화벽·NAT 뒤 클라이언트에서 문제가 되므로, 이를 해결하려고 클라이언트가 접속하는 Passive 모드가 고안됐다.","Passive 모드는 서버가 임의 고포트를 열기 때문에, 보안상 사용할 포트 범위를 제한하고 방화벽에서 그 범위만 허용해야 한다.","Active·Passive 모드 모두 제어 연결은 서버의 21번 포트를 사용하므로 옳은 설명이다."],"rel":["3-1"]},{"n":50,"s":"s3","q":"DNSSEC의 전자서명과 서명검증 절차를 지원하기 위하여 추가한 신규 리소스 레코드와 관련이 없는 것은?","c":["DNSCA","DNSKEY","RRSIG","NSEC/NSEC3"],"a":0,"e":"DNSSEC가 추가한 리소스 레코드는 DNSKEY(공개키), RRSIG(서명), DS(위임 서명자), NSEC/NSEC3(부재 증명)이다. DNSCA라는 레코드는 존재하지 않는다.","ce":["DNSCA라는 리소스 레코드는 DNSSEC에 존재하지 않는다. DNSSEC는 PKI의 CA 구조 대신 DS 레코드로 신뢰 체인을 만든다.","DNSKEY는 존(zone)의 서명 검증용 공개키를 담는 DNSSEC 신규 레코드이다.","RRSIG는 각 리소스 레코드 집합에 대한 전자서명 값을 담는 DNSSEC 신규 레코드이다.","NSEC/NSEC3는 질의한 이름이 존재하지 않음을 서명으로 증명(부재 증명)하는 DNSSEC 신규 레코드이다."],"rel":["3-7"]},{"n":51,"s":"s3","q":"개발된 소스 코드를 살펴봄으로써 코드 상의 취약점을 찾는 방식은?","c":["Black Box Testing","White Box Testing","Green Box Testing","Brown Box Testing"],"a":1,"e":"화이트박스 테스트는 소스 코드의 내부 구조·논리를 직접 검토해 취약점을 찾는 방식이다. 블랙박스 테스트는 내부 코드 없이 입력과 출력만으로 기능·취약점을 검증한다.","ce":["블랙박스 테스트는 내부 코드를 보지 않고 입력과 출력만으로 기능·취약점을 검증하는 방식이다.","화이트박스 테스트는 소스 코드의 내부 구조·논리를 직접 검토해 취약점을 찾는 방식으로 지문과 일치한다.","그린박스 테스트는 표준화된 테스트 기법 명칭이 아니며, 소스 코드 검토 방식을 뜻하지 않는다.","브라운박스 테스트는 소스 코드 기반 취약점 점검을 뜻하는 표준 용어가 아니다."],"rel":["3-9"]},{"n":52,"s":"s3","q":"메일 수신 서버 또는 웹 메일 서버로부터 전자우편 메시지를 자신의 컴퓨터 단말 장치로 전송받는 데 사용되는 프로토콜이 아닌 것은?","c":["IMAP(Internet Mail Access Protocol)","RTP(Realtime Transport Protocol)","POP(Post Office Protocol)","HTTP(HyperText Transfer Protocol)"],"a":1,"e":"RTP는 음성·영상 등 실시간 멀티미디어 스트림 전송용 프로토콜로 메일 수신과 무관하다. 메일 서버에서 메시지를 받는 데는 POP3·IMAP, 웹 메일은 HTTP를 사용한다.","ce":["IMAP은 메일을 서버에 둔 채 폴더·동기화로 관리하며 단말에서 열람하는 메일 수신 프로토콜이다.","RTP는 음성·영상 등 실시간 멀티미디어 스트림을 UDP로 전송하는 프로토콜로, 메일 수신과 무관하다.","POP(POP3)는 메일 서버에서 메시지를 단말로 내려받는 메일 수신 프로토콜이다.","HTTP는 웹 메일 서버의 메일을 브라우저로 받아 보는 데 사용되므로 메일 수신에 쓰인다."],"rel":["3-2"]},{"n":53,"s":"s3","q":"㉠, ㉡에 들어갈 용어로 올바르게 짝지어진 것은?","c":["㉠ 작업증명 ㉡ 채굴","㉠ 작업증명 ㉡ 송금","㉠ 지분증명 ㉡ 채굴","㉠ 지분증명 ㉡ 송금"],"a":0,"e":"비트코인은 대량의 해시 연산으로 조건을 만족하는 논스(nonce)를 찾는 작업증명(PoW) 방식으로 블록을 추가하며, 그 보상으로 코인을 얻는 것을 채굴이라 한다. 지분증명(PoS)은 보유 지분에 따라 블록 생성 권한을 부여하는 방식이다.","ce":["비트코인은 대량 해시 연산으로 조건을 만족하는 nonce를 찾는 작업증명(PoW)으로 블록을 추가하고, 그 보상으로 코인을 얻는 것을 채굴이라 한다.","㉠ 작업증명은 맞지만, 블록 추가로 코인을 획득하는 것은 송금이 아니라 채굴이다. 송금은 코인을 다른 주소로 보내는 거래이다.","지분증명(PoS)은 보유 지분에 따라 블록 생성 권한을 주는 방식으로 대량 해시 연산이 필요 없다. 비트코인은 PoW를 쓴다.","㉠ 지분증명과 ㉡ 송금 모두 틀렸다. 비트코인은 작업증명, 보상 획득은 채굴이다."],"rel":["1-15"],"box":"비트코인의 경우, 블록체인에 새로운 블록을 추가하기 위해서는 대량의 해시(hash) 연산을 통해 조건에 맞는 난수를 찾는 ( ㉠ )이 필요하며, 이렇게 새로운 블록을 추가함으로써 코인을 획득하는 것을 흔히 ( ㉡ )이라고 한다."},{"n":54,"s":"s3","q":"HWP, TXT, PDF, 도면 등 업무에 사용하는 파일을 암호화하여, 외부자는 물론 허가된 내부자에 의한 주요 정보유출을 원천 차단함으로써 기업 정보 유출을 막는 솔루션은?","c":["IPS(Intrusion Prevention System)","DRM(Digital Rights Management)","ESM(Enterprise Security Management)","VPN(Virtual Private Network)"],"a":1,"e":"문서 DRM은 업무 파일을 암호화하고 열람·편집·출력 권한을 통제해, 파일이 반출되더라도 권한 없는 사용자는 내용을 볼 수 없게 한다. IPS는 네트워크 침입 차단, VPN은 통신 구간 암호화 기술이다.","ce":["IPS는 네트워크 트래픽에서 공격을 탐지해 차단하는 장비로, 업무 파일 자체를 암호화하지 않는다.","문서 DRM은 업무 파일을 암호화하고 열람·편집·출력 권한을 통제해, 반출되더라도 권한 없는 사용자는 내용을 볼 수 없게 한다.","ESM은 여러 보안 장비의 이벤트를 통합 관리·분석하는 솔루션으로 파일 암호화 기능이 없다.","VPN은 통신 구간을 암호화하는 기술로, 저장된 파일을 암호화해 내부자 유출을 막지 않는다."],"rel":["3-12"]},{"n":55,"s":"s3","q":"다음 중 SSO에 대한 설명으로 적절하지 못한 것은?","c":["하나의 아이디로 여러 사이트를 이용할 수 있는 시스템이다.","싱글사인온(SSO)을 사용하면 응용서비스 로그인 시간을 줄여준다.","SSO를 이용하면 개별 애플리케이션 단위로 동일한 암호를 설정하게 되므로 편리하기는 하지만 보안의 입장에서는 권장하지 않는다.","SSO 솔루션을 통해 직원이 어디서 어떤 응용서비스에 접속하여 무엇을 하는지에 대한 로그정보 저장이 가능하다."],"a":2,"e":"SSO는 중앙 인증 서버에서 한 번 인증하면 발급된 토큰·티켓으로 여러 서비스에 접근하는 방식으로, 애플리케이션마다 같은 암호를 따로 설정하는 방식이 아니다. 중앙 인증으로 접속 로그를 통합 관리할 수 있다.","ce":["SSO는 한 번의 인증으로 하나의 계정으로 여러 사이트·시스템을 이용하게 하므로 옳은 설명이다.","서비스마다 반복 로그인하지 않아도 되므로 로그인 시간이 줄어 옳은 설명이다.","SSO는 중앙 인증 서버에서 한 번 인증 후 토큰·티켓으로 여러 서비스에 접근하는 방식으로, 애플리케이션마다 같은 암호를 설정하는 방식이 아니다.","인증이 중앙에서 이뤄지므로 누가 어디서 어떤 서비스에 접속했는지 로그를 통합 저장·관리할 수 있어 옳은 설명이다."],"rel":["4-9"]},{"n":56,"s":"s3","q":"디지털 포렌식의 원칙 중 어느 원칙에 대한 설명인가?","c":["연계보관성의 원칙","정당성의 원칙","무결성의 원칙","재현의 원칙"],"a":0,"e":"증거 획득부터 이송·분석·보관·법정 제출까지 각 단계의 담당자와 인계 과정을 명확히 기록해 추적 가능하게 하는 것은 연계보관성(Chain of Custody) 원칙이다. 무결성 원칙은 증거가 획득 이후 변경되지 않았음을 해시 등으로 입증하는 것이다.","ce":["증거의 획득·이송·분석·보관·법정 제출 각 단계의 담당자와 인계 과정을 기록해 추적 가능하게 하는 것이 연계보관성(Chain of Custody) 원칙이다.","정당성의 원칙은 증거가 적법한 절차로 수집되어야 한다는 원칙으로, 위법 수집 증거는 증거능력을 잃는다.","무결성의 원칙은 수집된 증거가 이후 변경되지 않았음을 해시값 비교 등으로 입증해야 한다는 원칙이다.","재현의 원칙은 같은 조건에서 같은 절차로 분석하면 같은 결과가 나와야 한다는 원칙이다."],"rel":["3-11"],"box":"증거가 획득된 다음 증거에 대한 이송, 분석, 보관, 법정 제출이라는 일련의 과정 및 각 과정마다 담당자가 명확해야 하며 이에 대한 추적이 가능해야 한다."},{"n":57,"s":"s3","q":"다음 지문이 설명하는 소프트웨어 보안 약점을 고르면?","c":["크로스사이트 요청 위조 공격(CSRF)","크로스 사이트 스크립트(XSS)","경로 조작 및 자원 삽입","SQL 삽입"],"a":0,"e":"CSRF는 사용자가 인지하지 못한 상태에서 사용자의 인증된 세션으로 공격자가 의도한 요청(수정·삭제·등록)을 서버에 보내게 하는 공격이다. XSS는 사용자 브라우저에서 스크립트를 실행시키는 공격으로, 서버 요청 위조가 핵심이 아니다.","ce":["CSRF는 사용자가 인지하지 못한 채 인증된 세션으로 공격자가 의도한 요청(수정·삭제·등록)을 서버에 보내게 하는 공격으로 지문과 일치한다.","XSS는 사용자 브라우저에서 악성 스크립트를 실행시켜 쿠키 탈취 등을 노리는 공격으로, 요청 의도 미확인에 따른 요청 위조와 구별된다.","경로 조작 및 자원 삽입은 입력값으로 파일 경로·자원 식별자를 조작해 허가되지 않은 자원에 접근하는 약점이다.","SQL 삽입은 입력값에 SQL 구문을 넣어 DB 쿼리를 조작하는 약점으로, 사용자 의도와 무관한 요청 전송과 다르다."],"rel":["3-6"],"box":"특정 웹사이트에 대해서 사용자가 인지하지 못한 상황에서 사용자의 의도와는 무관하게 공격자가 의도한 행위(수정, 삭제, 등록 등)를 요청하게 하는 공격을 말한다. 웹 응용프로그램이 사용자로부터 받은 요청에 대해서 사용자가 의도한 대로 작성되고 전송된 것인지 확인하지 않을 경우 발생 가능하고 특히 해당 사용자가 관리자인 경우 사용자 권한 관리, 게시물 삭제, 사용자 등록 등 관리자 권한으로만 수행 가능한 기능을 공격자의 의도대로 실행시킬 수 있게 된다."},{"n":58,"s":"s3","q":"다음 지문에서 설명하는 것은?","c":["이상행위 탐지시스템(FDS)","침입탐지시스템(IDS)","블록체인(Blockchain)","SET(Secure Electronic Transaction)"],"a":0,"e":"FDS(Fraud Detection System)는 결제자의 단말·접속·거래 정보를 수집해 정상 패턴과 다른 이상 거래를 탐지하고 차단하는 시스템이다. SET는 신용카드 결제 보안 프로토콜로 이상 거래 탐지 기능이 아니다.","ce":["FDS는 결제자의 단말·접속·거래 정보를 수집해 정상 패턴과 다른 이상 결제를 탐지·차단하는 시스템으로 지문과 일치한다.","IDS는 네트워크·호스트의 침입 행위를 탐지하는 시스템으로, 결제 패턴 기반 이상 거래 차단이 목적이 아니다.","블록체인은 분산 원장으로 거래 기록의 위변조를 어렵게 하는 기술로, 이상 결제를 탐지하는 방식이 아니다.","SET은 이중서명·인증서로 카드 결제 정보를 보호하는 전자결제 프로토콜로, 빅데이터 기반 이상 거래 탐지와 무관하다."],"rel":["3-13"],"box":"결제자의 다양한 정보를 수집해 패턴을 만든 후 패턴과 다른 이상 결제를 잡아내고, 결제 경로를 차단하는 보안 방식으로 보안 솔루션에 의존하던 기존 보안과 달리, 빅데이터를 바탕으로 적극적인 보안 개입을 하는 것이 특징이다."},{"n":59,"s":"s3","q":"다음 지문의 빈칸 ㉠, ㉡에 들어갈 내용이 올바르게 짝지어 진 것은?","c":["A의 공개키, B의 개인키","비밀키, A의 개인키","비밀키, B의 공개키","A의 개인키, B의 공개키"],"a":2,"e":"SET의 전자봉투는 메시지 암호화에 사용한 대칭 비밀키(세션키)를 수신자 B의 공개키로 암호화한 것으로, B만 자신의 개인키로 열어 비밀키를 얻을 수 있다.","ce":["A의 공개키는 누구나 알 수 있어 봉투 보호에 쓸 수 없고, B의 개인키는 B만 가지므로 A가 봉투 생성에 사용할 수 없다.","비밀키는 맞지만, A의 개인키로 암호화하면 누구나 A의 공개키로 열 수 있어 비밀키가 보호되지 않는다.","전자봉투는 메시지 암호화에 쓴 대칭 비밀키(세션키)를 수신자 B의 공개키로 암호화한 것으로, B만 자신의 개인키로 열 수 있다.","A의 개인키는 전자서명 생성에 쓰는 키이며, 전자봉투에는 암호화 대상인 비밀키가 들어가야 하므로 짝이 틀렸다."],"rel":["3-13"],"box":"SET에서는 대칭키 방식의 암호화를 위해 송·수신자 간에 비밀키 교환이 이루어진다. 비밀키 교환을 위해 A가 B에게 전자봉투를 생성하여 전송할 때 전자봉투 생성에 필요한 것은 ( ㉠ )와 ( ㉡ )이다."},{"n":60,"s":"s3","q":"다음 지문에서 설명하는 보안 기술은 무엇인가?","c":["SOAP(Security Orchestration Automation Platform)","SOAR(Security Orchestration Automation and Response)","SIEM(Security Information and Events Management)","UEBA(User and Entity Behavior Analytics)"],"a":1,"e":"SOAR는 보안 오케스트레이션·자동화(SOA), 보안 사고 대응(SIRP), 위협 인텔리전스(TIP)를 포괄해 위협 대응 수준을 자동 분류하고 표준 절차(플레이북)에 따라 대응을 자동화하는 플랫폼이다. SIEM은 로그 수집·상관분석이 중심이고, UEBA는 사용자·개체 행위 이상 분석 기술이다.","ce":["SOAP은 원래 XML 기반 웹 서비스 메시지 프로토콜(Simple Object Access Protocol)의 약어로, 보안 대응 플랫폼 명칭이 아니다.","SOAR는 보안 오케스트레이션·자동화(SOA), 사고 대응(SIRP), 위협 인텔리전스(TIP)를 포괄해 대응 수준을 자동 분류하고 플레이북으로 대응을 자동화하는 플랫폼이다.","SIEM은 로그·이벤트를 수집해 상관분석·탐지하는 데 중점을 두며, 대응 절차 자동화와 사람-기계 협업 플랫폼까지 포괄하지 않는다.","UEBA는 사용자·개체의 행위를 기계학습으로 분석해 이상 행위를 탐지하는 기술로, 대응 자동화 플랫폼이 아니다."],"rel":["1-11"],"box":"SOA, SIRP, TIP를 폭넓게 포함하는 개념으로 보안 운영에 있어 유입되는 위협에 대해 대응 레벨을 자동으로 분류하고, 표준화된 업무 프로세스에 따라 사람과 기계가 유기적으로 협력할 수 있도록 지원하는 대응 플랫폼을 말한다. 수집된 모든 로그 및 이벤트를 바탕으로 위협 인텔리전스와 능동적 탐지를 통해 침해정보와 영향도를 도출하고 이를 개선하기 위한 시스템 변경을 자동화할 수 있다."},{"n":61,"s":"s4","q":"다음 지문이 설명하고 있는 암호 공격방식은?","c":["암호문 단독 공격","기지 평문 공격","선택 평문 공격","선택 암호문 공격"],"a":2,"e":"공격자가 암호기에 접근해 원하는 평문을 선택하고 그에 대응하는 암호문을 얻어 키나 평문을 추정하는 것은 선택 평문 공격(CPA)이다. 기지 평문 공격은 이미 알려진 평문-암호문 쌍을 이용하고, 선택 암호문 공격은 복호기에 접근해 암호문을 선택한다.","ce":["암호문 단독 공격은 암호문만 가지고 평문이나 키를 추정하는 공격으로, 암호기에 접근해 평문을 선택하지 않는다.","기지 평문 공격은 이미 알려진 평문-암호문 쌍을 이용하는 공격으로, 공격자가 평문을 직접 선택하지는 못한다.","암호기에 접근해 원하는 평문을 선택하고 대응 암호문을 얻어 키·평문을 추정하는 것이 선택 평문 공격(CPA)이다.","선택 암호문 공격은 복호기에 접근해 원하는 암호문을 선택하고 대응 평문을 얻는 공격이다."],"rel":["4-1"],"box":"암호 해독자가 사용된 암호기에 접근할 수 있어 평문 P를 선택하여 그 평문 P에 해당하는 암호문 C를 얻은 다음 키나 평문을 추정하여 암호를 해독하는 방법"},{"n":62,"s":"s4","q":"수동적, 능동적 공격 방식의 예가 올바르게 짝지어진 것은?","c":["[수동적 공격] 트래픽 분석 - [능동적 공격] 삽입공격","[수동적 공격] 재생공격 - [능동적 공격] 삭제공격","[수동적 공격] 메시지 변조 - [능동적 공격] 재생공격","[수동적 공격] 메시지 변조 - [능동적 공격] 도청"],"a":0,"e":"수동적 공격은 데이터를 변경하지 않고 엿보는 도청·트래픽 분석이고, 능동적 공격은 데이터를 변경·생성하는 삽입·삭제·재생·변조·서비스 거부이다. 재생공격과 메시지 변조는 능동적 공격, 도청은 수동적 공격이므로 ②~④는 틀리다.","ce":["트래픽 분석은 데이터를 변경하지 않는 수동적 공격, 삽입공격은 데이터를 생성·주입하는 능동적 공격으로 올바른 짝이다.","재생공격은 캡처한 메시지를 다시 보내 데이터 흐름에 개입하므로 수동적이 아니라 능동적 공격이다.","메시지 변조는 데이터를 바꾸는 능동적 공격이므로 수동적 공격 칸에 들어갈 수 없다.","메시지 변조는 능동적 공격이고, 도청은 데이터를 변경하지 않는 수동적 공격이라 수동·능동이 뒤바뀌었다."],"rel":["4-1"],"box":"번호 | [수동적 공격] | [능동적 공격]\n① | 트래픽 분석 | 삽입공격\n② | 재생공격 | 삭제공격\n③ | 메시지 변조 | 재생공격\n④ | 메시지 변조 | 도청"},{"n":63,"s":"s4","q":"블록 암호 알고리즘을 사용하여 메시지 인증 코드(MAC)를 생성할 때 가장 적합한 블록 암호 모드는 무엇인가?","c":["CBC 모드","ECB 모드","OFB 모드","CTR 모드"],"a":0,"e":"CBC 모드는 이전 암호 블록이 다음 블록 암호화에 연쇄적으로 반영되어 마지막 블록이 메시지 전체에 의존하므로 이를 MAC(CBC-MAC)으로 사용한다. ECB는 블록 간 연쇄가 없고, OFB·CTR은 키스트림 방식이라 MAC 생성에 부적합하다.","ce":["CBC 모드는 이전 암호 블록이 다음 블록 암호화에 연쇄 반영되어 마지막 블록이 메시지 전체에 의존하므로 이를 MAC(CBC-MAC)으로 쓴다.","ECB 모드는 블록을 독립적으로 암호화해 블록 간 연쇄가 없으므로, 블록 순서 변경·치환을 탐지하지 못해 MAC 생성에 부적합하다.","OFB 모드는 키스트림을 만들어 평문과 XOR하는 스트림 방식으로, 메시지 전체에 의존하는 인증값을 만들지 않는다.","CTR 모드는 카운터를 암호화한 키스트림을 XOR하는 방식이라 블록 간 연쇄가 없어 단독으로는 MAC 생성에 부적합하다(GCM은 별도 GHASH 사용)."],"rel":["4-3"]},{"n":64,"s":"s4","q":"인증 수단으로는 일반적으로 알고 있는 것, 자신의 모습, 가지고 있는 것, 위치하는 곳 등의 방식을 사용한다. 다음 인증 방식의 예로 옳지 않은 것은?","c":["알고 있는 것(something you know) - 사용자 아이디, 아이디에 해당하는 패스워드, OTP(One Time Password) 생성기","자신의 모습(something you are) - 지문, 망막, 홍채","가지고 있는 것(something you have) - 스마트 카드, 신분증","위치하는 곳(somewhere you are) - 사용자 IP 주소, 콜백(call back)"],"a":0,"e":"OTP 생성기(토큰)는 사용자가 소지하는 물리적 장치이므로 가지고 있는 것(소유 기반)에 해당한다. 알고 있는 것(지식 기반)의 예는 패스워드·PIN 등이다.","ce":["아이디·패스워드는 지식 기반이지만, OTP 생성기는 사용자가 소지하는 장치이므로 알고 있는 것이 아니라 가지고 있는 것(소유 기반)에 해당한다.","지문·망막·홍채는 사용자의 신체 특징을 이용하는 생체 기반(something you are) 인증의 예로 옳다.","스마트카드·신분증은 사용자가 소지한 물건으로 인증하는 소유 기반(something you have) 인증의 예로 옳다.","IP 주소 확인과 등록된 번호로 되거는 콜백은 사용자의 위치를 이용하는 위치 기반(somewhere you are) 인증의 예로 옳다."],"rel":["4-8"]},{"n":65,"s":"s4","q":"다음 중 사용자 인증 및 개인 식별에 대한 설명으로 옳지 않은 것은?","c":["사용자 인증 기술은 A가 B에게 자신이 A임을 확인시켜 줄 수 있는 기술이다.","개인 식별 기술은 B가 C에게 자신이 B가 아니라고 확인시켜 줄 수 있는 기술이다.","개인을 식별하는 방법으로 지문(생체정보), 보안 토큰(사용자 소유), 비밀번호(사용자 지식) 등이 사용될 수 있다.","사용자 인증시 보안 요구사항으로는 식별과 인증, 인가 및 책임추적성 등을 들 수 있다."],"a":1,"e":"개인 식별은 사용자가 자신이 누구인지를 상대에게 제시·확인시키는 것이지, 자신이 누구가 아니라고 확인시키는 기술이 아니다. 인증은 제시한 신원이 맞는지를 지식·소유·생체 정보로 검증하는 과정이다.","ce":["사용자 인증은 A가 B에게 자신이 A임을 증명하는 기술이므로 옳은 설명이다.","개인 식별은 사용자가 자신이 누구인지를 상대에게 제시·확인시키는 것으로, 자신이 '누가 아니라고' 확인시키는 기술이 아니다.","지문(생체), 보안 토큰(소유), 비밀번호(지식)는 개인을 식별·인증하는 대표 수단이므로 옳은 설명이다.","사용자 인증의 보안 요구사항으로 식별·인증·인가·책임추적성(IAAA)을 드는 것은 옳은 설명이다."],"rel":["4-8"]},{"n":66,"s":"s4","q":"다음 중 인증서 폐지 목록의 기본 영역에 포함되지 않는 것은?","c":["서명 알고리즘","발급자","버전","유효 기간"],"a":3,"e":"X.509 CRL 기본 영역은 버전, 서명 알고리즘, 발급자, 최근 갱신일(This Update), 다음 갱신일(Next Update), 폐지된 인증서 목록(일련번호·폐지 일자)으로 구성된다. 유효 기간(Validity)은 인증서 자체의 기본 필드이다.","ce":["서명 알고리즘은 CRL에 서명한 알고리즘 식별자로 CRL 기본 영역에 포함된다.","발급자는 CRL을 발행한 CA의 DN으로 CRL 기본 영역에 포함된다.","버전은 CRL 형식 버전(v2 등)으로 CRL 기본 영역에 포함된다.","유효 기간(Validity, notBefore·notAfter)은 인증서 자체의 기본 필드이다. CRL은 대신 이번 갱신일(This Update)·다음 갱신일(Next Update)을 가진다."],"rel":["4-7"]},{"n":67,"s":"s4","q":"다음은 접근통제가 이루어지는 과정을 설명한 것이다. 빈칸 ㉠에 공통적으로 들어갈 용어는?","c":["상주엔진","접근통제 API","시스템호출","보안커널"],"a":3,"e":"주체의 모든 접근 요청을 가로채 규칙에 따라 허가·거부하고 기록하는 참조 모니터(Reference Monitor)를 구현한 것이 보안 커널(Security Kernel)이다. 보안 커널은 우회 불가, 변조 불가, 검증 가능해야 한다.","ce":["상주엔진은 접근통제 이론의 표준 용어가 아니며, 모든 접근 요청을 가로채 판정하는 구성요소를 가리키지 않는다.","접근통제 API는 응용프로그램이 권한 확인을 요청하는 인터페이스일 뿐, 모든 접근을 우회 불가하게 가로채 판정하는 핵심 요소가 아니다.","시스템 호출은 프로세스가 커널 기능을 요청하는 인터페이스로, 접근 판정 주체가 아니라 판정 대상 요청의 통로이다.","주체의 모든 접근 요청을 가로채 규칙에 따라 허가·거부하고 기록하는 참조 모니터를 구현한 것이 보안 커널이며, 우회·변조 불가, 검증 가능해야 한다."],"rel":["4-10","1-1"],"box":"- 주체가 특정 객체에 접근을 요청하면 ( ㉠ )은(는) 이를 가로챈다.\n- ( ㉠ )은(는) 자신이 가지고 있는 기본규칙에 따라 접근권한(조직이 정의한 정책에 따라 설정됨)을 결정한다.\n- ( ㉠ )은(는) 정의된 접근규칙에 따라 접근을 허가 혹은 거부한다.\n- ( ㉠ )에서 처리되는 모든 접근 요청은 이후의 추적 및 분석을 위해 기록된다."},{"n":68,"s":"s4","q":"생체인식 기술이 가져야 할 보안 요구조건과 거리가 먼 것은?","c":["보편성(Universality)","구별성(Uniqueness)","일시성(Temporality)","획득성(Collectability)"],"a":2,"e":"생체인식 요구조건은 보편성, 유일성(구별성), 영구성(Permanence), 획득성, 정확성, 수용성, 기만 방지 등이다. 생체 특성은 시간이 지나도 변하지 않아야 하므로 일시성은 영구성과 반대되는 개념이다.","ce":["보편성은 모든 사람이 해당 생체 특성을 가지고 있어야 한다는 요구조건이다.","구별성(유일성)은 사람마다 특성이 달라 개인을 구별할 수 있어야 한다는 요구조건이다.","생체 특성은 시간이 지나도 변하지 않는 영구성(Permanence)이 필요하므로, 일시성은 요구조건과 반대되는 개념이다.","획득성은 센서로 특성을 쉽게 측정·정량화할 수 있어야 한다는 요구조건이다."],"rel":["4-8"]},{"n":69,"s":"s4","q":"다음 중 전자서명의 요구사항으로 가장 적절하지 않은 것은?","c":["전자서명 생성이 비교적 용이해야 한다.","전자서명을 위조하는 것이 계산적으로 실행 불가능해야 한다.","기억장소에 전자서명의 복사본을 유지하는 것이 실용적이어야 한다.","위조와 부인을 방지하기 위하여 수신자에 대한 정보를 사용해야 한다."],"a":3,"e":"전자서명은 위조·부인을 방지하기 위해 서명자(송신자)만이 가진 고유 정보, 즉 서명자의 개인키를 사용해야 한다. 수신자 정보를 사용하면 서명자를 특정할 수 없다.","ce":["서명자가 서명을 쉽게 생성할 수 있어야 실용적이므로 전자서명의 요구사항에 해당한다.","서명자의 개인키 없이 서명을 위조하는 것은 계산적으로 불가능해야 하므로 요구사항에 해당한다.","전자서명 복사본을 저장·보관하는 것이 실용적이어야 검증·분쟁 해결에 쓸 수 있어 요구사항에 해당한다.","위조·부인 방지를 위해서는 수신자가 아니라 서명자(송신자)만 가진 고유 정보, 즉 서명자 개인키를 사용해야 한다."],"rel":["4-6"]},{"n":70,"s":"s4","q":"다음 중 해시함수가 적용되는 분야를 모두 고른 것은?","c":["가, 나","가, 나, 라","가, 나, 다, 라","나, 라"],"a":1,"e":"해시함수는 전자서명(메시지 다이제스트 서명), 메시지 인증(MAC·HMAC), 패스워드 저장(해시 기반 암호화)에 적용된다. 해시는 일방향이라 원본 복원이 불가능하므로 데이터 압축 용도로 쓸 수 없다.","ce":["가·나는 맞지만, 해시 기반 패스워드 저장(라)도 해시함수 적용 분야이므로 빠졌다.","전자서명(가, 메시지 다이제스트에 서명), 메시지 인증(나, HMAC), 패스워드 기반 암호화(라, 해시 저장·키 유도)가 해시 적용 분야이다.","데이터 압축(다)은 원본 복원이 가능해야 하는데, 해시는 일방향이라 복원할 수 없으므로 포함할 수 없다.","나·라는 맞지만 전자서명(가)이 빠졌다. 전자서명은 메시지 해시값에 서명하는 대표적 해시 적용 분야이다."],"rel":["4-5"],"box":"가. 전자서명\n나. 메시지인증\n다. 데이터 압축\n라. 패스워드기반 암호화"},{"n":71,"s":"s4","q":"다음은 메시지 인증 절차를 설명한 것이다. 괄호 안에 들어갈 단어가 순서대로 나열된 것은?","c":["a 송신자 - b 개인키 - c 송신자 - d 공개키","a 송신자 - b 개인키 - c 송신자 - d 개인키","a 수신자 - b 개인키 - c 수신자 - d 공개키","a 송신자 - b 공개키 - c 수신자 - d 개인키"],"a":0,"e":"전자서명 방식의 메시지 인증은 송신자가 해시값을 자신의 개인키로 암호화(서명)하고, 수신자는 송신자의 공개키로 복호화한 값과 직접 계산한 해시값을 비교한다. 수신자 공개키로 암호화하면 기밀성은 얻지만 송신자 인증은 되지 않는다.","ce":["송신자가 해시값을 자신의 개인키로 암호화(서명)하고, 수신자는 송신자의 공개키로 복호화해 직접 계산한 해시값과 비교한다.","송신자 개인키로 서명한 값은 송신자의 공개키로 복호화해야 한다. 수신자는 송신자 개인키를 가질 수 없다.","수신자 개인키로 암호화하는 것은 수신자만 가능한 일이라 송신자의 서명 절차가 될 수 없다.","송신자가 공개키로 암호화하면 누구나 같은 값을 만들 수 있어 송신자 인증이 되지 않고, 수신자 개인키 복호화는 기밀성 절차이다."],"rel":["4-6"],"box":"- 송신자가 메시지를 생성한다.\n- 해시함수를 통해 메시지의 해시값을 생성한 후 이를 ( a )의 ( b )를 이용하여 암호화한다.\n- 암호화된 값을 메시지에 덧붙이고 압축한 후 수신자에게 전송한다.\n- 수신자가 파일을 수신하여 압축을 푼다.\n- 전자서명 부분을 분리한 후 ( c )의 ( d )로 복호화한다.\n- 해시함수를 통해 메시지 부분에 대한 해시값을 얻는다.\n- 두 결과의 값이 동일하면 메시지가 인증된다."},{"n":72,"s":"s4","q":"공개키 암호방식에 이용되는 이론적으로 풀기 어려운 수학 문제들은 대부분 소인수 분해 문제, 이산대수 문제, NP-complete 문제 등으로 분류할 수 있다. 다음 중 이산대수 문제에 기반한 공개키 알고리즘과 가장 거리가 먼 것은?","c":["ECC","Knapsack","DSA","ElGamal"],"a":1,"e":"Knapsack(배낭) 암호는 NP-complete 문제인 부분합(배낭) 문제에 기반한다. ElGamal·DSA는 유한체 이산대수, ECC는 타원곡선 이산대수 문제에 기반한다.","ce":["ECC는 타원곡선 위의 이산대수 문제(ECDLP)에 기반한 공개키 알고리즘이다.","Knapsack(배낭) 암호는 NP-complete 문제인 부분합(배낭) 문제에 기반하므로 이산대수 문제와 가장 거리가 멀다.","DSA는 유한체 곱셈군의 이산대수 문제에 기반한 전자서명 알고리즘이다.","ElGamal은 유한체 이산대수 문제(및 Diffie-Hellman 문제)에 기반한 공개키 암호이다."],"rel":["4-4"]},{"n":73,"s":"s4","q":"패스워드는 사용자 인증에 흔히 사용되는 기법이지만 보안에 매우 취약한 문제가 있다. 다음 지문의 빈칸 ㉠에 들어갈 용어로 적절한 것은?","c":["핀(PIN)","패스프레이즈(Passphrase)","풀(Pool)","사전(Dictionary)"],"a":3,"e":"패스워드로 자주 쓰일 가능성이 높은 단어를 모은 목록을 사전(Dictionary)이라 하며, 이를 대입하는 것이 사전 공격이다. 패스프레이즈는 여러 단어로 구성한 긴 패스워드를 의미한다.","ce":["PIN은 주로 숫자로 된 짧은 개인 식별 비밀번호로, 공격자가 선별한 단어 모음을 가리키지 않는다.","패스프레이즈는 여러 단어로 구성한 긴 패스워드로, 오히려 사전 공격에 강한 패스워드 방식이다.","풀(Pool)은 패스워드 공격에서 선별 단어 목록을 뜻하는 표준 용어가 아니다.","패스워드로 쓰일 가능성이 높은 단어를 선별한 목록을 사전(Dictionary)이라 하며, 이를 대입하는 것이 사전 공격이다."],"rel":["4-1"],"box":"사용자는 기억하기 쉬운 단어를 패스워드로 사용할 가능성이 높다. 이런 이유로 공격자는 패스워드로 사용될 가능성이 높은 단어를 적절히 선별할 경우 패스워드 공격의 성공 확률을 높일 수 있으며, 이렇게 선별된 단어 모음을 흔히 ( ㉠ )이라고 부른다."},{"n":74,"s":"s4","q":"자신의 비밀을 노출하지 않으면서 자신이 비밀을 알고 있다는 것을 증명하는 인증 방법은?","c":["패스워드","영지식 인증","바이오매트릭스","시도-응답 인증"],"a":1,"e":"영지식 증명(Zero-Knowledge Proof)은 증명자가 비밀 자체를 전혀 노출하지 않고 검증자에게 비밀을 알고 있다는 사실만 확신시키는 인증 방법이다. 패스워드는 비밀을 직접 전달하고, 시도-응답은 비밀로 계산한 응답을 보내는 방식이다.","ce":["패스워드 인증은 비밀(패스워드)을 검증자에게 직접 전달하거나 비교하므로 비밀이 노출될 수 있다.","영지식 인증(증명)은 비밀 자체를 전혀 노출하지 않고 검증자에게 비밀을 알고 있다는 사실만 확신시키는 방법이다.","바이오메트릭스는 지문·홍채 등 신체 특징으로 인증하는 방식으로, 비밀을 안다는 사실을 증명하는 구조가 아니다.","시도-응답 인증은 비밀로 계산한 응답을 보내 비밀을 직접 전송하지는 않지만, 응답에서 정보가 누출될 여지가 있어 영지식성을 보장하지 않는다."],"rel":["4-1"]},{"n":75,"s":"s4","q":"다음 지문에서 설명하는 암호방식은?","c":["동형(Homomorphic) 암호화","형태보존(Format Preserving) 암호화","순서보존(Order Preserving) 암호화","블록체인(Block Chain) 암호화"],"a":0,"e":"동형암호는 암호문끼리 연산한 결과를 복호화하면 평문끼리 연산한 결과와 같아, 복호화 없이 암호화된 데이터를 분석·연산할 수 있다. 형태보존 암호화는 암호문이 평문과 같은 형식·길이를 유지하는 방식이다.","ce":["동형암호는 암호문끼리 연산한 결과를 복호화하면 평문끼리 연산한 결과와 같아, 복호화 없이 암호화된 데이터를 분석·연산할 수 있다.","형태보존 암호화(FPE)는 암호문이 평문과 같은 형식·길이를 유지하게 해 기존 DB 스키마를 바꾸지 않는 방식으로, 암호문 연산 기능이 아니다.","순서보존 암호화(OPE)는 평문의 대소 순서가 암호문에서도 유지돼 범위 검색이 가능하지만, 일반 연산 결과 일치를 보장하지 않는다.","블록체인은 해시 체인으로 원장 위변조를 막는 분산 기술로, 암호문 상태 연산을 위한 암호방식이 아니다."],"rel":["4-1"],"box":"평문에 대한 연산을 수행하여 암호화한 결과와 암호문에 대한 연산을 수행한 결과가 동일한 암호방식으로, 암호화된 데이터를 복호화하지 않고 데이터에 대한 연산이 가능하다. 금융, 의료분야에서 개인정보에 대한 빅데이터 처리를 위해 유용한 암호화 방식이다."},{"n":76,"s":"s4","q":"MAC에 대한 설명 중 잘못된 것은?","c":["메시지 인증은 메시지 송수신자 사이에 문서의 위·변조 공격에 대한 대응 방안으로 활용한다.","MAC 생성에 키를 사용하는 해시함수가 널리 사용된다.","MAC 자체만으로는 재전송 공격에 취약하다.","메시지 인증은 송신자와 수신자의 안전하고 훼손되지 않는 Key 관리가 목표이다."],"a":3,"e":"메시지 인증(MAC)의 목표는 메시지의 무결성과 출처(송신자) 인증이며, 키 관리는 MAC이 전제로 하는 별도 과제이다. MAC 자체에는 순서·시간 정보가 없어 재전송 공격에 취약하므로 순서번호·타임스탬프를 함께 쓴다.","ce":["MAC은 메시지 위·변조를 탐지하는 수단으로 송수신자 간 무결성 공격 대응에 활용되므로 옳은 설명이다.","HMAC처럼 비밀키를 넣은 해시함수가 MAC 생성에 널리 쓰이므로 옳은 설명이다.","MAC에는 순서·시간 정보가 없어 가로챈 메시지를 그대로 다시 보내도 검증을 통과하므로 재전송 공격에 취약하다. 옳은 설명이다.","메시지 인증의 목표는 메시지 무결성과 출처(송신자) 인증이다. 안전한 키 관리는 MAC이 전제로 하는 별도 과제이지 목표가 아니다."],"rel":["4-5"]},{"n":77,"s":"s4","q":"다음 중 정보자원에 접근하기 위한 3단계 절차에 해당하지 않는 보안 요구사항은 무엇인가?","c":["식별(Identification)","인증(Authentication)","인가(Authorization)","책임추적성(Accountability)"],"a":3,"e":"접근통제 3단계는 식별(누구인지 제시) → 인증(신원 검증) → 인가(권한 부여)이다. 책임추적성은 접근 이후 행위를 기록·추적하는 감사 요구사항으로 AAA의 Accounting에 해당한다.","ce":["식별은 사용자가 자신이 누구인지(ID)를 시스템에 제시하는 접근 절차의 1단계이다.","인증은 제시한 신원이 맞는지 패스워드·인증서 등으로 검증하는 2단계이다.","인가는 인증된 사용자에게 자원별 접근 권한을 부여하는 3단계이다.","책임추적성은 접근 이후 행위를 기록·추적하는 감사(Accounting) 요구사항으로, 접근 3단계 절차에 포함되지 않는다."],"rel":["4-10"]},{"n":78,"s":"s4","q":"메시지 인증 코드의 구조적 제약사항에 따른 재전송 공격을 막는 방법과 거리가 먼 것은?","c":["Sequence Number","Hash","Nonce","Timestamp"],"a":1,"e":"재전송 공격은 메시지마다 고유성·신선도를 부여하는 순서번호, 논스, 타임스탬프로 막는다. 해시는 같은 메시지에 같은 값을 내므로 그대로 재전송된 메시지를 구별하지 못한다.","ce":["순서번호(Sequence Number)는 메시지마다 증가하는 번호를 붙여 이미 받은 번호의 재전송을 탐지하므로 재전송 방지 수단이다.","해시는 같은 메시지에 항상 같은 값을 내므로, 그대로 재전송된 메시지를 구별하지 못해 재전송 공격 방지와 거리가 멀다.","Nonce는 한 번만 쓰는 임의 값으로 요청-응답의 신선도를 보장해 재전송을 막는다.","Timestamp는 메시지 생성 시각을 넣어 허용 시간을 넘긴 재전송 메시지를 거부할 수 있게 한다."],"rel":["4-5"]},{"n":79,"s":"s4","q":"다음 지문에서 설명하는 것은?","c":["SSO(Single Sign On)","OAuth","OpenID","OIDC(OpenID Connect)"],"a":1,"e":"OAuth는 사용자 계정 정보를 넘기지 않고 제3의 애플리케이션이 SNS 등 서비스의 API에 위임 접근하도록 하는 공개 표준 인가 프로토콜로, 2010년 RFC 5849(OAuth 1.0)로 발표되었다. OpenID는 인증 중심, OIDC는 OAuth 2.0 위에 인증 계층을 얹은 표준이다.","ce":["SSO는 한 번 인증으로 여러 시스템을 이용하게 하는 통합 인증 개념으로, 2010년 RFC 5849로 발표된 특정 표준이 아니다.","OAuth는 계정 정보를 넘기지 않고 제3 애플리케이션이 SNS 등의 API에 위임 접근하게 하는 공개 표준으로, 2010년 RFC 5849(OAuth 1.0)로 발표되었다.","OpenID는 하나의 ID로 여러 사이트에 로그인하는 분산 인증 표준으로, OpenID 재단 규격이며 RFC 5849가 아니다.","OIDC는 2014년 OAuth 2.0 위에 인증(ID 토큰) 계층을 추가한 표준으로, 2010년 RFC 5849와 다르다."],"rel":["4-9"],"box":"인터넷 애플리케이션에서 사용자 인증에 사용되는 공개 API로 구현된 표준 인증 방법이다. 매시업(Mashup) 서비스로 만들어진 애플리케이션이나 트위터, 페이스북과 같은 SNS 서비스를 다른 애플리케이션 또는 기기(PC, 스마트폰 등)에서 사용자 정보에 접근할 때 사용할 수 있도록 한다. 2010년 IETF에서 공식 표준안(RFC 5849)이 발표되었다."},{"n":80,"s":"s4","q":"다음 지문에서 설명하는 용어는 무엇인가?","c":["혼돈","확산","차분(Differential)","선형(Linear)"],"a":1,"e":"확산(Diffusion)은 평문 한 비트의 변화가 암호문의 여러 비트에 퍼지도록 해 평문과 암호문 사이의 통계적 관계를 감추는 성질이다. 혼돈(Confusion)은 암호문과 키 사이의 관계를 복잡하게 만드는 성질이며, 차분·선형은 암호 분석 기법이다.","ce":["혼돈(Confusion)은 암호문과 키 사이의 관계를 복잡하게 만들어 키 추정을 어렵게 하는 성질로, 지문의 평문 비트 종속과는 다르다.","확산(Diffusion)은 암호문의 각 비트가 평문의 여러 비트에 종속되도록 퍼뜨려 평문-암호문 간 통계적 관계를 숨기는 성질이다.","차분 분석은 평문 쌍의 차이가 암호문 차이에 전파되는 확률을 이용하는 암호 분석 기법으로, 설계 개념이 아니다.","선형 분석은 평문·암호문·키 비트 사이의 선형 근사식을 이용하는 암호 분석 기법이다."],"rel":["4-2"],"box":"Shannon은 순환과 대치를 반복적으로 사용하며 평문과 암호문 사이의 관계 파악을 어렵게 만드는 합성암호를 소개하며, 암호문의 각각의 비트나 문자가 평문의 모든 비트나 특정 비트에 종속적으로 결정되어 암호문에 대한 통계적인 테스트를 통하여 평문을 찾고자 하는 공격자를 좌절시키는 개념을 소개하였다."},{"n":81,"s":"s5","q":"정보를 전송하는 과정에서 송신자와 수신자가 해당 자원에 대한 사용이 정당한지를 확인하기 위한 절차를 무엇이라고 하는가?","c":["인증","인가(Authorization)","감사(Auditing)","관리"],"a":1,"e":"인가(Authorization)는 인증된 주체가 특정 자원을 사용할 정당한 권한이 있는지 확인·부여하는 절차이다. 인증은 신원이 맞는지 검증하는 것이고, 감사는 행위를 기록·검토하는 것이다.","ce":["인증은 사용자가 주장하는 신원이 맞는지를 검증하는 절차로, 자원 사용의 정당성(권한) 확인과 구별된다.","인가는 인증된 주체가 특정 자원을 사용할 정당한 권한이 있는지 확인하고 허용하는 절차이다.","감사는 접근·행위를 기록하고 검토해 사후 추적하는 절차로 사용 권한 판단이 아니다.","관리는 보안 서비스의 특정 절차를 가리키는 용어가 아니다."],"rel":["4-10","5-1"]},{"n":82,"s":"s5","q":"다음 중 주요정보통신기반시설 관리기관이 취약점 분석·평가를 의뢰할 수 없는 기관은?","c":["「국가정보화기본법」에 의한 한국정보화진흥원","「정보통신기반보호법」에 의한 정보공유·분석센터","「정보보호산업의 진흥에 관한 법률」에 따라 지정된 정보보호 전문서비스 기업","「정부출연연구기관 등의 설립·운영 및 육성에 관한 법률」에 의한 한국전자통신연구원"],"a":0,"e":"정보통신기반 보호법 제9조에 따라 관리기관은 취약점 분석·평가를 한국인터넷진흥원, 정보공유·분석센터(소정 요건 충족 시), 정보보호 전문서비스 기업, 한국전자통신연구원에 의뢰할 수 있다. 한국정보화진흥원은 의뢰 대상 기관이 아니다(개정 여부 확인).","ce":["정보통신기반 보호법 제9조의 취약점 분석·평가 의뢰 기관에 한국정보화진흥원(현 한국지능정보사회진흥원)은 포함되지 않는다(개정 여부 확인).","정보공유·분석센터(ISAC)는 대통령령 요건을 갖춘 경우 취약점 분석·평가를 의뢰받을 수 있는 기관이다.","정보보호산업법에 따라 지정된 정보보호 전문서비스 기업은 취약점 분석·평가 의뢰 대상 기관이다.","한국전자통신연구원(ETRI)은 법에 명시된 취약점 분석·평가 의뢰 대상 기관이다."],"rel":["5-13"]},{"n":83,"s":"s5","q":"이것은 영국표준협회(BSI)에서 만든 정보보호관리체계에 대한 표준으로, 최상의 정보보호관리를 위한 포괄적인 일련의 관리 방법에 대하여 요건 별로 해석해 놓은 규격으로, 기업이 고객 정보의 기밀성, 무결성, 가용성을 보장한다는 것을 공개적으로 확인하는 것이 목적이다. 이것은 현재 국제표준 기구인 ISO에 의해 ISO 27000 시리즈로 발전하였다. 이것은 무엇인가?","c":["ITSEC(Information Technology Security Evaluation Criteria)","TCSEC(Trusted Computer System Evaluation Criteria)","CC(Common Criteria)","BS7799(British Standard 7799)"],"a":3,"e":"BS7799는 영국표준협회가 제정한 정보보호관리체계 표준으로 ISO/IEC 17799를 거쳐 ISO/IEC 27001·27002로 발전하였다. ITSEC(유럽)·TCSEC(미국)·CC(국제)는 보안 제품 평가 기준이다.","ce":["ITSEC은 영국·독일·프랑스·네덜란드가 만든 유럽의 IT 보안 제품 평가 기준(E0~E6)으로, 관리체계 표준이 아니다.","TCSEC(오렌지북)은 미국 국방부의 컴퓨터 시스템 보안 평가 기준(D~A1)으로, 관리체계 표준이 아니다.","CC는 ISO/IEC 15408 국제 IT 보안 제품 평가 기준(EAL1~7)으로, 관리체계 표준이 아니다.","BS7799는 영국표준협회가 제정한 정보보호관리체계 표준으로, ISO/IEC 17799를 거쳐 ISO/IEC 27001·27002로 발전하였다."],"rel":["5-12"]},{"n":84,"s":"s5","q":"사이버 폭력의 특징이 아닌 것은?","c":["사이버 폭력 행위는 빠르게 확산된다.","익명성으로 인해 사이버 폭력 행위를 쉽게 하게 된다.","가해자를 찾아내기 쉽다.","자신도 모르는 사이에 사이버 폭력 행위를 할 수 있다."],"a":2,"e":"사이버 폭력은 익명성과 빠른 확산성 때문에 가해자를 특정하고 찾아내기 어렵다는 것이 특징이다. 따라서 \"가해자를 찾아내기 쉽다\"는 특징에 해당하지 않는다.","ce":["사이버 공간에서는 게시물·메시지가 복제·공유되며 순식간에 확산되므로 사이버 폭력의 특징이다.","익명성으로 죄의식이 줄어 가해 행위를 쉽게 저지르게 되는 것은 사이버 폭력의 특징이다.","익명성과 빠른 확산 때문에 가해자를 특정하고 찾아내기 어려운 것이 특징이므로 '찾아내기 쉽다'는 틀렸다.","댓글 공유·퍼나르기 등으로 자신도 모르게 가해에 가담할 수 있다는 것은 사이버 폭력의 특징이다."]},{"n":85,"s":"s5","q":"개인정보보호법에서 정한 '민감정보'에 해당하지 않는 것은?","c":["장애 등급","지문 인증 방식에 사용되는 지문 정보","인종에 관한 정보","혈액형"],"a":3,"e":"민감정보는 사상·신념, 노동조합·정당 가입·탈퇴, 정치적 견해, 건강·성생활, 유전정보, 범죄경력, 특정 개인 식별 목적의 생체인식정보, 인종·민족 정보이다. 장애 등급은 건강정보, 지문 인증 정보는 생체인식정보로 민감정보에 해당하며, 혈액형은 민감정보로 규정되어 있지 않다(개정 여부 확인).","ce":["장애 등급은 건강에 관한 정보로 개인정보 보호법상 민감정보에 해당한다.","특정 개인을 알아볼 목적으로 처리하는 지문 등 생체인식정보는 시행령상 민감정보에 해당한다.","인종·민족에 관한 정보는 시행령상 민감정보에 해당한다.","혈액형은 개인정보 보호법·시행령의 민감정보 목록(사상·신념, 정당 가입, 건강, 유전정보, 범죄경력, 생체인식, 인종·민족 등)에 규정되어 있지 않다(개정 여부 확인)."],"rel":["5-7"]},{"n":86,"s":"s5","q":"위험분석 방법론으로 적절히 짝지은 것은?","c":["㉠ 확률분포법 ㉡ 순위결정법","㉠ 시나리오법 ㉡ 델파이법","㉠ 델파이법 ㉡ 확률분포법","㉠ 순위결정법 ㉡ 시나리오법"],"a":1,"e":"어떤 사건도 예상대로 발생하지 않는다는 사실을 전제로 일정 조건에서 발생 가능한 결과를 추정하는 것은 시나리오법이고, 전문가 집단의 토론으로 위험을 분석하는 것은 델파이법이다. 두 방법 모두 정성적 위험분석 기법이다.","ce":["확률분포법은 미지의 사건을 확률 분포로 추정하는 정량적 방법이고, 순위결정법은 위험 요소에 점수를 매겨 순위를 비교하는 방법으로 둘 다 지문과 맞지 않는다.","예상대로 발생하지 않는다는 전제로 조건별 발생 가능한 결과를 추정하는 것은 시나리오법(㉠), 전문가 집단 토론으로 분석하는 것은 델파이법(㉡)이다.","델파이법은 ㉡(전문가 토론)에 해당하는데 ㉠에 넣었고, 확률분포법은 ㉡의 설명과 맞지 않는다.","순위결정법은 위험 요소별 상대 순위를 매기는 방법이라 ㉠과 맞지 않고, 시나리오법은 ㉡이 아니라 ㉠의 설명이다."],"rel":["5-2"],"box":"㉠: 어떤 사건도 예상한 대로 발생하지 않는다는 사실에 근거하여 일정 조건하에서 위험에 대한 발생 가능한 결과들을 추정하는 방법\n㉡: 시스템에 관한 전문적인 지식을 가진 전문가의 집단을 구성하고 위험을 분석 및 평가하여 정보시스템이 직면한 다양한 위협과 취약성을 토론을 통해 분석하는 방법"},{"n":87,"s":"s5","q":"개인정보의 가명정보 처리에 대한 설명으로 틀린 것은?","c":["개인정보처리자는 통계작성, 과학적 연구, 공익적 기록보존 등을 위하여 정보주체의 동의 없이 가명정보를 처리할 수 있다.","누구든지 특정 개인을 알아보기 위한 목적으로 가명정보를 처리해서는 아니 된다.","가명정보 및 가명정보를 원래의 상태로 복원하기 위한 추가 정보에 대하여 안전성 확보 조치는 개인정보처리자가 임의로 처리하여야 한다.","개인정보처리자는 가명정보를 처리하는 과정에서 특정 개인을 알아볼 수 있는 정보가 생성된 경우에는 즉시 해당 정보의 처리를 중지하고 지체 없이 회수·파기하여야 한다."],"a":2,"e":"개인정보 보호법 제28조의4에 따라 가명정보와 추가 정보는 분리 보관하고 대통령령으로 정하는 기술적·관리적·물리적 안전성 확보조치를 해야 하므로, 처리자가 임의로 처리할 수 없다. ①·②·④는 제28조의2·제28조의5 내용이다(개정 여부 확인).","ce":["제28조의2에 따라 통계작성·과학적 연구·공익적 기록보존 목적이면 정보주체 동의 없이 가명정보를 처리할 수 있어 옳은 설명이다.","제28조의5에 따라 누구든지 특정 개인을 알아보기 위한 목적으로 가명정보를 처리해서는 안 되므로 옳은 설명이다.","제28조의4에 따라 가명정보와 추가 정보는 분리 보관하고 대통령령으로 정한 기술적·관리적·물리적 안전성 확보조치를 해야 하므로 '임의로'가 틀렸다(개정 여부 확인).","처리 중 특정 개인을 알아볼 수 있는 정보가 생성되면 즉시 처리를 중지하고 지체 없이 회수·파기해야 하므로 옳은 설명이다."],"rel":["5-7"]},{"n":88,"s":"s5","q":"'위치정보'란 이동성 있는 물건 또는 개인이 특정한 시간에 존재하거나 존재하였던 장소에 관한 정보를 말한다. 다음 중 「위치정보보호를 위한 관리적·기술적 보호조치 권고」와 관련한 설명으로 적절하지 않은 것은?","c":["관리적·기술적 보호조치에 의해 보호되어야 하는 위치 정보의 범위는 개인위치정보뿐 아니라 이동성 있는 물건의 위치정보를 포함한다.","위치 좌표값이 그 자체만으로는 특정인의 위치를 나타내지 못하고 통신단말기 번호 또는 단말기 소지자의 이름 등과 결합하여 특정인의 위치를 알 수 있을 때에는 개인위치정보로 볼 수 있다.","결합 가능한 정보들이 여러 DB로 분산되어 있거나 제휴 회사 등이 별도로 보유하고 있더라도 서비스 제공을 위해 상호 결합될 가능성이 많다면 개인위치정보에 해당될 수 있다.","법인이나 단체 등의 위치정보도 개인위치정보 보호대상에 포함된다."],"a":3,"e":"개인위치정보는 특정 개인의 위치정보(다른 정보와 용이하게 결합해 개인을 알아볼 수 있는 경우 포함)를 말하므로, 법인·단체의 위치정보는 개인위치정보 보호대상에 포함되지 않는다. 다만 보호조치 권고상 사물 위치정보도 위치정보로서 보호 범위에 포함된다.","ce":["위치정보 보호조치 권고는 개인위치정보뿐 아니라 이동성 있는 물건의 위치정보도 보호 범위에 포함하므로 옳은 설명이다.","좌표값만으로 특정인을 알 수 없어도 단말기 번호·이름과 결합해 알 수 있으면 개인위치정보로 보므로 옳은 설명이다.","정보가 여러 DB·제휴사에 분산돼 있어도 서비스 제공을 위해 결합될 가능성이 높으면 개인위치정보가 될 수 있어 옳은 설명이다.","개인위치정보는 특정 '개인'의 위치정보를 말하므로 법인·단체의 위치정보는 개인위치정보 보호대상에 포함되지 않는다."],"rel":["5-10"]},{"n":89,"s":"s5","q":"개인정보의 안전성 확보조치 기준에서 사용되는 용어 정의이다. 올바르지 않은 것은?","c":["'개인정보파일'이란 개인정보를 쉽게 검색할 수 있도록 일정한 규칙에 따라 체계적으로 배열하거나 구성한 개인정보의 집합물을 말한다.","'개인정보처리시스템'이란 개인정보를 처리할 수 있도록 데이터베이스시스템에 직접 접속하는 단말기를 말한다.","'바이오정보'란 지문, 얼굴, 홍채, 정맥, 음성, 필적 등 개인의 신체적 또는 행동적 특징에 관한 정보로서 그로부터 가공되거나 생성된 정보를 포함한다.","'내부망'이란 물리적 망분리, 접근통제시스템 등에 의해 인터넷 구간에서의 접근이 통제 또는 차단되는 구간을 말한다."],"a":1,"e":"개인정보처리시스템은 데이터베이스시스템 등 개인정보를 처리할 수 있도록 체계적으로 구성한 시스템을 말하며, DB에 접속하는 단말기가 아니다. 단말기는 \"개인정보취급자가 사용하는 업무용 컴퓨터\" 등으로 별도 정의된다(개정 여부 확인).","ce":["개인정보파일을 쉽게 검색하도록 일정 규칙에 따라 체계적으로 배열·구성한 개인정보 집합물로 정의하므로 옳은 설명이다.","개인정보처리시스템은 데이터베이스시스템 등 개인정보를 처리하도록 체계적으로 구성한 시스템이며, DB에 접속하는 단말기가 아니다(개정 여부 확인).","바이오정보를 지문·얼굴·홍채·정맥·음성·필적 등 신체적·행동적 특징 정보와 그 가공·생성 정보로 정의하므로 옳은 설명이다(당시 고시 기준).","내부망을 물리적 망분리·접근통제시스템 등으로 인터넷 구간 접근이 통제·차단되는 구간으로 정의하므로 옳은 설명이다."],"rel":["5-9"]},{"n":90,"s":"s5","q":"다음은 개인정보보호법상 개인정보의 처리기준 및 정보주체의 권리에 관한 설명이다. 설명이 가장 올바른 것은?","c":["주소불명 등으로 정보주체의 사전 동의를 받을 수 없는 경우로서 명백히 정보주체 또는 제3자의 급박한 생명, 신체, 재산의 이익을 위하여 필요하다고 인정되는 경우에 동의 없이 개인정보를 수집·이용할 수 있다.","개인정보처리자의 정당한 이익을 달성하기 위하여 필요한 경우로서 명백하게 정보주체의 권리보다 우선하는 경우에는 정보주체의 동의 없이 개인정보를 제3자에게 제공할 수 있다.","정보주체에게 재화나 서비스를 홍보하거나 판매를 권유하기 위하여 개인정보처리위탁에 대한 동의를 받으려는 때에는 정보주체가 이를 명확하게 인지할 수 있도록 알리고 동의를 받아야 한다.","개인정보보호법상 바이오정보(생체정보)는 민감정보에 해당하므로 건강정보와 마찬가지로 별도의 동의를 받아야 한다."],"a":0,"e":"①은 시험 당시 개인정보 보호법 제15조 제1항 제5호의 수집·이용 예외 사유이다. ② 정당한 이익 사유는 수집·이용 근거일 뿐 제3자 제공 근거가 아니고, ③ 홍보·판매 권유 업무 위탁은 동의가 아니라 위탁 업무 내용과 수탁자를 정보주체에게 알려야 하며, ④ 생체정보는 특정 개인을 식별할 목적인 경우에만 민감정보이다(2023년 개정으로 ① 요건 변경, 개정 여부 확인).","ce":["시험 당시 제15조 제1항 제5호는 주소불명 등으로 사전 동의를 받을 수 없고 명백히 급박한 생명·신체·재산 이익을 위해 필요한 경우 동의 없는 수집·이용을 허용했다(2023년 개정으로 요건 변경).","처리자의 정당한 이익이 정보주체 권리보다 명백히 우선하는 경우는 수집·이용(제15조) 근거일 뿐, 동의 없는 제3자 제공(제17조) 근거가 아니다.","홍보·판매 권유 목적임을 명확히 알리고 동의를 받는 대상은 '개인정보 처리'이며, 그런 업무를 '위탁'할 때는 동의가 아니라 위탁 업무 내용과 수탁자를 정보주체에게 알려야 한다.","생체정보는 특정 개인을 알아볼 목적으로 처리하는 경우에만 민감정보이므로, 바이오정보가 언제나 민감정보라는 설명은 부정확하다(개정 여부 확인)."],"rel":["5-8"]},{"n":91,"s":"s5","q":"개인정보취급자 등의 금지행위에 관한 설명이다. 가장 부적절한 것은?","c":["정보보호 관리체계 인증 업무에 종사했던 자가 그 직무상 알게 된 비밀을 학생들에게 인증 업무 사례로 소개한 경우 형사처벌을 받을 수 있다.","보험회사의 직원이 친구의 부탁을 받고 친구에게 돈을 빌려간 채무자의 주소, 전화번호 등 연락처를 알려준 경우 형사처벌을 받을 수 있다.","회사의 개발업무에 종사하고 있는 직원이 학위논문 연구를 위해 고객의 개인정보의 일부를 노트북에 내려받아 실험한 것은 유출로 간주되지 않는다.","개인정보를 처리하던 자가 위계의 방법으로 개인정보처리에 관한 동의를 받는 경우 형사처벌을 받을 수 있다."],"a":2,"e":"업무 목적이 아닌 개인 학위논문 연구를 위해 고객 개인정보를 노트북에 내려받는 것은 권한 없는 목적 외 이용·유출에 해당해 개인정보 보호법 제59조 위반이 될 수 있다. ②는 업무상 알게 된 개인정보의 제3자 제공, ④는 부정한 수단의 동의 취득으로 처벌 대상이다.","ce":["ISMS 인증 업무에 종사했던 자가 직무상 알게 된 비밀을 누설하면 정보통신망법상 비밀유지 의무 위반으로 형사처벌 대상이 될 수 있어 옳은 설명이다.","업무상 알게 된 채무자의 주소·연락처를 친구에게 알려주는 것은 개인정보의 부당 제공으로 형사처벌 대상이 될 수 있어 옳은 설명이다.","업무 목적이 아닌 개인 학위논문을 위해 고객 개인정보를 노트북에 내려받는 것은 권한 없는 목적 외 이용·유출에 해당할 수 있어 '유출로 간주되지 않는다'가 틀렸다.","위계 등 거짓·부정한 수단으로 개인정보 처리 동의를 받는 것은 개인정보 보호법상 처벌 대상이므로 옳은 설명이다."],"rel":["5-9"]},{"n":92,"s":"s5","q":"위험 처리 방안 중 보안 솔루션을 도입하여 보안 통제를 수립하는 방안에 해당하는 것은?","c":["위험 감소","위험 수용","위험 회피","위험 전가"],"a":0,"e":"보안 솔루션 등 통제를 도입해 위협 발생 가능성이나 영향을 줄이는 것은 위험 감소(완화)이다. 위험 전가는 보험·외주로 제3자에게 넘기는 것이고, 위험 회피는 위험을 유발하는 업무·자산 자체를 포기하는 것이다.","ce":["보안 솔루션 등 통제를 도입해 위협 발생 가능성이나 영향을 줄이는 것이 위험 감소(완화)이다.","위험 수용은 위험 수준이 허용 범위 내이거나 대책 비용이 더 클 때 대책 없이 그대로 받아들이는 방안이다.","위험 회피는 위험을 유발하는 업무·자산 자체를 포기하거나 중단하는 방안으로, 통제를 도입하지 않는다.","위험 전가는 보험 가입·외주 계약 등으로 위험을 제3자에게 넘기는 방안이다."],"rel":["5-2"]},{"n":93,"s":"s5","q":"다음 중 조직의 정보보호 조직체계와 역할 및 책임에 대한 사항으로 가장 부적절한 것은?","c":["정보보호 최고책임자 및 개인정보 보호책임자는 예산, 인력 등 자원을 할당할 수 있는 임원급으로 지정하고 관련 법령에 따른 자격요건을 충족하여야 한다.","모든 정보통신서비스제공자는 정보보호 최고책임자를 지정 및 신고하여야 한다.","조직 전반에 걸쳐 중요한 정보보호 및 개인정보 보호 관련사항에 대한 검토, 승인 및 의사결정(위험평가 결과, 내부감사 결과 등)을 할 수 있는 위원회를 구성하여 운영하여야 한다.","주요 직무를 수행하는 임직원 및 외부자를 주요 직무자로 지정하고, 주요 직무자를 최소한으로 지정하여 그 목록을 최신으로 관리하여야 한다."],"a":1,"e":"정보통신망법 제45조의3에 따라 정보통신서비스 제공자는 CISO를 지정·신고해야 하지만, 자본금·매출액 등이 대통령령 기준 이하인 소기업 등은 신고 의무에서 제외된다. 따라서 \"모든\"은 틀린 표현이다(개정 여부 확인).","ce":["CISO·CPO는 예산·인력 등 자원을 할당할 수 있는 임원급으로 지정하고 법령상 자격요건을 충족해야 한다는 것은 ISMS-P 인증기준 내용으로 옳다.","정보통신망법상 CISO 지정·신고 의무는 자본금·매출액 등이 대통령령 기준 이하인 소기업 등은 제외되므로 '모든 정보통신서비스제공자'가 틀렸다(개정 여부 확인).","위험평가·내부감사 결과 등 중요 사항을 검토·승인·의사결정하는 정보보호위원회를 구성·운영해야 한다는 것은 인증기준 내용으로 옳다.","주요 직무자를 최소한으로 지정하고 목록을 최신으로 관리해야 한다는 것은 인증기준(2.2.1) 내용으로 옳다."],"rel":["5-12","5-11"]},{"n":94,"s":"s5","q":"위험관리 절차를 순서대로 배열한 것을 고르면?","c":["㉠ - ㉡ - ㉢ - ㉣ - ㉤","㉠ - ㉣ - ㉢ - ㉡ - ㉤","㉠ - ㉡ - ㉣ - ㉢ - ㉤","㉠ - ㉣ - ㉡ - ㉢ - ㉤"],"a":1,"e":"위험관리는 위험 식별(㉠) → 위험 분석(㉣) → 위험 평가(㉢) → 위험 처리(㉡) → 위험 감시 및 재검토(㉤) 순으로 수행한다. 처리 방안은 분석·평가로 위험 수준이 정해진 뒤에 선택한다.","ce":["위험 처리(㉡)가 식별 직후에 오면 위험 수준을 모른 채 대책을 고르게 된다. 처리는 분석·평가 뒤에 와야 한다.","위험 식별(㉠) → 분석(㉣) → 평가(㉢) → 처리(㉡) → 감시 및 재검토(㉤) 순이 올바른 위험관리 절차이다.","처리(㉡)를 분석·평가보다 먼저 두었고, 평가(㉢)와 분석(㉣) 순서도 뒤바뀌었다.","분석(㉣) 다음에 평가(㉢)가 와야 하는데 처리(㉡)를 평가보다 먼저 두어 순서가 틀렸다."],"rel":["5-12","5-2"],"box":"㉠ 위험 식별\n㉡ 위험 처리\n㉢ 위험 평가\n㉣ 위험 분석\n㉤ 위험 감시 및 재검토"},{"n":95,"s":"s5","q":"다음은 업무연속성 5단계 방법론 중 특정 단계를 설명한 것이다. 어떤 단계를 설명한 것인가?","c":["사업영향평가","위험분석","복구계획 수립","정보보호 대책 구현"],"a":0,"e":"핵심 업무 프로세스 식별, 우선순위화, 복구 목표 시간(RTO)·복구 목표 수준(RPO) 산출, 업무 중단에 따른 재정적 손실 영향 파악은 사업영향평가(BIA) 단계이다. 복구계획 수립은 BIA 결과를 바탕으로 복구 전략과 절차를 정하는 단계이다.","ce":["핵심 업무 프로세스 식별·우선순위화, RTO·복구 목표 수준 산출, 업무 중단 시 재정적 손실 영향 파악은 사업영향평가(BIA) 단계의 업무이다.","위험분석은 자산·위협·취약점을 바탕으로 위험 수준을 산정하는 단계로, 업무별 복구 목표시간 산출이 중심이 아니다.","복구계획 수립은 BIA 결과를 바탕으로 복구 전략·절차를 정하는 후속 단계이다.","정보보호 대책 구현은 선정된 통제를 실제로 적용하는 단계로, 업무 영향도 파악과 다르다."],"rel":["5-3"],"box":"업무연속성 계획 수립 과정에서 수행하는 업무로 주요 업무 프로세스 식별, 우선순위화, 프로세스별 복구 목표시간, 복구 목표수준 산출 등 각 사업단위가 받게 될 재정적인 손실의 영향도 등을 파악하는 단계이다.","flag":"99번과 동일 문항(보기 순서만 다름)"},{"n":96,"s":"s5","q":"조직이 수행하는 모든 정보보호 활동의 근거가 되는 최상위 수준의 정보보호 정책 수립 시, 포함하여야 할 사항과 가장 거리가 먼 것은?","c":["조직의 정보보호 활동을 실행하기 위한 절차, 주기, 수행 주체 등에 관한 사항","조직의 정보보호에 대한 최고경영자 등 경영진의 의지 및 방향","조직의 정보보호를 위한 역할과 책임, 대상과 범위에 관한 사항","조직이 수행하는 관리적, 기술적, 물리적 정보보호 활동의 근거"],"a":0,"e":"최상위 정보보호 정책에는 경영진의 의지·방향, 역할과 책임, 대상과 범위, 정보보호 활동의 근거를 담는다. 구체적인 절차·주기·수행 주체는 하위 문서인 지침·절차서에 규정하는 사항이다.","ce":["구체적인 활동 절차·주기·수행 주체는 최상위 정책이 아니라 하위 문서인 지침·절차서에 규정하는 사항이다.","최고경영자 등 경영진의 정보보호 의지와 방향은 최상위 정책에 반드시 포함해야 하는 사항이다.","정보보호를 위한 역할과 책임, 대상과 범위는 최상위 정책에 포함해야 하는 사항이다.","관리적·기술적·물리적 정보보호 활동의 근거는 최상위 정책이 제공해야 하는 사항이다."],"rel":["5-1"]},{"n":97,"s":"s5","q":"용어에 대한 설명으로 옳지 않은 것은?","c":["'침해사고'란 정보통신망 또는 이와 관련된 정보 시스템을 공격하는 행위로 인하여 발생한 사태를 말한다.","'정보통신기반시설'이라 함은 국가안전보장·행정·국방·치안·금융·통신·운송·에너지 등의 업무와 관련된 전자적 제어·관리시스템 및 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」에 따른 정보통신망을 말한다.","'개인위치정보'라 함은 특정 개인의 위치정보(위치정보만으로는 특정 개인의 위치를 알 수 없는 경우에도 다른 정보와 용이하게 결합하여 특정 개인의 위치를 알 수 있는 것을 포함한다)를 말한다.","'개인신용정보'란 기업 및 법인에 관한 정보를 제외한 생존 여부와 상관없는 개인에 관한 신용정보로서 해당 정보의 성명, 주민등록번호 및 영상 등을 통하여 특정 개인을 알아볼 수 있는 정보만 말한다."],"a":3,"e":"신용정보법 제2조의 개인신용정보는 기업·법인 정보를 제외한 \"살아 있는\" 개인에 관한 신용정보로, 성명·주민등록번호·영상 등으로 특정 개인을 알아볼 수 있는 정보뿐 아니라 다른 정보와 쉽게 결합해 알아볼 수 있는 정보도 포함한다. 따라서 \"생존 여부와 상관없는\", \"~만 말한다\"가 틀리다(개정 여부 확인).","ce":["정보통신망법상 침해사고는 해킹·바이러스·서비스 거부 등으로 정보통신망 또는 관련 정보시스템을 공격해 발생한 사태로 정의되어 옳은 설명이다.","정보통신기반 보호법상 정보통신기반시설은 국가안보·행정·국방·금융·통신·에너지 등 업무 관련 전자적 제어·관리시스템과 정보통신망으로 정의되어 옳은 설명이다.","위치정보법상 개인위치정보는 다른 정보와 용이하게 결합해 특정 개인의 위치를 알 수 있는 것을 포함하므로 옳은 설명이다.","신용정보법상 개인신용정보는 '살아 있는' 개인의 신용정보이며, 다른 정보와 쉽게 결합해 개인을 알아볼 수 있는 정보도 포함하므로 '생존 여부 무관'·'~만'이 틀렸다(개정 여부 확인)."],"rel":["5-10","5-13"]},{"n":98,"s":"s5","q":"인증제도는?","c":["ISO 27001","ITSEC","CC","TCSEC"],"a":2,"e":"CC(Common Criteria, ISO/IEC 15408)는 제품 유형별 보호프로파일(PP)을 기준으로 IT 보안제품을 평가하고 EAL1~EAL7의 7단계 보증 등급을 부여하는 국제 평가·인증 제도이다. TCSEC은 D~A1 등급, ITSEC은 E0~E6 등급을 사용한다.","ce":["ISO 27001은 조직의 정보보호관리체계(ISMS) 인증 표준으로, 제품별 PP와 EAL 등급을 쓰지 않는다.","ITSEC은 유럽의 보안 제품 평가 기준으로 E0~E6 등급을 쓰며, PP·EAL1~7 체계가 아니다.","CC(ISO/IEC 15408)는 제품 유형별 보호프로파일(PP)을 기준으로 IT 보안제품을 평가하고 EAL1~EAL7의 7단계 등급을 부여하는 국제 평가·인증 제도이다.","TCSEC(오렌지북)은 미국의 평가 기준으로 D~A1 등급을 사용하며 PP·EAL 체계가 아니다."],"rel":["5-6"],"box":"현재 사용되는 IT 보안제품에 대해 보안성을 평가하는 제도로 제품유형별 PP(Protection Profile)를 정의하고, 8개 군의 평가항목을 대상으로 평가가 이루어진다. 평가결과는 IT 보안제품의 보안위협 및 자산가치의 정도에 따라 EAL1(Evaluation Assurance Level 1) - EAL7(Evaluation Assurance Level 7)까지 7단계로 부여하며 인증서가 제공된다."},{"n":99,"s":"s5","q":"업무연속성 5단계 방법론 중 특정 단계를 설명한 것이다. 어떤 단계를 설명한 것인가?","c":["사업영향평가","위험분석","정보보호 대책 구현","복구계획 수립"],"a":0,"e":"주요 업무 프로세스 식별·우선순위화, RTO·복구 목표 수준 산출, 업무 중단 시 재정적 손실 영향 파악은 사업영향평가(BIA) 단계이다. 위험분석은 자산·위협·취약점을 기반으로 위험 수준을 산정하는 단계이다.","ce":["주요 업무 프로세스 식별·우선순위화, 복구 목표시간·수준 산출, 재정적 손실 영향 파악은 사업영향평가(BIA) 단계이다(95번과 동일 문항).","위험분석은 자산·위협·취약점으로 위험 수준을 산정하는 단계로, 업무별 복구 목표 산출과 손실 영향도 파악이 중심이 아니다.","정보보호 대책 구현은 선정된 보호대책을 실제로 적용하는 단계이다.","복구계획 수립은 BIA 결과를 바탕으로 복구 전략과 세부 절차를 정하는 후속 단계이다."],"rel":["5-3"],"box":"업무연속성 계획 수립 과정에서 수행하는 업무로 주요 업무 프로세스 식별, 우선순위화, 프로세스별 복구 목표시간, 복구 목표수준 산출 등 각 사업단위가 받게 될 재정적인 손실의 영향도 등을 파악하는 단계이다.","flag":"95번과 동일 문항(보기 순서만 다름)"},{"n":100,"s":"s5","q":"\"개인정보보호법\"상의 \"개인정보처리자의 개인정보 보호 원칙\"에 관한 설명 중 가장 부적절한 것은?","c":["목적에 필요한 범위에서 최소한의 개인정보만을 적법하고 정당하게 수집한다.","정보주체의 사생활 침해를 최소화하는 방법으로 개인정보를 처리하여야 한다.","개인정보의 정확성, 완전성 및 최신성이 보장되도록 하여야 한다.","개인정보는 반드시 실명으로 처리되어야 한다."],"a":3,"e":"개인정보 보호법 제3조 제7항은 익명 처리로 목적을 달성할 수 있으면 익명으로, 익명으로 달성할 수 없으면 가명으로 처리될 수 있도록 하라고 규정한다. 따라서 \"반드시 실명으로 처리\"는 보호 원칙에 반한다.","ce":["목적에 필요한 범위에서 최소한의 개인정보만 적법·정당하게 수집하는 것은 제3조 제1항의 보호 원칙이다.","정보주체의 사생활 침해를 최소화하는 방법으로 처리하는 것은 제3조 제6항의 보호 원칙이다.","처리 목적 범위에서 개인정보의 정확성·완전성·최신성을 보장하는 것은 제3조 제3항의 보호 원칙이다.","제3조 제7항은 익명으로 목적 달성이 가능하면 익명, 불가능하면 가명으로 처리될 수 있도록 하라고 규정하므로 '반드시 실명'은 원칙에 반한다."],"rel":["5-8"]}]},{"id":"2021-03-27","title":"2021년 3월 27일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"내부 정보 유출 차단을 위한 보안 제품은 무엇인가?","c":["DRM","DLP","VDI","EDMS"],"a":1,"e":"DLP(Data Loss Prevention)는 PC 에이전트·네트워크 단에서 메일·메신저·웹 업로드 등으로 나가는 중요정보를 탐지·차단하는 내부 정보 유출 방지 솔루션이다. DRM은 콘텐츠 자체를 암호화해 사용 권한을 통제하는 기술이고, VDI는 데스크톱 가상화, EDMS는 전자문서관리시스템이다.","ce":["DRM(Digital Rights Management)은 문서·콘텐츠 자체를 암호화하고 열람·편집·출력 권한을 통제하는 기술로, 에이전트가 메일·웹 전송 경로를 감시해 유출을 차단하는 제품은 아니다.","DLP(Data Loss Prevention)는 PC 에이전트·네트워크 단에서 메일·SNS·웹 업로드로 나가는 중요정보를 패턴 탐지해 차단하므로 지문 설명과 일치한다.","VDI(Virtual Desktop Infrastructure)는 서버에 가상 데스크톱을 두고 화면만 전송하는 데스크톱 가상화 기술로, 유출 경로 탐지·차단 제품이 아니다.","EDMS(Electronic Document Management System)는 전자문서의 등록·보관·검색·버전을 관리하는 문서관리시스템으로, 유출 탐지 기능이 본질이 아니다."],"rel":["1-11"],"box":"PC에 에이전트를 설치하여 메일, SNS, 웹사이트 등을 통해 발생할 수 있는 중요 정보 유출을 탐지하여 차단한다."},{"n":2,"s":"s1","q":"다음 중 Windows에서 사용하는 일반사용자 그룹인 Users 그룹에 대한 설명 중 적합하지 않은 것은?","c":["User는 시스템 크기의 레지스트리 설정, 운영체제 파일 또는 프로그램 파일을 수정할 수 없다.","User는 워크스테이션을 종료할 수는 있지만 서버는 종료할 수 없다.","Users가 로컬 그룹을 만들 수는 있지만 자신이 만든 로컬 그룹만 관리할 수 있다.","Users 그룹의 구성원은 다른 Users 그룹에서 실행할 수 있는 프로그램을 설치할 수 있다."],"a":3,"e":"Users 그룹 구성원은 시스템 전역에 영향을 주는 프로그램(다른 사용자도 실행 가능한 프로그램)을 설치할 권한이 없으며, 이는 Administrators(과거 Power Users) 권한이다. 시스템 레지스트리·OS 파일 수정 불가, 워크스테이션 종료만 가능, 자신이 만든 로컬 그룹 관리 가능은 Users 그룹의 올바른 특성이다.","ce":["옳은 설명이다. Users 그룹은 시스템 전역 레지스트리(HKLM 등)·OS 파일·Program Files 수정 권한이 없어 시스템 무결성이 보호된다.","옳은 설명이다. 일반 사용자는 자신이 쓰는 워크스테이션은 종료할 수 있으나 서버 종료 권한은 기본적으로 관리자 계열에만 있다.","옳은 설명이다. Users 구성원도 로컬 그룹을 만들 수 있지만 관리 범위는 자신이 만든 그룹으로 한정된다.","적합하지 않은 설명이다. 다른 사용자도 실행할 수 있는 전역 프로그램 설치는 Administrators(과거 Power Users) 권한이며, Users는 자신만 쓰는 프로그램만 설치할 수 있다."],"rel":["1-17"]},{"n":3,"s":"s1","q":"파일 무결성 점검 도구에 해당하는 것은?","c":["John the Ripper","Tripwire","Snort","Nmap"],"a":1,"e":"Tripwire는 파일의 해시값 기준선(DB)을 만든 뒤 주기적으로 비교해 변경 여부를 탐지하는 대표적 무결성 점검 도구이다. John the Ripper는 패스워드 크래킹 도구, Snort는 네트워크 IDS, Nmap은 포트 스캐너이다.","ce":["John the Ripper는 사전·무차별 대입으로 패스워드 해시를 크래킹해 취약 패스워드를 점검하는 도구로, 파일 변경 탐지 도구가 아니다.","Tripwire는 파일의 해시·속성 기준선 DB를 만든 뒤 주기적으로 비교해 변조 여부를 탐지하는 대표적 파일 무결성 점검 도구이다.","Snort는 시그니처 규칙으로 네트워크 패킷을 검사하는 오픈소스 NIDS/IPS로, 호스트 파일의 무결성을 점검하지 않는다.","Nmap은 호스트 발견·포트 스캔·서비스/OS 식별을 수행하는 네트워크 스캐너로, 파일 무결성과 관계된 기능이 아니다."],"rel":["1-11"]},{"n":4,"s":"s1","q":"주체가 주도적으로 자신이 소유한 객체(파일 등)에 대한 접근 권한(Read, Write, Execution, Append 등)을 다른 주체(사용자)에게 양도하는 등의 행위가 가능한 접근통제 정책은?","c":["MAC","RBAC","CBAC","DAC"],"a":3,"e":"DAC(임의적 접근통제)는 객체 소유자가 자신의 재량으로 다른 주체에게 권한을 부여·양도할 수 있는 신원 기반 정책이다. MAC은 보안 레이블에 따라 시스템이 강제하므로 소유자가 임의 양도할 수 없고, RBAC은 역할에 권한을 할당하는 방식이다.","ce":["MAC(강제적 접근통제)은 주체·객체의 보안 레이블(등급)을 시스템이 비교해 강제하므로 소유자가 임의로 권한을 양도할 수 없다.","RBAC(역할 기반 접근통제)은 관리자가 역할에 권한을 할당하고 사용자를 역할에 배정하는 방식으로, 소유자 재량 양도가 핵심이 아니다.","CBAC(Context-Based Access Control)는 시스코 IOS의 상태 기반 트래픽 필터링 등 문맥 기반 통제로, 객체 소유자의 권한 양도 개념과 무관하다.","DAC(임의적 접근통제)는 객체 소유자가 자신의 재량으로 다른 사용자에게 읽기·쓰기·실행 권한을 부여·양도할 수 있는 신원 기반 정책이다."],"rel":["4-10"]},{"n":5,"s":"s1","q":"다음 지문이 설명하는 파일 시스템은?","c":["exFAT(Extended File Allocation Table)","ext4(extended file system)","HFS(Hierarchical File System)","ReFS(Resilient File System)"],"a":0,"e":"exFAT은 마이크로소프트가 플래시 메모리용으로 설계해 Windows CE 6.0에 처음 도입하고 Vista SP1·7·Server 2008 등에 적용한 파일 시스템으로, FAT32의 4GB 파일 크기 제한 등을 해소했다. ext4는 리눅스, HFS는 애플 macOS 계열, ReFS는 Windows Server 2012부터 도입된 복원력 중심 파일 시스템이다.","ce":["exFAT은 마이크로소프트가 플래시 메모리용으로 설계해 Windows CE 6.0에 처음 넣고 Vista SP1·7·Server 2008에 적용했으며, FAT32의 파일 크기(4GB)·디렉터리 제약을 해소했다.","ext4는 리눅스의 저널링 파일 시스템(ext3 후속)으로, 마이크로소프트가 Windows CE용으로 만든 것이 아니다.","HFS는 애플이 Mac OS용으로 만든 계층형 파일 시스템(후속 HFS+·APFS)으로, 윈도우 계열과 무관하다.","ReFS는 Windows Server 2012부터 도입된 무결성·복원력 중심 파일 시스템으로, Windows CE 6.0·Vista·Server 2008 도입 설명과 맞지 않는다."],"rel":["1-18"],"box":"마이크로소프트사가 윈도우 CE 6.0 장치와 데스크톱 운영체제인 윈도우 비스타 및 윈도우 7 그리고 윈도우 서버 2008에 도입하기 위해 만들었다. 자료구조의 오버헤드 문제나 파일 크기/디렉터리 제약 문제에 효과적이다."},{"n":6,"s":"s1","q":"다음은 윈도우 부팅 순서이다. 올바르게 나열된 것은?","c":["바-다-라-가-마-나","나-바-가-다-라-마","나-바-다-라-가-마","바-가-마-나-다-라"],"a":1,"e":"전원 투입 후 POST(하드웨어 자가진단) → CMOS 설정 읽기 → MBR 로드 → NTLDR 실행(boot.ini 읽기) → NTDETECT.com(하드웨어 검사) → ntoskrnl.exe(HAL.dll 로드) 순으로 진행된다. 따라서 나-바-가-다-라-마가 옳으며, CMOS(바)로 시작하는 보기는 POST보다 앞서므로 틀리다.","ce":["바(CMOS)로 시작하지만 CMOS 설정 적용은 POST 이후이며, NTLDR(다)이 MBR(가)보다 앞서 있어 순서가 틀리다.","POST(나) → CMOS(바) → MBR(가) → NTLDR(다) → NTDETECT.com(라) → ntoskrnl.exe(마) 순으로, 윈도우 NT 계열 부팅 절차와 일치한다.","POST·CMOS까지는 맞으나 NTLDR(다)이 MBR(가)보다 먼저 올 수 없다. NTLDR은 MBR 부트 코드가 부트 섹터를 거쳐 로드하는 프로그램이다.","CMOS(바)로 시작하고 커널(마)이 POST(나)보다 앞서는 등 하드웨어 점검 → 부트로더 → 커널의 기본 흐름을 거스른다."],"rel":["1-17"],"box":"가. MBR - 부팅 매체에 대한 기본적인 파일시스템 정보가 들어 있는 MBR 정보를 읽는다.\n나. POST - 하드웨어 자체가 시스템에 문제가 없는지 기본적인 사항을 체크하는 과정\n다. NTLDR - 하드디스크의 부팅 파티션에 있는 프로그램으로 윈도우가 부팅될 수 있도록 간단한 파일시스템을 실행하며 boot.ini 파일의 내용을 읽는다.\n라. NTDETECT.com - 설치된 하드웨어를 검사한다.\n마. ntoskrnl.exe - HAL.dll을 로드한다.\n바. CMOS - 사용자가 설정한 기본 사항을 읽어 시스템에 적용한다."},{"n":7,"s":"s1","q":"소유자 외에는 읽기, 쓰기, 실행 등 일체의 접근을 불허하기 위한 umask 설정값으로 알맞은 것은?","c":["umask 077","umask 020","umask 022","umask 066"],"a":3,"e":"공식 정답은 ④ umask 066이다. 파일 기본 권한 666에 066을 적용하면 600(rw-------)이 되어 그룹·기타 사용자의 접근이 차단된다는 취지이다. 다만 디렉터리(777 기준)까지 고려하면 066은 711이 되어 실행 권한이 남으므로, 엄밀히 '일체 불허'는 077(파일 600, 디렉터리 700)이 더 정확하다.","ce":["이론상 가장 정확한 값이다. 파일 666→600, 디렉터리 777→700이 되어 그룹·기타의 모든 권한이 제거되나, 공식 정답은 ④(066)로 발표되어 이의 소지가 있다.","umask 020은 그룹 쓰기 권한만 제거(파일 646, 디렉터리 757)하므로 그룹·기타의 읽기 권한이 남는다.","umask 022는 그룹·기타의 쓰기 권한만 제거(파일 644, 디렉터리 755)하는 일반적 기본값으로, 읽기·실행이 허용된다.","공식 정답이다. 파일 기본 666에서 066을 빼면 600(rw-------)이 되어 소유자만 접근한다는 취지이나, 디렉터리는 711이 되어 실행 권한이 남으므로 엄밀히는 077이 더 정확하다."],"rel":["1-4"],"flag":"이의 소지: 이론상 077이 더 정확하나 공식 정답·기존 txt 모두 4번(066)"},{"n":8,"s":"s1","q":"'last' 명령을 사용하여 정보를 확인할 수 있는 로그파일은?","c":["wtmp","utmp","pacct","lastlog"],"a":0,"e":"last 명령은 /var/log/wtmp에 누적된 사용자 로그인·로그아웃, 시스템 재부팅 이력을 출력한다. utmp는 현재 로그인 사용자 정보로 who·w 명령이 참조하고, lastlog는 lastlog 명령, pacct는 lastcomm(acctcom) 명령이 참조한다.","ce":["wtmp(/var/log/wtmp)는 로그인·로그아웃·재부팅·셧다운 이력을 누적 기록하는 바이너리 로그로, last 명령으로 조회한다.","utmp는 현재 로그인 중인 사용자 정보를 담으며 who·w·users 명령이 참조한다. 과거 이력을 보는 last와는 다르다.","pacct는 사용자가 실행한 명령 이력을 기록하는 프로세스 accounting 로그로, lastcomm·acctcom 명령으로 확인한다.","lastlog는 사용자별 마지막 로그인 시각을 기록하며 같은 이름의 lastlog 명령으로 조회한다(last 명령이 아님)."],"rel":["1-7"]},{"n":9,"s":"s1","q":"다음 지문에서 설명하는 파일은 무엇인가?","c":["hosts.equiv","hosts","inetd.conf","shadow"],"a":1,"e":"/etc/hosts는 IP 주소와 호스트 이름을 정적으로 매핑하는 파일로 DNS 질의보다 먼저 참조되므로, 쓰기 권한이 탈취되면 악성 사이트로 유도하는 파밍 공격에 악용된다. hosts.equiv는 r계열 서비스의 신뢰 호스트 설정 파일이고, shadow는 패스워드 해시 저장 파일이다.","ce":["/etc/hosts.equiv는 rlogin·rsh 등 r계열 서비스에서 패스워드 없이 접속을 허용할 신뢰 호스트 목록으로, IP-호스트명 매핑 파일이 아니다.","/etc/hosts는 IP 주소와 호스트명을 정적으로 매핑하며 DNS보다 먼저 참조되므로, 쓰기 권한이 탈취되면 파밍(가짜 사이트 유도)에 악용된다.","/etc/inetd.conf는 inetd 슈퍼데몬이 관리할 서비스(telnet·ftp 등)와 실행 프로그램을 정의하는 설정 파일로, 이름 해석과 무관하다.","/etc/shadow는 사용자 패스워드 해시와 만료 정책을 저장하는 파일로, IP-호스트명 매핑 기능이 없다."],"rel":["1-16"],"box":"리눅스 /etc 디렉터리 안에 위치하며, IP주소와 호스트 이름을 매핑하는 이 파일에 비인가자 쓰기 권한이 부여된 경우, 공격자는 악의적인 시스템 등록을 통해 정상적인 DNS를 우회하며 악성 사이트로의 접속을 유도하는 파밍 공격 등을 실행할 수 있다."},{"n":10,"s":"s1","q":"다음 지문에서 설명하는 것은?","c":["Session","Web Beacon","Super Cookie","History Stealing"],"a":1,"e":"웹 비콘(Web Beacon)은 웹페이지·이메일에 삽입된 1×1 픽셀의 보이지 않는 이미지로, 로딩 시 서버에 요청이 발생해 열람·방문 행동을 추적한다. 슈퍼 쿠키는 삭제가 어려운 비표준 저장소 기반 추적 쿠키이고, History Stealing은 브라우저 방문 기록을 탈취하는 기법이다.","ce":["세션(Session)은 서버가 사용자 상태를 서버 측에 유지하고 세션 ID로 식별하는 방식으로, 1×1 픽셀 이미지 추적 기법이 아니다.","웹 비콘(Web Beacon)은 웹페이지·메일에 삽입된 1×1 픽셀 투명 이미지로, 로딩 시 서버 요청을 발생시켜 열람·행동을 추적하며 Web bug·pixel tag로도 불린다.","슈퍼 쿠키는 Flash LSO·HTML5 저장소 등 일반 쿠키 삭제로 지워지지 않는 저장소에 식별자를 남기는 추적 기법으로, 이미지 삽입 방식이 아니다.","History Stealing은 CSS :visited 스타일 차이 등을 이용해 사용자의 방문 기록을 알아내는 기법으로, 픽셀 이미지로 행동을 모니터링하는 것과 다르다."],"rel":["3-4"],"box":"쿠키와 결합되어 이용자가 웹사이트를 이용하거나 이메일을 보내는 등의 행동을 모니터링하기 위해 사용하는 1픽셀*1픽셀 정도 크기의 임베딩된 이미지를 말한다. 이것은 주로 마케팅 목적으로 사용되며 Web bug, pixel tag, e-mail 트래킹이라는 다양한 이름으로 불리며, 해커에 의해 모니터링용 도구로 사용되기도 한다."},{"n":11,"s":"s1","q":"access log에는 referer라는 필드가 존재한다. 이 필드가 의미하는 것은?","c":["서비스에서 발생하는 이벤트 서버와 글로벌 카탈로그 사이의 연결문제를 기록한다.","사이트를 방문한 사용자가 어떤 경로를 통해 사이트를 방문했는지 알 수 있게 해준다.","시스템 구성요소가 기록하는 이벤트로 시스템 부팅 시 드라이버가 로드되지 않는 경우와 같이 구성요소의 오류를 기록한다.","응용프로그램이 기록한 다양한 이벤트가 저장되며, 저장되는 부분은 소프트웨어 개발자에 의해 결정된다."],"a":1,"e":"Referer는 HTTP 요청 헤더로, 현재 페이지로 오기 직전 사용자가 머물던(링크를 클릭한) 이전 페이지 URL을 담아 유입 경로를 파악하게 해준다. ③은 윈도우 시스템 로그, ④는 응용 프로그램 로그에 대한 설명이다.","ce":["이벤트 서버와 글로벌 카탈로그 사이의 연결 문제 기록은 윈도우 디렉터리 서비스(AD) 로그에 해당하며, 웹 access log의 referer와 무관하다.","Referer는 사용자가 현재 페이지에 오기 직전 머물던(링크를 클릭한) 이전 페이지 URL로, 방문 유입 경로를 파악하게 해준다.","부팅 시 드라이버 로드 실패 등 시스템 구성요소 오류를 기록하는 것은 윈도우 시스템 로그에 대한 설명이다.","응용 프로그램이 기록하고 내용을 개발자가 정하는 로그는 윈도우 응용 프로그램 로그에 대한 설명이다."],"rel":["3-4"]},{"n":12,"s":"s1","q":"루트 사용자 소유로 SUID 권한을 부여한 경우, 이러한 파일로 의심되는 파일을 검색하는 명령어로 알맞은 것은?","c":["find / -user -perm -1000 -print","find / -user -perm -2000 -print","find / -user -perm -3000 -print","find / -user -perm -4000 -print"],"a":3,"e":"특수 권한 비트는 SUID=4000, SGID=2000, Sticky bit=1000이므로 SUID 파일은 -perm -4000으로 검색한다(원래는 -user root 형태로 소유자를 지정). -2000은 SGID, -1000은 Sticky bit 검색이다.","ce":["-perm -1000은 Sticky bit가 설정된 파일(주로 /tmp 같은 공유 디렉터리)을 찾는 조건으로, SUID 검색이 아니다.","-perm -2000은 SetGID가 설정된 파일을 찾는 조건으로, 실행 시 그룹 권한을 얻는 파일이 대상이다.","-perm -3000은 SGID(2000)와 Sticky(1000)가 모두 설정된 파일을 찾는 조건으로, SUID(4000) 비트가 포함되지 않는다.","특수권한 값은 SUID=4000, SGID=2000, Sticky=1000이므로 SUID 파일은 -perm -4000으로 검색한다(정확히는 -user root로 소유자 지정)."],"rel":["1-5"]},{"n":13,"s":"s1","q":"Unix 명령($ ls -l)의 실행 결과에 대한 설명으로 가장 옳은 것은?","c":["파일 aaa에 대한 소유자는 bbb이다.","파일 bbb에 대한 소유자는 aaa이다.","파일 ccc에 대한 소유자는 aaa이다.","파일 aaa에 대한 소유자는 ccc이다."],"a":2,"e":"ls -l 출력은 '권한 링크수 소유자 그룹 크기 수정일시 파일명' 순이므로, 소유자 aaa·그룹 bbb·크기 98·파일명 ccc이다. 따라서 파일 ccc의 소유자는 aaa이며, bbb는 소유 그룹이다.","ce":["aaa는 파일명이 아니라 소유자이고 bbb는 소유 그룹이다. 파일명은 마지막 필드인 ccc이다.","bbb는 파일명이 아니라 그룹 필드이다. ls -l에서 파일명은 행의 마지막(ccc)에 온다.","ls -l 출력은 '권한 링크수 소유자 그룹 크기 날짜 파일명' 순이므로 파일 ccc의 소유자는 aaa, 그룹은 bbb이다.","ccc는 소유자가 아니라 파일명이고, aaa는 파일명이 아니라 소유자이다."],"rel":["1-4"],"box":"-rwxr--r-- aaa bbb 98 Aug 7 19:16 ccc"},{"n":14,"s":"s1","q":"Crontab을 이용해 정기적으로 매일 오전 1시에 아파치 웹 서버 로그를 백업하고자 한다. 백업 경로는 /backup/logs/ 이며, 파일 이름은 \"log-년월일시분\" 형식을 따른다. 정상적으로 작동시키기 위해 Crontab에 등록해야할 값으로 올바른 것은? (파일이름 예시: log-201903210019)","c":["* * * 1 0 cp /etc/httpd/logs/access_log /backup/logs/log-`date +\\%Y\\%m\\%d\\%H\\%M`","0 1 * * * cp /etc/httpd/logs/access_log /backup/logs/log-`date +\\%Y\\%m\\%d\\%H\\%M`","* * * 0 1 cp /etc/httpd/logs/access_log /backup/logs/log-`date +\\%Y\\%m\\%d\\%H\\%M`","0 1 * * 0 cp /etc/httpd/logs/access_log /backup/logs/log-`date +\\%Y\\%m\\%d\\%H\\%M`"],"a":1,"e":"crontab 필드는 '분 시 일 월 요일' 순이므로 매일 01:00은 '0 1 * * *'이다. ④ '0 1 * * 0'은 일요일에만 실행되고, ①·③은 월·요일 자리에 값을 넣어 의도와 다르게 동작한다. crontab 안에서 %는 개행으로 해석되므로 \\%로 이스케이프해야 한다.","ce":["'* * * 1 0'은 분·시를 모두 *로 두고 월=1, 요일=0(일요일)을 지정해 1월 일요일마다 매분 실행되므로 매일 01:00 요건과 다르다.","crontab은 '분 시 일 월 요일' 순이므로 '0 1 * * *'은 매일 01시 00분이며, %를 \\%로 이스케이프해 date 형식도 올바르게 동작한다.","'* * * 0 1'은 월=0(유효 범위 1~12 밖)·요일=1을 지정하고 분·시가 *라 매일 01:00 실행이 되지 않는다.","'0 1 * * 0'은 요일 필드가 0(일요일)이므로 매주 일요일 01:00에만 실행되어 '매일' 요건을 충족하지 못한다."],"rel":["1-16"],"flag":"원문 date 명령 따옴표는 백틱(`)으로 추정 전사"},{"n":15,"s":"s1","q":"하드웨어 및 소프트웨어를 탑재한 시스템 요소를 의미하는 것은?","c":["TCB","EGID","PCB","CC"],"a":0,"e":"TCB(Trusted Computing Base)는 보안 정책을 강제하는 하드웨어·펌웨어·소프트웨어 보호 메커니즘 전체의 집합이다. PCB는 프로세스 제어 블록, EGID는 유효 그룹 ID, CC는 공통평가기준(국제 보안 평가 표준)이다.","ce":["TCB(Trusted Computing Base)는 보안 정책을 강제하는 하드웨어·펌웨어·소프트웨어 보호 메커니즘 전체의 집합으로, 발문의 시스템 요소에 해당한다.","EGID(Effective Group ID)는 프로세스가 권한 판단에 사용하는 유효 그룹 ID로, 식별자일 뿐 하드웨어·소프트웨어 시스템 요소가 아니다.","PCB(Process Control Block)는 운영체제가 프로세스 상태·레지스터·스케줄링 정보를 저장하는 자료구조로, 보안 하드웨어·소프트웨어 집합이 아니다.","CC(Common Criteria)는 정보보호제품 보안성을 평가하는 국제 표준(ISO/IEC 15408)으로, 시스템 구성요소가 아니라 평가 기준이다."],"rel":["1-1"]},{"n":16,"s":"s1","q":"다음 지문에서 설명하고 있는 공격은 무엇인가?","c":["스펙터","캐시 포이즈닝","멜트다운","미라이"],"a":2,"e":"멜트다운(Meltdown)은 인텔 CPU의 비순차(Out-of-Order) 실행 중 권한 검사 우회를 악용해 사용자 프로세스가 커널 메모리를 캐시 부채널로 읽어내는 취약점(CVE-2017-5754)이다. 스펙터는 분기 예측(투기적 실행)을 악용해 다른 프로세스 메모리를 읽는 취약점이며, 미라이는 IoT 봇넷 악성코드이다.","ce":["스펙터(Spectre)는 분기 예측·투기적 실행을 악용해 다른 프로세스 메모리를 읽는 취약점으로, 인텔 비순차 실행의 권한 검사 우회 버그와는 원리가 다르다.","캐시 포이즈닝은 DNS·웹 캐시에 위조 데이터를 주입해 사용자를 속이는 공격으로, CPU 하드웨어 취약점이 아니다.","멜트다운(Meltdown, CVE-2017-5754)은 비순차 실행 중 권한 검사가 늦게 이뤄지는 점을 악용해 커널 메모리를 캐시 부채널로 읽어내는 CPU 취약점이다.","미라이(Mirai)는 기본 계정을 쓰는 IoT 기기를 감염시켜 봇넷을 만들고 DDoS를 수행한 악성코드로, CPU 캐시 취약점과 무관하다."],"rel":["1-19"],"box":"인텔, AMD, ARM의 CPU 제품에서 발견된 보안 취약점 중 하나이다. 인텔 CPU에서 사용하는 비순차 명령 실행 검사 우회 버그를 악용하며 해킹 프로그램이 CPU의 캐시 메모리에 접근하고, 데이터를 유출할 수 있게 되는 취약점이다."},{"n":17,"s":"s1","q":"윈도우 로그는 무엇인가?","c":["응용 프로그램 로그","시스템 로그","보안 로그","설정 로그"],"a":1,"e":"시스템 로그는 드라이버·서비스 등 윈도우 운영체제 구성요소가 기록하는 이벤트로, 부팅 시 장치 드라이버 로드 실패 등이 남는다. 응용 프로그램 로그는 애플리케이션이 기록하고, 보안 로그는 로그온·감사 정책 관련 이벤트를 기록한다.","ce":["응용 프로그램 로그는 DB·웹서버 등 애플리케이션이 기록하는 이벤트로, 기록 내용은 개발자가 정한다. OS 구성요소·드라이버 로드 기록이 아니다.","시스템 로그는 드라이버·서비스 등 윈도우 운영체제 구성요소가 기록하는 이벤트로, 부팅 시 장치 드라이버 로드 실패 등이 남는다.","보안 로그는 감사 정책에 따라 로그온 성공·실패, 파일 접근, 권한 사용 등 보안 이벤트를 기록한다.","설정(Setup) 로그는 업데이트·역할·기능 설치 등 설치 관련 이벤트를 기록하는 로그로, 부팅 시 드라이버 로드 기록과 구분된다."],"rel":["1-17","1-8"],"box":"이 로그는 윈도우 운영체제의 구성요소가 기록하는 로그이다. 이 로그는 운영체제가 시작될 때, 장치 드라이버의 로드 여부 등을 이벤트로 남긴 것을 말한다."},{"n":18,"s":"s1","q":"파일 공유와 관련된 서비스 포트에 대한 내용으로 적절하지 않은 것은?","c":["445(TCP/UDP, Direct Host)","139(TCP, NetBIOS Session)","137(UDP, NetBIOS Name)","335(UDP, NetBIOS Datagram)"],"a":3,"e":"NetBIOS 데이터그램 서비스는 UDP 138번 포트를 사용하므로 335는 틀리다. 137은 NetBIOS 이름 서비스, 139는 NetBIOS 세션 서비스, 445는 NetBIOS 없이 SMB를 직접 운용하는 Direct Host 포트이다.","ce":["적절한 내용이다. 445는 NetBIOS 없이 SMB를 TCP 위에서 직접 운용하는 Direct Host(SMB over TCP) 포트이다.","적절한 내용이다. 139/TCP는 NetBIOS 세션 서비스로 NetBIOS 기반 파일·프린터 공유(SMB) 세션에 쓰인다.","적절한 내용이다. 137/UDP는 NetBIOS 이름 서비스로 NetBIOS 이름을 IP로 해석한다.","적절하지 않다. NetBIOS 데이터그램 서비스는 UDP 138번 포트를 사용하며 335번이 아니다."],"rel":["1-17"]},{"n":19,"s":"s1","q":"유닉스 시스템에서 계정과 패스워드에 관련된 설명으로 틀린 것은?","c":["유닉스 시스템에서 사용자들은 각각 고유의 아이디를 갖고 있으며, 그 아이디에 대한 정보는 /etc/passwd에 저장된다.","유닉스 시스템에서는 각각의 사용자만이 접근 가능한 파일과 디렉터리가 존재할 수 있다.","사용자 패스워드는 /etc/passwd 또는 /etc/shadow 파일에서 관리한다.","/etc/shadow 파일에는 사용자의 패스워드가 AES-256 알고리즘에 의해 암호화되어 저장된다."],"a":3,"e":"/etc/shadow에는 패스워드가 복호화 가능한 AES 암호문이 아니라 솔트를 포함한 단방향 해시(MD5·SHA-256·SHA-512 등, $1$·$5$·$6$ 식별자)로 저장된다. 계정 정보는 /etc/passwd에 저장되고, shadow 미사용 시 passwd에 해시가 저장되므로 ③은 옳다.","ce":["옳은 설명이다. 각 사용자는 고유 UID와 계정명을 가지며 계정명·UID·GID·홈디렉터리·셸 정보가 /etc/passwd에 저장된다.","옳은 설명이다. 파일 권한을 rwx------처럼 설정하면 소유자만 접근 가능한 파일·디렉터리를 만들 수 있다.","옳은 설명이다. 섀도 패스워드 미사용 시 /etc/passwd 두 번째 필드에, 사용 시 /etc/shadow에 해시가 저장된다.","틀린 설명이다. /etc/shadow에는 복호화 가능한 AES 암호문이 아니라 솔트를 붙인 단방향 해시(MD5·SHA-256·SHA-512 등, $1$·$5$·$6$)가 저장된다."],"rel":["1-6"]},{"n":20,"s":"s1","q":"접근권한을 확인하였더니 'rwSr--r--'이었다. 권한 내의 대문자 S에 대한 설명으로 옳은 것은?","c":["SetUID를 실행 권한이 없는 파일에 설정할 경우 대문자 S로 표기된다.","SetGID를 실행 권한이 없는 파일에 설정할 경우 대문자 S로 표기된다.","디렉터리에 스티키 비트가 설정되어 대문자 S로 표기하였다.","SetGID를 설정하여 대문자 S로 표기하였다."],"a":0,"e":"S가 소유자 실행 자리에 있으므로 SetUID이며, 대문자는 소유자 실행(x) 권한 없이 SetUID만 설정된 상태를 뜻한다(실행 권한이 있으면 소문자 s). SetGID는 그룹 실행 자리에 표시되고, 스티키 비트는 기타 실행 자리에 t/T로 표시된다.","ce":["소유자 실행 자리에 S가 있으므로 SetUID이며, 대문자는 소유자 실행(x) 권한 없이 SetUID만 설정된 상태를 뜻한다(x가 있으면 소문자 s).","SetGID는 그룹 실행 자리(7번째 문자)에 s/S로 표시된다. 이 권한의 그룹 자리는 r--로 SetGID가 없다.","스티키 비트는 기타 사용자 실행 자리(마지막 문자)에 t/T로 표시되며, 권한 문자열에 t가 없고 S는 소유자 자리에 있다.","S의 위치가 그룹 실행 자리가 아니라 소유자 실행 자리이므로 SetGID가 아닌 SetUID이다."],"rel":["1-5"]},{"n":21,"s":"s2","q":"다음은 WEP에 대한 설명이다. 빈칸 ㉠에 들어갈 내용으로 적절한 것은?","c":["Encryption Key","Initial Key","Initial Vector","Encryption Vector"],"a":2,"e":"WEP는 RC4 키스트림 생성 시 공유키에 24비트 IV(Initialization Vector)를 붙여 사용하며, IV는 평문으로 전송된다. IV 길이가 짧아 재사용(충돌)이 빈번하고 이것이 WEP 키 크래킹의 주요 원인이다.","ce":["Encryption Key는 사용자가 설정하는 40/104비트 WEP 공유 비밀키 자체로, 매 프레임마다 랜덤 생성되어 전송되는 값이 아니다.","Initial Key는 WEP 표준 용어가 아니다. 공유키는 고정이고 매 프레임 달라지는 값은 IV이다.","WEP는 24비트 IV(Initialization Vector)를 랜덤 생성해 공유키 앞에 붙여 RC4 키스트림을 만들고 IV는 평문으로 전송한다. 24비트로 짧아 재사용이 잦은 것이 약점이다.","Encryption Vector는 WEP에서 쓰는 용어가 아니다. 랜덤 생성·평문 전송되는 값의 정식 명칭은 Initialization Vector이다."],"rel":["2-10"],"box":"WEP(Wired Equivalent Privacy)는 무선랜 통신을 위한 암호화 기술 중 가장 기본적인 방법이다. 암호화 알고리즘으로는 RC4를 사용하고, 암호화키 길이는 64비트 또는 128비트이다. 무선 단말에서 무선 AP와 통신을 위해 인증 요청을 보내고, 요청을 받은 무선 AP에서는 중간에 키를 계속 가로챌 경우 키 생성 순서를 예측하는 것을 방지하기 위해 랜덤하게 ( ㉠ )를 생성하며 무선 단말기에 보낸다."},{"n":22,"s":"s2","q":"무선랜의 전송 패킷에 덧붙여지는 32bytes 길이의 고유 식별자로서, 무선장치들이 BSS(Basic Service Set)에 접속할 때 패스워드같이 사용되는 코드는 무엇인가?","c":["무선 네트워크 아이디(SSID)","WEP(Wired Equivalent Privacy)","MAC(Message Authentication Code)","RFID 태그"],"a":0,"e":"SSID(Service Set Identifier)는 최대 32바이트의 무선랜 네트워크 식별자로, 단말이 BSS에 접속할 때 구분·접속 코드로 사용된다. WEP는 무선 암호화 방식, MAC(Message Authentication Code)은 메시지 무결성 인증 코드이다.","ce":["SSID(Service Set Identifier)는 최대 32바이트의 무선 네트워크 이름으로, 단말이 BSS에 접속할 때 식별 코드로 사용된다.","WEP는 RC4 기반의 무선랜 암호화 방식으로, 32바이트 네트워크 식별자가 아니다.","MAC(Message Authentication Code)은 공유키로 메시지 무결성·출처를 검증하는 인증 코드로, 무선 네트워크 식별자가 아니다.","RFID 태그는 무선주파수로 사물을 식별하는 칩·안테나 장치로, 무선랜 BSS 접속 식별자와 무관하다."],"rel":["2-10"]},{"n":23,"s":"s2","q":"지문에서 설명하고 있는 것은?","c":["NFV(Network Function Virtualization)","MDR(Managed Detection &Response)","EDR(Endpoint Detection &Response)","SDN(Software Defined Networking)"],"a":3,"e":"SDN은 제어 평면(Control Plane)과 데이터 평면(Data Plane)을 분리하고 중앙 컨트롤러 소프트웨어로 네트워크를 프로그래밍·제어하는 개방형 구조이다. NFV는 방화벽·라우터 등 네트워크 기능을 범용 서버 위 가상화 소프트웨어로 구현하는 기술로, 트래픽 제어의 소프트웨어화라는 지문 핵심과는 다르다.","ce":["NFV는 방화벽·라우터 등 네트워크 기능을 전용 장비 대신 범용 서버 위 가상 머신(VNF)으로 구현하는 기술로, 제어 기능의 소프트웨어 분리와는 초점이 다르다.","MDR(Managed Detection & Response)은 외부 전문업체가 위협 탐지·대응을 대행하는 관리형 보안 서비스로, 네트워크 구조 기술이 아니다.","EDR(Endpoint Detection & Response)은 PC·서버 등 엔드포인트 행위를 수집·분석해 위협을 탐지·대응하는 솔루션으로, 네트워크 장비 제어 기술이 아니다.","SDN(Software Defined Networking)은 제어 평면과 데이터 평면을 분리해 중앙 컨트롤러 소프트웨어로 트래픽 흐름·QoS를 프로그래밍하는 개방형 구조로 지문과 일치한다."],"rel":["2-13"],"box":"이것은 폐쇄적이었던 네트워크 장비들을 열린 구조로 바꾸고 소프트웨어로 제어할 수 있는 기능성을 통해서 네트워크 구조의 새로운 패러다임을 이끌고 있으며 네트워크의 관리적인 측면에서 많은 발전을 이루고 있다. 트래픽의 미세흐름 조정을 통해 네트워크의 효율성을 높이고, 지금까지 어려웠던 QoS 보장 기술을 확보하며, 손쉬운 장비 관리 등 네트워크의 성능과 관리성을 향상시킬 수 있다."},{"n":24,"s":"s2","q":"다음 중 지능형 지속 위협에 대한 설명으로 옳은 것은?","c":["공격의 설계부터 침투까지 매우 빠른 시간 내에 이루어진다.","다른 형태의 공격들에 비해 대체로 공격자의 비용이 적게 든다.","시스템관리자는 가능한 모든 공격을 고려해야 되기 때문에 방어가 매우 어렵다.","하나의 타깃에 대해서 같은 방법으로 지속적으로 뚫을 때까지 공격하는 것이다."],"a":2,"e":"APT(Advanced Persistent Threat)는 특정 대상을 정해 제로데이·스피어피싱 등 다양한 기법을 조합해 장기간 은밀히 공격하므로 방어자가 모든 경로를 고려해야 해 방어가 어렵다. 장기간 정찰·잠복하므로 ①은 틀리고, 고도의 기술·자원이 투입되어 비용이 크며(②), 같은 방법만 반복하지 않고 여러 기법을 바꿔 사용한다(④).","ce":["APT는 정찰·침투·잠복·유출까지 수개월~수년에 걸쳐 은밀히 진행되므로 '매우 빠른 시간 내'는 틀리다.","APT는 제로데이 취약점, 맞춤형 악성코드 등 고도의 기술·자원이 투입되어 공격자 비용이 오히려 크다.","APT는 스피어피싱·제로데이·워터링홀 등 다양한 경로를 조합하므로 방어자가 모든 공격 가능성을 고려해야 해 방어가 매우 어렵다.","APT는 한 가지 방법을 반복하지 않고 대상에 맞춰 여러 기법을 바꿔가며 지속적으로 공격한다는 점에서 틀리다."],"rel":["1-19"]},{"n":25,"s":"s2","q":"다음 지문의 빈칸 ㉠, ㉡에 들어갈 용어로 올바르게 짝지어진 것은?","c":["㉠ MAC ㉡ 암호화","㉠ MAC ㉡ 인증","㉠ 스위치 ㉡ 인증","㉠ 스위치 ㉡ 암호화"],"a":1,"e":"무차별(Promiscuous) 모드에서는 NIC가 목적지 MAC 주소가 자신이 아닌 프레임도 수신하므로 ㉠은 MAC이다. 교사용 시험지 정답은 ㉡ '인증'(②)으로 표시되어 있으나, 스니핑된 내용의 노출을 막는 일반적 대책은 전송 데이터 암호화이므로 ①(암호화)을 정답으로 보는 자료도 있다. ㉠이 스위치인 ③·④는 틀리다.","ce":["㉠ MAC은 맞다. ㉡ 암호화는 스니핑 내용 노출을 막는 일반적 대책으로 이론상 타당하나, 교사용 공식 정답은 ②(인증)로 표시되어 논란이 있다.","공식(교사용) 정답이다. 무차별 모드는 목적지 MAC 주소가 자신이 아닌 프레임도 수신하므로 ㉠은 MAC이며, ㉡은 공식 정답상 인증이다(암호화가 더 타당하다는 이견 있음).","무차별 모드는 NIC가 자신의 MAC 주소 필터링을 해제하는 것이므로 ㉠에 '스위치'는 맞지 않는다.","㉠이 스위치로 잘못되었다. 수신 필터링 기준은 NIC의 MAC 주소이다(㉡ 암호화 자체는 일반적 대책)."],"rel":["2-5"],"box":"무차별 모드로 설정하면 자신의 ( ㉠ ) 주소로 오는 패킷이 아닌 것도 전달받을 수 있다. 이를 방어하기 위한 가장 효과적인 대처 방안은 ( ㉡ )이다.","flag":"정답 불일치: 이미지 교사용 ❷(인증) vs 기존 txt 1번(암호화). 이미지 기준 채택, 이론상 암호화가 타당 — 확인 필요"},{"n":26,"s":"s2","q":"OSI 7 Layer 중 어느 계층에 대한 설명인가?","c":["Transport Layer","Network Layer","Session Layer","Physical Layer"],"a":0,"e":"전송 계층(Transport Layer)은 종단 간(End-to-End) 신뢰성 있는 데이터 전달을 담당하며, 오류 검출·재전송·흐름제어·순서 제어를 수행한다(TCP·UDP). 네트워크 계층은 라우팅(경로 선택), 세션 계층은 대화(세션) 설정·동기화를 담당한다.","ce":["전송 계층(Transport)은 종단 간(End-to-End) 신뢰성 있는 전달을 담당하며 오류 검출·재전송·흐름·순서 제어를 수행한다(TCP). 지문과 일치한다.","네트워크 계층은 IP 주소 기반 라우팅(경로 선택)과 패킷 전달을 담당하며, 종단 간 유실 방지·재전송 요청은 수행하지 않는다.","세션 계층은 통신 세션의 설정·유지·종료와 동기점(체크포인트) 관리를 담당하며, 종단 간 오류 검출·재전송 계층이 아니다.","물리 계층은 비트를 전기·광 신호로 전송하는 전기적·기계적 규격을 다루며, 데이터 유실 보장 기능이 없다."],"rel":["2-1"],"box":"데이터를 주고 받을 때 데이터의 유실(Loss)이 없도록 보장해주는 계층이며, 신뢰성을 보장하기 위해 데이터를 주고 받는 End-to-End에서 전달받은 데이터의 오류를 검출하고, 만약 오류가 있다고 판단되면 재전송을 요청한다."},{"n":27,"s":"s2","q":"틀린 것은?(문제 복원 오류로 문제 내용이 정확하지 않습니다. 정답은 2번입니다.)","c":["출발지 211.1.99.1 / 목적지주소 32.15.1.1인 패킷은 규칙 1에 의해 거부된다.","출발지 211.1.99.1 / 목적지주소 32.15.6.15인 패킷은 규칙 2에 의해 허용된다.","출발지 211.1.37.15 / 목적지주소 32.15.6.15인 패킷은 규칙 2에 의해 허용된다.","출발지 211.1.37.15 / 목적지주소 32.15.1.1인 패킷은 규칙 3에 의해 차단된다."],"a":1,"e":"원 문제의 방화벽(패킷 필터링) 규칙표가 복원되지 않아 정확한 풀이가 불가능하며, 공개 정답은 ②이다. 패킷 필터링 규칙은 위에서부터 순서대로 비교해 처음 일치하는 규칙이 적용된다는 점(first match)이 이 유형의 핵심 풀이 원리이다.","ce":["원문 규칙표 누락으로 판단 근거 없음 — 공식 정답(②) 기준으로 옳은 진술로 처리된다. 규칙은 위에서부터 처음 일치하는 규칙이 적용된다(first match).","공식 정답(틀린 진술)이다. 원문 규칙표가 복원되지 않아 규칙 2가 이 패킷에 적용되지 않는 구체적 근거는 확인 불가 — 공식 정답 기준.","원문 규칙표 누락으로 판단 근거 없음 — 공식 정답 기준으로 옳은 진술로 처리된다.","원문 규칙표 누락으로 판단 근거 없음 — 공식 정답 기준으로 옳은 진술로 처리된다."],"rel":["2-9"],"flag":"문제 복원 오류(규칙표 누락) — comcbt 원문 그대로, 정답 2번만 신뢰"},{"n":28,"s":"s2","q":"TCP의 3-Way Handshaking을 통한 서버와의 연결 설정 과정에서, 연결에 성공한 클라이언트 측의 연결 상태 천이 다이어그램상의 상태 변화의 순서를 바르게 나열한 것은?","c":["CLOSED→SYN_RCVD→ESTABLISHED","CLOSED→SYN_SENT→ESTABLISHED","LISTEN→SYN_RCVD→ESTABLISHED","LISTEN→SYN_SENT→ESTABLISHED"],"a":1,"e":"클라이언트는 CLOSED 상태에서 SYN을 보내 SYN_SENT가 되고, SYN+ACK를 받아 ACK를 보내면 ESTABLISHED가 된다. LISTEN→SYN_RCVD→ESTABLISHED는 서버 측(수동 개방) 상태 천이이다.","ce":["SYN_RCVD는 SYN을 받은 쪽(서버)이 SYN+ACK를 보낸 뒤의 상태이다. 클라이언트는 SYN을 보내므로 SYN_SENT를 거친다.","클라이언트는 CLOSED에서 SYN을 보내 SYN_SENT가 되고, SYN+ACK를 받고 ACK를 보내면 ESTABLISHED가 된다(능동 개방).","LISTEN→SYN_RCVD→ESTABLISHED는 연결을 기다리던 서버 측(수동 개방)의 상태 천이이다.","LISTEN은 서버의 대기 상태이고 SYN_SENT는 클라이언트 상태여서, 두 역할의 상태가 섞인 잘못된 순서이다."],"rel":["2-1"]},{"n":29,"s":"s2","q":"보안 솔루션은 무엇인가?","c":["SIEM","SOAR","NGFW","UTM"],"a":1,"e":"SOAR(Security Orchestration, Automation and Response)는 보안 도구 연계(오케스트레이션)·플레이북 기반 자동화로 낮은 수준의 이벤트를 자동 처리하고 사고 대응을 표준화하는 솔루션이다. SIEM은 로그를 수집·상관분석해 위협을 탐지하는 데 중점을 두며, UTM은 방화벽·IPS·백신 등을 하나의 장비에 통합한 제품이다.","ce":["SIEM(Security Information and Event Management)은 여러 장비 로그를 수집·상관분석해 위협을 탐지·경보하는 데 중점을 두며, 대응 자동화(플레이북)는 SOAR의 영역이다.","SOAR(Security Orchestration, Automation and Response)는 보안 도구 연계와 플레이북 기반 자동화로 저수준 이벤트를 자동 처리하고 사고 대응 절차를 표준화한다.","NGFW(차세대 방화벽)는 애플리케이션 식별·사용자 인식·IPS 기능을 통합한 방화벽으로, 대응 프로세스 자동화 솔루션이 아니다.","UTM(Unified Threat Management)은 방화벽·IPS·백신·VPN 등 기능을 한 장비에 통합한 제품으로, 업무 프로세스 기반 대응 자동화와는 다르다."],"rel":["1-11"],"box":"다양한 보안 위협에 대한 대응 프로세스를 자동화해 낮은 수준의 보안 이벤트는 사람의 도움 없이 처리하고, 보안사고 발생 시 표준화된 업무 프로세스에 따라 담당자가 쉽게 대응할 수 있는 차세대 솔루션이다."},{"n":30,"s":"s2","q":"다음 지문은 무엇에 대한 설명인가?","c":["traceroute","ping","netstat","route"],"a":0,"e":"traceroute는 TTL 값을 1부터 증가시키며 UDP(또는 ICMP) 패킷을 보내고, 각 라우터가 반환하는 ICMP Time Exceeded 메시지로 경로상의 라우터 IP를 확인한다. ping은 ICMP Echo로 도달성만 확인하고, netstat는 연결·포트 상태를, route는 라우팅 테이블을 보여준다.","ce":["traceroute는 TTL을 1부터 늘려 UDP(또는 ICMP) 패킷을 보내고, 각 라우터가 돌려주는 ICMP Time Exceeded로 경로상의 라우터 IP를 확인한다.","ping은 ICMP Echo Request/Reply로 대상 호스트의 도달 가능성과 왕복 시간만 확인하며, 중간 라우터 목록은 보여주지 않는다.","netstat는 로컬 호스트의 연결 상태·리스닝 포트·라우팅 테이블 등을 출력하는 도구로, 원격 경로 추적 기능이 없다.","route는 로컬 라우팅 테이블을 조회·추가·삭제하는 명령으로, 패킷이 실제 거치는 라우터를 추적하지 않는다."],"rel":["2-2"],"box":"패킷이 목적지까지 도달하는 동안 거치는 라우터 IP를 확인하는 도구이다. 이 도구는 udp와 icmp, ip의 ttl 값을 이용한다. 상대방의 IP 주소를 알고 있는 상태에서 상대방에게 인터넷 서비스를 제공하고 있는 회사를 알아내는 데 사용할 수 있다."},{"n":31,"s":"s2","q":"NMAP 포트 스캔에 대한 설명으로 올바르지 못한 것은?","c":["TCP Connect Scan: 대상 포트에 대해 3-Way Handshaking을 정상적으로 통신하는 방식으로 정상적이면 포트가 열려있다고 판단할 수 있다.","TCP FIN Scan: 대상 포트로 FIN 패킷을 전송하는 방식으로 응답을 받으면 포트가 열려있다고 판단할 수 있다.","TCP X-MAS Scan: 대상 포트로 FIN, URG, PSH 플래그가 모두 설정된 패킷을 전송하는 방식으로 응답을 받으면 포트가 닫혀있다고 판단할 수 있다.","TCP Null Scan: 대상 포트로 NULL 패킷을 전송하는 방식으로 응답을 받으면 포트가 닫혀있다고 판단할 수 있다."],"a":1,"e":"FIN·NULL·X-MAS 스텔스 스캔은 포트가 닫혀 있으면 RST/ACK 응답이 오고, 열려 있으면 응답이 없다. 따라서 FIN 스캔에서 응답을 받으면 '닫힘'으로 판단해야 하므로 ②가 틀렸다. TCP Connect 스캔은 완전한 3-Way Handshake 성립 시 열린 포트로 판단한다.","ce":["옳은 설명이다. TCP Connect Scan은 connect()로 3-Way Handshake를 완성하며, 연결이 성립하면 포트가 열린 것으로 판단한다(로그가 남음).","틀린 설명이다. FIN 스캔에서 포트가 닫혀 있으면 RST가 돌아오고 열려 있으면 응답이 없으므로, 응답을 받으면 '닫힘'으로 판단해야 한다.","옳은 설명이다. X-MAS 스캔(FIN·URG·PSH)도 닫힌 포트는 RST를 응답하고 열린 포트는 무응답이므로 응답 시 닫힘으로 판단한다.","옳은 설명이다. NULL 스캔(플래그 없음)도 닫힌 포트는 RST로 응답하므로 응답을 받으면 닫힘으로 판단한다."],"rel":["2-4"]},{"n":32,"s":"s2","q":"다음 중 스푸핑 공격의 종류가 아닌 것은?","c":["ARP","DNS","IP","UDP"],"a":3,"e":"스푸핑은 주소·식별 정보를 위조하는 공격으로 ARP 스푸핑(MAC 위조), DNS 스푸핑(도메인 응답 위조), IP 스푸핑(출발지 IP 위조), 이메일 스푸핑 등이 대표적이다. UDP는 전송 계층 프로토콜로 'UDP 스푸핑'은 일반적인 스푸핑 공격 분류에 해당하지 않는다(UDP Flooding은 DoS 공격).","ce":["ARP 스푸핑은 위조한 ARP Reply로 IP-MAC 매핑(ARP 캐시)을 조작해 트래픽을 가로채는 대표적 스푸핑 공격이다.","DNS 스푸핑은 DNS 질의에 위조 응답을 먼저 보내 사용자를 공격자 IP로 유도하는 스푸핑 공격이다.","IP 스푸핑은 출발지 IP 주소를 위조해 신뢰 관계를 악용하거나 추적을 회피하는 스푸핑 공격이다.","UDP는 전송 계층 프로토콜명으로 일반적인 스푸핑 공격 분류(ARP·IP·DNS·이메일)에 들지 않는다. UDP는 Flooding 같은 DoS 공격에서 주로 언급된다."],"rel":["2-5"]},{"n":33,"s":"s2","q":"가장 상위의 계층에서 이루어지는 서비스 거부 공격은 무엇인가?","c":["ICMP Flooding Attack","LAND Attack","HTTP GET Flooding Attack","Teardrop Attack"],"a":2,"e":"HTTP GET Flooding은 정상 세션을 맺은 뒤 대량의 HTTP 요청을 보내 웹서버 자원을 소모시키는 응용 계층(7계층) DDoS 공격이다. ICMP Flooding·LAND·Teardrop은 네트워크 계층(IP·ICMP) 수준의 공격이다.","ce":["ICMP Flooding은 대량의 ICMP Echo 등으로 대역폭을 소진시키는 네트워크 계층(3계층) 공격이다.","LAND Attack은 출발지와 목적지 IP·포트를 동일하게 위조한 SYN 패킷을 보내는 네트워크·전송 계층 수준 공격이다.","HTTP GET Flooding은 정상 TCP 세션을 맺은 뒤 대량 HTTP 요청으로 웹서버 자원을 고갈시키는 응용 계층(7계층) 공격으로 가장 상위 계층이다.","Teardrop은 IP 단편(fragment)의 오프셋을 겹치게 조작해 재조립 오류를 유발하는 네트워크 계층 공격이다."],"rel":["2-3"]},{"n":34,"s":"s2","q":"침입탐지시스템(IDS)에 대한 설명으로 가장 옳은 것은 무엇인가?","c":["침입 경로를 찾을 수 있도록 탐지대상으로부터 생성되는 로그를 제공한다.","Host-IDS는 운영체제에 독립적이다.","오용 침입탐지 기법은 오탐률(False Positive)이 높다.","'침입분석 및 탐지→ 데이터수집→데이터 가공 및 축약→보고 및 대응'의 단계로 실행된다."],"a":0,"e":"IDS는 탐지 대상에서 생성되는 로그·이벤트를 기록·제공해 침입 경로 추적과 사후 분석을 가능하게 한다. HIDS는 호스트 OS에 설치되므로 운영체제에 종속적이고, 오용(시그니처) 탐지는 오탐률이 낮은 대신 미탐이 높으며, 실행 단계는 데이터 수집→가공·축약→분석·탐지→보고·대응 순이다.","ce":["IDS는 탐지 대상에서 생성되는 로그·이벤트를 기록·제공해 침입 경로 추적과 사후 분석을 가능하게 한다.","HIDS는 호스트에 에이전트로 설치되어 OS 로그·시스템 호출을 감시하므로 운영체제에 종속적이다.","오용(시그니처) 탐지는 알려진 패턴과 일치할 때만 탐지하므로 오탐률(False Positive)이 낮고, 신종 공격 미탐(False Negative)이 높다.","실행 단계는 데이터 수집 → 가공·축약 → 분석·탐지 → 보고·대응 순이다. 보기는 분석·탐지를 수집보다 앞에 두어 순서가 틀리다."],"rel":["2-9"]},{"n":35,"s":"s2","q":"공격 특징 및 대응방안과 관련성이 가장 높은 것은?","c":["UDP Flooding","SYN Flooding","ICMP Flooding","GET Flooding"],"a":1,"e":"SYN Flooding은 SYN 패킷만 대량 전송해 서버의 Backlog Queue(반개방 연결) 등 TCP 스택 자원을 고갈시키는 공격으로, 출발지 IP별 PPS 임계치 설정·비정상 헤더 차단·SYN Cookie로 대응한다. UDP·ICMP Flooding은 대역폭 소진형이고, GET Flooding은 응용 계층 공격이다.","ce":["UDP Flooding은 대량의 UDP 패킷으로 대역폭을 소진시키는 공격으로, TCP 스택(연결 큐) 자원 소모 특징과 맞지 않는다.","SYN Flooding은 SYN만 대량 전송해 서버 TCP 스택의 Backlog Queue(반개방 연결)를 고갈시키며, 출발지 IP별 PPS 임계치·비정상 헤더 차단·SYN Cookie로 대응한다.","ICMP Flooding은 ICMP 패킷으로 회선 대역폭을 소진시키는 공격으로, TCP 스택 자원과 관계없다.","GET Flooding은 3-Way Handshake를 정상 완료한 뒤 HTTP 요청을 반복하는 7계층 공격으로, 대응은 요청 빈도·캡차 등 응용 계층 기반이다."],"rel":["2-3"],"box":"웹서버 OS의 TCP 스택(Stack) 자원을 소모하는 특징을 갖는 웹서버 자원 소모 공격으로 사용될 수 있으며, 그 대응방법으로 Anti-DDoS 장비에서 소스 IP별로 PPS 임계치를 설정하거나 패킷 헤더 검사를 통해 정상적인 옵션 필드값을 갖지 않는 비정상 패킷을 차단할 수 있다."},{"n":36,"s":"s2","q":"VPN에 대한 설명으로 올바르지 못한 것은?","c":["SSL VPN은 웹브라우저만 있으면 언제 어디서나 사용이 가능하다.","IPSec VPN은 네트워크 계층에서 안전하게 정보를 전송하는 방법이다.","IPSec VPN은 운영방식에 따라 트랜스포트 모드만 지원하고 암호화 여부에 따라 ESP, AH 프로토콜을 사용한다.","기본적으로 SSL VPN과 IPSec VPN은 데이터의 기밀성과 무결성이 동일하며, 단지 데이터의 암호화 구현 방식에 차이가 있다."],"a":2,"e":"IPSec은 운영 모드로 전송(Transport) 모드와 터널(Tunnel) 모드를 모두 지원하므로 '트랜스포트 모드만 지원'은 틀리다. 보안 프로토콜로는 인증·무결성만 제공하는 AH와 암호화까지 제공하는 ESP를 사용한다. SSL VPN은 별도 클라이언트 없이 웹브라우저로 접속 가능하다.","ce":["옳은 설명이다. SSL VPN은 별도 클라이언트 설치 없이 웹브라우저의 SSL/TLS 기능으로 접속할 수 있다.","옳은 설명이다. IPSec VPN은 네트워크 계층(3계층)에서 IP 패킷을 인증·암호화해 전송한다.","틀린 설명이다. IPSec은 전송(Transport) 모드와 터널(Tunnel) 모드를 모두 지원하며, 인증·무결성만 제공하는 AH와 암호화까지 제공하는 ESP를 사용한다.","옳은 설명이다. 두 VPN 모두 강력한 암호 알고리즘으로 기밀성·무결성을 제공하며, 차이는 동작 계층(3계층 vs 4~7계층)과 구현 방식에 있다."],"rel":["2-7","2-6"]},{"n":37,"s":"s2","q":"다음 지문에서 빈칸 ㉠에 해당하는 것은?","c":["Proxy","Cookie","Apache","ActiveX"],"a":0,"e":"프록시(Proxy) 서버는 클라이언트를 대신해 웹서버에 HTTP 요청을 전달하고, 최근 요청 객체를 캐시에 저장해 동일 요청 시 직접 응답한다. 쿠키는 브라우저 측 상태 저장 정보이고, Apache는 웹서버 소프트웨어이다.","ce":["프록시(Proxy) 서버는 클라이언트를 대신해 웹서버에 HTTP 요청을 전달하고 최근 객체 사본을 캐시에 저장해 응답하는 네트워크 개체이다.","쿠키(Cookie)는 서버가 브라우저에 저장시키는 작은 상태 정보로, 요청을 대신 처리하거나 객체를 캐싱하는 네트워크 개체가 아니다.","Apache는 오픈소스 웹서버 소프트웨어로 요청의 최종 처리자이며, 웹서버를 '대신하여' 요청을 먼저 받는 중계 개체가 아니다.","ActiveX는 마이크로소프트의 브라우저 확장 컴포넌트 기술로, HTTP 요청을 중계·캐싱하는 기능과 무관하다."],"rel":["2-10"],"box":"( ㉠ )는 웹서버를 대신하여 HTTP 요청을 충족시키는 네트워크 개체이다. 자체의 저장 디스크를 갖고 있어 최근 호출된 객체의 사본을 저장 및 보존한다. 브라우저는 사용자의 모든 HTTP 요청이 먼저 ( ㉠ )에 보내지도록 구성될 수 있다. 이렇게 설정되면 객체에 대한 각각의 브라우저 요청들은 가장 먼저 ( ㉠ )에 보내지게 된다."},{"n":38,"s":"s2","q":"침입탐지시스템(IDS)에 대한 설명으로 가장 적절하지 않은 것은?","c":["패킷의 유형에 따라 차단하거나 보내주는 간단한 패킷 필터링 기능을 제공한다.","네트워크상의 패킷을 분석하여 침입을 탐지하거나, 내부 사용자들의 활동을 감시하여 해킹 시도를 탐지한다.","네트워크 기반, 호스트 기반, 오용 탐지, 비정상 탐지 등이 있다.","침입 경로를 찾을 수 있도록 탐지대상으로부터 생성되는 로그를 제공한다."],"a":0,"e":"패킷을 유형에 따라 허용·차단하는 패킷 필터링은 방화벽의 기능이며, IDS는 탐지·경보 중심의 수동적 시스템이다. IDS는 데이터 소스에 따라 NIDS·HIDS, 탐지 기법에 따라 오용 탐지·비정상 탐지로 분류된다.","ce":["적절하지 않다. 패킷 유형에 따라 허용·차단하는 패킷 필터링은 방화벽 기능이며, IDS는 탐지·경보 중심의 수동적 시스템이다.","옳은 설명이다. IDS는 네트워크 패킷 분석(NIDS)이나 호스트 내부 사용자 활동 감시(HIDS)로 해킹 시도를 탐지한다.","옳은 설명이다. 데이터 소스에 따라 네트워크·호스트 기반, 탐지 기법에 따라 오용·비정상(이상) 탐지로 분류된다.","옳은 설명이다. IDS는 탐지 대상의 로그·이벤트를 기록해 침입 경로 추적과 포렌식 분석 자료를 제공한다."],"rel":["2-9"]},{"n":39,"s":"s2","q":"비대면 업무 환경에 대한 설명으로 올바르지 않은 것은?","c":["기업 업무망에 안전하게 접속하기 위해서는 VPN 또는 암호통신이 필수적이다.","원격 근무자가 기업 업무망에 VPN을 통해 접속할 경우 다중 인증을 사용하지 않아도 안전하다.","구축형 영상회의 플랫폼을 이용할 경우 참가자는 기업에서 제공하는 VPN을 이용해서 접속해야 한다.","비대면 업무에 사용하는 네트워크 환경이 안전하지 않을 경우 통신 내용 또는 데이터가 유출될 수 있다."],"a":1,"e":"VPN은 통신 구간을 암호화할 뿐 계정 탈취에 따른 부정 접속은 막지 못하므로, 원격 접속 시에는 OTP 등 다중 인증(MFA)을 함께 적용해야 한다. 업무망 접속 시 VPN·암호통신 적용, 안전하지 않은 네트워크에서의 유출 위험은 올바른 설명이다.","ce":["옳은 설명이다. 원격에서 업무망에 접속할 때는 VPN이나 TLS 등 암호통신으로 전송 구간을 보호해야 한다.","올바르지 않다. VPN은 통신 구간만 암호화하며 계정 탈취에 의한 부정 접속은 막지 못하므로 OTP 등 다중 인증(MFA)을 함께 적용해야 한다.","옳은 설명이다. 내부에 구축한 영상회의 플랫폼은 외부에서 기업 VPN을 거쳐 접속하도록 해야 회의 내용이 보호된다.","옳은 설명이다. 공용 Wi-Fi 등 안전하지 않은 네트워크에서는 스니핑·중간자 공격으로 통신 내용이 유출될 수 있다."],"rel":["2-7"]},{"n":40,"s":"s2","q":"traceroute 프로그램은 icmp protocol을 이용하여 패킷의 전송경로를 보여주는 프로토콜이다. 다음 icmp 메시지 중 traceroute와 연관이 있는 것은?","c":["가, 나","나, 다","다, 라","가, 라"],"a":0,"e":"traceroute는 TTL을 1씩 늘려 보내고 중간 라우터가 반환하는 ICMP Time Exceeded(가)로 경로를 확인하며, 윈도우 tracert는 ICMP Echo Request/Reply(나)를 사용한다. Source Quench는 혼잡 제어용, Timestamp는 시각 동기·측정용 메시지로 traceroute와 무관하다.","ce":["traceroute는 중간 라우터가 반환하는 ICMP Time Exceeded(가)로 경로를 확인하고, 윈도우 tracert는 ICMP Echo(나)를 탐지 패킷으로 사용하므로 둘 다 연관된다.","Echo(나)는 관련 있지만 Source Quench(다)는 수신 측 버퍼 혼잡 시 송신 속도를 낮추라는 흐름제어 메시지로 경로 추적과 무관하다.","Source Quench(다)는 혼잡 제어, Timestamp(라)는 시각 정보 교환용 메시지로 둘 다 traceroute에 쓰이지 않는다.","Time Exceeded(가)는 맞지만 Timestamp(라)는 송수신 시각을 교환해 지연을 측정하는 메시지로 traceroute와 무관하다."],"rel":["2-2","2-12"],"box":"가. 시간초과(time exceeded)\n나. 에코(echo)\n다. 송신지 억제(source quench)\n라. 타임스탬프(timestamp)"},{"n":41,"s":"s3","q":"다음 지문에서 설명하는 DRM 기술은 무엇인가?","c":["DOI","핑거프린팅","안티탬퍼링 기술","워터마킹"],"a":3,"e":"워터마킹은 저작권자 정보를 콘텐츠에 삽입하는 기술로, 동일 콘텐츠에는 동일한 워터마크가 들어간다. 핑거프린팅은 구매자(사용자) 정보를 삽입해 콘텐츠마다 비트 패턴이 달라지므로 불법 유포자 추적에 쓰인다. DOI는 디지털 콘텐츠 식별 체계이다.","ce":["DOI(Digital Object Identifier)는 디지털 콘텐츠에 부여하는 고유 식별 체계로, 콘텐츠 안에 비트 패턴을 삽입하는 기술이 아니다.","핑거프린팅은 구매자(사용자) 정보를 삽입하므로 콘텐츠마다 비트 패턴이 달라진다. '항상 동일'이라는 지문 조건과 반대이다.","안티탬퍼링은 소프트웨어·콘텐츠의 역공학·변조를 방지하는 기술로, 저작권 정보를 비트 패턴으로 삽입하는 것이 아니다.","워터마킹은 저작권자 정보를 콘텐츠에 비트 패턴으로 삽입하며, 동일 자료에는 항상 같은 워터마크가 들어가 소유권 증명에 쓰인다."],"rel":["3-12"],"box":"디지털 저작권 보호 관리를 위한 정보보호 기술의 하나로서 디지털 이미지, 오디오, 비디오 등 디지털 형식으로 되어 있는 지적재산의 저작권 보호를 위해 자료에 삽입한 비트 패턴을 말한다. 동일한 자료에 삽입되는 비트 패턴은 항상 동일하다."},{"n":42,"s":"s3","q":"서버를 점검하던 중 다음과 같은 문장이 포함된 ASP 스크립트가 존재하는 것을 알게 되었다. 의심되는 공격은 무엇인가?","c":["Buffer Overflow","CSRF","웹셸(WebShell)","DoS/DDoS"],"a":2,"e":"<% eval request(\"cmd\") %>는 요청 파라미터 cmd 값을 서버에서 그대로 실행하는 한 줄 ASP 웹셸 코드로, 공격자가 원격 명령을 실행하게 된다. CSRF는 사용자 브라우저를 이용해 위조 요청을 보내는 공격으로 서버에 스크립트 파일을 남기지 않는다.","ce":["버퍼 오버플로는 입력 길이 검증 미흡으로 메모리 경계를 넘어 쓰게 해 실행 흐름을 바꾸는 공격으로, 서버에 남은 ASP 스크립트와 무관하다.","CSRF는 사용자 브라우저가 인증 세션으로 위조 요청을 보내게 하는 공격으로, 서버에 명령 실행용 스크립트 파일을 남기지 않는다.","<% eval request(\"cmd\") %>는 요청 파라미터 cmd 값을 서버에서 그대로 실행하는 한 줄 ASP 웹셸로, 공격자가 원격 명령을 실행하게 된다.","DoS/DDoS는 자원·대역폭을 고갈시켜 서비스를 방해하는 공격으로, 명령 실행 백도어 스크립트와는 목적이 다르다."],"rel":["3-6","3-4"],"box":"<% eval request(\"cmd\") %>"},{"n":43,"s":"s3","q":"다음 지문에서 설명하고 있는 DNS 구성요소는?","c":["whois 클라이언트","리소스 레코드 에이전트","도메인 제어기","리졸버"],"a":3,"e":"리졸버(Resolver)는 클라이언트 측 DNS 구성요소로, 네임서버들에게 질의해 특정 도메인의 원하는 유형(A·MX 등) 리소스 레코드를 조회한다. 도메인 제어기는 윈도우 액티브 디렉터리 인증 서버이고, whois는 도메인 등록 정보 조회 도구이다.","ce":["whois 클라이언트는 도메인·IP의 등록자·등록기관 정보를 조회하는 도구로, 리소스 레코드(A·MX 등)를 질의하는 DNS 구성요소가 아니다.","리소스 레코드 에이전트는 DNS 표준 구성요소 명칭이 아니다. 레코드 조회 주체는 리졸버이다.","도메인 제어기(DC)는 윈도우 액티브 디렉터리에서 인증·정책을 담당하는 서버로, DNS 레코드 조회 구성요소가 아니다.","리졸버(Resolver)는 클라이언트 측 DNS 구성요소로, 여러 네임서버에 질의해 특정 도메인의 원하는 유형 리소스 레코드를 조회한다."],"rel":["3-7"],"box":"인터넷상에 산재하여 존재하고 있는 네임서버들 가운데에서 특정한 도메인 이름에 대해서 원하는 유형의 리소스 레코드 데이터를 조회하는 기능을 수행하는 역할을 한다."},{"n":44,"s":"s3","q":"HTTP 요청 방식은 무엇인가?","c":["GET 방식","POST 방식","HEAD 방식","CONNECT 방식"],"a":1,"e":"POST 방식은 요청 데이터를 URL이 아닌 HTTP 메시지 바디에 담아 전송하므로 파일 업로드·게시판 글쓰기에 주로 쓰이고, 인수값이 URL에 노출되지 않는다. GET은 데이터를 URL 쿼리스트링에 붙여 전송하고, HEAD는 응답 바디 없이 헤더만 요청한다.","ce":["GET 방식은 요청 데이터를 URL 쿼리스트링에 붙여 전송하므로 인수값이 URL·로그·히스토리에 노출된다. 지문과 반대이다.","POST 방식은 데이터를 HTTP 메시지 바디에 담아 전송하므로 파일 업로드·게시판 글쓰기에 쓰이고 인수값이 URL에 드러나지 않는다.","HEAD 방식은 GET과 같지만 응답 바디 없이 헤더만 받는 메서드로, 데이터 업로드에 쓰이지 않는다.","CONNECT 방식은 프록시에 대상 서버와의 터널(주로 HTTPS) 수립을 요청하는 메서드로, 파일 업로드용이 아니다."],"rel":["3-3"],"box":"이 요청 방식은 게시판 등에 파일 업로드를 위해 주로 사용하는 방식으로서 URL에 요청 데이터를 기록하지 않고, HTTP 바디에 데이터를 전송한다. 따라서 인수값을 URL을 통해 직접 전송하지 않기 때문에 다른 사람이 링크를 통해 해당 페이지를 볼 수 없다."},{"n":45,"s":"s3","q":"FTP 공격 유형 중 어떤 공격 유형인지 고르면?","c":["FTP 무차별 대입 공격","FTP 바운스 공격","익명 FTP 공격","TFTP 공격"],"a":1,"e":"FTP 바운스 공격은 PORT 명령으로 데이터 연결 대상 주소를 임의 지정할 수 있는 FTP 구조적 결함을 악용해, FTP 서버를 경유지로 포트스캔·Fake Mail 전송 등을 수행하는 공격이다. 무차별 대입 공격은 계정 패스워드를 반복 대입하는 공격이고, TFTP 공격은 인증 없는 TFTP로 파일을 탈취하는 공격이다.","ce":["FTP 무차별 대입 공격은 계정·패스워드를 반복 대입해 로그인을 시도하는 공격으로, PORT 명령 조작과 관계없다.","FTP 바운스 공격은 PORT 명령으로 데이터 연결 대상을 임의 지정할 수 있는 구조적 결함을 악용해 FTP 서버를 경유지로 포트스캔·Fake Mail 등을 수행한다.","익명 FTP 공격은 anonymous 계정의 쓰기 가능 디렉터리 등 설정 미흡을 악용해 악성 파일 업로드 등을 하는 공격으로, 데이터 포트 목적지 미검사 결함과 다르다.","TFTP 공격은 인증 없는 TFTP(UDP 69)로 설정 파일 등을 무단으로 내려받는 공격으로, FTP PORT 명령과 무관하다."],"rel":["3-1"],"box":"FTP 서버가 데이터를 데이터 포트(20/TCP)로 전송할 때 목적지가 어딘지 검사하지 않는 프로토콜의 구조적 문제점을 이용하는 공격 유형이다. 익명 FTP 서버를 이용해 공격자가 자신을 숨기고 PORT 명령을 조작하여 공격대상의 네트워크 및 포트스캔, Fake Mail 전송, 데이터 전송이 가능하며, 또한 방화벽 내부에 FTP 서버가 있으면 방화벽 패킷 필터링을 무시하고 여러 공격이 가능하다."},{"n":46,"s":"s3","q":"다음 빈칸 ㉠에 들어갈 내용으로 알맞은 것은?","c":["Cookie","Set-Cookie","Session","Keep-alive"],"a":1,"e":"서버는 HTTP 응답 헤더 Set-Cookie에 쿠키 값을 담아 보내 클라이언트에 쿠키를 생성하고, 이후 클라이언트는 요청 헤더 Cookie로 이를 되돌려 보낸다. Cookie는 요청 헤더이고, Keep-alive는 연결 유지 관련 헤더이다.","ce":["Cookie는 클라이언트가 이미 가진 쿠키를 서버로 보낼 때 쓰는 요청 헤더로, 응답에서 쿠키를 생성하는 헤더가 아니다.","Set-Cookie는 서버가 응답 헤더에 설정해 클라이언트에 쿠키(세션 토큰 등)를 생성하게 하는 헤더이다.","Session은 서버 측 상태 관리 개념이며 HTTP 헤더 이름이 아니다. 세션 ID는 Set-Cookie로 전달된다.","Keep-alive는 TCP 연결을 여러 요청에 재사용하도록 하는 연결 관리 헤더로, 쿠키 생성과 무관하다."],"rel":["3-3"],"box":"웹 세션 동작 메커니즘 중 클라이언트가 세션 토큰을 포함하지 않은 HTTP 요청 메시지를 전송했을 때, 서버는 클라이언트로 응답 메시지를 보내는 경우에 헤더에 ( ㉠ )값을 설정하면 클라이언트에 쿠키를 만들 수 있다."},{"n":47,"s":"s3","q":"전자서명(Digital Signature) 메커니즘에서 제공되는 기능과 가장 거리가 먼 것은?","c":["메시지 송신자에 대한 인증","전자서명 메시지에 대한 부인방지","전자서명 검증 과정을 통한 메시지 무결성","송수신 메시지에 대한 비밀성"],"a":3,"e":"전자서명은 서명자의 개인키로 해시값에 서명하므로 송신자 인증·무결성·부인방지를 제공하지만, 메시지 자체를 암호화하지 않으므로 기밀성(비밀성)은 제공하지 않는다. 기밀성이 필요하면 수신자 공개키나 대칭키 암호화를 별도로 적용해야 한다.","ce":["전자서명은 서명자 개인키로만 생성되고 공개키로 검증되므로 송신자 인증을 제공한다.","서명 생성에 쓰인 개인키는 서명자만 가지므로 서명 사실을 부인할 수 없는 부인방지를 제공한다.","메시지 해시에 서명하므로 검증 시 해시 불일치로 변조를 탐지하는 무결성을 제공한다.","전자서명은 메시지를 암호화하지 않으므로 비밀성(기밀성)을 제공하지 않는다. 기밀성은 수신자 공개키·대칭키 암호화로 별도 확보한다."],"rel":["4-6"]},{"n":48,"s":"s3","q":"다음 지문에서 설명하는 서명 방식은?","c":["이중 서명","은닉 서명","비밀 서명","지불 서명"],"a":0,"e":"이중 서명(Dual Signature)은 SET에서 주문정보(OI)와 지불정보(PI)의 해시를 결합해 서명함으로써 상점은 지불정보를, 은행은 주문정보를 모르면서도 두 정보의 연관성을 검증하게 한다. 은닉(블라인드) 서명은 서명자가 메시지 내용을 모른 채 서명하는 방식으로 전자화폐·전자투표에 쓰인다.","ce":["이중 서명(Dual Signature)은 SET에서 주문정보(OI)와 지불정보(PI)의 해시를 결합해 서명해, 상점은 지불정보를·은행은 주문정보를 모른 채 연관성을 검증하게 한다.","은닉(블라인드) 서명은 서명자가 메시지 내용을 모른 채 서명하는 방식으로, 전자화폐·전자투표의 익명성 확보에 쓰이며 SET의 결제 구조와 다르다.","비밀 서명은 SET에서 정의된 서명 방식 명칭이 아니다.","지불 서명은 표준 서명 방식 명칭이 아니다. SET에서 주문·지불정보 분리를 위한 방식은 이중 서명이다."],"rel":["3-10","3-13"],"box":"SET에서 도입된 기술로 상점이 카드 사용자의 계좌번호와 같은 지불정보를 모르게 하는 동시에 상점에 대금을 지불하는 은행은 카드 사용자가 상점에서 산 물건을 모르지만 상점이 요구한 결제 대금이 정확한지 확인할 수 있게 한다."},{"n":49,"s":"s3","q":"TFTP에 대한 설명으로 옳지 않은 것은?","c":["RRQ와 WRQ 메시지는 클라이언트가 서버에게 전송하는 요청이다.","DATA 메시지는 클라이언트와 서버가 모두 사용한다.","ACK 메시지는 클라이언트와 서버가 모두 사용한다.","TCP 69번 포트를 통해 데이터를 전송한다."],"a":3,"e":"TFTP(Trivial FTP)는 인증 없이 동작하는 단순 파일 전송 프로토콜로 TCP가 아닌 UDP 69번 포트를 사용한다. RRQ(읽기)·WRQ(쓰기)는 클라이언트 요청이고, 업로드·다운로드 방향에 따라 양측이 DATA와 ACK를 모두 사용한다.","ce":["옳은 설명이다. RRQ(읽기 요청)와 WRQ(쓰기 요청)는 클라이언트가 서버에 보내는 전송 시작 요청이다.","옳은 설명이다. 다운로드 시에는 서버가, 업로드 시에는 클라이언트가 DATA를 보내므로 양측 모두 사용한다.","옳은 설명이다. DATA를 받는 쪽이 블록마다 ACK를 보내므로 전송 방향에 따라 양측 모두 사용한다.","옳지 않다. TFTP는 TCP가 아니라 UDP 69번 포트를 사용하며, 신뢰성은 블록 단위 ACK·재전송으로 자체 보완한다."],"rel":["3-1"]},{"n":50,"s":"s3","q":"PGP는 전자우편 보안 시스템이다. PGP가 제공하지 않는 기능은?","c":["전자서명","압축","수신 부인방지","단편화와 재조립"],"a":2,"e":"PGP는 전자서명(인증·송신 부인방지), 기밀성(암호화), 압축(ZIP), 전자우편 호환성(Radix-64), 단편화와 재조립 기능을 제공한다. 수신자가 받은 사실을 부인하지 못하게 하는 수신 부인방지는 PGP의 기본 기능이 아니다.","ce":["PGP는 송신자 개인키로 해시에 서명하는 전자서명(RSA·DSS 등)을 제공해 인증·무결성·송신 부인방지를 보장한다.","PGP는 서명 후 암호화 전에 ZIP 압축을 수행해 전송량을 줄이고 암호 강도를 높인다.","PGP는 송신 부인방지는 제공하지만 수신자가 수신 사실을 부인하지 못하게 하는 수신 부인방지(수신 확인) 기능은 제공하지 않는다.","PGP는 메일 크기 제한에 맞추기 위해 메시지를 분할하고 수신 측에서 재조립하는 단편화·재조립 기능을 제공한다."],"rel":["3-2"]},{"n":51,"s":"s3","q":"㉠, ㉡에 들어갈 내용으로 올바르게 짝지어진 것은?","c":["㉠ 21 ㉡ 1024","㉠ 20 ㉡ 1024","㉠ 21 ㉡ 2048","㉠ 20 ㉡ 2048"],"a":0,"e":"Passive 모드에서는 클라이언트가 서버의 21번 제어 포트로 접속한 뒤, 서버가 알려준 1024 이상의 임의 포트로 데이터 연결도 클라이언트가 연다. 따라서 방화벽은 21/TCP와 1024 이상 TCP의 인바운드를 허용해야 하며, 20번 포트는 Active 모드의 데이터 포트이다.","ce":["Passive 모드는 클라이언트가 서버의 21번 제어 포트로 접속하고, 서버가 알려준 1024 이상 임의 포트로 데이터 연결도 클라이언트가 연다. 따라서 21/TCP와 1024 이상/TCP 인바운드 허용이 필요하다.","20번은 Active 모드에서 서버가 클라이언트로 데이터 연결을 걸 때 쓰는 출발지 포트로, Passive 모드 인바운드 목적지 포트가 아니다. 제어 포트는 21번이다.","㉠ 21은 맞지만 Passive 모드 데이터 포트는 1024 이상의 비특권(임시) 포트 범위이므로 2048은 틀리다.","제어 포트는 20이 아니라 21이고, 데이터 포트 범위 하한도 2048이 아니라 1024이다."],"rel":["3-1"],"box":"FTP 서버가 Passive mode로 동작할 수 있기 위해서는 보안 정책에서 모든 인터넷으로부터 FTP 서버로 목적지 포트 ( ㉠ )/TCP, 모든 인터넷으로부터 FTP 서버로 목적지 포트 ( ㉡ )이상/TCP 허용하는 규칙이 필요하다."},{"n":52,"s":"s3","q":"인터넷 메일 구조의 핵심요소에 대한 설명으로 옳지 않은 것은?","c":["MUA-사용자 액터(actor)와 사용자 응용프로그램을 대신하여 동작한다.","MSA-원격서버로부터 POP3 또는 IMAP을 사용하여 메시지를 추출한다.","MDA-메시지를 MHS에서 MS로 메시지를 전달한다.","MTA-메시지가 목적지 MDA에 도달할 때까지 중계 역할을 한다."],"a":1,"e":"MSA(Message Submission Agent)는 MUA가 제출한 메일을 받아 MTA로 넘기는 제출 에이전트(주로 587 포트)이며, POP3·IMAP으로 원격 서버에서 메시지를 가져오는 것은 MUA(또는 MRA)의 역할이다. MDA는 메시지를 사용자 메일박스(MS)에 전달하고, MTA는 메일 서버 간 중계를 담당한다.","ce":["옳은 설명이다. MUA(Message User Agent)는 사용자와 응용프로그램을 대신해 메일 작성·송신·열람을 수행하는 클라이언트(Outlook 등)이다.","옳지 않다. MSA(Message Submission Agent)는 MUA가 제출한 메일을 받아 MTA로 넘기는 제출 에이전트(주로 587 포트)이며, POP3·IMAP으로 메시지를 가져오는 것은 MUA(또는 MRA)의 역할이다.","옳은 설명이다. MDA(Message Delivery Agent)는 MHS(메시지 처리 시스템)에서 받은 메시지를 수신자의 메시지 저장소(MS, 메일박스)에 전달한다.","옳은 설명이다. MTA(Message Transfer Agent)는 SMTP로 메일 서버 간 메시지를 중계해 목적지 MDA까지 전달한다."],"rel":["3-2"]},{"n":53,"s":"s3","q":"다음 중 웹(Web) 방화벽이 수행하는 주요 기능이 아닌 것은?","c":["파일 업로드 제어 및 검사 기능","HTTP 공격 패킷 탐지 및 차단","웹 서버 오류 필터링 및 기밀 정보 유출 차단","IP 주소와 포트 기반 패킷 탐지 및 차단"],"a":3,"e":"IP 주소와 포트 기반 패킷 필터링은 네트워크 방화벽(3~4계층)의 기능이다. 웹 방화벽(WAF)은 HTTP(S) 트래픽을 7계층에서 분석해 SQL 인젝션·XSS 등 공격 차단, 파일 업로드 검사, 오류 메시지·개인정보 등 응답 유출 차단을 수행한다.","ce":["웹 방화벽은 업로드 파일의 확장자·내용을 검사해 웹셸 등 악성 파일 업로드를 차단하는 기능을 제공한다.","웹 방화벽은 HTTP(S) 요청을 7계층에서 분석해 SQL 인젝션·XSS 등 공격 패킷을 탐지·차단하는 것이 핵심 기능이다.","웹 방화벽은 응답을 검사해 서버 오류 메시지 노출을 막고 주민번호·카드번호 등 기밀 정보 유출을 차단한다.","IP 주소·포트 기반 패킷 탐지·차단은 3~4계층 네트워크 방화벽 기능이다. 웹 방화벽은 HTTP 내용 기반으로 동작한다."],"rel":["2-10"]},{"n":54,"s":"s3","q":"다음 지문에서 설명하고 있는 원칙으로 적절한 것은?","c":["재현의 원칙","무결성의 원칙","정당성의 원칙","연계보관성의 원칙"],"a":3,"e":"연계보관성(Chain of Custody) 원칙은 증거의 획득·이송·분석·보관·법정 제출 각 단계에서 담당자와 처리 내역이 명확히 기록·추적 가능해야 한다는 디지털 포렌식 원칙이다. 무결성 원칙은 증거가 수집 이후 변조되지 않아야 함(해시 검증)을, 정당성 원칙은 적법한 절차로 수집해야 함을 뜻한다.","ce":["재현의 원칙은 같은 조건과 절차로 분석하면 같은 결과가 나와야 한다는 원칙으로, 증거 처리 과정의 추적성과는 다르다.","무결성의 원칙은 수집된 증거가 이후 변조되지 않았음을 해시값 비교 등으로 입증해야 한다는 원칙이다.","정당성의 원칙은 증거가 적법한 절차로 수집되어야 한다는 원칙으로, 위법 수집 증거는 증거능력을 잃는다.","연계보관성(Chain of Custody) 원칙은 획득·이송·분석·보관·법정제출 각 단계의 담당자와 처리 내역이 기록·추적 가능해야 한다는 원칙이다."],"rel":["3-11"],"box":"증거는 획득, 이송, 분석, 보관, 법정제출이라는 일련의 과정이 명확해야 하고 이런 과정에 대한 추적이 가능해야 한다."},{"n":55,"s":"s3","q":"웹 보안 취약점은 무엇인가?","c":["XSS","CSRF","WebShell","Injection Flaws"],"a":1,"e":"CSRF(Cross-Site Request Forgery)는 사용자의 인증된 세션(쿠키 등)을 이용해 사용자가 의도하지 않은 요청을 서버로 보내게 하는 공격으로, 공격 대상이 서버라는 점이 특징이다. XSS는 악성 스크립트가 사용자 브라우저에서 실행되어 클라이언트를 공격 대상으로 한다는 점에서 다르다.","ce":["XSS는 악성 스크립트가 피해자 브라우저에서 실행되어 쿠키 탈취 등 클라이언트를 공격 대상으로 하므로 '공격 대상이 서버'라는 지문과 다르다.","CSRF는 쿠키·인증서 등 자동 전송되는 신뢰 정보를 이용해 사용자가 의도하지 않은 요청을 서버에 보내게 하는 공격으로, 공격 대상이 서버이다.","웹셸은 서버에 업로드된 스크립트로 원격 명령을 실행하는 백도어로, 사용자 요청 변조·신뢰 정보 악용과는 다르다.","Injection Flaws는 SQL·OS 명령 등 입력값을 해석기에 전달해 의도하지 않은 명령을 실행하게 하는 취약점으로, 인증된 사용자 권한을 도용하는 요청 위조와 다르다."],"rel":["3-6"],"box":"세션 쿠키, SSL 인증서, 윈도우 도메인 인증과 같이 자동으로 입력된 신뢰 정보를 기반으로 한 웹 애플리케이션에서 사용자의 요청을 변조함으로써 해당 사용자의 권한으로 악의적인 공격을 수행한다. 공격 대상은 클라이언트가 아니라 서버이며, 웹 2.0 환경에서 매우 효과적인 공격 기법이다."},{"n":56,"s":"s3","q":"다음 중 OTP에 대한 설명으로 틀린 것은?","c":["OTP는 전송계층에서 동작한다.","정적인 일반 패스워드와 달리 단방향 암호 기반의 해시를 매번 다르게 계산하여 패스워드로 사용한다.","OTP 생성 및 인증 방식에는 S/KEY 방식, 시간 동기화 방식 등이 있다.","온라인 뱅킹, 전자상거래, 온라인 게임 등에 사용된다."],"a":0,"e":"OTP는 응용 계층 수준의 사용자 인증 수단으로, 전송계층에서 동작하는 프로토콜이 아니다. 해시 체인(S/KEY), 시간 동기화, 이벤트(카운터) 동기화, 질의-응답 방식으로 매번 다른 일회용 패스워드를 생성하며 금융·전자상거래 인증에 널리 쓰인다.","ce":["틀린 설명이다. OTP는 전송계층 프로토콜이 아니라 응용 수준의 사용자 인증 수단(일회용 패스워드)이다.","옳은 설명이다. OTP는 해시 체인·시간·카운터 등을 입력으로 단방향 함수를 계산해 매번 다른 패스워드를 만든다.","옳은 설명이다. 생성 방식에는 S/KEY(해시 체인), 시간 동기화, 이벤트(카운터) 동기화, 질의-응답 방식 등이 있다.","옳은 설명이다. OTP는 온라인 뱅킹·전자상거래·게임 계정 보호 등 추가 인증 수단으로 널리 쓰인다."],"rel":["4-8"]},{"n":57,"s":"s3","q":"다음에 제시된 <보기 1>의 사용자 인증방법과 <보기 2>의 사용자 인증도구를 바르게 연결한 것은?","c":["①","②","③","④"],"a":2,"e":"지식 기반 인증은 사용자가 알고 있는 것(패스워드, B), 소지 기반 인증은 가지고 있는 것(OTP 토큰, A), 생체 기반 인증은 신체 특성(홍채, C)이다. 따라서 ㄱ-B, ㄴ-A, ㄷ-C로 짝지은 ③이 옳다.","ce":["ㄱ(지식)에 OTP 토큰(A)을 둔 것이 틀리다. OTP 토큰은 사용자가 가진 물건이므로 소지 기반이고, 지식 기반은 패스워드이다.","ㄱ-A(OTP), ㄴ-C(홍채), ㄷ-B(패스워드)로 세 가지 모두 어긋난다. 홍채는 생체, 패스워드는 지식 기반이다.","지식 기반=패스워드(B), 소지 기반=OTP 토큰(A), 생체 기반=홍채(C)로 모두 올바르게 연결되었다.","ㄱ-B(패스워드)는 맞지만 ㄴ(소지)에 홍채(C), ㄷ(생체)에 OTP 토큰(A)을 둔 것이 뒤바뀌었다."],"rel":["4-8"],"box":"<보기 1>\nㄱ. 지식 기반 인증\nㄴ. 소지 기반 인증\nㄷ. 생체 기반 인증\n<보기 2>\nA. OTP 토큰  B. 패스워드  C. 홍채\n\n     [ㄱ] [ㄴ] [ㄷ]\n①   A    B    C\n②   A    C    B\n③   B    A    C\n④   B    C    A"},{"n":58,"s":"s3","q":"DNS 공격 유형은 무엇인가?","c":["DNS 터널링","DNS 스푸핑","DNS 하이재킹","NXDOMAIN 공격"],"a":2,"e":"DNS 하이재킹은 DNS 서버를 해킹하거나 설정·패킷을 조작해 특정 도메인의 질의 결과를 공격자가 원하는 IP로 바꿔 사용자를 가로채는 공격이다. DNS 터널링은 DNS 질의·응답에 데이터를 숨겨 유출하는 기법이고, NXDOMAIN 공격은 존재하지 않는 도메인 질의를 대량 발생시키는 DoS 공격이다.","ce":["DNS 터널링은 DNS 질의·응답 필드에 데이터를 숨겨 방화벽을 우회하거나 정보를 유출하는 기법으로, 도메인-IP 매핑 위조가 목적이 아니다.","DNS 스푸핑도 위조 응답으로 사용자를 다른 IP로 유도하는 유사 개념이나, 지문의 'DNS 서버 해킹'까지 포함한 표현에 대해 공식 정답은 하이재킹이다.","DNS 하이재킹은 DNS 서버를 해킹하거나 설정·패킷을 조작해 특정 도메인의 IP를 공격자가 원하는 주소로 바꾸는 공격으로 공식 정답이다.","NXDOMAIN 공격은 존재하지 않는 도메인 질의를 대량 발생시켜 DNS 서버·리졸버 자원을 고갈시키는 DoS 공격이다."],"rel":["3-7"],"box":"해커가 DNS 서버를 해킹하거나, 패킷을 조작하여 특정 도메인에 대응하는 IP 주소를 해커가 원하는 IP 주소로 위조하는 기법이다.","flag":"DNS 스푸핑도 유사 개념이나 공식 정답은 3번(하이재킹)"},{"n":59,"s":"s3","q":"다음 중 유일하게 HTTP(HyperText Transfer Protocol) 응답(response)에 body data가 없는 메소드는?","c":["HEAD","GET","TRACE","POST"],"a":0,"e":"HEAD 메소드는 GET과 동일한 요청을 하되 응답에서 메시지 바디 없이 상태줄과 헤더만 반환하므로, 리소스 존재·수정 여부 확인에 쓰인다. TRACE는 수신한 요청 메시지를 바디에 그대로 되돌려주고, GET·POST 응답은 바디를 포함한다.","ce":["HEAD는 GET과 같은 요청을 하되 응답에서 바디 없이 상태줄과 헤더만 반환하므로 리소스 존재·변경 여부 확인에 쓰인다.","GET 응답은 요청한 리소스(HTML·이미지 등)를 메시지 바디에 담아 반환한다.","TRACE 응답은 서버가 받은 요청 메시지를 바디에 그대로 되돌려 주므로 바디가 있다(XST 공격에 악용 가능).","POST 응답은 처리 결과 페이지 등을 바디에 담아 반환하는 것이 일반적이다."],"rel":["3-3"]},{"n":60,"s":"s3","q":"전자상거래 SET 보안 프로토콜의 송신측 암호화 절차이다. 빈칸 ㉠, ㉡, ㉢, ㉣에 들어갈 용어로 적절한 것은?","c":["㉠ 공개키 ㉡ 대칭키 ㉢ 대칭키 ㉣ 개인키","㉠ 개인키 ㉡ 공개키 ㉢ 대칭키 ㉣ 공개키","㉠ 공개키 ㉡ 대칭키 ㉢ 공개키 ㉣ 공개키","㉠ 개인키 ㉡ 대칭키 ㉢ 대칭키 ㉣ 공개키"],"a":3,"e":"SET 전자봉투 방식에서 송신자는 메시지 해시를 자신의 개인키로 서명(㉠)하고, 원문과 서명을 대칭키(세션키)로 암호화(㉡)한 뒤, 그 대칭키(㉢)를 수신자의 공개키(㉣)로 암호화해 함께 보낸다. 서명에 공개키를 쓰거나 대용량 메시지를 공개키로 직접 암호화하는 보기는 틀리다.","ce":["㉠ 서명은 송신자의 공개키가 아니라 개인키로 해야 하고, ㉣ 대칭키 암호화에는 수신자의 개인키가 아니라 공개키를 써야 한다.","㉡ 원문+서명을 공개키로 직접 암호화하면 속도가 느려 비효율적이다. 전자봉투는 메시지를 대칭키(세션키)로 암호화한다.","㉠ 서명에 공개키를 쓸 수 없고, ㉢ 수신자 공개키로 다시 암호화하는 대상은 공개키가 아니라 사용된 대칭키이다.","개인키로 서명(㉠) → 대칭키로 메시지 암호화(㉡) → 그 대칭키(㉢)를 수신자 RSA 공개키(㉣)로 암호화하는 전자봉투 절차와 일치한다."],"rel":["3-13","3-10"],"box":"가. 송신자는 메시지를 압축하고, 압축된 메시지를 다시 송신자의 ( ㉠ )로 암호화하여 전자서명을 만든다.\n나. 원문 메시지에 전자서명을 첨부한 다음 이를 ( ㉡ )로 암호화한다.\n다. 그 다음 사용된 ( ㉢ )를 다시 수신자의 RSA ( ㉣ )로 암호화한 후 암호문과 함께 전송한다."},{"n":61,"s":"s4","q":"다음 지문에서 BLP 모델에 대한 설명으로 옳지 않은 것은?","c":["No-write-down 정책은 인가받은 보안등급 이하의 정보를 수정하지 못하게 하는 정책이다.","BLP 모델에서는 정보를 Top Secret, Secret, Unclassified 등과 같은 보안 등급에 따라 분류하고 있으며 정보의 기밀성 보장에 초점을 두고 있다.","BLP 모델에서 주체와 객체의 보안등급은 각각 취급등급(clearance), 비밀등급(security label)을 사용한다.","No-read-up 정책은 낮은 보안등급을 인가받은 주체가 보안등급이 높은 객체에 대한 읽기/쓰기 접근을 허용하지 않음으로 정보의 기밀성을 보장하게 된다."],"a":3,"e":"No-read-up(단순 보안 속성)은 낮은 등급 주체가 높은 등급 객체를 '읽는 것'만 금지하며, 상위 등급으로의 쓰기(write-up)는 *-속성에 따라 오히려 허용된다. 따라서 읽기/쓰기를 모두 금지한다는 ④가 틀리다. BLP는 기밀성 중심 모델로 no-read-up, no-write-down 규칙을 가진다.","ce":["옳은 설명이다. No-write-down(*-속성)은 주체가 자신의 등급보다 낮은 객체에 쓰지 못하게 해 상위 정보가 하위로 유출되는 것을 막는다.","옳은 설명이다. BLP는 Top Secret·Secret·Unclassified 등 등급으로 정보를 분류하며 기밀성 보장에 초점을 둔다.","옳은 설명이다. 주체에는 취급등급(clearance), 객체에는 비밀등급(classification·보안 레이블)을 부여해 비교한다.","옳지 않다. No-read-up은 낮은 등급 주체의 상위 객체 '읽기'만 금지하며, 상위 등급으로의 쓰기(write-up)는 *-속성상 허용된다."],"rel":["4-11"]},{"n":62,"s":"s4","q":"다음 해시함수 설명 중 잘못된 것은?","c":["해시함수는 임의의 유한 길이의 비트 스트링을 고정된 길이의 비트 스트링으로 변환하는 함수이다.","효율적 전자서명 생성을 위해 전자서명 생성 과정에서 해시함수가 사용된다.","일방향 특성으로서 해시함수 h에 대해 해시값 y로부터 h(x)=y가 되는 입력값 x를 찾는 것이 계산상 불가능해야 한다.","강한 충돌방지 특성으로서 해시함수 h에 대해 h(y)=h(x)가 되는 입력값 쌍 y와 x(단, y ≠ x)를 찾는 것이 어렵지 않아야 한다."],"a":3,"e":"강한 충돌 저항성은 h(x)=h(y)를 만족하는 서로 다른 입력 쌍 (x, y)를 찾는 것이 계산상 '어려워야' 한다는 성질이므로, '어렵지 않아야 한다'는 ④가 틀리다. 고정 길이 출력, 서명 효율화를 위한 해시 사용, 역상 저항성(일방향성)은 올바른 설명이다.","ce":["옳은 설명이다. 해시함수는 임의 길이 입력을 고정 길이(예 SHA-256은 256비트) 출력으로 압축한다.","옳은 설명이다. 긴 문서 대신 짧은 해시값에 서명하므로 서명 생성·검증 연산이 효율적이다.","옳은 설명이다. 역상 저항성(일방향성)은 해시값 y로부터 h(x)=y인 x를 찾는 것이 계산상 불가능해야 함을 뜻한다.","잘못된 설명이다. 강한 충돌 저항성은 h(x)=h(y)인 서로 다른 입력 쌍을 찾는 것이 계산상 '어려워야' 한다는 성질이다."],"rel":["4-5"]},{"n":63,"s":"s4","q":"RSA 암호화 방식에서 공개키가 (7,33), 개인키가 (3,33)일 경우, 공개키로 암호화 한 값이 3이라고 할 때 이를 복호화 한 값은 무엇인가?","c":["99","27","2,187","343"],"a":1,"e":"복호화는 M = C^d mod n이므로 3^3 mod 33 = 27 mod 33 = 27이다. 검증하면 27^7 mod 33 = 3이 되어 암호문과 일치한다. 2,187(=3^7)은 공개키 지수를 잘못 적용하고 mod 연산을 생략한 값이다.","ce":["99는 3×33으로 mod 33 결과가 0이 되어야 하므로 모듈러 연산 결과(0~32 범위)가 될 수 없다.","복호화는 M = C^d mod n = 3^3 mod 33 = 27이다. 27^7 mod 33 = 3으로 암호문과 일치해 검증된다.","2,187은 3^7로 공개키 지수 7을 잘못 적용하고 mod 33 연산도 생략한 값이다.","343은 7^3으로 암호문 대신 공개 지수를 밑으로 쓰는 등 식을 잘못 세웠고 mod 33도 적용하지 않은 값이다."],"rel":["4-4"]},{"n":64,"s":"s4","q":"CRL에 포함되어야 하는 기본 필드에 속하지 않는 것은?","c":["버전(Version)","서명 알고리즘(Signature)","다음 발급일자(Next Update)","인증서 효력정지 및 폐지 목록 번호(CRL Number)"],"a":3,"e":"X.509 CRL의 기본 필드는 버전, 서명 알고리즘, 발급자, 이번 발급일자(This Update), 다음 발급일자(Next Update), 폐지 인증서 목록(일련번호·폐지일자)이다. CRL Number는 CRL 순번을 나타내는 확장(Extension) 필드로 기본 필드에 속하지 않는다.","ce":["버전(Version)은 CRL 형식(v2 등)을 나타내는 X.509 CRL 기본 필드이다.","서명 알고리즘(Signature)은 CA가 CRL에 서명할 때 쓴 알고리즘 식별자로 기본 필드에 포함된다.","다음 발급일자(Next Update)는 다음 CRL이 발행될 예정 시각으로 기본 필드에 포함된다.","CRL Number는 CRL의 일련 순번을 나타내는 확장(Extension) 필드로, 기본 필드(버전·서명 알고리즘·발급자·This/Next Update·폐지 목록)에 속하지 않는다."],"rel":["4-7"]},{"n":65,"s":"s4","q":"RADIUS 프로토콜의 기본 기능과 가장 거리가 먼 것은?","c":["인증","계정 관리","권한 부여","책임추적성"],"a":3,"e":"RADIUS는 원격 접속 사용자에 대한 AAA, 즉 인증(Authentication)·권한 부여(Authorization)·계정 관리(Accounting)를 제공하는 프로토콜이다. 책임추적성(Accountability)은 AAA의 기본 기능 명칭이 아니다.","ce":["인증(Authentication)은 사용자 ID·패스워드 등을 검증하는 RADIUS AAA의 기본 기능이다.","계정 관리(Accounting)는 접속 시간·사용량 등을 기록해 과금·감사에 활용하는 RADIUS AAA의 기본 기능이다.","권한 부여(Authorization)는 인증된 사용자에게 접근 가능한 서비스·IP 등 권한을 할당하는 RADIUS AAA의 기본 기능이다.","책임추적성(Accountability)은 행위를 주체에 연결하는 보안 목표 개념으로, RADIUS AAA(인증·권한부여·계정관리)의 기능 명칭이 아니다."],"rel":["2-8"]},{"n":66,"s":"s4","q":"한국형 암호 알고리즘은 무엇인가?","c":["SEED","ARIA","HIGHT","LEA"],"a":3,"e":"LEA(Lightweight Encryption Algorithm)는 국가보안기술연구소가 2013년 개발한 128비트 경량 블록 암호로, 2019년 ISO/IEC 29192-2 국제표준에 포함되었고 AES 대비 빠른 소프트웨어 처리 성능을 가진다. HIGHT도 경량 암호이지만 64비트 블록으로 2006년 개발되었고, SEED(1999)·ARIA(2004)는 범용 128비트 블록 암호이다.","ce":["SEED는 한국인터넷진흥원(KISA) 주도로 1999년 개발된 128비트 범용 블록 암호로, 2013년 경량 암호가 아니다.","ARIA는 2004년 국가보안기술연구소 중심으로 개발된 128비트 범용 블록 암호(국가표준)로, IoT용 경량 암호가 아니다.","HIGHT도 경량 암호이지만 2006년 개발된 64비트 블록 암호로, 2013년 개발·AES 대비 고처리량 설명과 맞지 않는다.","LEA(Lightweight Encryption Algorithm)는 국가보안기술연구소가 2013년 개발한 128비트 경량 블록 암호로, 2019년 ISO/IEC 29192-2 국제표준에 포함되었다."],"rel":["4-2"],"box":"국가보안기술연구소에서 2013년 개발한 경량 블록 암호 알고리즘으로 2019년 국제표준으로 제정되었다. 특징으로는 AES 암호알고리즘에 대비하여 경량 암호로 높은 처리량, 낮은 전력소비로 사물인터넷 암호화에 적합한 알고리즘이다."},{"n":67,"s":"s4","q":"해시함수 h의 성질에 관한 설명 중 틀린 것은?","c":["역상저항성은 주어진 임의의 출력값 y에 대해 y=h(x)를 만족하는 입력값 x를 찾는 것이 계산적으로 불가능한 성질이다.","두 번째 역상 저항성은 주어진 입력값 x에 대해 h(x)=h(x')를 만족하는 다른 입력값 x'을 찾는 것이 계산적으로 불가능한 성질이다.","충돌 저항성은 h(x)=h(x')를 만족하는 두 입력값 x와 x'을 찾는 것이 계산적으로 불가능한 성질이다.","충돌 저항성은 역상 저항성을 보장한다."],"a":3,"e":"충돌 저항성은 두 번째 역상 저항성을 함의하지만, 역상 저항성(일방향성)까지 보장하지는 않는다(충돌 저항적이면서 역상을 쉽게 구할 수 있는 함수를 구성할 수 있음). ①~③은 역상·두 번째 역상·충돌 저항성의 올바른 정의이다.","ce":["옳은 설명이다. 역상 저항성(일방향성)은 출력 y로부터 y=h(x)인 입력 x를 찾기 계산상 불가능한 성질이다.","옳은 설명이다. 두 번째 역상 저항성은 주어진 x에 대해 같은 해시값을 갖는 다른 x'를 찾기 불가능한 성질이다.","옳은 설명이다. 충돌 저항성은 h(x)=h(x')인 임의의 서로 다른 두 입력 쌍을 찾기 불가능한 성질이다.","틀린 설명이다. 충돌 저항성은 두 번째 역상 저항성을 함의하지만 역상 저항성까지 보장하지는 않는다."],"rel":["4-5"]},{"n":68,"s":"s4","q":"암호 알고리즘 공격 방법은 무엇인가?","c":["암호문 단독 공격","기지 평문 공격","선택 평문 공격","선택 암호문 공격"],"a":2,"e":"선택 평문 공격(CPA)은 공격자가 암호기에 접근해 원하는 평문을 넣고 대응 암호문을 얻어 키를 추정하는 공격이다. 기지 평문 공격은 이미 알려진 평문-암호문 쌍만 이용하고, 선택 암호문 공격은 복호기에 접근해 선택한 암호문의 평문을 얻는다.","ce":["암호문 단독 공격은 암호문만 가지고 평문·키를 추정하는 가장 제한된 공격으로, 암호기에 접근할 수 없다.","기지 평문 공격은 이미 알려진 평문-암호문 쌍을 이용하는 공격으로, 공격자가 암호기에 원하는 평문을 넣을 수는 없다.","선택 평문 공격(CPA)은 암호기에 접근해 원하는 평문을 넣고 대응 암호문을 얻어 키를 추정하는 공격이다.","선택 암호문 공격(CCA)은 복호기에 접근해 선택한 암호문의 평문을 얻는 공격으로, 암호기 접근 조건과 다르다."],"rel":["4-1"],"box":"암호 해독자가 사용된 암호기에 접근할 수 있어 평문에 해당하는 암호문을 얻을 수 있는 상황에서 키를 추정하며 암호를 해독하는 방법이다."},{"n":69,"s":"s4","q":"Kerberos 키 분배 프로토콜의 기반 기술에 해당하는 것은?","c":["Needham-Schroeder 프로토콜","Challenge-Response 프로토콜","Diffie-Hellman 프로토콜","RSA 이용 키 분배 프로토콜"],"a":0,"e":"Kerberos는 신뢰된 제3자(KDC)가 대칭키로 세션키를 분배하는 Needham-Schroeder 대칭키 프로토콜을 기반으로, 재전송 공격 방지를 위해 타임스탬프를 추가한 구조이다. Diffie-Hellman·RSA는 공개키 기반 키 교환·분배 방식이다.","ce":["Kerberos는 신뢰된 제3자(KDC)가 대칭키로 세션키를 분배하는 Needham-Schroeder 대칭키 프로토콜에 타임스탬프를 더해 재전송 공격을 막은 구조이다.","Challenge-Response는 난수 질의에 대한 응답으로 신원을 확인하는 일반적 인증 기법으로, Kerberos의 키 분배 기반 프로토콜 명칭이 아니다.","Diffie-Hellman은 양측이 공개값만 교환해 공통 비밀키를 계산하는 공개키 기반 키 합의로, 제3자 KDC가 키를 분배하는 Kerberos와 다르다.","RSA 키 분배는 세션키를 상대 공개키로 암호화해 전달하는 방식으로, 대칭키만 쓰는 Kerberos의 기반이 아니다."],"rel":["4-12","2-8"]},{"n":70,"s":"s4","q":"다음 지문이 설명하는 해시(Hash) 함수에 해당하는 것은?","c":["MD4","MD5","SHA-1","SHA-256"],"a":1,"e":"MD5는 512비트 블록 단위로 처리해 128비트 해시를 출력하며, 4라운드 각 16단계로 총 64단계 연산을 수행한다. MD4는 128비트 출력이지만 3라운드(48단계)이고, SHA-1은 160비트, SHA-256은 256비트를 출력한다.","ce":["MD4는 128비트 출력·512비트 블록이지만 3라운드(48단계)로 구성되어 4라운드 64단계 조건과 다르다.","MD5는 512비트 블록을 처리해 128비트 해시를 출력하며 4라운드×16단계=64단계 연산으로 구성된다.","SHA-1은 512비트 블록을 처리하지만 출력이 160비트이고 80단계로 구성된다.","SHA-256은 512비트 블록을 처리하지만 출력이 256비트이고 64라운드로 구성되어 128비트 출력 조건과 다르다."],"rel":["4-5"],"box":"- 128비트 출력\n- 512비트 블록단위로 처리\n- 4라운드 64단계로 구성"},{"n":71,"s":"s4","q":"전자서명이 갖추어야 할 조건이 아닌 것은?","c":["개인키를 알고 있는 서명자만 서명을 생성할 수 있다.","서명자를 누구든지 검증할 수 있다.","문서의 해시값에 서명하므로 생성된 서명은 다른 문서에 재사용할 수 있다.","서명자는 자신의 서명 사실을 부인할 수 없다."],"a":2,"e":"전자서명은 해당 문서의 해시값에 종속되므로 다른 문서에 재사용할 수 없어야 한다(재사용 불가). 위조 불가(서명자만 생성), 서명자 인증(누구나 검증), 부인방지, 변경 불가는 전자서명의 필수 조건이다.","ce":["옳은 조건이다. 위조 불가 — 개인키를 가진 서명자만 유효한 서명을 생성할 수 있어야 한다.","옳은 조건이다. 서명자 인증 — 공개키로 누구든지 서명자를 검증할 수 있어야 한다.","조건이 아니다. 서명은 해당 문서의 해시값에 종속되므로 다른 문서에 재사용할 수 없어야 한다(재사용 불가).","옳은 조건이다. 부인방지 — 서명자는 자신의 서명 사실을 나중에 부인할 수 없어야 한다."],"rel":["4-6"]},{"n":72,"s":"s4","q":"다음 지문이 설명하는 키 교환 방식은?","c":["KDC 교환 방식","RSA 키 교환방식","Diffie-Hellman 키 교환방식","사전공유 키 교환방식"],"a":2,"e":"Diffie-Hellman 키 교환은 키 자체를 전송하지 않고 양측이 공개값(g^a mod p, g^b mod p)만 교환해 각자 동일한 비밀키를 계산하며, 이산대수 문제의 어려움에 안전성을 둔다. RSA 키 교환은 한쪽이 생성한 세션키를 상대 공개키로 암호화해 전달하는 방식이고, KDC 방식은 제3자가 키를 분배한다.","ce":["KDC 방식은 신뢰된 키 분배 센터가 세션키를 생성해 양측에 전달하는 방식으로, 완성된 키를 전달한다는 점에서 지문과 반대이다.","RSA 키 교환은 한쪽이 생성한 세션키를 상대 공개키로 암호화해 '완성된 키'를 전달하는 방식이다.","Diffie-Hellman은 g^a mod p, g^b mod p 같은 공개값만 교환하고 양측이 각자 동일한 비밀키 g^ab mod p를 계산하므로 지문과 일치한다.","사전공유 키 방식은 미리 동일한 키를 양측에 배포해 두는 방식으로, 교환한 정보로 키를 계산하지 않는다."],"rel":["4-12","4-4"],"box":"양자 간에 완성된 키를 교환하지 않고, 서로가 주고받은 특정 정보로 양자가 동일한 키를 계산하여 키를 분배한다."},{"n":73,"s":"s4","q":"전자서명의 요구사항으로 가장 적절하지 않은 것은?","c":["전자서명을 위조하는 것이 계산적으로 실행 불가능해야 한다.","전자서명 생성이 비교적 용이해야 한다.","기억장소에 전자서명의 복사본을 유지하는 것이 실용적이어야 한다.","위조와 부인을 방지하기 위하여 수신자에 대한 정보를 사용해야 한다."],"a":3,"e":"위조·부인 방지를 위해 전자서명에는 수신자가 아니라 송신자(서명자)만이 가진 고유 정보(개인키)를 사용해야 한다. 위조의 계산적 불가능성, 생성·검증의 용이성, 복사본 보관의 실용성은 W. Stallings가 제시한 전자서명 요구사항이다.","ce":["옳은 요구사항이다. 서명 위조는 계산적으로 실행 불가능해야 한다.","옳은 요구사항이다. 서명 생성(및 인식·검증)은 비교적 용이해야 실용적이다.","옳은 요구사항이다. 서명 사본을 저장해 두는 것이 실용적이어야 분쟁 시 검증할 수 있다.","적절하지 않다. 위조·부인 방지를 위해서는 수신자가 아니라 송신자(서명자)만의 고유 정보(개인키)를 사용해야 한다."],"rel":["4-6"]},{"n":74,"s":"s4","q":"블록암호 모드는 무엇인가?","c":["암호 블록체인 모드(Cipher Block Chaining Mode)","암호 피드백 모드(Cipher Feedback Mode)","출력 피드백 모드(Output Feedback Mode)","카운터 모드(Counter Mode)"],"a":1,"e":"CFB 모드는 IV(이후엔 직전 암호문 블록)를 암호화한 값과 평문을 XOR해 암호문을 만들므로 암호화 시 오류가 이후 블록으로 전파되지만, 복호화 시 암호문 오류 영향은 국지적이다. OFB는 암호화 출력값 자체를 피드백해 암호문에 의존하지 않고, CBC는 평문과 이전 암호문을 XOR한 뒤 암호화한다.","ce":["CBC 모드는 평문 블록을 이전 암호문 블록과 XOR한 뒤 암호화하므로, '암호화한 값과 평문을 XOR'하는 지문의 순서와 다르다.","CFB 모드는 IV(이후 직전 암호문)를 암호화한 값과 평문을 XOR해 암호문을 만들고 그 암호문을 다시 입력으로 쓰며, 복호화 오류 영향이 국지적이다.","OFB 모드는 암호문이 아니라 블록 암호의 출력값 자체를 다음 입력으로 피드백하므로 평문 블록이 이후 암호문에 영향을 주지 않는다.","CTR 모드는 카운터 값을 암호화해 평문과 XOR하며 블록 간 연쇄가 없어, 특정 평문이 이후 모든 암호문에 영향을 주지 않는다."],"rel":["4-3"],"box":"초기값을 암호화한 값과 평문 블록을 XOR하여 암호문 블록을 생성하고, 그 암호문을 입력으로 사용하여 다시 암호화한 값과 평문 블록을 XOR하여 암호문 블록을 생성하는 작업을 반복하는 방식이다. 암호화에서는 특정 평문 블록이 이후의 모든 암호문 블록에 영향을 미치지만, 복호화에서는 특정 암호문 블록 오류의 영향이 국지적이라는 특성을 갖는다."},{"n":75,"s":"s4","q":"공개키 암호화 방식에 대한 설명으로 옳은 것은?","c":["고급 데이터 암호화 기법","DES(Data Encryption Standard)","부인방지 및 인증 지원","암호화 속도가 빠름"],"a":2,"e":"공개키 암호는 개인키 서명을 통해 인증과 부인방지를 지원한다. AES(고급 데이터 암호화 표준)와 DES는 대칭키 알고리즘이며, 공개키 방식은 수학적 연산량이 커서 대칭키보다 암호화 속도가 느리다.","ce":["고급 데이터 암호화 기법(AES)은 대칭키 블록 암호 표준으로, 공개키 암호 방식의 설명이 아니다.","DES는 56비트 키를 쓰는 대칭키 블록 암호 표준으로 공개키 방식이 아니다.","공개키 암호는 개인키로 서명하고 공개키로 검증하므로 인증과 부인방지를 지원한다.","공개키 암호는 큰 수의 모듈러 거듭제곱 등 연산량이 많아 대칭키보다 암호화 속도가 느리다."],"rel":["4-4"]},{"n":76,"s":"s4","q":"해시함수에 대한 내용으로 옳지 않은 것은?","c":["정보의 무결성을 확인하기 위한 목적으로 사용한다.","해시함수는 일방향성, 충돌 회피, 효율성의 특징이 있다.","SHA-1 함수는 MD5보다 조금 느리지만 보안성 측면에서 좀 더 안전하다.","인증에서 증명 용도로 사용될 수 없다."],"a":3,"e":"해시함수는 MAC(HMAC), 패스워드 저장·검증, 전자서명 등 인증 과정의 증명 용도로 널리 사용되므로 ④가 틀리다. 무결성 확인 용도, 일방향성·충돌 저항성, SHA-1(160비트)이 MD5(128비트)보다 느리지만 상대적으로 안전하다는 설명은 옳다.","ce":["옳은 설명이다. 원본과 수신본의 해시값을 비교해 변조 여부를 확인하는 무결성 검증에 쓰인다.","옳은 설명이다. 해시함수는 일방향성(역상 저항성), 충돌 회피(충돌 저항성), 빠른 계산(효율성)을 갖춰야 한다.","옳은 설명이다. SHA-1(160비트 출력·80단계)은 MD5(128비트·64단계)보다 약간 느리지만 출력이 길어 상대적으로 안전하다(현재는 둘 다 충돌 공격으로 권고 제외).","옳지 않다. 해시는 HMAC 메시지 인증, 패스워드 해시 저장·검증, 전자서명 등 인증 과정의 증명 용도로 널리 쓰인다."],"rel":["4-5"]},{"n":77,"s":"s4","q":"㉠, ㉡, ㉢에 들어갈 내용으로 적절한 것은?","c":["㉠ 취약점 ㉡ 위협 ㉢ 위험","㉠ 위험 ㉡ 위협 ㉢ 취약점","㉠ 위험 ㉡ 취약점 ㉢ 위협","㉠ 취약점 ㉡ 위험 ㉢ 위협"],"a":0,"e":"백신을 최신화하지 않은 상태는 자산의 약점인 취약점, 시스템을 공격하는 바이러스는 위협, 위협이 취약점을 이용해 피해를 줄 가능성은 위험이다. 즉 위험은 자산·위협·취약점의 함수로 정의된다.","ce":["백신 미갱신 상태는 자산의 약점인 취약점(㉠), 바이러스는 공격 주체인 위협(㉡), 위협이 취약점을 이용해 피해를 줄 가능성은 위험(㉢)이다.","㉠ 백신 미갱신은 피해 가능성(위험)이 아니라 시스템의 약점(취약점)이고, ㉢ 피해 가능성은 취약점이 아니라 위험이다.","㉠은 취약점, ㉡ 바이러스는 공격을 가하는 위협, ㉢ 피해 가능성은 위험이어야 하는데 세 항목이 모두 어긋난다.","㉠ 취약점은 맞지만 ㉡ 바이러스는 피해 가능성(위험)이 아니라 위협이고, ㉢ 피해 가능성은 위협이 아니라 위험이다."],"rel":["5-2"],"box":"정보시스템에 백신 프로그램을 설치한 후, 최신으로 유지하지 않는다면 해당 시스템은 바이러스에 ( ㉠ )을 가지고 있는 것이다. 여기서 바이러스는 시스템을 공격하는 ( ㉡ )이 되고, 바이러스 공격으로 발생하는 해당 시스템의 피해 가능성을 ( ㉢ )이라고 한다."},{"n":78,"s":"s4","q":"생체인증 기술의 정확성을 나타내는 FRR(False Rejection Rate)과 FAR(False Acceptance Rate)에 대해서 잘못 설명한 것은?","c":["시스템에 접근하려 할 때 FRR이 낮으면 사용자 편의성이 증대된다.","시스템에 접근하려 할 때 FAR이 높으면 사용자 편의성이 증대된다.","시스템의 생체인증 보안성을 강화하게 되면 FRR이 높아진다.","시스템의 생체인증 보안성을 강화하게 되면 FAR이 높아진다."],"a":3,"e":"보안성을 강화(임계치 상향)하면 타인을 잘못 수락하는 FAR은 낮아지고 본인을 잘못 거부하는 FRR은 높아진다. 따라서 FAR이 높아진다는 ④가 틀리다. FRR이 낮거나 FAR이 높으면 거부가 적어 편의성은 증대된다.","ce":["옳은 설명이다. FRR(본인 거부율)이 낮으면 정당한 사용자가 잘못 거부되는 일이 줄어 편의성이 커진다.","옳은 설명이다. FAR(타인 수락율)이 높으면 거부가 드물어 편의성은 커지지만 보안성은 떨어진다.","옳은 설명이다. 보안성을 강화(판정 임계치 상향)하면 본인도 잘못 거부될 확률, 즉 FRR이 높아진다.","잘못된 설명이다. 보안성을 강화하면 타인을 잘못 수락하는 FAR은 낮아진다. FAR과 FRR은 반비례(트레이드오프) 관계이다."],"rel":["4-8"]},{"n":79,"s":"s4","q":"공격과 이를 방어하는 기술로 알맞게 짝지어진 것은?","c":["키 추측공격 - 의사난수 알고리즘, 키 길이 확대","중간자공격 - 대칭암호, 공개키 암호","재전송공격 - 순서번호, 타임스탬프, 비표","위조공격 - 일방향 해시함수, 메시지 인증 알고리즘"],"a":2,"e":"지문은 가로챈 메시지와 MAC을 그대로 다시 보내는 재전송(Replay) 공격이며, 순서번호·타임스탬프·비표(Nonce)로 메시지의 새로움(freshness)을 확인해 방어한다. MAC 자체는 위조는 막지만 재전송은 막지 못한다는 점이 핵심이다.","ce":["키 추측 공격은 키 공간을 탐색해 키를 알아내는 공격으로, 지문처럼 가로챈 메시지·MAC을 그대로 재전송하는 상황과 다르다.","중간자 공격은 통신 사이에서 메시지를 가로채 변조·중계하는 공격으로, 방어는 상호 인증·인증서 검증이 핵심이며 지문은 변조 없는 재전송이다.","지문은 가로챈 메시지와 MAC을 그대로 반복 전송하는 재전송(Replay) 공격이며, 순서번호·타임스탬프·비표(Nonce)로 메시지의 새로움을 확인해 방어한다.","위조 공격은 메시지를 조작하는 공격으로 해시·MAC으로 막을 수 있으나, 지문은 원래 유효한 메시지와 MAC을 그대로 보내므로 MAC으로는 탐지되지 않는다."],"rel":["4-5"],"box":"메시지 인증 및 무결성을 보장하고자 송신자는 메시지와 함께 그 메시지의 MAC(Message Authentication Code)을 수신자에게 보낸다. 이때 공격자가 중간에 이 메시지와 MAC을 가로채서 보관한다. 그리고 송신자 대신 메시지 및 MAC을 그대로 수신자에게 반복해서 보내면 수신자는 송신자로부터 온 것으로 판단하고, 이를 반복해서 처리하는 공격을 받게 된다."},{"n":80,"s":"s4","q":"다음 지문은 Diffie-Hellman 키 사전 분배에 대한 내용을 설명한 것이다. ㉠~㉣에 들어가야 할 단어로 옳은 것은?","c":["㉠ 이산대수문제 ㉡ 큰 정수 ㉢ 공개키 ㉣ 개인키","㉠ 이산대수문제 ㉡ 큰 소수 ㉢ 개인키 ㉣ 공개키","㉠ 소인수분해문제 ㉡ 큰 정수 ㉢ 개인키 ㉣ 공개키","㉠ 소인수분해문제 ㉡ 큰 소수 ㉢ 공개키 ㉣ 개인키"],"a":1,"e":"Diffie-Hellman은 이산대수 문제의 어려움에 기반하며, 키 분배 센터가 큰 소수 p와 원시근 g를 공개한다. 가입자는 비밀값(개인키) x를 선정하고 g^x mod p(공개키)를 계산해 공개한다. 소인수분해 문제는 RSA의 안전성 근거이다.","ce":["㉡은 임의의 큰 정수가 아니라 원시근이 존재하는 큰 소수여야 하고, 가입자는 개인키(㉢)를 선정해 공개키(㉣)를 계산하므로 ㉢·㉣이 뒤바뀌었다.","DH는 이산대수 문제(㉠)에 기반하고, 센터가 큰 소수 p(㉡)와 원시근 g를 공개하며, 가입자는 개인키 x(㉢)를 정해 g^x mod p 공개키(㉣)를 공개한다.","소인수분해 문제는 RSA의 안전성 근거로 DH와 다르며, p도 큰 정수가 아니라 큰 소수여야 한다.","㉡ 큰 소수는 맞지만 ㉠ 소인수분해 문제는 RSA의 근거이고, ㉢·㉣도 개인키 선정 → 공개키 계산 순서가 뒤바뀌었다."],"rel":["4-12"],"box":"Diffie-Hellman 키 사전 분배 방식은 Diffie-Hellman의 키 교환 방식을 응용한 방식으로 ( ㉠ )를 기반으로 구성된다. 키 분배 센터는 ( ㉡ ) p를 선정하고 Zp위에서 원시근 g를 찾아 공개한다. 가입자는 ( ㉢ )를 선정하며 ( ㉣ )를 계산하여 공개한다."},{"n":81,"s":"s5","q":"BCP의 접근 5단계 방법론을 순차적으로 올바르게 나열한 것은?","c":["프로젝트의 범위 설정 및 기획 → 복구전략 개발 → 사업영향평가 → 복구계획 수립 → 프로젝트의 수행 테스트 및 유지보수","프로젝트의 범위 설정 및 기획 → 사업영향평가 → 복구전략 개발 → 복구계획 수립 → 프로젝트의 수행 테스트 및 유지보수","프로젝트의 범위 설정 및 기획 → 복구계획 수립 → 사업영향평가 → 복구전략 개발 → 프로젝트의 수행 테스트 및 유지보수","프로젝트의 범위 설정 및 기획 → 복구계획 수립 → 복구전략 개발 → 사업영향평가 → 프로젝트의 수행 테스트 및 유지보수"],"a":1,"e":"BCP는 범위 설정·기획 → 사업영향평가(BIA, 핵심 업무·RTO 도출) → 복구전략 개발 → 복구계획 수립 → 테스트·유지보수 순으로 수행한다. BIA 결과를 근거로 복구전략을 세워야 하므로 BIA보다 복구전략·복구계획이 앞서는 보기들은 틀리다.","ce":["복구전략 개발이 사업영향평가(BIA)보다 앞서 있다. 복구전략은 BIA로 도출한 핵심 업무·RTO를 근거로 세워야 한다.","범위 설정·기획 → 사업영향평가(BIA) → 복구전략 개발 → 복구계획 수립 → 테스트·유지보수 순으로 BCP 5단계 방법론과 일치한다.","복구계획 수립이 BIA와 복구전략보다 앞서 있다. 계획은 전략이 정해진 뒤 구체화하는 단계이다.","복구계획 → 복구전략 → BIA 순으로 거꾸로 되어 있다. BIA가 가장 먼저 수행되어야 이후 단계의 근거가 된다."],"rel":["5-3"]},{"n":82,"s":"s5","q":"'사이버위기경보'의 등급 중 복수 정보통신서비스제공자(ISP)망에 장애 또는 마비가 발생하였을 경우, 발령하는 경보의 단계는 무엇인가?","c":["심각 단계","경계 단계","주의 단계","관심 단계"],"a":1,"e":"사이버위기경보는 관심-주의-경계-심각 4단계이며, 복수 ISP망 장애·마비 등 다수 기관의 정보통신망에 장애가 발생한 경우 '경계'가 발령된다. '주의'는 일부 기관 정보시스템 장애, '심각'은 국가 전반의 정보통신망 장애·마비 시 발령된다(개정 여부 확인).","ce":["심각 단계는 국가 전반의 정보통신망 장애·마비 등 대규모 피해가 발생했거나 확실시될 때 발령된다(개정 여부 확인).","경계 단계는 복수 ISP망·국가 기간망 등 다수 기관 정보통신망에 장애·마비가 발생하거나 가능성이 높을 때 발령된다(개정 여부 확인).","주의 단계는 일부 기관의 정보시스템 장애나 침해 확산 가능성이 증가할 때 발령되며, 복수 ISP망 장애보다 낮은 수준이다.","관심 단계는 해외 사이버공격 증가, 웜·바이러스 출현 등 위협 징후가 있을 때 발령되는 최하위 단계이다."],"rel":["5-13"]},{"n":83,"s":"s5","q":"정보통신기반보호법에 따르면 관리기관의 장은 대통령령이 정하는 바에 따라 정기적으로 소관 주요정보통신기반시설의 취약점을 분석·평가하여야 한다. 이때 관리기관의 장은 특정 기관으로 하여금 소관 주요정보통신기반시설의 취약점을 분석·평가하게 할 수 있는데, 그에 속하지 아니 하는 기관은?","c":["한국인터넷진흥원","국가정보원","대통령령이 정하는 기준을 충족하는 정보공유·분석센터","정부출연 연구기관 등의 설립·운영 및 육성에 관한법률의 규정에 의한 한국전자통신연구원"],"a":1,"e":"정보통신기반보호법 제9조에 따라 취약점 분석·평가를 대행할 수 있는 기관은 한국인터넷진흥원, 요건을 갖춘 정보공유·분석센터, 정보보호 전문서비스 기업(지식정보보안 컨설팅전문업체), 한국전자통신연구원이다. 국가정보원은 공공분야 기반시설의 보호 지원·기술지원 주체일 뿐 대행 기관 목록에 없다(개정 여부 확인).","ce":["한국인터넷진흥원(KISA)은 정보통신기반보호법 제9조에 따라 취약점 분석·평가를 대행할 수 있는 기관이다(개정 여부 확인).","국가정보원은 공공분야 기반시설 보호의 지원·기술지원 주체로, 제9조의 취약점 분석·평가 대행 기관 목록에 포함되지 않는다.","대통령령이 정하는 기준을 충족하는 정보공유·분석센터(ISAC)는 취약점 분석·평가를 대행할 수 있는 기관이다.","정부출연연구기관법에 따른 한국전자통신연구원(ETRI)은 취약점 분석·평가를 대행할 수 있는 기관으로 명시되어 있다."],"rel":["5-13"]},{"n":84,"s":"s5","q":"A기업은 정보보호관리체계 수립을 위한 일환으로 보호해야 할 정보자산을 식별하고 식별된 정보자산에 대한 가치평가를 하려고 한다. 이때 정보자산의 가치평가에 사용하는 평가항목으로 적절하지 않은 것은?","c":["무결성 평가","가용성 평가","기밀성 평가","부인방지 평가"],"a":3,"e":"정보자산의 가치(중요도)는 일반적으로 기밀성(C)·무결성(I)·가용성(A) 3요소에 대한 영향도로 평가한다. 부인방지는 전자서명 등 보안 서비스의 한 기능이지 자산 가치평가 항목이 아니다.","ce":["무결성 평가는 자산이 변조될 경우의 영향도를 따지는 것으로, CIA 기반 자산 가치평가 항목이다.","가용성 평가는 자산을 쓸 수 없을 때 업무에 미치는 영향도를 따지는 것으로, 자산 가치평가 항목이다.","기밀성 평가는 자산이 유출될 경우의 영향도를 따지는 것으로, 자산 가치평가 항목이다.","부인방지는 전자서명 등으로 제공되는 보안 서비스 기능이며, 자산 가치(중요도)는 기밀성·무결성·가용성 영향도로 평가한다."],"rel":["5-12"]},{"n":85,"s":"s5","q":"「정보보호산업의 진흥에 관한 법률」에 따른 '정보보호 공시제도'에 관한 설명이다. 가장 거리가 먼 것은?","c":["정보보호 공시제도는 정보보호에 대한 기업의 투자 현황 및 활동을 공개하여 주주의 알권리를 확보하고, 투자자들에게 투자정보를 제공하기 위한 제도이다.","정보보호 공시제도는 이용자들에게 정보보호에 대한 기업의 투자 현황과 활동을 공개하여 정보보호에 대한 기업의 투자를 촉진하기 위한 제도이다.","정보보호 공시제도는 기업의 책임 하에 제공되는 정보이지만 공시내용의 투명성 확보를 위해 정부는 모니터링 점검단을 통해 정기적으로 공시내용에 대한 정확성을 검증한다.","정보보호 공시제도를 통해 해당 기업의 정보보호 관련 투자현황, 전문인력현황, 인증현황, 정보보호 위반 관련 행정처분 내역 등을 알 수 있다."],"a":3,"e":"정보보호 공시 항목은 정보보호 투자 현황, 전문인력 현황, 인증·평가·점검 현황, 정보보호 활동 현황 등이며, 정보보호 위반 관련 행정처분 내역은 공시 항목이 아니다. 공시는 투자 촉진과 이용자·투자자 알권리 보장을 목적으로 하고, 정부가 이행 점검을 한다(개정 여부 확인).","ce":["옳은 설명이다. 공시제도는 기업의 정보보호 투자·활동을 공개해 주주 알권리와 투자자 판단 정보를 제공한다.","옳은 설명이다. 이용자에게 정보보호 투자·활동을 공개해 기업의 정보보호 투자를 유도·촉진하는 것이 제도 목적이다.","옳은 설명이다. 공시 내용은 기업 책임이지만 정부(과기정통부·KISA)가 이행 점검을 통해 정확성을 검증한다(개정 여부 확인).","거리가 멀다. 공시 항목은 투자 현황·전문인력 현황·인증 현황·정보보호 활동 등이며, 정보보호 위반 관련 행정처분 내역은 공시 항목이 아니다."],"rel":["5-10"]},{"n":86,"s":"s5","q":"정보통신기반보호법상 중앙행정기관의 장은 소관분야의 정보통신기반시설 중 전자적 침해행위로부터의 보호가 필요하다고 인정되는 정보통신기반시설을 주요정보통신기반시설로 지정할 수 있는데, 이 경우에 고려할 사항으로 명시되지 않은 것은?","c":["당해정보통신기반시설을 관리하는 기관이 수행하는 업무의 국가 사회적 중요성","침해사고가 발생할 경우 국제적으로 미칠 수 있는 피해의 범위","다른 정보통신기반시설과의 상호 연계성","침해사고의 발생가능성 또는 그 복구의 용이성"],"a":1,"e":"정보통신기반보호법 제8조의 지정 기준은 업무의 국가사회적 중요성, 업무의 기반시설 의존도, 다른 기반시설과의 상호연계성, 침해사고 시 국가안전보장과 경제사회에 미치는 피해규모 및 범위, 침해사고 발생가능성 또는 복구의 용이성이다. '국제적으로 미칠 수 있는 피해의 범위'는 명시되어 있지 않다(개정 여부 확인).","ce":["명시된 고려사항이다. 기반시설을 관리하는 기관이 수행하는 업무의 국가사회적 중요성은 제8조 지정 기준이다.","명시되지 않았다. 법은 침해사고 시 '국가안전보장과 경제사회에 미치는 피해규모 및 범위'를 규정하며 '국제적 피해 범위'는 기준이 아니다.","명시된 고려사항이다. 다른 정보통신기반시설과의 상호연계성은 제8조 지정 기준이다.","명시된 고려사항이다. 침해사고의 발생가능성 또는 그 복구의 용이성은 제8조 지정 기준이다."],"rel":["5-13"]},{"n":87,"s":"s5","q":"다음은 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」상 정보통신망에 유통되어서는 안 되는 불법정보 관련 조항을 나열한 것이다. 실제 내용과 다른 것은 무엇인가?","c":["음란한 부호·문언·음향·화상 또는 영상을 배포·판매·임대하거나 공공연하게 전시하는 내용의 정보","법령에 따라 금지되는 사행행위에 해당하는 내용의 정보","사람을 비방할 목적으로 공공연하게 사실이나 거짓의 사실을 드러내어 타인의 명예를 모욕하는 내용의 정보","공포심이나 불안감을 유발하는 부호·문언·음향·화상 또는 영상을 반복적으로 상대방에게 도달하도록 하는 내용의 정보"],"a":2,"e":"정보통신망법 제44조의7 제1항 제2호의 실제 문구는 '타인의 명예를 훼손하는 내용의 정보'이며, '모욕하는'으로 바뀐 ③이 틀리다. 음란정보 배포·전시(제1호), 공포심·불안감 유발 정보의 반복 도달(제3호), 법령상 금지된 사행행위 정보(제6호)는 조문 내용과 일치한다(개정 여부 확인).","ce":["조문과 일치한다. 음란한 부호·문언·음향·화상·영상을 배포·판매·임대·공공연 전시하는 정보는 제44조의7 제1항 제1호 불법정보이다.","조문과 일치한다. 법령에 따라 금지되는 사행행위에 해당하는 내용의 정보는 불법정보로 규정된다.","실제 내용과 다르다. 조문은 비방 목적으로 사실이나 거짓 사실을 드러내어 타인의 명예를 '훼손'하는 정보이며, '모욕'이 아니다.","조문과 일치한다. 공포심·불안감을 유발하는 부호·문언·음향·화상·영상을 반복적으로 상대방에게 도달하게 하는 정보는 불법정보이다."],"rel":["5-10"]},{"n":88,"s":"s5","q":"다음 중 「개인정보 보호법」의 개인정보 보호 원칙이 아닌 것은 무엇인가?","c":["개인정보를 익명 또는 가명으로 처리하여도 개인정보 수집목적을 달성할 수 있는 경우 익명처리가 가능한 경우에는 익명에 의하여, 익명처리로 목적을 달성할 수 없는 경우에는 가명에 의하여 처리될 수 있도록 하여야 한다.","개인정보의 처리 목적에 필요한 범위에서 개인정보의 독립성, 객관성 및 공정성이 보장되도록 하여야 한다.","개인정보의 처리 목적에 필요한 범위에서 적합하게 개인정보를 처리하여야 하며, 그 목적 외의 용도로 활용하여서는 아니 된다.","개인정보 처리방침 등 개인정보의 처리에 관한 사항을 공개하여야 하며, 열람청구권 등 정보주체의 권리를 보장하여야 한다."],"a":1,"e":"개인정보 보호법 제3조 제3항은 처리 목적에 필요한 범위에서 개인정보의 '정확성, 완전성 및 최신성'이 보장되도록 하라고 규정하므로, '독립성, 객관성 및 공정성'으로 바꾼 ②가 틀리다. 익명·가명 처리 우선(제7항), 목적 외 활용 금지(제2항), 처리방침 공개·정보주체 권리 보장(제5항)은 보호 원칙에 해당한다.","ce":["보호 원칙에 해당한다. 익명처리로 목적 달성이 가능하면 익명, 불가능하면 가명으로 처리하도록 하는 제3조 원칙이다.","보호 원칙이 아니다. 제3조는 처리 목적에 필요한 범위에서 개인정보의 '정확성, 완전성 및 최신성'을 보장하도록 규정한다.","보호 원칙에 해당한다. 목적에 필요한 범위에서 적합하게 처리하고 목적 외 용도로 활용하지 말라는 제3조 원칙이다.","보호 원칙에 해당한다. 처리방침 등을 공개하고 열람청구권 등 정보주체 권리를 보장하라는 제3조 공개·권리보장 원칙이다."],"rel":["5-8"]},{"n":89,"s":"s5","q":"조직의 위험평가 수립 및 운영에 대한 사항으로 가장 적절하지 않은 것은?","c":["위험관리 계획에 따라 위험평가를 연 1회 이상 정기적으로 또는 필요한 시점에 수행하여야 한다. 매년 위험평가 대상에 변동이 없어도 위험평가는 수행되어야 한다.","위험관리를 위한 수행인력, 기간, 대상, 방법, 예산 등의 방법 및 절차를 구체화한 위험관리 계획을 수립하여야 하며, 위험평가 참여자는 위험관리를 운영하는 IT 부서 또는 정보보호 부서 인력으로 구성된다.","위험관리를 위한 위험평가 방법 선정은 베이스라인 접근법, 상세위험 분석법, 복합 접근법, 위협 및 시나리오 기반 등의 다양한 방법론 중에서 해당 조직에 맞는 방법론을 선정하고 유지하여야 한다. 선정한 방법론을 운영하는 과정에서 해당 조직에 적절하지 않다고 판단하여 위험분석 방법론을 변경하여도 상관없다.","조직에서 수용 가능한 목표 위험수준을 정하고 그 수준을 초과하는 위험을 식별하여야 한다. 수용 가능한 목표 위험수준(DoA, Degree of Assurance)을 정보보호 최고책임자 등 경영진 의사결정에 의하여 결정하여야 한다."],"a":1,"e":"위험평가는 정보보호 부서뿐 아니라 IT 부서, 현업 부서, 개인정보보호 담당 등 자산·업무를 잘 아는 관련 부서 인력이 함께 참여해야 하므로 참여자를 IT·정보보호 부서로 한정한 ②가 부적절하다. 연 1회 이상 정기 수행, 조직에 맞는 방법론 선정·변경, 경영진의 목표 위험수준(DoA) 결정은 ISMS-P 요구사항에 부합한다.","ce":["적절하다. 위험평가는 연 1회 이상 정기적으로 수행해야 하며, 대상 변동이 없어도 위협 환경 변화를 반영하기 위해 수행한다.","부적절하다. 위험평가에는 IT·정보보호 부서뿐 아니라 현업 부서, 개인정보 담당 등 자산·업무를 아는 관련 부서 인력이 함께 참여해야 한다.","적절하다. 베이스라인·상세위험·복합·시나리오 기반 등에서 조직에 맞는 방법론을 선정하고, 부적합하면 변경할 수 있다.","적절하다. 수용 가능한 목표 위험수준(DoA)을 정해 초과 위험을 식별하며, DoA는 CISO 등 경영진이 결정한다."],"rel":["5-11","5-12"]},{"n":90,"s":"s5","q":"디지털 저작권에 관련된 사항 중 적절하지 않은 것은?","c":["본인이 촬영하고 편집한 동영상은 저작물에 따로 등록하지 않아도 저작권이 적용될 수 있다.","온라인 비대면 수업과 회의 참가자의 사진을 허락없이 촬영하여 업로드한 경우 초상권 침해가 될 수 있다.","공공 데이터포털에서 공개하고 있는 데이터의 경우 저작권자는 공개한 공공기관이므로 공공데이터는 별도의 저작권자의 이용 허락 없이 활용할 수 있다.","비영리적 목적으로 사용하도록 승인한 공개 소프트웨어는 개인, 기업 모두 자유롭게 사용할 수 있다."],"a":3,"e":"비영리 목적으로만 사용을 허락한 소프트웨어는 개인의 비영리 사용만 허용되며, 영리 활동을 하는 기업은 별도 라이선스 없이 자유롭게 사용할 수 없다. 저작권은 창작과 동시에 발생(무방식주의)하므로 등록 없이도 보호되고, 공공데이터법에 따라 공공데이터는 원칙적으로 자유 이용이 가능하다.","ce":["적절하다. 저작권은 창작과 동시에 발생하는 무방식주의이므로 등록하지 않아도 직접 촬영·편집한 영상은 보호된다.","적절하다. 참가자 얼굴이 담긴 사진을 허락 없이 촬영·게시하면 초상권 침해가 될 수 있다.","적절하다. 공공데이터법상 공공데이터포털 공개 데이터는 원칙적으로 누구나 별도 허락 없이 이용할 수 있다(제3자 권리 포함 데이터는 예외).","적절하지 않다. 비영리 목적으로만 허락된 소프트웨어는 영리 활동을 하는 기업이 별도 라이선스 없이 자유롭게 쓸 수 없다."]},{"n":91,"s":"s5","q":"개인정보 보호책임자의 책임 및 역할로 가장 적절하지 않은 것은 무엇인가?","c":["개인정보 처리와 관련한 불만의 처리 및 피해 구제","개인정보 유출 및 오용·남용 방지를 위한 내부통제시스템의 구축","개인정보파일의 현행화 작성","개인정보 처리 실태 및 관행의 정기적인 조사 및 개선"],"a":2,"e":"개인정보 보호법 제31조의 보호책임자 업무는 보호계획 수립·시행, 처리 실태·관행의 정기 조사·개선, 불만 처리·피해 구제, 유출·오남용 방지 내부통제시스템 구축, 교육계획 수립·시행, 개인정보파일의 보호 및 관리·감독이다. '개인정보파일의 현행화 작성'은 법정 업무로 명시되어 있지 않다.","ce":["보호책임자 업무이다. 개인정보 처리 관련 불만 처리 및 피해 구제는 제31조에 명시된 업무이다.","보호책임자 업무이다. 유출 및 오용·남용 방지를 위한 내부통제시스템 구축은 제31조에 명시된 업무이다.","적절하지 않다. 법정 업무는 '개인정보파일의 보호 및 관리·감독'이며, '개인정보파일의 현행화 작성'은 명시되어 있지 않다.","보호책임자 업무이다. 개인정보 처리 실태 및 관행의 정기적인 조사 및 개선은 제31조에 명시된 업무이다."],"rel":["5-9"]},{"n":92,"s":"s5","q":"「정보통신망법」 제44조의9에 의거하여 일정 규모 이상의 정보통신서비스제공자가 운영 및 관리하는 정보통신망을 통하여 일반에게 공개되어 유통되는 정보의 유통을 방지하기 위한 불법촬영물 등 유통 방지 책임자를 지정하도록 되어 있는 기준에 해당되지 않는 것은 무엇인가?","c":["「영유아보육법」 제15조의4제3항에 따른 영상정보","「아동·청소년의 성보호에 관한 법률」 제2조제5호에 따른 아동·청소년성착취물","「성폭력범죄의 처벌 등에 관한 특례법」 제14조의2에 따른 편집물·합성물·가공물 또는 복제물","「성폭력범죄의 처벌 등에 관한 특례법」 제14조에 따른 촬영물 또는 복제물"],"a":0,"e":"불법촬영물 등 유통방지 책임자 제도의 대상 정보는 성폭력처벌법 제14조의 촬영물·복제물, 제14조의2의 편집물·합성물·가공물·복제물, 청소년성보호법상 아동·청소년성착취물이다. 영유아보육법에 따른 어린이집 CCTV 영상정보는 대상이 아니다(개정 여부 확인).","ce":["해당되지 않는다. 영유아보육법에 따른 어린이집 CCTV 영상정보는 불법촬영물 등 유통방지 대상 정보가 아니다(개정 여부 확인).","해당된다. 청소년성보호법 제2조제5호의 아동·청소년성착취물은 유통방지 책임자 제도의 대상 정보이다.","해당된다. 성폭력처벌법 제14조의2의 허위영상물(편집물·합성물·가공물) 및 복제물은 대상 정보이다.","해당된다. 성폭력처벌법 제14조의 불법 촬영물 또는 복제물은 대상 정보이다."],"rel":["5-10"]},{"n":93,"s":"s5","q":"「정보통신망법」 제22조의2에 의거하여 해당 서비스를 제공하기 위하여 반드시 필요한 접근권한이 아닌 경우에 고지해야 할 사항이다. 다음 중 가장 적절하지 않은 것은?","c":["접근권한이 필요한 이유","접근권한이 필요한 정보 및 기능의 항목","접근권한이 필요한 기간","접근권한 허용에 대하여 동의하지 아니할 수 있다는 사실"],"a":2,"e":"선택적 접근권한의 경우 고지 사항은 접근권한이 필요한 정보 및 기능의 항목, 접근권한이 필요한 이유, 접근권한 허용에 동의하지 않을 수 있다는 사실이다. '접근권한이 필요한 기간'은 법정 고지 사항이 아니다(개정 여부 확인).","ce":["고지 사항이다. 선택적 접근권한도 '접근권한이 필요한 이유'를 알려야 한다.","고지 사항이다. '접근권한이 필요한 정보 및 기능의 항목'을 명확히 알려야 한다.","법정 고지 사항이 아니다. 필수가 아닌 접근권한의 고지 사항은 항목·이유·동의하지 않을 수 있다는 사실이며 '필요한 기간'은 포함되지 않는다.","고지 사항이다. 필수가 아닌 접근권한은 허용에 동의하지 않을 수 있다는 사실을 함께 알려야 한다."],"rel":["5-10"],"box":"「정보통신망 이용촉진 및 정보보호등에 관한 법률」 제22조의2(접근권한에 대한 동의) ① 정보통신서비스제공자는 해당 서비스를 제공하기 위하여 이용자의 이동통신단말장치 내에 저장되어 있는 정보 및 이동통신단말장치에 설치된 기능에 대하여 접근할 수 있는 권한이 필요한 경우 이용자가 명확하게 인지할 수 있도록 알리고 이용자의 동의를 받아야 한다."},{"n":94,"s":"s5","q":"개인정보 영향평가 시 고려할 사항으로 가장 거리가 먼 것은?","c":["처리하는 개인정보의 수","개인정보의 제3자 제공 여부","정보주체의 권리를 해할 가능성 및 그 위험 정도","개인정보의 위탁 관리 여부"],"a":3,"e":"개인정보 보호법 제33조는 영향평가 시 처리하는 개인정보의 수, 개인정보의 제3자 제공 여부, 정보주체의 권리를 해할 가능성 및 그 위험 정도, 그 밖에 대통령령으로 정한 사항을 고려하도록 한다. 위탁 관리 여부는 법에 명시된 고려사항이 아니다(개정 여부 확인).","ce":["고려사항이다. 처리하는 개인정보의 수는 제33조에 명시된 영향평가 고려사항이다.","고려사항이다. 개인정보의 제3자 제공 여부는 제33조에 명시된 영향평가 고려사항이다.","고려사항이다. 정보주체의 권리를 해할 가능성 및 그 위험 정도는 제33조에 명시된 고려사항이다.","거리가 멀다. 개인정보의 위탁 관리 여부는 제33조에 명시된 영향평가 고려사항이 아니다(개정 여부 확인)."],"rel":["5-9"]},{"n":95,"s":"s5","q":"다음 중 개인정보보호법에서 정의하는 개인정보를 수집할 수 있는 경우에 해당되지 않는 것은?","c":["정보주체의 동의를 받는 경우","법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위하여 불가피한 경우","정보주체와의 계약의 체결 및 이행을 위하여 불가피하게 필요한 경우","정보주체의 정당한 이익을 달성하기 위하여 필요한 경우로서 명백하게 개인정보처리자의 권리보다 우선하는 경우"],"a":3,"e":"제15조 제1항 제6호는 '개인정보처리자'의 정당한 이익을 달성하기 위해 필요한 경우로서 명백하게 '정보주체'의 권리보다 우선하는 경우로 규정하므로, 주체를 뒤바꾼 ④가 틀리다. 동의, 법률 규정·법령상 의무, 계약 체결·이행을 위한 경우는 수집 근거에 해당한다(2023년 개정으로 일부 문구 변경, 개정 여부 확인).","ce":["수집 근거이다. 정보주체의 동의를 받은 경우는 제15조 제1항 제1호의 수집 근거이다.","수집 근거이다. 법률에 특별한 규정이 있거나 법령상 의무 준수를 위해 불가피한 경우는 제15조 제1항 제2호에 해당한다.","수집 근거이다. 정보주체와의 계약 체결·이행을 위해 필요한 경우는 제15조 제1항 제4호에 해당한다(2023년 개정으로 '불가피하게' 문구 삭제, 개정 여부 확인).","해당되지 않는다. 법은 '개인정보처리자'의 정당한 이익을 위해 필요하고 명백히 '정보주체'의 권리보다 우선하는 경우로 규정하므로 주체가 뒤바뀌었다."],"rel":["5-8"]},{"n":96,"s":"s5","q":"「개인정보 보호법」에 의해 정보주체는 자신의 개인정보처리와 관련하여 권리를 가지는데, 다음 중 정보주체의 권리로 적절하지 않은 것은 무엇인가?","c":["개인정보의 처리에 관한 동의 여부, 동의 범위 등을 선택하고 결정할 권리","개인정보의 처리 정지, 정정 삭제 및 파기를 요구할 권리","개인정보의 처리에 관한 정보를 제공할 권리","개인정보의 처리로 인하여 발생한 피해를 신속하고 공정한 절차에 따라 구제받을 권리"],"a":2,"e":"제4조의 정보주체 권리는 개인정보의 처리에 관한 정보를 '제공받을' 권리이며, '제공할' 권리가 아니다. 동의 여부·범위 선택권, 처리정지·정정·삭제·파기 요구권, 피해 구제권은 법에 명시된 권리이다.","ce":["정보주체의 권리이다. 처리에 관한 동의 여부·동의 범위 등을 선택하고 결정할 권리는 제4조에 명시되어 있다.","정보주체의 권리이다. 처리 정지, 정정·삭제 및 파기를 요구할 권리는 제4조에 명시되어 있다.","적절하지 않다. 제4조의 권리는 개인정보 처리에 관한 정보를 '제공받을' 권리이며 '제공할' 권리가 아니다.","정보주체의 권리이다. 처리로 인해 발생한 피해를 신속·공정한 절차에 따라 구제받을 권리는 제4조에 명시되어 있다."],"rel":["5-8"]},{"n":97,"s":"s5","q":"침해사고 발생 대응 방법론의 일반적인 수행과정의 순서로 올바른 것은?","c":["사고 전 준비 → 초기대응 → 사고탐지 → 대응전략 체계화 → 보고서 작성 → 사고조사","사고 전 준비 → 사고탐지 → 초기대응 → 대응전략 체계화 → 사고조사 → 보고서 작성","사고 전 준비 → 사고탐지 → 초기대응 → 사고조사 → 대응전략 체계화 → 보고서 작성","사고 전 준비 → 사고탐지 → 대응전략 체계화 → 초기대응 → 사고조사 → 보고서 작성"],"a":1,"e":"침해사고 대응 7단계는 사고 전 준비 → 사고 탐지 → 초기 대응 → 대응 전략 체계화 → 사고 조사 → 보고서 작성 → 해결이다. 탐지 전에 초기대응을 하거나, 전략 수립 전에 사고조사를 하는 순서는 틀리다.","ce":["초기대응이 사고탐지보다 앞서 있다. 사고를 탐지해야 초기대응을 할 수 있으며, 보고서 작성도 사고조사 뒤에 온다.","사고 전 준비 → 사고탐지 → 초기대응 → 대응전략 체계화 → 사고조사 → 보고서 작성 순으로 침해사고 대응 방법론과 일치한다.","사고조사가 대응전략 체계화보다 앞서 있다. 조사 방향·방법을 정하는 전략 수립 뒤에 사고조사를 수행한다.","대응전략 체계화가 초기대응보다 앞서 있다. 탐지 직후 피해 확산 방지를 위한 초기대응이 먼저이다."],"rel":["5-3","3-11"]},{"n":98,"s":"s5","q":"정보보호 최고책임자가 수행하는 정보보호 업무와 관련 없는 것은?","c":["정보보호 관리체계의 수립 및 관리·운영","개인정보보호 업무","침해사고의 예방 및 대응","중요 정보의 암호화 및 보안서버의 적합성 검토"],"a":1,"e":"정보통신망법상 정보보호 최고책임자(CISO)는 정보보호관리체계 수립·운영, 취약점 분석·평가·개선, 침해사고 예방·대응, 중요 정보 암호화·보안서버 적합성 검토 등을 수행한다. 개인정보보호 업무는 개인정보 보호법상 개인정보 보호책임자(CPO)의 업무이다(개정 여부 확인).","ce":["CISO 업무이다. 정보보호 관리체계의 수립 및 관리·운영은 정보통신망법상 CISO 업무이다(개정 여부 확인).","관련 없다. 개인정보보호 업무는 개인정보 보호법상 개인정보 보호책임자(CPO)의 업무로, CISO 정보보호 업무 목록에 포함되지 않는다.","CISO 업무이다. 침해사고의 예방 및 대응은 정보통신망법상 CISO 업무이다.","CISO 업무이다. 중요 정보의 암호화 및 보안서버의 적합성 검토는 정보통신망법상 CISO 업무이다."],"rel":["5-12"]},{"n":99,"s":"s5","q":"정보보안의 위험 관리 과정에서 조직의 보안 요구사항에 대한 효과적인 식별 및 효율적인 위험의 감소를 실현하기 위해 세부적인 위험 분석 방법들이 존재한다. <보기>에서 설명하는 (가)에 해당하는 위험 분석 방법으로 가장 옳은 것은?","c":["비정형 접근법","복합 접근법","상세위험 분석","베이스라인 접근법"],"a":3,"e":"베이스라인 접근법은 모든 시스템에 표준화된 기본 보안대책(체크리스트)을 적용하고 미적용 대책을 찾아 보완하는 방식으로, 비용·시간이 적지만 조직 특성 반영이 미흡하다. 상세위험 분석은 자산·위협·취약점을 정밀 분석하고, 비정형 접근법은 전문가 경험에 의존한다.","ce":["비정형 접근법은 정해진 구조 없이 전문가의 경험·지식에 의존해 위험을 분석하는 방법으로, 체크리스트 기반 표준 대책 적용과 다르다.","복합 접근법은 중요 시스템은 상세위험 분석, 그 외는 베이스라인 접근법을 병행하는 방식이다.","상세위험 분석은 자산 가치·위협·취약점을 정밀하게 평가해 위험을 산정하는 방식으로, 표준화된 체크리스트 적용이 아니다.","베이스라인 접근법은 모든 시스템에 표준화된 기본 보안대책을 체크리스트로 점검해 미적용 대책을 적용하는 방식이다."],"rel":["5-12"],"box":"(가)는 모든 시스템에 대하여 표준화된 보안 대책을 제시하며 체크리스트 형태로 보안 대책이 있는지 없는지를 판단하여 적용되어 있지 않은 보안대책을 적용하는 방법으로 수행하는 위험 분석 방법"},{"n":100,"s":"s5","q":"개인정보 보호법에 따르면 정보주체의 동의 외에도 당초 수집 목적과 합리적으로 관련된 범위 내에서 개인정보를 추가 활용할 수 있도록 허용하고 있다. 다음 중 그 합리성을 판단하는 기준과 거리가 먼 것은?","c":["당초 개인정보를 수집한 목적과 관련성이 있는지 여부","정보주체의 이익을 부당하게 침해하는지 여부","개인정보의 추가적인 이용 또는 제공에 대한 예측 가능성이 있는지 여부","개인정보처리자의 정당한 이익을 달성하기 위해 필요한 경우로서 명백히 정보주체 권리보다 우선하는 경우인지 여부"],"a":3,"e":"시행령 제14조의2의 추가 이용·제공 판단 기준은 당초 수집 목적과의 관련성, 수집 정황·처리 관행에 비춘 예측 가능성, 정보주체 이익의 부당한 침해 여부, 가명처리·암호화 등 안전성 확보 조치 여부이다. ④는 제15조 제1항 제6호의 수집·이용 근거로, 추가 이용 판단 기준이 아니다(개정 여부 확인).","ce":["판단 기준이다. 당초 수집 목적과의 관련성 여부는 시행령 제14조의2 추가 이용·제공 판단 기준이다(개정 여부 확인).","판단 기준이다. 정보주체의 이익을 부당하게 침해하는지 여부는 시행령 제14조의2 판단 기준이다.","판단 기준이다. 수집 정황·처리 관행에 비춘 추가 이용·제공의 예측 가능성 여부는 시행령 제14조의2 판단 기준이다.","거리가 멀다. 이는 제15조 제1항 제6호의 수집·이용 근거(처리자의 정당한 이익)로, 추가 이용·제공의 합리성 판단 기준이 아니다."],"rel":["5-8"]}]},{"id":"2020-09-05","title":"2020년 9월 5일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"리눅스 운영체제 특수 권한에 대한 설명으로 틀린 것은?","c":["SetGID가 부여된 파일은 소유 그룹의 실행 권한이 x에서 s로 변경된다.","SetUID가 부여된 파일은 소유자의 실행 권한이 x에서 s로 변경된다.","Sticky bit이 부여된 디렉터리는 기타 사용자의 실행 권한이 x에서 s로 변경된다.","Sticky bit는 /tmp와 같은 777 권한의 공용 디렉터리에서 파일 삭제 통제에 이용된다."],"a":2,"e":"Sticky bit가 설정되면 기타 사용자(other)의 실행 권한 자리가 x에서 s가 아닌 t로 표시된다(실행 권한이 없으면 T). SetUID·SetGID는 각각 소유자·그룹 실행 자리에 s로 표시되며, Sticky bit는 /tmp처럼 모두가 쓸 수 있는 디렉터리에서 소유자만 파일을 삭제하도록 통제한다.","ce":["옳은 설명이다. SetGID가 설정되면 그룹 실행 자리의 x가 s로 표시된다(그룹 실행 권한이 없으면 S).","옳은 설명이다. SetUID가 설정되면 소유자 실행 자리의 x가 s로 표시된다(소유자 실행 권한이 없으면 S).","틀린 설명이다. Sticky bit는 기타 사용자 실행 자리의 x가 s가 아니라 t로 표시된다(실행 권한이 없으면 T).","옳은 설명이다. /tmp처럼 777 권한의 공용 디렉터리에 Sticky bit를 설정하면 파일 소유자(및 root)만 해당 파일을 삭제·이름변경할 수 있다."],"rel":["1-5"]},{"n":2,"s":"s1","q":"악성코드 유형은 무엇인가?","c":["루트킷","트로이 목마","스파이웨어","파일리스"],"a":3,"e":"파일리스(Fileless) 악성코드는 디스크에 실행 파일을 남기지 않고 메모리에서 직접 실행되며, PowerShell·WMI 같은 정상 시스템 도구를 악용해 백신 탐지를 회피한다. 루트킷은 침입 흔적과 악성 프로세스를 숨기는 도구 모음이고, 트로이 목마는 정상 프로그램으로 위장한 악성코드로 보통 파일 형태로 존재한다.","ce":["루트킷은 커널·시스템 도구를 변조해 침입 흔적과 악성 프로세스를 숨기는 도구 모음으로, 디스크 비설치·PowerShell 실행이 핵심 특징이 아니다.","트로이 목마는 정상 프로그램으로 위장해 설치되는 악성코드로, 보통 실행 파일 형태로 디스크에 존재한다.","스파이웨어는 사용자 동의 없이 설치되어 개인정보·행동을 수집·전송하는 악성코드로, 메모리 전용 실행이 정의 요소가 아니다.","파일리스(Fileless) 악성코드는 디스크에 파일을 남기지 않고 메모리에서 직접 실행되며, PowerShell·WMI 등 정상 도구를 악용해 백신 탐지를 회피한다."],"rel":["1-19"],"box":"- 하드디스크 내에 악성코드 파일을 설치하지 않고, 시스템 메모리에 곧바로 로드되어 실행된다.\n- OS에 내장된 정상적인 도구 PowerShell, WMI(Windows Management Instrumentation)를 이용하여 실행되므로 백신 프로그램을 정상 실행으로 판단한다.\n- E-Mail의 첨부파일, PDF 문서, JPEG 파일 등에 삽입되어 배포된다."},{"n":3,"s":"s1","q":"최근 기관이나 단체를 사칭하는 것부터 이력서나 발주서 등을 사칭해 무의식 중에 열어보도록 하는 방법을 사용하여 이메일에 첨부파일이나 URL을 삽입한 후, 이를 클릭해 악성코드를 실행하도록 하는 등의 공격이 성행하고 있다. 이러한 공격의 차단을 목적으로 하는 가장 적합한 솔루션은?","c":["WAF(Web Application Firewall)","CDR(Content Disarm &Reconstruction)","TMS(Threat Management System)","DLP(Data Loss Prevention)"],"a":1,"e":"CDR은 첨부 문서 내 매크로·스크립트 등 잠재적 악성 요소를 제거(무해화)한 뒤 안전한 문서로 재구성해 전달하므로, 문서형 악성코드를 이용한 이메일 공격 차단에 적합하다. WAF는 웹 서버 대상 공격을 막고, DLP는 내부 정보 유출 방지 솔루션이다.","ce":["WAF(웹 방화벽)는 웹 서버로 들어오는 SQL 인젝션·XSS 등 HTTP 공격을 차단하는 장비로, 이메일 첨부 문서의 악성코드를 무해화하지 않는다.","CDR(Content Disarm & Reconstruction)은 첨부 문서의 매크로·스크립트 등 잠재적 악성 요소를 제거한 뒤 안전한 문서로 재구성해 전달하므로 문서형 이메일 공격 차단에 적합하다.","TMS(Threat Management System)는 네트워크 트래픽을 분석해 위협 상황을 관제·경보하는 시스템으로, 첨부파일 자체를 무해화하지 않는다.","DLP(Data Loss Prevention)는 내부 중요정보가 밖으로 나가는 것을 탐지·차단하는 솔루션으로, 외부에서 들어오는 악성 첨부파일 차단 목적이 아니다."],"rel":["1-11"]},{"n":4,"s":"s1","q":"문제 복원 오류로 내용이 없습니다. 정답은 임의로 1번으로 설정하였습니다.","c":["문제 복원 오류로 내용이 없습니다.","문제 복원 오류로 내용이 없습니다.","문제 복원 오류로 내용이 없습니다.","문제 복원 오류로 내용이 없습니다."],"a":0,"e":"원 문항이 복원되지 않아 문제와 보기가 존재하지 않으며, 정답은 comcbt에서 임의로 1번으로 설정한 것이다. 학습 시에는 이 문항을 건너뛰어도 무방하다.","ce":["원문 누락으로 판단 근거 없음 — 발문·보기가 복원되지 않은 문항이다. 정답은 comcbt에서 임의로 ①로 설정한 것이다.","원문 누락으로 판단 근거 없음 — 발문·보기가 복원되지 않은 문항이다.","원문 누락으로 판단 근거 없음 — 발문·보기가 복원되지 않은 문항이다.","원문 누락으로 판단 근거 없음 — 발문·보기가 복원되지 않은 문항이다."],"flag":"문제 복원 오류(발문·보기 없음) — 정답 1번은 임의 설정, 출제 제외 권장"},{"n":5,"s":"s1","q":"다음 지문이 설명하는 파일 시스템은?","c":["exFAT(Extended File Allocation Table)","ext4(extended file system)","HFS(Hierarchical File System)","ReFS(Resilient File System)"],"a":0,"e":"exFAT은 마이크로소프트가 플래시 메모리용으로 설계해 Windows CE 6.0에 처음 도입하고 Vista SP1·7·Server 2008 등에 적용한 파일 시스템으로, FAT32의 4GB 파일 크기 제한 등을 해소했다. ext4는 리눅스, HFS는 애플 macOS 계열, ReFS는 Windows Server 2012부터 도입된 파일 시스템이다.","ce":["exFAT은 마이크로소프트가 플래시 메모리용으로 설계해 Windows CE 6.0에 처음 넣고 Vista SP1·7·Server 2008에 적용했으며, FAT32의 파일 크기(4GB)·디렉터리 제약을 해소했다.","ext4는 리눅스의 저널링 파일 시스템(ext3 후속)으로, 마이크로소프트가 Windows CE용으로 만든 것이 아니다.","HFS는 애플이 Mac OS용으로 만든 계층형 파일 시스템(후속 HFS+·APFS)으로, 윈도우 계열과 무관하다.","ReFS는 Windows Server 2012부터 도입된 무결성·복원력 중심 파일 시스템으로, Windows CE 6.0·Vista·Server 2008 도입 설명과 맞지 않는다."],"rel":["1-18"],"box":"마이크로소프트사가 윈도우 CE 6.0 장치와 데스크톱 운영체제인 윈도우 비스타 및 윈도우 7 그리고 윈도우 서버 2008에 도입하기 위해 만들었다. 자료구조의 오버헤드 문제나 파일 크기/디렉터리 제약 문제에 효과적이다."},{"n":6,"s":"s1","q":"다음 중 윈도우 운영체제에서 시스템에 대한 비인가 변경을 통제하기 위한 기술에 해당하는 것은?","c":["커널 모드","윈도우 디펜더","보안 업데이트","사용자 계정 컨트롤"],"a":3,"e":"사용자 계정 컨트롤(UAC)은 관리자 권한이 필요한 시스템 변경 시 사용자에게 승인(권한 상승)을 요구해 악성코드 등에 의한 비인가 변경을 통제한다. 윈도우 디펜더는 백신(악성코드 탐지), 보안 업데이트는 취약점 패치이며, 커널 모드는 CPU 특권 실행 수준이다.","ce":["커널 모드는 CPU가 OS 커널 코드를 특권 수준(Ring 0)으로 실행하는 상태로, 사용자에게 변경 승인을 요구하는 통제 기술이 아니다.","윈도우 디펜더는 악성코드를 탐지·치료하는 백신 기능으로, 시스템 설정 변경 시 권한 상승 승인을 요구하는 기술이 아니다.","보안 업데이트는 알려진 취약점을 패치하는 조치로, 실행 중 발생하는 비인가 시스템 변경을 승인 절차로 통제하는 기능이 아니다.","사용자 계정 컨트롤(UAC)은 관리자 권한이 필요한 변경 시 사용자 승인(권한 상승)을 요구해 악성코드 등에 의한 비인가 시스템 변경을 통제한다."],"rel":["1-17"]},{"n":7,"s":"s1","q":"OTP(One-Time Password) 사용자 인증방식에 대한 설명으로 틀린 것은?","c":["OTP는 해시함수 등 암호학적 알고리즘에 의해 패스워드를 생성하기 때문에 다음 생성될 암호를 예측하는 것은 계산상 불가능하다.","OTP에 의해 생성된 패스워드는 재사용이 불가능한 특징을 보인다.","OTP 단말기와 서버는 사전에 공유한 비밀값을 암호학적 알고리즘에 적용하여 패스워드를 생성한다.","시간 동기화 방식을 사용하는 OTP 시스템에서 OTP 서버와 단말기에 적용되는 시간은 정확한 패스워드 생성을 위해 시간 오차를 전혀 허용하지 않는다."],"a":3,"e":"시간 동기화 OTP(TOTP)는 단말기와 서버 간 시계 오차를 고려해 일정 시간 창(예: 앞뒤 한두 주기)을 허용하도록 구현한다. 시간 오차를 전혀 허용하지 않으면 정상 사용자도 인증에 실패하므로 ④가 틀리다. 예측 불가능성, 재사용 불가, 사전 공유 비밀값 사용은 OTP의 특징이다.","ce":["옳은 설명이다. OTP는 해시·블록암호 등 암호 알고리즘으로 생성되므로 이전 값으로 다음 값을 예측하는 것이 계산상 불가능하다.","옳은 설명이다. 한 번 사용한 OTP는 서버가 폐기하므로 재사용(재전송 공격)이 불가능하다.","옳은 설명이다. 단말기와 서버는 사전에 공유한 비밀값(시드)에 시간·카운터 등을 적용해 같은 패스워드를 각자 생성한다.","틀린 설명이다. 시간 동기화 OTP는 단말기와 서버 간 시계 오차를 고려해 앞뒤 일정 시간 창을 허용하도록 구현한다."],"rel":["4-8"]},{"n":8,"s":"s1","q":"다음 지문에서 설명하는 파일은?","c":["mediarun.msc","activerun.inf","autorun.inf","execute.inf"],"a":2,"e":"autorun.inf는 CD/DVD·USB 루트 디렉터리에 위치해 연결 시 자동 실행할 프로그램을 지정하는 설정 파일로, USB 웜 등 악성코드 확산에 악용되어 자동 실행 기능 비활성화가 권고된다. 나머지 파일명은 윈도우 자동 실행 설정 파일이 아니다.","ce":["mediarun.msc는 윈도우 자동 실행 설정 파일이 아니다. .msc는 MMC 관리 콘솔 스냅인 파일 확장자이다.","activerun.inf는 윈도우가 인식하는 자동 실행 설정 파일명이 아니다.","autorun.inf는 CD/DVD·USB 루트에 위치해 연결 시 자동 실행할 프로그램을 지정하는 파일로, USB 웜 확산에 악용되어 자동 실행 비활성화가 권고된다.","execute.inf는 윈도우 자동 실행 기능이 참조하는 파일명이 아니다."],"rel":["1-17"],"box":"이 파일은 미디어 장치의 루트 디렉터리에 위치하며 미디어(CD/DVD, USB) 연결 시 특정 프로그램이 자동으로 실행되도록 제어한다. 해당 미디어가 악성코드에 감염되었을 때 감염 확산 또는 정보 유출 등의 피해가 발생할 수 있다."},{"n":9,"s":"s1","q":"secure.txt 파일의 소유자에게는 읽기와 실행권한을 부여하고 다른 사용자에게는 읽기 권한을 제거하는 권한 변경 명령어로 알맞은 것은?","c":["chmod 401 secure.txt","chmod o+rx, a-r secure.txt","chmod 504 secure.txt","chmod u=rx, o-r secure.txt"],"a":3,"e":"심볼릭 모드에서 u=rx는 소유자 권한을 읽기·실행으로 지정하고, o-r은 기타 사용자의 읽기 권한을 제거한다. chmod 504는 기타 사용자에게 읽기(4)를 부여해 반대이고, o+rx·a-r은 대상(u/o)이 잘못 지정되었다.","ce":["chmod 401은 소유자 r--(4), 그룹 ---(0), 기타 --x(1)로 소유자 실행 권한이 빠지고 기타 사용자에게 실행 권한을 준다.","o+rx는 소유자(u)가 아니라 기타 사용자에게 읽기·실행을 부여하고, a-r은 소유자를 포함한 모두의 읽기를 제거해 요구와 반대이다.","chmod 504는 소유자 r-x(5)는 맞지만 기타 사용자에게 r--(4) 읽기 권한을 부여하므로 '읽기 권한 제거'와 반대이다.","u=rx는 소유자 권한을 읽기·실행으로 지정하고, o-r은 기타 사용자의 읽기 권한을 제거하므로 요구사항과 일치한다."],"rel":["1-4"]},{"n":10,"s":"s1","q":"다음 중 빈칸 ㉠에 들어갈 알맞은 용어는?","c":["클라우드","저장소","젠킨스","빌드"],"a":1,"e":"KISA 등이 발표한 '온라인 소스코드 저장소(Repository) 보안 강화 권고'로, GitHub·GitLab·Bitbucket 같은 원격 저장소의 공개(public) 설정 오류로 소스코드·접속정보가 노출되는 것을 방지하기 위한 것이다. 젠킨스는 CI/CD 자동화 도구이고, 빌드는 소스를 실행 파일로 만드는 과정이다.","ce":["클라우드는 인터넷으로 컴퓨팅 자원을 제공하는 서비스 형태의 총칭으로, GitHub·GitLab·Bitbucket을 묶는 용어로는 부정확하다.","GitHub·GitLab·Bitbucket은 온라인 소스코드 저장소(Repository)로, 공개 설정 오류 시 소스코드·접속정보 노출 위험이 있어 보안 강화 권고 대상이 되었다.","젠킨스(Jenkins)는 빌드·테스트·배포를 자동화하는 CI/CD 도구로, 소스코드를 호스팅하는 서비스가 아니다.","빌드는 소스코드를 컴파일·패키징해 실행 파일을 만드는 과정으로, GitHub 등을 가리키는 용어가 아니다."],"rel":["1-19"],"box":"\"온라인 소스코드 ( ㉠ ) 보안 강화 권고\"는 IT 개발 프로젝트에서 사용되는 온라인 소스코드 ( ㉠ )에 대한 취약한 보안설정으로 인해 프로젝트가 외부에 공개되어 공격자가 소스코드를 열람하거나 정보가 탈취되어 공급망 공격 등에 활용될 수 있는 상황을 방지하기 위한 것이다. 소스코드 ( ㉠ )로는 GitHub, GitLab, Bitbucket 등이 있다."},{"n":11,"s":"s1","q":"윈도우 시스템 인증 구성요소에서 모든 계정의 로그인에 대한 검증을 하고, 비밀번호 변경을 처리하며 자원 접근 토큰을 생성하는 것은?","c":["LSA(Local Security Authority)","SAM(Security Account Manager)","SRM(Security Reference Monitor)","NTLM(NT LAN Manager)"],"a":0,"e":"LSA는 로컬·원격 로그인 검증, 보안 정책 관리, 비밀번호 변경 처리, 접근 토큰 생성, 감사 로그 기록을 담당하는 윈도우 인증의 핵심 구성요소이다. SAM은 계정·패스워드 해시 데이터베이스를 관리하고, SRM은 접근 토큰을 바탕으로 객체 접근 권한을 검사하며 SID 기반 접근 제어를 수행한다.","ce":["LSA(Local Security Authority)는 모든 계정의 로그인 검증, 비밀번호 변경 처리, 접근 토큰 생성, 보안 정책·감사를 담당한다.","SAM(Security Account Manager)은 계정과 패스워드 해시를 저장·관리하는 데이터베이스로, LSA의 요청에 따라 인증 정보를 대조할 뿐 토큰을 생성하지 않는다.","SRM(Security Reference Monitor)은 LSA가 만든 접근 토큰(SID)을 바탕으로 객체 접근 권한을 검사하고 감사 메시지를 생성한다.","NTLM(NT LAN Manager)은 챌린지-응답 방식의 윈도우 인증 프로토콜로, 인증 구성요소 자체가 아니다."],"rel":["1-2"]},{"n":12,"s":"s1","q":"도메인 계정에 대한 로그인 성공, 실패 관련 이벤트 로그를 기록하기 위해 보안설정이 필요한 감사 항목은?","c":["계정 관리 감사","계정 로그인 이벤트 감사","개체 액세스 감사","시스템 이벤트 감사"],"a":1,"e":"계정 로그온(로그인) 이벤트 감사는 도메인 컨트롤러에서 도메인 계정 자격 증명 검증(로그인 성공·실패)을 기록한다. '로그온 이벤트 감사'는 로컬 컴퓨터에서의 로그온·로그오프를, 계정 관리 감사는 계정 생성·변경·삭제를, 개체 액세스 감사는 파일·레지스트리 접근을 기록한다.","ce":["계정 관리 감사는 사용자 계정·그룹의 생성·변경·삭제, 비밀번호 설정 등을 기록하며 로그인 성공·실패를 기록하지 않는다.","계정 로그인(로그온) 이벤트 감사는 도메인 컨트롤러가 도메인 계정 자격 증명을 검증할 때의 성공·실패를 기록한다.","개체 액세스 감사는 SACL이 설정된 파일·폴더·레지스트리 등 개체 접근을 기록한다.","시스템 이벤트 감사는 시스템 시작·종료, 보안 로그 삭제 등 시스템 보안에 영향을 주는 이벤트를 기록한다."],"rel":["1-17"]},{"n":13,"s":"s1","q":"레지스트리에 대한 설명으로 틀린 것은?","c":["시스템 구성정보를 저장하는 데이터베이스로 저장되는 위치는 윈도우 운영체제 버전에 따라 다르다.","레지스트리의 편집을 위해 사용되는 도구는 regedit.exe이다.","레지스트리 키는 HKEY_CLASSES_ROOT, HKEY_USERS, HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE, HKEY_CURRENT_CONFIG 등을 포함한다.","레지스트리 백업 및 복구는 shell.exe를 구동하여 수행한다."],"a":3,"e":"레지스트리 백업·복구는 regedit.exe의 내보내기/가져오기, reg.exe(reg save/restore), 시스템 복원 등으로 수행하며 shell.exe라는 도구는 이 용도가 아니다. 레지스트리는 시스템 구성 정보 데이터베이스이고 5개 루트 키(HKCR·HKU·HKCU·HKLM·HKCC)를 가진다.","ce":["옳은 설명이다. 레지스트리는 하드웨어·소프트웨어·사용자 설정을 담은 계층형 DB이며, 하이브 파일 위치는 OS 버전에 따라 다르다.","옳은 설명이다. 레지스트리 편집은 regedit.exe(레지스트리 편집기)로 한다.","옳은 설명이다. 루트 키는 HKCR·HKU·HKCU·HKLM·HKCC 5개로 구성된다.","틀린 설명이다. 백업·복구는 regedit의 내보내기/가져오기, reg save/restore, 시스템 복원 등으로 하며 shell.exe는 이 용도의 도구가 아니다."],"rel":["1-3"]},{"n":14,"s":"s1","q":"㉠, ㉡, ㉢에 들어갈 내용이 올바르게 짝지어진 것은?","c":["㉠ 패스워드 무차별 대입 ㉡ disable ㉢ 10","㉠ 패스워드 무차별 대입 ㉡ deny ㉢ 600","㉠ 부채널 ㉡ disable ㉢ 10","㉠ 부채널 ㉡ deny ㉢ 600"],"a":1,"e":"계정 잠금 임계값은 패스워드 무차별 대입(Brute Force) 공격 대응책이다. pam_tally2.so에서 실패 허용 횟수는 deny 옵션으로, 잠금 해제 시간은 unlock_time(초 단위)으로 지정하므로 10분은 600이다.","ce":["㉠ 무차별 대입은 맞지만, pam_tally2의 실패 허용 횟수 옵션은 disable이 아니라 deny이고 unlock_time은 초 단위라 10분은 600이다.","계정 잠금은 무차별 대입 대응책이며, pam_tally2.so의 실패 허용 횟수는 deny=3, 잠금 해제 시간은 unlock_time=600(초, 10분)이다.","부채널 공격은 전력·시간·전자파 등 물리적 누출 정보로 키를 추정하는 공격으로 계정 잠금으로 막을 수 없고, 옵션명·시간 단위도 틀리다.","옵션 deny·600은 맞지만 ㉠ 부채널 공격은 계정 잠금 정책과 무관하다. 로그인 실패 횟수 제한은 패스워드 무차별 대입 대응책이다."],"rel":["1-16"],"box":"리눅스 서버 관리자 A는 ( ㉠ ) 공격에 대응하기 위해 PAM 모듈을 활용하고자 한다.\n(계정보안 정책은 패스워드 3회 입력 실패 시, 10분간 계정을 잠금)\nauth required pam_tally2.so ( ㉡ )=3 unlock_time=( ㉢ )"},{"n":15,"s":"s1","q":"쿠키(Cookie)에 대한 설명 중 옳지 않은 것은?","c":["웹사이트에 마지막으로 방문한 시간, 페이지 등 다양한 정보를 기록할 수 있다.","웹서버가 웹브라우저에게 보내어 저장했다가 서버의 부가적인 요청이 있을 때 다시 서버로 보내준다.","일정한 기간 동안만 유효하게 할 수 있고, 유효(만료) 기한이 설정되지 않을 경우 웹브라우저 종료 시에 자동 삭제된다.","웹서버에 저장된 쿠키값은 개인정보보호를 위해 정기적으로 삭제해야 한다."],"a":3,"e":"쿠키는 서버가 아니라 클라이언트(웹브라우저) 측에 저장되는 정보이므로 '웹서버에 저장된 쿠키값'이라는 설명이 틀리다. 서버 측에 저장되는 상태 정보는 세션이다. 만료 기한이 없는 쿠키는 세션 쿠키로 브라우저 종료 시 삭제된다.","ce":["옳은 설명이다. 쿠키에는 마지막 방문 시간, 방문 페이지, 로그인 상태, 장바구니 등 다양한 정보를 기록할 수 있다.","옳은 설명이다. 서버가 Set-Cookie로 브라우저에 저장시키고, 이후 요청 때 브라우저가 Cookie 헤더로 다시 보낸다.","옳은 설명이다. Expires·Max-Age로 유효기간을 정할 수 있으며, 설정하지 않으면 세션 쿠키로 브라우저 종료 시 삭제된다.","옳지 않다. 쿠키는 웹서버가 아니라 클라이언트(웹브라우저)에 저장된다. 서버 측에 저장되는 상태 정보는 세션이다."],"rel":["3-3"]},{"n":16,"s":"s1","q":"다음 중 AD(Active Directory) 시스템을 안전하게 관리하기 위한 방안을 잘못 설명한 것은?","c":["전용 계정을 별도로 관리하여 일반 업무용 AD 계정과는 분리하여 사용한다.","관리자 계정은 특수성이 있으므로 비밀번호 갱신주기에 대해서는 예외적용을 하도록 한다.","비밀번호 갱신 정책에는 최근에 사용한 비밀번호들을 재사용하지 못하게 하는 제약조건도 고려되어야 한다.","관리자용 단말은 인터넷과 격리된 망분리 환경으로 구성되어야 한다."],"a":1,"e":"관리자 계정은 탈취 시 도메인 전체가 장악되므로 오히려 더 엄격한 비밀번호 복잡도·갱신 주기를 적용해야 하며, 예외를 두는 것은 잘못이다. 관리 전용 계정 분리, 비밀번호 재사용 금지, 관리자 단말의 망분리는 AD 보안 권고 사항이다.","ce":["올바른 방안이다. AD 관리 전용 계정을 일반 업무용 계정과 분리하면 일상 업무 중 계정 탈취 시 관리자 권한 노출을 막을 수 있다.","잘못된 방안이다. 관리자 계정은 탈취 시 도메인 전체가 장악되므로 오히려 더 엄격한 비밀번호 복잡도·갱신 주기를 적용해야 한다.","올바른 방안이다. 최근 사용한 비밀번호 재사용 금지(암호 기록 적용)는 비밀번호 갱신 정책의 필수 요소이다.","올바른 방안이다. 관리자용 단말은 인터넷과 분리해 악성코드 유입·자격증명 탈취 경로를 차단해야 한다."],"rel":["1-17"]},{"n":17,"s":"s1","q":"스택에서 특정 코드 실행을 막기 위해 수정해야 하는 파일은?","c":["/etc/system","/etc/getty","/etc/fsck","/etc/conf"],"a":0,"e":"솔라리스(Solaris)에서는 /etc/system 파일에 set noexec_user_stack=1(및 noexec_user_stack_log=1)을 설정해 스택 영역의 코드 실행을 금지함으로써 스택 버퍼 오버플로 공격을 완화한다. getty는 터미널 로그인 프로그램, fsck는 파일 시스템 점검 도구이다.","ce":["솔라리스 /etc/system 파일에 set noexec_user_stack=1을 설정하면 스택 영역 코드 실행이 금지되어 스택 버퍼 오버플로를 완화한다.","/etc/getty는 터미널 포트를 열어 로그인 프롬프트를 제공하는 프로그램과 관련된 것으로, 스택 실행 제어 설정 파일이 아니다.","fsck는 파일 시스템 무결성을 점검·복구하는 도구로, 스택 실행 권한과 무관하다.","/etc/conf는 스택 실행 방지 설정을 담는 표준 시스템 파일이 아니다. 해당 설정은 /etc/system에 한다."],"rel":["1-10"]},{"n":18,"s":"s1","q":"시스템 오류를 공격하는 Heap Overflow 공격의 특징 및 원리에 대한 설명으로 틀린 것은?","c":["프로그램이 실행되면서 메모리를 동적으로 할당하는 영역을 이용한다.","프로그래머가 malloc과 같은 메모리 할당 함수를 이용한다.","힙 영역을 오버플로우 시켜서 특정 코드를 실행하여 공격하는 기술이다.","버스를 통해 전달되는 중요 정보를 엿보고 가로채는 공격 기술이다."],"a":3,"e":"힙 오버플로는 malloc 등으로 동적 할당되는 힙 영역의 경계를 넘겨 써서 인접 데이터·함수 포인터를 덮어쓰고 공격 코드를 실행하는 기법이다. 버스를 통해 전달되는 정보를 엿보는 것은 스니핑(또는 하드웨어 버스 스누핑)에 해당하므로 ④가 틀리다.","ce":["옳은 설명이다. 힙은 실행 중 동적으로 메모리를 할당하는 영역이며, 힙 오버플로는 이 영역을 대상으로 한다.","옳은 설명이다. 힙 메모리는 malloc·calloc·new 등 동적 할당 함수로 확보된다.","옳은 설명이다. 할당된 힙 버퍼 경계를 넘겨 써서 인접 데이터·함수 포인터를 덮어쓰고 공격 코드를 실행한다.","틀린 설명이다. 버스로 전달되는 정보를 엿보고 가로채는 것은 스니핑(버스 스누핑)이며, 힙 오버플로의 원리가 아니다."],"rel":["1-10"]},{"n":19,"s":"s1","q":"다음 지문의 설정사항이 의미하는 것은?","c":["root 계정의 패스워드 임계치를 설정하고 있다.","모든 계정에 대한 패스워드 임계치를 설정하고 있다.","모든 계정에 대한 암호화 접속을 활성화하기 위한 설정이다.","root 계정의 원격접속을 제한하는 설정이다."],"a":3,"e":"/etc/securetty는 root가 로그인할 수 있는 터미널 목록으로, pts(원격 가상 터미널) 항목을 제거하면 root의 telnet 등 원격 직접 접속이 차단되고, HP-UX에서는 console만 남겨 콘솔에서만 root 로그인을 허용한다. 패스워드 임계치는 PAM(pam_tally 등) 설정 사항이다.","ce":["root 패스워드 임계치(실패 횟수 제한)는 PAM(pam_tally2 등) 설정 사항이며, /etc/securetty는 root 로그인 가능 터미널 목록이다.","모든 계정의 패스워드 임계치 역시 PAM 설정 사항이며, securetty는 root 계정에만 적용된다.","암호화 접속 활성화는 SSH 사용·telnet 비활성화 등으로 구현하며, securetty는 암호화와 무관하다.","/etc/securetty에서 pts(원격 가상 터미널)를 제거하거나 console만 허용하면 root의 telnet 등 원격 직접 접속이 제한된다."],"rel":["1-16"],"box":"[Linux 환경]\n\"/etc/securetty\" 파일에서 pts/0 ~ pts/x 설정 제거 또는 주석 처리\n\n[HP-UX 환경]\nvi 편집기를 이용하여 \"/etc/securetty\" 파일을 연 후 아래와 같이 주석 제거 또는 신규 삽입\n(수정 전) #console\n(수정 후) console"},{"n":20,"s":"s1","q":"윈도우 시스템에 포함된 원격 접속 프로그램인 터미널 서비스 기능을 이용할 때 사용되는 명령어는?","c":["vnc","mstsc","teamviewer","realvnc"],"a":1,"e":"mstsc(Microsoft Terminal Services Client)는 윈도우에 기본 포함된 원격 데스크톱 연결(RDP, 기본 3389/TCP) 클라이언트 실행 명령이다. VNC·RealVNC·TeamViewer는 별도로 설치하는 서드파티 원격 제어 프로그램이다.","ce":["vnc는 RFB 프로토콜 기반의 서드파티 원격 제어 프로그램 계열로, 윈도우 기본 터미널 서비스 명령이 아니다.","mstsc(Microsoft Terminal Services Client)는 윈도우에 기본 포함된 원격 데스크톱 연결(RDP, 기본 3389/TCP) 클라이언트 실행 명령이다.","TeamViewer는 별도 설치하는 상용 원격 지원 프로그램으로, 윈도우 내장 터미널 서비스가 아니다.","RealVNC는 VNC 계열의 서드파티 원격 제어 제품으로, 윈도우 내장 기능이 아니다."],"rel":["1-17"]},{"n":21,"s":"s2","q":"가상사설망(VPN)의 터널링에 사용되는 프로토콜이 아닌 것은?","c":["PPTP","L2F","RSVP","IPSec"],"a":2,"e":"RSVP(Resource Reservation Protocol)는 QoS 보장을 위해 네트워크 자원(대역폭)을 예약하는 신호 프로토콜로 터널링과 무관하다. PPTP·L2F·L2TP는 2계층, IPSec은 3계층 VPN 터널링 프로토콜이다.","ce":["PPTP(Point-to-Point Tunneling Protocol)는 마이크로소프트가 주도한 2계층 VPN 터널링 프로토콜이다.","L2F(Layer 2 Forwarding)는 시스코가 개발한 2계층 터널링 프로토콜로, PPTP와 결합해 L2TP로 발전했다.","RSVP(Resource Reservation Protocol)는 QoS 보장을 위해 경로상 대역폭 등 자원을 예약하는 신호 프로토콜로, 터널링과 무관하다.","IPSec은 3계층에서 AH·ESP로 IP 패킷을 인증·암호화하는 대표적 VPN 터널링 프로토콜이다."],"rel":["2-7"]},{"n":22,"s":"s2","q":"아래 지문에서 강조(밑줄)된 프로토콜의 기능과 가장 거리가 먼 것은?","c":["네트워크 장치의 동적 상황 검사","Routing Table 변경 요청","IP 통신을 위한 진단 데이터 전송","Multi-casting 제어"],"a":3,"e":"밑줄 친 ICMP는 IP 통신의 오류 보고·진단(Echo, Destination Unreachable 등), 라우팅 경로 변경 요청(Redirect), 네트워크 상태 점검 기능을 제공한다. 멀티캐스트 그룹 가입·탈퇴 제어는 IGMP의 기능이다.","ce":["ICMP의 기능이다. Echo Request/Reply 등으로 네트워크 장치의 도달성·상태를 동적으로 점검한다.","ICMP의 기능이다. ICMP Redirect 메시지로 더 나은 경로를 알려 호스트의 라우팅 테이블 변경을 요청한다(DoubleDirect 공격이 악용).","ICMP의 기능이다. Destination Unreachable·Time Exceeded 등 IP 통신 오류 보고·진단 데이터를 전송한다.","거리가 멀다. 멀티캐스트 그룹 가입·탈퇴 제어는 IGMP(Internet Group Management Protocol)의 기능이다."],"rel":["2-12"],"box":"- 'DoubleDirect'라고 명명된 공격기법은 iOS, MAC OS X, Android에 이르기까지 상용화 되었던 대부분의 모바일 운영체제를 대상으로 하는 중간자 공격(Man-in-the-Middle attack) 기술이었다. 무선 네트워크 공격에 널리 사용되는 ICMP 프로토콜을 이용했다.\n- 공격대상의 DNS 트래픽을 스니핑(Sniffing)하며 IP 주소를 예측하고, 해당 IP를 대상으로 ICMP Redirect 패킷을 이용해 공격대상 기기의 라우팅 테이블을 변경하고 트래픽을 우회시킨다."},{"n":23,"s":"s2","q":"다음 보기 중 빅데이터의 방대한 정보 속에서 단순한 로그 수집 및 분석이 아닌 사후에 추적 등이 가능하도록 상관분석과 포렌식 기능을 제공해주는 지능적 위협에 대한 조기 경고 모니터링 체계를 의미하는 것은?","c":["IPS","TMS","UTM","SIEM"],"a":3,"e":"SIEM(Security Information and Event Management)은 이기종 보안장비·시스템 로그를 빅데이터 기반으로 수집·상관분석하고 포렌식·사후 추적을 지원해 지능형 위협을 조기 경고한다. ESM이 단순 로그 통합 관리였다면 SIEM은 이를 확장한 개념이며, TMS는 네트워크 위협 관리, UTM은 통합 보안 장비이다.","ce":["IPS(침입방지시스템)는 네트워크 트래픽을 실시간 검사해 공격을 차단하는 장비로, 이기종 로그의 빅데이터 상관분석·포렌식 체계가 아니다.","TMS(위협관리시스템)는 네트워크 트래픽 기반으로 위협 상황을 관제·경보하는 시스템으로, 로그 상관분석·사후 추적 중심의 SIEM과 다르다.","UTM(통합위협관리)은 방화벽·IPS·백신·VPN 등을 한 장비에 통합한 제품으로, 로그 빅데이터 분석 체계가 아니다.","SIEM은 이기종 장비·시스템 로그를 빅데이터 기반으로 수집·상관분석하고 포렌식·사후 추적을 지원해 지능형 위협을 조기 경고한다."],"rel":["2-10","1-11"]},{"n":24,"s":"s2","q":"다음 지문은 네트워크 공격기술에 대한 설명이다. 적절하지 못한 것으로 짝지어진 것은?","c":["㉠, ㉡","㉠, ㉢","㉡, ㉣","㉢, ㉣"],"a":3,"e":"㉢은 ICMP 패킷을 증폭 네트워크(브로드캐스트)로 보내는 스머프(Smurf) 공격 설명이고, ㉣은 동시 접속 수 제한을 소모시키는 SYN 플러딩 설명이므로 두 공격의 설명이 서로 뒤바뀌었다. Boink는 IP 단편 재조합 오류를 악용하고, LAND는 출발지·목적지 IP를 동일하게 만든 공격으로 ㉠·㉡은 옳다.","ce":["㉠ Boink(IP 단편 재조합 오류 악용)와 ㉡ LAND(출발지=목적지 IP)는 모두 올바른 설명이다.","㉠은 올바르다. ㉢은 틀린 설명이 맞지만 ㉣도 틀린 설명이므로 짝이 맞지 않는다.","㉡ LAND 공격 설명은 올바르다. 틀린 것은 ㉢과 ㉣이다.","㉢은 ICMP 증폭을 이용하는 스머프 공격 설명이고, ㉣은 동시 접속 수 제한을 소모시키는 SYN 플러딩 설명이어서 두 설명이 서로 뒤바뀌었다."],"rel":["2-3","2-12"],"box":"㉠ Boink 공격은 불완전한 IP 단편 처리 로직을 악용하여 시스템 장애를 발생시킨다.\n㉡ 랜드(LAND) 공격은 패킷을 전송할 때 출발지 IP 주소와 목적지 IP 주소를 똑같이 만들어 공격 대상에게 보내는 방식이다.\n㉢ SYN 플러딩(flooding) 공격은 ICMP 패킷과 네트워크에 존재하는 임의의 시스템을 이용하여 패킷을 증폭함으로써 서비스 거부 공격을 수행한다.\n㉣ 스머프(Smurf) 공격은 동시 사용자 수 제한을 이용하는 것으로, 존재하지 않는 클라이언트가 서버별로 한정된 접속 가능 공간에 접속한 것처럼 속여 다른 사용자가 서비스를 제공 받지 못하도록 하는 공격이다."},{"n":25,"s":"s2","q":"다음 지문은 라우팅에 관한 설명이다. 빈칸에 들어갈 내용을 순서대로 나열한 것은?","c":["(가) 라우터 (나) 라우팅 테이블 (다) Static Route","(가) 라우터 (나) 라우팅 테이블 (다) Default route","(가) 스위치 (나) 목적지 테이블 (다) Static Route","(가) 스위치 (나) 목적지 테이블 (다) Default Route"],"a":1,"e":"라우터는 라우팅 테이블에서 목적지 IP와 일치하는 경로를 찾아 패킷을 전달하고, 일치하는 항목이 없는 목적지는 기본 경로(Default Route, 0.0.0.0/0)로 전송한다. Static Route는 관리자가 특정 목적지에 대해 수동 지정한 경로로, '등록되지 않은 목적지'에 적용되는 것이 아니다.","ce":["라우터·라우팅 테이블은 맞지만, 테이블에 없는 목적지 전송에 쓰이는 것은 Static Route가 아니라 Default Route이다. Static Route는 특정 목적지를 수동 지정한 경로이다.","라우터가 라우팅 테이블에서 목적지 IP와 일치하는 경로를 찾고, 일치 항목이 없으면 Default Route(0.0.0.0/0)로 전송한다.","스위치는 MAC 주소 테이블로 2계층 프레임을 전달하며 IP 기반 경로 결정을 하지 않고, (다)도 Default Route여야 한다.","(다) Default Route는 맞지만 IP 기반 경로 결정 주체는 스위치가 아니라 라우터이고, 참조 테이블은 라우팅 테이블이다."],"rel":["2-12"],"box":"(가)는 입력된 패킷의 목적지 IP를 바탕으로 (나)에 등록된 서브넷 정보와 일치하는 레코드의 인터페이스 정보와 게이트웨이 정보를 확인하며 패킷을 (나)에 전달한다. (가)에서 패킷을 수신하면 (나)상의 상대방 네트워크 IP 주소를 검색하며 패킷을 어디로 보낼 것인가를 결정하는데 라우터에 (다)가 설정되어 있으면 (나)상에서 등록되어 있지 않은 목적지 IP 주소들에 대해서는 설정된 경로로 전송하게 된다."},{"n":26,"s":"s2","q":"스위칭 환경에서 시도할 수 있는 스니핑 공격 유형과 거리가 먼 것은?","c":["SYN Flooding","Switch jamming","ICMP Redirect","ARP Spoofing"],"a":0,"e":"SYN Flooding은 반개방 연결로 서버 자원을 고갈시키는 서비스 거부 공격으로 스니핑 기법이 아니다. 스위치 환경에서는 MAC 테이블을 넘치게 하는 Switch Jamming(MAC Flooding), ARP Spoofing, ICMP Redirect 등으로 트래픽을 공격자에게 유도해 스니핑한다.","ce":["SYN Flooding은 반개방 연결로 서버 연결 큐를 고갈시키는 서비스 거부 공격으로, 트래픽을 공격자에게 유도해 엿보는 스니핑 기법이 아니다.","Switch Jamming(MAC Flooding)은 위조 MAC으로 스위치 MAC 테이블을 가득 채워 허브처럼 모든 포트로 브로드캐스트하게 만드는 스위치 환경 스니핑 기법이다.","ICMP Redirect는 위조 Redirect 메시지로 대상 호스트의 경로를 공격자 쪽으로 바꿔 트래픽을 가로채는 스위치 환경 스니핑 기법이다.","ARP Spoofing은 위조 ARP Reply로 게이트웨이 등의 MAC을 공격자 MAC으로 바꿔 트래픽을 경유시키는 대표적 스위치 환경 스니핑 기법이다."],"rel":["2-5"]},{"n":27,"s":"s2","q":"지문에서 설명한 공격의 대응 방안으로 옳지 않은 것은?","c":["위조된 패킷이 인터넷망으로 인입되지 않도록 ISP의 네트워크 단에서 직접 차단한다.","사전 공격에 악용될 소지가 있는 취약한 DNS 서버 등에 대해 보완 조치한다.","악의적으로 이용되지 않기 위해 ICMP 프로토콜을 사용할 필요가 없는 시스템인 경우에는 스위치 또는 서버에서 해당 프로토콜을 차단한다.","외부 인터넷 서버의 접속이 잦을 경우 클라이언트의 보호를 위해 HTTP 프로토콜을 차단한다."],"a":3,"e":"지문은 정상 서버를 반사체(Reflector)로 악용하는 DRDoS 공격이다. ISP 단의 출발지 위조 패킷 차단(Ingress 필터링), 반사체로 쓰일 수 있는 DNS 등 서버 보완, 불필요한 ICMP 차단은 올바른 대응이나, 정상 서비스인 HTTP 자체를 차단하는 것은 대응 방안으로 부적절하다.","ce":["옳은 대응이다. DRDoS는 출발지 IP를 피해자로 위조하므로, ISP 단에서 위조 패킷 유입을 차단(Ingress 필터링)하면 반사 공격을 줄일 수 있다.","옳은 대응이다. 오픈 리졸버 DNS 등 반사체(Reflector)로 악용될 수 있는 서버를 보완하면 증폭·반사 공격을 막을 수 있다.","옳은 대응이다. ICMP가 필요 없는 시스템에서 ICMP를 차단하면 ICMP 기반 반사 공격에 악용되는 것을 막을 수 있다.","옳지 않다. 정상 서비스 프로토콜인 HTTP 자체를 차단하는 것은 서비스 가용성을 해칠 뿐 DRDoS 반사 공격 대응이 되지 않는다."],"rel":["2-3"],"box":"DDoS 공격의 에이전트 설치상의 어려움을 보완한 공격 기법으로 TCP 프로토콜 및 라우팅 테이블 운영상의 취약성을 이용하며, 정상적인 서비스를 제공 중인 서버를 Agent로 활용하는 공격기법이다."},{"n":28,"s":"s2","q":"다음 지문에서 설명하는 것은?","c":["페트야 공격(Patya Attack)","이터널블루 공격(EternalBlue Attack)","공급망 공격(Supply Chain Attack)","갠드크랩 공격(GandCrab Attack)"],"a":1,"e":"이터널블루(EternalBlue)는 NSA가 개발한 것으로 알려진 윈도우 SMBv1 원격 코드 실행 취약점(MS17-010) 익스플로잇으로, 2017년 섀도 브로커스가 유출했고 워너크라이 등 랜섬웨어에 악용되었다. 페트야·갠드크랩은 랜섬웨어 이름이며, 공급망 공격은 SW 배포 경로를 오염시키는 공격이다.","ce":["페트야(Petya)는 MBR·MFT를 암호화하는 랜섬웨어 이름으로(변종 NotPetya가 이터널블루 활용), NSA가 개발한 SMB 익스플로잇 자체가 아니다.","이터널블루(EternalBlue)는 NSA가 개발한 것으로 알려진 SMBv1 원격 코드 실행 취약점(MS17-010) 익스플로잇으로, 2017년 섀도 브로커스가 공개했다.","공급망 공격은 소프트웨어 개발·배포·업데이트 경로를 오염시켜 다수를 감염시키는 공격 유형으로, SMB 구현 취약점을 직접 공격하는 도구가 아니다.","갠드크랩(GandCrab)은 2018년 등장한 서비스형 랜섬웨어(RaaS)로, NSA 유출 SMB 익스플로잇이 아니다."],"rel":["1-19"],"box":"윈도우의 소프트웨어 취약점을 악용하는 것으로 NSA가 개발한 것으로 추정되는 공격도구로서 섀도 브로커스에 의해 2017년도에 공개되었다. 이는 미국 볼티모어시 정부에 대한 랜섬웨어 공격에서 다시금 부상하게 되었다. 문제는 많은 컴퓨터가 구식의 윈도우 운영체제를 계속 사용하고 있다는 것이다. 마이크로소프트의 SMB 구현의 취약점을 공격한다."},{"n":29,"s":"s2","q":"다음 괄호 안에 들어갈 수 있는 적절한 용어는?","c":["Blackhole 필터링","Unicast RPF를 이용한 필터링","Ingress filtering","Multicast RPF를 이용한 필터링"],"a":0,"e":"Blackhole(Null Routing) 필터링은 특정 목적지 IP·대역으로 가는 패킷을 Null0 가상 인터페이스로 라우팅해 폐기하는 방식으로, access-list보다 라우터 부하가 적고 적용이 간편하다. Unicast RPF는 수신 인터페이스와 출발지 IP의 역경로를 검사해 위조 패킷을 차단하는 기법이다.","ce":["Blackhole(Null Routing) 필터링은 특정 IP·대역을 Null0 가상 인터페이스로 라우팅해 폐기하는 방식으로, 라우팅 명령만으로 간편하게 차단할 수 있다.","Unicast RPF는 수신 인터페이스와 출발지 IP의 역경로가 일치하는지 검사해 위조 출발지 패킷을 차단하는 기법으로, Null 인터페이스 라우팅 방식이 아니다.","Ingress filtering은 외부에서 들어오는 패킷 중 내부 대역 등 비정상 출발지 IP를 access-list로 차단하는 기법이다.","Multicast RPF는 멀티캐스트 트래픽이 소스로의 역경로 인터페이스로 들어왔는지 검사해 루프를 막는 멀티캐스트 라우팅 메커니즘이다."],"rel":["2-12"],"box":"라우터를 활용하여 네트워크 보안을 강화하기 위한 방법으로 access-list와 함께 유용하게 사용할 수 있는 기법으로는 (  )이 있다. 이는 access-list와 비슷한 효과를 내면서도 더욱 간편하게 사용할 수 있는데, 다음과 같은 경우를 생각해보자. 만약 시스템이나 네트워크를 모니터링 하던 중 특정 ip 또는 특정 대역에서 비정상적인 시도가 감지되었을 경우, 해당 ip를 차단하기 위해 매번 기존 access-list를 지우고 새롭게 ip를 추가하여 작성하는 것은 여간 번거로운 일이 아닐 수 없다. 이 필터링은 이때 사용될 수 있는데 명령어 자체는 특정한 목적지 ip 또는 ip 대역에 대하여 라우팅 테이블을 생성하는 방식과 동일하다. 다만 특정한 ip 또는 ip 대역에 대해 Null이라는 가상의 쓰레기 인터페이스로 보냄으로써 패킷의 통신이 되지 않도록 하는 것이다."},{"n":30,"s":"s2","q":"다음 지문에서 설명하는 용어는?","c":["멀버타이징(Malvertising)","익스플로잇(Exploit)","사이버 킬 체인(Cyber Kill Chain)","사이버 위협 인텔리전스(CTI)"],"a":2,"e":"사이버 킬 체인은 록히드 마틴이 제시한 모델로, 공격을 정찰→무기화→전달→익스플로잇→설치→명령·제어→목적 달성 단계로 분석해 각 단계에서 공격을 끊어 대응하는 전략이다. CTI는 위협 정보를 수집·분석해 공유하는 활동이고, 멀버타이징은 광고를 통한 악성코드 유포이다.","ce":["멀버타이징은 온라인 광고 네트워크에 악성코드를 심어 광고 노출·클릭으로 유포하는 공격 기법으로, 공격 단계 분석 전략이 아니다.","익스플로잇은 취약점을 실제로 악용하는 코드·기법으로, 킬 체인의 한 단계에 해당할 뿐 전체 대응 전략이 아니다.","사이버 킬 체인은 공격을 정찰→무기화→전달→익스플로잇→설치→명령·제어→목적 달성 단계로 분석해 각 단계에서 공격을 끊는 대응 전략이다.","CTI(사이버 위협 인텔리전스)는 위협 행위자·IoC·TTP 정보를 수집·분석·공유하는 활동으로, 공격 단계별 분쇄 전략 모델 자체와는 다르다."],"rel":["1-19","3-11"],"box":"이것은 사이버 공격을 프로세스 상으로 분석해 각 공격 단계에서 조직에 가해지는 위협 요소들을 파악하고 공격자의 목적과 의도, 활동을 분쇄 완화해 조직의 회복 탄력성을 확보하는 전략이다. 한 마디로 공격자의 관점에서 사이버 공격 활동을 파악, 분석해 공격 단계별로 조직에 가해지는 위협 요소를 제거하거나 완화하자는 것이다."},{"n":31,"s":"s2","q":"다음 지문에서 설명하는 용어는?","c":["HA(High Availability)","Null Routing","Cut-Through","Load Balancing"],"a":1,"e":"Null Routing으로 패킷을 Null 인터페이스로 폐기할 때 라우터가 출발지로 ICMP Unreachable 메시지를 보내면 대량 공격 시 부하가 커지므로 'no ip unreachables'를 설정하는 것이 권장된다. Cut-Through는 스위치의 프레임 전달 방식, Load Balancing은 부하 분산 기술이다.","ce":["HA(High Availability)는 이중화·장애 조치로 서비스 연속성을 보장하는 구성으로, 필터링 시 ICMP Unreachable 발생과 무관하다.","Null Routing은 패킷을 Null 인터페이스로 폐기하는 방식으로, 이때 출발지로 ICMP Unreachable이 생성되어 부하가 커지므로 'no ip unreachables' 설정이 권장된다.","Cut-Through는 스위치가 목적지 MAC만 읽고 즉시 프레임을 전달하는 스위칭 방식으로, 패킷 필터링 기법이 아니다.","Load Balancing은 트래픽을 여러 서버·링크에 분산하는 기술로, 공격 패킷을 폐기하는 기능이 아니다."],"rel":["2-12"],"box":"라우터나 스위치에서 DDoS 또는 DoS를 차단하는 경우 패킷이 특정 인터페이스로 보내져 패킷이 필터링 될 때마다 패킷의 출발지 ip로 ICMP Unreachable이라는 에러 메시지를 보내게 되는데, 필터링 하는 패킷이 많을 경우에는 라우터나 스위치에 과부하를 유발할 수 있기 때문에 ICMP 에러 메시지를 보내지 않도록 이것을 설정하는 것이 좋다."},{"n":32,"s":"s2","q":"다음 중 nmap의 TCP Half Open 스캔과 TCP FIN/NULL/XMAS 스캔에 대한 특징으로 옳지 않은 것은?","c":["TCP Half Open 스캔과 TCP FIN/NULL/XMAS 스캔은 대상 호스트에 로그를 남기지 않는다.","nmap 사용 시, TCP Half Open 스캔은 -sS 옵션, TCP FIN/NULL/XMAS 스캔은 각각 -sF, -sN, -sX 옵션을 사용한다.","공격대상의 닫힌 포트에 대한 TCP Half Open 스캔과 TCP FIN/NULL/XMAS 스캔은 각각 RST + ACK, RST 응답이 온다.","공격대상의 열린 포트에 대한 TCP Half Open 스캔과 TCP FIN/NULL/XMAS 스캔 시 둘 다 SYN + ACK 응답이 온다."],"a":3,"e":"열린 포트에 대해 Half Open(SYN) 스캔은 SYN+ACK 응답이 오지만, FIN/NULL/XMAS 스캔은 아무 응답이 없다(무응답=열림). 따라서 둘 다 SYN+ACK가 온다는 ④가 틀리다. 두 방식 모두 완전한 세션을 맺지 않아 대상 호스트 로그에 잘 남지 않는 스텔스 스캔이다.","ce":["옳은 설명이다. 두 방식 모두 3-Way Handshake를 완성하지 않아 애플리케이션 연결 로그에 잘 남지 않는 스텔스 스캔이다.","옳은 설명이다. nmap에서 SYN(Half Open) 스캔은 -sS, FIN·NULL·XMAS 스캔은 각각 -sF·-sN·-sX 옵션이다.","옳은 설명이다. 닫힌 포트에 SYN을 보내면 RST+ACK, FIN/NULL/XMAS를 보내면 RST(RST+ACK) 응답이 온다.","옳지 않다. 열린 포트에 SYN 스캔은 SYN+ACK가 오지만, FIN/NULL/XMAS 스캔은 아무 응답이 없다(무응답=열림)."],"rel":["2-4"]},{"n":33,"s":"s2","q":"무선랜의 보안 취약점에 대한 설명으로 잘못된 것은 무엇인가?","c":["무선랜은 유선처럼 물리적으로 랜케이블을 연결할 필요가 없기 때문에 관리자의 눈을 피해 불법침입자가 접속하기 용이하다.","기존의 AP를 제거하고 불법으로 AP를 교체하거나, 임의의 장소에 불법으로 AP를 설치하는 방법으로 내부 네트워크를 해킹할 수 있다.","무선망에서의 트래픽은 기존의 유선망과 동일한 패킷 프레임 구조로 구성되어 유선망에서의 해킹공격과 동일한 형식의 공격이 가능하다.","단말기에 대한 인증과 무선 구간의 암호화를 위해 WEP/WPA 프로토콜 등을 사용하여 보안기능을 일부 강화할 수 있다."],"a":2,"e":"무선랜(IEEE 802.11)은 유선 이더넷(802.3)과 MAC 프레임 구조가 다르며, 무선 매체 특성상 도청·Rogue AP·비인가 접속 등 무선 고유의 공격이 존재한다. 물리적 연결 없이 접속 가능한 점, 불법 AP 설치 위험, WEP/WPA를 통한 인증·암호화 보완은 올바른 설명이다.","ce":["옳은 설명이다. 무선랜은 전파 도달 범위 안이면 물리적 연결 없이 접속할 수 있어 비인가 침입자의 접근이 쉽다.","옳은 설명이다. 기존 AP를 불법 교체하거나 임의 장소에 Rogue AP를 설치해 내부 네트워크를 공격할 수 있다.","잘못된 설명이다. 무선랜(IEEE 802.11)은 유선 이더넷(802.3)과 프레임 구조가 다르며, 도청·Rogue AP 등 무선 고유의 공격이 존재한다.","옳은 설명이다. WEP/WPA/WPA2 등으로 단말 인증과 무선 구간 암호화를 적용해 보안을 일부 강화할 수 있다."],"rel":["2-10"]},{"n":34,"s":"s2","q":"다음 중 모바일 기기를 통한 애플리케이션 배포, 데이터 및 환경설정 변경, 모바일 분실 및 장치 관리를 통합적으로 해주는 시스템은?","c":["MDM","ESM","NAC","DLP"],"a":0,"e":"MDM(Mobile Device Management)은 모바일 기기의 앱 배포, 정책·환경설정, 분실 시 원격 잠금·삭제 등을 중앙에서 통합 관리한다. ESM은 보안 장비 로그 통합 관리, NAC는 단말의 네트워크 접속 통제, DLP는 정보 유출 방지 솔루션이다.","ce":["MDM(Mobile Device Management)은 모바일 기기의 앱 배포, 정책·환경설정 변경, 분실 시 원격 잠금·삭제 등을 중앙에서 통합 관리한다.","ESM(Enterprise Security Management)은 방화벽·IDS 등 이기종 보안 장비의 로그·이벤트를 통합 관리하는 시스템으로, 모바일 기기 관리 기능이 아니다.","NAC(Network Access Control)는 단말이 네트워크에 접속할 때 인증·보안 정책 준수 여부를 검사해 접속을 통제하는 솔루션이다.","DLP(Data Loss Prevention)는 중요정보 유출을 탐지·차단하는 솔루션으로, 앱 배포·분실 기기 관리 기능이 없다."],"rel":["1-15"]},{"n":35,"s":"s2","q":"다음 무선통신 보안에 관한 설명 중 틀린 것은?","c":["MAC 주소 인증은 사전에 미리 등록을 하여야 하는 번거로움이 있다.","WEP 인증은 데이터 암호화와 사용자 인증 기능을 제공한다.","SSID는 AP가 브로드캐스팅하지 않으면 접속할 방법이 없다.","EAP 인증을 통해 공격자의 패킷 도청을 방어할 수 있다."],"a":2,"e":"SSID 브로드캐스트를 중지(숨김)해도 사용자가 SSID를 직접 입력하면 접속할 수 있고, 프로브 요청을 스니핑하면 SSID를 알아낼 수 있다. MAC 인증은 사전 등록이 필요하고, WEP은 공유키 인증과 RC4 암호화를 제공한다.","ce":["옳은 설명이다. MAC 주소 인증은 허용할 단말의 MAC을 AP에 사전 등록해야 해 관리가 번거롭다(MAC 위조로 우회도 가능).","옳은 설명이다. WEP은 공유키 인증과 RC4 기반 데이터 암호화를 제공한다(다만 취약하다).","틀린 설명이다. SSID 브로드캐스트를 숨겨도 사용자가 SSID를 직접 입력하면 접속할 수 있고, 프로브 요청을 스니핑해 SSID를 알아낼 수도 있다.","옳은 설명이다. EAP(802.1X) 인증으로 사용자별 동적 키를 생성·교환하면 무선 구간 암호화가 강화되어 도청 방어에 기여한다."],"rel":["2-10"]},{"n":36,"s":"s2","q":"방화벽 장비에 대한 설명으로 가장 부적절한 것은?","c":["Transport Mode의 IPSec VPN이 구현될 수 있다.","보호하고자 하는 네트워크에 허가받지 않은 사용자들의 접근을 통제할 수 있는 시스템이다.","주요 기능으로 IP, PORT 차단 기능이 있다.","내부 네트워크 주소와 인터넷 주소를 변환시켜주는 기능을 설치하여 운영할 수 있다."],"a":0,"e":"방화벽(보안 게이트웨이)에 구현되는 IPSec VPN은 게이트웨이 간 원래 IP 패킷 전체를 캡슐화하는 터널(Tunnel) 모드가 사용되며, 전송(Transport) 모드는 종단 호스트 간 통신에 쓰인다. 비인가 접근 통제, IP·포트 차단, NAT는 방화벽의 기본 기능이다.","ce":["부적절하다. 방화벽(보안 게이트웨이)에서는 원래 IP 패킷 전체를 캡슐화하는 터널(Tunnel) 모드 IPSec VPN이 구현되며, 전송 모드는 종단 호스트 간 통신에 쓰인다.","적절하다. 방화벽은 보호 네트워크에 대한 비인가 사용자의 접근을 정책에 따라 통제하는 시스템이다.","적절하다. 출발지·목적지 IP와 포트 기반 허용·차단은 방화벽의 기본 기능이다.","적절하다. 방화벽은 NAT로 내부 사설 주소와 인터넷 공인 주소를 변환해 내부 구조를 숨길 수 있다."],"rel":["2-9","2-6"]},{"n":37,"s":"s2","q":"US-CERT는 크랙(KRACK)이라 부르는 WPA2(Wi-Fi Protected Access II) 프로토콜 내 취약점에 대한 내용을 공개하였으며, 키 재설정 공격인 크랙(Key Reinstallation Attack, KRACK)은 와이파이 인증 표준인 WPA2의 키 관리 취약점을 공격하는 것이다. 다음 중 이 취약점을 이용하는 공격과 거리가 먼 것은?","c":["TCP 연결 하이재킹","HTTP 컨텐츠 인젝션","Wi-Fi 패킷 재전송","SSID 브로드캐스팅"],"a":3,"e":"KRACK은 4-way 핸드셰이크 메시지 재전송으로 이미 사용 중인 키를 재설치시켜 논스를 초기화함으로써 패킷 복호화·재전송·위조를 가능하게 하며, 이를 통해 TCP 하이재킹, HTTP 콘텐츠 주입 등이 가능하다. SSID 브로드캐스팅은 AP의 일반 동작(비콘)으로 공격 기법이 아니다.","ce":["KRACK으로 세션 키 재설치 후 패킷을 복호화하면 TCP 시퀀스 번호를 알아내 TCP 연결 하이재킹이 가능하다.","KRACK으로 복호화·위조가 가능해지면 암호화되지 않은 HTTP 응답에 악성 콘텐츠를 주입할 수 있다.","KRACK은 4-way 핸드셰이크 메시지 3을 재전송해 논스를 초기화하므로 Wi-Fi 패킷 재전송(replay)이 가능해진다.","SSID 브로드캐스팅은 AP가 비콘 프레임으로 네트워크 이름을 알리는 정상 동작으로, KRACK 취약점을 이용한 공격이 아니다."],"rel":["2-10"]},{"n":38,"s":"s2","q":"TCP SYN Flooding 공격은 대량의 패킷을 생성하여 공격하는 방식이다. 다음 중 TCP SYN Flooding 공격과 관련이 없는 것은?","c":["Half Open Connection 공격","분산 DoS 공격","Reflector 공격","Teardrop 공격"],"a":3,"e":"Teardrop은 IP 단편(Fragment)의 오프셋을 겹치게 조작해 재조합 오류를 유발하는 공격으로 SYN Flooding과 무관하다. SYN Flooding은 반개방(Half Open) 연결을 쌓는 공격이며, 분산(DDoS) 형태나 반사체(Reflector)를 이용한 DRDoS 형태로도 수행된다.","ce":["SYN Flooding은 SYN만 보내고 ACK를 보내지 않아 서버에 반개방(Half Open) 연결을 쌓는 공격이므로 관련이 있다.","SYN Flooding은 다수의 좀비 PC로 동시에 수행하는 분산 DoS(DDoS) 형태로 흔히 실행되므로 관련이 있다.","출발지를 피해자 IP로 위조한 SYN을 정상 서버(반사체)에 보내 SYN+ACK가 피해자에게 몰리게 하는 Reflector(DRDoS) 공격도 SYN을 이용하므로 관련이 있다.","Teardrop은 IP 단편의 오프셋을 겹치게 조작해 재조합 오류를 유발하는 공격으로, TCP SYN 반개방 연결과 무관하다."],"rel":["2-3"]},{"n":39,"s":"s2","q":"Snort 탐지 옵션 정의 중 틀린 것은?","c":["sid : 규칙을 분류·식별하기 위한 ID 옵션이다.","nocase : 대소문자 구분 없이 탐지하는 옵션이다.","offset : content 옵션 명령이 검사할 byte 수를 지정하는 옵션이다.","distance : 이전 content 옵션으로 찾은 패턴의 끝부분 이후 몇 byte부터 검색할지 정하는 옵션이다."],"a":2,"e":"offset은 페이로드의 몇 번째 바이트부터 content 검사를 시작할지 지정하는 옵션이며, 검사할 바이트 수(범위)를 지정하는 것은 depth이다. sid는 규칙 식별자, nocase는 대소문자 무시, distance는 이전 매칭 이후 떨어진 거리 지정 옵션이다.","ce":["옳은 정의이다. sid는 Snort 규칙을 고유하게 식별하는 ID이다(1,000,000 이상은 사용자 정의 권장).","옳은 정의이다. nocase는 content 패턴을 대소문자 구분 없이 매칭한다.","틀린 정의이다. offset은 페이로드의 몇 번째 바이트부터 검사를 시작할지 지정하며, 검사할 바이트 수(범위)를 지정하는 것은 depth이다.","옳은 정의이다. distance는 이전 content 매칭이 끝난 위치로부터 몇 바이트 떨어진 곳부터 검색할지 지정한다."],"rel":["2-11"]},{"n":40,"s":"s2","q":"다음 중 로드 밸런싱을 제공하는 장비는?","c":["L2 스위치","L3 스위치","L4 스위치","허브"],"a":2,"e":"L4 스위치는 IP 주소와 TCP/UDP 포트 정보를 기반으로 트래픽을 여러 서버에 분산하는 로드 밸런싱 기능을 제공한다. L2 스위치는 MAC 기반 프레임 전달, L3 스위치는 IP 기반 라우팅, 허브는 단순 신호 재전송 장비이다.","ce":["L2 스위치는 MAC 주소 테이블로 프레임을 전달하는 장비로, IP·포트 기반 서버 부하 분산 기능이 없다.","L3 스위치는 IP 주소 기반 라우팅을 수행하지만 TCP/UDP 포트 단위 세션 분산(로드 밸런싱)은 제공하지 않는다.","L4 스위치는 IP와 TCP/UDP 포트 정보를 기반으로 트래픽을 여러 서버에 분산하는 로드 밸런싱 기능을 제공한다.","허브는 수신 신호를 모든 포트로 재전송하는 1계층 장비로, 트래픽 분산 기능이 없다."],"rel":["2-10","2-1"]},{"n":41,"s":"s3","q":"SSO에 대한 설명 중 적절하지 못한 것은?","c":["SSO는 한번의 인증으로 여러 서비스에 대한 이용을 지원하는 사용자 인증 시스템이다.","SSO를 도입하면 여러 응용 프로그램의 로그인 처리가 간소화되어 사용자들의 편의성이 증진될 수 있다.","SSO를 도입하면 최초 로그인 대상이 되는 응용 프로그램 또는 운영체제에 대한 보안 강화가 요구될 수 있다.","SSO를 도입하면 사이트별로 각각의 사용자 인증 시스템을 운영하는 방식에 비하여 보안이 강화된다."],"a":3,"e":"SSO는 한 번의 인증으로 여러 시스템에 접근하므로 인증 정보가 탈취되면 연계된 모든 시스템이 위험해지는 단일 실패 지점(SPOF) 문제가 있어, 개별 인증 방식보다 보안이 무조건 강화된다고 할 수 없다. 그래서 최초 인증 지점에 다중 인증 등 보안 강화가 요구된다.","ce":["적절하다. SSO는 한 번의 인증으로 여러 서비스를 이용하게 하는 인증 체계이다.","적절하다. 여러 애플리케이션 로그인이 하나로 간소화되어 사용자 편의성이 높아진다.","적절하다. 최초 인증 지점이 뚫리면 전체가 노출되므로 해당 지점에 다중 인증 등 보안 강화가 요구된다.","부적절하다. SSO는 인증 정보 탈취 시 연계된 모든 시스템이 위험해지는 단일 실패 지점(SPOF) 문제가 있어 개별 인증보다 보안이 무조건 강화되지 않는다."],"rel":["4-9"]},{"n":42,"s":"s3","q":"다음은 여러 공격 유형에 대해 DNSSEC이 방어 기능을 제공할 수 있는지를 보여주는 분석표이다. 분석이 잘못된 공격유형은?(문제 오류로 분석표가 없습니다. 정답은 4번입니다.)","c":["파밍","피싱","DDos 공격","웜바이러스에 의한 hosts 파일 안의 정보변조"],"a":3,"e":"원 문제의 분석표가 누락되어 있으나, DNSSEC은 DNS 응답에 전자서명을 붙여 DNS 캐시 포이즈닝 등 응답 위·변조를 막는 기술이다. 웜바이러스가 로컬 hosts 파일을 변조하면 DNS 질의 자체가 발생하지 않으므로 DNSSEC으로 방어할 수 없으며, 표에서 이 항목이 잘못 분석된 것이 정답(④)이다.","ce":["원문 분석표 누락으로 판단 근거 없음 — 공식 정답 기준 올바르게 분석된 항목이다. 참고로 DNSSEC은 DNS 응답 위조를 이용한 파밍을 방어할 수 있다.","원문 분석표 누락으로 판단 근거 없음 — 공식 정답 기준 올바르게 분석된 항목이다. 참고로 피싱(유사 도메인·기만 메일)은 DNS 응답 위조가 아니어서 DNSSEC으로 막기 어렵다.","원문 분석표 누락으로 판단 근거 없음 — 공식 정답 기준 올바르게 분석된 항목이다. 참고로 DNSSEC은 가용성 공격인 DDoS를 막지 못한다(오히려 응답 크기 증가로 증폭 우려).","공식 정답이다. 웜이 로컬 hosts 파일을 변조하면 DNS 질의 자체가 발생하지 않으므로 DNSSEC으로 방어할 수 없는데, 분석표가 이를 잘못 분석한 것으로 보인다."],"rel":["3-7"],"flag":"문제 복원 오류(분석표 누락) — 정답 4번만 신뢰"},{"n":43,"s":"s3","q":"다음은 KISA의 리눅스 Wi-Fi 보안취약성에 대한 보안권고문 중 일부이다. 빈칸 ㉠에 공통적으로 들어갈 용어는?","c":["XML injection","Brute force","SSRF(Server-Side Request Forgery)","Buffer Overflow"],"a":3,"e":"CVE-2019-17666은 리눅스 커널 rtlwifi 드라이버가 P2P NoA(Notice of Absence) 패킷의 길이를 검증하지 않아 경계값을 넘는 데이터로 발생하는 버퍼 오버플로 취약점으로, 시스템 충돌이나 코드 실행을 유발한다. SSRF는 서버가 공격자가 지정한 내부 자원에 요청하게 만드는 웹 취약점이다.","ce":["XML injection은 사용자 입력으로 XML 문서 구조·XPath 질의를 조작하는 웹 취약점으로, 드라이버의 경계값 체크 미흡과 무관하다.","Brute force는 가능한 값을 반복 대입해 패스워드·키를 알아내는 공격으로, 패킷 길이 경계값 문제가 아니다.","SSRF는 서버가 공격자가 지정한 내부 자원으로 요청을 보내게 만드는 웹 취약점으로, 커널 Wi-Fi 드라이버 결함과 무관하다.","CVE-2019-17666은 rtlwifi 드라이버가 NoA 패킷 길이를 검증하지 않아 경계를 넘는 데이터가 기록되는 버퍼 오버플로로, 시스템 충돌·코드 실행을 유발한다."],"rel":["1-10"],"box":"리눅스의 특정 드라이버에서 발생하는 ( ㉠ ) 취약점 (CVE-2019-17666)\n\n▶ 취약점 내용\n- 리눅스 커널의 \"rtlwifi\" 드라이버에서 경계값 체크가 미흡하여 ( ㉠ ) 발생\n  ※ rtlwifi 드라이버 : 특정 Realtek Wi-Fi 모듈이 리눅스OS 시스템과 통신할 수 있도록 허용해 주는 컴포넌트\n- 공격자가 경계값을 넘어서는 길이의 \"NoA\" 패킷을 전송하면 ( ㉠ )로 인해 시스템 장애(crash) 발생"},{"n":44,"s":"s3","q":"인터넷과 같은 공용 통신망에서 안전한 데이터 전달과 사용자 인증 기능을 수행하는 SSL 보안 프로토콜 중 전송되는 데이터에 대한 암호화 및 복호화, 메시지 인증 코드의 생성과 검증을 수행하는 프로토콜은?","c":["Handshake 프로토콜","Alert 프로토콜","Change Cipher Spec 프로토콜","Record 프로토콜"],"a":3,"e":"Record 프로토콜은 상위 데이터를 단편화·압축하고 MAC 생성·검증과 암호화·복호화를 수행해 실제 데이터의 기밀성·무결성을 제공한다. Handshake는 알고리즘 협상·인증·키 교환, Change Cipher Spec은 협상된 암호 사양 적용 통지, Alert는 오류·경고 전달을 담당한다.","ce":["Handshake 프로토콜은 암호 알고리즘 협상, 서버(·클라이언트) 인증, 키 교환을 수행하며 실제 데이터 암호화·MAC 처리는 하지 않는다.","Alert 프로토콜은 오류·경고(예 인증서 오류, 연결 종료 통지)를 상대에게 전달한다.","Change Cipher Spec 프로토콜은 협상된 암호 사양을 이후 레코드부터 적용한다고 알리는 1바이트 메시지이다.","Record 프로토콜은 상위 데이터를 단편화·압축하고 MAC 생성·검증과 암호화·복호화를 수행해 실제 전송 데이터의 기밀성·무결성을 제공한다."],"rel":["2-7"]},{"n":45,"s":"s3","q":"MS SQL 서버는 윈도우 인증과 SQL 서버 인증이라는 두 가지 인증 방법을 제공하고 있다. 이에 대한 설명으로 잘못된 것은?","c":["SQL Server의 기본 인증 모드는 윈도우 인증이다.","윈도우 인증 모드가 적용되어 있을 경우 SQL 서버 인증을 이용할 수 없다.","혼합 인증 모드가 적용되어 있을 경우 윈도우 인증과 SQL 서버 인증 모두 사용될 수 있다.","윈도우 인증과 SQL 서버 인증 중 보안성이 높은 안전한 인증 방법은 SQL 서버 인증이다."],"a":3,"e":"윈도우 인증은 OS 계정 정책(Kerberos, 암호 정책·잠금)을 그대로 활용하므로 SQL 서버 자체 인증보다 보안성이 높아 권장된다. 기본 모드는 윈도우 인증이며, 윈도우 인증 모드에서는 SQL 인증을 쓸 수 없고 혼합 모드에서는 둘 다 사용할 수 있다.","ce":["옳은 설명이다. SQL Server 설치 시 기본 인증 모드는 윈도우 인증이다.","옳은 설명이다. 윈도우 인증 모드에서는 SQL Server 자체 계정(sa 등) 로그인이 허용되지 않는다.","옳은 설명이다. 혼합 인증 모드에서는 윈도우 인증과 SQL Server 인증을 모두 사용할 수 있다.","잘못된 설명이다. 윈도우 인증이 Kerberos·도메인 암호 정책·계정 잠금을 활용하므로 SQL Server 인증보다 보안성이 높아 권장된다."],"rel":["3-8"]},{"n":46,"s":"s3","q":"쿠키에 대한 설명 중 가장 부적절한 것은?","c":["웹사이트에 마지막으로 방문한 시간, 페이지 등 다양한 정보를 기록할 수 있다.","쿠키의 유효 기간을 설정할 수 있으며, 유효(만료) 기간이 설정되지 않을 경우 웹브라우저 종료 시에 자동 삭제된다.","웹서버가 웹브라우저에게 보내어 저장했다가 해당 사이트를 다시 방문할 때 서버에게 전달된다.","웹 서버에 저장된 쿠키값은 개인정보보호를 위해 정기적으로 삭제해야 한다."],"a":3,"e":"쿠키는 서버가 아닌 클라이언트(웹브라우저)에 저장되므로 '웹 서버에 저장된 쿠키값'이라는 표현이 틀리다. 서버 측에서 상태를 유지하는 것은 세션이다. 만료 기간이 없는 쿠키는 브라우저 종료 시 삭제되는 세션 쿠키이다.","ce":["적절하다. 쿠키에 마지막 방문 시간, 방문 페이지, 사용자 설정 등 다양한 정보를 기록할 수 있다.","적절하다. Expires·Max-Age로 유효기간을 설정할 수 있고, 설정하지 않으면 세션 쿠키로 브라우저 종료 시 삭제된다.","적절하다. 서버가 Set-Cookie로 브라우저에 저장시키고 같은 사이트 재방문 시 Cookie 헤더로 서버에 전달된다.","부적절하다. 쿠키는 웹 서버가 아니라 클라이언트(웹브라우저)에 저장된다. 서버 측 상태 저장은 세션이다."],"rel":["3-3"]},{"n":47,"s":"s3","q":"DRM 구성 요소 중에서 콘텐츠를 이용하는 사용자에 대해 정해진 정책에 따라 사용 권한을 결정하고, 부여된 사용 권한에 따라 라이선스의 발급 및 그 내역을 관리하는 시스템을 무엇이라고 하는가?","c":["패키저(Packager)","클리어링 하우스(Clearing House)","시큐어 컨테이너(Secure Container)","DRM 제어기(DRM Controller)"],"a":1,"e":"클리어링 하우스는 콘텐츠 사용 권한(라이선스) 발급·관리와 사용량에 따른 결제·정산을 담당한다. 패키저는 콘텐츠를 메타데이터와 함께 암호화·패키징하고, 시큐어 컨테이너는 보호된 콘텐츠 형태, DRM 제어기는 사용자 단말에서 권한에 따라 콘텐츠 이용을 통제한다.","ce":["패키저(Packager)는 콘텐츠를 메타데이터와 함께 암호화·패키징해 보호 콘텐츠로 만드는 구성요소로, 라이선스 발급 주체가 아니다.","클리어링 하우스(Clearing House)는 사용자 정책에 따라 사용 권한을 결정하고 라이선스 발급·내역 관리 및 결제·정산을 담당한다.","시큐어 컨테이너(Secure Container)는 암호화된 콘텐츠와 메타데이터를 담은 보호 형태(포맷)로, 권한을 결정하는 시스템이 아니다.","DRM 제어기(DRM Controller)는 사용자 단말에서 라이선스에 따라 콘텐츠 복호화·이용을 통제하는 구성요소로, 라이선스를 발급하지 않는다."],"rel":["3-12"]},{"n":48,"s":"s3","q":"버퍼 오버플로우 공격을 막는 가장 중요한 방법으로 프로그래밍 시 권장하는 함수가 아닌 것은?","c":["strncat()","fgets()","snprintf()","strcpy()"],"a":3,"e":"strcpy()는 대상 버퍼의 크기를 검사하지 않고 복사하므로 버퍼 오버플로에 취약해 사용을 피해야 한다. strncat·fgets·snprintf는 처리할 최대 길이를 인자로 받아 경계를 제한하는 안전한 대체 함수이다(strcpy 대신 strncpy·strlcpy 권장).","ce":["strncat()은 덧붙일 최대 문자 수를 인자로 받아 버퍼 경계를 제한하므로 strcat 대신 권장된다.","fgets()는 읽을 최대 길이를 지정하므로 길이 검사 없는 gets() 대신 권장된다.","snprintf()는 출력 버퍼 크기를 지정해 초과 기록을 막으므로 sprintf() 대신 권장된다.","strcpy()는 대상 버퍼 크기를 검사하지 않고 복사해 버퍼 오버플로에 취약하므로 사용을 피하고 strncpy·strlcpy 등으로 대체해야 한다."],"rel":["1-10","3-9"]},{"n":49,"s":"s3","q":"다음 디지털 포렌식에 대한 설명 중 옳지 않은 것은?","c":["디지털 증거는 현실적으로 손상되기 쉽고, 분석 중에 훼손 및 변경, 조작될 수 있다.","정당성의 원칙은 수집 증거가 위변조 되지 않았음을 증명하는 것이다.","디지털 증거는 증거 식별, 수집, 획득, 보존, 분석 등의 과정을 거친다.","연계보관성의 원칙은 증거를 획득, 이송, 분석, 법정 제출의 각 단계에서 담당자 및 책임자를 명확히 하는 것이다."],"a":1,"e":"수집 증거가 위·변조되지 않았음을 증명하는 것은 무결성의 원칙(해시값 비교)이다. 정당성의 원칙은 증거가 적법한 절차에 따라 수집되어야 한다는 원칙으로, 위법하게 수집된 증거는 증거능력이 없다(독수독과).","ce":["옳은 설명이다. 디지털 증거는 복제·수정이 쉬워 수집·분석 중 훼손·변경·조작될 위험이 있으므로 쓰기 방지·해시 검증이 필요하다.","옳지 않다. 수집 증거가 위변조되지 않았음을 증명하는 것은 무결성의 원칙이며, 정당성의 원칙은 적법한 절차로 수집해야 한다는 원칙이다.","옳은 설명이다. 디지털 증거는 식별 → 수집 → 획득 → 보존 → 분석 → 보고 등의 절차를 거친다.","옳은 설명이다. 연계보관성 원칙은 획득·이송·분석·보관·법정 제출 각 단계의 담당자와 책임자를 명확히 기록하는 것이다."],"rel":["3-11"]},{"n":50,"s":"s3","q":"전자메일의 실제 발송자를 추적하기 위해 사용되는 메일 헤더의 항목은?","c":["Message-ID","Content-Type","From","Received"],"a":3,"e":"Received 헤더는 메일이 거쳐 간 각 메일 서버(MTA)가 수신 시각·서버명·IP를 역순으로 추가하므로, 가장 아래 Received 항목으로 실제 발송 서버를 추적할 수 있다. From은 발신자가 임의로 위조할 수 있고, Content-Type은 본문 형식, Message-ID는 메일 고유 식별자이다.","ce":["Message-ID는 메일마다 부여되는 고유 식별자로 중복 판별·스레드 연결에 쓰이며, 경유 서버 경로 정보를 담지 않는다.","Content-Type은 본문의 MIME 형식(text/html, multipart 등)과 문자셋을 나타내는 헤더로, 발송 경로 추적과 무관하다.","From은 발신자가 임의로 작성·위조할 수 있는 표시용 헤더이므로 실제 발송자 추적 근거로 신뢰할 수 없다.","Received는 메일이 거친 각 MTA가 수신 시각·서버명·IP를 위에 추가해 가므로, 가장 아래 Received로 실제 발송 서버를 추적할 수 있다."],"rel":["3-2"]},{"n":51,"s":"s3","q":"데이터베이스의 보안 유형과 거리가 먼 것은?","c":["접근 제어(Access Control)","데이터 집계연산(Aggregation)","가상 테이블(Views)","암호화(Encryption)"],"a":1,"e":"집계(Aggregation)는 낮은 등급의 개별 정보를 모아 높은 등급의 정보를 알아내는 데이터베이스 보안 '위협'이며 보안 통제 수단이 아니다. 접근 제어, 뷰(View)를 통한 노출 범위 제한, 암호화는 데이터베이스 보안 통제 방법이다.","ce":["접근 제어는 사용자·역할별로 테이블·열 접근 권한(GRANT/REVOKE)을 제한하는 데이터베이스 보안 통제 수단이다.","집계(Aggregation)는 낮은 등급의 개별 정보를 모아 상위 등급의 민감 정보를 알아내는 데이터베이스 보안 '위협'으로, 보안 통제 유형이 아니다.","뷰(View)는 사용자에게 필요한 행·열만 보이는 가상 테이블을 제공해 노출 범위를 제한하는 데이터베이스 보안 통제 수단이다.","암호화는 저장 데이터(컬럼·테이블스페이스)를 암호화해 유출 시에도 내용을 보호하는 데이터베이스 보안 통제 수단이다."],"rel":["3-8"]},{"n":52,"s":"s3","q":"전자 금융거래에서 사용되는 단말 정보, 접속 로그, 거래 정보 등을 분석하여 이상 금융거래 또는 부정 거래 행위를 탐지 및 예방하는 시스템은?","c":["IDS(Intrusion Detection System)","FDS(Fraud Detection System)","POS(Point Of Sale System)","HDS(Hitachi Data System)"],"a":1,"e":"FDS(이상금융거래탐지시스템)는 단말기·접속 정보, 거래 패턴 등을 수집·분석해 평소와 다른 이상 거래를 실시간 탐지·차단한다. IDS는 네트워크·호스트 침입 탐지 시스템이고, POS는 판매시점 정보관리 시스템이다.","ce":["IDS(침입탐지시스템)는 네트워크·호스트의 침입 시도를 탐지하는 시스템으로, 금융거래 패턴 기반 부정거래 탐지 시스템이 아니다.","FDS(이상금융거래탐지시스템)는 단말·접속 정보와 거래 패턴을 수집·분석해 평소와 다른 이상 거래를 실시간 탐지·차단한다.","POS(Point Of Sale)는 판매 시점에 매출·재고 정보를 기록·관리하는 판매시점 정보관리 시스템이다.","HDS(Hitachi Data Systems)는 스토리지 업체명으로, 이상 금융거래 탐지 시스템과 무관하다."],"rel":["3-13"]},{"n":53,"s":"s3","q":"다음 지문에서 설명하는 보안 솔루션은?","c":["DRM(Digital Rights Management)","DLP(Data Loss Prevention)","NAC(Network Access Control)","MLS(Multi-Level Security)"],"a":1,"e":"DLP는 사용 중(in use)·전송 중(in motion)·저장(at rest) 상태의 민감 데이터를 식별·모니터링하고 유출 시도를 탐지·차단한다. DRM은 콘텐츠 암호화와 사용 권한 통제로 저작권·문서를 보호하고, NAC는 단말의 네트워크 접속을 통제한다.","ce":["DRM은 콘텐츠를 암호화하고 열람·복사·출력 권한을 통제하는 기술로, 사용·전송·저장 상태 데이터의 유출 전송 감지가 주목적이 아니다.","DLP는 사용 중(in use)·전송 중(in motion)·저장(at rest) 상태의 민감 데이터를 식별·모니터링하고 유출 시도를 탐지·차단한다.","NAC(Network Access Control)는 단말의 네트워크 접속 시 인증·보안 정책 준수를 검사해 접속을 통제하는 솔루션이다.","MLS(Multi-Level Security)는 보안 등급이 다른 정보를 한 시스템에서 등급별로 분리·통제하는 다단계 보안 모델이다."],"rel":["3-12","1-11"],"box":"잠재적인 데이터 또는 정보(데이터)의 유출 전송을 감지하며, 사용 중 또는 이동 중 정지 상태에 있는 민감한 데이터 또는 정보를 모니터링 하거나 감지, 차단함으로써 이를 방지한다."},{"n":54,"s":"s3","q":"다음 지문에서 설명하는 공격 기법은 무엇인가?","c":["Bounce 공격","XSS 공격","Anonymous FTP 공격","디렉터리 리스팅 공격"],"a":0,"e":"FTP 바운스 공격은 PORT 명령으로 데이터 연결 목적지를 임의로 지정할 수 있는 취약점을 이용해 익명 FTP 서버를 경유지로 삼아 포트 스캔 등을 수행한다. Anonymous FTP 공격은 익명 계정의 쓰기 권한 등 설정 미흡을 악용하는 공격이다.","ce":["FTP 바운스 공격은 PORT 명령으로 데이터 연결 목적지를 임의 지정할 수 있는 취약점을 이용해 익명 FTP 서버를 경유지로 포트 스캔 등을 수행한다.","XSS는 웹 페이지에 악성 스크립트를 삽입해 방문자 브라우저에서 실행시키는 웹 공격으로, FTP 데이터 포트 취약점과 무관하다.","Anonymous FTP 공격은 익명 계정의 쓰기 가능 디렉터리 등 설정 미흡을 악용해 파일 업로드·자료 탈취를 하는 공격으로, 목적지 미검사 결함을 이용하지 않는다.","디렉터리 리스팅 공격은 웹 서버의 디렉터리 인덱싱 설정 미흡으로 파일 목록이 노출되는 취약점을 악용하는 것이다."],"rel":["3-1"],"box":"익명 FTP 서버를 이용하여 공격 대상의 네트워크를 포트 스캐닝하는 데 사용하는 공격 기법으로서 FTP 서버가 데이터 포트로 데이터를 전송할 때 목적지가 어디인지 검사하지 않는다는 취약점을 이용한다."},{"n":55,"s":"s3","q":"WPKI 구성요소의 역할을 잘못 기술한 것은?","c":["인증기관(CA) : 인증서 발급","등록기관(RA) : 인증서 폐지","사용자(Client) : 인증서 발급 및 관리에 대한 요청","디렉터리(Directory) : CA가 발행한 인증서 정보 저장"],"a":1,"e":"등록기관(RA)은 사용자 신원 확인과 인증서 발급·폐지 요청의 접수·중계를 담당하며, 실제 인증서 발급·폐지(CRL 발행)는 인증기관(CA)이 수행한다. 디렉터리는 인증서와 CRL을 저장·공개한다.","ce":["옳게 기술되었다. 인증기관(CA)은 신원 확인이 끝난 요청에 대해 인증서를 발급(서명)한다.","잘못 기술되었다. 등록기관(RA)은 신원 확인과 발급·폐지 요청의 접수·중계를 담당하며, 실제 인증서 폐지(CRL 발행)는 CA가 수행한다.","옳게 기술되었다. 사용자(Client)는 인증서 발급·갱신·폐지 등 관리 요청을 한다.","옳게 기술되었다. 디렉터리(저장소)는 CA가 발행한 인증서와 CRL을 저장·공개한다."],"rel":["3-14"]},{"n":56,"s":"s3","q":"XML 조회를 위한 질의문(XPath, XQuery 등) 생성 시 사용되는 입력값과 조회 결과에 대한 검증 방법(필터링 등)을 설계하고 유효하지 않은 값에 대한 처리방법을 설계할 때 고려해야 할 사항 중 잘못된 것은?","c":["공통 검증 컴포넌트를 이용한 입력값 필터링","필터 컴포넌트를 이용한 입력값 필터링","개별 코드에서 입력값을 필터링하도록 시큐어코딩 규칙 정의","필터를 이용한 출력값 검증"],"a":3,"e":"행정안전부 SW 보안약점 진단 가이드의 XML 삽입 대응 설계 항목은 공통 검증 컴포넌트·필터 컴포넌트를 이용한 입력값 필터링, 개별 코드의 입력값 필터링 시큐어코딩 규칙 정의 등 '입력값' 중심이다. 필터를 이용한 출력값 검증은 해당 설계 고려사항에 포함되지 않는다.","ce":["고려사항이다. 공통 검증 컴포넌트로 XPath·XQuery 입력값의 특수문자를 필터링하도록 설계한다.","고려사항이다. 필터 컴포넌트를 이용해 요청 단계에서 입력값을 일괄 필터링하도록 설계한다.","고려사항이다. 개별 코드에서 입력값을 필터링하도록 시큐어코딩 규칙을 정의해 개발자가 적용하게 한다.","잘못된 사항이다. XML 삽입 대응 설계는 질의문에 들어가는 '입력값' 검증이 핵심이며, 필터를 이용한 출력값 검증은 해당 설계 고려사항에 포함되지 않는다."],"rel":["3-6"]},{"n":57,"s":"s3","q":"TLS에 대한 공격대상과 공격방법의 쌍이 올바르지 못한 것은?","c":["DHE export Key - Logjam","CBC mode encryption - BEAST","CBC mode encryption + padding - FREAK","OpenSSL(SSL 3.0) - Heartbleed"],"a":2,"e":"FREAK은 수출용(export) 512비트 RSA 키로 다운그레이드시키는 공격이며, CBC 모드 패딩을 노린 공격은 POODLE·Lucky13이다. Logjam은 수출용 DHE 키 다운그레이드, BEAST는 CBC 모드 IV 예측, Heartbleed는 OpenSSL Heartbeat 확장 구현 결함 공격이다.","ce":["올바른 쌍이다. Logjam은 TLS 연결을 수출용(export) 512비트 DHE 키로 다운그레이드시켜 이산대수를 풀어내는 공격이다.","올바른 쌍이다. BEAST는 TLS 1.0 CBC 모드의 예측 가능한 IV를 악용해 암호문을 복호화하는 공격이다.","올바르지 못한 쌍이다. FREAK은 수출용 512비트 RSA 키로 다운그레이드시키는 공격이며, CBC 모드 패딩을 노린 공격은 POODLE·Lucky13이다.","공식적으로 올바른 쌍으로 처리된다. Heartbleed는 OpenSSL의 Heartbeat 확장 구현 결함으로 서버 메모리를 유출하는 공격이다(엄밀히는 SSL 3.0이 아닌 TLS Heartbeat 구현 문제)."],"rel":["2-7"],"flag":"④ Heartbleed는 SSL 3.0이 아닌 OpenSSL Heartbeat(TLS) 구현 결함이나 원문 그대로 전사"},{"n":58,"s":"s3","q":"다음 중 SSL이 제공하는 보안 기능과 거리가 먼 것은?","c":["암호화 세션","서버 인증","클라이언트 인증","부인 방지"],"a":3,"e":"SSL/TLS는 암호화 세션을 통한 기밀성, MAC을 통한 무결성, 인증서를 통한 서버 인증과 선택적 클라이언트 인증을 제공한다. 메시지 단위 전자서명을 남기지 않으므로 부인 방지는 제공하지 않는다.","ce":["제공 기능이다. SSL/TLS는 협상된 대칭키로 암호화 세션을 만들어 전송 데이터의 기밀성을 보장한다.","제공 기능이다. 서버 인증서를 검증해 접속한 서버의 신원을 확인한다.","제공 기능이다. 선택적으로 클라이언트 인증서를 요구해 클라이언트를 인증할 수 있다.","거리가 멀다. SSL은 메시지 단위 전자서명을 남기지 않으므로 송신 사실을 제3자에게 증명하는 부인 방지를 제공하지 않는다."],"rel":["2-7"]},{"n":59,"s":"s3","q":"다음 지문에서 웹 로그파일에 저장되는 내용을 모두 고른 것은?","c":["가, 나, 다","다, 라, 마","가, 나, 다, 마","나, 다, 라, 마"],"a":2,"e":"웹 서버 접근 로그(Common/Combined Log Format)에는 클라이언트 IP, 사용자 ID(identd·인증 사용자), 접속 시간, 요청 방식(GET·POST 등의 요청 종류)이 기록된다. 공식 정답은 요청 내용(라)을 제외한 가·나·다·마이며, POST 바디 등 요청 데이터 내용은 기본 로그에 저장되지 않는다는 취지이다.","ce":["가·나·다는 기록되지만, 요청 종류(마, GET·POST 등 메서드)도 로그에 기록되므로 빠져 있어 불완전하다.","클라이언트 IP(가)와 접속 시간(나)이 빠졌다. 두 항목은 접근 로그의 기본 필드이며, 요청 내용(라)은 공식 정답상 제외 대상이다.","공식 정답이다. Common/Combined Log Format에는 클라이언트 IP·사용자 ID·접속 시간·요청 방식이 기록된다(요청 라인의 URL도 남으므로 '요청내용' 제외는 논란 소지가 있다).","클라이언트 IP(가)가 빠졌고 요청 내용(라)이 들어갔다. IP는 접근 로그 첫 필드로 반드시 기록되며, 공식 정답은 POST 바디 등 요청 데이터 내용은 기본 저장되지 않는다고 본다."],"rel":["3-4"],"box":"가. 클라이언트 IP\n나. 클라이언트 접속시간\n다. 클라이언트 ID\n라. 클라이언트 요청내용\n마. 클라이언트 요청종류","flag":"요청 라인(URL)도 기록되므로 '요청내용' 제외는 논란 소지 — 공식 정답 3번 유지"},{"n":60,"s":"s3","q":"OTP(One-Time Password)는 고정된 패스워드 대신 랜덤하게 생성되는 일회성 패스워드를 말하며 동일한 패스워드를 사용할 경우 발생할 수 있는 보안상 취약점을 극복하여 일회성의 서로 다른 패스워드를 생성함으로써 안전한 전자상거래를 진행할 수 있게 한다. 다음 중 OTP의 생성 및 인증 방식이 아닌 것은?","c":["이벤트 동기화 방식","캡차(CAPTCHA) 방식","질의/응답 방식","시간 동기화 방식"],"a":1,"e":"OTP 생성·인증 방식에는 질의/응답(Challenge-Response), 시간 동기화, 이벤트(카운터) 동기화, 시간·이벤트 혼합 방식이 있다. CAPTCHA는 사람과 자동화 프로그램(봇)을 구분하기 위한 튜링 테스트 기법으로 OTP 방식이 아니다.","ce":["OTP 방식이다. 이벤트(카운터) 동기화 방식은 인증 요청 횟수를 카운터로 삼아 단말과 서버가 같은 OTP를 생성한다.","OTP 방식이 아니다. CAPTCHA는 왜곡 문자·이미지로 사람과 자동화 봇을 구분하는 튜링 테스트 기법이다.","OTP 방식이다. 질의/응답 방식은 서버가 보낸 난수(질의)를 단말에 입력해 계산한 응답값을 OTP로 사용한다.","OTP 방식이다. 시간 동기화 방식은 단말과 서버가 현재 시각(예 30·60초 단위)을 입력으로 같은 OTP를 생성한다."],"rel":["4-8"]},{"n":61,"s":"s4","q":"다음 중 Needham-Schroeder 키 분배에 대한 설명으로 옳지 않은 것은?","c":["키 분배 센터를 이용하는 키 분배 방법이다.","질의-응답(Challenge-Response) 방식을 이용하여 설계되었다.","Kerberos 프로토콜의 취약점을 개선한 프로토콜이다.","재전송 공격(Replay attack)에 취약하다."],"a":2,"e":"선후관계가 반대로, Needham-Schroeder 프로토콜(1978)의 재전송 공격 취약점을 타임스탬프로 개선한 것이 Kerberos이다. Needham-Schroeder는 KDC를 이용하고 논스 기반 질의-응답으로 설계되었으나 이전 세션키가 노출되면 재전송 공격에 취약하다.","ce":["옳은 설명이다. Needham-Schroeder 대칭키 프로토콜은 신뢰된 키 분배 센터(KDC)가 세션키를 분배한다.","옳은 설명이다. 논스(nonce)를 이용한 질의-응답 방식으로 상대의 세션키 보유 여부를 확인하도록 설계되었다.","옳지 않다. 선후관계가 반대이다. Needham-Schroeder(1978)의 재전송 공격 취약점을 타임스탬프로 개선한 것이 Kerberos이다.","옳은 설명이다. 이전 세션키가 노출되면 공격자가 옛 메시지를 재전송해 새 세션처럼 속일 수 있다(Denning-Sacco 공격)."],"rel":["4-12"]},{"n":62,"s":"s4","q":"다음 지문에서 공유 폴더에 적용된 접근통제 방식은?","c":["강제적 접근통제","임의적 접근통제","역할기반 접근통제","규칙기반 접근통제"],"a":1,"e":"공유 폴더 접근 권한이 개별 사용자·그룹 단위로 부여되고, 권한을 가진 IT팀 직원이 재량으로 권한을 갱신한 것은 신원 기반·소유자 재량의 임의적 접근통제(DAC)이다. 강제적 접근통제(MAC)는 보안 레이블에 따라 시스템이 강제하고, RBAC은 직무(역할)에 권한을 부여한다.","ce":["강제적 접근통제(MAC)는 주체·객체의 보안 레이블을 시스템이 비교해 강제하므로, 개별 직원·그룹에 권한을 부여·갱신하는 지문 상황과 다르다.","사용자·그룹 단위로 권한이 부여되고 권한을 가진 IT팀 직원이 재량으로 갱신한 것은 신원 기반·재량 방식의 임의적 접근통제(DAC)이다.","역할기반 접근통제(RBAC)는 직무(역할)에 권한을 할당하고 사용자를 역할에 배정하는 방식으로, 개별 직원에게 직접 권한을 부여하지 않는다.","규칙기반 접근통제는 시간·위치 등 관리자가 정한 전역 규칙을 모든 사용자에게 일괄 적용하는 방식으로, 사용자별 권한 부여와 다르다."],"rel":["4-10"],"box":"IT 팀장이 직원으로부터 공유 폴더에 접근할 수 없다는 보고를 받은 후 조사를 했더니 다음과 같은 사실을 발견하였다.\n- 해당 직원 또는 직원이 속한 그룹에게 공유 폴더에 대한 접근 권한이 부여되어 있지 않았다.\n- 다른 직원 또는 그룹에게 공유 폴더에 대한 접근 권한이 부여되어 있었다.\n- IT팀 내 다른 직원이 최근에 공유 폴더에 대한 접근 권한을 갱신하였다."},{"n":63,"s":"s4","q":"다음 중 Kerberos 프로토콜에 대한 설명으로 옳지 않은 것은?","c":["비밀키 암호작성법에 기초를 둔 온라인 암호키 분배방법이다.","Kerberos 프로토콜의 목적은 인증되지 않은 클라이언트도 서버에 접속할 수 있도록 하는 것이다.","Kerberos 프로토콜은 데이터의 기밀성과 무결성을 보장한다.","키 분배 센터에 오류 발생 시, 전체 서비스를 사용할 수 없게 된다."],"a":1,"e":"Kerberos의 목적은 신뢰된 제3자(KDC)가 발급한 티켓으로 '인증된' 클라이언트만 서버에 접속하도록 하는 것이다. 대칭키 기반 온라인 키 분배 방식이며, KDC가 단일 실패 지점이라 KDC 장애 시 전체 서비스를 사용할 수 없다는 한계가 있다.","ce":["옳은 설명이다. Kerberos는 대칭키(비밀키) 암호에 기초해 KDC가 온라인으로 세션키를 분배한다.","옳지 않다. Kerberos의 목적은 KDC가 발급한 티켓으로 '인증된' 클라이언트만 서버에 접속하게 하는 것이다.","옳은 설명이다. 티켓과 세션키로 암호화·인증을 수행해 전송 데이터의 기밀성과 무결성을 보장한다.","옳은 설명이다. KDC(AS·TGS)가 단일 실패 지점이므로 KDC 장애 시 전체 인증 서비스를 쓸 수 없다."],"rel":["2-8","4-12"]},{"n":64,"s":"s4","q":"다음은 커버로스 프로토콜의 세션키 전송 절차에 필요한 단계이다. 이 단계의 순서가 올바르게 나열된 것은?","c":["㉣ → ㉢ → ㉤ → ㉡ → ㉠","㉠ → ㉣ → ㉡ → ㉢ → ㉤","㉣ → ㉤ → ㉡ → ㉠ → ㉢","㉤ → ㉡ → ㉠ → ㉢ → ㉣"],"a":2,"e":"클라이언트가 인증서버(AS)에 인증(㉣) → AS가 TGT를 발급해 티켓 발급서버(TGS) 이용을 허용(㉤) → TGS가 인증된 클라이언트에게 서비스 티켓 발급(㉡) → 클라이언트가 티켓으로 서버에 접속(㉠) → 서버가 티켓 확인 후 접속 허락(㉢) 순이다. AS 인증 이전에 서비스 티켓을 쓰거나 서버에 접속하는 순서는 틀리다.","ce":["서버 접속 허락(㉢)이 인증서버 인증(㉣) 바로 다음에 와서, 티켓 발급 과정(㉤·㉡) 없이 접속을 허락하는 잘못된 순서이다.","클라이언트가 티켓으로 서버에 접속(㉠)하는 단계가 맨 앞에 있어, 티켓을 받기도 전에 접속하는 순서이다.","AS 인증(㉣) → TGT 발급으로 TGS 이용 허용(㉤) → TGS의 서비스 티켓 발급(㉡) → 티켓으로 서버 접속(㉠) → 서버의 확인·허락(㉢) 순으로 올바르다.","인증서버 인증(㉣)이 맨 마지막에 있다. AS 인증이 가장 먼저 이루어져야 이후 티켓 발급이 가능하다."],"rel":["2-8"],"box":"㉠ 클라이언트는 티켓을 이용하여 서버에 접속\n㉡ 티켓 발급서버는 인증된 클라이언트에게 티켓을 발급\n㉢ 서버는 티켓을 확인 후 클라이언트를 인증하여 접속을 허락\n㉣ 클라이언트는 서버에 접속하기 위해 인증서버와 인증(패스워드)\n㉤ 인증서버는 인증된 클라이언트에게 티켓 발급서버로부터 티켓 발급을 허용"},{"n":65,"s":"s4","q":"다음은 특정 블록 암호 운영 모드의 암호화 과정이다. 해당 모드는?(문제 오류로 운영모드 이미지가 없습니다. 정답은 2번입니다.)","c":["ECB 모드","CBC 모드","CFB 모드","OFB 모드"],"a":1,"e":"원 문제의 운영 모드 그림이 누락되어 정확한 풀이가 불가능하며 공개 정답은 CBC이다. CBC는 평문 블록을 직전 암호문 블록(첫 블록은 IV)과 XOR한 뒤 암호화하는 방식으로, ECB는 블록을 독립적으로 암호화하고 CFB·OFB는 암호화 출력을 평문과 XOR하는 스트림형 모드이다.","ce":["원문 그림 누락으로 판단 근거 없음 — 공식 정답은 CBC이다. ECB는 각 블록을 독립적으로 암호화해 같은 평문 블록이 같은 암호문이 되는 모드이다.","공식 정답이다. 그림은 누락되었으나 CBC는 평문 블록을 직전 암호문 블록(첫 블록은 IV)과 XOR한 뒤 암호화하는 모드이다.","원문 그림 누락으로 판단 근거 없음 — 공식 정답은 CBC이다. CFB는 직전 암호문(또는 IV)을 암호화한 출력과 평문을 XOR하는 모드이다.","원문 그림 누락으로 판단 근거 없음 — 공식 정답은 CBC이다. OFB는 블록 암호 출력을 다시 입력으로 피드백해 만든 키스트림을 평문과 XOR하는 모드이다."],"rel":["4-3"],"flag":"문제 복원 오류(운영모드 그림 누락) — 정답 2번만 신뢰"},{"n":66,"s":"s4","q":"스트림 암호에 대한 설명으로 가장 부적절한 것은?","c":["일회성 패드를 실용적으로 구현할 목적으로 개발되었다.","짧은 주기와 높은 선형 복잡도가 요구되며 주로 LFSR을 이용한다.","블록단위 암호화 대비 비트단위로 암호화하여 암호화 시간이 더 빠르다.","블록 암호의 OFB 모드는 스트림 암호와 유사하게 동작한다."],"a":1,"e":"스트림 암호의 키스트림은 반복되면 안 되므로 '긴' 주기와 높은 선형 복잡도가 요구되며, 주로 LFSR(선형 되먹임 시프트 레지스터) 조합으로 구현한다. 일회성 패드의 실용적 구현, 비트 단위의 빠른 처리, OFB 모드와의 유사성은 올바른 설명이다.","ce":["적절하다. 스트림 암호는 무작위 키스트림을 평문과 XOR하는 일회성 패드(OTP)를 짧은 키로 실용적으로 구현하려는 목적에서 나왔다.","부적절하다. 키스트림이 반복되면 안 되므로 '짧은' 주기가 아니라 '긴' 주기와 높은 선형 복잡도가 요구되며, 주로 LFSR 조합으로 구현한다.","적절하다. 비트(바이트) 단위로 키스트림과 XOR하므로 블록 단위 처리보다 빠르고 하드웨어 구현이 간단하다.","적절하다. OFB 모드는 블록 암호로 키스트림을 생성해 평문과 XOR하므로 동기식 스트림 암호처럼 동작한다."],"rel":["4-2"]},{"n":67,"s":"s4","q":"다음 중 전자서명에 대한 설명으로 옳지 않은 것은?","c":["서명문에 공개키 암호화 방식(혹은 비대칭 암호화 방식)을 이용하여 서명자의 개인키로 생성한 정보","전자서명은 서명문의 위조 불가, 서명한 행위의 부인 방지를 제공할 수 있다.","은닉서명은 서명자가 서명문의 내용을 알지 못하는 상태에서 서명하도록 한 방식으로 서명자의 익명성이 보장된다.","DSA 알고리즘은 이산대수 문제의 어려움에 기반을 두고 있는 대표적인 전자서명 알고리즘이다."],"a":0,"e":"공식 정답은 ①이다. 전자서명은 서명문 자체가 아니라 서명문의 해시값에 서명자 개인키를 적용해 생성하며, 공개키로 '암호화'하는 것이 아니라는 점에서 표현이 부정확하다고 본 것이다. 은닉서명은 서명 요청자(메시지 제공자)의 익명성을 보장하므로 ③도 엄밀히는 논란이 있다.","ce":["공식 정답이다. 전자서명은 서명문 자체가 아니라 서명문의 해시값에 서명자 개인키를 적용해 생성한다는 점에서 표현이 부정확하다고 본 것이다.","옳은 설명이다. 개인키를 가진 서명자만 서명을 만들 수 있어 위조 불가, 서명 사실을 부인할 수 없어 부인 방지를 제공한다.","공식적으로는 옳은 설명으로 처리된다. 다만 은닉서명은 서명자가 아니라 서명 요청자(메시지 제공자)의 익명성을 보장하므로 엄밀히는 이의 소지가 있다.","옳은 설명이다. DSA(Digital Signature Algorithm)는 이산대수 문제의 어려움에 기반한 미국 전자서명 표준(DSS) 알고리즘이다."],"rel":["4-6"],"flag":"이의 소지: ③ 은닉서명은 서명자가 아닌 '서명 요청자'의 익명성 보장 — 공식 정답 1번 유지"},{"n":68,"s":"s4","q":"다음 중 KDC(Key Distribution Center)에 대한 설명으로 옳지 않은 것은?","c":["사용자가 아무리 많더라도 KDC에서 관리하여야 할 키의 수는 동일하다.","사용자는 상대방과의 암호 통신에 사용될 키를 생성할 필요가 없다.","키의 관리는 KDC에서 이루어지기 때문에 사용자의 키 관리가 요구되지 않는다.","KDC에서 많은 키를 관리하기 때문에 해커에 의한 공격 위험이 높다."],"a":0,"e":"KDC는 사용자마다 KDC와 공유하는 마스터키를 하나씩 관리하므로 사용자 수(n)가 늘어나면 관리할 키 수도 n개로 증가한다. 세션키는 KDC가 생성·분배하므로 사용자가 직접 키를 생성할 필요가 없고, 키가 집중되어 공격 표적이 되고 단일 실패 지점이 된다는 단점이 있다.","ce":["옳지 않다. KDC는 사용자마다 KDC와 공유하는 마스터키를 하나씩 관리하므로 사용자 수 n이 늘면 관리할 키도 n개로 증가한다.","옳은 설명이다. 세션키는 KDC가 생성해 분배하므로 사용자가 상대별 통신 키를 직접 생성할 필요가 없다.","옳은 설명이다. 사용자는 KDC와의 마스터키 하나만 보관하면 되고 세션키 관리는 KDC가 담당한다.","옳은 설명이다. 모든 키가 KDC에 집중되어 해커의 주요 공격 표적이 되고 단일 실패 지점이 된다."],"rel":["4-12"]},{"n":69,"s":"s4","q":"공개키 기반 구조(PKI)에서 등록기관(RA)이 수행하는 기능이 아닌 것은?","c":["인증서 발급 대행","사용자 신분 확인","인증 요청서 보관","인증서 폐지 목록 저장"],"a":3,"e":"인증서 폐지 목록(CRL)은 인증기관(CA)이 발행하고 디렉터리(저장소)에 저장·공개된다. RA는 사용자 신원 확인, 인증서 발급·폐지 요청 접수 및 CA로의 중계(발급 대행), 요청서 보관 등을 수행한다.","ce":["RA 기능이다. RA는 사용자의 인증서 발급 요청을 접수해 CA에 중계하는 발급 대행을 수행한다.","RA 기능이다. RA는 인증서 신청자의 신원을 대면·서류 등으로 확인한다.","RA 기능이다. RA는 접수한 인증 요청서와 신원 확인 자료를 보관한다.","RA 기능이 아니다. CRL은 CA가 발행·서명하고 디렉터리(저장소)에 저장·공개된다."],"rel":["4-7"]},{"n":70,"s":"s4","q":"아래 지문은 긴 메시지에 전자서명하는 방법에 대한 설명이다. 이렇게 하는 가장 근본적인 이유는?","c":["전자서명 알고리즘의 특성상 전자서명 및 검증속도가 데이터량에 따라 많은 영향을 받기 때문이다.","국제표준으로 규정된 것이기 때문이다.","해시함수로 생성된 해시값이 안전한 전자서명을 보장하기 때문이다.","전자서명에 대칭암호시스템이 사용되기 때문이다."],"a":0,"e":"공개키 기반 전자서명 연산은 데이터 크기에 비례해 매우 느리므로, 긴 메시지 대신 고정 길이의 짧은 해시값에 서명해 서명·검증 효율을 높인다. 해시값 자체가 서명의 안전성을 보장하는 것은 아니며, 전자서명에는 대칭키가 아닌 공개키 암호가 사용된다.","ce":["공개키 서명 연산은 데이터 크기에 비례해 매우 느리므로, 긴 메시지 대신 고정 길이 해시값에 서명해 서명·검증 효율을 높이는 것이 근본 이유이다.","국제표준 규정 여부는 근본 이유가 아니다. 해시 후 서명은 효율성 때문에 표준들이 채택한 방식이다.","해시값이 서명의 안전성을 보장하는 것은 아니다. 안전성은 서명 알고리즘과 해시의 충돌 저항성이 함께 결정하며, 해시 사용의 주목적은 효율이다.","전자서명에는 대칭암호가 아니라 공개키(비대칭) 암호가 사용된다."],"rel":["4-6"],"box":"긴 메시지의 해시값을 생성하고, 이를 자신의 개인키로 전자서명 한다. 검증자는 수신된 긴 메시지로부터 해시값을 계산하고, 전자서명자의 공개키로 전자서명된 해시값으로부터 해시값을 복원한다. 이렇게 얻어진 2개의 해시값을 비교하여 동일성 여부로 전자서명을 검증한다."},{"n":71,"s":"s4","q":"256 비트 키 길이의 AES 알고리즘의 라운드의 개수는?","c":["10","12","14","16"],"a":2,"e":"AES는 키 길이에 따라 라운드 수가 다르며 128비트 키는 10라운드, 192비트는 12라운드, 256비트는 14라운드이다. 블록 크기는 키 길이와 무관하게 128비트로 고정이다.","ce":["10라운드는 128비트 키 AES의 라운드 수이다.","12라운드는 192비트 키 AES의 라운드 수이다.","256비트 키 AES는 14라운드를 수행한다(블록 크기는 키 길이와 무관하게 128비트 고정).","16라운드는 DES의 라운드 수로, AES의 어떤 키 길이에도 해당하지 않는다."],"rel":["4-2"]},{"n":72,"s":"s4","q":"다음 설명 중 틀린 것은?","c":["사용자의 인증서에 인증기관의 올바른 전자서명이 붙어 있고 인증서의 유효기간이 유효하면 인증서를 신뢰한다.","개인키가 제대로 관리되고 있어도 인증서는 폐지될 수 있다.","인증서가 폐지되면 CRL에 추가되고 폐지 대상 인증서 목록에 인증기관이 전자서명을 한다.","인증서에 포함되어 있는 공개키가 바른지를 알아보기 위해서는 인증기관의 공개키가 필요하다."],"a":0,"e":"인증서는 CA 서명과 유효기간 외에도 CRL·OCSP로 폐지 여부를 확인해야 신뢰할 수 있으므로 ①이 틀리다. 소속 변경·정보 변경 등으로 개인키 유출이 없어도 폐지될 수 있고, CRL은 CA가 서명하며, 인증서 검증에는 CA의 공개키가 필요하다.","ce":["틀린 설명이다. CA 서명과 유효기간이 정상이어도 CRL·OCSP로 폐지 여부를 확인해야 인증서를 신뢰할 수 있다.","옳은 설명이다. 소속 변경, 정보 변경, 이용 중지 요청 등으로 개인키 유출이 없어도 인증서는 폐지될 수 있다.","옳은 설명이다. 폐지된 인증서는 CRL에 추가되고, CRL 위변조를 막기 위해 CA가 전자서명을 한다.","옳은 설명이다. 인증서 속 공개키의 정당성은 CA 서명을 CA 공개키로 검증해 확인한다."],"rel":["4-7"]},{"n":73,"s":"s4","q":"다음 중 HMAC에 대한 설계 목적의 설명으로 올바르지 않은 것은?","c":["내장된 해시함수를 손쉽게 교체할 수 있어야 한다.","사용되는 해시함수를 손쉽게 구할 수 있어야 한다.","제공되는 해시함수를 목적에 맞게 변경하여 사용할 수 있어야 한다.","해시함수의 원래의 성능을 거의 유지할 수 있어야 한다."],"a":1,"e":"공식 정답은 ②이다. RFC 2104의 HMAC 설계 목표는 이용 가능한 해시함수를 수정 없이 사용, 내장 해시함수의 손쉬운 교체, 해시함수 원래 성능의 유지, 간단한 키 처리, 해시함수 강도에 근거한 안전성 분석이다. 다만 '해시함수를 변경하지 않고 사용'이 목표이므로 ③도 부정확해 보여 이의 소지가 있다.","ce":["설계 목적에 해당한다. 더 안전한 해시가 나오면 내장 해시함수를 손쉽게 교체할 수 있어야 한다(RFC 2104).","공식 정답이다. 다만 RFC 2104는 '코드를 자유롭게·널리 구할 수 있는 해시함수를 수정 없이 사용'을 목표로 명시해 이 보기도 설계 목적에 부합하므로 정답 논란이 있다.","공식적으로는 설계 목적으로 처리된다. 다만 RFC 2104는 해시함수를 '변경하지 않고' 사용하는 것을 목표로 하므로 이 보기가 더 명확히 틀렸다는 이의 소지가 있다.","설계 목적에 해당한다. HMAC은 해시함수의 원래 성능을 크게 떨어뜨리지 않고 유지해야 한다."],"rel":["4-5"],"flag":"이의 소지: RFC 2104 기준 ③(해시함수 변경 사용)이 더 명확히 틀림 — 이미지·txt 모두 2번"},{"n":74,"s":"s4","q":"다음 블록 암호 운영 모드 중 메시지 인증에 사용될 수 있는 것들로 올바르게 짝지어진 것은?","c":["㉠ - ㉡","㉠ - ㉢","㉡ - ㉢","㉡ - ㉣"],"a":3,"e":"CBC 모드는 마지막 암호문 블록을 MAC으로 쓰는 CBC-MAC에 사용되고, CTR 모드는 CCM(CTR+CBC-MAC)·GCM(CTR+GHASH) 같은 인증 암호 모드의 기반이 된다. ECB는 블록 간 연쇄가 없어 메시지 인증에 사용할 수 없다.","ce":["ECB는 블록 간 연쇄가 없어 블록 재배열·치환을 탐지할 수 없으므로 메시지 인증에 쓰이지 않는다.","ECB는 메시지 인증에 사용할 수 없다. CFB도 표준 MAC 구성의 기반으로 쓰이지 않는다.","CBC는 CBC-MAC에 쓰이지만, CFB는 표준 메시지 인증 구성(CCM·GCM 등)의 기반이 아니다.","CBC는 마지막 암호문 블록을 MAC으로 쓰는 CBC-MAC에, CTR은 CCM(CTR+CBC-MAC)·GCM(CTR+GHASH) 인증 암호 모드에 사용된다."],"rel":["4-3"],"box":"㉠ ECB   ㉡ CBC   ㉢ CFB   ㉣ CTR"},{"n":75,"s":"s4","q":"다음 중 CRL(Certificate Revocation List)에 대한 설명으로 옳지 않은 것은?","c":["인증서 폐지 사유로는 인증 발생 조직에서의 탈퇴, 개인키의 침해, 개인키의 유출 의심 등이 있다.","인증서 폐지 메커니즘은 X.509에 정의된 인증서 폐지 목록(CRL)으로 관리한다.","인증서의 폐지는 인증서 소유자 본인만 가능하다.","폐지된 인증서의 목록은 디렉터리에 보관하여 공개하고 네트워크를 통해 접속하여 확인할 수 있다."],"a":2,"e":"인증서 폐지는 소유자 본인의 요청뿐 아니라 개인키 침해 확인, 발급 조건 위반 등의 사유로 인증기관(CA)이 직권으로도 할 수 있다. 폐지 사유(조직 탈퇴·키 유출 등), X.509 CRL 관리, 디렉터리를 통한 공개는 올바른 설명이다.","ce":["옳은 설명이다. 조직 탈퇴(소속 변경), 개인키 침해, 개인키 유출 의심 등은 대표적 폐지 사유이다.","옳은 설명이다. 인증서 폐지는 X.509에 정의된 CRL로 관리하며, 실시간 확인에는 OCSP도 쓰인다.","옳지 않다. 소유자 요청 외에도 개인키 침해 확인, 발급 조건 위반 등의 사유로 CA가 직권으로 폐지할 수 있다.","옳은 설명이다. CRL은 디렉터리(LDAP 등)에 공개되어 네트워크로 접속해 확인할 수 있다."],"rel":["4-7"]},{"n":76,"s":"s4","q":"무선 네트워크 보안을 위한 WPA, WPA2 등에서는 순방향 기밀성(forward secrecy)을 지원하지 않고 있지만, 2018년 Wi-Fi Alliance에서는 순방향 기밀성을 지원하는 WPA3을 발표하였다. 다음 중 순방향 기밀성의 의미를 올바르게 설명하고 있는 것은?","c":["보안 프로토콜이 적용된 이후의 트래픽에 대해서는 기밀성이 보장된다.","중간자 공격을 통해 암호키를 탈취하는 공격에 대한 방어 메커니즘을 갖추고 있다.","현재 사용되는 세션키나 마스터키가 노출되더라도 예전에 암호화된 트래픽의 기밀성에 영향을 미치지 않는다.","192비트 이상의 암호 강도를 갖는 AES-256, SHA-384 등의 고강도 암호 알고리즘의 채택을 의무화하고, 취약한 비밀번호 사용을 차단한다."],"a":2,"e":"순방향 기밀성(전방향 안전성, PFS)은 장기 키나 현재 세션키가 노출되더라도 과거 세션의 암호화 트래픽은 복호화될 수 없음을 뜻하며, 세션마다 임시(Ephemeral) 키 교환으로 구현한다. ④는 WPA3-Enterprise 192비트 모드 설명이고, ②는 중간자 공격 방어로 순방향 기밀성의 정의가 아니다.","ce":["보호 프로토콜 적용 이후 트래픽의 기밀성은 일반적인 암호화의 효과일 뿐, 키 노출 시 과거 트래픽 보호라는 순방향 기밀성 정의가 아니다.","중간자 공격으로 키를 탈취하는 공격의 방어는 상호 인증(WPA3의 SAE 등)의 역할로, 순방향 기밀성의 정의가 아니다.","순방향 기밀성(PFS)은 현재 세션키나 장기 마스터키가 노출되어도 과거 세션의 암호화 트래픽은 복호화되지 않는 성질로, 세션별 임시 키 교환으로 구현한다.","192비트 암호 강도(AES-256·SHA-384 등) 의무화는 WPA3-Enterprise 192비트 모드 설명으로, 순방향 기밀성의 의미가 아니다."],"rel":["4-4"]},{"n":77,"s":"s4","q":"다음 지문의 괄호 안에 들어갈 용어를 순서대로 나열한 것은?","c":["개인키, 개인키","개인키, 공개키","공개키, 개인키","공개키, 공개키"],"a":3,"e":"기밀성을 위해 송신자는 수신자의 공개키로 암호화하고 수신자는 자신의 개인키로 복호화한다. 전자서명은 송신자의 개인키로 서명하고 검증자는 송신자의 공개키로 검증하므로 두 빈칸 모두 공개키이다.","ce":["수신자의 개인키로 암호화하면 누구나 공개키로 복호화할 수 있어 기밀성이 없고, 서명 검증에 송신자 개인키를 쓰면 검증자가 키를 가질 수 없다.","암호화는 수신자의 개인키가 아니라 공개키로 해야 수신자만 복호화할 수 있다. 서명 검증 키(송신자 공개키)는 맞다.","암호화 키(수신자 공개키)는 맞지만, 서명 검증은 송신자의 개인키가 아니라 공개키로 한다. 개인키는 서명 생성에 쓴다.","기밀성은 수신자 공개키로 암호화하고 수신자 개인키로 복호화하며, 서명은 송신자 개인키로 생성하고 송신자 공개키로 검증하므로 둘 다 공개키이다."],"rel":["4-4"],"box":"공개키 알고리즘으로 정보화 서비스와 전자서명 서비스를 제공할 때 암호화에 사용하는 키는 수신자의 (   )이고, 서명 검증에 사용하는 키는 송신자의 (   )이다."},{"n":78,"s":"s4","q":"공개키 기반구조와 인증서에 대한 다음 설명 중 적절치 않은 것은?","c":["인증서란 사용자의 공개키에 대해 인증기관이 인증해 주는 전자문서이다.","등록기관이란 공개키와 인증서 소유자 사이의 관계를 확인해주고 인증서 발급을 대행해 주는 기관이다.","인증서에는 평문 상태의 공개키와 암호문 상태의 개인키가 포함된다.","X.509 인증서의 확장영역은 CRL 배포지점 등 사용자나 공개키에 연계된 여러 가지 속성들에 해당하는 선택정보를 담고 있는 부분으로 X.509 버전 3에서 도입되었다."],"a":2,"e":"인증서에는 소유자 정보, 공개키, 유효기간, 발급자, CA 서명 등이 포함되며 개인키는 어떤 형태로도 포함되지 않는다(개인키는 소유자가 별도 보관). 확장 영역(Extensions)은 X.509 v3에서 도입되었다.","ce":["적절하다. 인증서는 사용자 공개키와 신원 정보의 결합을 CA가 전자서명으로 보증하는 전자문서이다.","적절하다. 등록기관(RA)은 신청자 신원과 공개키 소유 관계를 확인하고 인증서 발급을 대행한다.","적절치 않다. 인증서에는 평문 공개키, 소유자·발급자 정보, 유효기간, CA 서명 등이 들어가며 개인키는 어떤 형태로도 포함되지 않는다.","적절하다. 확장 영역(Extensions)은 X.509 v3에서 도입되어 CRL 배포지점, 키 용도 등 선택 속성을 담는다."],"rel":["4-7"]},{"n":79,"s":"s4","q":"다음 중 암호공격 방식에 대한 설명이 틀린 것은?","c":["트래픽 분석 : 불법적인 공격자가 전송되는 메시지를 도중에 가로채어 그 내용을 외부로 노출시키는 공격","재생 공격 : 공격자가 이전에 특정 송신자와 수신자 간에 행해졌던 통신내용을 캡처하여 보관하고 있다가 나중에 다시 전송하는 공격","삽입 공격 : 불법적인 공격자가 정당한 송신자로 가장하여 특정 수신자에게 위조된 메시지를 보내어 불법적인 효과를 발생시키는 공격","메시지 변조 : 전송되는 메시지들의 순서를 바꾸거나 메시지의 일부분을 다른 메시지로 대체하여 불법적인 효과를 발생시키는 공격"],"a":0,"e":"트래픽 분석은 메시지 내용이 암호화되어 있어도 송수신자, 통신 빈도·길이 등 패턴을 관찰해 정보를 추론하는 소극적 공격이다. 메시지를 가로채 내용을 노출시키는 것은 도청(메시지 내용 공개)에 해당한다.","ce":["틀린 설명이다. 트래픽 분석은 내용이 암호화되어 있어도 송수신자·통신 빈도·길이 패턴을 관찰해 정보를 추론하는 소극적 공격이며, 내용 노출은 도청(메시지 내용 공개)이다.","옳은 설명이다. 재생(재전송) 공격은 이전 통신 내용을 캡처했다가 나중에 다시 보내 부정한 효과를 얻는다.","옳은 설명이다. 삽입 공격은 정당한 송신자로 가장해 위조 메시지를 끼워 넣는 공격이다.","옳은 설명이다. 메시지 변조는 메시지 순서를 바꾸거나 일부를 다른 내용으로 대체해 부정한 효과를 얻는 공격이다."],"rel":["4-1"]},{"n":80,"s":"s4","q":"해시함수 h와 주어진 입력값 x에 대해 h(x)=h(x')를 만족하는 x'(≠x)를 찾는 것이 계산적으로 불가능한 것을 무엇이라고 하는가?","c":["압축성","일방향성","두 번째 역상저항성","강한 충돌 저항성"],"a":2,"e":"입력 x가 주어졌을 때 같은 해시값을 갖는 다른 입력 x'을 찾기 어려운 성질은 두 번째 역상 저항성(약한 충돌 저항성)이다. 강한 충돌 저항성은 x를 지정하지 않고 h(x)=h(x')인 임의의 쌍을 찾기 어려운 성질이며, 일방향성은 해시값으로부터 입력을 찾기 어려운 성질이다.","ce":["압축성은 임의 길이 입력을 고정 길이 출력으로 만드는 성질로, 같은 해시값을 갖는 다른 입력을 찾기 어려운 성질과 다르다.","일방향성(역상 저항성)은 해시값 y만 주어졌을 때 h(x)=y인 입력 x를 찾기 어려운 성질이다.","특정 입력 x가 주어졌을 때 h(x)=h(x')인 다른 x'를 찾기 어려운 성질은 두 번째 역상 저항성(약한 충돌 저항성)이다.","강한 충돌 저항성은 x를 지정하지 않고 h(x)=h(x')인 임의의 서로 다른 쌍을 찾기 어려운 성질이다."],"rel":["4-5"]},{"n":81,"s":"s5","q":"빈칸 ㉠, ㉡에 들어갈 용어를 순서대로 나열한 것은 무엇인가?","c":["㉠ 목표 ㉡ 위협 수준을","㉠ 업무특성 ㉡ 위협 수준을","㉠ 목표 ㉡ 중요도를","㉠ 업무특성 ㉡ 중요도를"],"a":3,"e":"ISMS-P 인증기준(1.2.1 정보자산 식별)은 조직의 업무특성에 따라 정보자산 분류기준을 수립하고, 범위 내 모든 정보자산을 식별·분류한 뒤 중요도를 산정해 목록을 최신으로 관리하도록 한다. 위협 수준 평가는 자산 식별 이후 위험평가 단계의 활동이다.","ce":["분류기준은 조직의 '목표'가 아니라 '업무특성'에 따라 수립하고, 자산 식별 단계에서는 위협 수준이 아니라 중요도를 산정한다.","㉠ 업무특성은 맞지만 ㉡ 위협 수준 평가는 자산 식별 이후 위험평가 단계의 활동이다. 자산 식별 단계에서는 중요도를 산정한다.","㉡ 중요도는 맞지만 ㉠은 ISMS-P 인증기준상 조직의 '업무특성'이다.","ISMS-P 1.2.1은 업무특성에 따라 정보자산 분류기준을 수립하고 모든 자산을 식별·분류한 뒤 중요도를 산정해 목록을 최신으로 관리하도록 한다."],"rel":["5-11"],"box":"위험관리의 정보자산 식별 활동에서는 조직의 ( ㉠ )에 따라 정보자산 분류기준을 수립하여 관리체계 범위 내 모든 정보자산을 식별/분류하고, ( ㉡ ) 산정한 후 그 목록을 최신으로 관리하여야 한다."},{"n":82,"s":"s5","q":"다음 중 정보보호 교육 및 훈련에 대한 설명으로 적절하지 않은 것은 무엇인가?","c":["위험분석을 통해 구현된 정보보호 대책을 실제 운영 또는 시행할 부서 및 담당자를 파악하여 관련 내용을 공유하고 교육한다.","정책, 지침 및 절차 등이 개정된 사항에 대해서는 모두 모이기 어렵기 때문에 집합 또는 온라인 교육보단 게시판 등을 통해서 알리는 것이 보다 효과적이다.","타사의 침해사고 사례, 최근 발생한 보안위협 등에 대한 최근 동향을 지속적으로 교육함으로써 보안인식 제고를 위해 노력한다.","출장, 휴가 등의 사정으로 정기 정보보호 교육을 받지 못한 인력에 대해서 전달교육, 추가교육, 온라인 교육 등의 방법으로 정보보호 교육을 수행한다."],"a":1,"e":"정책·지침·절차의 개정 등 중요한 변경 사항은 게시판 공지에 그치지 않고 집합·온라인 교육 등으로 관련 인력에게 명확히 교육해야 한다(ISMS-P 2.2.4). 대책 운영 부서 공유 교육, 최신 위협 동향 교육, 미이수자 추가 교육은 적절한 활동이다.","ce":["적절하다. 위험분석으로 도출·구현된 대책을 운영할 부서·담당자를 파악해 내용을 공유하고 교육해야 한다.","적절하지 않다. 정책·지침·절차 개정 같은 중요 변경은 게시판 공지에 그치지 않고 집합·온라인 교육 등으로 관련 인력에게 명확히 교육해야 한다.","적절하다. 타사 침해사고 사례와 최신 보안위협 동향을 지속적으로 교육해 보안인식을 높인다.","적절하다. 정기 교육 미이수자에게는 전달교육·추가교육·온라인 교육 등으로 교육을 보완해야 한다."],"rel":["5-11"]},{"n":83,"s":"s5","q":"다음 지문이 설명하는 것은?","c":["업무연속성관리체계","재난복구체계","보안성평가체계","정보보호관리체계"],"a":3,"e":"정보보호관리체계(ISMS)는 정보자산의 기밀성·무결성·가용성을 실현하기 위한 절차와 과정을 체계적으로 수립·문서화하고 지속적으로 관리·운영하는 시스템이다. 업무연속성관리체계(BCMS)는 재해·장애 시 핵심 업무의 지속에 초점을 둔다.","ce":["업무연속성관리체계(BCMS)는 재해·장애 시 핵심 업무를 지속·복구하는 데 초점을 두며, CIA 전반을 관리하는 체계가 아니다.","재난복구체계(DRS)는 재해 발생 시 정보시스템을 복구하기 위한 설비·절차로, 가용성 회복에 초점을 둔다.","보안성평가체계는 정보보호 제품·시스템의 보안 기능을 평가·인증하는 체계(예 CC 평가)로, 조직의 지속적 관리 운영 시스템이 아니다.","정보보호관리체계(ISMS)는 정보자산의 기밀성·무결성·가용성을 위한 절차와 과정을 체계적으로 수립·문서화하고 지속적으로 관리·운영하는 시스템이다."],"rel":["5-12"],"box":"이것은 정보자산의 기밀성, 무결성, 가용성을 실현하기 위한 절차와 과정을 체계적으로 수립, 문서화하고 지속적으로 관리, 운영하는 시스템을 말한다."},{"n":84,"s":"s5","q":"다음 중 정량적 위험분석의 장점이 아닌 것은?","c":["위험관리 성능평가가 용이하다.","위험평가 결과가 금전적 가치, 백분율, 확률 등으로 표현되어 이해가 쉽다.","정보자산의 가치가 논리적으로 평가되고 화폐로 표현되어 이해가 쉽다.","위험분석 작업을 위한 시간과 비용이 절약된다."],"a":3,"e":"정량적 위험분석은 자산 가치, 발생 빈도, 손실액(ALE 등)을 수치로 산출해야 하므로 계산이 복잡하고 시간·비용이 많이 드는 것이 단점이다. 시간·비용 절약은 정성적 분석의 장점이며, 결과의 금전적 표현과 성능평가 용이성은 정량적 분석의 장점이다.","ce":["정량적 분석의 장점이다. 결과가 수치로 나와 보안 투자 전후의 위험 감소 효과(성능)를 평가하기 쉽다.","정량적 분석의 장점이다. 결과가 금액·백분율·확률로 표현되어 경영진이 이해하기 쉽다.","정량적 분석의 장점이다. 자산 가치를 논리적으로 산정해 화폐 단위로 표현하므로 비용 대비 효과 판단이 쉽다.","정량적 분석의 장점이 아니다. 자산 가치·발생 빈도·ALE 등을 수치로 산출해야 해 시간·비용이 많이 들며, 시간·비용 절약은 정성적 분석의 장점이다."],"rel":["5-2"]},{"n":85,"s":"s5","q":"개인정보 영향평가를 하는 경우에 고려할 사항이 아닌 것은?","c":["처리하는 개인정보의 수","개인정보의 제3자 제공여부","개인정보처리의 위탁 여부","정보주체의 권리를 해할 가능성 및 그 위험의 정도"],"a":2,"e":"개인정보 보호법 제33조는 영향평가 시 처리하는 개인정보의 수, 제3자 제공 여부, 정보주체의 권리를 해할 가능성 및 그 위험 정도, 그 밖에 대통령령으로 정한 사항을 고려하도록 한다. 처리 위탁 여부는 법에 명시된 고려사항이 아니다(개정 여부 확인).","ce":["고려사항이다. 처리하는 개인정보의 수는 개인정보 보호법 제33조에 명시된 영향평가 고려사항이다.","고려사항이다. 개인정보의 제3자 제공 여부는 제33조에 명시된 영향평가 고려사항이다.","고려사항이 아니다. 개인정보 처리 위탁 여부는 제33조에 명시된 영향평가 고려사항이 아니다(개정 여부 확인).","고려사항이다. 정보주체의 권리를 해할 가능성 및 그 위험의 정도는 제33조에 명시된 고려사항이다."],"rel":["5-9"]},{"n":86,"s":"s5","q":"인터넷 기업이 사물인터넷(Internet of Things, IoT)을 이용한 비즈니스를 구상하고 있다. 사물인터넷은 이종 장치들과 유무선 네트워크 기술 그리고 지능화 플랫폼을 기반으로 개발되어야 한다. 서비스 제공자와 사용자가 IoT 장치의 전 주기 세부단계에서 고려해야 하는 공통 보안 요구사항 중에서 'IoT 장치 및 서비스 운영/관리/폐기 단계의 보안요구사항'으로 가장 부적절한 것은?","c":["IoT 침해사고 대응체계 및 책임추적성 확보 방안 마련","안전한 운영·관리를 위한 정보보호 및 프라이버시 관리 체계 마련","안전한 소프트웨어 및 하드웨어 개발 기술 적용 및 검증","IoT 제품·서비스의 취약점 보안패치 및 업데이트 지속 이행"],"a":2,"e":"KISA IoT 공통보안가이드에서 안전한 소프트웨어·하드웨어 개발 기술 적용 및 검증은 '설계·개발 단계'의 보안 요구사항이다. 운영·관리·폐기 단계에는 보안패치·업데이트 지속 이행, 정보보호·프라이버시 관리체계 마련, 침해사고 대응체계·책임추적성 확보 등이 해당한다.","ce":["운영·관리·폐기 단계 요구사항이다. 운영 중 발생하는 침해사고에 대응할 체계와 책임추적성 확보 방안을 마련해야 한다.","운영·관리·폐기 단계 요구사항이다. 안전한 운영·관리를 위한 정보보호 및 프라이버시 관리체계를 마련해야 한다.","부적절하다. 안전한 소프트웨어·하드웨어 개발 기술 적용 및 검증은 KISA IoT 공통보안가이드상 '설계·개발 단계'의 보안 요구사항이다.","운영·관리·폐기 단계 요구사항이다. 출시 후 발견된 취약점에 대한 보안패치·업데이트를 지속적으로 이행해야 한다."],"rel":["1-15"]},{"n":87,"s":"s5","q":"다음 중 「개인정보보호법」에 따른 국무총리 소속의 개인정보보호위원회의 기능이 아닌 것은?","c":["개인정보보호 관련 법령, 정책 등을 수립하거나 집행","개인정보보호에 관한 법령의 해석·운영에 관한 사항 심의","개인정보의 처리에 관한 공공기관 간의 의견조정에 관한 사항 의결","관계 기관 등에 대한 자료제출이나 사실조회 요구"],"a":0,"e":"공식 정답은 ①이다. 출제 기준(개정 전 심의·의결 기구 체계)에서 보호위원회는 법령 해석·운영 심의, 공공기관 간 의견조정 의결, 관계 기관에 대한 자료제출·사실조회 요구 등을 수행하며, 정책을 직접 '집행'하는 기관이 아니라고 본 것이다. 다만 2020년 8월 시행 개정법으로 보호위원회가 중앙행정기관이 되어 정책·제도의 수립·집행 기능을 가지게 되었으므로 현행 기준과는 다를 수 있다(개정 여부 확인).","ce":["공식 정답이다. 출제 기준(개정 전 심의·의결 기구)에서는 정책을 직접 '집행'하는 기능이 없다고 보았으나, 2020.8.5 시행 개정법으로 위원회가 중앙행정기관이 되어 현행 기준으로는 논란 소지가 있다(개정 여부 확인).","보호위원회 기능이다. 개인정보보호에 관한 법령의 해석·운영에 관한 사항을 심의·의결한다.","보호위원회 기능이다. 개인정보 처리에 관한 공공기관 간 의견조정에 관한 사항을 심의·의결한다.","보호위원회 기능이다. 업무 수행에 필요하면 관계 기관 등에 자료제출이나 사실조회를 요구할 수 있다."],"rel":["5-10"],"flag":"법 개정(2020.8.5 시행)으로 현행 기준 ①도 보호위원회 소관 — 정답 논란 소지"},{"n":88,"s":"s5","q":"정보통신서비스 제공자가 이용자에 대한 정보를 이용하려고 수집하는 경우 이용자에게 알리고 동의 받아야 할 사항이 아닌 것은?","c":["개인정보의 수집·이용 목적","동의를 거부할 권리가 있다는 사실 및 동의 거부에 따른 불이익이 있는 경우에는 그 불이익의 내용","수집하는 개인정보의 항목","개인정보의 보유·이용 기간"],"a":1,"e":"시험 당시 정보통신망법 제22조는 정보통신서비스 제공자가 수집·이용 목적, 수집 항목, 보유·이용 기간을 알리고 동의를 받도록 규정했다. 동의 거부권 및 불이익 고지는 개인정보 보호법 제15조의 고지 사항이다. 2020년 8월 개정으로 망법 해당 조항은 개인정보 보호법 특례로 이관되었다(개정 여부 확인).","ce":["고지·동의 사항이다. 시험 당시 정보통신망법 제22조는 개인정보의 수집·이용 목적을 알리고 동의를 받도록 했다.","시험 당시 정보통신망법 제22조의 고지 사항이 아니었다. 동의 거부권과 거부 시 불이익 고지는 개인정보 보호법 제15조의 고지 사항이다(2020.8 개정으로 망법 조항 이관, 개정 여부 확인).","고지·동의 사항이다. 수집하는 개인정보의 항목을 알리고 동의를 받아야 한다.","고지·동의 사항이다. 개인정보의 보유·이용 기간을 알리고 동의를 받아야 한다."],"rel":["5-8"]},{"n":89,"s":"s5","q":"업무연속성관리 및 재난복구계획을 위하여 수행하는 내용 중에서 올바르지 않은 것은 무엇인가?","c":["재난복구서비스 중에 웜사이트는 재난 발생 시 새로운 컴퓨터를 설치할 수 있는 컴퓨터실을 미리 준비해 둔 것으로 별다른 장비는 가지고 있지 않은 것을 의미한다.","업무연속성계획의 접근5단계 방법론에는 프로젝트의 범위 설정 및 기획, 사업영향평가, 복구전략 개발, 복구계획 수립, 프로젝트의 수행 테스트 및 유지 보수로 나눌 수 있다.","재해복구테스트 종류는 체크리스트 방법, 구조적 점검 테스트, 시뮬레이션, 병렬테스트, 전체 시스템 중단 테스트 등이 있다.","업무영향분석의 목적은 운영의 전부 혹은 일부 그리고 컴퓨터서비스가 작동하지 않을 때, 조직을 보호하기 위한 핵심 업무를 파악하는 것이며, 핵심 업무의 정지로 인해 조직에 발생하는 잠재적인 손해 혹은 손실을 파악하는 것이다."],"a":0,"e":"전산실 공간·전원·배선만 준비하고 장비는 없는 형태는 콜드 사이트(Cold Site)이다. 웜 사이트(Warm Site)는 중요 업무 위주로 일부 장비와 네트워크를 갖추고 데이터는 주기적으로 백업해 수일 내 복구하는 방식이다. BCP 5단계, 재해복구 테스트 유형, BIA 목적은 올바른 설명이다.","ce":["올바르지 않다. 공간·전원·배선만 준비하고 장비가 없는 형태는 콜드 사이트이며, 웜 사이트는 중요 업무 위주로 일부 장비·네트워크를 갖춰 수일 내 복구하는 방식이다.","올바르다. BCP 접근 5단계는 범위 설정·기획 → 사업영향평가 → 복구전략 개발 → 복구계획 수립 → 테스트·유지보수이다.","올바르다. 재해복구 테스트에는 체크리스트, 구조적 점검(탁상), 시뮬레이션, 병렬 테스트, 전체 중단 테스트가 있다.","올바르다. 업무영향분석(BIA)은 핵심 업무를 식별하고 그 중단으로 발생하는 잠재적 손실을 파악해 복구 우선순위·RTO를 정하는 것이다."],"rel":["5-3"]},{"n":90,"s":"s5","q":"공공기관에서 개인정보파일을 운용하는 경우에 보호위원회에 등록해야 하는 사항에 포함되지 않는 것은?","c":["개인정보파일의 명칭","개인정보파일에 기록되는 개인정보 항목","개인정보를 일시적으로 제공하는 경우 그 제공받는 자","개인정보파일로 보유하고 있는 개인정보의 정보주체 수"],"a":2,"e":"개인정보 보호법 제32조의 등록 사항은 파일 명칭, 운영 근거·목적, 기록되는 개인정보 항목, 처리 방법, 보유 기간, 개인정보를 '통상적 또는 반복적으로' 제공하는 경우 그 제공받는 자, 시행령상 정보주체 수 등이다. 일시적 제공의 수령자는 등록 사항이 아니다.","ce":["등록 사항이다. 개인정보파일의 명칭은 개인정보 보호법 제32조 등록 사항이다.","등록 사항이다. 개인정보파일에 기록되는 개인정보의 항목은 제32조 등록 사항이다.","등록 사항이 아니다. 법은 개인정보를 '통상적 또는 반복적으로' 제공하는 경우의 제공받는 자를 등록하게 하며, 일시적 제공은 해당하지 않는다.","등록 사항이다. 개인정보파일로 보유하고 있는 정보주체의 수는 시행령상 등록 사항이다."],"rel":["5-14"]},{"n":91,"s":"s5","q":"위험분석 결과 식별된 위험에 대한 처리 전략과 위험별 위험처리를 위한 적절한 (개인)정보보호 대책을 선정한 내용 중에서 올바르지 않은 것은?","c":["위험감소: 비밀번호 도용의 위험을 줄이기 위해 개인정보처리시스템 등 중요한 시스템의 로그인 비밀번호 복잡도 길이를 3가지 문자조합, 8글자 이상 강제 설정하도록 비밀번호 설정 모듈을 개발하여 적용한다.","위험수용: 유지보수 등 협력업체, 개인정보 처리 수탁자 중에서 직접 모두 관리·감독할 수 없어 개인정보를 대량으로 처리하고 있는 IT 수탁사를 대상으로 관리·감독하고 나머지 수탁자는 이슈가 발생될 경우에만 관리·감독한다.","위험전가: 중요정보 및 개인정보 유출 시 손해 배상 소송 등에 따른 비용 손실을 줄이기 위해 관련 보험에 가입한다.","위험회피: 회사 홍보용 인터넷 홈페이지에서는 회원관리에 따른 위험이 존재하므로 회원 가입을 받지 않는 것으로 변경하고 기존 회원 정보는 모두 파기 처리한다."],"a":1,"e":"수탁자 관리·감독은 개인정보 보호법 제26조에 따른 법적 의무이므로, 일부 수탁자를 이슈 발생 시에만 감독하는 것은 위험수용 대상이 될 수 없다(법적 요구사항 위반 위험은 수용 불가). 비밀번호 복잡도 강화(감소), 보험 가입(전가), 회원 가입 폐지(회피)는 적절한 처리 전략이다.","ce":["적절하다. 비밀번호 복잡도·길이를 강제하는 모듈을 적용해 도용 가능성을 낮추는 것은 위험감소 전략이다.","올바르지 않다. 수탁자 관리·감독은 개인정보 보호법 제26조의 법적 의무이므로, 일부 수탁자를 감독하지 않는 것은 위험수용 대상이 될 수 없다.","적절하다. 보험 가입으로 유출 시 손해배상 비용 부담을 제3자(보험사)에게 넘기는 것은 위험전가 전략이다.","적절하다. 위험을 발생시키는 회원 가입 기능 자체를 없애고 기존 정보를 파기하는 것은 위험회피 전략이다."],"rel":["5-2"]},{"n":92,"s":"s5","q":"경영진 참여에 대한 사항으로 가장 부적절한 것은?","c":["경영진 참여가 이루어질 수 있도록 보고, 의사 결정 등의 책임과 역할을 문서화하지 않았지만 정기적으로 보고하고 있다.","경영진이 직접 정보보호 활동에 참여도 가능하지만 정보보호 위원회 등을 구성하여 중요한 의사결정 등을 결정할 수 있다.","조직의 규모 및 특성에 맞게 보고 및 의사결정 절차, 대상, 주기 등을 결정할 수 있다.","경영진 참여가 원칙이나, 내부 위임전결 등의 규정이 있는 경우에는 정보보호를 담당하고 있는 책임자가 경영진의 의사결정을 대행할 수 있다."],"a":0,"e":"ISMS-P 인증기준 1.1.1(경영진의 참여)은 경영진이 참여할 수 있도록 보고 및 의사결정 등의 책임과 역할을 문서화하도록 요구하므로, 문서화 없이 보고만 하는 ①은 결함 사례이다. 정보보호위원회 구성, 조직 특성에 맞는 절차 결정, 위임전결 규정에 따른 대행은 허용된다.","ce":["공식 정답이다. ISMS-P 1.1.1은 경영진 참여를 위한 보고·의사결정 등 책임과 역할을 문서화하도록 요구하므로, 문서화 없이 보고만 하는 것은 결함이다.","적절하다. 경영진이 직접 참여할 수도 있고 정보보호위원회 등을 구성해 중요한 의사결정을 할 수도 있다.","적절하다. 조직 규모·특성에 맞게 보고·의사결정 절차, 대상, 주기 등을 정할 수 있다.","공식적으로는 적절한 사항으로 처리된다. 내부 위임전결 규정이 있으면 정보보호 책임자가 의사결정을 대행할 수 있다고 보나, 인증기준 해설상 논란 소지가 있다."],"rel":["5-11"],"flag":"④ 위임전결 대행은 인증기준 해설상 논란 소지 있으나 공식 정답 1번"},{"n":93,"s":"s5","q":"다음 중 법률에 근거하여 운영되고 있는 정보보호 및 개인정보보호 관련 제도 중에서 자율제도가 아닌 의무제도에 해당하는 것은?","c":["정보보호 준비도 평가","클라우드 보안인증제","정보보호 공시제도","주요정보통신기반시설 취약점의 분석·평가"],"a":3,"e":"정보통신기반보호법 제9조에 따라 관리기관의 장은 주요정보통신기반시설의 취약점을 정기적으로 분석·평가해야 하는 법적 의무가 있다. 정보보호 준비도 평가, 클라우드 보안인증(민간), 정보보호 공시는 시험 당시 자율 제도였으며, 정보보호 공시는 2022년부터 일정 기준 이상 기업에 의무화되었다(개정 여부 확인).","ce":["자율제도이다. 정보보호 준비도 평가는 기업이 신청해 정보보호 수준을 평가받는 자율 제도였다.","자율제도이다. 클라우드 보안인증(CSAP)은 민간 클라우드 사업자가 공공기관 서비스를 위해 신청하는 인증으로, 시험 당시 법적 의무 제도가 아니었다.","시험 당시 자율제도였다. 정보보호 공시는 2022년부터 일정 기준 이상 기업에 의무화되었다(개정 여부 확인).","의무제도이다. 정보통신기반보호법 제9조에 따라 관리기관의 장은 주요정보통신기반시설의 취약점을 정기적으로 분석·평가해야 한다."],"rel":["5-13","5-10"]},{"n":94,"s":"s5","q":"개인정보처리자는 다음 지문의 사항이 포함된 것을 정하고 이를 정보주체가 쉽게 확인할 수 있게 공개하도록 되어 있다. 다음 지문의 사항이 포함된 문서의 법률적 명칭은 무엇인가?","c":["개인정보 보호정책","표준 개인정보 보호지침","개인정보 보호지침","개인정보 처리방침"],"a":3,"e":"개인정보 보호법 제30조에 따라 개인정보처리자는 처리 목적, 처리·보유 기간, 제3자 제공, 위탁, 정보주체의 권리·의무 및 행사방법 등을 포함한 '개인정보 처리방침'을 정해 공개해야 한다. 표준 개인정보 보호지침은 보호위원회가 정하는 고시이다.","ce":["개인정보 보호정책은 법률상 명칭이 아니다. 제30조가 규정하는 공개 문서의 명칭은 '개인정보 처리방침'이다.","표준 개인정보 보호지침은 개인정보보호위원회가 제12조에 따라 정하는 고시로, 개인정보처리자가 정해 공개하는 문서가 아니다.","개인정보 보호지침은 기관 내부 규정 성격의 명칭일 뿐, 제30조에 따라 정보주체에게 공개하는 문서의 법률적 명칭이 아니다.","개인정보 보호법 제30조에 따라 처리 목적·보유기간·제3자 제공·위탁·정보주체 권리 등을 포함해 공개하는 문서는 '개인정보 처리방침'이다."],"rel":["5-14"],"box":"개인정보의 처리 목적\n개인정보의 처리 및 보유 기간\n개인정보의 제3자의 제공에 관한 사항(해당되는 경우에만 정한다.)\n개인정보처리의 위탁에 관한 사항(해당되는 경우에만 정한다.)\n정보주체의 권리의무 및 그 행사방법에 관한 사항\n그 밖에 개인정보의 처리에 관하여 대통령령으로 정한 사항"},{"n":95,"s":"s5","q":"정보통신망을 통해 이용자가 원하지 않음에도 불구하고 일방적으로 전송되는 영리목적의 광고성 정보인 스팸에 관련된 내용 중에서 잘못된 것은?","c":["휴대전화 등의 앱 푸시 알람 ON/OFF 기능은 광고성 정보 수신 동의와 동일하므로 푸시 알람을 승인한 경우에는 광고성 정보를 전송하는 것이 가능하다.","전송자가 제공하는 재화 또는 서비스에 대한 조건 또는 특징에 대한 변경 안내 정보(회원 등급 변경·포인트 소멸 안내 등)는 영리 목적 광고성 정보의 예외이다.","광고성 정보를 전송하려면 사전에 문서(전자문서 포함) 또는 구술 등의 방법으로 수신자에게 명시적으로 수신 동의를 받아야 한다.","오후 9시부터 그 다음 날 오전 8시까지 전자적 전송매체를 이용하여 광고성 정보를 전송하려는 자는 수신자에게 별도의 사전 동의를 받아야 한다."],"a":0,"e":"앱 푸시 알림 허용(ON)은 단말기 기능 설정일 뿐 광고성 정보 수신 동의로 볼 수 없으므로, 앱 푸시로 광고를 보내려면 별도의 광고성 정보 수신 동의를 받아야 한다. 거래 조건 변경 안내는 광고성 정보의 예외, 사전 명시적 동의와 야간(21시~08시) 별도 동의는 정보통신망법 제50조 규정이다(개정 여부 확인).","ce":["잘못된 설명이다. 앱 푸시 알림 허용은 단말기 기능 설정일 뿐이므로 광고성 정보를 보내려면 별도의 광고성 정보 수신 동의를 받아야 한다.","옳은 설명이다. 회원 등급 변경·포인트 소멸 안내 등 거래 조건 변경 안내는 영리목적 광고성 정보의 예외로 본다.","옳은 설명이다. 정보통신망법 제50조에 따라 광고성 정보 전송 전 수신자의 명시적 사전 동의를 받아야 한다.","옳은 설명이다. 오후 9시부터 다음 날 오전 8시까지 전자적 전송매체로 광고를 보내려면 별도의 사전 동의가 필요하다(개정 여부 확인)."],"rel":["5-10"]},{"n":96,"s":"s5","q":"다음은 개인정보보호법상 개인정보처리 위탁에 관한 설명이다. 가장 거리가 먼 것은?","c":["개인정보처리자가 제3자에게 개인정보의 처리 업무를 위탁하는 경우에는 일정한 내용이 포함된 문서에 의하여야 한다.","개인정보처리자가 재화 또는 서비스를 홍보하거나 판매를 권유하는 업무를 위탁하는 경우에는 위탁에 대해 정보주체의 동의를 받아야 한다.","위탁자는 업무위탁으로 인하여 정보주체의 개인정보가 분실·도난·유출·변조 또는 훼손되지 아니하도록 수탁자를 교육하고, 처리 현황 점검 등 수탁자가 개인정보를 안전하게 처리하는지를 감독하여야 한다.","수탁자가 위탁받은 업무와 관련하여 개인정보를 처리하는 과정에서 이 법을 위반하여 발생한 손해배상책임에 대해서는 수탁자를 개인정보처리자의 소속 직원으로 본다."],"a":1,"e":"개인정보 보호법 제26조 제3항은 홍보·판매 권유 업무를 위탁하는 경우 위탁 업무 내용과 수탁자를 정보주체에게 '알려야' 한다고 규정할 뿐, 동의를 받도록 하지 않는다. 문서에 의한 위탁, 수탁자 교육·감독, 손해배상 시 수탁자를 소속 직원으로 간주하는 규정은 옳다.","ce":["옳은 설명이다. 업무 위탁은 목적 외 처리 금지, 기술적·관리적 보호조치 등이 포함된 문서에 의해야 한다(제26조 제1항).","거리가 멀다. 홍보·판매 권유 업무를 위탁하는 경우 위탁 업무 내용과 수탁자를 정보주체에게 '알려야' 할 뿐 동의를 받을 의무는 없다.","옳은 설명이다. 위탁자는 수탁자를 교육하고 처리 현황 점검 등으로 안전한 처리 여부를 감독해야 한다.","옳은 설명이다. 수탁자가 법을 위반해 발생한 손해배상책임에 대해서는 수탁자를 개인정보처리자의 소속 직원으로 본다."],"rel":["5-8"]},{"n":97,"s":"s5","q":"「정보통신기반 보호법」에 관련된 사항으로 적절하지 않은 것은?","c":["주요정보통신기반시설보호계획에는 주요정보통신 기반시설의 취약점 분석·평가에 관한 사항이 포함되어 있다.","주요정보통신기반시설보호대책의 미흡으로 국가 안전보장이나 경제사회 전반에 피해가 우려된다고 판단하여 그 보완을 명하는 경우 주요정보통신 기반시설의 침해사고 예방 및 복구 등의 업무에 대한 기술적 지원을 요청할 수 있다.","침해사고가 발생하여 소관 주요정보통신기반시설이 교란·마비 또는 파괴된 사실을 인지한 때에는 관계 행정기관, 수사기관 또는 인터넷진흥원에 그 사실을 통지하여야 한다.","금융·통신 등 분야별 정보통신기반시설을 위하여 취약점 및 침해요인과 그 대응방안에 관한 정보 제공, 침해사고가 발생하는 경우 실시간 경보·분석체계 운영 업무를 수행하는 사이버안전센터를 구축·운영할 수 있다."],"a":3,"e":"금융·통신 등 분야별로 취약점·침해요인 정보 제공과 실시간 경보·분석체계를 운영하는 조직은 정보통신기반보호법 제16조의 '정보공유·분석센터(ISAC)'이다. 보호계획의 취약점 분석·평가 포함, 기술지원 요청, 침해사고 통지 의무는 법 조문과 일치한다(개정 여부 확인).","ce":["적절하다. 주요정보통신기반시설보호계획에는 취약점 분석·평가에 관한 사항이 포함된다.","적절하다. 보호대책 미흡으로 보완을 명하는 경우 등에는 침해사고 예방·복구 업무에 대한 기술적 지원을 요청할 수 있다.","적절하다. 소관 기반시설의 교란·마비·파괴 사실을 인지하면 관계 행정기관, 수사기관 또는 인터넷진흥원에 통지해야 한다.","적절하지 않다. 금융·통신 등 분야별로 취약점 정보 제공과 실시간 경보·분석체계를 운영하는 조직은 '정보공유·분석센터(ISAC)'이다(제16조)."],"rel":["5-13"]},{"n":98,"s":"s5","q":"다음은 개인정보처리시스템을 기획하는 단계에서 개인정보 보호를 위해 검토하고 확인하여야 할 기본원칙에 관한 설명이다. 잘못된 것끼리 묶은 것은?","c":["가, 나","다, 라","마, 바","사, 아"],"a":1,"e":"개인정보 파기 방법은 사업 진행 상황에 따라 사후에 정하는 것이 아니라 기획 단계에서 보유기간과 파기 절차·방법을 미리 정해야 한다(다). 주민등록번호는 법령 근거 없이 처리할 수 없어 주민번호 인증을 통한 회원가입은 허용되지 않는다(라). 법령 검토, 수집 최소화, 기본 보안대책, 암호 알고리즘 결정, 처리방침 수립, 영향평가 고려는 올바른 원칙이다.","ce":["가(법령·지침 세부 검토)와 나(처리 목적 명확화를 통한 수집 최소화)는 기획 단계의 올바른 원칙이다.","다: 파기 방법은 사업 진행에 따라 사후 결정하는 것이 아니라 기획 단계에서 보유기간·파기 절차를 미리 정해야 한다. 라: 주민번호는 법령 근거 없이 처리할 수 없어 주민번호 인증 회원가입은 허용되지 않는다.","마(접근권한 등 기본 보안대책)와 바(전송·저장 시 암호화 알고리즘·방식 결정)는 기획 단계의 올바른 원칙이다.","사(처리방침 수립)와 아(공공기관 시스템의 영향평가 고려)는 기획 단계의 올바른 원칙이다."],"rel":["5-4","5-9"],"box":"가. 개인정보보호 관련 법령 및 지침 등 관련 규정을 세부적으로 검토\n나. 개인정보 수집 최소화를 위해 개인정보 처리 목적을 명확히 하고 수집\n다. 개인정보 목적 달성 시 파기 방법은 사업진행 상황에 따라 결정\n라. 주민등록번호 인증을 통한 회원가입 방법 제공\n마. 개인정보처리시스템에 대한 접근권한 등 기본적인 보안대책 마련\n바. 개인정보 전송 및 저장 시 적용할 암호화 알고리즘과 방식 결정\n사. 개인정보처리시스템과 관련된 개인정보 처리방침 수립\n아. 공공기관 개인정보처리시스템과 관련하여서는 개인정보 영향평가 고려"},{"n":99,"s":"s5","q":"개인정보보호법 상 개인정보 유출 시 개인정보 처리자가 정보 주체에게 알려야 할 사항으로 옳은 것만을 모두 고르면?","c":["㉠, ㉡","㉢, ㉣","㉠, ㉢","㉡, ㉣"],"a":3,"e":"개인정보 보호법 제34조에 따른 유출 통지 사항은 유출된 개인정보 항목, 유출 시점과 경위, 피해 최소화를 위해 정보주체가 할 수 있는 방법, 처리자의 대응조치 및 피해구제 절차, 피해 신고 접수 담당부서 및 연락처이다. 위탁 현황과 보관·폐기 기간은 통지 사항이 아니다(개정 여부 확인).","ce":["㉡ 유출 시점과 경위는 통지 사항이지만, ㉠ 위탁 현황은 제34조 유출 통지 사항이 아니다.","㉣ 피해 신고 접수 담당부서·연락처는 통지 사항이지만, ㉢ 보관·폐기 기간은 통지 사항이 아니다.","㉠ 위탁 현황과 ㉢ 보관·폐기 기간은 모두 제34조 유출 통지 사항이 아니다.","제34조 통지 사항은 유출 항목, 유출 시점과 경위(㉡), 피해 최소화 방법, 대응조치·피해구제 절차, 피해 신고 접수 담당부서·연락처(㉣)이다(개정 여부 확인)."],"rel":["5-9"],"box":"㉠ 유출된 개인정보의 위탁 현황\n㉡ 유출된 시점과 그 경위\n㉢ 개인정보 보관 폐기 기간\n㉣ 정보 주체에게 피해가 발생한 경우 신고 등을 접수할 수 있는 담당 부서 및 연락처"},{"n":100,"s":"s5","q":"정보통신서비스 제공자 등은 개인정보의 분실·도난·누출 사실을 안 때에는 지체 없이 다음 각 호의 모든 사항을 해당 이용자에게 알리고 방송통신위원회 또는 한국인터넷진흥원에 신고하여야 하며, 정당한 사유 없이 그 사실을 안 때부터 24시간을 경과하여 통지·신고해서는 아니 된다. 이때 정당한 사유에 관하여 잘못 설명된 것은?","c":["단전, 홍수, 폭설 등의 천재지변으로 인해 24시간 내에 신고가 불가능한 경우, 방송통신위원회 또는 한국인터넷진흥원에 대한 신고지연의 정당한 사유가 될 수 있다.","경찰이 이용자 통지에 대해 보류를 요청한 경우, 수사상의 이유로 이용자에 대한 통지 지연의 정당한 사유가 될 수 있다.","물리적·기술적·관리적인 사유로 통지가 불가능한 경우, 이용자에 대한 통지지연의 정당한 사유가 될 수 있다.","누출 등이 된 개인정보 항목이나 누출 등이 발생한 시점에 대한 파악이 24시간 내에 불가능한 경우, 통지·신고 지연의 정당한 사유가 될 수 있다."],"a":3,"e":"유출 항목이나 시점을 24시간 내에 모두 파악하지 못한 경우에도 우선 확인된 사항을 먼저 통지·신고하고 추가로 확인되는 사항을 이후 알려야 하므로, 이는 지연의 정당한 사유가 되지 않는다. 천재지변, 수사기관의 통지 보류 요청, 물리적·기술적 사유로 통지가 불가능한 경우는 정당한 사유로 인정된다(현행은 개인정보 보호법으로 통합·72시간 기준, 개정 여부 확인).","ce":["정당한 사유로 인정된다. 단전·홍수·폭설 등 천재지변으로 24시간 내 신고가 불가능한 경우는 신고 지연의 정당한 사유이다.","정당한 사유로 인정된다. 수사기관이 수사상 이유로 이용자 통지 보류를 요청한 경우는 통지 지연의 정당한 사유이다.","정당한 사유로 인정된다. 연락처 부재 등 물리적·기술적·관리적 사유로 통지가 불가능한 경우는 통지 지연의 정당한 사유이다.","잘못 설명되었다. 유출 항목·시점을 24시간 내에 다 파악하지 못해도 확인된 사항을 먼저 통지·신고하고 추가 확인분은 이후 알려야 하므로 지연 사유가 아니다(현행 기준은 개인정보 보호법 72시간, 개정 여부 확인)."],"rel":["5-9"]}]},{"id":"2020-05-30","title":"2020년 5월 30일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"리눅스 서버에서 xinetd 데몬을 이용한 접근 제어 시 지정된 원격지 IP 주소 대역에 대해 접근을 허락할 때 xinetd.conf 파일에서 사용하는 옵션은?","c":["enable","allow","enable_access","only_from"],"a":3,"e":"xinetd 설정에서 접근을 허용할 원격 호스트·IP 대역은 only_from 속성으로 지정하고, 거부할 대상은 no_access로 지정한다. allow·enable_access는 xinetd 속성이 아니며, allow는 TCP Wrapper(hosts.allow)의 개념이다.","ce":["enable은 xinetd 속성이 아니며, 서비스 활성화 여부는 'disable = no/yes' 속성으로 지정한다. 접근 허용 IP 대역 지정 기능은 없다.","allow는 TCP Wrapper의 /etc/hosts.allow 파일 개념이다. xinetd.conf에는 allow라는 속성이 없고 허용 대상은 only_from으로 쓴다.","enable_access라는 xinetd 속성은 존재하지 않는다. xinetd의 접근 제어 속성은 허용 only_from, 거부 no_access, 시간 제한 access_times이다.","only_from은 xinetd에서 서비스 접속을 허용할 호스트명·IP·네트워크 대역(예: 192.168.1.0/24)을 지정하는 속성이므로 정답이다."],"rel":["1-16"]},{"n":2,"s":"s1","q":"i-node가 가지고 있지 않은 정보는?","c":["파일 이름","파일의 링크 수","파일 크기","마지막으로 수정된 시간"],"a":0,"e":"i-node는 파일 소유자·권한·크기·링크 수·타임스탬프(atime/mtime/ctime)·데이터 블록 포인터 등 메타데이터를 담는다. 파일 이름은 i-node가 아니라 디렉터리 엔트리(파일명↔i-node 번호 매핑)에 저장된다.","ce":["파일 이름은 i-node가 아니라 디렉터리 파일의 엔트리(파일명 ↔ i-node 번호)에 저장된다. 그래서 하드 링크로 한 i-node에 여러 이름을 붙일 수 있다.","링크 수(link count)는 i-node에 저장되는 메타데이터로, 해당 i-node를 가리키는 하드 링크 개수이며 0이 되면 데이터 블록이 해제된다.","파일 크기(바이트 수)는 i-node에 저장되는 대표적 메타데이터로, ls -l에서 보이는 크기 값의 출처이다.","마지막 수정 시간(mtime)은 atime·ctime과 함께 i-node의 타임스탬프 필드에 저장된다."],"rel":["1-18"]},{"n":3,"s":"s1","q":"/etc/shadow 파일의 일부분이다. 이를 통해 알 수 있는 내용이 아닌 것은?","c":["sec_admin 사용자는 비밀번호 변경 후 최대 30일간 이를 사용할 수 있다.","sys_admin 사용자의 비밀번호는 아직 부여되지 않은 상태이며, 계정은 막혀 있다.","prog_user 사용자는 비밀번호 유효기간이 만료되기 7일 전부터 비밀번호 만료에 관한 경고메시지를 받는다.","prog_user 사용자는 비밀번호를 변경한 후 3일 이내에 자신의 비밀번호를 변경할 수 있다."],"a":3,"e":"shadow 필드는 계정:암호:최종변경일:최소사용기간:최대사용기간:경고일:비활성일:만료일 순이다. prog_user의 최소사용기간이 3이므로 변경 후 3일 이내에는 비밀번호를 다시 변경할 수 없어 ④가 틀렸다. sec_admin 최대 30일, sys_admin의 '!!'(암호 미설정·잠김), prog_user 경고 7일은 모두 맞는 해석이다.","ce":["sec_admin의 다섯째 필드(최대 사용 기간)가 30이므로 비밀번호 변경 후 최대 30일간 사용 가능하다는 해석은 옳다.","sys_admin의 암호 필드 '!!'는 비밀번호가 설정되지 않아 로그인할 수 없는 잠긴 상태를 뜻하므로 옳은 해석이다.","prog_user의 여섯째 필드(경고 기간)가 7이므로 만료 7일 전부터 경고 메시지를 받는다는 해석은 옳다.","prog_user의 넷째 필드(최소 사용 기간)가 3이므로 변경 후 3일 동안은 비밀번호를 다시 바꿀 수 없다. '3일 이내에 변경할 수 있다'는 반대로 해석한 틀린 내용이다."],"rel":["1-6"],"box":"sys_admin:!!:15265:0:99999:7:0:11423:\nsec_admin:$1$Elnjin$Excskscumink:15860:0:30:10:::\nprog_user:$1$LFNJHS$gGksceeskekks:15711:3:30:7::18108:"},{"n":4,"s":"s1","q":"파일 시스템이란 운영체제가 파일을 시스템의 디스크 상에 구성하는 방식을 말한다. 운영체제는 시스템의 디스크 파티션 상에 파일들을 일정한 규칙을 가지고 저장하는데 파일 시스템은 이러한 규칙들의 방식을 제시하는 역할을 한다. 다음 중 윈도우 운영체제에서 사용하는 파일 시스템이 아닌 것은?","c":["FAT16","FAT32","EXT3","NTFS"],"a":2,"e":"EXT3는 리눅스의 저널링 파일 시스템(EXT2 확장)이다. FAT16·FAT32·NTFS는 윈도우가 사용하는 파일 시스템이다.","ce":["FAT16은 MS-DOS·초기 윈도우에서 쓰던 파일 시스템으로 윈도우가 지원한다. 16비트 클러스터 주소로 볼륨 최대 2GB 수준의 제약이 있다.","FAT32는 윈도우 95 OSR2부터 지원한 파일 시스템으로 USB 메모리 등에서 널리 쓰이며, 단일 파일 4GB 제한이 있다.","EXT3는 리눅스용 파일 시스템(EXT2에 저널링 추가)으로 윈도우 기본 파일 시스템이 아니므로 정답이다.","NTFS는 윈도우 NT 계열의 기본 파일 시스템으로 ACL 기반 권한, 저널링($LogFile), EFS 암호화 등을 지원한다."],"rel":["1-18"]},{"n":5,"s":"s1","q":"좀비 프로세스를 확인하고 중지시키기 위한 UNIX 명령어에 대한 설명으로 올바른 것은?","c":["ps 명령어 실행 후 STAT 값이 Z로 표시되는 프로세스가 좀비 프로세스이며, kill 명령어 사용","ss 명령어 실행 후 STAT 값이 B로 표시되는 프로세스가 좀비 프로세스이며, kill 명령어 사용","ps 명령어 실행 후 STAT 값이 B로 표시되는 프로세스가 좀비 프로세스이며, halt 명령어 사용","zs 명령어 실행 후 STAT 값이 Z로 표시되는 프로세스가 좀비 프로세스이며, halt 명령어 사용"],"a":0,"e":"ps 출력의 STAT 필드에서 Z(defunct)가 좀비 프로세스이며, kill 명령으로 부모 프로세스에 신호를 보내 정리한다. halt는 시스템 종료 명령이고, zs 명령어는 존재하지 않는다.","ce":["ps 출력의 STAT 값 Z(defunct)가 좀비 프로세스이며, kill로 부모 프로세스에 신호를 보내 wait()로 회수시키거나 부모를 종료해 정리하므로 정답이다.","ss는 소켓 상태를 보는 명령어이고, 좀비 상태 코드는 B가 아니라 Z이다.","좀비 상태 코드는 B가 아니라 Z이며, halt는 시스템 전체를 종료하는 명령이라 특정 좀비 프로세스 정리 수단이 아니다.","zs라는 표준 UNIX 명령어는 없고(ps 사용), halt는 시스템 종료 명령이라 좀비 프로세스 정리에 쓰지 않는다."],"rel":["1-16"]},{"n":6,"s":"s1","q":"매일 오전 8시 40분에 /usr/logreport.sh 스크립트가 실행되도록 하기 위해 contab에 넣을 설정 내용으로서 적절한 것은?","c":["* 40 08 * * -exec {/usr/logreport.sh}","40 08 * * * /usr/logreport.sh","* * * 08 40 /usr/logreport.sh","* * * 08 40 -exec {/usr/logreport.sh}"],"a":1,"e":"crontab 필드 순서는 분 시 일 월 요일 명령이므로 '40 08 * * * /usr/logreport.sh'가 매일 08:40 실행이다. ③은 월 필드에 08, 요일 필드에 40을 넣은 잘못된 형식이며 -exec는 crontab 문법이 아니다.","ce":["필드가 '* 40 08 * *'로 시작해 분 자리에 *가 들어가 순서가 어긋났고, -exec {…}는 find 명령의 옵션으로 crontab 문법이 아니다.","crontab 필드 순서 '분 시 일 월 요일 명령'에 따라 40(분) 08(시) * * *(매일·매월·모든 요일) 뒤에 스크립트 경로를 쓴 올바른 형식이므로 정답이다.","'* * * 08 40'은 월 필드에 08, 요일 필드에 40을 넣은 것으로, 요일 값 범위(0~7)를 벗어나며 8시 40분 의미가 되지 않는다.","월·요일 필드에 08·40을 넣은 잘못된 순서이고, -exec {…}는 find 명령 문법이라 crontab에서 쓰지 않는다."],"rel":["1-16"]},{"n":7,"s":"s1","q":"다음 지문에서 설명하는 유닉스 시스템 관리자용 명령어는?","c":["df","ps","file","find"],"a":0,"e":"df(disk free)는 마운트된 파일 시스템별 전체·사용·가용 블록과 (df -i로) i-node 수를 슈퍼블록 정보에서 읽어 보여준다. ps는 프로세스 상태, file은 파일 유형 판별, find는 파일 검색 명령이다.","ce":["df(disk free)는 슈퍼블록 정보를 읽어 마운트된 파일 시스템별 사용·가용 블록 수와(df -i) i-node 수를 보여주므로 지문과 일치한다.","ps는 현재 실행 중인 프로세스의 PID·상태·CPU 사용 등을 보여주는 명령으로 디스크 블록 정보와 무관하다.","file은 파일 내용의 매직 넘버를 보고 파일 유형(텍스트·ELF 실행 파일 등)을 판별하는 명령이다.","find는 이름·권한·소유자·시간 등 조건으로 파일을 검색하는 명령으로 가용 블록 수를 알려주지 않는다."],"rel":["1-16"],"box":"슈퍼 블록에서 카운트하고 있는 마운트 된 파일 시스템, 디렉터리에서 사용 가능한 디스크 블록과 free node 수를 알려 줌"},{"n":8,"s":"s1","q":"다음 중 버퍼 오버플로우(Buffer Overflow)에 대한 대책으로 옳지 않은 것은?","c":["경계 검사를 하는 컴파일러 및 링크를 사용한다.","경계를 검사하는 함수를 사용한다.","운영체제 커널 패치를 실시한다.","최대 권한으로 프로그램을 실행한다."],"a":3,"e":"버퍼 오버플로우 공격이 성공하면 해당 프로세스 권한으로 코드가 실행되므로 최소 권한으로 실행해야 피해를 줄일 수 있다. 경계 검사 컴파일러(StackGuard 등), strncpy 같은 안전 함수, 커널 패치(스택 실행 방지·ASLR)는 올바른 대책이다.","ce":["경계 검사를 삽입하는 컴파일러·링커(StackGuard 카나리, -fstack-protector 등)는 스택 오버플로우를 탐지·차단하는 올바른 대책이다.","strcpy·gets 대신 strncpy·fgets·snprintf 같은 길이를 검사하는 함수를 쓰는 것은 버퍼 오버플로우의 기본 대책이다.","커널 패치로 스택 실행 방지(NX/DEP)·ASLR 같은 메모리 보호 기능을 적용하는 것은 올바른 대책이다.","최대(root) 권한으로 실행하면 오버플로우 성공 시 공격 코드도 최대 권한으로 실행된다. 최소 권한으로 실행해야 하므로 옳지 않은 대책이다."],"rel":["1-10"]},{"n":9,"s":"s1","q":"하이퍼바이저에 대한 내용으로 옳지 않은 것은?","c":["가상머신과 하드웨어 사이에 위치하여 다수의 가상머신들이 각각의 운영체제가 구동될 수 있도록 논리적으로 독립된 가상머신 환경을 제공한다.","주 기능은 CPU, 메모리 등 하드웨어 자원을 각 가상머신에 논리적으로 분할 할당·스케줄링하는 것이다.","하이퍼바이저는 bare-metal 타입, hosted 타입으로 나누어지며, bare-metal 타입은 하드웨어 상에서 동작하는 것이 아니라 호스트 운영체제 위에서 동작한다.","hosted 타입은 VMware Workstation, Parallels Desktop 등이 대표적이다."],"a":2,"e":"bare-metal(Type 1) 하이퍼바이저는 호스트 OS 없이 하드웨어 위에서 직접 동작하며(ESXi, Xen, Hyper-V 등), 호스트 OS 위에서 동작하는 것은 hosted(Type 2)이다. ③은 두 유형을 뒤바꿔 설명했다.","ce":["하이퍼바이저(VMM)는 가상머신과 하드웨어 사이에서 여러 게스트 OS가 독립된 가상 환경에서 동시에 동작하도록 하는 계층이라는 설명은 옳다.","하이퍼바이저의 핵심 기능은 CPU·메모리·I/O 같은 물리 자원을 가상머신별로 분할 할당하고 스케줄링하는 것이라는 설명은 옳다.","bare-metal(Type 1)은 호스트 OS 없이 하드웨어 위에서 직접 동작하고, 호스트 OS 위에서 동작하는 것은 hosted(Type 2)이다. 두 유형을 뒤바꿨으므로 틀린 설명이다.","VMware Workstation·Parallels Desktop·VirtualBox는 호스트 OS 위에서 애플리케이션처럼 동작하는 hosted(Type 2) 하이퍼바이저의 대표 예로 옳다."],"rel":["1-12"]},{"n":10,"s":"s1","q":"다음 중 리눅스에서 Process ID(PID) 1번을 가지고 있는 프로세스는 무엇인가?","c":["init","부트로더","OS 커널","BIOS"],"a":0,"e":"리눅스 커널이 부팅 후 처음 생성하는 사용자 공간 프로세스가 init(최근 배포판은 systemd)이며 PID 1을 갖고 모든 프로세스의 조상이 된다. 부트로더·BIOS는 커널 로딩 이전 단계로 프로세스가 아니다.","ce":["init(최근 배포판은 systemd)은 커널이 부팅 후 처음 실행하는 사용자 공간 프로세스로 PID 1을 가지며 모든 프로세스의 조상이므로 정답이다.","부트로더(GRUB·LILO 등)는 커널을 메모리에 적재하는 부팅 단계 프로그램으로, 커널 실행 전에 동작하므로 PID를 갖지 않는다.","커널 자체는 프로세스 목록에서 PID 1이 아니며, 커널이 만드는 첫 사용자 프로세스가 PID 1(init)이다. 리눅스에서 idle 태스크는 PID 0으로 취급된다.","BIOS는 메인보드 펌웨어로 POST와 부트 장치 선택을 수행할 뿐, OS의 프로세스가 아니다."],"rel":["1-16"]},{"n":11,"s":"s1","q":"다음 지문이 설명하는 것은?","c":["Kerberos","OAuth","EAP","RADIUS"],"a":1,"e":"OAuth는 사용자 비밀번호를 제3자 앱에 넘기지 않고 접근 토큰으로 SNS 등의 자원 접근을 위임하는 개방형 표준이다. Kerberos는 티켓 기반 대칭키 인증, RADIUS는 원격 접속 AAA 프로토콜, EAP는 확장 인증 프레임워크이다.","ce":["Kerberos는 MIT가 개발한 티켓(TGT·서비스 티켓) 기반 대칭키 인증 프로토콜로, SNS 사용자 정보 접근 위임용 OpenAPI 표준이 아니다.","OAuth는 사용자 비밀번호를 넘기지 않고 접근 토큰을 발급해 제3자 앱이 트위터·페이스북 등의 자원에 접근하도록 위임하는 개방형 표준이므로 정답이다.","EAP(Extensible Authentication Protocol)는 PPP·802.1X 등에서 다양한 인증 방식을 담는 확장 인증 프레임워크로 웹 API 권한 위임과 무관하다.","RADIUS는 NAS와 인증 서버 사이의 원격 접속 AAA 프로토콜로, SNS 자원 접근 위임 표준이 아니다."],"rel":["4-9"],"box":"인터넷 애플리케이션에서 사용자 인증에 사용되는 공개 API(OpenAPI)로 구현된 표준 인증 방법이다. 트위터, 페이스북과 같은 SNS 서비스를 다른 애플리케이션 또는 다른 기기(PC, 스마트폰 등)에서 사용자 정보에 접근할 때 사용할 수 있도록 한다."},{"n":12,"s":"s1","q":"윈도우 NTFS에서 모든 파일들과 디렉터리에 대한 정보를 포함하고 있는 것은?","c":["MFT(Master File Table)","FAT(File Allocation Table)","$AttrDef","$LogFile"],"a":0,"e":"NTFS의 MFT는 볼륨 내 모든 파일·디렉터리마다 레코드(속성·위치 정보)를 갖는 핵심 메타데이터 테이블이다. FAT는 FAT 파일시스템의 구조이고, $LogFile은 트랜잭션 저널, $AttrDef는 속성 정의 메타파일이다.","ce":["MFT(Master File Table)는 NTFS 볼륨의 모든 파일·디렉터리마다 레코드를 두고 이름·속성·데이터 위치를 담는 핵심 메타데이터 테이블이므로 정답이다.","FAT(File Allocation Table)는 FAT16·FAT32 파일 시스템의 클러스터 연결 테이블로 NTFS 구조가 아니다.","$AttrDef는 NTFS 메타파일 중 하나로 볼륨에서 쓰는 속성 유형의 이름·번호 등 '속성 정의'만 담는다.","$LogFile은 NTFS의 트랜잭션 저널로 메타데이터 변경을 기록해 장애 복구에 쓰이며, 모든 파일 정보를 담지 않는다."],"rel":["1-18"]},{"n":13,"s":"s1","q":"리눅스 시스템의 /etc/logrotate.conf 파일에서 로그순환 설정을 하려고 한다. 최소 6개월분의 로그를 저장하기 위해 빈칸 ㉠에 들어갈 용어로 적절한 것은?","c":["save","rotate","cycle","minimum"],"a":1,"e":"logrotate에서 'rotate N'은 순환된 로그 파일을 N개 보관하라는 지시어로, monthly와 함께 rotate 6이면 6개월분을 유지한다. save·cycle·minimum은 logrotate 지시어가 아니다.","ce":["save는 logrotate 지시어가 아니다. 보관할 순환 로그 개수는 rotate로 지정한다.","rotate N은 순환된 로그 파일을 N개까지 보관하는 지시어로, monthly와 함께 rotate 6이면 6개월분이 유지되므로 정답이다.","cycle은 logrotate 지시어가 아니다. 순환 주기는 daily·weekly·monthly·yearly로 지정한다.","minimum은 logrotate 지시어가 아니다. 크기 기준 순환은 size·minsize 지시어를 쓴다."],"rel":["1-7"],"box":"/etc/logrotate.conf\nmonthly\n( ㉠ ) 6\ncreate\ncompress\ninclude /etc/logrotate.d"},{"n":14,"s":"s1","q":"FTP 접속기록을 확인할 수 있는 파일은?","c":["xferlog","ftplog","error log","pacct"],"a":0,"e":"xferlog는 FTP 서버의 파일 전송(업로드·다운로드) 및 접속 기록을 남기는 로그 파일이다. pacct는 사용자 명령 실행 기록(프로세스 accounting) 파일이며, ftplog는 표준 로그 파일명이 아니다.","ce":["xferlog는 FTP 서버(wu-ftpd·vsftpd 등)의 파일 업로드·다운로드와 접속 기록을 남기는 로그 파일이므로 정답이다.","ftplog는 표준 FTP 로그 파일명이 아니다. FTP 전송 기록의 표준 로그는 xferlog이다.","error log는 주로 웹 서버(Apache error_log)의 오류 기록 파일로 FTP 접속 기록 파일이 아니다.","pacct는 프로세스 accounting 파일로 사용자가 실행한 명령 기록을 남기며, lastcomm·acctcom으로 조회한다."],"rel":["1-7"]},{"n":15,"s":"s1","q":"다음 지문에서 설명하고 있는 것은?","c":["S/Key 인증","RADIUS","Challenge Response","Kerberos"],"a":1,"e":"RADIUS(Remote Authentication Dial-In User Service)는 Livingston사가 개발한 원격 접속 AAA 프로토콜로, 클라이언트(NAS)/서버 구조에서 PAP·CHAP 등 인증을 중앙집중 처리한다. Kerberos는 MIT가 개발한 티켓 기반 인증이며, S/Key는 일회용 패스워드 방식이다.","ce":["S/Key는 벨코어가 개발한 해시 체인 기반 일회용 패스워드(OTP) 방식으로, ISP 원격 접속용 중앙 인증 서버 프로토콜이 아니다.","RADIUS는 리빙스턴사가 개발한 원격 접속 AAA 프로토콜로, NAS(클라이언트)/서버 구조에서 PAP·CHAP 등으로 사용자를 중앙집중 인증하므로 정답이다.","Challenge-Response는 서버가 난수를 주고 응답을 검증하는 인증 방식(기법)의 이름일 뿐, 특정 회사가 개발한 분산 인증 시스템이 아니다.","Kerberos는 MIT가 개발한 티켓 기반 인증 시스템으로, 리빙스턴사 개발·ISP 전화 접속 인증 서버라는 설명과 맞지 않는다."],"rel":["2-8"],"box":"리빙스턴사(루슨트에 인수)가 개발한 분산 보안 시스템(인증 프로토콜)이다. 통상적으로 ISP에서 사용하는 전화 등에 의한 원격 접속에 대한 인증용 서버를 지칭한다. 분산형 클라이언트/서버 기반의 동작으로 사용자 관리는 중앙집중식으로 수행한다. 인증방법은 PAP, CHAP 등 다양한 방법을 지원한다."},{"n":16,"s":"s1","q":"다음은 윈도우 부팅 순서이다. 올바르게 나열된 것은?","c":["바-다-라-가-마-나","나-바-가-다-라-마","나-바-다-라-가-마","바-가-마-나-다-라"],"a":1,"e":"윈도우(XP 계열) 부팅은 POST → CMOS 설정 적용 → MBR 로드 → NTLDR(BOOT.INI 읽기) → NTDETECT.COM(하드웨어 검사) → NTOSKRNL.EXE(HAL 로드) 순이다. 하드웨어 자가진단(POST)이 가장 먼저이므로 CMOS로 시작하는 ①·④는 틀렸다.","ce":["CMOS(바)로 시작하지만 전원 인가 후 가장 먼저 수행되는 것은 POST(나)이고, NTLDR(다)이 MBR(가)보다 앞설 수 없어 순서가 틀렸다.","POST(나) → CMOS 설정 적용(바) → MBR(가) → NTLDR(다) → NTDETECT.COM(라) → NTOSKRNL.EXE(마) 순서로 정답이다.","POST·CMOS 다음에 NTLDR(다)을 두고 MBR(가)을 뒤로 보냈다. NTLDR은 MBR·부트 섹터가 로드해야 실행되므로 MBR이 먼저다.","CMOS(바)로 시작하고 NTOSKRNL(마) 뒤에 POST(나)가 오는 등, 하드웨어 점검 → 부트 코드 → 커널 로드 흐름과 맞지 않는다."],"rel":["1-17"],"box":"가. MBR - 부팅 매체에 대한 기본적인 파일시스템 정보를 읽는다.\n나. POST - 하드웨어 자체의 시스템에 문제가 없는지 체크한다.\n다. NTLDR - 하드디스크 부팅 파티션에 있는 프로그램으로 윈도우가 부팅될 수 있도록 간단한 파일시스템을 실행하며, BOOT.INI 파일의 내용을 읽는다.\n라. NTDETECT.COM - 설치된 하드웨어를 검사한다.\n마. NTOSKRNL.EXE - HAL.dll을 로드한다.\n바. CMOS - 사용자가 설정한 기본사항을 읽어 시스템에 적용한다."},{"n":17,"s":"s1","q":"Cyber Kill Chain의 단계 중 빈칸 ⓐ, ⓑ에 들어갈 절차로 알맞은 것은?","c":["ⓐ 악성코드 제작(Develop) ⓑ 명령 및 제어(Command &Control)","ⓐ 명령 및 제어(Command &Control) ⓑ 전달(Delivery)","ⓐ 전달(Delivery) ⓑ 명령 및 제어(Command &Control)","ⓐ 전달(Delivery) ⓑ 악성코드 제작(Develop)"],"a":2,"e":"록히드마틴 Cyber Kill Chain은 정찰 → 무기화 → 전달(Delivery) → 취약점 악용 → 설치 → 명령 및 제어(C2) → 목표 실행의 7단계이다. 악성코드 제작은 무기화 단계에 포함되며 별도 단계가 아니다.","ce":["ⓑ 명령 및 제어는 맞지만, ⓐ의 '악성코드 제작'은 무기화(②) 단계에 포함되는 활동으로 별도 단계가 아니다. ③은 전달(Delivery)이다.","명령 및 제어(C2)는 설치 후 ⑥ 단계이고 전달(Delivery)은 무기화 직후 ③ 단계이다. 두 단계의 위치가 뒤바뀌었다.","정찰 → 무기화 → 전달(ⓐ) → 익스플로잇 → 설치 → 명령 및 제어(ⓑ) → 목표 실행의 록히드마틴 7단계와 일치하므로 정답이다.","ⓐ 전달은 맞지만, ⓑ는 설치 후 공격자 서버와 통신 채널을 여는 명령 및 제어(C2)이다. 악성코드 제작은 Kill Chain 단계명이 아니다."],"rel":["1-19"],"box":"① 정찰(Reconnaissance)\n② 무기화(Weaponization)\n③ ( ⓐ )\n④ 취약점 악용(Exploitation)\n⑤ 설치(Installation)\n⑥ ( ⓑ )\n⑦ 목표실행(Action)"},{"n":18,"s":"s1","q":"다음 지문이 설명하는 것은?","c":["CryptoCurrency Hijacking","CryptoCurrency Jacking","Currency Hijacking","CryptoJacking"],"a":3,"e":"크립토재킹(CryptoJacking)은 피해자 PC·서버의 CPU/GPU 자원을 몰래 사용해 암호화폐를 채굴하고 수익을 공격자가 가져가는 공격이다. 나머지 보기는 통용되는 용어가 아니다.","ce":["CryptoCurrency Hijacking은 통용되는 공격 명칭이 아니다. 자원을 몰래 써서 채굴하는 공격의 공식 용어는 CryptoJacking이다.","CryptoCurrency Jacking은 CryptoJacking을 풀어 쓴 듯한 조어로 표준 용어가 아니다.","Currency Hijacking은 통용되는 보안 용어가 아니며, 채굴 공격이라는 의미도 담고 있지 않다.","CryptoJacking(크립토재킹)은 감염 PC·서버·브라우저의 CPU/GPU 자원으로 몰래 암호화폐를 채굴해 공격자 지갑으로 보내는 공격이므로 정답이다."],"rel":["1-19"],"box":"감염 시스템의 리소스를 이용해 가상화폐를 채굴하며 공격자에게 전송하는 사이버 공격을 의미한다."},{"n":19,"s":"s1","q":"실행 레벨은 0부터 6까지 있는데 다음 지문의 빈칸 ㉠, ㉡, ㉢에 해당되는 실행 레벨로 알맞게 짝지어진 것은?","c":["㉠ 실행레벨 0 ㉡ 실행레벨 5 ㉢ 실행레벨 4","㉠ 실행레벨 1 ㉡ 실행레벨 6 ㉢ 실행레벨 3","㉠ 실행레벨 0 ㉡ 실행레벨 5 ㉢ 실행레벨 3","㉠ 실행레벨 1 ㉡ 실행레벨 6 ㉢ 실행레벨 2"],"a":1,"e":"SysV init 실행 레벨은 0 종료, 1 단일 사용자, 2 NFS 미지원 다중 사용자, 3 전체 다중 사용자(텍스트), 5 X11 그래픽, 6 재부팅이다. 레벨 2는 네트워크(NFS) 기능이 빠진 다중 사용자 모드라 ④는 틀렸다.","ce":["실행레벨 0은 시스템 종료(halt), 5는 X윈도 그래픽 다중 사용자, 4는 미사용(사용자 정의)이므로 세 짝 모두 틀렸다.","실행레벨 1은 단일 사용자 모드, 6은 재부팅, 3은 네트워크를 포함한 전체 다중 사용자(텍스트) 모드이므로 정답이다.","㉢ 3은 맞지만 ㉠ 0은 종료(halt), ㉡ 5는 그래픽 다중 사용자 모드라 틀렸다. 단일 사용자는 1, 재부팅은 6이다.","㉠ 1·㉡ 6은 맞지만 ㉢ 2는 NFS 등 네트워크 서비스가 빠진 다중 사용자 모드이다. 전체 서비스 지원 모드는 3이다."],"rel":["1-16"],"box":"㉠ 단일 사용자 모드(Single User Mode)\n㉡ 재부팅(Reboot)\n㉢ 전체 서비스를 지원하는 다중 사용자 모드(Full Multiuser Mode)"},{"n":20,"s":"s1","q":"유닉스 또는 리눅스 시스템에서 SetUID와 SetGID가 설정된 모든 파일을 찾으려고 한다. 명령어가 바르게 기술된 것은?","c":["find / -type f \\(-perm -1000 -o -perm -2000\\) -print","find / -type f \\(-perm -2000 -o -perm -4000\\) -print","find / -type f \\(-perm -100 -o -perm -200\\) -print","find / -type f \\(-perm -200 -o -perm -400\\) -print"],"a":1,"e":"특수 권한 비트는 SetUID=4000, SetGID=2000, Sticky bit=1000이므로 -perm -2000 -o -perm -4000으로 둘 중 하나라도 설정된 파일을 찾는다. ①의 1000은 Sticky bit이고, 100·200·400은 일반 실행·쓰기·읽기 권한 비트이다.","ce":["-perm -1000은 Sticky bit이므로 SetUID를 찾지 못한다. SetGID(2000)만 맞고 SetUID는 4000으로 지정해야 한다.","특수 권한 값 SetUID=4000, SetGID=2000을 -o(OR)로 묶어 둘 중 하나라도 설정된 일반 파일을 찾으므로 정답이다.","100·200은 각각 소유자 실행(x)·쓰기(w) 권한 비트로 특수 권한이 아니다. 특수 권한은 천의 자리(4000·2000·1000)에 표시한다.","200·400은 소유자 쓰기(w)·읽기(r) 권한 비트이다. SetUID·SetGID는 4000·2000이다."],"rel":["1-5","1-16"]},{"n":21,"s":"s2","q":"Smurf 공격을 방지하기 위하여 라우터에서 차단되어야 하는 기능은?","c":["Directed Broadcast","Ingress Filtering","HTTP GET Flooding","ICMP Ping Request"],"a":0,"e":"Smurf 공격은 출발지를 피해자 IP로 위조한 ICMP Echo Request를 네트워크의 Directed Broadcast 주소로 보내 증폭시키므로, 라우터에서 Directed Broadcast 전달을 차단(no ip directed-broadcast)해야 한다. Ingress Filtering은 위조 IP 차단 대책이지 '차단되어야 할 기능'이 아니며, HTTP GET Flooding은 별개의 공격이다.","ce":["Smurf 공격은 출발지를 피해자로 위조한 ICMP Echo Request를 Directed Broadcast 주소로 보내 응답을 증폭하므로, 라우터에서 Directed Broadcast 전달을 차단(no ip directed-broadcast)해야 한다.","Ingress Filtering은 외부에서 들어오는 위조 출발지 IP 패킷을 걸러내는 대책(RFC 2827)으로, 차단해야 할 기능이 아니라 적용해야 할 기능이다.","HTTP GET Flooding은 웹 서버에 대량 GET 요청을 보내는 애플리케이션 계층 DDoS 공격으로 라우터 기능이 아니며 Smurf와 무관하다.","ICMP Ping Request 자체는 정상 진단 기능이다. Smurf 증폭의 핵심은 브로드캐스트 주소로 전달되는 것이므로 차단 대상은 Directed Broadcast이다."],"rel":["2-3","2-12"]},{"n":22,"s":"s2","q":"IPv4의 IP 주소 고갈 및 라우팅 테이블 대형화에 대한 해소책으로 기존의 클래스 기반 IP 주소 체계를 벗어나 서브넷 마스크 정보를 IP 주소와 함께 라우팅 정보로 사용할 수 있게 만든 IP 주소 지정 방식은?","c":["FLSM","CIDR","VLSM","Static Routing"],"a":1,"e":"CIDR(Classless Inter-Domain Routing)은 클래스 구분 없이 '주소/프리픽스 길이' 형태로 할당하고 경로 집약(supernetting)으로 라우팅 테이블 크기를 줄인다. VLSM은 하나의 네트워크 내부에서 가변 길이 서브넷을 쓰는 서브네팅 기법이고, FLSM은 고정 길이 서브넷 방식이다.","ce":["FLSM(Fixed Length Subnet Mask)은 한 네트워크를 같은 크기 서브넷으로 나누는 고정 길이 서브네팅으로, 클래스 체계를 벗어난 라우팅 집약 방식이 아니다.","CIDR(Classless Inter-Domain Routing)은 클래스 구분 없이 '주소/프리픽스 길이'로 할당하고 경로 집약(supernetting)으로 라우팅 테이블을 줄이므로 정답이다.","VLSM(Variable Length Subnet Mask)은 한 네트워크 안에서 서로 다른 길이의 서브넷을 쓰는 서브네팅 기법으로, 인터넷 전체 주소 할당·경로 집약 방식은 CIDR이다.","Static Routing은 관리자가 경로를 수동 설정하는 라우팅 방식으로 IP 주소 지정 방식이 아니다."],"rel":["2-12"]},{"n":23,"s":"s2","q":"다음 지문에서 설명하는 네트워크 기술은?","c":["Bypass","LLCF","Failover","DPDK"],"a":2,"e":"Failover는 이중화 구성에서 주 장비·링크 장애를 감지하면 대기 장비·경로로 자동 전환하는 기능이다. Bypass는 장비 장애 시 트래픽을 우회 통과시키는 기능이고, DPDK는 인텔의 고속 패킷 처리 라이브러리이다.","ce":["Bypass는 보안 장비(IPS 등) 장애 시 트래픽을 장비를 거치지 않고 그대로 통과시켜 서비스 단절을 막는 기능으로, 이중화 경로 전환 기능이 아니다.","LLCF(Link Loss Carry Forward)는 한쪽 포트 링크가 끊기면 반대쪽 포트 링크도 내려 상대 장비가 장애를 인지하게 하는 기능이다. 경로 전환 자체를 수행하지는 않아 가장 적합한 답은 Failover이다.","Failover는 이중화 구성에서 주(Active) 장비·링크 장애를 감지하면 대기(Standby) 장비·경로로 자동 전환하는 기능이므로 정답이다.","DPDK(Data Plane Development Kit)는 인텔이 주도한 사용자 공간 고속 패킷 처리 라이브러리로 장애 감지·경로 전환 기능이 아니다."],"rel":["2-10"],"box":"보안 담당자 A씨는 중요 서비스에 대한 방화벽의 이중화 구성 시 방화벽의 링크 상태를 모니터링해 링크가 다운되었을 경우 경로정보를 변경하도록 하는 네트워크 기능을 적용하고자 한다."},{"n":24,"s":"s2","q":"스니핑 할 수 있는 공격방법과 거리가 먼 것은?","c":["ARP Redirect","Switch Jamming","ARP Spoofing","IP Spoofing"],"a":3,"e":"ARP Redirect·ARP Spoofing은 ARP 캐시를 조작해 트래픽을 공격자 경유로 돌리고, Switch Jamming은 MAC 테이블을 가득 채워 스위치를 허브처럼 동작시켜 스위칭 환경에서 스니핑을 가능하게 한다. IP Spoofing은 출발지 IP를 위조해 신뢰 관계를 악용하는 공격으로 스니핑 수단이 아니다.","ce":["ARP Redirect는 공격자가 자신이 게이트웨이라는 위조 ARP Reply를 보내 트래픽을 자신에게 우회시키는 스니핑 기법이다.","Switch Jamming은 위조 MAC 주소로 스위치의 MAC 테이블을 가득 채워 스위치를 허브처럼 브로드캐스트하게 만드는 스니핑 기법이다.","ARP Spoofing은 대상 호스트의 ARP 캐시를 위조해 트래픽을 공격자 경유로 돌려 엿보는 대표적 스니핑 기법이다.","IP Spoofing은 출발지 IP를 위조해 신뢰 관계를 악용하거나 추적을 피하는 공격으로, 응답이 위조된 주소로 가므로 트래픽을 엿보는 스니핑 수단과 거리가 멀다."],"rel":["2-5"]},{"n":25,"s":"s2","q":"다음 지문에서 설명하고 있는 공격 특징 및 대응방안과 관련성이 가장 높은 것은?","c":["UDP Flooding","SYN Flooding","ICMP Flooding","GET Flooding"],"a":1,"e":"SYN Flooding은 SYN만 대량 전송해 서버의 TCP 연결 대기 큐(Backlog)를 고갈시키는 TCP 스택 자원 소모 공격으로, 출발지별 PPS 임계치·SYN 패킷 헤더(옵션 필드) 검사로 대응한다. GET Flooding은 애플리케이션(HTTP) 계층 공격이고, UDP·ICMP Flooding은 주로 대역폭 소진형이다.","ce":["UDP Flooding은 대량 UDP 패킷으로 회선 대역폭을 고갈시키는 공격으로, TCP 스택 자원 소모나 TCP 옵션 필드 검사와 관련이 없다.","SYN Flooding은 SYN만 대량 전송해 서버 TCP 스택의 연결 대기 큐(Backlog)를 소모시키며, 소스 IP별 PPS 임계치와 SYN 패킷 옵션 필드 검사로 대응하므로 정답이다.","ICMP Flooding은 ICMP 패킷을 대량 전송해 대역폭을 소모하는 공격으로, TCP 스택이나 TCP 옵션 필드와 무관하다.","GET Flooding은 TCP 연결을 정상적으로 맺은 뒤 HTTP GET 요청을 반복하는 애플리케이션 계층 공격으로, 대응은 요청 빈도·행위 기반 차단이다."],"rel":["2-3"],"box":"웹서버 OS의 TCP 스택(Stack) 자원을 소모하는 특징을 갖는 웹서버 자원 소모 공격으로 사용될 수 있으며, 그 대응방법으로 Anti-DDoS 장비에서 소스 IP별로 PPS 임계치를 설정하거나 패킷 헤더 검사를 통해 정상적인 옵션 필드값을 갖지 않는 비정상 패킷을 차단할 수 있다."},{"n":26,"s":"s2","q":"컴퓨터 및 네트워크에서 서비스가 더 이상 진행되지 못하도록 하는 경우로써 <보기>에서 설명하고 있는 공격 방법으로 가장 옳은 것은?","c":["스머프(smurf) 공격","중간자(man-in-the-middle) 공격","포맷 스트링(format string) 공격","포맷 스트링(format string) 공격"],"a":0,"e":"스머프 공격은 출발지를 피해자 IP로 위조한 ICMP Echo Request를 브로드캐스트로 보내 다수 노드의 Echo Reply가 피해자에게 몰리게 하는 DoS 공격이다. 중간자 공격은 통신 가로채기, 포맷 스트링은 printf류 형식 지정자 악용 공격으로 DoS 증폭과 무관하다.","ce":["스머프 공격은 출발지를 피해자 IP로 위조한 ICMP Echo Request를 브로드캐스트 주소로 보내, 다수 노드의 Echo Reply가 피해자에게 몰려 과부하를 일으키므로 지문과 일치한다.","중간자 공격은 통신 당사자 사이에 끼어 트래픽을 가로채거나 변조하는 공격으로, ping 응답을 증폭시켜 서비스를 마비시키는 방식이 아니다.","포맷 스트링 공격은 printf류 함수에 %n·%x 같은 형식 지정자를 넣어 메모리를 읽거나 덮어쓰는 프로그램 취약점 공격이다. (원문 복원 오류로 ③·④ 보기가 중복됨)","바로 앞 보기와 같은 '포맷 스트링 공격'이 중복 복원된 것으로, 형식 지정자 악용 공격이라 ICMP 증폭 DoS와 무관하다. 원문의 넷째 보기는 누락되어 판단 근거 없음 — 공식 정답(스머프 공격) 기준."],"rel":["2-3"],"box":"- 핑(ping)을 사용하여 현재 동작 중인 노드가 에코 메시지를 보내게 한다.\n- 공격자가 발신주소를 공격하고자 하는 목적지의 IP 주소로 위장하며 ICMP 에코 메시지를 요청하며 다량의 패킷이 목적지로 전송되도록 한다.\n- 목표시스템은 과부하가 발생하며 정상적인 서비스가 불가능 하게 된다.","flag":"원문 보기 ③·④가 동일(포맷 스트링) — comcbt 관리자 주석: 문제 복원 오류로 3·4번 보기 중복"},{"n":27,"s":"s2","q":"다음 네트워크 공격은 무엇인가?","c":["Ping of death","LAND attack","Teardrop","Smurf attack"],"a":2,"e":"Teardrop은 IP 단편의 Fragment Offset을 겹치거나 틈이 생기게 조작해 재조립 시 오류·과부하를 유발하는 공격이다. Ping of Death는 65,535바이트를 초과하는 ICMP 패킷, LAND는 출발지와 목적지를 동일하게 위조하는 공격이다.","ce":["Ping of Death는 IP 최대 크기 65,535바이트를 넘는 ICMP 패킷을 단편화해 보내 재조립 시 버퍼 오버플로우를 일으키는 공격으로, offset 중첩 조작과는 다르다.","LAND 공격은 출발지 IP·포트를 목적지와 동일하게 위조한 SYN 패킷으로 대상이 자기 자신에게 응답하게 만드는 공격이다.","Teardrop은 IP 단편의 Fragment Offset을 겹치거나 틈이 생기게 조작해 재조립 과정에서 오류·과부하를 유발하므로 정답이다.","Smurf 공격은 ICMP Echo Request를 Directed Broadcast로 보내 응답을 피해자에게 증폭시키는 공격으로 단편화와 무관하다."],"rel":["2-12"],"box":"이 공격은 IP 단편화 과정을 이용하는 것으로 공격자가 전송되는 단편 위치 정보(offset)를 조작하며 단편들이 중첩되거나 빈 패킷을 보내는 것처럼 만들어 공격 대상에게 패킷 데이터 재조립 과정을 혼란스럽게 하며 과부하가 걸리게 하는 서비스 거부 공격 기법이다."},{"n":28,"s":"s2","q":"다음 보기의 내용은 어떤 공격에 대한 특징인가?","c":["Land Attack","Bonk","Boink","Teardrop"],"a":2,"e":"Boink는 Bonk를 변형한 공격으로, 정상 시퀀스 번호로 보내다가 중간중간 시퀀스 번호를 비정상적으로 조작한 패킷을 섞어 재조립에 부하를 준다. Bonk는 처음부터 동일한 시퀀스 번호를 반복 전송하며, Teardrop은 오프셋 중첩을 이용한다.","ce":["Land Attack은 출발지와 목적지 IP·포트를 동일하게 위조하는 공격으로, 시퀀스 번호 조작과는 관계가 없다.","Bonk는 처음부터 동일한 시퀀스 번호(예: 모두 1번)의 패킷을 반복 전송하는 공격이다. 정상 전송 중간에 비정상 번호를 섞는 것은 Boink이다.","Boink는 Bonk의 변형으로, 정상 시퀀스 번호로 보내다가 중간중간 비정상 시퀀스 번호 패킷을 섞어 재조립에 혼란을 주므로 정답이다.","Teardrop은 IP 단편의 Offset 값을 중첩되게 조작하는 공격으로, 지문처럼 정상 전송 후 중간에 번호를 어긋나게 섞는 특징과 구분된다."],"rel":["2-12"],"box":"처음 패킷을 1번으로 보낸 후, 다음 패킷을 100번, 다음 패킷을 200번 등 정상적으로 보내다가 20번째 패킷을 2002, 21번째 패킷을 100, 22번째 패킷을 다시 2002 등으로 중간에 패킷 시퀀스 번호를 비정상적인 상태로 전송하는 공격"},{"n":29,"s":"s2","q":"침입차단시스템(Firewall)의 기능과 가장 거리가 먼 것은?","c":["로깅(logging)과 감사추적(auditing) 기능","네트워크 접근제어 기능","데이터 축약 기능","사용자 인증 기능"],"a":2,"e":"방화벽의 주요 기능은 접근 통제, 사용자 인증, 감사 및 로그 기록, 프록시·NAT 등이다. 데이터 축약(압축)은 방화벽의 기능이 아니다.","ce":["방화벽은 허용·차단된 접속 내역을 기록하는 로깅과 감사 추적 기능을 제공하므로 방화벽의 기능이 맞다.","IP·포트·프로토콜 규칙에 따라 트래픽을 허용·차단하는 네트워크 접근제어가 방화벽의 핵심 기능이다.","데이터 축약(압축)은 전송 최적화 장비나 애플리케이션의 기능으로, 방화벽의 주요 기능(접근제어·인증·감사·NAT)에 속하지 않으므로 정답이다.","방화벽(특히 프록시·애플리케이션 게이트웨이)은 통과하는 사용자를 인증하는 기능을 제공하므로 방화벽의 기능이 맞다."],"rel":["2-9"]},{"n":30,"s":"s2","q":"hosts 파일을 통해 도메인 이름에 대한 IP 주소를 적어두면 이 스푸핑 공격에 대응할 수 있다. 이 공격은 무엇인가?","c":["DNS 스푸핑","IP 스푸핑","ARP 스푸핑","이메일 스푸핑"],"a":0,"e":"DNS 스푸핑은 위조된 DNS 응답으로 도메인을 공격자 IP로 연결시키는 공격이며, 중요 사이트를 hosts 파일에 정적으로 등록하면 DNS 질의보다 우선 적용돼 대응할 수 있다. ARP 스푸핑은 정적 ARP 테이블(arp -s)로 대응한다.","ce":["DNS 스푸핑은 위조 DNS 응답으로 도메인을 공격자 IP에 연결하는 공격이며, hosts 파일에 도메인-IP를 정적으로 적어두면 DNS 질의보다 우선 참조되어 대응할 수 있으므로 정답이다.","IP 스푸핑은 출발지 IP를 위조하는 공격으로, 대응은 Ingress/Egress 필터링과 IP 기반 신뢰 관계 제거이다. hosts 파일과 무관하다.","ARP 스푸핑은 IP-MAC 매핑을 위조하는 공격으로, 대응은 hosts 파일이 아니라 정적 ARP 테이블(arp -s) 설정이다.","이메일 스푸핑은 발신자 주소를 위조하는 공격으로, 대응은 SPF·DKIM·DMARC 같은 발신 도메인 인증이다."],"rel":["2-5","3-7"]},{"n":31,"s":"s2","q":"침입차단시스템(Firewall)의 동작 방식은?","c":["Circuit Gateway","Application Gateway","Packet Filtering","Stateful Inspection"],"a":3,"e":"Stateful Inspection은 패킷 필터링에 세션(상태) 테이블을 추가해 연결 순서에 맞지 않는 패킷을 차단하지만, 페이로드까지 분석하지 않아 데이터 내부 악성 정보 대응은 어렵다. Application Gateway는 7계층 페이로드까지 검사하는 프록시 방식이다.","ce":["Circuit Gateway는 세션(5계층)에서 클라이언트-서버 연결을 중계하는 프록시 방식(SOCKS 등)으로, 패킷 필터링에 상태 추적을 덧붙인 방식이 아니다.","Application Gateway는 7계층 프록시로 페이로드까지 검사하므로, '데이터 내부 악의적 정보 대응이 어렵다'는 지문 단점과 맞지 않는다.","Packet Filtering은 IP·포트 등 헤더만 개별 검사하고 세션 상태를 추적하지 않는다. 지문은 여기에 세션 추적을 추가한 방식을 묻는다.","Stateful Inspection은 패킷 필터링에 상태(세션) 테이블을 더해 순서에 어긋나는 패킷을 차단하지만 페이로드는 깊이 보지 않아 데이터 내부 공격 대응이 어려우므로 정답이다."],"rel":["2-9"],"box":"- 패킷의 헤더 내용을 분석하여 순서에 위배되는 패킷 차단\n- 패킷 필터링 방식에 비해 세션 추적 기능 추가\n- 데이터 내부에 악의적인 정보를 포함할 수 있는 프로토콜에 대한 대응이 어려움"},{"n":32,"s":"s2","q":"다음에서 설명하고 있는 기술은?","c":["ATP","MPI","DPI","SPI"],"a":2,"e":"DPI(Deep Packet Inspection)는 헤더뿐 아니라 페이로드까지 분석해 애플리케이션을 식별하고 보안·QoS·유해 콘텐츠 차단에 활용하는 기술이다. SPI(Stateful Packet Inspection)는 헤더와 세션 상태까지만 검사한다.","ce":["ATP(Advanced Threat Protection)는 샌드박스 등으로 APT·지능형 위협을 방어하는 솔루션군을 뜻하며, 페이로드 검사로 애플리케이션을 식별하는 트래픽 분석 기술 자체가 아니다.","MPI(Message Passing Interface)는 병렬 컴퓨팅의 프로세스 간 메시지 전달 표준으로 패킷 검사 기술이 아니다.","DPI(Deep Packet Inspection)는 헤더뿐 아니라 페이로드까지 분석해 애플리케이션을 식별하고 보안·트래픽 관리·유해 콘텐츠 차단에 쓰이므로 정답이다.","SPI(Stateful Packet Inspection)는 헤더와 세션 상태까지만 검사하며, 페이로드 내용 분석은 DPI의 영역이다."],"rel":["2-9","2-10"],"box":"이 기술의 정의는 유동적이나 일반적으로 패킷의 콘텐츠가 담긴 페이로드 부분(Payload)까지 검사할 수 있는 기술로 통용된다. 대규모 네트워크 환경에서 짧은 시간 안에 다양한 애플리케이션을 식별할 수 있는 기술로서 실시간으로 인터넷 트래픽을 분석하며 차별적으로 처리할 수 있도록 진화하였으며, 다양한 기능들을 하나의 장비에 구현할 수 있도록 발전하였다. 이로 인해서 보안, 트래픽 관리, 유해 콘텐츠 차단 등 다양한 목적을 위해 사용될 수 있다."},{"n":33,"s":"s2","q":"점차 증대되고 고도화되는 보안 위협에 대처하기 위해 예방, 탐지, 대응 등을 위한 보안 도구들을 유기적으로 연결하고 통합함으로써 보안 운영 업무를 자동화하고 보안 운영 효율성 극대화를 도모하는 기술은?","c":["UTM(Unified Threat Management)","IDS(Intrusion Detection System)","SOAR(Security Orchestration, Automation and Response)","ESM(Enterprise Security Management)"],"a":2,"e":"SOAR는 이기종 보안 도구를 오케스트레이션하고 플레이북 기반으로 대응을 자동화해 보안 운영 효율을 높이는 기술이다. UTM은 여러 보안 기능을 한 장비에 통합한 것이고, ESM은 보안 장비 로그의 통합 관리에 초점이 있다.","ce":["UTM은 방화벽·IPS·안티바이러스·VPN 등 여러 보안 기능을 한 장비에 통합한 것으로, 이기종 도구 연동과 대응 자동화(플레이북)를 목표로 하지 않는다.","IDS는 트래픽·로그에서 침입을 탐지해 경보를 내는 시스템으로, 여러 보안 도구를 오케스트레이션하는 기술이 아니다.","SOAR는 이기종 보안 도구를 연동(Orchestration)하고 플레이북 기반으로 대응을 자동화(Automation·Response)해 보안 운영 효율을 높이는 기술이므로 정답이다.","ESM은 여러 보안 장비의 로그·이벤트를 통합 수집·관리하는 체계로, 대응 절차 자동화까지 포함하는 SOAR보다 범위가 좁다."],"rel":["1-11"]},{"n":34,"s":"s2","q":"Snort의 threshold 옵션에서 다음 지문의 빈칸 ㉠에 들어갈 용어로 알맞은 것은?","c":["content","both","threshold","limit"],"a":1,"e":"Snort threshold의 type에는 limit(주기 내 처음 count개만 경보), threshold(count개마다 경보), both(주기 내 count개 도달 시 1회 경보)가 있으며 공식 정답은 both이다. 다만 지문처럼 100개마다 1번씩(200개→2번, 300개→3번) 카운트하는 동작은 문서상 threshold 유형에 해당하므로 정답 논란이 있는 문항이다. content는 페이로드 매칭 옵션이다.","ce":["content는 패킷 페이로드에서 특정 문자열·바이트 패턴을 매칭하는 옵션으로 threshold의 type 값이 아니다.","공식 정답은 both이다. 다만 Snort 문서상 both는 주기(60초) 내 count 도달 시 1회만 경보하므로, 지문처럼 100개마다 1번씩 세는 동작은 threshold 유형과 더 가깝다는 정답 논란이 있다.","threshold 유형은 주기 내 count개마다 경보를 내므로 200개→2번, 300개→3번이라는 지문 동작과 일치한다. 문서 기준으로는 이쪽이 맞다는 논란이 있으나 공식 정답은 ②이다.","limit 유형은 주기 내 처음 count개까지만 경보하고 이후는 억제하므로, 100개마다 1번씩 누적 카운트하는 동작과 다르다."],"rel":["2-11"],"box":"60초 내에서 규칙에 매치된 패킷이 200개라면 2번 카운트, 300개라면 3번 카운트\nthreshold : type ( ㉠ ), track by_dst, count 100, seconds 60;","flag":"공식 정답 both(②)이나 지문 동작(count마다 경보)은 Snort 문서상 type threshold(③)에 해당 — 정답 논란"},{"n":35,"s":"s2","q":"VPN 터널링 프로토콜과 관련이 없는 것은?","c":["L2TP","IPSec","SOCKS V5","IMAP"],"a":3,"e":"L2TP(2계층), IPSec(3계층), SOCKS v5(5계층)는 VPN 구현에 쓰이는 터널링 프로토콜이다. IMAP은 메일 서버에서 메일을 조회하는 메일 접근 프로토콜이다.","ce":["L2TP는 PPTP와 L2F를 통합한 2계층 VPN 터널링 프로토콜로, 보통 IPSec과 함께 암호화를 보완해 쓴다.","IPSec은 AH·ESP로 3계층에서 터널·전송 모드를 제공하는 대표적인 VPN 프로토콜이다.","SOCKS v5는 5계층(세션)에서 동작하는 프록시 프로토콜로, 인증을 지원해 세션 계층 VPN 구현에 쓰인다.","IMAP은 메일 서버에 저장된 메일을 조회·관리하는 메일 접근 프로토콜(TCP 143)로 VPN 터널링과 관련이 없으므로 정답이다."],"rel":["2-7"]},{"n":36,"s":"s2","q":"UTM(Unified Threat Management)에 대한 설명 중 옳지 않은 것은?","c":["UTM은 다양한 보안 솔루션을 하나의 장비에 탑재하여 운영하는 All-in-One 통합보안 솔루션이다.","보안정책 적용이 개별적으로 이루어지므로 전문가의 운영이 필요하다.","다양한 보안 기능을 하나의 솔루션에 통합하여 복합 해킹 위협에 효과적으로 대응하는데 목적을 두고 있다.","보안 정책, 필터링 시그니처를 통합 관리하여 일관성과 운영 효율성을 제공한다."],"a":1,"e":"UTM은 방화벽·IPS·안티바이러스·VPN 등을 한 장비에서 통합 정책으로 관리해 운영이 단순하고 비용이 절감되는 것이 장점이다. 보안정책이 개별적으로 적용된다는 ②는 UTM의 특성과 반대이다.","ce":["UTM은 방화벽·IPS·안티바이러스·VPN·웹 필터 등을 한 장비에 탑재한 All-in-One 통합보안 솔루션이라는 설명은 옳다.","UTM은 통합 관리 콘솔에서 단일 정책으로 운영해 관리가 단순한 것이 장점이다. '보안정책이 개별적으로 적용되어 전문가 운영이 필요하다'는 개별 장비 운영의 특징이므로 틀렸다.","여러 보안 기능을 하나로 통합해 복합적인 해킹 위협에 대응하는 것이 UTM의 도입 목적이라는 설명은 옳다.","보안 정책과 필터링 시그니처를 통합 관리해 일관성과 운영 효율을 높인다는 것은 UTM의 장점으로 옳다."],"rel":["2-10"]},{"n":37,"s":"s2","q":"TLS Record 프로토콜의 가공 단계를 올바른 순서대로 나열한 것은?","c":["나 → 가 → 다 → 라 → 마","나 → 다 → 가 → 라 → 마","나 → 라 → 다 → 가 → 마","나 → 라 → 가 → 다 → 마"],"a":0,"e":"TLS Record 프로토콜은 응용 데이터를 단편화(Fragment) → 압축(Compress) → MAC 추가 → 암호화(Encrypt) → 레코드 헤더 부착 순으로 처리한다. 암호화 후에는 압축 효율이 없으므로 압축이 암호화보다 앞선다.","ce":["단편화(나) → 압축(가) → MAC 추가(다) → 암호화(라) → 레코드 헤더 부착(마) 순서로 TLS Record 프로토콜 처리 순서와 일치하므로 정답이다.","MAC 추가(다)를 압축(가)보다 앞에 두었다. MAC은 압축된 데이터에 대해 계산하므로 압축이 먼저다.","암호화(라)를 MAC·압축보다 앞에 두었다. 암호화된 데이터는 압축 효율이 없고, TLS(1.2 이하 기본)는 MAC을 붙인 뒤 암호화한다.","암호화(라)가 압축·MAC보다 먼저 와서 틀렸다. 올바른 순서는 단편화 → 압축 → MAC → 암호화 → 헤더이다."],"rel":["2-7"],"box":"가. Compress\n나. Fragment\n다. ADD MAC\n라. Encrypt\n마. Append TLS Record Header"},{"n":38,"s":"s2","q":"포트 스캔 시 포트가 열린 경우 대상으로부터의 응답이 다른 것은?","c":["TCP Open Scan","NULL Scan","FIN Scan","XMAS Scan"],"a":0,"e":"TCP Open(Connect) Scan은 포트가 열려 있으면 SYN/ACK 응답을 받는다. NULL·FIN·XMAS 스캔은 포트가 열려 있으면 응답이 없고 닫혀 있으면 RST/ACK가 오는 스텔스 스캔이다.","ce":["TCP Open(Connect) Scan은 3-way handshake를 완료하는 방식이라 포트가 열려 있으면 SYN/ACK 응답을 받는다. 나머지는 열린 포트에서 무응답이므로 정답이다.","NULL Scan은 플래그를 모두 끈 패킷을 보내며, 열린 포트는 응답이 없고 닫힌 포트는 RST를 보낸다.","FIN Scan은 FIN 플래그만 설정해 보내며, 열린 포트는 응답이 없고 닫힌 포트는 RST를 보낸다.","XMAS Scan은 FIN·PSH·URG를 동시에 설정해 보내며, 열린 포트는 응답이 없고 닫힌 포트는 RST를 보낸다."],"rel":["2-4"]},{"n":39,"s":"s2","q":"빈칸 ㉠, ㉡, ㉢, ㉣에 들어갈 용어들이 올바르게 짝지어진 것은?","c":["㉠ L2TP ㉡ IPSec ㉢ MAC ㉣ ESP","㉠ AH ㉡ IPSec ㉢ Encapsulation ㉣ SSL","㉠ AH ㉡ ESP ㉢ MAC ㉣ HASH","㉠ L2TP ㉡ IPSec ㉢ HASH ㉣ MAC"],"a":2,"e":"IPSec에서 AH는 인증·무결성(기밀성 없음), ESP는 페이로드 암호화로 기밀성까지 제공한다. AH의 인증값(ICV)은 대칭키 기반 MAC이나 MD5·SHA 같은 해시 기반(HMAC) 방식으로 계산한다. L2TP는 2계층 터널링 프로토콜로 해당 없다.","ce":["L2TP는 2계층 터널링 프로토콜로 IPSec의 인증·무결성 헤더가 아니다(㉠은 AH). ESP는 기밀성 프로토콜이지 해시 방식 명칭이 아니다.","㉠ AH는 맞지만 ㉡ 기밀성 프로토콜은 IPSec 전체가 아니라 ESP이며, Encapsulation·SSL은 인증값 계산 알고리즘 방식이 아니다.","AH는 인증·무결성, ESP는 페이로드 암호화로 기밀성을 제공하고, 인증값은 대칭키 기반 MAC 또는 MD5·SHA 같은 해시(HMAC) 방식으로 계산하므로 정답이다.","㉠에 L2TP, ㉡에 IPSec을 넣어 틀렸고, 대칭키 기반은 MAC, MD5·SHA는 HASH이므로 ㉢·㉣도 뒤바뀌었다."],"rel":["2-6"],"box":"- 인증과 무결성을 위해 ( ㉠ ) 프로토콜 이용\n- 페이로드 기밀성 보호를 위해 ( ㉡ ) 프로토콜 이용\n- ( ㉠ ) 인증값을 계산하기 위해 사용되는 암호 알고리즘은 대칭키 기반의 ( ㉢ ) 방식 또는 MD5, SHA 등과 같은 ( ㉣ ) 방식을 이용한다."},{"n":40,"s":"s2","q":"보안 솔루션은?","c":["IPS","IDS","DLP","NAC"],"a":3,"e":"NAC(Network Access Control)는 단말이 네트워크에 접속할 때 사용자 인증과 보안 상태(패치·백신·방화벽) 무결성을 점검해 정책에 따라 허용·거부·격리한다. DLP는 정보 유출 방지, IPS·IDS는 트래픽 기반 침입 차단·탐지 솔루션이다.","ce":["IPS는 네트워크 트래픽을 실시간 검사해 공격 패킷을 차단하는 시스템으로, 단말의 사용자 인증·무결성(패치·방화벽) 검사를 수행하지 않는다.","IDS는 트래픽·로그를 분석해 침입을 탐지·경보하는 시스템으로, 접속 단말의 보안 상태 점검·격리 기능이 없다.","DLP(Data Loss Prevention)는 개인정보·기밀 데이터의 외부 유출을 탐지·차단하는 솔루션으로 네트워크 접속 통제와 다르다.","NAC는 단말 접속 시 사용자 인증과 OS 패치·백신·개인 방화벽 등 무결성을 점검하고 정책에 따라 허용·거부·격리하므로 정답이다."],"rel":["2-10"],"box":"- 접속한 경로와 관계없이 사용자에 대한 인증을 수행\n- 사용자의 컴퓨터에 대한 무결성 검사를 수행(OS 패치 및 구성 정보, 개인 방화벽 유무 등의 검사)\n- 인증 및 무결성 검사 결과를 정책 관리서버에 설정된 정책과 비교\n- 인증 및 무결성 검사 결과를 바탕으로 사용자가 접근하는 대상에 관한 정책 결정을 수행\n- 허용, 거부, 격리할 수 있는 일부 적용 장비 유형에 대한 네트워크 액세스 인증을 수행"},{"n":41,"s":"s3","q":"SSH의 기능과 가장 거리가 먼 것은?","c":["원격 접속 보호","파일 전송 보호","패킷 필터링","사용자 인증"],"a":2,"e":"SSH는 암호화된 원격 접속(터미널), SCP·SFTP를 통한 파일 전송 보호, 패스워드·공개키 기반 사용자 인증, 포트 포워딩 등을 제공한다. 패킷 필터링은 방화벽의 기능이다.","ce":["SSH는 텔넷·rlogin을 대체해 원격 터미널 접속을 암호화하므로 원격 접속 보호는 SSH의 기능이다.","SSH는 SCP·SFTP로 암호화된 파일 전송을 제공하므로 파일 전송 보호는 SSH의 기능이다.","패킷 필터링은 IP·포트 규칙으로 패킷을 허용·차단하는 방화벽(iptables 등)의 기능으로, SSH가 제공하지 않으므로 정답이다.","SSH는 패스워드·공개키 기반 사용자 인증과 호스트 키로 서버 인증을 수행하므로 사용자 인증은 SSH의 기능이다."],"rel":["2-7"]},{"n":42,"s":"s3","q":"DB 보안 위협 요소인 추론으로부터 정보 유출을 막기 위한 기술은?","c":["집성","DAC","암호화","다중 인스턴스화"],"a":3,"e":"다중 인스턴스화(Polyinstantiation)는 보안 등급별로 서로 다른 값을 가진 동일 키 튜플을 유지해 하위 등급 사용자가 상위 등급 데이터를 추론하지 못하게 한다. 집성(Aggregation)은 낮은 등급 정보를 모아 높은 등급 정보를 얻는 위협 자체이며, DAC는 임의적 접근통제 모델이다.","ce":["집성(Aggregation)은 낮은 등급의 정보를 모아 높은 등급의 정보를 얻어내는 DB 보안 위협 자체로, 추론을 막는 기술이 아니다.","DAC(임의적 접근통제)는 소유자가 권한을 부여하는 접근통제 모델로, 허용된 데이터로부터 민감 정보를 유추하는 추론 공격을 막지 못한다.","암호화는 저장·전송 데이터의 기밀성을 보호하지만, 권한 있는 사용자가 합법적으로 조회한 결과로 추론하는 것은 막지 못한다.","다중 인스턴스화(Polyinstantiation)는 보안 등급별로 같은 키에 다른 값을 가진 튜플을 두어 하위 등급 사용자가 상위 정보의 존재를 추론하지 못하게 하므로 정답이다."],"rel":["3-8"]},{"n":43,"s":"s3","q":"다음 지문의 설명에 가장 알맞은 기술은?","c":["HSM","OTP","SSO","DRM"],"a":0,"e":"HSM(Hardware Security Module)은 키를 장치 밖으로 반출하지 않고 내부 암호 연산으로 키 생성·전자서명을 수행하는 하드웨어 보안 장치(보안 토큰)이다. OTP는 일회용 비밀번호, SSO는 통합 인증, DRM은 디지털 콘텐츠 권리 관리 기술이다.","ce":["HSM(Hardware Security Module)은 전자서명 키 등 비밀정보를 장치 밖으로 내보내지 않고 내부 암호 연산으로 키 생성·서명을 수행하는 하드웨어 보안 토큰이므로 정답이다.","OTP는 매번 다른 일회용 비밀번호를 생성하는 인증 수단으로, 전자서명 키 저장·서명 생성 장치가 아니다.","SSO(Single Sign-On)는 한 번 인증으로 여러 시스템을 이용하게 하는 통합 인증 체계로 하드웨어 장치가 아니다.","DRM은 디지털 콘텐츠의 사용 권한을 암호화·라이선스로 통제하는 저작권 보호 기술이다."],"rel":["4-7"],"box":"보안 토큰이라고도 이야기하며, 전자 서명 생성 키 등 비밀정보를 안전하게 저장, 보관할 수 있고, 기기 내부에 암호 연산 장치가 있어 전자서명 키 생성 및 서명 생성 등이 가능한 하드웨어 장치를 말한다."},{"n":44,"s":"s3","q":"DNS 서버에 대한 질의 시 사용되는 type 옵션에 대한 설명으로 틀린 것은?","c":["MX : 도메인의 메일서버 질의","NS : 도메인의 네임서버 질의","A : 도메인에 대한 IP 주소 질의","SOA : IP에 대한 도메인 정보 질의"],"a":3,"e":"SOA(Start of Authority) 레코드는 해당 존의 주 네임서버·관리자 메일·시리얼·갱신 주기 등 권한 정보를 담는다. IP 주소로 도메인을 찾는 역방향 질의는 PTR 레코드를 사용한다.","ce":["MX 레코드는 해당 도메인의 메일 교환(수신) 서버와 우선순위를 알려주므로 옳은 설명이다.","NS 레코드는 해당 도메인(존)을 관리하는 권한 있는 네임서버를 알려주므로 옳은 설명이다.","A 레코드는 도메인 이름에 대응하는 IPv4 주소를 알려주므로 옳은 설명이다(IPv6는 AAAA).","SOA는 존의 주 네임서버·관리자 메일·시리얼·갱신 주기 등 권한 시작 정보를 담는다. IP로 도메인을 찾는 역방향 질의는 PTR 레코드이므로 틀렸다."],"rel":["3-7"]},{"n":45,"s":"s3","q":"다음 중 HTML 문서 내 입력받은 변수값을 서버측에서 처리할 때 부적절한 명령문이 포함되거나 실행되어 서버의 데이터가 유출되는 취약점은?","c":["SSI 인젝션","LDAP 인젝션","XPATH 인젝션","SQL 인젝션"],"a":0,"e":"SSI(Server Side Include) 인젝션은 HTML 문서에 입력값으로 <!--#exec cmd=...--> 같은 SSI 지시어를 삽입해 서버측에서 명령이 실행되게 하는 취약점이다. LDAP·XPATH·SQL 인젝션은 각각 디렉터리 질의, XML 질의, DB 질의문을 조작하는 공격이다.","ce":["SSI 인젝션은 HTML 문서 입력값에 <!--#exec cmd=\"…\"--> 같은 SSI 지시어를 넣어 서버측에서 명령이 실행되고 데이터가 유출되게 하므로 정답이다.","LDAP 인젝션은 입력값으로 LDAP 검색 필터(*, |, & 등)를 조작해 디렉터리 서비스 정보를 무단 조회하는 공격으로, HTML 문서의 서버측 처리 지시어와 다르다.","XPATH 인젝션은 XML 문서를 질의하는 XPath 식을 조작해 XML 데이터를 무단 조회하는 공격이다.","SQL 인젝션은 입력값으로 DB 질의문을 조작하는 공격으로, HTML 문서 내 서버측 명령문(SSI) 실행과는 대상이 다르다."],"rel":["3-6"]},{"n":46,"s":"s3","q":"다음 보안 프로토콜 중 작동 레이어가 OSI 7 Layer 중 가장 낮은 것은?","c":["S/MIME","IPSec","SSH","SSL"],"a":1,"e":"IPSec은 네트워크 계층(3계층)에서 동작한다. SSL/TLS는 전송 계층과 응용 계층 사이(4~5계층), SSH·S/MIME은 응용 계층에서 동작한다.","ce":["S/MIME은 이메일 본문을 암호화·서명하는 응용 계층(7계층) 보안 프로토콜이다.","IPSec은 네트워크 계층(3계층)에서 IP 패킷을 보호하므로 보기 중 가장 낮은 계층에서 동작해 정답이다.","SSH는 원격 접속·파일 전송을 보호하는 응용 계층 프로토콜(TCP 22 위에서 동작)이다.","SSL/TLS는 전송 계층(TCP)과 응용 계층 사이, 보통 4~5계층으로 분류되어 IPSec보다 높다."],"rel":["2-7","2-6"]},{"n":47,"s":"s3","q":"웹 서비스를 주요 대상으로 하는 공격 유형이 아닌 것은?","c":["CSRF","XSS","RFI","Format String"],"a":3,"e":"CSRF·XSS·RFI(Remote File Inclusion)는 웹 애플리케이션을 대상으로 하는 대표 공격이다. Format String은 C언어 printf류 함수의 형식 지정자 처리 결함을 이용하는 시스템(프로그램) 취약점 공격이다.","ce":["CSRF는 로그인한 사용자의 브라우저가 공격자가 의도한 요청을 웹 서버로 보내게 하는 웹 공격이다.","XSS는 웹 페이지에 악성 스크립트를 삽입해 다른 사용자 브라우저에서 실행시키는 대표적 웹 공격이다.","RFI(Remote File Inclusion)는 PHP include 등에 외부 URL을 넣어 원격 악성 파일을 서버에서 실행시키는 웹 애플리케이션 공격이다.","Format String은 C언어 printf류 함수의 형식 지정자 처리 결함을 악용하는 프로그램(시스템) 취약점 공격으로, 웹 서비스를 주 대상으로 하지 않으므로 정답이다."],"rel":["3-6","1-10"]},{"n":48,"s":"s3","q":"TLS handshake 과정을 순서에 맞게 나열한 것은?","c":["다 → 라 → 나 → 가 → 마","다 → 나 → 가 → 라 → 마","다 → 라 → 가 → 나 → 마","다 → 나 → 라 → 마 → 가"],"a":1,"e":"TLS 핸드셰이크는 Client Hello → Server Hello(→Certificate) → Server Key Exchange(→Server Hello Done) → Client Key Exchange → Change Cipher Spec(→Finished) 순으로 진행된다. 클라이언트 키 교환은 서버의 Hello와 키 교환 정보를 받은 뒤에 이루어진다.","ce":["Client Key Exchange(라)가 Server Hello(나)보다 앞섰다. 클라이언트는 서버의 Hello·인증서·키 교환 정보를 받은 뒤에 키 교환 메시지를 보낸다.","Client Hello(다) → Server Hello(나) → Server Key Exchange(가) → Client Key Exchange(라) → Change Cipher Spec(마) 순으로 TLS 핸드셰이크 흐름과 일치하므로 정답이다.","Client Key Exchange(라)와 Server Key Exchange(가)가 Server Hello(나)보다 먼저 나와 틀렸다. 서버는 먼저 Hello로 협상 결과를 알린다.","Server Key Exchange(가)가 Change Cipher Spec(마) 뒤에 와서 틀렸다. Change Cipher Spec은 키 교환이 모두 끝난 뒤 암호화 전환을 알리는 단계이다."],"rel":["2-7"],"box":"가. Server Key Exchange\n나. Server Hello\n다. Client Hello\n라. Client Key Exchange\n마. Change Cipher Spec"},{"n":49,"s":"s3","q":"다음 중 SQL injection에서 사용되는 여러 종류의 특수문자 용도에 대한 설명으로 가장 적합하지 않은 것은?","c":["-- 및 # 은 앞의 출력값을 받아 두 번째 입력값으로 사용한다.","; 은 쿼리 구분 기호이다.","' 은 문자 데이터 구분기호이다.","/* */은 구문 주석 처리 기호이다."],"a":0,"e":"--와 #은 이후 문자열을 주석 처리해 뒤따르는 쿼리 조건(예: 패스워드 검사)을 무력화하는 데 쓰인다. ;는 쿼리 구분, '는 문자열 구분, /* */는 블록 주석 기호로 나머지 설명은 맞다.","ce":["--와 #은 이후 문자열을 주석 처리해 뒤따르는 조건(예: AND password=…)을 무력화하는 기호이다. '앞의 출력값을 두 번째 입력값으로 사용'한다는 설명은 틀렸다.",";는 쿼리 구분 기호로, 뒤에 새 쿼리를 이어 붙이는 스택 쿼리(예: ; DROP TABLE…)에 쓰이므로 옳은 설명이다.","'는 문자열 데이터의 시작·끝을 구분하는 기호로, 이를 조기에 닫아 쿼리 구조를 조작하는 것이 SQL 인젝션의 기본이므로 옳다.","/* */는 블록 주석 기호로, 뒤 구문을 주석 처리하거나 공백 대신 삽입해 필터를 우회하는 데 쓰이므로 옳다."],"rel":["3-6"]},{"n":50,"s":"s3","q":"디지털포렌식의 일반원칙으로 적합하지 않은 것은?","c":["증거분석은 원본을 사용하여 분석하여야 한다.","디지털 증거는 신뢰성이 검증된 분석 도구(HW, SW)를 사용해야 한다.","디지털 증거는 추출, 분석된 데이터가 무결성, 동일성이 보장되어야 증거능력을 인정받을 수 있다.","증거분석의 전 과정을 기록하여야 한다."],"a":0,"e":"디지털 포렌식은 원본의 무결성 보존을 위해 해시값으로 동일성을 검증한 사본(이미지)으로 분석해야 한다. 검증된 도구 사용(신뢰성), 무결성 보장, 전 과정 기록(연계 보관성)은 올바른 원칙이다.","ce":["원본은 해시값을 계산해 보존하고, 동일성이 검증된 사본(이미지)으로 분석해야 한다. 원본을 직접 분석하면 변경 위험이 있어 무결성 원칙에 어긋나므로 틀린 원칙이다.","신뢰성 원칙에 따라 검증된 도구(쓰기 방지 장치, 인증된 분석 SW 등)를 사용해야 결과를 법정에서 인정받을 수 있어 옳은 원칙이다.","추출·분석 데이터가 원본과 같고 변경되지 않았음(해시 비교)이 입증되어야 증거능력이 인정되므로 무결성·동일성 원칙으로 옳다.","수집부터 제출까지 전 과정을 기록하는 연계 보관성(Chain of Custody) 원칙으로 옳다."],"rel":["3-11"]},{"n":51,"s":"s3","q":"빈칸 ⓐ, ⓑ, ⓒ에 들어갈 상태코드 값으로 알맞은 것은?","c":["ⓐ 200 ⓑ 400 ⓒ 500","ⓐ 400 ⓑ 300 ⓒ 200","ⓐ 200 ⓑ 500 ⓒ 300","ⓐ 300 ⓑ 400 ⓒ 500"],"a":2,"e":"HTTP 상태코드는 2xx 성공, 3xx 리다이렉션(다른 위치 자원 필요), 4xx 클라이언트 오류, 5xx 서버 오류이다. 따라서 ⓐ 200, ⓑ 500, ⓒ 300번대이며, 400번대는 클라이언트 요청 자체의 오류이다.","ce":["ⓐ 200번대는 맞지만, 400번대는 클라이언트 요청 오류(404 Not Found 등)이고 500번대는 서버 오류이므로 ⓑ·ⓒ가 틀렸다. 다른 곳의 자원이 필요함은 300번대이다.","400번대는 클라이언트 오류, 300번대는 리다이렉션, 200번대는 성공이므로 세 짝이 모두 어긋났다.","2xx 성공(ⓐ 200), 5xx 서버 오류(ⓑ 500), 3xx 리다이렉션으로 다른 위치 자원 필요(ⓒ 300)이므로 정답이다.","300번대는 성공이 아니라 리다이렉션, 400번대는 서버가 아니라 클라이언트 오류, 500번대는 서버 오류이므로 모두 어긋났다."],"rel":["3-3"],"box":"클라이언트의 요청이 성공적으로 수신되어 처리되었음을 의미한다. - ( ⓐ )번대\n서버 자체에서 생긴 오류 상황이나 클라이언트의 요구 사항을 제대로 처리할 수 없을 때 발생한다. - ( ⓑ )번대\n클라이언트의 요구 사항을 처리하려면 다른 곳에 있는 자원이 필요하다는 것을 의미한다. - ( ⓒ )번대"},{"n":52,"s":"s3","q":"전자상거래 보안에서 SSL/TLS의 특징이 아닌 것은?","c":["SSL은 Record Layer와 Handshake Layer로 구분한다.","응용계층의 프로토콜의 안정성을 보장한다.","https:// 로 표현된다.","전자서명을 통한 부인방지를 제공한다."],"a":3,"e":"SSL/TLS는 서버(선택적으로 클라이언트) 인증, 기밀성, 무결성을 제공하지만 거래 메시지에 대한 전자서명이 없어 부인방지는 제공하지 않는다. 이중서명으로 부인방지를 제공하는 것은 SET이다.","ce":["SSL/TLS는 Record 계층(단편화·압축·MAC·암호화) 위에 Handshake·Change Cipher Spec·Alert 프로토콜이 올라가는 구조로 옳은 설명이다.","SSL/TLS는 전송 계층과 응용 계층 사이에서 HTTP·SMTP·FTP 등 응용 프로토콜 통신을 안전하게 보호하므로 옳다.","HTTP over SSL/TLS는 https:// 스킴(기본 TCP 443)으로 표기되므로 옳다.","SSL/TLS는 인증·기밀성·무결성을 제공하지만 거래 메시지에 전자서명을 남기지 않아 부인방지는 제공하지 않는다. 이중서명으로 부인방지를 제공하는 것은 SET이므로 틀렸다."],"rel":["3-10","2-7"]},{"n":53,"s":"s3","q":"게시판에 올리는 글에 악성코드를 삽입하여 다른 게시판 이용자가 글을 읽을 경우 악성코드가 실행되도록 하여 클라이언트의 정보를 유출하는 공격 기법에 해당하는 것은?","c":["File Download","쿠키/세션 위조","XML 외부 개체","Cross Site Scripting"],"a":3,"e":"게시글에 스크립트를 저장해 열람자 브라우저에서 실행되게 하는 것은 저장형(Stored) XSS로, 쿠키·세션 탈취 등 클라이언트 정보 유출에 쓰인다. XML 외부 개체(XXE)는 서버의 XML 파서를 공격하는 기법이다.","ce":["File Download 취약점은 파일 다운로드 경로 조작(../)으로 서버의 임의 파일을 내려받는 공격으로, 게시글 열람 시 스크립트 실행과 다르다.","쿠키/세션 위조는 인증 쿠키 값을 조작·재사용해 다른 사용자로 행세하는 공격으로, XSS가 그 수단이 될 수 있으나 게시글에 악성코드를 심는 기법 자체는 아니다.","XML 외부 개체(XXE)는 서버의 XML 파서가 외부 엔티티를 해석하게 해 서버 파일을 읽는 공격으로, 공격 대상이 클라이언트가 아니라 서버이다.","게시글에 스크립트를 저장해 다른 이용자가 열람할 때 브라우저에서 실행되게 하는 저장형(Stored) XSS에 해당하므로 정답이다."],"rel":["3-6"]},{"n":54,"s":"s3","q":"SSL/TLS의 취약점과 관계가 먼 것은?","c":["Freak","logjam","Poodle","Spectre"],"a":3,"e":"FREAK·Logjam은 수출용 약한 암호(RSA·DH)로 다운그레이드시키는 공격이고, POODLE은 SSL 3.0의 CBC 패딩 취약점 공격이다. Spectre는 CPU의 투기적 실행을 악용하는 하드웨어 취약점이다.","ce":["FREAK은 SSL/TLS 협상을 수출용 512비트 RSA(EXPORT 등급)로 다운그레이드시켜 키를 해독하는 TLS 취약점이다.","Logjam은 TLS의 DHE 키 교환을 수출용 512비트 DH 파라미터로 다운그레이드시키는 TLS 취약점이다.","POODLE은 SSL 3.0의 CBC 패딩 검증 결함을 이용해 암호문을 한 바이트씩 해독하는 SSL 취약점이다.","Spectre는 CPU의 투기적 실행(분기 예측)을 악용해 다른 프로세스 메모리를 읽는 하드웨어 취약점으로 SSL/TLS와 관계없으므로 정답이다."],"rel":["2-7"]},{"n":55,"s":"s3","q":"다음 지문의 특징을 가진 공격 유형으로 적절한 것은?","c":["APT 공격","갠드크랩(GandCrab) 공격","클롭(CLOP) 공격","공급망 공격(Supply Chain)"],"a":3,"e":"개발환경·업데이트 서버에 침투해 정상 소프트웨어 배포 경로에 유효한 인증서로 서명된 악성코드를 끼워 넣는 것이 공급망(Supply Chain) 공격의 핵심 특징이다. APT도 은밀·지속 공격이지만 지문의 '개발환경·업데이트 서버 침투' 전략은 공급망 공격을 가리키며, GandCrab·CLOP은 랜섬웨어이다.","ce":["APT도 특정 대상을 은밀하고 지속적으로 공격하지만, 지문의 핵심인 '개발환경 침투·업데이트 서버 침투'로 정상 배포 경로를 오염시키는 전략은 공급망 공격을 가리킨다.","갠드크랩(GandCrab)은 파일을 암호화하고 금전을 요구하는 서비스형 랜섬웨어(RaaS)로, 소수 PC만 은밀히 감염시키는 표적 배포 전략과 다르다.","클롭(CLOP)은 기업 네트워크를 장악한 뒤 파일을 암호화하는 랜섬웨어로, 소프트웨어 개발·업데이트 경로 침투가 특징이 아니다.","개발환경·업데이트 서버에 침투해 유효한 인증서로 서명된 악성코드를 정상 소프트웨어 배포 경로에 끼워 넣는 것이 공급망(Supply Chain) 공격의 특징이므로 정답이다."],"rel":["1-19"],"box":"- 서버 장악 및 흔적 제거를 위해 PlugX 계열의 악성코드를 주로 사용\n- 악성코드 제작자는 제작 단계부터 공격 목표로 삼은 특정 회사를 타깃하며 정밀하게 제작하고 소수의 PC만을 최종적으로 감염시킴으로써 작전을 은밀하게 오래 수행\n- 유효한 인증서로 서명된 악성코드 활용, C 런타임 코드 변조 등의 탐지회피 기법에 능하며 고도화되고 지능적으로 공격 수행\n- '개발환경 침투'와 '업데이트 서버 침투' 등의 전략 사용"},{"n":56,"s":"s3","q":"다음 지문에서 설명하는 웹 공격 기법은?","c":["SQL Injection 공격","역직렬화 공격","CSRF 공격","디렉터리 리스팅(Directory Listing) 공격"],"a":2,"e":"CSRF(Cross-Site Request Forgery)는 인증된 사용자의 브라우저가 의도치 않은 요청(수정·삭제·송금 등)을 서버에 보내게 하여 서버가 이를 정상 요청으로 실행하게 만드는 공격이다. XSS가 클라이언트에서 스크립트가 실행되는 것과 달리 CSRF는 서버에서 행위가 수행된다.","ce":["SQL Injection은 입력값으로 DB 쿼리를 조작해 데이터를 탈취·변조하는 공격으로, 로그인 사용자의 권한으로 의도치 않은 요청을 보내게 하는 방식이 아니다.","역직렬화 공격은 조작된 직렬화 객체를 서버가 역직렬화할 때 임의 코드가 실행되게 하는 공격으로, 사용자 브라우저를 매개로 하지 않는다.","CSRF는 로그인한 사용자가 악성 게시물을 열면 의지와 무관하게 수정·삭제·송금 등 요청이 서버로 전송되어 서버가 정상 요청으로 실행하므로 정답이다.","디렉터리 리스팅은 웹 서버 설정 미흡으로 디렉터리 파일 목록이 노출되는 취약점으로, 사용자 행위를 위조하는 공격이 아니다."],"rel":["3-6"],"box":"공격자는 악성코드가 포함된 게시물을 서버에 등록해 두면 로그인된 사용자가 자신의 의지와 무관하게 공격자가 의도한 행위(수정, 삭제, 등록, 송금 등)를 하게 만드는 공격으로서 사용자가 악성 스크립트 구동을 서버에게 요청하며 실제 서버가 실행하도록 한다."},{"n":57,"s":"s3","q":"다음 지문에서 설명하는 것은?","c":["DRM","DOI","스테가노그래피","워터마킹"],"a":1,"e":"DOI(Digital Object Identifier)는 디지털 콘텐츠에 고유 식별자를 부여하는 체계로, 위치가 바뀌어도 콘텐츠를 식별·추적할 수 있다. DRM은 사용 권한 통제, 워터마킹·스테가노그래피는 콘텐츠 내부에 정보를 삽입하는 기술이다.","ce":["DRM은 암호화와 라이선스로 콘텐츠의 열람·복제·배포 권한을 통제하는 기술로, 콘텐츠에 고유 식별 번호를 부여하는 체계가 아니다.","DOI(Digital Object Identifier)는 디지털 콘텐츠 객체에 고유 식별자를 부여하는 체계로 저작권 보호와 유통 경로 추적을 쉽게 하므로 정답이다.","스테가노그래피는 이미지·음성 등에 비밀 메시지를 숨겨 존재 자체를 감추는 은닉 기술로 식별 체계가 아니다.","워터마킹은 콘텐츠 내부에 저작권자 정보를 삽입해 소유권을 주장하는 기술로, 고유 체계에 따른 식별자 부여와는 다르다."],"rel":["3-12"],"box":"디지털 환경에서 콘텐츠 객체를 식별하기 위한 것으로 고유의 체계에 따라 부여된다. 이를 통해 디지털 콘텐츠의 저작권 보호와 유통 경로 추적이 용이해진다."},{"n":58,"s":"s3","q":"윈도우 7을 사용하는 사용자가 한국인터넷진흥원 홈페이지(http://www.kisa.or.kr)에 접속하기 위해 IP 주소를 얻어오는 순서로 적절한 것은?","c":["로컬 DNS 서버 → 캐시 → Hosts 파일","Hosts 파일 → 캐시 → 로컬 DNS 서버","로컬 DNS 서버 → Hosts 파일 → 캐시","캐시 → Hosts 파일 → 로컬 DNS 서버"],"a":3,"e":"윈도우는 먼저 DNS 캐시를 확인하고, 없으면 Hosts 파일, 그래도 없으면 로컬 DNS 서버에 질의한다. 단 Hosts 파일 내용은 캐시에 미리 적재되므로 실질적으로 우선 적용되며, 시험에서는 캐시 → Hosts → DNS 서버 순서를 정답으로 한다.","ce":["로컬 DNS 서버에 먼저 질의하는 순서는 틀렸다. 윈도우 리졸버는 로컬(캐시·Hosts)을 먼저 확인하고 없을 때만 DNS 서버에 질의한다.","Hosts 파일이 캐시보다 먼저 온다고 보았으나, 시험 기준 순서는 DNS 캐시 → Hosts 파일 → DNS 서버이다(Hosts 내용은 캐시에 미리 적재됨).","로컬 DNS 서버가 가장 먼저 오는 순서는 틀렸다. 외부 질의는 로컬에서 해석하지 못할 때 마지막에 수행한다.","DNS 캐시 → Hosts 파일 → 로컬 DNS 서버 순서로 로컬 정보를 먼저 확인하고 마지막에 외부에 질의하므로 정답이다."],"rel":["3-7"]},{"n":59,"s":"s3","q":"갑자기 대량의 DNS(Domain Name System) 관련 트래픽이 유입되어 확인해 보니, DNS 증폭공격이라는 것을 알게 되었다. 다음 중 이 공격에 대해 바르게 설명하고 있는 것은?","c":["DNS zone transfer의 취약점을 이용한 공격이다.","DNSSEC의 취약점을 이용한 공격이다.","DNS bug이므로 취약한 서버는 최신 버전으로 패치를 하여야 한다.","resolving이 허용된 DNS를 매개체로 악용하는 형태의 공격이다."],"a":3,"e":"DNS 증폭 공격은 출발지를 피해자 IP로 위조해 재귀 질의(resolving)가 허용된 개방형 DNS 서버에 응답이 큰 질의(ANY 등)를 보내 증폭된 응답을 피해자에게 쏟아지게 하는 반사 공격이다. 소프트웨어 버그가 아닌 설정 악용이므로 패치보다 재귀 질의 제한이 대책이다.","ce":["Zone transfer(AXFR) 취약점은 존 전체 레코드가 비인가 서버로 유출되는 정보 노출 문제로, 반사·증폭 DDoS와 다르다.","DNSSEC은 DNS 응답의 위·변조를 막는 서명 확장이다. 서명 때문에 응답이 커져 증폭에 이용될 수는 있지만 DNSSEC 취약점을 이용하는 공격은 아니다.","DNS 증폭은 소프트웨어 버그가 아니라 재귀 질의를 외부에 허용한 설정을 악용하는 것이므로, 패치보다 재귀 질의 제한·응답률 제한(RRL)이 대책이다.","출발지를 피해자로 위조해 재귀 질의(resolving)가 허용된 개방형 DNS 서버에 ANY 등 응답이 큰 질의를 보내, 증폭된 응답이 피해자에게 쏟아지게 하는 반사 공격이므로 정답이다."],"rel":["3-7","2-3"]},{"n":60,"s":"s3","q":"SQL injection 공격 취약점에 대응하기 위한 방법과 가장 거리가 먼 것은?","c":["웹 방화벽을 웹 서버 앞단에 두고 미리 필터링 한다.","인터프리터 방식을 회피한다.","사용자 입력 값을 모두 Encoding 하여 유효성을 검증한다.","현재 쓰고 있는 웹브라우저를 업그레이드 하거나, 다른 것으로 바꾼다."],"a":3,"e":"SQL 인젝션은 서버측 쿼리 조립 결함이므로 웹 방화벽 필터링, 동적 쿼리(인터프리터) 회피와 Prepared Statement 사용, 입력값 검증·인코딩으로 대응한다. 클라이언트 웹브라우저 교체는 서버측 취약점과 무관하다.","ce":["웹 방화벽(WAF)을 웹 서버 앞단에 두어 ' OR 1=1 등 SQL 인젝션 패턴을 미리 필터링하는 것은 유효한 대응책이다.","입력값을 문자열로 이어 붙여 해석하는 동적 쿼리(인터프리터) 방식을 피하고 Prepared Statement(바인딩 변수)를 쓰는 것이 근본 대응이다.","사용자 입력값을 인코딩·이스케이프하고 화이트리스트로 유효성을 검증하는 것은 SQL 인젝션의 기본 대응이다.","SQL 인젝션은 서버측에서 쿼리를 조립하는 결함이므로 클라이언트 웹브라우저를 업그레이드·교체해도 막을 수 없어 대응 방법과 가장 거리가 멀다."],"rel":["3-6"]},{"n":61,"s":"s4","q":"다음 지문에서 설명하는 정보보호 용어는?","c":["위협(threat)","취약점(vulnerability)","자산(asset)","위험(risk)"],"a":0,"e":"위협은 자산에 손실을 초래할 수 있는 원치 않는 사건의 잠재적 원인(해킹, 악성코드, 화재 등)이다. 취약점은 위협이 이용할 수 있는 자산의 약점이고, 위험은 위협이 취약점을 이용해 손실이 발생할 가능성(자산·위협·취약점의 함수)이다.","ce":["위협은 해킹·악성코드·파손·화재처럼 조직 자산에 손실을 유발할 수 있는 잠재적 원인(사건)의 집합이므로 정답이다.","취약점은 위협이 이용할 수 있는 자산의 약점(패치 미적용, 설정 오류 등)으로, 해킹·화재 같은 외부 사건 자체가 아니다.","자산은 정보·시스템·인력처럼 조직이 보호해야 할 가치 있는 대상으로, 손실을 유발하는 사항이 아니다.","위험은 위협이 취약점을 이용해 자산에 손실을 일으킬 가능성(자산·위협·취약점의 함수)으로, 손실을 일으키는 원인 사건 목록인 위협과 구분된다."],"rel":["5-2"],"box":"조직이나 시스템에 손실 또는 손해를 유발시킬 수 있는 사항들의 집합으로 정의된다. 예로는 해킹, 악성코드, 파손 행위, 화재 등을 들 수 있다."},{"n":62,"s":"s4","q":"다음 지문에서 설명하고 있는 원칙은?","c":["직무 순환","상호 배제","책임추적성 보장","직무 분리"],"a":3,"e":"직무 분리(Separation of Duties)는 한 사람이 업무 전 과정을 통제하지 못하도록 개발·운영·감사 권한을 나누는 원칙으로, 개발자의 운영 데이터 접근 제한, 관리자의 로그 접근 제한이 그 예이다. 직무 순환은 일정 기간마다 담당 업무를 교대시켜 부정을 발견하는 통제이다.","ce":["직무 순환은 일정 기간마다 담당 업무를 교대시켜 부정을 발견·방지하는 통제로, 개발자·관리자의 권한을 분리하는 지문 내용과 다르다.","상호 배제는 운영체제에서 공유 자원에 한 프로세스만 접근하게 하는 동시성 제어 개념으로 인적 보안 원칙이 아니다.","책임추적성은 행위를 특정 주체까지 추적할 수 있게 로그를 남기는 것으로, 권한을 나누어 한 사람이 전 과정을 통제하지 못하게 하는 원칙과 다르다.","개발과 운영, 운영과 감사(로그) 권한을 서로 다른 사람에게 나누어 한 사람이 전 과정을 통제하지 못하게 하는 직무 분리이므로 정답이다."],"rel":["4-10"],"box":"- 개발자는 운영 데이터에 접근할 수 없으나 테스트를 위해 관리자의 승인을 받을 경우 제한된 규모의 운영 데이터에 접근할 수 있다.\n- 서버 관리자는 시스템 로그에 접근할 수 없다."},{"n":63,"s":"s4","q":"다음 지문은 블록 암호 알고리즘을 분석하는 방법에 대한 서술이다. 이 분석법에서 사용한 암호 해독의 원리는?","c":["암호문 단독 공격","선택 평문 공격","알려진 평문 공격","선택 암호문 공격"],"a":3,"e":"공식 정답은 선택 암호문 공격으로, 지문이 '암호문을 선택하고 그에 대응하는 평문을 얻는다'는 선택 암호문 공격의 정의를 서술하고 있기 때문이다. 다만 차분 공격(Biham·Shamir)은 일반적으로 차분이 정해진 평문 쌍을 선택해 암호화하는 선택 평문 공격으로 분류되므로 개념 구분에 주의해야 한다.","ce":["암호문 단독 공격은 공격자가 암호문만 가지고 평문·키를 추정하는 가장 약한 공격 모델로, 평문-암호문 쌍을 선택해 얻는 차분 분석과 다르다.","차분 공격은 학계에서 일반적으로 차분이 정해진 평문 쌍을 골라 암호화하는 선택 평문 공격으로 분류된다. 그러나 지문 마지막 문장이 '암호문을 선택해 평문을 얻는다'고 서술해 공식 정답은 ④이다.","알려진 평문 공격은 공격자가 선택하지 않은 평문-암호문 쌍을 이용하는 모델로, 선형 공격이 대표적이다. 지문의 '선택'하는 과정과 맞지 않는다.","지문이 '암호문을 선택하고 그에 대응하는 평문을 얻어 키 비트를 찾는다'고 서술하므로 공식 정답은 선택 암호문 공격이다. 차분 공격 자체는 보통 선택 평문 공격으로 분류된다는 논란이 있다."],"rel":["4-1"],"box":"먼저 암호 알고리즘의 비선형 요소에 대해 평문의 차분과 암호문의 차분 사이의 관계에 대한 차분 분포표를 구성한다. 그 후 차분 분포표에서 높은 확률을 갖는 공격에 필요한 평문 목록을 구성하고, 암호문을 선택하고 그에 대응하는 평문을 얻어 키의 특정 비트 정보를 찾는다.","flag":"차분분석은 통상 선택 평문 공격으로 분류 — 지문 마지막 문장 기준 공식 정답 ④"},{"n":64,"s":"s4","q":"전체 사용자가 10명인 시스템(또는 조직)내에서 어떤 사용자가 다른 사람에게 암호화된 메시지를 대칭키 암호를 사용하여 교환하고자 한다. 이때, 서로 다른 2명씩 대칭키를 사전에 공유한다고 가정할 때, 전체 시스템에서 존재하는 서로 다른 대칭키의 개수는 몇 개인가?","c":["10","45","55","100"],"a":1,"e":"n명이 두 명씩 서로 다른 대칭키를 공유하면 필요한 키 수는 n(n-1)/2이므로 10×9/2 = 45개이다. 공개키 방식이라면 사용자당 키 쌍 1개로 2n = 20개가 필요하다.","ce":["10은 사용자 수와 같은 값으로, 대칭키 방식에서 두 명씩 서로 다른 키를 공유할 때의 키 개수가 아니다.","n명이 두 명씩 서로 다른 대칭키를 공유하면 n(n-1)/2개가 필요하므로 10×9/2 = 45개로 정답이다.","55는 n(n+1)/2로 계산해 자기 자신과의 키까지 센 값으로, 서로 다른 2명 조합 수가 아니다.","100은 n²으로 계산한 값으로, 같은 쌍을 두 번 세고 자기 자신과의 키까지 포함한 잘못된 계산이다."],"rel":["4-1"]},{"n":65,"s":"s4","q":"기존의 사람과 사람, 사람과 디바이스 중심의 네트워크 환경이 디바이스와 디바이스 간의 네트워크로 확장됨에 따라 디바이스 인증이 중요한 쟁점으로 부각되고 있다. 디바이스 인증에 대한 설명 중 틀린 것은?","c":["디바이스의 진위성 및 네트워크 접속 권한을 제어하기 위한 것이다.","비 인가된 디바이스가 네트워크에 접속되어 IT 서비스를 위협하는 것을 방지하기 위한 것이다.","네트워크에 참여하는 다양한 디바이스들을 신뢰할 수 있도록 하기위한 것이다.","네트워크 및 시스템 사용권을 허가된 사용자로 제한하기 위한 것이다."],"a":3,"e":"디바이스 인증은 사람이 아닌 기기 자체의 진위성을 확인해 비인가 기기의 접속을 막고 기기 간 신뢰를 확보하는 것이다. 사용권을 허가된 '사용자'로 제한하는 것은 사용자 인증의 목적이다.","ce":["디바이스 인증은 기기가 진짜인지(진위성) 확인하고 네트워크 접속 권한을 제어하는 것이므로 옳은 설명이다.","비인가 디바이스가 네트워크에 접속해 IT 서비스를 위협하는 것을 막는 것이 디바이스 인증의 목적이므로 옳다.","IoT·M2M 환경에서 참여하는 다양한 기기 간 신뢰를 확보하는 것이 디바이스 인증의 역할이므로 옳다.","사용권을 허가된 '사용자'로 제한하는 것은 사람을 확인하는 사용자 인증의 목적이다. 디바이스 인증은 기기 자체를 확인하므로 틀린 설명이다."],"rel":["4-8"]},{"n":66,"s":"s4","q":"SSO(Single Sign On)는 사용자가 단 한 번의 인증절차만으로 다수의 애플리케이션에 접속할 수 있도록 해주는 인증 프로세스로 인증시간 단축, 사용자 계정의 효율적 관리, 접근권한의 효율적 통제가 가능하다. 다음 중 SSO 방식과 가장 거리가 먼 것은?","c":["RADIUS","SPNEGO","Kerberos","SESAME"],"a":0,"e":"Kerberos(티켓 기반), SESAME(Kerberos 확장 유럽 프로젝트), SPNEGO(Kerberos 기반 웹 통합 인증 협상)는 SSO 구현 방식이다. RADIUS는 원격 접속 사용자의 AAA를 처리하는 네트워크 접근 인증 프로토콜이다.","ce":["RADIUS는 NAS와 인증 서버 사이에서 원격 접속 사용자의 인증·권한·과금(AAA)을 처리하는 네트워크 접근 인증 프로토콜로, 여러 애플리케이션 SSO 방식이 아니므로 정답이다.","SPNEGO는 HTTP 등에서 Kerberos·NTLM 인증 방식을 협상해 윈도우 로그인만으로 웹 애플리케이션에 접속하게 하는 SSO 방식이다.","Kerberos는 한 번 받은 TGT로 여러 서비스 티켓을 발급받아 재인증 없이 접속하게 하는 대표적 SSO 방식이다.","SESAME는 Kerberos를 확장한 유럽 프로젝트로, 공개키 기반 확장과 권한 속성 인증서(PAC)로 SSO를 제공한다."],"rel":["4-9"]},{"n":67,"s":"s4","q":"대칭키 암호화와 MAC(Message Authentication Code)으로 해결할 수 없는 보안서비스는?","c":["메시지 무결성(Integrity)","메시지 인증(Authentication)","메시지 부인방지(Non Repudiation)","메시지 기밀성(Confidentiality)"],"a":2,"e":"대칭키 암호화는 기밀성, MAC은 무결성과 메시지 인증을 제공한다. 그러나 송·수신자가 같은 키를 공유하므로 누가 생성했는지 제3자에게 증명할 수 없어 부인방지는 공개키 기반 전자서명이 필요하다.","ce":["MAC은 메시지와 공유 비밀키로 계산한 태그를 비교해 변조 여부를 확인하므로 메시지 무결성을 제공한다.","MAC은 비밀키를 공유한 상대만 올바른 태그를 만들 수 있어 메시지 출처 인증을 제공한다.","송·수신자가 같은 비밀키를 가지므로 누가 메시지를 생성했는지 제3자에게 증명할 수 없어 부인방지는 불가능하다. 부인방지는 개인키 전자서명이 필요하므로 정답이다.","대칭키 암호화(AES 등)로 메시지를 암호화하면 키가 없는 제3자가 내용을 볼 수 없어 기밀성을 제공한다."],"rel":["4-5"]},{"n":68,"s":"s4","q":"다음 중 MD 계열 해시함수의 특징으로 옳지 않은 것은?","c":["160Bit의 출력 해시값을 생성한다.","데이터 무결성을 위해 메시지 압축·축약을 하는 해시 알고리즘이다.","해시 충돌 방지 확률은 약 이다.","MD4의 경우, 속도가 빠른 반면에 안정성에서 뒤떨어진다."],"a":0,"e":"MD4·MD5 등 MD 계열은 128비트 해시값을 출력하며, 160비트 출력은 SHA-1(및 RIPEMD-160)의 특징이다. MD4는 빠르지만 충돌이 발견되어 안전성이 낮다.","ce":["MD4·MD5 등 MD 계열 해시는 128비트 출력이다. 160비트 출력은 SHA-1·RIPEMD-160의 특징이므로 옳지 않은 설명이다.","해시 함수는 임의 길이 메시지를 고정 길이 값으로 압축·축약해 데이터 무결성 검증에 쓰이므로 옳은 설명이다.","원문 이미지에서 충돌 확률 수치가 누락되어 정확한 판단 근거가 없다 — 공식 정답(①) 기준으로 옳은 보기로 처리한다. 참고로 128비트 해시의 생일 공격 충돌 복잡도는 이론상 2의 64승 수준이다.","MD4는 32비트 연산 위주라 빠르지만 충돌이 실제로 발견되어 안전성이 낮으므로 옳은 설명이다."],"rel":["4-5"],"flag":"보기 ③의 수치(충돌 확률 식)가 원문 이미지에서 누락됨"},{"n":69,"s":"s4","q":"다음 지문에서 설명하는 접근통제 모델은?","c":["강제적 접근통제 모델","규칙기반 접근통제 모델","역할기반 접근통제 모델","임의적 접근통제 모델"],"a":3,"e":"임의적 접근통제(DAC)는 객체 소유자가 자신의 재량으로 다른 주체에게 접근 권한을 부여·위임하는 신원 기반 모델이다. 강제적 접근통제(MAC)는 보안 레이블(등급)에 따라 시스템이 강제하며 소유자가 권한을 임의로 넘길 수 없다.","ce":["강제적 접근통제(MAC)는 주체·객체의 보안 등급(레이블)에 따라 시스템이 접근을 강제하므로, 소유자가 임의로 권한을 넘길 수 없다.","규칙기반 접근통제는 관리자가 정한 규칙(시간·IP 등)에 따라 모든 사용자에게 일괄 적용하는 방식으로 소유권 기반 위임이 아니다.","역할기반 접근통제(RBAC)는 권한을 역할에 부여하고 사용자를 역할에 배정하는 방식으로, 권한 부여 주체는 소유자가 아니라 관리자이다.","임의적 접근통제(DAC)는 객체 소유자가 자기 재량으로 다른 주체에게 권한 일부 또는 전부를 부여하는 신원 기반 모델이므로 정답이다."],"rel":["4-10"],"box":"이 모델은 객체에 대한 소유권을 기반으로 소유권을 갖는 주체가 객체에 대한 권한의 일부 또는 전부를 다른 주체에게 부여할 수 있다."},{"n":70,"s":"s4","q":"다음은 암호키 관리의 운영단계 중 키변경 기능(Key Change Function)에 대한 설명이다. 잘못된 것은?","c":["기존의 암호키를 이용하여 새로운 암호키를 생성하는 방법을 키 갱신이라고 한다.","기존의 암호키와는 독립적인 방법으로 새로운 암호키를 생성하는 방법을 키 교체라고 한다.","갱신된 암호키가 노출된 경우, 갱신되기 이전의 암호키에 대한 정보는 노출되지 않으므로, 기존의 암호키가 노출되면 노출된 암호키를 변경하기 위해 키 갱신을 사용한다.","암호키의 노출이 확인되거나, 노출의 위협이 있는 경우 혹은 암호키 유효 기간의 만료가 가까워지는 경우 암호키를 안전하게 변경해야 하며, 암호키를 변경한 이후에는 기존의 암호키를 정지단계로 전환해야 한다."],"a":2,"e":"키 갱신은 기존 키로 새 키를 유도하므로 기존 키가 노출되면 갱신된 키도 추정될 수 있다. 따라서 키 노출 시에는 기존 키와 독립적으로 생성하는 키 교체를 사용해야 하며, ③은 이를 반대로 설명했다.","ce":["기존 암호키로부터 새 암호키를 유도해 생성하는 것을 키 갱신(Key Update)이라 하므로 옳은 설명이다.","기존 키와 독립적인 방법으로 새 암호키를 생성하는 것을 키 교체(Key Replacement)라 하므로 옳은 설명이다.","키 갱신은 기존 키로 새 키를 만들기 때문에 기존 키가 노출되면 갱신된 키도 추정될 수 있다. 따라서 키 노출 시에는 독립적으로 생성하는 키 교체를 써야 하므로 틀렸다.","키 노출 또는 노출 위협, 유효기간 만료 임박 시 키를 안전하게 변경하고 기존 키는 정지 단계로 전환하는 것은 키 수명주기 관리상 옳은 설명이다."],"rel":["4-4"]},{"n":71,"s":"s4","q":"다음 중 역할기반 접근통제(Role Based Access Control)의 설명으로 틀린 것은?","c":["대개 구현을 위하여 역할에 대한 추상화 작업이 요구된다.","Non-DAC 또는 비임의적 접근통제 모델로도 불린다.","사용자의 역할 및 직능에 따라 접근을 통제하는 방식이다.","사용자에게 지나친 권한이 부여될 우려가 있다."],"a":3,"e":"RBAC는 직무(역할)에 필요한 권한만 역할에 할당하고 사용자를 역할에 배정하므로 최소 권한 원칙과 직무 분리를 구현하기 쉽다. 사용자에게 과도한 권한이 부여될 우려는 소유자 재량으로 권한을 넘기는 DAC의 단점에 가깝다.","ce":["RBAC는 조직의 직무를 역할로 추상화해 권한을 묶는 작업(역할 공학)이 선행되어야 하므로 옳은 설명이다.","RBAC는 소유자 재량이 아니라 관리자가 중앙에서 역할을 통해 권한을 관리하므로 비임의적(Non-DAC) 접근통제로 분류되어 옳다.","RBAC는 사용자의 역할·직무에 따라 접근 권한을 부여하는 방식이므로 옳은 설명이다.","RBAC는 역할에 필요한 권한만 부여해 최소 권한과 직무 분리를 구현하기 쉽다. 사용자에게 지나친 권한이 부여될 우려는 소유자가 임의로 권한을 넘기는 DAC의 단점이므로 틀렸다."],"rel":["4-10"]},{"n":72,"s":"s4","q":"Kerberos 프로토콜이 적용된 시스템에 대한 설명 중 틀린 것은?","c":["사용자, 클라이언트, 인증서버, 티켓발급 서버, 응용서버로 구성된다.","인증된 클라이언트만 서버에 접근하도록 고안된 보안시스템이다.","인증 혹은 티켓 발급 서버가 정지되면 전체 서비스가 중단된다.","데이터의 무결성, 기밀성, 가용성, 부인방지 등의 보안 서비스를 제공한다."],"a":3,"e":"Kerberos는 대칭키 기반 티켓으로 인증과 기밀성·무결성을 제공하지만, 대칭키를 사용하므로 부인방지를 제공하지 못하고 KDC(AS·TGS)가 단일 장애점이라 가용성도 보장하지 못한다. ③처럼 KDC 정지 시 전체 서비스가 중단되는 것이 대표적 단점이다.","ce":["Kerberos는 사용자·클라이언트, 인증 서버(AS), 티켓 발급 서버(TGS), 응용 서버로 구성되므로 옳은 설명이다(AS+TGS=KDC).","티켓으로 인증된 클라이언트만 응용 서버에 접근하도록 고안된 네트워크 인증 시스템이므로 옳다.","KDC(AS·TGS)가 단일 장애점이라 정지되면 새 티켓을 받지 못해 전체 서비스가 중단되는 것이 Kerberos의 대표 단점으로 옳다.","Kerberos는 대칭키 기반이라 부인방지를 제공하지 못하고, KDC 단일 장애점 때문에 가용성도 보장하지 않으므로 틀린 설명이다."],"rel":["2-8","4-12"]},{"n":73,"s":"s4","q":"다음 지문에서와 같이 정의되었을 때, A가 B에게 메시지 M을 암호화 하여 보내고자 한다. 올바른 설명은?","c":["1","1","1","1"],"a":2,"e":"A가 B에게 기밀성을 보장해 보내려면 수신자 B의 공개키(Bpub)로 암호화하고, B는 자신의 개인키(Bpri)로 복호화해야 한다. 원문 보기가 수식 복원 오류로 소실되어 있으며, 공식 정답은 ③이다.","ce":["원문 보기 수식이 복원 오류로 소실되어(모두 '1'로 표시) 판단 근거가 없다 — 공식 정답 ③ 기준. 원칙은 기밀성을 위해 B의 공개키로 암호화하는 것이다.","원문 보기 수식 소실로 판단 근거 없음 — 공식 정답 ③ 기준. A의 개인키로 암호화하면 누구나 Apub로 복호화할 수 있어 기밀성이 아닌 서명 효과만 난다.","원문 수식은 소실되었으나 공식 정답이다. A는 수신자 B의 공개키(Bpub)로 M을 암호화하고, B는 자신의 개인키(Bpri)로 복호화해야 기밀성이 보장된다.","원문 보기 수식 소실로 판단 근거 없음 — 공식 정답 ③ 기준. 송신자 키(Apub·Apri)로 암호화하면 B만 복호화할 수 있는 기밀성이 성립하지 않는다."],"rel":["4-4"],"box":"(   ) : A의 개인키(Apri)와 공개키(Apub) 쌍\n(   ) : B의 개인키(Bpri)와 공개키(Bpub) 쌍\n: 키 로 암호화 표기\n: 키 로 복호화 표기\n: 평문 메시지\n: 암호문 메시지","flag":"comcbt 복원 오류: 지문 기호·보기 수식 소실(보기 모두 '1'로 표시), 관리자 주석상 정답 3번"},{"n":74,"s":"s4","q":"X.509 확장 영역에 속하는 것은?","c":["공개키","서명 알고리즘","인증서의 버전","주체 키 식별자"],"a":3,"e":"X.509 v3 확장 영역에는 주체 키 식별자, 기관 키 식별자, 키 용도, 인증서 정책, 주체 대체 이름, CRL 배포 지점 등이 있다. 버전, 서명 알고리즘, 주체 공개키 정보는 인증서의 기본 필드이다.","ce":["주체 공개키 정보(Subject Public Key Info)는 X.509 v1부터 있는 기본 필드로 확장 영역이 아니다.","서명 알고리즘(Signature Algorithm) 식별자는 인증서 기본 필드이며 확장 영역에 속하지 않는다.","버전(Version)은 v1·v2·v3를 표시하는 기본 필드로, 확장 영역은 v3에서 추가된 별도 영역이다.","주체 키 식별자(Subject Key Identifier)는 기관 키 식별자·키 용도·인증서 정책·주체 대체 이름 등과 함께 X.509 v3 확장 영역에 속하므로 정답이다."],"rel":["4-7"]},{"n":75,"s":"s4","q":"ⓐ, ⓑ 각각이 설명하는 서명 방식은 무엇인가?","c":["ⓐ 이중서명 ⓑ 정규서명","ⓐ 이중서명 ⓑ 분할서명","ⓐ 은닉서명 ⓑ 분할서명","ⓐ 은닉서명 ⓑ 이중서명"],"a":3,"e":"은닉서명(Blind Signature)은 서명자가 메시지 내용을 모른 채 서명해 익명성을 제공하며 전자화폐·전자투표에 쓰인다. 이중서명(Dual Signature)은 SET에서 주문정보와 지불정보 해시를 결합해 서명함으로써 상점과 은행이 각각 필요한 정보만 보게 한다.","ce":["ⓐ 메시지를 보여주지 않고 서명받아 익명성을 주는 방식은 은닉서명이고, 이중서명은 ⓑ SET의 주문·지불 정보 결합 서명이다. 정규서명은 해당 방식 명칭이 아니다.","이중서명은 ⓐ가 아니라 ⓑ에 해당하고, 분할서명은 두 해시를 결합해 한 번 서명하는 SET 방식의 명칭이 아니다.","ⓐ 은닉서명은 맞지만, ⓑ처럼 지불정보·주문정보 해시를 합쳐 다시 해시한 뒤 개인키로 서명하는 것은 분할서명이 아니라 이중서명이다.","ⓐ 서명자가 내용을 모른 채 서명해 익명성을 주는 은닉서명(Blind Signature), ⓑ SET에서 주문·지불 정보 해시를 결합해 서명하는 이중서명(Dual Signature)이므로 정답이다."],"rel":["4-6","3-10"],"box":"ⓐ 사용자 A가 서명자 B에게 자신의 메시지(서명문)를 보여주지 않고 서명자가 서명하는 방식으로 서명을 받는 사람의 신원과 서명문을 연결시킬 수 없도록 익명성을 제공하는 서명방식으로 메시지의 비밀성을 지키면서 타인의 인증을 받고자 하는 경우 사용됨.\nⓑ 전자상거래에서 구매자는 해당 주문에 대해 지불 정보와 주문 정보에 대해 각각의 해시값을 구하고, 두 해시를 합해 다시 한 번 해시값을 구하여 구매자가 마지막 해시값을 자신의 개인키로 서명하는 방식임."},{"n":76,"s":"s4","q":"이론적으로 전수공격(Brute Force Attack)에 가장 강한 암호 기법은?","c":["RC4","3-DES","AES","OTP(One Time Pad)"],"a":3,"e":"일회용 패드(OTP)는 평문과 같은 길이의 완전 무작위 키를 한 번만 사용하므로 모든 평문이 동일 확률로 가능해 전수 조사로도 평문을 특정할 수 없는 완전 안전성(Shannon)을 갖는다. RC4·3-DES·AES는 계산적 안전성에 의존한다.","ce":["RC4는 가변 길이 키(40~2048비트)의 스트림 암호로 계산적 안전성에 의존하며, 키 스트림 편향 등 알려진 약점도 있어 전수공격에 이론적으로 무한히 강하지 않다.","3-DES는 DES를 3번 적용해 유효 키 길이를 112비트 수준으로 늘린 방식으로, 키 공간이 유한해 이론적으로 전수공격이 가능하다.","AES는 128·192·256비트 키로 현실적으로 전수공격이 불가능하지만, 이는 계산적 안전성이며 이론적으로는 유한한 키 공간을 모두 시도할 수 있다.","OTP(일회용 패드)는 평문 길이와 같은 완전 무작위 키를 한 번만 쓰므로 모든 평문이 같은 확률로 가능해, 전수공격으로도 평문을 특정할 수 없는 완전 안전성(Shannon)을 가지므로 정답이다."],"rel":["4-1"]},{"n":77,"s":"s4","q":"메시지 인증을 위해 송신자가 메시지와 이에 대한 MAC 값을 동시에 수신자에게 보낼 때, 중간 공격자가 이를 가로채 가지고 있다가 송신자를 가장하여 언제든 수신자에게 보내는 재전송 공격이 가능하다. 다음 중 이를 방어하는 기술이 아닌 것은?","c":["메시지를 보낼 때 마다 순서번호(Sequence Number)를 포함시켜 MAC 값을 계산한다.","메시지를 보낼 때 마다 순서번호(Sequence Number)를 포함시켜 MAC 값을 계산한다.","비표(Nonce) 값을 포함시켜 MAC 값을 계산한다.","MAC 값을 암호화한다."],"a":3,"e":"재전송 공격은 순서번호, 타임스탬프, 비표(Nonce)처럼 매번 달라지는 값을 MAC 계산에 포함시켜 방어한다. MAC 값을 암호화해도 가로챈 메시지를 그대로 다시 보내면 수신자는 유효한 것으로 판단하므로 재전송을 막지 못한다.","ce":["메시지마다 증가하는 순서번호를 MAC 계산에 포함하면, 이미 받은 번호의 메시지가 다시 오면 재전송으로 판별할 수 있어 올바른 방어 기술이다.","원문 복원 오류로 ①과 같은 보기가 중복되었다(원래는 '타임스탬프'로 추정). 순서번호든 타임스탬프든 매번 달라지는 값을 MAC에 넣어 재전송을 탐지하는 방어 기술이다.","비표(Nonce)는 한 번만 쓰는 임의값으로, 이를 MAC 계산에 포함하면 같은 Nonce의 재사용을 거부해 재전송을 막을 수 있다.","MAC 값을 암호화해도 공격자는 가로챈 메시지와 암호화된 MAC을 그대로 다시 보내면 되므로 수신자는 유효한 메시지로 판단한다. 재전송 방어 기술이 아니므로 정답이다."],"rel":["4-5"],"flag":"원문 보기 ①·②가 동일(순서번호) — ② 원래 '타임스탬프(Timestamp)'로 추정"},{"n":78,"s":"s4","q":"Kerberos 키 분배 프로토콜의 기반 기술에 해당하는 것은?","c":["Needham-Schroeder 프로토콜","Diffie-Hellman 프로토콜","Challenge-Response 프로토콜","RSA 이용 키 분배 프로토콜"],"a":0,"e":"Kerberos는 신뢰할 수 있는 제3자(KDC)가 세션키를 분배하는 Needham-Schroeder 대칭키 프로토콜에 타임스탬프를 더해 재전송 약점을 보완한 것이다. Diffie-Hellman은 제3자 없이 키를 합의하는 공개키 기반 키 교환 방식이다.","ce":["Kerberos는 신뢰할 수 있는 제3자(KDC)가 대칭 세션키를 분배하는 Needham-Schroeder 대칭키 프로토콜에 타임스탬프를 더해 재전송 약점을 보완한 것이므로 정답이다.","Diffie-Hellman은 제3자 없이 두 당사자가 이산대수 기반으로 공유키를 합의하는 방식으로, KDC가 티켓·세션키를 발급하는 Kerberos의 기반이 아니다.","Challenge-Response는 난수 질의에 대한 응답으로 인증하는 일반 기법일 뿐, Kerberos 키 분배 구조(KDC·티켓)의 기반 프로토콜 명칭이 아니다.","Kerberos는 공개키(RSA)가 아닌 대칭키 기반으로 키를 분배하므로 RSA 이용 키 분배 프로토콜과 무관하다."],"rel":["4-12","2-8"]},{"n":79,"s":"s4","q":"다음 지문에서 설명하고 있는 대칭키 암호 알고리즘은?","c":["SEED","DES","SHA-1","IDEA"],"a":3,"e":"IDEA는 64비트 블록, 128비트 키, 8라운드(+출력 변환)로 XOR·모듈러 덧셈·모듈러 곱셈을 16비트 단위로 수행한다. SEED는 128비트 블록·16라운드, DES는 56비트 키·16라운드이며, SHA-1은 해시 함수이다.","ce":["SEED는 한국인터넷진흥원이 개발한 128비트 블록·128비트 키·16라운드 Feistel 구조 블록 암호로, 64비트 블록·8라운드와 맞지 않는다.","DES는 64비트 블록이지만 키는 56비트(패리티 포함 64비트)이고 16라운드 Feistel 구조이므로 지문과 다르다.","SHA-1은 160비트 해시값을 출력하는 해시 함수로 키를 쓰는 대칭키 암호 알고리즘이 아니다.","IDEA는 64비트 평문 블록을 128비트 키로 8라운드(+출력 변환) 처리하며, XOR·모듈러 덧셈·모듈러 곱셈을 모두 16비트 단위로 수행하므로 정답이다."],"rel":["4-2"],"box":"128비트의 키를 사용하며 64비트의 평문을 8라운드를 거쳐 64비트 암호문으로 만든다. 모든 연산이 16비트 단위로 이루어지도록 하며 16비트 프로세서에서 구현이 용이한 암호알고리즘이다."},{"n":80,"s":"s4","q":"다음 지문은 공개키 암호방식에 대한 내용을 설명한 것이다. (가)~(마)에 들어가야 할 단어로 옳은 것은?","c":["(가) 정수 (나) p × q (다) 이산대수 문제 (라) RSA (마) ElGamal","(가) 소수 (나) p + q (다) 소인수분해 문제 (라) 타원곡선암호 (마) Diffie-Hellman 암호","(가) 실수 (나) p + q (다) 이산대수 문제 (라) Rabin 암호 (마) 타원곡선암호","(가) 소수 (나) p × q (다) 소인수분해 문제 (라) RSA (마) Rabin 암호"],"a":3,"e":"두 큰 소수의 곱 n = p×q는 쉽게 계산되지만 n에서 p, q를 찾는 소인수분해는 어렵다는 성질에 기반한 알고리즘이 RSA와 Rabin이다. ElGamal·Diffie-Hellman·타원곡선암호는 이산대수 문제에 기반한다.","ce":["(나) p×q와 (라) RSA는 맞지만, p·q는 임의 정수가 아니라 소수이고 n에서 p·q를 찾는 어려움은 이산대수가 아니라 소인수분해 문제이며, ElGamal은 이산대수 기반이다.","(가) 소수·(다) 소인수분해는 맞지만 n=p+q가 아니라 p×q이고, 타원곡선암호·Diffie-Hellman은 이산대수 문제에 기반한다.","p·q는 실수가 아니라 소수, n은 p+q가 아니라 p×q, 어려운 문제는 소인수분해이며, 타원곡선암호는 이산대수 기반이라 대부분 어긋났다.","두 소수 p·q의 곱 n=p×q에서 p·q를 찾기 어려운 소인수분해 문제에 기반한 대표 알고리즘이 RSA와 Rabin이므로 정답이다."],"rel":["4-4"],"box":"두 개의 ( 가 ) p, q를 선택하며 n = ( 나 )를 계산한다. 이때, p, q를 알고 있는 사람은 n을 계산하기 쉽지만, n만 알고 있는 사람은 n으로부터 p, q를 찾는 것은 어렵다. 이를 ( 다 )라고 한다. 이에 기반한 대표적인 공개키 암호 알고리즘은 ( 라 ), ( 마 )이다."},{"n":81,"s":"s5","q":"과학기술정보통신부장관은 다음 중 어느 하나에 해당하는 사유를 발견한 경우 정보보호 관리체계 인증을 취소할 수 있다. 해당 사유 발생 시 반드시 인증을 취소해야 하는 것은?","c":["거짓이나 그 밖의 부정한 방법으로 정보보호 관리체계 인증을 받은 경우","사후관리를 거부한 경우","과학기술정보통신부장관이 정한 인증기준에 미달하게 된 경우","사후관리를 방해한 경우"],"a":0,"e":"정보통신망법 제47조에 따라 거짓이나 그 밖의 부정한 방법으로 인증을 받은 경우에는 인증을 반드시 취소해야 하는 필요적 취소 사유이다. 인증기준 미달, 사후관리 거부·방해는 취소할 수 있는 임의적 취소 사유이다(개정 여부 확인).","ce":["거짓이나 부정한 방법으로 인증을 받은 경우는 정보통신망법 제47조상 반드시 취소해야 하는 필요적 취소 사유이므로 정답이다(개정 여부 확인).","사후관리를 거부한 경우는 인증을 '취소할 수 있는' 임의적 취소 사유로, 반드시 취소해야 하는 사유는 아니다.","인증기준에 미달하게 된 경우는 보완 기회를 줄 수 있는 임의적 취소 사유로, 필요적 취소 사유가 아니다.","사후관리를 방해한 경우도 거부와 함께 '취소할 수 있는' 임의적 취소 사유이다."],"rel":["5-11"]},{"n":82,"s":"s5","q":"개인정보의 안정성 확보조치 기준(고시)의 제7조(개인정보의 암호화)에 따라 반드시 암호화하여 저장해야하는 개인정보가 아닌 것은?","c":["비밀번호","고유식별번호","바이오 정보","전화번호"],"a":3,"e":"당시 개인정보의 안전성 확보조치 기준 제7조는 비밀번호(일방향 암호화), 고유식별정보, 바이오정보를 저장 시 암호화 대상으로 규정했다. 전화번호는 일반 개인정보로 저장 시 암호화 의무 대상이 아니다(개정 여부 확인).","ce":["비밀번호는 제7조에 따라 저장 시 복호화되지 않도록 일방향(해시) 암호화해야 하는 대상이다.","고유식별번호(주민등록번호·여권번호·운전면허번호·외국인등록번호)는 저장 시 암호화해야 하는 대상이다.","바이오정보(지문·홍채·얼굴 등)는 당시 고시 제7조에서 저장 시 암호화해야 하는 대상으로 규정되었다(개정 여부 확인).","전화번호는 일반 개인정보로, 당시 고시상 저장 시 암호화 의무 대상(비밀번호·고유식별정보·바이오정보 등)에 포함되지 않으므로 정답이다(개정 여부 확인)."],"rel":["5-9"]},{"n":83,"s":"s5","q":"아래 지문에서 설명하고 있는 것은 무엇인가?","c":["정성적 위험분석","정량적 위험분석","상세 위험분석","베이스라인 접근법"],"a":3,"e":"베이스라인 접근법은 표준화된 보호 대책 목록(체크리스트)을 기준으로 현재 적용되지 않은 대책을 식별하는 방식으로, 빠르고 비용이 적지만 조직 특성을 반영하기 어렵다. 상세 위험분석은 자산·위협·취약점을 구체적으로 평가하는 방식이다.","ce":["정성적 위험분석은 델파이·시나리오법처럼 전문가 판단으로 위험을 등급(상·중·하)으로 평가하는 방법으로, 표준 대책 체크리스트 대조 방식이 아니다.","정량적 위험분석은 ALE 등 금액·확률 수치로 위험을 계산하는 방법으로, 적용되지 않은 표준 대책을 확인하는 방식과 다르다.","상세 위험분석은 자산·위협·취약점을 구체적으로 식별·평가해 조직 맞춤 대책을 도출하는 방법으로 시간·비용이 많이 든다.","베이스라인 접근법은 모든 시스템에 표준화된 보호대책 목록(체크리스트)을 적용해 미적용 대책을 찾는 방법이므로 정답이다."],"rel":["5-12"],"box":"모든 정보시스템에 대하여 표준화된 보안 대책을 제시하며 Check List로 보안대책이 있는지 판단한다. 즉 적용되지 않은 보안대책을 확인하는 위험 분석 방법이다."},{"n":84,"s":"s5","q":"정보보호 내부 감사 시 고려해야할 사항으로 가장 부적합한 것은?","c":["내부감사를 수행하는 구성원은 정보보호 전문가들로 제한한다.","감사의 범위는 다양한 위험을 분석 및 검토할 수 있도록 가능한 포괄적이어야 한다.","감사활동은 기업 내외부로부터 독립성을 유지할 수 있도록 해야 한다.","내부감사는 조직의 위험을 파악하여 개선사항을 제시할 수 있다."],"a":0,"e":"내부 감사는 독립성과 객관성을 갖춘 인원이 수행하면 되며, 업무·법률 등 다양한 관점이 필요하므로 정보보호 전문가로만 제한할 필요는 없다. 포괄적 범위, 독립성 유지, 개선사항 제시는 올바른 감사 고려사항이다.","ce":["내부 감사는 독립성·객관성을 갖춘 인원이면 되고 업무·법률·IT 등 다양한 관점이 필요하므로 정보보호 전문가로만 제한할 필요가 없어 가장 부적합하다.","감사 범위를 포괄적으로 잡아야 조직 전반의 다양한 위험을 분석·검토할 수 있으므로 적절한 고려사항이다.","감사 활동은 피감 부서와 이해관계에서 독립적이어야 객관적 결과를 낼 수 있으므로 적절한 고려사항이다.","내부 감사는 조직의 위험과 통제 미비점을 파악해 개선사항을 제시하는 것이 목적이므로 적절한 설명이다."],"rel":["5-12"]},{"n":85,"s":"s5","q":"100만명 미만의 정보주체에 관한 개인정보를 보유한 중소기업의 내부관리계획의 내용에 포함하지 않아도 될 사항은 무엇인가?","c":["개인정보 보호책임자의 지정에 관한 사항","개인정보 유출사고 대응·계획 수립·시행에 관한 사항","개인정보의 암호화 조치에 관한 사항","개인정보 처리업무를 위탁하는 경우 수탁자에 대한 관리 및 감독에 관한 사항"],"a":3,"e":"당시 안전성 확보조치 기준(2019년 고시)은 100만명 미만 정보주체 정보를 처리하는 중소기업(유형2)이 내부관리계획에서 위험도 분석·대응, 수탁자 관리·감독 사항 등을 제외할 수 있도록 했다. 보호책임자 지정, 유출사고 대응, 암호화 조치는 포함해야 한다. 2023년 고시 개정으로 유형 구분이 통합되었으므로 현행 기준은 개정 여부 확인이 필요하다.","ce":["개인정보 보호책임자 지정에 관한 사항은 규모와 관계없이 내부관리계획에 포함해야 하는 기본 사항이다.","개인정보 유출사고 대응 계획 수립·시행에 관한 사항은 당시 고시상 중소기업 유형도 포함해야 하는 항목이다(개정 여부 확인).","개인정보의 암호화 조치에 관한 사항은 안전성 확보조치의 핵심으로 내부관리계획에 포함해야 한다.","당시(2019년) 고시는 100만명 미만 정보주체를 보유한 중소기업이 수탁자 관리·감독 사항 등을 내부관리계획에서 제외할 수 있게 했으므로 정답이다. 2023년 고시 개정으로 유형 구분이 바뀌어 현행 기준은 개정 여부 확인이 필요하다."],"rel":["5-9"]},{"n":86,"s":"s5","q":"다음 중 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제47조의 정보보호 관리체계의 인증 제도에 대한 설명으로 옳지 않은 것은?","c":["정보보호 관리체계 인증의 유효기간은 3년이다.","정보보호 관리체계 인증은 의무 대상자는 반드시 인증을 받아야 하며 의무 대상자가 아닌 경우에도 인증을 취득할 수 있다.","정보보호 관리체계는 정보통신망의 안정성·신뢰성 확보를 위하여 관리적·기술적·물리적 보호조치를 포함한 종합적 관리체계를 의미한다.","정보보호 관리체계 의무대상자는 국제표준 정보보호 인증을 받거나 정보보호 조치를 취한 경우에는 인증 심사의 전부를 생략할 수 있다."],"a":3,"e":"정보통신망법 제47조는 국제표준 정보보호 인증을 받거나 정보보호 조치를 취한 경우 인증 심사의 '일부'를 생략할 수 있다고 규정하므로 '전부'는 틀렸다. 인증 유효기간 3년, 의무·자율 인증 병행은 맞는 설명이다(개정 여부 확인).","ce":["정보통신망법 제47조에 따른 ISMS 인증의 유효기간은 3년이므로 옳은 설명이다(개정 여부 확인).","의무 대상자는 반드시 인증을 받아야 하고, 의무 대상이 아닌 사업자도 자율적으로 인증을 신청해 취득할 수 있으므로 옳다.","ISMS는 정보통신망의 안정성·신뢰성 확보를 위한 관리적·기술적·물리적 보호조치를 포함한 종합적 관리체계라는 정의로 옳다.","국제표준 정보보호 인증을 받거나 정보보호 조치를 취한 경우 인증 심사의 '일부'를 생략할 수 있을 뿐 '전부' 생략은 불가하므로 틀렸다(개정 여부 확인)."],"rel":["5-11"]},{"n":87,"s":"s5","q":"개인정보처리자가 정보주체의 동의를 받을 때 정보주체에게 알려야 하는 항목이 아닌 것은?","c":["개인정보의 수집·이용 목적","수집하려는 개인정보의 항목","개인정보의 보유 및 이용 기간","개인정보의 수집 출처"],"a":3,"e":"개인정보 보호법 제15조 제2항에 따라 동의 시 수집·이용 목적, 수집 항목, 보유·이용 기간, 동의 거부 권리 및 거부 시 불이익을 알려야 한다. 수집 출처는 정보주체 이외로부터 수집한 경우 요구 시 고지하는 사항(제20조)이다.","ce":["개인정보의 수집·이용 목적은 개인정보 보호법 제15조 제2항에 따라 동의를 받을 때 알려야 하는 항목이다.","수집하려는 개인정보의 항목은 동의 시 정보주체에게 알려야 하는 법정 고지 항목이다.","개인정보의 보유 및 이용 기간은 동의 시 알려야 하는 법정 고지 항목이다.","수집 출처는 동의 시 고지 항목이 아니라, 정보주체 이외로부터 수집한 개인정보에 대해 정보주체가 요구할 때 알리는 사항(제20조)이므로 정답이다."],"rel":["5-8"]},{"n":88,"s":"s5","q":"정성적 위험분석 방법론에 해당되지 않는 것은?","c":["델파이 기법","순위 결정법","시나리오법","과거 자료 분석법"],"a":3,"e":"과거 자료 분석법은 과거 자료를 통계적으로 분석해 발생 확률을 수치로 산출하는 정량적 분석 방법이다. 델파이 기법, 순위 결정법, 시나리오법, 퍼지 행렬법은 전문가 판단에 의존하는 정성적 방법이다.","ce":["델파이 기법은 전문가 집단에 설문을 반복해 의견을 수렴하는 정성적 위험분석 방법이다.","순위 결정법은 위협·위험을 상호 비교해 우선순위를 매기는 정성적 방법이다.","시나리오법은 특정 조건에서 위협이 일으킬 결과를 가정해 추정하는 정성적 방법이다.","과거 자료 분석법은 과거 사고 자료를 통계 처리해 발생 확률을 수치로 산출하는 정량적 방법이므로 정성적 방법에 해당하지 않아 정답이다."],"rel":["5-2"]},{"n":89,"s":"s5","q":"다음 중 아래 내용에 해당하는 위험분석 방법론으로 적절히 짝지은 것은?","c":["㉠ 시나리오법 ㉡ 델파이법","㉠ 확률 분포법 ㉡ 순위결정법","㉠ 델파이법 ㉡ 확률 분포법","㉠ 시나리오법 ㉡ 순위결정법"],"a":3,"e":"시나리오법은 어떤 사건도 기대대로 발생하지 않는다는 전제에서 특정 조건의 위협 결과를 추정하고, 순위결정법은 위협을 상호 비교해 우선순위를 도출한다. 델파이법은 전문가 집단의 의견을 반복 수렴하는 방법이고, 확률 분포법은 정량적 방법이다.","ce":["㉠ 시나리오법은 맞지만, ㉡ 델파이법은 전문가 의견을 반복 설문으로 수렴하는 방법이다. 위협을 상호 비교해 우선순위를 매기는 것은 순위결정법이다.","㉡ 순위결정법은 맞지만, ㉠ 확률 분포법은 미지 사건의 확률분포를 추정해 위험을 계산하는 정량적 방법으로, '기대대로 발생하지 않는다'는 전제의 결과 추정은 시나리오법이다.","델파이법은 ㉠이 아니라 전문가 합의 방법이고, 확률 분포법은 ㉡의 상호 비교 우선순위 도출 방법이 아니다.","㉠ 어떤 사건도 기대대로 일어나지 않는다는 전제로 결과를 추정하는 시나리오법, ㉡ 위협을 상호 비교해 우선순위를 도출하는 순위결정법이므로 정답이다."],"rel":["5-2"],"box":"㉠ 어떤 사건도 기대대로 발생하지 않는다는 사실에 근거하여 일정 조건하에서 위협에 대한 발생 가능한 결과들을 추정하는 방법\n㉡ 각각의 위협을 상호 비교하여 최종 위협요인의 우선순위를 도출하는 방법"},{"n":90,"s":"s5","q":"다음의 ISMS 인증 의무 대상자에 대한 설명으로 잘못 기술된 것은?","c":["전기통신사업법의 전기통신사업자로 전국적으로 정보통신망 서비스를 제공하는 사업자","타인의 정보통신서비스 제공을 위하여 집적된 정보통신시설을 운영·관리하는 사업자","정보통신서비스 부문 전년도 매출액 100억 이상 사업자","전년도말 기준 직전 6개월간 일일 평균 이용자 수 100만명 이상 사업자"],"a":3,"e":"ISMS 의무 대상 기준은 전년도 말 기준 직전 3개월간 일일평균 이용자 수 100만명 이상인 사업자이므로 '6개월'은 틀렸다. ISP(전국 정보통신망 서비스), IDC(집적정보통신시설), 정보통신서비스 매출 100억원 이상 사업자는 맞는 의무 대상이다(개정 여부 확인).","ce":["전기통신사업법상 전기통신사업자로 전국적으로 정보통신망 서비스를 제공하는 사업자(ISP)는 ISMS 의무 대상이다.","타인의 정보통신서비스를 위해 집적정보통신시설을 운영·관리하는 사업자(IDC)는 ISMS 의무 대상이다.","정보통신서비스 부문 전년도 매출액 100억원 이상 사업자는 당시 ISMS 의무 대상 기준에 해당한다(개정 여부 확인).","이용자 수 기준은 전년도 말 기준 직전 '3개월간' 일일평균 이용자 수 100만명 이상이므로 '6개월'은 틀렸다(개정 여부 확인)."],"rel":["5-11"]},{"n":91,"s":"s5","q":"다음 경제협력개발기구(OECD) 개인정보 보안 8원칙에 대한 설명 중 옳지 않은 것은?","c":["수집 제한의 법칙: 개인정보는 적법하고 공정한 방법을 통해 수집해야 한다.","목적 명시의 원칙(Purpose Specification Principle): 개인정보는 수집 과정에서 수집 목적을 명시하고, 명시된 목적에 적합하게 이용해야 한다.","비공개의 원칙(Closedness Principle): 개인정보의 처리 및 보호를 위한 관리자에 대한 정보는 비공개해야 한다.","책임의 원칙(Accountability Principle): 개인정보 관리자에게 원칙 준수 의무 및 책임을 부과해야 한다."],"a":2,"e":"OECD 8원칙은 수집 제한, 정보 정확성, 목적 명시, 이용 제한, 안전성 확보, 공개(Openness), 개인 참가, 책임의 원칙이다. 개인정보 처리 방침과 관리자 정보는 공개해야 하므로 '비공개의 원칙'은 존재하지 않는다.","ce":["수집 제한의 원칙은 개인정보를 적법·공정한 수단으로, 필요 시 정보주체의 인지·동의를 얻어 수집해야 한다는 원칙으로 옳다.","목적 명시의 원칙은 수집 시점에 목적을 명시하고 이후 이용은 그 목적에 부합해야 한다는 원칙으로 옳다.","OECD 8원칙에는 '비공개의 원칙'이 없고, 개인정보 처리 정책과 관리자 정보를 공개해야 한다는 공개(Openness)의 원칙이 있으므로 틀렸다.","책임의 원칙은 개인정보 관리자에게 원칙 준수 의무와 책임을 부과하는 것으로 옳다."],"rel":["5-8"]},{"n":92,"s":"s5","q":"다음 중 위험분석을 위한 ALE 계산에 사용되지 않는 값은 무엇인가?","c":["자산가치","노출계수","연간발생률","우선순위"],"a":3,"e":"ALE(연간 예상 손실) = SLE × ARO이며, SLE(단일 예상 손실) = 자산가치(AV) × 노출계수(EF)이다. 우선순위는 ALE 계산 요소가 아니라 분석 결과를 활용하는 단계의 개념이다.","ce":["자산가치(AV)는 SLE = AV × EF 계산에 쓰이므로 ALE 계산 요소이다.","노출계수(EF)는 위협 발생 시 자산가치가 손실되는 비율로 SLE 계산에 쓰이므로 ALE 계산 요소이다.","연간발생률(ARO)은 ALE = SLE × ARO에서 곱해지는 값이므로 ALE 계산 요소이다.","우선순위는 ALE 산출 이후 대책 선정에 활용하는 결과 해석 단계의 개념으로, ALE 계산식(AV×EF×ARO)에 쓰이지 않으므로 정답이다."],"rel":["5-2"]},{"n":93,"s":"s5","q":"정보시스템의 개발 및 시험 과정을 검토한 결과, 정보보안 측면에서 가장 적절하지 않은 것은?","c":["시험데이터로 임의의 데이터를 생성하거나 운영데이터를 가공 변환한 후 사용하고 있다.","실 운영데이터를 테스트 용도로 사용하고 테스트 완료 후 테스트 DB에서 삭제하였다.","이전 버전의 소스 코드를 운영 서버에 보관하고 있다.","실 운영데이터를 테스트 용도로 사용하고 테스트 DB에 대해 운영 DB와 동일한 수준의 접근통제를 적용하고 있다."],"a":2,"e":"소스 코드와 이전 버전 프로그램은 운영 환경과 분리된 별도 저장소(형상관리 시스템)에 보관해야 하며, 운영 서버에 두면 소스 유출·악용 위험이 있다. 운영데이터를 불가피하게 시험에 쓰는 경우 동일 수준 접근통제 적용과 시험 후 삭제는 허용되는 통제이다.","ce":["시험 데이터를 임의로 생성하거나 운영 데이터를 가공·변환(비식별화)해 쓰는 것은 권장되는 시험 데이터 관리 방식이다.","불가피하게 운영 데이터를 시험에 쓴 뒤 테스트 DB에서 삭제하는 것은 허용되는 보완 통제이다.","이전 버전 소스 코드는 운영 환경과 분리된 형상관리 저장소에 보관해야 하며, 운영 서버에 두면 소스 유출·악용 위험이 있어 가장 부적절하므로 정답이다.","운영 데이터를 시험에 쓸 때 테스트 DB에 운영 DB와 같은 수준의 접근통제를 적용하는 것은 적절한 보호조치이다."],"rel":["5-11"]},{"n":94,"s":"s5","q":"다음 지문에서 설명하는 백업 설비는?","c":["콜드 사이트","미러 사이트","웜 사이트","핫 사이트"],"a":3,"e":"핫 사이트는 주 센터와 동일한 설비를 대기(Standby) 상태로 유지하다 재해 시 수 시간 내 전환하는 방식이다. 미러 사이트는 동일 설비를 Active-Active로 실시간 동시 운영하며, 웜 사이트는 일부 핵심 설비만, 콜드 사이트는 공간·기반 시설만 확보한다.","ce":["콜드 사이트는 전산실 공간·전원·배선 등 기반 시설만 확보하고 장비는 재해 후 반입하므로, 동일 수준 자원을 대기 상태로 두는 방식이 아니다.","미러 사이트는 주 센터와 동일한 설비를 Active-Active로 실시간 동시 운영하므로, Active-Standby로 대기하다 전환하는 지문과 다르다.","웜 사이트는 중요 업무용 일부 설비만 갖춰 두는 방식으로, 주 센터와 동일한 수준의 자원을 보유하지 않는다.","핫 사이트는 주 센터와 동일한 수준의 IT 자원을 원격지에 대기(Standby) 상태로 두었다가 재해 시 Active로 전환하므로 정답이다."],"rel":["5-3"],"box":"주 센터와 동일한 수준의 정보기술자원을 대기상태(Standby)로 원격지 사이트에 보유하면서(Active-Standby), 주 센터 재해 시 원격지 시스템을 Active 상태로 전환하여 서비스를 제공한다."},{"n":95,"s":"s5","q":"다음 빈칸 ㉠에 들어갈 말로 적절한 것은?","c":["ISMS","PIMS","ISMS-P","GDPR"],"a":2,"e":"ISMS-P(정보보호 및 개인정보보호 관리체계)는 ISMS에 개인정보 생명주기(수집·보유·이용·제공·파기) 보호 요구사항을 통합한 인증으로, 2018년 ISMS와 PIMS를 통합해 도입되었다. ISMS는 정보보호만, GDPR은 EU 개인정보 보호 법규이다.","ce":["ISMS는 정보보호 관리체계 인증으로, 개인정보 생명주기(수집·보유·이용·제공·파기)와 개인정보처리시스템·취급자까지 인증범위에 포함하지 않는다.","PIMS는 개인정보보호 관리체계 인증으로, 2018년 ISMS와 통합되어 ISMS-P로 바뀌었으며 정보보호 전반을 함께 다루지 않았다.","ISMS-P는 정보보호와 개인정보보호 조치가 인증기준에 적합함을 KISA·인증기관이 증명하는 제도로, 개인정보 처리 전 단계를 인증범위에 포함하므로 정답이다.","GDPR은 EU의 일반 개인정보 보호 규정(법률)으로, 국내 인증기관이 증명하는 인증 제도가 아니다."],"rel":["5-11","5-5"],"box":"( ㉠ )은 정보보호 및 개인정보보호를 위한 일련의 조치와 활동이 인증기준에 적합함을 인터넷진흥원 또는 인증기관이 증명하는 제도이다. 인증범위로는 정보서비스의 운영 및 보호에 필요한 조직, 물리적 위치, 정보자산 뿐만 아니라 개인정보 처리를 위한 수집, 보유, 이용, 제공, 파기에 관여하는 개인정보처리 시스템, 취급자를 포함한다."},{"n":96,"s":"s5","q":"다음 지문의 정보통신망 이용촉진 및 정보보호 등에 관한 법률에서 정의하는 용어에 대한 설명으로 옳지 않은 것은 무엇인가?","c":["a, b","b, c","c, d","b, d"],"a":0,"e":"a의 전자문서는 '전자적인 형태로 작성되어 송수신되거나 저장된' 자료이며 '암호화되어'라는 요건이 없고, b의 개인정보는 '생존하는 개인'에 관한 정보로 사망자 정보는 포함하지 않는다. c 침해사고와 d 이용자 정의는 법 조문과 일치한다(개인정보 정의는 2020년 개정으로 개인정보 보호법으로 일원화, 개정 여부 확인).","ce":["a 전자문서는 '전자적 형태로 작성되어 송수신되거나 저장된' 자료로 '암호화되어' 요건이 없고, b 개인정보는 '생존하는 개인'의 정보로 사망자는 제외되므로 a·b가 틀린 설명이라 정답이다(개인정보 정의는 이후 개인정보 보호법으로 일원화, 개정 여부 확인).","b는 틀렸지만 c 침해사고 정의(해킹·바이러스·논리폭탄·메일폭탄·서비스거부·고출력 전자기파)는 법 조문과 일치하므로 옳은 설명이다.","c 침해사고와 d 이용자 정의는 모두 법 조문과 일치하는 옳은 설명이다.","b는 틀렸지만 d '이용자'는 정보통신서비스 제공자의 서비스를 이용하는 자로 법 조문과 일치하는 옳은 설명이다."],"rel":["5-10"],"box":"a. \"전자문서\"란 컴퓨터 등 정보처리능력을 가진 장치에 의하여 전자적인 형태로 작성되어 송수신되거나 암호화되어 저장된 문서형식의 자료로서 표준화된 것을 말한다.\n\nb. \"개인정보\"란 생존 및 사망한 개인에 관한 정보로서 성명·주민등록번호 등에 의하여 특정한 개인을 알아볼 수 있는 부호·문자·음성·음향 및 영상 등의 정보(해당 정보만으로는 특정 개인을 알아볼 수 없어도 다른 정보와 쉽게 결합하여 알아볼 수 있는 경우에는 그 정보를 포함한다)를 말한다.\n\nc. \"침해사고\"란 해킹, 컴퓨터바이러스, 논리폭탄, 메일폭탄, 서비스거부 또는 고출력 전자기파 등의 방법으로 정보통신망 또는 이와 관련한 정보시스템을 공격하는 행위를 하여 발생한 사태를 말한다.\n\nd. \"이용자\"란 정보통신서비스 제공자가 제공하는 정보통신서비스를 이용하는 자를 말한다."},{"n":97,"s":"s5","q":"정보통신망 이용촉진 및 정보보호 등에 관한 법률에 따라 침해사고의 유형별 통계, 해당 정보 통신망의 소통량 통계 및 접속경로별 이용 통계 등의 침해사고 관련 정보를 과학기술정보통신부 장관이나 한국인터넷진흥원에 제공해야 하는 기관이 아닌 것은?","c":["정보보호 전문서비스 기업","주요정보통신서비스 제공자","컴퓨터바이러스 백신소프트웨어 제조자","집적정보통신시설 사업자"],"a":0,"e":"정보통신망법 제48조의2에 따라 침해사고 관련 정보 제공 의무가 있는 자는 주요정보통신서비스 제공자, 집적정보통신시설 사업자, 대통령령으로 정하는 자(백신소프트웨어 제조자, 정보보호산업 관련 사업자 등)이다. 정보보호 전문서비스 기업은 해당 제공 의무 기관으로 규정되어 있지 않다(개정 여부 확인).","ce":["정보보호 전문서비스 기업은 정보통신망법 제48조의2의 침해사고 관련 정보 제공 의무 기관으로 규정되어 있지 않으므로 정답이다(개정 여부 확인).","주요정보통신서비스 제공자는 침해사고 유형별 통계·소통량 통계 등을 제공해야 하는 의무 기관이다.","컴퓨터바이러스 백신소프트웨어 제조자는 대통령령으로 정하는 정보 제공 의무 기관에 해당한다.","집적정보통신시설 사업자(IDC)는 침해사고 관련 정보 제공 의무 기관이다."],"rel":["5-10"]},{"n":98,"s":"s5","q":"다음에서 설명하는 것은?","c":["암호모듈검증 제도","정보보호시스템 공통평가 제도","보안 적합성 검증 제도","정보보호 사전점검 제도"],"a":3,"e":"정보보호 사전점검은 신규 정보통신망·서비스의 기획·설계 단계에서 위협·취약점을 분석해 보호대책을 미리 반영하는 제도로 정보통신망법 제45조의2에 근거했다. 암호모듈검증은 암호모듈 안전성, 공통평가(CC)는 정보보호제품 보안성, 보안적합성 검증은 공공기관 도입 제품을 검증하는 제도이다(개정 여부 확인).","ce":["암호모듈검증 제도(KCMVP)는 공공기관에서 쓰는 암호모듈의 안전성·구현 적합성을 검증하는 제도로, 서비스 구축 단계 보안 컨설팅이 아니다.","정보보호시스템 공통평가 제도(CC)는 정보보호 제품의 보안 기능을 국제공통평가기준으로 평가·인증하는 제품 평가 제도이다.","보안 적합성 검증 제도는 국가·공공기관이 도입하는 정보보호 제품의 안전성을 국가정보원이 검증하는 제도이다.","정보보호 사전점검 제도는 신규 정보통신망·서비스의 계획·설계 단계에서 위협·취약점·위험을 분석해 보호대책을 미리 반영하는 제도이므로 정답이다(개정 여부 확인)."],"rel":["5-10"],"box":"정보통신서비스 제공자는 새로이 정보통신망을 구축하거나 정보통신서비스를 제공하고자 하는 때에는 그 계획 또는 설계에 정보보호에 관한 사항을 고려하여야 한다.\nIT 서비스의 구축 단계에서 정보보호 위협 및 취약점 분석·위험분석 등의 절차를 통해 사전에 취약점을 제거하고 보호대책을 수립하는 일련의 보안 컨설팅 활동이다."},{"n":99,"s":"s5","q":"위험 분석 수행의 주목적은 기업이 피해를 입었을 때 손실 비용에 대한 값을 산정하거나 가치를 부여하기 위해 잠재적 위협의 충격 정도를 정하는 것이다. 위협이 가해질 때 특정 위협이나 위협 그룹에 관련된 위험을 제거하기 위해 적용된 통제나 대응방안을 의미하는 것은?","c":["세이프가드","규제 정책","가이드","복구 절차"],"a":0,"e":"세이프가드(Safeguard, 보호대책)는 위협에 대응해 위험을 감소·제거하기 위해 적용하는 통제·대응 방안이다. 가이드는 권고 지침이고, 복구 절차는 사고 발생 후의 회복 활동이다.","ce":["세이프가드(Safeguard, 보호대책)는 특정 위협과 관련된 위험을 제거·감소하기 위해 적용하는 통제·대응 방안이므로 정답이다.","규제 정책은 법·규정 준수를 위한 조직 방침으로, 특정 위협에 적용하는 개별 통제 수단을 가리키는 용어가 아니다.","가이드는 권고 성격의 지침 문서로 강제 통제나 대응 방안 자체가 아니다.","복구 절차는 사고 발생 후 서비스를 회복하는 사후 활동으로, 위협에 대해 위험을 제거하는 통제 전반을 뜻하지 않는다."],"rel":["5-12"]},{"n":100,"s":"s5","q":"정보보호 관리의 목적, 이유, 범위 등에 대한 거시적이고 개괄적인 설명 중 가장 부적절한 것은?","c":["조직은 정보보호관리를 통해 정보 및 자산의 기밀성, 무결성, 가용성 서비스를 받을 수 있다.","조직이 정보보호관리를 구현하고 실행하는 것은 조직의 목적, 보안요구사항, 조직의 크기 및 구조에 영향을 받는다.","조직의 요구 및 수요에 따라 정보보호관리 규모가 변화될 수 있다.","정보보호관리의 적용 범위는 정보보호 실무자가 위험분석에 의해 결정한다."],"a":3,"e":"정보보호관리의 적용 범위는 조직의 사업 목표·요구사항을 고려해 경영진이 승인·결정하는 사항이며 실무자가 위험분석만으로 정하는 것이 아니다. 조직의 목적·규모·요구에 따라 구현 방식과 규모가 달라진다는 설명은 적절하다.","ce":["정보보호관리의 목적은 정보·자산의 기밀성·무결성·가용성을 확보하는 것이므로 적절한 설명이다.","정보보호관리의 구현 방식은 조직의 목적·보안 요구사항·규모·구조에 따라 달라지므로 적절한 설명이다.","조직의 요구와 사업 변화에 따라 정보보호관리의 규모가 조정될 수 있으므로 적절한 설명이다.","적용 범위는 사업 목표와 요구사항을 고려해 경영진이 결정·승인하는 사항으로, 실무자가 위험분석만으로 정하는 것이 아니므로 부적절하다."],"rel":["5-12"]}]},{"id":"2019-09-07","title":"2019년 9월 7일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"다음 윈도우 운영체제의 기능은?","c":["Privileged Access Management","Privileged Account Management","User Access Control","User Account Control"],"a":3,"e":"UAC(User Account Control, 사용자 계정 컨트롤)는 관리자 계정이라도 평소 표준 권한으로 실행하다가 시스템 설정 변경·소프트웨어 설치 시 권한 상승 확인(또는 관리자 암호)을 요구하는 윈도우 Vista 이후 기능이다. PAM(Privileged Access/Account Management)은 특권 계정 관리 솔루션 개념이며, 'User Access Control'은 윈도우 기능명이 아니다.","ce":["Privileged Access Management(PAM)는 특권 계정의 접근을 통제·기록하는 별도 보안 솔루션 개념으로, 윈도우의 설정 변경 시 확인 대화상자 기능이 아니다.","Privileged Account Management는 관리자·root 같은 특권 계정의 비밀번호·사용 이력을 관리하는 솔루션 개념으로 윈도우 내장 기능명이 아니다.","'User Access Control'은 윈도우 기능명이 아니다. 해당 기능의 정식 명칭은 User Account Control(사용자 계정 컨트롤)이다.","UAC(User Account Control)는 무결성 수준 기반 강제적 접근제어(MIC)를 활용해 평소 표준 권한으로 실행하다가, 설정 변경·소프트웨어 설치 시 동의나 관리자 암호를 요구하므로 정답이다."],"rel":["1-17"],"box":"- 강제적 접근제어를 구현\n- 컴퓨터 설정을 변경하는 작업을 하거나 소프트웨어를 설치할 때 이 대화상자가 나타나 관리자 암호를 요구함"},{"n":2,"s":"s1","q":"보기의 취약점 또는 사이버 공격 중 그 원인이 하드웨어에 기반하는 것은?","c":["Heartbleed","Shellshock","Spectre","WannaCry"],"a":2,"e":"Spectre는 CPU의 분기 예측·투기적 실행(speculative execution) 구조를 악용해 메모리 내용을 유출하는 하드웨어 기반 취약점이다. Heartbleed는 OpenSSL, Shellshock는 Bash의 소프트웨어 결함이며, WannaCry는 SMB 취약점(MS17-010)을 이용한 랜섬웨어이다.","ce":["Heartbleed(CVE-2014-0160)는 OpenSSL의 하트비트 확장에서 길이 검증을 빠뜨려 서버 메모리가 유출되는 소프트웨어 결함이다.","Shellshock(CVE-2014-6271)는 Bash가 환경변수에 정의된 함수 뒤의 명령까지 실행하는 소프트웨어 결함이다.","Spectre는 CPU의 분기 예측·투기적 실행 구조를 악용해 다른 프로세스 메모리를 읽는 하드웨어 기반 취약점이므로 정답이다.","WannaCry는 윈도우 SMBv1 취약점(MS17-010, EternalBlue)을 이용해 전파된 랜섬웨어로 원인이 소프트웨어 취약점이다."],"rel":["1-19"]},{"n":3,"s":"s1","q":"리눅스 설정 파일의 일부이다. 이 설정 파일로 알맞은 것은?","c":["/etc/services","/etc/ports","/etc/protocols","/etc/resolv.conf"],"a":0,"e":"/etc/services는 '서비스명 포트/프로토콜 별칭' 형식으로 서비스와 포트 번호를 매핑하는 파일이다. /etc/protocols는 프로토콜 이름과 IP 프로토콜 번호(tcp 6 등)를, /etc/resolv.conf는 DNS 서버 주소를 정의한다.","ce":["/etc/services는 '서비스명 포트/프로토콜 별칭' 형식으로 서비스와 포트 번호를 매핑하는 파일로, 지문의 'ftp 21/tcp' 형식과 일치해 정답이다.","/etc/ports는 리눅스 표준 설정 파일이 아니다. 서비스-포트 매핑은 /etc/services가 담당한다.","/etc/protocols는 'tcp 6 TCP'처럼 프로토콜 이름과 IP 프로토콜 번호를 매핑하는 파일로, 포트 번호를 담지 않는다.","/etc/resolv.conf는 'nameserver 8.8.8.8'처럼 DNS 서버 주소와 검색 도메인을 지정하는 파일이다."],"rel":["1-16"],"box":"systat 11/tcp users\ndaytime 13/tcp\nftp-data 20/tcp\nftp 21/tcp"},{"n":4,"s":"s1","q":"좀비 프로세스의 존재를 확인하기 위한 명령어들로 올바르게 짝지어진 것은?","c":["(가), (다)","(나), (라)","(가), (나)","(다), (라)"],"a":2,"e":"top의 요약 행은 'Tasks: … N zombie'로 좀비 수를 보여주므로 top -b -n 1 | grep zombie로 확인할 수 있다. ps -ef 출력에서는 좀비 프로세스가 <defunct>로 표시되므로 grep defunct를 사용한다. ps에는 'zombie' 문자열이 나오지 않고 top 프로세스 목록에는 defunct 표시가 기본적으로 없다.","ce":["(가)는 맞지만 (다) ps -ef 출력에는 'zombie' 문자열이 나오지 않고 좀비는 <defunct>로 표시되므로 grep zombie로 찾을 수 없다.","(나)는 맞지만 (라) top 출력에서 좀비 수는 요약 행의 'zombie'로 표시되고 'defunct' 문자열은 기본적으로 나타나지 않는다.","top 요약 행의 'Tasks: … N zombie'를 grep zombie로, ps -ef 출력의 <defunct> 표시를 grep defunct로 확인하므로 (가)·(나)가 정답이다.","(다) ps에는 'zombie', (라) top에는 'defunct' 문자열이 기본적으로 표시되지 않아 두 명령 모두 좀비를 찾지 못한다."],"rel":["1-16"],"box":"(가) top -b -n 1 | grep zombie\n(나) ps -ef | grep defunct\n(다) ps -ef | grep zombie\n(라) top -b -n 1 | grep defunct"},{"n":5,"s":"s1","q":"홈페이지 회원 계정 및 패스워드 보안 강화를 위해 홈페이지 서버 관리자가 수행할 내용과 가장 거리가 먼 것은?","c":["패스워드 무작위 대입 공격에 대응하기 위해 서버를 이중화 하였다.","초기 설정한 암호는 반드시 바꾸도록 설정하였다.","/etc/shadow 파일에서 사용기간 및 만료일을 설정하였다.","5회 연속 암호 실패 시, 일정시간이 경과한 후 재 로그인 하도록 계정 Lock을 설정하였다."],"a":0,"e":"서버 이중화는 가용성 확보 대책이며 패스워드 무작위 대입(Brute Force) 공격 대응과 무관하다. 무작위 대입에는 로그인 실패 횟수 제한·계정 잠금, 복잡도 정책, 초기 암호 변경 강제, 사용기간 설정 등이 대책이다.","ce":["서버 이중화는 장애 시 서비스를 유지하는 가용성 대책으로, 패스워드 무작위 대입(Brute Force) 공격 차단과 무관하므로 가장 거리가 멀다.","초기 설정 암호를 반드시 변경하게 하면 기본·추측 가능한 암호가 계속 쓰이는 것을 막아 계정 보안이 강화된다.","/etc/shadow의 최대 사용기간·만료일을 설정하면 오래된 암호의 지속 사용을 막아 패스워드 보안이 강화된다.","연속 실패 횟수 초과 시 일정 시간 계정을 잠그면 무작위 대입 공격 속도를 크게 늦출 수 있어 적절한 대책이다."],"rel":["1-16","1-6"]},{"n":6,"s":"s1","q":"Null Session 취약점을 갖는 것은?","c":["Admin$","C$","IPC$","D$"],"a":2,"e":"IPC$(Inter-Process Communication) 공유는 사용자명·암호 없이 익명으로 연결(Null Session)할 수 있어 계정·공유 목록 등 정보 수집에 악용된다. Admin$·C$·D$는 관리 목적의 기본 공유로 관리자 인증이 필요하다.","ce":["Admin$는 %SystemRoot%(C:\\Windows)를 원격 관리용으로 공유하는 기본 관리 공유로, 관리자 인증이 필요해 익명 Null Session 대상이 아니다.","C$는 C 드라이브 루트의 기본 관리 공유로 관리자 자격 증명이 있어야 접근할 수 있다.","IPC$는 프로세스 간 통신용 명명된 파이프 공유로, 사용자명·암호 없이 익명 연결(Null Session)이 가능해 계정·공유 목록 수집에 악용되므로 정답이다.","D$는 D 드라이브의 기본 관리 공유로 관리자 인증이 필요하며 Null Session 취약점과 무관하다."],"rel":["1-17"]},{"n":7,"s":"s1","q":"리눅스/유닉스 시스템에서 최상위 디렉터리를 올바르게 짝지은 것은?","c":["㉠ /usr ㉡ /tmp ㉢ /var","㉠ /usr ㉡ /temp ㉢ /dev","㉠ /etc ㉡ /temp ㉢ /var","㉠ /etc ㉡ /tmp ㉢ /dev"],"a":3,"e":"/etc는 시스템 설정 파일, /tmp는 임시 파일, /dev는 장치 특수 파일을 담는다. /usr는 사용자 프로그램·라이브러리, /var는 로그·스풀 등 가변 데이터 디렉터리이며 /temp는 표준 디렉터리가 아니다.","ce":["/tmp는 맞지만 /usr는 사용자 프로그램·라이브러리 디렉터리이고, /var는 로그·스풀 등 가변 데이터 디렉터리이다. 설정 파일은 /etc, 장치 파일은 /dev이다.","/dev는 맞지만 설정 파일 디렉터리는 /usr가 아니라 /etc이고, /temp는 표준 디렉터리가 아니다(임시 파일은 /tmp).","/etc는 맞지만 /temp는 표준 디렉터리가 아니고(/tmp), /var는 로그 등 가변 데이터 디렉터리로 장치 특수 파일은 /dev에 있다.","/etc는 설정 파일, /tmp는 임시 파일, /dev는 프린터·터미널 등 장치 특수 파일을 담으므로 정답이다."],"rel":["1-16"],"box":"( ㉠ ) : 시스템의 환경 설정 및 주요 설정 파일을 담고 있다.\n( ㉡ ) : 프로그램 실행 시 생성되는 임시 파일을 담고 있다.\n( ㉢ ) : 프린터나 터미널 같은 물리적인 장치를 다루기 위한 특수 파일을 담고 있다."},{"n":8,"s":"s1","q":"'X'가 해킹을 위해 사용했을 것으로 의심되는 위치는?","c":["/etc/crontab","/etc/resolv.conf","/etc/sysconfig/network","/etc/rc.d/rc.local"],"a":3,"e":"/etc/rc.d/rc.local은 부팅 과정의 마지막에 실행되는 스크립트로, 여기에 명령을 추가하면 시스템 시작 시마다 자동 실행된다. /etc/crontab은 부팅이 아니라 주기적 시각에 작업을 실행하고, resolv.conf와 sysconfig/network는 네트워크 설정 파일이다.","ce":["/etc/crontab은 지정한 시각·주기마다 작업을 실행하는 파일로, '시스템이 시작될 때마다' 자동 실행하는 부팅 스크립트와 목적이 다르다.","/etc/resolv.conf는 DNS 서버 주소를 지정하는 파일로, 프로그램을 자동 실행하는 기능이 없다.","/etc/sysconfig/network는 호스트명·게이트웨이 등 네트워크 기본 설정 파일로 프로그램 자동 실행 위치가 아니다.","/etc/rc.d/rc.local은 부팅 과정 마지막에 실행되는 스크립트라 여기에 명령을 넣으면 시스템 시작 시마다 해킹 툴이 자동 구동되므로 정답이다."],"rel":["1-16"],"box":"Black Hacker인 X는 리눅스 서버의 보안 취약점을 이용하여 root 권한을 획득하는데 우연히 성공했다. X는 이후 시스템이 시작될 때마다 자신이 만들어 놓은 해킹 툴을 자동으로 구동시키기 위하여 관련된 파일을 변조하였다."},{"n":9,"s":"s1","q":"ftp 접근 여부를 검토할 수 있는 로그는?","c":["wtmp","utmp","sulog","xferlog"],"a":3,"e":"xferlog는 FTP 서버의 접속 및 파일 송수신 내역을 기록한다. wtmp는 로그인·로그아웃 이력, utmp는 현재 로그인 사용자, sulog는 su 명령 사용 기록이다.","ce":["wtmp는 사용자 로그인·로그아웃과 재부팅 이력을 기록하며 last 명령으로 조회한다. FTP 파일 전송 기록은 남지 않는다.","utmp는 현재 로그인한 사용자 정보를 담으며 w·who 명령으로 조회한다.","sulog는 su 명령으로 다른 사용자(주로 root)로 전환한 기록을 남긴다.","xferlog는 FTP 서버의 접속과 파일 업로드·다운로드 내역을 기록하므로 정답이다."],"rel":["1-7"]},{"n":10,"s":"s1","q":"트로이목마의 기능과 가장 거리가 먼 것은?","c":["패스워드 가로채기","원격 조정","시스템 파일 파괴","악성코드 전파"],"a":3,"e":"트로이목마는 정상 프로그램으로 위장해 설치된 뒤 패스워드 탈취, 원격 제어(백도어), 파일 파괴 등을 수행하지만 스스로 복제·전파하지 않는다. 자기 복제·전파는 웜·바이러스의 특징이다.","ce":["트로이목마는 키로깅 등으로 사용자 패스워드를 가로채 공격자에게 보내는 기능을 흔히 수행한다.","트로이목마는 백도어를 열어 공격자가 감염 시스템을 원격 조정(RAT)하게 하는 것이 대표 기능이다.","트로이목마는 공격자 명령에 따라 시스템 파일을 삭제·파괴하는 기능을 수행할 수 있다.","트로이목마는 스스로 복제·전파하지 않는다. 자기 복제로 다른 시스템에 퍼지는 것은 웜·바이러스의 특징이므로 정답이다."],"rel":["1-9"]},{"n":11,"s":"s1","q":"로그인 실패 시 로그가 저장되는 파일은?","c":["utmp","pacct","wtmp","btmp"],"a":3,"e":"btmp는 실패한 로그인 시도를 기록하며 lastb 명령으로 조회한다. utmp는 현재 로그인 사용자(w, who), wtmp는 성공한 로그인·로그아웃·재부팅 이력(last), pacct는 사용자 명령 실행 기록이다.","ce":["utmp는 현재 로그인해 있는 사용자 정보를 담는 파일로(w·who), 실패한 로그인은 기록하지 않는다.","pacct는 프로세스 accounting 파일로 사용자가 실행한 명령 이력을 기록한다(lastcomm).","wtmp는 성공한 로그인·로그아웃과 시스템 재부팅 이력을 기록하며(last), 실패 기록은 btmp에 남는다.","btmp는 실패한 로그인 시도를 기록하며 lastb 명령으로 조회하므로 정답이다."],"rel":["1-7"]},{"n":12,"s":"s1","q":"유닉스 또는 리눅스에서 실행 파일 a.out의 소유자가 root, 그룹은 staff이라고 할 때, chmod 4755 a.out 명령을 수행한 후의 a.out의 특성에 대해 올바르게 설명하고 있는 것은?","c":["그룹이 staff인 모든 사용자에 한해 a.out을 읽고 실행시킬 수 있다.","root만이 a.out을 읽고 실행시킬 수 있다.","실행하는 사용자에 관계없이 a.out은 root의 권한으로 실행된다.","실행하는 사용자에 관계없이 a.out은 staff의 권한으로 실행된다."],"a":2,"e":"4755의 4는 SetUID 비트로, 실행 시 실행자가 아니라 파일 소유자(root)의 권한(EUID)으로 동작한다. 755이므로 모든 사용자가 읽기·실행 가능하며, 그룹(staff) 권한으로 실행되게 하려면 SetGID(2000)가 필요하다.","ce":["권한 755는 소유자 rwx, 그룹 r-x, 기타 r-x이므로 staff 그룹뿐 아니라 모든 사용자가 읽고 실행할 수 있다.","755는 기타 사용자에게도 r-x를 주므로 root만 실행할 수 있다는 설명은 틀렸다.","4755의 4는 SetUID 비트로, 누가 실행하든 파일 소유자인 root의 권한(EUID=0)으로 실행되므로 정답이다.","그룹(staff) 권한으로 실행되게 하는 것은 SetGID(2000) 비트이다. 4755는 SetUID만 설정되어 소유자 root 권한으로 실행된다."],"rel":["1-5"]},{"n":13,"s":"s1","q":"리눅스 사용자 'test_user'에게 60일 마다 패스워드의 교체를 의무화시키기 위한 보안정책을 반영하기 위한 명령어에 해당하는 것은?","c":["passwd -x 60 test_user","useradd -e 60 test_user","passwd +x 60 test_user","usermod -f 60 test_user"],"a":0,"e":"passwd -x(최대 사용기간) 옵션은 비밀번호를 변경 없이 사용할 수 있는 최대 일수를 지정하며, chage -M 60과 같은 효과이다. useradd -e는 계정 만료 날짜, usermod -f는 암호 만료 후 비활성화까지의 유예 일수를 지정한다.","ce":["passwd -x 60은 비밀번호 최대 사용기간을 60일로 지정해 60일마다 교체를 강제하므로 정답이다(chage -M 60과 같은 효과).","useradd -e는 계정 만료 날짜(YYYY-MM-DD)를 지정하는 옵션으로, 주기적 비밀번호 교체 정책이 아니다.","passwd에 +x 옵션은 없다. 최대 사용기간은 -x로 지정한다.","usermod -f는 비밀번호 만료 후 계정이 비활성화되기까지의 유예 일수(inactive)를 지정하는 옵션이다."],"rel":["1-6"]},{"n":14,"s":"s1","q":"아래 지문이 설명하는 평가인증 제도는 무엇인가?","c":["TCSEC","KTSEC","ITSEC","CC"],"a":3,"e":"CC(Common Criteria, ISO/IEC 15408)는 보안기능 요구사항 11개 클래스(FAU~FTP)와 평가보증등급 EAL1~EAL7을 사용하는 국제 공통평가기준이다. TCSEC은 미국 기준으로 D~A1 등급, ITSEC은 유럽 기준으로 E0~E6 등급을 사용한다.","ce":["TCSEC(오렌지북)은 미국 국방부 기준으로 D·C1·C2·B1·B2·B3·A1 등급을 사용하며, 11개 기능 클래스와 EAL1~7 체계가 아니다.","KTSEC은 과거 국내 정보보호시스템 평가 기준(K1~K7 등급)으로, CC 도입 후 대체되었다.","ITSEC은 유럽 기준으로 보증 등급 E0~E6을 사용하며, EAL1~7 등급 체계는 CC에서 정의했다.","CC(Common Criteria, ISO/IEC 15408)는 FAU~FTP 11개 보안기능 클래스와 EAL1~EAL7 평가보증등급을 사용하므로 정답이다."],"rel":["5-6"],"box":"보안기능 요구사항은 11개 클래스로 구성: FAU(보안감사), FCO(통신), FCS(암호지원), FDP(사용자 데이터 보호), FMT(보안관리), FIA(식별 및 인증), FPR(프라이버시), FPT(TOE 보안기능의 보호), FRU(자원활용), FTA(TOE 접근), FTP(안전한 경로/채널)\n- 평가보증등급은 7등급(EAL1, EAL2, EAL3, EAL4, EAL5, EAL6, EAL7)으로 구분되며 등급이 높아질수록 보증요구사항이 강화된다."},{"n":15,"s":"s1","q":"윈도우 레지스트리 중 등록된 응용 프로그램과 확장자 사이의 관계 정보를 담고 있는 곳은?","c":["HKEY_CLASSES_ROOT","HKEY_LOCAL_MACHINE\\SYSTEM","HKEY_CURRENT_CONFIG","HKEY_USERS"],"a":0,"e":"HKEY_CLASSES_ROOT(HKCR)는 파일 확장자와 연결 프로그램, COM 객체 등록 정보를 담는다. HKEY_CURRENT_CONFIG는 현재 하드웨어 프로필, HKEY_USERS는 전체 사용자 프로필 설정을 담는다.","ce":["HKEY_CLASSES_ROOT(HKCR)는 파일 확장자와 연결 프로그램, COM 객체 등록 정보를 담으므로 정답이다.","HKEY_LOCAL_MACHINE\\SYSTEM은 부팅에 필요한 서비스·드라이버·컨트롤 세트 정보를 담으며, 확장자 연결 정보가 아니다.","HKEY_CURRENT_CONFIG는 현재 사용 중인 하드웨어 프로필 정보를 담는다.","HKEY_USERS는 시스템의 모든 사용자 프로필(SID별) 설정을 담으며, 확장자 연결을 대표하는 키가 아니다."],"rel":["1-3"]},{"n":16,"s":"s1","q":"rlogin은 원격 시스템에 접속할 때 사용하는 서비스로 사전에 서버의 특정 파일에 호스트를 등록하여 클라이언트가 패스워드를 입력할 필요 없이 로그인이 가능하게 하는 서비스이다. 다음 중 호스트를 등록하는 파일은?","c":["/etc/hosts","/etc/hosts.equiv","/etc/resolv.conf","/etc/syslog.conf"],"a":1,"e":"/etc/hosts.equiv(시스템 전체)와 사용자별 ~/.rhosts에 등록된 신뢰 호스트는 r-계열 명령(rlogin·rsh)으로 패스워드 없이 접속할 수 있어 보안상 제거·제한 대상이다. /etc/hosts는 호스트명-IP 매핑 파일이다.","ce":["/etc/hosts는 호스트명과 IP 주소를 정적으로 매핑하는 파일로, rlogin 신뢰 호스트 등록 파일이 아니다.","/etc/hosts.equiv는 시스템 전체 신뢰 호스트를 등록해 rlogin·rsh 접속 시 패스워드 없이 로그인하게 하므로 정답이다(사용자별은 ~/.rhosts).","/etc/resolv.conf는 DNS 서버 주소를 지정하는 파일로 원격 접속 인증과 무관하다.","/etc/syslog.conf는 syslog 데몬의 로그 종류별 저장 위치를 지정하는 설정 파일이다."],"rel":["1-16"]},{"n":17,"s":"s1","q":"다음 지문에서 설명하는 파일시스템으로 옳은 것은?","c":["FAT16","FAT32","NTFS","EXT"],"a":3,"e":"EXT(Extended File System)는 1992년 리눅스용으로 처음 개발된 파일시스템으로 최대 2GB 볼륨, 255바이트 파일명을 지원하지만 개별 타임스탬프 등을 지원하지 않고 단편화가 심해 EXT2로 대체되었다. FAT16·FAT32·NTFS는 윈도우 계열 파일시스템이다.","ce":["FAT16은 MS-DOS·윈도우용 파일시스템으로 8.3 형식 파일명을 기본으로 하며, 리눅스용으로 개발된 것이 아니다.","FAT32는 윈도우 95 OSR2부터 도입된 윈도우용 파일시스템으로 볼륨 크기가 2GB를 훨씬 넘는다.","NTFS는 윈도우 NT 계열 파일시스템으로 ACL 접근제어·저널링을 지원하므로 '접근제어 불가'라는 지문과 반대다.","EXT는 초창기 리눅스용으로 개발되어 최대 2GB 볼륨, 255바이트 파일명을 지원했으나 개별 타임스탬프 등이 없고 단편화가 심해 EXT2로 대체되었으므로 정답이다."],"rel":["1-18"],"box":"- 초창기 리눅스용으로 개발되었으며, 최대 2GB까지 파일시스템 크기를 지원한다.\n- 256byte까지 파일명을 지원한다.\n- 접근제어, inode 수정, 타임스탬프 수정 등의 기능이 불가능하다.\n- 사용할수록 단편화가 심해진다."},{"n":18,"s":"s1","q":"리눅스용 패킷 필터 기반 시스템 접근통제 도구와 거리가 먼 것은?","c":["iptables","ipfwadm","ipchains","modsecurity"],"a":3,"e":"ipfwadm(커널 2.0) → ipchains(2.2) → iptables(2.4 이후)는 리눅스 커널 패킷 필터링 도구의 변천이다. ModSecurity는 Apache 등에 모듈로 동작하는 오픈소스 웹 방화벽(WAF)이다.","ce":["iptables는 리눅스 커널 2.4 이후 netfilter 기반의 대표적 패킷 필터링 도구이다.","ipfwadm은 리눅스 커널 2.0 시절의 패킷 필터 방화벽 관리 도구이다.","ipchains는 리눅스 커널 2.2의 패킷 필터링 도구로 ipfwadm을 대체했고 이후 iptables로 대체되었다.","ModSecurity는 Apache·Nginx 등 웹 서버 모듈로 HTTP 요청을 검사하는 오픈소스 웹 방화벽(WAF)으로, 패킷 필터 기반 도구가 아니므로 정답이다."],"rel":["1-16"]},{"n":19,"s":"s1","q":"지문의 내용에 해당하는 것으로 가장 적절한 것은?","c":["Format String","Heap Spray","Race Condition","Buffer Overflow"],"a":2,"e":"Race Condition 공격은 SetUID 프로그램이 임시 파일을 생성·사용하는 시간 차를 노려 같은 이름의 파일에 중요 파일(/etc/passwd 등)로의 심볼릭 링크를 걸어 권한 있는 작업이 해당 파일에 수행되게 한다. Heap Spray는 힙에 셸코드를 대량 분사하는 기법이다.","ce":["Format String은 printf류 함수에 %n·%x 같은 형식 지정자를 넣어 메모리를 읽거나 쓰는 공격으로, 임시 파일·심볼릭 링크 경쟁과 무관하다.","Heap Spray는 힙 메모리 여러 곳에 셸코드를 대량 배치해 실행 흐름이 셸코드로 가게 할 확률을 높이는 기법이다.","Race Condition 공격은 권한 있는 프로그램이 임시 파일을 만들고 쓰는 시간 차를 노려, 같은 이름의 파일을 중요 파일로의 심볼릭 링크로 바꿔치기하므로 정답이다.","Buffer Overflow는 버퍼 크기보다 큰 입력으로 인접 메모리(복귀 주소 등)를 덮어쓰는 공격으로, 자원 경쟁을 이용하지 않는다."],"rel":["1-10"],"box":"한정된 자원을 동시에 이용하려는 여러 프로세스가 자원의 이용을 위해 경쟁을 벌이는 현상을 의미하는 것으로, 취약 프로그램이 생성하는 임시 파일과 같은 이름의 파일을 생성한 후 생성한 임시 파일에 대한 심볼릭 링크를 설정한다."},{"n":20,"s":"s1","q":"Users 그룹에 대한 설명 중 틀린 것은?","c":["Users 그룹의 구성원은 워크스테이션을 종료할 수 있고, 서버도 종료할 수 있다.","Users 그룹의 구성원은 관리자가 설치하거나 배포한 인증된 프로그램을 실행할 수 있다.","Users 그룹의 구성원은 로컬 그룹을 만들 수는 있지만 자신이 만든 로컬 그룹만 관리할 수 있다.","Users 그룹의 구성원은 자신의 모든 데이터 파일(%userprofile%) 및 레지스트리에서 자신에 속하는 부분(HKEY_CURRENT_USER)을 완전하게 제어할 수 있다."],"a":0,"e":"Users 그룹 구성원은 워크스테이션은 종료할 수 있지만 서버는 종료할 수 없다(서버 종료는 Administrators·Server Operators 등의 권한). 인증된 프로그램 실행, 자신이 만든 로컬 그룹 관리, 자신의 프로필·HKCU 제어는 가능하다.","ce":["Users 그룹 구성원은 워크스테이션은 종료할 수 있지만 서버는 종료할 수 없다. 서버 종료는 Administrators·Server Operators 등의 권한이므로 틀린 설명이다.","Users 그룹 구성원은 관리자가 설치하거나 배포한 인증된 프로그램을 실행할 수 있으므로 옳은 설명이다.","Users 그룹 구성원은 로컬 그룹을 만들 수 있으나 자신이 만든 로컬 그룹만 관리할 수 있으므로 옳은 설명이다.","Users 그룹 구성원은 자신의 프로필 데이터(%userprofile%)와 레지스트리의 HKEY_CURRENT_USER를 완전히 제어할 수 있으므로 옳은 설명이다."],"rel":["1-17"],"box":"윈도우에서는 사용자 계정을 추가하면 일반 사용자 그룹인 Users 그룹에 자동으로 포함된다. NTFS로 포맷된 볼륨에서는 이 그룹의 구성원이 운영체제 및 설치된 프로그램의 무결성을 손상시킬 수 없도록 새로 설치된 시스템의 기본 보안 설정이 지정된다."},{"n":21,"s":"s2","q":"㉠, ㉡, ㉢에 적합한 내용으로 짝지어진 것은?","c":["8Byte, 2Byte, 1Byte","8Byte, 4Byte, 2Byte","6Byte, 4Byte, 2Byte","6Byte, 2Byte, 1Byte"],"a":2,"e":"MAC 주소는 48비트(6바이트), IPv4 주소는 32비트(4바이트), TCP/UDP 포트 번호는 16비트(2바이트)이다. 8바이트(64비트)는 EUI-64 인터페이스 식별자 길이로 이더넷 MAC 주소와 다르다.","ce":["MAC 주소는 8바이트가 아니라 6바이트(48비트)이고, IPv4 주소는 4바이트, 포트는 2바이트이므로 세 값이 모두 틀렸다.","IP 4바이트·포트 2바이트는 맞지만 이더넷 MAC 주소는 8바이트가 아니라 6바이트(48비트)이다. 8바이트는 EUI-64 식별자 길이이다.","이더넷 MAC 주소 6바이트(48비트), IPv4 주소 4바이트(32비트), TCP/UDP 포트 2바이트(16비트)이므로 정답이다.","MAC 6바이트는 맞지만 IPv4 주소는 2바이트가 아니라 4바이트이고, 포트 번호는 1바이트가 아니라 2바이트(0~65535)이다."],"rel":["2-1"],"box":"- 이더넷은 네트워크 인터페이스 카드에 설정된 ( ㉠ ) 물리 주소를 사용한다.\n- 인터넷 계층의 주소는 ( ㉡ ) 논리 주소를 사용한다.\n- 전송 계층의 주소는 ( ㉢ ) 포트 주소를 사용한다."},{"n":22,"s":"s2","q":"분산서비스 거부공격(DDoS)의 구성요소가 아닌 것은?","c":["마스터(Master)","포트 미러링(Port Mirroring)","에이전트(Agent)","공격자(Attacker)"],"a":1,"e":"DDoS는 공격자(Attacker) → 마스터(Handler) → 에이전트(Agent/Daemon) → 피해자(Target)의 계층 구조로 구성된다. 포트 미러링은 스위치에서 특정 포트 트래픽을 복사해 모니터링 포트로 보내는 네트워크 관리 기능이다.","ce":["마스터(Handler)는 공격자의 명령을 받아 다수의 에이전트를 제어하는 DDoS 구성요소이다.","포트 미러링은 스위치에서 특정 포트의 트래픽을 복제해 모니터링 포트로 보내는 네트워크 관리 기능으로 DDoS 구성요소가 아니므로 정답이다.","에이전트(Agent·Daemon)는 마스터의 명령에 따라 실제로 피해자에게 공격 트래픽을 보내는 감염 시스템이다.","공격자(Attacker)는 마스터에 명령을 내려 전체 DDoS 공격을 지휘하는 최상위 구성요소이다."],"rel":["2-3"]},{"n":23,"s":"s2","q":"SSL Handshake 프로토콜에 대한 설명으로 옳지 않은 것은?","c":["Cipher Suite은 공개키 암호 시스템, 대칭키 암호 시스템, 해시 알고리즘 등 3개의 정보로 구성된다.","SSL Handshake 프로토콜 동작과정을 통해 SSL 클라이언트와 서버가 공유하는 암호 알고리즘들과 키 값들이 생성된다.","SSL 클라이언트는 통신 상대인 서버의 신원확인을 위해 전자인증서 기반의 인증을 수행한다.","SSL 클라이언트와 서버의 전자인증서는 대칭키 암호 시스템을 이용한다."],"a":3,"e":"SSL/TLS의 전자인증서(X.509)는 공개키와 CA의 전자서명을 담는 공개키 암호 시스템 기반이다. 대칭키는 핸드셰이크로 합의한 세션키로 데이터를 암호화할 때 사용하며, Cipher Suite는 키 교환(공개키)·대칭 암호·해시(MAC) 알고리즘 조합이다.","ce":["Cipher Suite는 키 교환(공개키), 대칭 암호, 해시(MAC) 알고리즘의 조합으로 구성되므로 옳은 설명이다.","Handshake 과정에서 암호 알고리즘을 협상하고 pre-master secret으로 master secret과 세션 키를 생성·공유하므로 옳다.","클라이언트는 서버가 보낸 X.509 인증서를 CA 서명으로 검증해 서버 신원을 확인하므로 옳다.","전자인증서는 공개키와 CA의 전자서명을 담는 공개키 암호 시스템 기반이다. 대칭키는 합의된 세션키로 데이터를 암호화할 때 쓰이므로 틀렸다."],"rel":["2-7"]},{"n":24,"s":"s2","q":"VLAN에 대한 설명이다. 빈칸에 들어갈 내용을 순서대로 나열한 것은?","c":["㉠ 멀티캐스팅 ㉡ 논리적인 ㉢ Port Mirroring","㉠ 브로드캐스팅 ㉡ 논리적인 ㉢ Port Mirroring","㉠ 브로드캐스팅 ㉡ 물리적인 ㉢ Port Filtering","㉠ 멀티캐스팅 ㉡ 물리적인 ㉢ Port Filtering"],"a":1,"e":"VLAN은 물리 배치와 무관하게 스위치에서 논리적으로 LAN을 분할해 브로드캐스트 도메인을 나누고 불필요한 브로드캐스트 트래픽을 줄인다. 스위치 트래픽을 분석하려면 특정 포트 트래픽을 복제해 주는 Port Mirroring(SPAN)을 사용한다.","ce":["㉡ 논리적·㉢ Port Mirroring은 맞지만, VLAN이 제한하는 것은 멀티캐스트가 아니라 브로드캐스트 트래픽(브로드캐스트 도메인 분할)이다.","VLAN은 브로드캐스트 트래픽을 제한하는 논리적 LAN이고, 스위치 트래픽 분석에는 특정 포트 트래픽을 복제하는 Port Mirroring(SPAN)을 쓰므로 정답이다.","㉠ 브로드캐스팅은 맞지만 VLAN은 물리 배치와 무관한 논리적 LAN이고, 트래픽 분석 기능은 Port Filtering이 아니라 Port Mirroring이다.","VLAN이 제한하는 것은 브로드캐스트, VLAN은 논리적 분할, 분석 기능은 Port Mirroring이므로 세 항목이 모두 틀렸다."],"rel":["2-12"],"box":"VLAN이란 ( ㉠ ) 트래픽을 제한하여 불필요한 트래픽을 차단하기 위한 ( ㉡ ) LAN이다. 스위치는 허브처럼 한 포트에서 발생한 데이터를 모든 포트에 전달하지 않기 때문에 스위치에 흐르는 데이터를 분석하려면 허브와는 달리 ( ㉢ ) 기능을 사용해야 한다."},{"n":25,"s":"s2","q":"TTL의 의미를 맞게 설명한 것은?","c":["Echo Reply 패킷 크기","Reply 패킷을 받기까지의 시간","라우팅 정보가 잘못되어 발생하는 패킷 무한 반복을 제어하기 위한 값","손실된 패킷의 수"],"a":2,"e":"TTL(Time To Live)은 라우터를 지날 때마다 1씩 감소해 0이 되면 폐기되므로, 라우팅 루프로 패킷이 무한히 순환하는 것을 방지한다. 출력의 '바이트=32'는 패킷 크기, '시간'은 응답 시간이며 TTL과 별개다.","ce":["Echo Reply 패킷 크기는 출력의 '바이트=32' 값이며 TTL과 별개이다.","응답을 받기까지의 시간은 출력의 '시간<1ms' 값(RTT)이며 TTL은 시간 단위 측정값이 아니다.","TTL은 라우터를 지날 때마다 1씩 감소해 0이 되면 폐기되므로, 잘못된 라우팅으로 패킷이 무한 순환하는 것을 막으므로 정답이다(윈도우 기본값 128).","손실된 패킷 수는 통계의 '손실 = 0'으로 표시되며 TTL과 관계없다."],"rel":["2-12","2-2"],"box":"C:\\>ping 127.0.0.1\nPing 127.0.0.1 32바이트 데이터 사용\n127.0.0.1의 응답 바이트=32 시간 <1ms TTL=128\n127.0.0.1의 응답 바이트=32 시간 <1ms TTL=128\n127.0.0.1에 대한 Ping 통계\n패킷 보냄 = 4, 받음 =4, 손실 = 0 (0% 손실),\n왕복 시간(밀리초)\n최소 = 0ms, 최대 = 0ms, 평균 = 0ms"},{"n":26,"s":"s2","q":"TCP 플래그 값을 모두 off(비활성화)한 패킷들을 이용하여 스캔하는 기법은?","c":["FIN 스캔","TCP SYN 스캔","Null 스캔","XMAS 스캔"],"a":2,"e":"Null 스캔은 모든 TCP 플래그를 끈 패킷을 보내 열린 포트는 무응답, 닫힌 포트는 RST/ACK로 응답하는 점을 이용한다. XMAS 스캔은 FIN·PSH·URG를 모두 설정하고, FIN 스캔은 FIN만 설정한다.","ce":["FIN 스캔은 FIN 플래그 하나를 설정해 보내는 스캔으로, 모든 플래그를 끈 것이 아니다.","TCP SYN 스캔은 SYN 플래그를 설정해 보내고 SYN/ACK 응답으로 열린 포트를 확인하는 하프 오픈 스캔이다.","Null 스캔은 TCP 플래그를 모두 끈 패킷을 보내 열린 포트는 무응답, 닫힌 포트는 RST로 응답하는 점을 이용하므로 정답이다.","XMAS 스캔은 FIN·PSH·URG 플래그를 모두 켜서 보내는 스캔으로, 플래그를 모두 끈 Null 스캔과 반대이다."],"rel":["2-4"]},{"n":27,"s":"s2","q":"공격 특징 및 대응방안과 관련성이 가장 높은 것은?","c":["UDP Flooding","SYN Flooding","GET Flooding","ICMP Flooding"],"a":1,"e":"SYN Flooding은 대량의 SYN으로 서버의 TCP 연결 대기 큐(Backlog)를 채워 TCP 스택 자원을 고갈시키며, 출발지 IP별 PPS 임계치와 SYN 패킷 옵션 필드 검사로 대응한다. GET Flooding은 HTTP 계층, UDP·ICMP Flooding은 대역폭 소진 공격이다.","ce":["UDP Flooding은 대량 UDP 패킷으로 회선 대역폭을 소진시키는 공격으로, TCP 스택 자원 소모나 TCP 옵션 필드 검사와 관계가 없다.","SYN Flooding은 SYN만 대량 전송해 서버 TCP 스택의 연결 대기 큐(Backlog)를 고갈시키며, 소스 IP별 PPS 임계치와 SYN 패킷 옵션 필드 검사로 대응하므로 정답이다.","GET Flooding은 TCP 연결을 정상 수립한 뒤 HTTP GET 요청을 반복하는 애플리케이션 계층 공격으로, 대응은 URL·요청 빈도 기반 임계치이다.","ICMP Flooding은 ICMP Echo 등을 대량 전송해 대역폭을 소모하는 공격으로 TCP 스택·옵션 필드와 무관하다."],"rel":["2-3"],"box":"웹서버 OS의 TCP 스택(Stack) 자원을 소모하는 특징을 갖는 웹서버 자원 소모 공격으로 사용될 수 있으며, 그 대응방법으로 Anti-DDoS 장비에서 소스 IP별로 PPS 임계치를 설정하거나 패킷 헤더 검사를 통해 정상적인 옵션 필드값을 갖지 않는 비정상 패킷을 차단할 수 있다."},{"n":28,"s":"s2","q":"수동적 공격과 가장 거리가 먼 것은?","c":["도청","메세지 수정","감시","메세지 내용 절취"],"a":1,"e":"수동적 공격은 시스템에 변화를 주지 않고 정보를 엿듣는 도청·감시·트래픽 분석·내용 절취이다. 메시지 수정은 데이터를 변조하는 능동적 공격으로 무결성을 침해한다.","ce":["도청은 통신 내용을 변경하지 않고 엿듣는 대표적 수동적 공격으로 기밀성을 침해한다.","메시지 수정은 전송 중인 데이터를 변조하는 능동적 공격으로 무결성을 침해하므로 수동적 공격과 가장 거리가 멀다.","감시(모니터링)는 시스템에 변화를 주지 않고 통신·활동을 관찰하는 수동적 공격이다.","메시지 내용 절취는 전송 내용을 몰래 획득(Release of Message Contents)하는 수동적 공격이다."],"rel":["2-5","4-1"]},{"n":29,"s":"s2","q":"3계층 터널링 프로토콜은?","c":["PPTP VPN","L2TP VPN","IPSec VPN","SSL VPN"],"a":2,"e":"IPSec은 네트워크 계층(3계층)에서 IP 패킷을 보호하는 터널링 프로토콜이다. PPTP·L2TP는 2계층, SSL VPN은 전송 계층 이상(4~7계층)에서 동작한다.","ce":["PPTP는 PPP 프레임을 GRE로 캡슐화하는 2계층 터널링 프로토콜이다.","L2TP는 PPTP와 L2F를 통합한 2계층 터널링 프로토콜로, 자체 암호화가 없어 IPSec과 함께 쓴다.","IPSec은 네트워크 계층(3계층)에서 AH·ESP로 IP 패킷을 보호·캡슐화하는 터널링 프로토콜이므로 정답이다.","SSL VPN은 TCP 위의 SSL/TLS를 이용하므로 전송 계층 이상(4~7계층)에서 동작한다."],"rel":["2-7"]},{"n":30,"s":"s2","q":"iptables 설정 내용을 /etc/iptables.tmp 파일에 저장하는 명령어로 적절한 것은?","c":["iptables -store > /etc/iptables.tmp","iptables -config > /etc/iptables.tmp","iptables -restore > /etc/iptables.tmp","iptables -save > /etc/iptables.tmp"],"a":3,"e":"iptables-save는 현재 규칙을 표준 출력으로 내보내므로 리다이렉션(>)으로 파일에 저장하고, 복원은 iptables-restore < 파일로 한다. -store·-config는 존재하지 않는 명령이다.","ce":["iptables에 -store 옵션이나 iptables-store 명령은 없다. 규칙 저장 명령은 iptables-save이다.","-config는 iptables 옵션이 아니며, 규칙을 표준 출력으로 내보내는 기능이 없다.","iptables-restore는 저장된 규칙 파일을 읽어 적용하는 복원 명령으로, 'iptables-restore < 파일'처럼 입력 리다이렉션으로 쓴다.","iptables-save는 현재 규칙을 표준 출력으로 내보내므로 '> /etc/iptables.tmp'로 파일에 저장할 수 있어 정답이다."],"rel":["1-16"]},{"n":31,"s":"s2","q":"포트의 open 여부를 확인하는 방법이 다른 하나는?","c":["Null 스캔","FIN 스캔","SYN 스캔","XMAS 스캔"],"a":2,"e":"SYN 스캔은 열린 포트에서 SYN/ACK 응답을 받아 open을 판단한다. Null·FIN·XMAS 스캔은 열린 포트가 무응답이고 닫힌 포트가 RST를 보내는 점을 이용하는 역방향 판단 방식이다.","ce":["Null 스캔은 플래그를 모두 끈 패킷을 보내 열린 포트는 무응답, 닫힌 포트는 RST 응답으로 판단한다(무응답=open 방식).","FIN 스캔은 FIN 패킷을 보내 열린 포트는 무응답, 닫힌 포트는 RST로 판단하는 스텔스 방식이다.","SYN 스캔은 열린 포트에서 SYN/ACK 응답이 오는 것으로 open을 판단하므로, 무응답을 open으로 보는 나머지 세 스캔과 방식이 달라 정답이다.","XMAS 스캔은 FIN·PSH·URG를 설정해 보내 열린 포트는 무응답, 닫힌 포트는 RST로 판단한다."],"rel":["2-4"]},{"n":32,"s":"s2","q":"공격자는 공격대상 시스템을 10.10.10.5로 에이전트가 있는 네트워크를 192.168.3.0/24로 설정하고 패킷 생성도구를 이용하여 패킷을 보냈다. 다음 보기 중 이러한 공격 행위와 가장 관련이 있는 것은?","c":["SYN Flooding","Ping of Death","LAND","Smurf"],"a":3,"e":"-a 10.10.10.5로 출발지를 피해자 IP로 위조하고 브로드캐스트 주소로 ICMP Echo Request를 대량 전송하면, 해당 네트워크 호스트들의 Echo Reply가 피해자에게 몰리는 Smurf 공격이 된다. LAND는 출발지와 목적지를 동일하게 위조하고, Ping of Death는 초대형 ICMP 패킷을 이용한다.","ce":["SYN Flooding은 TCP SYN을 대량 전송하는 공격이다. 명령어의 --icmp 옵션은 ICMP 패킷을 보내므로 해당하지 않는다.","Ping of Death는 65,535바이트를 넘는 초대형 ICMP 패킷을 보내는 공격으로, 브로드캐스트 주소·출발지 위조가 핵심이 아니다.","LAND는 출발지와 목적지를 같은 IP로 위조하는 공격이다. 여기서는 출발지(10.10.10.5)와 목적지(브로드캐스트)가 서로 다르다.","-a 10.10.10.5로 출발지를 피해자로 위조하고 브로드캐스트 주소(.255)로 ICMP Echo Request를 대량 전송해 응답을 피해자에게 몰리게 하는 Smurf 공격이므로 정답이다(지문의 192.168.3.0/24와 명령의 192.168.0.255 불일치는 원문 그대로)."],"rel":["2-3"],"box":"hping 192.168.0.255 -a 10.10.10.5 --icmp --flood","flag":"지문은 에이전트 네트워크를 192.168.3.0/24로 설명하나 명령은 192.168.0.255 — 원문 그대로"},{"n":33,"s":"s2","q":"어떤 공격을 방어하기 위한 것인가?","c":["Get Flooding 공격 방어","ICMP Flooding 공격 방어","SYN Flooding 공격 방어","TCP Session 공격 방어"],"a":0,"e":"HTTP GET Flooding은 정상 세션을 맺은 뒤 동일 URL을 반복 요청하므로 콘텐츠·URL별 요청 임계치 설정과 웹 스크래핑(자동 요청 검증) 기법으로 차단한다. SYN·ICMP Flooding은 네트워크·전송 계층 공격이라 URL 기준 임계치로 방어하지 않는다.","ce":["콘텐츠 요청 횟수·시간별 URL 접속 임계치·웹 스크래핑(자동 요청 검증)은 동일 URL을 반복 요청하는 HTTP GET Flooding 방어 기법이므로 정답이다.","ICMP Flooding은 네트워크 계층 대역폭 공격으로, 대응은 ICMP 차단·대역폭 제한이지 URL 요청 임계치가 아니다.","SYN Flooding은 TCP 연결 대기 큐 고갈 공격으로, 대응은 SYN Cookie·Backlog 확대·SYN PPS 임계치이다.","TCP Session 공격(세션 하이재킹 등)의 대응은 시퀀스 번호 예측 방지·암호화 세션이며, 웹페이지 URL 접속 임계치와 무관하다."],"rel":["2-3"],"box":"- 콘텐츠 요청 횟수에 대한 임계치 설정에 의한 차단\n- 시간별 웹페이지 URL 접속 임계치 설정에 의한 차단\n- Web-Scraping 기법을 이용한 차단"},{"n":34,"s":"s2","q":"공격 대상이 방문할 가능성이 있는 합법적인 웹 사이트를 미리 감염시킨 뒤, 잠복하고 있다가 피해자가 방문하면 피해자의 컴퓨터에 악성코드를 설치하는 공격 방법은?","c":["Malicious Bot 공격","Watering Hole 공격","Spear Phishing 공격","Pharming 공격"],"a":1,"e":"워터링 홀 공격은 표적 집단이 자주 방문하는 정상 웹사이트를 먼저 감염시켜 방문자에게 드라이브 바이 다운로드로 악성코드를 설치한다. 스피어 피싱은 표적에게 맞춤형 메일을 직접 보내고, 파밍은 DNS·hosts 조작으로 가짜 사이트로 유도한다.","ce":["Malicious Bot 공격은 감염된 봇이 C&C 명령을 받아 스팸·DDoS 등을 수행하는 것으로, 표적이 방문할 합법 사이트를 미리 감염시키는 방식이 아니다.","Watering Hole 공격은 표적 집단이 자주 방문하는 합법 웹사이트를 먼저 감염시키고 잠복했다가 방문자에게 드라이브 바이 다운로드로 악성코드를 설치하므로 정답이다.","Spear Phishing은 특정 표적에게 맞춤형 메일을 직접 보내 첨부파일·링크를 열게 하는 공격이다.","Pharming은 DNS·hosts 파일을 조작해 정상 주소를 입력해도 가짜 사이트로 접속되게 하는 공격이다."],"rel":["1-19"]},{"n":35,"s":"s2","q":"스위칭 환경에서 스니핑을 수행하기 위한 공격이 아닌 것은?","c":["ICMP 리다이렉트","ARP 스푸핑","스위치 재밍","IP 스푸핑"],"a":3,"e":"ICMP 리다이렉트는 라우팅 경로를 공격자로 바꾸고, ARP 스푸핑은 ARP 캐시를 조작하며, 스위치 재밍은 MAC 테이블을 넘치게 해 스위치를 허브처럼 만들어 스위칭 환경에서 스니핑을 가능하게 한다. IP 스푸핑은 출발지 IP를 위조하는 공격으로 트래픽을 수집하는 수단이 아니다.","ce":["ICMP 리다이렉트는 위조 ICMP Redirect로 대상의 라우팅 경로를 공격자로 바꿔 트래픽을 경유시키므로 스위칭 환경 스니핑 기법이다.","ARP 스푸핑은 대상의 ARP 캐시를 위조해 트래픽이 공격자 MAC으로 가게 하는 스위칭 환경 스니핑 기법이다.","스위치 재밍은 위조 MAC으로 MAC 테이블을 가득 채워 스위치가 허브처럼 모든 포트로 전송하게 만드는 스니핑 기법이다.","IP 스푸핑은 출발지 IP를 위조해 신뢰 관계를 악용하거나 추적을 피하는 공격으로, 트래픽을 공격자에게 오게 하는 스니핑 수단이 아니므로 정답이다."],"rel":["2-5"]},{"n":36,"s":"s2","q":"다음 설명에 해당하는 시스템은?","c":["NAC","ESM","SIEM","IDS"],"a":0,"e":"NAC(Network Access Control)는 단말의 인증과 보안정책 준수(패치·백신) 여부를 접속 전에 검사해 허용·격리·차단한다. ESM·SIEM은 보안 로그·이벤트 통합 관리·분석, IDS는 침입 탐지 시스템이다.","ce":["NAC는 단말이 내부망에 접속하기 전에 인증과 보안정책 준수(패치·백신 등)를 검사해 접속을 허용·격리·차단하므로 정답이다.","ESM은 여러 보안 장비의 이벤트를 통합 수집·관리하는 체계로, 단말의 접속 전 보안성 검증 기능이 아니다.","SIEM은 로그·이벤트를 수집·상관분석해 위협을 탐지하는 솔루션으로, 단말 접속을 사전 통제하지 않는다.","IDS는 네트워크·호스트의 침입을 탐지해 경보를 내는 시스템으로, 단말 보안정책 준수 검사와 접속 통제를 하지 않는다."],"rel":["2-10","1-11"],"box":"- 네트워크에 접근하는 접속 단말의 보안성을 검증하여 보안성을 강제화하고 접속을 통제할 수 있는 보안 인프라이다.\n- 사용 단말이 내부 네트워크에 접속하기 전에 보안정책을 준수했는지 여부를 검사해 네트워크 접속을 통제하는 보안 솔루션이다.\n- 주요 기능으로는 접근제어/인증, PC 및 네트워크 장비 통제, 해킹, 웜, 유해 트래픽 탐지 및 차단 등이 있다."},{"n":37,"s":"s2","q":"다음 중 내부망에서 외부망을 향하는 패킷들을 모니터링하고 통제하여 비인가 트래픽이나 악성 트래픽이 내부망을 벗어나지 않도록 만드는 방식의 필터링으로 알맞은 것은?","c":["Contents Filtering","Blacklist Filtering","Egress Filtering","Inference Filtering"],"a":2,"e":"Egress Filtering은 내부에서 외부로 나가는 패킷을 검사해 위조된 출발지 IP나 악성·비인가 트래픽의 유출을 차단한다. 반대로 외부에서 들어오는 패킷을 검사하는 것은 Ingress Filtering이다.","ce":["Contents Filtering은 웹·메일 콘텐츠의 유해 정보(키워드·URL 등)를 차단하는 방식으로, 방향(내부→외부) 기준 필터링 개념이 아니다.","Blacklist Filtering은 알려진 악성 IP·도메인 목록과 일치하는 트래픽을 차단하는 방식으로, 나가는 트래픽 통제를 뜻하는 용어가 아니다.","Egress Filtering은 내부망에서 외부로 나가는 패킷을 검사해 위조 출발지 IP·악성 트래픽 유출을 막으므로 정답이다(반대 방향은 Ingress Filtering).","Inference Filtering은 통용되는 네트워크 필터링 방식 명칭이 아니다."],"rel":["2-12"]},{"n":38,"s":"s2","q":"IP Fragmentation을 이용하여 공격을 수행하는 공격 기법은?","c":["Teardrop","SYN Flooding","ICMP Flooding","LAND Attack"],"a":0,"e":"Teardrop은 IP 단편의 Fragment Offset을 중첩·조작해 재조립 과정에서 오류와 시스템 장애를 일으키는 공격이다. LAND는 출발지·목적지 IP를 동일하게 위조하고, SYN Flooding은 TCP 연결 대기 큐를 고갈시킨다.","ce":["Teardrop은 IP 단편의 Fragment Offset을 중첩·조작해 재조립 과정에서 오류와 장애를 일으키는 IP Fragmentation 이용 공격이므로 정답이다.","SYN Flooding은 TCP SYN만 대량 전송해 연결 대기 큐를 고갈시키는 공격으로 단편화와 무관하다.","ICMP Flooding은 ICMP 패킷을 대량 전송해 대역폭을 소진하는 공격으로 단편 조작이 핵심이 아니다.","LAND Attack은 출발지와 목적지 IP·포트를 같게 위조한 SYN 패킷으로 대상이 자신에게 응답하게 하는 공격이다."],"rel":["2-12","2-3"]},{"n":39,"s":"s2","q":"IPSec 프로토콜의 설명 중 옳지 않은 것은?","c":["IPSec은 전송데이터 보호 구간에 따라 트랜스포트 모드와 터널 모드로 나뉘며, End-to-End 전송 데이터 보호를 위해서는 터널 모드를 사용해야 한다.","ESP를 설정하면 데이터 기밀성을 제공하여 데이터가 노출되는 것을 차단할 수 있다.","AH를 설정할 시 데이터가 수정되지 않았음을 보장할 수 있다.","트랜스포트 모드 AH헤더는 IP헤더와 IP페이로드 사이에 삽입된다."],"a":0,"e":"종단 호스트 간(End-to-End) 보호에는 원래 IP 헤더를 유지하고 페이로드만 보호하는 트랜스포트 모드를 사용하며, 터널 모드는 IP 패킷 전체를 캡슐화해 주로 게이트웨이 간(VPN) 구간 보호에 쓴다. ESP의 기밀성, AH의 무결성, 트랜스포트 모드 AH 헤더 위치 설명은 맞다.","ce":["종단 호스트 간(End-to-End) 보호에는 원래 IP 헤더를 두고 페이로드만 보호하는 트랜스포트 모드를 쓴다. 터널 모드는 IP 패킷 전체를 캡슐화해 주로 게이트웨이 간 VPN에 쓰므로 틀렸다.","ESP는 페이로드를 암호화해 기밀성을 제공하므로 데이터 노출을 막는다는 설명은 옳다.","AH는 ICV(인증값)로 데이터 무결성과 출처 인증을 제공하므로 수정되지 않았음을 보장한다는 설명은 옳다.","트랜스포트 모드에서 AH 헤더는 원래 IP 헤더와 상위 계층 페이로드(TCP/UDP) 사이에 삽입되므로 옳다."],"rel":["2-6"]},{"n":40,"s":"s2","q":"TTL 필드가 0이 되었으나 아직 목적지에 도달하지 못한 경우 발생하는 ICMP 메시지로 알맞은 것은?","c":["목적지 도달 불가능(destination-unreachable)","시간 경과(time-exceeded)","매개변수 문제(parameter-problem)","발신지 억제(source-quench)"],"a":1,"e":"라우터는 TTL이 0이 된 패킷을 폐기하고 송신자에게 ICMP Time Exceeded(Type 11)를 보내며, traceroute가 이 원리를 이용한다. Destination Unreachable(Type 3)은 경로·포트 도달 불가, Source Quench(Type 4)는 혼잡 제어 메시지이다.","ce":["Destination Unreachable(Type 3)은 경로 없음·호스트·포트 도달 불가 등으로 전달할 수 없을 때 보내며, TTL 만료 시 메시지가 아니다.","라우터는 TTL이 0이 된 패킷을 폐기하고 송신자에게 ICMP Time Exceeded(Type 11)를 보내므로 정답이다(traceroute가 이를 이용).","Parameter Problem(Type 12)은 IP 헤더 필드 값이 잘못되어 처리할 수 없을 때 보내는 메시지이다.","Source Quench(Type 4)는 수신 측 버퍼가 넘칠 때 송신 속도를 줄이라고 요청하는 혼잡 제어 메시지이다(현재는 폐기)."],"rel":["2-12"]},{"n":41,"s":"s3","q":"다음 지문에서 설명하고 있는 DB 보안 요구사항으로 적절한 것은?","c":["감사 기능","추론 방지","데이터 무결성","접근 통제"],"a":2,"e":"데이터 무결성은 잘못된 갱신·불법 조작으로부터 데이터를 보호해 값의 정확성과 일관성을 유지하는 요구사항이다. 추론 방지는 비밀 정보가 공개 정보로부터 유추되는 것을 막는 것이고, 감사 기능은 접근 기록을 남기는 것이다.","ce":["감사 기능은 DB 접근·변경 기록을 남겨 사후 추적을 가능하게 하는 요구사항으로, 값의 정확성 유지 자체가 아니다.","추론 방지는 공개된 통계·데이터로부터 비밀 정보를 유추하지 못하게 하는 요구사항이다.","데이터 무결성은 잘못된 갱신·불법 조작으로부터 데이터를 보호해 값의 정확성·일관성을 유지하는 요구사항이므로 정답이다.","접근 통제는 사용자별 권한에 따라 데이터 접근을 허용·거부하는 요구사항으로, 정확성 보장은 그 결과일 뿐 정의가 다르다."],"rel":["3-8"],"box":"- 데이터베이스 내에 있는 자료값들이 정확하도록 보장하는 관리 작업\n- 잘못된 갱신으로부터의 보호나 불법적인 조작에 대한 보호를 통한 정확성 유지"},{"n":42,"s":"s3","q":"디지털포렌식 과정 중 수집된 디지털 증거를 이송, 분석, 보관, 법정 제출 등 각 단계에서 담당자 및 책임자를 명확히 함으로써 증거물의 진정성을 판단하는 중요한 기준을 지칭하는 원칙은?","c":["관리 연속성","독수독과성","전문 배제성","증거 무결성"],"a":0,"e":"연계 보관성(Chain of Custody, 관리 연속성)은 증거의 수집·이송·분석·보관·제출 전 과정에서 담당자와 이력을 기록해 증거가 바뀌지 않았음을 입증하는 원칙이다. 증거 무결성은 해시값 등으로 증거 자체가 변경되지 않았음을 보장하는 원칙이다.","ce":["관리 연속성(연계 보관성, Chain of Custody)은 증거의 이송·분석·보관·제출 각 단계의 담당자와 이력을 명확히 해 진정성을 입증하는 원칙이므로 정답이다.","독수독과성(독수독과 이론)은 위법하게 수집된 증거에서 파생된 증거도 증거능력이 없다는 법 원칙으로, 단계별 책임자 명확화와 다르다.","전문 배제성(전문법칙)은 직접 경험하지 않은 전해 들은 진술의 증거능력을 원칙적으로 부정하는 법칙이다.","증거 무결성은 해시값 등으로 증거가 수집 이후 변경되지 않았음을 보장하는 원칙으로, 단계별 담당자 기록을 강조하는 연계 보관성과 구분된다."],"rel":["3-11"]},{"n":43,"s":"s3","q":"전자상거래 환경에서 구매자의 신용카드 정보 등 중요 지불 정보를 이용하여 판매자 대신 신용카드사 등 금융기관에 결제를 요청하고 처리하는 기관의 명칭은?","c":["CA(Certification Authority)","PG(Payment Gateway)","TGS(Ticket Granting Service)","KDC(Key Distribution Center)"],"a":1,"e":"PG(Payment Gateway)는 상점과 카드사·은행 등 금융망을 중계해 구매자의 지불 정보로 결제 승인을 대행하는 기관이다. CA는 인증서 발급 기관이고, TGS·KDC는 Kerberos의 구성 요소이다.","ce":["CA(인증기관)는 공개키 인증서를 발급·관리하는 기관으로, 결제 승인을 대행하지 않는다.","PG(Payment Gateway)는 상점을 대신해 구매자의 지불 정보로 카드사·은행에 결제를 요청·처리하는 기관이므로 정답이다.","TGS(Ticket Granting Service)는 Kerberos에서 서비스 티켓을 발급하는 구성요소로 전자상거래 결제와 무관하다.","KDC(Key Distribution Center)는 Kerberos 등에서 세션키를 분배하는 키 분배 센터로 결제 기관이 아니다."],"rel":["3-13"]},{"n":44,"s":"s3","q":"웹에서 보안 문제 발생 시 아파치 로그를 분석하여 문제를 해결하는 방법으로 가장 부적절한 것은?","c":["클라이언트의 IP 주소, 클라이언트의 접속시간 정보에 대한 로그 내용을 분석한다.","클라이언트의 요청방식(GET, POST) 및 요청 내용(URL)에 대한 로그 내용을 분석한다.","특정 파일에 대한 연속적인 요청이 있을 시 로그 패턴을 분석한다.","웹서버에서 특정 웹페이지(파일)의 요청이 많은 경우에 대한 로그 패턴을 분석한다."],"a":3,"e":"특정 웹페이지 요청이 많은 것은 정상적인 인기 페이지에서도 나타나므로 그 자체로 보안 문제 분석 기준이 되기 어렵다. 반면 클라이언트 IP·접속시간, 요청 방식·URL, 특정 파일에 대한 연속 요청 패턴은 공격 탐지에 직접 활용된다.","ce":["클라이언트 IP와 접속 시간은 공격 출처와 시점을 파악하는 기본 분석 항목이므로 적절한 방법이다.","요청 방식(GET·POST)과 요청 URL을 분석하면 SQL 인젝션·웹셸 접근 등 공격 흔적을 찾을 수 있어 적절하다.","특정 파일에 대한 연속 요청 패턴은 무차별 대입·스캐닝·DoS 징후이므로 분석할 가치가 있어 적절하다.","특정 페이지 요청이 많은 것은 정상적인 인기 페이지에서도 흔히 나타나므로, 그 자체로는 보안 문제 분석 기준이 되기 어려워 가장 부적절하다."],"rel":["3-4"]},{"n":45,"s":"s3","q":"FTP bounce 공격과 거리가 먼 것은?","c":["익명 FTP 서버를 이용해 그 FTP 서버를 경유해서 호스트를 스캔","FTP 서버를 통해 임의의 네트워크 접속을 릴레이함으로써 수행","네트워크에 대한 포트 스캐닝에 이용","익명 사용자가 서버에 쓰기 권한이 있을 때 악성코드 생성"],"a":3,"e":"FTP 바운스 공격은 FTP PORT 명령으로 데이터 연결 대상을 임의 호스트·포트로 지정해 FTP 서버를 경유한 포트 스캔이나 접속 릴레이를 수행한다. 익명 쓰기 권한을 이용한 악성코드 업로드는 Anonymous FTP 설정 취약점이다.","ce":["익명 FTP 서버의 PORT 명령으로 데이터 연결 대상을 임의 호스트·포트로 지정해 FTP 서버를 경유한 스캔을 하는 것이 FTP 바운스 공격이다.","PORT 명령을 악용해 FTP 서버가 제3의 호스트로 연결하게 만들어 접속을 릴레이하는 것이 FTP 바운스 공격이다.","FTP 서버를 경유해 방화벽 내부 네트워크의 포트를 스캔하는 데 쓰이므로 FTP 바운스 공격의 활용 사례이다.","익명 사용자에게 쓰기 권한이 있을 때 악성코드를 올리는 것은 Anonymous FTP 설정 취약점으로, PORT 명령을 악용하는 바운스 공격과 다르므로 정답이다."],"rel":["3-1"]},{"n":46,"s":"s3","q":"다음 중 DB 보안 강화를 위한 지침으로 가장 부적절한 것은?","c":["노출 및 기능 최소화","관리자 최소화","로컬 계정 사용 금지","Guest 계정 사용 금지"],"a":2,"e":"DB 보안 지침은 불필요한 기능·노출 최소화, 관리자 계정 최소화, 기본·Guest 계정 제거 등이다. 로컬 계정 자체를 금지하는 것은 DB 운영상 불가능하고 보안 지침에 해당하지 않는다.","ce":["불필요한 기능·서비스·포트 노출을 최소화하는 것은 공격 표면을 줄이는 기본 DB 보안 지침이다.","DBA 등 관리자 권한 계정을 최소화하면 권한 오남용·탈취 피해를 줄일 수 있어 적절한 지침이다.","로컬 계정 자체를 금지하는 것은 DB 운영상 불가능하며 일반적인 DB 보안 지침이 아니므로 가장 부적절하다.","Guest·기본(샘플) 계정은 공격자가 쉽게 추측할 수 있어 제거·잠금하는 것이 적절한 지침이다."],"rel":["3-8"]},{"n":47,"s":"s3","q":"KISA에서 발표한 생체인식기반 간편 공인인증 가이드라인의 보안 요구사항으로 부적합한 사항들은?","c":["ⓐ, ⓓ","ⓐ, ⓒ","ⓑ, ⓒ","ⓑ, ⓓ"],"a":2,"e":"생체정보 로컬인증도 무차별 대입을 막기 위해 실패 횟수를 제한해야 하므로 ⓑ는 틀렸고, 타인을 본인으로 받아들이는 오인식률(FAR) 5%는 인증 수단으로 허용할 수 없을 만큼 높은 수치라 ⓒ도 부적합하다. 안전한 하드웨어 저장소(TEE·SE) 활용과 장치 취약점 발견 시 즉시 보안조치는 적합한 요구사항이다.","ce":["ⓐ 루팅·탈옥 시 일반 저장소가 노출되므로 TEE·SE 같은 안전한 하드웨어 저장소 활용 권고와 ⓓ 취약점 발견 즉시 보안조치는 모두 적합한 요구사항이다.","ⓐ는 적합한 요구사항이다. ⓒ는 부적합하지만 ⓐ가 짝으로 들어가 틀렸다.","ⓑ 생체정보 로컬인증도 무차별 대입 방지를 위해 실패 횟수를 제한해야 하고, ⓒ 오인식률(FAR) 5%는 타인을 본인으로 받아들일 비율이 지나치게 높아 부적합하므로 정답이다.","ⓑ는 부적합하지만 ⓓ 지문인식 장치 취약점 발견 즉시 보안조치는 적합한 요구사항이라 짝이 틀렸다."],"rel":["4-8"],"box":"ⓐ 루팅 및 탈옥 등 스마트폰이 불법 변경되면 모든 저장소에 접근이 가능하여 안전한 하드웨어 저장소를 활용할 것을 권고한다.\nⓑ 생체정보 등의 로컬인증 실패 횟수는 제한하지 않되 비밀번호 등은 실패 횟수를 제한하여야 한다.\nⓒ 장치의 오인식률(FAR)은 5%미만이어야 한다.\nⓓ 스마트폰 내 지문인식 장치의 취약점이 발견되는 즉시 보안조치가 이루어져야 한다."},{"n":48,"s":"s3","q":"DRM에 대한 설명 중 적절하지 못한 것은?","c":["커널에 삽입된 DRM 모듈은 응용 프로그램이 작성한 문서를 암호화하여 하드디스크에 저장한다.","문서보안 기술의 하나로서 문서의 열람, 편집, 인쇄에 접근권한을 설정하여 통제한다.","관리자는 각 개인의 DRM 인증서에 권한을 설정하여 각 개인의 문서에 대한 접근권한을 관리할 수 있다.","DRM은 과거 IP 관리 시스템이 발전한 형태의 솔루션으로서, MAC 주소를 기반으로 접근제어 및 인증을 수행한다."],"a":3,"e":"DRM은 문서(콘텐츠) 자체를 암호화하고 사용자 인증서·라이선스에 설정된 권한에 따라 열람·편집·인쇄를 통제하며, MAC 주소 기반 접근제어 솔루션이 아니다. MAC 주소·IP 기반 단말 통제는 IP 관리 시스템이나 NAC의 특성이다.","ce":["DRM 클라이언트 모듈(커널 필터 드라이버 등)이 응용 프로그램이 저장하는 문서를 자동 암호화해 디스크에 저장하는 것은 문서 DRM의 동작 방식으로 옳다.","문서의 열람·편집·인쇄·반출 등 사용 권한을 설정해 통제하는 문서보안 기술이라는 설명은 옳다.","관리자가 사용자 인증서·라이선스에 권한을 설정해 문서별 접근 권한을 관리하는 것은 DRM의 권한 관리 방식으로 옳다.","DRM은 콘텐츠 자체를 암호화하고 라이선스로 사용 권한을 통제하는 기술이다. IP 관리 시스템에서 발전해 MAC 주소 기반으로 접근제어하는 것은 NAC의 특성이므로 틀렸다."],"rel":["3-12"]},{"n":49,"s":"s3","q":"서버 측 스크립트 언어가 아닌 것은?","c":["JSP","ASP","HTML","PHP"],"a":2,"e":"JSP·ASP·PHP는 웹 서버에서 실행되어 결과 HTML을 생성하는 서버 측 스크립트 언어이다. HTML은 브라우저가 해석하는 마크업 언어로 서버 측 스크립트가 아니다.","ce":["JSP(Java Server Pages)는 웹 서버(서블릿 컨테이너)에서 실행되어 HTML을 생성하는 서버 측 스크립트이다.","ASP(Active Server Pages)는 IIS 웹 서버에서 실행되는 마이크로소프트의 서버 측 스크립트이다.","HTML은 브라우저가 해석해 화면을 구성하는 마크업 언어로, 서버에서 실행되는 스크립트 언어가 아니므로 정답이다.","PHP는 웹 서버에서 실행되어 동적 HTML을 생성하는 대표적 서버 측 스크립트 언어이다."],"rel":["3-3"]},{"n":50,"s":"s3","q":"OWASP TOP 10 - 2017과 거리가 먼 것은?","c":["DDoS : UDP 등 사용하지 않는 프로토콜 차단 및 모니터링 체계 구성이 필요함","민감한 데이터 노출 : 중요한 데이터를 저장 및 전송할 때 암호화 같은 추가적인 보호 조치가 요구됨","취약한 인증 : 인증 및 세션 관리와 관련된 애플리케이션 기능이 잘못 구현되어 있는 상황에서 발생","불충분한 로깅 &모니터링 : 로깅과 모니터링을 적절히 수행하지 않을 경우 사고에 대한 적절한 대응이 불가"],"a":0,"e":"OWASP Top 10 2017은 인젝션, 취약한 인증, 민감한 데이터 노출, XXE, 취약한 접근통제, 보안 설정 오류, XSS, 안전하지 않은 역직렬화, 알려진 취약점 컴포넌트 사용, 불충분한 로깅·모니터링으로 구성된다. DDoS는 웹 애플리케이션 취약점이 아닌 네트워크 가용성 공격으로 목록에 없다.","ce":["DDoS는 네트워크·서비스 가용성을 공격하는 것으로, 웹 애플리케이션 보안 취약점 목록인 OWASP Top 10 2017에 포함되지 않으므로 정답이다.","민감한 데이터 노출(A3:2017)은 저장·전송 시 암호화 등 보호조치가 부족해 발생하는 OWASP Top 10 2017 항목이다.","취약한 인증(A2:2017)은 인증·세션 관리 기능이 잘못 구현되어 발생하는 OWASP Top 10 2017 항목이다.","불충분한 로깅 및 모니터링(A10:2017)은 탐지·대응 지연을 초래하는 OWASP Top 10 2017 항목이다."],"rel":["3-5"]},{"n":51,"s":"s3","q":"휘발성의 순위가 가장 높은 것은?","c":["Register, Cache","Routing Table, ARP Cache","Temporary File System","Disk"],"a":0,"e":"RFC 3227 증거 수집 순서는 휘발성이 높은 순으로 레지스터·캐시 → 라우팅 테이블·ARP 캐시·프로세스 테이블·메모리 → 임시 파일 시스템 → 디스크 → 원격 로그 → 백업 매체 순이다. 디스크는 전원이 꺼져도 유지되므로 휘발성이 가장 낮은 편이다.","ce":["레지스터·캐시는 CPU 내부에서 나노초 단위로 바뀌어 RFC 3227 수집 순서상 휘발성이 가장 높으므로 정답이다.","라우팅 테이블·ARP 캐시는 메모리에 있어 휘발성이 높지만 레지스터·캐시 다음 순위이다.","임시 파일 시스템은 메모리 정보보다 휘발성이 낮은 편으로 라우팅 테이블·메모리 다음에 수집한다.","디스크는 전원이 꺼져도 데이터가 유지되는 비휘발성 저장소로 휘발성 순위가 낮다."],"rel":["3-11"]},{"n":52,"s":"s3","q":"FTP 서비스에 대한 공격과 거리가 먼 것은?","c":["Sniffing 공격","비밀번호에 대한 Brute Force 공격","bounce 공격","CSRF 공격"],"a":3,"e":"FTP는 평문 전송으로 스니핑에 취약하고, 계정 무차별 대입 공격과 PORT 명령을 악용한 바운스 공격 대상이 된다. CSRF는 로그인된 웹 사용자의 브라우저로 위조 요청을 보내게 하는 웹 애플리케이션 공격이다.","ce":["FTP는 계정·데이터를 평문으로 전송해 스니핑으로 비밀번호가 노출될 수 있으므로 FTP 대상 공격이다.","FTP 로그인 계정에 비밀번호를 무작위로 대입하는 Brute Force 공격은 대표적 FTP 공격이다.","FTP PORT 명령을 악용해 제3 호스트로 연결을 우회시키는 bounce 공격은 FTP 고유의 공격이다.","CSRF는 로그인한 웹 사용자의 브라우저가 위조 요청을 보내게 하는 웹 애플리케이션 공격으로 FTP 서비스와 무관하므로 정답이다."],"rel":["3-1"]},{"n":53,"s":"s3","q":"SSL 프로토콜에 대한 설명 중 잘못된 것은?","c":["SSL 프로토콜에 지정된 포트는 443임","세션 계층에서 적용되며, FTP, TFTP, SYSLOG 등과 같은 응용 계층 프로토콜의 안전성 보장을 위해 사용될 수 있음","웹 서버와 브라우저 간의 안전한 통신을 위해 넷스케이프에 의해 개발됨","SSL을 사용하기 위해서는 우리가 흔히 사용하는 URL 표기 방식인 \"http://*\" 대신에 \"https://*\"를 사용해야 함"],"a":1,"e":"SSL은 TCP 위에서 동작하므로 UDP 기반인 TFTP·SYSLOG(기본 UDP 514)에는 그대로 적용할 수 없다. HTTPS 기본 포트 443, 넷스케이프 개발, https:// 표기 설명은 맞다.","ce":["HTTPS(HTTP over SSL/TLS)의 기본 지정 포트는 443이므로 옳은 설명이다.","SSL은 TCP 위에서 동작하므로 UDP 기반인 TFTP·SYSLOG(기본 UDP 514)에는 그대로 적용할 수 없어 틀린 설명이다.","SSL은 1990년대 넷스케이프가 웹 서버와 브라우저 간 안전한 통신을 위해 개발했으므로 옳다.","SSL로 보호되는 웹 통신은 http:// 대신 https:// 스킴으로 표기하므로 옳다."],"rel":["2-7"]},{"n":54,"s":"s3","q":"제3자가 소비자의 상품 대금을 보관하고 있다가 상품배송이 완료된 후 통신판매업자에게 지급하는 서비스로 알맞은 것은?","c":["선불전자지급 수단발행 서비스","전자지급결제대행(PG) 서비스","결제대금예치(Escrow) 서비스","전자고지결제(EBPP) 서비스"],"a":2,"e":"에스크로(결제대금예치)는 신뢰할 수 있는 제3자가 구매 대금을 보관하다가 구매자의 상품 수령 확인 후 판매자에게 지급해 거래 안전을 보장한다. PG는 결제 승인을 대행하고, EBPP는 전자 청구서 발송·납부 서비스이다.","ce":["선불전자지급수단 발행 서비스는 교통카드·게임머니처럼 미리 충전한 가치로 결제하게 하는 서비스로, 대금을 보관했다가 배송 후 지급하지 않는다.","전자지급결제대행(PG)은 상점을 대신해 카드사·은행에 결제 승인을 요청·정산하는 서비스로, 배송 완료까지 대금을 예치하는 기능이 핵심이 아니다.","결제대금예치(Escrow)는 신뢰할 수 있는 제3자가 구매 대금을 보관하다가 구매자의 상품 수령 확인 후 판매자에게 지급해 거래 안전을 보장하므로 정답이다.","전자고지결제(EBPP)는 공과금·카드대금 등 청구서를 전자적으로 발송하고 납부받는 서비스이다."],"rel":["3-13"]},{"n":55,"s":"s3","q":"다음 지문에서 설명하는 웹 서버 애플리케이션의 취약점은?","c":["SQL Injection","Buffer Overflow","Security Misconfiguration","Cross-Site Scripting(XSS)"],"a":3,"e":"XSS는 입력값을 검증·인코딩하지 않고 동적 페이지에 포함해 전송할 때 삽입된 스크립트가 열람자의 브라우저에서 실행되어 쿠키 등 클라이언트 정보를 유출한다. SQL Injection은 서버 DB 쿼리를 조작하는 공격이다.","ce":["SQL Injection은 입력값으로 서버의 DB 쿼리를 조작하는 공격으로, 게시글 열람자의 브라우저에서 스크립트가 실행되는 것이 아니다.","Buffer Overflow는 입력 길이 검증 미흡으로 프로그램 메모리를 덮어써 코드를 실행시키는 공격으로, 웹 페이지 재전송과 관계없다.","Security Misconfiguration은 기본 계정·불필요한 서비스·디렉터리 리스팅 등 설정 미흡 취약점으로, 입력 스크립트 삽입과 다르다.","입력 데이터를 필터링하지 않고 동적 웹 페이지에 포함해 재전송할 때 삽입된 스크립트가 열람자 브라우저에서 실행되어 정보가 유출되는 XSS이므로 정답이다."],"rel":["3-6"],"box":"게시판의 글에 원본과 함께 악성코드를 삽입하여 글을 읽을 경우 악성코드가 실행되도록 한다. 이는 클라이언트의 정보를 유출하는 공격기법으로, 웹 페이지가 사용자에게 입력 받은 데이터를 필터링하지 않고 그대로 동적으로 생성된 웹 페이지에 포함하여 사용자에게 재전송할 때 발생한다."},{"n":56,"s":"s3","q":"경계 검사의 미비로 버퍼 오버플로우를 발생시킬 우려가 있어 사용하지 않도록 권고되는 C 라이브러리 함수에 포함되지 않는 것은?","c":["strcpy( )","fgets( )","sscanf( )","gethostbyname( )"],"a":1,"e":"fgets()는 읽어 들일 최대 길이를 인자로 받아 경계를 검사하므로 gets()의 안전한 대체 함수로 권고된다. strcpy()·sscanf()는 길이 검사가 없고, gethostbyname()도 버퍼 오버플로우(GHOST 취약점 등) 위험으로 사용 자제가 권고된다.","ce":["strcpy()는 복사할 길이를 검사하지 않아 대상 버퍼보다 긴 문자열이 들어오면 오버플로우가 발생하므로 사용 자제 대상이다(strncpy·strlcpy로 대체).","fgets()는 읽을 최대 길이를 인자로 받아 경계를 검사하므로 gets()를 대체하는 안전한 함수로 권고되어 정답이다.","sscanf()는 %s 등 서식에 길이 제한이 없으면 대상 버퍼를 넘겨 쓸 수 있어 사용 자제 대상이다.","gethostbyname()은 내부 버퍼 처리 결함(glibc GHOST 취약점, CVE-2015-0235)이 있었고 재진입도 불가해 getaddrinfo()로 대체가 권고된다."],"rel":["1-10","3-9"]},{"n":57,"s":"s3","q":"다수의 부분 문자열을 입력하여 공격 문자열을 완성하는 공격기법으로 질의 결과로 참과 거짓만을 확인하며 수행하는 공격 방법은?","c":["SQL Injection","Blind SQL Injection","Union SQL Injection","Mass SQL Injection"],"a":1,"e":"Blind SQL Injection은 오류 메시지나 결과가 직접 노출되지 않을 때 참/거짓 조건(또는 응답 시간)에 따른 응답 차이로 DB 정보를 한 글자씩 추론한다. Union SQL Injection은 UNION으로 다른 테이블 결과를 직접 출력하고, Mass SQL Injection은 한 번에 대량의 DB 값을 변조한다.","ce":["일반 SQL Injection은 조작된 쿼리 결과나 오류 메시지가 화면에 직접 드러나는 경우로, 참·거짓 응답 차이만으로 한 글자씩 추론하는 방식을 특정하지 않는다.","Blind SQL Injection은 결과가 직접 노출되지 않을 때 참/거짓 조건에 따른 응답 차이로 부분 문자열을 하나씩 알아내 정보를 완성하므로 정답이다.","Union SQL Injection은 UNION SELECT로 다른 테이블의 조회 결과를 화면에 직접 출력시키는 방식이다.","Mass SQL Injection은 한 번의 공격으로 DB의 대량 값을 변조해 악성 스크립트 링크를 심는 방식이다."],"rel":["3-6"]},{"n":58,"s":"s3","q":"웹 취약점을 보완하기 위한 내용 중 설명이 틀린 것은?","c":["서버 통제 적용","특수문자 필터링","쿠키(cookie)의 사용","지속적인 세션 관리"],"a":2,"e":"쿠키는 클라이언트에 저장되어 사용자가 조작·탈취할 수 있으므로 중요 정보나 인증 판단을 쿠키에 의존하면 오히려 취약점이 된다. 서버 측 검증·통제, 특수문자 필터링, 서버 측 세션 관리가 올바른 보완책이다.","ce":["입력 검증·권한 확인을 클라이언트가 아닌 서버에서 통제하는 것은 올바른 웹 취약점 보완책이다.","', <, > 같은 특수문자를 필터링·인코딩하면 SQL 인젝션·XSS를 막을 수 있어 올바른 보완책이다.","쿠키는 클라이언트에 저장되어 사용자가 조작·탈취할 수 있으므로, 중요 정보·인증 판단을 쿠키에 의존하는 것은 오히려 취약점이 된다. 보완 내용으로 틀렸다.","세션을 서버 측에서 관리하고 타임아웃·재발급으로 지속적으로 관리하는 것은 세션 하이재킹 대응책으로 올바르다."],"rel":["3-3"]},{"n":59,"s":"s3","q":"CSRF 공격에 대한 설명이 틀린 것은?","c":["자신의 의도와는 무관하게 공격자가 의도한 행위(수정, 삭제, 등록, 송금 등)를 하게 만드는 공격이다.","특정 사용자를 대상으로 하지 않고 불특정 다수를 대상으로 한다.","기본적으로 XSS 공격과 매우 유사하며 XSS 공격의 발전된 형태로 보기도 한다.","XSS 공격은 사용자가 악성스크립트를 서버에 요청하는 데 반해 CSRF는 악성스크립트가 클라이언트에서 실행된다."],"a":3,"e":"XSS는 악성 스크립트가 클라이언트(브라우저)에서 실행되는 반면, CSRF는 사용자가 악성 요청을 서버에 보내 서버에서 공격자가 의도한 행위가 실행되는 것이므로 ④는 반대로 설명했다. 불특정 다수 대상, XSS와의 유사성은 맞는 설명이다.","ce":["CSRF는 로그인한 사용자가 의도와 무관하게 공격자가 의도한 수정·삭제·등록·송금 요청을 보내게 하므로 옳은 설명이다.","CSRF는 악성 게시물을 여는 불특정 다수 사용자를 대상으로 할 수 있다는 설명으로 수험서 기준 옳은 설명이다.","CSRF는 스크립트·태그를 삽입하는 방식이 XSS와 유사해 XSS의 발전된 형태로 보기도 하므로 옳다.","반대로 설명했다. XSS는 악성 스크립트가 클라이언트(브라우저)에서 실행되고, CSRF는 사용자가 위조 요청을 서버에 보내 서버에서 공격 행위가 실행된다."],"rel":["3-6"]},{"n":60,"s":"s3","q":"다음 취약점 및 버그 방지 개발 방법 중 새로운 프로세스를 생성하여 사용할 경우의 보안 대책과 거리가 먼 것은?","c":["모든 파일 기술자들을 닫았는지 확인한다.","strncat( ) 함수나 vfscanf( ) 함수의 사용을 제한한다.","자식 프로세스에 전달된 환경변수를 확인한다.","프로그램을 실행할 때 전체 경로 이름을 사용하는지 확인한다."],"a":1,"e":"새 프로세스 생성(fork/exec) 시에는 불필요한 파일 기술자 상속 차단, 환경변수(PATH 등) 검증, 전체 경로로 프로그램 실행 등을 점검해야 한다. strncat()·vfscanf() 사용 제한은 버퍼 오버플로우 방지 대책으로 프로세스 생성과 무관하다.","ce":["exec 전에 불필요한 파일 기술자를 닫지 않으면 자식 프로세스가 민감한 파일 핸들을 상속받으므로, 확인하는 것은 올바른 대책이다.","strncat()·vfscanf() 사용 제한은 버퍼 오버플로우 방지를 위한 함수 선택 문제로, 새 프로세스 생성 시 점검 사항과 관계가 멀어 정답이다.","자식 프로세스에 전달되는 PATH·LD_PRELOAD 등 환경변수가 조작되면 다른 프로그램이 실행될 수 있어 확인하는 것이 올바른 대책이다.","상대 경로로 실행하면 PATH 조작으로 악성 프로그램이 대신 실행될 수 있어 전체 경로 사용을 확인하는 것이 올바른 대책이다."],"rel":["3-9"]},{"n":61,"s":"s4","q":"블록암호 모드로 알맞은 것은?","c":["Electronic CodeBook Mode","Cipher FeedBack Mode","Output FeedBack Mode","Counter Mode"],"a":1,"e":"CFB 모드는 IV(이후 직전 암호문)를 암호화한 값과 평문을 XOR해 암호문을 만들고, 그 암호문을 다음 블록 암호화 입력으로 피드백한다. OFB는 암호문이 아닌 암호 알고리즘 출력을 피드백하고, CTR은 카운터 값을 암호화해 XOR한다.","ce":["ECB는 각 평문 블록을 독립적으로 같은 키로 암호화하는 모드로, IV나 암호문 피드백이 없다.","CFB는 IV(이후 직전 암호문)를 암호화한 값과 평문을 XOR해 암호문을 만들고 그 암호문을 다음 입력으로 되먹이므로 정답이다. 복호화 시 오류는 일부 블록에만 영향을 준다.","OFB는 암호문이 아니라 암호 알고리즘의 출력(키 스트림)을 다음 입력으로 피드백하므로, 암호문을 입력으로 쓰는 지문과 다르다.","CTR은 카운터 값을 증가시키며 암호화해 평문과 XOR하는 모드로, 이전 블록의 피드백을 사용하지 않는다."],"rel":["4-3"],"box":"초기치를 암호화한 값과 평문 블록을 XOR하여 암호문 블록을 생성하고 그 암호문을 입력으로 사용하여 다시 암호화한 값과 평문 블록을 XOR하여 암호문 블록을 생성하는 과정을 반복하는 방식이다. 암호화에서는 특정 입력이 이후에 계속 영향을 미치지만, 복호화에서는 특정 암호문의 오류가 계속적으로 이후에 영향을 미치지는 않는다는 특징이 있다."},{"n":62,"s":"s4","q":"해시함수 h에 대해 h(x)=h(x')을 만족하는 2개의 서로 다른 입력 x, x'를 찾는 것이 계산적으로 불가능한 것을 의미하는 것은?","c":["일방향성","무결성","두 번째 역상 저항성","충돌저항성"],"a":3,"e":"충돌 저항성은 해시값이 같은 임의의 서로 다른 입력 쌍 (x, x')을 찾기 어려운 성질이다. 두 번째 역상 저항성은 주어진 x에 대해 같은 해시값을 갖는 다른 x'를 찾기 어려운 성질이고, 일방향성은 해시값에서 입력을 찾기 어려운 성질이다.","ce":["일방향성(역상 저항성)은 해시값 y가 주어질 때 h(x)=y인 입력 x를 찾기 어려운 성질이다.","무결성은 데이터가 변경되지 않았음을 보장하는 보안 목표이며, 해시 함수의 수학적 성질 명칭이 아니다.","두 번째 역상 저항성은 이미 주어진 x에 대해 h(x)=h(x')인 다른 x'를 찾기 어려운 성질로, x를 고정한다는 점이 다르다.","충돌 저항성은 h(x)=h(x')를 만족하는 임의의 서로 다른 입력 쌍 (x, x')를 찾는 것이 계산적으로 불가능한 성질이므로 정답이다."],"rel":["4-5"]},{"n":63,"s":"s4","q":"Active Attack과 Passive Attack이 올바르게 짝지어진 것은?","c":["재생 공격, 메시지 변조 공격","트래픽분석 공격, 전송파일 도청","메시지 변조, 전송파일 도청","삽입 공격, 삭제 공격"],"a":2,"e":"능동적 공격은 데이터를 변경·생성하는 메시지 변조·재생·삽입·삭제·서비스 거부이고, 수동적 공격은 도청·트래픽 분석처럼 정보를 엿듣기만 한다. 따라서 (능동, 수동) 순서가 맞는 쌍은 '메시지 변조, 전송파일 도청'이다.","ce":["재생 공격과 메시지 변조는 모두 데이터를 재전송·변경하는 능동적 공격이라 (능동, 수동) 짝이 되지 않는다.","트래픽 분석과 전송파일 도청은 모두 정보를 엿듣기만 하는 수동적 공격이라 능동적 공격이 빠졌다.","메시지 변조는 데이터를 바꾸는 능동적 공격, 전송파일 도청은 엿듣기만 하는 수동적 공격이므로 올바른 짝이다.","삽입과 삭제는 모두 메시지 흐름을 바꾸는 능동적 공격이라 수동적 공격이 빠졌다."],"rel":["4-1"]},{"n":64,"s":"s4","q":"단일 치환 암호를 해독할 수 있는 방법으로 알맞은 것은?","c":["빈도 분석법","치환 분석법","알파벳 분석법","순서 분석법"],"a":0,"e":"단일 치환 암호는 평문 문자가 항상 같은 암호문 문자로 바뀌므로 언어별 문자 출현 빈도(영어의 E, T 등)가 암호문에 그대로 보존되어 빈도 분석으로 해독된다. 다중 치환(비즈네르 등)은 이를 완화하기 위해 고안되었다.","ce":["단일 치환 암호는 평문 문자가 항상 같은 암호문 문자로 바뀌어 언어의 문자 출현 빈도(영어 E·T 등)가 보존되므로 빈도 분석으로 해독되어 정답이다.","'치환 분석법'은 표준 암호 해독 기법 명칭이 아니다. 치환 암호를 푸는 대표 방법은 빈도 분석이다.","'알파벳 분석법'은 표준 해독 기법 명칭이 아니며, 문자 빈도를 이용하는 것이 핵심이다.","'순서 분석법'은 표준 해독 기법 명칭이 아니다. 문자 순서를 뒤섞는 전치 암호 분석과도 구별된다."],"rel":["4-1"]},{"n":65,"s":"s4","q":"전자서명 생성과 검증 과정에 사용되는 키가 올바르게 짝지어진 것은?","c":["생성 - 수신자의 공개키 검증 - 송신자의 개인키","생성 - 송신자의 공개키 검증 - 송신자의 개인키","생성 - 송신자의 개인키 검증 - 송신자의 공개키","생성 - 수신자의 공개키 검증 - 수신자의 개인키"],"a":2,"e":"전자서명은 송신자만 가진 개인키로 서명을 생성하고, 누구나 송신자의 공개키로 검증해 인증과 부인방지를 제공한다. 수신자 공개키로 암호화하고 수신자 개인키로 복호화하는 것은 기밀성을 위한 암호화 방식이다.","ce":["수신자의 공개키는 누구나 가질 수 있어 서명 생성에 쓰면 송신자를 입증할 수 없고, 송신자의 개인키로 검증하는 것은 개인키 공개를 전제로 해 틀렸다.","서명 생성과 검증의 키가 뒤바뀌었다. 서명은 송신자 개인키로 만들고 송신자 공개키로 검증한다.","전자서명은 송신자만 가진 개인키로 생성하고 누구나 송신자의 공개키로 검증해 인증·부인방지를 제공하므로 정답이다.","수신자 공개키로 암호화하고 수신자 개인키로 복호화하는 것은 기밀성을 위한 암호화 방식이지 전자서명이 아니다."],"rel":["4-6","4-4"]},{"n":66,"s":"s4","q":"다음 전자서명 기술은?","c":["이중서명","은닉서명","공개서명","다중서명"],"a":0,"e":"SET의 이중서명(Dual Signature)은 주문정보와 지불정보의 해시를 결합해 서명함으로써, 상점은 지불정보를, 지불 게이트웨이는 주문정보를 보지 못하면서도 두 정보의 연결을 검증할 수 있게 한다. 은닉서명은 서명자가 메시지 내용을 모르고 서명하는 익명성 제공 방식이다.","ce":["SET의 이중서명은 주문정보와 지불정보의 해시를 결합해 서명해, 상점은 지불정보를, PG는 주문정보를 보지 않고도 두 정보의 연결을 검증하게 하므로 정답이다.","은닉서명은 서명자가 메시지 내용을 모른 채 서명해 익명성을 주는 방식으로 전자화폐·전자투표에 쓰이며, SET 주문·지불정보 분리와 다르다.","공개서명은 SET에서 도입된 특정 전자서명 기술의 명칭이 아니다.","다중서명은 여러 서명자가 하나의 메시지에 공동으로 서명하는 방식으로, 한 서명자가 두 정보를 연결해 서명하는 이중서명과 다르다."],"rel":["4-6","3-10"],"box":"전자상거래 SET 프로토콜에서 도입된 기술로 고객의 구매 요청은 지불정보와 더불어 일단 상인에게 전달되면 상인은 그 구매 요청에 포함된 지불정보를 이용하여 지불 게이트웨이에게 유효성을 확인하게 된다. 또한 구매자의 자세한 주문정보와 지불정보를 판매자와 금융기관에 필요 이상으로 전달하지 않아야 한다."},{"n":67,"s":"s4","q":"다음 중 메시지 인증 코드(MAC)의 특징으로 옳지 않은 것은?","c":["메시지에 붙여지는 작은 데이터 블록을 생성하기 위해 비밀키를 이용","메시지와 비밀키를 입력하여 인증값으로 사용될 고정길이 값을 생성","수신자는 수신된 메시지에 동일키를 이용하여 새 메시지 인증코드를 생성하기 위해 동일한 계산을 수행","송신자는 메시지를 공개키로 암호화하여 보냄으로써 메시지 송신에 대한 부인을 방지"],"a":3,"e":"MAC은 송·수신자가 공유한 비밀키(대칭키)로 고정 길이 인증값을 생성·검증해 무결성과 메시지 인증을 제공하지만, 같은 키를 양쪽이 가지므로 부인방지는 제공하지 못한다. 부인방지는 송신자 개인키로 서명하는 전자서명으로 달성한다.","ce":["MAC은 송·수신자가 공유한 비밀키로 메시지에 붙일 작은 인증 데이터 블록(태그)을 생성하므로 옳은 특징이다.","MAC 함수는 메시지와 비밀키를 입력받아 고정 길이 인증값을 생성하므로 옳다.","수신자는 받은 메시지에 같은 비밀키로 MAC을 다시 계산해 받은 값과 비교하므로 옳다.","MAC은 공개키가 아니라 공유 비밀키를 쓰고, 양쪽이 같은 키를 가져 부인방지를 제공하지 못한다. 부인방지는 송신자 개인키 전자서명으로 달성하므로 틀렸다."],"rel":["4-5"]},{"n":68,"s":"s4","q":"강제적 접근통제의 특징이 아닌 것은?","c":["보안관리자 주도 하에 중앙집중적 관리가 가능","접근 규칙 수가 적어 통제가 용이","이직률이 높은 기업에 적합","사용자와 데이터는 보안등급을 부여 받아 적용"],"a":2,"e":"이직률(인사 이동)이 높은 조직에는 사용자 대신 역할에 권한을 부여해 역할 배정만 바꾸면 되는 역할기반 접근통제(RBAC)가 적합하다. MAC는 보안관리자가 주체·객체에 보안등급(레이블)을 부여하고 중앙에서 규칙으로 강제한다.","ce":["MAC(강제적 접근통제)는 보안관리자가 주체·객체의 보안등급과 규칙을 중앙에서 정해 강제하므로 옳은 특징이다.","MAC는 보안등급 비교라는 적은 수의 규칙으로 모든 접근을 판단해 통제가 용이하다는 것은 교재상 MAC의 특징이다.","이직률(인사 이동)이 높은 조직에는 사용자 대신 역할에 권한을 부여하는 RBAC가 적합하다. MAC는 사용자마다 등급을 부여·관리해야 해 이 특징에 해당하지 않으므로 정답이다.","MAC에서는 사용자(주체)와 데이터(객체)가 보안등급(레이블)을 부여받아 이를 비교해 접근을 결정하므로 옳다."],"rel":["4-10"]},{"n":69,"s":"s4","q":"다음 지문에서 설명하는 대칭키 알고리즘 공격방법은?","c":["암호문 단독 공격","기지 평문 공격","선택 평문 공격","선택 암호문 공격"],"a":1,"e":"기지 평문 공격(Known Plaintext Attack)은 공격자가 일정량의 평문-암호문 쌍을 알고 있는 상태에서 키나 다른 암호문의 평문을 추정한다. 선택 평문 공격은 공격자가 평문을 직접 골라 암호화 결과를 얻을 수 있는 경우이다.","ce":["암호문 단독 공격은 공격자가 암호문만 가진 상태로, 알려진 평문-암호문 쌍을 이용하지 않는다.","기지 평문 공격은 공격자가 일정량의 평문과 대응 암호문을 알고 있는 상태에서 키나 다른 암호문의 평문을 추정하므로 정답이다.","선택 평문 공격은 공격자가 원하는 평문을 골라 암호화 결과를 얻을 수 있는 경우로, 단순히 '알고 있는' 쌍을 쓰는 기지 평문 공격보다 강하다.","선택 암호문 공격은 공격자가 암호문을 골라 복호화 결과를 얻을 수 있는 경우이다."],"rel":["4-1"],"box":"- 암호화 키를 알아내거나, 다른 암호문들에 대응되는 평문을 추정하는 방법\n- 암호 해독자는 일정량의 알려진 평문에 대응하는 암호문을 알고 있음"},{"n":70,"s":"s4","q":"해시함수 MD5와 SHA-1의 출력 값의 비트수를 올바르게 나열한 것은?","c":["MD5 : 128 SHA-1 : 160","MD5 : 128 SHA-1 : 256","MD5 : 160 SHA-1 : 160","MD5 : 160 SHA-1 : 256"],"a":0,"e":"MD5는 128비트, SHA-1은 160비트 해시값을 출력한다. 256비트는 SHA-256의 출력 길이이며, 160비트는 RIPEMD-160도 해당한다.","ce":["MD5는 128비트, SHA-1은 160비트 해시값을 출력하므로 정답이다.","MD5 128비트는 맞지만 SHA-1은 160비트이다. 256비트는 SHA-256의 출력 길이이다.","SHA-1 160비트는 맞지만 MD5는 128비트이다. 160비트 출력은 SHA-1·RIPEMD-160이다.","MD5는 128비트, SHA-1은 160비트이므로 두 값 모두 틀렸다."],"rel":["4-5"]},{"n":71,"s":"s4","q":"접근통제 보안 모델은?","c":["State Machine Model","Bell-LaPadula Model","Biba Model","Lattice Model"],"a":1,"e":"BLP(Bell-LaPadula) 모델은 기밀성 중심의 최초 수학적 보안 모델로 No Read Up(단순 보안 속성)과 No Write Down(*-속성) 규칙을 적용한다. Biba 모델은 무결성 중심으로 No Read Down, No Write Up을 적용한다.","ce":["State Machine Model은 시스템이 항상 안전한 상태에서 안전한 상태로만 전이함을 증명하는 일반 개념으로, No Read Up·No Write Down 규칙을 가진 특정 모델이 아니다.","Bell-LaPadula 모델은 기밀성 중심의 최초 수학적 모델로, 상위 등급 읽기 금지(No Read Up)와 하위 등급 쓰기 금지(No Write Down)를 적용하므로 정답이다.","Biba 모델은 무결성 중심 모델로, 하위 등급 읽기 금지(No Read Down)와 상위 등급 쓰기 금지(No Write Up)를 적용해 BLP와 반대 방향이다.","Lattice Model은 보안 등급을 격자 구조로 정의해 상한·하한을 두는 개념 모델로, 지문의 '최초 정보 흐름 수학 모델'이자 두 규칙을 명시한 모델은 BLP이다."],"rel":["4-11"],"box":"이 모델은 허가되지 않은 방식의 접근을 방지하는 모델로서, 정보 흐름 모델 최초의 수학적 모델이다. MAC(Mandatory Access Control) 방식으로 접근을 통제하며, 시스템 내부에 있는 정보의 기밀성을 보호한다. 이 모델에서 주체는 자신의 인가권 수준보다 높은 수준의 데이터를 읽을 수 없으며, 주체는 데이터를 자신의 인가권 수준보다 낮은 수준의 객체에 기록할 수 없다."},{"n":72,"s":"s4","q":"은닉서명에 대한 설명으로 옳은 것은?","c":["은닉서명은 전자화폐 이용 시 사용자의 신원 노출 문제점을 해결하는 전자서명 기술이다.","은닉서명은 전자서명 발급 이후에 메시지에 대한 서명의 유효성을 확인할 수 없으나, 서명 생성자는 수신자의 신원을 알 수 있다.","은닉서명은 사용자 A가 서명자 B에게 자신의 메시지를 보여 주고 서명을 얻는 방법이다.","은닉서명 검증자는 메시지에 대한 서명의 유효성을 확인할 수 없으나 송신자의 신원을 알 수 있다."],"a":0,"e":"은닉서명(Blind Signature)은 서명자가 메시지 내용을 보지 못한 채 서명하고 나중에 서명과 요청자를 연결할 수 없어 전자화폐·전자투표의 익명성을 보장한다. 서명의 유효성은 누구나 검증할 수 있고, 메시지를 보여 주지 않는다는 점에서 ②~④는 틀렸다.","ce":["은닉서명은 서명자가 메시지 내용을 모른 채 서명하고 이후 서명과 요청자를 연결할 수 없어 전자화폐 사용자의 신원 노출 문제를 해결하므로 정답이다.","은닉서명도 발급 후 누구나 서명 유효성을 검증할 수 있고, 서명 생성자는 서명과 요청자의 신원을 연결할 수 없으므로 두 부분 모두 틀렸다.","은닉서명은 메시지를 가린(blinding) 상태로 서명받는 방식이므로, 메시지를 보여 주고 서명을 얻는다는 설명은 반대이다.","검증자는 서명의 유효성을 확인할 수 있고, 익명성 때문에 송신자 신원은 알 수 없으므로 두 부분 모두 반대로 설명했다."],"rel":["4-6"]},{"n":73,"s":"s4","q":"Hybrid 암호화 시스템에 관련된 설명으로 틀린 것은?","c":["대칭 암호시스템은 1회용 세션키로 데이터를 암호화하는 용도로 사용한다.","공개키 암호시스템은 대칭 암호알고리즘에서 사용할 1회용 세션키를 분배하는 용도로 사용한다.","공개키 암호시스템은 암·복호 속도가 느려 대용량 데이터 암호화에 부적합하기 때문에 속도가 빠른 대칭암호시스템을 혼용하는 것이다.","키 분배를 대칭암호시스템으로 암호화하여 분배하고, 암호화할 데이터를 공개키로 암호화한다."],"a":3,"e":"하이브리드 암호는 데이터는 빠른 대칭키(세션키)로 암호화하고, 세션키는 수신자의 공개키로 암호화해 분배한다. ④는 두 역할을 뒤바꿔 설명했다.","ce":["하이브리드 암호에서 대용량 데이터는 빠른 대칭키 알고리즘과 1회용 세션키로 암호화하므로 옳은 설명이다.","공개키 암호는 세션키를 수신자 공개키로 암호화해 안전하게 분배하는 용도로 쓰이므로 옳다.","공개키 암호는 연산이 느려 대용량 데이터에 부적합하므로 빠른 대칭키와 혼용한다는 설명은 옳다.","두 역할을 뒤바꿨다. 세션키 분배는 공개키 암호로, 데이터 암호화는 대칭키로 수행하므로 틀린 설명이다."],"rel":["4-1"]},{"n":74,"s":"s4","q":"X.509 공개키 인증서에 포함되는 내용이 아닌 것은?","c":["인증서 소유자","인증서 발행기관","인증서 서명 알고리즘명","인증서 소유자의 개인키"],"a":3,"e":"X.509 인증서에는 버전, 일련번호, 서명 알고리즘, 발행자, 유효기간, 소유자(주체), 소유자의 공개키 정보, CA의 서명 등이 포함된다. 개인키는 소유자만 비밀리에 보관해야 하므로 인증서에 절대 포함되지 않는다.","ce":["인증서 소유자(주체, Subject)의 식별 정보는 X.509 인증서의 기본 필드이다.","인증서 발행기관(Issuer)은 인증서를 서명한 CA의 이름으로 X.509 기본 필드이다.","인증서 서명 알고리즘(Signature Algorithm) 식별자는 CA 서명 방식을 나타내는 X.509 기본 필드이다.","개인키는 소유자만 비밀로 보관해야 하므로 인증서에 포함되지 않는다. 인증서에는 소유자의 공개키가 들어가므로 정답이다."],"rel":["4-7"]},{"n":75,"s":"s4","q":"블록암호의 운용 모드로 알맞은 것은?","c":["ECB 모드","CBC 모드","CFB 모드","OFB 모드"],"a":3,"e":"OFB 모드는 IV를 반복 암호화한 출력(키 스트림)을 평문과 XOR하므로 평문이 암호 알고리즘 입력으로 쓰이지 않고, 오류가 전파되지 않는 동기식 스트림 암호로 동작한다. CFB는 암호문을 피드백하므로 오류가 일부 전파되고, ECB·CBC는 평문 블록이 암호 알고리즘 입력으로 사용된다.","ce":["ECB는 각 평문 블록을 직접 블록 암호에 입력하므로 '평문이 암호 알고리즘 입력으로 전혀 쓰이지 않는다'는 특징과 맞지 않는다.","CBC는 평문을 직전 암호문과 XOR한 뒤 블록 암호에 입력하며, 복호화 시 오류가 다음 블록까지 전파된다.","CFB는 평문이 암호 알고리즘에 직접 들어가지는 않지만 암호문을 피드백하므로 암호문 오류가 후속 블록에 전파된다.","OFB는 IV를 반복 암호화한 출력(키 스트림)을 평문과 XOR하므로 평문이 알고리즘 입력으로 쓰이지 않고 오류가 전파되지 않는 동기식 스트림 암호이므로 정답이다."],"rel":["4-3"],"box":"- 평문이 블록암호 알고리즘의 입력으로 전혀 사용되지 않음\n- 평문이나 암호문의 오류가 후속 블록에 영향을 미치지 않음\n- 블록 암호를 기반으로 한 스트림 암호"},{"n":76,"s":"s4","q":"아래 함수의 용도로 가장 적절한 것은?","c":["메시지 인증","메시지 기밀성","송신자 부인 방지","서비스 거부 공격 방지"],"a":0,"e":"비밀키를 ipad(0x36 반복)·opad(0x5C 반복)와 XOR해 해시를 두 번 적용하는 구조는 HMAC(RFC 2104)으로, 무결성과 메시지 인증을 제공한다. 비밀키를 공유하는 대칭 방식이라 부인 방지는 제공하지 못하며, 해시이므로 기밀성도 제공하지 않는다.","ce":["비밀키를 ipad(0x36)·opad(0x5C)와 XOR해 해시를 두 번 적용하는 HMAC 구조로, 무결성과 메시지 인증을 제공하므로 정답이다(RFC 2104 표준은 ipad를 안쪽, opad를 바깥쪽에 둔다).","해시 함수는 입력을 복원할 수 없는 고정 길이 값만 만들 뿐 데이터를 암호화해 숨기지 않으므로 기밀성을 제공하지 않는다.","HMAC은 송·수신자가 같은 비밀키를 공유하므로 누가 만들었는지 제3자에게 증명할 수 없어 부인 방지를 제공하지 못한다.","HMAC은 메시지 인증 수단으로, 트래픽 폭주로 인한 서비스 거부 공격을 막는 기능이 없다."],"rel":["4-5"],"box":"H(key XOR 3636...36, H(key XOR 5C5C...5C, data))\n(H는 임의의 암호학적 해시 함수, key는 비밀키, 3636...36과 5C5C...5C 등은 key와 같은 길이의 16진수)"},{"n":77,"s":"s4","q":"공개키 기반구조의 구성요소에 해당하지 않는 것은?","c":["인증기관(CA)","등록기관(RA)","공개키 인증서의 소유자","비밀키 인증서와 CRL을 저장하는 저장소"],"a":3,"e":"PKI는 인증기관(CA), 등록기관(RA), 사용자(인증서 소유자), 공개키 인증서와 CRL을 공개하는 디렉터리(저장소)로 구성된다. 인증서는 공개키를 증명하는 것으로 '비밀키 인증서'는 존재하지 않는다.","ce":["인증기관(CA)은 공개키 인증서를 발급·폐지하고 CRL을 게시하는 PKI의 핵심 구성요소이다.","등록기관(RA)은 사용자 신원을 확인하고 인증서 발급 요청을 CA에 전달하는 PKI 구성요소이다.","공개키 인증서의 소유자(사용자·최종 개체)는 인증서를 이용해 서명·암호화를 수행하는 PKI 구성요소이다.","PKI 저장소(디렉터리)는 공개키 인증서와 CRL을 저장·공개한다. 인증서는 공개키를 증명하는 것으로 '비밀키 인증서'는 존재하지 않으므로 정답이다."],"rel":["4-7"]},{"n":78,"s":"s4","q":"대칭키 배송 문제를 해결할 수 있는 방법에 해당하지 않는 것은?","c":["Diffie-Hellman 키 교환 방법에 의한 해결","키 분배 센터에 의한 해결","전자서명에 의한 해결","공개키 암호에 의한 해결"],"a":2,"e":"대칭키 배송 문제는 키 사전 공유, 키 분배 센터(KDC), Diffie-Hellman 키 교환, 공개키 암호(세션키를 수신자 공개키로 암호화)로 해결한다. 전자서명은 인증·무결성·부인방지 수단이며 키를 안전하게 전달하는 기능이 없다.","ce":["Diffie-Hellman 키 교환은 공개 채널에서 이산대수 문제를 이용해 두 당사자가 같은 비밀키를 합의하므로 키 배송 문제의 해결책이다.","키 분배 센터(KDC)가 각 사용자와 공유한 마스터키로 세션키를 암호화해 나눠 주는 방식은 키 배송 문제의 해결책이다.","전자서명은 인증·무결성·부인방지를 제공하는 수단으로, 대칭키를 기밀하게 전달하는 기능이 없어 키 배송 문제 해결책이 아니므로 정답이다.","송신자가 세션키를 수신자 공개키로 암호화해 보내면 수신자만 개인키로 복호화할 수 있으므로 키 배송 문제의 해결책이다."],"rel":["4-12"]},{"n":79,"s":"s4","q":"메시지 인증 코드에서 재전송 공격을 방지하기 위한 방법과 가장 거리가 먼 것은?","c":["메시지 내부에 일방향 해시값(One-Way Hash)을 추가하여 메시지 인증코드를 생성한다.","메시지 내부에 매회 1씩 증가하는 순서번호(Sequence Number)를 추가하여 메시지 인증코드를 생성한다.","메시지 내부에 난수 형태의 일회용 Nonce 값을 추가하여 메시지 인증코드를 생성한다.","메시지 내부에 현재 시각 정보(Timestamp)를 추가하여 메시지 인증코드를 생성한다."],"a":0,"e":"재전송 공격은 매번 달라지는 순서번호, 타임스탬프, 비표(Nonce)를 MAC 계산에 포함시켜 방지한다. 일방향 해시값은 같은 메시지에 대해 항상 같은 값이 나오므로 재전송된 메시지를 구분하지 못한다.","ce":["일방향 해시값은 같은 메시지에 대해 항상 같은 값이 나오므로 재전송된 메시지를 새 메시지와 구분하지 못해 재전송 방지와 가장 거리가 멀다.","매회 1씩 증가하는 순서번호를 MAC에 포함하면 이미 받은 번호의 메시지를 재전송으로 탐지할 수 있다.","일회용 난수 Nonce를 MAC에 포함하면 같은 Nonce가 다시 오는 메시지를 재전송으로 거부할 수 있다.","현재 시각(Timestamp)을 MAC에 포함하면 허용 시간 범위를 벗어난 과거 메시지를 재전송으로 거부할 수 있다."],"rel":["4-5"]},{"n":80,"s":"s4","q":"SSL, IPSec 등 대부분의 네트워크 보안 프로토콜에서 RSA 공개키 암호를 이용하여 송신자(A)와 수신자(B) 간에 비밀 세션키를 공유하는 키분배 방식을 지원하고 있다. 이때, 송신자(A)가 수신자(B)에게 전달하는 세션키를 암호화할 때 필요로 하는 키 정보에 해당하는 것은?","c":["송신자(A)의 개인키","송신자(A)의 공개키","수신자(B)의 개인키","수신자(B)의 공개키"],"a":3,"e":"RSA 키 전송 방식에서 송신자는 세션키를 수신자(B)의 공개키로 암호화하고, 수신자만 자신의 개인키로 복호화할 수 있다. 송신자 개인키로 암호화하면 누구나 송신자 공개키로 풀 수 있어 기밀성이 없다.","ce":["송신자 개인키로 암호화하면 누구나 공개된 송신자 공개키로 복호화할 수 있어 세션키가 노출된다. 이는 서명 용도이지 키 분배 기밀성이 아니다.","송신자 공개키로 암호화하면 송신자 개인키로만 풀 수 있어 수신자 B는 세션키를 얻을 수 없다.","수신자 개인키는 B만 보유하므로 송신자 A는 이 키를 가질 수 없고, B가 복호화할 때 쓰는 키이다.","세션키를 수신자 B의 공개키로 암호화하면 B만 자신의 개인키로 복호화할 수 있어 비밀 세션키를 안전하게 공유하므로 정답이다."],"rel":["4-4","4-12"]},{"n":81,"s":"s5","q":"OECD 개인정보보호 8개 원칙 중 다음에서 설명하는 것은?","c":["수집 제한의 원칙(Collection Limitation Principle)","이용 제한의 원칙(Use Limitation Principle)","정보 정확성의 원칙(Data Quality Principle)","안전성 확보의 원칙(Security Safeguards Principle)"],"a":3,"e":"안전성 확보의 원칙은 개인정보의 분실·불법 접근·파괴·변조·공개 위험에 대해 합리적인 안전조치를 취해야 한다는 원칙이다. 수집 제한은 적법·공정한 수집, 이용 제한은 목적 외 이용 금지, 정보 정확성은 정보의 정확·완전·최신성 유지에 관한 원칙이다.","ce":["수집 제한의 원칙은 개인정보를 적법·공정한 수단으로, 필요 시 정보주체의 인지·동의를 얻어 수집해야 한다는 원칙으로 안전조치와 다르다.","이용 제한의 원칙은 정보주체 동의나 법적 근거 없이 명시된 목적 외로 이용·공개하지 않아야 한다는 원칙이다.","정보 정확성의 원칙은 이용 목적에 필요한 범위에서 개인정보를 정확·완전·최신으로 유지해야 한다는 원칙이다.","안전성 확보의 원칙은 개인정보의 분실·불법 접근·파괴·변조·공개 위험에 대해 물리적·조직적·기술적 안전조치를 확보해야 한다는 원칙이므로 정답이다."],"rel":["5-8"],"box":"개인정보 침해, 누설, 도용을 방지하기 위한 물리적·조직적·기술적인 안전조치를 확보해야 한다."},{"n":82,"s":"s5","q":"정보통신기반보호위원회의 기능에 대한 설명 중 잘못된 것은?","c":["주요정보통신기반시설의 지정 및 지정 취소","주요정보통신기반시설 보호정책의 조정","주요정보통신기반시설에 관한 보호계획의 종합·조정","주요정보통신기반시설 보호대책의 수립"],"a":3,"e":"정보통신기반 보호법상 보호대책은 주요정보통신기반시설을 관리하는 관리기관의 장이 취약점 분석·평가 결과에 따라 수립한다. 위원회는 보호정책 조정, 보호계획의 종합·조정, 기반시설 지정·취소 관련 사항 등을 심의한다(개정 여부 확인).","ce":["주요정보통신기반시설의 지정 및 지정 취소에 관한 사항은 정보통신기반보호위원회의 심의 기능에 포함된다(개정 여부 확인).","주요정보통신기반시설 보호정책의 조정은 위원회의 심의 기능이다.","주요정보통신기반시설에 관한 보호계획의 종합·조정은 위원회의 심의 기능이다.","보호대책은 기반시설을 관리하는 관리기관의 장이 취약점 분석·평가 결과에 따라 직접 수립하므로 위원회의 기능이 아니다(개정 여부 확인)."],"rel":["5-13"]},{"n":83,"s":"s5","q":"공인인증서의 폐지사유가 아닌 것은?","c":["가입자 또는 그 대리인이 공인인증서의 폐지를 신청한 경우","공인인증서의 유효기간이 경과한 경우","가입자의 전자서명생성정보가 분실·훼손 또는 도난·유출된 사실을 인지한 경우","가입자가 사위 기타 부정한 방법으로 공인인증서를 발급받은 사실을 인지한 경우"],"a":1,"e":"구 전자서명법에서 유효기간 경과는 인증서 효력이 소멸되는 사유이지 공인인증기관이 폐지하는 사유가 아니다. 가입자의 폐지 신청, 부정 발급, 전자서명생성정보의 분실·훼손·도난·유출은 폐지 사유였다. 전자서명법은 2020년 전부개정으로 공인인증서 제도가 폐지되었다(개정 여부 확인).","ce":["가입자 또는 그 대리인이 폐지를 신청한 경우는 구 전자서명법상 공인인증기관이 인증서를 폐지해야 하는 사유이다.","유효기간 경과는 인증서의 효력이 자동으로 소멸되는 사유이지 공인인증기관이 폐지하는 사유가 아니므로 정답이다(2020년 전부개정으로 공인인증서 제도 폐지, 개정 여부 확인).","가입자의 전자서명생성정보(개인키)가 분실·훼손·도난·유출된 사실을 인지한 경우는 폐지 사유이다.","가입자가 사위(속임수)나 부정한 방법으로 인증서를 발급받은 사실을 인지한 경우는 폐지 사유이다."],"rel":["5-10"]},{"n":84,"s":"s5","q":"전자서명법에서 정의된 용어에 대한 설명으로 적절하지 못한 것은?","c":["\"전자서명\"이라 함은 서명자를 확인하고 서명자가 당해 전자문서에 서명을 하였음을 나타내는데 이용하기 위하여 당해 전자문서에 첨부되거나 논리적으로 결합된 전자적 형태의 정보를 말한다.","\"전자문서\"라 함은 정보처리시스템에 의하여 전자적 형태로 작성되어 송신 또는 수신되거나 저장된 정보를 말한다.","\"전자서명 검증\"이라 함은 전자서명생성정보가 가입자에게 유일하게 속한다는 사실을 확인하고 이를 증명하는 행위를 말한다.","\"공인인증업무\"라 함은 공인인증서 발급, 인증관련 기록의 관리 등 공인인증역무를 제공하는 업무를 말한다."],"a":2,"e":"구 전자서명법에서 '전자서명생성정보가 가입자에게 유일하게 속한다는 사실을 확인하고 이를 증명하는 행위'는 '인증'의 정의이다. 전자서명 검증은 전자서명검증정보로 서명의 유효성을 확인하는 것이다(현행 전자서명법 개정 여부 확인).","ce":["구 전자서명법의 '전자서명' 정의(서명자 확인과 서명 사실 표시를 위해 전자문서에 첨부·결합된 전자적 정보)와 일치하므로 옳다.","'전자문서'는 정보처리시스템에 의해 전자적 형태로 작성·송수신·저장된 정보라는 정의로 옳다.","'전자서명생성정보가 가입자에게 유일하게 속한다는 사실을 확인·증명하는 행위'는 '인증'의 정의이다. 전자서명 검증은 검증정보로 서명의 유효성을 확인하는 것이므로 틀렸다.","'공인인증업무'는 공인인증서 발급, 인증 관련 기록 관리 등 공인인증역무를 제공하는 업무라는 당시 정의와 일치한다(현행법 개정 여부 확인)."],"rel":["5-10"]},{"n":85,"s":"s5","q":"정보보호 관리체계에 대한 설명 중 적절하지 못한 것은?","c":["정보보호 관리체계는 경영과 IT영역의 중요한 위험 관리 활동의 하나이다.","정보보호 관리체계는 정보보호에 관한 경영관리 시스템이다.","정보보호 관리체계는 기업에 있는 정보자산 보호를 목적으로 주로 기술적인 면을 고려하며, 일반적으로 정보보호 운영 또는 인적관리는 관리대상에서 배제한다.","정보보호 관리체계는 통상적으로 PDCA 사이클을 기반으로 실행된다."],"a":2,"e":"정보보호 관리체계는 기술적 대책뿐 아니라 정책·조직·인적 보안·운영 관리 등 관리적·물리적 대책을 포함하는 종합적 관리체계이다. 운영·인적 관리를 배제한다는 ③은 ISMS의 본질과 맞지 않는다.","ce":["ISMS는 경영과 IT 영역에 걸친 위험을 식별·평가·처리하는 위험 관리 활동이므로 옳은 설명이다.","ISMS는 정보보호를 경영 차원에서 계획·운영·점검·개선하는 경영관리 시스템이므로 옳다.","ISMS는 기술적 대책뿐 아니라 정책·조직·인적 보안·운영 관리 등 관리적·물리적 대책을 모두 포함하는 종합 체계이므로, 운영·인적 관리를 배제한다는 설명은 틀렸다.","ISMS는 Plan-Do-Check-Act 사이클로 지속적 개선을 수행하므로 옳다(ISO/IEC 27001 기반)."],"rel":["5-12"]},{"n":86,"s":"s5","q":"위험의 구성요소가 아닌 것은?","c":["자산","위협","취약점","정책"],"a":3,"e":"위험은 자산의 가치, 위협의 발생 가능성, 취약점의 정도의 함수로 평가된다. 정책은 위험을 관리하기 위한 통제 수단이며 위험의 구성요소가 아니다.","ce":["자산은 위험 평가의 대상으로, 자산 가치가 클수록 위험도가 커지므로 위험의 구성요소이다.","위협은 자산에 손실을 일으킬 잠재적 원인으로 발생 가능성이 위험 평가에 반영되므로 위험의 구성요소이다.","취약점은 위협이 이용할 수 있는 자산의 약점으로 위험 = f(자산, 위협, 취약점)의 구성요소이다.","정책은 위험을 줄이기 위한 관리적 통제 수단으로, 위험을 계산하는 구성요소(자산·위협·취약점)가 아니므로 정답이다."],"rel":["5-2"]},{"n":87,"s":"s5","q":"정보보호 위험의 정량적 평가방법이 아닌 것은?","c":["수학공식 접근법","과거자료 분석법","확률분포법","델파이법"],"a":3,"e":"델파이법은 전문가 집단의 의견을 반복 수렴하는 정성적 위험분석 방법이다. 수학공식 접근법, 과거자료 분석법, 확률분포법은 손실액·발생확률을 수치로 산출하는 정량적 방법이다.","ce":["수학공식 접근법은 위협 발생 빈도와 손실을 수식으로 계산하는 정량적 방법이다.","과거자료 분석법은 과거 사고 통계로 발생 확률을 수치화하는 정량적 방법이다.","확률분포법은 미지의 사건에 대해 확률분포(최저·보통·최고치)를 추정해 위험을 계산하는 정량적 방법이다.","델파이법은 전문가 집단의 의견을 설문으로 반복 수렴하는 정성적 방법이므로 정답이다."],"rel":["5-2"]},{"n":88,"s":"s5","q":"ISMS-P 인증제도에 관련된 설명으로 틀린 것은?","c":["ISMS-P에서는 관리체계 수립 및 운영, 보호대책 요구사항, 개인정보 처리단계별 요구사항의 102개 인증기준이 존재한다.","정보보호 및 개인정보보호를 위한 일련의 조치와 활동이 인증기준에 적합함을 인터넷진흥원 또는 인증기관이 증명하는 제도이다.","ISMS-P 인증기관 및 심사기관의 유효기간은 5년이며 유효기간이 끝나기 전 6개월부터 끝나는 날까지 재지정을 신청할 수 있다.","정보통신기반 보호법에 따른 주요정보통신기반시설의 취약점 분석·평가에 따른 정보보호 조치를 취한 경우 인증심사 일부를 생략할 수 있다."],"a":2,"e":"ISMS-P 인증기관·심사기관의 지정 유효기간은 3년이며, 만료 6개월 전부터 재지정을 신청할 수 있다. 인증기준 102개(관리체계 16·보호대책 64·개인정보 처리단계 22)와 기반시설 취약점 분석·평가 시 심사 일부 생략은 맞는 설명이다(개정 여부 확인).","ce":["ISMS-P 인증기준은 관리체계 수립·운영 16개, 보호대책 요구사항 64개, 개인정보 처리단계별 요구사항 22개로 총 102개였으므로 옳다(개정 여부 확인).","ISMS-P는 정보보호·개인정보보호 조치가 인증기준에 적합함을 KISA 또는 인증기관이 증명하는 제도이므로 옳다.","인증기관·심사기관의 지정 유효기간은 5년이 아니라 3년이므로 틀렸다(개정 여부 확인).","정보통신기반 보호법에 따른 주요정보통신기반시설 취약점 분석·평가로 보호조치를 한 경우 인증심사 일부를 생략할 수 있으므로 옳다."],"rel":["5-11"]},{"n":89,"s":"s5","q":"국내 정보보호 및 개인정보보호 관리체계(ISMS-P)의 관리체계 수립 및 운영 4단계 중 위험 관리 단계의 통제항목에 해당하지 않는 것은?","c":["정보자산 식별","현황 및 흐름 분석","보호대책 구현","위험 평가"],"a":2,"e":"ISMS-P 1.2 위험 관리 단계는 정보자산 식별, 현황 및 흐름분석, 위험 평가, 보호대책 선정의 4개 항목이다. 보호대책 구현은 1.3 관리체계 운영 단계의 통제항목이다.","ce":["정보자산 식별(1.2.1)은 ISMS-P 위험 관리 단계의 통제항목이다.","현황 및 흐름분석(1.2.2)은 서비스·업무·개인정보 흐름을 분석하는 위험 관리 단계의 통제항목이다.","보호대책 구현은 1.3 관리체계 운영 단계(1.3.1)의 통제항목으로, 위험 관리 단계에 속하지 않으므로 정답이다.","위험 평가(1.2.3)는 위험 관리 단계의 통제항목이다. 이 단계의 네 번째 항목은 보호대책 '선정'(1.2.4)이다."],"rel":["5-11"]},{"n":90,"s":"s5","q":"정보주체의 권리에 해당하지 않는 것은?","c":["개인정보의 처리 여부를 확인하고 개인정보에 대하여 열람을 요구할 권리","개인정보의 처리 정지, 정정·삭제 및 파기를 요구할 권리","개인정보의 처리에 관한 정보를 제공받을 권리","개인정보의 처리로 인하여 발생한 금전적 이익에 대해 배상받을 권리"],"a":3,"e":"개인정보 보호법 제4조의 정보주체 권리는 처리 정보를 제공받을 권리, 동의 여부 선택, 열람 요구, 처리 정지·정정·삭제·파기 요구, 처리로 발생한 '피해'를 신속·공정하게 구제받을 권리이다. 처리로 발생한 '금전적 이익'에 대한 배상 권리는 규정되어 있지 않다(개정 여부 확인).","ce":["처리 여부 확인과 열람(사본 발급 포함) 요구권은 개인정보 보호법 제4조의 정보주체 권리이다.","처리 정지, 정정·삭제 및 파기 요구권은 개인정보 보호법 제4조의 정보주체 권리이다.","개인정보 처리에 관한 정보를 제공받을 권리는 제4조 제1호의 정보주체 권리이다.","정보주체의 권리는 처리로 발생한 '피해'를 신속·공정하게 구제받을 권리이며, 처리로 생긴 '금전적 이익'을 배상받을 권리는 규정되어 있지 않으므로 정답이다(개정 여부 확인)."],"rel":["5-8"]},{"n":91,"s":"s5","q":"자동화된 위험분석 도구의 특징이 아닌 것은?","c":["위험분석의 일반적인 요구사항과 절차를 자동화한 도구이다.","위험분석에 소요되는 시간과 비용을 절감할 수 있다.","분석 과정에서 정확한 자료의 입력이 매우 중요하다.","수작업 시의 실수로 인한 오차를 줄일 수 있기 때문에 수작업에 비해 결과에 대한 신뢰도가 높다."],"a":1,"e":"공식 정답은 ②로, 자동화 도구도 정확한 자료 수집·입력과 도구 도입·숙련에 상당한 시간과 비용이 들어 반드시 절감된다고 볼 수 없다는 취지이다. 자동화 도구는 일반 절차를 자동화하고 입력 자료의 정확성이 결과를 좌우하며 계산 오차를 줄여준다.","ce":["자동화 도구는 위험분석의 일반 요구사항과 절차(자산·위협·취약점 입력 → 위험 계산)를 소프트웨어로 자동화한 것이므로 옳은 특징이다.","공식 정답이다. 정확한 자료 수집·입력과 도구 도입·숙련에 상당한 시간·비용이 들어 반드시 절감된다고 볼 수 없다는 취지이나, 이를 장점으로 드는 교재도 있어 논란 소지가 있다.","자동화 도구는 입력 자료로 결과를 계산하므로 부정확한 자료를 넣으면 결과도 부정확해져, 정확한 입력이 매우 중요하다는 설명은 옳다.","수작업 계산 실수를 줄여 결과 신뢰도를 높인다는 것은 자동화 도구의 장점으로 제시된다."],"rel":["5-12"],"flag":"시간·비용 절감을 자동화 도구 장점으로 보는 교재도 있어 정답 논란 소지"},{"n":92,"s":"s5","q":"정보통신기반 보호법상 '전자적 침해행위'로 규정한 공격행위에 속하지 않는 것은?","c":["고출력 전자기파","영업목적의 스팸메일","메일폭탄","컴퓨터바이러스"],"a":1,"e":"정보통신기반 보호법상 전자적 침해행위는 해킹, 컴퓨터바이러스, 논리폭탄, 메일폭탄, 서비스거부, 고출력 전자기파 등으로 주요정보통신기반시설을 공격하는 행위이다. 영업 목적의 스팸메일은 정보통신망법의 영리목적 광고성 정보 전송 규제 대상이다.","ce":["고출력 전자기파는 정보통신기반 보호법 제12조에서 전자적 침해행위 수단으로 명시되어 있다.","영업 목적의 스팸메일은 정보통신망법의 영리목적 광고성 정보 전송 규제 대상으로, 기반시설을 공격하는 전자적 침해행위에 해당하지 않으므로 정답이다.","메일폭탄은 대량 메일로 시스템을 마비시키는 공격으로 전자적 침해행위 수단으로 명시되어 있다.","컴퓨터바이러스는 해킹·논리폭탄 등과 함께 전자적 침해행위 수단으로 명시되어 있다."],"rel":["5-13"]},{"n":93,"s":"s5","q":"다음의 보기는 침해사고 등이 발생한 경우 「클라우드컴퓨팅 발전 및 이용자 보호에 관한 법률」에 따른 클라우드서비스 제공자의 의무를 설명한 것이다. 잘못 설명되어 있는 것은?","c":["클라우드컴퓨팅서비스 제공자는 이용자 정보가 유출된 때에는 즉시 그 사실을 과학기술정보통신부장관에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 사전예고 없이 대통령령으로 정하는 기간 이상 서비스 중단이 발생한 때에는 지체 없이 그 사실을 해당 과학기술정보통신부장관에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」에 따른 침해사고가 발생한 때에는 지체 없이 그 사실을 해당 이용자에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 이용자 정보가 유출된 때에는 지체 없이 그 사실을 해당 이용자에게 알려야 한다."],"a":1,"e":"클라우드컴퓨팅법 제25조에 따라 침해사고 발생, 사전예고 없는 일정 기간 이상의 서비스 중단, 이용자 정보 유출 시에는 지체 없이 '이용자'에게 알려야 하며, 이용자 정보 유출 시에는 추가로 과학기술정보통신부장관에게 즉시 알려야 한다. 서비스 중단의 통지 대상은 장관이 아니라 이용자이므로 ②가 틀렸다(개정 여부 확인).","ce":["이용자 정보가 유출된 때에는 이용자 통지와 별도로 과학기술정보통신부장관에게도 즉시 알려야 하므로 옳은 설명이다(개정 여부 확인).","사전예고 없이 일정 기간 이상 서비스가 중단된 때의 통지 대상은 과학기술정보통신부장관이 아니라 해당 '이용자'이므로 틀렸다(개정 여부 확인).","정보통신망법에 따른 침해사고가 발생한 때에는 지체 없이 해당 이용자에게 알려야 하므로 옳다.","이용자 정보가 유출된 때에는 지체 없이 해당 이용자에게 알려야 하므로 옳다."],"rel":["5-10"]},{"n":94,"s":"s5","q":"영향평가를 하는 경우에 고려해야 할 사항 중에서 가장 적합하지 않은 것은?","c":["개인정보의 제3자의 제공 여부","처리하는 개인정보의 수","정보주체의 권리를 해할 가능성 및 그 위험 정도","개인정보를 처리하는 수탁업체 관리·감독의 여부"],"a":3,"e":"개인정보 보호법 제33조는 영향평가 시 처리하는 개인정보의 수, 제3자 제공 여부, 정보주체의 권리를 해할 가능성 및 위험 정도 등을 고려하도록 규정한다. 수탁업체 관리·감독 여부는 법이 정한 영향평가 고려사항에 포함되지 않는다(개정 여부 확인).","ce":["개인정보의 제3자 제공 여부는 개인정보 보호법 제33조가 정한 영향평가 고려사항이다.","처리하는 개인정보의 수는 영향평가 고려사항이다(대량 처리일수록 위험 증가).","정보주체의 권리를 해할 가능성 및 그 위험 정도는 영향평가 고려사항이다.","수탁업체 관리·감독 여부는 위탁 시 처리자의 의무(제26조)일 뿐, 제33조의 영향평가 고려사항으로 규정되어 있지 않으므로 정답이다(개정 여부 확인)."],"rel":["5-9"]},{"n":95,"s":"s5","q":"주요정보통신기반시설 관리기관이 취약점 분석·평가를 의뢰할 수 없는 기관은?","c":["「국가정보화기본법」 제14조의 규정에 의한 한국정보화진흥원","「정보보호산업의 진흥에 관한 법률」 제23조에 따라 지정된 정보보호 전문서비스 기업","「정보통신기반보호법」 제16조의 규정에 의한 정보공유·분석센터","「정부출연연구기관 등의 설립·운영 및 육성에 관한 법률」 제8조의 규정에 의한 한국전자통신연구원"],"a":0,"e":"정보통신기반 보호법 제9조에 따라 취약점 분석·평가를 의뢰할 수 있는 기관은 한국인터넷진흥원, 정보공유·분석센터(ISAC), 정보보호 전문서비스 기업, 한국전자통신연구원이다. 한국정보화진흥원(현 한국지능정보사회진흥원)은 해당하지 않는다(개정 여부 확인).","ce":["한국정보화진흥원(현 한국지능정보사회진흥원)은 정보통신기반 보호법 제9조의 취약점 분석·평가 의뢰 가능 기관이 아니므로 정답이다(개정 여부 확인).","정보보호산업법 제23조에 따라 지정된 정보보호 전문서비스 기업은 취약점 분석·평가를 의뢰할 수 있는 기관이다.","정보통신기반 보호법 제16조의 정보공유·분석센터(ISAC)는 취약점 분석·평가를 의뢰할 수 있는 기관이다.","한국전자통신연구원(ETRI)은 취약점 분석·평가를 의뢰할 수 있는 기관으로 규정되어 있다."],"rel":["5-13"]},{"n":96,"s":"s5","q":"주 센터와 동일한 수준의 정보처리시스템을 원격지에 구축하여 Standby 상태로 유지하고, 주 센터 재해 발생 시 원격지의 시스템을 운영상태로 전환하는 유형은?","c":["미러 사이트","핫 사이트","웜 사이트","콜드 사이트"],"a":1,"e":"핫 사이트는 주 센터와 동일한 설비를 대기(Standby) 상태로 두었다가 재해 시 운영 상태로 전환한다. 미러 사이트는 동일 설비를 Active-Active로 동시 운영하고, 웜 사이트는 핵심 설비 일부만, 콜드 사이트는 장소·기반시설만 확보한다.","ce":["미러 사이트는 주 센터와 동일한 설비를 Active-Active로 실시간 동시 운영하므로, Standby로 대기하다 전환하는 방식이 아니다.","핫 사이트는 주 센터와 동일한 수준의 시스템을 원격지에 Standby 상태로 유지하다가 재해 시 운영 상태로 전환하므로 정답이다.","웜 사이트는 중요 업무용 일부 설비만 갖춘 방식으로, 주 센터와 동일한 수준의 시스템을 두지 않는다.","콜드 사이트는 공간·전원·배선 등 기반시설만 확보하고 장비는 재해 후 반입하는 방식이다."],"rel":["5-3"]},{"n":97,"s":"s5","q":"'개인정보 보호법'에서 개인정보 수집 시 그 목적에 필요한 최소한의 개인정보를 수집하여야 한다. 이 경우 최소한의 개인정보 수집에 대한 입증을 부담하는 담당자는?","c":["개인정보 담당자","개인정보 책임자","개인정보 처리자","정보주체"],"a":2,"e":"개인정보 보호법 제16조 제1항에 따라 개인정보처리자는 목적에 필요한 최소한의 개인정보를 수집해야 하며, 최소한의 개인정보라는 입증책임은 개인정보처리자가 부담한다. 정보주체는 보호 대상이며 입증책임을 지지 않는다.","ce":["'개인정보 담당자'는 법이 입증책임 주체로 정한 용어가 아니다. 제16조의 입증책임은 개인정보처리자에게 있다.","개인정보 보호책임자는 처리자가 지정하는 내부 책임자로 보호 업무를 총괄하지만, 최소 수집 입증책임의 법적 주체는 처리자이다.","개인정보 보호법 제16조 제1항에 따라 최소한의 개인정보를 수집했다는 입증책임은 개인정보처리자가 부담하므로 정답이다.","정보주체는 보호받는 대상으로, 최소 수집 여부에 대한 입증책임을 지지 않는다."],"rel":["5-8"]},{"n":98,"s":"s5","q":"위험처리 방식은?","c":["위험 수용","위험 감소","위험 회피","위험 전가"],"a":1,"e":"전자서명·암호화·공증 시스템 등 보호대책을 도입해 위험의 발생 가능성이나 영향을 낮추는 것은 위험 감소(완화)이다. 위험 회피는 해당 업무 자체를 포기하는 것이고, 위험 전가는 보험·외주로 제3자에게 넘기는 것이다.","ce":["위험 수용은 위험이 허용 수준 이하라 보고 별도 대책 없이 감수하는 것으로, 전자서명·암호화 등을 도입한 지문과 다르다.","전자서명·암호화·공증 시스템 같은 보호대책을 도입해 노출·변조·부인 위험의 발생 가능성과 영향을 낮추는 것은 위험 감소(완화)이므로 정답이다.","위험 회피는 위험이 있는 업무(고액 전자거래) 자체를 포기하거나 변경하는 것인데, 조직은 시스템 운영을 계속했다.","위험 전가는 보험 가입·외주 계약 등으로 손실 부담을 제3자에게 넘기는 것이다."],"rel":["5-2"],"box":"어떤 조직이 인터넷을 이용하여 고액의 전자거래 시스템을 운영하고자 위험 분석을 수행하였다. 위험 분석의 결과는 고액의 온라인 전송에 따른 거래 금액 노출, 변조, 거래 사실 부인의 위험이 매우 높았다. 해당 조직은 이 위험을 처리하기 위해 전자서명, 암호화, 송신자 부인방지를 위한 공증 시스템과 같은 대책을 도입하였다."},{"n":99,"s":"s5","q":"다음은 정보보호 조직의 구성원과 그 책임에 대한 설명이 옳지 않은 것은?","c":["정보보호 관리자 - 조직의 정보보호 정책 표준, 대책, 실무 절차를 설계, 구현, 관리, 조사할 책임","최고 경영자 - 정보보호를 위한 총괄 책임","데이터 관리자 - 정보시스템에 저장된 데이터의 정확성과 무결성을 유지하고 데이터 중요성 및 분류를 결정할 책임","정보보호 위원회 - 보안 목적이 적절하고 정보보호 정책, 표준, 대책, 실무 및 절차가 조직의 보안 목적에 따라 적절하게 이루어지고 있음을 독립적인 입장에서 관리자에게 보증할 책임"],"a":3,"e":"정책·절차가 적절히 이행되는지를 독립적인 입장에서 경영진에게 보증하는 것은 정보시스템 감사자(Auditor)의 책임이다. 정보보호 위원회는 정보보호 정책 승인, 자원 배분 등 주요 사항을 검토·의사결정하는 조직이다.","ce":["정보보호 관리자는 조직의 정보보호 정책 표준·대책·실무 절차를 설계·구현·관리·조사할 책임을 지므로 옳다.","최고 경영자는 조직의 정보보호에 대한 최종·총괄 책임을 지므로 옳다.","데이터 관리자(소유자)는 데이터의 정확성·무결성 유지와 중요도·분류 결정 책임을 지므로 옳다.","정책·절차가 적절히 이행되는지를 독립적으로 경영진에게 보증하는 것은 정보시스템 감사자의 책임이다. 정보보호 위원회는 정책 승인·자원 배분 등을 의사결정하는 조직이므로 틀렸다."],"rel":["5-12"]},{"n":100,"s":"s5","q":"다음의 지문은 무엇에 대한 설명인가?","c":["위험관리","업무 연속성 계획","재난 대비 가용성 확보 대책","피해 복구 대책"],"a":1,"e":"업무 연속성 계획(BCP)은 재해·재난 시 핵심 업무를 중단 없이 유지·복구해 기업 전체의 신뢰성과 가치를 지키기 위한 계획·절차이다. 재해복구계획(DRP)이 IT 시스템 복구에 초점을 둔다면 BCP는 비즈니스 전체의 연속성을 다룬다.","ce":["위험관리는 자산·위협·취약점을 분석해 위험을 허용 수준으로 줄이는 전반적 활동으로, 재해 시 사업 연속성 유지 계획 자체를 뜻하지 않는다.","업무 연속성 계획(BCP)은 재해·재난 시 핵심 시스템의 가용성을 회복하고 사업 연속성을 유지해 기업 전체의 신뢰성과 가치를 지키는 계획·절차이므로 정답이다.","재난 대비 가용성 확보 대책은 BCP의 일부 요소일 뿐, 사업 전체의 연속성과 기업 가치 유지까지 포괄하는 계획 명칭이 아니다.","피해 복구 대책(재해복구, DRP)은 IT 시스템·데이터 복구에 초점을 둔 것으로, 지문처럼 '단순한 데이터 복구를 넘어' 사업 전체 연속성을 다루는 BCP보다 범위가 좁다."],"rel":["5-3"],"box":"이것은 각종 재해 시 재난의 발생을 대비하기 위하여 핵심 시스템의 가용성과 신뢰성을 회복하고 사업의 연속성을 유지하기 위한 일련의 사업지속성 계획과 절차를 말한다. 단순한 데이터의 복구나 신뢰도를 유지하며 나아가 기업의 전체적인 신뢰성 유지와 가치를 최대화 하는 방법과 절차이다."}]},{"id":"2019-03-23","title":"2019년 3월 23일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"다음 중 주로 카메라, DVR 등 인터넷에 연결된 기기들을 감염시켜 봇넷을 만든 후 디도스(DDoS) 공격을 수행하는 악성 코드는?","c":["백오리피스(BackOrifice) 악성코드","다이어(Dyre) 악성코드","미라이(Mirai) 악성코드","워너크라이(Wannacry) 악성코드"],"a":2,"e":"미라이(Mirai)는 기본 계정·패스워드를 쓰는 IP 카메라, DVR 같은 IoT 기기를 감염시켜 봇넷을 만들고 대규모 DDoS를 일으킨 악성코드다(2016년 Dyn DNS 공격). 백오리피스는 원격 제어 트로이목마, 다이어는 금융정보 탈취 뱅킹 트로이목마, 워너크라이는 SMB 취약점을 이용한 랜섬웨어다.","ce":["백오리피스는 1998년 등장한 윈도우 원격 제어용 백도어(트로이목마)로, IoT 기기를 봇넷으로 만드는 악성코드가 아니다.","다이어(Dyre)는 브라우저를 가로채 인터넷뱅킹 계정정보를 탈취하는 금융 트로이목마로, 목적이 DDoS가 아닌 금융정보 탈취다.","미라이는 텔넷으로 기본 ID/PW를 쓰는 IP 카메라·DVR 등 IoT 기기를 감염시켜 봇넷을 구성하고 대규모 DDoS를 수행했다(2016년 Dyn DNS 공격).","워너크라이는 SMBv1 취약점(EternalBlue)으로 전파되며 파일을 암호화하고 비트코인을 요구하는 랜섬웨어로, DDoS 봇넷이 아니다."],"rel":["1-19"]},{"n":2,"s":"s1","q":"계정의 패스워드를 암호화된 형태로 저장하고 있는 파일은?","c":["/etc/security","/etc/shadow","/etc/profile","/etc/login.defs"],"a":1,"e":"/etc/shadow는 root만 읽을 수 있고 계정별 해시된 패스워드와 패스워드 만료 정보를 저장한다. /etc/profile은 로그인 셸 환경설정 파일이고, /etc/login.defs는 패스워드 정책의 기본값(최대 사용기간 등)을 정의하는 파일이다.","ce":["/etc/security는 AIX 등 일부 유닉스에서 보안 설정 파일들을 모아 두는 디렉터리 이름일 뿐, 리눅스의 표준 패스워드 저장 파일이 아니다.","/etc/shadow는 root만 읽을 수 있으며 계정별 해시(암호화)된 패스워드와 최종 변경일·만료일 등 패스워드 정보를 저장한다.","/etc/profile은 로그인 시 모든 사용자에게 적용되는 셸 환경변수(PATH 등) 설정 파일로 패스워드를 담지 않는다.","/etc/login.defs는 PASS_MAX_DAYS·PASS_MIN_LEN 등 계정·패스워드 정책의 기본값을 정의할 뿐 실제 패스워드 해시는 저장하지 않는다."],"rel":["1-6"]},{"n":3,"s":"s1","q":"Internet Explorer의 검색 히스토리는 어느 파일에 저장되는가?","c":["config.sys","command.com","index.dat","sys.bak"],"a":2,"e":"IE(버전 9 이하)는 방문 기록·쿠키·캐시 정보를 index.dat 파일에 저장하며, 포렌식에서 웹 사용 흔적 분석에 활용된다(IE 10부터는 WebCacheV01.dat). config.sys와 command.com은 DOS 시절의 시스템 설정·명령 해석기 파일이다.","ce":["config.sys는 MS-DOS·초기 윈도우에서 장치 드라이버와 메모리 설정을 지정하던 부팅 설정 파일이다.","command.com은 MS-DOS의 명령 해석기(셸) 실행 파일로 웹 방문 기록과 관계가 없다.","index.dat는 IE(9 이하)가 방문 기록(History)·쿠키·임시 인터넷 파일 목록을 저장하는 파일로 브라우저 포렌식의 주요 분석 대상이다.","sys.bak는 시스템 파일의 백업 사본을 가리키는 일반적인 이름일 뿐 IE 검색 기록 저장 파일이 아니다."],"rel":["1-18"]},{"n":4,"s":"s1","q":"ftp 접근 여부를 검토할 수 있는 로그는?","c":["utmp","sulog","wtmp","xferlog"],"a":3,"e":"xferlog는 FTP 서버의 파일 업로드·다운로드 전송 내역(접속 IP, 파일명, 방향 등)을 기록한다. utmp는 현재 로그인 사용자, wtmp는 로그인·로그아웃 이력, sulog는 su 명령 사용 기록이다.","ce":["utmp는 현재 로그인해 있는 사용자 정보를 담는 파일로 who·w 명령이 참조하며, FTP 전송 기록은 없다.","sulog는 su 명령으로 다른 계정(주로 root)으로 전환한 시도와 성공·실패를 기록한다.","wtmp는 사용자 로그인·로그아웃 이력과 시스템 재부팅 기록을 담으며 last 명령으로 조회한다. FTP 파일 전송 내용은 남지 않는다.","xferlog는 FTP 서버가 파일 업로드·다운로드마다 전송 시각, 원격 호스트, 파일명, 전송 방향 등을 기록하는 로그로 FTP 접근 검토에 쓰인다."],"rel":["1-7"]},{"n":5,"s":"s1","q":"Null Session 공유 취약점을 가지고 있는 것은?","c":["C$","Print$","IPC$","ADMIN$"],"a":2,"e":"IPC$는 프로세스 간 통신용 기본 공유로, 계정·패스워드 없이 연결하는 Null Session을 허용하면 사용자 목록·공유 정보 등이 노출될 수 있다. C$와 ADMIN$는 관리 목적의 드라이브·시스템 폴더 공유로 관리자 인증이 필요하다.","ce":["C$는 C 드라이브 루트를 관리자에게 공유하는 기본 관리 공유로, 관리자 계정 인증이 있어야 접근할 수 있다.","Print$는 원격 클라이언트에 프린터 드라이버를 배포하기 위한 공유로 Null Session 취약점의 대표 대상이 아니다.","IPC$는 명명된 파이프 등 프로세스 간 통신용 공유로, 빈 계정·빈 암호의 Null Session 연결을 허용하면 사용자·공유 목록이 열거된다.","ADMIN$는 %SystemRoot%(C:\\Windows) 폴더를 원격 관리용으로 공유하는 것이며 관리자 인증이 필요하다."],"rel":["1-17"]},{"n":6,"s":"s1","q":"root 계정과 동일한 권한을 가진 계정은?","c":["chalie 계정 uid: 0 gid: 200","sally 계정 uid: 100 gid: 0","johny 계정 uid: 10 gid: 10","sara 계정 uid: 10 gid: 200"],"a":0,"e":"유닉스 계열에서 권한은 UID로 판단하며 UID 0은 계정명과 무관하게 root(슈퍼유저) 권한을 가진다. sally처럼 GID만 0인 경우는 root 그룹 소속일 뿐 root와 동일한 권한이 아니다.","ce":["유닉스 커널은 권한을 계정명이 아닌 UID로 판단하므로 UID 0인 chalie는 이름과 관계없이 root와 동일한 슈퍼유저 권한을 가진다.","GID 0은 root 그룹 소속이라는 뜻일 뿐이며, UID가 100인 일반 사용자이므로 root와 같은 권한을 갖지 않는다.","UID 10, GID 10은 일반 시스템 계정 범위로 슈퍼유저 권한과 무관하다.","UID 10은 일반 계정이며 GID 200도 일반 그룹이므로 root 권한을 갖지 않는다."],"rel":["1-6"]},{"n":7,"s":"s1","q":"다음 지문에서 설명하는 크래킹 방법은?","c":["Rainbow Table Attack","Dictionary Attack","Brute Force Attack","Hash Attack"],"a":2,"e":"문자 범위 내에서 가능한 모든 조합을 차례로 대입하는 방식은 무차별 대입(Brute Force) 공격이다. 사전 공격은 자주 쓰이는 단어 목록만 대입하고, 레인보우 테이블은 미리 계산한 해시 체인 테이블로 해시값을 역추적한다.","ce":["레인보우 테이블 공격은 평문-해시 체인을 미리 계산해 둔 테이블로 해시값을 역추적하는 방식이며, 모든 조합을 실시간으로 대입하지 않는다.","사전 공격은 자주 쓰이는 단어·패스워드 목록(사전 파일)만 대입하므로 '범위 내 모든 조합 생성'과 다르다.","문자 범위를 정하고 가능한 모든 조합을 만들어 하나씩 대입하는 것은 무차별 대입(Brute Force) 공격의 정의다.","Hash Attack은 특정 크래킹 기법을 가리키는 표준 용어가 아니며, 해시 충돌 공격 등은 모든 조합 대입과는 다른 개념이다."],"rel":["4-1"],"box":"패스워드에 사용될 수 있는 문자열의 범위를 정하고, 그 범위 내에서 생성 가능한 모든 패스워드를 생성하며 이를 하나씩 대입, 패스워드 일치 여부를 확인한다."},{"n":8,"s":"s1","q":"리눅스 서버 관리자 A씨는 피해 시스템을 점검하던 중 다음과 같은 시스템 바이너리 파일들이 변조된 것을 확인하였다. 공격자의 입장에서 파일을 변조한 이유가 잘못 연결된 것은?","c":["ps, top: 특정 프로세스 정보를 숨김","ls, du: 특정 파일이나 디렉터리를 숨김","w, who: 특정 사용자의 정보를 숨김","ifconfig: 특정 IP에서의 접속을 숨김"],"a":3,"e":"루트킷은 ifconfig를 변조해 네트워크 인터페이스의 promiscuous(스니핑) 모드 설정을 숨긴다. 특정 IP에서의 접속을 숨기는 것은 netstat 등의 변조 목적이다. ps·top은 프로세스, ls·du는 파일, w·who는 로그인 사용자 은닉에 사용된다.","ce":["루트킷은 ps·top을 변조해 공격자의 백도어·스니퍼 프로세스를 목록에서 숨기므로 올바른 연결이다.","ls·du를 변조하면 공격 도구가 든 파일·디렉터리가 목록과 용량 계산에서 빠져 은닉되므로 올바른 연결이다.","w·who는 로그인 사용자 목록을 보여주므로 이를 변조해 공격자 계정의 로그인 사실을 숨긴다. 올바른 연결이다.","ifconfig 변조 목적은 스니퍼 동작 시 켜지는 인터페이스의 PROMISC(무차별) 모드 표시를 숨기는 것이다. 특정 IP의 접속 은닉은 netstat 변조 목적이다."],"rel":["1-9"]},{"n":9,"s":"s1","q":"소유자에게만 읽기와 쓰기 권한이 있는 경우는?","c":["rwxr--r-- 1 root root 312 Nov 30 13:05 listner.ora","r-xrw-r-- 1 root root 312 Nov 30 13:05 listner.ora","rwxrw-rw- 1 root root 312 Nov 30 13:05 listner.ora","rwxr—rw- 1 root root 312 Nov 30 13:05 listner.ora"],"a":0,"e":"rwxr--r--는 소유자만 쓰기(w) 권한을 가지고 그룹·기타 사용자는 읽기만 가능하다. ②③④는 그룹 또는 기타 사용자에게도 쓰기(w) 권한이 부여되어 있어 소유자 전용 쓰기가 아니다.","ce":["rwxr--r--는 소유자만 rw(쓰기 포함)를 갖고 그룹·기타는 r만 가지므로, 보기 중 소유자에게만 읽기·쓰기가 허용된 경우다.","r-xrw-r--는 소유자에게 쓰기(w)가 없고 오히려 그룹에 rw가 있어 조건과 반대다.","rwxrw-rw-는 그룹과 기타 사용자 모두에게 쓰기(w)가 있어 소유자 전용이 아니다.","rwxr--rw-(원문 표기 rwxr—rw-)는 기타 사용자에게 쓰기(w) 권한이 있어 소유자 전용 쓰기가 아니다."],"rel":["1-4"]},{"n":10,"s":"s1","q":"다음 빈 칸에 들어갈 서비스명으로 적절한 것은?","c":["RPC","SSHD","Bluetooth","NFS"],"a":0,"e":"RPC(Remote Procedure Call)는 원격 컴퓨터의 프로시저를 로컬 함수처럼 호출하게 해주는 프로토콜이며, XML-RPC는 이를 XML 인코딩과 HTTP로 구현한 방식이다. NFS는 RPC를 기반으로 동작하는 네트워크 파일 공유 서비스일 뿐 호출 방식 자체는 아니다.","ce":["RPC는 원격 프로시저를 로컬 함수처럼 호출하게 해 주는 프로세스 간 통신 프로토콜이며, XML-RPC는 매개변수·반환값을 XML로 인코딩해 HTTP로 전달한다.","SSHD는 SSH 원격 접속 서버 데몬으로 암호화된 원격 셸을 제공할 뿐 원격 프로시저 호출 방식이 아니다.","Bluetooth는 근거리 무선 통신 규격으로 원격 함수 호출 프로토콜과 무관하다.","NFS는 RPC 위에서 동작하는 네트워크 파일 공유 서비스로, RPC를 이용하는 쪽이지 호출 방식 자체가 아니며 'XML-NFS'라는 것도 없다."],"rel":["1-16"],"box":"( ㉠ ) 서비스는 별도의 원격 제어를 위한 코딩 없이 다른 주소 공간에서 함수나 프로시저를 실행할 수 있게 해주는 프로세스 간 프로토콜로써 어떤 프로그램이 네트워크상의 다른 컴퓨터에서 작동하는 프로그램에 서비스를 요청하는 데 사용되는 프로토콜이다.\nXML( ㉠ )라는 서비스는 XML 기반의 분산시스템 통신방법으로, ( ㉠ ) 호출에 대해 XML 형태로 매개변수나 리턴값을 반환하는 방식이다."},{"n":11,"s":"s1","q":"다음 지문에서 설명은?","c":["FAT16","FAT32","NTFS","EXT"],"a":3,"e":"EXT(Extended File System)는 리눅스 초기 파일시스템으로 MINIX 파일시스템의 한계(작은 파일시스템·파일명 크기)를 보완해 2GB 파일시스템과 255바이트 파일명을 지원했지만 타임스탬프 분리·단편화 문제가 있어 ext2로 대체되었다. FAT16·FAT32·NTFS는 마이크로소프트 파일시스템이다.","ce":["FAT16은 MS-DOS·초기 윈도우용 파일시스템으로 8.3 파일명을 기본으로 하며 MINIX를 보완한 리눅스 파일시스템이 아니다.","FAT32는 윈도우 95 OSR2부터 쓰인 파일시스템으로 단일 파일 4GB 제한이 특징이며 MINIX와 관계없다.","NTFS는 ACL 기반 접근제어·저널링을 지원하는 윈도우 파일시스템이어서 '접근제어 불가'라는 설명과 정반대다.","EXT는 MINIX 파일시스템의 한계를 보완한 최초의 리눅스 전용 파일시스템으로 최대 2GB·255바이트 파일명을 지원했으나 타임스탬프 분리가 없고 단편화가 심해 ext2로 대체되었다."],"rel":["1-18"],"box":"- MINIX File System을 보완하며, 최대 2G까지 파일시스템 크기를 지원한다.\n- 255byte까지 파일명을 지원한다.\n- 접근제어, inode 수정, 타임스탬프 수정 등의 기능이 불가능하다.\n- 사용할수록 단편화가 심해진다."},{"n":12,"s":"s1","q":"다음 중 윈도우 로그 종류와 설명이 가장 바르게 짝지어진 것은?","c":["계정 관리 감사 - 사용자 권한 할당 정책, 감사 정책, 신뢰 정책의 변경과 관련된 사항을 로깅한다.","정책 변경 감사 - 권한 설정 변경이나 관리자 권한이 필요한 작업을 수행할 때 로깅한다.","개체 액세스 감사 - 특정 파일이나 디렉터리, 레지스트리 키 등과 같은 객체에 대한 접근을 시도하거나 속성 변경 등을 탐지한다.","로그인 이벤트 감사 - 시스템의 시작과 종료, 보안 로그 삭제 등 시스템의 주요한 사항에 대한 이벤트를 남긴다."],"a":2,"e":"개체 액세스 감사는 SACL이 설정된 파일·폴더·레지스트리 키 등에 대한 접근 시도를 기록한다. ①은 정책 변경 감사, ②는 권한 사용 감사, ④는 시스템 이벤트 감사에 대한 설명으로 명칭과 설명이 서로 바뀌어 있다.","ce":["사용자 권한 할당·감사 정책·신뢰 정책 변경을 기록하는 것은 '정책 변경 감사'이다. 계정 관리 감사는 계정 생성·변경·삭제, 암호 설정 등을 기록한다.","권한 설정 변경이나 관리자 권한이 필요한 작업 수행을 기록하는 것은 '권한 사용 감사'이다. 정책 변경 감사와 설명이 바뀌어 있다.","개체 액세스 감사는 SACL이 설정된 파일·폴더·레지스트리 키·프린터 등 개체에 대한 접근 시도와 속성 변경을 기록하므로 올바른 짝이다.","시스템 시작·종료, 보안 로그 삭제 등은 '시스템 이벤트 감사' 대상이다. 로그인 이벤트 감사는 로컬 컴퓨터의 로그온·로그오프 시도를 기록한다."],"rel":["1-17"]},{"n":13,"s":"s1","q":"tcpwrapper의 설정파일의 내용이 다음과 같을 때, 어떤 현상이 발생하는가?","c":["모든 접속이 허용된다.","모든 접속이 차단된다.","일부 서비스는 모두 허용되고 일부 서비스는 모두 차단된다.","알 수 없다."],"a":0,"e":"TCP Wrapper는 hosts.allow를 먼저 검사하고 일치하면 즉시 허용하며, 일치하지 않을 때만 hosts.deny를 검사한다. hosts.allow에 ALL:ALL이 있으므로 모든 접속이 허용되고 hosts.deny는 적용되지 않는다.","ce":["TCP Wrapper는 hosts.allow를 먼저 검사해 일치하면 즉시 허용하고 hosts.deny는 보지 않는다. hosts.allow가 ALL:ALL이므로 모든 접속이 허용된다.","hosts.deny의 ALL:ALL은 hosts.allow에 일치하지 않은 요청에만 적용된다. 모든 요청이 hosts.allow에서 먼저 허용되므로 차단되는 접속은 없다.","두 파일 모두 서비스와 호스트를 ALL로 지정해 서비스별 차이가 생기지 않으므로 일부만 허용·차단되는 상황은 나오지 않는다.","TCP Wrapper의 평가 순서(allow 우선 → deny → 기본 허용)가 정해져 있어 결과를 정확히 알 수 있다."],"rel":["1-16"],"box":"/etc/hosts.deny\nAll: All\n/etc/hosts.allow\nAll: All"},{"n":14,"s":"s1","q":"wtmp 로그 파일에 대한 설명 중 옳지 않은 것은?","c":["사용자의 로그인 및 로그아웃 정보 포함","로그인 실패 정보 포함","바이너리 형태로 저장","시스템 종료 및 부팅 정보 포함"],"a":1,"e":"wtmp는 로그인·로그아웃 이력과 시스템 부팅·종료(reboot/shutdown) 기록을 바이너리로 저장하며 last 명령으로 확인한다. 로그인 실패 정보는 btmp(lastb 명령)에 기록된다.","ce":["wtmp는 사용자별 로그인·로그아웃 시각과 접속 터미널·호스트를 누적 기록하므로 옳은 설명이다.","로그인 실패 정보는 wtmp가 아니라 btmp에 기록되며 lastb 명령으로 확인한다.","wtmp는 텍스트가 아닌 바이너리 구조체로 저장되어 cat 대신 last 명령으로 읽어야 하므로 옳다.","wtmp에는 reboot·shutdown 가상 사용자 항목으로 시스템 부팅·종료 기록도 남아 last reboot로 조회할 수 있어 옳다."],"rel":["1-7"]},{"n":15,"s":"s1","q":"다음 지문에서 설명하고 있는 것은?","c":["sudo","PAM","Shell script","Batch file"],"a":1,"e":"PAM(Pluggable Authentication Modules)은 인증 기능을 모듈화한 공유 라이브러리로, /etc/pam.d 설정만 바꿔 응용프로그램 재컴파일 없이 인증 방식을 변경할 수 있다. sudo는 다른 사용자(주로 root) 권한으로 명령을 실행하게 해주는 도구다.","ce":["sudo는 /etc/sudoers에 허용된 사용자가 다른 사용자(주로 root) 권한으로 명령을 실행하게 해 주는 도구로, 인증 방식을 교체하는 라이브러리 묶음이 아니다.","PAM(Pluggable Authentication Modules)은 인증 기능을 모듈형 공유 라이브러리로 분리해 /etc/pam.d 설정만 바꾸면 응용프로그램 재컴파일 없이 인증 방법을 변경할 수 있다.","셸 스크립트는 셸 명령을 모아 자동 실행하는 텍스트 파일로 인증 모듈 프레임워크가 아니다.","Batch file(.bat)은 윈도우 명령 프롬프트용 명령 모음 파일이며 리눅스 인증 체계와 관계없다."],"rel":["1-16","1-6"],"box":"리눅스에서 시스템 관리자가 응용프로그램들이 사용자를 인증하는 방법을 선택할 수 있도록 해주는 공유라이브러리 묶음으로 이것을 사용하는 응용프로그램을 재컴파일 하지 않고, 인증방법을 변경할 수 있다."},{"n":16,"s":"s1","q":"리눅스 운영체제 특수 권한에 대한 설명으로 틀린 것은?","c":["SetGID가 부여된 파일은 소유 그룹의 실행 권한이 x에서 s로 변경","SetUID가 부여된 파일은 소유자의 실행 권한이 x에서 s로 변경","Sticky bit가 부여된 디렉터리는 그 외 사용자의 실행 권한이 x에서 s로 변경","Sticky bit는 /tmp와 같은 777 권한의 공용 디렉터리에서 파일 삭제 문제를 해결"],"a":2,"e":"Sticky bit가 설정되면 기타 사용자의 실행 권한 x가 s가 아닌 t로 표시된다(예: drwxrwxrwt). s 표시는 SetUID(소유자 자리)와 SetGID(그룹 자리)에 해당한다.","ce":["SetGID(2000)를 설정하면 그룹 실행 자리의 x가 s로 표시되므로(실행 권한이 없으면 S) 옳은 설명이다.","SetUID(4000)를 설정하면 소유자 실행 자리의 x가 s로 표시되므로 옳은 설명이다.","Sticky bit(1000)를 설정하면 기타 사용자 실행 자리의 x가 s가 아닌 t로 바뀐다(예: drwxrwxrwt). s는 SetUID·SetGID의 표시다.","Sticky bit가 걸린 /tmp 같은 777 공용 디렉터리에서는 파일 소유자(또는 root)만 해당 파일을 삭제·이름변경할 수 있어 남의 파일 삭제 문제가 해결되므로 옳다."],"rel":["1-5"]},{"n":17,"s":"s1","q":"각 파일확장자에 대한 정보와 관련 응용프로그램 간의 연결에 대한 정보를 포함하고 있는 윈도우 레지스트리 키는?","c":["HKEY_CLASSES_ROOT","HKEY_LOCAL_MACHINE","HKEY_CURRENT_CONFIG","HKEY_USERS"],"a":0,"e":"HKEY_CLASSES_ROOT(HKCR)는 파일 확장자와 연결 프로그램, COM 객체 등록 정보를 담는다. HKLM은 시스템 전체 하드웨어·소프트웨어 설정, HKCC는 현재 하드웨어 프로필, HKU는 모든 사용자 프로필 정보를 담는다.","ce":["HKEY_CLASSES_ROOT는 파일 확장자와 연결 프로그램(ProgID), COM 클래스 등록 정보를 담아 '더블클릭 시 어떤 프로그램으로 열지'를 결정한다.","HKEY_LOCAL_MACHINE은 하드웨어·드라이버·설치 소프트웨어 등 컴퓨터 전체 설정을 담는다. HKCR은 HKLM\\Software\\Classes 등을 병합해 보여 주는 것일 뿐, 문제의 대표 키는 HKCR이다.","HKEY_CURRENT_CONFIG는 시스템이 현재 사용하는 하드웨어 프로필 정보를 담는 키다.","HKEY_USERS는 컴퓨터에 로드된 모든 사용자 프로필(SID별)의 설정을 담는 키다."],"rel":["1-3"]},{"n":18,"s":"s1","q":"다음 지문에서 설명하는 것은?","c":["wireshark","tripwire","snort","iptables"],"a":2,"e":"Snort는 룰(시그니처) 기반의 오픈소스 경량 네트워크 IDS로 실시간 트래픽 분석과 패킷 로깅을 수행한다. Wireshark는 패킷 분석기, Tripwire는 파일 무결성 점검 도구, iptables는 리눅스 패킷 필터링 방화벽이다.","ce":["Wireshark는 패킷을 캡처해 GUI로 프로토콜을 분석하는 도구로, 룰 기반 탐지·경보를 하는 침입탐지시스템이 아니다.","Tripwire는 파일의 해시 기준값을 저장해 두고 변조 여부를 점검하는 호스트 기반 무결성 검사 도구다.","Snort는 룰(시그니처) 기반의 경량 오픈소스 NIDS로 실시간 트래픽 분석, 패킷 로깅, 프로토콜 분석·내용 매칭으로 스캔·오버플로우 등 공격을 탐지한다.","iptables는 리눅스 커널 netfilter를 제어하는 패킷 필터링 방화벽 도구로 탐지보다 허용·차단 정책 적용이 목적이다."],"rel":["2-11","2-9"],"box":"이것은 실시간 트래픽 분석과 IP 네트워크상에서 패킷 로깅이 가능한 가벼운(Lightweight) 네트워크 침입탐지시스템이다. 또한 프로토콜 분석, 내용 검색/매칭을 수행할 수 있으며, 오버플로우, Stealth 포트스캔, CGI 공격, SMB 탐색, OS 확인 시도 등의 다양한 공격과 스캔을 탐지할 수 있다."},{"n":19,"s":"s1","q":"빈칸 ㉠, ㉡에 들어갈 용어를 바르게 짝지은 것은?","c":["㉠ Web Shell ㉡ Fuzzing","㉠ Spear Phishing ㉡ Fuzzing","㉠ File Upload ㉡ Exploit","㉠ Drive By Download ㉡ Exploit"],"a":3,"e":"사용자가 웹 페이지에 접속하기만 해도 브라우저·플러그인 취약점을 공격하는 익스플로잇(Exploit) 코드가 실행되어 악성코드가 설치되는 기법이 드라이브 바이 다운로드다. 웹셸은 서버에 업로드된 원격 제어 스크립트, 퍼징은 취약점을 찾기 위한 비정상 입력 테스트 기법이다.","ce":["웹셸은 서버에 업로드해 원격 명령을 실행하는 스크립트이고, 퍼징은 취약점 발견을 위한 무작위 입력 테스트 기법이라 두 빈칸 모두 맞지 않는다.","스피어 피싱은 특정 대상을 노린 맞춤형 이메일 공격으로 '접속만으로 감염'되는 기법이 아니며, ㉡의 퍼징도 공격 코드가 아니다.","파일 업로드는 서버에 악성 파일을 올리는 서버 측 취약점 공격이다. ㉡ Exploit은 맞지만 ㉠이 사용자 PC 감염 기법이 아니다.","드라이브 바이 다운로드는 변조된 웹페이지에 숨긴 익스플로잇(Exploit) 코드가 브라우저·플러그인 취약점을 공격해 방문만으로 악성코드를 설치하는 기법이다."],"rel":["1-19"],"box":"( ㉠ ) 공격 기법이란 해커가 홈페이지를 해킹한 후, 취약점에 따른 ( ㉡ ) 코드가 있는 악성 스크립트를 은닉시키고 취약한 PC 환경의 이용자가 접속할 경우 악성코드가 다운로드 되는 공격 기법으로, 사용자의 개입 없이 접속만으로도 악성코드에 감염될 수 있다."},{"n":20,"s":"s1","q":"UNIX 또는 리눅스 시스템에서 똑같은 작업을 사용자가 지정된 시간에 반복 작업하기 위해서 cron 테이블을 작성한다. 사용자가 매주 토요일 오전 10시 정각에 'mytest' 라는 프로그램을 주기적으로 수행시키기 위해 작성한 cron 테이블 내용으로 맞는 것은?","c":["0 10 6 * * mytest","0 10 * * 6 mytest","0 10 * 6 * mytest","0 * * 10 6 mytest"],"a":1,"e":"crontab 필드 순서는 분·시·일·월·요일·명령이며 요일은 0(일)~6(토)이다. 따라서 매주 토요일 10시 0분은 '0 10 * * 6'이다. ①은 매월 6일, ③은 6월 매일 10시에 실행된다.","ce":["'0 10 6 * *'은 세 번째 필드(일)가 6이므로 매월 6일 10시 0분에 실행되어 매주 토요일과 다르다.","crontab 필드는 분·시·일·월·요일 순이고 요일 6은 토요일이므로 '0 10 * * 6'이 매주 토요일 10시 정각이다.","'0 10 * 6 *'은 네 번째 필드(월)가 6이므로 6월 한 달 동안 매일 10시에 실행된다.","'0 * * 10 6'은 시 필드가 *이고 월이 10이므로 10월의 토요일마다 매시 정각에 실행된다."],"rel":["1-16"]},{"n":21,"s":"s2","q":"다음 지문에서 설명하고 있는 보안 기술은?","c":["DRM","DLP","IPS","Firewall"],"a":1,"e":"DLP(Data Loss Prevention)는 중요 데이터를 식별하고 매체·네트워크·출력 등 유출 경로를 통제해 내부 정보유출을 방지하는 솔루션이다. DRM은 문서 자체를 암호화해 사용 권한을 통제하는 기술이고, IPS는 네트워크 침입을 실시간 차단하는 시스템이다.","ce":["DRM은 문서 자체를 암호화하고 열람·편집·출력 권한을 통제하는 기술로, 매체·통신 경로 제어가 핵심인 지문과 방식이 다르다.","DLP는 중요 데이터를 식별하고 USB 등 매체와 블루투스·메일 등 통신 경로를 통제해 내부 정보유출을 막는 솔루션이다.","IPS는 네트워크 트래픽에서 공격을 탐지해 실시간 차단하는 시스템으로 외부 침입 방어가 목적이다.","방화벽은 IP·포트 기반으로 네트워크 접근을 허용·차단할 뿐, 문서 내용을 식별해 매체 유출을 막지 않는다."],"rel":["1-11"],"box":"이 기술은 정보유출 사고들이 증가함에 따라 내부의 모든 문서의 중요한 자료에 대한 정보유출을 방지하기 위한 기술로, 매체제어(USB, 하드디스크 등), 통신규격 제어(블루투스, LTE 등)를 통해 기밀 자료가 유출되는 것을 막는 솔루션이다."},{"n":22,"s":"s2","q":"DDoS(Distributed Denial of Service) 공격에 대한 공격유형을 파악하려고 한다. 이때 유입 트래픽을 확보하기 위해 사용될 수 있는 도구로는?","c":["argus","ngrep","tcpdstat","tcpdump"],"a":3,"e":"tcpdump는 네트워크 인터페이스의 패킷을 캡처해 pcap 파일로 저장할 수 있어 DDoS 유입 트래픽 확보에 쓰인다. tcpdstat는 확보된 pcap 파일의 프로토콜별 통계를 내는 분석 도구이고, ngrep은 패킷 내용에서 문자열 패턴을 검색하는 도구다.","ce":["Argus는 네트워크 흐름(flow) 단위 통계를 생성·감사하는 도구로, 원시 패킷을 그대로 확보하는 용도가 아니다.","ngrep은 패킷 페이로드에서 문자열·정규식을 grep처럼 검색하는 분석 도구로 트래픽 확보보다 특정 패턴 확인에 쓰인다.","tcpdstat는 이미 저장된 pcap 파일의 프로토콜별 분포·통계를 산출하는 분석 도구로, 트래픽 확보 이후 단계에 쓰인다.","tcpdump는 인터페이스에서 패킷을 캡처해 pcap으로 저장(-w)할 수 있어 DDoS 유입 트래픽 확보 단계에 사용된다."],"rel":["2-3"]},{"n":23,"s":"s2","q":"NAC의 주요 기능으로 옳지 않은 것은?","c":["PC 및 네트워크 장치 통제","접근제어 및 인증","폭탄 메일이나 스팸 메일 차단","해킹, 웜, 유해 트래픽 탐지 및 차단"],"a":2,"e":"NAC(Network Access Control)는 네트워크 접속 단말을 인증하고 보안 정책 준수 여부를 점검해 접근을 통제하며, 유해 트래픽 단말을 격리한다. 폭탄·스팸 메일 차단은 스팸 차단 솔루션(메일 보안 게이트웨이)의 기능이다.","ce":["NAC는 네트워크에 접속하는 PC·장치를 식별하고 정책에 따라 접속을 허용·격리하므로 주요 기능에 해당한다.","NAC는 802.1X 등으로 사용자·단말을 인증하고 네트워크 접근을 통제하는 것이 핵심 기능이다.","폭탄·스팸 메일 차단은 메일 보안 게이트웨이(스팸 차단 솔루션)의 기능으로 NAC의 주요 기능이 아니다.","NAC는 웜 감염·유해 트래픽을 발생시키는 단말을 탐지해 격리·차단하는 기능도 수행하므로 해당한다."],"rel":["2-10","1-11"]},{"n":24,"s":"s2","q":"스머프 공격에서 echo request 패킷을 수신 서브넷 전체에 전달하기 위해 라우터의 해당 인터페이스에서 활성화해야 하는 것은?","c":["ip direct broadcast","ICMP Redirect","ARP Spoofing","Switch Jamming"],"a":0,"e":"스머프 공격은 출발지를 피해자로 위조한 ICMP echo request를 브로드캐스트 주소로 보내는데, 라우터가 directed broadcast를 허용해야 해당 서브넷 전체로 전달된다. 따라서 대응책은 라우터에서 no ip directed-broadcast를 설정하는 것이다.","ce":["라우터가 ip directed-broadcast를 허용하면 외부에서 온 브로드캐스트 목적지 패킷이 서브넷 전체로 전달되어 스머프 증폭이 일어난다(대책: no ip directed-broadcast).","ICMP Redirect는 라우터가 호스트에 더 나은 경로를 알려 주는 메시지로, 경로 조작 공격에 악용되지만 브로드캐스트 전달과 무관하다.","ARP 스푸핑은 IP-MAC 대응을 위조해 같은 LAN 트래픽을 가로채는 공격으로 라우터 인터페이스 설정 항목이 아니다.","스위치 재밍은 위조 MAC으로 스위치 MAC 테이블을 넘치게 해 허브처럼 동작하게 만드는 공격이며 스머프와 무관하다."],"rel":["2-3","2-12"]},{"n":25,"s":"s2","q":"다음 중 침입탐지시스템 및 침입방지시스템에 대한 설명으로 틀린 것은?","c":["침입탐지시스템에서 문자열을 비교하여 네트워크 패킷을 검사하는 방법은 Signature-based Detection의 일종이다.","Anomaly Detection은 정상 행위를 규정하여 공격을 탐지하는 방법이다.","알려지지 않은 공격을 Signature-based Detection 방법으로 탐지할 수 있다.","침입탐지시스템은 침입자에게 시스템이나 네트워크를 사용하지 못하게 하는 등 능동적인 기능을 수행할 수 있다."],"a":2,"e":"시그니처(오용) 기반 탐지는 알려진 공격 패턴과 비교하므로 새로운(Zero-day) 공격은 탐지하기 어렵다. 알려지지 않은 공격 탐지에는 정상 행위 프로파일과의 편차를 보는 이상(Anomaly) 탐지가 유리하다.","ce":["패킷 내용을 알려진 공격 문자열(패턴)과 비교하는 방식은 시그니처(오용) 기반 탐지의 전형이므로 옳다.","이상(Anomaly) 탐지는 정상 행위 프로파일을 정의하고 여기서 벗어난 행위를 공격으로 판단하므로 옳다.","시그니처 기반 탐지는 이미 알려진 공격 패턴만 비교하므로 제로데이 같은 알려지지 않은 공격은 탐지하기 어렵다. 이는 이상 탐지의 장점이다.","IDS도 탐지 후 TCP RST 전송이나 방화벽 연동 차단 같은 능동적 대응(Active Response)을 할 수 있어 옳은 설명으로 본다."],"rel":["2-9"]},{"n":26,"s":"s2","q":"다음 중 방화벽의 기능과 가장 거리가 먼 것은?","c":["접근제어","데이터 필터링과 축약","로깅과 감사추적","인증"],"a":1,"e":"방화벽의 주요 기능은 접근제어(ACL), 사용자 인증, 로깅·감사추적, 주소변환(NAT) 등이다. 패킷 필터링은 접근제어의 수단이지만 '데이터 축약'은 방화벽 기능이 아니어서, 보기 중 방화벽 기능과 가장 거리가 먼 것은 '데이터 필터링과 축약'이다.","ce":["접근제어는 IP·포트·프로토콜 규칙(ACL)으로 통과시킬 트래픽을 허용·거부하는 방화벽의 핵심 기능이다.","방화벽은 패킷 필터링은 하지만 '데이터 축약(압축·요약)'은 방화벽 기능이 아니므로, 이 묶음 표현이 방화벽 기능과 가장 거리가 멀다.","방화벽은 허용·차단된 연결을 로그로 남겨 사후 추적과 감사 증적을 제공하므로 주요 기능에 해당한다.","프록시·애플리케이션 게이트웨이형 방화벽은 사용자 인증 후 통과를 허용하는 인증 기능을 제공한다."],"rel":["2-9"]},{"n":27,"s":"s2","q":"다음 빈칸 ㉠에 들어갈 알맞은 용어는?","c":["PLC","SCADA","Modbus","Stuxnet"],"a":1,"e":"SCADA(Supervisory Control And Data Acquisition)는 원격지 설비의 데이터를 수집하고 공정을 감시·제어하는 중앙 집중형 산업제어시스템이다. PLC는 현장 설비를 직접 제어하는 컨트롤러, Modbus는 산업용 통신 프로토콜, Stuxnet은 SCADA/PLC를 공격한 악성코드다.","ce":["PLC(Programmable Logic Controller)는 현장의 모터·밸브 등 설비를 직접 제어하는 장치로, 공정 전체를 감시·제어하는 상위 시스템은 아니다.","SCADA는 원격 단말(RTU·PLC)에서 데이터를 수집하고 전력·수도 등 기반시설 공정을 중앙에서 감시·제어하는 컴퓨터 시스템이다.","Modbus는 PLC·센서 간 데이터를 주고받는 산업용 통신 프로토콜로 인증·암호화가 없다는 약점이 있으나 시스템 자체를 가리키지 않는다.","Stuxnet은 2010년 이란 원심분리기를 제어하던 지멘스 SCADA/PLC를 공격한 웜으로, 제어시스템이 아니라 공격 도구다."],"rel":["2-13"],"box":"( ㉠ )는/(은) 산업제어시스템(Industrial Control System)에 대한 공정, 기반 시설, 설비를 바탕으로 한 작업공정을 감시하고 제어하는 컴퓨터 시스템으로, 최근 이를 대상으로 이루어진 사이버 공격으로 인해 전력공급체계 등 사회기반시설 운영에 피해가 발생하고 있다."},{"n":28,"s":"s2","q":"다음 보기 중 서비스 이름과 잘 알려진 포트(well-known port) 번호가 잘못된 것은?","c":["IMAP - 134","HTTPS - 443","SMTP - 25","FTP - 20, 21"],"a":0,"e":"IMAP의 잘 알려진 포트는 143번(IMAPS는 993번)이다. HTTPS 443, SMTP 25, FTP 20(데이터)·21(제어)은 올바르다.","ce":["IMAP의 잘 알려진 포트는 143번이며(IMAPS 993번) 134번은 틀리다.","HTTPS는 TLS 위의 HTTP로 443번 포트를 사용하므로 올바른 짝이다.","SMTP는 메일 서버 간 전송에 25번 포트를 사용하므로 올바르다(제출용 587, SMTPS 465).","FTP는 21번을 제어 연결, 20번을 Active 모드 데이터 연결에 사용하므로 올바르다."],"rel":["2-1"]},{"n":29,"s":"s2","q":"다음 괄호에 들어갈 내용으로 올바르게 순서대로 나열한 것은?","c":["㉠ UDP ㉡ 67 ㉢ 68","㉠ TCP ㉡ 67 ㉢ 68","㉠ TCP ㉡ 68 ㉢ 67","㉠ UDP ㉡ 68 ㉢ 67"],"a":0,"e":"DHCP는 IP가 없는 클라이언트가 브로드캐스트로 요청해야 하므로 UDP를 사용하며, 서버는 67번, 클라이언트는 68번 포트를 사용한다(BOOTP와 동일).","ce":["DHCP는 IP 주소가 없는 클라이언트가 브로드캐스트로 요청해야 하므로 연결 설정이 없는 UDP를 쓰며, 서버 67번·클라이언트 68번 포트를 사용한다.","TCP는 연결 설정(3-way handshake)에 양쪽 IP가 필요해 주소가 없는 클라이언트가 쓸 수 없다. 포트 번호는 맞지만 전송계층이 틀렸다.","전송계층을 TCP로 잘못 적었고 서버(67)·클라이언트(68) 포트도 서로 뒤바뀌었다.","UDP는 맞지만 서버 68·클라이언트 67로 포트가 뒤바뀌었다. BOOTP 규약상 서버가 67, 클라이언트가 68이다."],"rel":["2-1","3-7"],"box":"DHCP에서는 전송계층으로 ( ㉠ ) 프로토콜을 사용하는데, 서버는 잘 알려진 ( ㉡ ) 포트를 사용하고, 클라이언트는 잘 알려진 ( ㉢ ) 포트를 사용한다."},{"n":30,"s":"s2","q":"DDoS 공격을 인지하기 위해 사용하는 방법으로 부적절한 것은?","c":["방화벽, IDS 등에서 유입 트래픽 크기를 조사한다.","동시 접속정보에 대하여 평시 대비 증감율을 비교한다.","웹서버 접속로그를 확인하여 비정상 접속 증가여부를 확인한다.","서버에서 유출되는 트래픽을 샘플링하여, 실제 트래픽을 분석한다."],"a":3,"e":"DDoS 인지는 유입(인바운드) 트래픽의 양, 동시 접속 수 증감, 웹 접속 로그의 비정상 증가 등을 평시와 비교해 판단한다. 서버에서 유출되는 트래픽을 샘플링하는 것은 공격 유형 분석 단계에 해당하며 공격 인지 방법으로는 부적절하다.","ce":["방화벽·IDS에서 유입 트래픽(bps·pps) 크기를 평시와 비교하는 것은 DDoS 인지의 기본 방법이다.","동시 접속 세션 수를 평시 대비 증감률로 비교하면 비정상 접속 폭증을 인지할 수 있어 적절하다.","웹 서버 접속 로그에서 특정 URL·IP의 요청 급증을 확인하는 것은 애플리케이션 계층 DDoS 인지에 유효하다.","DDoS는 외부에서 들어오는(인바운드) 트래픽이 문제이므로 서버에서 나가는 트래픽 샘플링은 인지 수단으로 부적절하며, 트래픽 분석은 공격 유형 파악 단계의 작업이다."],"rel":["2-3"]},{"n":31,"s":"s2","q":"다음 지문에서 설명하는 DDoS 공격은?","c":["UDP Flooding","SYN Flooding","Slow Header Flooding","ICMP Flooding"],"a":1,"e":"SYN Flooding은 대량의 SYN만 보내 서버의 연결 대기 큐(Backlog) 등 TCP/IP 스택 자원을 소진시키므로 출발지 IP별 PPS 임계치, SYN Cookie, 비정상 헤더 차단으로 대응한다. UDP·ICMP Flooding은 주로 대역폭을 소진시키며, Slow Header Flooding은 웹서버 연결 자원을 오래 점유하는 공격이다.","ce":["UDP Flooding은 대량의 UDP 패킷으로 회선 대역폭을 소진시키는 공격으로, 대응은 불필요한 UDP 서비스 차단·대역폭 임계치 설정이 중심이다.","SYN Flooding은 연결을 완료하지 않는 SYN을 대량으로 보내 서버의 백로그 큐 등 TCP/IP 스택 자원을 고갈시키므로 IP별 PPS 임계치·비정상 헤더 차단·SYN Cookie로 대응한다.","Slow Header Flooding(Slowloris)은 HTTP 헤더를 끝맺지 않고 천천히 보내 웹서버 커넥션을 오래 점유하는 애플리케이션 계층 공격이다.","ICMP Flooding은 대량의 ICMP Echo 등으로 대역폭을 소모시키는 공격으로 ICMP 차단·임계치로 대응하며 TCP 스택 자원 소모가 특징이 아니다."],"rel":["2-3"],"box":"TCP/IP 스택(Stack) 자원을 소모하는 특징이 있으므로 소스 IP별로 PPS 임계치를 설정하거나 패킷 헤더 검사를 통해 정상적인 옵션 필드값을 갖지 않는 비정상 패킷을 차단한다."},{"n":32,"s":"s2","q":"네트워크 기반 공격 기술 중 DDoS 공격의 설명으로 옳은 것은?","c":["㉠","㉡, ㉢","㉠, ㉡","㉠, ㉡, ㉢"],"a":3,"e":"DDoS는 악성코드에 감염된 다수의 좀비 PC(봇넷)를 동원해 특정 대상에 처리 한계를 넘는 트래픽·요청을 보내 서비스를 마비시키는 공격이므로 ㉠㉡㉢ 모두 옳다.","ce":["㉠만 고르면 불완전하다. ㉡(과도한 트래픽으로 마비)과 ㉢(좀비 PC 활용)도 DDoS에 대한 옳은 설명이다.","㉡·㉢은 옳지만, 다수 컴퓨터를 이용해 특정 사이트를 공격한다는 ㉠도 DDoS의 정의 그대로이므로 빠뜨렸다.","㉠·㉡은 옳지만 감염된 좀비 PC(봇넷)가 공격에 동원된다는 ㉢도 옳은 설명이므로 빠뜨렸다.","DDoS는 악성코드에 감염된 다수의 좀비 PC(㉢)를 동원해(㉠) 대상의 처리 능력을 넘는 트래픽을 유발해 마비시키는(㉡) 공격이므로 세 설명 모두 옳다."],"rel":["2-3"],"box":"㉠ DDoS 공격이란 다수의 컴퓨터를 이용하여 특정 사이트를 공격하는 방식이다.\n㉡ DDoS 공격의 목표는 공격 대상 서버가 처리할 수 없는 과도한 접속(트래픽)을 유발하여 시스템을 마비시키는 것이다.\n㉢ 일반적으로 좀비 PC들이 이 공격에 활용된다."},{"n":33,"s":"s2","q":"윈도우 명령어는?","c":["net use","net share","복원중","net computer"],"a":1,"e":"net share는 로컬 시스템의 공유 폴더 목록(C$, IPC$, ADMIN$ 등 기본 공유 포함)을 출력하고 공유를 생성·삭제한다. net use는 원격 공유 자원에 드라이브를 연결하거나 연결 목록을 보는 명령이고, net computer는 도메인에 컴퓨터를 추가·삭제하는 명령이다.","ce":["net use는 원격 컴퓨터의 공유 자원에 드라이브 문자를 연결·해제하거나 현재 연결 목록을 보여 주는 명령으로, 로컬 공유 목록을 출력하지 않는다.","net share는 로컬 컴퓨터가 공유 중인 자원 목록(C$·IPC$·ADMIN$ 같은 기본 공유 포함)을 출력하며 공유 생성·삭제(/delete)도 한다.","원문 복원 과정에서 보기 내용이 누락('복원중')되어 판단 근거가 없다 — 공식 정답(net share) 기준으로 오답이다.","net computer는 도메인 컨트롤러에서 도메인에 컴퓨터 계정을 추가(/add)·삭제(/del)하는 명령이다."],"rel":["2-13","1-17"],"box":"C:\\WINDOWS\\system32\\cmd.exe 실행 결과\n공유 이름   리소스                              설명\nC$          C:\\                                  기본 공유\nD$          D:\\                                  기본 공유\nE$          E:\\                                  기본 공유\nIPC$                                             원격 IPC\nprint$      C:\\WINDOWS\\system32\\spool\\drivers    프린터 드라이버\nADMIN$      C:\\WINDOWS                           원격 관리\n명령을 잘 실행했습니다.","flag":"원문은 명령 프롬프트 스크린샷, 텍스트로 전사"},{"n":34,"s":"s2","q":"IP Spoofing 공격과 가장 거리가 먼 것은?","c":["SYN Flooding 공격","RST를 이용한 접속 끊기","순서번호 추측","slowloris 공격"],"a":3,"e":"Slowloris는 정상 IP로 HTTP 헤더를 불완전하게 천천히 보내 웹서버 연결을 점유하는 공격으로, TCP 세션을 유지해야 하므로 IP 위조를 사용하지 않는다. SYN Flooding은 출발지 IP를 위조하고, RST 접속 끊기와 순서번호 추측은 신뢰 호스트로 위장(IP Spoofing)하는 세션 공격과 연계된다.","ce":["SYN Flooding은 응답(SYN/ACK)을 받을 필요가 없어 출발지 IP를 위조(Spoofing)해 추적을 피하고 반쪽 연결을 쌓으므로 IP 스푸핑과 밀접하다.","RST 패킷 접속 끊기는 통신 중인 상대 IP로 위장하고 순서번호를 맞춘 RST를 보내 세션을 강제 종료하므로 IP 스푸핑을 사용한다.","순서번호 추측은 신뢰 관계 호스트의 IP로 위장한 상태에서 서버의 TCP 순서번호를 예측해 세션을 수립하는 IP 스푸핑의 핵심 단계다.","Slowloris는 실제 TCP 연결을 맺고 HTTP 헤더를 천천히 보내야 하므로 자기 IP로 정상 연결을 유지해야 하며 IP 위조를 쓰지 않는다."],"rel":["2-5"]},{"n":35,"s":"s2","q":"FTP 전송모드에 대한 설명으로 옳은 것은?","c":["디폴트는 active 모드이며, passive 모드로의 변경은 FTP 서버가 결정한다.","디폴트는 active 모드이며, passive 모드로의 변경은 FTP 클라이언트가 결정한다.","디폴트는 passive 모드이며, active 모드로의 변경은 FTP 서버가 결정한다.","디폴트는 passive 모드이며, active 모드로의 변경은 FTP 클라이언트가 결정한다."],"a":1,"e":"FTP의 기본은 서버가 20번 포트에서 클라이언트로 데이터 연결을 여는 Active 모드이며, 클라이언트가 PASV 명령을 보내 Passive 모드로 전환을 결정한다. Passive 모드에서는 클라이언트가 서버의 임의 포트로 데이터 연결을 맺는다.","ce":["기본이 Active 모드인 것은 맞지만, Passive 전환은 클라이언트가 PASV 명령을 보내 요청하는 것이지 서버가 결정하지 않는다.","FTP 기본은 서버가 20번에서 클라이언트로 데이터 연결을 여는 Active 모드이며, 클라이언트가 PASV 명령을 보내 Passive 모드 전환을 결정한다.","FTP 프로토콜의 기본은 Active 모드이며, 모드 선택 주체도 서버가 아니라 클라이언트다.","FTP 표준의 기본 모드는 Passive가 아닌 Active다. 방화벽 때문에 많은 클라이언트가 Passive를 기본으로 설정하지만 프로토콜 기본값과는 다르다."],"rel":["3-1"]},{"n":36,"s":"s2","q":"포트가 열린 경우 응답이 다른 것은?","c":["NULL 스캔","TCP SYN 스캔","FIN 스캔","XMAS 스캔"],"a":1,"e":"TCP SYN 스캔은 포트가 열려 있으면 SYN/ACK 응답이 온다. NULL·FIN·XMAS 스캔은 포트가 열려 있으면 응답이 없고, 닫혀 있으면 RST/ACK가 돌아온다.","ce":["NULL 스캔은 플래그 없는 TCP 패킷을 보내며, 열린 포트는 응답하지 않고 닫힌 포트만 RST/ACK를 보낸다.","SYN 스캔은 열린 포트에서 SYN/ACK 응답이 돌아오고(이후 RST로 연결 미완성), 닫힌 포트에서는 RST/ACK가 오므로 열린 경우 응답이 있는 유일한 방식이다.","FIN 스캔은 FIN 플래그만 보내며, 열린 포트는 RFC 793에 따라 무응답, 닫힌 포트는 RST/ACK를 보낸다.","XMAS 스캔은 FIN·PSH·URG를 모두 켜서 보내며, 열린 포트는 무응답, 닫힌 포트는 RST/ACK를 보낸다."],"rel":["2-4"]},{"n":37,"s":"s2","q":"WPA2 CCMP 모드에서 무선구간 데이터 보호를 위해 사용되는 암호화 알고리즘은?","c":["AES","RC5","TKIP","DES"],"a":0,"e":"WPA2의 CCMP(Counter mode with CBC-MAC Protocol)는 AES 블록암호를 CTR 모드(기밀성)와 CBC-MAC(무결성)으로 사용한다. TKIP는 WPA에서 RC4 기반 WEP를 보완하기 위해 쓰인 프로토콜로 알고리즘 자체가 아니다.","ce":["CCMP는 AES 블록 암호를 CTR 모드(기밀성)와 CBC-MAC(무결성)로 조합해 사용하는 WPA2의 필수 암호 방식이다.","RC5는 Rivest가 설계한 가변 블록 암호로 802.11 무선랜 보안 표준에서 사용되지 않는다.","TKIP는 WPA에서 RC4 기반 WEP 장비를 재사용하려고 키를 패킷마다 바꾸도록 만든 프로토콜로, CCMP가 아닌 별도 방식이다.","DES는 56비트 키의 구형 블록 암호로 무선랜 WPA2 표준에서 사용되지 않는다."],"rel":["2-10"]},{"n":38,"s":"s2","q":"다음 지문에서 설명하는 것은?","c":["Threat Profiling","Heuristic Analysis","Sandbox","Injector"],"a":2,"e":"원 지문은 복원되지 않았으며 정답은 Sandbox로 공개되어 있다. 샌드박스는 의심 파일·코드를 시스템과 격리된 가상 환경에서 실행해 행위를 관찰·분석하는 기술로, 알려지지 않은 악성코드(APT) 탐지에 쓰인다. Heuristic Analysis는 코드의 특징·행위 규칙으로 악성 여부를 추정하는 방식이다.","ce":["Threat Profiling은 조직을 노리는 위협 행위자·공격 기법의 특성을 정리하는 위협 분석 활동이다. 지문 원문이 누락되어 공식 정답(Sandbox) 기준으로 오답 처리한다.","휴리스틱 분석은 코드 구조·행위 규칙으로 악성 여부를 추정하는 정적·동적 탐지 기법이다. 지문 누락으로 직접 비교는 어렵고 공식 정답은 Sandbox다.","샌드박스는 의심 파일을 격리된 가상 환경에서 실행해 행위를 관찰하는 기술로 공식 정답이다(원문 지문 누락 — 공식 정답 기준).","Injector는 악성 코드를 다른 프로세스 메모리에 주입하는 도구·모듈을 뜻한다. 지문 원문 누락으로 판단 근거가 제한적이며 공식 정답은 Sandbox다."],"rel":["2-10"],"flag":"원문 지문 누락(comcbt 복원 오류 안내문: 정답 3번만 제공). 지문 내용 확인필요"},{"n":39,"s":"s2","q":"다음 지문이 설명하는 컴퓨팅 기술은?","c":["마스터/슬레이브","클라이언트/서버","클라우드","피어 투 피어"],"a":2,"e":"클라우드 컴퓨팅은 가상화된 컴퓨팅 자원을 네트워크로 공유·임대하는 서비스이며, 제공 범위에 따라 IaaS(인프라), PaaS(플랫폼), SaaS(소프트웨어)로 구분한다. 클라이언트/서버와 P2P는 통신 구조 모델이다.","ce":["마스터/슬레이브는 한 장치가 다른 장치를 제어하는 통신·제어 구조로 가상화 자원 임대 서비스와 무관하다.","클라이언트/서버는 요청·응답 역할을 나눈 분산 구조 모델일 뿐 IaaS·PaaS·SaaS 같은 서비스 모델을 정의하지 않는다.","클라우드 컴퓨팅은 가상화된 자원을 네트워크로 공유·임대하며, 제공 계층에 따라 IaaS(인프라)·PaaS(플랫폼)·SaaS(소프트웨어)로 구분된다.","P2P는 서버 없이 동등한 노드끼리 자원을 직접 주고받는 구조로, 사업자가 자원을 임대하는 서비스 모델과 다르다."],"rel":["1-12"],"box":"기존 기술에 없었던 가상화와 공유 및 임대 서비스 등은 시스템 체계 및 네트워크 체계에 큰 변화를 예고하고 있다. 컴퓨팅 서비스로 IaaS, PaaS, SaaS 등이 대표적이다."},{"n":40,"s":"s2","q":"빈 칸에 들어갈 용어를 바르게 짝지은 것은?","c":["㉠ WLAN ㉡ Broadcast","㉠ Infrastructure ㉡ Ad Hoc","㉠ APD ㉡ Peer to Peer","㉠ VPN ㉡ Peer to Peer"],"a":1,"e":"IEEE 802.11은 AP를 중심으로 단말이 통신하는 Infrastructure 모드(BSS)와 AP 없이 단말끼리 직접 통신하는 Ad Hoc 모드(IBSS)를 정의한다.","ce":["WLAN은 무선랜 자체를 일컫는 말이고 Broadcast는 전송 방식이어서 802.11의 두 구성 모드 명칭이 아니다.","802.11은 AP를 중심으로 단말이 통신하는 Infrastructure 모드(BSS)와 AP 없이 단말끼리 직접 통신하는 Ad Hoc 모드(IBSS)를 정의한다.","APD는 802.11의 구성 모드 명칭이 아니며, Peer to Peer는 개념상 유사하지만 표준 용어는 Ad Hoc이다.","VPN은 공중망 위의 암호화 터널 기술로 무선랜 구성 모드가 아니다."],"rel":["2-10"],"box":"802.11 무선 표준에서는 무선랜의 구성에 따라 2개의 구성유형이 제시되고 있다. 첫 번째는 ( ㉠ ) 모드로 무선 AP와 무선 단말기로 구성되는 방식과, 두 번째는 무선 단말기 사이에 직접 통신이 이뤄지는 ( ㉡ ) 모드이다."},{"n":41,"s":"s3","q":"다음 지문에서 설명하고 있는 공격은?","c":["port attack","bounce attack","IP Spoofing","port scan"],"a":1,"e":"FTP 바운스 공격은 Active 모드의 PORT 명령에 제3의 호스트 IP·포트를 지정해 FTP 서버가 대신 접속하게 만드는 공격으로, 공격자 IP를 숨긴 포트 스캔이나 우회 접속에 악용된다. 대응책은 PORT 명령에서 클라이언트와 다른 IP나 1024 미만 포트를 거부하는 것이다.","ce":["port attack은 특정 공격 기법을 가리키는 표준 용어가 아니며, FTP PORT 명령 악용 공격의 정식 명칭은 바운스 공격이다.","FTP 바운스 공격은 PORT 명령에 제3 호스트의 IP·포트를 넣어 FTP 서버가 대신 접속하게 만들어, 공격자 IP를 숨긴 포트 스캔·우회 접속에 악용한다.","IP 스푸핑은 패킷의 출발지 IP를 직접 위조하는 기법으로, FTP 서버를 중계자로 이용하는 방식과 다르다.","포트 스캔은 바운스 공격으로 달성할 수 있는 목적(결과)일 뿐, FTP 서버에 PORT 명령을 보내 대신 접속시키는 공격 기법의 명칭은 아니다."],"rel":["3-1"],"box":"FTP 서버에 PORT 명령을 전송하며 서버로 하여금 공격 대상 호스트에 접속하게 하는 공격\n공격자 호스트의 IP를 숨긴 채 공격 대상 호스트의 포트를 모두 조사하는 데 사용될 수 있음"},{"n":42,"s":"s3","q":"포렌식 조사 원칙 중 틀린 것은?","c":["기밀성의 원칙: 수집 증거가 명백히 허가된 대상에게만 제공되어야 함.","무결성의 원칙: 수집 증거가 위·변조 되지 않았음을 증명해야 함.","재현의 원칙: 같은 조건에서 항상 같은 결과가 나와야 함.","신속성의 원칙: 전 과정이 지체 없이 신속하게 진행되어야 함."],"a":0,"e":"디지털 포렌식 5대 원칙은 정당성, 재현, 신속성, 연계보관성(Chain of Custody), 무결성이다. 기밀성은 포렌식 조사 원칙에 포함되지 않는다.","ce":["기밀성은 디지털 포렌식 5대 원칙(정당성·재현·신속성·연계보관성·무결성)에 포함되지 않는다.","무결성 원칙은 수집 증거가 위·변조되지 않았음을 해시값 비교 등으로 증명해야 한다는 것으로 올바르다.","재현 원칙은 같은 조건과 절차로 분석하면 항상 같은 결과가 나와야 한다는 것으로 올바르다.","신속성 원칙은 휘발성 증거가 사라지기 전에 전 과정을 지체 없이 진행해야 한다는 것으로 올바르다."],"rel":["3-11"]},{"n":43,"s":"s3","q":"합법적으로 소유하고 있던 사용자들의 도메인을 탈취하거나 DNS 조작을 통해 사용자들이 정확한 웹페이지 주소를 입력하더라도 가짜 웹페이지에 접속하도록 유도하여 개인정보를 훔치는 공격 방식은?","c":["피싱 공격","스피어 피싱 공격","파밍 공격","워터링 홀 공격"],"a":2,"e":"파밍(Pharming)은 hosts 파일 변조, DNS 캐시 포이즈닝, 도메인 탈취 등으로 올바른 주소를 입력해도 가짜 사이트로 연결시키는 공격이다. 피싱은 가짜 링크를 클릭하도록 유도하는 방식이고, 워터링 홀은 표적이 자주 방문하는 사이트를 감염시키는 공격이다.","ce":["피싱은 가짜 메일·문자의 링크를 클릭하게 유도해 가짜 사이트로 보내는 방식이라, 사용자가 올바른 주소를 입력하면 속지 않는다.","스피어 피싱은 특정 개인·조직을 노린 맞춤형 피싱으로, 역시 링크·첨부파일 유도 방식이며 DNS 조작이 아니다.","파밍은 hosts 파일 변조·DNS 캐시 포이즈닝·도메인 탈취로 정확한 주소를 입력해도 가짜 사이트로 연결시켜 개인정보를 훔치는 공격이다.","워터링 홀은 표적 집단이 자주 방문하는 정상 사이트를 감염시켜 방문자에게 악성코드를 퍼뜨리는 공격으로 DNS를 조작하지 않는다."],"rel":["3-7"]},{"n":44,"s":"s3","q":"이메일 공격유형 중 HTML 기능이 있는 클라이언트나 웹브라우저 사용자를 대상으로 하는 공격기법은?","c":["Buffer Overflow 공격","Active contents 공격","스팸메일 공격","트로이목마 공격"],"a":1,"e":"Active contents 공격은 HTML 메일에 자바스크립트·ActiveX 등 실행 가능한 콘텐츠를 삽입해 메일을 열람하는 것만으로 스크립트가 실행되게 하는 공격이다. 대응으로 메일 클라이언트의 스크립트 실행 기능을 제한한다.","ce":["버퍼 오버플로우는 입력 길이 검증 미흡으로 메모리를 덮어써 코드를 실행하는 공격으로, HTML 기능 사용자를 겨냥한 메일 공격 유형이 아니다.","Active contents 공격은 HTML 메일에 자바스크립트·ActiveX 같은 실행형 콘텐츠를 넣어, HTML을 지원하는 메일 클라이언트·브라우저에서 열람만으로 스크립트를 실행시킨다.","스팸 메일은 원치 않는 대량 광고 메일 발송으로, HTML 실행 기능을 이용한 공격 기법이 아니다.","트로이목마 공격은 정상 프로그램으로 위장한 첨부파일 실행을 유도하는 방식으로, HTML 렌더링 기능 자체를 겨냥하지 않는다."],"rel":["3-2"]},{"n":45,"s":"s3","q":"FTP 서비스를 운영할 때 준수하여야 할 보안사항으로 부적절한 것은?","c":["FTP 서비스는 필요한 경우에만 활성화하며, Secure FTP 또는 Trivial FTP 등을 사용한다.","관리자 외에는 읽기권한만 부여한다.","FTP 연결시간(timeout)을 제한한다.","FTP 서버에는 중요 문서 또는 보안파일을 저장하지 않는다."],"a":0,"e":"TFTP(Trivial FTP)는 UDP 69번을 사용하며 인증 절차가 없어 오히려 보안에 취약하므로 권장 대상이 아니다. 필요 시 SFTP·FTPS처럼 암호화된 프로토콜을 사용해야 한다.","ce":["TFTP(UDP 69)는 인증 절차가 전혀 없어 보안에 취약하므로 권장 대상이 아니다. 필요 시 SFTP·FTPS 같은 암호화 프로토콜을 써야 한다.","업로드 권한을 관리자로 한정하고 일반 사용자에게 읽기 권한만 주는 것은 최소 권한 원칙에 맞는 적절한 조치다.","유휴 연결에 timeout을 두면 방치된 세션 악용과 자원 점유를 줄일 수 있어 적절한 보안 설정이다.","FTP는 평문 전송·익명 접속 위험이 있으므로 중요 문서나 보안 파일을 두지 않는 것이 적절하다."],"rel":["3-1"]},{"n":46,"s":"s3","q":"다음 중 포맷 스트링 취약점 동작과 가장 거리가 먼 것은?","c":["프로세스 권한 상승","임의의 코드 실행","메모리 내용 변경","프로세스 메모리 보기"],"a":0,"e":"포맷 스트링 공격은 %x로 스택 메모리를 읽고, %n으로 임의 메모리에 값을 써서 반환 주소 등을 변경해 임의 코드를 실행할 수 있다. 권한 상승은 SetUID 프로그램 등에서 부수적으로 발생할 수 있는 결과이지 포맷 스트링 취약점 자체의 동작은 아니다.","ce":["권한 상승은 포맷 스트링이 SetUID 프로그램에서 악용될 때 나타나는 결과일 뿐, 취약점 자체의 동작(메모리 읽기·쓰기)으로 보기는 어렵다.","%n으로 반환 주소나 GOT 항목을 쉘코드 주소로 덮어쓰면 임의 코드를 실행할 수 있어 포맷 스트링의 대표 동작이다.","%n은 지금까지 출력한 바이트 수를 지정 주소에 기록하므로 공격자가 원하는 메모리 내용을 변경할 수 있다.","%x·%s 등을 인자 없이 넣으면 스택의 값을 차례로 출력하므로 프로세스 메모리를 엿볼 수 있다."],"rel":["1-10"]},{"n":47,"s":"s3","q":"XSS 공격에 대한 설명으로 옳은 것은?","c":["자료실에 올라간 파일을 다운로드할 때 전용 다운로드 프로그램이 파일을 가져오는데, 이때 파일 이름을 필터링 하지 않아서 취약점이 발생한다.","악성 스크립트를 웹 페이지의 파라미터 값에 추가하거나, 웹 게시판에 악성 스크립트를 포함시킨 글을 등록하여 이를 사용자의 웹 브라우저 내에서 적절한 검증 없이 실행되도록 한다.","네트워크 통신을 조작하여 통신 내용을 도청하거나 조작하는 공격 기법이다.","데이터베이스를 조작할 수 있는 스크립트를 웹 서버를 이용하여 데이터베이스로 전송한 후 데이터베이스의 반응을 이용하여 기밀 정보를 취득하는 공격 기법이다."],"a":1,"e":"XSS(Cross Site Scripting)는 입력값 검증 미흡을 이용해 악성 스크립트를 파라미터(반사형)나 게시글(저장형)에 삽입, 피해자 브라우저에서 실행시켜 쿠키 탈취 등을 하는 공격이다. ①은 파일 다운로드(경로 조작), ③은 중간자 공격, ④는 SQL 인젝션에 대한 설명이다.","ce":["다운로드 프로그램이 파일명(../ 등)을 필터링하지 않아 서버 임의 파일을 내려받게 되는 것은 파일 다운로드(경로 조작) 취약점이다.","XSS는 파라미터(반사형)나 게시글(저장형)에 악성 스크립트를 넣어, 검증 없이 사용자 브라우저에서 실행되게 해 쿠키 탈취 등을 하는 공격이다.","통신 내용을 가로채 도청·조작하는 것은 중간자(MITM)·스니핑 공격으로, 웹 페이지에 스크립트를 삽입하는 XSS와 다르다.","DB를 조작하는 구문을 웹 서버를 통해 전달하고 DB 반응으로 정보를 얻는 것은 SQL 인젝션(블라인드 SQLi 포함)이다."],"rel":["3-6"]},{"n":48,"s":"s3","q":"사용자가 http://www.kisa.or.kr에 접속하기 위해 IP 주소를 얻어오는 순서는?","c":["로컬 DNS 서버 → 캐시 → Hosts 파일","Hosts 파일 → 캐시 → 로컬 DNS 서버","로컬 DNS 서버 → Hosts 파일 → 캐시","캐시 → Hosts 파일 → 로컬 DNS 서버"],"a":3,"e":"윈도우는 먼저 로컬 DNS 캐시를 조회하고, 없으면 hosts 파일을, 그래도 없으면 로컬 DNS 서버에 질의한다(hosts 파일 내용은 캐시에 미리 적재됨). 이 때문에 hosts 파일이나 캐시를 변조하는 파밍 공격이 가능하다.","ce":["로컬 DNS 서버 질의는 로컬에서 해결되지 않을 때 가는 마지막 단계이므로 첫 순서가 될 수 없다.","hosts 파일 내용은 DNS 클라이언트 캐시에 미리 적재되어 함께 조회되므로, 윈도우 조회 순서는 캐시가 hosts 파일보다 먼저로 정리한다.","DNS 서버를 먼저 묻는 순서가 아니며, 로컬 자원(캐시·hosts)을 먼저 확인한 뒤 서버에 질의한다.","윈도우는 로컬 DNS 캐시 → hosts 파일 → 설정된 로컬 DNS 서버 순으로 조회하므로 이 순서가 맞다. 이 로컬 단계를 변조하는 것이 파밍이다."],"rel":["3-7"]},{"n":49,"s":"s3","q":"SET에서 주문정보와 지불정보의 해시값을 결합하여 생성된 메시지에 다시 해시함수를 적용한 후 그 결과를 고객의 개인키로 암호화하는데 이 과정을 의미하는 용어는?","c":["전자 서명","은닉 서명","이중 서명","영지식 서명"],"a":2,"e":"SET의 이중 서명(Dual Signature)은 주문정보(OI)와 지불정보(PI)의 해시를 연결해 다시 해시한 뒤 고객 개인키로 서명한다. 이를 통해 상점은 지불정보를, 금융기관은 주문정보를 보지 못하면서도 두 정보의 연관성을 검증할 수 있다. 은닉 서명은 서명자가 내용을 모른 채 서명하는 방식이다.","ce":["일반 전자서명은 한 메시지의 해시에 서명하는 것이다. OI·PI 두 해시를 결합해 다시 해시·서명하는 SET 고유 방식은 이중 서명이라 부른다.","은닉 서명(Blind Signature)은 서명자가 메시지 내용을 모른 채 서명하게 하는 방식으로 전자화폐의 익명성에 쓰인다.","SET 이중 서명은 H(H(OI)||H(PI))를 고객 개인키로 서명해, 상점은 지불정보를, 은행은 주문정보를 보지 않고도 두 정보의 연계를 검증하게 한다.","영지식 증명은 비밀을 드러내지 않고 알고 있음을 증명하는 기법으로, SET의 주문·지불정보 결합 서명과 무관하다."],"rel":["3-10"]},{"n":50,"s":"s3","q":"CPU 하드웨어에 존재하는 부채널 관련 버그로써 빠른 수행을 위해 개발된 캐싱 및 추측 실행 기능을 악용하는 공격의 명칭은?","c":["merkle tree","spectre","man-in-the-middle","covert channel"],"a":1,"e":"스펙터(Spectre)는 CPU의 분기 예측·추측 실행(Speculative Execution)과 캐시 타이밍 부채널을 악용해 다른 프로세스의 메모리를 읽는 취약점이다(2018년 멜트다운과 함께 공개). 머클 트리는 해시 트리 구조, 은닉 채널은 정책을 우회한 비정상 정보 전달 경로다.","ce":["머클 트리는 데이터 블록 해시를 트리로 묶어 루트 해시로 무결성을 검증하는 자료구조(블록체인 등)로 CPU 버그가 아니다.","스펙터는 CPU의 분기 예측·추측 실행으로 캐시에 남은 흔적을 타이밍 부채널로 읽어 다른 프로세스 메모리를 유출하는 하드웨어 취약점(2018년 공개)이다.","중간자 공격은 통신 경로 중간에서 트래픽을 가로채 도청·변조하는 네트워크 공격이다.","은닉 채널은 보안 정책이 허용하지 않은 방식으로 정보를 전달하는 통신 경로 일반을 가리키며, 특정 CPU 추측 실행 버그의 명칭이 아니다."],"rel":["1-19"]},{"n":51,"s":"s3","q":"SQL 인젝션 공격에 대응하는 효과적인 방법이 아닌 것은?","c":["데이터베이스 내장 프로시저를 사용","원시 ODBC 에러를 사용자가 볼 수 없도록 코딩","사용자가 입력하여 서버로 전송되는 파라미터값을 검증","DB 애플리케이션의 접근권한을 최대한 허용"],"a":3,"e":"SQL 인젝션 대응은 입력값 검증, 바인딩 변수(Prepared Statement)·저장 프로시저 사용, 상세 DB 오류 메시지 은닉, 그리고 DB 계정 권한의 최소화다. 접근권한을 최대한 허용하면 인젝션 성공 시 피해가 커진다.","ce":["저장 프로시저를 매개변수화해 호출하면 입력값이 SQL 구문이 아닌 데이터로 처리되어 인젝션 위험을 줄이므로 대응책에 해당한다.","원시 ODBC·DB 오류 메시지를 노출하지 않으면 공격자가 테이블·컬럼 구조를 알아내는 오류 기반 인젝션을 어렵게 만든다.","서버로 전송되는 파라미터의 특수문자(' -- ; 등)를 검증·필터링하는 것은 SQL 인젝션의 가장 기본적인 대응책이다.","DB 애플리케이션 계정 권한은 최소 권한으로 제한해야 한다. 권한을 최대한 허용하면 인젝션 성공 시 테이블 삭제·시스템 명령 실행까지 피해가 커진다."],"rel":["3-6"]},{"n":52,"s":"s3","q":"다음에서 설명하는 웹 서비스 공격은?","c":["직접 객체 참조","Cross Site Request Forgery","Cross Site Scripting","SQL Injection"],"a":3,"e":"SQL Injection은 입력값에 SQL 구문(예: ' OR 1=1--)을 삽입해 인증을 우회하거나 DB 데이터를 조회·조작하는 공격이다. CSRF는 사용자 권한으로 원치 않는 요청을 보내게 하고, XSS는 사용자 브라우저에서 스크립트를 실행시키는 공격이다.","ce":["직접 객체 참조(IDOR)는 URL의 파일명·키 값 등을 바꿔 권한 없는 객체에 접근하는 취약점으로, 질의에 코드를 삽입하는 방식이 아니다.","CSRF는 로그인한 사용자가 모르는 사이 공격자가 의도한 요청(송금·글쓰기 등)을 보내게 하는 공격으로 DB 질의 조작이 아니다.","XSS는 사용자 브라우저에서 악성 스크립트를 실행시키는 공격으로, 서버 DB 인증 우회를 목표로 하지 않는다.","SQL Injection은 입력값에 ' OR 1=1-- 같은 SQL 구문을 삽입해 DB 인증을 우회하거나 데이터를 조회·변조하는 공격이다."],"rel":["3-6"],"box":"공격자가 사용자의 명령어나 질의어에 특정한 코드를 삽입하여 DB 인증을 우회하거나 데이터를 조작한다."},{"n":53,"s":"s3","q":"다음 지문에서 설명하는 공격 기법은?","c":["DNS Zone transfer","Domain Shadowing","DNS Spoofing","Fast Flux Hosting"],"a":1,"e":"도메인 섀도잉은 탈취한 정상 도메인 계정에 다수의 서브도메인을 몰래 생성해 중간 경유 서버·유포 서버 주소로 사용함으로써 도메인 평판 기반 차단을 우회한다. Fast Flux는 하나의 도메인에 대응하는 IP를 매우 짧은 주기로 바꿔 추적을 회피하는 기법이고, Zone Transfer는 DNS 서버 간 영역 정보 복제다.","ce":["DNS Zone Transfer는 주 DNS 서버의 영역 정보를 보조 서버로 복제하는 기능으로, 허용 대상을 제한하지 않으면 내부 호스트 정보가 노출되는 문제가 있을 뿐 유포 경유지 지정 기법이 아니다.","도메인 섀도잉은 탈취한 정상 도메인 계정에 대량의 서브도메인을 몰래 만들어 경유지·유포지로 사용함으로써 도메인 평판 기반 탐지·차단을 우회한다.","DNS 스푸핑은 위조 DNS 응답으로 사용자를 가짜 IP로 보내는 공격으로, 공격자가 경유·유포 서버 도메인을 만들어 지정하는 기법과 다르다.","Fast Flux는 한 도메인에 연결된 IP를 수 분 단위로 계속 바꿔 서버 추적·차단을 피하는 기법으로, IP를 바꾸는 쪽이지 정상 도메인의 서브도메인을 만드는 기법은 아니다."],"rel":["3-7"],"box":"이것은 보안장비에서 사용하는 도메인네임 기반 탐지/차단을 우회하기 위하여 사용하는 기법으로 희생자를 악성코드 유포서버에 접속시키고자 유도할 때, 바로 악성코드 유포서버로 접속시키지 않고, 먼저 중간 단계의 서버에 접속시킨 다음, 그 곳으로부터 악성코드 유포서버로 접속시키는 기법을 사용한다. 이때 중간 단계의 서버 및 유포 서버를 지정할 때 사용되는 기법이다."},{"n":54,"s":"s3","q":"스마트카드 보안 기술에 대한 설명 중 틀린 것은?","c":["사용자 식별과 인증을 위해 필요한 정보를 저장하고 관리하는 모듈로 WIM(Wireless Identity Module)을 사용한다.","개인 이동성과 서비스 이동성을 겸비한 이동 통신용 스마트카드를 USIM(Universal Subscriber Identity Module)이라고 한다.","USIM은 ME(Mobile Equipment)와 인터페이스하기 위해 T=0 통신 프로토콜을 사용한다.","WIM은 WTLS와 연계하여 사용할 수 없다."],"a":3,"e":"WIM은 WAP 환경에서 WTLS(Wireless Transport Layer Security) 세션 설정과 전자서명에 필요한 키·인증서를 안전하게 저장·연산하는 모듈이므로 WTLS와 연계해 사용된다. USIM은 가입자 인증과 개인·서비스 이동성을 제공하는 이동통신용 스마트카드다.","ce":["WIM은 WAP 환경에서 사용자 식별·인증에 필요한 키와 인증서를 저장·관리하는 보안 모듈이므로 옳다.","USIM은 가입자 인증과 함께 개인 이동성(단말을 바꿔도 가입자 유지)과 서비스 이동성을 제공하는 이동통신용 스마트카드이므로 옳다.","USIM은 ISO/IEC 7816 기반으로 단말(ME)과 T=0 문자 전송 프로토콜로 통신하므로 옳은 설명으로 본다.","WIM은 WTLS 세션 수립과 전자서명에 필요한 개인키 연산을 수행하도록 설계되어 WTLS와 연계해 사용되므로 '사용할 수 없다'는 틀렸다."],"rel":["3-14"]},{"n":55,"s":"s3","q":"SSL 핸드셰이크 과정에서 End-to-End에 오류가 발생하면 사용자에게 경고하는 프로토콜은?","c":["핸드셰이크 프로토콜","암호규격변경 프로토콜","Alert 프로토콜","SSL Record 프로토콜"],"a":2,"e":"Alert 프로토콜은 SSL/TLS 통신 중 발생한 오류나 경고(warning/fatal)를 상대방에게 알린다. 핸드셰이크는 암호 스위트 협상·인증·키 교환, Change Cipher Spec은 협상된 암호 방식 적용, Record 프로토콜은 데이터 단편화·암호화·MAC 처리를 담당한다.","ce":["핸드셰이크 프로토콜은 버전·암호 스위트 협상, 인증서 교환, 키 교환을 수행하며 오류 통보 전용 프로토콜이 아니다.","Change Cipher Spec 프로토콜은 협상된 암호 방식을 이후 레코드부터 적용하겠다고 알리는 1바이트 메시지다.","Alert 프로토콜은 통신 중 오류·이상을 warning 또는 fatal 수준으로 상대에게 통보하며, fatal이면 즉시 세션을 종료한다.","Record 프로토콜은 상위 데이터를 단편화·압축하고 MAC과 암호화를 적용해 전송하는 하위 계층이다."],"rel":["2-7"]},{"n":56,"s":"s3","q":"다음 중 SSO 방식과 가장 거리가 먼 것은?","c":["RADIUS","SPNEGO","Kerberos","SESAME"],"a":0,"e":"RADIUS는 원격 접속 사용자에 대한 AAA(인증·권한·과금) 프로토콜로 SSO 방식이 아니다. Kerberos와 SESAME는 티켓(인증서) 기반 SSO 프로토콜이고, SPNEGO는 Kerberos 등을 이용해 웹 환경에서 통합 인증(SSO)을 가능하게 하는 협상 메커니즘이다.","ce":["RADIUS는 원격 접속(다이얼업·VPN·무선) 사용자에 대한 AAA를 중앙 서버에서 처리하는 프로토콜로, 여러 서비스 로그인을 하나로 통합하는 SSO 방식이 아니다.","SPNEGO는 Kerberos 등 인증 방식을 협상해 윈도우 로그인 정보로 웹 애플리케이션에 자동 인증하게 해 주므로 SSO 구현에 쓰인다.","Kerberos는 KDC가 발급한 티켓(TGT)으로 여러 서비스에 재인증 없이 접근하게 하는 대표적 SSO 프로토콜이다.","SESAME는 Kerberos를 확장해 공개키 기반 권한 인증서(PAC)를 사용하는 유럽의 SSO 프로토콜이다."],"rel":["4-9","2-8"]},{"n":57,"s":"s3","q":"SSL/TLS에 대해 잘못 설명한 것은?","c":["SSL/TLS는 메시지의 기밀성 및 무결성을 보장한다.","Null cipher suites는 encryption을 지원하지 않는다.","SSL2.0/SSL3.0은 취약한 버전이라 더 이상 사용하지 않는 것이 좋다.","최신 버전의 HTTP/2를 사용하려면 TLS 1.0 이상이 활성화되어 있어야 한다."],"a":3,"e":"HTTP/2 표준(RFC 7540)은 TLS 사용 시 TLS 1.2 이상을 요구하므로 'TLS 1.0 이상'은 틀린 설명이다. Null cipher suite는 암호화 없이 무결성만 제공하며, SSL 2.0/3.0은 POODLE 등 취약점으로 사용이 금지되었다.","ce":["SSL/TLS는 대칭키 암호화로 기밀성을, MAC(HMAC·AEAD)으로 무결성을 보장하므로 옳다.","Null cipher suite(예: TLS_RSA_WITH_NULL_SHA)는 인증·무결성만 제공하고 데이터를 암호화하지 않으므로 옳다.","SSL 2.0은 설계 결함, SSL 3.0은 POODLE 공격으로 RFC에서 사용 금지되었으므로 옳다.","HTTP/2(RFC 7540)는 TLS 사용 시 TLS 1.2 이상과 SNI를 요구하므로 'TLS 1.0 이상'은 틀렸다."],"rel":["2-7"]},{"n":58,"s":"s3","q":"다음 지문에서 설명하는 테스트 방식은?","c":["시스템 하드닝","코드 리뷰","블랙박스 테스트","화이트박스 테스트"],"a":3,"e":"화이트박스 테스트는 소스코드 등 내부 구조 정보를 알고 모든 처리 경로·루틴을 검증하는 방식이다. 블랙박스 테스트는 내부 구조를 모르는 상태에서 입력과 출력만으로 기능·취약점을 확인한다.","ce":["시스템 하드닝은 불필요한 서비스 제거·설정 강화로 공격 표면을 줄이는 보안 조치로, 테스트 방식이 아니다.","코드 리뷰는 사람이 소스코드를 읽어 결함을 찾는 정적 검토 활동으로, 모든 처리 루틴을 실행해 검증하는 테스트 방식과는 구분된다.","블랙박스 테스트는 내부 구조를 모른 채 입력과 출력만으로 기능·취약점을 확인하므로 지문과 반대다.","화이트박스 테스트는 소스코드 등 내부 구조를 분석해 문장·분기·경로 등 모든 처리 루틴을 검증하는 방식이다."],"rel":["3-9"],"box":"모의해킹 중 프로그램 내부 구조에 대한 타당성 여부를 시험하는 방식으로 프로그램 내부 구조를 분석하며 프로그램의 모든 처리 루틴을 테스트 하는 방식"},{"n":59,"s":"s3","q":"E-Mail 관련 프로토콜이 아닌 것은?","c":["S/MIME","IRC","IMAP","SMTP"],"a":1,"e":"IRC(Internet Relay Chat)는 실시간 채팅 프로토콜이다. SMTP는 메일 전송, IMAP은 메일 수신·관리, S/MIME은 메일 암호화·전자서명 표준이다.","ce":["S/MIME은 X.509 인증서로 메일 본문을 암호화하고 전자서명하는 메일 보안 표준이다.","IRC(Internet Relay Chat)는 채널 기반 실시간 채팅 프로토콜로 이메일과 무관하며, 과거 봇넷 C&C 채널로 악용되기도 했다.","IMAP(143)은 메일을 서버에 둔 채 폴더 단위로 조회·관리하는 메일 수신 프로토콜이다.","SMTP(25)는 메일 클라이언트→서버, 서버→서버로 메일을 전송하는 프로토콜이다."],"rel":["3-2"]},{"n":60,"s":"s3","q":"HTTP 상태 코드에 대한 해석 중 옳지 않은 것은?","c":["400 - Bad Request","401 - Authorized","403 - Forbidden","404 - Not Found"],"a":1,"e":"401은 'Unauthorized'로 인증이 필요하거나 인증에 실패한 경우의 응답이다. 400은 잘못된 요청, 403은 접근 금지, 404는 자원 없음이다.","ce":["400 Bad Request는 요청 문법이 잘못되어 서버가 이해할 수 없을 때의 응답으로 올바르다.","401은 Authorized가 아니라 Unauthorized로, 인증 정보가 없거나 틀려서 인증이 필요하다는 응답이다.","403 Forbidden은 인증 여부와 관계없이 해당 자원에 대한 접근 권한이 없을 때의 응답으로 올바르다.","404 Not Found는 요청한 자원을 서버에서 찾을 수 없을 때의 응답으로 올바르다."],"rel":["3-3"]},{"n":61,"s":"s4","q":"메시지 인증 코드에 대한 설명으로 옳지 않은 것은?","c":["MAC 값은 메시지와 함께 송신자 및 수신자만이 공유하고 있는 키값을 함께 해시함수로 처리하여 계산한다.","송신자가 전송한 MAC 값을 검증에 성공하는 경우 수신자는 메시지의 무결성과 메시지의 출처를 확인할 수 있다.","MAC 값을 활용하면 메시지에 대한 해시값만을 이용하는 경우 발생할 수 있는 메시지 내용과 해시값이 동시에 변조되는 위협에 대응할 수 있다.","MAC 값을 활용하면 전자서명과 동일한 보안 서비스를 얻을 수 있다."],"a":3,"e":"MAC은 송·수신자가 같은 비밀키를 공유하므로 제3자에게 누가 만들었는지 증명할 수 없어 부인방지를 제공하지 못한다. 따라서 무결성·메시지 인증은 가능하지만 전자서명과 동일한 보안 서비스는 아니다.","ce":["MAC(특히 HMAC)은 송·수신자가 공유한 비밀키와 메시지를 함께 해시(또는 블록암호)로 처리해 계산하므로 옳다.","비밀키를 가진 상대만 올바른 MAC을 만들 수 있으므로 검증에 성공하면 무결성과 메시지 출처(인증)를 확인할 수 있어 옳다.","단순 해시는 공격자가 메시지를 바꾸고 해시도 다시 계산해 붙일 수 있지만, MAC은 비밀키 없이 새 값을 만들 수 없어 동시 변조에 대응할 수 있다.","MAC은 양측이 같은 키를 가지므로 누가 생성했는지 제3자에게 증명할 수 없어 부인방지를 제공하지 못한다. 전자서명과 동일한 서비스가 아니다."],"rel":["4-5"]},{"n":62,"s":"s4","q":"BLP에 대한 설명으로 옳지 않은 것은?","c":["BLP 모델이 개발된 주요 목적은 정보의 비밀성과 무결성 보호에 있다.","모든 주체와 객체에는 보안 레이블이 부여되며 보안 레이블에 의해 접근이 통제된다.","주체가 객체에 정보를 기록(write)하려 할 때 *(star) 규칙이 적용되며 객체의 보안 레이블이 주체의 보안 레이블을 지배하는 경우 기록(write)이 허용된다.","주체가 객체에 포함된 정보를 조회(read)할 때 simple security 규칙이 적용되며 주체의 보안 레이블이 객체의 보안 레이블을 지배하는 경우 조회(read)가 허용된다."],"a":0,"e":"BLP(Bell-LaPadula)는 군사 환경의 기밀성(비밀성) 보호만을 목적으로 한 모델이며, 무결성 보호는 Biba 모델의 목적이다. BLP는 No Read Up(simple security)과 No Write Down(*-property) 규칙을 적용한다.","ce":["BLP는 군사 환경의 기밀성(비밀성) 보호만을 목적으로 한 모델이며 무결성 보호는 Biba 모델의 목적이므로 틀렸다.","BLP는 모든 주체·객체에 보안 레이블(등급+범주)을 부여하고 레이블 비교로 접근을 통제하는 강제적 접근통제 모델이므로 옳다.","*-속성(No Write Down)에 따라 객체 레이블이 주체 레이블을 지배(같거나 높음)할 때만 쓰기가 허용되므로 옳다.","단순 보안 속성(No Read Up)에 따라 주체 레이블이 객체 레이블을 지배할 때만 읽기가 허용되므로 옳다."],"rel":["4-11"]},{"n":63,"s":"s4","q":"다음 지문에서 설명하는 대칭키 암호 공격방식은?","c":["선형 공격","차분 공격","통계적 분석","전수 공격"],"a":1,"e":"차분 공격(Differential Cryptanalysis)은 선택 평문 공격으로, 입력 평문 쌍의 차이가 암호문 쌍의 차이에 전파되는 확률 특성을 이용해 키를 추정한다(Biham·Shamir). 선형 공격은 기지 평문 공격으로 평문·암호문·키 비트 사이의 선형 근사식을 이용한다.","ce":["선형 공격은 평문·암호문·키 비트의 선형 근사식을 이용하는 기지 평문 공격(Matsui)으로, 두 평문의 차이를 이용하지 않는다.","차분 공격은 선택 평문 공격으로, 평문 쌍의 차이가 암호문 쌍의 차이로 전파되는 확률 특성을 분석해 키를 찾는다(Biham·Shamir).","통계적 분석은 암호문의 문자 빈도 등 통계 특성으로 평문을 추정하는 방식으로, 블록 쌍의 비트 차이를 이용하는 기법이 아니다.","전수 공격은 가능한 모든 키를 대입하는 방식으로 평문 차이 분석이 필요 없다."],"rel":["4-1"],"box":"일종의 선택된 평문공격법으로 두 개의 평문 블록들의 비트의 차이에 대하여 대응되는 암호문 블록들의 비트의 차이를 이용하여 사용된 비밀키를 찾아내는 방법이다."},{"n":64,"s":"s4","q":"다음 중 전자서명 알고리즘이 아닌 것은?","c":["DSA","KCDSA","ECDSA","A5"],"a":3,"e":"A5는 GSM 이동통신 음성 암호화에 쓰이는 스트림 암호다. DSA는 미국 전자서명 표준, KCDSA는 국내 표준 전자서명, ECDSA는 타원곡선 기반 DSA다.","ce":["DSA는 이산대수 문제 기반의 미국 전자서명 표준(FIPS 186)이다.","KCDSA는 한국형 인증서 기반 전자서명 알고리즘으로 국내 표준(TTA)이다.","ECDSA는 DSA를 타원곡선 군에서 구현한 전자서명 알고리즘으로, 짧은 키로 같은 안전성을 제공한다.","A5(A5/1·A5/2)는 GSM 휴대전화의 무선 구간 음성을 암호화하는 스트림 암호로 전자서명 알고리즘이 아니다."],"rel":["4-6","4-2"]},{"n":65,"s":"s4","q":"일회용 패스워드 생성방식은?","c":["시간 동기화 방식","질의/응답 방식","S/KEY 방식","이벤트 동기화 방식"],"a":1,"e":"질의/응답(Challenge-Response) 방식은 서버가 보낸 질의값을 토큰에 입력해 응답값을 만들므로 동기화가 필요 없지만, 사용자가 질의값을 입력하는 불편과 서버의 질의값 관리 부담이 있다. 시간·이벤트 동기화 방식은 시각이나 카운터를 서버와 토큰이 맞춰야 한다.","ce":["시간 동기화 방식은 토큰과 서버의 시각을 기준값으로 OTP를 만들므로 시간 동기화가 필수여서 '동기화 불필요'와 맞지 않는다.","질의/응답 방식은 서버가 준 질의값을 토큰에 입력해 응답값을 만들므로 동기화가 필요 없고, 서버는 사용자별 질의값을 관리해야 하는 부담이 있다.","S/KEY는 비밀값에 해시를 반복 적용한 해시 체인을 역순으로 사용하는 방식으로, 사용자가 질의값을 토큰에 입력하는 구조가 아니다.","이벤트 동기화 방식은 인증 횟수 카운터를 토큰과 서버가 맞춰야 하므로 동기화 기준 정보가 존재한다."],"rel":["4-8"],"box":"- 사용자가 OTP 인증 요청 시 인증서버로부터 받은 질의값을 직접 OTP 토큰에 입력하여 응답값(난수 형태)을 생성한다.\n- OTP 토큰과 인증서버 간에 동기화해야 할 기준 정보가 없기 때문에, 동기화할 필요가 없다.\n- 사용자와 서버 간에 상호 인증을 제공하는 방식으로 쉽게 확장이 가능하다.\n- 인증서버도 해당 사용자의 질의값을 관리해야 하는 부담이 있다."},{"n":66,"s":"s4","q":"타원곡선 암호를 적용하기에 적합한 공개키 암호 알고리즘은?","c":["ElGamal","Rabin","HIGHT","RSA"],"a":0,"e":"ElGamal은 이산대수 문제 기반이므로 유한체의 곱셈군을 타원곡선 점 군으로 바꾸어 EC-ElGamal로 그대로 적용할 수 있다(ECDSA·ECDH도 같은 원리). RSA·Rabin은 소인수분해 문제 기반이라 타원곡선 적용 대상이 아니며, HIGHT는 국산 경량 블록암호다.","ce":["ElGamal은 이산대수 문제 기반이라 유한체 곱셈군을 타원곡선 점 덧셈군으로 바꾼 EC-ElGamal로 그대로 적용할 수 있다.","Rabin은 제곱근 계산, 즉 소인수분해 문제 난해성에 기반하므로 타원곡선 이산대수 구조로 옮겨 적용하는 대상이 아니다.","HIGHT는 국내 개발 64비트 경량 블록 암호(대칭키)로 공개키 알고리즘이 아니다.","RSA는 큰 수의 소인수분해 문제에 기반해 타원곡선 군 연산과 구조가 맞지 않는다."],"rel":["4-4"]},{"n":67,"s":"s4","q":"사용자 인증방식 중 동일한 기술로 바르게 짝지어진 것은?","c":["[㉠, ㉢, ㉣] [㉡, ㉤, ㉥]","[㉠, ㉡, ㉢] [㉣, ㉤, ㉥]","[㉠, ㉣, ㉤] [㉡, ㉢, ㉥]","[㉠, ㉣, ㉥] [㉡, ㉢, ㉤]"],"a":2,"e":"홍채·음성·지문은 사용자의 신체적·행위적 특징을 이용하는 존재 기반(Something you are) 생체인증이다. 스마트카드·OTP·USB 토큰은 사용자가 가진 매체를 이용하는 소유 기반(Something you have) 인증이다.","ce":["홍채·음성은 생체(존재 기반)지만 OTP는 소유 기반이 섞였고, 스마트카드·USB 토큰(소유)과 지문(생체)도 섞여 있다.","홍채(생체)와 스마트카드·OTP(소유)가 한 묶음이고, 음성·지문(생체)과 USB 토큰(소유)이 한 묶음이어서 분류가 틀렸다.","홍채·음성·지문은 사용자 신체·행동 특징을 이용하는 존재 기반 인증, 스마트카드·OTP·USB 토큰은 소지한 매체를 이용하는 소유 기반 인증으로 올바르게 묶였다.","USB 토큰(소유 기반)이 생체 묶음에, 지문(존재 기반)이 소유 묶음에 들어가 서로 바뀌었다."],"rel":["4-8"],"box":"㉠ 홍채   ㉡ 스마트 카드   ㉢ OTP\n㉣ 음성   ㉤ 지문         ㉥ USB 토큰"},{"n":68,"s":"s4","q":"강제적 접근통제의 특징과 가장 거리가 먼 것은?","c":["보안관리자 주도하에 중앙 집중적 관리가 가능","접근규칙 수가 적어 통제가 용이","이직률이 높은 기업에 적합","사용자와 데이터에 보안 등급을 부여하여 적용"],"a":2,"e":"MAC(강제적 접근통제)은 관리자가 주체·객체의 보안 등급(레이블)을 중앙에서 부여해 규칙대로 통제한다. 인사 이동·이직이 잦은 조직에는 사용자 대신 역할에 권한을 부여하는 RBAC(역할기반 접근통제)가 적합하다.","ce":["MAC은 보안관리자가 주체·객체의 보안 등급을 중앙에서 부여·관리하므로 특징에 해당한다.","MAC은 등급 비교라는 소수의 규칙(No Read Up 등)으로 통제하므로 규칙 수가 적고 통제가 명확하다는 특징이 있다.","인사 이동·이직이 잦은 조직에는 개인 대신 역할에 권한을 부여하는 RBAC가 적합하며, MAC의 특징이 아니다.","MAC은 사용자에게 비밀취급인가, 데이터에 보안 등급(레이블)을 부여해 비교하므로 특징에 해당한다."],"rel":["4-10"]},{"n":69,"s":"s4","q":"인증서 관리와 관련한 설명으로 틀린 것은?","c":["인증서 폐지 요청은 인증서 소유자에 의해서만 가능함","폐지된 인증서에 대한 목록을 공개하고 디렉터리에 보관","인증서 폐지 목록은 주기적으로 또는 실시간으로 생성할 수 있음","OCSP로 인증서 유효성 검증을 할 수 있음"],"a":0,"e":"인증서 폐지는 소유자 요청뿐 아니라 개인키 노출, 소속 변경, 부정 발급 등 사유가 있으면 인증기관(CA)이나 소유자의 대리인도 요청·처리할 수 있다. 폐지 정보는 CRL로 디렉터리에 공개하거나 OCSP로 실시간 조회한다.","ce":["인증서 폐지는 소유자뿐 아니라 개인키 노출·부정 발급·자격 상실 등의 사유가 있으면 CA나 권한 있는 대리인도 요청·처리할 수 있으므로 틀렸다.","폐지된 인증서는 CRL로 만들어 LDAP 디렉터리 등에 공개·보관해 누구나 확인할 수 있게 하므로 옳다.","CRL은 정해진 주기로 발행하거나, 델타 CRL·OCSP 등으로 실시간에 가깝게 폐지 정보를 제공할 수 있어 옳다.","OCSP는 개별 인증서의 상태(유효·폐지·알 수 없음)를 실시간으로 질의해 유효성을 검증하는 프로토콜이므로 옳다."],"rel":["4-7"]},{"n":70,"s":"s4","q":"블록 암호 종류에 해당되지 않는 것은?","c":["3DES","AES","SEED","RC4"],"a":3,"e":"RC4는 바이트 단위로 키 스트림을 생성해 XOR하는 스트림 암호로 WEP, 초기 SSL 등에 쓰였다. 3DES(64비트 블록), AES(128비트 블록), SEED(128비트 블록)는 블록 암호다.","ce":["3DES는 64비트 블록을 DES로 3회(암호화-복호화-암호화) 처리하는 블록 암호다.","AES는 128비트 블록, 128/192/256비트 키를 사용하는 미국 표준 블록 암호다.","SEED는 KISA가 개발한 128비트 블록 암호(16라운드 Feistel)다.","RC4는 키로 의사난수 키 스트림을 만들어 평문과 바이트 단위로 XOR하는 스트림 암호이므로 블록 암호가 아니다."],"rel":["4-2"]},{"n":71,"s":"s4","q":"해시함수 h( )에 대한 설명 중 틀린 것은?","c":["해시함수는 임의의 길이 메시지를 고정된 길이의 해시값으로 출력한다.","해시함수는 주어진 결과값으로부터 입력값을 찾는 것이 계산적으로 어렵다.","h(x₁)=h(x₂)가 임의의 x₁≠x₂를 찾는 것은 계산적으로 어렵다.","x₁과 h(x₁) 그리고 h( ) 함수를 알고 있다면 h(x₁)=h(x₂)인 임의의 x₂를 찾는 것이 계산적으로 용이하다."],"a":3,"e":"주어진 x₁에 대해 같은 해시값을 갖는 다른 x₂를 찾기 어려워야 한다는 성질이 제2 역상 저항성(약한 충돌 저항성)이므로 ④는 틀린 설명이다. ②는 역상 저항성(일방향성), ③은 충돌 저항성이다.","ce":["해시함수는 임의 길이 입력을 고정 길이 출력(예: SHA-256은 256비트)으로 압축하므로 옳다.","주어진 해시값으로부터 입력을 찾기 어려운 역상 저항성(일방향성)을 가져야 하므로 옳다.","같은 해시값을 갖는 서로 다른 두 입력을 찾기 어려워야 한다는 충돌 저항성(강한 충돌 저항성)이므로 옳다.","x₁과 h(x₁)을 알아도 같은 해시값의 다른 x₂를 찾기 어려워야 하는 것이 제2 역상 저항성이므로 '용이하다'는 틀렸다."],"rel":["4-5"]},{"n":72,"s":"s4","q":"국내에서 개발된 암호 알고리즘이 아닌 것은?","c":["AES","ARIA","SEED","LEA"],"a":0,"e":"AES는 벨기에의 Rijndael 알고리즘이 2001년 미국 NIST 표준으로 채택된 것이다. SEED(KISA, 1999), ARIA(국가보안기술연구소 등, 2004), LEA(국가보안기술연구소, 2013 경량 암호)는 국내 개발 블록 암호다.","ce":["AES는 벨기에 연구자의 Rijndael이 2001년 미국 NIST 표준(FIPS 197)으로 채택된 것으로 국내 개발이 아니다.","ARIA는 학계·국가보안기술연구소 등이 개발해 2004년 국가표준(KS)으로 제정된 국내 128비트 블록 암호다.","SEED는 1999년 KISA 주도로 개발된 국내 128비트 블록 암호다.","LEA는 국가보안기술연구소가 개발한 국내 128비트 경량 블록 암호다."],"rel":["4-2"]},{"n":73,"s":"s4","q":"공격자는 전송 중인 메시지와 MAC 값을 중간에 가로채 가지고 있다가 반복하여 재전송함으로써 잘못된 반복 처리가 가능하다. 이를 방지하기 위한 방법이 아닌 것은?","c":["순서번호","타임스탬프","CBC","비표"],"a":2,"e":"재전송(Replay) 공격은 메시지마다 순서번호, 타임스탬프, 비표(Nonce)를 포함시켜 이전 메시지의 재사용을 탐지함으로써 방지한다. CBC는 블록 암호 운영 모드로 재전송 방지 수단이 아니다.","ce":["메시지마다 증가하는 순서번호를 넣고 MAC에 포함하면, 이미 받은 번호의 메시지를 재전송 공격으로 판별할 수 있다.","타임스탬프를 MAC 계산에 포함하면 허용 시간 범위를 벗어난 과거 메시지를 거부해 재전송을 방지한다.","CBC는 이전 암호문 블록을 다음 평문과 XOR하는 블록 암호 운영 모드로, 메시지의 재사용 여부를 판별하는 기능이 없다.","비표(Nonce)는 한 번만 쓰이는 임의값으로, 매번 새 값을 넣게 하면 이전 메시지를 그대로 재전송해도 탐지된다."],"rel":["4-5"]},{"n":74,"s":"s4","q":"다음 지문에서 설명하고 있는 접근통제 모델은?","c":["비바모델","상태머신 모델","클락-윌슨 모델","벨-라파듈라 모델"],"a":3,"e":"벨-라파듈라(BLP) 모델은 최초의 수학적 기밀성 모델로 상위 등급 읽기 금지(No Read Up)와 하위 등급 쓰기 금지(No Write Down)를 규정한다. 비바 모델은 무결성 모델로 No Read Down, No Write Up을 적용하며, 클락-윌슨은 상업용 무결성 모델이다.","ce":["비바 모델은 무결성 모델로 No Read Down·No Write Up을 규정하며, '높은 등급을 읽을 수 없다'는 기밀성 규칙과 반대다.","상태머신 모델은 시스템이 항상 안전한 상태에서 안전한 상태로만 전이함을 보이는 추상 개념으로, BLP 등이 이를 바탕으로 한다.","클락-윌슨 모델은 잘 구성된 트랜잭션과 직무분리로 무결성을 보장하는 상업용 모델이다.","벨-라파듈라 모델은 최초의 수학적 정보흐름(기밀성) 모델로, 주체가 상위 등급 데이터를 읽지 못하게(No Read Up) 한다."],"rel":["4-11"],"box":"- 허가되지 않은 방식의 접근을 방지하는 모델이다.\n- 정보흐름 모델 최초의 수학적 모델이다.\n- 주체는 보다 높은 보안 수준의 데이터를 읽을 수 없다."},{"n":75,"s":"s4","q":"인증서의 유효성 확인이 주 기능인 것은?","c":["PKI","CA","RA","CRL"],"a":3,"e":"CRL(Certificate Revocation List)은 폐지된 인증서 목록으로, 인증서가 폐지되었는지 확인해 유효성을 검증하는 데 사용된다. CA는 인증서 발급·관리, RA는 사용자 신원 확인과 등록을 담당하며, PKI는 이들을 포괄하는 기반 구조다.","ce":["PKI는 CA·RA·디렉터리·인증서 정책 등을 포괄하는 공개키 기반 구조 전체를 가리킬 뿐 유효성 확인이라는 단일 기능이 아니다.","CA는 인증서를 발급·서명하고 폐지 목록을 발행하는 기관으로, 주 기능은 발급·관리다.","RA는 인증서 신청자의 신원을 확인하고 등록을 대행하는 기관이다.","CRL은 CA가 서명해 공개하는 폐지 인증서 목록으로, 인증서가 폐지되었는지 대조해 유효성을 확인하는 데 쓰인다."],"rel":["4-7"]},{"n":76,"s":"s4","q":"다음 보기 중 FDS에 해당하는 통제는?","c":["예방 통제","탐지 통제","교정 통제","복구 통제"],"a":1,"e":"FDS(Fraud Detection System, 이상금융거래탐지시스템)는 거래 정보를 분석해 평소와 다른 이상 거래를 실시간으로 탐지하는 탐지 통제다. 예방 통제는 사전 차단(접근통제 등), 교정 통제는 발생 후 원인 제거와 재발 방지에 해당한다.","ce":["예방 통제는 접근통제·암호화처럼 사고가 일어나기 전에 막는 통제로, 이미 발생 중인 이상 거래를 찾아내는 FDS와 성격이 다르다.","FDS는 접속 정보·거래 패턴을 분석해 평소와 다른 이상 금융거래를 실시간으로 찾아내 경보·추가인증을 요구하는 탐지 통제다.","교정 통제는 사고 발생 후 원인을 제거하고 재발을 막는 통제(패치 적용, 절차 개선 등)다.","복구 통제는 백업 복원·재해복구처럼 손상된 자원을 정상 상태로 되돌리는 통제다."],"rel":["3-13"]},{"n":77,"s":"s4","q":"생체인증 요구사항의 특성에 해당되지 않는 것은?","c":["유일성","보편성","지속성","시간의존성"],"a":3,"e":"생체인증 특징의 요구사항은 보편성(누구나 가짐), 유일성(개인마다 다름), 영속성·지속성(시간에 따라 변하지 않음), 획득성(측정 용이) 등이다. 시간에 따라 달라지는 시간의존성은 요구사항과 반대된다.","ce":["유일성은 사람마다 생체 특징이 달라 구별할 수 있어야 한다는 요구사항이다.","보편성은 모든 사람이 그 생체 특징을 가지고 있어야 한다는 요구사항이다.","지속성(영속성)은 생체 특징이 시간이 지나도 변하지 않아야 한다는 요구사항이다.","시간의존성은 시간에 따라 특징이 변한다는 뜻으로 지속성 요구와 정반대이므로 생체인증 요구사항이 아니다."],"rel":["4-8"]},{"n":78,"s":"s4","q":"블록 암호 종류에 해당되지 않는 것은?","c":["3DES","AES","SEED","RC4"],"a":3,"e":"RC4는 가변 길이 키로 의사난수 키 스트림을 생성해 평문과 XOR하는 스트림 암호다. 3DES, AES, SEED는 고정 크기 블록 단위로 암호화하는 블록 암호다.","ce":["3DES는 DES를 세 번 적용해 64비트 블록 단위로 암호화하는 블록 암호다(70번과 동일 문항).","AES는 128비트 고정 블록을 SPN 구조로 처리하는 블록 암호다.","SEED는 128비트 블록을 Feistel 구조로 처리하는 국산 블록 암호다.","RC4는 블록 단위가 아니라 바이트 단위 키 스트림을 평문에 XOR하는 스트림 암호이므로 블록 암호가 아니다."],"rel":["4-2"],"flag":"70번과 동일 문항(원문 그대로)"},{"n":79,"s":"s4","q":"인가된 사용자가 조직의 정보자산에 적시에 접근하여 업무를 수행할 수 있도록 유지하는 것을 목표로 하는 정보 보호 요소는?","c":["기밀성(confidentiality)","무결성(integrity)","가용성(availability)","인증성(authentication)"],"a":2,"e":"가용성은 인가된 사용자가 필요한 시점에 정보와 시스템을 사용할 수 있도록 보장하는 것으로, DoS 공격이 대표적 위협이다. 기밀성은 인가되지 않은 노출 방지, 무결성은 인가되지 않은 변경 방지다.","ce":["기밀성은 인가되지 않은 사람에게 정보가 노출되지 않도록 하는 것으로, '적시 접근 보장'과는 다른 목표다.","무결성은 인가되지 않은 방법으로 정보가 변경·파괴되지 않도록 보장하는 것이다.","가용성은 인가된 사용자가 필요한 시점에 정보·시스템을 사용할 수 있도록 보장하는 것으로, DoS 공격이 대표적 위협이다.","인증성은 사용자·메시지 출처가 주장한 대로 진짜임을 확인하는 성질로 적시 접근 유지와 다르다."],"rel":["5-1"]},{"n":80,"s":"s4","q":"어떠한 사용자가 실제 사람인지 컴퓨터 프로그램인지 구별하기 위한 목적으로 사용되는 것은?","c":["무결성 점검 도구","PKI","전자서명","CAPTCHA"],"a":3,"e":"CAPTCHA(Completely Automated Public Turing test to tell Computers and Humans Apart)는 왜곡된 문자·이미지 인식 등 사람은 쉽게 풀고 프로그램은 풀기 어려운 과제로 자동화 봇을 구별한다. 계정 대량 생성, 무차별 로그인 시도 방지에 쓰인다.","ce":["무결성 점검 도구(Tripwire 등)는 파일 해시를 비교해 변조 여부를 확인하는 도구로 사람과 봇을 구별하지 않는다.","PKI는 인증서로 공개키 소유자를 증명하는 기반 구조로, 상대가 사람인지 프로그램인지 판별하지 못한다.","전자서명은 서명자 인증·무결성·부인방지를 제공하지만 서명 주체가 자동화 프로그램인지 사람인지는 구별하지 않는다.","CAPTCHA는 왜곡된 문자·이미지 인식 등 사람은 풀기 쉽고 프로그램은 풀기 어려운 과제로 자동화 봇을 구별하는 튜링 테스트다."]},{"n":81,"s":"s5","q":"다음 빈 칸에 들어가야 할 내용으로 올바르게 나열된 것은?","c":["㉠ 프레임워크 ㉡ 정보자산 식별 ㉢ 위험관리 ㉣ 정보보호 정책","㉠ 정보보호 정책 ㉡ 취약점 ㉢ 정보자산 식별 ㉣ 프레임워크","㉠ 프레임워크 ㉡ 취약점 ㉢ 정보자산 식별 ㉣ 정보보호 정책","㉠ 정보보호 정책 ㉡ 정보자산 식별 ㉢ 위험관리 ㉣ 프레임워크"],"a":3,"e":"구 ISMS의 정보보호관리과정 5단계는 정보보호 정책 수립 및 조직 구성, 범위 설정 및 정보자산 식별, 위험관리, 구현, 사후관리이며, 이를 정보보호관리 프레임워크로 수립·운영한다(2018년 ISMS-P 통합 이후 관리체계 수립 및 운영 16개 항목으로 개편).","ce":["㉠에 프레임워크, ㉣에 정보보호 정책이 들어가 위치가 뒤바뀌었다. 1단계는 '정보보호 정책 수립 및 조직 구성'이고 전체 체계가 '관리 프레임워크'다.","㉠·㉣은 맞지만 ㉡에 취약점, ㉢에 정보자산 식별을 넣어 틀렸다. 범위 설정과 함께 하는 것은 정보자산 식별, 3단계는 위험관리다.","㉠·㉣이 뒤바뀌었고 ㉡·㉢도 틀렸다(범위 설정 및 정보자산 식별 → 위험관리).","구 ISMS 5단계는 정보보호 정책 수립 및 조직 구성 → 범위 설정 및 정보자산 식별 → 위험관리 → 구현 → 사후관리이며, 이를 정보보호관리 프레임워크로 수립한다."],"rel":["5-12","5-11"],"box":"정보보호관리를 이행하기 위해서 조직은 ( ㉠ ) 및 조직수립, 범위설정 및 ( ㉡ ), ( ㉢ ), 구현, 사후관리활동으로 구성된 5단계의 논리적이고 체계적인 정보보호관리 ( ㉣ )를 수립하고, 기획, 관리하여야 한다."},{"n":82,"s":"s5","q":"조직의 정보자산을 보호하기 위하여 정보자산에 대한 위협과 취약점을 분석하여 비용 대비 적절한 보호 대책을 마련함으로써 위험을 감수할 수 있는 수준으로 유지하는 일련의 과정은?","c":["업무 연속성 계획","위험관리","정책과 절차","탐지 및 복구 통제"],"a":1,"e":"위험관리는 자산·위협·취약점을 분석해 위험을 평가하고, 비용 대비 효과적인 보호대책으로 위험을 수용 가능한 수준(DoA) 이하로 유지하는 과정이다. 업무 연속성 계획은 재해·장애 시 핵심 업무를 지속·복구하기 위한 계획이다.","ce":["업무 연속성 계획(BCP)은 재해·장애 발생 시 핵심 업무를 지속하고 복구하기 위한 계획으로, 위협·취약점 분석으로 위험을 수용 수준으로 유지하는 일련의 과정 자체는 아니다.","위험관리는 자산·위협·취약점을 분석해 위험을 평가하고 비용 대비 효과적인 보호대책으로 위험을 수용 가능한 수준(DoA)으로 유지하는 과정이다.","정책과 절차는 위험관리 결과를 반영해 조직의 보호 방향과 수행 방법을 문서화한 것으로, 분석·평가 과정 전체를 뜻하지 않는다.","탐지·복구 통제는 위험관리 결과 선택되는 개별 보호대책의 유형일 뿐 과정 전체의 명칭이 아니다."],"rel":["5-2"]},{"n":83,"s":"s5","q":"「정보통신망 이용 촉진 및 정보보호 등에 관한 법률」에서 \"해킹, 컴퓨터바이러스, 논리폭탄, 메일폭탄, 서비스 거부 또는 고출력 전자기파 등의 방법으로 정보통신망 또는 이와 관련된 정보시스템을 공격하는 행위를 하여 발생한 사태\"로 정의된 용어는?","c":["침해사고","보안사고","물리적 공격","사이버 공격"],"a":0,"e":"정보통신망법 제2조 제1항 제7호는 해킹·컴퓨터바이러스·논리폭탄·메일폭탄·서비스 거부·고출력 전자기파 등으로 정보통신망 또는 관련 정보시스템을 공격해 발생한 사태를 '침해사고'로 정의한다. 보안사고·사이버 공격은 이 법의 정의 용어가 아니다.","ce":["정보통신망법 제2조 제1항 제7호는 해킹·바이러스·논리폭탄·메일폭탄·서비스 거부·고출력 전자기파 등으로 정보통신망·정보시스템을 공격해 발생한 사태를 '침해사고'로 정의한다.","'보안사고'는 일상적으로 쓰는 말이지만 정보통신망법 제2조의 정의 용어가 아니다.","고출력 전자기파가 포함되지만 법은 이를 공격 방법 중 하나로 열거할 뿐 '물리적 공격'이라는 용어로 정의하지 않는다.","'사이버 공격'은 일반적으로 쓰이는 표현일 뿐, 정보통신망법이 이 문구로 정의한 용어는 침해사고다(개정 여부 확인)."],"rel":["5-10"]},{"n":84,"s":"s5","q":"위험 분석에 대한 설명으로 옳지 않은 것은?","c":["자산의 식별된 위험을 처리하는 방안으로는 위험 수용, 위험 회피, 위험 전가 등이 있다.","자산의 가치 평가를 위해 자산구입비용, 자산유지보수비용 등을 고려할 수 있다.","자산의 적절한 보호를 위해 소유자와 책임소재를 지정함으로써 자산의 책임추적성을 보장받을 수 있다.","자산의 가치 평가 범위에 데이터베이스, 계약서, 시스템 유지보수 인력 등은 제외된다."],"a":3,"e":"위험 분석의 자산에는 하드웨어·소프트웨어뿐 아니라 데이터베이스·계약서 같은 정보자산과 유지보수 인력 등 인적 자산도 포함되어 가치를 평가해야 한다. 위험 처리 방안은 수용·회피·전가·감소이며, 자산별 소유자 지정은 책임추적성 확보에 필요하다.","ce":["식별된 위험은 수용·회피·전가·감소 중에서 처리 방안을 선택하므로 옳은 설명이다.","자산 가치는 구입 비용뿐 아니라 유지보수 비용, 대체 비용, 업무 영향 등을 고려해 평가할 수 있어 옳다.","자산마다 소유자와 책임자를 지정해야 보호 책임과 책임추적성이 확보되므로 옳다.","데이터베이스·계약서 같은 정보(문서) 자산과 유지보수 인력 같은 인적 자산도 자산 가치 평가 범위에 포함되므로 '제외된다'는 틀렸다."],"rel":["5-12","5-2"]},{"n":85,"s":"s5","q":"다음 지문은 업무연속성계획(BCP)의 접근 5단계 방법론에 따라 업무의 순서대로 작성되었다. 다음 중 빈 칸에 들어갈 용어의 순서가 가장 적합한 것은?","c":["㉠ 복구계획 수립 ㉡ 복구전략 개발 ㉢ 사업영향평가","㉠ 복구전략 개발 ㉡ 복구계획 수립 ㉢ 사업영향평가","㉠ 사업영향평가 ㉡ 복구계획 수립 ㉢ 복구전략 개발","㉠ 사업영향평가 ㉡ 복구전략 개발 ㉢ 복구계획 수립"],"a":3,"e":"BCP 5단계 방법론은 범위 설정·기획 → 사업영향평가(BIA, 핵심 업무와 RTO 도출) → 복구전략 개발 → 복구계획 수립 → 테스트 및 유지보수 순이다. 영향평가 결과가 있어야 전략을, 전략이 정해져야 세부 복구계획을 수립할 수 있다.","ce":["복구계획을 먼저 세우고 사업영향평가를 마지막에 두면, 핵심 업무와 복구 목표시간(RTO)도 모르는 상태에서 계획을 세우는 셈이라 순서가 거꾸로다.","복구전략 개발이 사업영향평가보다 앞설 수 없다. 영향평가로 우선순위와 RTO를 정해야 전략을 선택할 수 있다.","사업영향평가가 첫 단계인 것은 맞지만, 복구계획 수립은 복구전략이 결정된 뒤에 세우는 것이므로 ㉡·㉢ 순서가 뒤바뀌었다.","BCP 5단계는 범위 설정·기획 → 사업영향평가(BIA) → 복구전략 개발 → 복구계획 수립 → 테스트·유지보수 순이다."],"rel":["5-3"],"box":"프로젝트의 범위·설정·기획 → ( ㉠ ) → ( ㉡ ) → ( ㉢ ) → 프로젝트의 수행 테스트 및 유지 보수"},{"n":86,"s":"s5","q":"다음 제도는?","c":["CC","ISMS","PIMS","ISMS-P"],"a":3,"e":"ISMS-P(정보보호 및 개인정보보호 관리체계 인증)는 기존 ISMS와 PIMS를 통합해 2018년 11월부터 시행된 제도로, 정보보호와 개인정보보호 조치 모두의 인증기준 적합성을 증명한다. ISMS는 정보보호만, PIMS는 개인정보보호만 대상이었고, CC는 정보보호제품 평가 기준이다.","ce":["CC(Common Criteria)는 정보보호 제품의 보안 기능·보증 수준을 평가하는 국제 공통평가기준으로, 조직의 관리체계 인증이 아니다.","ISMS는 정보보호 관리체계만을 인증 대상으로 하므로, 지문처럼 개인정보보호까지 포함한 인증 제도는 아니다.","PIMS는 개인정보보호 관리체계만을 인증하던 제도로, 2018년 ISMS-P로 통합되었다.","ISMS-P는 ISMS와 PIMS를 통합해 2018년 11월 시행된 제도로, 정보보호와 개인정보보호 조치가 인증기준에 적합함을 KISA 또는 인증기관이 증명한다."],"rel":["5-11","5-5"],"box":"이것은 정보보호 및 개인정보보호를 위한 일련의 조치와 활동이 인증기준에 적합함을 한국인터넷진흥원 또는 인증기관이 증명하는 제도이다."},{"n":87,"s":"s5","q":"정보보호 최고책임자에 대한 다음의 설명 중 적절하지 못한 것은?","c":["정보통신서비스 제공자는 임원급의 정보보호 최고책임자를 지정하고 과학기술정보통신부장관에게 신고하여야 한다.","정보보호 최고책임자는 법에서 정한 업무 이외에도 기업의 형편에 따라 다른 업무를 겸직할 수 있다.","정보통신서비스 제공자는 침해사고에 대한 공동 예방 및 대응과 필요한 정보의 교류 등의 사업을 수행하기 위하여 정보보호 최고책임자를 구성원으로 하는 정보보호 최고책임자 협의회를 구성·운영할 수 있다.","정보보호 최고책임자는 정보보호관리체계의 수립 및 관리·운영, 정보보호 취약점 분석·평가 및 개선, 침해사고의 예방 및 대응 등의 업무를 총괄한다."],"a":1,"e":"정보통신망법 제45조의3 개정(2019년 6월 시행)으로 일정 규모 이상(자산총액 5조원 이상 또는 ISMS 의무대상 중 자산총액 5천억원 이상) 사업자의 CISO는 정보보호 업무 외 다른 업무의 겸직이 금지되어 '형편에 따라 겸직 가능'은 부적절하다. 임원급 지정·신고, CISO 협의회, 총괄 업무는 법 조문 내용이다(개정 여부 확인).","ce":["정보통신망법 제45조의3에 따라 정보통신서비스 제공자는 임원급 CISO를 지정하고 과학기술정보통신부장관에게 신고해야 하므로 옳다(개정 여부 확인).","2018년 개정(2019년 6월 시행)으로 자산총액 등 일정 기준 이상 사업자의 CISO는 정보보호 외 다른 업무 겸직이 금지되어, '형편에 따라 겸직 가능'은 부적절하다(개정 여부 확인).","침해사고 공동 예방·대응과 정보 교류를 위해 CISO를 구성원으로 하는 정보보호 최고책임자 협의회를 구성·운영할 수 있다는 규정이 있어 옳다.","CISO는 정보보호관리체계 수립·운영, 취약점 분석·평가·개선, 침해사고 예방·대응 등을 총괄하도록 법에 규정되어 옳다."],"rel":["5-12"]},{"n":88,"s":"s5","q":"개인정보 안전성 확보를 위한 암호화에 대한 설명으로 적절하지 않은 것은?","c":["인터넷 구간 및 인터넷 구간과 내부망의 중간 지점(DMZ)에 고유식별정보를 저장하는 경우에는 이를 암호화하여야 한다.","비밀번호 및 바이오정보는 암호화하여 저장하여야 한다. 다만 비밀번호를 저장하는 경우에는 양방향 암호화하여 저장하여야 한다.","고유식별정보, 비밀번호, 바이오정보를 정보통신망을 통하여 송신하거나 보조저장매체 등을 통하여 전달하는 경우에는 이를 암호화하여야 한다.","업무용 컴퓨터 또는 모바일 기기에 고유식별정보를 저장하여 관리하는 경우 상용 암호화 소프트웨어 또는 안전한 암호화 알고리즘을 사용하여 암호화한 후 저장하여야 한다."],"a":1,"e":"개인정보의 안전성 확보조치 기준은 비밀번호를 복호화되지 않도록 일방향 암호화(해시)하여 저장하도록 규정한다. 바이오정보는 양방향 암호화가 허용되며, DMZ 저장·전송 시 암호화와 업무용 PC 저장 시 암호화는 기준에 맞는 설명이다(개정 여부 확인).","ce":["인터넷 구간이나 DMZ에 고유식별정보를 저장할 때는 반드시 암호화하도록 안전성 확보조치 기준에 규정되어 있어 옳다.","비밀번호는 복호화할 수 없도록 일방향 암호화(해시)해 저장해야 하므로 '양방향 암호화'는 틀렸다. 양방향 암호화 저장은 바이오정보 등에 해당한다.","고유식별정보·비밀번호·바이오정보를 정보통신망으로 송신하거나 보조저장매체로 전달할 때는 암호화해야 하므로 옳다.","업무용 컴퓨터·모바일 기기에 고유식별정보를 저장할 때는 상용 암호화 소프트웨어나 안전한 알고리즘으로 암호화해야 하므로 옳다(개정 여부 확인)."],"rel":["5-9"]},{"n":89,"s":"s5","q":"A사의 개인정보처리자는 A사에서 수집한 개인정보를 사용 목적이 종료되어 파기하고자 한다. 이때 파기하기 위한 조치사항으로 부적절한 것은?","c":["하드디스크의 개인정보를 파기하기 위해 하이레벨 포맷 수행","데이터가 복원되지 않도록 초기화 또는 덮어쓰기 수행","전용 소자장비를 이용하여 개인정보 파기 수행","기록물, 인쇄물, 서면, 그 밖의 기록매체의 일부만 파기할 경우 해당 부분을 마스킹, 천공 등으로 삭제"],"a":0,"e":"하이레벨(빠른) 포맷은 파일 시스템 정보만 초기화하므로 복구 도구로 데이터를 되살릴 수 있어 파기 방법으로 부적절하다. 개인정보는 복원 불가능하도록 로우레벨 포맷·덮어쓰기(와이핑)·디가우저(소자)·물리적 파괴로 파기하고, 일부 파기 시 마스킹·천공을 사용한다.","ce":["하이레벨(빠른) 포맷은 파일시스템 메타데이터만 초기화하고 실제 데이터는 남아 복구 도구로 되살릴 수 있어 파기 방법으로 부적절하다.","전체 영역을 초기화하거나 무작위 값으로 덮어쓰면 기존 데이터를 복원할 수 없게 되므로 적절한 파기 방법이다.","디가우저(전용 소자장비)는 강한 자기장으로 자기 매체의 기록을 영구 삭제하므로 적절한 파기 방법이다.","매체의 일부만 파기할 때 해당 부분을 마스킹·천공 등으로 삭제하는 것은 표준 개인정보 보호지침이 정한 방법이다."],"rel":["5-9"]},{"n":90,"s":"s5","q":"침해사고 등이 발생한 경우 클라우드서비스 제공자의 의무로 적절하지 않은 것은?","c":["클라우드컴퓨팅서비스 제공자는 이용자 정보가 유출된 때에는 즉시 그 사실을 과학기술정보통신부장관에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 사전예고 없이 대통령령으로 정하는 기간 이상 서비스 중단이 발생한 때에는 지체 없이 그 사실을 과학기술정보통신부장관에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 이용자 정보가 유출된 때에는 지체 없이 그 사실을 해당 이용자에게 알려야 한다.","클라우드컴퓨팅서비스 제공자는 「정보통신망법」에 따른 침해사고가 발생한 때에는 지체 없이 그 사실을 해당 이용자에게 알려야 한다."],"a":1,"e":"클라우드컴퓨팅법 제25조에 따라 사전예고 없는 일정 기간 이상의 서비스 중단은 지체 없이 '이용자'에게 알려야 하는 사항이다. 이용자 정보 유출 시에는 이용자에게 알리고 과학기술정보통신부장관에게도 알려야 하며, 침해사고 발생 시에는 이용자에게 알려야 한다(개정 여부 확인).","ce":["클라우드컴퓨팅법 제25조 제2항은 이용자 정보 유출 시 즉시 그 사실을 과학기술정보통신부장관에게 알리도록 규정하므로 옳다(개정 여부 확인).","사전예고 없는 일정 기간 이상의 서비스 중단은 지체 없이 '이용자'에게 알릴 사항이며, 장관 통지 의무 대상으로 규정된 것은 이용자 정보 유출이다.","이용자 정보가 유출된 때에는 지체 없이 해당 이용자에게 알려야 하므로 옳다.","정보통신망법상 침해사고가 발생한 때에는 지체 없이 해당 이용자에게 알려야 하므로 옳다."],"rel":["5-10"]},{"n":91,"s":"s5","q":"개인정보보호 원칙에 대한 설명으로 올바르지 않은 것은?","c":["개인정보의 처리 목적에 필요한 범위에서 적합하게 개인정보를 처리해야 한다.","개인정보의 처리 목적에 필요한 범위에서 개인정보의 정확성, 완전성 및 최신성이 보장되도록 해야 한다.","정보주체의 사생활 침해를 최소화하기 위해 개인정보의 익명처리가 가능한 경우에도 개인정보를 식별하여 처리해야 한다.","개인정보 처리방침 등 개인정보의 처리에 관한 사항을 공개해야 한다."],"a":2,"e":"개인정보보호법 제3조는 개인정보를 익명으로 처리하여도 목적을 달성할 수 있는 경우 익명으로 처리하도록 노력해야 한다고 규정한다(2020년 개정으로 '익명 또는 가명'). 목적 범위 내 적합한 처리, 정확성·완전성·최신성 보장, 처리방침 공개는 법상 원칙이다.","ce":["처리 목적에 필요한 범위에서 적합하게 개인정보를 처리해야 한다는 것은 개인정보보호법 제3조의 목적 적합성 원칙으로 옳다.","처리 목적 범위에서 정확성·완전성·최신성을 보장해야 한다는 것은 제3조의 정확성 원칙으로 옳다.","제3조는 익명으로 처리해도 목적을 달성할 수 있으면 익명 처리하도록 규정하므로 '익명처리가 가능해도 식별해 처리'는 틀렸다(2020년 개정으로 익명·가명 처리 원칙).","개인정보 처리방침 등 처리에 관한 사항을 공개해야 한다는 것은 제3조의 공개 원칙으로 옳다."],"rel":["5-8"]},{"n":92,"s":"s5","q":"다음 중 「개인정보보호법」상 정보주체의 동의를 받아야 개인정보를 수집·이용할 수 있는 경우는?","c":["경력직 직원의 채용을 위해 지원자의 종교, 질병, 범죄경력 등의 개인정보를 수집·이용한 경우","개인정보처리자가 도난 또는 화재 예방을 위하여 자재 창고 앞에 CCTV를 설치한 경우","소비자가 주문한 세탁기를 배달하기 위하여 소비자의 집 주소와 전화번호를 수집·이용한 경우","교통사고로 인해 정보주체가 의식이 없는 상태에서 급박한 수술을 위해 보호자의 전화번호를 수집·이용한 경우"],"a":0,"e":"종교·건강(질병)·범죄경력은 민감정보로, 제23조에 따라 다른 개인정보와 별도로 정보주체의 동의를 받거나 법령 근거가 있어야 처리할 수 있다. ②는 제25조의 시설안전·화재예방 목적 CCTV, ③은 계약 이행, ④는 급박한 생명·신체 이익 보호에 해당해 동의 없이 가능하다.","ce":["종교·건강(질병)·범죄경력은 민감정보로, 제23조에 따라 다른 개인정보와 별도로 정보주체 동의를 받거나 법령 근거가 있어야 처리할 수 있다.","도난·화재 예방을 위한 CCTV 설치는 제25조 제1항 시설안전·화재 예방 사유에 해당해 동의 없이 운영할 수 있다(안내판 설치 등 요건은 준수).","주문한 상품 배송을 위한 주소·전화번호 처리는 제15조 제1항 제4호 계약 체결·이행에 불가피한 경우로 동의 없이 가능하다.","의식이 없는 정보주체의 급박한 수술을 위한 보호자 연락처 처리는 제15조 제1항 제5호 급박한 생명·신체 이익 보호에 해당해 동의 없이 가능하다."],"rel":["5-7","5-8"]},{"n":93,"s":"s5","q":"개인정보 영향평가 시 고려 사항에 해당되지 않는 것은?","c":["처리하는 개인정보의 수","개인정보 처리 방법","개인정보 보유기간","정보주체의 권리를 해할 가능성 및 그 위험 정도"],"a":1,"e":"개인정보보호법 제33조와 시행령은 영향평가 시 처리하는 개인정보의 수, 제3자 제공 여부, 정보주체 권리 침해 가능성·위험 정도, 민감정보·고유식별정보 처리 여부, 보유기간 등을 고려하도록 한다. 개인정보 처리 방법은 고려 사항으로 열거되어 있지 않다(개정 여부 확인).","ce":["처리하는 개인정보의 수는 개인정보보호법 제33조가 영향평가 시 고려하도록 명시한 사항이다.","개인정보 처리 방법은 법·시행령의 영향평가 고려 사항으로 열거되어 있지 않다(개정 여부 확인).","개인정보 보유기간은 시행령이 영향평가 고려 사항으로 정한 항목이다.","정보주체의 권리를 해할 가능성과 그 위험 정도는 제33조가 명시한 고려 사항이다."],"rel":["5-9"]},{"n":94,"s":"s5","q":"다음의 개인정보보호법 제17조 ①항에 따라 개인정보처리자가 정보주체의 개인정보를 수집한 목적범위 안에서 제3자에게 제공할 수 있는 경우로 <보기>에서 옳은 것만을 모두 고른 것은?","c":["ㄱ","ㄷ","ㄴ,ㄷ","ㄱ,ㄴ,ㄷ"],"a":2,"e":"시험 당시 제17조 제1항 제2호는 제15조 제1항 제2호(법률 특별규정·법령상 의무), 제3호(공공기관 소관 업무), 제5호(급박한 생명·신체 이익)에 따라 수집한 목적 범위에서 제3자 제공을 허용했다. 계약 체결·이행(제15조 제1항 제4호)은 수집·이용 근거일 뿐 제3자 제공 근거가 아니다(2020년 개정으로 제6호 추가, 개정 여부 확인).","ce":["ㄱ(계약 체결·이행)은 제15조 제1항 제4호의 수집·이용 근거일 뿐, 시험 당시 제17조 제1항 제2호가 준용한 제3자 제공 근거에 포함되지 않는다.","ㄷ(법률 특별 규정·법령상 의무)은 맞지만 공공기관 소관 업무 수행(ㄴ)도 제3자 제공 근거에 포함되므로 빠졌다.","시험 당시 제17조 제1항 제2호는 제15조 제1항 제2호(ㄷ)·제3호(ㄴ)·제5호로 수집한 목적 범위에서 제3자 제공을 허용했으므로 ㄴ·ㄷ이 옳다(개정 여부 확인).","ㄱ 계약 체결·이행 목적은 제3자 제공 근거가 아니므로 모두 고른 것은 틀렸다."],"rel":["5-8"],"box":"<보기1>\n제17조(개인정보의 제공) ① 개인정보처리자는 다음 각 호의 어느 하나에 해당되는 경우에는 정보주체의 개인정보를 제3자에게 제공(공유를 포함한다. 이하 같다)할 수 있다.\n<보기2>\nㄱ. 정보주체와의 계약의 체결 및 이행을 위하여 불가피하게 필요한 경우\nㄴ. 공공기관의 법령 등에서 정하는 소관 업무의 수행을 위하여 불가피한 경우\nㄷ. 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위하여 불가피한 경우"},{"n":95,"s":"s5","q":"빈 칸 ㉠, ㉡에 들어갈 적합한 단어는?","c":["자산 가치, 소비","소비 가치, 노출","자산 가치, 노출","소비 가치, 생산"],"a":2,"e":"단일 예상 손실(SLE) = 자산 가치(AV) × 노출 계수(EF)이며, 연간 예상 손실(ALE) = SLE × 연간 발생률(ARO)이다. 노출 계수는 위협 발생 시 자산 가치가 손실되는 비율이다.","ce":["㉠ 자산 가치는 맞지만 ㉡의 '소비 계수'라는 요소는 없다. 곱해지는 것은 손실 비율인 노출 계수다.","'소비 가치'라는 용어는 정량적 위험분석 공식에 없으며, 기준값은 자산 가치(AV)다.","SLE = 자산 가치(AV) × 노출 계수(EF)이며, 노출 계수는 위협 발생 시 자산 가치가 손실되는 비율이다. ALE = SLE × ARO로 확장된다.","'소비 가치'와 '생산 계수'는 위험분석 공식의 요소가 아니다."],"rel":["5-2"],"box":"정량적 위험분석 방법으로는 연간 예상 손실, 과거자료 분석법, 수학공식 접근법, 확률 분포법 등이 있다.\n이 중 예상 손실은 단일 예상 손실과 연간 예상 손실을 계산할 수 있는데, 단일 예상 손실을 산출하기 위한 공식은 다음과 같다.\n( ㉠ ) * ( ㉡ ) 계수 = 단일 예상 손실"},{"n":96,"s":"s5","q":"「개인정보보호법」 제34조 및 관련 시행령에 따른 개인정보 유출 통지 및 신고에 대한 설명이다. 빈 칸 ㉠, ㉡에 들어갈 알맞은 용어는?","c":["㉠ 1천명 ㉡ 한국인터넷진흥원","㉠ 1만명 ㉡ 한국인터넷진흥원","㉠ 5천명 ㉡ 한국정보화진흥원","㉠ 1만명 ㉡ 한국정보화진흥원"],"a":0,"e":"시험 당시 개인정보보호법 시행령은 1천명 이상의 정보주체 개인정보가 유출된 경우 통지 결과와 조치 결과를 행정안전부장관 또는 전문기관인 한국인터넷진흥원(KISA)에 신고하도록 했다. 현재는 신고 기관이 개인정보보호위원회로 바뀌고, 민감·고유식별정보나 해킹에 의한 유출은 1건이라도 신고하도록 확대되었다(개정 여부 확인).","ce":["시험 당시 시행령은 1천명 이상의 개인정보 유출 시 행정안전부장관 또는 전문기관인 한국인터넷진흥원(KISA)에 신고하도록 했다(현재 신고 기관은 개인정보보호위원회 등, 개정 여부 확인).","신고 기관(KISA)은 맞지만 기준 인원은 1만명이 아니라 1천명이다.","기준 인원 5천명과 한국정보화진흥원 모두 틀렸다. 한국정보화진흥원(현 NIA)은 정보화 정책 지원 기관으로 유출 신고 전문기관이 아니다.","기준 인원(1천명)과 전문기관(KISA)이 모두 틀렸다."],"rel":["5-9"],"box":"개인정보 유출 시 신고 방법\n- 대상: ( ㉠ ) 이상의 정보주체에 관한 개인정보가 유출된 경우\n- 기관: 행정안전부, 전문기관( ㉡ )\n- 시기: 지체없이\n- 방법: 전화, 전자우편, 팩스\n- 내용: 통지내용, 유출피해 최소화 대책 및 조치 결과"},{"n":97,"s":"s5","q":"정보보호 내부 감사 시 고려해야할 사항으로 가장 부적합한 것은?","c":["내부감사를 수행하는 구성원은 정보보호 전문가들로 제한한다.","감사의 범위는 다양한 위험을 분석 및 검토할 수 있도록 가능한 포괄적이어야 한다.","내부감사는 조직의 위험을 파악하여 개선사항을 제시할 수 있다.","감사활동은 기업 내외부로부터 독립성을 유지할 수 있도록 해야 한다."],"a":0,"e":"내부감사는 독립성과 객관성을 갖춘 인력으로 구성하면 되며, 업무·법률·IT 감사 등 다양한 전문성이 필요하므로 정보보호 전문가로만 제한할 필요는 없다. 감사 범위의 포괄성, 개선사항 제시, 독립성 유지는 내부감사의 요건이다.","ce":["내부감사는 독립성·객관성을 갖춘 인력이면 되고, 업무·법률·IT 등 다양한 역량이 필요하므로 정보보호 전문가로만 제한할 필요가 없다.","감사 범위는 조직의 다양한 위험을 분석·검토할 수 있도록 가능한 포괄적으로 설정해야 하므로 적합한 고려사항이다.","내부감사는 위험과 통제 미비점을 파악해 개선사항을 제시하는 역할을 하므로 적합하다.","감사인은 감사 대상 업무로부터 독립성을 유지해야 결과의 객관성과 신뢰성이 확보되므로 적합하다."],"rel":["5-12"]},{"n":98,"s":"s5","q":"「개인정보 보호법」 제23조(민감정보의 처리 제한), 「개인정보 보호법 시행령」 제18조(민감정보의 범위)에서 규정하고 있는 민감정보에 대한 내용으로 가장 적절하지 않은 것은?","c":["범죄경력자료","성생활에 관한 정보","여권번호","유전정보"],"a":2,"e":"여권번호는 주민등록번호·운전면허번호·외국인등록번호와 함께 고유식별정보(제24조)에 해당한다. 민감정보는 사상·신념, 노동조합·정당 가입·탈퇴, 정치적 견해, 건강, 성생활 정보와 시행령상 유전정보, 범죄경력자료 등이다(2020년 생체인식정보, 인종·민족 정보 추가).","ce":["범죄경력자료는 시행령 제18조가 정한 민감정보에 해당한다.","성생활 등에 관한 정보는 개인정보보호법 제23조가 직접 열거한 민감정보다.","여권번호는 주민등록번호·운전면허번호·외국인등록번호와 함께 고유식별정보(제24조, 시행령 제19조)로, 민감정보가 아니다.","유전자검사 등의 결과로 얻어진 유전정보는 시행령 제18조가 정한 민감정보다."],"rel":["5-7"]},{"n":99,"s":"s5","q":"「개인정보보호법 제25조의1」에 따르면 누구든지 다음 각 호의 경우를 제외하고는 공개된 장소에 영상정보처리기기를 설치·운영하여서는 아니 된다. 각 호에 해당하지 않은 것은?","c":["교통단속을 위하여 필요한 경우","교통정보의 수집·분석 및 제공을 위하여 필요한 경우","시설안전 및 화재 예방을 위하여 필요한 경우","소관 업무의 수행을 위하여 불가피한 경우"],"a":3,"e":"제25조 제1항은 법령 허용, 범죄 예방·수사, 시설안전·화재 예방, 교통단속, 교통정보 수집·분석·제공 목적으로만 공개된 장소의 영상정보처리기기 설치를 허용한다. '소관 업무 수행을 위해 불가피한 경우'는 제15조의 공공기관 개인정보 수집 근거로 CCTV 설치 사유가 아니다(개정 여부 확인).","ce":["교통단속을 위하여 필요한 경우는 제25조 제1항 제4호의 허용 사유다.","교통정보의 수집·분석 및 제공을 위하여 필요한 경우는 제25조 제1항 제5호의 허용 사유다.","시설안전 및 화재 예방을 위하여 필요한 경우는 제25조 제1항 제3호의 허용 사유다.","'소관 업무 수행을 위해 불가피한 경우'는 제15조 공공기관의 개인정보 수집·이용 근거일 뿐, 공개된 장소 CCTV 설치 허용 사유가 아니다(개정 여부 확인)."],"rel":["5-14"]},{"n":100,"s":"s5","q":"다음 사건 중 피의자 K씨가 한 행위와 가장 관련 있는 법률은?","c":["정보통신망 이용촉진 및 정보보호 등에 관한 법률","통신비밀보호법","정보통신기반 보호법","사행행위 등 규제 및 처벌 특례법"],"a":0,"e":"시험 당시 정보통신서비스 제공자(사이트 운영자)의 이용자 개인정보 수집·목적 외 이용·제3자 제공은 정보통신망법의 개인정보 특례 규정이 적용되었고, 악성 프로그램 유포 금지(제48조)도 정보통신망법에 규정되어 있다. 2020년 8월 개정으로 개인정보 조항은 개인정보보호법으로 이관되었다(개정 여부 확인).","ce":["시험 당시 사이트 운영자(정보통신서비스 제공자)의 이용자 개인정보 수집·목적 외 이용·제3자 제공은 정보통신망법 특례가, 악성 프로그램 유포 금지는 같은 법 제48조가 규율했다(2020년 개인정보 조항 이관, 개정 여부 확인).","통신비밀보호법은 우편물 검열·전기통신 감청·통신사실확인자료 제공 등 통신비밀을 보호하는 법으로 개인정보 목적 외 이용과 악성코드 유포를 다루지 않는다.","정보통신기반 보호법은 주요정보통신기반시설의 지정·보호와 취약점 분석을 규정하는 법이다.","사행행위 등 규제 및 처벌 특례법은 복권·경품 등 사행행위 영업을 규제하는 법으로, 거짓 이벤트가 등장해도 개인정보 불법 이용·악성코드 유포의 근거 법률이 아니다."],"rel":["5-10"],"box":"피의자 K씨는 어느 사이트를 운영하며 이용자의 개인정보를 수집하였다. 이에 그치지 않고 경품 추첨을 진행한다는 거짓 이벤트를 통해 이용자의 민감한 정보까지 수집하였다. 하지만 K씨는 이를 동의 없이 개인정보 목적 외 이용 및 제3자에게 제공한 사실이 드러났고, 사이트를 통해 악성 프로그램을 유포하였다."}]},{"id":"2018-09-08","title":"2018년 9월 8일","src":"comcbt 교사용","official":true,"items":[{"n":1,"s":"s1","q":"어떤 공격을 방지하기 위한 것인가?","c":["XSS 공격","힙 스프레이 공격","CSRF 공격","SQL 인젝션 공격"],"a":1,"e":"DEP/NX는 힙·스택 같은 데이터 영역의 메모리에서 코드가 실행되지 못하게 막는 메모리 보호 기법으로, 힙에 셸코드를 대량 뿌려 두고 실행 흐름을 옮기는 힙 스프레이 공격 대응에 쓰인다. XSS·CSRF·SQL 인젝션은 웹 애플리케이션 입력 검증 문제로 DEP와 무관하다.","ce":["XSS는 입력값에 스크립트를 넣어 피해자 브라우저에서 실행시키는 웹 공격으로, 서버 입력 검증·출력 인코딩으로 막으며 메모리 실행 방지(DEP/NX)와 무관하다.","DEP/NX는 힙·스택 등 데이터 영역을 실행 불가로 표시해, 힙에 대량으로 뿌려 둔 셸코드로 실행 흐름을 넘기는 힙 스프레이 공격의 코드 실행을 막는다.","CSRF는 로그인된 사용자의 권한으로 원치 않는 요청을 보내게 하는 공격으로, CSRF 토큰·Referer 검증으로 대응한다.","SQL 인젝션은 입력값에 SQL 구문을 넣어 DB 질의를 조작하는 공격으로, 바인딩 변수·입력 검증으로 대응한다."],"rel":["1-10"],"box":"Data Execution Prevention(DEP), NX(No Execute)"},{"n":2,"s":"s1","q":"다음 중 옳지 않은 것은?","c":["리눅스 시스템에서는 계정 목록을 /etc/passwd 파일에 저장하고 있다.","일반 사용자의 사용자 번호(UID, User ID)는 0번으로 부여받게 된다.","디렉토리의 권한은 특수권한, 파일 소유자 권한, 그룹 권한, 일반(Others) 권한으로 구분된다.","접근 권한이 rwxr-xr-x인 경우 고유한 숫자로 표기하면 755가 된다."],"a":1,"e":"UID 0은 root(관리자)에게 부여되는 번호이며, 일반 사용자는 배포판에 따라 500 또는 1000 이상의 UID를 받는다. rwxr-xr-x는 4+2+1, 4+1, 4+1로 755가 맞다.","ce":["리눅스는 계정명·UID·GID·홈 디렉터리·셸 등 계정 목록을 /etc/passwd에 저장하므로 옳다(해시 패스워드는 /etc/shadow).","UID 0은 root(관리자) 전용이며, 일반 사용자는 배포판에 따라 500 또는 1000번 이상의 UID를 받는다.","권한은 특수권한(SetUID·SetGID·Sticky)과 소유자·그룹·기타(Others) 권한으로 구분되므로 옳다.","rwx=4+2+1=7, r-x=4+1=5, r-x=5이므로 rwxr-xr-x는 755로 옳다."],"rel":["1-6","1-4"]},{"n":3,"s":"s1","q":"적절하게 고른 것은?","c":["가 /usr 나/temp 다/dev","가 /usr 나/tmp 다/var","가 /etc 나/temp 다/var","가 /etc 나/tmp 다/dev"],"a":3,"e":"/etc는 시스템 설정 파일, /tmp는 임시 파일, /dev는 장치 파일이 위치하는 디렉터리다. /usr은 사용자 프로그램·라이브러리, /var는 로그·스풀 등 가변 데이터가 저장된다.","ce":["/usr은 사용자 프로그램·라이브러리·문서가 설치되는 곳이고, 임시 파일 디렉터리는 /temp가 아니라 /tmp다.","/tmp는 맞지만 /usr은 설정 파일 위치가 아니며, /var는 로그·메일 스풀 같은 가변 데이터 디렉터리로 장치 파일 위치가 아니다.","/etc는 맞지만 임시 디렉터리 이름은 /tmp이고, 장치 파일은 /var가 아니라 /dev에 있다.","/etc는 시스템 설정 파일, /tmp는 실행 중 생성되는 임시 파일, /dev는 프린터·터미널 등 장치를 다루는 특수(장치) 파일이 위치한다."],"rel":["1-16"],"box":"가. 시스템의 환경 설정 및 주요 설정 파일\n나. 프로그램 실행시 생성되는 임시 파일\n다. 프린터나 터미널 같은 물리적인 장치를 다루기 위한 특수 파일"},{"n":4,"s":"s1","q":"인적자원 관리자가 특정 부서 사용자들에게 같은 직무를 수행할 수 있는 접근 권한을 할당하고 있다. 이것은 다음 중 어느 것의 예인가?","c":["역할기반 접근 통제","규칙기반 접근 통제","중앙집중식 접근 통제","강제적 접근 통제"],"a":0,"e":"직무(역할)에 권한을 부여하고 사용자를 역할에 배정하는 방식이 RBAC(역할기반 접근통제)다. 강제적 접근통제는 보안 등급(레이블) 비교로, 규칙기반은 사전에 정한 규칙 목록으로 접근을 결정한다.","ce":["같은 직무(역할)에 필요한 권한을 역할에 묶고 사용자를 역할에 배정하는 것이 RBAC이므로, 부서 사용자에게 직무별 권한을 할당하는 사례에 해당한다.","규칙기반 접근통제는 시간·IP 등 사전에 정한 규칙 목록으로 모든 사용자에게 일괄 적용하는 방식으로, 직무 단위 권한 할당과 다르다.","중앙집중식 접근통제는 권한을 한 곳에서 관리하는 관리 형태를 가리킬 뿐, 직무 기반으로 권한을 묶는 모델의 명칭이 아니다.","강제적 접근통제(MAC)는 주체·객체의 보안 등급(레이블)을 비교해 접근을 결정하므로 직무 단위 할당과 다르다."],"rel":["4-10"]},{"n":5,"s":"s1","q":"윈도우 레지스트리 하이브 파일이 아닌 것은?","c":["HKEY-CLASSES-ROOT","HKEY LOCAL-MACHINE","HKEY-CURRENT-SAM","HKEY-CURRENT-USER"],"a":2,"e":"윈도우 레지스트리 루트 키는 HKEY_CLASSES_ROOT, HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE, HKEY_USERS, HKEY_CURRENT_CONFIG 5개다. HKEY_CURRENT_SAM이라는 키는 없으며, SAM은 HKLM\\SAM 하위의 하이브다.","ce":["HKEY_CLASSES_ROOT는 파일 확장자 연결·COM 등록 정보를 담는 실제 레지스트리 루트 키다.","HKEY_LOCAL_MACHINE은 SAM·SECURITY·SOFTWARE·SYSTEM 하이브 파일을 포함하는 실제 루트 키다.","HKEY_CURRENT_SAM이라는 키는 존재하지 않는다. SAM은 HKLM\\SAM 아래에 로드되는 하이브다.","HKEY_CURRENT_USER는 현재 로그인 사용자의 설정(NTUSER.DAT 하이브)을 담는 실제 루트 키다."],"rel":["1-3"]},{"n":6,"s":"s1","q":"윈도우 NTFS에서 모든 파일들과 디렉터리에 대한 정보를 포함하고 있는 것은?","c":["MFT(Master File Table)","FAT(File Allocation Table)","$Attr Def","$LogFile"],"a":0,"e":"MFT는 NTFS 볼륨의 모든 파일·디렉터리에 대한 레코드(이름, 속성, 데이터 위치 등)를 담는 핵심 메타데이터 파일이다. FAT는 FAT 파일시스템의 클러스터 할당표, $LogFile은 트랜잭션 로그, $AttrDef는 속성 정의 파일이다.","ce":["MFT는 NTFS 볼륨의 모든 파일·디렉터리마다 레코드(이름, 시간, 보안 속성, 데이터 위치)를 저장하는 핵심 메타데이터 테이블이다.","FAT는 FAT 파일시스템에서 클러스터 연결 정보를 저장하는 할당표로 NTFS의 구성요소가 아니다.","$AttrDef는 NTFS에서 사용하는 속성 유형(이름·번호·크기)의 정의를 담는 메타 파일로 개별 파일 정보를 담지 않는다.","$LogFile은 메타데이터 변경을 기록하는 트랜잭션 저널로, 장애 시 볼륨 일관성 복구에 쓰인다."],"rel":["1-18"]},{"n":7,"s":"s1","q":"리눅스/유닉스 시스템에서 로그를 확인하는 명령어나 로그파일과 가장 거리가 먼 것은?","c":["wtmp","history","pacct","find"],"a":3,"e":"find는 조건에 맞는 파일을 검색하는 명령어로 로그와 무관하다. wtmp는 로그인·로그아웃 이력, history는 셸 명령 실행 이력, pacct는 사용자별 실행 프로세스 기록(lastcomm으로 확인)이다.","ce":["wtmp는 로그인·로그아웃과 재부팅 이력을 저장하는 로그 파일로 last 명령으로 확인한다.","history는 사용자가 셸에서 실행한 명령 이력(.bash_history)을 보여 주어 침해 분석에 활용된다.","pacct는 프로세스 accounting 로그로, 사용자별 실행 명령을 기록하며 lastcomm으로 확인한다.","find는 이름·시간·권한 등 조건으로 파일을 검색하는 명령으로, 로그를 기록하거나 확인하는 전용 명령·파일이 아니다."],"rel":["1-7"]},{"n":8,"s":"s1","q":"다음 지문이 설명하는 데이터베이스 보안 유형은 무엇인가?","c":["Access Control","Encryption","Views","Authorization Rules"],"a":2,"e":"뷰(View)는 기본 테이블에서 허가된 행·열만 보여 주는 가상 테이블로, 사용자가 볼 수 있는 데이터 범위를 제한하는 보안 수단이다. 접근 통제와 허가 규칙은 객체에 대한 연산 권한 부여, 암호화는 데이터 자체를 보호하는 방식이다.","ce":["접근 제어는 사용자·객체별로 SELECT·UPDATE 등 연산 권한을 부여·회수하는 수단으로, 사용자 관점의 가상 테이블을 만드는 방식이 아니다.","암호화는 저장·전송 데이터를 읽을 수 없게 변환해 보호하는 수단으로, 보이는 데이터 범위를 한정하지 않는다.","뷰는 기본 테이블에서 허가된 행·열만 골라 보여 주는 가상 테이블로, 사용자가 자기 관점의 데이터만 보도록 제한한다.","허가 규칙은 어떤 사용자가 어떤 객체에 어떤 연산을 할 수 있는지 정의한 규칙 집합으로, 데이터 범위를 가상 테이블로 한정하는 것과 다르다."],"rel":["3-8"],"box":"전체 데이터베이스 중 자신이 허가 받은 사용자 관점만 볼 수 있도록 한정한 것"},{"n":9,"s":"s1","q":"패스워드와 함께 일방향 해시함수에 입력되는 12비트 난수값은?","c":["세션키","메시지","솔트(salt)","멜로리"],"a":2,"e":"솔트는 패스워드에 덧붙여 해시하는 난수로, 같은 패스워드라도 다른 해시값이 나오게 해 사전·레인보우 테이블 공격을 어렵게 한다. 전통적 유닉스 crypt(DES 기반)는 12비트 솔트를 사용했다.","ce":["세션키는 한 통신 세션 동안만 쓰는 대칭 암호키로, 패스워드 해시 입력에 덧붙이는 난수가 아니다.","메시지는 해시함수의 입력 데이터 일반을 가리킬 뿐 패스워드와 함께 넣는 12비트 난수를 뜻하지 않는다.","솔트는 패스워드에 덧붙여 해시하는 난수로, 같은 패스워드도 다른 해시가 되게 해 사전·레인보우 테이블 공격을 어렵게 한다. 전통적 유닉스 crypt는 12비트 솔트를 썼다.","멜로리(Mallory)는 암호 프로토콜 설명에서 능동적 공격자를 지칭하는 가상 인물 이름이다."],"rel":["1-6","4-5"]},{"n":10,"s":"s1","q":"아이노드(i-node)가 가지고 있지 않은 정보는?","c":["파일의 이름","파일의 링크 수","파일 수정시각","파일 유형"],"a":0,"e":"i-node는 파일 유형, 권한, 소유자, 크기, 링크 수, 시각 정보(MAC time), 데이터 블록 주소를 저장한다. 파일 이름은 i-node가 아니라 디렉터리 엔트리(이름-i-node 번호 매핑)에 저장된다.","ce":["파일 이름은 i-node가 아니라 디렉터리 엔트리(이름 ↔ i-node 번호)에 저장되므로 i-node가 가지지 않는 정보다.","하드 링크 수는 i-node에 저장되며 0이 되면 파일이 실제로 삭제된다.","수정 시각(mtime)을 포함한 접근·변경 시각은 i-node에 저장된다.","일반 파일·디렉터리·링크 등 파일 유형은 i-node의 모드 필드에 저장된다."],"rel":["1-18"]},{"n":11,"s":"s1","q":"다음 악성코드에 대한 설명 중 옳지 않은 것은?","c":["루트킷(Rootkit)은 단일 컴퓨터 또는 일련의 컴퓨터 네트워크에 대해 관리자 레벨의 접근을 가능하도록 하는 도구의 집합이다.","웜(Worm)은 네트워크 등의 연결을 통하여 자신의 복제품을 전파한다.","트로이목마(Trojan Horse)는 정상적인 프로그램으로 가장한 악성 프로그램으로 보통 복제 과정을 통해 스스로 전파된다.","트랩도어(Trapdoor)는 정상적인 인증 과정을 거치지 않고 프로그램에 접근하는 일종의 통로이다."],"a":2,"e":"트로이목마는 정상 프로그램으로 위장해 사용자가 직접 실행하도록 유도할 뿐 스스로 복제·전파하지 않는다. 자기 복제·전파는 웜과 바이러스의 특징이다.","ce":["루트킷은 침입 흔적을 숨기고 관리자 수준 접근을 유지하게 해 주는 도구 모음이므로 옳다.","웜은 숙주 파일 없이 네트워크 취약점 등을 이용해 자신을 복제·전파하므로 옳다.","트로이목마는 정상 프로그램으로 위장해 사용자가 실행하도록 유도할 뿐, 스스로 복제·전파하지 않는다. 자기 복제는 웜·바이러스의 특징이다.","트랩도어(백도어)는 정상 인증 절차를 거치지 않고 프로그램에 접근하는 비밀 통로이므로 옳다."],"rel":["1-9"]},{"n":12,"s":"s1","q":"디스크 공간 할당의 논리적 단위는?","c":["Volume","Page","Cluster","Stream"],"a":2,"e":"클러스터는 파일시스템이 디스크 공간을 할당하는 논리적 단위로, 여러 물리적 섹터를 묶은 것이다. 페이지는 가상 메모리 관리 단위이고, 볼륨은 포맷된 저장 영역 전체를 말한다.","ce":["볼륨은 하나의 파일시스템으로 포맷된 저장 영역 전체를 말하며 할당 단위가 아니다.","페이지는 가상 메모리를 관리하는 고정 크기 단위로, 디스크 파일 공간 할당 단위가 아니다.","클러스터는 여러 섹터를 묶은 파일시스템의 최소 논리 할당 단위로, 파일은 클러스터 단위로 공간을 받는다.","스트림은 연속된 데이터 흐름(NTFS에서는 파일 데이터 속성인 ADS 등)을 뜻하며 공간 할당 단위가 아니다."],"rel":["1-18"]},{"n":13,"s":"s1","q":"다음 중 파일 시스템의 무결성 보장을 위해 점검해야 할 사항으로 옳지 않은 것은?","c":["파일의 소유자, 소유그룹 등의 변경 여부 점검","파일의 크기 변경 점검","최근에 파일에 접근한 시간 점검","파일의 symbolic link의 수 점검"],"a":3,"e":"무결성 점검(Tripwire 등)은 파일의 소유자·그룹·권한, 크기, 시각 정보, 해시값의 변경 여부를 기준 정보와 비교한다. 심볼릭 링크 수는 i-node의 링크 수 정보(하드링크 수)와 달리 파일 속성에 기록되지 않아 점검 대상이 아니다.","ce":["소유자·소유 그룹 변경은 공격자가 권한을 바꾼 흔적일 수 있어 무결성 점검 항목이다.","파일 크기가 바뀌면 내용이 변조되었을 가능성이 있어 무결성 점검 항목이다.","최근 접근·변경 시각은 침입자가 파일을 건드렸는지 판단하는 근거가 되어 점검 항목으로 쓰인다.","심볼릭 링크 수는 파일 속성으로 관리되지 않아(i-node는 하드 링크 수만 가짐) 무결성 점검 항목이 아니다."],"rel":["1-11"]},{"n":14,"s":"s1","q":"다음 파일시스템(FAT, NTFS)에 대한 설명 중 옳지 않은 것은?","c":["FAT 뒤의 숫자는 표현 가능한 최대 클러스터 개수와 관련되어 있다.","NTFS 파일시스템은 대용량 볼륨, 보안 및 암호화를 지원한다.","NTFS 파일시스템은 타 운영체제 호환이 용이하다.","저용량 볼륨에서는 FAT가 NTFS보다 속도가 빠르다."],"a":2,"e":"NTFS는 윈도우 전용으로 설계되어 다른 운영체제(구형 리눅스, 맥 등)에서의 읽기·쓰기 호환성이 낮으며, 호환성이 높은 것은 FAT 계열이다. FAT12/16/32의 숫자는 클러스터 주소 비트 수로 최대 클러스터 수를 결정한다.","ce":["FAT12·16·32의 숫자는 클러스터 주소 비트 수로, 표현 가능한 최대 클러스터 개수를 결정하므로 옳다.","NTFS는 대용량 볼륨, ACL 기반 보안, EFS 암호화, 저널링을 지원하므로 옳다.","NTFS는 윈도우 전용 구조라 타 운영체제에서는 읽기만 되거나 별도 드라이버가 필요하므로 호환성이 낮다. 호환성이 좋은 것은 FAT 계열이다.","FAT는 구조가 단순하고 저널링·보안 오버헤드가 없어 소용량 볼륨에서는 NTFS보다 빠를 수 있으므로 옳은 설명으로 본다."],"rel":["1-18","1-3"]},{"n":15,"s":"s1","q":"다음 중 SECaaS에 대한 설명으로 적합하지 않은 것은?","c":["클라우드 컴퓨팅 환경 하에서 인터넷을 통하여 보안서비스를 제공하는 것을 두고 SECaaS(Security as a Service)라고 한다.","SECaaS는 Standalone으로 클라우드 기반 보안서비스를 제공하는 형태와 클라우드 서비스 제공업체가 자사의 고객에게 보안기능을 제공하는 형태로 나뉠 수 있다","SECaaS는 보안서비스를 ASP 형태로 공급한다는 측면에서 넓은 의미의 PaaS(Platform as a Service) 로 볼 수 있다.","SECaaS는 인증, 안티바이러스, 침입탐지, 모의침투, 보안이벤트 관리 등의 다양한 보안 기능을 제공할 수 있다."],"a":2,"e":"SECaaS는 보안 기능을 소프트웨어 서비스 형태(ASP 방식)로 구독 제공하므로 넓은 의미의 SaaS(Software as a Service)로 본다. PaaS는 애플리케이션 개발·실행 플랫폼을 제공하는 서비스 모델이다.","ce":["클라우드 환경에서 인터넷을 통해 보안 기능을 서비스로 제공하는 것이 SECaaS의 정의이므로 옳다.","보안 전문업체가 독립적으로 제공하는 형태와 클라우드 사업자가 자사 고객에게 부가 제공하는 형태로 나눌 수 있어 옳다.","SECaaS는 완성된 보안 기능을 ASP 방식으로 구독 제공하므로 넓은 의미의 SaaS에 해당한다. PaaS는 개발·실행 플랫폼을 제공하는 모델이다.","인증, 안티바이러스, 침입탐지, 모의침투, 보안이벤트 관리 등 다양한 보안 기능을 서비스로 제공할 수 있어 옳다."],"rel":["1-12"]},{"n":16,"s":"s1","q":"SAM에 대한 설명으로 옳지 않은 것은?","c":["사용자 패스워드는 해시된 상태로 저장된다.","SID를 사용하여 각 자원에 대한 접근권한을 명시한다.","SAM 파일은 사용자, 그룹 계정 및 암호화된 패스워드 정보를 저장하고 있는 데이터베이스이다.","사용자 로그인 정보와 SAM 파일에 저장된 사용자 패스워드 정보를 비교해 인증 여부가 결정된다."],"a":1,"e":"SID(보안 식별자)를 이용해 자원별 접근권한을 명시하는 것은 SRM(Security Reference Monitor)과 객체의 ACL이 하는 역할이다. SAM은 계정·그룹 정보와 패스워드 해시를 저장하고 로그인 시 비교·인증에 쓰이는 데이터베이스다.","ce":["SAM은 사용자 패스워드를 평문이 아닌 LM/NTLM 해시로 저장하므로 옳다.","SID를 이용해 각 자원에 대한 접근권한을 명시하는 것은 객체의 보안 기술자(ACL)와 SRM(보안 참조 모니터)의 역할이며 SAM의 역할이 아니다.","SAM은 로컬 사용자·그룹 계정과 패스워드 해시를 저장하는 데이터베이스이므로 옳다.","로그인 시 LSA가 입력값의 해시를 SAM에 저장된 해시와 비교해 인증 여부를 결정하므로 옳다."],"rel":["1-2"]},{"n":17,"s":"s1","q":"로그분석에 사용되며 문자열을 처리하는 Unix 명령어와 가장 거리가 먼 것은?","c":["awk","wc","grep","nohup"],"a":3,"e":"nohup은 로그아웃 후에도 명령이 계속 실행되도록(HUP 시그널 무시) 하는 명령으로 문자열 처리와 무관하다. awk는 필드 단위 텍스트 처리, grep은 패턴 검색, wc는 줄·단어·문자 수 계산에 쓰인다.","ce":["awk는 줄을 필드 단위로 나눠 조건 처리·집계하는 텍스트 처리 언어로 로그 분석에 널리 쓰인다.","wc는 줄·단어·문자 수를 세어 로그 건수 집계 등에 쓰이는 문자열 처리 명령이다.","grep은 정규식 패턴과 일치하는 줄을 찾아 특정 IP·에러 등을 로그에서 추출한다.","nohup은 로그아웃해도 HUP 시그널을 무시하고 명령을 계속 실행하게 하는 명령으로 문자열 처리와 무관하다."],"rel":["1-7"]},{"n":18,"s":"s1","q":"다음 지문에서 설명하고 있는 침입탐지 기술이 무엇인지 고르시오.","c":["IDS(Instrusion Detection System)","IPS(Instrusion Prevention System)","UTM(Unified Threat Management)","Honeypot"],"a":3,"e":"허니팟은 의도적으로 취약하게 만든 미끼 시스템으로 공격자를 유인해 행동 정보를 수집하고, 공격자를 오래 머무르게 해 관리자의 대응 시간을 확보한다. IDS·IPS는 실제 시스템으로 향하는 공격을 탐지·차단하는 장비다.","ce":["IDS는 실제 시스템·네트워크로 향하는 트래픽을 분석해 침입을 탐지·경보할 뿐, 공격자를 유인해 오래 머물게 하지 않는다.","IPS는 탐지한 공격을 인라인에서 즉시 차단하는 장비로 공격자를 머무르게 하는 목적과 반대다.","UTM은 방화벽·IPS·안티바이러스 등을 한 장비에 통합한 경계 보안 장비다.","허니팟은 의도적으로 취약하게 만든 미끼 시스템으로, 공격자 행동 정보를 수집하고 오래 머물게 해 관리자가 대응할 시간을 번다."],"rel":["2-10"],"box":"- 공격자의 동작에 관한 정보를 수집한다.\n- 공격자가 시스템에 충분히 오랜 시간 동안 머무르기를 유도함으로써 관리자가 반응할 수 있도록 한다."},{"n":19,"s":"s1","q":"다음 중 Unix 시스템에서 secure.txt 파일의 소유자에게는 읽기와 실행권한을 부여하고 다른 사용자에게는 읽기 권한을 제거하라는 권한 변경 명령어로 알맞은 것은?","c":["#chmod 306 secure.txt","#chmod 504 secure.txt","#chmod otrx, a-r secure.txt","#chmod u=rx, o-r secure.txt"],"a":3,"e":"심볼릭 모드에서 u=rx는 소유자 권한을 읽기·실행으로 지정하고, o-r은 기타 사용자의 읽기 권한을 제거한다. 숫자 모드 504는 기타 사용자에게 읽기(4)를 부여하므로 조건에 맞지 않는다.","ce":["306은 소유자 -wx(3), 그룹 ---(0), 기타 rw-(6)로 소유자 읽기가 없고 기타에 읽기·쓰기를 주어 조건과 반대다.","504는 소유자 r-x(5)는 맞지만 기타 사용자에게 읽기(4)를 부여해 '읽기 권한 제거'와 반대다.","'otrx, a-r'은 올바른 심볼릭 모드 표기가 아니며, a-r은 소유자를 포함한 모든 사용자의 읽기까지 제거해 조건과 맞지 않는다.","u=rx는 소유자 권한을 읽기·실행으로 지정하고 o-r은 기타 사용자의 읽기를 제거하므로 요구 조건과 정확히 일치한다."],"rel":["1-4"]},{"n":20,"s":"s1","q":"리눅스에서 관리하는 주요 로그파일에 대한 설명으로 옳지 않은 것은?","c":["/var/log/cron : 시스템의 정기적인 작업에 대한 로그","/var/log/messages : 커널에서 보내주는 실시간 메시지","/var/log/secure : 시스템의 접속에 관한 로그로 언제/누가/어디의 정보를 포함","/var/log/xferlog : 메일 송수신에 관한 로그"],"a":3,"e":"xferlog는 FTP 파일 전송 기록이며, 메일 송수신 로그는 /var/log/maillog에 기록된다. cron은 예약 작업, messages는 커널·시스템 전반 메시지, secure는 인증·원격 접속 기록이다.","ce":["/var/log/cron은 crond가 수행한 예약(정기) 작업의 실행 기록을 남기므로 옳다.","/var/log/messages는 커널과 주요 데몬이 syslog로 보내는 시스템 전반 메시지를 기록하므로 옳다.","/var/log/secure는 SSH·telnet 로그인, su 등 인증·접속 기록(언제·누가·어디서)을 남기므로 옳다.","xferlog는 FTP 파일 전송 기록이다. 메일 송수신 로그는 /var/log/maillog에 기록된다."],"rel":["1-7"]},{"n":21,"s":"s2","q":"다음은 PORT 스캔 공격에 관한 설명이다. 설명 중 맞는 것을 모두 고른 것은?","c":["가, 나","가, 나, 다.","가, 나, 라","가, 나, 다, 라"],"a":2,"e":"공식 정답은 ③(가, 나, 라)이다. 포트 스캔은 열린 포트를 확인하는 정보수집 공격이고, SYN만 보내는 Half-Open 스캔은 세션을 완성하지 않아 로그가 적게 남는 대표적 스텔스 스캔이며, UDP 스캔은 닫힌 포트에서 ICMP Port Unreachable을 받는다. 다만 '다'의 Null 스캔 설명도 RFC 793 기준으로 옳아 ④가 맞다는 이의가 있는 문항이다.","ce":["'가'·'나'는 맞지만 UDP 스캔의 닫힌 포트 ICMP Unreachable 응답을 설명한 '라'도 옳으므로 빠뜨렸다.","'라'(UDP 스캔: 열림=무응답, 닫힘=ICMP Port Unreachable)가 옳은데 빠졌다. '다'의 포함 여부는 정답 논란이 있다.","공식 정답이다. 포트 스캔 정의(가), Half-Open(SYN) 스캔이 대표 스텔스 스캔(나), UDP 스캔의 닫힌 포트 ICMP Unreachable 응답(라)이 옳다.","Null 스캔은 RFC 793 기준 열린 포트 무응답, 닫힌 포트 RST/ACK이므로 '다'도 옳아 이 보기가 맞다는 이의가 있다. 공식 정답은 ③(가·나·라)이다."],"rel":["2-4"],"box":"가. PORT 스캔은 공격대상 시스템의 포트가 열려 있는지 확인하는 일종의 공격이다.\n나. Stealth 스캔의 대표적인 경우로 TCP Half-Open 스캔이 있다.\n다. Null 스캔은 포트가 열려 있을 경우에는 응답이 없고, 닫혀있을 경우에만 RST/ACK 패킷이 되돌아 온다.\n라. UDP Open 스캔은 포트가 열려 있을 경우에는 아무런 응답이 없고, 포트가 닫혀있을 경우에는 ICMP Unreachable 패킷을 받게 된다.","flag":"정답 논란: 공식 정답 ③이나 '다'(Null 스캔: 열림=무응답, 닫힘=RST/ACK)도 일반적으로 옳은 설명이라 ④가 맞다는 오류 신고 다수(comcbt 해설집)"},{"n":22,"s":"s2","q":"다음의 포트 스캔 중 플래그 (SYN, RST, ACK, AN, PS URG)을 모두 off하여 스캔하는 것은?","c":["TCP SYN 스캔","Fin 스캔","Null 스캔","Xmas 스캔"],"a":2,"e":"Null 스캔은 TCP 플래그를 하나도 설정하지 않은 패킷을 보낸다. FIN 스캔은 FIN만, Xmas 스캔은 FIN·PSH·URG를 모두 설정하며, TCP SYN 스캔은 SYN만 설정한다.","ce":["TCP SYN 스캔은 SYN 플래그만 켜서 보내는 Half-Open 스캔이다.","FIN 스캔은 FIN 플래그만 켜서 보내는 스텔스 스캔이다.","Null 스캔은 TCP 플래그를 하나도 설정하지 않은(모두 off) 패킷을 보내 열린 포트의 무응답, 닫힌 포트의 RST로 판별한다.","Xmas 스캔은 FIN·PSH·URG 플래그를 모두 켜서 보내는 스캔으로 Null 스캔과 반대 방향이다."],"rel":["2-4"]},{"n":23,"s":"s2","q":"오용탐지 방법으로 적당하지 않은 것은?","c":["시그니처 분석","페트리넷(Petri-net)","상태전이 분석","데이터마이닝"],"a":3,"e":"오용(Misuse) 탐지는 알려진 공격 패턴을 기반으로 하며 시그니처 분석, 페트리넷, 상태전이 분석, 전문가 시스템 등을 사용한다. 데이터마이닝은 통계·신경망 등과 함께 정상 행위 프로파일을 학습하는 이상(Anomaly) 탐지 기법에 속한다.","ce":["시그니처 분석은 알려진 공격 패턴을 트래픽·로그와 대조하는 대표적 오용탐지 방법이다.","페트리넷은 공격 단계를 상태와 전이로 모델링한 그래프로 알려진 공격 시나리오를 표현하므로 오용탐지 방법에 속한다(IDIOT 등).","상태전이 분석은 공격을 초기 상태에서 침해 상태로 가는 전이 순서로 정의해 탐지하므로 오용탐지 방법이다.","데이터마이닝은 대량 데이터에서 정상 행위 패턴을 학습·분류하는 기법으로, 통계·신경망 등과 함께 이상(Anomaly) 탐지 방법으로 분류된다."],"rel":["2-9"]},{"n":24,"s":"s2","q":"공격 대상이 방문할 가능성이 있는 합법적인 웹 사이트를 미리 감염시킨 뒤, 잠복하고 있다가 공격 대상이 방문하면 대상의 컴퓨터에 악성코드를 설치하는 공격 방법은?","c":["악성 봇(Malicious Bot) 공격","워터링 홀(Watering Hole) 공격","스피어 피싱(Spear Phishing) 공격","피싱(Phishing) 공격"],"a":1,"e":"워터링 홀은 사자가 물웅덩이에서 먹잇감을 기다리듯 표적 집단이 자주 방문하는 정상 사이트를 감염시켜 방문자를 공격하는 APT 기법이다. 스피어 피싱은 특정 대상에게 맞춤형 이메일을 보내 악성 첨부·링크를 열게 하는 방식이다.","ce":["악성 봇 공격은 봇에 감염된 PC를 원격 제어해 DDoS·스팸 등에 동원하는 방식으로, 특정 정상 사이트에 잠복해 방문자를 노리는 기법이 아니다.","워터링 홀은 표적 집단이 자주 방문하는 합법 사이트를 미리 감염시키고, 대상이 방문하면 악성코드를 설치하는 APT 기법이다.","스피어 피싱은 특정 대상에게 맞춤형 이메일을 보내 악성 첨부·링크를 열게 하는 방식으로 사이트 방문을 기다리지 않는다.","피싱은 불특정 다수에게 가짜 메일·링크를 보내 위조 사이트로 유도하는 방식이며, 합법 사이트를 감염시키지 않는다."],"rel":["1-19"]},{"n":25,"s":"s2","q":"다음 중 패킷의 출발지와 목적지 모두를 반영하여 주소 변환을 수행하는 NAT(Network Address Translation)는?","c":["동적 NAT","정적 NAT","바이패스 NAT","폴리시 NAT"],"a":3,"e":"폴리시(Policy) NAT는 출발지뿐 아니라 목적지 주소(및 포트) 조건까지 정책으로 지정해, 같은 내부 주소라도 목적지에 따라 다른 주소로 변환한다. 정적·동적 NAT는 출발지(내부) 주소만을 기준으로 변환한다.","ce":["동적 NAT는 내부 출발지 주소를 공인 주소 풀에서 동적으로 골라 변환할 뿐 목적지 주소는 조건에 반영하지 않는다.","정적 NAT는 내부 주소와 공인 주소를 1:1로 고정 매핑하며 목적지와 무관하게 동일하게 변환한다.","바이패스 NAT는 특정 트래픽을 주소 변환 없이 그대로 통과시키는 설정으로, 출발지·목적지를 함께 반영한 변환이 아니다.","폴리시 NAT는 출발지뿐 아니라 목적지 주소(포트) 조건까지 정책으로 지정해, 같은 내부 주소도 목적지에 따라 다른 주소로 변환한다."],"rel":["2-12"]},{"n":26,"s":"s2","q":"도메인을 탈취하거나 도메인 네임 시스템 또는 프록시 서버의 주소를 변조함으로써 사용자들로 하여금 진짜 사이트로 오인하여 접속하도록 유도한 뒤, 개인 정보를 탈취하는 해킹 기법은?","c":["피싱","파밍","스미싱","봇넷"],"a":1,"e":"파밍은 DNS·hosts 파일·프록시 설정을 변조하거나 도메인을 탈취해 정확한 주소를 입력해도 가짜 사이트로 연결시키는 공격이다. 피싱은 가짜 메일·링크로 유도하고, 스미싱은 문자메시지(SMS)를 이용한다.","ce":["피싱은 가짜 메일·문자의 링크를 눌러 위조 사이트로 가게 하는 방식이라, DNS·프록시 변조 없이 사용자의 클릭에 의존한다.","파밍은 도메인 탈취, DNS·hosts 파일·프록시 주소 변조로 사용자가 정상 주소를 입력해도 가짜 사이트에 접속하게 만들어 개인정보를 탈취한다.","스미싱은 SMS(문자메시지)에 악성 URL을 넣어 앱 설치·소액결제를 유도하는 공격이다.","봇넷은 악성코드에 감염된 좀비 PC들의 네트워크로 DDoS·스팸 발송에 쓰이며, 특정 해킹 기법의 명칭이 아니다."],"rel":["2-5"]},{"n":27,"s":"s2","q":"다음 용어 중 개념상 나머지와 가장 거리가 먼 것은?","c":["sniffing","eavesdropping","tapping","spoofing"],"a":3,"e":"스니핑, 도청(eavesdropping), 탭핑(tapping)은 통신 내용을 몰래 엿듣는 수동적 공격이다. 스푸핑은 IP·MAC·DNS 등을 위조해 다른 대상으로 위장하는 능동적 공격이다.","ce":["스니핑은 네트워크를 지나는 패킷을 몰래 엿보는 수동적 공격으로 도청 계열에 속한다.","eavesdropping(도청)은 통신 내용을 몰래 엿듣는 수동적 공격이다.","tapping(탭핑)은 회선에 장치를 연결해 신호를 가로채는 물리적 도청으로 역시 수동적 공격이다.","스푸핑은 IP·MAC·DNS 등을 위조해 다른 주체로 위장하는 능동적 공격으로, 엿듣기 계열인 나머지 셋과 개념이 다르다."],"rel":["2-5"]},{"n":28,"s":"s2","q":"다음 중 end point에 설치되어 다양한 보안 기능을 통합적으로 수행하는 보안 시스템을 지칭하는 것은?","c":["IPS","NAC","Firewall","UTM"],"a":1,"e":"NAC는 엔드포인트(단말)에 에이전트를 설치하거나 네트워크에서 단말을 식별해 인증, 보안 정책 준수(백신·패치) 점검, 격리·치료 등 여러 보안 기능을 통합 수행한다. UTM은 방화벽·IPS·안티바이러스 등을 네트워크 경계의 한 장비에 통합한 것으로 엔드포인트에 설치되지 않는다.","ce":["IPS는 네트워크 경로에 인라인으로 설치되어 공격 트래픽을 차단하는 장비로 엔드포인트에 설치되지 않는다.","NAC는 단말(엔드포인트)에 에이전트를 두어 인증, 백신·패치 등 보안 정책 준수 점검, 미준수 단말 격리·치료 등 여러 기능을 통합 수행한다.","방화벽은 네트워크 경계에서 IP·포트 규칙으로 트래픽을 허용·차단하는 장비다(PC 방화벽은 단일 기능).","UTM은 방화벽·IPS·안티바이러스 등을 통합하지만 네트워크 경계에 두는 게이트웨이 장비로, 엔드포인트에 설치되지 않는다."],"rel":["2-10","1-11"]},{"n":29,"s":"s2","q":"다음 중 전문가 시스템(Expert System)을 이용한 IDS에서 사용되는 침입 탐지기법은?","c":["Behavior Detection","State Transition Detection","Knowledge Based Detection","Statistical Detection"],"a":2,"e":"전문가 시스템은 알려진 공격에 관한 지식을 규칙(if-then)으로 표현해 추론하므로 지식 기반(오용) 탐지에 해당한다. Behavior·Statistical Detection은 정상 행위 통계를 이용하는 이상 탐지 기법이다.","ce":["Behavior Detection은 정상 행위 프로파일과의 차이를 보는 행위(이상) 기반 탐지로, 규칙 추론을 하는 전문가 시스템 방식이 아니다.","State Transition Detection은 공격을 상태 전이 순서로 모델링하는 오용탐지 기법이며, 전문가 시스템의 규칙 추론 방식과는 구분된다.","전문가 시스템은 알려진 공격 지식을 if-then 규칙으로 표현해 추론하므로 지식 기반(오용) 탐지에 해당한다.","Statistical Detection은 정상 사용 통계와의 편차로 판단하는 이상 탐지 기법이다."],"rel":["2-9"]},{"n":30,"s":"s2","q":"Snort의 각 규칙은 고정된 헤더와 옵션을 가지고 있다. 패킷의 payload 데이터를 검사할 때 사용되는 옵션에 포함되지 않는 필드는?","c":["ttl","content","depth","offset"],"a":0,"e":"content(검색 문자열), offset(검색 시작 위치), depth(검색 범위) 등은 페이로드 검사 옵션이다. ttl은 IP 헤더의 TTL 값을 검사하는 non-payload 옵션이다.","ce":["ttl은 IP 헤더의 TTL 값을 비교하는 non-payload 옵션으로, 페이로드 검사 옵션이 아니다.","content는 페이로드에서 찾을 문자열·바이트 패턴을 지정하는 대표적 페이로드 옵션이다.","depth는 content 검색을 페이로드 앞에서부터 몇 바이트까지 할지 지정하는 페이로드 옵션이다.","offset은 페이로드의 몇 번째 바이트부터 content 검색을 시작할지 지정하는 페이로드 옵션이다."],"rel":["2-11"]},{"n":31,"s":"s2","q":"아래 지문 빈칸에 들어갈 용어를 바르게 짝지은 것은?","c":["가 : 포트 미러링(Port Mirroring) 나 : 수집 모드(Acquisition Mode)","가 : 포트 미러링(Port Mirroring) 나 : 무차별 모드(Promiscuous Mode)","가 : 패킷 포워딩(Packet Forwarding) 나 : 수집 모드(Acquisition Mode)","가 : 패킷 포워딩(Packet Forwarding) 나 : 무차별 모드(Promiscuous Mode)"],"a":1,"e":"스위치 환경에서는 포트 미러링(SPAN)으로 다른 포트의 트래픽을 모니터링 포트로 복사해야 한다. 또한 NIC를 무차별(Promiscuous) 모드로 설정해야 자신의 MAC 주소가 아닌 프레임도 버리지 않고 운영체제로 전달한다.","ce":["포트 미러링은 맞지만 '수집 모드(Acquisition Mode)'라는 NIC 동작 모드는 없다. 자기 MAC이 아닌 프레임을 받으려면 무차별 모드가 필요하다.","스위치의 포트 미러링(SPAN)으로 다른 포트 트래픽을 복사받고, NIC를 무차별(Promiscuous) 모드로 두어야 자기 MAC이 아닌 프레임도 OS로 전달된다.","패킷 포워딩은 라우터·호스트가 받은 패킷을 다른 목적지로 전달하는 기능으로 스위치 트래픽 복사가 아니며, 수집 모드도 존재하지 않는 용어다.","무차별 모드는 맞지만 스위치에서 다른 포트 트래픽을 받는 기능은 패킷 포워딩이 아니라 포트 미러링이다."],"rel":["2-5"],"box":"Tcpdump는 네트워크 인터페이스를 거치는 패킷의 내용을 출력해 주는 프로그램이다. 스니핑 도구의 일종으로 자신의 컴퓨터로 들어오는 모든 패킷의 내용을 모니터링 할 수 있다. LAN 상의 모든 트래픽을 모니터링 하기 위해서는 이더넷 스위치에서의 ( 가 )을 통해 다른 컴퓨터로 향하는 트래픽도 수신하도록 한다. 이 때 이더넷 모드를 ( 나 )로 변경하여야 컴퓨터로 들어온 패킷을 운영체제에서 확인할 수 있다."},{"n":32,"s":"s2","q":"다음 중 VoIP 서비스에 대한 공격과 가장 거리가 먼 것은?","c":["Register 플러딩 공격","GET 플러딩 공격","INVITE 플러딩 공격","RTP 플러딩 공격"],"a":1,"e":"VoIP는 SIP(REGISTER, INVITE 등 메시지)로 호를 설정하고 RTP로 음성을 전송하므로 이들 메시지·패킷을 대량 전송하는 플러딩이 VoIP 공격이다. GET 플러딩은 HTTP GET 요청을 대량 전송하는 웹서버 대상 공격이다.","ce":["SIP REGISTER 메시지를 대량 전송해 등록 서버(Registrar)의 자원을 소진시키는 VoIP 공격이다.","GET 플러딩은 HTTP GET 요청을 대량 전송해 웹 서버를 마비시키는 공격으로 VoIP 서비스 대상이 아니다.","SIP INVITE 메시지를 대량 전송해 호 설정을 처리하는 SIP 서버·단말을 마비시키는 VoIP 공격이다.","음성 데이터를 나르는 RTP 패킷을 대량 전송해 통화 품질을 떨어뜨리거나 단말을 마비시키는 VoIP 공격이다."],"rel":["2-3"]},{"n":33,"s":"s2","q":"3개의 IP 패킷으로 fragmentation 되는 과정을 설명한 것이다. 세 번째 패킷의 필드에 들어갈 값으로 적절한 것은?","c":["가: 1040 , 나: 130","가: 1000 , 나: 370","가: 1040 , 나: 370","가: 1000 , 나: 125"],"a":2,"e":"각 조각의 데이터는 1500-20(헤더)=1480바이트이고 오프셋은 8바이트 단위이므로 두 번째 조각의 오프셋은 1480/8=185, 세 번째는 2960/8=370이다. 원 데이터그램을 4000바이트(데이터 3980)로 보면 남은 데이터는 1020바이트라 세 번째 조각 크기는 헤더 포함 1040이며, 마지막 조각이므로 MF 플래그는 0이다(지문 표에 원 크기가 없어 보기 조합 기준으로 판단).","ce":["오프셋 130은 틀렸다. 앞 두 조각이 1480바이트씩 총 2960바이트를 보냈으므로 세 번째 오프셋은 2960/8=370이다.","오프셋 370은 맞지만, 해설 기준 원 데이터그램 4000바이트(데이터 3980)에서 남은 데이터는 1020바이트이므로 패킷 크기는 헤더 포함 1040이지 1000이 아니다.","앞 두 조각의 데이터가 1480바이트씩이라 세 번째 오프셋은 2960/8=370이고, 남은 데이터 1020바이트+헤더 20바이트로 크기는 1040, MF 플래그는 0이다.","크기 1000과 오프셋 125 모두 틀렸다. 오프셋은 바이트 수를 8로 나눈 값으로 세 번째 조각은 370이다."],"rel":["2-12"],"box":"패킷사이즈 | flag | offset\n1500 | 1 | 0\n1500 | 1 | 185\n(가) | 0 | (나)"},{"n":34,"s":"s2","q":"스위치 장비가 동작하는 방식 중 전체 프레임을 모두 받고 오류 검출 후 전달하는 방식은?","c":["Cut-through 방식","Fragment-Free 방식","Direct Switching 방식","Store and Forward 방식"],"a":3,"e":"Store and Forward는 프레임 전체를 버퍼에 저장한 뒤 FCS(CRC)로 오류를 검사하고 전달해 신뢰성은 높지만 지연이 크다. Cut-through는 목적지 MAC만 읽고 바로 전달하며, Fragment-Free는 앞 64바이트까지만 확인한 뒤 전달한다.","ce":["Cut-through는 목적지 MAC 주소(앞 6바이트)만 읽고 즉시 전달해 지연이 가장 적지만 오류 프레임도 전달한다.","Fragment-Free는 충돌 조각을 거르기 위해 앞 64바이트까지만 받은 뒤 전달하므로 전체 프레임을 검사하지 않는다.","Direct Switching은 Cut-through와 같은 즉시 전달 방식을 가리키며 전체 프레임 오류 검사를 하지 않는다.","Store and Forward는 프레임 전체를 버퍼에 저장하고 FCS(CRC)로 오류를 검사한 뒤 전달해 신뢰성이 높지만 지연이 크다."],"rel":["2-12"]},{"n":35,"s":"s2","q":"VPN의 기능과 가장 거리가 먼 것은?","c":["데이터 기밀성","데이터 무결성","접근통제","시스템 무결성"],"a":3,"e":"VPN은 터널링과 암호화로 전송 데이터의 기밀성·무결성, 송신자 인증, 접근통제를 제공한다. 시스템(호스트) 자체의 무결성 보장은 VPN의 기능이 아니다.","ce":["VPN은 터널 구간의 데이터를 암호화해 기밀성을 제공한다.","VPN은 MAC·해시(IPSec AH/ESP 등)로 전송 중 데이터 변조 여부를 검증해 무결성을 제공한다.","VPN은 인증된 사용자·장비만 터널을 맺게 해 내부망 접근을 통제한다.","시스템 무결성은 /bin·/sbin 등 호스트 시스템 파일이 변조되지 않았음을 보장하는 것으로, 전송 구간을 보호하는 VPN의 기능이 아니다."],"rel":["2-7"]},{"n":36,"s":"s2","q":"스위칭 환경에서의 스니핑 공격 유형 중, 공격자가 \"나의 MAC 주소가 라우터의 MAC 주소이다.\"라는 위조된 ARP Reply를 브로드캐스트로 네트워크에 주기적으로 보내어 스위칭 네트워크상의 다른 모든 호스트들이 공격자 호스트를 라우터로 믿게 하는 공격은?","c":["Switching Jamming","ICMP Redirect","ARP Redirect","DNS Spoofing"],"a":2,"e":"ARP Redirect는 게이트웨이(라우터)의 IP에 공격자 MAC을 매핑한 위조 ARP Reply를 브로드캐스트해 네트워크 전체 호스트의 외부행 트래픽을 공격자로 우회시키는 공격이다. Switch Jamming은 MAC 테이블을 가득 채워 스위치를 허브처럼 동작하게 하고, ICMP Redirect는 ICMP 메시지로 라우팅 경로를 변경시킨다.","ce":["Switch Jamming은 위조 MAC으로 스위치 MAC 테이블을 넘치게 해 허브처럼 모든 포트로 트래픽이 퍼지게 하는 공격으로, 라우터로 위장하는 ARP 응답과 다르다.","ICMP Redirect는 위조 ICMP Redirect 메시지로 특정 호스트의 라우팅 경로를 공격자로 바꾸는 방식으로, ARP Reply를 쓰지 않는다.","ARP Redirect는 게이트웨이 IP에 공격자 MAC을 매핑한 위조 ARP Reply를 브로드캐스트해, 모든 호스트가 공격자를 라우터로 믿고 외부행 트래픽을 보내게 한다.","DNS 스푸핑은 위조 DNS 응답으로 도메인 이름을 가짜 IP로 해석하게 하는 공격으로, MAC 주소 위조와는 계층이 다르다."],"rel":["2-5"]},{"n":37,"s":"s2","q":"보안 위협과 공격에 대한 설명 중 옳지 않은 것은?","c":["분산 반사 서비스 거부 공격(DRDoS : Distributed Reflection DoS)은 DDoS의 발전된 공격 기술로서 공격자의 주소를 위장하는 IP Spoofing 기법과 실제 공격을 수행하는 좀비와 같은 감염된 반사체 시스템을 통한 트래픽 증폭 기법을 이용한다.","봇넷을 이용한 공격은 봇에 의해 감염된 다수의 컴퓨터가 좀비와 같이 C&C 서버를 통해 전송되는 봇 마스터의 명령에 의해 공격이 이루어지므로 공격자 즉 공격의 진원지를 추적하는데 어려움이 있다.","Smurf 공격은 ICMP Flooding 기법을 이용한 DoS 공격으로 Broadcast address 주소의 동작특성과 IP Spoofing 기법을 악용하고 있다.","XSS(Cross-Site Scripting) 공격은 공격 대상 사용자가 이용하는 컴퓨터 시스템의 브라우저 등에서 악성코드가 수행되도록 조작하여 사용자의 쿠키 정보를 탈취, 세션 하이재킹과 같은 후속 공격을 가능하게 한다."],"a":0,"e":"DRDoS의 반사체는 감염된 좀비가 아니라 DNS·NTP·웹 서버 같은 정상 서버로, 출발지를 피해자로 위조한 요청을 받아 응답을 피해자에게 보내게 된다. 봇넷의 C&C 구조, Smurf의 브로드캐스트·IP 위조 악용, XSS의 쿠키 탈취 설명은 옳다.","ce":["DRDoS의 반사체는 감염된 좀비가 아니라 DNS·NTP·웹 서버 같은 정상 서버다. 출발지를 피해자로 위조한 요청을 받아 응답을 피해자에게 보내게 된다.","봇넷 공격은 봇 마스터의 명령이 C&C 서버를 거쳐 다수 좀비에 전달되므로 실제 공격 진원지 추적이 어렵다는 설명이 옳다.","스머프는 출발지를 피해자로 위조한 ICMP Echo Request를 브로드캐스트 주소로 보내 응답이 피해자에게 몰리게 하므로 옳은 설명이다.","XSS는 사용자 브라우저에서 악성 스크립트를 실행시켜 쿠키를 탈취하고 세션 하이재킹 같은 후속 공격을 가능하게 하므로 옳다."],"rel":["2-3"]},{"n":38,"s":"s2","q":"다음 지문의 방법들이 탐지하려는 공격은?","c":["MITM 공격","TCP 세션 하이재킹","스푸핑 공격","스머프 공격"],"a":1,"e":"TCP 세션 하이재킹은 시퀀스 번호를 조작해 서버와 클라이언트를 비동기화 상태로 만들기 때문에 ACK Storm, 패킷 유실·재전송 증가, 예기치 않은 연결 리셋 같은 현상이 나타난다. 이 현상들을 탐지해 하이재킹을 식별한다.","ce":["MITM은 통신 경로 중간에서 트래픽을 중계·가로채는 공격으로, 비동기화 상태나 ACK Storm 같은 TCP 세션 이상 징후가 대표 탐지 지표는 아니다.","TCP 세션 하이재킹은 시퀀스 번호를 조작해 서버·클라이언트를 비동기화시키므로 ACK Storm, 패킷 유실·재전송 증가, 예기치 않은 리셋이 나타난다.","스푸핑은 주소 위조 전반을 뜻하며, 지문의 비동기화·ACK Storm은 세션을 탈취하는 하이재킹에서 나타나는 특유의 징후다.","스머프는 ICMP 브로드캐스트를 이용한 DoS로, 대량 ICMP Echo Reply 유입이 징후이며 TCP 세션 비동기화와 무관하다."],"rel":["2-5"],"box":"- 비동기화 상태 탐지\n- Ack Storm 탐지\n- 패킷의 유실과 재전송 증가 탐지\n- 예상치 못한 접속의 리셋"},{"n":39,"s":"s2","q":"L2 스위치로 구성된 네트워크 환경에서 스니핑 공격에 대한 설명으로 옳지 않은 것은?","c":["L2 스위치로 구성된 네트워크 환경에서 스니핑 공격을 시도하기 위해 사용되는 주요 방법들로는 ARP Spoofing ICMP Redirect, MAC Address Flooding 등이 있다.","ARP Spoofing 공격은 공격자가 대상 시스템에 조작된 ARP Request를 지속적으로 전송함으로써 이루어지며, 대상시스템의 ARP cache table을 변조한다.","ICMP Redirect 공격은 공격자가 ICMP Redirect 메시지를 생성하여 공격 대상 시스템에 전송함으로써 공격대상 시스템이 전송하는 패킷이 공격자에게 먼저 전송되도록 한다.","MAC Address Flooding 공격은 공격자가 조작된 MAC 주소를 프레임의 출발지 MAC 주소에 설정하여 보내는 과정을 반복함으로써 스위치가 더미허브처럼 동작하도록 한다."],"a":1,"e":"ARP 스푸핑은 조작된 ARP Reply(응답)를 지속적으로 보내 대상의 ARP 캐시 테이블을 변조하는 공격이다. ARP는 요청 없이 받은 Reply도 캐시에 반영하는 무상태 특성이 있어 악용된다.","ce":["스위치 환경에서 스니핑하려면 트래픽을 공격자에게 오게 해야 하므로 ARP 스푸핑, ICMP Redirect, MAC 플러딩이 대표 방법이라는 설명은 옳다.","ARP 스푸핑은 조작된 ARP Request가 아니라 조작된 ARP Reply를 지속적으로 보내 대상의 ARP 캐시를 변조한다.","위조 ICMP Redirect 메시지로 대상의 경로를 공격자로 바꾸면 대상이 보내는 패킷이 공격자에게 먼저 전달되므로 옳다.","출발지 MAC을 계속 바꾼 프레임으로 MAC 테이블을 넘치게 하면 스위치가 모든 포트로 플러딩하는 더미 허브처럼 동작하므로 옳다."],"rel":["2-5"]},{"n":40,"s":"s2","q":"IDS의 동작 순서를 바르게 나열한 것은?","c":["가 - 나 - 다 - 라","나 - 가 - 다 - 라","나 - 다 - 가 - 라","나 - 다 - 라 - 가"],"a":1,"e":"IDS는 데이터 수집(패킷·로그) → 데이터 가공 및 축약(필터링·정규화) → 분석 및 침입 탐지 → 보고 및 대응 순으로 동작한다. 가공하지 않은 원시 데이터는 양이 많아 분석 전에 축약 과정이 필요하다.","ce":["가공·축약은 수집한 원시 데이터를 대상으로 하므로 데이터 수집(나)보다 먼저 올 수 없다.","IDS는 데이터 수집 → 가공 및 축약(필터링·정규화) → 분석 및 침입 탐지 → 보고 및 대응 순으로 동작한다.","원시 데이터는 양이 많아 분석 전에 가공·축약해야 하므로 분석(다)이 가공(가)보다 먼저 올 수 없다.","가공·축약을 보고·대응 뒤 마지막에 두는 것은 처리 흐름과 맞지 않는다. 축약은 분석을 위한 전처리 단계다."],"rel":["2-9"],"box":"가. 데이터 가공 및 축약\n나. 데이터 수집\n다. 분석 및 침입탐지 단계\n라. 보고 및 대응(Reporting and Response)"},{"n":41,"s":"s3","q":"다음 중 XML 기반 Web 기술과 관련성이 가장 적은 것은?","c":["OCSP","UDDI","WSDL","SOAP"],"a":0,"e":"OCSP는 인증서의 폐지 여부를 실시간 조회하는 PKI 프로토콜이다. SOAP(메시지 교환), WSDL(서비스 기술), UDDI(서비스 등록·검색)는 XML 기반 웹 서비스의 3대 구성 기술이다.","ce":["OCSP는 인증서 폐지 여부를 실시간 조회하는 PKI 프로토콜로(ASN.1 기반 요청·응답) XML 웹 서비스 기술이 아니다.","UDDI는 웹 서비스를 등록·검색하는 XML 기반 레지스트리로 웹 서비스 3대 기술에 속한다.","WSDL은 웹 서비스의 인터페이스·위치·메시지 형식을 기술하는 XML 언어다.","SOAP은 XML 형식의 메시지를 HTTP 등으로 교환하는 웹 서비스 통신 프로토콜이다."],"rel":["3-14"]},{"n":42,"s":"s3","q":"전자입찰시스템 및 프로토콜의 특징에 대한 설명 중 틀린 것은?","c":["전자 입찰 도구로는 자바, 디지털서명, XML 등이 이용될 수 있다.","입찰 기간 마감은 여러 개의 입찰 서버가 있을 경우 단계적으로 마감된다.","전자 입찰은 입찰자, 입찰 공고자, 전자입찰시스템으로 구성된다.","전자 입찰 시 독립성, 비밀성, 무결성 등이 요구된다."],"a":1,"e":"전자입찰은 공정성을 위해 입찰 서버가 여러 개라도 입찰 마감이 동시에 이루어져야 하며, 단계적 마감은 먼저 마감된 정보를 이용한 부정을 가능하게 한다. 전자입찰에는 독립성, 비밀성, 무결성, 공정성, 안전성 등이 요구된다.","ce":["전자 입찰 시스템 구현에 자바, 입찰서 서명용 디지털 서명, 문서 표현용 XML 등을 사용할 수 있어 옳다.","입찰 서버가 여러 개여도 공정성을 위해 마감은 동시에 이루어져야 한다. 단계적 마감은 먼저 마감된 정보를 이용한 부정을 허용한다.","전자 입찰은 입찰자, 입찰 공고자, 전자입찰시스템으로 구성되므로 옳다.","전자 입찰에는 독립성, 비밀성, 무결성, 공정성, 안전성 등이 요구되므로 옳다."],"rel":["3-13"]},{"n":43,"s":"s3","q":"아래 그림은 공격자가 웹 해킹을 시도하는 화면이다. 아래 화면의 URL을 고려할 때, 공격자가 이용하는 웹 취약점으로 가장 적절한 것은?","c":["관리자 페이지 노출 취약점","파일 다운로드 취약점","파일 업로드 취약점","디렉터리 리스팅(Directory Listing) 취약점"],"a":0,"e":"admin.php처럼 추측하기 쉬운 경로의 관리자 페이지가 외부에서 접근 가능하면 무차별 대입 등으로 관리자 권한이 탈취될 수 있다. 대응은 관리자 페이지 경로 변경, 접근 IP 제한, 강한 인증 적용이다.","ce":["admin.php처럼 추측하기 쉬운 관리자 페이지가 외부에 노출되면 무차별 대입 등으로 관리자 권한이 탈취될 수 있다. URL이 관리자 페이지 노출을 보여 준다.","파일 다운로드 취약점은 download.php?file=../../etc/passwd처럼 파일 경로 파라미터를 조작하는 형태로, 지문 URL에 그런 파라미터가 없다.","파일 업로드 취약점은 웹셸 등 실행 가능한 파일을 업로드하는 공격으로, 관리자 경로 접근 URL과 무관하다.","디렉터리 리스팅은 인덱스 파일이 없는 디렉터리 경로(/upload/ 등) 요청 시 파일 목록이 노출되는 것으로, 특정 php 파일 요청과 다르다."],"rel":["3-4"],"box":"http://cms2580.cafe24.com/admin.php"},{"n":44,"s":"s3","q":"권장하는 함수에 속하는 것은?","c":["strcat()","gets()","sprintf()","strncpy()"],"a":3,"e":"strncpy()는 복사할 최대 길이를 지정할 수 있어 버퍼 오버플로우 방지를 위해 권장된다. strcat(), gets(), sprintf()는 입력 길이를 검사하지 않아 각각 strncat(), fgets(), snprintf()로 대체해야 하는 취약 함수다.","ce":["strcat()은 대상 버퍼 크기를 확인하지 않고 문자열을 이어 붙여 오버플로우 위험이 있어 strncat() 등으로 대체해야 한다.","gets()는 입력 길이를 전혀 제한하지 않는 대표적 위험 함수로 fgets()로 대체해야 한다.","sprintf()는 출력 버퍼 크기를 검사하지 않아 snprintf()로 대체해야 한다.","strncpy()는 복사할 최대 길이를 지정할 수 있어 버퍼 오버플로우 방지용 권장 함수로 분류된다(널 종료 보장은 별도 처리 필요)."],"rel":["1-10","3-9"]},{"n":45,"s":"s3","q":"보안담당자 A씨는 자바스크립트 코드를 분석하기 위해 파일을 열었더니 아래와 같은 내용을 확인할 수 있었다. 아래와 같은 기법의 명칭은?","c":["암호화","난독화","복호화","정규화"],"a":1,"e":"코드의 기능은 그대로 두고 변수명·문자열을 무의미하게 바꾸거나 인코딩해 사람이 읽기 어렵게 만드는 기법이 난독화(Obfuscation)다. 악성 자바스크립트는 eval·escape·인코딩 문자열 등으로 난독화되어 분석과 시그니처 탐지를 회피한다.","ce":["암호화는 키로 내용을 읽을 수 없게 만들어 복호화 키가 있어야 실행·열람이 가능하다. 원문 코드 그림이 누락되어 공식 정답(난독화) 기준으로 판단한다.","난독화는 코드 기능은 유지한 채 변수명·문자열을 무의미하게 바꾸거나 인코딩해 분석을 어렵게 하는 기법으로 공식 정답이다(원문 그림 누락).","복호화는 암호문을 평문으로 되돌리는 과정으로, 코드를 읽기 어렵게 만든 상태를 가리키는 명칭이 아니다.","정규화는 인코딩된 입력을 표준 형태로 변환해 비교·검증하기 쉽게 하는 과정으로, 난독화를 풀 때 쓰이는 반대 방향 작업이다."],"rel":["3-9"],"flag":"원문 그림 누락(comcbt 복원 오류로 코드 이미지 없음)"},{"n":46,"s":"s3","q":"다음 지문에서 설명한 프로토콜을 올바르게 나열한 것은?","c":["가:인출 프로토콜 나:지불 프로토콜 다:예치 프로토콜","가:인출 프로토콜 나:예치 프로토콜 다:지불 프로토콜","가:지불 프로토콜 나:인출 프로토콜 다:예치 프로토콜","가:예치 프로토콜 나:지불 프로토콜 다:인출 프로토콜"],"a":0,"e":"전자화폐 시스템은 은행이 사용자에게 화폐를 발급하는 인출(Withdrawal), 사용자가 상점에 지불하는 지불(Payment), 상점이 받은 화폐를 은행에 입금·결제받는 예치(Deposit) 프로토콜로 구성된다.","ce":["은행→사용자 화폐 발급은 인출, 사용자→상점 대금 지불은 지불, 상점→은행 입금·결제는 예치 프로토콜이다.","'나'(사용자가 상점에 지불)는 지불 프로토콜이고 '다'(상점이 은행에서 결제받음)가 예치 프로토콜인데 서로 바뀌었다.","'가'(은행이 사용자에게 발급)는 인출 프로토콜이고 '나'(상점에 지불)가 지불 프로토콜인데 서로 바뀌었다.","'가'는 인출, '다'는 예치 프로토콜인데 서로 바뀌었다."],"rel":["3-13"],"box":"가: 사용자와 은행 사이에서 수행되는 프로토콜로서 은행이 사용자에게 전자 화폐를 발급해 주는 절차를 명세한 프로토콜이다.\n나: 사용자와 상점 사이에서 수행되는 프로토콜로서 사용자가 구매 대금으로 자신의 전자 화폐를 상점에 지불하는 과정을 명세한 프로토콜이다.\n다: 상점과 은행 사이에서 수행되는 프로토콜로서 상점이 사용자로부터 받은 전자 화폐를 은행이 결제해 주는 프로토콜이다."},{"n":47,"s":"s3","q":"다음의 지문이 설명하고 있는 무선 랜 보안 표준은?","c":["WLAN","WEP","WPA","WPA2"],"a":3,"e":"WPA2는 2004년 IEEE 802.11i 표준을 완전히 구현한 것으로, 엔터프라이즈 모드에서 802.1X/EAP 인증 서버를 사용하고 AES 기반 CCMP로 암호화한다. WPA는 802.11i 초안 기반으로 RC4 기반 TKIP를 사용하며, WEP는 고정 키 RC4를 사용한다.","ce":["WLAN은 무선 근거리 통신망 자체를 가리키는 말로 보안 표준이 아니다.","WEP는 고정 공유키와 RC4를 사용하며 EAP 인증 서버나 동적 키 변경을 지원하지 않는 초기 표준이다.","WPA는 802.11i 초안 기반으로 RC4 기반 TKIP를 사용하므로 AES를 사용하는 802.11i 완전 준수 표준이 아니다.","WPA2는 2004년 IEEE 802.11i를 완전히 구현해 802.1X/EAP 인증 서버, 동적 키 관리, AES 기반 CCMP를 사용한다."],"rel":["2-10"],"box":"이 무선 랜 보안 표준은 IEEE 802 11(2004년)을 준수하며, 별도의 인증 서버를 이용하는 EAP 인증 프로토콜을 사용하고 암호 키를 동적으로 변경 가능하며, AES 등 강력한 블록 암호 알고리즘을 사용한다."},{"n":48,"s":"s3","q":"다음 지문이 설명하고 있는 DRM의 구성요소는?","c":["콘텐츠","워터마크","DOI","컨트롤러"],"a":0,"e":"DRM 구성요소 중 콘텐츠는 보호 대상이 되는 원본 디지털 정보이며, 패키저가 이를 암호화·메타데이터와 묶어 보안 컨테이너로 만든다. 컨트롤러는 사용자 단말에서 라이선스에 따라 콘텐츠 이용을 통제하는 요소다.","ce":["콘텐츠는 패키저가 암호화·메타데이터와 함께 패키징하기 전 원본으로, 지적재산권으로 보호되어야 할 정보 단위다.","워터마크는 콘텐츠에 저작권 정보를 삽입해 소유권을 증명하는 기술 요소로, 보호 대상 원본 자체가 아니다.","DOI는 디지털 콘텐츠에 부여하는 고유 식별 번호 체계로 원본 정보 단위를 뜻하지 않는다.","컨트롤러는 사용자 단말에서 라이선스를 확인해 콘텐츠 이용을 통제하는 구성요소다."],"rel":["3-12"],"box":"지적재산권으로 보호되어야 할 정보의 단위로 일반적으로 패 키지를 통해 패키징 되기 이전의 원본을 의미한다."},{"n":49,"s":"s3","q":"HTTP의 요청 메소드가 아닌 것은?","c":["GET","POST","PUSH","PUT"],"a":2,"e":"HTTP/1.1 요청 메소드는 GET, POST, PUT, DELETE, HEAD, OPTIONS, TRACE, CONNECT 등이다. PUSH는 HTTP 요청 메소드가 아니다(HTTP/2의 서버 푸시는 PUSH_PROMISE 프레임으로 구현).","ce":["GET은 지정 자원을 조회하는 HTTP 요청 메소드다.","POST는 요청 본문에 데이터를 담아 서버에 제출하는 HTTP 요청 메소드다.","PUSH는 HTTP 요청 메소드가 아니다. HTTP/2 서버 푸시는 서버가 PUSH_PROMISE 프레임으로 보내는 기능이다.","PUT은 지정한 URI에 자원을 생성·대체 저장하는 HTTP 요청 메소드다."],"rel":["3-3"]},{"n":50,"s":"s3","q":"다음 중 디지털 핑거프린팅 기술에 대한 설명으로 옳지 않은 것은?","c":["디지털 핑거프린팅 기술은 콘텐츠 내에 소유자 정보와 구매자 정보를 함께 포함하는 핑거프린트 정보를 삽입하여 후에 불법으로 배포된 콘텐츠로부터 배포자가 누구인지를 역추적 할 수 있도록 해 주는 기술이다.","핑거프린팅된 콘텐츠는 서로 다른 구매자 정보를 삽입하기 때문에 구매자에 따라 콘텐츠가 조금씩 다르다.","공모공격 (collusion attack)이란 여러 개의 콘텐츠를 서로 비교하여 워터마킹된 정보를 제거하거나 혹은 유추하여 다른 워터마크 정보를 삽입할 수 있는 것을 의미하는데, 이처럼 워터마킹은 공모공격에 취약하지만 디지털 핑거프린팅 기술은 이 공격에 매우 안전하다.","디지털 핑거프린팅 기술은 워터마킹 기술과 같이 삽입과 추출기술로 분류되는데 삽입기술은 삽입하는 정보만 다를뿐 워터마킹 기술과 동일하다."],"a":2,"e":"핑거프린팅은 구매자마다 다른 정보를 삽입하므로 여러 구매자가 복사본을 비교하면 차이 나는 부분을 찾아낼 수 있어 오히려 공모공격에 취약하며, 이를 막기 위한 공모 저항 코드가 연구된다. 구매자 정보 삽입을 통한 불법 배포자 추적, 구매자별로 콘텐츠가 다르다는 설명은 옳다.","ce":["핑거프린팅은 콘텐츠에 소유자와 구매자 정보를 삽입해 불법 배포 시 유출자를 역추적하게 하므로 옳다.","구매자마다 다른 정보를 삽입하므로 구매자별 콘텐츠가 조금씩 다르다는 설명은 옳다.","핑거프린팅은 구매자마다 삽입 정보가 달라 여러 사본을 비교하면 차이 부분이 드러나므로 오히려 공모공격에 취약하며, 이를 막는 공모 저항 코드가 필요하다.","핑거프린팅은 워터마킹처럼 삽입·추출 기술로 나뉘며 삽입 정보(구매자 정보)만 다를 뿐 삽입 기술은 같으므로 옳다."],"rel":["3-12"]},{"n":51,"s":"s3","q":"DNS Cache를 확인하는 윈도우 명령어는?","c":["ipconfig/dnsdisplay","ipconfig/displaydns","ipconfig/flushdns","ipconfig/dnsflush"],"a":1,"e":"ipconfig /displaydns는 로컬 DNS 리졸버 캐시에 저장된 레코드(이름, 유형, TTL, 주소)를 출력한다. ipconfig /flushdns는 DNS 캐시를 비우는 명령이며, dnsdisplay·dnsflush라는 옵션은 없다.","ce":["ipconfig에는 /dnsdisplay라는 옵션이 없다. 옵션 이름의 단어 순서가 뒤바뀐 형태다.","ipconfig /displaydns는 로컬 DNS 리졸버 캐시에 저장된 레코드 이름·유형·TTL·주소를 출력하므로 지문과 같은 결과가 나온다.","ipconfig /flushdns는 DNS 캐시를 비우는 명령으로, 캐시 내용을 출력하지 않는다(파밍 의심 시 캐시 초기화에 사용).","ipconfig에는 /dnsflush라는 옵션이 없으며, 캐시 삭제 옵션의 정확한 이름은 /flushdns다."],"rel":["3-7"],"box":"ds.kisa.or.kr\n----------------------------------------\n데이터 이름..........ds.kisa.or.kr\n데이터 유형............ 1\nTTL(Time To Live)....7972\n데이터 길이............. 5\n섹션. ............ 응답\n(호스트)레코드......... 121.254.150.6\n\nicms.kisa.or.kr\n----------------------------------------\n데이터 이름...........icms.kisa.or.kr\n데이터 유형.. .....1\nTTL(Time To Live)....82\n데이터 길이........... 5\n섹션........... 응답\n(호스트)레코드....... 121.254.229.1621"},{"n":52,"s":"s3","q":"아래는 vsftp의 설정파일인 vsftpd.conf에 대한 설명이다. 올바른 내용을 모두 고르시오.","c":["가, 나, 다","가, 다","가, 나, 다, 라","가, 다, 라"],"a":3,"e":"port_enable=YES는 PORT 명령을 이용하는 Active 모드 데이터 연결을 허용하는 설정이며, Passive 모드는 pasv_enable로 설정하므로 '나'가 틀리다. anonymous_enable(익명 접속, 보안상 NO 권장), xferlog_enable(전송 로그 기록, 위치는 vsftpd_log_file), local_enable(로컬 계정 접속 허용) 설명은 옳다.","ce":["'가'·'다'는 옳지만 '나'가 틀렸다. port_enable은 Active 모드(PORT 명령) 데이터 연결 허용 설정이고, 옳은 설명인 '라'도 빠졌다.","'가'·'다'는 옳지만, 로컬 계정 접속 허용을 설정하는 local_enable 설명 '라'도 옳으므로 빠뜨렸다.","'나'가 틀렸다. port_enable=YES는 Active 모드 데이터 연결을 허용하는 설정이며 Passive 모드는 pasv_enable로 설정한다.","익명 접속 설정 anonymous_enable(NO 권장), 전송 로그 xferlog_enable(위치는 vsftpd_log_file), 로컬 계정 접속 local_enable 설명이 옳다."],"rel":["3-1"],"box":"가: anonymous_enable : 익명 접속 설정으로 권장은 NO이다.\n나: port_enable : YES 값은 데이터 전송을 위해서 Passive Mode를 사용하도록 설정한다.\n다: xferlog_enable : FTP 로그를 남길 것인지에 대한 설정으로 로그 위치는 vsftpd_log file에서 설정한다.\n라: local_enable : 로컬 계정 사용자들의 접속 허용을 설정한다."},{"n":53,"s":"s3","q":"다음에서 설명하는 정보보호 기술은?","c":["핑거프린트(Fingerprint)","DOI(Digital Object Identifier)","디지털 워터마크(Digital watermark)","스테가노그래피(Steganography)"],"a":3,"e":"스테가노그래피는 이미지·오디오 등 커버 매체 속에 메시지를 숨겨 비밀 통신의 존재 자체를 감추는 기술이다. 디지털 워터마크는 저작권자 정보를 삽입해 소유권을 증명하는 목적이고, DOI는 디지털 콘텐츠 식별 번호 체계다.","ce":["핑거프린트는 콘텐츠에 구매자 정보를 삽입해 불법 배포자를 추적하는 기술로, 비밀 통신의 존재를 숨기는 목적이 아니다.","DOI는 디지털 콘텐츠에 부여하는 영구 식별 번호 체계로 정보 은닉 기술이 아니다.","디지털 워터마크는 저작권자 정보를 삽입해 소유권을 증명하는 목적이며, 워터마크의 존재가 알려져도 무방하다는 점에서 지문과 다르다.","스테가노그래피는 이미지·오디오 등 커버 매체에 메시지를 숨겨 통신 사실 자체를 감추는 기술로, 내용을 보호하는 암호화와 구분된다."],"rel":["3-12"],"box":"전달하려는 정보를 이미지, 오디오 파일에 인간이 감지할 수 없도록 숨겨 상대방에게 전달하는 기술을 총칭한다.\n일반 암호화 방법은 암호화를 통해 정보의 내용을 보호하는 기술인 반면에 이 기술은 정보의 존재 자체를 숨기는 보안 기술이다."},{"n":54,"s":"s3","q":"다음 지문은 무엇을 설명한 것인가?","c":["IPSec","PGP","SSL/TLS","SHTTP"],"a":2,"e":"SSL/TLS는 전송계층(TCP)과 응용계층 사이에서 동작하며 Handshake, Change Cipher Spec, Alert, Record 프로토콜로 구성된다. IPSec은 네트워크 계층(AH·ESP), PGP는 이메일 보안, S-HTTP는 응용계층 메시지 단위 보안 프로토콜이다.","ce":["IPSec은 네트워크 계층(IP)에서 AH·ESP로 보안을 제공하며 Handshake·Alert·Record 프로토콜로 구성되지 않는다.","PGP는 전자우편에 암호화·전자서명을 제공하는 응용 프로그램으로 전송 계층 위 하위 프로토콜 구성과 무관하다.","SSL/TLS는 TCP(전송 계층) 바로 위에서 상호 인증·기밀성·무결성을 제공하며 Handshake, Change Cipher Spec, Alert, Record 프로토콜로 구성된다.","S-HTTP는 HTTP 메시지 단위로 보안을 적용하는 응용 계층 프로토콜로, 지문의 4개 하위 프로토콜 구성을 갖지 않는다."],"rel":["2-7"],"box":"- TCP/IP 프로토콜에서 전송 계층 바로 위에 위치하며 보안기능을 수행한다.\n- 사용자 상호인증, 데이터 기밀성, 메시지 무결성 등의 보안서비스를 제공한다.\n- Handshake 프로토콜, Change Cipher Spec, Alert 프로토콜 Record 프로토콜로 구성된다."},{"n":55,"s":"s3","q":"다음 지문이 설명하는 전자 거래 문서의 유형으로 알맞은 것은?","c":["SWIFT","ebXML","EDI(Electronic Data Interchange)","XML(Extensible Markup Language)"],"a":3,"e":"XML은 SGML의 구조화·확장성과 HTML의 웹 친화성을 결합해 W3C가 제안(1996년 초안, 1998년 권고)한 마크업 언어다. ebXML은 XML을 기반으로 한 전자상거래 프레임워크이고, EDI는 기업 간 정형 문서 교환 방식, SWIFT는 국제 은행 간 통신망이다.","ce":["SWIFT는 국제 은행 간 금융 메시지를 교환하는 통신망·표준으로 SGML·HTML의 장점을 결합한 마크업 언어가 아니다.","ebXML은 XML을 기반으로 한 전자상거래 비즈니스 프레임워크로, 1996년 W3C가 제안한 마크업 언어 자체는 아니다.","EDI는 기업 간 정형 거래 문서를 표준 형식으로 전자 교환하는 방식으로 웹 마크업 언어가 아니다.","XML은 SGML의 구조화·확장성과 HTML의 웹 친화성을 결합해 1996년 W3C가 제안한 마크업 언어로 전자거래 표준 문서 형식으로 쓰인다."],"rel":["3-14"],"box":"데이터의 저장 및 교환을 위한 대표적 문서교환 표준인 SGML (Standard Generalized Markup Language)과 HTML (Hyper Text Markup Language)의 장점을 모두 가지고 있다.\n1996년 W3C에서 제안하였으며, 웹상에서 구조화된 문서를 전송 가능하도록 설계된 웹표준이며, 최근 전자거래 및 각종 업무에서 표준으로 폭넓게 채택되어 사용되고 있다."},{"n":56,"s":"s3","q":"다음 보기가 설명하는 취약성은?","c":["Poodle","Ghost","Shellshock","Heartbleed"],"a":3,"e":"하트블리드(CVE-2014-0160)는 OpenSSL의 Heartbeat 확장에서 요청 길이 검증이 누락되어 한 번에 최대 64KB의 서버 메모리를 읽어 낼 수 있는 취약점이다. POODLE은 SSL 3.0 패딩 오라클, Shellshock은 Bash 환경변수 명령 실행, GHOST는 glibc gethostbyname 버퍼 오버플로우 취약점이다.","ce":["POODLE은 SSL 3.0의 CBC 패딩 검증 결함을 이용해 암호문을 한 바이트씩 해독하는 패딩 오라클 공격이다.","GHOST는 glibc의 gethostbyname() 함수에서 발생한 버퍼 오버플로우 취약점이다.","Shellshock은 Bash가 환경변수에 정의된 함수 뒤의 명령을 실행해 버리는 원격 명령 실행 취약점이다.","하트블리드는 OpenSSL Heartbeat 확장에서 요청 길이 검증이 빠져 한 번에 최대 64KB의 서버 메모리를 읽어 낼 수 있는 취약점으로, 개인키 유출까지 가능하다."],"rel":["2-7"],"box":"이것은 암호화를 위해 대중적으로 사용되는 OpenSSL 라이브러리에서 서버 메모리 중 64KB의 데이터에 대해 공격자가 덤프를 뜰 수 있게 하는 취약점이다. 해당 취약점을 이용하여 시스템 메모리에 저장되어 있는 무의미한 작은 정보들을 지속적으로 유출시키면, 이러한 무의미한 정보들이 모여 하나의 완전한 유의미한 정보가 될 수 있다. 특히 개인키의 경우 암호화하여 전달되는 데이터를 모두 열람할 수 있는 핵심정보 이기때문에 매우 심각한 취약성이라 할 수 있다."},{"n":57,"s":"s3","q":"다음 표는 Apache 웹 서버의 주요 파일에 대한 접근권한을 나타낸다. 각각에 들어갈 내용으로 적절한 것은?","c":["가:640 나:root 다:511","가:511 나:nobody 다:640","가:640 나:nobody 다:511","가:511 나:root 다:640"],"a":1,"e":"httpd 실행 파일은 실행만 가능하도록 511(r-x--x--x), 웹 인증용 passwd 파일은 웹서버 프로세스 계정(nobody) 그룹이 읽을 수 있도록 그룹을 nobody로, httpd.conf 설정 파일은 소유자만 쓰고 그룹은 읽기만 하도록 640으로 설정한다.","ce":["httpd 실행 파일을 640으로 두면 실행 권한이 없어 서버가 실행되지 않으며, httpd.conf를 511로 두면 설정 파일을 읽기 어렵다(가·다 뒤바뀜).","httpd는 실행만 허용하는 511, passwd는 웹서버 프로세스 계정 nobody 그룹이 읽을 수 있도록 그룹 nobody, httpd.conf는 소유자만 수정 가능한 640이다.","그룹 nobody는 맞지만 httpd(실행 파일)에 640, httpd.conf에 511을 주어 두 권한이 뒤바뀌었다.","권한 511·640 배치는 맞지만 passwd 그룹을 root로 두면 nobody 권한으로 동작하는 웹서버가 인증 파일을 읽을 수 없다."],"rel":["3-4"],"box":"디렉터리 | 소유자 | 그룹 | 권한\nbin | root | root | 755\nhttpd | root | root | ( 가 )\npasswd | root | ( 나 ) | 640\nhttpd.conf | root | nobody | ( 다 )\nlog | root | root | 755"},{"n":58,"s":"s3","q":"SSL/TLS에 대한 설명으로 옳은 것은?","c":["상위계층 프로토콜의 메시지에 대해 기밀성과 부인방지를 제공한다.","종단 대 종단 간의 안전한 서비스를 제공하기 위해 UDP를 사용하도록 설계하였다.","레코드(Record) 프로토콜에서는 응용계층의 메시지에 대해 단편화, 압축, MAC 첨부, 암호화 등을 수행한다.","암호명세 변경(Change Cipher Spec) 프로토콜에서는 클라이언트와 서버가 사용할 알고리즘과 키를 협상한다."],"a":0,"e":"공식 정답은 ①로 발표되었으나, SSL/TLS는 대칭키 MAC을 사용하므로 기밀성·무결성·서버(상호) 인증은 제공해도 부인방지는 제공하지 않는다는 이의가 있다. 교과서적으로는 ③처럼 Record 프로토콜이 단편화·압축·MAC 첨부·암호화를 수행하는 것이 옳다. ②는 TCP를 사용하므로 틀리고, ④의 알고리즘·키 협상은 Handshake 프로토콜의 역할이다.","ce":["공식 정답이나 논란이 있다. SSL/TLS는 기밀성은 제공하지만 대칭키 MAC을 쓰므로 부인방지는 제공하지 않는다는 이의가 제기되었다.","SSL/TLS는 신뢰성 있는 연결형 전송을 전제로 TCP 위에서 동작하도록 설계되었다. UDP용은 별도의 DTLS다.","Record 프로토콜이 응용 데이터를 단편화·압축하고 MAC을 붙여 암호화하는 것은 교과서적으로 옳아, 이 보기가 정답이라는 이의가 있다.","알고리즘과 키를 협상하는 것은 Handshake 프로토콜이다. Change Cipher Spec은 협상된 방식을 이후 적용한다고 알리는 메시지일 뿐이다."],"rel":["2-7"],"flag":"정답 논란: 공식 정답 ①이나 SSL/TLS는 부인방지를 제공하지 않고 ③(Record 프로토콜의 단편화·압축·MAC·암호화)이 교과서적으로 옳다는 오류 신고 있음(comcbt 해설집)"},{"n":59,"s":"s3","q":"다음 중 PGP의 기능이 아닌 것은?","c":["기밀성","전자서명","단편화와 재조립","송수신 부인방지"],"a":3,"e":"PGP는 기밀성(암호화), 전자서명(인증·무결성·송신 부인방지), 압축, 전자우편 호환성(Radix-64), 단편화와 재조립 기능을 제공한다. 수신자가 메일을 받았음을 증명하는 수신 부인방지는 제공하지 않으므로 '송수신 부인방지'는 PGP 기능이 아니다.","ce":["PGP는 세션키로 메시지를 대칭 암호화하고 세션키를 수신자 공개키로 암호화해 기밀성을 제공한다.","PGP는 송신자 개인키로 서명해 메시지 인증·무결성과 송신 부인방지를 제공한다.","PGP는 메일 시스템의 메시지 크기 제한에 맞추기 위한 단편화와 재조립 기능을 제공한다.","PGP의 전자서명은 송신 부인방지만 제공할 뿐, 수신자가 메일을 받았음을 증명하는 수신 부인방지 기능은 없다."],"rel":["3-2"]},{"n":60,"s":"s3","q":"다음 중 데이터베이스 보안 유형이 아닌 것은?","c":["접근 제어(Access Control)","허가 규칙(Authorization Rule)","암호화(Encryption)","집합(Aggregation)"],"a":3,"e":"데이터베이스 보안 유형(수단)은 접근 제어, 허가 규칙, 뷰, 암호화 등이다. 집합(Aggregation)은 낮은 등급 정보들을 모아 높은 등급 정보를 알아내는 DB 보안 위협에 해당한다.","ce":["접근 제어는 사용자별로 DB 객체 접근을 허용·거부하는 대표적 DB 보안 유형이다.","허가 규칙은 사용자가 어떤 객체에 어떤 연산(SELECT·UPDATE 등)을 할 수 있는지 정의하는 DB 보안 유형이다.","암호화는 저장·전송되는 DB 데이터를 읽을 수 없게 변환하는 DB 보안 유형이다.","집합(Aggregation)은 낮은 등급 정보를 모아 높은 등급 정보를 알아내는 DB 보안 위협으로 보안 유형(대책)이 아니다."],"rel":["3-8"]},{"n":61,"s":"s4","q":"국내 암호모듈 검증에 있어 검증대상 암호알고리즘으로 지정된 비밀키 블록암호 알고리즘으로 구성된 것은?","c":["가:AES, 나:LEA 다:SEED","가:AES, 나:LEA 다:ARIA","가:ARIA, 나:LEA 다:SEED","가:ARIA, 나:AES 다:SEED"],"a":2,"e":"KCMVP(암호모듈 검증제도)의 검증대상 블록암호는 국내 개발 알고리즘인 ARIA, SEED, LEA이며, AES는 검증대상에 포함되지 않는다(시험 당시 기준, 개정 여부 확인).","ce":["AES는 미국 표준 블록 암호로, 시험 당시 KCMVP 검증대상 블록암호(ARIA·SEED·LEA)에 포함되지 않았다.","LEA·ARIA는 검증대상이지만 AES가 포함되지 않았고 SEED가 빠졌다.","KCMVP 검증대상 블록암호는 국내 개발 알고리즘인 ARIA, LEA, SEED다(시험 당시 기준, 개정 여부 확인).","ARIA·SEED는 검증대상이지만 AES는 포함되지 않고 LEA가 빠졌다."],"rel":["4-2","5-6"]},{"n":62,"s":"s4","q":"사용자 인증에서는 3가지 유형의 인증방식을 사용하고 있으며, 보안을 강화하기 위하여 2가지 유형을 결합하여 2 factor 인증을 수행한다. 다음 중 2 factor 인증으로 적절하지 않은 것은?","c":["USB 토큰, 비밀번호","스마트카드, PIN(Personal Identification Number)","지문, 비밀번호","음성인식, 수기서명"],"a":3,"e":"2 factor 인증은 지식(비밀번호·PIN), 소유(토큰·스마트카드), 존재(생체) 중 서로 다른 두 유형을 결합해야 한다. 음성인식과 수기서명은 모두 생체(행위) 특성 기반 인증으로 같은 유형이라 2 factor가 아니다.","ce":["USB 토큰(소유)과 비밀번호(지식)는 서로 다른 유형을 결합하므로 2 factor 인증이다.","스마트카드(소유)와 PIN(지식)은 서로 다른 유형을 결합하므로 2 factor 인증이다.","지문(존재·생체)과 비밀번호(지식)는 서로 다른 유형을 결합하므로 2 factor 인증이다.","음성인식과 수기서명은 둘 다 사용자의 행위적 생체 특성(존재 기반)으로 같은 유형이라 2 factor 인증이 아니다."],"rel":["4-8"]},{"n":63,"s":"s4","q":"강제적 접근통제 정책에 대한 설명으로 옳지 않은 것은?","c":["모든 주체와 객체에 보안관리자가 부여한 보안레이블이 부여되며 주체가 객체를 접근할 때 주체와 객체의 보안 레이블을 비교하여 접근허가 여부를 결정한다.","미리 정의된 보안규칙들에 의해 접근허가 여부가 판단되므로 임의적 접근통제 정책에 비해 객체에 대한 중앙 집중적인 접근통제가 가능하다.","강제적 접근통제 정책을 지원하는 대표적 접근통제 모델로는 BLP(Bell-Lapadula), Biba 등이 있다.","강제적 접근통제 정책에 구현하는 대표적 보안 메커니즘으로 Capability List와 ACL(Access Control List) 등이 있다"],"a":3,"e":"Capability List와 ACL은 주체·객체별로 권한을 나열하는 접근통제 행렬의 구현 방식으로 임의적 접근통제(DAC)의 대표 메커니즘이다. MAC은 보안 레이블(등급) 비교 방식으로 구현된다.","ce":["MAC은 보안관리자가 모든 주체·객체에 보안 레이블을 부여하고, 접근 시 두 레이블을 비교해 허가 여부를 결정하므로 옳다.","사전에 정의된 보안 규칙으로 판단하므로 소유자 재량에 맡기는 DAC보다 중앙 집중적 통제가 가능하다는 설명은 옳다.","BLP(기밀성)와 Biba(무결성)는 보안 레이블 비교에 기반한 대표적 MAC 모델이므로 옳다.","Capability List와 ACL은 사용자·객체별 권한을 나열하는 접근통제 행렬 구현 방식으로 임의적 접근통제(DAC)의 대표 메커니즘이다. MAC은 보안 레이블로 구현된다."],"rel":["4-10"]},{"n":64,"s":"s4","q":"다음 지문이 설명하고 있는 프로토콜은?","c":["Needham-Schroeder 프로토콜","공개키 암호","KDC 기반 키 분배","Diffie-Hellman 프로토콜"],"a":3,"e":"Diffie-Hellman 키 교환은 양측이 공개값을 교환해 각자 같은 비밀키를 계산하며, 이산대수 문제의 어려움에 안전성을 둔다. 상대방 인증 절차가 없어 중간자 공격에 취약하므로 전자서명 등으로 인증을 보완한다.","ce":["Needham-Schroeder는 KDC(또는 공개키)를 이용해 세션키를 분배·인증하는 프로토콜로, 이산대수 기반 공동 계산 방식이 아니다.","공개키 암호는 공개키·개인키 쌍을 쓰는 암호 방식의 총칭으로, 지문처럼 공유 비밀키를 함께 계산해 만드는 특정 프로토콜을 가리키지 않는다.","KDC 기반 키 분배는 신뢰 기관이 키를 생성해 전달하는 방식이라 양측이 공유키를 계산해 만들지 않는다.","Diffie-Hellman은 공개값을 교환해 양측이 같은 비밀키를 각자 계산하며, 이산대수 문제에 기반하고 상대 인증이 없어 중간자 공격에 취약하다."],"rel":["4-4","4-12"],"box":"- 공유할 암호키를 계산하며 만들어낸다.\n- 유한체상의 이산대수문제를 풀기 어려움에 기반한다.\n- 중간자 공격이나 재전송 공격에는 취약하다."},{"n":65,"s":"s4","q":"아래 보기에서 설명하고 있는 공격기법은?","c":["차분 공격(Differential Cryptanalysis)","선형 공격(Linear Cryptanalysis)","전수 공격(Exhaustive key search)","통계적 분석(Statistical analysis)"],"a":2,"e":"전수 공격(Exhaustive key search)은 가능한 모든 키를 대입해 보는 방법으로, 키 공간이 작으면 확실하지만 키 길이가 길면 계산량 때문에 사실상 불가능하다. Diffie와 Hellman은 1977년 DES의 56비트 키가 전수 공격에 취약함을 분석했다. 차분 공격은 Biham·Shamir, 선형 공격은 Matsui가 제안했다.","ce":["차분 공격은 1990년 Biham·Shamir가 제안한 선택 평문 공격으로 평문 쌍의 차이 전파를 이용하며, 모든 경우를 조사하지 않는다.","선형 공격은 1993년 Matsui가 제안한 기지 평문 공격으로 선형 근사식을 이용한다.","전수 공격은 가능한 모든 키를 대입하는 방법으로, 키 공간이 작으면 확실하지만 크면 실현 불가능하다. Diffie와 Hellman이 DES 키 전수조사 가능성을 분석했다(지문 연도는 원문 표기).","통계적 분석은 암호문의 문자 빈도 같은 통계 특성으로 평문을 추정하는 방법으로 모든 경우를 조사하는 방식이 아니다."],"rel":["4-1"],"box":"1997년 Diffie와 Hellman이 제안하였으며 암호화할 때 일어날 수 있는 모든 가능한 경우에 대하여 조사하는 방법으로 경우 의 수가 적을 때는 가장 정확한 방법이지만, 일반적으로 경우의 수가 많은 경우에는 실현 불가능하다.","flag":"지문 '1997년'은 원문 그대로(Diffie·Hellman의 DES 전수조사 분석은 1977년)"},{"n":66,"s":"s4","q":"소프트웨어로 구성되는 난수 생성기를 가장 적절하게 표현한 것은?","c":["SRNG","HRNG","PRNG","RRNG"],"a":2,"e":"소프트웨어 난수 생성기는 시드(seed)로부터 결정적 알고리즘으로 난수처럼 보이는 수열을 만드는 의사난수 생성기(PRNG)다. 열잡음 같은 물리 현상을 이용하는 하드웨어 기반 생성기는 TRNG(진난수 생성기)라 한다.","ce":["SRNG는 소프트웨어 난수 생성기를 가리키는 표준 용어가 아니다. 소프트웨어 알고리즘 방식은 의사난수 생성기(PRNG)라 부른다.","HRNG(하드웨어 난수 생성기)는 열잡음 등 물리 현상을 이용하는 방식으로 소프트웨어 구성이 아니다.","PRNG는 시드로부터 결정적 알고리즘으로 난수처럼 보이는 수열을 만드는 소프트웨어 난수 생성기다.","RRNG는 통용되는 난수 생성기 분류 용어가 아니다. 물리적 진난수 생성기는 TRNG라 한다."],"rel":["4-1"]},{"n":67,"s":"s4","q":"아래 보기에서 설명하고 있는 공격기법은?","c":["차분 공격(Differential Cryptanalysis)","선형 공격(Linear Cryptanalysis)","전수 공격(Exhaustive key search)","통계적 분석(Statistical analysis)"],"a":0,"e":"차분 공격은 Biham과 Shamir가 제안한 선택 평문 공격으로, 평문 쌍의 차분이 암호문 쌍의 차분으로 전파되는 확률적 특성을 이용해 키를 추정한다. 선형 공격은 1993년 Matsui가 제안한 기지 평문 공격으로 선형 근사식을 이용한다.","ce":["차분 공격은 1990년 Biham과 Shamir가 개발한 선택 평문 공격으로, 평문 쌍의 비트 차이와 암호문 쌍의 비트 차이 관계로 키를 찾는다.","선형 공격은 1993년 Matsui가 제안한 기지 평문 공격으로, 차이가 아닌 선형 근사식을 이용한다.","전수 공격은 모든 키를 대입하는 방법으로 평문 쌍의 차이를 분석하지 않는다.","통계적 분석은 암호문의 통계 특성(빈도 등)을 이용하는 방법으로 선택 평문 쌍을 쓰지 않는다."],"rel":["4-1"],"box":"1990년 Biham과 Shamir에 의하여 개발된 선택 평문 공격법 으로, 두 개의 평문 블록들의 비트 차이에 대하여 대응되는 암호문 블록들의 비트 차이를 이용하여 사용된 암호키를 찾아 내는 방법이다."},{"n":68,"s":"s4","q":"다음의 장·단점을 가진 인증기술은?","c":["커버로스(Kerberos) 프로토콜","OTP 인증","ID/패스워드 인증","메시지 출처 인증"],"a":0,"e":"커버로스는 KDC(인증서버 AS와 티켓발급서버 TGS)가 발급한 티켓과 대칭키로 인증하고 데이터 기밀성·무결성을 제공한다. 그러나 KDC가 단일 장애점이어서 KDC 장애 시 전체 인증이 불가능하고, 시간 동기화가 필요하다는 단점이 있다.","ce":["커버로스는 KDC(AS·TGS)가 발급한 티켓과 대칭키로 기밀성·무결성을 보장하지만, KDC가 단일 장애점이어서 장애 시 전체 서비스를 이용할 수 없다.","OTP 인증은 매번 바뀌는 일회용 비밀번호로 재사용 공격을 막는 방식으로, 인증서버·티켓발급서버 구조를 갖지 않는다.","ID/패스워드 인증은 지식 기반 단일 인증으로 데이터 기밀성·무결성을 제공하지 않으며 KDC가 없다.","메시지 출처 인증은 MAC·전자서명으로 메시지 송신자를 확인하는 서비스로 키 분배센터 장애와 무관하다."],"rel":["2-8","4-12"],"box":"- 장점 : 데이터의 기밀성, 무결성 보장\n- 단점 : 키 분배센터(인증서버 & 티켓발급서버) 에 오류 발생시 전체 서비스 이용불가"},{"n":69,"s":"s4","q":"키 관리는 키 생성, 분배, 설치, 갱신, 취소 폐기, 저장, 복구 등을 요구하는 포괄적인 개념이다. 한 사용자 또는 기관이 비밀키를 설정하여 다른 사용자에게 전달하는 기술을 키 분배라고 하며, 둘 또는 그 이상의 사용자가 공개된 통신 채널을 통하여 비밀키를 설정하는 것을 키 합의라고 한다. 다음 중 키 분배 방식에 해당되는 것은?","c":["Diffie-Hellman 방식","Matsumoto-Takashima-Imai 방식","Okamoto-Nakamura 방식","Needham-Schroeder 방식"],"a":3,"e":"Needham-Schroeder 프로토콜은 KDC(신뢰기관)가 세션키를 생성해 양측에 전달하는 키 분배 방식이다. Diffie-Hellman, Matsumoto-Takashima-Imai, Okamoto-Nakamura 방식은 양측이 공개 정보를 교환해 공동으로 키를 계산하는 키 합의 방식이다.","ce":["Diffie-Hellman은 양측이 공개값을 교환해 공동으로 비밀키를 계산하는 키 합의 방식이다.","Matsumoto-Takashima-Imai 방식은 각자의 공개 정보로 양측이 같은 키를 계산하는 키 합의(키 사전 분배) 방식으로 분류된다.","Okamoto-Nakamura 방식은 신분 기반으로 양측이 공동 계산하는 키 합의 방식으로 분류된다.","Needham-Schroeder는 신뢰 기관(KDC)이 세션키를 생성해 양측에 전달하는 키 분배 방식이다."],"rel":["4-12"]},{"n":70,"s":"s4","q":"다음 중 해시함수의 특징이 아닌 것은?","c":["고정된 크기의 해시코드를 생성함","일방향성(one-wayness)","강 · 약 충돌 회피성이 보장됨","안전한 키를 사용할 경우 결과값의 안전성이 보장됨"],"a":3,"e":"해시함수는 키를 사용하지 않는 공개 함수로, 임의 길이 입력에 대해 고정 길이 출력, 일방향성, 약·강 충돌 저항성을 가진다. 비밀키를 사용해 안전성을 확보하는 것은 MAC(HMAC 등)의 특징이다.","ce":["해시함수는 임의 길이 입력을 고정 크기 해시코드로 출력하는 것이 기본 특징이다.","해시값에서 원래 입력을 찾기 어려운 일방향성은 해시함수의 핵심 특징이다.","약한 충돌 회피성(제2 역상 저항성)과 강한 충돌 회피성은 안전한 해시함수가 갖춰야 할 특징이다.","해시함수는 키를 사용하지 않는 공개 함수다. 비밀키로 결과의 안전성을 확보하는 것은 MAC(HMAC 등)의 특징이다."],"rel":["4-5"]},{"n":71,"s":"s4","q":"다음 중 암호시스템에 대한 수동적 공격은?","c":["트래픽 분석","메시지 순서 변경","메시지 위조","삭제 공격"],"a":0,"e":"수동적 공격은 데이터를 변경하지 않고 엿보는 공격으로 도청(메시지 내용 공개)과 트래픽 분석이 해당한다. 메시지 순서 변경, 위조, 삭제는 데이터를 조작하는 능동적 공격이다.","ce":["트래픽 분석은 암호화된 내용을 바꾸지 않고 통신 빈도·길이·주체만 관찰해 정보를 추론하는 수동적 공격이다.","메시지 순서 변경은 전송 메시지를 재배열해 처리를 방해하는 능동적 공격이다.","메시지 위조는 가짜 메시지를 만들어 삽입하는 능동적 공격이다.","삭제 공격은 전송 중인 메시지를 지워 전달을 막는 능동적 공격이다."],"rel":["4-1"]},{"n":72,"s":"s4","q":"다음 중 스트림 암호의 특징으로 알맞지 않은 것은?","c":["원타임 패스워드를 실용적으로 구현할 목적으로 개발되었다.","짧은 주기와 높은 선형복잡도가 요구되며 주로 LFSR을 이용한다.","블록단위 암호화 대비 비트단위로 암호화하여 암호화 시간이 더 빠르다.","블록 암호의 CFB, OFB 모드는 스트림 암호와 비슷한 역할을 한다."],"a":1,"e":"스트림 암호의 키 스트림은 반복되면 안전성이 떨어지므로 '긴 주기'와 높은 선형복잡도가 요구된다. 스트림 암호는 OTP(일회성 패드)를 실용화하려는 목적에서 출발했고, 블록 암호의 CFB·OFB 모드는 키 스트림을 만들어 스트림 암호처럼 동작한다.","ce":["스트림 암호는 매번 다른 키를 쓰는 원타임 패드를 의사난수 키 스트림으로 실용화하려는 목적에서 출발했으므로 옳다.","키 스트림이 반복되면 안전성이 떨어지므로 짧은 주기가 아니라 '긴 주기'와 높은 선형복잡도가 요구된다.","비트·바이트 단위로 키 스트림과 XOR하므로 블록 단위 처리보다 빠르고 하드웨어 구현이 간단하다는 설명은 옳다.","CFB·OFB 모드는 블록 암호로 키 스트림을 만들어 평문과 XOR하므로 스트림 암호처럼 동작한다는 설명은 옳다."],"rel":["4-2"]},{"n":73,"s":"s4","q":"\"한 단계 앞의 암호문 블록\"을 대신할 비트열을 무엇이라 하는가?","c":["패딩","초기화 벡터","스트림 블록","운영모드"],"a":1,"e":"CBC·CFB 등 운영 모드는 이전 암호문 블록을 다음 블록 처리에 사용하는데, 첫 블록에는 앞 블록이 없으므로 이를 대신하는 임의의 비트열인 초기화 벡터(IV)를 사용한다. 패딩은 마지막 블록의 길이를 블록 크기에 맞추기 위해 덧붙이는 데이터다.","ce":["패딩은 마지막 블록 길이를 블록 크기에 맞추려고 덧붙이는 데이터로, 이전 암호문 블록을 대신하지 않는다.","CBC·CFB 등은 이전 암호문 블록을 다음 처리에 쓰는데, 첫 블록에는 앞 블록이 없으므로 이를 대신하는 임의 비트열로 초기화 벡터(IV)를 사용한다.","스트림 블록은 운영 모드에서 쓰이는 표준 용어가 아니다.","운영모드는 ECB·CBC·CFB처럼 블록 암호를 반복 적용하는 방식 전체를 가리키며 특정 비트열이 아니다."],"rel":["4-3"]},{"n":74,"s":"s4","q":"이중서명(Dual Signature)은 사용자가 구매정보와 지불정보를 각각 해시한 후 해시값을 합하여 다시해시 그리고 최종 해시값을 카드 사용자의 개인키로 암호화한 서명을 말하는 것으로 이중서명 절차이다. 이중서명을 사용하는 것으로 적합한 것은?","c":["SET","PKI","전자화폐","전자수표"],"a":0,"e":"SET(Secure Electronic Transaction)은 이중서명을 이용해 상점은 지불정보를, 은행(지불 게이트웨이)은 구매정보를 볼 수 없게 하면서 두 정보의 연결성을 검증한다. 이는 신용카드 기반 전자결제 프로토콜인 SET의 핵심 기술이다.","ce":["SET은 신용카드 전자결제 프로토콜로, 이중서명으로 상점은 지불정보를, 은행은 구매정보를 보지 못하게 하면서 두 정보의 연계를 검증한다.","PKI는 공개키 인증서를 발급·관리하는 기반 구조일 뿐, 구매정보·지불정보를 묶는 이중서명 절차를 정의하지 않는다.","전자화폐는 은닉 서명 등으로 익명성을 보장하는 방식이며, 구매·지불정보 이중서명은 SET의 고유 기술이다.","전자수표는 지불인의 전자서명으로 수표를 발행하는 방식으로 이중서명과 무관하다."],"rel":["4-6","3-10"]},{"n":75,"s":"s4","q":"다음 지문이 설명하는 것은?","c":["Diffie-Hellman Protocol","Kerberos Protocol","Needham-schroeder Protocol","SET Protocol"],"a":1,"e":"커버로스는 MIT의 Athena 프로젝트에서 개발된 대칭키(비밀키) 기반 티켓 인증 시스템으로, KDC가 세션키와 티켓을 온라인으로 분배한다. Needham-Schroeder는 커버로스의 이론적 기반이 된 키 분배 프로토콜이다.","ce":["Diffie-Hellman은 이산대수 기반 키 합의 프로토콜로, MIT가 개발한 티켓 기반 인증 시스템이 아니다.","커버로스는 MIT Athena 프로젝트에서 개발된 비밀키(대칭키) 기반 네트워크 인증 시스템으로, KDC가 티켓과 세션키를 온라인 분배하며 KDC 장애가 단점이다.","Needham-Schroeder는 커버로스의 이론적 기반이 된 키 분배 프로토콜(1978년)로, MIT의 네트워크 인증 시스템 자체는 아니다.","SET은 VISA·MasterCard가 주도한 신용카드 전자결제 프로토콜로 네트워크 개체 인증 시스템이 아니다."],"rel":["2-8","4-12"],"box":"이것은 MIT(Massachusetts Institute of Technology) 대학에서 개발한 분산 환경 하에서 개체 인증서비스를 제공하는 네트워크 인증시스템이다. 비밀키 암호작성법에 기초를 둔 자주 이용되는 온라인 암호키 분배 방법이다. 이 시스템의 목적은 인증된 클라이언트만이 서버에 접속하도록 하는 것이다. 이것의 장점으로는 데이터의 기밀성과 무결성을 보장한다는 점을 들 수 있고, 이것의 단점으로는 키 분배센터에 장애 발생 시 전체서비스가 사용 불가 상태가 됨을 들 수 있다."},{"n":76,"s":"s4","q":"다음 중 임의적 접근통제(DAC : Dscretionary access control) 에 해당하는 특징이 아닌 것은?","c":["사용자 기반 및 ID 기반 접근통제","중앙 집중적 관리가 가능","모든 개개의 주체와 객체 단위로 접근권한 설정","객체의 소유주가 주체와 객체 간의 접근통제 관계를 정의"],"a":1,"e":"DAC는 객체 소유자가 자신의 판단으로 사용자(ID)별 권한을 부여하는 분산형 방식이라 중앙 집중적 관리가 어렵다. 중앙 집중적 관리는 보안관리자가 레이블을 부여하는 MAC이나 RBAC의 특징이다.","ce":["DAC는 사용자 ID(신원)에 따라 권한을 부여하는 신원 기반 접근통제이므로 특징에 해당한다.","DAC는 객체 소유자가 각자 권한을 부여하는 분산형 방식이라 중앙 집중 관리가 어렵다. 중앙 집중 관리는 MAC·RBAC의 특징이다.","DAC는 접근통제 행렬(ACL 등)로 개개의 주체·객체 단위 권한을 설정하므로 특징에 해당한다.","객체 소유자가 자기 재량으로 누구에게 어떤 권한을 줄지 정의하는 것이 DAC의 핵심 특징이다."],"rel":["4-10"]},{"n":77,"s":"s4","q":"다음 중 대칭 암호 알고리즘이 아닌 것은?","c":["BlowFish","SEED","Diffie-Hellman","3DES"],"a":2,"e":"Diffie-Hellman은 이산대수 문제에 기반한 공개키 방식의 키 교환(합의) 알고리즘이다. Blowfish, SEED, 3DES는 대칭키 블록 암호다.","ce":["Blowfish는 Schneier가 설계한 64비트 블록, 가변 길이 키의 대칭 블록 암호다.","SEED는 KISA가 개발한 128비트 대칭 블록 암호다.","Diffie-Hellman은 이산대수 문제에 기반한 공개키 방식의 키 교환(합의) 알고리즘으로 대칭 암호 알고리즘이 아니다.","3DES는 DES를 세 번 적용하는 대칭 블록 암호다."],"rel":["4-2","4-4"]},{"n":78,"s":"s4","q":"다음 중 인증서가 폐지되는 사유가 아닌 것은?","c":["인증서 발행 조직에서 탈퇴","개인키의 손상","개인키의 유출 의심","인증서의 유효기간 만료"],"a":3,"e":"인증서 폐지는 유효기간 내에 개인키 손상·유출(의심), 소속 조직 탈퇴, 신원 정보 변경 등으로 더 이상 신뢰할 수 없을 때 CA가 CRL에 등록하는 것이다. 유효기간 만료는 폐지가 아니라 자연 만료(효력 상실)다.","ce":["인증서 발행 조직에서 탈퇴하면 인증서에 담긴 소속 정보가 더 이상 유효하지 않으므로 폐지 사유가 된다.","개인키가 손상되면 해당 인증서로 서명·복호화를 신뢰할 수 없으므로 폐지 사유가 된다.","개인키 유출이 의심되기만 해도 도용 위험이 있으므로 즉시 폐지 사유가 된다.","유효기간 만료는 폐지가 아니라 자연 만료(효력 상실)로, CRL에 등록할 대상이 아니다."],"rel":["4-7"]},{"n":79,"s":"s4","q":"다음 그림은 블록암호 운용모드의 한 종류를 나타낸 것이다. 다음 그림에 해당하는 블록암호 운용모드는?","c":["CBC(Cipher Block Chaining)","ECB(Electronic CodeBook)","CTR(CounTeR)","CFB(Cipher FeedBack)"],"a":3,"e":"IV를 먼저 블록 암호로 암호화한 출력과 평문을 XOR해 암호문을 만들고, 그 암호문을 다음 블록의 암호화 입력으로 되먹이는 구조는 CFB(암호 피드백) 모드다. CBC는 평문과 이전 암호문을 XOR한 뒤 암호화하고, OFB는 암호화 출력 자체를 되먹인다.","ce":["CBC는 평문을 이전 암호문과 XOR한 뒤 블록 암호화하는 구조로, 암호화 출력과 평문을 XOR하는 지문 그림과 순서가 다르다.","ECB는 각 블록을 독립적으로 암호화하며 IV나 피드백이 없다.","CTR은 IV 대신 증가하는 카운터 값을 암호화해 평문과 XOR하며, 암호문을 되먹이지 않는다.","CFB는 IV를 암호화한 출력과 평문을 XOR해 암호문을 만들고, 그 암호문을 다음 블록의 암호화 입력으로 되먹이는 구조로 그림과 일치한다."],"rel":["4-3"],"box":"Initialization Vector(IV) → Block Cipher Encryption(Key) → ⊕ Plaintext → Ciphertext\nCiphertext → 다음 Block Cipher Encryption(Key) 입력 → ⊕ Plaintext → Ciphertext (반복)","fig":"past/2018-09-08-q79.png"},{"n":80,"s":"s4","q":"n명의 사람이 대칭키 암호화 통신을 할 경우 몇 개의 대칭키가 필요한가?","c":["n(n+1)/2","n(n-1)/2","n(n-1)","n(n+1)"],"a":1,"e":"대칭키 방식은 통신하는 두 사람마다 서로 다른 키가 하나씩 필요하므로 n명 중 2명을 고르는 조합 수 n(n-1)/2개의 키가 필요하다. 공개키 방식에서는 1인당 키 쌍 1개로 2n개가 필요하다.","ce":["n(n+1)/2는 자기 자신과의 조합까지 포함한 값으로, 서로 다른 두 사람 쌍의 수보다 n개 많다.","두 사람마다 서로 다른 키가 하나씩 필요하므로 n명 중 2명을 고르는 조합 nC2 = n(n-1)/2개의 키가 필요하다.","n(n-1)은 순서를 구분한 쌍의 수(순열)로, A-B와 B-A가 같은 키를 쓰는 대칭키에서는 2배로 과대 계산된다.","n(n+1)은 필요한 키 수와 관련이 없는 값이다. 공개키 방식이라면 1인당 키 쌍으로 2n개다."],"rel":["4-1"]},{"n":81,"s":"s5","q":"괄호에 공통적으로 들어갈 적절한 것은?","c":["취약점","위협","위험","침해"],"a":0,"e":"취약점은 위협이 이용할 수 있는 시스템·관리상의 약점(결함)으로, 보호대책으로 줄일 수 있지만 새로운 취약점이 계속 발견되므로 완전히 제거할 수 없다. 위협은 자산에 손실을 줄 수 있는 잠재적 원인, 위험은 위협이 취약점을 이용해 손실이 발생할 가능성이다.","ce":["취약점은 정보시스템의 결함·약점으로, 보호대책으로 줄일 수 있지만 새로운 취약점이 계속 발견되어 완전히 제거할 수 없다.","위협은 자산에 손실을 줄 수 있는 외부·내부의 잠재적 원인(해커, 재해 등)으로 시스템 결함에서 생기는 것이 아니다.","위험은 위협이 취약점을 이용해 손실이 발생할 가능성(자산·위협·취약점의 함수)으로, 시스템 결함 자체를 뜻하지 않는다.","침해는 위협이 실제로 실현되어 보안이 깨진 사건으로, 사전에 존재하는 결함을 가리키지 않는다."],"rel":["5-2"],"box":"(     )은 정보시스템 또는 정보보호시스템의 결함 또는 손실에 의하여 발생되고, 정보보호 대책을 적용함으로써 감소시킬 수 있다. 그러나(     )이 없는 시스템은 존재하지 않고, 주기적인 진단과 패치의 적용에도 불구하고, 새로운 (     )이 발생되기 때문에 완전제거는 불가능하다"},{"n":82,"s":"s5","q":"위험분석 방법론으로 적절히 짝지은 것은?","c":["가: 확률분포법 나: 순위결정법","가: 시나리오법 나: 델파이법","가: 델파이법 나: 확률분포법","가: 순위결정법 나:시나리오법"],"a":1,"e":"시나리오법은 어떤 사건도 기대대로 발생하지 않는다는 전제에서 특정 조건의 위협 시나리오와 결과를 추정하는 정성적 기법이다. 델파이법은 전문가 집단의 토론·의견 수렴으로 위험을 분석하는 정성적 기법이며, 확률분포법은 통계적 분포를 이용하는 정량적 기법이다.","ce":["확률분포법은 미지의 사건을 확률 분포로 추정하는 정량적 기법이고, 순위결정법은 위험 항목에 순위를 매겨 비교하는 기법이라 두 설명과 맞지 않는다.","시나리오법은 사건이 기대대로 발생하지 않는다는 전제에서 조건별 위협 결과를 추정하고, 델파이법은 전문가 집단 토론으로 위협·취약성을 분석한다.","델파이법은 전문가 토론 기법이므로 '나'에 해당하고, 확률분포법은 '가'의 시나리오 추정과 다른 정량적 기법이다.","순위결정법은 위험 항목의 우선순위를 비교하는 기법이며, 전문가 토론은 시나리오법이 아니라 델파이법이다."],"rel":["5-2"],"box":"가: 그 어떤 사건도 기대대로 발생하지 않는다는 사실에 근거하여 일정 조건 하에서 위협에 대한 발생 가능한 결과를 추정하는 방법\n나: 시스템에 관한 전문적인 지식을 가진 전문가 집단을 구성하고 위험을 분석 및 평가하여 정보시스템이 직면한 다양 한 위협과 취약성을 토론을 통해 분석하는 방법"},{"n":83,"s":"s5","q":"「개인정보보호법」에 의거하여 개인정보처리자는 개인정보의 처리에 대하여 정보주체의 동의를 받을 때에는 각각의 동의 사항을 구분하여 정보주체가 이를 명확하게 인지할 수 있도록 알리고 각각 동의를 받아야 한다. 동의를 서면으로 받을 때에는 중요한 내용을 정하는 방법에 따라 명확히 표시하여 알아보기 쉽게 하도록 되어 있다. 이때 중요한 내용에 해당되지 않는 것은?","c":["동의를 거부할 권리가 있다는 사실 및 거부에 따른 불이익이 있을 경우에는 불이익에 대한 내용","개인정보를 제공받는 자","개인정보를 제공받는 자의 개인정보 이용 목적","개인정보의 보유 및 이용 기간"],"a":0,"e":"시험 당시 시행령 제17조는 서면 동의 시 명확히 표시할 중요한 내용으로 홍보·판매 권유 목적의 연락 가능성, 민감정보·고유식별정보(여권·운전면허·외국인등록번호), 보유·이용 기간, 제공받는 자와 그 이용 목적을 규정했다. 동의 거부권과 불이익은 동의 시 알려야 하는 고지 사항이지만 이 '중요한 내용' 목록에는 포함되지 않았다(개정 여부 확인).","ce":["시험 당시 시행령 제17조의 '중요한 내용' 목록(홍보·판매 권유 연락 가능성, 민감·고유식별정보, 보유·이용 기간, 제공받는 자와 이용 목적)에 동의 거부권·불이익은 포함되지 않았다(개정 여부 확인).","개인정보를 제공받는 자는 시행령상 서면 동의 시 명확히 표시해야 하는 중요한 내용에 해당한다.","제공받는 자의 개인정보 이용 목적은 시행령상 중요한 내용에 해당한다.","개인정보의 보유 및 이용 기간은 시행령상 중요한 내용에 해당한다."],"rel":["5-8"]},{"n":84,"s":"s5","q":"「개인정보보호법」에 의거하여 공공기관의 장은 대통령령으로 정하는 기준에 해당하는 개인정보 파일의 운용으로 인하여 정보주체의 개인정보 침해가 우려되는 경우에는 그 위험 요인의 분석과 개선사항 도출을 위한 영향평가를 하고 그 결과를 행정안전부장관에게 제출하여야 한다. 영향평가를 하는 경우에 고려해야 할 사항으로 적합하지 않은 것은?","c":["처리하는 개인정보의 수","개인정보의 제3자 제공 여부","정보주체의 권리를 해할 가능성 및 그 위험 정도","개인정보를 처리하는 수탁업체 관리·감독의 여부"],"a":3,"e":"개인정보보호법 제33조 제3항은 영향평가 시 처리하는 개인정보의 수, 제3자 제공 여부, 정보주체 권리 침해 가능성 및 위험 정도, 그 밖에 대통령령으로 정한 사항(민감·고유식별정보 처리 여부, 보유기간)을 고려하도록 한다. 수탁업체 관리·감독 여부는 법정 고려사항이 아니다(현재 결과 제출처는 개인정보보호위원회, 개정 여부 확인).","ce":["처리하는 개인정보의 수는 제33조가 명시한 영향평가 고려사항이다.","개인정보의 제3자 제공 여부는 제33조가 명시한 영향평가 고려사항이다.","정보주체의 권리를 해할 가능성 및 그 위험 정도는 제33조가 명시한 고려사항이다.","수탁업체 관리·감독 여부는 위탁 규정(제26조)의 의무 사항일 뿐, 영향평가 법정 고려사항으로 열거되어 있지 않다(개정 여부 확인)."],"rel":["5-9"]},{"n":85,"s":"s5","q":"\"개인정보 보호법\"에서 개인정보의 파기 및 보존 시 가장 적절하지 않은 경우는?","c":["개인정보의 이용목적이 달성된 때에는 즉시 파기하여야 한다.","개인정보 삭제 시 만일의 경우에 대비하여 일정기간 보관한다.","개인정보를 파기하지 않고 보관할 시에는 다른 개인정보와 분리하여 저장 · 관리한다.","전자적 파일 형태인 경우, 복원이 불가능한 방법으로 영구 삭제한다."],"a":1,"e":"제21조에 따라 보유기간 경과·처리 목적 달성 등으로 불필요해진 개인정보는 지체 없이 파기해야 하며, '만일에 대비한' 임의 보관은 허용되지 않는다. 다른 법령에 따라 보존해야 하는 경우에만 다른 개인정보와 분리해 저장·관리하고, 전자 파일은 복원 불가능한 방법으로 영구 삭제한다.","ce":["처리 목적이 달성되거나 보유기간이 지나 불필요해진 개인정보는 지체 없이 파기해야 한다는 제21조 취지에 맞다.","'만일의 경우에 대비한' 임의 보관은 허용되지 않는다. 다른 법령에 보존 의무가 있는 경우에만 보관할 수 있다.","법령에 따라 파기하지 않고 보존할 때는 다른 개인정보와 분리해 저장·관리해야 하므로 적절하다.","전자적 파일 형태의 개인정보는 복원이 불가능한 방법으로 영구 삭제해야 하므로 적절하다."],"rel":["5-9"]},{"n":86,"s":"s5","q":"「개인정보보호법」에 의거하여 개인정보처리자가 정보주체 이외로부터 수집한 개인정보를 처리하는 때에는 정보주체의 요구가 있으면 즉시 정보주체에게 알려야 하는 사항들에 해당되지 않는 것은?","c":["개인정보 처리의 정지를 요구할 권리가 있다는 사실","개인정보의 보유·이용 기간","개인정보의 수집 출처","개인정보의 처리 목적"],"a":1,"e":"제20조 제1항에 따라 정보주체 이외로부터 수집한 개인정보는 요구가 있으면 즉시 개인정보의 수집 출처, 처리 목적, 처리 정지를 요구할 권리가 있다는 사실을 알려야 한다. 보유·이용 기간은 이 고지 사항에 포함되지 않는다(개정 여부 확인).","ce":["개인정보 처리의 정지를 요구할 권리가 있다는 사실은 제20조 제1항의 고지 사항이다.","보유·이용 기간은 제20조 제1항이 정한 고지 사항(수집 출처, 처리 목적, 처리정지 요구권)에 포함되지 않는다(개정 여부 확인).","정보주체 이외로부터 수집했으므로 개인정보의 수집 출처는 제20조 제1항의 핵심 고지 사항이다.","개인정보의 처리 목적은 제20조 제1항의 고지 사항이다."],"rel":["5-8"]},{"n":87,"s":"s5","q":"다음 지문이 설명하는 위험분석방법론은?","c":["과거자료 분석법","확률 분포법","델파이법","시나리오법"],"a":2,"e":"델파이법은 전문가 집단의 토론·반복 설문으로 위험을 추정하는 정성적 기법으로, 짧은 시간과 적은 비용으로 결과를 얻지만 정확도가 낮다. 과거자료 분석법과 확률 분포법은 수치 자료를 활용하는 정량적 기법이다.","ce":["과거자료 분석법은 과거 사고 자료의 통계를 바탕으로 위험 발생 가능성을 예측하는 정량적 기법으로 전문가 토론을 쓰지 않는다.","확률 분포법은 미지의 사건을 확률 분포(최저·보통·최고 추정)로 분석하는 정량적 기법이다.","델파이법은 전문가 집단의 토론·반복 설문으로 위협과 취약성을 분석하는 정성적 기법으로, 빠르고 저렴하지만 정확도가 낮다.","시나리오법은 특정 조건에서 위협이 발생했을 때의 결과를 시나리오로 추정하는 정성적 기법으로 전문가 토론이 핵심이 아니다."],"rel":["5-2"],"box":"- 시스템에 관한 전문적인 지식을 가진 전문가의 집단을 구성하고 위험을 분석 및 평가하여 정보시스템이 직면한 다양한 위협과 취약성을 토론을 통해 분석하는 방법이다.\n- 위험 분석을 짧은 기간에 도출할 수 있어 시간과 비용을 절약할 수 있지만, 추정의 정확도가 낮다."},{"n":88,"s":"s5","q":"정보보호 사전점검에 대한 설명으로 옳은 것은?","c":["정보보호 사전점검은 전자적 침해행위에 대비하기 위한 정보시스템의 취약점 분석 평가와 이에 기초한 보호대책의 제시 또는 정보보호 관리체계 구축 등을 주된 목적으로 한다.","방송통신위원회는 사업자가 사전점검을 실시하거나 실시 계약을 체결한 경우 해당 사업 또는 서비스에 대하여 가점을 부여하는 등 우대조치를 할 수 있다.","사전점검 수행기관으로 지정받으려는 자는 수행기관 지정 신청서를 방송통신위원회에 제출하여야 한다.","사전점검 대상 범위는 제공하려는 사업 또는 정보통신 서비스를 구성하는 하드웨어, 소프트웨어, 네트워크 등의 유무형 설비 및 시설을 대상으로 한다."],"a":3,"e":"정보보호 사전점검(정보통신망법 제45조의2)은 신규 정보통신서비스·전기통신사업의 기획·설계 단계에서 보안 요구사항 반영 여부를 점검하는 제도로, 서비스를 구성하는 하드웨어·소프트웨어·네트워크 등 유무형 설비와 시설이 대상이다. ①은 취약점 분석·평가나 관리체계 구축 제도의 목적이고, 사전점검의 주관 부처는 방송통신위원회가 아니라 과학기술정보통신부(당시 미래창조과학부)다(개정 여부 확인).","ce":["취약점 분석·평가와 보호대책 제시, 관리체계 구축 등은 정보보호 컨설팅·취약점 분석 제도의 목적이다. 사전점검은 신규 서비스 기획·설계 단계의 보안 요구사항 반영 점검이 목적이다.","사전점검 관련 우대조치 권한은 방송통신위원회가 아니라 주관 부처인 과학기술정보통신부(당시 미래창조과학부)에 있다(개정 여부 확인).","사전점검 수행기관 지정 신청서는 방송통신위원회가 아니라 과학기술정보통신부(당시 미래창조과학부)에 제출한다(개정 여부 확인).","사전점검은 제공하려는 사업·정보통신서비스를 구성하는 하드웨어, 소프트웨어, 네트워크 등 유무형 설비와 시설을 대상으로 하므로 옳다."],"rel":["5-10"]},{"n":89,"s":"s5","q":"도출된 위험이 해당 사업에 심각한 영향을 주는 관계로 보험에 가입하였다. 이런 식으로 위험을 경감 또는 완화시키는 처리 유형은 무엇인가?","c":["위험 감소(reduction)","위험 전가(transfer)","위험 수용(acceptance)","위험 회피(avoidance)"],"a":1,"e":"보험 가입이나 외주 계약처럼 위험으로 인한 손실 부담을 제3자에게 넘기는 처리 방식은 위험 전가다. 위험 감소는 보호대책 구현으로 위험을 줄이는 것, 위험 회피는 위험을 유발하는 업무·자산 자체를 포기하는 것이다.","ce":["위험 감소는 보호대책(방화벽 설치, 백업 등)을 구현해 위험의 발생 가능성이나 영향을 직접 줄이는 방식이다.","보험 가입이나 외주 계약처럼 손실 부담을 제3자에게 넘기는 방식이 위험 전가다.","위험 수용은 위험을 인지하고도 비용 대비 효과 등을 고려해 별도 대책 없이 그대로 받아들이는 방식이다.","위험 회피는 위험을 유발하는 업무·자산·서비스 자체를 중단하거나 포기하는 방식이다."],"rel":["5-2"]},{"n":90,"s":"s5","q":"다음 중 공인인증기관이 발급하는 공인인증서에 포함되어야 하는 사항이 아닌 것은 무엇인가?","c":["가입자의 전자서명검증정보","공인인증서 비밀번호","가입자와 공인인증기관이 이용하는 전자서명방식","공인인증기관의 명칭 등 공인인증기관을 확인할 수 있는 정보"],"a":1,"e":"당시 전자서명법 제15조는 공인인증서에 가입자 이름, 전자서명검증정보, 전자서명방식, 인증서 일련번호, 유효기간, 공인인증기관 명칭 등을 포함하도록 했다. 인증서 비밀번호는 가입자가 개인키를 보호하기 위해 설정하는 값으로 인증서에 기재되지 않는다(2020년 전자서명법 전부개정으로 공인인증서 제도 폐지, 개정 여부 확인).","ce":["가입자의 전자서명검증정보(공개키)는 구 전자서명법 제15조가 정한 공인인증서 필수 포함 사항이다.","인증서 비밀번호는 가입자가 개인키 파일을 보호하려고 설정하는 값으로 인증서에 기재되지 않는다.","가입자와 공인인증기관이 이용하는 전자서명 방식은 공인인증서 필수 포함 사항이다.","공인인증기관의 명칭 등 인증기관을 확인할 수 있는 정보는 공인인증서 필수 포함 사항이다(2020년 공인인증서 제도 폐지, 개정 여부 확인)."],"rel":["5-10"]},{"n":91,"s":"s5","q":"고유식별정보는 법령에 따라 개인을 고유하게 구별하기 위하여 부여된 식별정보로서 대통령령으로 정하는 정보이다. 다음 중 개인정보처리자가 고유식별정보를 처리할 수 있는 경우에 해당하는 것은?","c":["정보주체의 동의를 받지 않은 경우","법령에서 구체적으로 고유식별정보의 처리를 요구하거나 허용하는 경우","교통단속을 위하여 필요한 경우","시설 안전 및 화재 예방을 위하여 필요한 경우"],"a":1,"e":"제24조에 따라 고유식별정보는 다른 개인정보와 별도로 정보주체의 동의를 받거나, 법령에서 구체적으로 처리를 요구·허용하는 경우에만 처리할 수 있다. 교통단속, 시설 안전·화재 예방은 영상정보처리기기 설치 허용 사유(제25조)다.","ce":["고유식별정보는 원칙적으로 처리가 금지되며, 정보주체의 별도 동의가 있어야 처리할 수 있으므로 '동의를 받지 않은 경우'는 허용 사유가 아니다.","제24조는 정보주체의 별도 동의 또는 법령에서 구체적으로 고유식별정보 처리를 요구·허용하는 경우에만 처리를 허용한다.","교통단속은 제25조의 공개된 장소 영상정보처리기기 설치 허용 사유로, 고유식별정보 처리 근거가 아니다.","시설 안전 및 화재 예방은 제25조의 영상정보처리기기 설치 허용 사유로, 고유식별정보 처리 근거가 아니다."],"rel":["5-7"]},{"n":92,"s":"s5","q":"다음 중 아래 지문의 빈칸 안에 들어가야 할 단어 또는 문장으로 가장 적합한 것은?","c":["가:주민등록번호 나: 구분","가:성별 나: 유추","가:주민등록번호 나: 결합","가:성별 나: 구분"],"a":2,"e":"시험 당시 두 법은 개인정보를 성명·주민등록번호 및 영상 등으로 개인을 알아볼 수 있는 정보와, 다른 정보와 쉽게 결합하여 알아볼 수 있는 정보로 정의했다. 2020년 개정으로 정의가 개인정보보호법으로 일원화되고 가명정보가 추가되었다(개정 여부 확인).","ce":["(가) 주민등록번호는 맞지만 (나)는 '구분'이 아니라 '결합'이다. 다른 정보와 쉽게 결합해 개인을 알아볼 수 있으면 개인정보에 포함된다.","성별만으로는 개인을 알아볼 수 없어 정의 예시로 쓰이지 않았고, (나)도 '유추'가 아니라 '결합'이다.","시험 당시 두 법은 성명·주민등록번호 및 영상 등으로 개인을 알아볼 수 있는 정보와, 다른 정보와 쉽게 결합하여 알아볼 수 있는 정보를 개인정보로 정의했다.","(가) 성별과 (나) 구분 모두 법 조문 문구가 아니다. 조문은 주민등록번호와 결합이다(개정 여부 확인)."],"rel":["5-7"],"box":"「개인정보 보호법」 제2조(정의) 이 법에서 사용하는 용어의 뜻 은 다음과 같다.\n\"개인정보\"란 살아 있는 개인에 관한 정보로서 성명 ( 가 ) 및 영상 등을 통하여 개인을 알아볼 수 있는 정보 (해당 정보만으로는 특정 개인을 알아볼 수 없더라도 다른 정보 와 쉽게 ( 나 )하여 알아볼 수 있는 것을 포함한다)를 말한다.\n「정보통신망법」 제2조(정의) 1이 법에서 사용하는 용어의 뜻 은 다음과 같다. \"개인정보란 생존하는 개인에 관한 정보로서 성명 ( 가 ) 등에 의하여 특정한 개인을 알아볼 수 있는 부호 · 문자· 음성 · 음향 및 영상 등의 정보(해당 정보만으로는 특정 개인을 알아볼 수 없어도 다른 정보와 쉽게 ( 나 )하여 알아 볼 수 있는 경우에는 그 정보를 포함한다)를 말한다."},{"n":93,"s":"s5","q":"개인정보영향평가 시 반드시 고려할 사항이 아닌 것은?","c":["처리하는 개인정보의 수","개인정보 취급자의 인가 여부","개인정보의 제3자 제공 여부","정보주체의 권리를 해할 가능성 및 그 위험"],"a":1,"e":"개인정보보호법 제33조 제3항의 영향평가 고려사항은 처리하는 개인정보의 수, 제3자 제공 여부, 정보주체 권리 침해 가능성 및 위험 정도, 대통령령으로 정한 사항이다. 개인정보 취급자의 인가 여부는 법정 고려사항이 아니다.","ce":["처리하는 개인정보의 수는 제33조가 명시한 영향평가 고려사항이다.","개인정보 취급자의 인가 여부는 안전성 확보조치(접근권한 관리) 사항일 뿐, 영향평가 법정 고려사항이 아니다.","개인정보의 제3자 제공 여부는 제33조가 명시한 영향평가 고려사항이다.","정보주체의 권리를 해할 가능성 및 그 위험 정도는 제33조가 명시한 영향평가 고려사항이다."],"rel":["5-9"]},{"n":94,"s":"s5","q":"개인정보의 안정성 확보조치 기준(고시)의 제7조(개인정보의 암호화)에 따라 반드시 암호화하여 저장해야하는 개인정보가 아닌 것은?","c":["비밀번호","고유식별번호","바이오 정보","전화번호"],"a":3,"e":"개인정보의 안전성 확보조치 기준 제7조는 비밀번호(일방향 암호화), 바이오정보, 고유식별정보(주민등록번호·여권번호·운전면허번호·외국인등록번호)를 암호화 대상으로 규정한다. 전화번호는 의무 암호화 저장 대상이 아니다(개정 여부 확인).","ce":["비밀번호는 제7조에 따라 반드시 일방향 암호화하여 저장해야 하는 대상이다.","고유식별정보(주민등록번호·여권번호·운전면허번호·외국인등록번호)는 제7조의 암호화 대상이다.","바이오정보는 제7조에 따라 암호화하여 저장해야 하는 대상이다.","전화번호는 일반 개인정보로 제7조의 의무 암호화 저장 대상에 포함되지 않는다(개정 여부 확인)."],"rel":["5-9"]},{"n":95,"s":"s5","q":"다음은 정보통신기반 보호법에 따른 주요 정보통신기반시설의 지정요건이다. 빈칸 가 ~ 마 에 들어갈 알맞은 단어를 바르게 나열한 것은?","c":["가:중요성 나:기밀성 다:의존도 라:발생가능성 마:용이성","가:기밀성 나:중요성 다:의존도 라:용이성 마:경제성","가:중요성 나:의존도 다:상호연계성 라:발생가능성 마:용이성","가:의존도 나:중요성 다:상호연계성 라:발생가능성 마:용이성"],"a":2,"e":"정보통신기반 보호법 제8조 제1항의 지정 기준은 업무의 국가사회적 중요성, 업무의 정보통신기반시설 의존도, 다른 기반시설과의 상호연계성, 침해사고 시 피해 규모·범위, 침해사고 발생 가능성 또는 복구의 용이성이다.","ce":["'가' 중요성은 맞지만 '나'는 기밀성이 아니라 의존도, '다'는 의존도가 아니라 상호연계성이다.","'가'에 기밀성, '나'에 중요성을 넣어 틀렸고, '라'·'마'도 발생가능성·용이성이 아닌 용이성·경제성으로 잘못되었다.","정보통신기반 보호법 제8조의 지정 기준은 업무의 국가사회적 중요성, 기반시설 의존도, 다른 시설과의 상호연계성, 피해 규모·범위, 침해사고 발생가능성 또는 복구 용이성이다.","'가'(중요성)와 '나'(의존도)가 서로 뒤바뀌었다. '다'·'라'·'마'는 맞다."],"rel":["5-13"],"box":"중앙행정기관의 장은 소관분야의 정보통신기반시설중 다음의 사항을 고려하여 전자적 침해행위로부터의 보호가 필요하다고 인정되는 정보통신기반시설을 주요정보통신기반시설로 지정할 수 있다.\n1. 당해 정보통신기반시설을 관리하는 기관이 수행하는 업무의 국가 사회적 ( 가 )\n2. 당해 정보통신기반시설을 관리하는 기관이 수행하는 업무의 정보통신기반시설에 대한 ( 나 )\n3. 다른 정보통신기반시설과의 ( 다 )\n4. 침해사고가 발생할 경우 국가안전보장과 경제사회에 미치는 피해규모 및 범위\n5. 침해사고의 ( 라 ) 또는 그 복구의 ( 마 )"},{"n":96,"s":"s5","q":"「개인정보보호법」상에서 민감정보로 명시되어 있는 것은?","c":["혈액형","사상·신념","결혼 여부","성별"],"a":1,"e":"제23조의 민감정보는 사상·신념, 노동조합·정당 가입·탈퇴, 정치적 견해, 건강, 성생활 등 사생활 침해 우려가 큰 정보와 시행령상 유전정보, 범죄경력자료 등이다. 혈액형, 결혼 여부, 성별은 법에 민감정보로 명시되어 있지 않다.","ce":["혈액형은 건강 관련 정보로 볼 여지가 있으나 제23조에 민감정보로 명시된 항목이 아니다.","사상·신념은 제23조가 민감정보로 직접 명시한 항목이다.","결혼 여부는 일반 개인정보로 민감정보로 명시되어 있지 않다.","성별은 일반 개인정보로 민감정보로 명시되어 있지 않다."],"rel":["5-7"]},{"n":97,"s":"s5","q":"다음 정보보호 관리체계 인증제도에 대한 설명으로 가장 적절하지 않은 것은?","c":["정보통신서비스와 직접적인 관련성이 낮은 전사적 자원관리 시스템(ERP), 분석용 데이터베이스(DW), 그룹웨어 등 기업 내부 시스템, 영업/마케팅 조직은 일반적으로 인증 범위에서 제외해도 된다.","인증범위는 신청기관이 제공하는 정보통신서비스를 기준으로 해당 서비스에 포함되거나 관련 있는 자산(시스템, 설비, 시설 등), 조직 등을 포함하여야 한다.","ISMS 의무인증범위 내에 있는 서비스, 자산, 조직(인력)을 보호하기 위한 보안시스템은 포함 대상에서 제외해도 된다.","해당 서비스의 직접적인 운영 및 관리를 위한 백오피스 시스템은 인증범위에 포함되며, 해당 서비스와 관련이 없더라도 그 서비스의 핵심정보자산에 접근 가능하다면 포함하여야 한다."],"a":2,"e":"ISMS 의무인증범위 내 서비스·자산·조직을 보호하는 보안시스템(방화벽, IPS, 접근통제 등)은 반드시 인증 범위에 포함해야 한다. 서비스와 직접 관련성이 낮은 ERP·DW·그룹웨어 등 내부 시스템은 제외할 수 있지만, 핵심정보자산에 접근 가능한 백오피스 시스템은 포함해야 한다.","ce":["정보통신서비스와 직접 관련성이 낮은 ERP·DW·그룹웨어 등 내부 시스템과 영업·마케팅 조직은 일반적으로 인증 범위에서 제외할 수 있어 적절하다.","인증 범위는 신청기관의 정보통신서비스를 기준으로 관련 자산(시스템·설비·시설)과 조직을 포함해야 하므로 적절하다.","의무인증범위 내 서비스·자산·조직을 보호하는 방화벽·IPS·접근통제 등 보안시스템은 반드시 인증 범위에 포함해야 하므로 '제외해도 된다'는 틀렸다.","서비스 운영·관리용 백오피스 시스템은 포함되며, 서비스와 무관해도 핵심정보자산에 접근 가능하면 포함해야 하므로 적절하다."],"rel":["5-11"]},{"n":98,"s":"s5","q":"다음 지문이 설명하는 인증제도는?","c":["ISO 27001","ITSEC","CC(Common Criteria)","ISMS"],"a":2,"e":"CC(공통평가기준, ISO/IEC 15408)는 제품 유형별 보호프로파일(PP)과 보안목표명세서(ST)를 바탕으로 IT 보안제품을 평가하고 EAL1~EAL7의 보증등급을 부여하는 국제 표준이다. ITSEC은 유럽의 평가기준(E0~E6), ISO 27001과 ISMS는 조직의 관리체계 인증이다.","ce":["ISO 27001은 조직의 정보보호 관리체계(ISMS) 국제 인증 표준으로 IT 제품을 EAL로 평가하지 않는다.","ITSEC은 유럽의 IT 보안 평가 기준으로 E0~E6 등급을 사용하며, EAL1~7과 PP 개념은 CC에서 정립되었다.","CC(ISO/IEC 15408)는 제품 유형별 보호프로파일(PP)을 정의하고 IT 보안제품을 평가해 EAL1~EAL7 보증등급을 부여하는 국제 공통평가기준이다.","ISMS는 조직의 정보보호 관리체계를 인증하는 국내 제도로 제품 보안성 평가가 아니다."],"rel":["5-6"],"box":"현재 사용되는 IT 보안제품에 대해 보안성을 평가하는 제도로 제품유형별 PP(Protection Profile)를 정의하고, 8개 군의 평가항 목을 대상으로 평가가 이루어진다. 평가결과는 IT 보안제품의 보안위협 및 자산가치의 정도에 따라 EAL1(Evaluation Assurance Level 1) - EAL7(Evaluation Assurance Level 7) 까지 7단계로 부여하며 인증서가 제공된다."},{"n":99,"s":"s5","q":"다음의 지문이 설명하는 정보보호 용어는?","c":["재난 예방 계획","업무연속성 계획","기업 안정성 확보 계획","시스템 운영 계획"],"a":1,"e":"업무연속성 계획(BCP)은 재해·재난 시 핵심 업무를 중단 없이 유지하거나 허용 시간 내 복구해 기업의 신뢰성과 가치를 지키기 위한 계획과 절차다. IT 시스템 복구에 초점을 둔 재해복구계획(DRP)보다 넓은 개념이다.","ce":["재난 예방 계획은 재해 발생 자체를 막는 예방 활동에 초점이 있어, 발생 후 핵심 업무 지속·복구 절차를 뜻하지 않는다.","업무연속성 계획(BCP)은 재해·재난 시 핵심 시스템 가용성을 회복하고 사업을 지속해 기업 신뢰성과 가치를 유지하기 위한 계획과 절차다.","기업 안정성 확보 계획은 정보보호 분야의 표준 용어가 아니다.","시스템 운영 계획은 평상시 시스템 운영 절차를 다루는 것으로 재해 대비 사업 지속성과 다르다."],"rel":["5-3"],"box":"이것은 각종 재해나 재난의 발생을 대비하기 위하여 핵심 시스템의 가용성과 신뢰성을 회복하고 사업의 지속성을 유지하기 위한 일련의 계획과 절차를 말한다. 이것은 단순한 데이터의 복구나 신뢰도를 유지하는 것 뿐 아니라 나아가 기업의 전체적인 신뢰성 유지와 가치를 최대화하는 방법과 절차이다."},{"n":100,"s":"s5","q":"개인정보처리자는 다음 지문의 사항이 포함된 것을 정하고 이를 정보주체가 쉽게 확인할 수 있게 공개하도록 되어 있다. 다음 지문의 사항이 포함된 문서의 법률적 명칭은 무엇인가?","c":["개인정보 보호정책","표준 개인정보 보호지침","개인정보 보호지침","개인정보 처리방침"],"a":3,"e":"개인정보보호법 제30조는 개인정보처리자가 처리 목적, 처리·보유 기간, 제3자 제공, 위탁, 정보주체의 권리·의무와 행사방법 등을 포함한 개인정보 처리방침을 정해 공개하도록 규정한다. 표준 개인정보 보호지침은 행정안전부(현 개인정보보호위원회)가 정하는 고시다.","ce":["'개인정보 보호정책'은 일상적으로 쓰는 표현일 뿐, 개인정보보호법 제30조가 정한 공개 문서의 법률적 명칭은 '개인정보 처리방침'이다.","표준 개인정보 보호지침은 개인정보 처리 기준을 정한 행정안전부(현 개인정보보호위원회) 고시로, 개별 처리자가 공개하는 문서가 아니다.","개인정보 보호지침은 법에서 사용하는 공개 문서의 명칭이 아니다.","개인정보보호법 제30조는 처리 목적, 처리·보유 기간, 제3자 제공, 위탁, 정보주체 권리·의무와 행사방법 등을 담은 '개인정보 처리방침'을 정해 공개하도록 규정한다."],"rel":["5-14"],"box":"1. 개인정보의 처리 목적\n2. 개인정보의 처리 및 보유 기간\n3. 개인정보의 제3자의 제공에 관한 사항(해당되는 경우에만 정한다.)\n4. 개인정보처리의 위탁에 관한 사항(해당되는 경우에만 정한다.)\n5. 정보주체의 권리·의무 및 그 행사방법에 관한 사항\n6. 그 밖에 개인정보의 처리에 관하여 대통령령으로 정한 사항"}]}];
